window.MG_LITERATURE_DATA = [{"pmid": "42308456", "title": "Functional Profiling of Acetylcholine Receptor Antibodies Informs Therapeutic Outcome of FcRn Inhibitor Therapy in Myasthenia Gravis.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction most commonly associated with acetylcholine receptor (AChR) antibodies (AChR-Abs), detected in up to 80% of patients. The emergence of targeted therapies, such as neonatal Fc receptor (FcRn) inhibitors, highlights the need for standardized functional assays capable of dissecting AChR-Ab pathogenic mechanisms. By selectively reducing circulating IgG through FcRn blockade, these agents differ fundamentally from conventional immunosuppressants, emphasizing the need to characterize antibody-mediated AChR dysfunction and complement activation as potential markers of therapeutic response. However, current functional assays often rely on transiently transfected or heterogeneous cell systems, limiting reproducibility and scalability. A stably transfected human cell line expressing physiologically clustered adult AChRs could fill this methodological gap and enable standardized, quantitative evaluation of antibody effector functions.\nMETHODS: We generated a stable rhabdomyosarcoma (RD) cell line expressing clustered human adult AChRs (hAChR-RDcl) using the PiggyBac transposon system for genomic integration of AChR subunit genes. The hAChR-RDcl line was applied to functional cell-based assays using serum samples from 30 patients with AChR-MG before and after one treatment cycle with efgartigimod. Clinical efficacy was assessed by Quantitative Myasthenia Gravis (QMG) and MG Activities of Daily Living (MG-ADL) scores.\nRESULTS: The hAChR-RDcl cell line showed stable transcription and surface expression of adult AChR subunits, confirmed by RT-qPCR, α-bungarotoxin binding, and antibody-specific reactivity (mAb637 and patient serum samples). Baseline functional assays identified blocking antibodies in 15 of 30 (50%), internalizing antibodies in 20 of 30 (66.7%), and complement-activating antibodies in 14 of 30 (46.6%) samples. After efgartigimod treatment, all 3 antibody-mediated mechanisms were significantly reduced. Patients with persistent complement activity after treatment experienced more severe symptoms (higher QMG scores) compared with those showing other antibody-mediated pathogenetic mechanisms or complete suppression of antibody effector functions.\nDISCUSSION: The hAChR-RDcl cell line represents a reliable and scalable platform for standardized functional profiling of AChR-Abs. Functional characterization of AChR-Abs provides a translational approach to monitor therapeutic responses and elucidate the mechanisms underlying FcRn inhibitor efficacy in MG.", "authors": ["Morcone Veronica", "Morroni Jacopo", "Valenzano Giuseppe", "Marini Sofia", "Falso Silvia", "Marini Martina", "Habetswallner Federico", "Farì Giorgia", "Carrozza Cinzia", "Iorio Raffaele"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2026/06/17 16:03", "pub_date": "2026-Jul", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42308456/", "affiliations": ["Department of Neuroscience, Università Cattolica del Sacro Cuore, Rome, Italy."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "42306338", "title": "Retraction: Exploring the therapeutic potential of IL-17A inhibition in myasthenia gravis: a retrospective study on secukinumab.", "abstract": "[This retracts the article DOI: 10.1136/bmjno-2025-001249.].", "authors": [], "journal": "BMJ neurology open", "entry_date": "2026/06/17 05:23", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42306338/", "affiliations": [], "pub_types": ["Journal Article", "Retraction Notice"], "china_related": false, "study_types": ["Comment"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42306025", "title": "Magnesium Sulfate-Induced Myasthenic Crisis in Pregnancy: A Case Report.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder characterized by antibodies targeting acetylcholine receptors (AChR) or muscle-specific kinase (MuSK) at the neuromuscular junction, resulting in fluctuating skeletal muscle weakness. Preeclampsia is an obstetric complication defined as new-onset hypertension and proteinuria, or new-onset hypertension with evidence of end-organ dysfunction with or without proteinuria, typically presenting after 20 weeks gestation or within six weeks postpartum. We report a 37-year-old woman at 19 weeks' gestation who developed a myasthenic crisis following administration of intravenous magnesium sulfate for suspected preeclampsia. When there is concern for preeclampsia in pregnant patients with MG, alternative treatments to magnesium sulfate should be utilized to avoid exacerbating or triggering a myasthenic crisis. In pregnant patients with MG, alternatives to magnesium sulfate should be considered for seizure prophylaxis and management because magnesium may precipitate or worsen myasthenic crisis. Hydralazine or nifedipine are considered first-line antihypertensive therapies in pregnant patients with MG; however, labetalol can also be used with caution because it may exacerbate MG symptoms.", "authors": ["Gould Lauren A", "Lorenz Andrea", "Nicotra Selena", "Rodriguez Vashun"], "journal": "Cureus", "entry_date": "2026/06/17 05:17", "pub_date": "2026-Jun", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42306025/", "affiliations": ["Emergency Medicine, Lakeland Regional Health Medical Center, Lakeland, USA."], "pub_types": ["Case Reports", "Journal Article"], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42304705", "title": "Comparing Efficacy and Safety of Various Monoclonal Antibodies in Myasthenia Gravis: A Systematic Review and Network Meta-Analysis of Randomized Controlled Trials.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder that causes muscle weakness due to disrupted neuromuscular transmission. This network meta-analysis compared the safety and effectiveness of monoclonal antibodies used to treat MG.\nMETHODS: PubMed, Cochrane Central, and ScienceDirect were searched through June 2025. A frequentist network meta-analysis was conducted using the \"meta\" and \"netmeta\" packages in RStudio version 4.3.3. Treatment rankings were determined by p-scores.\nRESULTS: Eighteen randomized controlled trials (RCTs) were included in this network meta-analysis. Rozanolixzumab (ROZ) 10 mg/kg significantly decreased the MG Activities of Daily Living (MG-ADL) score compared to placebo (MD = -2.33; 95%CI:[-3.60, -1.06]; p = 0.0003) and was ranked best (p-score = 0.77) regarding this outcome. Batoclimab (BAT) 680 mg significantly reduced the Quantitative MG (QMG) score compared to placebo (MD = -5.17; 95%CI:[-6.44, -3.89]; p <0.0001) and was rated the top performer (p-score = 0.96) for this endpoint. Regarding the MG Composite (MGC) score, BAT 340 mg was ranked best (p-score = 0.82), although the decrease in MGC score was insignificant (MD -5.30; 95%CI:[-11.01, 0.41]; p = 0.07). Eculizumab (ECU) was ranked best (p-score = 0.93) regarding the 15-item revised MG Quality of Life (MG-QoL 15r) score. Belimumab (BEL) 10 mg/kg was ranked best regarding the adverse events (p-score = 0.87).\nCONCLUSION: ROZ 10 mg/kg ranked best for MG-ADL. BAT 680 mg significantly reduced QMG and ranked best. BAT 340 mg had the highest probability of reducing the MGC score. ECU significantly decreased MG-QoL 15r and ranked best. BEL 10 mg/kg had the highest likelihood of reducing adverse events.", "authors": ["Waseem Muhammad Hassan", "Abideen Zain Ul", "Iqbal Minahil", "Ishtiaq Saniya", "Thada Pawan Kumar", "Dmytriw Adam A"], "journal": "Brain and behavior", "entry_date": "2026/06/17 01:43", "pub_date": "2026-Jun", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42304705/", "affiliations": ["Allama Iqbal Medical College, Lahore, Pakistan."], "pub_types": ["Journal Article", "Network Meta-Analysis", "Systematic Review", "Review"], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "42304472", "title": "Proteomic and machine learning analysis predicts treatment response signatures in Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a prototypical antibody-mediated autoimmune disease with variable treatment responses with a need for biomarkers to guide therapeutic decision making. Proteomic profiling, coupled with machine learning, offers a hypothesis-free approach to identify multi-protein signatures associated with treatment response.\nMETHODS: We analyzed sera collected at entry (baseline) from participants in a phase 3 trial randomized trial comparing thymectomy plus prednisone versus prednisone alone, along with matched controls using liquid chromatography-mass spectrometry. We derived disease-specific proteomic signatures and evaluated associations between baseline proteins and 6-month clinical outcomes using multiple machine-learning approaches with internal validation.\nRESULTS: Baseline serum proteomes distinguished MG from controls, with pathway enrichment implicating complement activation, immunoglobulin production, and T-cell receptor signaling. Distinct protein panels predicted 6-month clinical improvement within each treatment arm. In the thymectomy-plus-prednisone group, models captured non-linear relationships of predictive proteins in contrast with the predominant additive patterns observed in the prednisone-alone group. Predictive proteins were enriched for T-cell signaling and leukocyte trafficking functions, providing insight into treatment-specific biology.\nCONCLUSIONS: Baseline serum proteomics captures core disease characteristics of MG and predicts short-term clinical response in a treatment-specific manner. While our results require validation in independent cohorts, these findings could enable biomarker-guided selection of thymectomy, refine risk stratification, and furnish mechanistic readouts for future MG trials and clinical care. We aim to conduct future studies using -omic approaches to validate these baseline predictive biomarkers and pathways of treatment response in patients with MG.", "authors": ["Gilbert Karli", "Cheema Amrita K", "Kaminski Henry J", "Kusner Linda L"], "journal": "Journal of translational medicine", "entry_date": "2026/06/17 00:15", "pub_date": "2026-Jun-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42304472/", "affiliations": ["Laboratory for Myasthenia Gravis Research, George Washington University, Washington, DC, USA."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "42304385", "title": "HMGB1-mediated endoplasmic reticulum stress in monocyte-derived dendritic cells regulates CD4+ T cell immune responses in myasthenia gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder characterized by immune dysregulation at the neuromuscular junction. Monocyte-derived dendritic cells (moDCs) are increasingly recognized as key drivers of MG pathogenesis; however, the mechanisms that govern their dysfunction remain incompletely understood.\nMETHODS: This study integrated human genetics, patient immunophenotyping, and therapeutic evaluation in the experimental autoimmune myasthenia gravis (EAMG) model. Monocytes were isolated and differentiated into moDCs to assess the effects of HMGB1 and its inhibitor, 18α-glycyrrhetinic acid (18α-GA), on the expression profiles, phenotypes, and functions of moDCs. Therapeutic efficacy was further assessed in EAMG using 18α-GA, HMGB1 neutralizing antibody, and adoptive transfer of 18α-GA-induced tolerogenic moDCs.\nRESULTS: Mendelian randomization (MR) analyses revealed bidirectional causality between MG and moDCs. MG patients exhibited elevated plasma HMGB1 levels and mature phenotypes of moDCs. Mechanistically, HMGB1 activated the IRE1α/XBP1 and NF-κB pathways in moDCs through the engagement of TLR4, thereby inducing endoplasmic reticulum (ER) stress, promoting the activation of moDCs, and driving an imbalance in CD4+ T cell immune responses. Through a multitargeted mechanism of action, 18α-GA effectively inhibited both the IRE1α/XBP1 and NF-κB pathways in moDCs, thereby blunting ER stress and driving the differentiation of moDCs toward tolerogenic phenotypes. The minimal effective dose of 18α-GA alleviated EAMG by counteracting HMGB1-driven, moDC-mediated CD4+ T cell dysfunction, and showed better therapeutic performance compared with HMGB1 neutralizing antibody. Moreover, the adoptive transfer of 18α-GA-induced tolerogenic moDCs was effective in treating EAMG.\nCONCLUSIONS: HMGB1-mediated ER stress reprogrammed moDCs via the IRE1α/XBP1 and NF-κB pathways to promote pathogenic CD4+ T cell responses in MG. Targeting the HMGB1-ER stress axis in moDCs could restore immune balance and represent a promising therapeutic strategy for MG.", "authors": ["Zhang Qing", "Gu Zhongya", "Li Yaxuan", "Yang Mengge", "Ma Xue", "Pan Xuanxuan", "Bi Zhuajin", "Lin Jing", "Gui Mengcui", "Wang Furong", "Zhang Min", "Li Zhijun", "Bu Bitao"], "journal": "Journal of neuroinflammation", "entry_date": "2026/06/17 00:11", "pub_date": "2026-Jun-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42304385/", "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, 430030, China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 10.1, "journal_quartile": "1区"}, {"pmid": "42303225", "title": "The glutathione transferase omega 1-1 GSTO1*A140D polymorphism is associated with unfavourable prognosis in patients with thymoma and myasthenia gravis.", "abstract": "PURPOSE: Thymomas are rare organotypic tumors frequently associated with immune-related paraneoplastic syndromes. The genetic alterations of thymomas are largely unknown and rely on general transcription factor I (GTF2I) and Harvey rat sarcoma (HRAS) mutations. Glutathione transferase omega-1-1 (GSTO1-1) is an atypical member of the glutathione transferase superfamily involved in regulating pro-survival and anti-apoptotic pathways. The association between GSTO1-1 polymorphisms and the increased risk of different types of cancer has been investigated, but no study has focused on thymomas to date. Therefore, we have investigated whether two major GSTO1-1 genetic variants, namely GSTO1*A140D and GSTO1*E155del polymorphisms, might represent a risk for thymoma development.\nPATIENTS AND METHODS: Genotyping was performed in 47 patients diagnosed with thymoma and myasthenia gravis by using a PCR-RFLP assay.\nRESULTS: The results of our study show no significant correlation between the two polymorphisms and thymoma histotype, stage, disease progression, and myasthenia gravis symptoms. A worse progression-free survival (PFS; 66.8 vs 236.6 months) was found, however, in patients bearing the homozygous GSTO1*A140D polymorphism, suggesting a potential role for GSTO1-1 in thymoma. Indeed, enzymes with a regulatory function, such as GSTO1-1, could produce very different effects depending on both their activity and the relevance of their substrates in the risk/progression of a specific neoplasm.\nCONCLUSIONS: GSTO1*A140D polymorphism deserves to be further explored as a possible risk factor associated with a worse PFS in thymoma. Specific targets of GSTO1-1 in thymomas need to be determined.", "authors": ["Piaggi Simona", "Carnicelli Vittoria", "Pardini Eleonora", "Aprile Vittorio", "Coppedè Fabio", "Pompella Alfonso", "Petrini Iacopo", "Corti Alessandro"], "journal": "Advances in medical sciences", "entry_date": "2026/06/16 19:37", "pub_date": "2026-Jun-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42303225/", "affiliations": ["Department of Translational Research NTMS, University of Pisa, Pisa, Italy."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "3区"}, {"pmid": "42296853", "title": "Author's response to comment on \"Variations in clinical features and disease burden of myasthenia gravis between racial and ethnic groups: A retrospective cohort study of two national databases\".", "abstract": "", "authors": ["McLaren Nilay P", "Roy Bhaskar", "Nowak Richard J"], "journal": "Journal of the neurological sciences", "entry_date": "2026/06/15 18:08", "pub_date": "2026-Jun-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42296853/", "affiliations": ["Department of Neurology, Yale University School of Medicine, New Haven, CT, USA."], "pub_types": ["Letter"], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "42292478", "title": "Case Report: Use of telitacicept for ocular myasthenia gravis.", "abstract": "BACKGROUND: Despite existing treatments of ocular myasthenia gravis (OMG), there remains a need for more effective therapies with fewer side effects. Telitacicept, a novel agent that simultaneously inhibits B lymphocyte stimulator (BLyS) and a proliferation-inducing ligand (APRIL), represents a promising therapeutic candidate for OMG.\nCASE PRESENTATION: In this study, telitacicept monotherapy or combination therapy was administered to three patients with OMG who had shown an inadequate response to, or were intolerant of, standard treatments. All patients demonstrated clinically significant improvement post-treatment. Specifically, both the Myasthenia Gravis Foundation of America-Quantitative Myasthenia Gravis (MGFA-QMG) and the Myasthenia Gravis Activities of Daily Living (MG-ADL) scores showed a marked reduction, indicating decreased disease severity and improved quality of life. Immunological assessments revealed an initial decline in CD19+ B lymphocyte counts and acetylcholine receptor (AChR) antibody levels. Interestingly, despite well-controlled clinical symptoms, AChR antibody levels subsequently rebounded and stabilized. Furthermore, pulmonary infections in one patient were not established as causally related to telitacicept.\nCONCLUSION: Telitacicept monotherapy or combination treatment in OMG was associated with favorable clinical improvement and a mild adverse event profile, and its use can be tailored to the individual patient. However, larger-scale and longer-term studies are necessary to confirm these findings and fully establish the role of telitacicept in OMG management.", "authors": ["Yang Ali", "Zhao Jing", "Li Fangfang", "Pang Rui", "Zang Weizhou"], "journal": "Frontiers in immunology", "entry_date": "2026/06/15 07:28", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42292478/", "affiliations": ["Department of Neurology, Henan Provincial People's Hospital, Zhengzhou, China."], "pub_types": ["Case Reports", "Journal Article"], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42292465", "title": "Severe immune checkpoint inhibitor-induced 3M syndrome: a case report.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) have significantly improved survival rates in various advanced cancers, including cervical cancer. However, they can induce a range of immune-related adverse events (irAEs), with immune myocarditis being particularly dangerous, especially when combined with myositis and myasthenia gravis, forming the fatal 3M syndrome. Early symptoms are subtle, and delayed diagnosis and treatment often lead to severe consequences.\nCASE PRESENTATION: A 65-year-old female with stage FIGO stage IIIA cervical squamous cell carcinoma received one dose of anti-PD-1 monoclonal antibody (Enlarzumab) combined with chemoradiotherapy. Following initial disease stabilization, the patient developed early neuromuscular symptoms, including ptosis and facial weakness, on Day 21. By Day 25, she experienced sudden chest tightness and acute heart failure with new-onset atrial fibrillation and a decline in left ventricular ejection fraction from 57% to 40%. The concurrent elevation of cardiac biomarkers and creatine kinase, alongside neuromuscular involvement, confirmed the clinical diagnosis of ICI-induced 3M syndrome. Despite treatment with high-dose methylprednisolone, intravenous immunoglobulin (IVIG), and mycophenolate mofetil, the patient ultimately succumbed to progressive respiratory failure following the family's decision to decline further invasive respiratory support.\nCONCLUSION: This case highlights the insidious onset and rapid progression of 3M syndrome, where neuromuscular symptoms often serve as overlooked precursors to myocarditis. Establishing a systematic approach involving proactive monitoring and immediate immunosuppressive treatment is essential to ensure the safety of immunotherapy.", "authors": ["Yao Hairong", "Hao Zitong", "Zhang Xin", "Liu Shikai"], "journal": "Frontiers in immunology", "entry_date": "2026/06/15 07:28", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42292465/", "affiliations": ["Department of Gynecologic Oncology, Cangzhou Central Hospital, Cangzhou, Hebei, China."], "pub_types": ["Case Reports", "Journal Article"], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42289707", "title": "Isolated pulmonary Cryptococcus neoformans infection presenting with severe pulmonary involvement: a case report.", "abstract": "BACKGROUND: Pulmonary cryptococcosis is an uncommon fungal infection typically seen in immunocompromised hosts. In individuals with only mild immunosuppression, the disease is rare, often mimicking bacterial pneumonia, leading to diagnostic delays and inappropriate treatment.\nCASE PRESENTATION: We report a 50-year-old Chinese man with poorly controlled diabetes mellitus and myasthenia gravis on low-dose corticosteroids who presented with fever, cough, and hypoxemic respiratory failure. Initial imaging suggested severe community-acquired pneumonia, and broad-spectrum antibiotics were administered, but there was no clinical response. Chest CT revealed bilateral patchy consolidations, and bronchoalveolar lavage cultures confirmed Cryptococcus neoformans. Lumbar puncture excluded central nervous system involvement. The patient was initially treated with amphotericin B, but therapy was complicated by acute kidney injury, requiring a switch to flucytosine and fluconazole. Despite this, he demonstrated marked clinical and radiological improvement, with near-complete resolution at 6 months.\nCONCLUSION: Pulmonary cryptococcosis can masquerade as community-acquired pneumonia, delaying appropriate management. Clinicians should maintain a high index of suspicion in patients with prolonged corticosteroid use, poorly controlled diabetes mellitus, and poor response to antibiotics. Early recognition and timely antifungal therapy are vital to improving outcomes.", "authors": ["Ng Boon Hau", "Low Hsueh Jing", "Abeed Nik Nuratiqah Nik", "Sharil Nor Safiqah", "Khee Cheong Xiong", "Osman Rose Azzlinda", "Ban Andrea Yu-Lin"], "journal": "Journal of medical case reports", "entry_date": "2026/06/14 23:31", "pub_date": "2026-Jun-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42289707/", "affiliations": ["Respiratory Unit, Department of Medicine, Faculty of Medicine, Universiti Kebangsaan Malaysia, Hospital Canselor Tuanku Muhriz, Kuala Lumpur, Malaysia. ngboonhau@hotmail.com."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "42286316", "title": "Genomic co-alterations and immune-related adverse events shape outcomes of thymic malignancies treated with immune checkpoint inhibitors.", "abstract": "Thymic carcinoma, thymoma, and thymic neuroendocrine tumors are rare malignancies with limited treatment options in advanced stages. Immune checkpoint inhibitors (ICIs) have shown preliminary activity in thymic tumors, although their clinical benefit and toxicity profile remain incompletely defined. We retrospectively analyzed patients with thymic tumors treated with ICIs at MD Anderson Cancer Center from 2010 to 2024. Clinical characteristics, molecular profiles, treatment details, immune-related adverse events (irAEs), and survival outcomes were collected. The primary objective was ICI safety. Secondary endpoints included objective response rate (ORR), disease control rate (DCR), progression-free survival (PFS), and overall survival (OS). Cox regression identified predictors of survival. Forty-two patients were analyzed (median age, 59 years; 55% male), comprising 29 thymic carcinomas, 8 thymomas, and 5 neuroendocrine tumors. ICIs were administered as monotherapy (55%) or combinations (45%), most commonly anti-PD-1 agents (86%). IrAEs occurred in 60% overall and in all patients with thymoma. Grade ≥3 irAEs developed in 19%, including one treatment-related death from pneumonitis. Common irAEs included fatigue, rash, and musculoskeletal symptoms. Notable neuromuscular syndromes included concurrent myasthenia gravis and myocarditis in thymoma. Among 37 RECIST-evaluable patients, ORR was 21%, and DCR was 78%. Median PFS was 6.5 months, and median OS was 9.1 months. Any-grade irAEs were associated with reduced mortality risk (HR, 0.30). TP53 mutations and lung metastases predicted worse OS, whereas CDKN2A alterations correlated with improved OS. ICIs demonstrated preliminary activity in thymic tumors but were associated with substantial toxicity, especially in thymoma. Biomarker-driven patient selection and vigilant irAE monitoring are needed.", "authors": ["Tan Harold Nathan", "Le Hung", "Frej Khaoula Ben Haj", "Kang Lei", "Champiat Stephane", "Meric-Bernstam Funda", "Fossella Frank", "Naing Aung", "Sharon Elad", "Altan Mehmet", "Dumbrava Ecaterina E"], "journal": "NPJ precision oncology", "entry_date": "2026/06/12 23:25", "pub_date": "2026-Jun-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42286316/", "affiliations": ["Department of Investigational Cancer Therapeutics, The University of Texas MD Anderson Cancer Center, Houston, TX, USA. hntan@mdanderson.org."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 9.9, "journal_quartile": "1区"}, {"pmid": "42284727", "title": "[Demographic, clinical and therapeutic aspects of a French thyroid eye disease cohort].", "abstract": "PURPOSE: To study the epidemiological, clinical, and therapeutic aspects of a cohort of French patients with thyroid eye disease (TED).\nPATIENTS AND METHODS: We conducted a retrospective, single-center study over a 4-year period, including all patients referred to our tertiary referral center for TED. Patients without TED or with incomplete data were excluded.\nRESULTS: A total of 100 patients were included (77% women), with a mean age of 43.5years (range: 25 to 90years). Among them, 47% were smokers, 16% had a personal history of autoimmune diseases, and 24% had a family history of autoimmune conditions. One-third of the patients were euthyroid at the time of consultation, and one-third had undergone radical thyroid treatment. The most common symptoms were upper eyelid retraction (48%) and exophthalmos (42%). In our cohort, 5% of patients had associated myasthenia, most often presenting with ptosis. Among these, 80% had pure ocular myasthenia. An active form (CAS≥3) was found in 15% of the patients, primarily treated with corticosteroid boluses. Six patients had severe forms with optic neuropathy, requiring medical and surgical management in the majority of cases. Approximately half of the patients underwent surgical management (orbital decompression, strabismus surgery, eyelid surgery), either alone or sequentially.\nCONCLUSION: TED is a condition predominantly affecting women, typically presenting with upper eyelid retraction and/or exophthalmos. Approximately 5% of patients have associated myasthenia and compressive optic neuropathy. An active/inflammatory form is present in 15% of patients.", "authors": ["Lavigne A", "Lecolier N", "Dupre R", "Bresch S", "Martel A"], "journal": "Journal francais d'ophtalmologie", "entry_date": "2026/06/12 18:03", "pub_date": "2026-Jun-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42284727/", "affiliations": ["Service d'ophtalmologie, Hôpital Fondation Adolphe de Rothschild, 75019, Paris, France. Electronic address: lavigne.alexandre1@gmail.com."], "pub_types": ["English Abstract", "Journal Article"], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "42284706", "title": "Intestinal flora and metabolite changes: Uncovering pathogenic mechanisms in myasthenia gravis.", "abstract": "OBJECTIVES: The gut microbiota is associated with the occurrence of Myasthenia gravis (MG), but the biological relevance of these associations is often unclear. We conducted a study to determine whether gut microbiota and metabolites are disturbed in individuals with MG.\nMETHODS: Stool samples were obtained from 50 individuals with MG, and 15 matched healthy controls (HCs). Then, 16S ribosomal RNA gene amplification sequencing and gas chromatography-mass spectrometry were used to investigate the composition and structure of the gut microbiota community and the levels of metabolites in patients with MG and HCs. Clinical characteristics were collected, including clinical scores such as QMG score, MG-ADL score, MG-QOL-15 score, MMT score, and acetylcholine receptor antibody (AChR-Ab) titer levels. These parameters were used to analyze the correlation between distinct flora and clinical features.\nRESULTS: We observed pronounced differences in gut microbiota composition between MG patients and HCs. Notably, the association between Streptomyces and MG disease status was consistent and independent of therapeutic interventions. In treatment-naive MG patients, Acinetobacter and Escherichia-Shigella were significantly associated with disease status. Lachnospiraceae was negatively correlated with QMG score, MG-ADL score, MG-QOL-15 score, and AChR-Ab titer, while exhibiting a positive correlation with MMT score. With respect to the metabolome, a panel of specific metabolites effectively distinguished MG patients from HCs.\nCONCLUSION: The gut microbiota and their metabolites exert important effects on MG. The microbiota is closely related to clinical indicators, such as the severity of the disease. Intervention with gut microbes in MG patients may be a new treatment strategy.", "authors": ["Wu Qian", "Li Junlian", "Li Haiyan", "Kan Hongjiao", "Yuan Man", "Chen Yunna", "Sun Xiuting", "Zhao Kaijie", "Zhao Long", "Zhang Xiaoyan"], "journal": "Journal of neuroimmunology", "entry_date": "2026/06/12 18:03", "pub_date": "2026-Jun-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42284706/", "affiliations": ["Department of Neurology, The 940 Hospital of Joint Logistic Support Forces of PLA, Lanzhou, China; Department of Neurology, Heze Municipal Hospital, Shandong Province, Heze, China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42281359", "title": "A Rare Clinical Presentation of Variegate Porphyria.", "abstract": "BACKGROUND: Variegate porphyria is a rare heme biosynthesis disorder caused by pathogenic variants in the PPOX gene. Despite being relatively well characterized, its clinical manifestations are highly variable and can mimic a broad spectrum of neurological and systemic conditions.\nCASE PRESENTATION: We report the case of a young woman with recurrent episodes of muscle weakness, sometimes accompanied by respiratory dysfunction. Initially suspected to have myasthenia gravis, laboratory testing for this condition was negative. Whole-genome sequencing identified a heterozygous pathogenic variant c.338G>C in the PPOX gene and a homozygous variant of uncertain significance c.190G>A in MYMK, with no other disease-causing variants detected in genes associated with congenital myasthenic syndromes or periodic paralysis.\nCONCLUSION: In the described case, the patient's atypical clinical manifestations led to a prolonged and complex diagnostic workup. WGS findings suggested possible co-occurrence of variegate porphyria with a potential overlap with a Carey-Fineman-Ziter syndrome. This case highlights the importance of comprehensive evaluation of the clinical presentation in patients with unexplained neuromuscular symptoms.", "authors": ["Viakhireva I", "Murtazina A", "Orlova A", "Makretskaya N", "Nikitin S", "Skoblov M"], "journal": "Molecular genetics & genomic medicine", "entry_date": "2026/06/12 03:13", "pub_date": "2026-Jun", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42281359/", "affiliations": ["Research Centre for Medical Genetics, Moscow, Russia."], "pub_types": ["Journal Article", "Case Reports"], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "42278719", "title": "Triple-M Overlap Syndrome Associated with Immune Checkpoint Inhibitors: A FAERS Pharmacovigilance Analysis.", "abstract": "Background/Objectives: Immune checkpoint inhibitors (ICIs) improve cancer outcomes but may induce immune-related adverse events. Myasthenia gravis (MG), myositis, and myocarditis may co-occur as an overlap syndrome (\"Triple-M\"), but population-level data remain limited. This study aimed to characterize the pharmacovigilance profile, overlap patterns, and reported fatality of Triple-M associated with ICIs. Methods: A FAERS pharmacovigilance analysis was conducted using OpenVigil FDA and the openFDA API. Disproportionality metrics (ROR, PRR, χ2) were used to evaluate signals for MG, myositis, and myocarditis across nine ICIs. Triple-M was defined as the co-reporting of all three events and was evaluated over the study period from August 2016 to September 2025. Results: Among 272,753 ICI reports, 1395 (0.51%) MG, 3173 (1.16%) myocarditis, and 2018 (0.74%) myositis cases were identified; all nine ICIs met signal-detection criteria for all three toxicities (χ2 > 4). Pembrolizumab and nivolumab accounted for the highest absolute report counts, whereas nivolumab-relatlimab demonstrated the strongest disproportionality (ROR = 109.5 for MG, 106.4 for myocarditis, and 29.0 for myositis). Triple-M occurred in 114 unique reports (0.04% of all ICI-related adverse events), representing 8.2% of MG, 5.6% of myositis, and 3.6% of myocarditis cases. Co-reporting was common: among 5308 unique reports involving these toxicities, 1164 reports (21.9%) included at least two components of the triad. Triple-M cases were more common in men (56%), with a median age of 74 years (IQR 68-79), a median time-to-onset of 21 days (IQR 18-28), and 50% mortality among cases with available outcomes. Conclusions: Triple-M appears to be a severe overlap phenotype reported in association with immune checkpoint inhibitors, characterized by early onset, frequent co-reporting, and substantial reported fatality. Early recognition and coordinated multidisciplinary assessment may warrant further clinical evaluation and investigation of this overlap phenotype.", "authors": ["Alshamsan Bader", "Ng Terry L"], "journal": "Healthcare (Basel, Switzerland)", "entry_date": "2026/06/12 01:05", "pub_date": "2026-May-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42278719/", "affiliations": ["Department of Medicine, College of Medicine, Qassim University, Buraydah 52571, Saudi Arabia."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "4区"}, {"pmid": "42278322", "title": "Genome-Wide and Locus-Level Analyses Reveal Modest, Heterogeneous Genetic Sharing Between Alzheimer's Disease and Myasthenia Gravis.", "abstract": "Alzheimer's disease (AD) is a neurodegenerative disorder, whereas myasthenia gravis (MG) is an autoimmune neuromuscular disease. Despite their distinct clinical manifestations, both disorders involve immune dysregulation and cholinergic dysfunction, and epidemiological evidence for an association remains inconclusive. Here, we investigated the genetic architecture underlying the AD-MG relationship using large-scale European-ancestry genome-wide association study (GWAS) data, including early- and late-onset MG, within a multi-resolution analytical framework. Genome-wide analyses indicated modest polygenic overlap between AD and MG, supported by nominally significant and directionally consistent correlations across datasets, SNPeffect concordance in the primary GWAS, and robust gene-level overlap. Evidence for genome-wide correlation was weaker and non-significant across AD-MG subtypes. Local genetic correlation analyses revealed that shared AD-MG signals were largely locus-specific and heterogeneous, with regions showing both concordant and discordant effects, particularly across MG subtypes. Subtype-specific analyses indicated broader and more heterogeneous overlap for AD-late-onset MG, including both major histocompatibility complex (MHC) and non-MHC loci, whereas AD-early-onset MG showed more restricted patterns largely confined to the MHC. Cross-trait meta-analysis and colocalisation further refined these findings, identifying a limited number of loci with evidence of shared AD-MG association, while most regions were consistent with distinct causal variants. A chromosome 16 locus showed the most consistent shared cross-trait AD-MG signal across multiple analytical frameworks. Mendelian randomisation analyses provided no evidence of a causal effect of AD liability on MG and yielded only suggestive, and inconclusive evidence for the reverse direction. Gene-level and expression-informed analyses prioritised immune-related genes, as well as regulators of transcription, chromatin organisation, and synaptic processes, without implying concordant causal variants across traits. Tissue and pathway analyses suggested shared immune involvement, with differential emphasis on innate immune processes in AD and adaptive immune pathways in MG. Notably, heterogeneity of effects within the MHC and across loci suggests that overlap reflects a complex, context-dependent architecture rather than a uniform immune-driven signal. Overall, our findings indicate that the AD-MG relationship is characterised by modest genome-wide polygenic overlap, substantial locus-specific heterogeneity, and partial convergence on immune-related genetic architecture, rather than a uniformly shared mechanism.", "authors": ["Adewuyi Emmanuel O", "Auta Asa", "Ossai Chinedu I", "Anyaegbu Chidozie C", "Nguyen Thi Thu Huong", "Rahman Md Rezanur", "Stephan Blossom C M", "Tessema Gizachew A", "Nyholt Dale R", "Pereira Gavin"], "journal": "International journal of molecular sciences", "entry_date": "2026/06/12 01:04", "pub_date": "2026-May-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42278322/", "affiliations": ["Curtin School of Population Health, Faculty of Health Sciences, Curtin University, Perth, WA 6102, Australia."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "42275909", "title": "Long-term effectiveness, safety, and cost-effectiveness of intravenous immunoglobulin for generalized myasthenia gravis in an era of molecular targeted drugs: Insights from Japanese post-marketing surveillance.", "abstract": "OBJECTIVES: Intravenous immunoglobulin (IVIg) is widely used for generalized myasthenia gravis (gMG), but long-term, large-scale, real-world evidence remains limited. This study evaluated the 2-year effectiveness, safety, and cost-effectiveness of IVIg in Japanese patients with gMG.\nMETHODS: This retrospective, observational, post-marketing surveillance study was conducted between 2011 and 2016 at 316 facilities across Japan. All patients with gMG who received the first IVIg dose were eligible for enrolment. Patients who did not receive corticosteroids or immunosuppressants before IVIg initiation were excluded. The primary outcome was the time to retreatment with IVIg, intravenous methylprednisolone, plasmapheresis, or thymectomy due to disease progression or relapse. The cost-effectiveness of IVIg and molecular targeted drugs was evaluated using cost per responder and cost per Myasthenia Gravis Activities of Daily Living (MG-ADL) improvement analyses.\nRESULTS: In total, 1041 patients were included in this study (mean age, 58.7 years; women, 674 [65%]; mean MG-ADL score, 9.45; mean follow-up period, 331.5 days). The median time to retreatment was 386 days (95% confidence interval [CI]: 302-545) in all patients and 175 days (95% CI: 147-214) in 410 patients who received the second IVIg dose (p < 0.0001, log-rank test). The MG-ADL responder rate (≥2-point improvement) was 65.7% on day 14 and 46.7% on day 180. The cost per MG-ADL improvement was estimated at 7000-17,000 Japanese yen, which was substantially lower than that for molecular targeted drugs.\nDISCUSSION: These findings support the long-term effectiveness and cost-effectiveness of IVIg for gMG, without new safety concerns.", "authors": ["Suzuki Shigeaki", "Iida Minami", "Wakahara Takuya", "Shiko Yuki", "Murai Hiroyuki"], "journal": "Journal of autoimmunity", "entry_date": "2026/06/11 18:08", "pub_date": "2026-Jun-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42275909/", "affiliations": ["Department of Neurology, Tokyo Metropolitan Neurological Hospital, Tokyo, Japan. Electronic address: sgsuzuki@keio.jp."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "42274862", "title": "Diagnostic and Prognostic Value of Epigenetic Markers in Neurological Diseases. A Narrative Review.", "abstract": "Neurological disorders are a leading cause of disability and death, yet sensitive and specific biomarkers remain limited. Epigenetic modifications link genetic background with environmental influences and may improve diagnosis, prognosis, and treatment stratification. The study aimed to summarise the current knowledge on epigenetics in neurological diseases, primarily focusing on their diagnostic value. We performed a narrative review with elements of systematic methodology. PubMed was searched up to November 21, 2025, using broad neurology and epigenetics terms followed by disease-specific queries. Sixty-five original studies on epigenetic markers with diagnostic or prognostic utility in neurological diseases were included. Across neurological disorders, multiple disease-associated epigenetic signatures have been reported. In neurodegenerative diseases, deoxyribonucleic acid (DNA) methylation patterns, histone modifications, and non-coding ribonucleic acid (RNA) profiles discriminate patients from controls and correlate with disease stage and clinical outcomes. In multiple sclerosis, methylation changes in genes involved in disease pathogenesis and characteristic microRNAs may distinguish relapsing from progressive forms and relate to disability. In ischemic stroke and transient ischemic attack, epigenetic alterations in vascular, metabolic, circadian, and inflammatory pathways, together with non-coding RNAs and extracellular vesicle signatures, are associated with stroke risk, severity, and outcome. Evidence in epilepsy, migraine, myasthenia gravis, dystrophies, and leukodystrophies suggests additional disease-specific epigenetic candidates. Epigenetic biomarkers across DNA methylation, histone modifications, and non-coding RNAs hold substantial potential to enhance precision neurology, from early diagnosis to prognostic stratification and therapy guidance. However, current evidence is heterogeneous and often based on small cohorts and variable methodologies. Large, longitudinal studies with standardised protocols are required before routine clinical implementation.", "authors": ["Grodzka Olga", "Wołos Justyna", "Kupc Małgorzata", "Ahmadova Sara", "Eyileten Ceren", "Domitrz Izabela"], "journal": "Cellular and molecular neurobiology", "entry_date": "2026/06/11 11:17", "pub_date": "2026-Jun-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42274862/", "affiliations": ["Department of Neurology, Faculty of Medicine and Dentistry, Medical University of Warsaw, Warsaw, Poland. olga.grodzka@wum.edu.pl."], "pub_types": ["Journal Article", "Review"], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.8, "journal_quartile": "3区"}, {"pmid": "42274368", "title": "Low-Frequency Repetitive Nerve Stimulation in Myasthenia Gravis and Lambert-Eaton Myasthenic Syndrome.", "abstract": "OBJECTIVE: Lambert-Eaton myasthenic syndrome (LEMS) and myasthenia gravis (MG) exhibit distinct decrement patterns in low-frequency repetitive nerve stimulation. While a delayed nadir in LEMS is well-documented, we identified additional unique patterns. This study systematically compared low-frequency repetitive nerve stimulation features between the two conditions using prolonged protocols.\nMETHODS: We retrospectively analyzed 20 patients with LEMS (March 2019-August 2025) and 34 age-matched patients with MG (April 2023-August 2025). All subjects underwent low-frequency repetitive nerve stimulation (3 Hz, 5 Hz; 25 stimuli per train) on the abductor digiti minimi and trapezius muscles. Key parameters included compound muscle action potential nadir position and postnadir amplitude recovery.\nRESULTS: As previously reported, patients with LEMS had significantly lower baseline compound muscle action potential amplitudes than patients with MG. In MG, 90.9% of tested muscles showed a compound muscle action potential nadir at the 4th or 5th response. By contrast, 65.5% of LEMS muscles exhibited a delayed nadir between the 7th and 10th responses. Notably, 24.1% of LEMS muscles displayed a nadir at waves 4 to 5 followed by substantial amplitude recovery. In this subgroup, the amplitude difference between the nadir and the 10th or 25th response showed high sensitivity and specificity in differentiating LEMS from MG. Furthermore, 10.3% of LEMS muscles exhibited direct facilitation, characterized by an amplitude increase without an initial decrement.\nCONCLUSIONS: In addition to the previously reported delayed decrement, we identified two additional abnormal low-frequency repetitive nerve stimulation patterns in LEMS: early decrement with postnadir recovery and direct facilitation. These three LEMS-specific patterns differ from those observed in MG and may aid in the differential diagnosis of MG and LEMS.", "authors": ["Ding Qingyun", "Wu Shuang", "Hu Youfang", "Wu Yimin", "Tan Ying", "Cui Liying", "Guan Yuzhou"], "journal": "Journal of clinical neurophysiology : official publication of the American Electroencephalographic Society", "entry_date": "2026/06/11 10:13", "pub_date": "2026-Jun-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42274368/", "affiliations": ["Department of Neurology, Peking Union Medical College Hospital, Chinese Academy of Medical Sciences, Beijing, China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "42273833", "title": "Authors' reply: Myasthenia gravis following the initiation of statin therapy.", "abstract": "", "authors": ["Yan Vincent Ka Chun", "Xu Wanchun", "Taniguchi Yuta", "Fung Kwun Kei", "Chan Koon Ho", "Lau Gary Kui Kai", "Chui Celine Sze Ling", "Lai Francisco Tsz Tsun", "Li Xue", "Iwagami Masao", "Masuda Rie", "Tamiya Nanako", "Dorajoo Sreemanee Raaj", "Neo Jing Wei", "Chan Esther Wai Yin", "Wong Ian Chi Kei", "Wan Eric Yuk Fai"], "journal": "Journal of internal medicine", "entry_date": "2026/06/11 05:43", "pub_date": "2026-Jun-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42273833/", "affiliations": ["Department of Pharmacology and Pharmacy, Centre for Safe Medication Practice and Research, Li Ka Shing Faculty of Medicine, The University of Hong Kong, Hong Kong Special Administrative Region, China."], "pub_types": ["Letter"], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 9.2, "journal_quartile": "1区"}, {"pmid": "42271427", "title": "Development and validation of a predictive model for postoperative complications in thymoma patients.", "abstract": "OBJECTIVE: To develop and validate an intervention model for the risk factors of postoperative complications in patients with thymoma.\nMETHODS: A retrospective analysis was conducted on the clinical data of patients who underwent thymoma resection surgery at our hospital between June 2006 and July 2024. Postoperative complications were systematically categorized according to the Clavien-Dindo classification (Grade II-V), including but not limited to: ① 30-day mortality, ② respiratory failure (defined as mechanical ventilation > 48 h or unplanned reintubation), ③ myocardial injury (troponin elevation > 5×ULN).Whether complications occurred was divided into two groups. The data were randomly divided into a modeling cohort (70%) and a validation cohort (30%). Logistic regression was used to identify risk factors for postoperative complications, and model performance was evaluated using ROC curves and calibration plots.\nRESULTS: A total of 26.1% (66/253) of thymoma patients developed postoperative complications. Multivariable logistic regression analysis revealed that Masaoka-Koga stage, Myasthenia Gravis, intraoperative blood loss, forced expiratory volume in 1 second, and albumin were significant predictors in the model. The model demonstrated an area under the ROC curve of 0.84 (95% CI: 0.78-0.91) in the modeling cohort and 0.76 (95% CI: 0.63-0.89) in the validation cohort. The Hosmer-Lemeshow goodness-of-fit test showed: modeling cohort (χ2 = 5.0997, P = 0.6478), validation cohort (χ2 = 4.9946, P = 0.7582). Decision curve analysis indicated that the risk thresholds for the modeling and validation cohorts were 10%-70% and 10%-60%.\nCONCLUSION: This study developed a risk prediction model for postoperative complications in thymoma patients, demonstrating strong discriminative ability (C-statistic 0.82, 95% CI 0.78-0.86) and calibration (Brier score 0.11) upon internal validation. The model may aid in identifying high-risk patients for targeted preventive measures, though its impact on actual complication rates requires prospective intervention trials.", "authors": ["Lu Zhendong", "Liu Fangchao", "Yan Dongjie", "Wang Jinghui", "Ma Teng", "Ruan Hongyun"], "journal": "Journal of cardiothoracic surgery", "entry_date": "2026/06/11 00:13", "pub_date": "2026-Jun-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42271427/", "affiliations": ["Department of Cellular and Molecular Biology, Beijing Chest Hospital, Capital Medical University, Beijing Tuberculosis and Thoracic Tumor Research Institute, No 9, Bei guan Street, Tong Zhou District, 101149, Beijing, P. R. China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "2区"}, {"pmid": "42271114", "title": "Eculizumab in Myasthenia Gravis: A Multicenter Retrospective Real-World Study in China.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder needing long-term immunosuppressive therapy. Eculizumab is a promising treatment, but real-world evidence on its efficacy and safety is limited.\nMETHODS: This retrospective cohort study across six medical centers enrolled 60 patients with MG on eculizumab. Clinical data, including MG-Activities of Daily Living (MG-ADL) scores, quantitative MG scores (QMG), and oral corticosteroid dosage at baseline, weeks 1, 4, and 8, and final follow-up were obtained. Outcomes included score changes, post-intervention status (PIS), and safety profile.\nRESULTS: By week 8, 30.95% of patients achieved minimal manifestation status (MMS) or better, increasing to 32.69% at final follow-up. Mean ADL scores significantly dropped from 8.18 ± 3.99 at baseline to 5.59 ± 3.72 at week 1, 3.78 ± 3.42 at week 4, 3.50 ± 2.92 at week 8, and 3.33 ± 3.56 during final follow-up (p < 0.0001). Clinically meaningful improvement (CMI) was observed in 56.9%, 70.0%, 85.0%, and 76.27% at the respective time points. Both thymoma-associated and non-thymoma subgroups showed significant ADL improvement (p ≤ 0.026) with mixed-effects modeling revealing significant group × time interaction (p = 0.01).The thymoma-associated MG (TAMG) group had a faster initial response, with subsequent outcomes comparable between the two groups. Among the 37 patients (61.67%) who switched from FcRn inhibitor therapy to eculizumab, clinical outcomes were non-inferior to those of direct eculizumab recipients and the magnitude of MG-ADL improvement was comparable to that of the overall treatment group. The mean daily corticosteroid dose decreased from 21.21 ± 13.68 mg at baseline to 13.32 ± 10.42 mg at final follow-up (p < 0.0001) Adverse events were rare, with no treatment-related serious events.\nCONCLUSION: Eculizumab provides rapid and sustained clinical improvement in patients with MG, with a favorable safety profile. Patients with TAMG show a faster initial response. For patients with an inadequate response to FcRn inhibitors, eculizumab remains an effective rescue strategy.", "authors": ["Li Yue", "Yang Huan", "Tan Song", "Luo Lijun", "Cao Xuebing", "Hu JinQuan", "Bu Bitao", "Chang Ting", "Li Zhijun"], "journal": "Neurology and therapy", "entry_date": "2026/06/10 23:35", "pub_date": "2026-Jun-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42271114/", "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, 430030, China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "42269550", "title": "Involvement of monocyte/macrophage NLRP3-IL-1β signaling in the pathogenesis of myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis is an autoimmune disorder mediated by pathogenic autoantibodies targeting the neuromuscular junction. Although the role of adaptive immunity is well-established, the involvement of innate immune cells, particularly monocytes and macrophages, in myasthenia gravis pathogenesis remains unclear. This study investigated whether the NLRP3 inflammasome-caspase-1-IL-1β pathway in monocytes and macrophages contributes to disease development in myasthenia gravis and its experimental model.\nMETHODS: Experimental autoimmune myasthenia gravis was induced in Lewis rats by immunization with AChR97-116 peptide. Splenic and lymph node CD11b/c+ macrophages were analyzed by flow cytometry at early (d14), middle (d30), and late (d46) disease stages. Bulk RNA sequencing was performed on sorted splenic CD11b/c+ macrophages from experimental autoimmune myasthenia gravis and control rats at d14. Peripheral blood mononuclear cells were collected from myasthenia gravis patients during clinical exacerbation (n = 36) and healthy controls (n = 35). Monocyte subsets and intracellular caspase-1/IL-1β expression were assessed by flow cytometry. Correlations with clinical severity (QMG score) and lymphocyte counts were analyzed.\nRESULTS: In EAMG rats, the proportion of CD11b/c+ macrophages increased significantly in the spleen and lymph nodes during early and middle disease stages. These macrophages showed elevated expression of Nlrp3, Casp1, and Il1b, with enrichment of the NOD-like receptor signaling pathway. The frequencies of CD11b/c+caspase-1+ and CD11b/c+IL-1β+ macrophages were significantly higher in early and middle stages compared to controls and late stage. In myasthenia gravis patients, the proportion of CD14+ monocytes were increased during clinical exacerbation, with expansion of both classical (CD14++CD16-) and intermediate (CD14++CD16+) subsets. Classical monocytes exhibited elevated IL-1β expression, while intermediate monocytes showed increased caspase-1 expression. The frequency of CD14+ monocytes, CD14+caspase-1+ monocytes and IL-1β expression in intermediate monocytes positively correlated with QMG scores. Moreover, IL-1β+ classical and intermediate monocyte frequencies correlated with CD4+ T cell counts.\nCONCLUSION: Monocytes and macrophages contribute to myasthenia gravis pathogenesis through activation of the NLRP3-caspase-1-IL-1β pathway, particularly during early disease stages. This innate immune activation promotes T cell expansion and correlates with disease severity, suggesting that targeting this pathway may represent a potential therapeutic strategy for myasthenia gravis.", "authors": ["Zhou Yang", "Jia Ye-Fan", "Du Tong", "Zhang Peng", "Yang Xiao-Yu", "Zhai Yu-Yao", "Li Xiao-Li", "Yang Bing", "Liu Ru-Tao", "Yang Chun-Lin", "Duan Rui-Sheng", "Wang Cong-Cong"], "journal": "International immunopharmacology", "entry_date": "2026/06/10 18:10", "pub_date": "2026-Jun-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42269550/", "affiliations": ["Department of Neurology, The First Affiliated Hospital of Shandong First Medical University & Shandong Provincial Qianfoshan Hospital, Jinan, People's Republic of China; Shandong Institute of Neuroimmunology, Jinan, People's Republic of China; Shandong Provincial Medicine and Health Key Laboratory of Neuroimmunology, People's Republic of China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 4.7, "journal_quartile": "2区"}, {"pmid": "42268448", "title": "Thromboembolic risk in subcutaneous versus intravenous immunoglobulin therapy: a systematic review and narrative meta-synthesis.", "abstract": "Intravenous immunoglobulin (IVIg) therapy is associated with thromboembolic complications, including deep vein thrombosis (DVT), pulmonary embolism (PE), ischaemic stroke, and myocardial infarction (MI). Subcutaneous immunoglobulin (SCIg) achieves lower peak serum IgG concentrations and may confer a reduced thromboembolic risk. We systematically reviewed the comparative thromboembolic safety of SCIg versus IVIg across neurological and immunological indications. We searched PubMed, Embase, Cochrane Library, Web of Science, Scopus, and ClinicalTrials.gov from inception to December 2024. Studies reporting thromboembolic events in patients receiving IVIg or SCIg for any indication were eligible. Two reviewers independently screened, extracted data, and assessed risk of bias. Where feasible, pooled incidence rates with 95% confidence intervals (CIs) were calculated using Freeman-Tukey double arcsine transformation. Thirty-four studies (approximately 12,800 patient-years of immunoglobulin exposure) were included. IVIg-treated patients (approximately 10,600 patient-years across 27 studies) experienced thromboembolic events at a pooled incidence of 1.8 per 100 patient-years (95% CI: 0.9-3.1). SCIg-treated patients (approximately 2,200 patient-years across 7 studies) had a pooled incidence of 0.14 per 100 patient-years (95% CI: 0.01-0.52). Only 3 thromboembolic events were documented in SCIg cohorts, all in patients with pre-existing prothrombotic risk factors. No head-to-head randomised trial comparing thromboembolic outcomes between routes exists. GRADE certainty was very low for the comparative estimate. Indirect evidence suggests that SCIg may be associated with a lower thromboembolic risk than IVIg, consistent with pharmacokinetic predictions. However, substantial differences in patient populations, follow-up duration, and event ascertainment between SCIg and IVIg cohorts preclude definitive conclusions. Prospective comparative trials with pre-specified thromboembolic endpoints are needed.", "authors": ["Fang Shihshuan", "Chen Yu-Chieh", "Chen Shenghan"], "journal": "Clinical and experimental medicine", "entry_date": "2026/06/10 11:16", "pub_date": "2026-Jun-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42268448/", "affiliations": ["Department of Geriatrics, Landseed International Hospital, Taoyuan, Taiwan."], "pub_types": ["Journal Article", "Review"], "china_related": true, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 4.5, "journal_quartile": "3区"}, {"pmid": "42266700", "title": "Real-world efficacy of eculizumab in generalized myasthenia gravis patients with poor early response to efgartigimod: a prospective cohort study.", "abstract": "OBJECTIVE: The management of generalized myasthenia gravis (gMG) poses a therapeutic challenge. Efgartigimod, a neonatal Fc receptor (FcRn) inhibitor, has significant efficacy in patients with positive acetylcholine receptor (AChR) antibodies. However, approximately 30% of patients exhibit a poor early response. This study aimed to explore whether the complement C5 inhibitor, eculizumab, can bring clinical benefits to patients who have a poor early response to efgartigimod, thereby investigating potential sequential treatment strategies.\nMETHODS: We first conducted a prospective study to rigorously evaluate and longitudinally follow up 103 patients with gMG who received one treatment cycle of efgartigimod, ultimately enrolling 18 patients who demonstrated an inadequate response to the therapy. Then, these patients received eculizumab induction (900 mg weekly for four weeks) followed by maintenance dosing (1200 mg every two weeks or extended to once every three weeks). Clinical outcomes were assessed using MG-specific activities of daily living (MG-ADL) and quantitative myasthenia gravis (QMG) scores. Safety was evaluated through adverse event reporting.\nRESULTS: Significant clinical improvements were observed during the induction phase, with mean MG-ADL scores demonstrating a reduction from 7.9 ± 3.9 before eculizumab to 2.6 ± 1.7 [-5.3 (95% CI: -7.6 to -3.0); P < 0.001], while QMG scores dropped from 14.1 ± 6.6 to 6.5 ± 3.2 [-7.4 (95% CI: -10.2 to -4.7); P < 0.001]. All patients achieved clinically meaningful improvement (≥2-point MG-ADL reduction), with four patients reaching minimal symptom expression (MSE, defined as an MG-ADL score ≤1-point) by week 4. Among the 12 patients who completed the 16-week follow-up, seven patients (58.3%) achieved minimal symptom expression. Glucocorticoid doses were successfully reduced to ≤5mg per day in seven patients. Two mild adverse events (urinary tract infection and limb edema) were reported.\nCONCLUSION: Eculizumab exhibited rapid and significant efficacy in patients with gMG who were poor early response to efgartigimod, and exhibited a favorable safety profile. These findings suggest that complement inhibition may serve as a potential sequential therapy when FcRn antagonist modulation failure.", "authors": ["An Xueting", "Zhu Lijie", "Huang Xiaoyu", "Zhang Zhouao", "Zhang Yong", "Zhang Chao"], "journal": "Frontiers in immunology", "entry_date": "2026/06/10 04:39", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42266700/", "affiliations": ["Department of Neurology, Tianjin Neurological Institute, Tianjin Medical University General Hospital, Tianjin, China."], "pub_types": ["Journal Article"], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42266578", "title": "Risk factors for disease generalization in acetylcholine receptor antibody-positive ocular myasthenia: a multicenter retrospective study.", "abstract": "OBJECTIVE: This study aimed to identify factors associated with secondary generalization in patients with ocular-onset myasthenia gravis (OoMG) who were positive for anti-acetylcholine receptor (AChR) antibodies. Early identification of patients at higher risk of progression to generalized myasthenia gravis (gMG) is clinically relevant to optimize therapeutic strategies and improve long-term outcomes.\nMETHODS: We conducted a multicenter retrospective cohort study including patients with anti-AChR-positive OoMG recruited from three Italian neurology centers. Demographic, clinical, electrophysiological, and serological data were collected. Univariable and multivariable Cox regression analyses were performed to identify factors associated with disease generalization.\nRESULTS: Among 85 patients, 40 (47.1%) developed gMG during follow-up. In univariable Cox regression, higher anti-AChR antibody titers (HR 3.37, 95% CI 1.53-7.43; p = 0.002) and abnormal repetitive nerve stimulation of facial muscles (HR 2.49, 95% CI 1.16-5.34; p = 0.020) were significantly associated with secondary generalization. However, no independent predictors were identified in multivariable analysis.\nCONCLUSION: Higher anti-AChR antibody titers and abnormal facial repetitive nerve stimulation were associated with an increased risk of secondary generalization in seropositive OoMG. Although these factors did not independently predict generalization in multivariable analysis, their combined assessment may support early clinical risk stratification. Larger prospective studies are warranted to validate these findings and refine prognostic assessment.", "authors": ["Verriello Lorenzo", "Sartor Roberto", "Bellizzi Fabrizio", "Dalla Torre Chiara", "Pessa Maria Elena", "Belluzzo Marco", "Bratina Alessio", "Quagliotto Magda", "Mancinelli Chiara Rosa", "Rana Michele", "Pasquin Fulvio", "Fabris Martina", "Pauletto Giada", "Isola Miriam", "De Martino Maria", "Manganotti Paolo", "Valente Mariarosaria"], "journal": "Frontiers in neurology", "entry_date": "2026/06/10 04:38", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42266578/", "affiliations": ["Neurology Unit, Department of Head-Neck and Neurosciences, Santa Maria della Misericordia University Hospital, Udine, Italy."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42262806", "title": "Women and Myasthenia Gravis.", "abstract": "Myasthenia gravis (MG) is a prototypical antibody-mediated autoimmune disorder of the neuromuscular junction, characterized by fluctuating skeletal muscle weakness and substantial morbidity. Although therapeutic advances have markedly improved survival and long-term outcomes, MG is not a gender-homogeneous condition. Women are disproportionately affected, exhibit a distinct bimodal age distribution, and experience the disease within unique biological and psychosocial contexts that shape presentation, disease course, quality of life, and treatment response. Accumulating evidence highlights sex-specific differences in immune reactivity, hormonal influences, thymic pathology, clinical severity, fatigue burden, and patient-reported outcomes. Notably, women consistently report poorer quality of life despite comparable disease severity. Reproductive health introduces additional complexity, as pregnancy planning, contraception, teratogenic risk, postpartum exacerbation, and neonatal complications profoundly influence clinical decision-making and patient autonomy. Despite these well-recognized disparities, sex-specific considerations remain insufficiently integrated into routine care and are strikingly underrepresented in clinical trial design. Most MG trials fail to stratify outcomes by sex, account for sex-dependent pharmacokinetics or pharmacodynamics, or include pregnancy-relevant populations, resulting in critical evidence gaps. This narrative review synthesizes current knowledge on gender-related pathophysiological mechanisms, clinical phenotypes, and life stage-specific management of MG, with particular emphasis on the reproductive years. It also briefly examines the evolving role of novel biological therapies, including complement inhibitors, neonatal Fc receptor inhibitors, and B-cell-directed agents, which offer promise for more targeted and potentially safer treatment paradigms. Systematic gender-stratified analyses, dedicated pregnancy registries, and proactive, physician-led counselling are essential to advancing equitable, evidence-based care for women living with MG.", "authors": ["Menon Deepak", "Vengalil Seena", "Nashi Saraswati", "Nalini Atchayaram"], "journal": "Annals of Indian Academy of Neurology", "entry_date": "2026/06/09 11:51", "pub_date": "2026-May-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42262806/", "affiliations": ["Department of Neurology, National Institute of Mental Health and Neuro Sciences, Bengaluru, Karnataka, India."], "pub_types": ["Journal Article"], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "42261457", "title": "Refractory Pembrolizumab-Induced Myocarditis-Myositis-Myasthenia Gravis Overlap Syndrome With Concurrent Hepatitis and Thyroiditis in Endometrial Carcinoma: A Case Report.", "abstract": "Immune checkpoint inhibitors (ICIs) have transformed oncologic care but can trigger a spectrum of immune-related adverse events. The triad of myocarditis, myositis, and myasthenia gravis, termed MMM overlap syndrome, is a rare but life-threatening complication. Reports have predominantly involved melanoma and lung cancer; cases of endometrial carcinoma have rarely been described. A 77-year-old woman with stage IV serous endometrial carcinoma presented 24 days after a single dose of carboplatin, paclitaxel, and pembrolizumab, with progressive weakness, ptosis, diplopia, and respiratory compromise. Initial evaluation revealed creatine kinase (CK) of 13,000 IU/L, peak high-sensitivity troponin I of 15,000 ng/L, a new right bundle branch block (RBBB) with intermittent high-degree atrioventricular (AV) block, transaminitis, and thyrotoxicosis, indicating concurrent four-organ toxicity. Acetylcholine receptor (AChR), MuSK, and LRP4 antibodies were all negative, consistent with seronegative ICI-induced myasthenia gravis. She was treated with pulse corticosteroids and plasma exchange (PLEX), with rituximab added after the second session for an inadequate response. Persistent myocarditis with sustained troponin elevation prompted further escalation to abatacept and ruxolitinib. Symptoms and serum biomarkers subsequently improved, and she was discharged on continued corticosteroids and ruxolitinib with a planned graded taper. To our knowledge, this is the second reported case of MMM overlap syndrome in endometrial carcinoma and the first implicating pembrolizumab in this malignancy. The case is distinguished by refractory disease requiring four sequential lines of immunosuppression, concurrent immune-mediated hepatitis and thyroiditis, and a seronegative myasthenia gravis profile, consistent with the more heterogeneous, non-antibody-mediated mechanisms increasingly recognized in ICI-induced disease. It informs treatment escalation in refractory cases and underscores three principles essential to managing this high-mortality syndrome: early recognition, systematic screening for all syndromic components once any one is identified, and timely escalation through multiple lines of immunosuppression when disease proves refractory.", "authors": ["Beereddy Deepika", "Jonnalagadda Durga Naga Malleswara Rao", "Murillo-Garcia David R"], "journal": "Cureus", "entry_date": "2026/06/09 03:56", "pub_date": "2026-Jun", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42261457/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, Reading Hospital-Tower Health, West Reading, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42256950", "title": "The Heart of the Thymus: A Rare Tale of Nonischemic Cardiomyopathy in the Absence of Myasthenia Gravis.", "abstract": "Thymomas are rare epithelial tumors of the anterior mediastinum known for their association with autoimmune and paraneoplastic syndromes, most notably myasthenia gravis (MG). Cardiomyopathy is an exceptionally rare paraneoplastic manifestation. Emerging case reports suggest that thymoma may exert systemic effects independent of MG, including direct or immune-mediated myocardial injury. We report the case of a 54-year-old male with known nonischemic cardiomyopathy who presented with septic shock from pneumonia and cholecystitis, complicated by ventricular arrhythmias and decompensated heart failure. Imaging revealed a calcified anterior mediastinal mass, later diagnosed as a World Health Organization (WHO) type B thymoma. Notably, the patient lacked any clinical or serologic evidence of MG or other autoimmune syndromes. Cardiac magnetic resonance imaging (MRI) excluded myocarditis and takotsubo cardiomyopathy, while coronary angiography ruled out ischemic disease. Despite anticoagulation, a persistent left ventricular (LV) thrombus remained. The patient's cardiac dysfunction necessitated mechanical ventilation, vasopressors, and a multidisciplinary heart failure regimen. This case expands the phenotype of thymoma beyond the traditional paraneoplastic spectrum. It reinforces the need for heightened clinical suspicion and a multisystem diagnostic approach in cases of unexplained cardiomyopathy. Further investigation into immune-mediated cardiac injury in thymoma is warranted.", "authors": ["Barman Manish", "Al Hariri Bassem", "Babiker Tasneem", "Gadkarem Mohamed", "Alhariri Joudi", "Alharafsheh Ahmad"], "journal": "Clinical case reports", "entry_date": "2026/06/08 07:45", "pub_date": "2026-Jun", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42256950/", "pub_types": ["Journal Article"], "affiliations": ["HMGH, Hamad Medical Corporation Doha Qatar."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "42256566", "title": "Validation and clinical utility of OMGRate and MG-QOL15 in evaluating symptoms and quality of life in Chinese patients with ocular myasthenia gravis.", "abstract": "PURPOSE: This study aimed to evaluate the value of the OMGRate and MG-QOL 15 in assessing quality of life (QoL) before and after treatment in ocular myasthenia gravis (OMG) and to validate the applicability of OMGRate in the Chinese OMG population.\nMETHODS: This prospective observational cohort study was conducted via questionnaire among patients diagnosed with OMG at our hospital between November 2022 and January 2024. Patient outcomes were assessed at pre-treatment (baseline), 1, 3, and 6 months post-treatment. Efficacy was assessed using the OMGRate and O-QMGS, while the MG-QOL15 was used to evaluate the QoL of OMG patients.\nRESULTS: Our study included 52 patients with OMG. Age of onset and first Symptoms significantly impacted patients' QoL (p < 0.001); AChR-Ab positivity and thymic abnormalities were associated with disease severity (p < 0.05). Longitudinal observations revealed significant reductions in all scale scores (OMGRate, MG-QOL15, O-QMGS), reaching optimal levels at 6 months. OMGRate-e and OMGRate-q scores demonstrated moderate to strong positive correlations across all observation times; OMGRate and OMGRate-q scores showed positive correlations with MG-QOL15 scores at all observation time points; OMGRate and OMGRate-e scores showed positive correlations with O-QMGS scores only at post-treatment observation time points.\nCONCLUSION: The OMGRate was validated as an effective method for severity assessment in Chinese OMG patients. OMG significantly impairs patients' QoL, whereas standardised treatment not only effectively alleviates clinical symptoms but also concurrently improves quality of life, revealing good consistency between symptomatic improvement and patient-reported outcomes.", "authors": ["Tang Ting", "Feng Qiwen", "Cai Youran", "Dong Yuying", "Chen Jian", "Zhang Rijia", "Zhou Qing"], "journal": "Frontiers in neurology", "entry_date": "2026/06/08 07:42", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42256566/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, The First Affiliated Hospital of Jinan University, Guangzhou, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42256565", "title": "Current status of Internet medical health service usage behavior and demand of myasthenia gravis patients: a cross-sectional study.", "abstract": "OBJECTIVE: Internet-based medical and health services can help patients better manage chronic conditions. This study aimed to investigate the current usage, influencing factors, and needs of Internet medical health services among myasthenia gravis (MG) patients.\nMETHODS: Using a convenience sampling approach, 160 patients with myasthenia gravis who attended the First Affiliated Hospital of Guangzhou University of Chinese Medicine between February and June 2023 were recruited. Participants' baseline characteristics, current status of medical health service use, and demand for Internet medical health service and Internet disease health management services were assessed. Descriptive statistics, chi-squared tests, Fisher's exact tests, and binary logistic regression were used to examine service utilization and the factors influencing it.\nRESULTS: A total of 165 questionnaires were distributed, and 160 valid questionnaires were included. Among the 160 MG patients, 105 (65.6%) were women, and 45.0% were aged ≤ 39 years. The majority of MG patients had used Internet medical health services, but their frequency of use was low. Age and privacy concerns were identified as risk factors, whereas educational level and operational convenience (ease of use) of Internet medical health service software were protective factors. MG patients reported a high demand for online appointment booking (87.5%), knowledge inquiry (78.8%), and online consultation (73.1%). The top three Internet disease management services were medication management (80.0%), symptom management (77.5%), and lifestyle management (73.1%).\nCONCLUSION: MG patients demonstrated a high willingness to use Internet-based medical and health services. However, owing to operational difficulties, privacy concerns, insufficient trust, and other barriers, MG patients have not yet fully utilized these services. Internet medical health services should prioritize highly expected functions and provide information-rich content that is easy to use.", "authors": ["Dong Li", "Huang Yaoyi", "Wang Xinxian", "Bu Hailing", "Yang Yunying", "Su Yining"], "journal": "Frontiers in neurology", "entry_date": "2026/06/08 07:42", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42256565/", "pub_types": ["Journal Article"], "affiliations": ["The First Clinical Medical School of Guangzhou University of Chinese Medicine, Guangzhou, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42254084", "title": "Myasthenia Gravis With Chronic Kidney Disease: A Diagnostic Challenge.", "abstract": "The coexistence of myasthenia gravis (MG) and chronic kidney disease (CKD) presents a diagnostic challenge due to overlapping clinical features. MG is an autoimmune neuromuscular junction disorder, whereas CKD exhibits the gradual loss of kidney function. We report a 65-year-old male with long-standing CKD who developed progressive neuromuscular symptoms, including bilateral ptosis and bulbar involvement. His anti-acetylcholine receptor antibodies were negative; however, electrophysiological studies demonstrated a significant decremental response (> 10%) on repetitive nerve stimulation, supporting the diagnosis of MG. The patient required hemodialysis for worsening renal function and was treated with pyridostigmine for MG symptoms, resulting in clinical improvement. This case emphasizes the importance of distinguishing MG from CKD-related symptoms, particularly in seronegative patients, and highlights the need for careful clinical and electrophysiological evaluation.", "authors": ["Mahmood Zahra", "Mahmud Amina", "Akilimali Aymar"], "journal": "Clinical case reports", "entry_date": "2026/06/08 07:21", "pub_date": "2026-May", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42254084/", "pub_types": ["Journal Article"], "affiliations": ["Department of Nephrology Jinnah Postgraduate Medical Centre Karachi Pakistan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "42254010", "title": "Patient preferences and willingness-to-pay for therapy in generalized myasthenia gravis: a large-scale discrete choice experiment in China.", "abstract": "BACKGROUND: Generalized myasthenia gravis (gMG) is a rare, chronic autoimmune disorder that imposes a substantial disease burden in China. As novel therapeutic options emerge, understanding patient preferences has become essential for treatment decision-making. This study aimed to assess treatment preferences and willingness to pay (WTP) among Chinese gMG patients.\nMETHODS: This multicenter, cross-sectional survey was conducted from March to August 2025 among patients with gMG in China. A discrete choice experiment was used to quantify patient preferences by presenting hypothetical treatment scenarios defined by eight key attributes. A mixed Logit regression model was used to identify preference drivers, and WTP was estimated to reflect the monetary value assigned to changes in treatment attributes.\nRESULTS: Among the 909 analyzed patients, the mean age was 48.9 ± 13.27 years, and 61.8% were female. Within the selected attribute sets, safety was a key determinant of patient preferences, with consistently favored for lower risks of adverse drug reactions (ADRs) on metabolic diseases, infection, myelosuppression, and liver and kidney function impairment; WTP increased as risk levels decreased. Patients preferred oral administration, followed by subcutaneous injection and intravenous infusion. Infrequent dosing, once every-6-month, weekly or daily, was preferred over 2-3 times daily. Faster onset time of action (≤2 weeks) was favored, and higher out-of-pocket costs were disfavored. Subgroup analyses revealed young patients valued once weekly dosing, subcutaneous injection, and low risk of liver and kidney function impairment than old patients. Patients with high disease burden showed similar preferences for low and moderate ADRs risk. High-income patients favored low ADRs risk, infrequent dosing, subcutaneous injection, and were less sensitive to cost than to low- and medium-income patients.\nCONCLUSION: This large-scale study was the first to investigated treatment preferences and WTP among Chinese patients with gMG. Within the selected attribute sets, patients prioritized safety, infrequent and convenient administration route, affordability, and rapid onset of action. Patients were willing to invest financially in therapies that align with these preferences. Incorporating patient preferences in clinical decision-making and reimbursement policy may improve adherence, reduce disease burden, and enhance quality of life for individuals with gMG in China.", "authors": ["Xu Yafang", "Feng Ling", "Zhang Mingjie", "Zhou Jing", "Xiao Hongwei", "Ni Yuwen", "Wang Rui", "He Yueyue", "Jiang Qian", "Peng Jianyu", "Chen Hong", "Zhou Hongyu", "He Dingxian", "Luo Sushan", "Xi Jianying", "Song Jie", "Yan Chong", "Lu Jiahong", "Zhao Chongbo"], "journal": "Frontiers in immunology", "entry_date": "2026/06/08 07:20", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42254010/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Huashan Rare Disease Center and Department of Nursing, Huashan Hospital, National Center for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42254001", "title": "Real-world study of efgartigimod in AChR antibody-positive generalized myasthenia gravis: thymus status, multi-domain symptom improvement and steroid-sparing effect.", "abstract": "BACKGROUND: Efgartigimod has been approved for the treatment of gMG. However, real-world evidence regarding its efficacy across various functional domains in patients with differing thymic statuses, as well as its steroid-sparing effect when used in conjunction with conventional immunotherapy, remains limited.\nMETHODS: This single-center, real-world retrospective study included AChR antibody-positive patients with gMG who underwent at least two cycles of efgartigimod. The primary endpoints were the changes in MG-ADL and QMG scores at weeks 4 and 8. Secondary endpoints encompassed the MSE rate, IgG reduction, subgroup analyses stratified by thymic status and treatment regimens, and improvements in ocular, bulbar, limb, and trunk functional domains. Generalized estimating equations were employed for the analysis of longitudinal data.\nRESULTS: A total of 62 patients participated in the study, comprising 32 females and 30 males, with a mean age of 55 ± 14 years. Significant improvements in the MG-ADL (mean: 4.55 points) and QMG scores (mean: 7.52 points) were noted at week 4 (all P < 0.001), with these benefits sustained at week 8. After two treatment cycles, 77.4% (48/62) of patients experienced CMI. The MSE rate was significantly higher in the abnormal thymus group at week 4 (67.7% vs. 38.7%, P = 0.022), whereas no significant difference was observed between the two groups at weeks 8. Ocular symptoms, particularly ptosis, demonstrated the most substantial improvement, and significant enhancements were also recorded in bulbar and limb functions. Efficacy was comparable across the monotherapy, steroid combination, immunosuppressant combination, and triple therapy groups. Concomitant steroid treatment facilitated a maximum reduction in prednisone dosage of 78%. No adverse events were reported during the study.\nCONCLUSION: Efgartigimod rapidly, significantly, and sustainably alleviates symptoms in patients with AChR antibody-positive gMG, with its efficacy remaining unaffected by thymic status or concurrent immunotherapy. Patients with thymic abnormalities exhibit an earlier therapeutic response; however, long-term outcomes are comparable to those of patients with a normal thymus. The extent of improvement varies across functional domains, with the most pronounced benefits observed in ocular symptoms. Efgartigimod demonstrates independent therapeutic effects and facilitates substantial tapering of steroids when administered alongside glucocorticoids, underscoring its significant clinical value.", "authors": ["Aili Kariman", "Lu Mingjia", "Zhao Na", "Maimaiti Mayinuer"], "journal": "Frontiers in immunology", "entry_date": "2026/06/08 07:20", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42254001/", "pub_types": ["Journal Article"], "affiliations": ["Neuroimmunology Department, Neurology Diagnosis and Treatment Center, People's Hospital of Xinjiang Uygur Autonomous Region, Urumqi, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42251496", "title": "Regarding: Myasthenia gravis following the initiation of statin therapy.", "abstract": "", "authors": ["Zeng Sha", "Shi ZhengRong"], "journal": "Journal of internal medicine", "entry_date": "2026/06/07 02:52", "pub_date": "2026-Jun-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42251496/", "pub_types": ["Letter"], "affiliations": ["Department of Traditional Chinese Medicine Pharmacy, Chengdu Integrated TCM & Western Medicine Hospital, Chengdu, Sichuan, China."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 9.2, "journal_quartile": "1区"}, {"pmid": "42251157", "title": "The neurological adverse events of immune check point inhibitors in the treatment of cancer.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) have revolutionized cancer treatment with significant improvements in survival rates. With the increase in ICI use in the clinical setting, several case reports and series have described neurological adverse events associated with it. We conducted this systematic review and meta-analysis to estimate the incidence of neurological adverse events among ICI clinical trials.\nMETHODS: We searched PubMed, Embase, Scopus, and the Cochrane Central Register of Controlled Trials (CENTRAL) on November 25, 2025, using ICI and clinical trial as keywords along with their related MeSH terms. The inclusion criteria involved clinical trials investigating the efficacy or safety of any ICI as the only systemic therapy among never treated patients with cancer. To eliminate the impact of other systemic therapies, trials that used ICIs as an adjuvant to another systemic treatment or included patients previously treated with any systemic therapies were excluded. The incidence and its 95% confidence interval (95%CI) were used as the effect measures in the analysis. Subgroup analyses were conducted based on the type of cancer and number of ICIs used in the trial.\nRESULTS: We included a total of 8,826 patients with cancer from 31 clinical trials. The pooled incidence of neurological adverse events was 1.78 × 10-3% (95%CI 1.06 × 10-3%-2.78 × 10-3%). There was no difference (p = 0.481) in the incidence of neurological side effects between trials that used one ICI (1.83 × 10-3%; 95%CI 0.81 × 10-3%-3.22 × 10-3%) compared to those that used two ICIs (0.90 × 10-3%; 95%CI 0.01 × 10-3%-2.64 × 10-3%). There was also no significant difference (p > 0.622) in the incidence among patients with hepatocellular carcinoma (HCC) (1.20 × 10-3%; 95%CI 0.01 × 10-3%-3.67 × 10-3%), non-small cell lung carcinoma (NSCLC) (1.83 × 10-3%; 95%CI 0.01 × 10-3%-6.0 × 10-3%), and melanoma (1.16 × 10-3%; 95%CI 0.22 × 10-3%-2.71 × 10-3%). The most common neurological adverse events were peripheral neuropathy (1.34 × 10-3%; 95%CI 0.61 × 10-3%-2.3 × 10-3%), myositis (0.78 × 10-3%; 95%CI 0.29 × 10-3%-1.49 × 10-3%), aseptic meningitis (0.71 × 10-3%; 95%CI 0.25 × 10-3%-1.40 × 10-3%), autoimmune demyelinating polyneuropathy (0.66 × 10-3%; 95%CI 0.21 × 10-3%-1.32 × 10-3%), epilepsy (0.66 × 10-3%; 95%CI 0.21 × 10-3%-1.32 × 10-3%), and myasthenia gravis (0.66 × 10-3%; 95%CI 0.21 × 10-3%-1.32 × 10-3%).\nCONCLUSION: Taken all together, the incidence of ICI-related neurological adverse events among patients with cancer is low and estimated at 1 in 5000 patients. Individual data analysis of ICI clinical trials is needed to examine the factors associated with ICI-related neurological adverse events.", "authors": ["Toubasi Ahmad A", "Al-Sayegh Thuraya N"], "journal": "Journal of neurology", "entry_date": "2026/06/06 23:18", "pub_date": "2026-Jun-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42251157/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Department of Neurology, Vanderbilt University Medical Center (VUMC), 1211 Medical Center Drive, 37232, Nashville, TN, US. Ahmad.tubasi@vumc.org."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "42250887", "title": "Acute Liver Failure in a Patient with Myasthenia Gravis.", "abstract": "", "authors": ["Tang Tianzhi", "Jain Dhanpat", "Block Peter D"], "journal": "Gastroenterology", "entry_date": "2026/06/06 19:36", "pub_date": "2026-Jun-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42250887/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine, Yale New Haven Hospital, New Haven, CT 06510."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 25.1, "journal_quartile": "1区"}, {"pmid": "42247725", "title": "Complement C3 inhibition restores myasthenia gravis AChR antibody-mediated muscle pathophysiology.", "abstract": "BACKGROUND: In the autoimmune disorder myasthenia gravis (MG), the nicotinic acetylcholine receptors (nAChRs) are the primary targets of pathogenic antibodies. While MG mechanisms have been extensively studied in animal models, functional insights into how antibody binding disrupts nAChR-dependent calcium signaling and the effects of complement inhibition in human muscle cells remain limited.\nMETHODS: We used real-time live-cell calcium imaging to assess the effects of cholinergic stimulation or inhibition on human muscle cells with pharmacological agents, sera from patients with acetylcholine receptor antibody seropositive (AChR+) MG, purified recombinant antibodies targeting α- and β-subunits, and a complement C3 inhibitor. Transcriptional changes in nAChR subunits, muscle markers, voltage-gated calcium channels (VGCCs), and complement-related genes were analysed by RT-qPCR. Immunocytochemistry and quantitative image analysis were performed to assess nAChR distribution and membrane attack complex (MAC) deposition.\nFINDINGS: Cholinergic stimulation of human muscle cells activated nAChRs, resulting in membrane depolarisation, which in turn led to VGCC opening and calcium transients. MG-associated pathogenic antibodies, particularly those present in sera from patients with AChR + MG and pure recombinant AChR α-subunit-specific monoclonal antibody (mAb), but not β-subunit-specific, abolished choline-induced calcium responses in myotubes. α-subunit-specific mAb also induced transcriptional upregulation of nAChR subunits, muscle structural proteins, and complement components, and were associated with nAChR loss and MAC formation. Importantly, pharmacological inhibition of C3 activation restored calcium signaling, preserved nAChR distribution, and reduced MAC formation induced by α-subunit-specific mAb, implicating complement activation as a key driver of pathogenic effects.\nINTERPRETATION: These findings indicate that targeting the α-subunit impairs nAChR-dependent calcium signaling and can induce complement activation. Disrupted signaling and reduced nAChR levels were effectively restored by C3 inhibition, which blocks multiple downstream pathways; thus, terminal complement activation leading to MAC formation is a suggested, but it may not be the only mechanism. Overall, the results highlight C3 as a promising upstream therapeutic target and support combining subunit-specific interventions with proximal complement blockade in MG.\nFUNDING: This work was supported by Familjen Erling-Perssons Stiftelse (grant # 2022_0030 to ARP), the Myasthenia Gravis Foundation of America, and the Swedish Research Council (grant # 2025-02779 to ARP). MLF part of the work was supported by a grant from the Deutsche Gesellschaft für Muskelkranke e.V. (DGM).", "authors": ["Huang Yu-Fang", "Bhandage Amol Keshavasa", "Fichtner Miriam L", "Punga Anna Rostedt"], "journal": "EBioMedicine", "entry_date": "2026/06/05 18:00", "pub_date": "2026-Jun-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42247725/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 10.8, "journal_quartile": "1区"}, {"pmid": "42244451", "title": "Translating B-Cell and Plasma-Cell Targeting from Oncology to Autoimmunity: Modalities, Quantitative Bridging, and a Development Roadmap.", "abstract": "B cells drive B-cell malignancies and diverse autoimmune diseases through autoantibody production, antigen presentation, and cytokine dysregulation, and persistence of pathogenic B-cell or plasma-cell compartments. Across autoimmune diseases, the dominant pathogenic compartment varies, ranging from precursor-dependent states to tissue-compartment inflammation and long-lived plasma cell-weighted autoantibody production. This review synthesizes the biological rationale for B-cell-axis targeting across oncology and autoimmunity and proposes a pathobiological framework spanning precursor-dependent, compartment-dominant, and long-lived plasma cell-weighted archetypes. We outline the mechanisms, lineage coverage, depletion depth, durability, and tolerability of CD20-, CD19-, CD38-, and BCMA-directed antibodies, bispecific T-cell engagers, and chimeric antigen receptor (CAR) T cells, and map these modalities onto biologically defined autoimmune archetypes. We also compare dosing paradigms, pharmacokinetics/pharmacodynamics (PK/PD), exposure-response relationships, and safety trade-offs between oncology-style induction and chronic maintenance in autoimmunity, emphasizing biomarker-guided retreatment, infection-risk mitigation, and regimen adaptation for non-malignant disease. Clinically, therapies developed for lymphoma and myeloma have transformed B-cell cancer care and are now being repurposed for rheumatoid arthritis, multiple sclerosis, neuromyelitis optica spectrum disorder, IgG4-related disease, myasthenia gravis, systemic lupus erythematosus, and related disorders. We summarize pivotal translational inflection points, from rituximab extension beyond lymphoma to approvals of ocrelizumab, ofatumumab, ublituximab, and inebilizumab in neuroimmunology. We further review plasma cell-directed and T-cell-engaging strategies for deep immune resets in refractory disease, while clarifying implications for trial design, long-term safety, and implementation. Finally, we introduce a model-informed roadmap integrating population PK/PD, exposure-response, and quantitative systems pharmacology to optimize indication selection, patient enrichment, and dose/regimen design-supporting confident extrapolation rather than empiricism.", "authors": ["Yuan Min", "Xu Xu Steven"], "journal": "Clinical pharmacology and therapeutics", "entry_date": "2026/06/05 04:03", "pub_date": "2026-Jun-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42244451/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Health Data Science, Anhui Medical University, Hefei, Anhui, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "42242900", "title": "Pathogenic properties of myasthenia gravis AChR autoantibodies associate with clinical response to efgartigimod.", "abstract": "BACKGROUND: Efgartigimod, a neonatal Fc receptor (FcRn) blocker, effectively reduces total IgG, including pathogenic acetylcholine receptor (AChR) autoantibodies in myasthenia gravis (MG); however, clinical responses vary. To investigate this variability, we studied how efgartigimod impacts AChR-specific autoantibody profiles and associated pathogenic mechanisms, including complement activation, AChR internalisation and ACh-binding site blockade.\nMETHODS: Serum samples (N=150) were sourced from 50 AChR autoantibody-positive generalised MG patients participating in the phase 3 ADAPT study, randomised to receive efgartigimod (N=40) or placebo (N=10) in cycles of 4-weekly infusions. Samples were collected at baseline, day 29 and day 57 during the first cycle. Live cell-based assays quantified AChR-specific IgG subclasses and isotypes and assessed their capacity to mediate pathomechanisms.\nRESULTS: Efgartigimod decreased all detectable AChR-specific IgG subclasses. At baseline, AChR autoantibody-mediated C3b deposition, AChR internalisation and ACh-binding site blockade were detected in 42 (84%), 41 (82%) and 10 (20%) patients, respectively. After 4-weekly infusions of efgartigimod, the magnitude of all three pathomechanisms was significantly decreased. However, the extent of this reduction varied across individuals. Double responders on both MG-activities of daily living and quantitative MG scores demonstrated a greater reduction in complement activity and AChR internalisation compared with patients who responded on only one score or were double non-responders. In addition, efgartigimod reduced IgG-dependent IgM binding to AChR.\nCONCLUSIONS: These findings suggest that clinical efficacy may be more closely associated with functional modulation of the AChR-specific autoantibodies than with their absolute quantity alone. These results support the evaluation of mechanistic pathway monitoring as a potential strategy to predict or guide efgartigimod treatment response.", "authors": ["Khani-Habibabadi Fatemeh", "Verhamme Fien M", "Moshir Mahan", "Casneuf Tine", "Rao Vijayaraghava T S", "Steeland Sophie", "Ulrichts Peter", "Pham Minh C", "Nowak Richard J", "Roy Bhaskar", "O'Connor Kevin C"], "journal": "Journal of neurology, neurosurgery, and psychiatry", "entry_date": "2026/06/04 21:32", "pub_date": "2026-Jun-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42242900/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Yale School of Medicine, New Haven, Connecticut, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "42239682", "title": "Making the invisible audible: a real-world connected speech study in myasthenia gravis.", "abstract": "BACKGROUND: Bulbar involvement in myasthenia gravis (MG) can affect voice and speech; however, task-dependent and potentially subclinical alterations are often underrecognized.\nMETHODS: We conducted a cross-sectional study of consecutively enrolled adults with confirmed MG at a single center. Participants completed standardized voice recordings and contemporaneous clinical assessments [Myasthenia Gravis–Activities of Daily Living (MG-ADL) and revised Myasthenia Gravis Quality of Life (rMG-QOL15)]. Tasks included sustained vowels, standardized reading, and spontaneous speech. Acoustic metrics comprised root-mean-square intensity (RMS, dB) and fundamental frequency (F0, Hz).\nRESULTS: Seventeen patients were enrolled (median age 58 years; 52.9% female). Median MG-ADL was 6.0 and mean rMG-QOL15 was 16.6, with no significant correlation (ρ = 0.09, p = 0.74). Male participants exhibited significant intensity reductions in connected speech: reading (−3.22 dB, IQR − 5.98 to −2.09; pBH = 0.031; r = 0.84) and spontaneous speech (−5.46 dB, IQR − 6.11 to −4.93; pBH = 0.031; r = 0.84). Female participants showed smaller, non-significant changes (≤ − 2.2 dB; all pBH > 0.7). F0 shifts were modest and non-significant after correction. Across the cohort, MG-ADL correlated with both RMS and F0 drops in unadjusted models but not after adjusting for sex. rMG-QOL15 showed no overall association, although females demonstrated a correlation between F0 drop and QOL burden (ρ = 0.77, p = 0.014).\nCONCLUSION: Connected-speech intensity decrements may represent a sensitive acoustic marker of load-dependent and potentially subclinical bulbar dysfunction in MG, not fully captured by patient-reported outcomes, with potential sex-related differences requiring further validation in larger cohorts.", "authors": ["Zanghì Aurora", "Di Filippo Paola Sofia", "Rutigliano Claudia", "Avolio Carlo", "D'Amico Emanuele"], "journal": "Frontiers in neurology", "entry_date": "2026/06/04 05:42", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42239682/", "pub_types": ["Journal Article"], "affiliations": ["BRAND Center, Department of Medical and Surgical Sciences, University of Foggia, Foggia, Italy."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42238146", "title": "Navigating Anxiety Management in Myasthenia Gravis Crisis With Prolonged Corrected QT (QTc): A Case Report.", "abstract": "Myasthenia gravis (MG) crisis presents significant challenges in medication management, as treatment must balance risks of respiratory depression, worsening neuromuscular transmission, and QT interval prolongation when psychiatric symptoms such as anxiety coexist with medical instability. Concurrent corrected QT (QTc) prolongation further constrains treatment selection by limiting the use of many commonly prescribed anxiolytic and psychotropic agents. We present the case of a 75-year-old male with MG crisis and a markedly prolonged QTc interval of 563 ms, requiring careful balancing of neuromuscular, respiratory, and cardiac risks. Sertraline was selected due to its relatively favorable cardiac profile and established efficacy in anxiety disorders. The patient tolerated treatment without worsening of neuromuscular symptoms, and improvement in anxiety symptoms and QTc interval was observed during hospitalization. These changes occurred in a closely monitored, multifactorial clinical setting that included discontinuation of QT-prolonging medications and overall medical stabilization; therefore, the observed improvements should be interpreted as temporal associations rather than evidence of a direct causal effect of sertraline.", "authors": ["Burky Garrison"], "journal": "Cureus", "entry_date": "2026/06/04 05:26", "pub_date": "2026-May", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42238146/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Psychiatry, Summa Health, Akron, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42236345", "title": "Current management and treatment of patients with myasthenia gravis in France: A survey of the neurologist's perspective.", "abstract": "Myasthenia gravis (MG) is a rare autoimmune disease in which immunoglobulin G autoantibodies targeting post-synaptic receptors at neuromuscular junction play a central role. Due to recent therapeutic developments, there is a need to update current guidelines. FILNEMUS (the French network for rare neuromuscular diseases) conducted a survey in neurologists treating patients with MG to better understand the current clinical and therapeutic management of MG and to identify difficulties and unmet needs. The 45-questions survey assessed various aspects of MG management: including characteristics of neurologists and their patients, the treatments prescribed, and potential areas to improve MG management. Between the 21st of April and the 22nd of August 2022, 2,535 neurologists (90.4%) of the 2,792 registered in France (in 2022) were asked to participate. Finally, 321 complete the survey and were analysed. These population constitute a representative population of neurologists with all French regions and types of medical institutions represented. The survey found that 73.2% of patients with MG are treated by neurologists working in hospitals. Regarding treatment, most neurologists (96.9%) prescribed a cholinesterase inhibitor as first-line treatment most often combined with a corticosteroid (69.1%) or with a non-steroidal immunosuppressant (66.0%). Neurologists working in reference hospital centres tended to prescribe more corticosteroids as first-line treatment for ocular MG and as early disease-modifying treatment for generalized MG. Neurologists identified several aspects of MG management that needed to be improved, including the diagnosis of atypical types of MG, the transfer of patient information from neurologists to general practitioners, the need to optimise existing therapies (improve tolerance and effectiveness), continual medical education for neurologists, as well as the need for improved therapeutic patient education. Our survey shows that evidence from the neurologists' perspective can provide valuable insight into the management of patients with MG and can identify unmet clinical and therapeutics needs.", "authors": ["Cintas P", "Salort-Campana E", "Demeret S", "Stanbury T", "Bouquillon B", "Nadaj-Pakleza A", "Gallard J", "Solé G", "Attarian S"], "journal": "Revue neurologique", "entry_date": "2026/06/03 22:55", "pub_date": "2026-Jun-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42236345/", "pub_types": ["Journal Article"], "affiliations": ["Centre de référence des maladies neuromusculaires (CRMN), CHU de Toulouse, Toulouse, France."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "42235055", "title": "Systematic Review of Chimeric Antigen Receptor T-cell Therapy in Autoimmune Diseases.", "abstract": "OBJECTIVES: This study aimed to systematically summarize available clinical data on the use of chimeric antigen receptor (CAR) T-cell therapy in autoimmune diseases (ADs).\nMETHODS: A systematic review was conducted using PubMed and other literature databases to identify publications on CAR-T therapy in ADs published since 2020. Eligible studies included single-case reports and case series from clinical trials, while studies involving duplicated patient populations were excluded in accordance with PRISMA guidelines. Extractable patient-level data were analyzed for key clinical outcomes.\nRESULTS: A total of 32 studies encompassing 124 patients with ADs who received CAR-T therapy were included. The primary diseases treated were systemic lupus erythematosus (SLE) and myasthenia gravis (MG), with smaller numbers of patients reported in other ADs. In SLE trials, 83% achieved clinical remission or low disease activity following CAR-T therapy, within the first few months following infusion. In MG trials, minimal symptom expression was achieved in 73%. CAR-T disappearance and B-cell reconstitution generally occurred within the first few months following infusion and were predominantly of a naïve phenotype. Mild cytokine release syndrome was the most common adverse event; serious adverse events were reported in 4.8% of patients without treatment-related deaths.\nCONCLUSION: Preliminary clinical evidence suggests that CAR-T therapy is associated with meaningful clinical response in selected ADs. Larger studies with standardized outcome measures and longer follow-up are needed to better define its safety and efficacy.", "authors": ["Hershkowitz Nicole", "Andrzejczyk Anna", "DeStefano Vincent", "Schuster Michael", "Yao Qingping"], "journal": "Journal of clinical rheumatology : practical reports on rheumatic & musculoskeletal diseases", "entry_date": "2026/06/03 16:53", "pub_date": "2026-05-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42235055/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine, Stony Brook University Renaissance Medical School, Stony Brook, NY."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I"}, {"pmid": "42234197", "title": "Clinical effectiveness of efgartigimod in a broad population of patients with generalized myasthenia gravis: subgroup analyses from a randomized, double‑blind, placebo‑controlled, phase 3 trial (ADAPT).", "abstract": "BACKGROUND: The ADAPT phase 3 trial (NCT03669588) showed efgartigimod was well tolerated and efficacious in acetylcholine receptor antibody-positive (AChR-Ab +) patients with generalized myasthenia gravis (gMG). This analysis utilized data from the ADAPT trial to investigate the efficacy and safety of efgartigimod in different patient subgroups.\nMETHODS: ADAPT included a broad population of AChR-Ab + participants who received a stable dose of ≥ 1 (any) treatment for gMG and were randomized 1:1 to efgartigimod (10 mg/kg) or placebo (administered as four once-weekly infusions per cycle) for 26 weeks. Myasthenia Gravis Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG) responder rates in cycles 1 and 2, and rates of treatment-emergent adverse events (TEAEs) were analyzed in the following patient subgroups: history of nonsteroidal immunosuppressive treatment (NSIST), concomitant use of gMG treatments throughout the study, and baseline patient and disease characteristics, including time since diagnosis, age, baseline MG-ADL score, body mass index (BMI), sex, and prior thymectomy.\nRESULTS: In total, 129 AChR-Ab + participants were included (efgartigimod, n = 65; placebo, n = 64). Across all subgroups, higher MG-ADL and QMG responder rates were observed in participants treated with efgartigimod versus placebo during cycles 1 and 2. Rates of TEAEs were similar between participants treated with efgartigimod and placebo, regardless of concomitant gMG treatment type.\nCONCLUSION: Similar to outcomes observed in the ADAPT overall population, efgartigimod was well tolerated and efficacious across a broad range of patients, regardless of NSIST treatment history, concomitant use of gMG treatments, or baseline patient and disease characteristics.\nTRIAL REGISTRATION: ClinicalTrials.gov: NCT03669588 (registered September 13, 2018).", "authors": ["Howard James F", "Saccà Francesco", "Hoffmann Sarah", "Attarian Shahram", "De Bleecker Jan L", "Beauchamp Jon", "Brauer Edward", "Kerstens René", "Vissing John", "Meisel Andreas"], "journal": "Journal of neurology", "entry_date": "2026/06/03 11:16", "pub_date": "2026-06-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42234197/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase III", "Multicenter Study"], "affiliations": ["Department of Neurology, University of North Carolina at Chapel Hill, Chapel Hill, NC, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "42233901", "title": "Triple M Overlap Syndrome After Immune Checkpoint Inhibitors: A Case Series of a High-Mortality Phenotype.", "abstract": "Immune checkpoint inhibitor-associated Triple M overlap syndrome (TMOS), defined by concurrent myocarditis, myositis, and myasthenia gravis, is a rare but life-threatening immune-related adverse event. We report a single-center case series of 8 consecutive patients who developed TMOS during immune checkpoint inhibitor therapy for solid malignancies between 2023 and 2025. Median age was 76 years and median time to symptom onset was 14.5 days after exposure. All patients had myositis symptoms; 5 required mechanical ventilation and 1 subsequently required tracheostomy. Cardiac involvement was characterized by troponin elevation and frequent electrical abnormalities, including complete atrioventricular block, ventricular tachyarrhythmias, and bundle branch block, despite preserved left ventricular systolic function on imaging. Corticosteroid monotherapy was insufficient in practice, and all patients required additional immunomodulatory therapy. TMOS requires early recognition, close monitoring, and rapid multidisciplinary escalation of care.", "authors": ["Osorio Maria F", "Mitta Alekhya", "Malaguez-Webber Fabricio", "Jani Chinmay T", "Bilusic Marijo", "Maning Jennifer", "Wever-Pinzon Omar", "Chatzizisis Yiannis S"], "journal": "JACC. Case reports", "entry_date": "2026/06/03 10:30", "pub_date": "2026-06-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42233901/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["University of Miami/Jackson Memorial Hospital, Miami, Florida, USA. Electronic address: mfo40@miami.edu."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "42233017", "title": "Case Report: Anti-LGI1 encephalitis during FcRn inhibition with efgartigimod for myasthenia gravis: implications for the limitations of IgG recycling blockade.", "abstract": "OBJECTIVES: Anti-leucine-rich glioma-inactivated 1 (LGI1) antibody-associated autoimmune encephalitis is a treatable disorder characterized by subacute cognitive impairment. Efgartigimod is a neonatal Fc receptor (FcRn) antagonist that reduces circulating IgG levels. It is approved for the treatment of generalized myasthenia gravis (MG) and has recently been explored as a therapeutic option for antibody-mediated neurological diseases. We report a patient who developed anti-LGI1 antibody-associated encephalitis during ongoing efgartigimod therapy despite reduced serum IgG levels, raising considerations regarding the mechanisms of central nervous system autoimmunity under FcRn inhibition.\nMETHODS: A 72-year-old woman with thymoma-associated MG receiving efgartigimod was evaluated after presenting with rapidly progressive memory impairment. Clinical assessment included neurological examination, brain magnetic resonance imaging, cerebrospinal fluid analysis, and serological testing for neuronal and paraneoplastic antibodies.\nRESULTS: Brain magnetic resonance imaging revealed bilateral medial temporal lobe hyperintensities. Cerebrospinal fluid analysis showed negative LGI1 antibodies and a normal IgG index (0.524), with no evidence suggestive of intrathecal IgG synthesis. Subsequent serological testing confirmed anti-LGI1 antibody positivity, and anti-titin antibodies were also detected. High-dose intravenous methylprednisolone therapy resulted in marked clinical improvement.\nDISCUSSION: This case highlights a clinically relevant scenario in which autoimmune encephalitis can arise during FcRn inhibition therapy, suggesting that reduction of circulating IgG alone may be insufficient to prevent central nervous system autoimmunity. The absence of intrathecal IgG synthesis raises the possibility that pathogenic antibodies were predominantly derived from the peripheral compartment. These findings underscore the pharmacodynamic limitations of FcRn inhibition, particularly in the setting of thymoma-associated immune dysregulation.", "authors": ["Komatsu Yuka", "Eura Nobuyuki", "Nishimori Yukako", "Kakehi Yoshiaki", "Kiriyama Takao", "Sugie Kazuma"], "journal": "Frontiers in immunology", "entry_date": "2026/06/03 04:57", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42233017/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Nara Medical University, Nara, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42232178", "title": "Immune checkpoint inhibitors and myocarditis-myositis-myasthenia gravis overlap: a FAERS pharmacovigilance study with time-to-onset characterization.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) are associated with rare but life-threatening immune-related adverse events. Myocarditis-myositis-myasthenia gravis (MMM) overlap is among the most severe neuromuscular-cardiac toxicity patterns, but population-scale data on disproportionality, reported death outcomes, and time-to-onset (TTO) remain limited.\nMETHODS: We conducted a retrospective pharmacovigilance study using the FDA Adverse Event Reporting System (FAERS) from 2015Q1 to 2025Q4. Strict MMM overlap was defined at the report level by co-reporting of the Preferred Terms \"myocarditis,\" \"myositis,\" and \"myasthenia gravis\". ICI exposure was restricted to selected PD-1, PD-L1, and CTLA-4 inhibitors recorded as primary or secondary suspect drugs (PS/SS), with a prespecified sensitivity analysis restricted to PS reports only. Disproportionality was assessed primarily using reporting odds ratios (RORs) with Haldane-Anscombe correction for sparse cells; the Information Component (IC) and IC025 were calculated as complementary Bayesian metrics. Drug-level TTO was estimated by linking therapy start dates and event dates within eligible reports.\nRESULTS: Among 15,187,311 deduplicated FAERS reports, 151 met the strict MMM overlap definition, including 131 ICI-exposed reports. ICI exposure showed a strong disproportionality signal for strict MMM overlap (ROR 397.29, 95% CI 249.44-632.76; IC 5.50, IC025 5.24). Reported death outcomes were observed in 49/131 (37.4%) ICI-exposed MMM overlap reports, including 31/80 (38.8%) in PD-1 reports, 5/16 (31.3%) in PD-L1 reports, and 13/35 (37.1%) in combination ICI reports. Drug-level TTO was available for 53 ICI-exposed reports, with a median of 25 days (IQR 18-38); restricting to TTO ≤365 days yielded a similar median of 24 days (IQR 18-37), supporting a predominantly early-onset pattern. Sensitivity analyses restricted to PS were directionally consistent.\nCONCLUSION: In FAERS, ICI-associated strict MMM overlap showed a strong disproportionality signal and predominantly early reported onset; reported death outcomes were also observed in a substantial proportion of ICI-exposed overlap reports. These findings support heightened clinical vigilance for cardio-neuromuscular overlap toxicity, particularly during the first months after ICI initiation.", "authors": ["Pacaci Burak", "Yildirim Bilal", "Tunc Mustafa Alperen", "Demirel Ahmet", "Akagunduz Firat", "Kocaaslan Erkam", "Guren Ali Kaan", "Demircan Nazim Can", "Bayoglu Ibrahim Vedat"], "journal": "Frontiers in pharmacology", "entry_date": "2026/06/03 04:47", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42232178/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medical Oncology, Marmara University Pendik Training and Research Hospital, Istanbul, Türkiye."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "42231266", "title": "Patient-reported health utility in adults with myasthenia gravis: a systematic review and meta-analysis of EQ-5D outcomes.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder associated with impaired health-related quality of life. EQ-5D utility and EQ-VAS scores are used in health economic evaluations, but reported estimates vary across MG populations, instruments, tariffs, and study designs.\nMETHODS: We systematically searched PubMed, Embase, Scopus, and CENTRAL from inception to February 2026. Observational studies and randomized controlled trials reporting baseline or pre-intervention EQ-5D utility or EQ-VAS data in adults with MG were included. Random-effects meta-analyses used restricted maximum likelihood estimation. Subgroup, sensitivity, GRADE-informed certainty, and exploratory aggregate-level meta-regression analyses were performed.\nRESULTS: Ten studies were included. Eight studies (n = 1,514) contributed to EQ-5D utility synthesis, yielding a descriptive pooled mean of 0.74 (95% CI 0.68-0.80), with very high heterogeneity (I² = 95.4%; Cochran Q p < 0.001) and a wide prediction interval (0.52-0.96). Seven studies (n = 2,760) contributed to EQ-VAS synthesis, with a descriptive pooled mean of 66.49 (95% CI 60.99-71.99), very high heterogeneity (I² = 96.3%; Cochran Q p < 0.001), and a wide prediction interval (47.70-85.28). Sensitivity analysis excluding the RCT baseline dataset did not materially change the pooled EQ-5D estimate. In an exploratory analysis based on two studies, utility declined across Myasthenia Gravis Foundation of America (MGFA) classes I-IV. Exploratory meta-regression suggested a possible negative association between mean disease duration and utility, but certainty was very low.\nCONCLUSION: EQ-5D and EQ-VAS estimates indicate impaired patient-reported health status in MG, but pooled values should be interpreted as low-certainty descriptive summaries, not definitive utility inputs.", "authors": ["Budumuri Venkata Siva Karthik", "G Akshaya Kamalashree", "Murugadoss Hariharan", "Arun Vasanth", "Basheer Aneesh"], "journal": "BMC neurology", "entry_date": "2026/06/03 01:00", "pub_date": "2026-06-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42231266/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Department of General Medicine, SRM Medical College Hospital and Research Centre, Faculty of Medicine and Health Sciences, SRM Institute of science and technology, Kattankulathur, Chengalpattu, Tamilnadu, India."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "42227466", "title": "[Research Progress of CAR-T Cell Therapy in Autoimmune Diseases --Review].", "abstract": "Chimeric antigen receptor T (CAR-T) cell therapy has achieved significant success in the field of hematologic oncology. Considering the similarities in the origin and circulatory distribution between hematopoietic tumor cells and autoantigen-specific immune cells, research has commenced to apply CAR-T cell therapy to autoimmune diseases, yielding encouraging preliminary findings. This article reviews the mechanisms of action and clinical research data of CAR-T cells in diseases such as systemic lupus erythematosus, multiple sclerosis, type 1 diabetes, myasthenia gravis, and rheumatoid arthritis in recent years, with the aim of providing a broader perspective for the future application of CAR-T cells in the field of autoimmune diseases.\n题目: CAR-T细胞治疗在自身免疫性疾病中的研究进展.\n摘要: 嵌合抗原受体T（CAR-T）细胞疗法已经在血液肿瘤领域取得了卓越成就。鉴于血液系统肿瘤细胞和自身抗原特异性免疫细胞在起源和循环分布上的相似性，已有研究开始将此技术应用于自身免疫性疾病，并获得了令人鼓舞的初步研究成果。本文对近年来CAR-T细胞在系统性红斑狼疮、多发性硬化、Ⅰ型糖尿病、重症肌无力和类风湿性关节炎等疾病中的作用机制和临床研究数据进行了综述，期望为CAR-T细胞未来在自身免疫疾病领域的应用提供更广阔的视角.", "authors": ["Xiong Qiang", "Li Fei"], "journal": "Zhongguo shi yan xue ye xue za zhi", "entry_date": "2026/06/02 06:53", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42227466/", "pub_types": ["Journal Article", "Review", "English Abstract"], "affiliations": ["Department of Hematology, The First Affiliated Hospital of Nanchang University, Nanchang 330006, Jiangxi Province, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "42224956", "title": "The alterations of blood immune subpopulations, cytokines, and metabolites in anti-acetylcholine receptor antibody-positive myasthenia gravis: a real-world, observational, high-throughput study.", "abstract": "Comprehensive profiling of peripheral blood may reveal candidate markers and therapeutic targets for anti-AChR antibody positive myasthenia gravis (MG) patients. We enrolled 37 anti-AChR antibody positive MG patients and 37 healthy controls (HCs), and blood immune cells were analyzed by mass cytometry, plasma proteins were determined by Cytokine Array, and metabolites were measured by targeted metabolomics. Compared with HCs, anti-AChR antibody positive MG patients showed increased classical monocytes and Th2-like cells, and decreased Th1-like cells, regulatory T cells, CD4+T, and CD28+T cells. Cytokine profiling revealed reduced retinol-binding protein 4 (RBP4), epithelial neutrophil-activating peptide 78 (ENA-78), and stem cell factor receptor (SCF-R), but elevated angiogenin, RANTES (CCL5), and cystatin-A. Metabolomics indicated lower dehydroepiandrosterone sulfate (DHEAS), cystine, and arginine, with higher lactate, sarcosine, and ornithine. Notably, glucocorticoid pretreatment reduced myeloid dendritic cells, Th2-like cells, dendritic cells, classical monocytes, and total monocytes. Integrated multi-omics analysis identified immune-metabolic interactions associated with anti-AChR antibody positive MG pathogenesis. This study highlights potential candidate markers and provides insights for targeted therapy.", "authors": ["Meng Huanyu", "Chen Xiaoyu", "Zhu Zhuoying", "Sun Guangqiang", "He Lu", "Zhou Qinming", "Li Liang", "Yang Xinying", "Chu Xingkun", "Yang Dabing", "Feng Yuan", "Zhang Jing", "Chen Sheng"], "journal": "Immunobiology", "entry_date": "2026/06/01 18:07", "pub_date": "2026-05-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42224956/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Wuxi branch of Ruijin Hospital, Shanghai Jiao Tong University School of Medicine, Wuxi, Jiangsu Province, China; Department of Neurology, Ruijin Hospital, Shanghai Jiao Tong University School of Medicine, Shanghai, China; Clinical Center for Rare Diseases, Ruijin Hospital, Shanghai Jiao Tong University School of Medicine, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "42223343", "title": "Tacrolimus as Single-Agent Immunotherapy for Adult-Onset Myasthenia Gravis: Remission, Relapse, and Safety.", "abstract": "AIMS: To identify factors influencing remission and relapse, and to evaluate the safety of tacrolimus monotherapy (TAMO) in adult-onset mild-to-moderate myasthenia gravis (MG).\nMETHODS: This retrospective analysis was conducted on MG patients receiving TAMO. Remission was defined as achieving minimal symptom expression (MSE), and multivariable Cox regression analysis identified predictors of remission and relapse. Cancer risk was assessed by standardized incidence ratio (SIR), based on the age-specific cancer incidence rates in China in 2022.\nRESULTS: Among 153 patients, 77.8% achieved MSE, with a median time of 6.0 months. Age at onset (hazard ratio [HR] = 0.982, 95% confidence interval [CI] = 0.968-0.995, p = 0.009) and new-onset MG (HR = 2.065, 95% CI = 1.266-3.368, p = 0.004) were independent predictors of time to achieving MSE. The optimal cut-off value for age at onset was 70 years. Relapse occurred in 31% of patients. Tacrolimus concentration at MSE (HR = 0.815, 95% CI = 0.695-0.956, p = 0.012) and dose reduction speed (HR = 1.717, 95% CI = 1.280-2.305, p < 0.001) were independent predictors of relapse. The cut-off values were 5.30 ng/mL and 1.08 mg/year, respectively. Adverse drug reactions (ADRs) occurred in 45.0% of the 200 patients receiving TAMO, with hyperglycemia being the most common (17.5%). Eight patients developed cancer, and the SIR was 2.86 (95% CI = 1.23-5.63, p = 0.005) compared with the general Chinese population.\nCONCLUSION: TAMO was associated with higher rates of MSE in adult-onset mild-to-moderate MG patients with new-onset disease or with an onset age ≤ 70 years. To avoid MG relapse, tacrolimus concentration > 5.30 ng/mL at MSE and dose reduction speed ≤ 1.08 mg/year can be considered. Cancer surveillance may be considered for elderly patients undergoing long-term tacrolimus therapy. Limitations include the retrospective, uncontrolled design, moderate sample sizes, and limited follow-up duration; thus, long-term safety, particularly cancer risk, requires further validation.", "authors": ["Geng Zhangyan", "Jiang Yuting", "Xie Nairong", "Zhu Wenjia", "Chen Hai", "Wang Yaye", "Liu Haoran", "Liu Qinyao", "Lv Congwen", "Qian Yu", "Lu Yan", "Di Li", "Wang Min", "Xu Min", "Wen Xinmei", "Xie Bingchuan", "Da Yuwei"], "journal": "CNS neuroscience & therapeutics", "entry_date": "2026/06/01 09:53", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42223343/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Hospital of Hebei Medical University, Shijiazhuang, Hebei, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.0, "journal_quartile": "2区"}, {"pmid": "42220523", "title": "Complement C5 inhibition in generalized myasthenia gravis is associated with improved survival and increased cardiovascular risk.", "abstract": "BACKGROUND: Complement C5 inhibitors are effective disease-modifying therapies for acetylcholine receptor antibody-positive generalized myasthenia gravis (MG), but cardiovascular safety has not been evaluated as a dedicated outcome domain. With increasing and prolonged use, systematic assessment of cardiovascular and thromboembolic risk - including potential differences between individual C5 inhibitors - is needed.\nMETHODS: We performed a retrospective cohort study using the TriNetX federated electronic health record network, including adults with generalized MG. Propensity score-matched cohorts compared patients treated with C5 inhibitors with untreated controls (N = 1,094 vs. 1,094), and ravulizumab with eculizumab (N = 330 vs. 330). Outcomes included major adverse cardiovascular events (MACE), thrombotic disorders, acute kidney injury (AKI), arrhythmias, and all-cause mortality over 365 days. Associations were evaluated using risk ratios (RR) and Cox proportional hazards models.\nRESULTS: After matching, C5 inhibition was associated with increased risk of AKI (6.1% vs 3.2%, p<0.01; RR 1.70) and thrombotic disorders (5.1% vs 2.6%, p=0.002; RR 1.74) compared to no C5-inhibition treatment. All-cause mortality was significantly lower among C5-treated patients after one year (RR 0.54; p=0.045). MACE occurred more frequently with C5 inhibition (8.3% vs 5.5%; p=0.009), with a trend toward higher hazard over time. In agent-specific analyses (ravulizumab vs. eculizumab), ravulizumab was associated with a significantly lower hazard of MACE compared with eculizumab (6.6% vs 11.1%, p=0.041; HR 0.58, while hazards for mortality, thrombotic events, and other cardiovascular outcomes were similar.\nCONCLUSIONS: C5 inhibition in generalized MG is associated with improved survival but increased cardiovascular and thromboembolic risk. Although limited by its retrospective design, this analysis highlights a clinically relevant safety signal and suggests heterogeneity within the C5 inhibitor class. As use of complement inhibition expands, careful longitudinal cardiovascular monitoring will become increasingly important for clinicians managing patients with MG.", "authors": ["Vahldieck Carl", "Fels Benedikt"], "journal": "Frontiers in immunology", "entry_date": "2026/06/01 05:56", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42220523/", "pub_types": ["Journal Article"], "affiliations": ["Department of Anesthesiology and Intensive Care Medicine, University Medical Centre Schleswig-Holstein, Luebeck, Germany."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42218175", "title": "Development of the first myasthenia gravis patient registry in Latvia: a single-centre experience.", "abstract": "This study describes the development of Latvia's first myasthenia gravis (MG) patient registry in a single-centre setting. Adults with confirmed MG were recruited between January 2022 and May 2025 at Pauls Stradiņš Clinical University Hospital. Demographic and clinical data were collected, and patients were assessed using the MGFA Clinical Classification, MG Composite (MGC), MG-ADL, MGQOL15, and Fatigue Severity Scale (FSS). Data were stored in a secure digital registry. A total of 112 patients were enrolled (62/107 (55%) female, from the available data; mean age 57.2 years), with 523 visits recorded. Median disease duration was 4.5 years. Antibody profiles were 76% AChR, 4% anti-MuSK, and 6% seronegative, with 14% missing data. At baseline, 25% of patients were in remission; after a median follow-up of 1.3 years (IQR 0.8-1.9 years), remission increased to 34%, while MGFA classes III-IV declined from 19 to 2%. Median MGC, MG-ADL, and MGQOL15 scores improved significantly (p < 0.001). FSS improved modestly (45.5 → 42.0, p = 0.049), 50% reported relevant fatigue. Median prednisone dose decreased from 15.0 to 7.5 mg (p < 0.001). The registry demonstrates the feasibility of structured longitudinal data collection in MG, with clinical improvement observed during follow-up, although fatigue remains a persistent burden.", "authors": ["Grosmane-Bataraga Arta", "Krutovs Vladimirs", "Roddate Marija", "Žukova Violeta", "Ķauķe Gundega", "Glāzere Ieva", "Gailīte Linda", "Kurjāne Nataļja", "Ķēniņa Viktorija"], "journal": "Scientific reports", "entry_date": "2026/05/30 23:15", "pub_date": "2026-05-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42218175/", "pub_types": ["Journal Article"], "affiliations": ["Scientific Laboratory of Molecular Genetics, Rīga Stradiņš University, Riga, Latvia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "42216195", "title": "Triple M overlap syndrome in the intensive care unit: differential diagnosis and management.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) are increasingly used as first-line therapy for various malignancies and are associated with a growing spectrum of immune-related adverse events. While many toxicities are managed in the outpatient setting, a clinically significant subset progresses to life-threatening multisystem disease requiring intensive care. Among these, the Triple M overlap syndrome, characterized by concurrent myasthenia gravis-like disease, inflammatory myositis, and myocarditis, represents the most severe and lethal phenotype encountered in critical care.\nMAIN TEXT: Triple M overlap syndrome presents unique diagnostic and management challenges in critically ill patients. Clinical features frequently overlap with sepsis, pneumonia, thromboembolism, and cardiopulmonary disease, creating significant diagnostic uncertainty. In addition, traditional diagnostic tools such as myasthenia gravis antibody testing and early cardiac imaging may be normal or nondiagnostic early in the disease course. This review focuses on the recognition and management of Triple M overlap syndrome in the intensive care unit. We highlight key diagnostic pitfalls, including the frequent under-recognition of occult myocarditis and the limitations of electrophysiologic and serologic testing. A structured ICU-oriented approach is proposed, emphasizing early multisystem evaluation with creatine kinase, serial troponins, electrocardiography, and cardiac imaging, alongside concurrent assessment for infection. Management strategies include prompt discontinuation of ICIs, early initiation of corticosteroids, and escalation to intravenous immunoglobulin or plasma exchange for severe neuromuscular involvement. Cardiac complications require close monitoring and early immunosuppression. Targeted therapies such as abatacept are discussed in the context of myocarditis, with current evidence limited primarily to cardiac involvement. This review emphasizes a practical ICU-oriented framework incorporating parallel evaluation for immune-mediated toxicity and infection in critically ill patients.\nCONCLUSION: Triple M overlap syndrome represents a high-risk and often underrecognized manifestation of ICI toxicity in critically ill patients. Early recognition, parallel evaluation for infection and immune-mediated disease, and coordinated multisystem management are essential to improving outcomes. Greater awareness and structured diagnostic approaches may reduce delays in treatment and associated mortality.", "authors": ["Shah Chail", "Rajalbandi Rakesh Shetty", "Seshadri Vikram", "Chandra Alvin", "Abidoye Oluseyi", "Battley Joshua"], "journal": "Critical care (London, England)", "entry_date": "2026/05/29 23:45", "pub_date": "2026-05-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42216195/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuro Critical Care, Department of Neurology, UT Southwestern Medical Center, 5323 Harry Hines Blvd, Dallas, TX, 75390, USA. Chaildeepak.shah@utsouthwestern.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 9.3, "journal_quartile": "1区"}, {"pmid": "42216051", "title": "Monoclonal antibody passive experimental autoimmune myasthenia gravis: current progress and future directions.", "abstract": "Experimental Autoimmune Myasthenia Gravis (EAMG) remains a cornerstone platform for mechanistic studies of pathogenic antibodies in myasthenia gravis (MG). In particular, monoclonal antibody passive-transfer EAMG (mAb-PTMG) has been instrumental in establishing causal links between defined antibody specificities and downstream neuromuscular junction (NMJ) dysfunction, as well as in dissecting key mechanisms underlying AChR antibody-mediated disease. More recently, PTMG studies using patient-derived MuSK monoclonal antibodies have expanded the mechanistic landscape of MG and provided an in vivo framework for evaluating the efficacy and mechanisms of action of agonistic anti-MuSK therapeutic antibodies. In this review, we summarize practical considerations for monoclonal antibody sourcing and preparation, standardized experimental workflows, major readouts and their interpretation, and representative applications across MG subtypes. We also highlight emerging opportunities for model refinement and translational application, with the aim of supporting mechanism-guided interpretation and the development of targeted antibody therapies.", "authors": ["Zheng Liting", "Wang Jianghao", "Tang Siying", "Zhang Meiying", "Yu Zheng"], "journal": "Cell & bioscience", "entry_date": "2026/05/29 23:38", "pub_date": "2026-05-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42216051/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of neurology, The Second Affiliated Hospital of Fujian Medical University, Quanzhou, 362000, Fujian Province, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 6.2, "journal_quartile": "2区"}, {"pmid": "42211303", "title": "Association of steroid regimens and withdrawal with relapse risk in myasthenia gravis: a real-world cohort study.", "abstract": "BACKGROUND: Corticosteroids (steroids) are the first-line immunotherapy for myasthenia gravis (MG), but the optimal steroid dosing regimen and effects of discontinuation remain unclear. This study aimed to investigate the associations of steroid regimens and steroid withdrawal with relapse risk in patients on steroid monotherapy.\nMETHODS: This cohort study, based on a prospective registry, included MG patients who achieved minimal manifestations or better status for at least 6 months with steroid monotherapy. The primary outcome was relapse. Group-based trajectory modeling (GBTM) identified steroid regimens, and Cox proportional hazards models with propensity score matching (PSM) assessed the association of regimens and steroid withdrawal with relapse.\nRESULTS: Among 209 patients followed for a median of 54.0 months, 113 (54.1%) experienced relapses. GBTM identified three regimens reflecting baseline disease severity: \"High Start, Fast Taper\" (Regimen 1), \"Moderate Start, Gradual Taper\" (Regimen 2), and \"Low Start, Slow Taper\" (Regimen 3). Compared to the high-risk Regimen 1, Regimen 2 (HR = 0.27, p < 0.001) and Regimen 3 (HR = 0.15, p < 0.001) were associated with significantly lower relapse risks. A statistically determined cut-off analysis found that requiring a maximum induction dose >0.83 mg/kg to achieve MM or better status was a predictor of relapse (HR = 1.54, p = 0.033). Sixty-eight (32.5%) withdrew steroids, and PSM showed that steroid withdrawal significantly increased relapse risk versus low-dose maintenance (HR = 1.64, p = 0.009).\nCONCLUSION: In this steroid-responsive population, patients requiring a maximum induction dose > 0.83 mg/kg to achieve MM or better status have a significantly higher risk of future relapse. Steroid withdrawal is associated with a higher relapse risk compared to low-dose maintenance and should be approached with caution.", "authors": ["Huang Yangyu", "Tan Ying", "Yan Jingwen", "Guan Yuzhou"], "journal": "Frontiers in neurology", "entry_date": "2026/05/29 04:48", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42211303/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking Union Medical College Hospital, Peking Union Medical College, Chinese Academy of Medical Sciences, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42211300", "title": "Disease-specific divergence of inflammatory and metabolic biomarkers in neurocritical neuromuscular disorders.", "abstract": "BACKGROUND: Myasthenia gravis (MG) and Guillain-Barré syndrome (GBS) are immune mediated neuromuscular disorders that may require intensive immunotherapy and respiratory support. Although inflammatory biomarkers have been explored in both conditions, their diagnosis specific prognostic value remains unclear. We aimed to compare hemogram-derived inflammatory indices and metabolic injury-related biomarkers in hospitalized MG and GBS patients and to evaluate their associations with disease severity and clinical outcomes.\nMETHODS: This retrospective cohort study included 162 patients (88 MG, 74 GBS) treated with intravenous immunoglobulin and/or plasma exchange. Hemogram-derived indices (neutrophil-to-lymphocyte ratio [NLR], systemic immune-inflammation index [SII]), classical inflammatory markers, and metabolic biomarkers including lactate dehydrogenase (LDH) and the LDH to albumin ratio (LAR) were analyzed in relation to neurological severity, length of hospital stay (LOS), and mechanical ventilation (MV). Receiver operating characteristic analyses and diagnosis-specific multivariable logistic regression models were performed.\nRESULTS: Mechanical ventilation occurred in 10.5% of patients and was strongly associated with baseline neurological severity in both disorders (p < 0.001). In MG, hemogram-derived indices (particularly NLR and SII) demonstrated good discriminatory performance for severe disease and were associated with adverse outcomes. LDH-based parameters, particularly LAR, which may reflect metabolic stress, were associated with disease severity and respiratory involvement in MG. In GBS, outcomes were predominantly determined by neurological severity measures, whereas inflammatory indices showed limited and inconsistent prognostic value. Post-treatment transaminase elevations were modestly associated with more severe disease in GBS. In multivariable models, baseline clinical severity remained the most consistent determinant of mechanical ventilation across both conditions.\nCONCLUSIONS: Biomarker utility differs between MG and GBS. In MG, inflammatory indices and LDH-based parameters, particularly the LAR, were associated with disease severity and may support risk stratification, including identification of patients at risk for respiratory deterioration. These findings are exploratory and require prospective validation. In GBS, outcomes remain primarily determined by neurological severity.", "authors": ["Kehaya Sezgin", "Şensöz Erdi"], "journal": "Frontiers in neurology", "entry_date": "2026/05/29 04:48", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42211300/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Faculty of Medicine, Trakya University, Edirne, Türkiye."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42209038", "title": "Intrathecal morphine pump associated Trichosporon infection complicated by new-onset myasthenia gravis.", "abstract": "Fungal infections in immunocompetent patients-even those with intrathecal drug delivery pumps (ITDDPs)-are exceedingly rare. This is the first report of Trichosporon arachnoiditis in a patient with an ITDDP. The patient presented with falls and progressive lower extremity weakness. Imaging showed a compressive lesion, for which the patient was taken for exploration and decompression. Cultures grew Trichosporon and pathology showed fungus consistent with Aspergillus The patient's recovery was complicated by respiratory failure requiring re-intubation secondary to an exacerbation of myasthenia gravis. Additionally, the patient developed cholestatic hepatotoxicity from voriconazole requiring biliary sphincterotomy and replacement of voriconazole. ITDDPs pose a significant risk of infection, and although fungal arachnoiditis is rare, it should be considered in the differential diagnosis in this patient population.", "authors": ["Gluski Jacob", "Santangelo Gabrielle", "Sciubba Daniel M", "Nieto Jamie"], "journal": "BMJ case reports", "entry_date": "2026/05/28 20:53", "pub_date": "2026-05-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42209038/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Neurosurgery, Wayne State University, Detroit, Michigan, USA jgluski@northwell.edu."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "42207816", "title": "A preliminary cost-utility analysis of routine myasthenia gravis and thyroid dysfunction screening in acquired comitant Esotropia.", "abstract": "This study evaluated the cost-effectiveness of routine screening for acetylcholine receptor antibody (AChR-Ab) and thyroid function tests (TFT) in patients with acquired comitant esotropia (ACE) without overt signs of myasthenia gravis (MG) or thyroid eye disease (TED). A retrospective cost-utility analysis was conducted in 110 patients at a Thai tertiary hospital between 2014 and 2024. A decision tree combined with a 10-year Markov model compared two strategies: no routine screening (symptom-triggered testing) and universal baseline screening with AChR-Ab and TFT. Costs were expressed in 2024 Thai Baht (THB) from a healthcare sector perspective, and outcomes were measured in quality-adjusted life years (QALYs). Model uncertainty was assessed using one-way sensitivity analyses and probabilistic sensitivity analysis with 10,000 simulations, incorporating downstream costs of follow-up, confirmatory evaluation, and treatment. In the base-case analysis incorporating real-world diagnostic accuracy, universal screening yielded higher QALYs (109.56 vs. 105.45) but also higher costs (฿2,826,680 vs. ฿1,653,500), resulting in an incremental cost-effectiveness ratio (ICER) of ฿285,360 per QALY gained. This exceeded Thailand's willingness-to-pay threshold of ฿160,000-200,000 per QALY, indicating that universal screening was not cost-effective. Probabilistic sensitivity analysis showed that most simulations were located in the northeast quadrant of the cost-effectiveness plane, reflecting greater effectiveness with higher cost, with many exceeding the willingness-to-pay threshold. Key drivers included MG prevalence, utility loss from undiagnosed MG, and AChR-Ab test cost. TFT screening contributed minimal benefit due to the very low prevalence of thyroid dysfunction. Universal AChR-Ab screening may improve early detection of MG in ACE, but it was not cost-effective under current assumptions. Exploratory targeted screening appeared relatively more efficient, and symptom-triggered thyroid testing may be a more appropriate approach. These findings are preliminary and require validation in larger studies.", "authors": ["Srimanan Worapot", "Keokajee Phawasutthi", "Sawangsribanterng Sunita"], "journal": "PloS one", "entry_date": "2026/05/28 13:43", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42207816/", "pub_types": ["Journal Article"], "affiliations": ["Division of Ophthalmology, Phramongkutklao Hospital, Bangkok, Thailand."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "42202556", "title": "Correspondence regarding: Clinical and quality-of-life outcomes associated with efgartigimod in patients with generalized myasthenia gravis transitioning from intravenous immunoglobulin.", "abstract": "", "authors": ["Azarmi Ajirlou Elshan"], "journal": "Clinical neurology and neurosurgery", "entry_date": "2026/05/27 18:05", "pub_date": "2026-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42202556/", "pub_types": ["Letter"], "affiliations": ["School of Medicine, Tehran University of Medical Sciences, Tehran, Iran. Electronic address: elshanazarmi@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "42202343", "title": "Botulinum Toxin Procedures: A Practical Approach to Cosmetic Injections.", "abstract": "Botulinum toxin injection for treatment of facial wrinkles is the most commonly performed minimally invasive cosmetic procedure in the United States. Cosmetic indications approved by the US Food and Drug Administration include treatment of wrinkles in the upper face (eg, glabellar lines [frown lines], frontalis lines [horizontal forehead lines], lateral orbicularis oculi lines [crow's feet]). Treatment offers predictable results with high patient satisfaction and few adverse effects. Facial wrinkles are formed by dermal atrophy and repetitive contraction of underlying musculature. Injection of small quantities of botulinum toxin, a potent neurotoxin, into specific overactive muscles causes localized muscle relaxation, smoothing the overlying skin and thereby reducing wrinkles. Clinical effects of botulinum toxin typically take 2 weeks to fully develop and last approximately 3 to 4 months. Treatment of dynamic wrinkles, seen during muscle contraction, yield more dramatic results than static wrinkles, which are visible at rest. Botulinum toxin injection is contraindicated in patients with keloidal scarring, neuromuscular disorders (eg, myasthenia gravis), and allergy to constituents of the botulinum toxin product. Minor bruising and swelling can occur with these injections. Temporary blepharoptosis and eyebrow ptosis are technique-dependent complications, and their incidence declines as injector skill improves. Clinicians can attain procedural proficiency through formal instructional courses and precepting with an experienced aesthetic medicine clinician.", "authors": ["Small Rebecca"], "journal": "American family physician", "entry_date": "2026/05/27 17:54", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42202343/", "pub_types": ["Journal Article", "Review"], "affiliations": ["University of California-San Francisco (UCSF) School of Medicine, San Francisco."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "42200436", "title": "Therapeutic Apheresis in Nigeria: A Multi-Center Summary of Abstracts From the Inaugural Nigerian Society for Apheresis Scientific Meeting.", "abstract": "BACKGROUND: Therapeutic apheresis (TA) is an established treatment modality for hematologic, neurologic, and immunologic disorders, yet access remains severely limited in sub-Saharan Africa. Donor apheresis, including platelet apheresis collection from healthy donors, represents an important complementary modality supporting blood product availability and national transfusion services. The Nigerian Society for Apheresis (NSFA) held its inaugural scientific meeting on February 6, 2026, representing a significant milestone in advancing apheresis services in West Africa.\nMETHODS: We present a comprehensive summary of seven oral presentations and three poster abstracts submitted to the inaugural NSFA meeting, representing multi-center experiences from Lagos, southeastern Nigeria, and international collaborative programs.\nRESULTS: Collectively, over 3800 therapeutic and donor apheresis procedures were reported across multiple centers over varying time periods. The most common procedures were apheresis platelets (73.7% of 2405 procedures at one center) and automated red cell exchange for sickle cell disease (25.7%). Therapeutic plasma exchange (TPE) was performed for neurological indications including Guillain-Barré syndrome, myasthenia gravis, and neuromyelitis optica, as well as for renal transplant desensitization. A national survey revealed limited awareness among healthcare workers (mean knowledge score 5.10 ± 2.44/10), yet 88.4% expressed interest in hands-on training. International collaboration through the ISN Sister Renal Centers program successfully established TPE capabilities at two centers in southwestern Nigeria. Common challenges included equipment availability, consumables supply, and cost barriers.\nCONCLUSIONS: These abstracts demonstrate growing therapeutic and donor apheresis capacity in Nigeria despite significant infrastructural and economic challenges. The establishment of NSFA and collaborative international programs represents a critical step toward expanding access to this essential therapy in West Africa.", "authors": ["Bazuaye Nosa", "Okwuonu Chimezie", "Idam Evelyn", "Adelekan-Popoola Folasade", "Gold-Olufadi Shakirat", "Kalejaiye Olufunto Olufela", "Ogala Abdullateef", "Aloziem Zinnah", "Amamchukwu Blossom", "Elimia Patience", "Obot-Obot Mkpoikanabasi", "Mbakwe Henry", "Maduagwuna Praises", "Akinrodoye Olatunji", "Anyanwu Chiamaka", "Anyanwu Benjamin", "Akinsiku Adedamola", "Akinsiku Oluwatoyin A", "Hassan Muzamil O", "Arogundade Fatiu A", "Ojo Olalekan E", "Weli Homayemem", "Adenihun Jesupelumi", "Adelaja Aderemi", "Bamgboye Ebun", "Olatise Olalekan", "Faponle Ade E", "Odeyemi Ayoola", "Muoka Michael", "Asaolu Stephen", "Busari Qudrat", "Dawudu Blessing", "Naiyeju Michael", "Balogun Rasheed A"], "journal": "Therapeutic apheresis and dialysis : official peer-reviewed journal of the International Society for Apheresis, the Japanese Society for Apheresis, the Japanese Society for Dialysis Therapy", "entry_date": "2026/05/27 06:52", "pub_date": "2026-05-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42200436/", "pub_types": ["Journal Article", "Review"], "affiliations": ["African Medical Center of Excellence, Abuja, Nigeria."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "42199478", "title": "Preperitoneal Myelolipoma Occurring after Video-Assisted Thoracoscopic Surgery for Thymoma: A Case Report.", "abstract": "INTRODUCTION: Myelolipoma is a benign tumor composed of mature adipose tissue and hematopoietic elements that typically arises in the adrenal glands, and involvement of the anterior abdominal region is extremely uncommon. We report a rare case of myelolipoma arising in the subxiphoid preperitoneal region adjacent to the site where a sternum-lifting device had been placed during previous surgery.\nCASE PRESENTATION: A 62-year-old man had undergone extended thymectomy for thymoma associated with myasthenia gravis at the age of 39. The procedure was performed via bilateral video-assisted thoracoscopic surgery using a sternum-lifting technique. The tumor was classified as Masaoka stage III, and postoperative radiotherapy was administered. No recurrence was observed during 13 years of follow-up. Ten years after completion of follow-up, CT performed for an unrelated condition incidentally revealed a slowly enlarging 65 × 40-mm mass in the preperitoneal space, adjacent to the previous surgical site where a sternum-lifting device had been placed. MRI demonstrated a fat-containing component within the lesion, and the differential diagnosis included liposarcoma and teratoma. Complete surgical resection was therefore planned. A midline incision extending caudally from the xiphoid process was made, and en bloc resection of the tumor with the involved peritoneum was performed via laparotomy. Histopathological examination revealed mature adipose tissue admixed with hematopoietic elements, confirming the diagnosis of myelolipoma.\nCONCLUSIONS: This unique case of extra-adrenal myelolipoma highlights the importance of MRI-based qualitative assessment for tumors arising at unusual sites and underscores the need to include extra-adrenal myelolipoma in the differential diagnosis of fat-containing lesions occurring at previous surgical sites.", "authors": ["Nakagami Chikara", "Kumata Sakiko", "Inoue Chihiro", "Ogasawara Hiroyuki", "Watanabe Tatsuaki", "Ito Takayasu", "Kobayashi Jun-Ichi", "Oriyama Ko", "Kamata Satoshi", "Kawakami Toru", "Onodera Ken", "Watanabe Yui", "Suzuki Takaya", "Notsuda Hirotsugu", "Oishi Hisashi", "Okada Yoshinori"], "journal": "Surgical case reports", "entry_date": "2026/05/27 04:27", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42199478/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Thoracic Surgery, Institute of Development, Aging and Cancer, Tohoku University, Sendai, Miyagi, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "42199141", "title": "Multidimensional roles of acetylcholine receptors in neurobiology and their therapeutic significance.", "abstract": "Dysfunction of cholinergic signaling has emerged as a convergent mechanism across neurological and neuromuscular disorders, linking disturbances in synaptic, immune, and metabolic regulation. This review summarizes recent structural, functional, and imaging advances, demonstrating that nicotinic and muscarinic acetylcholine receptors play central roles in neural plasticity, neurotransmission, and neuroimmune homeostasis. Studies in structural biology and molecular pharmacology have clarified receptor architectures and conformational transitions, which enhance our understanding of subtype-specific ligand binding and signaling bias. This knowledge, in turn, supports the development of rational strategies for therapeutic modulation. In vivo molecular imaging using positron emission tomography and single-photon emission computed tomography has provided important insights into receptor distribution and binding changes in Alzheimer's disease, Parkinson's disease, schizophrenia, and myasthenia gravis. These findings suggest that impaired cholinergic tone contributes to synaptic instability, dopaminergic imbalance, and neuroinflammatory processes. Experimental and translational studies further indicate that selective agonists and positive allosteric modulators targeting cholinergic pathways can restore aspects of neurotransmission and neuronal function, supporting their potential for clinical translation. Beyond small-molecule pharmacology, the use of engineered exosome delivery systems and artificial intelligence-driven ligand discovery has opened new directions for improving receptor targeting and blood-brain barrier permeability. Although these emerging methods remain at an early stage, they offer valuable opportunities for optimizing receptor selectivity and drug delivery efficiency. Overall, the collective findings indicate that acetylcholine receptors act as integrative modulators of neuronal, glial, and immune communication. Continued integration of structural, imaging, and computational methodologies may help refine receptor-based therapeutic strategies. Such interdisciplinary efforts are expected to advance the development of more targeted and durable cholinergic interventions that promote neuronal resilience and functional recovery in neurological and neuromuscular diseases.", "authors": ["Zhang Yongcai", "Yu Zhenzhen", "Luo Wen", "Zhan Yihong", "Chen Jindong", "Wang Chen"], "journal": "Neural regeneration research", "entry_date": "2026/05/27 04:14", "pub_date": "2026-05-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42199141/", "pub_types": ["Journal Article"], "affiliations": ["Xiamen Xianyue Hospital, Xianyue Hospital Affiliated to Xiamen Medical College, Fujian Psychiatric Center, Fujian Clinical Research Center for Mental Disorders, Xiamen, Fujian Province, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 6.7, "journal_quartile": "2区"}, {"pmid": "42198688", "title": "Epstein-Barr Virus-Positive Primary CNS Lymphoma in a Patient Receiving Mycophenolate Mofetil: Diagnostic and Therapeutic Considerations.", "abstract": "Epstein-Barr virus (EBV)-positive primary central nervous system lymphoma (PCNSL) is a rare entity typically associated with profound immunosuppression, most commonly in transplant recipients or individuals with HIV. We report a case of EBV-positive PCNSL arising in a 75-year-old male with myasthenia gravis receiving chronic mycophenolate mofetil (MMF) therapy outside the transplant setting. The patient presented with progressive neurological deficits, and brain magnetic resonance imaging demonstrated multiple enhancing lesions. Stereotactic biopsy revealed diffuse large B-cell lymphoma of non-germinal center subtype with immunoblastic features and EBV-encoded RNA (EBER) positivity, confirming EBV-positive PCNSL. MMF was discontinued, and the patient was treated with rituximab and high-dose methotrexate, resulting in stable disease. This case highlights that prolonged MMF therapy may confer sufficient immunosuppression to permit EBV-driven lymphoproliferative disease even in non-transplant patients. Early recognition, withdrawal of immunosuppression, and initiation of methotrexate-based chemotherapy can lead to favorable outcomes.", "authors": ["Burner Danielle N", "López Giselle Y", "Low Justin T", "Luftig Micah A"], "journal": "Viruses", "entry_date": "2026/05/27 01:25", "pub_date": "2026-04-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42198688/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Molecular Genetics and Microbiology, Duke University School of Medicine, Durham, NC 27710, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "42190696", "title": "Treatment Patterns and Outcomes of Anti-MuSK Antibody-Positive Myasthenia Gravis: A Retrospective Single-Center Study.", "abstract": "BACKGROUND: There is limited knowledge regarding the real-world treatment status of muscle-specific tyrosine kinase antibody-positive myasthenia gravis (MuSK-MG) patients in clinical practice. The aim of this study was to analyze the overall treatment patterns and outcomes of MuSK-MG in Korea.\nMETHODS: In this single-center cohort study, we retrospectively included patients diagnosed with MuSK-MG. We analyzed their demographic features, clinical characteristics, treatment patterns focusing on corticosteroids (CSs), non-steroidal immunosuppressants (NSISs), and rituximab, and treatment outcomes. Specifically, we investigated the achievement of minimal manifestation status with a prednisolone dose 5 mg/day or below (MM-5).\nRESULTS: The study included 30 patients with MuSK-MG, predominantly female (93.3%). The average age at time of diagnosis was 43.9 ± 16.0 years, with the onset age of 42.3 ± 16.2 years. All patients initially received CSs, and 24 patients (80%) were treated with NSISs. Tacrolimus was the most frequently prescribed NSIS, used in 70.8% of cases, followed by azathioprine (62.5%). All 10 patients who received rituximab therapy showed clinical improvement, with 5 patients (50%) achieving MM-5.\nCONCLUSION: This study summarized the treatment patterns and outcomes of patients with MuSK-MG in real-world clinical settings. As patients who received rituximab demonstrated a favorable prognosis, early administration of rituximab may be an effective treatment strategy for MuSK-MG, potentially reducing the adverse effects associated with long-term use of CSs and NSISs. Rituximab should be considered early in MuSK-MG patients who show insufficient response to initial immunosuppressive treatment.", "authors": ["Seo Dongjin", "Chung Hye Yoon", "Kim Ki Hoon", "Kim Seung Woo", "Shin Ha Young"], "journal": "Journal of Korean medical science", "entry_date": "2026/05/26 18:52", "pub_date": "2026-05-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42190696/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Severance Hospital, Yonsei University College of Medicine, Seoul, Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "42190394", "title": "Can muscle ultrasound assessments aid in the diagnosis of Myasthenia gravis? Findings from a single-center case-control study.", "abstract": "OBJECTIVE: Fatigability and fluctuating muscle weakness represent the hallmarks of Myasthenia gravis (MG). This study investigates whether muscle ultrasound (MUS) can detect muscle fatigability in patients with generalized MG (gMG).\nMETHODS: In this single-center case-control study, 35 gMG patients and 35 matched healthy controls underwent standardized MUS assessment of four limb muscles (deltoid, biceps brachii, rectus femoris, tibialis anterior). Muscle echogenicity, thickness, and area (A) were assessed during rest and maximum voluntary contraction, both before and after a standardized exercise protocol. Interphase changes were quantified to reflect baseline contractility, post-exercise contractility, and fatigability [(f); post- versus pre-exercise contractility)]. The potential of MUS parameters to distinguish gMG patients from healthy individuals was evaluated using receiver operating characteristic analyses. A data-driven approach based on individual indices was used to derive composite indices across muscles with potential superior discriminatory value.\nRESULTS: Among all MUS parameters, fatigability-related changes in muscle area [A(f)] consistently differentiated gMG patients from controls across all examined muscles. Composite A(f) indices, which sum the number of fatigable muscles, demonstrated good to excellent accuracy, correctly classifying approximately 90% of participants. Discriminatory performance remained robust across subgroups defined by disease severity and cumulative corticosteroid exposure.\nCONCLUSIONS: A(f) discerns gMG patients from healthy controls. Further validation in longitudinal and prediagnostic cohorts is warranted to examine the potential utility of MUS in pragmatic diagnostic settings.\nSIGNIFICANCE: Given its ability to differentiate between patients and healthy individuals, MUS may serve as a complementary tool in diagnosis and monitoring of gMG.", "authors": ["Dimitriou Elena", "Spiliopoulos Kanellos C", "Liampas Ioannis", "Veltsista Dimitra", "Kefalopoulou Zinovia", "Chroni Elisabeth", "van Alfen Nens"], "journal": "Clinical neurophysiology : official journal of the International Federation of Clinical Neurophysiology", "entry_date": "2026/05/26 18:06", "pub_date": "2026-05-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42190394/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University Hospital of Patras, Patras, Greece. Electronic address: elenadim90@gmail.com."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "42190146", "title": "Comparative Study of Sporadic and Immune Checkpoint Inhibitor-Related Forms of Myasthenia Gravis-Myositis Overlap Syndrome.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis-inflammatory myopathy (MG-IM) overlap syndrome can occur as an immune-related adverse event (irAE) after immune checkpoint inhibitor (ICI) therapy. Before the advent of ICIs, a sporadic form of MG-IM (s-MG-IM), often thymoma-associated, was already described. This study compared clinical and serologic features, treatment strategies, and outcomes of s-MG-IM and ICI-related MG-IM (ir-MG-IM).\nMETHODS: We conducted a multicenter, retrospective cohort study across 8 Italian centers, including consecutive patients fulfilling established criteria for both MG and IM, with or without previous exposure to ICIs. Clinical features, antibody profiles, oncologic history, treatments, and outcomes were collected and compared. Available serum samples were tested for binding capacity and pathogenic properties (antigenic modulation and complement-activating capacity) against clustered adult (A) and fetal (F) AChR isoforms using a live cell-based assay (L-CBA).\nRESULTS: Thirty-eight patients were identified (19 with s-MG-IM and 19 with ir-MG-IM). The ir-MG-IM cohort was older (median 77 vs 59 years, p < 0.001), predominantly male (84.2% vs 47.4%), and exclusively presented with concurrent MG/IM onset, whereas s-MG-IM often manifested sequentially. Thymoma was detected in 73.7% of patients with s-MG-IM but in none of the ir-MG-IM group. CK levels were higher in the ir-MG-IM cohort (median 3,145 vs 1,000 U/L, p = 0.001). Myocarditis, orbital myositis, and severe bulbar/respiratory involvement were more frequent in the ir-MG-IM cohort (p < 0.05). Anti-AChR antibodies were found in all patients with s-MG-IM and in 68% of patients with ir-MG-IM. Exploratory in vitro assays showed antigenic modulation and complement activation in s-MG-IM serum samples (8/9), whereas no activity was detected in the ir-MG-IM samples tested (0/4). Anti-titin antibodies were identified in 85.7% of patients with s-MG-IM (all thymoma-associated) and 50% of patients with ir-MG-IM. Acute mortality occurred in 36.8% of patients with ir-MG-IM and in no patients with s-MG-IM (p < 0.01). Relapses occurred in 63.2% of patients with s-MG-IM but were absent in patients with ir-MG-IM (p < 0.001).\nDISCUSSION: Although they share some similarities, s-MG-IM represents a chronic, predominantly thymoma-associated overlap syndrome with classical MG and IM features, whereas ir-MG-IM is typically an aggressive, likely monophasic condition characterized by severe myositis, with frequent ocular and cardiac involvement, and lacking classical MG features. Study limitations include the retrospective design, small sample size, and limited serum availability, warranting confirmation in larger prospective cohorts.", "authors": ["Lauletta Antonio", "Rossini Elena", "Beretta Francesca", "Damato Valentina", "Rossi Simone", "Iorio Raffaele", "Marchioni Enrico", "Petrucci Antonio", "Vogrig Alberto", "Romano Carmela", "Tufano Laura", "Leonardi Luca", "Morino Stefania", "Forcina Francesca", "Marando Demetrio", "Vera Valentina", "Falso Silvia", "Marini Sofia", "Spagni Gregorio", "Masciocchi Stefano", "Bini Paola", "Lotti Antonio", "Garibaldi Matteo", "Fionda Laura"], "journal": "Neurology", "entry_date": "2026/05/26 16:02", "pub_date": "2026-06-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42190146/", "pub_types": ["Journal Article", "Comparative Study", "Multicenter Study"], "affiliations": ["Department of Neuroscience, Mental Health and Sensory Organs (NESMOS), SAPIENZA University of Rome, Italy."], "china_related": false, "study_types": ["Non-randomized controlled cohort"], "evidence_level": "III", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "42186189", "title": "[PEMBROLIZUMAB-ASSOCIATED MYOCARDITIS FOLLOWED BY STEROID MYOPATHY IN A PATIENT WITH RENAL CELL CARCINOMA].", "abstract": "Immune checkpoint inhibitors (ICIs) are increasingly used as adjuvant therapy in high-risk renal cell carcinoma (RCC), but may cause serious immune-related adverse events, such as myocarditis. We report a rare case of myocarditis followed by steroid-induced myopathy during adjuvant pembrolizumab therapy. A 74-year-old man underwent partial and radical nephrectomy for bilateral clear cell RCC (pT1b and pT3a). Pembrolizumab was initiated postoperatively. On day 22, he developed exertional fatigue and cardiac enzyme levels were elevated. Myocardial biopsy confirmed myocarditis, and corticosteroid pulse therapy was started. Although cardiac markers improved initially, they rose again, requiring a second steroid pulse and higher maintenance doses. After 27 days of steroid therapy, the patient developed severe proximal muscle weakness. Myasthenia gravis and other autoimmune diseases were excluded. Steroid-induced myopathy was diagnosed, and steroid tapering plus rehabilitation led to functional recovery. He was later discharged without recurrence of myocarditis. This case highlights the importance of early detection and treatment of ICI-related myocarditis and awareness of secondary complications such as steroid myopathy. Multidisciplinary care is essential in managing these rare but serious conditions.", "authors": ["Nagano Yuki", "Hirayama Yukiyoshi", "Iwamoto Kouhei", "Takahashi Katsuya", "Kimura Kaoru", "Nishide Syunji", "Hasaka Tomohiro", "Nishihara Chikako", "Asai Toshihiro", "Ishii Keiichi", "Kamikawa Sadanori"], "journal": "Hinyokika kiyo. Acta urologica Japonica", "entry_date": "2026/05/26 01:04", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42186189/", "pub_types": ["Journal Article", "Case Reports", "English Abstract"], "affiliations": ["The Department of Urology, Osaka City General Hospital."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "42184545", "title": "Outcomes in checkpoint inhibitor induced neuromuscular immune related adverse events: A case series.", "abstract": "Immune-checkpoint inhibitors, a mainstay of treatment of solid tumors, rarely lead to activation of the host immune system against another target, causing autoimmune inflammation of other end organs known as immune-related adverse events (ir-AEs). When ir-AEs are directed at the neuromuscular system, clinical consequences include myositis and myasthenic syndromes. In this article, we describe three cases presenting with neuromuscular ir-AEs. Two patients had lung adenocarcinoma and were treated with pembrolizumab. One patient had gastroesophageal junction adenocarcinoma treated with nivolumab. Each were found to be seropositive for an autoantibody implicated in myasthenia gravis. All patients came off immunotherapy, halted cancer-directed treatments, and transitioned to comfort care following ir-AE onset. We emphasize that while most described neuromuscular ir-AE cases improve with treatment, in a subset of patients, neuromuscular ir-AEs lead to termination of cancer-directed care and transition to comfort care. To our knowledge, this study is the first in the literature to look specifically at a group of patients who withdrew attempts at curative therapy following neuromuscular ir-AE diagnosis. Better understanding of neuromuscular ir-AE treatment and identification of patients at higher risk for neuromuscular ir-AEs are needed.", "authors": ["Lanni James", "Bose Abigail", "Cachia David"], "journal": "Journal of neuroimmunology", "entry_date": "2026/05/25 18:03", "pub_date": "2026-05-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42184545/", "pub_types": ["Journal Article"], "affiliations": ["University of Massachusetts Chan Medical School, 55 North Lake Ave., Worcester, MA, United States of America. Electronic address: james.lanni@umassmed.edu."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42182700", "title": "Limited adoption of thymectomy for nonthymomatous myasthenia gravis.", "abstract": "BACKGROUND: Thymectomy had been an accepted treatment for myasthenia gravis (MG) for decades. Despite this, practice patterns of thymectomy for MG vary even though there is growing evidence of its safety and efficacy. This retrospective database study aimed to assess the safety of thymectomy for patients with nonthymomatous MG and to determine how surgical management of nonthymomatous MG changed following the 2016 publication of results from a phase 3, multicenter, randomized trial (MGTX trial) demonstrating thymectomy plus prednisone was superior to medical management alone.\nMETHODS: We retrospectively reviewed all thymectomy cases 2005-2023 in the National Surgical Quality Improvement Program (NSQIP) database. We compiled postoperative complications and mortality into broad and narrow composite outcomes to display adverse events associated with thymectomy in MG patients. We then used National Institutes of Health (NIH) Joinpoint models to indicate changes in annual rates of thymectomy (in general) and minimally invasive thymectomy (specifically) for MG between 2005-2023 pre- and post- publication of the MGTX trial.\nRESULTS: The queried NSQIP database had a total of 352 nonthymomatous thymectomies performed on MG patients between 2005-2023. The odds of experiencing a broad composite outcome following thymectomy was 7.1% (N=25) and the odds of experiencing a narrow outcome was 3.1% (N=11). The data also showed that there were no 30-day mortalities. Annual percentage change (APC) of thymectomy and minimally invasive thymectomy for MG gradually increased until 2019 and 2020 (2.52% and 4.01% APC, respectively), before decreasing through 2023 (-10.79% APC, P=0.02, and -17.51% APC, P=0.27, respectively).\nCONCLUSIONS: Following the 2016 MGTX trial, thymectomy continues to be a safe procedure among MG patients. Despite this, the current study reveals limited adoption of thymectomy into practice as reflected by the predicted annual rate of thymectomy in MG patients.", "authors": ["Carrera Daniel", "Sadur Alana", "Ely Sora", "Kaminski Henry J", "Mortman Keith"], "journal": "Journal of thoracic disease", "entry_date": "2026/05/25 08:12", "pub_date": "2026-04-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42182700/", "pub_types": ["Journal Article"], "affiliations": ["Division of Thoracic Surgery, Department of Surgery, The George Washington University, Washington, DC, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "42182584", "title": "An Immune Model Incorporating NK Cells and IL-12 to Predict the Efficacy of the Initial Treatment Cycle of Efgartigimod in Generalized Myasthenia Gravis.", "abstract": "BACKGROUND: Efgartigimod (EFG), a neonatal Fc receptor (FcRn) antagonist for generalized myasthenia gravis (gMG), exhibits variable treatment responses. This study aimed to investigate the associations of baseline clinical characteristics and multidimensional immune profiles with the clinical response to EFG in patients with acetylcholine receptor antibody-positive (AChR+) gMG, and develop a predictive model.\nMETHODS: This multicenter retrospective observational study enrolled 35 AChR+ gMG patients who received at least one cycle of EFG. Responders were defined as those achieving a Myasthenia Gravis Activities of Daily Living (MG-ADL) score reduction of ≥ 2 points that was sustained for ≥ 1 month. After univariable screening, three models (Clinical, Immune, Integrated) were constructed using a complete-case modeling subset of 26 patients via multivariable logistic regression, least absolute shrinkage and selection operator (LASSO), and random forest algorithms. The optimal model was selected via leave-one-out cross-validation (LOOCV) and translated into a clinical risk score and an online calculator.\nRESULTS: Among 35 patients, 25 responded (68.6%). Non-responders had significantly higher baseline NK cell counts (p = 0.013) and showed a trend toward lower IL-12p70 levels (p = 0.095). Both NK cell (OR = 0.985) and IL-12p70 (OR = 11.657) were independent predictors of EFG response. The Immune Model (NK cells + IL-12p70) demonstrated robust discrimination (AUC = 0.861), outperforming the Clinical Model (AUC = 0.625, p = 0.021) and the Integrated Model (AUC = 0.847, p = 0.782). It showed good calibration and clinical utility. Bootstrap validation confirmed robustness (corrected AUC = 0.872, optimism=0.017). A derived clinical risk score stratified patients into high (100%), moderate (80.0%), and low (33.3%) response probability groups. An online prediction calculator was developed.\nCONCLUSION: Baseline NK cell counts and IL-12p70 levels may predict EFG response in AChR+ gMG. The dual-biomarker Immune Model demonstrates robust performance, and has been translated into an online tool but yet requires validation in prospective, larger cohorts.", "authors": ["Xin Hanyu", "Zhong Yuan", "Zhang Mengze", "Wu Lianshuang", "Li Qiuju", "Li Xia", "Wu Yanan", "Zhang Lu", "Peng Jing", "Xie Chong", "Zhu Desheng", "Hao Yong", "Guan Yangtai", "Wang Kan"], "journal": "Drug design, development and therapy", "entry_date": "2026/05/25 08:12", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42182584/", "pub_types": ["Journal Article", "Observational Study", "Multicenter Study"], "affiliations": ["Department of Neurology, Punan Branch of Renji Hospital, Shanghai Jiao Tong University School of Medicine (Punan Hospital in Pudong New District), Shanghai, 200125, People's Republic of China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.1, "journal_quartile": "2区"}, {"pmid": "42181373", "title": "Myositis-Myasthenia Overlap Syndrome After Immune Checkpoint Inhibitor Treatment: A Case Report.", "abstract": "Immune checkpoint inhibitors (ICIs) are increasingly used in cancer therapy and are associated with immune-related adverse events (irAEs) that can mimic common emergency department (ED) presentations. These complications may resemble cardiopulmonary or neuromuscular disease, making early recognition challenging for emergency clinicians. We report the case of a 77-year-old man who presented to the ED with chest pressure and exertional dyspnea shortly after initiating immunotherapy. Initial evaluation focused on the treatment of a non-ST-elevation myocardial infarction. During his hospitalization, he developed progressive generalized weakness, ptosis, and worsening dyspnea with increasing oxygen requirements and reduced negative inspiratory force consistent with evolving respiratory compromise. He was ultimately diagnosed with probable ICI-associated myositis-myasthenia gravis overlap syndrome based on clinical findings despite negative serologic and electrodiagnostic testing. The patient was initially treated with high-dose intravenous methylprednisolone with transient improvement, but subsequently deteriorated after transition to oral corticosteroids. Empiric plasmapheresis was initiated, after which his respiratory status and neuromuscular strength gradually improved. He was discharged on a high-dose oral steroid taper with close neurology and oncology follow-up. This case highlights the diverse presentations of ICI-related irAEs and underscores the importance of obtaining a thorough oncology and immunotherapy history in patients presenting to the ED with unexplained cardiopulmonary or neuromuscular symptoms.", "authors": ["Awad Christopher S", "Redick Jack C", "Scheel Sydney", "Pohlman Neal", "Khandelwal Sorabh", "Bischof Jason"], "journal": "Cureus", "entry_date": "2026/05/25 08:00", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42181373/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Emergency Medicine, The Ohio State University Wexner Medical Center, Columbus, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42178262", "title": "Coexistence of Parkinson's Disease and Myasthenia Gravis with Symptom Exacerbation Induced by Biperiden: A Case Report.", "abstract": "Advanced-stage Parkinson's disease (PD) and myasthenia gravis (MG) share overlapping clinical features, including dysphagia, dysarthria, fatigue, and fluctuating symptoms. When PD precedes MG, these manifestations may be misinterpreted as a progression of PD, potentially leading to an underdiagnosis of MG. Although the coexistence of PD and MG is rare, it nevertheless requires careful consideration. Furthermore, the pharmacological treatments for these two disorders differ substantially, and medications used for one condition may exacerbate the other condition. We report a patient with PD complicated by MG, in whom anticholinergic treatment with biperiden led to the exacerbation of MG-related symptoms, ultimately resulting in the diagnosis of MG.", "authors": ["Yamanishi Yuki", "Miyaue Noriyuki", "Ochi Chikako", "Ito Yuko", "Ando Rina", "Nagai Masahiro"], "journal": "Internal medicine (Tokyo, Japan)", "entry_date": "2026/05/24 22:04", "pub_date": "2026-05-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42178262/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Pharmacology and Therapeutics, Ehime University Graduate School of Medicine, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "42171932", "title": "Hsa_circ_0065149 mediates the ceRNA network pathway: Research on the mechanism regulating myasthenia gravis.", "abstract": "CircRNAs have been linked to the pathogenesis and progression of myasthenia gravis (MG), but research on this association remains limited. This study aims to provide a new perspective for understanding the molecular pathogenesis of MG. We obtained RNA-seq data from patients with acetylcholine receptor (AChR)-positive MG and healthy individuals from the Gene Expression Omnibus (GEO) database. A bioinformatics analysis was performed to identify differentially expressed circRNAs related to MG; the circRNA that was most consistently identified in most databases as a key factor involved in MG, hsa_circ_0065149, was chosen for further analysis. AChR localized at the postsynaptic membrane of the neuromuscular junction (NMJ) plays a pivotal role in mediating synaptic signal transmission. The CHRNA1 gene, which encodes the α1 subunit of AChR and is critical for its function-was subsequently selected as the target mRNA in our investigation, whereas our prediction pipeline identified miR-330-5p as the target. For functional assays, various constructs (e.g., hsa_circ_0065149-siRNA) were transfected as described in the Methods section. The qRT‒PCR results indicated that hsa_circ_0065149 knockdown significantly upregulated miR-330-5p and downregulated CHRNA1, while the inhibition of miR-330-5p significantly upregulated both hsa_circ_0065149 and CHRNA1. We also performed functional rescue experiments to confirm the regulatory hierarchical relationships among these factors. A dual-luciferase reporter assay confirmed that hsa_circ_0065149 and CHRNA1 are direct targets of miR-330-5p. These results suggest that hsa_circ_0065149 regulates MG by mediating the ceRNA network pathway, and we reasonably hypothesize that it may further contribute to the pathological process of MG by impairing signal transmission in the NMJ.", "authors": ["Liu Siyu", "Tian Qinghua", "Liu Zhaojun", "Ren Yingjie", "Yu Aoqing", "Chen Biying", "Zhou Tianyang", "Li Xiang", "Wang Jianjian", "Wang Lihua", "Zhang Huixue"], "journal": "Journal of molecular neuroscience : MN", "entry_date": "2026/05/22 11:25", "pub_date": "2026-05-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42171932/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital, Harbin Medical University, Harbin, Heilongjiang Province, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "42169116", "title": "Autoimmune diseases and risk of adverse pregnancy outcomes: a population-based cohort study of five million pregnancies in the UK.", "abstract": "BACKGROUND: With an increasing trend in the prevalence of maternal autoimmune diseases in pregnancy, there is need for evidence on the association between autoimmune diseases and pregnancy outcomes.\nMETHODS: This population-based cohort study used data on pregnancies from primary care practices that contributed to the UK Clinical Practice Research Datalink (CPRD) database (Gold and Aurum) between 2000 and 2022, linked to Hospital Episode Statistics (HES). Modified Poisson regression with robust standard errors estimated adjusted relative risks (aRR) and 95% confidence intervals (95% CI) assessing the association between 17 autoimmune diseases and 12 pregnancy outcomes, selected following literature review and expert consultation. Models were adjusted for demographic and comorbidity variables. Findings were evaluated using the Benjamini-Yekutieli procedure to control for multiple testing across autoimmune disease-outcome associations.\nRESULTS: A total of 5,239,383 pregnancies from the CPRD pregnancy register and 2,485,366 births recorded in HES maternity data met the eligibility criteria. Women with autoimmune diseases had an increased risk across all pregnancy outcomes examined. Among antenatal outcomes, markedly elevated risks were observed for hyperemesis gravidarum in Addison's disease (aRR 3.72, 95% CI 2.48-5.59), miscarriage in Sjögren's syndrome (1.66, 1.02-2.70), gestational hypertension in type 1 diabetes mellitus (T1DM; 2.95, 2.77-3.15), pre-eclampsia/eclampsia in T1DM (3.56, 3.32-3.82), and gestational diabetes mellitus in Graves' disease (1.37, 1.21-1.54). For obstetric outcomes, increased risks were observed for caesarean birth in inflammatory bowel disease (IBD; 1.27, 1.22-1.31), small for gestational age in systemic lupus erythematosus (SLE; 2.45, 1.65-3.62), preterm birth in rheumatoid arthritis (1.53, 1.33-1.76), and stillbirth in SLE (1.82, 1.12-1.84). Perinatal mental health outcomes were more common across several autoimmune diseases, with particularly high risks in myasthenia gravis (anxiety 3.05, 1.89-4.92; depression 1.77, 1.37-2.28), SLE (anxiety 2.11, 1.67-2.67; depression 1.36, 1.22-1.53), and multiple sclerosis (anxiety 1.76, 1.38-2.23; depression 1.94, 1.77-2.12). Inverse associations were observed for hyperemesis gravidarum in systemic sclerosis, SLE, and myasthenia gravis, and for hypertensive disorders of pregnancy in multiple sclerosis. After Benjamini-Yekutieli correction for multiple testing, the number of statistically significant associations was reduced, with a core set of robust associations persisting across selected autoimmune diseases particularly, T1DM, SLE, Graves' disease, IBD and key pregnancy outcomes.\nCONCLUSIONS: Autoimmune diseases were associated with increased risks across a wide range of adverse pregnancy outcomes, with marked heterogeneity between individual conditions. This study provides adjusted relative risks across multiple domains of pregnancy outcomes including antenatal (e.g. miscarriage, hyperemesis gravidarum, gestational hypertension, pre-eclampsia, gestational diabetes), obstetric (e.g. preterm birth, caesarean birth, small for gestational age, stillbirth), and perinatal mental health outcomes (anxiety and depression), for both common and less frequently studied autoimmune diseases. The findings highlight the importance of disease-specific evaluation of pregnancy risks.", "authors": ["Singh Megha", "Subramanian Anuradhaa", "Wambua Steven", "Cockburn Neil", "Hanley Stephanie J", "Lee Siang Ing", "Gonzalez-Izquierdo Arturo", "Black Mairead", "Reynolds John A", "Crowe Francesca L", "Nirantharakumar Krishnarajah"], "journal": "BMC medicine", "entry_date": "2026/05/22 00:34", "pub_date": "2026-05-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42169116/", "pub_types": ["Journal Article"], "affiliations": ["Department of Applied Health Sciences, University of Birmingham, Birmingham, UK. m.singh.6@bham.ac.uk."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.3, "journal_quartile": "1区"}, {"pmid": "42168668", "title": "Anti-acetylcholine receptor antibody overshoot following efgartigimod in myasthenia gravis: Two case reports with literature review.", "abstract": "BACKGROUND: FcRn antagonists have reshaped generalized myasthenia gravis (MG) treatment by enhancing IgG catabolism, complementing traditional antibody-depleting therapy (ADT). However, disrupting IgG homeostasis may paradoxically cause antibody overshoot, potentially worsening MG symptoms. The risk factors and optimal management of antibody overshoot remain inadequately characterized.\nMETHODS: We report two novel cases of anti-acetylcholine receptor (AChR) antibody overshoot and clinical exacerbation following FcRn antagonist efgartigimod treatment. To contextualize these findings, we performed a literature search in PubMed, identifying 10 previously reported cases of antibody overshoot in MG (2 following efgartigimod and 8 following plasma exchange).\nRESULTS: In the efgartigimod cohort (n=4, including our two novel cases), all patients were anti AChR positive, had thymoma associated MG (TAMG, 100%), and had undergone prior thymectomy (100%). Notably, none had received adequate background immunosuppressive therapy before efgartigimod initiation (75% inadequate, 25% none). All patients (100%) experienced severe clinical exacerbation (MGFA class V in the 3 patients with available data). Rescue therapies-including corticosteroids (75%), eculizumab (50%), IVIG (50%), and tacrolimus (50%)-were effective, with all four patients showing significant improvement. Furthermore, analysis of the plasma exchange cohort (n=8) and the combined cohort (n=12) revealed a distinct and shared clinical risk profile for the development of antibody overshoot.\nCONCLUSION: Anti AChR antibody overshoot following efgartigimod therapy is a rare but clinically significant adverse event, predominantly affecting patients with TAMG or prior thymectomy who lack adequate baseline immunosuppression. Given the dissociation between total IgG reduction and autoantibody rebound, monitoring should focus specifically on anti-AChR titer rather than total IgG level alone.", "authors": ["Yang Rui-Yuan", "Wang Bian-Rong", "Hong Ye", "Fu Yi-Jia", "Liu Yu-Kai", "Yuan Zhen-Hua", "Zhao Hong-Dong", "Jiang Teng", "Shi Jian-Quan"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/05/21 23:40", "pub_date": "2026-05-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42168668/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Neurology, Nanjing First Hospital, Nanjing Medical University, Nanjing, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42167622", "title": "Chimeric antigen receptor-based cellular therapy in autoimmune diseases: A systematic review and meta-analysis of clinical, serological and safety outcomes.", "abstract": "OBJECTIVE: Chimeric antigen receptor (CAR)-T cell and natural killer cell therapies are emerging as treatments for autoimmune diseases (AIDs), capable of inducing immune reprogramming and drug-free remission. However, their efficacy, safety, and durability across AIDs remain incompletely defined.\nMETHODS: We performed a systematic review and meta-analysis of proportions to evaluate the efficacy and safety of CAR-based therapies in AIDs. PubMed, Embase, and CENTRAL were searched from January 1, 2010, to October 20, 2025. The primary outcome was medication-free remission (MFR); secondary outcomes included disease-specific remission indices, incidence of adverse events and their severity. Subgroup and meta-regression analyses were conducted.\nRESULTS: Of 3367 records screened, 56 studies met the inclusion criteria (15 eligible for meta-analysis; 41 synthesized qualitatively). For CAR-T cell therapies, among SLE patients, pooled MFR was 0·76 and DORIS remission 0·75. Subgroup analyses revealed a longer disease duration was associated with lower remission rates. From the qualitative analysis, CAR-T cell therapies demonstrated promising clinical efficacy and seroconversion rates in other AIDs, such as systemic sclerosis, myositis and myasthenia gravis. Across all AIDs, CRS of any grade occurred in 0·63, but grade ≥ 3 CRS and any grade of ICANS were negligible (both 0·00). Hypogammaglobulinaemia of any grade occurred in 0·47, while grade ≥ 3 events were rare. Cytopenias were common: neutropenia and anemia of any grade were most frequent. Severe cytopenias occurred in ≤0·3. Infection within 3 months occurred in 0·29.\nCONCLUSION: CAR-T cell therapies targeting CD19 or BCMA appear highly effective in inducing remission in refractory autoimmune diseases, with predominantly mild CRS and negligible neurotoxicity.", "authors": ["Wong Hon Jen", "Lee Ainsley Ryan Yan Bin", "Yap Qai Ven", "Chan Esther", "Schett Georg", "Tay Sen Hee"], "journal": "Autoimmunity reviews", "entry_date": "2026/05/21 19:40", "pub_date": "2026-05-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42167622/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medicine, Yong Loo Lin School of Medicine, National University of Singapore, Singapore."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "42166045", "title": "Comprehensive review on myasthenia gravis: patho-physiology, diagnosis, management strategies.", "abstract": "Myasthenia gravis (MG) is a heterogeneous autoimmune neuromuscular disorder with distinct serological subtypes, including antibodies against acetylcholine receptors (AChRs), MuSK, and LRP4. Despite increasing recognition of these subtypes, clinical practice still lacks a standardized, subtype-specific approach to diagnosis, characterization, and management. Current treatment strategies are often applied uniformly, without fully accounting for differences in disease phenotype, prognosis, and therapeutic response among antibody-defined groups. This review provides a comprehensive overview of adult MG, focusing on the various autoantibody subtypes and their implications for pathogenesis, clinical features, diagnosis, and management. We highlight how combining serological findings with clinical subtyping can inform a more personalized approach to therapy and better align treatment decisions with disease biology. By emphasizing the clinical relevance of serological classification, this review aims to bridge the gap between immunopathological understanding and individualized patient care in MG.\nDie Myasthenia gravis (MG) ist eine heterogene neuromuskuläre Autoimmunkrankheit mit verschiedenen serologischen Subtypen, inklusive Antikörpern gegen Acetylcholinrezeptoren (AChR), MuSK und LRP4. Trotz zunehmender Anerkennung dieser Subtypen fehlt es in der klinischen Praxis noch an einem standardisierten, subtypenspezifischen Ansatz für Diagnose, Charakterisierung und Behandlung. Aktuelle Therapiestrategien werden oft einheitlich angewendet, ohne die Unterschiede in Bezug auf Krankheitsphänotyp, Prognose und Therapieantwort bei den antikörperdefinierten Gruppen vollständig zu berücksichtigen. In der vorliegenden Übersicht wird ein umfassender Überblick über die MG bei Erwachsenen gegeben, der Schwerpunkt liegt dabei auf den verschiedenen Autoantikörpersubtypen und ihrer Bedeutung für Pathogenese, klinische Kennzeichen, Diagnose und Behandlung. Es wird aufgezeigt, wie die Kombination serologischer Befunde mit der klinischen Subtypisierung zu einem stärker personalisierten Behandlungsansatz und einer besseren Übereinstimmung von Therapieentscheidungen mit der Krankheitsbiologie beitragen kann. Durch Darlegung der klinischen Relevanz der serologischen Klassifizierung soll die vorliegende Übersichtsarbeit die Lücke zwischen immunpathologischem Verständnis und individualisierter Patientenversorgung bei MG schließen.", "authors": ["Ozor Ifeoma Nneozor", "Hwidi Anes Abdulmajid", "Khan Ammar Ali", "Kuriakose Jerrin Jolly", "Hajj Fatima", "Iwuagwu Mary", "Trivedi Vidhi Kashyap", "Hamed Mostafa Hassan Mohammed Elsayed", "Cai Long Yin"], "journal": "Wiener medizinische Wochenschrift (1946)", "entry_date": "2026/05/21 11:13", "pub_date": "2026-05-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42166045/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Faculty of Medicine Nis, University of Nis, Nis, Serbia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.9}, {"pmid": "42163150", "title": "Breakthrough serogroup Y meningococcal disease in a vaccinated patient with myasthenia gravis receiving ravulizumab: a case report.", "abstract": "We report a case of fulminant invasive meningococcal disease caused by Neisseria meningitidis serogroup Y in a young, immunocompromised adult with myasthenia gravis receiving long-term immunosuppressive therapy including ravulizumab, despite prior meningococcal vaccination. Serogroup Y is increasingly recognized in epidemiological surveillance and may be associated with atypical clinical manifestations, including the uncommon coexistence of meningitis and pulmonary involvement, as observed in this patient. The illness was characterized by rapid progression to septic shock, meningitis, and presumed pleuropneumonia. Diagnosis was confirmed by both blood PCR and culture. This case highlights the increased susceptibility to invasive meningococcal infections in individuals receiving complement-inhibiting therapy and underscores the importance of comprehensive preventive strategies, including a carefully planned and implemented vaccination schedule and careful individualized consideration of antimicrobial prophylaxis.\nNot applicable.", "authors": ["Strugar Silvija Šoprek", "Petrović Paško", "Butić Iva", "Gjurašin Branimir", "Kutleša Marko"], "journal": "BMC infectious diseases", "entry_date": "2026/05/21 01:05", "pub_date": "2026-05-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42163150/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Microbiology, University Hospital for Infectious Diseases, Zagreb, 10000, Croatia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "42162585", "title": "Non-Cyclic Rozanolixizumab Administration in Complex Generalized Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Rozanolixizumab, an inhibitor of the neonatal Fc receptor (FcRn), is used to treat patients with generalized myasthenia gravis (gMG) refractory to standard therapies. However, the approved six-week cyclic regimen may be associated with a \"wearing-off\" effect and disease fluctuations. We evaluated the non-cyclic administration of rozanolixizumab in patients with complex gMG.\nMETHODS: We retrospectively studied eight patients with anti-acetylcholine receptor antibody-positive complex gMG treated at Bordeaux University Hospital. \"Complex\" was defined by refractoriness, contraindications, intolerance to immunosuppressants or highly active MG. Patients transitioned to weekly or fortnightly rozanolixizumab after relapse during intermittent therapy. The primary outcome was ≥ 2-point improvement in Myasthenia Gravis Activities of Daily Living (MG-ADL) score at 3 months. Clinical data and serum immunoglobulin G (IgG) levels were collected at baseline, 3, 6, and 12 months.\nRESULTS: The cohort (mean age 70.5 years; 75% female) had a mean baseline MG-ADL score of 10.8, which improved rapidly to 4.1 at 3 months. Hospitalization days dropped from 15.8/month pre-treatment to zero by 6-12 months. Corticosteroids were tapered from 30.3 to 13.3 mg/day at 1 year. Mean serum IgG levels declined by almost 50% and stabilized. Only one discontinuation occurred due to gastrointestinal symptoms; no serious infections or severe adverse events were observed.\nDISCUSSION: Fortnightly rozanolixizumab yielded sustained clinical benefits, reduced hospitalizations, and enabled steroid tapering in complex gMG patients. This approach may prevent cyclical relapses seen with intermittent dosing. Larger studies are needed to confirm efficacy and long-term safety.", "authors": ["Abi Aoun Marc", "Beauvais Diane", "Barnay Marlène", "Violleau Marie-Hélène", "Mathis Stéphane", "Duval Fanny", "Sole Guilhem"], "journal": "Muscle & nerve", "entry_date": "2026/05/20 23:53", "pub_date": "2026-05-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42162585/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Department, Robert Boulin Hospital, Libourne, France."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "42162453", "title": "Disease changes and cost analysis of myasthenia gravis: a 10 years retrospective study from a reference center in Italy.", "abstract": "OBJECTIVE: Objective study was the quantification of controlled/inadequately controlled generalized myasthenia gravis (gMG) disease burden, health care resource utilization and costs in MG patients, followed-up at a reference center for MG in Italy.\nDESIGN AND SETTING: The study is a 2010 to 2020 retrospective analysis of gMG patients. Clinical and health economics variables were those observed during routine clinical care. Data were anonymized and treated in aggregated forms in compliance with GDPR.\nPARTICIPANTS: Only patients with gMG were included in the study.\nRESULTS: Out of 237 patients, 55.3% were males and 44.7% females with a median follow up duration of 4.7 years. Males were older, with a median age at onset of 58.3 years versus 45.7 years for females; an increased representation of late and very late onset patients was recorded. A shorter time from onset to diagnosis was observed in males. The incidence rate per year of exacerbations changed from 0.76 in the first year to 0.23 at the sixth year, with a similar trend for MG crisis; both exacerbations and crisis incidence were higher in inadequately controlled patients. Disease burden and health care resources utilizations were particularly evident in inadequately controlled patients, which showed a 138% increase of costs.\nCONCLUSIONS: Our data confirmed the observed epidemiological changes occurring in MG population and the high use of health care system resources in uncontrolled patients. The estimates obtained will provide a useful basis for assessing the impact of recently introduced targeted therapies on healthcare expenditure for MG.", "authors": ["Mantegazza Renato", "Antozzi Carlo", "Baggi Fulvio", "Maggi Lorenzo", "Frangiamore Rita", "Vanoli Fiammetta", "Bonanno Silvia", "Giannarelli Diana", "Polistena Barbara", "Verneau Ferdinando", "Spandonaro Federico"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/05/20 23:40", "pub_date": "2026-05-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42162453/", "pub_types": ["Journal Article"], "affiliations": ["Associazione Italiana Miastenia (AIM), Via Celoria 11, Milano, 20133, Italy. mantegazza.renato@gmail.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42161670", "title": "Real-world implications of efgartigimod in managing refractory myasthenia gravis.", "abstract": "INTRODUCTION: Refractory myasthenia gravis (RMG) affects 10-20% of patients with generalized MG (gMG) and is associated with persistent disability, recurrent myasthenic crises, and elevated healthcare costs despite multiple lines of immunosuppressive therapy. Efgartigimod (EFG), an engineered IgG1 Fc fragment that competitively inhibits the neonatal Fc receptor (FcRn), reduces pathogenic IgG and is approved for gMG in more than 30 countries worldwide.\nAREAS COVERED: This review synthesizes evidence on EFG in RMG from a literature search of PubMed and Embase (inception to March 2026), covering international refractory definitions, the ADAPT trial, multicenter real-world cohorts, rescue therapy in myasthenic crisis, treatment switching after biologic failure, and safety.\nEXPERT OPINION: EFG provides consistent symptom relief and substantial corticosteroid-sparing benefits across diverse RMG subtypes, including seronegative patients and those unresponsive to C5 complement inhibitors or B-cell depleting agents. EFG also serves as an effective rapid rescue therapy for refractory myasthenic crises. Despite reducing circulating IgG by approximately 60%, EFG does not increase severe infection rates. Therapeutic limitations include autoantibody rebound and inefficacy against non-IgG pathogenic autoantibodies. Further prospective trials utilizing modernized RMG definitions and validated predictive biomarkers are essential to establish EFG's therapeutic role in this challenging population.", "authors": ["He Dingxian", "Hu Nayuan", "Yan Chong", "Ma Chunlai", "Song Jie", "Luo Sushan", "Zhao Chongbo", "Xi Jianying"], "journal": "Expert opinion on biological therapy", "entry_date": "2026/05/20 21:42", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42161670/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.0, "journal_quartile": "3区"}, {"pmid": "42161616", "title": "[Efficacy analysis of the \"six-step\" robot-assisted subxiphoid extended thymectomy for myasthenia gravis].", "abstract": "To evaluate the clinical effect of the\"six-step\" robot-assisted subxiphoid extended thymectomy for myasthenia gravis. Clinical data of 45 patients with myasthenia gravis were retrospectively collected from the First Affiliated Hospital of Fujian Medical University between November 2022 and June 2025, including 22 males and 23 females, with the age of (48.0±12.0) years. Robot-assisted subxiphoid extended thymectomy was performed using a \"six-step\" approach. Perioperative data were collected, including operative time, intraoperative blood loss, postoperative thoracic drainage time and volume, length of postoperative hospital stay, postoperative complications, pathologic findings, and follow-up outcomes. All 45 procedures were completed without conversion or incision extension. The operation time was (158±26) min, the intraoperative blood loss was 15(8, 20) ml, the thoracic drainage time was 3(2, 3) d, and the postoperative thoracic drainage volume were 180.0(17.5, 400.0) ml on postoperative day 1, 40.0(10.0, 65.0) ml on postoperative day 2, and 15.0(7.5, 35.0) ml on postoperative day 3. The length of postoperative hospital stay was 4(3, 5) d. Postoperative complications occurred in 4 patients, including 1 case of hoarseness, 1 case of myasthenic crisis, and 2 cases of pulmonary infection, all of whom improved or recovered after symptomatic treatment. Pathology showed thymic hyperplasia in 9 cases and thymoma in 36 cases,among which ectopic thymus tissue was identified in 19 cases. Follow-up was conducted up to October 31, 2025, with a follow-up duration of 24.0(14.0, 29.0) months. No recurrence of complications, tumor recurrence or metastasis, or death was observed during follow-up.\"six-step\" robot-assisted subxiphoid extended thymectomy is safe and feasible with favorable short-term outcomes and offers a standardized, generalizable approach for myasthenia gravis surgery.\n探讨“六步法”机器人辅助经剑突下胸腺扩大切除治疗重症肌无力患者的疗效。回顾性收集2022年11月至2025年6月福建医科大学附属第一医院的45例重症肌无力患者的临床资料，男22例、女23例，年龄（48.0±12.0）岁。采用“六步法”模式行机器人辅助经剑突下胸腺扩大切除术。记录患者手术时间、术中出血量、术后引流管拔除时间、术后胸腔引流量、术后住院天数、术后并发症、术后病理学检查结果并进行随访。45例患者均顺利完成“六步法”机器人辅助经剑突下胸腺扩大切除术，无中转开胸或扩大切口。手术时间（158±26）min，术中出血量15（8，20）ml，术后引流管拔除时间3（2，3）d，术后胸腔引流量［术后第1天180.0（17.5，400.0）ml，术后第2天40.0（10.0，65.0）ml，术后第3天15.0（7.5，35.0）ml］，术后住院天数4（3，5）d。术后并发症4例（声嘶1例、肌无力危象1例、肺部感染2例），均经对症处理好转或痊愈。病理结果为胸腺增生9例，胸腺瘤36例，其中发现异位胸腺19例。随访截至2025年10月31日，随访时间为24.0（14.0，29.0）个月，随访期间无并发症复发、肿瘤复发转移或死亡病例。“六步法”机器人辅助经剑突下胸腺扩大切除术安全可行，近期疗效良好，具有标准化与可推广价值。.", "authors": ["Lin J B", "Zhuang R Z", "Zhuo Y", "Lin N L", "Yu F Q", "Lai F C"], "journal": "Zhonghua yi xue za zhi", "entry_date": "2026/05/20 21:36", "pub_date": "2026-05-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42161616/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Department of Thoracic Surgery, the First Affiliated Hospital of Fujian Medical University, Fuzhou 350005, China Department of Thoracic Surgery, National Regional Medical Center, Binhai Campus of the First Affiliated Hospital, Fujian Medical University, Fuzhou 350212, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "42160469", "title": "Real-World Occurrence of Adverse Events Associated With Adjuvant Pembrolizumab Therapy for Renal Cell Carcinoma: A Multicenter Retrospective Study.", "abstract": "BACKGROUND: Pembrolizumab is indicated as adjuvant therapy after nephrectomy in patients with high-risk renal cell carcinoma (RCC). However, data regarding the occurrence of treatment-related adverse events (TRAEs) associated with pembrolizumab in real-world clinical settings in Japanese patients remain limited. In this study, we aimed to assess the clinical safety of adjuvant pembrolizumab therapy in Japan.\nMETHODS: This multicenter, retrospective, observational study enrolled patients who received adjuvant pembrolizumab therapy for RCC at five facilities in Japan between August 2022 and March 2025. The primary endpoint was the occurrence of TRAEs, which were classified by grade according to the Common Terminology Criteria for Adverse Events version 5.0. Secondary endpoints focused on disease-free survival (DFS) and overall survival (OS).\nRESULTS: This study enrolled 35 patients and had a median follow-up period of 7.0 months (interquartile range: 2.0-14.0). TRAEs occurred in 13 patients (37.1%), including two (5.7%) with grade ≥ 3 events. Five patients (14.3%) discontinued pembrolizumab treatment because of TRAEs, and no treatment-related deaths were observed. Grade ≥ 3 TRAEs included one case each of erythema multiforme, myocarditis, gastrointestinal perforation, and myasthenia gravis. During follow-up, no disease recurrence or death was observed, and the median DFS and OS were not achieved.\nCONCLUSIONS: The safety profile of pembrolizumab as an adjuvant therapy was found to be acceptable in Japanese patients with high-risk RCC. Therefore, postoperative adjuvant pembrolizumab following surgical intervention may be recommended as a treatment option for eligible patients in clinical practice.", "authors": ["Iinuma Koji", "Nishikawa Kohei", "Sano Yuta", "Ozawa Kaori", "Yamada Toyohiro", "Taniguchi Tomoki", "Nakane Keita", "Inoue Takahiro", "Akamatsu Shusuke", "Koie Takuya"], "journal": "International journal of urology : official journal of the Japanese Urological Association", "entry_date": "2026/05/20 14:13", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42160469/", "pub_types": ["Journal Article", "Multicenter Study", "Observational Study"], "affiliations": ["Department of Urology, Graduate School of Medicine, Gifu University, Gifu, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "42160148", "title": "[MIASTOP: from Alfred Blalock to modern concept of perioperative management of thymectomy in myasthenic patients].", "abstract": "History of thymus surgery spans nearly 130 years, and 114 years have been largely devoted to thymectomy. Symptoms of myasthenia gravis (MG) were first described in 1658, but breakthrough in defining the role of thymus in this pathology occurred in the early 20th century. Improvements in conservative treatment for MG occurred simultaneously with development of thoracic surgery and anesthesiology. These processes converged in 1936, when Alfred Blalock performed and described in detail thymectomy and perioperative management of a patient with MG using available techniques. Despite modern advances in surgical and therapeutic treatment of MG, there is still no unified strategy based on integrative personalized approach to patient management. The article analyzes history of each component of perioperative support of thymectomy with emphasis on Blalock's systemic approach, and also proposes the concept of MIASTOP covering all stages of management of patients with myasthenia.\nИстория хирургии вилочковой железы насчитывает почти 130 лет, из которых 114 лет в значительной части посвящены тимэктомии. Клиническая картина myasthenia gravis (МГ) впервые описана в 1658 г., однако существенный прорыв в определении роли вилочковой железы при этом заболевании произошел в начале XX века. Усовершенствование консервативных методов лечения МГ происходило одновременно с развитием торакальной хирургии и анестезиологии, которые сошлись воедино в 1936 г., когда Alfred Blalock выполнил и подробно описал тимэктомию в совокупности с периоперационным ведением пациента с МГ с применением доступных ему методик. Несмотря на современные достижения в хирургическом и медикаментозном лечении МГ, до сих пор отсутствует единая стратегия, основанная на интегративном персонализированном подходе ведения пациента мультидисциплинарной командой. В статье представлен анализ истории развития каждого из этапов периоперационного сопровождения тимэктомии, при этом особое внимание уделено системному подходу A. Blalock, а также предложена концепция МИАСТОП, охватывающая все компоненты ведения пациента с миастенией.", "authors": ["Topolnitskiy E B", "Gusakov V V"], "journal": "Khirurgiia", "entry_date": "2026/05/20 12:10", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42160148/", "pub_types": ["Journal Article", "Historical Article", "English Abstract"], "affiliations": ["Siberian State Medical University, Tomsk, Russia."], "china_related": false, "study_types": ["Historical Article"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "42159021", "title": "The Clinical Efficacy and Safety of Efgartigimod in the Treatment of Autoimmune Encephalitis.", "abstract": "OBJECTIVE: Efgartigimod, an innovative human IgG Fc receptor antagonist, clears pathogenic IgG autoantibodies. However, its efficacy and safety in autoimmune encephalitis (AE) remain undefined.\nMETHODS: We retrospectively analyzed the modified Rankin Scale (mRS) scores, Clinical Assessment Scale for Autoimmune Encephalitis (CASE) scores, immunological parameters, and routine clinical laboratory data from AE patients treated with efgartigimod.\nRESULTS: The study included 15 AE patients who received efgartigimod. After the initial 4-week treatment period, a clinically meaningful improvement was observed in mRS scores [median: 4 (IQR 3, 5) vs. 2 (IQR 1, 2)]and CASE scores [median: 13 (IQR 7, 16) vs. 2 (IQR 1, 3)] (p < .001). Subgroup analyses further suggested a trend of clinical improvement in AE patients with neuronal surface autoantibodies (NSAab) (p < .01). Alongside clinical improvement, serum IgG levels decreased after the first infusion and continued to decline with subsequent treatments (p < .05). No serious adverse events were reported. Other immune markers and clinical laboratory parameters showed no observable changes (p > .05).\nCONCLUSIONS: In this small retrospective cohort, efgartigimod was associated with clinical improvement and selectively reduced IgG levels with an acceptable safety profile. However, no causal relationship was established between IgG reduction and clinical response. These findings need further validation.\nAutoimmune encephalitis (AE) encompasses a group of inflammatory brain diseases caused by pathogenic autoantibodies. While standard immunotherapy is available, it fails to halt disease progression in some patients, creating a need for alternative treatments. Efgartigimod, a human IgG Fc receptor antagonist, is currently approved for treating myasthenia gravis (MG). Given growing evidence supporting its efficacy in IgG-mediated autoimmune diseases, interest has increased in evaluating its therapeutic potential for AE. This study aimed to retrospectively assess the efficacy and safety of efgartigimod in AE patients. We enrolled a broad cohort that included diverse AE subtypes. Patients showed notable improvement, as measured by the modified Rankin Scale (mRS) and Clinical Assessment Scale for Autoimmune Encephalitis (CASE). Subgroup analysis further indicated a trend of improvement in patients with neuronal surface autoantibody (NSAab)-mediated AE. This clinical improvement was accompanied by a reduction in serum IgG levels, without a corresponding decrease in albumin. No serious adverse events or clinically discernible changes in routine blood parameters were observed during treatment. Our preliminary findings suggest that efgartigimod may be a therapeutic option with an acceptable safety profile for AE.", "authors": ["Qin Jin", "Zhang Jiewen"], "journal": "Immunological investigations", "entry_date": "2026/05/20 05:23", "pub_date": "2026-05-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42159021/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Henan Provincial People's Hospital, Zhengzhou University People's Hospital, Zhengzhou, Henan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "4区"}, {"pmid": "42158815", "title": "Association Between Post-COVID-19 Herpes Zoster Reactivation and Peripheral Nervous System Disorders: Multinational Real-World Evidence from TriNetX.", "abstract": "BACKGROUND: The increased incidence of herpes zoster (HZ) following coronavirus disease 2019 (COVID-19) suggests a period of immune dysregulation, but the associated long-term neuro-immunological risks remain unclear.\nMETHODS: Utilizing de-identified electronic health records from the TriNetX Global Collaborative Network, we established 1:1 propensity score-matched cohorts of COVID-19 survivors, comparing HZ-exposed and unexposed groups over a three-year follow-up. Primary endpoints included the incidence of peripheral nervous system disorders: Bell's palsy, Guillain-Barré syndrome (GBS), and myasthenia gravis (MG). Analyses included Cox proportional hazards models, landmark analyses, and multiple sensitivity analyses.\nRESULTS: HZ reactivation was associated with increased three-year risks of all outcomes. The risk of Bell's palsy was elevated early and remained sustained (hazard ratio 3.625, 95% confidence interval 3.151-4.170). In contrast, the risks of GBS (hazard ratio 1.858, 95% confidence interval 1.243-2.779) and MG (hazard ratio 1.640, 95% confidence interval 1.178-2.284) showed delayed increases emerging after the first year. These associations remained consistent across sensitivity analyses and were more pronounced in individuals with metabolic comorbidities. COVID-19 vaccination was not associated with an increased risk of these outcomes, although subgroup findings should be interpreted with caution due to limited event counts.\nCONCLUSIONS: Post-COVID-19 HZ is associated with an increased risk of peripheral nervous system disorders, highlighting the need for symptom-based neurological awareness during both early and delayed post-infectious periods.", "authors": ["Cheng Yu-Chen", "Lu Chien-Lin", "Wang Joshua", "Hou Yi-Chou", "Lu Kuo-Cheng"], "journal": "International journal of medical sciences", "entry_date": "2026/05/20 04:43", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42158815/", "pub_types": ["Journal Article"], "affiliations": ["School of Medicine, College of Medicine, Fu Jen Catholic University, New Taipei City, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "42157574", "title": "Evaluation of Sustained Disease Control With Nipocalimab Versus Placebo in the Phase 3 Vivacity-MG3 Study.", "abstract": "BACKGROUND: Patients with generalized myasthenia gravis (gMG) frequently have variable and fluctuating symptoms. Treatments providing long-term, sustained disease control are essential for improving function and health-related quality of life.\nMETHODS: In the phase 3 Vivacity-MG3 study, nipocalimab improved clinical outcomes in adults with gMG when added to standard-of-care (SOC) therapy. These post hoc analyses further assessed the ability of nipocalimab to produce sustained responses over 24 weeks, using the following response categories for total score improvements in Myasthenia Gravis-Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG), respectively: Meaningful Clinical Improvement (MCI; ≥ 2- and ≥ 3-point), Substantial Improvement (SI; ≥ 3- and ≥ 4-point), Considerable Improvement (CIP; ≥ 4- and ≥ 5), Composite Response (CR; MG-ADL improvement ≥ 2-points plus QMG improvement ≥ 3-points), and Minimal Symptom Expression (MSE; MG-ADL 0 or 1).\nRESULTS: Significantly higher percentages of nipocalimab-treated than placebo-treated participants achieved MG-ADL MCI, SI, and CIP, sustained for ≥ 12 consecutive weeks; achievement of these outcomes occurred as early as week 1 among nipocalimab-treated participants. Similar results were observed for QMG MCI, SI, and CIP. Significantly higher percentages of nipocalimab-treated participants achieved CR, sustained for ≥ 8 consecutive weeks versus placebo; the likelihood of achieving sustained CR for ≥ 8 weeks was higher with nipocalimab (odds ratio = 6.3). Nipocalimab-treated participants were 4-fold more likely to achieve MSE, sustained for ≥ 8 consecutive weeks versus placebo (p = 0.022). MSE and CR were achieved earlier among nipocalimab-treated participants.\nCONCLUSIONS: Nipocalimab treatment improves gMG symptoms earlier than placebo and provides meaningful and long-term sustained disease control over 24 weeks among participants with gMG.", "authors": ["Vu Tuan", "Beydoun Said R", "Nowak Richard J", "Katzberg Hans", "Ait-Tihyaty Maria", "Gandhi Kavita", "Sheehan John J", "Pease Sheryl", "Turkoz Ibrahim", "Sattin Bernie", "Choudhry Zia", "Ramchandren Sindhu", "Antozzi Carlo"], "journal": "European journal of neurology", "entry_date": "2026/05/20 02:23", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42157574/", "pub_types": ["Journal Article", "Clinical Trial, Phase III", "Randomized Controlled Trial", "Multicenter Study"], "affiliations": ["Department of Neurology, University of South Florida Morsani College of Medicine, Tampa, Florida, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "42156031", "title": "[Botulism in Japan].", "abstract": "Botulism is a paralytic disease caused by the neurotoxin mainly produced by Clostridium botulinum. Botulism is classified as infant, foodborne, wound, adult intestinal toxemia, iatrogenic, and inhalation botulism. In Japan, type E botulism associated with the consumption of \"izushi,\" a traditional fermented fish product, was prevalent before 2000. Since the 2000s, type A botulism has become more common. In some cases, foodborne botulism was suspected, but no incriminating food or sporadic cases were identified. Therefore, foodborne botulism should be considered even in the absence of a clear history of high-risk food consumption or a mass outbreak. Differential diagnoses of botulism include Guillain-Barré syndrome, Miller-Fisher syndrome, myasthenia gravis, and Lambert-Eaton myasthenic syndrome. Although botulism is rare, it is clinically important. In patients presenting with acute flaccid paralysis accompanied by brainstem symptoms, botulism should be considered as a differential diagnosis. When botulism is suspected, the local public health authorities should be promptly notified to prevent additional cases. To improve clinical outcomes, early administration of botulinum antitoxin is essential.", "authors": ["Kihara Keigo", "Mochizuki Hideki"], "journal": "Brain and nerve = Shinkei kenkyu no shinpo", "entry_date": "2026/05/19 20:22", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42156031/", "pub_types": ["Journal Article", "Review", "English Abstract"], "affiliations": ["Department of Neurology, Osaka Rosai Hospital."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "42154663", "title": "Long Term Mortality in Patients with Myasthenia Gravis: A Nationwide Population-Based Cohort Study in Korea.", "abstract": "OBJECTIVES: Recent studies have reported conflicting results regarding the mortality risk in patients with myasthenia gravis (MG); however, evidence from East Asian populations remains limited. Understanding the mortality patterns and risk factors of MG is essential for improving patient outcomes. We conducted a nationwide, retrospective cohort study using data from the Korean National Health Insurance Service database to investigate mortality and its associated factors in patients with MG.\nMETHODS: Incident MG cases diagnosed between 2005 and 2020 were identified based on validated operational definitions and matched 1:5 with age- and sex-matched controls. All-cause mortality was assessed using Kaplan-Meier analysis, and mortality-associated risk factors were identified by multivariate Cox regression after adjusting for variables.\nRESULTS: This study included 21,642 patients with MG and 108,210 matched controls. The MG group showed a significantly higher mortality rate than that in controls (144.40 vs. 92.60 per 10,000 person-years; adjusted hazard ratio 1.41, 95% CI 1.34-1.49). Risk factors associated with increased mortality included older age, male sex, high comorbidity burden, high-dose corticosteroid use (≥15 mg/day), thymoma, and myasthenic crisis. Thymectomies were associated with reduced mortality. The leading causes of death included malignancy, cardiac disease, and MG. Myasthenic crisis and thymoma were respectively associated with early mortality and a gradual increase in late mortality.\nCONCLUSION: This study demonstrated increased mortality in Korean patients with MG, identifying key disease- and treatment-related risk factors. These findings underscore the need for early risk stratification, comorbidity management, and individualized treatment approaches to improve long-term outcomes.", "authors": ["Chung Hye Yoon", "Yu Min Heui", "Shin Ha Young", "Park Hyung Jun", "Hong Namki", "Kim Seung Woo"], "journal": "Neuroepidemiology", "entry_date": "2026/05/19 13:14", "pub_date": "2026-05-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42154663/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.0, "journal_quartile": "3区"}, {"pmid": "42154647", "title": "Evaluating nipocalimab for the treatment of chronic inflammatory demyelinating polyneuropathy.", "abstract": "INTRODUCTION: Chronic inflammatory demyelinating polyneuropathy (CIDP) is an immune-mediated neuropathy. Established first-line treatments for CIDP included immunoglobulin, corticosteroids, and plasma exchange, whereas the potential efficacy of a neonatal fragment crystallized receptor (FcRn) inhibitor has recently been highlighted. FcRn inhibitors have a selective action on serum IgG reduction, and a phase 2/3 trial with nipocalimab is ongoing, according to the findings of a phase 1 trial.\nAREAS COVERED: The present article discussed the potential mechanism of action, efficacy, and safety of nipocalimab for CIDP. The safety of nipocalimab was investigated in prior phase 1 trials for healthy participants and phase 2 and 3 trials for myasthenia gravis. Further, efgartigimod has already demonstrated its efficacy in the phase 2 trial and has been approved for CIDP in several countries. Based on these data, the mechanism of action, efficacy, and safety of nipocalimab for CIDP have been assumed.\nEXPERT OPINION: Nipocalimab represents a novel and potentially effective treatment option for CIDP, and the phase 2/3 trial is ongoing. One thing that clinicians will need to consider is the difference in the route of administration. Regardless, it should be considered positive that new treatment options are emerging for CIDP.", "authors": ["Shibuya Kazumoto", "Kito Kazuaki", "Suichi Tomoki", "Misawa Sonoko", "Kuwabara Satoshi"], "journal": "Expert review of neurotherapeutics", "entry_date": "2026/05/19 13:13", "pub_date": "2026-05-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42154647/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "42152296", "title": "Successful treatment of anti-LGI1-associated autoimmune encephalitis with efgartigimod: A case report and literature review.", "abstract": "RATIONALE: Anti leucine rich glioma inactivated 1 (LGI1)- associated autoimmune encephalitis (AE) is the common form of AE, The treatments for AE may cause many adverse effects and some treatments rely on limited blood resources. Monoclonal antibodies directed against neonatal crystallizable fragment receptor (FcRn), efgartigimod, accelerate autoantibody degradation by blocking IgG recirculation. The efficacy of efgartigimod has been demonstrated in myasthenia gravis. However, there are few case reports on the treatment of anti-LGI1-associated AE with efgartigimod. In this study, we present the case of a patient with anti-LGI1-associated AE who was treated with efgartigimod successfully.\nPATIENT CONCERNS: A 64-year-old female patient presented with decline in short-term memory and limb tremor. Cranial magnetic resonance imaging (MRI) scan showed hyperintensity and swelling in the medial aspect of the right temporal-occipital lobe on T2- and FLAIR-weighted sequences, without obvious enhancement lesions. The anti-LGI1 antibody titer in serum and CSF was positive.\nDIAGNOSES: The patient was diagnosed with anti-LGI1-associated AE.\nINTERVENTIONS: Initially, the patient received methylprednisolone pulse therapy. Levetiracetam and oxcarbazepine were both administered orally in the meantime. Following treatment failure, efgartigimod was administered once a week for 3 weeks.\nOUTCOMES: After treatment, the patient's limb tremors ceased and her memory improved. The level of anti-LGI1 antibody titer in serum decreased, and the abnormal signals on the MRI attenuated.\nLESSONS: Efgartigimod is an effective treatment for anti-LGI1-associated AE. This study presents a new approach to treat anti-LGI1-associated AE. However, further research is needed to establish the optimal dosage and frequency of efgartigimod, and to clarify its long-term safety and efficacy.", "authors": ["Gao Rui", "Hong Yan", "Zhou Guanen"], "journal": "Medicine", "entry_date": "2026/05/19 01:01", "pub_date": "2026-05-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42152296/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Neurology, Tianjin Key Laboratory of Cerebral Vascular and Neurodegenerative Diseases, Tianjin Huanhu Hospital, Tianjin, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "42149058", "title": "Identification of Ocular and Systemic Predictors and Development of a Prediction Model in Ocular Myasthenia Gravis.", "abstract": "PURPOSE: Predicting patients with ocular myasthenia gravis (OMG) achieving minimal manifestation status (MMS) or better is crucial for guiding treatment decisions. Prognostic models are becoming increasingly popular in the medical field due to their high accuracy. This study aimed to develop a clinical tool based on both ocular and systemic factors.\nMETHODS: We reviewed patients from our hospital from 2020 to 2023. Logistic and Least Absolute Shrinkage and Selection Operator (LASSO) regressions were applied to determine key predictors. A logistic nomogram model was constructed based on the selected factors. The model's performance was rigorously evaluated through internal validation for discrimination, calibration, and clinical utility.\nRESULTS: Among 216 patients, 126 individuals were included in the study. A total of 61 patients (48.4%) achieved MMS or better status in the 1-year outcome. Five key variables were selected to conduct the prognostic model, including ocular deviation angle, duration, antibody, corticosteroid therapy, and thyroid ultrasound. The area under the curve (AUC) was 0.889 (95% confidence interval [CI] = 0.832-0.947), demonstrating a good performance. The calibration curves also showed excellent agreement between predicted and observed probabilities in both training and validation cohorts.\nCONCLUSIONS: This study provides a clinically applicable predictive model, which accurately identifies patients with OMG likely to achieve MMS or better status within 1 year. The model is predictive of individual patients with great performance, thereby increasing clinical confidence and utility.\nTRANSLATIONAL RELEVANCE: This study translates specific ocular examination findings into a practical prognostic tool. The developed model directly assists clinicians in identifying patients with OMG with a high probability of achieving remission within 1 year, thereby informing personalized management strategies.", "authors": ["Cai Youran", "Tang Ting", "Peng Shiyi", "Gong Di", "Zhang Rijia", "Zhou Qing"], "journal": "Translational vision science & technology", "entry_date": "2026/05/18 10:38", "pub_date": "2026-05-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42149058/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, The First Affiliated Hospital of Jinan University, Guangzhou, People's Republic of China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "42148089", "title": "CFD+CD14+ monocytes: potential pathogenic subset in myasthenia gravis uncovered by multi-omics integration and machine learning analysis.", "abstract": "BACKGROUND: Transcriptome-wide association study (TWAS) contributes to discovering novel susceptibility genes related to diseases. Single-cell RNA sequencing (scRNA-seq) has been extensively applied to characterize cellular heterogeneity in various biological and pathological conditions. However, few studies have integrated TWAS and scRNA-seq to decode the pathogenesis of myasthenia gravis (MG) at cellular resolution.\nMETHODS: We integrated multi-omics data from GEO, genome-wide association study (GWAS) catalog, and Genotype-Tissue Expression (GTEx) databases, including scRNA-seq data, GWAS summary data, and expression quantitative trait loci. A set of risk genes genetically associated with MG were identifies using TWAS analysis. TWAS activity status across cell types in MG at single cell resolution was assessed based on these genes. Seven machine learning algorithms were performed to identify high TWAS activity related signature genes. Machine learning benchmark was incorporated to select the best model using R package \"mlr3\". Meanwhile, we performed scRNA-seq on peripheral blood collected from MG patients and healthy controls to generate a validation dataset.\nRESULTS: scRNA-seq analysis revealed an elevated proportion of CD14+ monocytes in MG patients, accompanied by notable transcriptomic reprogramming. Compared with other cell types, CD14+ monocytes exhibited higher TWAS activity. High TWAS activity subsets mainly enriched in the MG group and functionally associated with mTORC1 signaling, complement, and inflammatory response pathways. Machine learning-based feature selection revealed six robust signature genes (FKBP15, EHMT1, CHPT1, KLC1, SCPEP1, and CFD). Among these, CFD showed elevated expression early in high TWAS activity monocyte development. Compared to control group, CFD maintained higher levels throughout disease progression in MG group. CFD+CD14+ monocytes exhibited enhancer plasticity than CFD- CD14+ monocytes and were related to complement and coagulation cascades, antigen processing and presentation, and proteasome pathways. CFD+CD14+ monocytes in MG exhibit enhanced intercellular communication activity compared to CFD- cells, demonstrating greater signal reception and transmission capacity.\nCONCLUSION: In summary, this study systematically delineates the important role of CFD+CD14+ monocytes in MG pathogenesis through multi-omics analysis, providing novel insights for a deeper understanding of MG immunopathology and potential therapeutic targets.", "authors": ["Li Shuang", "Zhang Yifan", "Hou Chenlu", "Chang Ting"], "journal": "Frontiers in immunology", "entry_date": "2026/05/18 06:59", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42148089/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tangdu Hospital, the Fourth Military Medical University, Xi'an, Shaanxi, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42147223", "title": "Case Report: Thymoma-associated stiff person syndrome and myasthenia gravis: an index case with exploratory exome sequencing and review of reported cases.", "abstract": "BACKGROUND: Thymoma is frequently associated with myasthenia gravis (MG), but the coexisting of stiff person syndrome (SPS) is exceedingly rare. This overlap syndrome poses diagnostic and therapeutic challenges, and its immunopathogenic basis is not well understood.\nMETHODS: A 55-year-old woman with thymoma-associated SPS and MG was evaluated using detailed clinical, electrophysiological, serological and radiologic investigations. In addition, a PubMed-based literature review of published cases of thymoma complicated by SPS with MG was conducted. Exploratory whole-exome sequencing (WES) with pathway analysis were performed on resected thymoma tissue.\nRESULTS: The index patient presented with progressive gait unsteadiness, painful axial and lower-limb stiffness, dysarthria and dysphagia. Examination revealed marked truncal rigidity and exaggerated startle responses. Serology demonstrated high-titer anti-glutamic acid decarboxylase 65 (GAD65) and elevated acetylcholine receptor (AChR) antibodies. Chest computed tomography (CT) demonstrated an anterior mediastinal soft-tissue mass highly suggestive of thymoma. Treatment with immunotherapy, symptomatic agents and thymectomy resulted in substantial clinical improvement. The literature search identified seven additional patients with thymoma-associated SPS and MG, typically characterized by GAD65 positivity, World Health Organization (WHO) B1/B2 mixed histology, and favorable outcomes after combined immunotherapy and surgical resection. WES of the thymoma revealed a somatic CACNA1A frameshift variant and variants in immune-signaling genes, with enrichment of pathways related to calcium channels, γ-aminobutyric acidergic (GABAergic) synapses and immune regulation.\nCONCLUSION: Thymoma-associated SPS and MG constitute a rare but recognizable overlap syndrome. Integration of clinical, literature and exploratory genomic data supports a convergent mechanism involving thymic epithelial neoplasia, impaired inhibitory neurotransmission and neuromuscular junction autoimmunity.", "authors": ["Zhao Lu", "Fang Linan", "Tang Mingbo", "Zhang Kewei", "Liu Wei", "Qiang Min"], "journal": "Frontiers in oncology", "entry_date": "2026/05/18 06:52", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42147223/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["College of Clinical Medicine, Jilin University, Changchun, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "42145953", "title": "Correlations between inflammatory biomarkers and clinicopathological features in surgically resected thymic epithelial tumors: implications for preoperative diagnosis.", "abstract": "OBJECTIVE: This study aimed to analyze the correlations between pathological characteristics, risk factors, and inflammatory biomarkers in patients with thymic epithelial tumors (TETs) undergoing surgical resection.\nMETHODS: A retrospective cohort of adult patients with histopathologically confirmed TETs undergoing radical resection between 2015 and 2024 was analyzed. The Kruskal-Wallis test was employed to evaluate associations of systemic immune-inflammation index (SII), platelet-to-lymphocyte ratio (PLR), and neutrophil-to-lymphocyte ratio (NLR) with clinical features (age; gender; myasthenia gravis (MG); World Health Organization (WHO) stage; tumor size; Masaoka stage; WHOMScore). A nomogram diagnostic model was constructed to differentiate thymoma from thymic carcinoma.\nRESULTS: A total of 111 patients (52 males, 59 females) were enrolled, including eight cases of type A thymoma, 38 type AB, nine type B1, 16 type B2, 12 type B3, and 28 thymic carcinomas. Correlations between SII, NLR, PLR, and clinicopathological features (gender, age, MG, tumor size, risk stratification, Masaoka stage, and WHO classification) were analyzed. Significant differences in SII, NLR, and PLR were observed across WHO classifications (P SII < 0.001; P NLR < 0.001; P PLR = 0.004). Dunn's test further revealed that these differences primarily stemmed from distinctions between thymoma and thymic carcinoma groups. Based on PLR and MG status, a combined diagnostic model was developed, which demonstrated favorable performance in differentiating thymoma from thymic carcinoma (AUC = 0.804).\nCONCLUSION: Our findings suggest that inflammatory biomarkers (SII, NLR, and PLR) are significantly associated with the malignancy of TETs. The combination of PLR and MG status may serve as a useful auxiliary tool for distinguishing thymoma from thymic carcinoma, showing potential for clinical application.", "authors": ["Fu Jun", "Han Peng", "Xu Jiahang", "Deng Wanjun", "Chen Baojun", "Liu Yong"], "journal": "PeerJ", "entry_date": "2026/05/18 06:39", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42145953/", "pub_types": ["Journal Article"], "affiliations": ["Thoracic Surgery, The Central Hospital of Wuhan, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, Hubei, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42145731", "title": "Neuroinflammation: a critical bridge linking peripheral pathology and age-related degeneration in myasthenia gravis.", "abstract": "Myasthenia gravis (MG) has traditionally been conceptualized as a peripheral autoimmune disorder primarily mediated by autoantibodies targeting the neuromuscular junction. However, this classical paradigm fails to adequately explain the prevalent central nervous system (CNS) manifestations in patients, including profound fatigue and cognitive impairment. Emerging evidence indicates that neuroinflammation plays a pivotal role in bridging peripheral pathology and central symptoms. Systemic inflammatory mediators can breach the compromised blood-brain barrier (BBB) or activate CNS-resident microglia and astrocytes via neuroimmune pathways, thereby initiating neuroinflammatory cascades. Once activated, these glial cells release pro-inflammatory cytokines and reactive oxygen species (ROS), which impair neuronal energy metabolism, synaptic plasticity, and neurotransmitter homeostasis, directly contributing to central symptomatology. Critically, neuroinflammation serves as a key mechanistic bridge linking the peripheral autoimmune pathology of MG with age-related neurodegenerative changes. With advancing age, immunosenescence manifests as diminished T-cell repertoire diversity, impaired regulatory T-cell function, and chronic low-grade inflammation (inflammaging), which not only increases susceptibility to MG but also provides a permissive environment for the initiation and perpetuation of neuroinflammation. Concurrently, age-related degenerative alterations at the neuromuscular junction-including reduced acetylcholine receptor (AChR) density and mitochondrial dysfunction-decrease the safety margin of neuromuscular transmission, rendering elderly patients more vulnerable to autoantibody-mediated attack. A vicious cycle emerges among neuroinflammation, mitochondrial dysfunction, and oxidative stress, which synergistically accelerate neuronal damage and apoptosis. Consequently, the clinical phenotype, therapeutic response, and prognosis of MG demonstrate marked age-dependency. Late-onset MG patients typically experience more severe disease courses and poorer outcomes, attributable in part to the compounding effects of immunosenescence, underlying neurodegeneration, and neuroinflammation. Elucidating the central role of neuroinflammation and its intricate interactions with age-related pathological processes holds significant theoretical and clinical implications for developing novel neuroprotective strategies targeting CNS symptoms in MG and achieving personalized, precision medicine tailored to patients across different age groups.", "authors": ["Liu Fan-Yu", "Huang Yan-Peng", "Li Zhao-Qing", "Li Xu", "Zhang Jing-Sheng", "Guan Le", "Qiao Wen-Jun"], "journal": "Frontiers in medicine", "entry_date": "2026/05/18 06:37", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42145731/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Liaoning University of Traditional Chinese Medicine, Shenyang, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "42143506", "title": "The evolution of CAR therapies across oncology and autoimmunity: mechanistic insights and therapeutic innovations.", "abstract": "Chimeric antigen receptor (CAR)-engineered cellular therapies have progressed from early proof of concept into highly programmable platforms capable of mediating potent cytotoxicity and precise immune modulation. In oncology, successive CAR design has incorporated optimized costimulatory domains, cytokine-secreting modules, and gene-editing technologies to enhance efficacy and durability in hematologic malignancies. CD19- and BCMA-directed CAR-T cells induce deep and durable remissions in refractory B-cell leukemias, lymphomas, and multiple myeloma. Emerging strategies, including logic-gated CARs, synthetic Notch (SynNotch) circuits, and modular adaptor-based systems, aim to overcome antigen escape, reduce off-tumor toxicity, and extend efficacy to heterogeneous solid tumors. Concurrently, a conceptual shift has expanded CAR applications beyond cancer toward immune modulation in autoimmune diseases. CD19-directed CAR-T therapy has achieved deep B-cell depletion and clinical improvement in small early-phase studies (typically 5-18 patients) of systemic lupus erythematosus, inducing drug-free remission in some patients; however, randomized controlled trials are lacking and evidence remains preliminary. Antigen-specific approaches, including chimeric autoantibody receptor (CAAR)-T cells and CAR-engineered regulatory T-cells (CAR-Tregs), enable selective depletion of autoreactive B-cell clones or localized restoration of immune tolerance. These strategies are under investigation across systemic sclerosis, multiple sclerosis, myasthenia gravis, type 1 diabetes, inflammatory bowel disease, and rheumatoid arthritis. Collectively, advances in synthetic receptor engineering and translational application position CAR platforms as versatile, next-generation therapeutics across malignant and immune-mediated diseases.", "authors": ["Abd El-Fattah Eslam E", "Hamdy Rania", "Soliman Sameh S M", "Husseiny Mohamed I"], "journal": "International immunopharmacology", "entry_date": "2026/05/17 03:34", "pub_date": "2026-08-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42143506/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Beckman Research Institute, City of Hope, Duarte, CA, USA; Department of Biochemistry, Faculty of Pharmacy, Delta University for Science and Technology, Gamasa, Egypt."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.7, "journal_quartile": "2区"}, {"pmid": "42142527", "title": "Rare adverse events after COVID-19 vaccination among Swedish older adults-evidence from a nationwide register-based study.", "abstract": "INTRODUCTION: COVID-19 vaccinations have saved millions of lives, particularly among older adults. Rare potential adverse events have been reported in case reports, but risks among older adults remain unclear. This study assessed risks of selected potential adverse events in this population.\nMETHODS: We included more than 2 million Swedish adults ≥65y in a nationwide register-based cohort. Post-vaccination risks were assessed for herpes zoster (HZ), encephalitis, myelitis and encephalomyelitis, multiple sclerosis (MS), myasthenia gravis, cranial nerve palsy, sudden sensorineural hearing loss (SSNHL), postinfectious arthritis and polymyalgia rheumatica (PMR) in several risk windows (1-30, 31-60, and 61-180 days) after each vaccine dose. Hazard ratios (HRs) with 95% confidence intervals (95%CIs) compared with unvaccinated were estimated by Cox regression adjusted for potential confounders. Sensitivity analyses included adding primary health care (PHC) visits, and applying analysis-specific 5-year disease-free wash-out periods.\nRESULTS: No increased HRs were observed for most outcomes. SSNHL showed increased HRs within 180 days after each dose [1.60 (95%CI 1.15-2.24); 1.43 (1.03-1.99); 1.61 (1.05-2.46) for dose 1, 2 and 3], with similar estimates across all three risk windows. Increased HRs were also seen for PMR after dose 2 [1.14 (1.04-1.24)] and dose 3 [1.16 (1.03-1.30)], with higher HRs during later time windows. HZ showed increased HRs in the sensitivity analysis with PHC visits, [1.19 (1.07-1.31); 1.31 (1.19-1.43); 1.42 (1.26-1.60) for dose 1, 2 and 3]. MS showed reduced risk after dose 3 in the sensitivity analysis with longer wash-out (targeting incident MS), but not in the main analysis (potential relapses included).\nCONCLUSIONS: COVID-19 vaccines are generally safe in older adults, with very low incidence of the potential rare adverse events assessed. Slightly increased relative risks for SSNHL, PMR and HZ were observed, but these findings do not alter the overall benefit-risk profile of COVID-19 vaccination in older adults.", "authors": ["Xu Yiyi", "Nyberg Fredrik", "Marking Ulrika", "Gisslén Magnus", "Wastesson Jonas W", "Johnell Kristina"], "journal": "Vaccine", "entry_date": "2026/05/16 18:07", "pub_date": "2026-07-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42142527/", "pub_types": ["Journal Article"], "affiliations": ["School of Public Health and Community Medicine, Institute of Medicine, Sahlgrenska Academy, University of Gothenburg, Gothenburg, Sweden. Electronic address: yiyi.xu@amm.gu.se."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "42139024", "title": "Nipocalimab (Imaavy) for myasthenia gravis.", "abstract": "", "authors": [], "journal": "The Medical letter on drugs and therapeutics", "entry_date": "2026/05/15 12:23", "pub_date": "2026-05-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42139024/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "42138399", "title": "Predictive Value of Single-Fiber Electromyography for Ocular Myasthenia Gravis in a Low Prevalence Cohort.", "abstract": "PURPOSE: Single-fiber electromyography (SFEMG) is a sensitive test to diagnose ocular myasthenia gravis (OMG) when the clinical suspicion is high but the predictive value of the test is also dependent on the prevalence of the condition in the referral population. In a low prevalence population, false positive results can be as common as true positive results. Most of the patients referred for SFEMG at our center do not have symptoms or signs that are strongly suggestive for OMG.\nMETHODS: A retrospective chart review was performed of all patients referred to our laboratory for possible OMG for a 1-year period and analyzed the long-term accuracy of SFEMG in a cohort of 33 patients.\nRESULTS: Eleven of these (33%) were eventually diagnosed with a disease of neuromuscular transmission and SFEMG was abnormal in all of these (100% sensitivity). With the requirement that 3 jitter pairs be abnormal or that mean jitter was elevated, SFEMG was normal in the remaining 22 patients (100% specific).\nCONCLUSIONS: The results confirm that SFEMG is an excellent confirmatory test when clinical suspicion for OMG is high and also demonstrate that when strict criteria are applied, the test accurately excludes OMG in patients with ocular complaints that are not truly suggestive of OMG.", "authors": ["Gomez Yorjannys", "Puwanant Araya", "Caress James B"], "journal": "Journal of clinical neurophysiology : official publication of the American Electroencephalographic Society", "entry_date": "2026/05/15 09:03", "pub_date": "2026-05-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42138399/", "pub_types": ["Journal Article"], "affiliations": ["Biomedical Research Imaging Center, School of Medicine, University of North Carolina at Chapel Hill, Chapel Hill, North Carolina, U.S.A.; and."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "42138115", "title": "Myasthenia gravis and myocarditis induced by immune checkpoint inhibitors: a case report.", "abstract": "", "authors": ["Świętoń Paulina", "Słoń Jakub", "Matys Paulina", "Jakubowicz-Lachowska Dominika", "Chorąży Monika", "Kochanowicz Jan", "Kułakowska Alina", "Kapica-Topczewska Katarzyna"], "journal": "Neurologia i neurochirurgia polska", "entry_date": "2026/05/15 06:23", "pub_date": "2026-05-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42138115/", "pub_types": ["Journal Article"], "affiliations": ["Student Scientific Society at the Department of Neurology, Medical University of Bialystok, Poland. paulaswieton@wp.pl."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "42137634", "title": "Meningococcal prophylaxis in neurological diseases treated with complement inhibitors: an expert consensus for Germany, Austria, and Switzerland.", "abstract": "Inhibition of terminal complement activation is an effective therapeutic strategy for acetylcholine receptor antibody-positive generalized myasthenia gravis (gMG) and aquaporin-4 antibody-positive neuromyelitis optica spectrum disorder (NMOSD), but it increases the risk of invasive meningococcal infections. Consequently, vaccination against meningococcal serogroups A, C, W, Y, and B is mandatory for all patients receiving complement inhibitors. This article provides expert consensus recommendations for managing meningococcal vaccination in patients with NMOSD and gMG receiving complement-inhibiting therapies in Germany, Austria, and Switzerland. The timing and procedures of vaccination should be adapted to the underlying diagnosis and the individual risk of disease exacerbation in this population. In NMOSD, treatment often must begin promptly, particularly after an acute attack; in such cases, vaccination should be administered at treatment initiation together with antibiotic prophylaxis. By contrast, treatment urgency in gMG is typically lower, allowing vaccination to be completed in advance and thereby avoiding antibiotic exposure, which may worsen gMG symptoms. For both diseases, ceftriaxone is recommended as first-line therapy for suspected infection, rifampicin for prophylaxis, and either rifampicin or intramuscular ceftriaxone for post-exposure chemoprophylaxis. Patients should also carry a standby dose of ciprofloxacin for emergency self-administration at the first signs of meningitis, followed by immediate clinical evaluation. These recommendations should be reviewed regularly and updated as necessary to reflect emerging evidence and new vaccine options.\nHow to prevent serious infections during treatment for NMOSD and myasthenia gravis Blocking terminal complement activation is an effective treatment for people with acetylcholine receptor antibody–positive generalized myasthenia gravis (gMG) and aquaporin-4 antibody–positive neuromyelitis optica spectrum disorder (NMOSD). However, this treatment increases the risk of serious meningococcal infections. For this reason, all patients receiving complement inhibitors must be vaccinated against meningococcal serogroups A, C, W, Y, and B. This article presents expert consensus recommendations on how to manage meningococcal vaccination in patients with NMOSD and gMG receiving complement-inhibiting therapies in Germany, Austria, and Switzerland. The timing and approach to vaccination should be adapted to the specific disease and to each patient’s risk of worsening symptoms. In NMOSD, treatment often needs to start quickly, especially after an acute attack. In these cases, vaccination should be given at the start of complement inhibitor therapy together with preventive antibiotic treatment. In contrast, treatment for gMG is usually less urgent. This often allows vaccination to be completed before therapy begins and helps avoid antibiotic use, which may worsen gMG symptoms. For both diseases, ceftriaxone is recommended as the first treatment if infection is suspected. Rifampicin is recommended for preventive antibiotic treatment, and either rifampicin or intramuscular ceftriaxone can be used after possible exposure to infection. Patients should also carry a standby dose of ciprofloxacin to take immediately if early signs of meningitis appear, followed by urgent medical evaluation. These recommendations should be reviewed regularly and updated as new evidence and vaccines become available.", "authors": ["Berthele Achim", "Aktas Orhan", "Ayzenberg Ilya", "Claus Heike", "Lâm Thiên-Trí", "Löscher Wolfgang N", "Pröbstel Anne-Katrin", "Prüss Harald", "Rademacher Nina", "Ringelstein Marius", "Rommer Paulus", "Schara-Schmidt Ulrike", "Schoser Benedikt", "Weber Jörg R", "Zschüntzsch Jana", "Meisel Andreas", "Lünemann Jan D"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/05/15 04:54", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42137634/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, School of Medicine and Health, Technical University Munich, Munich, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "42134213", "title": "Chimeric antigen receptor T-cell therapy in neurological disorders: Emerging applications, evidence, and challenges.", "abstract": "Chimeric antigen receptor (CAR) T-cell therapy, initially developed for hematologic malignancies, engineers autologous T cells to eliminate pathogenic immune populations and aims to induce durable immune remodeling. Advancing understanding of the immunopathogenesis of several neurological disorders, particularly antibody-mediated diseases, has prompted investigation of CAR T-cell therapy beyond oncology. Early clinical studies suggest that CAR T-cell therapy may induce sustained remission in selected antibody-mediated neurological disorders, including myasthenia gravis, multiple sclerosis, and neuromyelitis optica spectrum disorder. However, evidence for immune-mediated neuropathies remains limited and largely theoretical, whereas genetic and metabolic neuromuscular disorders are biologically unsuitable targets. Neurological toxicities, particularly immune effector cell-associated neurotoxicity syndrome, remain a concern for broader adoption. Ultimately, CAR T-cell therapy represents a paradigm shift from chronic immunosuppression toward immune reconstitution in neurology. Its future role will depend on careful patient selection, strategies to mitigate neurotoxicity, and rigorous neurologist-led clinical trials. This work reviews the biological rationale, emerging clinical evidence, and neurological considerations for CAR T-cell therapy across central and peripheral nervous system disorders. We summarize clinical studies evaluating CAR T-cell therapy in neuroimmunology with an emphasis on feasibility, safety, neurological efficacy, and management of its complications.", "authors": ["Luo Jin Jun", "Wang Shaun", "Si Xiaohong"], "journal": "Journal of the neurological sciences", "entry_date": "2026/05/14 18:09", "pub_date": "2026-08-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42134213/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurology, Lewis Katz School of Medicine at Temple University, 3401 North Broad Street, Suite 525, Philadelphia, PA 19140, USA. Electronic address: jluo@temple.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "42132748", "title": "Clinical Features, Treatment, and Outcomes of Sintilimab-Induced Myocarditis.", "abstract": "To examine the clinical characteristics of sintilimab-induced myocarditis and to provide evidence for its diagnosis and management. Retrospective analysis was conducted on clinical case reports of sintilimab-induced myocarditis documented before July 31, 2025. A total of 34 patients were included, with a median age of 64 years (range: 33-85), including 23 (67.6%) male cases. The onset of myocarditis ranged from 1 to 120 days post-treatment, with a median onset of 21 days. The primary clinical presentations included dyspnea (41.2%), chest tightness (35.3%), palpitations (17.6%), and shortness of breath (14.7%), with some cases remaining asymptomatic (8.8%). Comorbid immune-related adverse events included myasthenia gravis (44.1%), myositis (17.6%), and hepatitis (17.6%). Laboratory findings often revealed elevated cardiac troponin I, N-terminal probrain natriuretic peptide, creatine kinase MB, and lactate dehydrogenase. The electrocardiogram mainly showed atrioventricular block (41.2%), ST-T segment changes (44.1%), and atrial or ventricular arrhythmias (50.0%). Echocardiography examination can show normal (34.5%), left ventricular diastolic dysfunction (31.0%), left atrial enlargement (13.8%), and pericardial effusion (13.8%). Cardiac magnetic resonance imaging may show normal (42.9%), myocardial edema (28.6%), and delayed myocardial enhancement (28.6%). Coronary angiography showed normal (73.3%) and coronary artery stenosis of the lumen (26.7%). All patients discontinued sintilimab and received steroid and intravenous immunoglobulin treatment. Outcomes indicated that 79.4% recovered from myocarditis, while 20.6% succumbed. Sintilimab-induced myocarditis has nonspecific manifestations and a high mortality rate. Myasthenia gravis and myositis can occur simultaneously with myocarditis. During simtimab treatment, it is necessary to closely monitor cardiac parameters and symptoms.", "authors": ["Liu Miao", "Sun Wei", "Pan Yong", "Wang Chunjiang"], "journal": "Journal of immunotherapy (Hagerstown, Md. : 1997)", "entry_date": "2026/05/14 10:33", "pub_date": "2026-06-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42132748/", "pub_types": ["Journal Article"], "affiliations": ["Department of pharmacy, The Affiliated Cancer Hospital of Xiangya School of Medicine, Central South University/Hunan Cancer Hospital, Changsha, Hunan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "42131832", "title": "Low-dose versus standard-dose intravenous immunoglobulin in generalized myasthenia gravis: a prospective single-center cohort study.", "abstract": "BACKGROUND: Generalized myasthenia gravis (gMG) is commonly treated with high-dose intravenous immunoglobulin (IVIG), typically at cumulative doses near 2 g/kg, during clinical worsening. However, the minimal effective IVIG exposure remains uncertain.\nMETHODS: In this prospective single-center cohort study, we enrolled 34 adults with AChR-positive gMG who received either low-dose IVIG (target ≤0.2 g/kg/day; n = 21) or standard-dose IVIG (target 0.4 g/kg/day; n = 13) according to routine clinical practice. Clinical outcomes were assessed using the Myasthenia Gravis Activities of Daily Living (MG-ADL) scale and the Quantitative Myasthenia Gravis (QMG) score at baseline and at weeks 1, 2, 4, 8, and 12. For the index IVIG course, infusion days, cumulative dose, and primary treatment indication were recorded. Oral prednisone use was evaluated as a short-term steroid-sparing outcome. Between-group comparisons were explored using regression models adjusted for age and thymoma status.\nRESULTS: Both regimens were associated with clinically meaningful improvement in MG-ADL and QMG through week 12, and no statistically significant between-group differences were detected at any follow-up visit. Most patients received 5 infusion days. After weight-based conversion, the low-dose group clustered around a cumulative exposure of approximately 1.0 g/kg, whereas the standard-dose group clustered around approximately 2.0 g/kg. Acute exacerbation was the most common indication in both groups, whereas maintenance therapy was more frequent in the standard-dose cohort. Prednisone requirements did not decline over 12 weeks in either group.\nCONCLUSION: In this prospective observational cohort, low-dose IVIG was associated with short-term clinical improvement comparable to that observed with standard-dose IVIG, without a clear steroid-sparing signal. These findings should be interpreted cautiously given the small sample size, baseline imbalance, and non-randomized design.", "authors": ["Luo Haocheng", "Dong Li", "Yang Li", "Deng Yufei", "Zhang Chaoyue", "Zhang Xuxiang", "Hu Liqing", "Wu Zhenyu", "Yang Xiaojun", "Jiang Qilong"], "journal": "Frontiers in neurology", "entry_date": "2026/05/14 04:58", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42131832/", "pub_types": ["Journal Article"], "affiliations": ["The First Clinical Medical College of Guangzhou University of Chinese Medicine, Guangzhou, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42127467", "title": "Efgartigimod in myasthenia gravis: Efficacy and steroid-sparing benefits in a real-world cohort.", "abstract": "OBJECTIVE: Efgartigimod, a neonatal Fc receptor (FcRn) antagonist, has been shown to reduce pathogenic immunoglobulin G (IgG) autoantibodies, notably anti-acetylcholine receptor (AChR) antibodies, in myasthenia gravis (MG). While clinical trials have established its safety and efficacy, real-world evidence regarding its therapeutic effectiveness and steroid-sparing potential remains limited. This study aimed to evaluate the real-world efficacy and steroid-sparing benefits of efgartigimod in the clinical management of MG.\nMETHODS: Forty-one patients with generalized myasthenia gravis (gMG) were enrolled in this prospective study. Participants received efgartigimod treatment and were followed for 26 weeks. Clinical outcomes, primarily Myasthenia Gravis Activities of Daily Living (MG-ADL) scores and corticosteroid dosages, were systematically evaluated. Statistical analyses were performed using R version 4.5.0.\nRESULTS: Patients were stratified into two cohorts based on treatment cycles: 22 received two cycles of efgartigimod, while 19 received a single cycle. Bulbar and respiratory symptoms improved within two weeks, whereas ocular and limb weakness required a more prolonged treatment duration to achieve clinical benefit. Myasthenia Gravis Activities of Daily Living (MG-ADL) scores demonstrated a significant decline, with a more rapid response observed in severe cases. By Week 26, the proportion of patients requiring more than 16 mg/d of methylprednisolone decreased from 63.4% at baseline to 14.6%. The two-cycle cohort exhibited a lower mean cumulative methylprednisolone dose (4861.50 mg vs. 5469.24 mg). No treatment-related adverse effects were observed.\nCONCLUSION: Efgartigimod demonstrated variable clinical responses across different muscle groups, with early improvements in bulbar and respiratory function alongside significant steroid-sparing advantages. Given that baseline MG-ADL scores serve as a reliable predictor of the time to achieve minimal symptom expression (MSE), and considering that repeated treatment cycles further augment therapeutic efficacy, efgartigimod represents a promising steroid-sparing immunomodulatory strategy for the management of MG.", "authors": ["Xu Xiao-Na", "Jiang Feng", "Li Jin-Ming", "Li Xiao", "Liu Rui", "Liu Chang", "Meng Tong-Yu", "Zhang Yue", "Yang Chun-Sheng"], "journal": "Clinical neurology and neurosurgery", "entry_date": "2026/05/13 18:01", "pub_date": "2026-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42127467/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, Tianjin 300052, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "42127347", "title": "Risk of Myasthenia Gravis Exacerbation During Pregnancy and Postpartum: A Nationwide Cohort Study.", "abstract": "BACKGROUND AND OBJECTIVES: The impact of pregnancy on the clinical course of myasthenia gravis (MG) remains uncertain, with existing evidence mainly derived from small case series. Using nationwide longitudinal register data, we aimed to assess the risk of MG exacerbation during pregnancy and up to 1 year postpartum.\nMETHODS: In this population-based cohort study, we included women with MG recorded in the Swedish National MG Register who had singleton pregnancies documented in the Medical Birth Register after MG diagnosis (1987-2019). The exposure was pregnancy, and the outcome was MG exacerbation. The primary outcome measure was hospital admissions with MG during pregnancy and the postpartum year, compared with the year preceding pregnancy. Cox proportional hazards models estimated hazard ratios (HRs), adjusting for disease duration and prior thymectomy. The secondary outcome measure was changes in immunosuppressive MG medications during pregnancy and postpartum.\nRESULTS: We identified 112 women with MG (median age 30 years) with 176 singleton pregnancies. During pregnancy, women were not more likely to be hospitalized for MG than in the prepregnancy year (HR 0.74, 95% CI 0.39-1.41), and there was no increased risk of longer hospital admissions (HR 0.83, 95% CI 0.36-1.88). The postpartum period was associated with an increased risk of prolonged MG admissions during the first 3 months (HR 5.02, 95% CI 1.66-15.24), with a similar risk observed throughout the first 12 months postpartum (HR 4.52, 95% CI 1.26-16.14). During pregnancy, immunosuppressive MG medications were reduced or discontinued in 13 pregnancies and increased in 6. Postpartum, medications were initiated or escalated in 10 pregnancies and reduced in none. The risk of prolonged MG admissions was higher in periods outside of pregnancy compared with the prepregnancy year (HR 2.95, 95% CI 0.84-10.43), suggesting that women conceive during periods of relative disease stability.\nDISCUSSION: Pregnancy was not associated with an increased risk of MG exacerbation. The postpartum period was linked to more severe or prolonged exacerbations in a minority of women, highlighting the importance of close monitoring after delivery. Milder exacerbations not requiring hospitalization or clear medication escalation may have been underestimated, underscoring the need for larger prospective international studies that include detailed clinical data.", "authors": ["O'Connor Laura", "Gabrysch Katja", "Wikström Anna-Karin", "Rostedt Punga Anna"], "journal": "Neurology", "entry_date": "2026/05/13 16:04", "pub_date": "2026-06-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42127347/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medical Sciences, Uppsala University, Sweden."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "42125648", "title": "Real-world experience with efgartigimod in generalized myasthenia gravis: a single-center retrospective study in China.", "abstract": "OBJECTIVE: This study aimed to evaluate the real-world efficacy, safety, and application patterns of efgartigimod in Chinese patients with generalized myasthenia gravis (gMG), with a focus on individualized treatment strategies.\nMETHODS: We conducted a single-center, retrospective analysis of 81 gMG patients who received at least one standard cycle of efgartigimod (10 mg/kg weekly for 4 weeks). Disease severity was assessed using Myasthenia Gravis Activities of Daily Living (MG-ADL), Quantitative Myasthenia Gravis (QMG), and Myasthenia Gravis Composite (MGC) scores at baseline, week 2, and week 4. Retreatment and regimen modifications were individualized, which included exploration of a reduced-frequency regimen (2 infusions every 2 weeks) in selected patients.\nRESULTS: In the overall cohort, 65 (80.25%) and 63 (77.78%) patients achieved MG-ADL (reduction ≥2) and QMG (reduction ≥3) responses, respectively, after the first cycle. 65 (80.25%) patients received only one cycle; among them, 41 (63.07%) maintained disease control with concomitant immunosuppressive therapies without requiring additional efgartigimod. The 16 patients receiving multiple cycles (≥2) had higher baseline disease severity (higher Myasthenia Gravis Foundation of America class, MG-ADL, and QMG scores) and showed progressive improvement with flexible retreatment. In a selected subgroup of 9 patients (based on age, robust response, and significant IgG reduction), a reduced-frequency regimen (2 infusions every 2 weeks) maintained efficacy while reducing the infusion burden. Adverse events were mostly mild, with no new safety signals.\nINTERPRETATION: Efgartigimod demonstrated rapid and broad efficacy in a real-world gMG cohort. An \"induction-maintenance\" strategy, using efgartigimod for acute control and conventional immunosuppressants for long-term management, proved effective in most patients. A reduced-frequency regimen may be feasible in selected cases, highlighting the value of individualized treatment approaches in optimizing outcomes and reducing treatment burden.", "authors": ["Niu Zhenyu", "Wang Jianchun", "Ren Jingru", "Liu Ran", "Guo Jing", "Zhang Nan", "Zheng Yiming", "Hao Hongjun", "Gao Feng", "Jin Haiqiang"], "journal": "Frontiers in immunology", "entry_date": "2026/05/13 04:47", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42125648/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking University First Hospital, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42121846", "title": "Cell Death in Skeletal Muscle Diseases: Diverse Roles and Pathological Processes.", "abstract": "Skeletal muscle is vital for movement and metabolism, and its dysfunction underpins disorders like muscular dystrophy and sarcopenia, severely impacting life quality. In these diseases, various cell death pathways are pivotal, driving core pathological features such as fiber loss and chronic inflammation. This study reviews the central role of cell death in skeletal muscle diseases, and analyzes its roles and mechanisms in genetic muscle disorders such as Duchenne muscular dystrophy (DMD), glycogen storage diseases (GSD), mitochondrial myopathies, as well as acquired muscle disorders such as idiopathic inflammatory myopathy, sarcopenia, rhabdomyolysis, and myasthenia gravis (MG). We also explore the potential of cell death-related molecules as biomarkers and discuss emerging therapeutic strategies that target these pathways, aiming to provide new insights for diagnosis and treatment.", "authors": ["Yang Ya-Lan", "Guo Liang"], "journal": "Cells", "entry_date": "2026/05/13 01:03", "pub_date": "2026-04-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42121846/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Key Laboratory of Exercise and Health Sciences of the Ministry of Education, Shanghai University of Sport, Shanghai 200438, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.2, "journal_quartile": "2区"}, {"pmid": "42121215", "title": "Multicentric prognostic observational study on biomarker profile in immunotherapy-naïve patients with highly active generalized myasthenia gravis (PROGNO-MG): a study protocol.", "abstract": "BACKGROUND: Myasthenia gravis has a variable disease course. Early identification of patients with a highly active disease is crucial to prevent myasthenic exacerbations and crisis, necessitating more aggressive immunotherapy. However, no biomarkers currently exist to identify patients at risk for highly active disease course.\nOBJECTIVE: The PROGNO-MG study aims to identify blood-based biomarker signatures associated with a highly active disease course in immunotherapy-naïve patients with acetylcholine-receptor-antibody positive (AChR+) generalized Myasthenia gravis (gMG).\nMETHODS: This is an investigator-initiated prospective, multicentric, observational study. Seventy newly diagnosed immunotherapy-naïve AChR+ gMG patients will be enrolled and followed up for 24 months. Blood samples and clinical data will be collected biannually. Biomarkers (calprotectin, neurofilament light chain, ITIH3, complement activation, kappa free light chains, and exploratory proteome-analyses and immune cell phenotyping) will be measured and their association with clinical outcomes will be evaluated.\nPERSPECTIVE: The results will provide evidence for prognostic biomarkers, supporting risk stratification and early individualized treatment for AChR+ gMG patients.\nTRIAL REGISTRATION: The study is registered in the German clinical trial register (DRKS00035457).", "authors": ["Kohle Felix", "Konen Franz Felix", "Grittner Ulrike", "Schulze Daniel", "Glaubitz Stefanie", "Nelke Christopher", "Schroeter Christina B", "Huntemann Niklas", "Trillenberg Peter", "Großkreutz Julian", "Schoser Benedikt", "Schubert Charlotte", "Zschüntzsch Jana", "Schroeter Michael", "Hegelmaier Tobias", "Skripuletz Thomas", "Sieb Jörn Peter", "Ruck Tobias", "Meuth Sven", "Wiendl Heinz", "Keller Christian Wolfgang", "Lünemann Jan D", "Lehnerer Sophie", "Meisel Andreas", "Stascheit Frauke"], "journal": "Neurological research and practice", "entry_date": "2026/05/13 00:15", "pub_date": "2026-05-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42121215/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Faculty of Medicine, University of Cologne and University Hospital Cologne, Cologne, Germany."], "china_related": false, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "42115958", "title": "Diagnostic Accuracy of the Combined Bedside Tests (Icepack and Fatigability) in Diagnosing Juvenile Myasthenia Gravis.", "abstract": "BackgroundDiagnosing juvenile myasthenia gravis (JMG) can be challenging because of limited access to confirmatory tests.ObjectiveThis study evaluates the validity of bedside tests (the ice pack test, fatigability test, and combined bedside test) for diagnosing JMG in patients with ptosis.MethodsA retrospective analysis of children, aged 1 month to 18 years, diagnosed with ptosis who underwent bedside evaluation. We used sensitivity, specificity, accuracy, positive predictive value, negative predictive value, and statistical analyses to compare the diagnostic performance to that of standard confirmatory tests.ResultsOf the 43 identified ptosis patients, 32 were included. The combined bedside test had a sensitivity of 92.8% and accuracy of 87.5% but modest specificity (50%). It outperformed the ice pack test (P = .0005), which showed low sensitivity (42.8%) and accuracy (43.8%). The fatigability test had 82% sensitivity and 92% PPV.ConclusionThe combined bedside test is a dependable screening instrument for JMG and may facilitate early diagnosis. The fatigability test is also a useful addition.", "authors": ["Kortnoi Pechpailin", "Amornvit Jakkrit", "Paprad Tanitnun"], "journal": "Journal of child neurology", "entry_date": "2026/05/12 00:34", "pub_date": "2026-05-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42115958/", "pub_types": ["Journal Article"], "affiliations": ["Division of Neurology, Department of Pediatrics, Faculty of Medicine, Chulalongkorn University, Bangkok, Thailand."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "3区"}, {"pmid": "42112324", "title": "Dysbiosis of gut microbiota and metabolomic alterations in myasthenia gravis: insights from 16S rRNA sequencing and untargeted metabolomics.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder of neuromuscular transmission. Gut dysbiosis has been implicated in autoimmune pathogenesis, yet integrated microbial and metabolomic profiling in MG remains scarce. To characterize gut microbiota and the fecal metabolome in MG, identify diagnostic biomarkers, and explore associations between microbial taxa, metabolites, and clinical severity.\nMETHODS: Fecal samples from 29 MG patients and 10 healthy controls underwent 16S rRNA sequencing and UHPLC-Q-TOF MS metabolomics. LEfSe identified differential taxa; metabolites were screened by VIP > 1.0, P < 0.05, FDR q < 0.05. Random Forest and Spearman correlation assessed biomarker performance and microbiota - metabolite - clinical associations.\nRESULTS: MG patients showed significantly reduced alpha- and beta-diversity. LEfSe identified 232 discriminative taxa, with depletion of butanoic acid-producing commensals (Faecalibacterium prausnitzii, Ruminococcus bromii, Bifidobacterium bifidum) and enrichment of Klebsiella. Metabolomics revealed 567 altered metabolites (424 downregulated), including reduced short-chain fatty acids and secondary bile acids (lithocholic, isolithocholic, and allolithocholic acid). The Random Forest metabolite model achieved AUC = 1.0. Spearman analysis revealed that lithocholic acid (P < 0.05) and allocholic acid (P < 0.001) showed positive correlations with the QMGS, while Ruminococcus abundance was positively correlated with butanoic acid (P < 0.01). KEGG analysis implicated cholinergic synapse, bile secretion, sphingolipid signaling, and mTOR pathways.\nCONCLUSIONS: MG patients exhibit a distinct profile of gut dysbiosis and metabolic disturbances. The specific microbial and metabolic biomarkers identified in this study may offer novel insights for auxiliary diagnosis of MG and guide future microbiota-targeted intervention strategies.", "authors": ["Shan Yunan", "Chen Wei", "Li Yanbin"], "journal": "Frontiers in immunology", "entry_date": "2026/05/11 07:00", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42112324/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Shandong First Medical University & Shandong Provincial Qianfoshan Hospital, Shandong Institute of Neuroimmunology, Shandong Key Laboratory of Rheumatic Disease and Translational Medicine, Jinan, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42112121", "title": "Ginsenoside Rg1 ameliorates experimental autoimmune myasthenia gravis by regulating T cell subsets, inhibiting PI3K-AKT pathway and modulating gut microbiota and metabolites.", "abstract": "BACKGROUND: Ginsenoside Rg1 (GRg1), a bioactive saponin derived from ginseng, exhibits diverse pharmacological properties, including anti-inflammatory, antioxidant, and neuroprotective effects. However, its role in myasthenia gravis (MG) remains unexplored. This study investigated the therapeutic potential of GRg1 in experimental autoimmune myasthenia gravis (EAMG).\nMETHODS: The EAMG model was established in Lewis rats using the AChR97-116 peptide. ELISA was employed to determine serum anti-AChR antibody levels in rats, while Flow cytometry or PCR was used to analyze T cell subsets. Gut microbiota composition was assessed via 16S rRNA sequencing, while non-targeted metabolomics identified metabolic changes. Network pharmacology and molecular docking were employed to predict GRg1's therapeutic targets in EAMG, followed by experimental validation using immunohistochemistry.\nRESULTS: GRg1 administration significantly alleviated the clinical symptoms of EAMG rats, reduced serum anti-AChR antibody levels, and modulated T cell responses. KEGG analysis implicating the PI3K-AKT pathway. Molecular docking confirmed strong binding affinities between GRg1 and key PI3K-AKT proteins. Immunohistochemistry revealed GRg1-mediated inhibition of PI3K/AKT phosphorylation in splenic tissues. Additionally, GRg1 restored gut microbiota homeostasis. Metabolomic analysis further revealed significant differences in metabolites between EAMG and CFA rats, which were inhibited after GRg1 treatment.\nCONCLUSIONS: GRg1 ameliorates EAMG through immunomodulation, PI3K-AKT pathway inhibition, gut microbiota restoration, and metabolic reprogramming, highlighting its potential as a novel therapeutic agent for MG.", "authors": ["Li Yan", "Shan Yu-Nan", "Xu Lin", "He Zhi-Lin", "Wang Guan-Qing", "Wang Qing", "Li Yan-Bin", "Chen Wei"], "journal": "Journal of ginseng research", "entry_date": "2026/05/11 06:58", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42112121/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Shandong First Medical University & Shandong Provincial Qianfoshan Hospital, Shandong Institute of Neuroimmunology, Shandong Provincial Medicine and Health Key Laboratory of Neuroimmunology, Jinan, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 0.3, "journal_quartile": null}, {"pmid": "42111069", "title": "Myasthenia gravis complicated with autoimmune encephalitis: a review.", "abstract": "OBJECTIVE: This review aims to provide updated information about myasthenia gravis (MG) complicated with autoimmune encephalitis.\nBACKGROUND: MG and autoimmune encephalitis are both antibody-mediated disorders with a need for active and individually adapted immunosuppressive treatment. The two disorders can co-exist. This represents therapeutic and diagnostic challenges but may help in elucidating disease mechanisms and risk factors.\nMETHODS: A literature search combined the words \"myasthenia gravis,\" \"autoimmune encephalitis,\" and further combined each specific antibody associated with autoimmune encephalitis and \"myasthenia gravis.\"\nRESULTS: Epidemiological data and multiple single case reports illustrate the increased risk for autoimmune encephalitis in MG. The target antigens for the antibodies in both MG and autoimmune encephalitis vary among patients. Clinical manifestations, choice of therapy, and prognosis depend on antibody pattern. MG should be treated actively with immunosuppression according to updated and generally accepted guidelines. For treatment of autoimmune encephalitis, high corticosteroid doses, intravenous immunoglobulin (IVIg), plasma exchange, and rituximab should be considered. FcRn-blockers represent an additional option.\nCONCLUSION: MG and autoimmune encephalitis have overlapping pathogenesis and similar preferred drug therapies. This comorbidity represents a therapeutic challenge, and often with the need of high-dose immunosuppressive combination therapy. New and targeted therapies are applied in some MG patients, and such therapies have relevance also for autoimmune encephalitis.", "authors": ["Gilhus Nils Erik"], "journal": "Frontiers in neurology", "entry_date": "2026/05/11 06:48", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42111069/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Clinical Medicine, University of Bergen, Bergen, Norway."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "42110106", "title": "Severe Hypogammaglobulinemia (IgG) During Efgartigimod Therapy in Neurological Practice: A Real-World Case Series.", "abstract": "Background Efgartigimod is a neonatal Fc receptor (FcRn) antagonist approved for adults with generalized myasthenia gravis (gMG) who are anti-acetylcholine receptor antibody-positive, and for chronic inflammatory demyelinating polyradiculoneuropathy (CIDP). By blocking FcRn-mediated IgG recycling, efgartigimod lowers circulating IgG and reduces pathogenic autoantibodies. Clinical trials have demonstrated efficacy and an overall acceptable safety profile, but patients with low baseline IgG were generally not well represented. Objective The main objective of this study is to describe severe reductions in serum IgG observed in routine neurologic practice during efgartigimod therapy, and to explore their potential clinical implications, including infection risk and management considerations. Methods We performed a retrospective case series of 10 patients treated with efgartigimod in our practice between 2025 and 2026 for CIDP and MG. Available clinical data were reviewed, including diagnosis, prior immunotherapy exposure, baseline IgG (when available), serial IgG measurements, nadir IgG, and any documented infectious complications.  Results Several patients developed marked hypogammaglobulinemia during treatment, including profound reductions to levels below 100 mg/dL in selected cases. Several patients reached IgG levels within ranges associated with increased susceptibility to infection (<500 mg/dL, particularly <400 mg/dL), although no severe infections were observed. One patient with CIDP and prior rituximab exposure had a baseline IgG of approximately 800 mg/dL, and later developed an IgG level of 66 mg/dL. Another patient without prior B-cell-depleting therapy also developed an IgG level below 100 mg/dL. No major infectious complication was documented during the observation period, but the degree of IgG suppression raised concern for clinically meaningful vulnerability to severe infection. Conclusions Efgartigimod therapy was associated with significant reductions in IgG in this real-world cohort. Because trial populations excluded or underrepresented patients with low baseline IgG, and did not meaningfully study extreme hypogammaglobulinemia, baseline and serial IgG monitoring should be strongly considered in all patients starting therapy, especially during the first six months. These findings highlight the potential for clinically meaningful IgG decline in certain patients, and support consideration of individualized monitoring strategies. These observations are hypothesis-generating and warrant further study.", "authors": ["Espinosa Patricio S", "Preisler Johanna", "Motiño Villanueva Ada", "Bellon McKenzie B", "Hennekens Charles H"], "journal": "Cureus", "entry_date": "2026/05/11 06:40", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42110106/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Espinosa Neuroscience Institute, Boca Raton, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42107209", "title": "Factors associated with initial exacerbation after corticosteroids treatment in myasthenia gravis patients with bulbar symptoms.", "abstract": "BACKGROUND: Corticosteroid (CS) administration is a fundamental immunotherapy for myasthenia gravis (MG), but it may temporarily worsen symptoms, especially in patients with bulbar symptoms, and even lead to myasthenic crisis (MC).\nOBJECTIVE: To investigate factors associated with initial exacerbation after CS treatment in MG patients with bulbar symptoms, with a particular focus on comparing the risk between two initial CS regimens: intravenous methylprednisolone (IVMP) pulse regimen versus oral CS regimen.\nDESIGN: A single-center retrospective study.\nMETHODS: We conducted a retrospective cohort study of 119 bulbar MG patients who received CS treatment between 2012 and 2023. We observed an initial exacerbation after CS administration. Univariate analysis and multiple logistic regression models were used to determine the associated factors for initial exacerbation and severe exacerbation after CS treatment.\nRESULTS: 62 (52.1%) patients experienced an initial exacerbation after CS treatment, while 16 (13.5%) experienced a severe exacerbation. The median onset of initial exacerbation after CS treatment was day 3. The median duration of initial exacerbation was 3.5 days. The rates of initial exacerbation and severe exacerbation in the IVMP group were significantly higher than those in the oral CS group (74.2% vs. 44.3% and 29.0% vs. 8.0%, respectively). Multivariate logistic regression analysis revealed IVMP regimen (OR4.902, 95%CI 1.774-13.541, p = 0.002) and reduced biting strength/difficulty (OR7.286, 95%CI 2.036-26.071, p = 0.002) were factors independently associated with initial exacerbation. For severe exacerbation, IVMP regimen (OR7.695, 95%CI 1.394-42.464, p = 0.019), reduced cough strength (OR11.558, 95%CI 1.392-95.937, p = 0.023), and maximal voluntary ventilation (MVV) ≤ 60%(OR8.213,95%CI 1.637-41.217, p = 0.011) were independently associated factors.\nCONCLUSIONS: IVMP regimen is associated with initial exacerbation after CS treatment in bulbar MG patients. Caution should be exercised when using IVMP regimen in clinical practice for bulbar MG patients, especially in those with reduced cough strength and low MVV.", "authors": ["Liu Xinxin", "Li Ran", "Xie Qiucheng", "Wang Jiawei", "Jing Yun"], "journal": "Journal of clinical neuroscience : official journal of the Neurosurgical Society of Australasia", "entry_date": "2026/05/10 18:06", "pub_date": "2026-05-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42107209/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Beijing Tongren Hospital, Capital Medical University, Beijing 100730, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "42106024", "title": "Clinical Significance of B7-H4 in Peripheral Blood of Patients With Myasthenia Gravis.", "abstract": "OBJECTIVES: This study aimed to systematically investigate the dynamics changes in membrane-bound B7-H4 (mB7-H4) expression and soluble B7-H4 (sB7-H4) levels in the peripheral blood of patients with acetylcholine receptor antibodies (AchR-Ab)-positive myasthenia gravis (MG) across different disease phases, and to explore their clinical significance.\nMETHODS: AchR-Ab-positive MG patients at baseline, relapse, and remission stages, along with age- and sex-matched healthy controls (HCs), were enrolled. Peripheral blood was obtained from all participants. mB7-H4 expression on circulating immune cell subsets was determined by flow cytometry, while plasma sB7-H4 concentration was quantified using enzyme-linked immunosorbent assay (ELISA).\nRESULTS: Compared to HC, patients with relapsing MG exhibited significantly increased mB7-H4 expression on CD4+ T cells and CD14+ monocytes (p < 0.05). In contrast, plasma sB7-H4 levels were markedly decreased in relapsing-MG patients relative to HC (p < 0.05). Among MG subgroups, mB7-H4 expression on CD4+ T cells was significantly higher in relapsing-MG patients than in those at baseline or in remission (p < 0.05). Conversely, plasma sB7-H4 levels were significantly lower in both relapsing and remitting patients compared with the baseline-MG group (p < 0.05). Within the relapsing-MG patients, patients with abnormal thymic pathology exhibited significantly lower sB7-H4 levels than those with a normal thymus (p < 0.05). Correlation analyses demonstrated that mB7-H4 expression on CD14+ monocytes was positively correlated with quantitative MG scores (QMGs; r = 0.544, p = 0.020), whereas sB7-H4 levels were negatively correlated with QMGs (r = -0.417, p = 0.016). Immunosuppressive treatment did not significantly affect sB7-H4 levels compared with pre-treatment values (p > 0.05). Univariate analysis identified elevated mB7-H4 expression on CD4+ T cells as a potential risk factor for MG relapse. However, this association did not remain significant after multivariate adjustment for confounders variables.\nCONCLUSIONS: During MG relapse, inflammatory activation may engage the B7-H4 pathway, characterized by increased mB7-H4 and decreased sB7-H4 levels, which may cooperatively contribute to immune suppression and serve as a compensatory protective mechanism. B7-H4 expression appears to be associated with disease severity. Thymic abnormalities may contribute to the downregulation of sB7-H4, whereas immunosuppressive treatment may not significantly modify its circulating levels. Although increased CD4+ B7-H4 expression is associated with relapse, it does not represent an independent predictor of relapse risk.", "authors": ["Zhou Xiaoling", "Zhu Yunfei", "Gui Tiantian", "Gu Yanzheng", "Lu Haifeng", "Ju Wentong", "Tian Jingluan", "Xue Qun"], "journal": "Journal of immunology research", "entry_date": "2026/05/09 19:14", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42106024/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Soochow University, Suzhou, 215000, Jiangsu, China, sdfyy.cn."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.0, "journal_quartile": "3区"}, {"pmid": "42104987", "title": "Prevalence and characteristics of patients with seronegative myasthenia gravis.", "abstract": "Myasthenia gravis is an autoimmune disorder characterized by antibodies targeting the neuromuscular junction, causing fatigue of skeletal muscle. Natural history and epidemiological studies report that around 10% of patients diagnosed with myasthenia gravis do not have detectable levels of antibodies, categorized as seronegative. Theories of the pathophysiology in these patients are predominantly centered around undetectable antibody titers and antibodies against yet undefined antigens in the neuromuscular junction. This study aims to investigate the regional prevalence and characteristics of patients with seronegative myasthenia gravis. This study is a retrospective chart review of 350 patients with myasthenia gravis treated at the Copenhagen Neuromuscular Center. Of these, 15 (4.3%) were seronegative and 335 (95.7%) were seropositive. No differences were found when comparing the two groups on demographics, symptom profile, comorbidities, treatment, and diagnostic delay. The frequency of seronegative myasthenia gravis patients was lower in this cohort than previously reported. Seronegative myasthenia gravis patients were essentially indistinguishable from seropositive patients on all parameters evaluated. These findings correspond well with the emerging evidence of a similar pathophysiology in the two groups.", "authors": ["Andersen Rebecca Kjær", "Ankjær Peter", "Axelsen Kasper Holst", "Andersen Linda Kahr", "Vissing John", "Witting Nanna"], "journal": "Journal of neurology", "entry_date": "2026/05/09 11:02", "pub_date": "2026-05-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42104987/", "pub_types": ["Journal Article"], "affiliations": ["Copenhagen Neuromuscular Center, Rigshospitalet, Inge Lehmanns Vej 8, Copenhagen, Denmark."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "42104835", "title": "Adaptive trial design and interim decision-making using incomplete longitudinal measurements: Methods and application to myasthenia gravis.", "abstract": "Sample size re-estimation designs using a promising zone framework are widely used adaptive trial methodologies that guide study continuation or modification during interim analyses. Conventional implementations often base interim calculations solely on participants with available primary endpoints, overlooking predictive information from baseline and earlier visits. This underutilization can lead to inefficient interim decision-making. In this work, we adapt semi-parametric efficient estimators that leverage baseline and intermediate data for use within a promising zone sample size re-estimation design. By incorporating information from participants who have not yet reached their primary endpoint, these estimators enable more precise interim estimators while maintaining strict Type I error control through the inverse normal combination function. Using data from the ADAPT study in generalized myasthenia gravis, we illustrate how these methods integrate into a promising zone sample size re-estimation framework. Simulations based on longitudinal profiles of anti-acetylcholine receptor antibody-seronegative participants demonstrate improved operating characteristics compared with the conventional approach, including increased overall power, especially for moderate effect sizes, without inflating the one-sided Type I error. Our findings highlight the practical benefit of applying existing semi-parametric estimators within promising zone sample size re-estimation designs, enabling more efficient and timely interim decision-making in settings with partially observed longitudinal data.", "authors": ["Kapur Kush", "Gistelinck Fien", "Vandebosch An", "Van Lancker Kelly"], "journal": "Clinical trials (London, England)", "entry_date": "2026/05/09 05:32", "pub_date": "2026-05-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42104835/", "pub_types": ["Journal Article"], "affiliations": ["argenx, Ghent, Belgium."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "4区"}, {"pmid": "42104265", "title": "Efficacy and safety of low-dose trazodone hydrochloride for insomnia in patients with myasthenia gravis.", "abstract": "BACKGROUND: The management of insomnia in patients with myasthenia gravis (MG) poses a clinical challenge, as MG is a well-recognized contraindication to sedative-hypnotic agents. This retrospective study aimed to assess the efficacy and safety of low-dose trazodone hydrochloride for the management of insomnia in MG patients.\nMETHODS: Clinical data were collected from MG patients with comorbid insomnia who received low-dose trazodone hydrochloride (25-100 mg, once nightly, for ≥ 4 weeks). Enrolled patients were stratified into three groups based on Self-Rating Depression Scale (SDS) scores: pure insomnia group (SDS: 0-52), mild depression group (SDS: 53-62), and moderate-to-severe depression group (SDS ≥ 63). Changes in Pittsburgh Sleep Quality Index (PSQI) scores, SDS scores, and Myasthenia Gravis Activities of Daily Living (MG-ADL) scores before and after trazodone hydrochloride administration were analyzed.\nRESULTS: Total 68 MG patients were enrolled, including 17 cases of ocular MG and 51 cases of mild generalized MG. Of these patients, 18 (26.5%) were assigned to the pure insomnia group, 30 (44.1%) to the mild depression group, and 20 (29.4%) to the moderate-to-severe depression group. Post-treatment PSQI scores were significantly reduced compared to baseline across all groups (all p < 0.01). The mild depression group exhibited a significant decrease in SDS scores after treatment (p < 0.01), whereas no significant reduction in SDS scores was observed in the moderate-to-severe depression group. No patients experienced an increase in MG-ADL scores. Mild adverse events were reported in 4 patients (5.9%), including hypotension (n = 2), dizziness (n = 1), and nausea (n = 1).\nCONCLUSIONS: Low-dose trazodone hydrochloride demonstrates favorable efficacy and safety in improving insomnia in patients with stable and mild MG.", "authors": ["Peng Jing-Ting", "Kong Xiu-Yun", "Li Ran", "Cao Yang-Yue", "Jiang Han-Qiu", "Wang Jia-Wei", "Cui Shi-Lei"], "journal": "BMC neurology", "entry_date": "2026/05/08 23:44", "pub_date": "2026-05-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42104265/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Department, Beijing Tongren Hospital, Capital Medical University, Beijing, 100730, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "42104030", "title": "Correction to: Italian recommendations for the diagnosis and treatment of myasthenia gravis.", "abstract": "", "authors": ["Fionda Laura", "Alboini Paolo Emilio", "Antozzi Carlo", "Bonifati Domenico Marco", "Damato Valentina", "Habetswallner Francesco", "Inghilleri Maurizio", "Iorio Raffaele", "Liguori Rocco", "Tassoni Michelangelo Maestri", "Maggi Lorenzo", "Mantegazza Renato", "Massa Roberto", "Pegoraro Elena", "Rodolico Carmelo", "Pino Mariangela", "Antonini Giovanni", "Evoli Amelia"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/05/08 23:23", "pub_date": "2026-05-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42104030/", "pub_types": ["Published Erratum"], "affiliations": ["Neuromuscular and Rare Disease Centre, Neurology Unit, Sant'Andrea Hospital, Via di Grottarossa 1035-1039, 00189, Rome, Italy. laura.fionda@uniroma1.it."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42102247", "title": "Robot-Assisted Versus Video-Assisted Thymectomy: A Narrative Review of Current Evidence.", "abstract": "OBJECTIVES: Minimally invasive thymectomy has transformed the surgical management of thymic epithelial tumours and myasthenia gravis (MG). Video-assisted thoracoscopic surgery (VATS) is well established, whereas robot-assisted thoracoscopic surgery (RATS) provides technical and ergonomic advantages but at a higher cost. We reviewed current evidence to clarify the indications, oncological validity, perioperative performance, and economic implications of RATS compared with VATS and open thymectomy.\nMETHODS: A structured narrative review was conducted, drawing on multi-institutional cohorts, registry-based propensity-matched studies, and systematic reviews. Evidence was organized by tumour characteristics, special populations (MG, obesity, recurrent thymoma), perioperative and long-term outcomes, surgeon-centred considerations, and cost-effectiveness.\nRESULTS: In early-stage thymoma and MG, both VATS and RATS achieve R0 resection rates ≥95% and recurrence outcomes comparable with sternotomy. Robot-assisted thoracoscopic surgery is associated with lower blood loss, fewer conversions, and signals of faster recovery, with particular advantages in obese or redo cases. Long-term survival appears equivalent across minimally invasive approaches, without evidence of oncological superiority. However, RATS incurs higher per-case costs, primarily from instrumentation and platform expenses.\nCONCLUSIONS: VATS remains efficient for straightforward cases, whereas RATS may safely extend minimally invasive eligibility to anatomically complex scenarios while maintaining oncological integrity. Adoption should be indication-driven and resource-conscious. Further multicentre studies with long-term follow-up, patient-reported outcomes, and cost-effectiveness analyses are needed to define the sustainable role of RATS in thymectomy.\nCLINICAL REGISTRATION NUMBER: Not applicable.", "authors": ["Bae Seon Yong", "Na Kwon Joong"], "journal": "European journal of cardio-thoracic surgery : official journal of the European Association for Cardio-thoracic Surgery", "entry_date": "2026/05/08 14:14", "pub_date": "2026-04-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42102247/", "pub_types": ["Review", "Research Support, Non-U.S. Gov't"], "affiliations": ["Department of Thoracic and Cardiovascular Surgery, Seoul National University Hospital, Seoul 03080, Republic of Korea."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "42101054", "title": "Evaluation of steroid toxicity using the Glucocorticoid Toxicity Index-Metabolic Domains instrument in adults with myasthenia gravis: a real-world study in the USA.", "abstract": "Aim: The Glucocorticoid Toxicity Index-Metabolic Domains (GTI-MD) has been utilized to assess steroid toxicity in clinical trials and practice but has not been applied previously to large datasets. The GTI-MD was used to investigate steroid toxicity in patients with myasthenia gravis (MG) using a large real-world dataset. Materials & methods: Steroid toxicity was assessed in adults with MG (≥2 diagnoses occurring between ≥30 and ≤730 days apart) using Optum® electronic health records. Patients were categorized into steroid-initiator (MG-SI) or steroid-naive (MG-SN) cohorts. The GTI-MD algorithm assessed changes in steroid toxicity during follow-up using vital signs and simple laboratory tests pertaining to toxicity in the body mass index, blood pressure, glucose tolerance and lipid metabolism domains. Changes in steroid toxicity were reported as cumulative worsening scores (CWS) and aggregate improvement scores (AIS). Results: A total of 682 (MG-SI:377; MG-SN: 305) patients with MG were included. The potential for steroid toxicity at index date, as assessed by the GT-SNAPSHOT scores, was comparable between the cohorts at baseline (92.0 ± 31.1 vs 88.8 ± 32.8; p = 0.117). At follow-up, the MG-SI cohort had higher CWS scores than the MG-SN cohort (22.6 ± 22.8 vs 18.7 ± 21.2; p = 0.023) and were more likely to exceed the 10-point minimum clinically important difference (68% vs 59%; p = 0.016) and the 20-point threshold (44% vs 36%; p = 0.030). Patients with multiple steroid exposures had higher CWS (25.7 ± 24.8 vs 19.2 ± 19.9; p = 0.006) and AIS (9.6 ± 34.7 vs -0.3 ± 33.7; p = 0.005) values than one-time steroid users. Patients who received ≥20 mg/day of steroids (prednisone-equivalent) at index had higher CWS values (25.0 ± 23.0 vs 19.9 ± 22.3; p = 0.033) and AIS values (8.3 ± 32.9 vs 1.1 ± 35.9; p = 0.044) compared with those who received <20 mg/day of steroids. Conclusion: The GTI-MD is a valuable and sensitive method for unmasking steroid toxicity in MG using large datasets to gather real-world evidence.\nWhat is this article about? This study looked at how steroids, commonly used medications, can cause side effects in people with myasthenia gravis, a rare muscle-weakening condition. The researchers used a simplified tool called the Glucocorticoid Toxicity Index-Metabolic Domains (GTI-MD), which focuses on common health measures like body weight, blood pressure, blood sugar and cholesterol, to track these side effects using real-world health records. What were the results? The study included over 600 people with myasthenia gravis, comparing those who began steroid treatment with those who did not. People who used steroids showed greater increases in negative health effects over time, especially in body weight. Those who took higher doses or had multiple courses of steroids experienced more side effects. The simplified GTI-MD tool was sensitive enough to detect these changes using routine health data. What do the results mean? Why is this important? Steroid side effects can be serious and may go unnoticed without proper monitoring. This study shows that it is possible to track steroid toxicity using everyday medical data, helping doctors spot problems early and adjust treatments to reduce harm. The findings also suggest that people starting strong or repeated steroid treatments may need closer follow-up to manage risks. This approach could be used in other diseases where steroids are commonly prescribed.", "authors": ["Phillips Glenn", "Qi Cynthia", "Gelinas Deborah", "Stone Martha", "Chamberas Anthony", "Amirthaganesan Dakshinamoorthy", "Kulkarni Rucha", "Whangbo Albert", "Stone John H"], "journal": "Journal of comparative effectiveness research", "entry_date": "2026/05/08 08:23", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42101054/", "pub_types": ["Journal Article"], "affiliations": ["argenx BVBA, Ghent, Belgium."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "3区"}, {"pmid": "42099932", "title": "Construction of patient trajectories to model clinical trial outcomes: application to myasthenia gravis.", "abstract": "INTRODUCTION: Accurate prediction of patient outcomes in clinical trials is crucial for the timely assessment of treatment efficacy. This study proposes a novel approach to predict patient response using longitudinal clinical data.\nMETHODS: We construct temporal trajectories from longitudinal data and extrapolate these trajectories to forecast individual patient outcomes. Additionally, we assess when new patients align with established response patterns. The approach is evaluated using data from the MGTX trial involving patients with myasthenia gravis.\nRESULTS: Our analysis demonstrates the predictability of patient trajectories and enables automatic clustering of patients based on treatment success. The clustering reveals potential associations with age and smoking status.\nDISCUSSION: These findings highlight the potential of trajectory-based methods for early prediction of treatment response in clinical trials. We also discuss possible confounding factors that may influence the observed associations and predictive performance.", "authors": ["Garbey Marc", "Lesport Quentin", "Kaminski Henry J"], "journal": "Frontiers in digital health", "entry_date": "2026/05/08 05:00", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42099932/", "pub_types": ["Journal Article"], "affiliations": ["Care Constitution Corp, Houston, TX, United States."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.8, "journal_quartile": "2区"}, {"pmid": "42096038", "title": "Effectiveness and safety of efgartigimod in myasthenia gravis: A meta-analysis of different antibody subtypes.", "abstract": "OBJECTIVE: To assess the effectiveness and safety of intravenous efgartigimod in patients with myasthenia gravis (MG) and to compare treatment responses between anti-acetylcholine receptor antibody (AChR-Ab)-positive and -negative subtypes.\nMETHODS: A comprehensive search was conducted in the PubMed, Scopus, Web of Science, and Cochrane CENTRAL databases up to 15 October 2025. Clinical trials and cohort studies evaluating the effectiveness and safety of efgartigimod in patients with MG were included. A random-effects model was used to pool mean differences (MDs) for continuous outcomes and proportions for categorical outcomes, with corresponding 95% confidence intervals (CIs). Subgroup analyses were performed based on study design and MG subtype.\nRESULTS: Twenty-nine studies (1594 patients) were included. Overall, 83% of patients achieved clinically meaningful improvement (CMI; ≥ 2-point reduction in MG Activities of Daily Living [MG-ADL] score), and 36% achieved minimal symptom expression (MSE; MG-ADL score of 0 or 1) with no significant difference between AChR-Ab-positive and AChR-Ab-negative subtypes. MG-ADL score significantly decreased from baseline (MD: -4.3 points, 95% CI: -4.99 to -3.61), with no difference between the MG subtypes. Quantitative MG score (QMG; MD: -3.6 points, 95% CI: -4.28 to -2.91), MG Quality of Life 15-item revised scale (MG-QoL15r), IgG levels, and corticosteroid use showed significant reductions in the AChR-Ab-positive subtype; however, these outcomes were not reported in the AChR-Ab-negative subtype. Serious adverse events were reported in 4.42% of patients.\nCONCLUSION: Efgartigimod significantly improved clinical symptoms and quality of life in patients with MG and may offer a steroid-sparing effect, with no significant differences observed between subtypes.", "authors": ["Sabet Haneen", "AbuHamdia Abrar", "Zanaty Mohamed Ahmed", "El-Moslemani Mohamed", "Ewis Dalia Kamal", "Elyamany Ziyad", "Khatatbeh Abdallah", "Almarfadi Abdullah", "Al-Rayess Hala", "Altalab Gergis", "Aldehri Majed", "Al-Fawzan Foziah F", "Shaban E A", "Abbas Abdallah"], "journal": "Immunologic research", "entry_date": "2026/05/07 11:09", "pub_date": "2026-05-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42096038/", "pub_types": ["Journal Article", "Meta-Analysis"], "affiliations": ["Faculty of Medicine, South Valley University, Qena, Egypt. haninsabet225@gmail.com."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.1, "journal_quartile": "4区"}, {"pmid": "42091851", "title": "Predictive Factors for Non-response to First Use of Polyvalent Intravenous Immunoglobulin in Generalised Myasthenia Gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune neurological disorder affecting the neuromuscular junction. Rapid clinical deterioration during a myasthenic crisis (MC) or severe exacerbation may be life-threatening due to respiratory or bulbar involvement. Plasma exchange (PLEX) and intravenous immunoglobulin (IVIg) are two rescue therapies that show comparable efficacy in this setting. However, the characteristics of patients who respond poorly to IVIg remain insufficiently described. The aim of this study was to identify predictive factors of non-response to IVIg administered during a first MC or exacerbation.\nMETHODS: This was a single-centre retrospective cohort study carried out at a French referral centre for neuromuscular diseases between 2017 and 2023. Adult patients with generalised MG experiencing a first MC or exacerbation and treated for the first time with IVIg were included in the study. Data on clinical, laboratory, electrophysiological and therapeutic variables were collected. Treatment response was defined as the maximum gain in Garches clinical score following IVIg, adjusted for baseline score.\nRESULTS: A total of 93 were included in the study. The median age of the cohort was 68 (interquartile range [IQR] 49-76) years, and the median delay from diagnosis was 0.7 years. The median baseline Garches score was 66/100 (IQR 55-75) points, which improved to 85/100 (IQR 75-94) points after treatment. Bulbar involvement was significantly associated with a greater response to IVIg.\nCONCLUSIONS: In this large and heterogeneous cohort, IVIg demonstrated consistent efficacy without identification of significant predictors of non-response. These findings support IVIg as a reliable and evidence-based first-line therapy for patients with MG experiencing exacerbation or MC.", "authors": ["Dion Matthias", "Gavoille Antoine", "Chamouard Valérie", "Pegat Antoine", "Bouhour Françoise"], "journal": "Neurology and therapy", "entry_date": "2026/05/06 23:24", "pub_date": "2026-05-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42091851/", "pub_types": ["Journal Article"], "affiliations": ["Service ENMG et de Pathologies Neuromusculaires, Centre de Référence des Maladies Neuromusculaires PACA-Réunion-Rhône Alpes, Hôpital Neurologique P. Wertheimer-Hospices Civils de Lyon, 59 boulevard Pinel, 69500, Bron, France. mat.dion@sfr.fr."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "42091015", "title": "Immune-related markers define clinically relevant prognostic subgroups in thymic epithelial tumors.", "abstract": "BACKGROUND: Characterizing the immune landscape of thymic epithelial tumors (TETs) is essential for patient stratification for emerging immunotherapeutic approaches and for optimizing follow-up strategies. In this study, we examined the expression patterns and clinical significance of five immune-related markers in a large cohort of TETs.\nMATERIAL AND METHODS: Expression of TIM3, OX40L, GTF2I, XPO1, and GITR was assessed by immunohistochemistry (IHC) in the epithelial and lymphocytic compartments of 137 surgically resected TETs and correlated with clinicopathological parameters and patient outcomes. Tumors were grouped according to their immune profile using cluster analysis.\nRESULTS: TIM3, GTF2I, and XPO1 showed high and consistent expression in the epithelial compartment of TETs across histological subgroups, whereas GITR expression was mostly absent. In the lymphocytic compartment, only XPO1 was highly expressed, with no significant differences between TET subtypes. Epithelial and lymphocytic OX40L expressions were significantly higher in patients with myasthenia gravis (vs. those without this autoimmune disorder; p = 0.004 and p = 0.045, respectively). Importantly, hierarchical clustering identified four distinct TET subgroups based on their combined immune marker expression profiles, which displayed widely divergent survival outcomes (p < 0.0001). Among these, the subgroup characterized by elevated epithelial expression of GTF2I, XPO1, and TIM3 showed worse survival in our multivariate model (HR 6.37; p = 0.025).\nCONCLUSIONS: TIM3, GTF2I, and XPO1 are highly expressed in the epithelial compartment of TETs, providing a rationale for therapeutic targeting in future immunotherapy trials. Differential IHC expression of TIM3, OX40L, GTF2I, XPO1, and GITR defines distinct TET subtypes with independent prognostic relevance, enabling more accurate risk assessment in these highly heterogeneous thoracic malignancies.", "authors": ["Megyesfalvi Evelyn", "Teglas Vivien", "Ferencz Bence", "Pipek Orsolya", "Pozonec Maria Dorothea", "Lippai Zoltan", "Revi Barnabas", "Nagy Kristof", "Horvath Lilla", "Ferenczy Anita", "Izso David", "Radeczky Peter", "Fillinger Janos", "Bogos Krisztina", "Laszlo Viktoria", "Schelch Karin", "Moser Bernhard", "Aigner Clemens", "Hegedus Balazs", "Renyi-Vamos Ferenc", "Dome Balazs", "Ghimessy Aron", "Megyesfalvi Zsolt"], "journal": "Lung cancer (Amsterdam, Netherlands)", "entry_date": "2026/05/06 18:09", "pub_date": "2026-04-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42091015/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic and Abdominal Tumors and Clinical Pharmacology, National Institute of Oncology, Budapest, Hungary; Department of Thoracic Surgery, Semmelweis University and National Institute of Oncology, Budapest, Hungary."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "42088710", "title": "Healthcare Professionals' Perspectives on Barriers and Facilitators in Care and Rehabilitation of Adults with Myasthenia Gravis in Neurological Departments in Denmark.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a rare, chronic autoimmune disease that causes various fluctuating symptoms. Healthcare professionals at neurological departments often focus on treating MG with the risk of overlooking other aspects of daily living. Rehabilitation seeks to enable people with disabilities to become as independent as possible in everyday activities. This study aims to explore how healthcare professionals at neurological departments perceive barriers and facilitators in care and rehabilitation of adults with MG in Denmark to target future rehabilitation initiatives.\nMETHODS/MATERIALS: A qualitative design using individual interviews with healthcare professionals employed at neurological departments was performed. The qualitative interpretive description methodology aimed at informing clinical practice and the critical psychology framework by Klaus Holzkamp guided the study. Ten participants were included.\nRESULTS: The results showed how \"Supporting patient understanding and navigation through personalized care\", \"Navigating responsibility and resources in clinical practice\", and \"Organizational structures impacting on professional quality of care\" were important areas for the healthcare professionals when considering barriers and facilitators to rehabilitation for their patients. The first two areas were the center of the participants' clinical practice, and surrounding and impacting on this center was the participants' perception of their ability to navigate responsibilities and resources in their clinical practice. The third area had significant impact on the quality of care, allocation of resources, and structural changes within the specialized healthcare services.\nCONCLUSION: Healthcare professionals at neurological departments experience multiple facilitators and barriers to the rehabilitation of adults with MG. Their agency potential is deeply rooted in the relational, organizational, and structural settings that they engage in. Their ability to support adults with MG in coping with their condition depends on expertise, flexibility, continuity, and interdisciplinary collaboration both in and outside their organization. It is pivotal that organizational structures support these conditions. If not, it may have negative consequences for the patients' agency potential, rehabilitation, and health.", "authors": ["Olesen Lene Klem", "Werlauff Ulla", "Missel Malene", "Schirakow Liselotte", "Handberg Charlotte"], "journal": "Journal of multidisciplinary healthcare", "entry_date": "2026/05/06 05:04", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42088710/", "pub_types": ["Journal Article"], "affiliations": ["Research and Development, National Rehabilitation Center for Neuromuscular Diseases, Aarhus, Denmark."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42084498", "title": "Effect of nipocalimab on IgG responses to vaccinations and viral infections in patients with IgG autoantibody-mediated diseases: Post hoc analyses of three randomized, placebo-controlled trials.", "abstract": "Nipocalimab is a neonatal Fc receptor (FcRn)-blocking monoclonal antibody approved for the treatment of generalized myasthenia gravis (gMG) and is being evaluated for other immunoglobulin G (IgG) autoantibody- or alloantibody-mediated diseases. Nipocalimab binds to FcRn with high specificity and affinity, eliciting increased clearance of IgG antibodies without affecting IgG production or other immune functions. However, nipocalimab's impact on vaccine responses in patients has not been previously reported. The effect of nipocalimab on pre-existing antibodies against tetanus toxoid (TT) and herpes zoster virus (HZV) vaccines as well as humoral responses to TT vaccines, severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) vaccines, and SARS-CoV-2 infections was examined in post hoc analyses of data from three randomized, placebo-controlled trials in participants with gMG, rheumatoid arthritis, and Sjögren's disease. The levels of pre-existing anti-TT and anti-HZV IgG followed the kinetics of total IgG during nipocalimab treatment (60%-65% and 53%-68% IgG reduction, respectively) and returned to baseline after discontinuation. Nevertheless, the majority of nipocalimab-treated participants maintained pre-existing anti-HZV (66/90, 73.3% above ≥100 IU/L reference threshold) and anti-TT IgG levels (62/81, 76.5% ≥0.16 IU/mL protective threshold) throughout the study period. Participants treated with nipocalimab elicited positive IgG responses to TT and SARS-CoV-2 vaccination, similar to placebo-treated participants. SARS-CoV-2 infections during the studies were mild to moderate in severity with no complications. These results suggest that nipocalimab does not impair the development of humoral responses to vaccines or viral infections in patients with IgG autoantibody-mediated diseases.Trial registration number: NCT04951622, NCT04991753, NCT04968912.", "authors": ["Yu Faye", "Myshkin Eugene", "Nguyen Brandon", "Bobadilla Mendez Carolina", "Cossu Marta", "Fei Kaiyin", "Wang Qingmin", "Hubbard Jonathan J", "Campbell Kim", "Ramchandren Sindhu", "Rojo Cella Ricardo", "Edwards Robert", "Taylor Peter C", "Gottenberg Jacques-Eric", "Noaiseh Ghaith", "Vu Tuan", "Antozzi Carlo", "Winthrop Kevin L", "Cuff Carolyn A", "Loza Matthew J", "Dimitrova Dessislava", "Gao Sheng"], "journal": "Human vaccines & immunotherapeutics", "entry_date": "2026/05/05 09:53", "pub_date": "2026-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42084498/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Johnson & Johnson, Cambridge, MA, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "42083560", "title": "Topical pyridostigmine for ocular myasthenia gravis: a translational hypothesis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction predominantly mediated by antibodies that target the acetylcholine receptors in the skeletal muscles. Ocular involvement of the levator palpebrae superioris and extraocular muscles is common, resulting in ptosis and diplopia. Oral pyridostigmine, an acetylcholinesterase, is typically the first-line therapy, but its administration is frequently limited by systemic cholinergic adverse effects and inconsistent relief of ocular symptoms.\nHYPOTHESIS: We hypothesize that pyridostigmine can be reformulated as a topical ocular/periocular formulation to directly enhance the neuromuscular transmission of the levator palpebrae superioris and extraocular muscles, thereby improving ptosis and strabismus while minimizing systemic side effects. The levator palpebrae superioris and extraocular muscles underlie the conjunctiva. Pyridostigmine bromide is a small, hydrophilic quaternary ammonium compound with topical application properties that favor conjunctival permeability while limiting transcorneal penetration. Its formulation pH closely approximates that of conjunctival tissue. Clinical precedent from alpha-adrenergic eye drops (e.g., apraclonidine) that elevate the eyelid via Müller's muscle support the plausibility of a topical approach. Although limited residence time on the ocular surface is a potential barrier, advances in delivery systems, including hydrogels, nanoparticles, and ionic liquids, may enhance retention and conjunctival penetration. Periocular transdermal delivery may further exploit the thin periocular skin to achieve localized vascular access. Based on the pharmacological mechanism of acetylcholinesterase inhibition, we propose that ex vivo animal model ocular permeability and tissue integrity be examined to determine the feasibility of topical pyridostigmine formulation providing effective localized neuromuscular transmission enhancement in patients with ocular MG.\nCONCLUSIONS: If preliminary ex vivo animal model observations find that topical pyridostigmine formulations are stable with appropriate conjunctival penetration and preserved epithelial integrity, it would support progression to in vivo animal studies and translational modelling. The feasibility of topical or periocular pyridostigmine as a localized treatment strategy for ocular MG deserves further investigation. If validated, this approach could shift management toward targeted, better-tolerated topical therapies with reduced systemic risk.", "authors": ["Ing Edsel B", "Lim Kate", "Davies Neal M", "Lobenberg Raimar", "Harunur Rashid Md", "Le Tyson S", "Rullo Jacob"], "journal": "Medical hypothesis, discovery & innovation ophthalmology journal", "entry_date": "2026/05/05 03:35", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42083560/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology and Visual Sciences, University of Alberta, Edmonton, Canada."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null}, {"pmid": "42081930", "title": "Exploring the role of circulating glial fibrillary acidic protein and neurofilament light chain in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction caused by antibodies against the acetylcholine receptor (AChR) or muscle-specific kinase (MuSK). Although these antibodies enable diagnosis, they correlate poorly with disease activity and prognosis. Emerging data suggest that MG involves broader neuroimmune mechanisms beyond the peripheral synapse. Glial fibrillary acidic protein (GFAP), a marker of astroglial activation, and neurofilament light chain (NfL), a marker of neuroaxonal injury, have been proposed as circulating biomarkers in several neurological diseases. This study aimed to evaluate serum GFAP and NfL concentrations in MG patients and to assess its potential diagnostic utility.\nMETHODS: In this retrospective case-control study, 137 patients with confirmed MG and 338 healthy controls were enrolled. Clinical classification followed MGFA criteria. Anti-AChR and anti-MuSK antibodies were measured by ELISA. Serum GFAP and NfL concentrations were quantified using a fully automated chemiluminescent immunoassay (Lumipulse G1200). Group comparisons were performed using non-parametric tests, correlations using Spearman analysis, and independent determinants assessed with multivariable linear regression. Receiver operating characteristic (ROC) curve analysis was performed to evaluate diagnostic performance.\nRESULTS: Serum GFAP concentrations were higher in MG patients than controls (44.6 vs 29.6 pg/mL) and strongly correlated with age (r = 0.64, p < 0.0001), but not with antibody titers. In multivariable regression, age was the main independent determinant of GFAP (β = 0.00827, p < 0.0001), whereas MG status was not. GFAP showed moderate diagnostic performance (AUC = 0.704). In an age- and sex-matched analysis, NfL concentrations were modestly higher in MG patients compared with controls (30.2 vs 15.5 pg/mL; p = 0.047). A moderate positive correlation between GFAP and NfL was observed in both groups.\nCONCLUSIONS: Circulating GFAP levels are elevated in MG but are primarily driven by age and sex rather than disease-specific mechanisms, limiting their diagnostic utility. NfL shows a modest increase, suggesting subtle neuroaxonal involvement; however, its clinical relevance remains uncertain. Together, these findings indicate that GFAP and NfL reflect non-specific neurobiological processes rather than robust biomarkers of MG.", "authors": ["Gambino Caterina Maria", "Agnello Luisa", "Scazzone Concetta", "Tamburello Martina", "Masucci Anna", "Vassallo Roberta", "Di Stefano Vincenzo", "Brighina Filippo", "Ciaccio Marcello"], "journal": "Clinica chimica acta; international journal of clinical chemistry", "entry_date": "2026/05/04 19:11", "pub_date": "2026-05-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42081930/", "pub_types": ["Journal Article"], "affiliations": ["Institute of Clinical Biochemistry, Clinical Molecular Medicine, and Clinical Laboratory Medicine, Department of Biomedicine, Neurosciences, and Advanced Diagnostics, University of Palermo, 90127 Palermo, Italy; Department of Laboratory Medicine, University Hospital \"Paolo Giaccone\", 90127 Palermo, Italy."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "42078791", "title": "Diagnostic Challenges of LRP4 Antibody Testing in Myasthenia Gravis: A Case Series of Four LRP4 Positive Cases With Uncertain Diagnostic Significance.", "abstract": "Myasthenia gravis is an autoimmune disorder characterized by muscle weakness due to impaired neuromuscular transmission. While antibodies against the acetylcholine receptor and muscle-specific kinase are commonly used for diagnosis, a subset of patients remains seronegative, necessitating alternative biomarkers. Low-density lipoprotein receptor-related Protein 4 antibodies have emerged as a potential diagnostic marker in seronegative myasthenia gravis cases. However, misleading positive results have obscured diagnosis and management. This study explores the clinical relevance of low-density lipoprotein receptor-related Protein 4 antibodies in myasthenia gravis through four patient case studies. Patients presenting with concern for myasthenia gravis underwent a comprehensive diagnostic evaluation, including antibody testing for acetylcholine receptor, muscle-specific kinase, and low-density lipoprotein receptor-related Protein 4. Volitional single-fiber electromyography was also performed. All tests were employed per standardized laboratory protocols. All four patients were initially evaluated for suspected myasthenia gravis; however, despite positive low-density lipoprotein receptor-related Protein 4 antibody results, comprehensive clinical and electrophysiological evaluation ultimately excluded the diagnosis of myasthenia gravis. These cases underscore the limitations of low-density lipoprotein receptor-related Protein 4 antibody testing.", "authors": ["Kinnard Katherine Rosella", "Khalid Ehtesham"], "journal": "Case reports in neurological medicine", "entry_date": "2026/05/04 06:28", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42078791/", "pub_types": ["Journal Article"], "affiliations": ["Ochsner Medical Center, New Orleans, Louisiana, USA, ochsner.org."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "42074613", "title": "Thrombosis in Neuromuscular Medicine: Current Evidence, Unmet Needs, and Future Directions.", "abstract": "Venous thromboembolism (VTE), comprising deep vein thrombosis and pulmonary embolism, is an important but under-recognised complication in neuromuscular diseases. In adults, emerging epidemiological data suggests increased VTE occurrence in conditions such as Amyotrophic Lateral Sclerosis, myotonic dystrophy, myasthenia gravis, inflammatory neuropathies, inflammatory myopathies, and POEMS syndrome. This heightened risk reflects not only disease-related immobility but also disorder-specific biological mechanisms, including inflammation, endothelial dysfunction and cardiomyopathy-related stasis. Therapies such as corticosteroids, IVIG-related hyperviscosity, long-term central venous access, perioperative immobility, critical illness, and complex orthopaedic procedures have prothrombotic effects. Despite this multifactorial risk profile, disease-specific guidance for thromboprophylaxis is lacking, and current practice relies heavily on extrapolation from general medical and surgical recommendations rather than data derived from neuromuscular cohorts. In children and adolescents, the VTE burden is less well-characterised, but events have been reported in Duchenne and Becker muscular dystrophy, congenital myopathies, and spinal muscular atrophy particularly with advanced motor impairment, severe cardiomyopathy, ventilatory insufficiency, and prolonged hospitalisation. Beyond venous events, selected neuromuscular disorders also exhibit increased arterial thrombosis risk. Myotonic dystrophy and dystrophinopathies are associated with cardiomyopathy and arrhythmia that predispose to systemic embolism and stroke, while inflammatory myopathies may demonstrate arterial events related to vasculitic or endothelial processes, although overall evidence remains limited. This review summarises available empirical and epidemiological evidence on venous and arterial thrombosis across adult and paediatric neuromuscular disorders, outlines disease-specific mechanistic pathways, examines treatment-related contributors, and highlights key evidence gaps that must be addressed to guide rational and targeted prophylaxis strategies in this complex, heterogeneous population.", "authors": ["Quak Zhi Xuan", "Wang Furene", "Tay Stacey K H", "Koh Pei Lin", "Yap Eng Soo", "Ng Kay Wei Ping"], "journal": "Journal of clinical medicine", "entry_date": "2026/05/04 01:15", "pub_date": "2026-04-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42074613/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Division of Neurology, Department of Medicine, National University Hospital, Singapore 119074, Singapore."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "42072999", "title": "Physical Exercise in Myasthenia Gravis: A Systematic Review.", "abstract": "Background: Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by fluctuating skeletal muscle weakness and fatigue, leading to reduced functional independence and impaired quality of life (QoL). Although exercise has historically been discouraged due to concerns about symptom exacerbation, emerging evidence suggest that structured exercise programs may be safe and beneficial in clinically stable patients. This systematic review critically evaluates current evidence on exercise and physical activity interventions in MG, focusing on effectiveness, safety, and impact on functional outcomes, fatigue, and QoL. Materials and Methods: A systematic review was conducted following PRISMA guidelines. Searches were performed in PubMed, Web of Science, Google Scholar, Scopus and ScienceDirect for studies published between 2015 and 2025. Keywords included MG, physical activity, aerobic training, resistance training, and respiratory muscle training. Methodological quality was assessed using the Downs and Black checklist. Results: Eight controlled studies met the inclusion criteria, encompassing aerobic, resistance, combined, and respiratory muscle training interventions. Sample sizes ranged from small pilot studies to moderate-size randomized controlled trials. Overall, exercise interventions were well tolerated, with no evidence of sustained symptoms exacerbation. Aerobic and combined programs consistently improved functional capacity, muscle strength, and activities of daily living. Respiratory muscle training demonstrated improvements in pulmonary function and inspiratory muscle strength, although findings were more heterogeneous. Study quality ranged from poor to excellent, with common limitations including small sample size, short follow-up duration, and heterogeneity in exercise programs. Conclusions: Current evidence supports the safety and potential efficacy of individualized, symptom-guided exercise interventions in clinically stable MG. Regular physical activity exercise may reduce secondary deconditioning, improve functional outcomes, and enhance QoL. However, larger, high-quality randomized controlled trials with standardized programs and longer follow-up periods are required to strengthen clinical recommendations and clarify long-term effects.", "authors": ["Vinciguerra Claudia", "Leale Ignazio", "Rini Nicasio", "Orlando Fabio Tiziano", "Bevilacqua Liliana", "Barone Paolo", "Brighina Filippo", "Di Stefano Vincenzo", "Battaglia Giuseppe"], "journal": "Healthcare (Basel, Switzerland)", "entry_date": "2026/05/04 01:09", "pub_date": "2026-04-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42072999/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurology Unit, Department of Medicine, Surgery and Dentistry \"Scuola Medica Salernitana\", University Hospital San Giovanni di Dio e Ruggi d'Aragona, 84131 Salerno, Italy."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.4, "journal_quartile": "4区"}, {"pmid": "42070450", "title": "Depressive symptoms, but not OSA severity, are associated with general fatigue in myasthenia gravis.", "abstract": "BACKGROUND: General fatigue is a common and disabling symptom in myasthenia gravis (MG), distinct from muscle fatigability, and often associated with impaired quality of life. Sleep-disordered breathing, particularly obstructive sleep apnea (OSA), has been proposed as a potential contributor, but evidence in MG remains limited and inconsistent.\nMETHODS: We conducted a prospective observational study of clinically stable MG patients recruited from two neuromuscular clinics in Toronto, Canada (April 2022-February 2023). Participants completed validated questionnaires assessing fatigue (Neuro-QoL, MFIS), sleep quality (PSQI), daytime sleepiness (ESS), depression (BDI), and MG symptom severity (MGII), and performed a 10-min psychomotor vigilance task (PVT). Home sleep apnea testing (HSAT) was performed over two nights using the MediByte device, with indices including apnea-hypopnea index (AHI), oxygen desaturation index (ODI), mean SpO2, and percent time below 90% oxygen saturation (T90%). Separate linear regression models examined associations between each predictor and fatigue, separately adjusting for age, sex, or BMI. Partial rank-order Spearman correlations adjusting for age, sex, and BMI were performed. Additional analyses further adjusted for AHI (alongside age, sex, and BMI) when examining the relationship between depression and fatigue and similarly, when examining the relationship between AHI and fatigue, we adjusted for depression, age, sex, and BMI.\nRESULTS: Of 66 approached patients, 25 were enrolled with complete HSAT data. The mean age was 62.2 ± 14.5 years, 40% were female, and median BMI was 26.5 [23.3, 31.4] kg/m2. OSA severity indices (AHI, ODI, mean SpO2, T90%) were not significantly associated with Neuro-QoL or MFIS fatigue scores. Depression (BDI) was consistently associated with greater fatigue across all models (p < 0.001). MG symptom severity (MGII) and PVT performance showed selective associations with fatigue depending on the scale used.\nCONCLUSION: In this cohort, general fatigue in MG was not statistically associated with OSA-related variables, nor with other sleep parameters. However, these findings should be interpreted as an absence of detected association rather than evidence of no relationship. Conversely, depressive symptoms demonstrated consistent associations with fatigue scales, perhaps highlighting an importance for screening in MG patients. However, given the cross-sectional nature of this study, longitudinal studies are needed to clarify causal relationships amongst these variables. Given the modest sample size, risk of Type II error, and use of HSAT (which may not capture the full spectrum of sleep-disordered breathing) these results should be interpreted as hypothesis-generating.", "authors": ["Tchoudnovski Dennis", "Yang Donna", "Ntale Ivan", "Xie Henry", "Zinman Lorne", "Izenberg Aaron", "Choi Stephen", "Abrahao Agessandro", "Katzberg Hans", "Boulos Mark I"], "journal": "Sleep medicine", "entry_date": "2026/05/03 18:04", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42070450/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Hurvitz Brain Sciences Research Program, Sunnybrook Research Institute, Sunnybrook Health, Sciences Centre, Wellness Way, Toronto, Ontario, M4N 3M5, Canada; Undergraduate MD Program, University of Toronto, 27 King's College Cir, Toronto, Ontario, M5S 1A1, Canada."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "42070048", "title": "Untargeted serum metabolomic profiling in patients with generalized and ocular Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia Gravis (MG) is divided into ocular (OMG) and generalized (GMG) subtypes. While clinical diagnosis is well-established, understanding the underlying biochemical mechanisms and metabolic shifts during disease progression remains challenging; untargeted metabolomics offers a novel perspective to explore these systemic alterations.\nOBJECTIVE: To characterize the serum metabolic landscape of MG patients and identify potential metabolic signatures associated with disease subtypes (OMG and GMG) via untargeted metabolomics.\nMETHODS: 91 participants (41 GMG, 22 OMG, 28 healthy controls [HC]) were enrolled. Fasting serum samples were analyzed by LC-MS/MS. Multivariate analyses (PCA, PLS-DA/OPLS-DA), differential metabolite screening (VIP > 1.0, p < 0.05), and KEGG pathway enrichment were performed.\nRESULTS: HC and MG groups showed distinct metabolic profiles. MG had 515 (175 up, 340 down) and 368 (146 up, 222 down) differential metabolites in positive/negative ion modes, respectively. Key perturbed pathways included glycerophospholipid, sphingolipid metabolism, and unsaturated fatty acid biosynthesis. Ten representative metabolites (e.g., ubiquinone, cortisol) differed significantly among groups; clustering analysis revealed distinct metabolite abundance trajectories across HC, OMG, and GMG.\nCONCLUSION: MG is associated with notable systemic metabolic dysregulation, particularly in lipid-related pathways. Rather than serving as immediate diagnostic tools, these integrative metabolic signatures provide a crucial biochemical framework for understanding disease pathogenesis and offer valuable clues for future hypothesis-driven research and prospective validation.", "authors": ["Wei Bin", "Yuan Haoyu", "He Jiawei", "Hu Yuxiang", "Li Jing", "Wu Xiaorong"], "journal": "BMC ophthalmology", "entry_date": "2026/05/02 23:28", "pub_date": "2026-05-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42070048/", "pub_types": ["Journal Article"], "affiliations": ["The 1st Affiliated Hospital, Jiangxi Medical College, Nanchang University, Nanchang, Jiangxi, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "42069815", "title": "Phase 1 dose-finding study of topical neostigmine ophthalmic solution for alleviating myasthenic ptosis.", "abstract": "The study aimed to investigate the safety, optimal biologic dose, and preliminary efficacy of topical neostigmine ophthalmic solution (TNOS) in myasthenia gravis (MG) patients with ptosis. A dose-escalation study comprising cohorts of three patients in each step was performed. The first cohort received 1.5 mg/mL TNOS and was evaluated for safety and efficacy. Then, the subsequent cohorts received the selected dose of TNOS according to the safety and efficacy protocols to determine the optimal biologic dose. Vital signs, visual acuity, intraocular pressure, pupillary size, slit-lamp examinations, and abnormal ocular symptoms were recorded as safety measures. Vertical palpebral fissure and self-reported alleviation of ptosis were investigated as efficacy measures. No systemic or ocular adverse effects were observed in any participant. Vertical palpebral fissure increased by more than 2 mm in 83.3% and 33.3% of patients receiving 1.5 and 1.0 mg/mL TNOS, respectively. The 1.5 mg/mL TNOS significantly increased vertical palpebral fissure from baseline (maximal mean difference 3.30 mm; 95% confidence interval 2.32 to 4.27; p < 0.001). All participants in the 1.5 mg/mL group and 33.3% in the 1.0 mg/mL group reported ptosis alleviation. The 1.5 mg/mL TNOS was considered the optimal biologic dose for alleviating myasthenic ptosis without adverse events.", "authors": ["Ongprakobkul Chuthamas", "Apinyawasisuk Supanut", "Jariyakosol Supharat", "Chariyavilaskul Pajaree", "Meesilpavikkai Kornvalee", "Chongpison Yuda"], "journal": "Scientific reports", "entry_date": "2026/05/02 23:22", "pub_date": "2026-05-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42069815/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, Faculty of Medicine, Chulalongkorn University, 1873 Rama 4 Road, Pathum Wan, Bangkok, 10330, Thailand."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "42064058", "title": "Thymoma-associated anti-AMPAR encephalitis with myasthenia gravis: a case report.", "abstract": "BACKGROUND: Thymoma can trigger a spectrum of paraneoplastic neurological disorders, including autoimmune encephalitis (AE) and myasthenia gravis (MG). However, the sequential development of anti-α-amino-3-hydroxy-5-methyl-4-isoxazole-propionic acid receptor (AMPAR) autoimmune encephalitis followed by MG in the same patient is rarely reported.\nOBJECTIVE: To describe the clinical presentation, diagnostic work-up, treatment response, and outcome of a patient who developed thymoma-associated anti-AMPAR encephalitis and later presented with MG.\nMETHODS: We retrospectively reviewed the medical records, imaging findings, laboratory results, and treatment course of a 49-year-old man who was evaluated at our institution. Serum and cerebrospinal fluid (CSF) autoantibodies were screened using cell-based assays and indirect immunofluorescence.\nRESULTS: The patient initially presented with subacute cognitive decline, confusion, and behavioral changes. CSF analysis revealed mild lymphocytic pleocytosis. Anti-AMPAR antibodies were positive in both serum and CSF, and contrast-enhanced chest computed tomography (CT) scan showed an anterior mediastinal mass consistent with thymoma. High-dose intravenous methylprednisolone followed by tapering oral prednisone, plasma exchange (PE), and intravenous immunoglobulin (IVIG) and rituximab led to marked neurological improvement. Two months after discharge, he developed left-sided ptosis, diplopia, and dyspnea. Repetitive nerve stimulation showed a decremental response, and serology was positive for acetylcholine receptor (AChR), titin, and ryanodine receptor (RyR) antibodies, establishing the diagnosis of MG. Symptoms improved substantially with prednisone and tacrolimus, and subsequent thymectomy combined with efgartigimod further achieved sustained clinical remission.\nCONCLUSIONS: This case illustrates that patients with anti-AMPAR encephalitis should be closely monitored for the subsequent emergence of MG, particularly when an underlying thymoma is present. Comprehensive antibody profiling is essential for early recognition and targeted immunotherapy. Long-term immunosuppression combined with tumor-directed treatment may be required to prevent relapses of both disorders and achieve optimal clinical outcomes.", "authors": ["Teng Wenbin", "Wei Fuzan", "Zhang Guiqiang", "Zhou Shaodan", "Hu Ruiting"], "journal": "Frontiers in immunology", "entry_date": "2026/05/01 05:10", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42064058/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, The Minzu Hospital of Guangxi Zhuang Autonomous Region, Nanning, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42053690", "title": "When treatment becomes a challenge: myasthenia gravis in a patient with Meige syndrome.", "abstract": "", "authors": ["Geçer Burak", "Bilen Şule"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/04/29 11:06", "pub_date": "2026-04-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42053690/", "pub_types": ["Letter"], "affiliations": ["Department of Neurology, Ankara Bilkent City Hospital, Ankara, Turkey. dr.burakgecer@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42053191", "title": "Retrospective Evaluation of Dual Specialty Ports in Therapeutic Apheresis.", "abstract": "Dual specialty ports were evaluated for safety and efficacy in therapeutic apheresis by analyzing outcomes across 97 port placement events in 88 patients, focusing on two configurations: dual Bard PowerFlow (BP2) and a combination of Bard PowerFlow with AngioDynamics SmartPort (BP + AD). This retrospective cohort study was conducted at a tertiary care center from December 2017 to July 2024 and included 97 port placement events (194 total ports) across 88 patients with conditions such as bronchiolitis obliterans, sickle cell disease, myasthenia gravis, and graft-versus-host disease who required therapeutic apheresis. Measured outcomes included port revisions, removals, total port days, and complications. The BP2 configuration was used in 43 events (44.3%), and the BP + AD configuration in 54 events (55.7%). Common indications included bronchiolitis obliterans (40.2%), sickle cell disease (17.5%), myasthenia gravis (12.4%), and GVHD (12.4%). Revisions were necessary in 5.7% of ports due to mechanical issues or thrombosis, while 36.1% of ports were removed, mainly due to infection/bacteremia or completion of therapy. Port functionality ranged from 22 to 2080 days, with a mean of 564 days. The mortality rate during follow-up was 21.6%. Dual specialty ports demonstrate viable long-term access for therapeutic apheresis in selected patients, with functionality extending from months to years. Success appears highly dependent on patient selection, with infection risks particularly notable in immunocompromised populations. These findings support the use of specialty ports as an alternative to traditional tunneled catheters, particularly for those with preserved immune function requiring chronic therapy.", "authors": ["Swar-Eldahab Mugtaba", "Obeng-Gyasi Barnabas", "Haste Paul", "Krosin Matthew"], "journal": "Journal of clinical apheresis", "entry_date": "2026/04/29 08:24", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42053191/", "pub_types": ["Journal Article"], "affiliations": ["Department of Radiology and Imaging Sciences, Indiana University School of Medicine, Indianapolis, Indiana, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "4区"}, {"pmid": "42053006", "title": "Lambert-Eaton Myasthenic Syndrome During Immunotherapy in Extensive-Stage Small-Cell Lung Cancer: A Case Report.", "abstract": "AIMS/BACKGROUND: Lambert-Eaton myasthenic syndrome (LEMS) is a rare autoimmune disorder of the neuromuscular junction that is frequently associated with small-cell lung cancer (SCLC). It is characterized by proximal muscle weakness, reduced deep tendon reflexes, and autonomic symptoms, all of which can significantly impair quality of life and complicate oncologic management. Early recognition and timely intervention are crucial to improving clinical outcomes.\nCASE PRESENTATION: We report a case of a 76-year-old man with extensive-stage SCLC and chronic renal insufficiency whose LEMS worsened during durvalumab immunotherapy. Despite continued chemotherapy and immunotherapy, his symptoms progressively worsened. Chemotherapy failed to improve his neurological condition, with subsequent recurrent episodes of muscle weakness. Subsequent administration of intravenous immunoglobulin (IVIG) combined with pyridostigmine led to marked neurological improvement and restoration of muscle strength to grade 5, enabling continuation of antitumor therapy. The patient subsequently received three cycles of second-line lurbinectedin chemotherapy, during which inflammatory responses, anemia, and venous thrombosis developed but were effectively managed with supportive treatment.\nRESULTS: Following chemotherapy and immunotherapy, the patient's limb muscle strength recovered to grade 5, followed by recurrent muscle weakness symptoms. Hematologic and biochemical parameters gradually normalized, and inflammatory markers returned to baseline. At discharge, his clinical condition was stable.\nCONCLUSION: This case highlights the importance of early recognition and standardized management of paraneoplastic LEMS in enhancing functional recovery and enabling the safe continuation of antitumor therapy.", "authors": ["Feng Yunyin", "Yang Yan", "Ding Liren"], "journal": "British journal of hospital medicine (London, England : 2005)", "entry_date": "2026/04/29 06:33", "pub_date": "2026-04-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42053006/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Respiratory Medicine, Kaihua County Traditional Chinese Medicine Hospital, 324300 Quzhou, Zhejiang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "42052862", "title": "Immune checkpoint inhibitor cardiomyotoxicity: a case series of five patients and development of a clinical management algorithm.", "abstract": "Immune checkpoint inhibitor (ICI) therapies have revolutionised the management of a range of malignancies. However, the syndrome of ICI induced cardiomyotoxicity, also reported as triple \"M\" syndrome (myasthenia gravis, myositis and myocarditis) is an unfortunate severe consequence in up to 1%-2% of patients receiving ICI, with an associated mortality of up to 50%. Based on international evidence and local experience, we have developed a clinical pathway in our institution as a guide to the early identification and targeted management of this condition.", "authors": ["Xie S Z", "Salem J E", "Nagrial A", "Menzies A", "Thomas L", "Ramanathan S", "Berglund L J", "Sasson S C", "Grey A C", "Habib R", "Wong M", "Carlino M S", "Jeffrey B", "Mo J", "Lin M W"], "journal": "Internal medicine journal", "entry_date": "2026/04/29 05:43", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42052862/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Clinical Immunology and Immunopathology, ICPMR, Westmead Hospital, Sydney, New South Wales, Australia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "42051486", "title": "Efficacy and safety of efgartigimod in very-late-onset myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disease. Recently, the prevalence of very late-onset MG (VLOMG; onset ≥ 65 years) has rapidly increased. The treatment of VLOMG groups is associated with several challenges, including multiple comorbidities, polypharmacy, and immunosenescence. Efgartigimod, which is the first approved neonatal Fc receptor (FcRN) antagonist, is reported to rapidly ameliorate MG symptoms with a favorable safety profile. Thus, efgartigimod is a potential novel therapeutic for VLOMG.\nOBJECTIVE: This study retrospectively analyzed the clinical data of patients with VLOMG treated with efgartigimod at our center over the past two years to assess its long-term efficacy and safety.\nMETHODS: This study retrospectively enrolled 62 patients with VLOMG who received at least one efgartigimod treatment cycle. The primary efficacy outcomes were the proportion of patients achieving minimum symptom expression (MSE) and the reduction in glucocorticoid dosage. The secondary efficacy outcomes were changes in Myasthenia Gravis-Activities of Daily Living (MG-ADL) scale scores, Quantitative Myasthenia Gravis (QMG) scale scores, Myasthenia Gravis Quality of Life 15-item revised (MG-QoL15r) scale scores, and scores of key muscle groups (ocular, bulbar, respiratory, axial, and limb muscles) relative to baseline.\nRESULTS: This study enrolled 62 eligible patients with VLOMG. Of these 62 patients, 37, 10, and 15 completed 1, 2, and ≥3 treatment cycles, respectively. The cumulative MSE achievement rate was 41.9% (26/62) by the end of the study. MG-ADL, QMG and MG-QoL15r scores after treatment were significantly reduced relatively to baseline in patients who underwent 1, 2, and ≥ 3 treatment cycles (all P < 0.001, P < 0.01, and P < 0.05, respectively). Subgroup analysis of muscle groups revealed that bulbar, limb (including axial), and ocular muscle function after treatment was significantly improved relatively to baseline in 37 patients (all P < 0.01). Limb (including axial) muscle function after treatment was significantly improved relatively to baseline in 15 patients (P < 0.05). Glucocorticoid dosage after treatment was significantly decreased relatively to baseline in patients who underwent 1, 2, and ≥ 3 treatment cycles (P < 0.0001, P < 0.05, P < 0.05, respectively). During treatment with efgartigimod, one patient developed an allergic rash, one patient experienced gastric discomfort, and two patients reported headache.\nCONCLUSION: This study demonstrated that efgartigimod effectively ameliorates symptoms and improves the quality of life in patients with VLOMG and enables short-term glucocorticoid dosage reduction. Thus, efgartigimod seems to be a safe and effective long-term therapeutic agent for VLOMG.", "authors": ["Zhao Yunbin", "Qu Meijie", "Rong Xi", "Sun Xupeng", "Wang Li", "Liu Min", "Sui Jiaona"], "journal": "Frontiers in immunology", "entry_date": "2026/04/29 04:46", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42051486/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Qingdao University, Qingdao, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "42048741", "title": "A novel circ_0018483/miR-4310/ERRFI1 ceRNA axis in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is one of the most prevalent disorder of the neuromuscular junction (NMJ). Non-coding RNAs regulate myoblast proliferation and differentiation.\nMETHODS: The differential expression of miRNAs was analysed by using RNA microarrays. Protein levels and gene expression were analysed by using Western blotting and quantitative real-time polymerase chain reaction. The interactions of miR-4310 with circ_0018483 or ERBB receptor feedback inhibitor 1 (ERRFI1) were assessed using dual-luciferase reporter assays. The expression and aggregation of acetylcholine receptors (AChRs) were observed and analysed by using immunofluorescence.\nRESULTS: The expression of miR-4310 was downregulated in the whole blood of patients. circ_0018483 exhibited a sponge effect on miR-4310, and the inhibition of miR-4310 weakened AChR function. Additionally, miR-4310 targeted ERRFI1 and circ_0018483, and circ_0018483 affected the expression and aggregation of AChR by regulating miR-4310 and ERRFI1. circ_0018483 regulates the expression of ERRFI1 by targeting miR-4310, which in turn affects AChR expression and aggregation at the NMJ.\nCONCLUSIONS: We confirmed a novel circ_0018483/miR-4310/ERRFI1 ceRNA axis in MG. Our findings suggest novel AChR regulation and MG molecular mechanisms research avenues.", "authors": ["Lv Jie", "Liu Jing", "Zhang Linyuan", "Zhang Yingna", "Zhang Jing", "Zhao Xue", "Yang Junhong", "Guo Wei", "Chen Shufan", "Sun Zhan", "Liu Ruichen", "Zhang Mengdi", "Liu Qian", "Zhou Xinyue", "Hu Jia", "Dong Haiyan", "Cui Xinxin", "Gao Qingye", "Gao Feng"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/28 18:02", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42048741/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42048329", "title": "Comparative study of ocular and generalized myasthenia gravis in a South Korean cohort.", "abstract": "PURPOSE: To compare ocular myasthenia gravis (OMG) and generalized myasthenia gravis (GMG) in a South Korean cohort through an integrated analysis of clinical characteristics, diagnostic findings, and treatment patterns.\nMETHODS: We conducted a retrospective study of 138 patients with myasthenia gravis (98 with OMG and 40 with GMG). Demographic characteristics, ophthalmic symptoms, serologic results, repetitive nerve stimulation test (RNST) findings, thymic pathology, autoimmune comorbidities, and treatment patterns were evaluated.\nRESULTS: GMG patients had a younger age at symptom onset and a higher proportion of females compared with OMG patients. Combined horizontal and vertical diplopia was more frequent in OMG. AChR antibody positivity was significantly higher in GMG than in OMG (92.5% vs. 36.3%), as were abnormal RNST findings (90.0% vs. 23.5%). A modest but statistically significant positive correlation was observed between AChR-Ab titer and the highest CMAP decrement in the overall cohort (r = 0.381, p = 0.011); however, this association was not significant when analyzed separately in OMG and GMG patients. Thymic abnormalities, particularly thymoma, were more common in GMG. Nonsteroidal immunosuppressant use-especially tacrolimus and azathioprine-was significantly more frequent in GMG, whereas corticosteroid use did not differ significantly between subtypes. Among OMG patients, systemic immunotherapy was more frequently administered to those presenting with both ptosis and diplopia than to those with isolated ptosis.\nCONCLUSIONS: In this South Korean cohort, OMG and GMG exhibited distinct demographic, serologic, electrophysiologic, and therapeutic profiles. Recognition of these subtype-specific differences may facilitate accurate diagnosis, individualized treatment selection, and improved clinical management.", "authors": ["Kwon Chaerin", "Oh Jeeyoung", "Shin Hyun Jin"], "journal": "PloS one", "entry_date": "2026/04/28 13:33", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42048329/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Graduate School of Medicine, Konkuk University, Seoul, Republic of Korea."], "china_related": false, "study_types": ["Non-randomized controlled cohort"], "evidence_level": "III", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "42047999", "title": "Myasthenia Gravis patients have reduced DTI-ALPS-Index and gBOLD-CSF coupling, suggesting impaired brain waste clearance.", "abstract": "", "authors": ["Zeng Jianxian", "Han Shuting", "Zhu Mengying", "Shang Yi", "Wu Peng", "Gu Qinghua", "Li Yonggang"], "journal": "Brain imaging and behavior", "entry_date": "2026/04/28 11:23", "pub_date": "2026-04-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42047999/", "pub_types": ["Journal Article"], "affiliations": ["Department of Radiology, The First Affiliated Hospital of Soochow University, Suzhou, 215006, Jiangsu, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "42046766", "title": "A Case of Myasthenia Gravis Diagnosed After Hospitalization in a Patient Receiving Home Oxygen Therapy for Respiratory Failure.", "abstract": "INTRODUCTION: Respiratory failure has various causes, including neuromuscular disorders. We report a case of myasthenic crisis requiring intensive care after a delayed diagnosis.\nCASE PRESENTATION: A woman in her 70s had been on home oxygen therapy for 10 months due to dyspnea. She was admitted with worsening dyspnea, type II respiratory failure, and pneumonia requiring mechanical ventilation. Although her pneumonia improved, ventilator weaning was unsuccessful. Muscle weakness raised suspicion of neuromuscular disease. Myasthenia gravis was a differential diagnosis, but she showed no thymoma, ocular symptoms, or abnormal findings on edrophonium or repetitive nerve stimulation tests. On Day 19, she tested positive for MuSK antibodies and myasthenia gravis was diagnosed. She was treated with prednisone, tacrolimus, intravenous immunoglobulin, and plasmapheresis. She was successfully weaned from mechanical ventilation and discharged home on hospital Day 81.\nCONCLUSION: Myasthenia gravis should be considered as a differential diagnosis of unexplained respiratory failure.", "authors": ["Yamamoto Yuki", "Onoe Atsunori", "Ono Shohei", "Nakamura Yoshihiro", "Oishi Takahiro", "Nakamura Fumiko", "Nakajima Mari", "Sakuramoto Kazuhito", "Muroya Takashi", "Kajino Kentaro", "Ikegawa Hitoshi", "Kuwagata Yasuyuki"], "journal": "Acute medicine & surgery", "entry_date": "2026/04/28 03:57", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42046766/", "pub_types": ["Journal Article"], "affiliations": ["Department of Emergency and Critical Care Medicine Kansai Medical University Osaka Osaka Japan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "42046591", "title": "Early Relapse Frequency as a Potential Predictor of Generalization in Ocular Myasthenia Gravis: A Case Report.", "abstract": "Ocular myasthenia gravis (OMG) is characterized by symptoms confined to the extraocular muscles and progresses to generalized myasthenia gravis (GMG) in approximately half of patients, most commonly within two years of onset. Several predictors of generalization have been identified, including anti-acetylcholine receptor (AChR) antibody seropositivity, abnormal repetitive nerve stimulation (RNS) findings, older age at onset, thymoma, and greater disease severity. However, the prognostic significance of early relapse frequency in OMG remains poorly defined. We report a patient with OMG marked by early, recurrent relapses who subsequently progressed to GMG. A 69-year-old male presented with a three-day history of diplopia. Neurological examination revealed no bulbar, respiratory, or limb weakness. Laboratory testing showed elevated anti-AChR antibody levels (12 nmol/L), and RNS demonstrated a significant decremental response in the trapezius and nasalis muscles. Imaging studies revealed no evidence of thymoma. Based on ocular symptoms and supportive serological and electrophysiological findings, a diagnosis of OMG was established. High-dose intravenous methylprednisolone led to complete resolution of symptoms. Despite maintenance therapy with low-dose oral prednisolone, the patient experienced relapses of diplopia and ptosis at two and four months after onset, each requiring additional courses of high-dose intravenous methylprednisolone. During this period, no generalized muscle weakness was observed, and anti-AChR antibody titers remained stable. Seven months after onset, the patient developed dyspnea and bulbar symptoms, accompanied by a marked increase in anti-AChR antibody levels (81 nmol/L). Clinical deterioration, abnormal respiratory parameters, and a positive edrophonium test confirmed progression to GMG. Plasma exchange resulted in rapid clinical improvement, and symptoms were subsequently controlled with prednisolone and tacrolimus. In this case, relapses at months two and four occurred in the absence of generalized weakness and preceded generalization at month seven, suggesting that early, frequent relapses may represent a potential predictor of generalization in OMG. These findings underscore the potential importance of relapse frequency as a clinical marker and emphasize the need for treatment strategies in OMG aimed not only at symptom control but also at preventing generalization.", "authors": ["Terai Jun", "Matsubayashi Taiki", "Furuki Misako", "Obayashi Masato"], "journal": "Cureus", "entry_date": "2026/04/28 03:54", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42046591/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, National Hospital Organization (NHO) Disaster Medical Center, Tokyo, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42046195", "title": "CAR T-Cell Therapy in Neurology: A Scoping Review of Neuro-Oncology, Autoimmune Diseases & Neurotoxicity.", "abstract": "Chimeric antigen receptor (CAR) T-cell therapy has been investigated in neurological diseases, encompassing both central nervous system malignancies and autoimmune disorders, thereby extending its application beyond hematological cancers. This scoping review evaluates CAR T-cell therapy applications in neurological conditions, assessing therapeutic efficacy, safety profiles, and neurotoxicity management strategies. A literature search across four databases (January 2020-December 2025) identified 33 studies meeting the inclusion criteria, encompassing original and secondary research from international centers. CAR T-cell therapy demonstrated promising efficacy across diverse neurological conditions. In glioblastoma trials, 44% of patients (n = 128) achieved partial or complete clinical/radiographic responses with favorable safety profiles. Moreover, compelling results emerged from neuromyelitis optica spectrum disorder studies, in which 92% of patients (11/12) achieved sustained relapse-free remission over a median follow-up of 5.5 months. Multiple sclerosis, myasthenia gravis, and stiff-person syndrome cases exhibited excellent treatment tolerance without significant immune effector cell-associated neurotoxicity syndrome (ICANS), which is a major concern affecting 27% of patients with hematological malignancies. Overall, CAR T-cell therapy emerges as a novel therapeutic strategy in neurology, encompassing both oncological and autoimmune conditions. Toxicity profiles in neurological CAR T-cell applications differ substantially from those observed in hematologic malignancies, underscoring the need for condition-specific risk assessment frameworks and customized management approaches. Future research should prioritize larger multicenter trials with extended follow-up to establish definitive efficacy and safety profiles in neurological indications.", "authors": ["Alqaisi Omar", "Dibas Mohammed", "Tai Patricia", "Dibas Ala", "Souied Osama", "Al-Ghabeesh Suhair"], "journal": "Annals of clinical and translational neurology", "entry_date": "2026/04/28 00:33", "pub_date": "2026-04-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42046195/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Nursing Department, Al-Zaytoonah University, Amman, Jordan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "42046139", "title": "Robotic thymectomy in myasthenia gravis: current evidence, outcomes, and future perspective.", "abstract": "", "authors": ["Huang Jianwei", "Pan Chunhui", "He Jing", "Qin Junqi", "Liang Shengjing", "Zhou Yifan", "Zhong Yonglong"], "journal": "Journal of cardiothoracic surgery", "entry_date": "2026/04/28 00:10", "pub_date": "2026-04-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42046139/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Thoracic Surgery, People's Hospital of Guangxi Zhuang Autonomous Region, Guangxi Academy of Medical Sciences, No. 6 Taoyuan Road, Nanning, 530021, P.R. China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "2区"}, {"pmid": "42043793", "title": "Efficacy and Safety of Vemircopan in Generalized Myasthenia Gravis: A Randomized Clinical Trial.", "abstract": "IMPORTANCE: Inhibition of terminal complement component 5 has proven effective in acetylcholine receptor antibody-positive (AChR-Ab+) generalized myasthenia gravis (gMG) but requires intravenous or daily subcutaneous administration and is associated with an increased meningococcal infection risk. Targeting the complement alternative pathway (AP) may offer similar benefits while sparing the classical and lectin pathways, preserving some immune responses against infection.\nOBJECTIVE: To evaluate the efficacy, safety, pharmacokinetics, and pharmacodynamics of vemircopan, an oral, selective factor D inhibitor that blocks AP-mediated complement activation and amplification, in adults with AChR-Ab+ gMG.\nDESIGN, SETTING, AND PARTICIPANTS: This double-blind, parallel-group, placebo-controlled phase 2 randomized clinical trial was conducted between April 14, 2022, and April 3, 2024, at 60 sites across 8 countries. Adults with AChR-Ab+ gMG, Myasthenia Gravis-Activities of Daily Living (MG-ADL) score of 5 or greater, and Myasthenia Gravis Foundation of America classes II through IV classification were eligible for inclusion. Data were unblinded in June 2024; final analysis was completed October 2024.\nINTERVENTION: Randomization 2:1:2 to twice-daily oral vemircopan, 180 mg or 120 mg, or placebo.\nMAIN OUTCOMES AND MEASURES: The primary end point was the proportion of participants achieving a 2-point or greater reduction in MG-ADL total score from baseline for 4 consecutive weeks, without rescue therapy, during the 8-week, double-blind primary evaluation period. Secondary end points were change from baseline to week 8 in MG-ADL total score, Quantitative Myasthenia Gravis total score, and Neurological Disorders Fatigue questionnaire score.\nRESULTS: Of 99 individuals screened, 70 met eligibility criteria, and 29 were excluded. Of 70 participants randomized (vemircopan, 180 mg: n = 28; vemircopan, 120 mg: n = 14; placebo: n = 28), 38 participants (54%) were female; mean (SD) age at diagnosis was 45.4 (18.5) years. The proportion of participants achieving the primary end point did not differ significantly between placebo (18 of 28 [64%]; 90% CI, 47%-79%) and either vemircopan group (180 mg: 16 of 28 [57%]; 90% CI, 40%-73%; 120 mg: 8 of 14 [57%]; 90% CI, 33%-79%). No significant differences were observed for the secondary end points. No cases of meningococcal infection were reported; 1 participant died due to hepatic failure and 1 discontinued study treatment due to herpes simplex meningitis.\nCONCLUSIONS AND RELEVANCE: In this double-blind, parallel-group, placebo-controlled phase 2 randomized clinical trial, vemircopan did not meet the prespecified threshold for efficacy, and consequently, the study was terminated.\nTRIAL REGISTRATION: ClinicalTrials.gov Identifier: NCT05218096.", "authors": ["Saccà Francesco", "Gialdini Gino", "Howard James F", "Vu Tuan H", "Meisel Andreas", "Peric Stojan", "Lünemann Jan D", "Sgarzi Manlio", "Shaibani Aziz", "Bril Vera", "Yeh Jiann-Horng", "Reyes-Garrido Virginia", "Liao Serena", "Metais Camille", "van der Valk Ralf J P"], "journal": "JAMA neurology", "entry_date": "2026/04/27 11:32", "pub_date": "2026-06-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42043793/", "pub_types": ["Journal Article"], "affiliations": ["GENESIS Department, Federico II University of Naples, Naples, Italy."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 21.3, "journal_quartile": "1区"}, {"pmid": "42043767", "title": "Treatment Characteristics and Healthcare Resource Utilization Among Patients with Myasthenia Gravis Initiating Rozanolixizumab: A US Claims Database Analysis.", "abstract": "INTRODUCTION: Rozanolixizumab is indicated for the treatment of adults with generalized myasthenia gravis (MG). This retrospective, non-interventional cohort study evaluated adults with MG initiating rozanolixizumab in the USA.\nMETHODS: Patients were selected from de-identified claims data from the Komodo Healthcare Map® (July 2023-March 2025). Enrolled patients were aged ≥ 18 years with MG diagnosis, ≥ 1 rozanolixizumab medical/pharmacy claim, and continuous enrollment/plan coverage for 12 months (baseline period) before first rozanolixizumab treatment initiation (index date). The follow-up period was from 1 day post-index to last enrollment date. Treatment patterns and healthcare resource utilization (HCRU) were assessed during baseline and follow-up. A second study (July 2023-June 2024) assessed patients for 12 months post-index who had ≥ 1 efgartigimod claim ≤ 12 months prior to index.\nRESULTS: The main study included 719 patients. Patients with ≥ 365 days since rozanolixizumab initiation (n = 287) started a mean (standard deviation) 2.9 (1.8) treatment cycles in Year 1. Total MG-related HCRU incidence rates per 100 person-years were 88.0 during baseline and 82.9 during follow-up, and 86.2 versus 80.8 for outpatient, 25.6 versus 17.3 for inpatient, and 24.9 versus 14.0 for emergency room visits. Approximately half (53.7%, 386/719) of patients used corticosteroids at baseline and had ≥ 3 months' follow-up. 29.0% (n = 112) tapered their dose by ≥ 5 mg, and a further 29.3% (n = 113) discontinued corticosteroids during follow-up. In patients who had ≥ 1 claim for efgartigimod before initiating rozanolixizumab (n = 26), 19.2% tapered corticosteroids by ≥ 5 mg during follow-up, and 7.7% discontinued completely.\nCONCLUSION: This real-world study of patients receiving rozanolixizumab in the USA showed reductions in corticosteroid use and HCRU following rozanolixizumab initiation, including in those who switched from efgartigimod. The mean number of rozanolixizumab cycles (2.9) was lower than the mean 4.1 cycles in Phase 3 studies (patients with ≥ 1 year of follow-up), demonstrating that treatment patterns in clinical practice can be individually adjusted.", "authors": ["Kumar Mohita", "Harrold Alexandria", "Park Minjee", "Nair Aaksa", "Bardenheuer Kristina", "Tarancón Thaïs", "Ting Angela", "Pata Diogo"], "journal": "Neurology and therapy", "entry_date": "2026/04/27 11:25", "pub_date": "2026-04-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42043767/", "pub_types": ["Journal Article"], "affiliations": ["UCB, Atlanta, GA, USA. Mohita.Kumar@ucb.com."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "42041547", "title": "Exosomes in Myasthenia Gravis-Review.", "abstract": "Myasthenia gravis (MG) is a rare autoimmune disorder characterized by muscle weakness and fatigue, caused by autoantibodies produced by B-cells that target proteins in the postsynaptic membrane of the neuromuscular junction. Clinical manifestations are heterogeneous and may include diplopia, ptosis, dysarthria, dysphagia, and limb muscle weakness, with severity ranging from mild symptoms to life-threatening myasthenic crisis. Despite advances in diagnostic approaches and the availability of immunomodulatory and biological therapies, there remains a need for an improved understanding of the disease mechanisms and biomarker development in MG. Blood-derived exosomes are small extracellular vesicles that carry proteins, lipids, nucleic acids, and glycoconjugates, and are involved in intercellular communication and the transfer of biological material between cells. Circulating exosomes may reflect aspects of cellular and immune status and have been proposed as a minimally invasive source of biomarkers in various diseases. In this review, we summarize current evidence on the potential role of exosomes in MG, with a focus on their involvement in disease-associated processes and their possible utility as biomarkers, as well as directions for future research.", "authors": ["Ejdys Krystian", "Mycko Marcin P"], "journal": "Cells", "entry_date": "2026/04/27 09:23", "pub_date": "2026-04-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42041547/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology and Neurosurgery, Laboratory of Neuroimmunology, University of Warmia and Mazury in Olsztyn, 10-082 Olsztyn, Poland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.2, "journal_quartile": "2区"}, {"pmid": "42039746", "title": "Disruption of intestinal barrier and immune homeostasis links gut microbiota dysbiosis to aggravated experimental autoimmune myasthenia gravis.", "abstract": "INTRODUCTION: Myasthenia Gravis (MG) is an acquired autoimmune disease. The imbalance between Th17 and Treg cells plays a crucial role in the pathogenesis of MG. A stable intestinal microbiota is essential for maintaining immune balance, a function primarily mediated by the Th17/Treg axis. This study aims to explore the role of gut microbiota in the pathogenesis of experimental autoimmune myasthenia gravis (EAMG) to identify potential new treatment strategies.\nMETHODS: An EAMG model was established in Lewis rats by immunization with the AChRα97-116 peptide segment. The composition and structure of the gut microbiota were analyzed by 16S rRNA sequencing. The serum levels of inflammatory cytokines (IFN-γ, TNF-α, IL-17, IL-10), AChR-Ab, and LPS were measured using the ELISA method. Colon tissues were subjected to Hematoxylin and eosin (H&E) staining, and Claudin-1 and Muc2 expression was analyzed via immunofluorescence. A microbiota disorder animal model was established by administering an antibiotic mixture via gavage, followed by fecal microbiota transplantation. Splenic CD3+CD4+IL-17A+ Th17 cells and CD3+CD4+CD25+Foxp3+ Treg cells were quantified by flow cytometry.\nRESULTS: 1. Compositional and structural changes of the gut microbiota in EAMG. Compared with HC, the serum levels of IFN-γ, TNF-α, IL-17, and AChR-Ab in EAMG were significantly increased (P < 0.0001), while the serum level of IL-10 was significantly decreased (P < 0.0001), and the serum level of LPS was increased (P < 0.01). The protein levels of Claudin-1 (P < 0.001) and Muc2 (P < 0.05) in the colon were significantly reduced in EAMG. 2. Relative to rats receiving HC microbiota transplantation (HMb), those receiving EAMG microbiota transplantation (MMb) exhibited significantly elevated serum levels of AChR-Ab (P < 0.01), TNF-α (P < 0.05), IL-17 (P < 0.05), and LPS (P < 0.01), alongside significantly reduced colonic levels of Claudin-1 (P < 0.05) and Muc2 (P < 0.0001). 3. Compared with the EAMG group, the ABX + EAMG group (EAMG with microbiota dysbiosis) exhibited significantly lower colonic levels of Claudin-1 and Muc2 (P < 0.05), a significantly greater splenic Th17/Treg cell imbalance (P < 0.01), and significantly higher serum AChR-Ab levels (P < 0.01).\nDISCUSSION: The gut microbiota is intricately linked to the progression of EAMG. Microbiota dysbiosis can exacerbate intestinal barrier damage in EAMG and may further influence the pathological changes of myasthenia by disrupting the Th17/Treg immune balance. These findings suggest a novel therapeutic strategy for the treatment of myasthenia gravis by re-establishing microbial homeostasis.", "authors": ["Tian Wenqi", "Peng Shanshan", "Xu Fanfan", "Kong Xiaotong", "Li Ying", "Zhang Wei", "Liu Zhaojun", "Zhang Huixue", "Wang Jianjian", "Wang Lihua"], "journal": "Frontiers in cellular and infection microbiology", "entry_date": "2026/04/27 07:02", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42039746/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Harbin Medical University, Harbin, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "42037957", "title": "Immune Checkpoint Inhibitor Overlap Syndrome: Myocarditis, Myositis, and Myasthenia Gravis in a Patient With Metastatic Melanoma.", "abstract": "Immune checkpoint inhibitors can produce severe immune-mediated toxicity involving multiple organ systems. A rare manifestation is the myocarditis, myositis, and myasthenia gravis (MMM) overlap syndrome, also referred to as triple M syndrome or immune-related MMM overlap syndrome, characterized by concurrent myocarditis, myositis, and myasthenia gravis and capable of rapid progression to life-threatening cardiac and neuromuscular complications. A 78-year-old man with metastatic melanoma developed palpitations, profound fatigue, proximal muscle weakness, diplopia, and ptosis two weeks after initiation of nivolumab and ipilimumab. Initial evaluation revealed marked elevations in high-sensitivity troponin (11,399 ng/L), creatine kinase (6,046 U/L), and transaminases, with sinus tachycardia on electrocardiography and preserved systolic function on echocardiography. Intravenous methylprednisolone was started, and immunotherapy was discontinued; however, his biomarkers continued to rise, and his condition rapidly deteriorated after transferring to a tertiary cardiac intensive care unit. He developed a complete heart block requiring transvenous pacing and subsequently demonstrated severe biventricular systolic dysfunction on cardiac imaging. Coronary angiography showed no obstructive disease. Despite escalation to pulse-dose steroids, his neuromuscular weakness worsened, and he progressed to respiratory failure requiring mechanical ventilation, followed by malignant ventricular arrhythmias and hemodynamic collapse before additional therapies, including plasmapheresis, could be initiated. Care was transitioned to comfort measures, and death occurred shortly thereafter. Endomyocardial biopsy confirmed lymphocytic myocarditis with myocyte necrosis. This case highlights that early neuromuscular symptoms accompanied by marked troponin and creatine kinase elevation may represent the first manifestations of MMM overlap syndrome and can precede rapid progression to life-threatening cardiac and respiratory complications.", "authors": ["Bennett Samuel", "Harish Abhinav", "Althumairy Hamad", "Wang Elisa", "Mysore Manu"], "journal": "Cureus", "entry_date": "2026/04/27 06:46", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42037957/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, University of Maryland Medical Center, Baltimore, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42035597", "title": "Successful treatment with eculizumab in refractory myasthenia gravis with both anti-AChR and anti-LRP4 antibodies: two case reports.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG), an antibody-induced autoimmune disorder of the neuromuscular junction, is characterized by fluctuating skeletal muscle weakness and fatigability. Approximately 85% of patients with MG have antibodies against the acetylcholine receptor (AChR), 5-10% against muscle-specific kinase receptor, and 1-5% against lipoprotein-related protein 4 (LRP4). In addition to the detection of antibodies providing insight into the diagnosis and prognosis of gMG, it also affects the choice of treatment. In the majority of cases, gMG can be managed effectively using a tailored regimen of acetylcholinesterase inhibitors, immunosuppressive medication, and thymectomy. However, existing treatments fail to adequately manage the manifestations in 10-15% of individuals with gMG (refractory gMG). Eculizumab, a recombinant humanized monoclonal antibody that specifically targets the complement protein C5, is approved for anti-AChR-positive gMG patients. Anti-AChR antibodies, anti-LRP4 antibodies, and anti-Titin antibodies all have the capacity to activate the complement protein signaling pathway.\nCASE PRESENTATION: We report two cases of refractory gMG with multiple antibody positivity. The first case, an 82-year-old male patient, was positive for anti-AChR, anti-LRP4, and anti-Titin antibodies; the second case, a 67-year-old female, was positive for anti-AChR and anti-LRP4 antibodies. Both cases of refractory gMG responded well to eculizumab treatment.\nCONCLUSION: This report of highlights two cases of refractory gMG with multiple antibody positivity (both patients had anti-AChR and anti-LRP4 antibodies) that responded to eculizumab. These findings warrent further experience with eculizumab treatment in gMG patients with multiple antibody positivity.", "authors": ["Karaman Bedriye", "Gören Göker", "Tuncel Rasim", "Ekmekci Özgül", "Yüceyar Nur"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/26 18:07", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42035597/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Ege University Hospital, Department of Neurology, Izmir, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42033803", "title": "Taiwan Clinical Practice Guidelines for Myasthenia Gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by muscle weakness and fatigue due to autoantibodies impairing neuromuscular transmission. With a global prevalence of 40-180 per million, Taiwan has seen a rise in MG cases from 4476 in 2013 to 5752 in 2019, with generalized MG (GMG) prevalence increasing significantly, whereas GMG patients incur substantially higher medical costs and resource utilization compared to non-MG patients. To standardize MG management, the Society formed an expert committee of 37 MG specialists and a patient representative, tasked with developing evidence-based guidelines. The committee, organized into 11 thematic subgroups, conducted a systematic review of literature from 2015 to 2024 and employed a Modified Delphi method to achieve consensus on clinical guidance statements. Recommendations cover diagnosis (e.g., antibody testing and electrophysiological tests), treatment (e.g. thymectomy, steroids, and novel biologics), and management of specific MG subtypes, including ocular, early- and late-onset, muscle-specific tyrosine kinase-related, and refractory MG, as well as myasthenic crisis and neonatal MG. The guidelines emphasize early diagnosis, integrated management of comorbidities, and long-term care strategies, including patient support and tailored exercise programs. These consensus statements aim to enhance care quality, improve patient outcomes, and guide future research and pharmaceutical development in Taiwan's medical community.", "authors": ["Yeh Hsu-Ling", "Chang Che-Cheng", "Liu An-Bang", "Tsai Meng-Han", "Ro Long-Sun", "Chang Yi-Chen", "Tiong Tung-Yu", "Su Jen-Jen", "Lee Yi-Chung", "Huang Yu-Ning", "Liao Shu-Lang", "Lin Thy-Sheng", "Liao Yi-Chu", "Chung Chen-Chih", "Chang Kuo-Hsuan", "Chao Shu-Ping", "Sun Yuan-Ting", "Guo Yuh-Cherng", "Huang Chin-Chang", "Chiu Wei-Ting", "Chen Chiung-Mei", "Chang Ming-Hsing", "Chao Chi-Chao", "Chou Cheng-Che", "Chou I-Jun", "Kuo Yung-Ting", "Chang Anne", "Chang Chen-Shu", "Cheng Mei-Yun", "Lin Kuan-Yu", "Lin Kon-Ping", "Chen Wei-Hung", "Hsu Jung-Lung", "Yang Chih-Chao", "Tsai Nai-Wen", "Yeh Jiann-Horng", "Chiu Hou-Chang"], "journal": "Acta neurologica Taiwanica", "entry_date": "2026/04/25 16:43", "pub_date": "2026-04-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42033803/", "pub_types": ["Journal Article", "Practice Guideline"], "affiliations": ["Department of Neurology, Shin Kong Wu Ho Su Memorial Hospital, Taipei, Taiwan."], "china_related": true, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "42033462", "title": "Burden of Disease in Myasthenia Gravis: A Targeted Literature Review.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune neurologic disorder with a heterogenous disease presentation. The objective of this targeted literature review was to characterize the burden of disease and unmet treatment needs in patients with MG.\nMETHODS: Scientific articles published in English between May 4, 2013, and November 24, 2025, were identified in the PubMed, Medline, Embase, and Cochrane Library databases using a pre-defined Boolean search strategy. Titles and abstracts were screened for information on clinical presentation, pathology, and diagnostic considerations for MG; burden of disease, including epidemiologic, clinical, humanistic, and economic burden; and treatments, including treatment guidelines.\nRESULTS: The analysis included 318 records. Population-based estimates of MG incidence published from 2007 onwards ranged from 0.3 to 6.1 per 100,000 person-years, and prevalence estimates ranged from 2.2 to 58.6 per 100,000 persons. The clinical and humanistic burden of MG remains high, with patients reporting inadequate symptom control, fatigue, poor quality of life, and dissatisfaction with their current treatment. Greater disease severity was associated with reduced quality of life and poorer mental health. Medical costs varied by region, and key drivers of direct medical costs include hospitalization and treatment of exacerbation or myasthenic crisis.\nCONCLUSION: The burden of MG remains high, despite the availability of novel treatments. Studies are needed to better characterize the current burden of MG in the context of newer treatment options and to explore how the disease burden may be reduced for patients.", "authors": ["Pasnoor Mamatha", "Miller-Wilson Lesley-Ann", "Edwards Yuriy", "Copley-Merriman Kati", "Costello Jessica", "Foss Allison", "Muppidi Srikanth"], "journal": "Journal of neurology", "entry_date": "2026/04/25 11:02", "pub_date": "2026-04-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42033462/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University of Kansas Medical Center, 3599 Rainbow Blvd, Kansas City, KS, 66103, USA. mpasnoor@kumc.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "42030966", "title": "Is partial complement blockade enough in myasthenia gravis?", "abstract": "", "authors": ["Iorio Raffaele"], "journal": "Lancet (London, England)", "entry_date": "2026/04/24 18:52", "pub_date": "2026-05-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42030966/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroscience, Università Cattolica del Sacro Cuore, 00168 Rome, Italy; Fondazione Policlinico Universitario Agostino Gemelli IRCCS, Rome, Italy. Electronic address: raffaele.iorio@policlinicogemelli.it."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 98.4, "journal_quartile": "1区"}, {"pmid": "42030965", "title": "Efficacy and safety of cemdisiran siRNA in myasthenia gravis (NIMBLE): a double-blind, randomised, placebo-controlled, phase 3 trial.", "abstract": "BACKGROUND: Autoantibody-mediated complement activation drives pathology in acetylcholine receptor (AChR) antibody-positive generalised myasthenia gravis. Newer targeted therapies lower overall antibody concentrations or inhibit complement activity. We aimed to evaluate an siRNA (cemdisiran) targeting complement component 5 (C5) as monotherapy and in combination with a C5 antibody (pozelimab) in generalised myasthenia gravis.\nMETHODS: NIMBLE is a randomised, double-blind, placebo-controlled, phase 3 trial conducted at 86 centres in 13 countries. We enrolled patients aged 18 years or older with a diagnosis of generalised myasthenia gravis, positive serology for anti-AChR or anti-LRP4 antibodies, and a Myasthenia Gravis-Activities of Daily Living (MG-ADL) score of 6 or greater. Patients were randomly allocated to receive cemdisiran monotherapy (600 mg every 12 weeks; cemdisiran group), pozelimab monotherapy (200 mg every 4 weeks; pozelimab group), combined cemdisiran (200 mg every 4 weeks) and pozelimab (200 mg every 4 weeks; combination group), or placebo, all administered subcutaneously, during a 24-week double-blind treatment period. The primary endpoint was change from baseline in MG-ADL scores at week 24, assessed in the modified intention-to-treat (mITT) primary analysis set (the first 245 randomly allocated patients who received any dose of study treatment and had at least one post-baseline assessment). A prespecified hierarchal statistical testing strategy was used; multiplicity was controlled for comparisons of cemdisiran versus placebo and combination versus placebo (pozelimab was not statistically tested against placebo and was used only to assess the contribution of components to the combination treatment). Safety was mainly assessed by recording of treatment-emergent adverse events in all patients who received any dose of study treatment. This study is registered with ClinicalTrials.gov (NCT05070858); the current status is active, not recruiting.\nFINDINGS: Between Jan 20, 2022 and July 18, 2025, 390 participants were screened and, as of the data cut-off presented in this report (July 8, 2025), 284 were randomly allocated to the cemdisiran group (79 [28%] patients), pozelimab group (50 [18%]), combination group (80 [28%]), and placebo group (75 [26%]). Of 277 patients who received any study treatment, 263 (95%) completed the double-blind treatment period. In the mITT primary analysis set, at week 24, the least-squares mean change from baseline in MG-ADL total score was -4·5 (SE 0·4) in the cemdisiran group (n=64), -4·0 (0·4) in the combination group (n=67), and -2·2 (0·5) in the placebo group (n=59). Placebo-adjusted least-squares mean differences in MG-ADL score at week 24 were -2·3 (SE 0·7; 95% CI -3·6 to -1·0; p=0·0005) in the cemdisiran group and -1·7 (0·7; -3·0 to -0·4; p=0·0086) in the combination group. The proportion of participants with at least one adverse event during the double-blind treatment period was 54 (69%) of 78 in the cemdisiran group, 65 (81%) of 80 in the combination group, 40 (82%) of 49 in the pozelimab group, and 54 (77%) of 70 in the placebo group. The most common adverse event in the cemdisiran group was upper respiratory tract infection (nine [12%] of 78 patients), which occurred at a similar incidence in the placebo group (eight [11%] of 70). No serious or meningococcal infections occurred in the cemdisiran group. Adverse events leading to treatment discontinuation occurred in two participants (3%) in the placebo group and one participant (2%) in the pozelimab group. No deaths occurred during the double-blind treatment period. Two deaths occurred after the double-blind treatment period, one of which was assessed as treatment-related by the investigator but not treatment-related by the sponsor.\nINTERPRETATION: Cemdisiran monotherapy and combination therapy were effective in the treatment of generalised myasthenia gravis, and were generally well tolerated. Subcutaneous dosing of cemdisiran, administered every 3 months, could provide a convenient treatment approach for generalised myasthenia gravis.\nFUNDING: Regeneron Pharmaceuticals.", "authors": ["Vu Tuan", "Habib Ali A", "Jacob Saiju", "Mantegazza Renato", "Murai Hiroyuki", "Vissing John", "Shaibani Aziz", "Levine Todd", "Hussain Yessar", "Meisel Andreas", "Adamczak-Ratajczak Agnieszka", "Ilkowski Jan", "Sgobbi Paulo", "Guerreiro Alexandre", "Luo Sushan", "Pavani Rodrigo", "Chaudhari Umesh", "Jalali Neda", "DeVeaux Michelle", "Moore Warren", "Meagher Karoline A", "Burczynski Michael E", "Kokate Shital", "Sherman Steven", "Pawaskar Dipti", "Singh Nikhil", "Souttou Amal", "Sirulnik Andres", "Perlee Lorah", "Yancopoulos George D", "Howard James F"], "journal": "Lancet (London, England)", "entry_date": "2026/04/24 18:52", "pub_date": "2026-05-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42030965/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase III", "Multicenter Study"], "affiliations": ["University of South Florida Morsani College of Medicine, Tampa, FL, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 98.4, "journal_quartile": "1区"}, {"pmid": "42030590", "title": "Combined inhibition of complement C5 and neonatal Fc receptor in refractory generalized myasthenia gravis: A report of two cases.", "abstract": "In patients with refractory generalized myasthenia gravis (MG) inadequately controlled by standard immunotherapies, including intravenous immunoglobulin and intravenous methylprednisolone, molecular targeted therapies have emerged as important treatment options. Although both neonatal Fc receptor (FcRn) inhibitors and complement C5 inhibitors have demonstrated efficacy in anti-acetylcholine receptor antibody-positive generalized MG, the clinical utility of their combined use remains unclear. Here, we report two cases of refractory anti-acetylcholine receptor antibody-positive generalized MG successfully managed with combined FcRn and C5 inhibition. In Case 1, disease control was not achieved despite thymectomy, multiple standard immunotherapies, and FcRn inhibition alone. Sequential treatment with C5 inhibitors, including eculizumab, ravulizumab, and zilucoplan, was attempted; sustained stabilization occurred only after combination therapy with zilucoplan and subcutaneous efgartigimod. In Case 2, standard therapies were ineffective, and thymectomy under general anesthesia was considered unsafe because of severe disease activity. Combination therapy was therefore introduced to stabilize the disease and enable safe perioperative management. Following successful thymectomy, targeted therapies were discontinued in Case 2, whereas Case 1 required ongoing treatment. To our knowledge, this is one of the first reports demonstrating effective disease control using combined FcRn and C5 inhibition in refractory generalized MG. These cases suggest that this strategy may benefit selected patients with refractory disease, particularly when stable disease control is required; however, further studies are warranted to determine its broader applicability and long-term safety.", "authors": ["Irie Ken-Ichi", "Imai Tatsuya", "Koga Tamon", "Tanaka Yoshiko", "Isogai Masashige", "Harada Masaya", "Mori Shinichiro", "Hoshino Tomoaki", "Tateishi Takahisa"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/24 17:59", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42030590/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Division of Respirology, Neurology and Rheumatology, Department of Medicine, Kurume University School of Medicine, Kurume, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42028749", "title": "Orbicularis Oculi Toxin Injection for Treating Levator Palpebrae Superioris Weakness: Clinical Effect and Safety in a Cohort Study.", "abstract": "BACKGROUND: Ptosis, the drooping of the upper eyelid caused by levator palpebrae superioris muscle dysfunction, is a common condition that can impair vision and quality of life. It can arise independently or as a secondary condition to diseases such as myasthenia gravis. Traditional treatments for ptosis include surgical interventions, but botulinum toxin injections have gained interest due to their non-invasive nature and promising results in improving eyelid function.\nOBJECTIVES: To evaluate the efficacy and safety of orbicularis oculi muscle toxin injections in comparison to traditional levator palpebrae superioris muscle shortening surgery for the treatment of ptosis.\nMETHODS: A cohort study was conducted with 36 patients diagnosed with levator palpebrae superioris muscle weakness. Patients were divided into two groups: an experimental group receiving botulinum toxin injections and a control group undergoing traditional surgery. Primary outcomes included changes in palpebral fissure height, visual scores, and patient satisfaction. Secondary outcomes involved adverse reactions and recovery time.\nRESULTS: The experimental group showed a significant improvement in palpebral fissure height (3.5 mm) and visual function compared to the control group (1.7 mm). Patient satisfaction was higher in the experimental group, particularly due to the non-invasive nature and shorter recovery period. The incidence of adverse reactions was lower in the experimental group, with fewer complications like scarring.\nCONCLUSIONS: Botulinum toxin injection may represent a minimally invasive alternative in carefully selected patients, particularly those with mild dysfunction or those wishing to avoid surgery. It provides significant improvements in palpebral fissure height and visual function, with fewer side effects and a faster recovery, making it a viable option for early-stage patients or those wishing to avoid surgery. Further studies should explore its long-term effectiveness.", "authors": ["Lu Shunbing", "Wei Qingqian", "Ma Juan", "Zhuang Jun", "Su Xueshang", "Lu Yunshun", "Zhang Ziming", "Liang Yutong", "Hu Jintian"], "journal": "Aesthetic surgery journal", "entry_date": "2026/04/24 06:33", "pub_date": "2026-04-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42028749/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cosmetic Injection Center, Plastic Surgery Hospital, Chinese Academy of Medical Sciences and Peking Union Medical College, Beijing, China."], "china_related": true, "study_types": ["Non-randomized controlled cohort"], "evidence_level": "III", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "42028533", "title": "Unusual Association of a Thymic Cyst and Thymolipoma: A Case Report.", "abstract": "Benign thymic lesions are uncommon and mainly include thymic cysts, thymic hyperplasia, and thymolipoma. Their coexistence is exceptionally rare and may represent a significant diagnostic challenge, particularly because of the potential for confusion with malignant tumors of the anterior mediastinum. We report the case of a 68-year-old woman who presented with a large anterosuperior mediastinal mass that was radiologically suggestive of a thymoma, in the absence of clinical or biological features of myasthenia gravis. Complete surgical excision was performed, and histopathological examination revealed a multilocular thymic cyst arising in a thymolipoma, characterized by multiple cystic spaces lined by a benign epithelium and thymic parenchyma largely replaced by mature adipose tissue containing residual thymic islands with Hassall's corpuscles, without cytological atypia or evidence of invasion. This case highlights the limitations of imaging in the assessment of anterior mediastinal masses and emphasizes the pivotal role of histopathological analysis in distinguishing benign thymic lesions from malignant thymic tumors, thereby avoiding overdiagnosis and unnecessary aggressive treatment, with complete surgical resection providing an excellent prognosis.", "authors": ["Zahouani Kholoud", "Assadiki Akram", "Haloui Anass", "Karich Nassira", "Bennani Amal"], "journal": "Cureus", "entry_date": "2026/04/24 04:59", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42028533/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Pathology, Mohammed VI University Hospital, Faculty of Medicine and Pharmacy of Oujda, Mohammed First University, Oujda, MAR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42027923", "title": "Myasthenia gravis in Latin America and the Caribbean: epidemiology, resources, and accessibility to diagnosis and treatment.", "abstract": "Latin-American and Caribbean (LAC) countries face persistent challenges in achieving universal health coverage, with out-of-pocket healthcare expenditures posing a significant barrier. Access to care for rare diseases, such as myasthenia gravis (MG), is significantly impacted. We conducted an exploratory descriptive study between LAC countries, and we assessed the availability of diagnostic and therapeutic resources for MG across 12 LAC countries, along with associated costs and access barriers. We found marked inequalities regarding the availability and coverage of diagnostic tests and therapies by public healthcare systems. The elevated out-of-pocket costs, up to several times the minimum wage, and shortage of neurologists, makes appropriate diagnosis and treatments inaccessible for many patients living with MG. Novel treatments for MG are unavailable for most people with MG in Latin America.", "authors": ["Salutto Valeria L", "Navarro Cristian E", "Urra Pincheira Alejandra", "Dondis Camaño David R", "Guerrero Karina", "Dos Santos André C J", "Moreno Martinez Carlos A", "Ojeda Jacquet Víctor D", "Peñaloza Miranda Lenin", "Perna Ramos Abayubá", "Romero Suárez Guillermo", "Vargas Cañas Edwin S", "Idiaquez Rios Juan Francisco", "Barnett-Tapia Carolina"], "journal": "Frontiers in public health", "entry_date": "2026/04/24 04:52", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42027923/", "pub_types": ["Journal Article"], "affiliations": ["Medical Research Institute Alfredo Lanari, Buenos Aires University, Buenos Aires, Argentina."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "42025269", "title": "Real-world evidence on utilization and clinical outcomes of efgartigimod in patients with generalized myasthenia gravis.", "abstract": "Conventional therapies for acetylcholine receptor antibody-positive (AChR-Ab+) generalized Myasthenia Gravis (gMG) often provide inadequate disease control. Although neonatal Fc receptor (FcRn) inhibitors have proven effective in clinical trials, real-world evidence on their use and effectiveness in heterogeneous patient populations is still limited. This study evaluates clinical outcomes, steroid-sparing effects, and treatment utilization of efgartigimod in patients with refractory AChR-Ab+ gMG. We conducted a retrospective analysis of 27 adult patients with AChR-Ab+ gMG treated with efgartigimod. Effectiveness, treatment utilization and long-term outcomes were evaluated over seven treatment cycles using longitudinal Myasthenia Gravis Activities of Daily Living (MG-ADL) scores, inter-cycle interval duration, daily corticosteroid dosing, need for rescue therapies, and transition to other advanced therapies. In total, 130 treatment cycles were analyzed. Overall, the patients showed rapid and sustained clinical improvement. Baseline MG-ADL scores (EMM = 8.48) significantly decreased by 2.96 points by cycle-2 (p < 0.001), reaching maximum reduction of 3.95 points by cycle-6. Severe impairment (MG-ADL ≥ 10) decreased from 41% at baseline to 0% by cycle-5, while 66% of patients achieved mild symptoms (MG-ADL 2-4) or Minimal Symptom Expression by cycle-7. Significant corticosteroid-sparing effect occurred by cycle-3 (p = 0.023), with mean daily methylprednisolone doses decreasing from 5.8 mg at baseline to 2.3 mg by cycle-5. Four patients (15%) were non-responders and transitioned to complement inhibition therapy. Real-world efgartigimod use provides rapid symptomatic relief and significant corticosteroid reduction in patients with refractory AChR-Ab+ gMG. While most achieve sustained improvement, non-responders and patients with history of myasthenic crises require close monitoring and potential transition to alternative advanced therapies.", "authors": ["Miguet Lauren", "De Merlier Martijn", "Claeys Kristl G"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/23 20:09", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42025269/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurosciences, Laboratory for Muscle Diseases and Neuropathies, KU Leuven, and Leuven Brain Institute (LBI), and Leuven Institute for Rare Diseases (Leuven.IRD), Leuven, Belgium."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "42025103", "title": "Cellular therapies in autoimmune neuromuscular disorders: the new frontier.", "abstract": "Antibody-mediated humoral immunity plays a vital role in a number of autoimmune neuromuscular disorders (AINMD), such as myasthenia gravis, Lambert-Eaton myasthenic syndrome (LEMS), stiff-person syndrome (SPS), and autoimmune myositides. Although biologics based B cell and plasma cell depletion (BCDT) therapy effectively treats some AINMDs, its variable success highlights the limitations of this therapeutic modality. B cell directed cellular therapy (BCDcT) targeting a wide array of B cell lineages, including short-lived plasma cells, has emerged as an effective treatment modality in hematological malignancies, resulting in impressive reductions in tumor burden, relapse rates, and mortality. Despite the impressive success of BCDcT, especially in hematological malignancies, its initial use was limited to last-resort cases due to the high morbidity associated with cytokine release syndrome (CRS) and immune cell-associated neurological toxicity (ICANS). Recent improvements in the safety profile of BCDcTs and better clinical management have lowered the incidences of CRS and ICANS, leading to its earlier use in some cancers. The success of BCDcT in B cell malignancies has promoted strong interest in applying this therapeutic approach to autoimmune disorders, particularly AINMD. This review will cover cell therapy fundamentals, limitations of current BCDTs, experiences with cell therapy in AINMD, and both ongoing and planned trials in this field.", "authors": ["Habib Ali Aamer", "Villalta S Armando", "Pratap Siddhant", "Mozaffar Tahseen"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2026/04/23 18:09", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42025103/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Departments of Neurology, University of California, Irvine, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "42019752", "title": "Exosomes for myasthenia gravis: unraveling pathogenic insights and pioneering therapies.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by pathogenic autoantibodies targeting the neuromuscular junction, leading to fatigable muscle weakness. While traditional and novel biologic therapies have advanced management, the complex immunopathology necessitates deeper mechanistic insights and improved diagnostic tools. Exosomes-small extracellular vesicles secreted by virtually all cell types-have emerged as pivotal players in intercellular communication, immune regulation, and disease propagation. This review synthesizes current evidence on the multifaceted roles of exosomes in MG. We detail their therapeutic potential, highlighting how engineered exosomes from tolerogenic dendritic cells or mesenchymal stem cells can deliver immunomodulatory cargo (e.g., miR-146a, caspase-1 inhibitors) to restore immune tolerance, suppress pathogenic antibody production, and ameliorate disease in experimental models. We explore their diagnostic utility as reservoirs of stable biomarkers, where dysregulated exosomal microRNAs (e.g., miR-106a-5p, miR-150-5p) and long non-coding RNAs correlate with disease severity, subtype, and treatment response, offering promise for non-invasive monitoring, especially in seronegative MG. Furthermore, we examine pathogenic mechanisms, whereby exosomal cargos may disrupt central thymic tolerance, amplify B- and T-cell activation via lncRNA-mediated miRNA sequestration, and contribute to neuromuscular dysfunction. By integrating findings across these domains, this review positions exosomes as critical mediators linking immune dysregulation to clinical manifestations in MG. Their dual nature as both disease contributors and therapeutic vehicles underscores their translational significance, paving the way for novel biomarker-driven strategies and targeted, cell-free immunotherapies in the precision medicine era.", "authors": ["Roudsari Zahra Oushyani", "Hashemi Motahar Haniyeh", "Anarjan Fatemeh Salahpour", "Rahdan Fereshteh", "Shodikulova Gulandom", "Badr Istabraq H", "Movahedpour Ahmad", "Ehtiati Sajad"], "journal": "Clinica chimica acta; international journal of clinical chemistry", "entry_date": "2026/04/22 19:15", "pub_date": "2026-04-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42019752/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Biotechnology, School of Medicine, Zanjan University of Medical Sciences, Zanjan, Iran."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "42019495", "title": "Descartes-08: Unlocking the potential of mRNA CAR T-cell therapy in myasthenia gravis.", "abstract": "", "authors": ["Howard James F"], "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "entry_date": "2026/04/22 18:41", "pub_date": "2026-05-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42019495/", "pub_types": ["Journal Article"], "affiliations": ["University of North Carolina, Chapel Hill, NC, USA. Electronic address: howardj@neurology.unc.edu."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "42018844", "title": "Osteoporosis knowledge and health beliefs in ındividuals with myasthenia gravis: a cross-sectional controlled study.", "abstract": "OBJECTIVE: The aim of this study was to investigate knowledge and health beliefs regarding osteoporosis in individuals with myasthenia gravis.\nMETHODS: This cross-sectional study included 40 individuals with myasthenia gravis and 40 healthy controls, who were selected among individuals accompanying patients at outpatient clinics and hospital support staff. Participants completed the Revised Osteoporosis Knowledge Test and the Osteoporosis Health Belief Scale. For individuals with myasthenia gravis, additional data were collected, including disease duration, current use of prednisolone, and clinical classification.\nRESULTS: In the myasthenia gravis group, the mean total Revised Osteoporosis Knowledge Test score was 16.6±2.3, and the mean total Osteoporosis Health Belief Scale score was 146.4±6.1, with no statistically significant difference compared with the controls (p>0.05). The myasthenia gravis group had significantly higher \"barriers to exercise\" scores compared with controls (p<0.001). Only 37.5% of individuals with myasthenia gravis perceived themselves to be at risk of developing osteoporosis. In the patient group, educational level showed a strong positive correlation with both total Revised Osteoporosis Knowledge Test (r=0.756, p<0.001) and total Osteoporosis Health Belief Scale (r=0.313, p=0.005) scores, whereas disease duration showed no significant correlation. There was also no significant difference in total Revised Osteoporosis Knowledge Test and Osteoporosis Health Belief Scale scores between patients currently receiving prednisolone and those not receiving it (p>0.05).\nCONCLUSION: This study indicates that individuals with myasthenia gravis have inadequate knowledge and low perception of osteoporosis risk. To enhance early identification and prevent osteoporosis-related complications, implementing targeted educational and preventive strategies is essential in this vulnerable population.", "authors": ["Meral Hatice Betigül", "Aysal Fikret", "Aliyeva Tehran", "Toplutaş Eren"], "journal": "Revista da Associacao Medica Brasileira (1992)", "entry_date": "2026/04/22 15:33", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42018844/", "pub_types": ["Journal Article"], "affiliations": ["Istanbul Medipol University, Faculty of Medicine, Department of Physical Medicine and Rehabilitation - Istanbul, Turkey."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "42015819", "title": "Characteristics of Patients with Myasthenia Gravis in the French Rare Disease Registry.", "abstract": "BACKGROUND: The French National Rare Diseases Registry (BNDMR) was established in 2007 to ensure access to optimal care standards for all patients with rare diseases in dedicated reference centres. The objective of this retrospective cohort study was to describe patients with myasthenia gravis (MG) in the BNDMR.\nMETHODS: All patients aged ≥ 18 years in the BNDMR with a confirmed diagnosis of MG visiting a reference centre at least once between 2007 and 2021 (inclusive) were included. Diagnosis was defined through ORPHA:589 or ORPHA:391490 disease codes. Patients were followed for ≥ 12 months until 31 December 2022 (or until death). Data were collected on demographics and disease history. Mortality was estimated using Kaplan-Meier survival analysis. Healthcare resource utilisation at the reference centre was documented.\nRESULTS: Overall, 3963 patients were analysed. Mean follow-up duration was 6.1 ± 3.8 years. The median interval between diagnosis and inclusion was 3.8 months [IQR: 1.5-7.5] and the median age at symptom onset was 52.0 [IQR: 34.0-69.0] years. Survival probability was 82.7% at 10 years, and higher in women than men (p < 0.001; logrank test). The mean interval between visits was 4.1 months. The mean number of overnight or day hospitalisations per patient was 2.6 ± 3.4 and the mean number of physician consultations per patient per year was 1.7 ± 1.1.\nCONCLUSION: This national registry study provides reference data for patients in France with a confirmed diagnosis of MG. However, all patients with MG are still not managed in dedicated reference centres.", "authors": ["Camdessanche Jean-Philippe", "Echaniz-Laguna Andoni", "Solé Guilhem", "Blein Cécile", "Ciumas Mariana", "Messiaen Claude", "Jannot Anne-Sophie", "Attarian Shahram"], "journal": "European journal of neurology", "entry_date": "2026/04/22 04:13", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42015819/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Neuromuscular Disease Reference Centre, Hôpital Nord, University Hospital of Saint-Étienne, Euro-NMD, Saint-Étienne, France."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "42015320", "title": "Complement deposition, IgG subtyping and endplate destruction in LRP4-ab-positive myasthenia gravis.", "abstract": "UNLABELLED: Involvement of the complement system in myasthenia gravis (MG) depends on the IgG subclass of the mediating antibody. LRP4 antibodies (LRP4-ab) are typically of the IgG1 or IgG2 subclass, implying distinct capacities to activate complement. The extent and pattern of complement involvement in LRP4-ab⁺ MG remain insufficiently characterized at the human neuromuscular junction (NMJ). We examined intercostal muscle biopsies from seven patients with LRP4-ab⁺ generalized MG using immunohistochemistry, immunofluorescence including IgG-subtyping, electron microscopy (EM), and qPCR for complement-associated gene expression. AChR-ab⁺ MG patients and non-disease controls served as comparators. C5b-9 deposition at NMJs was observed in all LRP4-ab⁺ biopsies, affecting 6–96% of identified endplates. Co-localization with IgG1 was consistently detected, whereas IgG2 and IgG4 were absent. One double-seropositive patient showed focal IgG3 staining. Complement transcript levels (C1QC, C3) were higher in LRP4-ab⁺ and AChR-ab⁺ MG compared with controls. Ultrastructural analysis revealed reduced and shortened postsynaptic clefts in 3/4 evaluable LRP4-ab⁺ patients. One therapy-refractory LRP-ab + MG patient with complement deposition and endplate destruction improved after targeted complement inhibition was introduced to his therapeutic regimen, which was based on the biopsy finding. Our findings provide in situ evidence of classical complement pathway activation and associated structural alterations at the human NMJ in LRP4-ab⁺ MG. These tissue-based data contribute to a better understanding of the pathophysiology in this rare MG subgroup.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s40478-026-02284-0.", "authors": ["Hoffmann Sarah", "Brokamp Katharina", "Meisel Andreas", "Doksani Paolo", "Helmig Lissy", "Schuelke Markus", "Rückert Jens-Carsten", "Pumberger Matthias", "Schömig Friederike", "Wolfsgruber Marlene", "Koneczny Inga", "Mayrhofer Marie", "Blüthner Martin", "Ruck Tobias", "Pawlitzki Marc", "Stenzel Werner", "Preusse Corinna"], "journal": "Acta neuropathologica communications", "entry_date": "2026/04/22 00:30", "pub_date": "2026-04-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42015320/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology with Experimental Neurology, Charité - Universitätsmedizin Berlin, Freie Universität Berlin, Humboldt Universität zu Berlin, Charitéplatz 1, 10117, Berlin, Germany. sarah.hoffmann@charite.de."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.7, "journal_quartile": "1区"}, {"pmid": "42015252", "title": "Trends in hospitalisation, myasthenic crisis and intensive care use in myasthenia gravis: a nationwide population-based study in Spain (2016-2022).", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a chronic autoimmune disorder increasingly affecting older adults, with rising prevalence and comorbidity burden across Europe. Contemporary nationwide data describing MG-related hospital utilisation in European healthcare systems remain limited. We examined temporal trends and severity-related hospital outcomes in Spain between 2016 and 2022.\nMETHODS: We conducted a retrospective, population-based analysis using the Spanish Minimum Basic Data Set, including all adult hospital episodes with a primary diagnosis of MG (ICD-10-ES G70.00, G70.01). Hospital admissions, day-hospital visits and emergency department (ED) encounters were evaluated. Variables included demographics, intensive care unit (ICU) admission, myasthenic crisis, in-hospital mortality and comorbidities. Temporal trends were analysed using segmented negative binomial regression models incorporating a breakpoint in 2018.\nRESULTS: A total of 20,251 MG-related episodes corresponding to 6,308 unique patients were identified. Following 2018, hospital admissions declined by 5.4% annually (95% CI − 8.4 to − 2.4), whereas day-hospital and ED utilisation increased markedly, particularly among older adults. In-hospital mortality remained low and stable (mean 2.6%). ICU admissions increased from 8.2% to 13.7% of hospitalised patients. Myasthenic crisis accounted for 4.5% of admissions and was strongly associated with ICU utilisation, representing 39% of all ICU stays.\nCONCLUSIONS: MG care in Spain is undergoing a sustained transition toward ambulatory management without evidence of worsening short-term hospital outcomes. Despite an ageing patient population and rising ICU utilisation, in-hospital mortality remained stable, supporting the safety of outpatient-based MG care models. These findings highlight the need for integrated clinical data to inform future healthcare planning in MG.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s42466-026-00485-5.", "authors": ["Garrido-Hernández Tania", "Del-Águila-Mejía Javier", "Rodríguez-Camacho Marta", "Martínez-Salmerón María Del Mar", "Vélez-Gómez Beatriz"], "journal": "Neurological research and practice", "entry_date": "2026/04/22 00:27", "pub_date": "2026-04-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42015252/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Hospital Universitario Torrecárdenas, Hermandad de Donantes de Sangre S/N Street, Almería, 04009, Andalusia, Spain."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "42011445", "title": "Bulbar Onset Generalized Myasthenia Gravis in an Elderly Patient: A Diagnostic Challenge.", "abstract": "Myasthenia gravis (MG) can present with variable and atypical symptoms, particularly in older adults, where isolated bulbar involvement may mimic stroke or motor neuron disease. We report a case of an elderly patient with late-onset, acetylcholine receptor (AChR) antibody-positive generalized myasthenia gravis who initially presented with ptosis, followed by progressive dysphagia and dysarthria, and subsequently developed head drop. Electromyography (EMG) confirmed a neuromuscular junction disorder, and serology demonstrated markedly elevated AChR antibodies. Early initiation of pyridostigmine and corticosteroids led to rapid clinical improvement, with the Myasthenia Gravis Activities of Daily Living (MG-ADL) score decreasing from 11/24 to 0/24 within three weeks. This case highlights the importance of considering MG in elderly patients presenting with isolated bulbar symptoms and demonstrates the diagnostic value of electrophysiology and antibody testing for timely treatment.", "authors": ["Abay Befkadu", "Mehjeba Moushumi", "Bajgamage Anushka", "Suman Sanjay"], "journal": "Cureus", "entry_date": "2026/04/21 03:59", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42011445/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Geriatrics, Medway NHS Foundation Trust, Gillingham, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "42008666", "title": "Failure of early B cell tolerance and possible BCR signaling dysregulation underlie NF155-mediated autoimmune nodopathies.", "abstract": "Autoimmune nodopathies (AINs) are rare acquired autoimmune neuropathies with distinct clinical features and circulating autoantibodies, often of the immunoglobulin G4 (IgG4) subclass, targeting proteins at the node of Ranvier. Defects in B cell tolerance checkpoints have been implicated in several autoimmune diseases, including MuSK-positive myasthenia gravis, another IgG4 autoantibody-mediated disease. Here, we investigated whether tolerance defects exist in neurofascin-155-mediated AIN (NF155-AIN), using a well-established assay, by generating recombinant antibodies from new emigrant (NE) and mature naive (MN) B cells from three NF155-AIN patients, and tested them for polyreactivity and autoreactivity. Additionally, we analyzed the transcriptome of peripheral blood mononuclear cells, with a particular focus on naive B cells and CD4+ T cells at the single-cell level, and characterized cell-cell interactions. NF155-AIN patients have an elevated frequency of polyreactive B cells in the NE (37.4% compared to 9.7% in healthy controls (HCs), P = 0.03) and MN (31.5% compared to 10.5% in HCs, P = 0.03) compartments, consistent with a breach in early B cell tolerance checkpoints. In this unbiased exploratory transcriptomics analysis, we observed potentially abnormal B cell receptor (BCR) signaling characterized by low CD79B, CSK, BLNK, and BTK expression, and possible impaired CD4+ T cell regulatory function. Moreover, comparison with chronic inflammatory demyelinating polyneuropathy, a related autoimmune neuropathy, suggested that these differences are specific to NF155-AIN. A breach in early B cell tolerance checkpoints, with defective BCR signaling, and disrupted T cell-B cell interactions in NF155-AIN, may contribute to the development of pathogenic autoreactivity.", "authors": ["Roy Bhaskar", "Obaid Abeer H", "Wang Zhenjian", "Kovacs Kristof G", "Ohashi Sarah", "Kalayci F Naz Cemre", "Joo Daniel", "Masi Gianvito", "Coppola Carmina", "Das Sameeran", "Hernandez Amanda L", "Martin-Aguilar Lorena", "Lleixà Cinta", "Nowak Richard J", "Querol Luis", "O'Connor Kevin C"], "journal": "Proceedings of the National Academy of Sciences of the United States of America", "entry_date": "2026/04/20 15:02", "pub_date": "2026-04-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42008666/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT 06510."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "42008094", "title": "Treatment Patterns in Patients with Late-Onset Myasthenia Gravis in Japan: An Insurance Claims Database Study.", "abstract": "BACKGROUND AND OBJECTIVE: This study evaluated treatment patterns and oral corticosteroid (OCS) use in Japanese patients with myasthenia gravis, comparing late-onset (mean age 79.8 years) and early/adult-onset (mean age 61.3 years) cohorts. It also explored treatment frequency rates.\nMETHODS: We conducted a retrospective analysis of the DeSC Healthcare claims database (2014-21). Adults with myasthenia gravis starting immunosuppressant therapy and with ≥ 2 years of follow-up were included. Patients were stratified by age group (< 75 and ≥ 75 years) and by exposure to early fast-acting treatment (EFT). Outcomes included OCS dose trajectories, time to achieve a maintenance dose of ≤ 5 mg/day, and the frequency of myasthenia gravis cases treated with immunotherapy.\nRESULTS: Early fast-acting treatment use was lower in the late-onset cohort (31/148 patients; 20.9%) than in the early-onset cohort (42/180; 28.0%). Initial and maximum OCS doses and time spent > 20 mg/day tended to be lower in late-onset patients. The OCS target was achieved more often and sooner in late-onset patients (median 5.1 vs 14.9 months), particularly in those without EFT. The frequency of treated myasthenia gravis cases was higher in late-onset patients (7.09 vs 3.97 per 100,000).\nCONCLUSIONS: Late-onset patients were less likely to receive EFT, received lower OCS doses yet reached the OCS target earlier, which may reflect physician caution with OCS exposure and good response to treatments. The findings highlight timely identification of the need for EFT, safer OCS-sparing strategies, and clearer clinical guidance in patients with late-onset myasthenia gravis.", "authors": ["Uzawa Akiyuki", "Samukawa Makoto", "Konno Shingo", "Mishiro Izumi", "Taki Kentaro", "Todaka Hiroshi", "Quelen Céline", "Jabłońska Katarzyna", "Majewska Renata", "Ohashi Yohei"], "journal": "Drugs - real world outcomes", "entry_date": "2026/04/20 11:08", "pub_date": "2026-04-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42008094/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "42005993", "title": "Thymoma-Associated Systemic Lupus Erythematosus and Myasthenia Gravis.", "abstract": "Thymomas, rare tumors originating from thymic epithelial cells, can disrupt immune tolerance and contribute to the development of autoimmune diseases. While thymomas are commonly associated with myasthenia gravis (MG), their link to autoimmune rheumatic diseases such as systemic lupus erythematosus (SLE) is less frequently observed. We present a case of a 32-year-old woman with SLE who was admitted with headache, blurred vision in her right eye with ptosis, generalized weakness, and dysphagia. She had been experiencing dysphagia and weakness for the past year, with symptoms intensifying in the three weeks leading up to admission. Her SLE had been diagnosed a year earlier, presenting with polyarthritis, positive antinuclear and anti-dsDNA antibodies, and low levels of C3 and C4. Inpatient laboratories revealed positive anti-acetylcholine receptor antibodies. A chest computed tomography (CT) scan revealed an anterior mediastinal mass invading the left pleural space as well as the left brachial and cephalic veins. A CT-guided biopsy of the mass confirmed a thymoma consistent with World Health Organization type AB. She was diagnosed with MG and thymoma. MG was managed with prednisone, pyridostigmine, and intravenous immunoglobulin. She underwent four cycles of neoadjuvant chemotherapy for her thymoma, with two additional cycles, with a modified treatment regimen, administered to enhance tumor reduction prior to surgery. She underwent thymectomy, pericardiectomy, venorrhaphy, and pneumorrhaphy and was initiated on radiation therapy due to tumor invasion of adjacent structures. At 12-month follow-up, her MG symptoms had completely resolved. As for her SLE, arthralgias persisted in the absence of arthritis, and no additional lupus manifestations developed. This case illustrates the diagnostic challenges posed by overlapping autoimmune disorders and emphasizes the need for careful evaluation to identify underlying malignancies, like thymoma, in patients presenting with atypical or evolving autoimmune symptoms.", "authors": ["González-Ramos Keysha", "Rivera-Burgos Ileana", "Cedeño Carlos", "Lafontaine Jean", "Marcos-Martínez María J", "Vilá Luis M"], "journal": "Case reports in rheumatology", "entry_date": "2026/04/20 07:43", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42005993/", "pub_types": ["Journal Article"], "affiliations": ["Division of Rheumatology, Department of Medicine, University of Puerto Rico School of Medicine, Medical Sciences Campus, San Juan, Puerto Rico, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "42004615", "title": "Perioperative use of eculizumab in patients with thymoma-associated myasthenia gravis: A preliminary case series of five patients.", "abstract": "Patients with myasthenia gravis (MG) are at risk of myasthenic crisis (MC) or clinical deterioration following thymectomy. Although eculizumab has demonstrated efficacy in the management of MC, its role in perioperative optimization for thymectomy in MG patients has not been systematically evaluated. To assess the efficacy of eculizumab in the perioperative management of thymectomy in MG patients, we included five patients with MG who received perioperative eculizumab treatment during thymectomy. Clinical features and perioperative data were comprehensively analyzed. Outcomes were assessed using the Quantitative Myasthenia Gravis (QMG), MG-Activities of Daily Living (MG-ADL), and Clinical Absolute Scores (CAS). Additionally, we measured acetylcholine receptor antibody (AChR-Ab) levels, total hemolytic complement (CH50), immunoglobulin G (IgG) concentrations, and lymphocyte subset percentages. In this study, from baseline to pre-surgery, all patients except patient 2 and patient 5 exhibited a reduction in QMG and CAS scores; Patients 2 and 5 showed no changes in MG-ADL scores, whereas Patients 1, 3, and 4 all demonstrated clinical improvement with reduced scores. All patients demonstrated decreased CH50 levels, fluctuating AChR-Ab levels and IgG levels. The thymectomy was performed smoothly, and the tracheal tube was removed promptly after surgery. No exacerbation of MG symptoms, postoperative myasthenic crisis (POMC), or serious complications occurred within 7 days post-surgery. In conclusion, these preliminary findings suggest that perioperative eculizumab may provide a feasible strategy for reducing the risk of POMC in MG patients. As a hypothesis-generating case series, further large-scale prospective studies are warranted to confirm these observations.", "authors": ["Ou Yaotong", "Wen Yi", "Liu Yiyi", "Lai Mingjun", "Wang Honghao", "Chen Xi", "Zhang Huili", "Peng Yu"], "journal": "IBRO neuroscience reports", "entry_date": "2026/04/20 07:31", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42004615/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, the Second Affiliated Hospital, School of Medicine, South China University of Technology, Guangzhou, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "42003220", "title": "Plasma Exchange as a Bridge to Recovery in Severe Pediatric Neurological Diseases in Pediatric Intensive Care.", "abstract": "BACKGROUND: Therapeutic plasma exchange (TPE) removes circulating pathogenic antibodies, immune complexes, cytokines, and complement components. While established in adult neurology, evidence on its safety and efficacy in pediatric neurocritical care remains limited.\nOBJECTIVE: To evaluate the indications, clinical efficacy, and safety of TPE in children with acute or subacute immune-mediated neurological disorders admitted to the pediatric intensive care unit (PICU).\nMETHODS: A retrospective cohort of 24 pediatric patients (aged 1-18 years) treated with TPE between February 2023 and October 2025 was analyzed. Diagnoses included multiple sclerosis (n = 8), Guillain-Barré syndrome (n = 5), acute disseminated encephalomyelitis (n = 3), transverse myelitis (n = 3), autoimmune encephalitis (n = 3), optic neuritis (n = 1), and myasthenia gravis (n = 1). Patients received 3-7 TPE sessions. Clinical response was measured using the modified Rankin Scale (mRS) and GBS disability scores before and after treatment.\nRESULTS: A total of 130 sessions were performed. Clinical improvement occurred in 20 of 24 patients (83%)-moderate in 8 (33%) and mild in 12 (50%). Median mRS/GBS scores decreased from 4.0 to 3.0 (p = 0.001). Early initiation of TPE (≤ 7 days from symptom onset) was associated with a higher likelihood of neurological improvement in multivariable analysis. No life-threatening complications were observed. Transient, reversible events included hypocalcemia (2.3%), hypotension (1.5%), and urticaria (1.6%).\nCONCLUSION: TPE appears to be a safe and potentially beneficial intervention for severe or refractory pediatric neuroimmunological disorders. Earlier initiation of TPE was associated with improved neurological outcomes; however, these findings should be interpreted cautiously given the small sample size and heterogeneous disease groups. These findings support integrating TPE into multidisciplinary PICU management and add to the growing evidence supporting its use in pediatric neuroimmunology.", "authors": ["Şık Güntülü", "Başak Gamze", "Kanar Tuğba", "Yüce Servet", "Güler Serhat", "Kılıç Hüseyin", "Saltık Sema"], "journal": "Therapeutic apheresis and dialysis : official peer-reviewed journal of the International Society for Apheresis, the Japanese Society for Apheresis, the Japanese Society for Dialysis Therapy", "entry_date": "2026/04/20 02:43", "pub_date": "2026-04-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42003220/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatric Intensive Care, İstanbul University-Cerrahpaşa, Cerrahpaşa Faculty of Medicine, İstanbul, Türkiye."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "42000538", "title": "Impact of a ketogenic diet on clinical outcomes and immunological markers in myasthenia gravis: A randomized pilot study.", "abstract": "OBJECTIVE: Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by fluctuating weakness and disabling fatigue. This pilot study assessed the feasibility and explored potential clinical and immunological effects of a ketogenic diet (KD) in generalized MG.\nMETHODS: In a randomized, controlled, open-label 12-week pilot study, adults with generalized MG were assigned to a KD (n = 20) or to continue their habitual diet (n = 21). The primary endpoint was change in Myasthenia Gravis-Activities of Daily Living (MG-ADL). Secondary outcomes included Quantitative Myasthenia Gravis score (QMG), MGFA class, Fatigue Severity Scale (FSS), Myasthenia Gravis Quality of Life (MG-QoL15r), Patient Acceptable Symptom State (PASS), serum calprotectin (sCLP), serum neurofilament light chain (sNfL), and T-cell subsets. Analyses were conducted descriptively using effect sizes and 95% confidence intervals.\nRESULTS: Numerical improvements were observed in the KD group compared to controls. MG-ADL decreased (median Δ -2; moderate effect size, 95% CI including zero). QMG improved (median Δ -3; effect size 1.29, 95% CI 0.55-2.02), and fatigue decreased (median Δ -7; effect size 1.19, 95% CI 0.45-1.91). MG-QoL15r and PASS remained stable in the intervention group but worsened in controls. sCLP showed a numerical decrease, while sNfL remained unchanged. Adherence, defined as study completion, was 75%.\nCONCLUSION: A ketogenic diet is feasible and safe. Numerical improvements in clinical outcomes, and exploratory immunological changes were observed. Given the exploratory design findings should be interpreted with caution and require confirmation in larger, blinded studies.", "authors": ["Makus Benjamin", "Schulze Daniel", "Lehnerer Sophie", "Gerischer Lea", "Stein Maike", "Doksani Paolo", "Dusemund Carla", "Hoffmann Sarah", "Meisel Andreas", "Stascheit Frauke"], "journal": "Journal of autoimmunity", "entry_date": "2026/04/18 23:01", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/42000538/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology with Experimental Neurology, Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41999078", "title": "Digital Phenotyping and Lifestyle Intervention in Patients With Myasthenia Gravis (DIG-MG): A Randomized Controlled Trial of Feasibility, Adherence, and Effects on Fatigue.", "abstract": "INTRODUCTION/AIMS: Physical activity and sleep influence fatigue in myasthenia gravis (MG), and digital health technologies (DHT) enable objective monitoring of these behaviors in daily life. Using this approach, we evaluated whether a lifestyle intervention targeting physical activity or sleep hygiene could reduce fatigue in MG.\nMETHODS: In this three-arm, randomized controlled trial (DIG-MG; NCT05992025), 72 MG patients completed 6 weeks of baseline monitoring with a DHT ring (OURA), followed by 12 weeks of (i) physical activity guidance, (ii) sleep hygiene education, or (iii) observation, and a 6-week follow-up. The primary outcome was the MG Activities of Daily Living (MG-ADL) score 1 week postintervention. Secondary outcomes included Fatigue Severity Scale (FSS) scores; exploratory outcomes were DHT-derived physical activity and sleep parameters.\nRESULTS: Baseline MG-ADL scores were similar (median: 5.0). Postintervention medians were 4.0 (physical activity), 3.5 (sleep hygiene), and 3.0 (control), with no significant differences (p = 0.073). Clinically meaningful MG-ADL improvement occurred in six, seven, and six participants, respectively. FSS scores showed no group differences (p = 0.992), with clinically relevant improvement in eight participants in each intervention group and five controls. Participants were more physically active than expected: 64.7% exceeded 600 MET-min/week at baseline. DHT adherence was excellent. REM sleep was lower than expected, while deep sleep was preserved. Self-reported data aligned with DHT measurements.\nDISCUSSION: Digital lifestyle interventions were feasible and well-accepted but did not improve MG-ADL or FSS in this unusually active population. However, DHT-based monitoring may support individualized follow-up, and reduced REM sleep warrants further investigation as a fatigue-related factor.", "authors": ["Norling Maja", "Eriksson Niclas", "Westerberg Elisabet", "Nygren Ingela", "Norman Klara", "Hedberg Julia", "Wong Sui H", "Jernelöv Susanna", "Åsenlöf Pernilla", "Punga Anna Rostedt"], "journal": "Muscle & nerve", "entry_date": "2026/04/18 02:43", "pub_date": "2026-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41999078/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Clinical Neurophysiology, Department of Medical Sciences, Uppsala University, Uppsala, Sweden."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41998298", "title": "Enhanced antibody detection via live cell-based assay among RIA negative myasthenia gravis patients: toward improved diagnosis and clinical correlates.", "abstract": "BACKGROUND: Radioimmunoprecipitation assay (RIA) is the gold standard for antibody detection in myasthenia gravis (MG), while fixed cell-based assays (CBAs) are widely used as second-line or first-line tests. Live CBA represents an alternative approach and its combined use with fixed CBA may improve diagnostic sensitivity. Our aim was to evaluate the diagnostic yield of fixed and live CBA for AChR and MuSK antibodies in a large cohort of RIA seronegative MG patients and to investigate clinical associations and outcomes.\nMETHODS: Sera from 124 AChR- and MuSK-RIA seronegative MG patients and 72 control samples were tested using fixed CBA for fetal and adult AChR isoforms and MuSK. All sera were also analyzed with an in-house live CBA, with cells expressing clustered AChR or MuSK.\nRESULTS: Fixed CBA identified AChR antibodies in 3/124 (2.4%) patients, all with mild early-onset MG; none were MuSK positive. Live CBA detected AChR antibodies in 11 (8.9%) and MuSK antibodies in 13 (10.5%) patients. Live CBA seronegative patients were predominantly female (77/100, 77%) compared with AChR-live (4/11, 36.4%) and MuSK-live (7/13, 53.8%) groups (p = 0.0068), and more frequently had generalized MG (87% vs 53.8% in MuSK-live; p = 0.0146). Unchanged or worsened MGFA-PIS occurred in 4/13 (30.8%) of MuSK-live patients and 18/82 (21.9%) of live CBA seronegative patients, whereas all AChR-live CBA patients achieved minimal manifestations or better.\nCONCLUSION: Live CBA identifies AChR or MuSK antibodies in approximately 20% of RIA seronegative MG patients and provides clinically meaningful subgroup stratification. Fixed CBA performed only slightly better than RIA.", "authors": ["Rinaldi Elena", "Puleo Elisa", "Di Maro Angela", "Fusco Raffaele", "Canciello Amalia", "Giacopuzzi Grigoli Eleonora", "Frangiamore Rita", "Cheli Marta", "Vanoli Fiammetta", "Bonanno Silvia", "Mantegazza Renato", "Antozzi Carlo", "Baggi Fulvio", "Andreetta Francesca", "Maggi Lorenzo"], "journal": "Journal of neurology", "entry_date": "2026/04/17 23:26", "pub_date": "2026-04-18", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41998298/", "pub_types": ["Journal Article"], "affiliations": ["Neurology 4-Neuroimmunology and Neuromuscular Diseases Unit, Fondazione IRCCS Istituto Neurologico Carlo Besta, Milan, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41995788", "title": "Comment on: 'Association between obesity and subsequent risk of myasthenia gravis: a nationwide population-based cohort study'.", "abstract": "", "authors": ["Sökmen Okan"], "journal": "Acta neurologica Belgica", "entry_date": "2026/04/17 11:06", "pub_date": "2026-04-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41995788/", "pub_types": ["Letter"], "affiliations": ["Department of Neurology, Atatürk Sanatoryum Research and Training Hospital, Ankara, Türkiye. drokansokmen@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41994709", "title": "Massive Bilateral Pulmonary Embolism Presenting as Isolated Abdominal Pain: An Atypical Presentation and Incidental Detection in Dual Immune-Mediated Disease.", "abstract": "Pulmonary embolism (PE) is a potentially life-threatening condition that classically presents with chest pain, tachycardia, and dyspnea. Atypical manifestations such as gastrointestinal symptoms may occur, particularly in elderly patients with multiple comorbidities that can potentially skew and delay diagnosis. We report the case of a 79-year-old woman with a history of multiple myeloma and myasthenia gravis who presented with acute-onset abdominal pain with nausea and vomiting. Computed tomography (CT) of the abdomen and pelvis was obtained to evaluate suspected intra-abdominal pathology that incidentally detected pulmonary arterial filling defects in the right lower lobe of the lung. Subsequent CT pulmonary angiography confirmed extensive bilateral pulmonary emboli. The patient was urgently transferred to a tertiary care center for mechanical pulmonary thrombectomy with successful hemodynamic stabilization. This case highlights an atypical presentation of life-threatening PE that presented predominantly with gastrointestinal symptoms and was incidentally identified on abdominal imaging. Clinicians should maintain a high index of suspicion for PE in patients with unexplained gastrointestinal complaints, particularly in the setting of comorbidities such as malignancy and autoimmune disease that may mimic symptoms.", "authors": ["Marhaba Rani", "Sriparna Manjari", "Hamzane Mohamed", "Kalani Sonya", "Blaney Shannon"], "journal": "Cureus", "entry_date": "2026/04/17 05:35", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41994709/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Montefiore Medical Center, Bronx, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41993176", "title": "Exploring medication adherence and illness perception in patients with neuroimmune diseases: a cross-sectional study.", "abstract": "OBJECTIVE: Neuroimmune diseases (NIDs) including myasthenia gravis (MG), multiple sclerosis (MS), and neuromyelitis optica spectrum disorder (NMOSD) require long-term medication adherence to optimize prognosis. This study aimed to investigate factors influencing medication adherence and its association with illness perception among NIDs patients.\nMETHODS: A cross-sectional survey was conducted at the Outpatient Department of Neurology, West China Hospital, Sichuan University, from March to August 2025. Patients with clinically diagnosed MG, MS, or NMOSD and ≥ 6 months of treatment were enrolled. The questionnaire on basic information, the Eight-Item Morisky Medication Adherence Scale (MMAS-8), and the Brief Illness Perception Questionnaire (BIPQ) were used for data collection. SPSS 27.0, Prism and hiplot.cn were used for statistical analysis and illustration.\nRESULTS: A total of 137 valid questionnaires were collected via face-to-face interviews. Univariate analyses showed significant differences in illness perception (F = 43.969, P < 0.001), disease duration (F = 4.182, P = 0.017), and average income (χ² = 16.590, P < 0.001) across adherence subgroups. Multiple linear regression identified illness perception (P < 0.001) and average income (P = 0.003) as independent predictors, with cognitive (P < 0.001) and emotional representations (P = 0.008) exerting negative effects. Subgroup analyses revealed illness perception as the primary predictor in MG/MS patients, while income additionally affected NMOSD patients (P = 0.014). Low and moderate income patients were respectively influenced by emotional and cognitive representations.\nCONCLUSION: Illness perception and average income are key factors affecting medication adherence in NIDs patients, with diseases and income disparities. Individualized education targeting cognitive and emotional perceptions, along with economic considerations in treatment, may improve long-term outcomes.", "authors": ["Fu Ruizi", "Wang Xiaofei", "Shi Ziyan", "Wang Rui", "Zhou Hongyu"], "journal": "Frontiers in immunology", "entry_date": "2026/04/17 05:16", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41993176/", "pub_types": ["Journal Article"], "affiliations": ["West China School of Medicine, Sichuan University, Chengdu, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41993163", "title": "Case report: Efgartigimod combined with intravenous methylprednisolone in a case of co-occurrence of unexplained myasthenia gravis, inflammatory myopathy, and fulminant myocarditis.", "abstract": "The co-occurrence of myasthenia gravis (MG), inflammatory myopathy (IM), and fulminant myocarditis (FM) has rarely been reported. The few previous articles were mostly case reports or small sample data analysis, and the etiology was mostly attributed to thymoma and/or the application of immune checkpoint inhibitors (ICIs). We report a 74-year-old woman with an acute onset of general weakness, chest tightness, shortness of breath, dysarthria, masticatory weakness and dysphagia, without myalgia or rash. Acetylcholine receptor antibody was positive. Serum creatine kinase, transaminase, and myoglobin were higher than normal. A variety of autoimmune antibodies including anti-Ro-52, JO-1, nRNP and dsDNA antibodies were positive. Chest CT showed no thymoma, bronchiectasis with infection in both lungs. Some of them showed interstitial changes. Electromyography repetitive nerve stimulation of the bilateral deltoid muscle demonstrated a decremental response at low frequencies without an incremental response at high frequencies. Needle electromyography revealed spontaneous potentials. Echocardiography showed that left ventricular wall motion was generally reduced, left ventricular systolic function was reduced, and cardiac function was EF18%. Muscle biopsy suggested myogenic injury. The patient was diagnosed with MG-IM-FM coexisting without thymoma and without ICIs. After treatment with Efgartigimod combined with intravenous methylprednisolone, the symptoms were relieved, serum creatine kinase, myoglobin and other laboratory indicators and cardiac function returned to normal. MG-IM-FM is a complex disease with rapid onset, rapid progression and critical condition. Clinicians should be on high alert and early intervention is the key to improve the prognosis. The immune mechanism of its occurrence is still unclear and needs to be further studied. Traditional glucocorticoid is still the first-line drug, but the new targeted drug Efgartigimod has less adverse reactions and faster onset of action, which may become a good choice, but needs to be verified by a larger sample.", "authors": ["Yang Hongxia", "Pan Zulin", "Yang Ying", "Wang Yaxuan", "Cheng Biqi", "Qi Guoyan"], "journal": "Frontiers in immunology", "entry_date": "2026/04/17 05:16", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41993163/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Center of Treatment of Myasthenia Gravis, Shijiazhuang People's Hospital, Shijiazhuang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41992576", "title": "Adaptive Therapeutic Plasma Exchange Technologies in Low-resource Settings: Utilization, Safety, and Clinical Insights from 2507 Neurological Cases.", "abstract": "BACKGROUND: Therapeutic plasma exchange (TPE) is an established immunomodulatory therapy with proven efficacy in a wide range of neurological disorders. In recent years, expanding indications, combined with cost-effectiveness and a favorable safety profile, have increased their relevance, particularly in low-resource settings where access to intravenous immunoglobulin may be limited. This study analyzes our institutional experience with TPE in the management of diverse neurological conditions.\nMATERIALS AND METHODS: We conducted a retrospective observational study over a 5-year period (January 2015-December 2019) at the transfusion medicine department of a tertiary care neurological center. TPE was performed with a target plasma removal of 150-200 mL/kg body weight per session, using appropriate replacement fluids. Data regarding patient demographics, neurological indications, American Society for Apheresis indication categories, number of procedures, and procedure-related complications were analyzed.\nRESULTS: A total of 13,387 TPE procedures were performed in 2507 patients, with ages ranging from 9 to 86 years (mean age: 38.18 years). Guillain-Barré syndrome was the most common indication, accounting for 56.20% of cases, followed by other immune-mediated neurological disorders. Hypotension was the most frequently observed adverse event. Importantly, no procedure-related mortality was recorded during the study period.\nCONCLUSION: Therapeutic plasmapheresis is a safe, effective, and adaptable treatment modality for a broad spectrum of neurological disorders. Its favorable safety profile and clinical utility support its role as a valuable and sustainable therapeutic option, particularly in low-resource healthcare settings.\nRésumé Contexte:L’échange plasmatique thérapeutique (TPE) est une thérapie immunomodulatrice établie dont l’efficacité est prouvée dans un large éventail de troubles neurologiques. Ces dernières années, l’expansion des indications, combinée à un rapport coût-efficacité et à un profil d’innocuité favorable, a accru leur pertinence, en particulier dans les contextes à faibles ressources où l’accès aux immunoglobulines intraveineuses peut être limité. Cette étude analyse notre expérience institutionnelle avec l’ETP dans la prise en charge de diverses affections neurologiques.Matériels et méthodes:Nous avons mené une étude observationnelle rétrospective sur une période de 5 ans (janvier 2015-décembre 2019) au service de médecine transfusionnelle d’un centre neurologique de soins tertiaires centre. L’ETP a été réalisée avec une élimination plasmatique cible de 150 à 200 ml/kg de poids corporel par séance, en utilisant des liquides de remplacement appropriés. Les données concernant les données démographiques des patients, les indications neurologiques, les catégories d’indications de l’American Society for Apheresis, le nombre d’interventions et les complications liées à l’intervention ont été analysées.Résultats:Au total, 13 387 procédures d’ETP ont été réalisées chez 2 507 patients, âgés de 9 à 86 ans (âge moyen : 38,18 ans). Le syndrome de Guillain-Barré était l’indication la plus fréquente, représentant 56,20 % des cas, suivis par d’autres troubles neurologiques à médiation immunitaire. L’hypotension était l’événement indésirable le plus fréquemment observé. Il est important de noter qu’aucune mortalité liée à l’intervention n’a été enregistrée au cours de la période d’étude.Conclusion:La plasmaphérèse thérapeutique est une modalité de traitement sûre, efficace et adaptable pour un large spectre de troubles neurologiques. Son profil d’innocuité favorable et son utilité clinique confortent son rôle en tant qu’option thérapeutique précieuse et durable, en particulier dans les contextes de soins de santé à faibles ressources.", "authors": ["Kumawat Vijay", "Tripathi Parmatma Prasad", "Vittal Vidyashree Anchan"], "journal": "Annals of African medicine", "entry_date": "2026/04/17 01:23", "pub_date": "2026-04-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41992576/", "pub_types": ["Journal Article"], "affiliations": ["Department of Transfusion Medicine and Haematology, National Institute of Mental Health and Neurosciences, Bengaluru, Karnataka, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41992404", "title": "Differential Toxicity of Immune Checkpoint Inhibitors in Older Adults: A Large-Scale, Propensity Score-Matched Real-World Analysis.", "abstract": "BACKGROUND: The risk-benefit profile of immune checkpoint inhibitors (ICIs) in the understudied elderly population (≥75 years) remains poorly defined. We characterized clinical outcomes and immune-related adverse events (irAEs) in this population using a large real-world dataset.\nMETHODS: Using the TriNetX network, we identified cancer patients initiating ICIs, creating two cohorts: ≥75 and 18-74 years. After 1:1 propensity score matching (PSM), we compared overall survival, all-cause hospitalization, and 5-year irAE risk.\nRESULTS: We matched 37,417 older patients to 37,417 younger controls. Older adults had worse overall survival (median 753 vs 955 days; HR 1.15; 95% CI 1.13 - 1.18). Paradoxically, they had lower risks for endocrine (RR 0.86; 95% CI 0.83 - 0.89) and gastrointestinal (RR 0.80; 95% CI 0.76 - 0.84) events. However, risks significantly increased for myocarditis (RR 1.27; 95% CI 1.05 - 1.53), myasthenia gravis (RR 2.38; 95% CI 1.76 - 3.21), polymyalgia rheumatica (RR 2.12; 95% CI 1.62 - 2.76), pemphigoid (RR 2.05; 95% CI 1.58 - 2.67), and acute kidney injury (RR 1.09; 95% CI 1.05 - 1.13).\nCONCLUSION: Patients ≥75 years exhibited poorer survival and a unique irAE profile characterized by lower overall incidence but heightened risk of specific, highly morbid toxicities. These findings highlights the need for age-specific vigilance in geriatric oncology.", "authors": ["Awidi Muhammad", "Al Zyoud Muntaser", "Bader Noor S", "Al-Alwan Ahmad", "Junaid Tariq Muhammad"], "journal": "Cancer investigation", "entry_date": "2026/04/17 00:26", "pub_date": "2026-04-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41992404/", "pub_types": ["Journal Article"], "affiliations": ["Department of Hematology and Medical Oncology, Charleston Area Medical Center (CAMC), Charleston, West Virginia, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41989988", "title": "Efgartigimod as Rescue Therapy for PD-1 Inhibitor-Associated Myasthenia Gravis, Myocarditis, and Myositis (MMM) Syndrome: A 2-Case Report and Literature Review.", "abstract": "BACKGROUND The combination of myasthenia gravis, myocarditis, and myositis (MMM) overlap syndrome caused by PD-1 inhibitors is rare and has a high death rate. The most effective immunomodulatory therapy is yet to be determined. Efgartigimod is approved for treating generalized myasthenia gravis, but there is limited evidence for its effectiveness in PD-1 inhibitor-induced MMM syndrome. This study aimed to evaluate the effectiveness of adjunctive efgartigimod for MMM syndrome through 2 severe cases and a focused literature review. CASE REPORT After PD-1 inhibitor therapy, 2 patients quickly experienced severe MMM syndrome. Both individuals experienced drooping eyelids, muscle weakness affecting speaking and swallowing, rapidly worsening respiratory failure requiring mechanical ventilation, and inflammation of the heart and muscles. In patient 1, whose anti-acetylcholine receptor antibody was positive, efgartigimod (800 mg weekly ×4) was started after a limited response to high-dose corticosteroids, intravenous immunoglobulin, and plasmapheresis. On day 22, he was taken off the ventilator, and his serum creatine kinase and troponin I levels decreased by over 90% from their highest points. In patient 2, whose anti-titin antibody was positive, efgartigimod led to an approximately 80% decline in cardiac enzymes and allowed longer daily periods off the ventilator (up to 6 hours by day 74); however, the overall intensive care course remained prolonged. CONCLUSIONS Efgartigimod could be a promising additional treatment for MMM syndrome induced by PD-1 inhibitors when standard immunosuppressive therapies show limited response. Nonetheless, in titin-predominant phenotypes, responses might be reduced, necessitating prospective studies to determine patient selection, ideal timing, and the safety of efgartigimod.", "authors": ["Liu Zi-Han", "Duan Li-Min", "Fang Xiang-Zhi", "Jiang Wen", "Sun Sheng-Wen", "Shang You", "Huang Chao-Lin", "Yuan Yin"], "journal": "The American journal of case reports", "entry_date": "2026/04/16 13:23", "pub_date": "2026-04-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41989988/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Critical Care Medicine, Wuhan Jinyintan Hospital, Tongji Medical College of Huazhong University of Science and Technology; Hubei Clinical Research Center for Infectious Diseases, Wuhan Research Center for Communicable Disease Diagnosis and Treatment, Chinese Academy of Medical Sciences; Joint Laboratory of Infectious Diseases and Health, Wuhan Institute of Virology and Wuhan Jinyintan Hospital, Chinese Academy of Sciences, Wuhan, Hubei, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41987131", "title": "Sleep disorders in patients with myasthenia gravis based on antibody subtypes: a polysomnographic study.", "abstract": "BACKGROUND: Sleep-disordered breathing (SDB) is increasingly recognized in myasthenia gravis (MG), yet potential differences in sleep respiratory patterns between antibody-defined MG subtypes remain poorly understood. We aimed to evaluate sleep disorders and polysomnographic characteristics in patients with acetylcholine receptor antibody–positive (AChR-MG) and muscle-specific tyrosine kinase antibody–positive (MuSK-MG) generalized MG.\nMETHODS: Eighteen clinically stable MG patients (9 AChR-MG, 9 MuSK-MG) and 9 healthy controls underwent attended overnight polysomnography followed by the Multiple Sleep Latency Test (MSLT). Standardized sleep questionnaires and MG clinical scales were administered to assess sleep-related symptoms and disease severity.\nRESULTS: Obstructive sleep apnea was detected in 89% of AChR-MG and 78% of MuSK-MG patients. Both MG subgroups showed significantly higher apnea–hypopnea index values compared with controls (p < 0.05). Although overall AHI severity did not differ significantly between antibody groups, distinct respiratory patterns were observed. Respiratory events clustered predominantly during REM sleep in AChR-MG, whereas MuSK-MG patients exhibited more frequent events during NREM or supine sleep.\nCONCLUSIONS: Sleep-disordered breathing appears to be common in MG, but polysomnographic patterns may differ according to antibody subtype. REM-predominant respiratory events in AChR-MG and NREM or positional predominance in MuSK-MG may reflect differences in muscle involvement between these subtypes. These findings suggest that antibody-specific mechanisms may influence nocturnal respiratory dysfunction in MG and highlight the importance of targeted sleep assessment in this population.", "authors": ["Arslan Beyza", "Uluc Kayihan", "Agan Kadriye", "Koytak Pinar Kahraman", "Sunter Gulin"], "journal": "BMC neurology", "entry_date": "2026/04/16 01:08", "pub_date": "2026-04-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41987131/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology & Clinical Neurophysiology, Van Yuzuncu Yil University Medical Faculty, Van, Turkey."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41983870", "title": "Complement Inhibition Therapy in Myasthenic Crisis-A Multicentre Retrospective Analysis of 17 Cases From Germany.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) may progress to life-threatening myasthenic crises (MC) requiring mechanical ventilation. Standard therapy includes intravenous immunoglobulins (IVIg), plasmapheresis (PLEX), immunoadsorption (IA), and high-dose corticosteroids. This study aimed to evaluate the real-world effectiveness of complement-inhibitors (C5-I) in patients refractory to the standard treatment of MC (termed therapy-refractory MC).\nMETHODS: This multicentre, retrospective study included patients with acetylcholine-receptor-antibody positive (AChR-ab+) gMG experiencing MC or severe exacerbations (MGFA IVb/V) treated with eculizumab or ravulizumab in the intensive or intermediate care unit (ICU/IMC). The primary outcome was the proportion of patients discharged from ICU/IMC within six weeks after C5-I initiation (German Clinical Trials Registry; DRKS00032104).\nRESULTS: Among 17 identified cases, seven had thymoma-associated MG (TAMG) and 10 had late-onset MG; median age was 77 years. Five patients required non-invasive and 12 invasive ventilation; nine underwent tracheotomy. Therapies included IVIg, PLEX, IA, and corticosteroids. Rituximab was added in two cases. Twelve patients received eculizumab and five ravulizumab. Median hospitalization before C5-I initiation was 32 days (IQR 22-50) and median ICU-stay was 17 days (IQR 4.5-35) thereafter. Fourteen patients (82%) reached the primary outcome. Two patients died due to bacterial sepsis; no meningococcal infection was observed.\nCONCLUSION: In MC or severe exacerbations insufficiently responsive to standard treatment with IVIg and PLEX/IA, add-on C5-I therapy may represent an effective therapeutic approach. Importantly, TAMG, a subtype typically excluded from interventional trials yet often requiring more intensive therapy, also demonstrated clinical improvement. These findings warrant further systematic evaluation of C5-I as adjunctive therapy for AChR-ab+ therapy-refractory MC.", "authors": ["Gerischer Lea", "Stein Maike", "Schneider Alice", "Tangen Hanna", "Loris Johanna", "Glaubitz Stefanie", "Zschüntzsch Jana", "Oy Ulrich Hofstadt-van", "Schubert Charlotte", "Heesen Christoph", "Schlag Melina", "Hagenacker Tim", "Oeztuerk Menekse", "Ruck Tobias", "Doksani Paolo", "Dusemund Carla", "Herdick Meret", "Herzig-Nichtweiß Julia", "Mergenthaler Philipp", "Stascheit Frauke", "Suboh Amani", "Schwarz Lisa", "Hoffmann Sarah", "Meisel Andreas", "Lehnerer Sophie"], "journal": "European journal of neurology", "entry_date": "2026/04/15 09:44", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41983870/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology With Experimental Neurology, Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41982618", "title": "Reframing thymic epithelial tumors through single-cell transcriptomics: a narrative review.", "abstract": "BACKGROUND AND OBJECTIVE: Thymic epithelial tumors (TETs) are rare neoplasms originating from thymic epithelial cells (TECs). They exhibit histological, molecular, and immunological diversity shaped by aberrant interactions between neoplastic TECs and immune cells. World Health Organization (WHO) histological classification effectively captures their clinicopathological features, whereas inter- and intra-subtype heterogeneity persists. In this point, single-cell transcriptomics is well-suited to resolve cellular heterogeneity in TETs. This narrative review synthesizes findings from recent single-cell studies that illuminate epithelial subpopulations, intra-tumoral immune landscape, and disease-specific aberrations such as myasthenia gravis (MG)-associated phenotypes in TETs.\nMETHODS: We conducted a focused narrative review on three key studies that applied single-cell RNA sequencing (scRNA-seq) to primary human TETs.\nKEY CONTENT AND FINDINGS: Single-cell analyses identified a distinct TEC subpopulation ectopically expressing neuromuscular antigens, termed neuromuscular medullary TECs (nmTECs), in MG-associated thymomas, implicating aberrant antigen presentation and immune cell recruitment in autoantibody production. Other studies delineated tumor epithelial programs that shape the immune microenvironment, linking TEC transcriptional identities to the persistence of immature T-cells or dominance of mature T-cells. Bioinformatic approaches of ligand-receptor networks supported pathogenic crosstalk between neoplastic TECs and immune cells. Notably, independent groups converged on functionally oriented classifications that align across studies, stratifying TETs by epithelial lineage programs and immune composition with correspondence to biological behavior and prognosis.\nCONCLUSIONS: Single-cell approaches have revealed TET heterogeneity encompassing abnormal epithelial cell states, immune development trajectories, and autoimmune-associated molecular programs with high resolution. The ongoing accumulation of single-cell transcriptomics datasets would refine a cell-centric framework for TET classification and pathogenesis, while also deepening insight into normal TEC biology.", "authors": ["Matsumoto Minoru", "Saijo Yasuyo", "Tsuneyama Koichi", "Oya Takeshi"], "journal": "Mediastinum (Hong Kong, China)", "entry_date": "2026/04/15 04:28", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41982618/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Molecular Pathology, Tokushima University Graduate School of Biomedical Sciences, Tokushima, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41979428", "title": "Insufficient immunosuppressive treatment in patients with myasthenia gravis in the context of the possibility of new therapies - a single center experience.", "abstract": "AIM OF THE STUDY: The authors aimed to characterize the population with myasthenia gravis (MG), focusing on their eligibility for a therapeutic program with terminal complement protein C5 inhibition (ravulizumab), neonatal Fc receptor (FcRn) modulation (efgartigimod), and with anti-cluster of differentiation 20 (anti-CD20) monoclonal antibody rituximab reimbursed by the Polish National Health Fund (NFZ), and also to create a database with clinical and epidemiological details of a large MG population.\nCLINICAL RATIONALE FOR THE STUDY: Myasthenia gravis is a rare, life-threatening autoimmune neurological disease and, as such, is usually treated with traditional immunosuppressants. The therapeutic program enables the use of advanced agents, but the eligibility criteria are highly restrictive. It is not known how many patients may be eligible for treatment with advanced therapies since the available data is sparse.\nMATERIAL AND METHODS: The authors reviewed the clinical files of all 82 hospitalizations (of 65 patients) due to MG at the Department of Neurology of Poznan University Hospital between January 2023 and May 2025. Collected data included: age, gender, reason for admission, treatment before and after hospitalization with doses, The Myasthenia Gravis-Activities of Daily Living scale (MG-ADL), and Myasthenia Gravis Foundation of America (MGFA) scores on admission, treatment with intravenous immunoglobulin (IVIG)/plasmapheresis during hospitalization, data describing the autoimmunologic and comorbidities profile of each patient. Furthermore, the authors explored whether patients fulfilled the therapeutic program enrollment criteria: 1) history of glucocorticoids (GCS) therapy for at least 6 months (at least 3 months of 30 mg of prednisone daily); 2) history of using two drugs from the class of non-steroidal immunosuppressive drugs, including one for at least 12 months and the other for at least 6 months. Statistical analyses were conducted using JASP software (University of Amsterdam, the Netherlands).\nRESULTS: Among 65 patients, the median age was 64 years, 57% were women, and 94% had at least one comorbidity. During 82 hospitalizations, the authors used IVIG 23 times, plasmapheresis 8 times, and a combination of these therapies 3 times. In only 6.1% of hospitalized patients, there was a proven history of adequate oral steroid therapy, and no patient fulfilled definitively the criterion for a history of treatment with two non-steroidal immunosuppressive drugs.\nCONCLUSIONS AND CLINICAL IMPLICATIONS: Only a small percentage of patients are eligible for the therapeutic program as an indication of insufficient immunosuppressive treatment of MG before hospitalization.", "authors": ["Rajczewski Aleksander", "Kania Karolina", "Kozubski Wojciech", "Michalak Sławomir", "Ambrosius Wojciech"], "journal": "Neurologia i neurochirurgia polska", "entry_date": "2026/04/14 09:43", "pub_date": "2026-04-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41979428/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurochemistry and Neuropathology, Institute of Neurological Disorders, Poznan University of Medical Sciences, Poznan, Poland. aleksander.rajczewski@gmail.com."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "41974154", "title": "Clinical Characteristics of Childhood-Onset Myasthenia Gravis in a Large Chinese Cohort.", "abstract": "BACKGROUND: Among the new cases of myasthenia gravis in China, the proportion of new childhood-onset myasthenia gravis (CMG) patients ranges from 10.3% to 12.6% and is increasing annually. Nevertheless, it remains a rare disease with limited extensive cohort studies. This study aimed to summarize and describe the clinical characteristics of CMG patients in China.\nMETHODS: We reviewed the data from CMG patients treated at the Center for Myasthenia Gravis in Hebei Province between 2013 and 2023 and finally included data from 1031 patients.\nRESULTS: The gender ratio (male: female) was 1:1.4 and the median age of onset was 5 years, with a single peak at ages 1-3 years. Within the cohort, family history accounted for 1.7% (18/1031) of the patients. Furthermore, common cold was the most prevalent medical history factor in the cohort, accounting for 4.8% of the total patients. Overall, 62.4% (643/1031) and 0.5% (5/1031) of patients tested positive for acetylcholine receptor antibodies (AChR-Abs) and muscle-specific kinase antibodies (MuSK-Abs), respectively. In addition, the AChR-/MuSK-Ab-double positive rate was 0.1% (1/1031), whereas that for MuSK/AChR-Ab double negativity was 37.25% (384/1031). The Myasthenia Gravis Foundation of America (MGFA) I classification grade was high across all age groups, with the remaining classification grades increasing with age. In addition, ocular weakness as an initial symptom was high across all age groups, and as the age of the patients increased, the proportion of patients with weakness in the limbs, bulbar, and respiratory also increased. Finally, the AChR-Ab titer level was lowest in patients with MGFA I classification and may be related to prognosis.\nCONCLUSIONS: CMG has a peak incidence at ages 1-3 years, with some familial predisposition and a predominance of high MGFA I classification and AChR-Ab positivity. The complexity of the initial symptoms in CMG patients is related to increasing age. Interestingly, the AChR-Ab titer levels may be a potential factor in predicting patient prognosis.", "authors": ["Dong Huimin", "Li Mengna", "Ma Mei", "Gu Shanshan", "Liu Peng", "Qi Guoyan"], "journal": "Pediatric neurology", "entry_date": "2026/04/13 18:55", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41974154/", "pub_types": ["Journal Article"], "affiliations": ["Center of Treatment of Myasthenia Gravis, People's Hospital of Shijiazhuang, Shijiazhuang, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "41973420", "title": "Economic Evaluation of Thymectomy for the Treatment of Nonthymomatous Myasthenia Gravis.", "abstract": "IMPORTANCE: Myasthenia gravis (MG) is a chronic autoimmune disease that significantly impairs patients' quality of life by causing fluctuating muscle weakness and fatigue. While pharmacological treatment with corticosteroids remains a cornerstone of treatment, long-term use is often associated with substantial adverse effects. Although thymectomy is an established and effective alternative and adjunct to pharmacological treatment, its long-term cost-effectiveness within the UK National Health Service (NHS) is unknown.\nOBJECTIVE: To evaluate the cost-effectiveness of thymectomy in addition to prednisolone therapy compared with prednisolone therapy alone for patients with nonthymomatous MG.\nDESIGN, SETTING, AND PARTICIPANTS: This economic evaluation used a Markov state-transition model to simulate the costs and health outcomes of patients with nonthymomatous MG. The patients' baseline characteristics, disease progression, and treatment efficacy were derived from patient-level data from the Thymectomy Trial in Nonthymomatous Myasthenia Gravis Patients Receiving Prednisone Therapy (MGTX) clinical trial. The model adopted a UK NHS and Personal Social Services perspective over a lifetime horizon. Data analysis was performed from June 2024 to October 2025.\nMAIN OUTCOMES AND MEASURES: The primary outcomes were incremental costs and quality-adjusted life years (QALYs) discounted at 3.5% per annum and the incremental cost-effectiveness ratio (ICER). Extensive deterministic and probabilistic sensitivity analyses were conducted to assess the robustness of the findings to parameter uncertainty.\nRESULTS: There were 126 participants in the MGTX trial, with a mean age of 35.08 years; 70.63% were female. In the base-case analysis, thymectomy plus prednisolone dominated prednisolone alone, yielding higher health gains (14.63 QALYs vs 14.11 QALYs) and lower lifetime costs (£181 716 vs £194 730). This generated an incremental gain of 0.52 QALYs and a cost saving of £13 014 per patient. The results were robust across a wide range of sensitivity analyses. Probabilistic analysis (1000 simulations) showed that thymectomy had a greater than 99% probability of being cost-effective at a willingness-to-pay threshold of £25 000 per QALY.\nCONCLUSIONS AND RELEVANCE: In this economic evaluation, thymectomy was found to be a highly cost-effective intervention for nonthymomatous MG in the UK and likely to be cost-saving relative to prednisolone alone. These findings support current clinical guidelines recommending thymectomy for eligible patients and establish it as the most relevant comparator in evaluations of future health technologies. More broadly, this study demonstrates the importance of high-quality randomized clinical trial evidence in enabling health technology assessment of surgical procedures.", "authors": ["Lord Joseph", "Walton Matthew", "Murphy Peter", "Shepherd Lucy", "Wolfe Gil I", "Sussman Jon", "Cutter Gary", "Kaminski Henry", "Aban Inmaculada", "Hamedani Ali G", "Hodgson Robert"], "journal": "JAMA network open", "entry_date": "2026/04/13 11:33", "pub_date": "2026-04-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41973420/", "pub_types": ["Journal Article"], "affiliations": ["Sheffield Centre for Health and Related Research (SCHARR), University of Sheffield, Sheffield, United Kingdom."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 9.7, "journal_quartile": "1区"}, {"pmid": "41972441", "title": "[Management of Pregnancy Due to Concern for Preeclampsia in a Woman with Myasthenia Gravis, Chronic Hypertension, and Epilepsy - A Case Report].", "abstract": "Myasthenia gravis (MG) is an autoimmune disease impairing neuromuscular ‎transmission due to antibodies against acetylcholine receptors. Preeclampsia is a ‎pregnancy-specific hypertensive disorder that can lead to seizures and cerebral ‎complications, typically prevented with IV magnesium sulfate.‎ In MG patients, magnesium is contraindicated as it inhibits acetylcholine release, ‎worsening muscle weakness and risking respiratory failure.‎ We present a pregnant MG patient with additional preeclampsia risk factors: nulliparity, ‎age, epilepsy, gestational diabetes and chronic hypertension. Due to limited literature, a tailored protocol ‎was created including instructions to:‎ avoid magnesium; use levetiracetam or diazepam for seizures;‎ control blood pressure with hydralazine; add labetalol if needed; Cesarean only for obstetric reasons and to ensure team awareness and minimize stress.‎ This case emphasizes the need for individualized care in high-risk pregnancies with MG.", "authors": ["Dezuadi Lasry Moran", "Yekel Yael", "Hochler Hila"], "journal": "Harefuah", "entry_date": "2026/04/13 08:12", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41972441/", "pub_types": ["Case Reports", "Journal Article", "English Abstract"], "affiliations": ["Maternal-Fetal Unit, Laniado Hospital, Netanya. Affiliated with the Faculty of Health Sciences, Ariel University, Leumit Health Services."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41972167", "title": "Neurotoxicity of immune checkpoint inhibitors: a retrospective pharmacovigilance study using FAERS database.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs), an antitumor therapeutic strategy, have shown great potential for cancer treatment. With the widespread use of ICIs, immune-related adverse events (irAEs) have increased gradually. Neurotoxicity, as an irAE, has a low incidence rate, but high disability and mortality rates, warranting clinical attention.\nMATERIAL AND METHODS: This study aimed to quantify the association between neurological adverse events and ICI treatment and describe the characteristics of ICI-related neurological complications in real-world practice. Data were sourced from the FDA Adverse Event Reporting System (FAERS) database from the first quarter of 2004 to the first quarter of 2025. Data mining was performed using the reporting odds ratio (ROR) method. Classification and statistics were conducted using the system organ class (SOC), high-level group term (HLGT), and preferred term (PT) from the Medical Dictionary for Regulatory Activities (MedDRA) terminology set (version 28.0).\nRESULTS: The entire FAERS database included 56,321,150 adverse event records, of which 26,629 records were identified as being related to neurological immune-related adverse events (n-irAEs) following ICI therapy. The main adverse events include encephalitis, encephalopathy, myasthenia gravis, paraneoplastic syndromes, and peripheral neuropathy. Among these reports, males (53.51%) outnumbered females (37.82%), and the median patient age was 67 years. The number of reports in 2024 was slightly higher than that in other years, but the difference was not significant. Physicians were the primary reporters (43.23%) and the United States had the highest number of reports (35.78%). The median time to the onset of adverse events was 30 days. Serious reports accounted for a high proportion of the patients (91.23%).\nCONCLUSION: Pharmacovigilance analysis indicated that neurological immune-related adverse events associated with ICIs mainly involved central nervous system inflammation and neuromuscular junction dysfunction. Different ICI immunotherapies are associated with distinct neurological disease characteristics, and combination therapies may influence the reporting patterns of neurotoxicity. In clinical practice, the early recognition and management of ICI-related n-irAEs are critical.", "authors": ["Cao Lin", "Wang Yanfei", "Dai Peng", "Li Xia"], "journal": "Frontiers in immunology", "entry_date": "2026/04/13 06:47", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41972167/", "pub_types": ["Journal Article"], "affiliations": ["College of Traditional Chinese Medicine, Changchun University of Chinese Medicine, Jilin, Changchun, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41972143", "title": "Predictors of exacerbation in myasthenia gravis after minimal symptom expression: a bicenter cohort study.", "abstract": "BACKGROUND: Predicting exacerbation risk in clinically treated patients with myasthenia gravis (MG) is essential for personalised intervention with neurotherapies. This study investigated whether dynamic monitoring of anti-acetylcholine receptor antibody (AChR-ab) levels could predict exacerbation in MG patients following minimal symptom expression (MSE), and developed a validated model for risk stratification to inform treatment decisions.\nMETHODS: We conducted a bicenter cohort study enrolling AChR-ab+ adult MG patients who achieved MSE. The derivation cohort included 339 patients from Huashan Hospital, and the validation cohort comprised 60 patients from West China Hospital. Exacerbation was defined as an increase of ≥ 2 points in the MG Activities of Daily Living score. Independent predictors were identified through univariate and multivariate logistic regression analyses, and a prediction model was subsequently developed and validated using discrimination and calibration metrics.\nRESULTS: Longitudinal AChR-ab levels strongly correlated with disease progression, with a median time to exacerbation of 35.1 months post-MSE. Independent predictors included disease duration to MSE achievement, AChR-ab change, thymoma, comorbid immune-related diseases, and history of myasthenic crisis. The model demonstrated excellent discrimination in derivation (AUC = 0.886) and validation cohorts (AUC = 0.829), with good calibration in both datasets.\nCONCLUSION: Dynamic AChR-ab monitoring provides strong predictive value for MG exacerbation, and our validated prediction model offers clinicians a practical tool for personalized risk stratification and therapeutic decision-making in patients achieving disease stability.", "authors": ["He Dingxian", "Chen Hongxi", "Zhong Huahua", "Zhang Nana", "Yan Chong", "Song Jie", "Xi Jianying", "Luo Sushan", "Zhao Chongbo", "Zhou Hongyu"], "journal": "Frontiers in immunology", "entry_date": "2026/04/13 06:47", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41972143/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41969435", "title": "Thymic epithelial tumors: a narrative review of diagnostic and therapeutic advances.", "abstract": "BACKGROUND AND OBJECTIVE: Thymic epithelial tumors (TETs), comprising thymoma and thymic carcinoma, are rare mediastinal neoplasms that pose significant diagnostic and therapeutic challenges due to their complex anatomy and frequent association with paraneoplastic syndromes like myasthenia gravis (MG). This narrative review synthesizes recent advances in the multidisciplinary management of TETs, providing clinicians with a contemporary, tumor-specific overview.\nMETHODS: We conducted systematic literature searches across PubMed, Scopus, and Web of Science for publications from January 2018 to June 2024, focusing on high-impact studies (impact factor >3) with sample sizes >10 patients. Key terms included \"thymoma\", \"thymic carcinoma\", \"minimally invasive thymectomy\", \"targeted therapy\", and \"immunotherapy\". Content screening prioritized TETs-specific evidence.\nKEY CONTENT AND FINDINGS: Innovations in computed tomography (CT), magnetic resonance imaging (MRI), and positron emission tomography/CT (PET/CT) have enhanced TETs characterization, though differentiation of thymic hyperplasia remains challenging. Surgical management has shifted toward minimally invasive techniques [uniportal video-assisted thoracoscopic surgery (VATS), subxiphoid approach] and robotic surgery, reducing morbidity while maintaining oncological outcomes. For giant or invasive TETs, extended open techniques like clamshell incision remain indispensable. Systemic therapy advances include KIT/PIK3CA-targeted agents (imatinib, everolimus) showing modest efficacy, while programmed death-1/programmed death-ligand 1 (PD-1/PD-L1) inhibitors demonstrate 20-30% response rates in thymic carcinoma but are associated with a >50% risk of severe immune-related adverse events (irAEs). Platinum-based chemotherapy [cisplatin, doxorubicin, cyclophosphamide (CAP) regimen] remains standard for advanced disease. Multidisciplinary team (MDT) integration is fundamental, particularly for managing MG perioperatively.\nCONCLUSIONS: TETs management is evolving rapidly through technological and biological advances. Future progress hinges on: (I) validating artificial intelligence (AI)-driven imaging classifiers; (II) conducting randomized controlled trials (RCTs) comparing surgical approaches; (III) elucidating immunotherapy toxicity mechanisms; and (IV) developing predictive composite biomarkers integrating genomic, immunological, and clinical parameters to enable precision medicine while mitigating fatal toxicities.", "authors": ["Chen Minghai", "Li Yunbin", "Liao Lihang", "Du Xiaojun"], "journal": "Translational cancer research", "entry_date": "2026/04/13 06:26", "pub_date": "2026-03-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41969435/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Thoracic Surgery, The Affiliated Hospital of Guizhou Medical University, Guiyang, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "41966710", "title": "Autologous CD19/BCMA CAR-T cell therapy for myasthenia gravis: Advancing care for those with severe disease.", "abstract": "Ruan and colleagues report that dual-target CD19/BCMA CAR-T cell therapy produced marked clinical improvement in highly refractory myasthenia gravis, with steroid discontinuation and minimal toxicity. Beyond symptom control, deep immune profiling revealed sustained B-cell depletion, reduced autoantibodies, and systemic immune reprogramming toward a less inflammatory state.", "authors": ["Kaminski Henry J", "Kusner Linda L"], "journal": "Med (New York, N.Y.)", "entry_date": "2026/04/12 11:52", "pub_date": "2026-04-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41966710/", "pub_types": ["Journal Article"], "affiliations": ["Laboratory for Myasthenia Gravis, George Washington University, Washington, DC, USA; Department of Neurology and Rehabilitation Medicine, George Washington University, Washington, DC, USA. Electronic address: hkaminski@mfa.gwu.edu."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41964792", "title": "Patient- and Caregiver-Reported Burden and Quality of Life in Generalised Myasthenia Gravis: A Multinational Real-World Survey in the Asia-Pacific Region.", "abstract": "INTRODUCTION: Understanding patient- and caregiver-reported burden of generalised myasthenia gravis (gMG) is essential to inform region-specific management and policy decisions. However, real-world data from the Asia-Pacific region remain limited.\nMETHODS: Data were drawn from the Adelphi Real World gMG Disease Specific Programme™, a cross-sectional survey of neurologists and their patients with gMG conducted in Australia, China, Japan, Malaysia, South Korea, and Taiwan between July 2023 and January 2024. Neurologists reported patient demographics, clinical characteristics, and perceived patient quality of life (QoL). Patients, and patients' caregivers provided answers to self-reported outcome measures, including the EQ-5D-5L, corresponding to status at the time of survey. Analyses were descriptive other than weighted kappa analyses used to measure neurologist-patient agreement on subjective patient QoL at the time of survey.\nRESULTS: Overall, 163 neurologists reported data for 434 patients, of whom 205 self-reported data alongside 151 caregivers. Most patients were female (58.5%), with a mean (SD) age of 51.4 (15.2) years, and received caregiver support (71.4%). Patients reported deficits across all EQ-5D-5L domains, including usual activities (79.4%), and moderate to extreme anxiety/depression (29.4%), with a mean (SD) index score of 0.72 (0.23). Most patients (54.6%) had a FACIT-Fatigue score < 30, indicating severe fatigue, and 45.0% of patients had reduced employment due to gMG. A kappa value of 0.2692 indicated a fair agreement between neurologist and patient perceived patient QoL. Mean (SD) patient absenteeism was 11.8% (20.8%), presenteeism 39.2% (22.5%), overall work productivity loss of 42.9% (23.9%), and activity impairment of 51.3% (23.9%). Caregivers reported a mean (SD) 27.6% (19.6%) overall work productivity loss and 47.0% (24.1%) activity impairment.\nCONCLUSION: Patients and their caregivers reported substantial burden to QoL, including impaired work productivity, limitations in activities of daily living, fatigue, and anxiety/depression. Further research into health-policy initiatives is warranted to more effectively address these unmet needs in the Asia-Pacific.", "authors": ["Yu DaeYoung", "Kasahara-Kiritani Mami", "Lee Bolam", "Tsai I Ching", "Birija Shiva Lauretta", "Conyers Joe", "Connolly Hannah", "Gibson Gregor", "Hong Yoon-Ho"], "journal": "Neurology and therapy", "entry_date": "2026/04/11 11:06", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41964792/", "pub_types": ["Journal Article"], "affiliations": ["Market Access (Asia-Pacific) Johnson & Johnson, Singapore, Singapore. dyu5@its.jnj.com."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41964787", "title": "Immune checkpoint inhibitors-related Overlap Syndrome: can a second course of intravenous immunoglobulin help?", "abstract": "", "authors": ["Chaari Anis", "Alshaikh Raneem", "Bousselmi Kamel", "Alkhaja Mohamad"], "journal": "Acta neurologica Belgica", "entry_date": "2026/04/11 11:06", "pub_date": "2026-04-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41964787/", "pub_types": ["Letter"], "affiliations": ["Critical Care Department, King Hamad University Hospital, Royal Medical Services, Building 2435, Road 2835, Block 228, P.O. Box 24343, Bussaiteen, Kingdom of Bahrain. anischaari2004@yahoo.fr."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41962987", "title": "Myasthenia gravis in Spain: A survey of specialized neurologists to uncover unmet needs.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a neuromuscular autoimmune disease that requires prompt diagnosis and management by neurologists. The challenges of MG management are associated with the diagnostic process and the selection of an effective form of therapy enabling long-term remission of the disease. The objective of this study was to assess the state of MG in Spain to identify unaddressed needs in the clinical progression, diagnosis, and treatment approaches.\nMETHODS: A survey was distributed via email between 19 July and 25 October 2022 to neurologists belonging to the Spanish Society of Neurology. A comprehensive descriptive analysis was conducted on all collected data.\nRESULTS: In total, 69 completed surveys, representing 64 Spanish hospitals, were analyzed and included in the results. The study identified that economic difficulties, such as departmental budgets, have led to a lack of access to antibody testing during diagnosis. Furthermore, corticosteroids were found to achieve the best clinical response, despite also being associated with a higher frequency of adverse effects. The results show that 34% of patients with MG present active symptoms. Eighteen percent have symptoms that limit their daily activities. Additionally, 29% of patients have requested an unscheduled follow-up visit within the last year.\nCONCLUSIONS: Several areas present unmet needs in terms of improving access to diagnostic assays, residual disease burden in treated patients, and the management and diagnosis of MG.", "authors": ["Cortés-Vicente E", "Casasnovas C", "Juntas R", "Sevilla T", "Pardo J", "Rodríguez de Rivera F", "Guerrero Sola A"], "journal": "Neurologia", "entry_date": "2026/04/10 20:53", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41962987/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Diseases Unit, Department of Neurology, Hospital de la Santa Creu i Sant Pau, Barcelona, Spain; Neuromuscular Diseases Laboratory, Biomedical Research Institute Sant Pau, Barcelona, Spain; Centro de Investigación Biomédica en Red de Enfermedades Raras (CIBERER), Instituto de Salud Carlos III, Madrid, Spain. Electronic address: ecortes@santpau.cat."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41961712", "title": "Causal effects of Epstein-Barr virus antibodies on autoimmune neuroinflammatory diseases: A generalised summary data-based Mendelian randomisation study.", "abstract": "Observational studies associate Epstein-Barr virus (EBV) with multiple sclerosis (MS), but causality across autoimmune neuroinflammatory diseases (ANDs) remains uncertain. This study aimed to assess the causal effects of 5 EBV antibodies on ANDs using Mendelian randomization (MR). Bidirectional, two-sample MR was performed using generalized summary-data-based MR (GSMR). Genetic instruments for EBV antibodies (anti-EBNA-1, VCA p18, ZEBRA, EA-D, IgG) were sourced from UK Biobank (UKB). Outcome data for ANDs (multiple sclerosis [MS], neuromyelitis optica [NMO], myasthenia gravis [MG], Guillain-Barré syndrome [GBS], and chronic inflammatory demyelinating polyneuropathy [CIDP]) were from FinnGen (discovery), UKB, and International Multiple Sclerosis Genetics Consortium (replication). Applying an evidence-tiered interpretation, we found a high-confidence, protective causal effect of increased ZEBRA antibody levels on MS risk (odds ratio [OR] = 0.705, P = 2.967 × 10-6), which was robust to multiple testing nominally supported in an independent cohort (IMSGC). In contrast, the association between EBNA-1 antibodies and increased MS risk (OR = 1.284, P = 2.450 × 10-4) was graded as suggestive as it showed nominal support only in one of 2 validation cohorts (UKB) and was substantially attenuated after excluding HLA-region single nucleotide polymorphisms, indicating shared genetic architecture rather than direct causation. Steiger directionality tests confirmed the primary causal direction was from antibodies to MS. Results for NMO, MG, GBS, and CIDP were inconclusive due to limited statistical power, and thus no definitive conclusions can be drawn regarding EBV antibodies and these diseases. This study provides high-confidence genetic evidence for a protective role of ZEBRA antibodies in MS, which was robust to multiple testing and nominally supported in an independent cohort [International MS Genetics Consortium (IMSGC)], and suggestive evidence for an HLA-mediated link between EBV-encoded nuclear antigen-1 (EBNA-1) and MS which showed nominal support only in one of 2 validation cohorts. The role of EBV in other ANDs warrants investigation in larger, well-powered cohorts.", "authors": ["Sun Shujun", "Wen Yiyong", "Tang Pan", "Xie Fan", "Ding Tao", "Wen Jun", "Xu Anding"], "journal": "Medicine", "entry_date": "2026/04/10 13:05", "pub_date": "2026-04-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41961712/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Stroke Center, The First Affiliated Hospital of Jinan University, Guangzhou, Guangdong, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41960209", "title": "Surgical outcomes of thoracoscopic extended thymectomy via subxyphoid and left intercostal approach.", "abstract": "BACKGROUND: Minimally invasive thymectomy is widely adopted for the management of thymic diseases and myasthenia gravis (MG). Among thoracoscopic techniques, the intercostal approach (ICA) is the most commonly used, whereas the subxiphoid approach (SA) has been proposed to reduce postoperative pain. However, comparative evidence remains heterogeneous.\nMETHODS: This single-center retrospective cohort study included consecutive patients who underwent minimally invasive thymectomy between January 2019 and December 2023. Patients were assigned to the ICA or SA group according to the surgical approach performed. The primary outcome was early postoperative pain assessed using the visual analog scale (VAS) within 48 h. Secondary outcomes included operative and perioperative parameters, postoperative complications, and short-term follow-up outcomes. Multivariable linear regression analysis was conducted to adjust for potential confounders.\nRESULTS: Of 168 patients assessed for eligibility, 90 were included in the final analysis (ICA, n = 48; SA, n = 42). Baseline characteristics were comparable between groups. Operative time, intraoperative blood loss, duration of chest drainage, length of hospital stay, and hospitalization costs did not differ significantly. Early postoperative pain was lower in the SA group, with significantly reduced VAS scores during the first 48 h. Postoperative complication rates were low and similar between approaches, with no perioperative mortality observed. Among patients with MG, short-term neurological improvement did not differ significantly. Multivariable analysis confirmed that the subxiphoid approach was independently associated with lower early postoperative pain.\nCONCLUSIONS: Intercostal and subxiphoid thoracoscopic thymectomy demonstrated comparable perioperative safety and short-term clinical outcomes in this cohort. The subxiphoid approach was associated with lower early postoperative pain, while other operative and recovery-related parameters were similar. These findings support individualized surgical decision-making rather than a universally superior approach.", "authors": ["Jiang Zhenlin", "Dong Zuxin", "Chen Junting", "Yan Jianhua"], "journal": "Frontiers in surgery", "entry_date": "2026/04/10 05:40", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41960209/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Hunan Provincial People's Hospital (The First Affiliated Hospital of Hunan Normal University), Changsha City, Hunan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "41960072", "title": "Clinical outcomes and follow-up after thymectomy in patients with myasthenia gravis: A Colombian cohort study.", "abstract": "OBJECTIVE: To describe 5-year clinical outcomes after thymectomy in patients with myasthenia gravis (MG).\nMETHODS: We retrospectively analyzed patients who underwent thymectomy for MG between 2010 and 2023. Preoperative and annual postoperative assessments (up to 5 years) used the Myasthenia Gravis Foundation of America classification. Outcomes were stratified as complete stable remission (CSR), pharmacologic remission, or minimal manifestations, with additional evaluation by patient-reported changes in symptoms. Kaplan-Meier analyses were conducted for time-to-event data.\nRESULTS: Eighty-six patients were included (median age, 42 years; 60.5% female). The median duration of symptoms was 480 days (interquartile range, 28-56 days). Most patients (n = 70; 81.4%) had a low comorbidity burden. Preoperatively, 34% were Myasthenia Gravis Foundation of America class I. Acetylcholinesterase inhibitors were used in 95% of patients. Right video-assisted thoracoscopic thymectomy was the most common approach (76%), with a 2.3% intraoperative complication rate. Thymic hyperplasia was present in 87%; thymoma, in 13%. Postoperative intensive care was required in 96.5%, with myasthenic crisis the most frequent complication (8%). The median hospital length of stay was 4 days, and there was no 30-day mortality. At 1 year, 81.7% were Myasthenia Gravis Foundation of America class I. Kaplan-Meier analysis showed 50% reported symptom improvement by 360 days (95% confidence interval, 350-375 days). By 5 years, 8% achieved CSR. Although a decline in acetylcholinesterase inhibitor dosage was observed, this was not significant (P = .225).\nCONCLUSIONS: Thymectomy is associated with favorable long-term symptom control in MG, with low perioperative morbidity. However, rates of complete stable remission remain low, underscoring the need for further investigation into post-thymectomy outcomes and predictors of remission.", "authors": ["Alvarez-Ortega Astrid Carolina", "Padilla-Londoño Natalia", "Posso-Nuñez Jose Alejandro", "Gomez-Martinez Josué Daniel", "Quiñones-Bautista Jairo Alonso", "Torres-España Nicolás Felipe", "Sanchez-Ortiz Álvaro Ignacio", "Velasquez-Galvis Mauricio"], "journal": "JTCVS open", "entry_date": "2026/04/10 05:38", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41960072/", "pub_types": ["Journal Article"], "affiliations": ["Clinical Research Center Department, Fundación Valle del Lili, Cali, Colombia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41959797", "title": "High risk of hypoxemic COVID-19 pneumonia in myasthenia gravis patients with type I IFN autoantibodies.", "abstract": "Patients with myasthenia gravis (MG) may produce autoantibodies neutralizing type I interferons (AAN-I-IFN), which have been shown to underlie severe viral diseases, including critical COVID-19 pneumonia, in patients without MG. We studied an international cohort of 85 unvaccinated SARS-CoV-2-infected MG patients with no antiviral treatment. Hypoxemic pneumonia occurred in 48 of these patients, including 22 (45.8%) with AAN-I-IFN, which neutralized both IFN-α2 and IFN-ω in 14 (29.2%) patients. Six (16.2%) of the remaining 37 patients had AAN-I-IFN, which neutralized both IFN-α2 and IFN-ω in three patients. The risk of hypoxemic pneumonia was greater in MG patients with AAN-I-IFN neutralizing 10 ng/mL of both IFN-α2 and IFN-ω (odds ratio and 95% confidence interval (OR [95% CI]): 12.7 [2.1-78.9], p=0. 0010) or IFN-α2 at any dose (4.7 [1.5-15.0], p=0.0054) than in those without such autoantibodies. The risk of AAN-I-IFN production was much higher in MG patients than in the general population (28.9 [10.8-77.7], p=4.9×10-27). Fourteen patients had thymoma, which increased the risk of AAN-I-IFN (64% versus 27%, (OR [95% CI]: 5.6 [1.6-19.4], p=0.0050) and hypoxemic pneumonia (9.2 [1.9-44.2]; p=0.0019). Thymoma is, thus, associated with a higher risk of producing AAN-I-IFN, and these autoantibodies are associated with a higher risk of developing life-threatening COVID-19 pneumonia in patients with MG.", "authors": ["Gervais Adrian", "Marchal Astrid", "Maillard Alexis", "Le Voyer Tom", "Rosain Jérémie", "Philipot Quentin", "Bizien Lucy", "Peel Jessica", "Cederholm Axel", "Migaud Mélanie", "Pons Sylvie", "Saker Kahina", "Laforet Pascal", "Aubart Mélodie", "Gitiaux Cyril", "Biggs Catherine", "Leon Lopez Rafael", "Souvannanorath Sarah", "Tard Céline", "Nadaj Pakleza Aleksandra", "Grapperon Aude-Marie", "Heming Nicholas", "Annane Djillali", "Verschueren Annie", "Attarian Shahram", "Bigaut Kévin", "Hankiewicz Karolina", "Kouton Ludivine", "Villar-Quiles Rocio-Nur", "Cauquil Cécile", "Fleury Marie-Céline", "Rocher Emilie", "Nicolas Guillaume", "de Paula Estephan Eduardo", "da Penha Ananias Morita Maria", "Zanoteli Edmar", "Saied Zakaria", "Rachdi Amine", "Rim Amouri", "Belal Samir", "Ben Sassi Samia", "Hübers Annemarie", "Faure Emmanuel", "Desguerre Isabelle", "Basse Clémence", "Girard Nicolas", "Béziat Vivien", "Pan-Hammarström Qiang", "Hammarström Lennart", "Bodansky Aaron", "Parent Audrey V", "Anderson Mark S", "DeRisi Joseph L", "Demeret Sophie", "Truffault Frédérique", "Fort Romain", "Ader Florence", "Wallet Florent", "Abel Laurent", "Molina Thierry", "Alyanakian Marie-Alexandra", "Le Panse Rozen", "Solé Guilhem", "Cobat Aurélie", "Landegren Nils", "Casanova Jean-Laurent", "Puel Anne", "Bastard Paul", "Jouanguy Emmanuelle"], "journal": "medRxiv : the preprint server for health sciences", "entry_date": "2026/04/10 05:37", "pub_date": "2026-04-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41959797/", "pub_types": ["Journal Article", "Preprint"], "affiliations": ["Laboratory of Human Genetics of Infectious Diseases, Necker Branch, INSERM U1163, Necker Hospital for Sick Children, Paris, France, EU."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41958428", "title": "Myasthenic syndrome in systemic lupus erythematosus successfully treated with plasma exchange: through one of the unexplored faces of neuropsychiatric involvement.", "abstract": "Neuropsychiatric systemic lupus erythematosus (NPSLE) encompasses a wide range of neurological manifestations, including, though rarely, myasthenia gravis (MG). We report the case of a 47-year-old woman with long-standing SLE who developed diplopia and fluctuating muscle weakness. Electromyography revealed a decremental response to low-frequency stimulation in the absence of MG-specific autoantibodies. These neurological features were interpreted as manifestations of NPSLE and were initially treated with azathioprine and then rituximab, the latter discontinued due to an adverse reaction. Several years later, immunosuppressive therapy with mycophenolate mofetil and voclosporin was initiated following a renal flare. Although renal remission was achieved, the patient experienced a concomitant relapse of neurological symptoms. After multidisciplinary consultation with neurologists, the patient underwent three monthly cycles of plasma exchange combined with corticosteroid pulses, resulting in marked clinical improvement of neurologic symptoms and sustained serological and clinical stability during the follow-up. The coexistence of SLE and MG is uncommon; distinguishing between an overlap syndrome or lupus-related myasthenic manifestations and choosing the optimal therapeutic strategy remain challenging. In this case, plasma exchange proved to be an effective rescue therapy, highlighting the importance of a multidisciplinary approach and individualized treatment strategies in managing complex NPSLE presentations.", "authors": ["Ferrigno Sara", "Prevete Immacolata", "Orefice Valeria", "Scirocco Chiara", "Sebastiani Gian Domenico"], "journal": "Reumatismo", "entry_date": "2026/04/10 05:23", "pub_date": "2026-04-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41958428/", "pub_types": ["Journal Article"], "affiliations": ["Rheumatology Unit, San Camillo-Forlanini Hospital, Rome."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41958278", "title": "Chimeric Antigen Receptor T-Cells in Myasthenia Gravis: Advances, Safety Challenges, and Future Directions.", "abstract": "This review examines the emerging application of chimeric antigen receptor (CAR) T-cell therapy in myasthenia gravis (MG), with emphasis on safety, efficacy signals, and future therapeutic potential in treatment-refractory disease. A comprehensive literature search was conducted across PubMed, medRxiv, bioRxiv, and Google Scholar for studies published between January 1, 2010 and July 1, 2025, using the terms \"CAR T-cell,\" \"chimeric antigen receptor,\" and \"myasthenia gravis.\" Eligible reports included clinical trials, case reports, case series, and mechanistic studies describing CAR T-cell therapy outcomes in MG. Across five independent case series, seven patients receiving CAR T-cells targeting CD19, BCMA, or bispecific antigens showed consistent clinical improvement. Peak expansion occurred 8-22 days postinfusion, with persistence of 28 to ~180 days. Despite small cohorts, safety in CAR T-cell therapy was favorable versus oncology, with mainly Grade 1-2 cytokine release syndrome, rare immune effector cell-associated neurotoxicity, and no severe or life-threatening events. Seven registered trials (> 260 patients) are expected to conclude between 2026 and 2029. Overall, CAR T-cell therapy shows substantial promise for treatment-refractory MG, potentially offering greater durability than existing therapies with an acceptable safety profile. Nevertheless, current evidence is restricted to small, uncontrolled studies, and long-term efficacy, durability, and optimal patient selection require validation in larger controlled trials.", "authors": ["Hegelmaier Tobias", "Duscha Alexander", "Desel Christiane", "Stassen Sarah", "Krzemien Tim", "Hennemann Ann-Katrin", "Pappa Vaia", "Haghikia Aiden"], "journal": "Muscle & nerve", "entry_date": "2026/04/10 03:33", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41958278/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology and Clinical Neurophysiology, Hannover Medical School, Hannover, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41957339", "title": "Digital Monitoring of Patients with Generalized Myasthenia Gravis: A Prospective Pilot Study.", "abstract": "INTRODUCTION: Monitoring patients with myasthenia gravis (MG) can be challenging due to the fluctuating nature of the disease. We aimed to test the reliability of using the MG Activities of Daily Living (MG-ADL) scale in the form of a smartphone application as a means for optimal patient monitoring and early exacerbation detection.\nMETHODS: We conducted an observational, prospective, single-center study including patients with generalized MG at risk of clinical worsening. Follow-up was based on routine outpatient visits, remote monitoring via weekly self-completion of the MG-ADL scale, and home visits by specialist nurses.\nRESULTS: Thirty-one patients were included [41.9% female; mean (SD) age 59 (15) years], 87.1% seropositive for anti-AChR antibodies. MG-ADL scores reported by the patient via the application showed excellent agreement with healthcare provider scores (ICC = 0.92, P < 0.01), moderate correlation with the MG Composite scale (ρ = 0.595, P < 0.01), and weak correlation with the Quantitative MG scale (ρ = 0.328, P < 0.01). Over the 15-month follow-up period, compared to 23 exacerbations detected during routine outpatient visits, the application detected 38 exacerbations in 14 patients, 20 of which led to therapeutic modifications.\nCONCLUSION: This study demonstrates the reliability of MG-ADL scale data obtained via a smartphone application in reflecting clinical status and in detecting deterioration episodes sometimes missed during routine outpatient visits.", "authors": ["Vesperinas Ana", "Rocaspana-Codana Josep", "Reyes-Leiva David", "Caballero-Ávila Marta", "Carbayo Álvaro", "Collet-Vidiella Roger", "Llansó Laura", "Gallardo Eduard", "Turon-Sans Joana", "Rojas-García Ricard", "Cortés-Vicente Elena"], "journal": "Neurology and therapy", "entry_date": "2026/04/09 23:29", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41957339/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Diseases Unit, Department of Neurology, Hospital de la Santa Creu i Sant Pau, C/Pare Claret 167, 08025, Barcelona, Spain."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41954011", "title": "Therapeutic approach to myasthenia gravis treatment in the era of new biologics - review of existing and upcoming therapies.", "abstract": "Myasthenia gravis (MG) is a heterogenous autoimmune disease affecting the neuromuscular junction, which in many patients leads to devastating symptoms significantly influencing patients' lives or causing life-threatening episodes. The incidence and prevalence of myasthenia are growing worldwide. By definition, MG is characterized by muscle weakness exacerbated with activity and improving with rest. A total of 15-20% of patients during the course of the disease develop myasthenic crisis (MC), defined as respiratory insufficiency requiring intubation, with a high mortality rate. Approximately 30-50% of patients have unsatisfactory response to the standard treatment. Moreover, the standard of care (SoC), although efficient in most of patients, may be complicated by significant side effects, in most cases resulting from long-term treatment with glucocorticosteroids. In recent decades, new therapies have been approved for MG, including neonatal Fc receptor (FcRn) antagonists and complement component 5 (C5) inhibitors, as add-on to standard therapy. They showed efficacy and safety, even in patients previously considered as resistant MG. In several cases their rapid onset of action led to successful use as rescue treatments in impending crisis. Furthermore, it is noteworthy that new biologics show relevant steroid-sparing effects. This review summarizes new therapeutic approaches already approved for MG and introduces upcoming ones.", "authors": ["Sobieszczuk Ewa", "Szczudlik Piotr", "Barańska Judyta", "Kostera-Pruszczyk Anna"], "journal": "Neurologia i neurochirurgia polska", "entry_date": "2026/04/09 05:23", "pub_date": "2026-04-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41954011/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Medical University of Warsaw, Poland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "41948617", "title": "Autoreactive T cells and thymic atrophy pathway in thymic hyperplasia patients with myasthenia gravis.", "abstract": "BACKGROUND: T cells play a vital role in antigen presentation, immune tolerance imbalance, and secretion of pathogenic cytokines in the progression of Myasthenia Gravis (MG). Previous studies have founded that patients with thymic hyperplasia accompanied by MG exhibit autoreactive T cells in thymus that can recognize self-antigens at the neuromuscular junction (NMJ), leading to the destruction of acetylcholine receptors (AChR) and the appearance of muscle weakness. Furthermore, Thymic hyperplasia is associated with T-cell-related autoimmune diseases, and increased expression of WNT4 and FOXN1 are beneficial to the growth of thymic cells and the maintenance of the thymic microenvironment.\nMETHODS: The samples were obtained from surgical patients who met the criteria, and this study was ethically approved. We first measured the proportion of T cell subsets in the peripheral blood and thymus of thymic hyperplasia patients with and without myasthenia gravis. Then, we quantified the WNT4 and FOXN1 proteins in the thymus. Finally, we used the Pearson correlation test to analyze the correlation between autoreactive T cells and the thymic atrophy pathway.\nRESULTS: Flow cytometry clarified that Th1 and Th17 cells were elevated in the peripheral blood and thymus of patients with MG (1.207 ± 1.444 and 3.788 ± 0.6920 in Th1, 7.683 ± 1.025 and 0.3127 ± 0.1936 in Th17). Western blotting revealed increased expression of key molecules in the thymic atrophy pathway, WNT4 and FOXN1, in the MG group. Additionally, the abnormal activation of the thymic atrophy pathway may be one of the causes of autoreactive T cell production.\nCONCLUSION: Our study has identified an increased number of Th1 and Th17 cells in the peripheral blood and thymus of patients with thymic hyperplasia associated MG. Quantitative analysis of proteins and RNA indicates that the expression of WNT4 and FOXN1 is upregulated in patients with thymic hyperplasia accompanied by MG. Additionally, the abnormal activation of the thymic atrophy pathway may be one of the causes of autoreactive T cell production. This research provides a potential perspective on the pathogenesis of MG in patients with thymic hyperplasia.", "authors": ["Wang Xuemin", "Chen Pei", "Yang Wenjing", "Chen Jiaxin", "Li Shiyin", "Luo Chuanming", "Huang Xin"], "journal": "Frontiers in neurology", "entry_date": "2026/04/08 04:32", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41948617/", "pub_types": ["Journal Article"], "affiliations": ["The Seventh Affiliated Hospital of Sun Yat-sen University, Shenzhen, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41947805", "title": "A Delphi consensus on integrating novel therapies into the management of generalized myasthenia gravis.", "abstract": "BACKGROUND: The treatment landscape for myasthenia gravis (MG) has evolved with the introduction of novel therapies. An international consensus on patient selection criteria and optimal time to initiate these therapies could improve clinical outcomes and reduce delays for likely beneficiaries.\nOBJECTIVE: This Delphi consensus was undertaken by MG specialists from selected European countries to explore gaps in the application of national guidelines and elicit expert opinion in practice.\nDESIGN: A mixed-method approach was used; qualitative and quantitative study phases were combined to explore key concepts and reach consensus.\nMETHODS: The qualitative first phase involved seven healthcare professionals (HCPs) and two patient advocacy group representatives who participated in idea generation. Findings from this phase supported the development of a Delphi survey, which was completed by 16 HCPs in two rounds. This constituted the quantitative second phase of the study. Consensus was defined as ⩾70% agreement or disagreement on a 6-point Likert scale.\nRESULTS: In total, 65% of statements achieved consensus. Key findings include-HCPs highly regard international guidelines but find critical discrepancies between the \"ideal\" scenario and current clinical practices. Consensus was achieved on the importance of incorporating patient-related quality of life in decision-making, despite limited current methods. Consensus was obtained on steroid tapering and treatment-switch criteria based on steroid dose and duration. Consensus was also achieved on suitable patient profiles, including those with persistent symptoms, severe side effects, or needing rapid control.\nCONCLUSION: This study recognized that guidelines offer valuable direction but do not replace individualized treatment decisions. This study identified the areas of alignment and opportunities to refine patient selection criteria and treatment-switch categories, particularly to integrate novel therapy use in MG management, highlighting a path to a more patient-centric approach.", "authors": ["Vissing John", "Zimprich Fritz", "Atula Sari", "Chan Andrew", "Andersen Henning", "Topakian Raffi", "Tannemaat Martijn R", "Weber Konrad P", "Cetin Hakan", "Neuwirth Christoph", "Kuusisto Hanna", "Loescher Wolfgang N"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/04/08 04:23", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41947805/", "pub_types": ["Journal Article"], "affiliations": ["Copenhagen Neuromuscular Center, Rigshospitalet, University of Copenhagen, Copenhagen DK-1165, Denmark."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41945881", "title": "Efficacy of Pyridostigmine in Myasthenia Gravis: A Randomized, Double-Blind, Placebo-Controlled Crossover Trial.", "abstract": "BACKGROUND AND OBJECTIVES: Pyridostigmine, an acetylcholinesterase inhibitor, is a symptomatic drug approved for the treatment of myasthenia gravis (MG), but no randomized controlled trials substantiate its widespread use. We aimed to assess the efficacy and cost utility of pyridostigmine in patients with anti-acetylcholine receptor-positive MG (AChR MG).\nMETHODS: A randomized, double-blind, placebo-controlled crossover trial was conducted at Leiden University Medical Center, a tertiary center for the treatment of MG in the Netherlands. Main eligibility criteria were current use of pyridostigmine and a stable dose of other MG treatments. Participants were assigned to a sequence of 2 treatment periods for 5 days separated by a 2-day washout, in which patients either first received placebo and then pyridostigmine, or vice versa. Pyridostigmine dosing matched each participant's prestudy regimen. The primary outcome was change in the Myasthenia Gravis Impairment Index (MGII) score. Secondary efficacy outcome measures included the Myasthenia Gravis Activities of Daily Living (MG-ADL) scale, the Quantitative Myasthenia Gravis (QMG) score, and the revised 15-item Myasthenia Gravis Quality of Life (MG-QOL15r) questionnaire. For the post hoc cost-utility analysis, a mathematical model was developed to translate the observed study results into long-term annual effect on societal costs and quality-adjusted life years (QALYs).\nRESULTS: A total of 19 patients (median age 59 years, 58% female) were recruited between March 23, 2023, and February 21, 2024. The estimated mean difference in the MGII score between pyridostigmine and placebo interventions was 5.3 (95% CI 1.9-8.7, p = 0.004). Secondary efficacy outcome measures showed estimated mean differences of 1.4 (95% CI 0.5-2.3) for the QMG score, 1.2 (95% CI 0.5-1.8) for the MG-ADL score, and 2.0 (95% CI 0.03-3.91) for the MG-QoL15r score. The post hoc cost-utility analysis showed lower annual societal costs (€6,565, 95% CI €328-€15,945) and annual improved QALYs (0.106, 95% CI 0.019-0.210) for patients using pyridostigmine.\nDISCUSSION: This trial showed that, in patients with AChR MG chronically treated with pyridostigmine, pyridostigmine demonstrated benefit over placebo across all efficacy outcome measures and substantially reduced societal costs.\nTRIAL REGISTRATION INFORMATION: The trial was registered at EudraCT (2021-004110-20, registration date: July 12, 2022) and ClinicalTrials.gov (NCT05919407, registration date: June 16, 2023). First patient enrolled: March 23, 2023.\nCLASSIFICATION OF EVIDENCE: This study provides Class I evidence that, in adults with AChR ab-positive ocular or generalized MG on stable standard-of-care therapy and currently using pyridostigmine, pyridostigmine improves MG symptoms compared with placebo.", "authors": ["Remijn-Nelissen Linda", "Bakker Wisse R", "van den Hout Wilbert B", "van Gelder Teun", "Ruiter Annabel M", "Campman Yvonne J M", "Badrising Umesh A", "Straathof Chiara S M", "Verschuuren Jan J G M", "Tannemaat Martijn R"], "journal": "Neurology", "entry_date": "2026/04/07 16:03", "pub_date": "2026-04-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41945881/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology, Leiden University Medical Center, the Netherlands."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41945880", "title": "Efficacy and Safety of Amifampridine in Myasthenia Gravis: A Randomized, Double-Blind, Placebo-Controlled Crossover Trial.", "abstract": "BACKGROUND AND OBJECTIVES: Amifampridine, a short-acting potassium-channel blocker, is the first-line treatment for Lambert-Eaton myasthenic syndrome. Its benefit as add-on to pyridostigmine in acetylcholine receptor (AChR)-positive myasthenia gravis (MG) has been proposed, but no randomized controlled trials have been conducted. We aimed to evaluate the efficacy and safety of amifampridine in AChR-MG with insufficient symptom control on pyridostigmine.\nMETHODS: A randomized, double-blind, placebo-controlled crossover trial was conducted at Leiden University Medical Center, a tertiary center for the treatment of MG in the Netherlands, as part 2 of the IMPACT-MG trial. Eligible patients had either completed part 1 (pyridostigmine vs placebo) or failed the initial 2-day pyridostigmine washout, and had an Myasthenia Gravis Impairment Index (MGII) score >10. Participants were randomized (1:1:1) to 1 of 3 treatment sequences. Each treatment period lasted 5 days, with a 2-day washout between treatments, during which participants received either 30 mg or 60 mg of amifampridine modified release, or placebo. The primary outcome was the difference in MGII score between the 2 amifampridine dosages and placebo. Pharmacokinetics, safety, and tolerability were assessed throughout the trial.\nRESULTS: Between March 2023 and April 2024, 20 patients were enrolled (median age 60 years, 55% female). For the MGII score, the estimated mean differences were -1.0 (95% CI -4.1 to 2.0, p = 0.681) for amifampridine 30 mg vs placebo and -1.7 (95% CI -4.7 to 1.4, p = 0.379) for amifampridine 60 mg vs placebo. No statistically significant association was observed between pharmacokinetic parameters and the MGII. No serious adverse events were reported. Adverse events were more common with amifampridine 30 mg (12 patients [60%]) and 60 mg (15 patients [75%]), compared with placebo (6 patients [30%]), with paresthesia, fatigue, numbness, dizziness, and sleep disturbances most frequently reported. Three patients discontinued amifampridine early due to adverse events.\nDISCUSSION: The addition of amifampridine to pyridostigmine was not superior to treatment with pyridostigmine alone and was associated with a higher incidence of adverse events.\nTRIAL REGISTRATION INFORMATION: The trial was registered at EudraCT (2021-004110-20, registration date: July 12, 2022) and ClinicalTrials.gov (NCT05919407, registration date: June 16, 2023). First patient enrolled: March 23, 2023.\nCLASSIFICATION OF EVIDENCE: This study provides Class I evidence that in patients with AChRAb+ MG, the addition of amifampridine to pyridostigmine was not superior to treatment with pyridostigmine alone and was associated with a higher incidence of adverse events.", "authors": ["Remijn-Nelissen Linda", "Bakker Wisse R", "van Gelder Teun", "Moes Dirk Jan A R", "Ruiter Annabel M", "Campman Yvonne J M", "Badrising Umesh A", "Straathof Chiara S M", "Verschuuren Jan J G M", "Tannemaat Martijn R"], "journal": "Neurology", "entry_date": "2026/04/07 16:03", "pub_date": "2026-04-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41945880/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology, Leiden University Medical Centre, the Netherlands; and."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41940306", "title": "Hidden diagnoses among patients with double seronegative myasthenia gravis.", "abstract": "INTRODUCTION: Double seronegative myasthenia gravis (dSnMG) is defined as myasthenia gravis (MG) without detectable antibodies to acetylcholine receptor (AChR) and muscle-specific kinase (MuSK). Absence of a disease-specific biomarker and clinical heterogeneity can significantly complicate diagnostic pathway. This study aimed to identify cases misdiagnosed as dSnMG.\nMETHODOLOGY: The study included 33 patients [64% females, median age at onset 30 (22.5-40) years, median age at testing 46 (34-58) years] previously diagnosed with dSnMG. Disease severity was assessed using MG-ADL and QMG at testing, peak MGFA, intensive care unit (ICU) hospitalization and MG crisis history. Indirect immunofluorescence was performed to detect low-density lipoprotein receptor-related protein 4 (LRP4) antibodies. Whole exome sequencing (WES) was conducted, along with genetic testing for myotonic dystrophy type 1 and 2 (DM1 and DM2) and oculopharyngeal muscular dystrophy (OPMD).\nRESULTS: Mean MG-ADL and QMG scores at testing were 1 (0-3) and 6 (3-9), respectively. More than half of the patients had ocular MG (52%). One patient experienced myasthenic crisis. One patient tested positive for LRP4 antibodies, and one was diagnosed with paraneoplastic Lambert-Eaton myasthenic syndrome. WES showed likely pathogenic variant c.517G > A in the CHRNA1 gene associated with autosomal dominant slow channel congenital myasthenic syndrome and only one variant c.2368G > A in the MUSK gene. One patient displayed a DM2 premutation (32-35 CCTG repeats).\nCONCLUSION: This study highlights the importance of considering alternative diagnoses in patients with dSnMG and emphasizes the value of comprehensive testing. Early recognition of causative etiologies can significantly improve patient management and outcome and prevent unnecessary exposure to prolonged immunosuppression.", "authors": ["Ivanovic Vukan", "Peric Stojan", "Briggs Caitlin", "Marjanovic Ana", "Pesovic Jovan", "Basta Ivana", "Jansson Johan", "Randhawa Simrat", "Rajic Sonja", "Gokhale Sankalp"], "journal": "Frontiers in neurology", "entry_date": "2026/04/06 06:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41940306/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Clinic, University Clinical Center of Serbia, Belgrade, Serbia."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41940097", "title": "Case Report and literature review: immune checkpoint inhibitor-associated myasthenia gravis and myocarditis.", "abstract": "To investigate the clinical features of immune checkpoint inhibitor (ICI)-associated myasthenia gravis (MG) with concurrent myocarditis with the aim of enhancing our understanding. We retrospectively analyzed the clinical data of a patient diagnosed with ICI-associated MG and myocarditis, and reviewed the relevant literature. A 67-year-old man was admitted with a 4-day history of right-sided ptosis and blurred vision. His medical history included resection of adenocarcinoma in the right upper lung lobe over 18 years ago and a diagnosis of new lung cancer in the right lower lobe four months prior to presentation. In May 2025, lung cancer recurrence was identified but the patient declined any treatment at that time. In September 2025, following radiotherapy and a single dose of serplulimab (a programmed cell death protein 1 inhibitor, PD-1), the patient developed clinical symptoms including ptosis, a positive fatigue test, and a positive neostigmine test, suggestive of myasthenia gravis. Biochemical tests, electrocardiogram (ECG), and echocardiography indicated myocarditis. The clinical diagnosis was ICI-associated myocarditis. Management involved the discontinuation of immunotherapy, administration of glucocorticoids, and symptomatic supportive treatment, which led to clinical improvement. A literature review summarized 45 cases, indicating that this overlapping immune-related adverse event is rare and has a poor prognosis. Multiple adverse reactions to ICIs can occur simultaneously. Prompt recognition of symptoms and initiation of targeted and effective treatments are crucial for optimizing clinical outcomes.", "authors": ["Shang Zhiyue", "Hao Shuai", "Wang Jianhong", "Li Weirong"], "journal": "Frontiers in cardiovascular medicine", "entry_date": "2026/04/06 06:23", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41940097/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Cardiovascular Hospital Affiliated to Shanxi Medical University; Shanxi Key Laboratory of Heart Failure Precision Medicine, Taiyuan, Shanxi, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41938022", "title": "Aplastic Anemia Proceeding to Thymoma: A Rare Co-Occurrence-A Case Report and Review Article.", "abstract": "BACKGROUND: Malignant thymoma is a rare tumor associated with various paraneoplastic syndromes, such as myasthenia gravis, pure red cell aplasia, and hypogammaglobulinemia. Aplastic anemia (AA) is an uncommon complication of thymoma that may occur during the disease or after thymoma resection. We report a case presented with AA before the thymoma.\nCASE: We report the case of a 34-year-old man with thymoma who developed AA before the detection of the tumor. Although pancytopenia did not improve after thymectomy, prolonged immunosuppressive therapy led to complete resolution of AA. The patient has no recurrence during a 42-month follow-up period.\nCONCLUSION: AA may precede the detection of thymoma and represent its initial clinical manifestation. So, thymoma should be considered a rare cause, along with other more common etiologies of AA. Patients with AA and thymoma require prolonged immunosuppressive therapy after surgery.", "authors": ["Ghazizadeh Maryam", "Ghazizadeh Matin", "Moini Mohammad"], "journal": "Case reports in hematology", "entry_date": "2026/04/06 06:06", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41938022/", "pub_types": ["Journal Article"], "affiliations": ["Department of Hematology-Oncology, Shahid Modarres Hospital, Shahid Beheshti University of Medical Sciences, Tehran, Iran, sbmu.ac.ir."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41937978", "title": "Is Isolated Inferior Rectus Weakness a Strong Indicator for Myasthenia Gravis?", "abstract": "BACKGROUND: Isolated inferior rectus weakness (IRW) has historically been reported as a possible presenting sign of myasthenia gravis (MG). Orthoptists often identify IRW, prompting further investigations. This service evaluation aims to determine whether patients with IRW or other symptoms were subsequently diagnosed with MG.\nMETHODS: A retrospective review of patient case notes was conducted. The cohort included consecutive patients who presented to the adult strabismus service and received acetylcholine receptor antibody (ACR) testing between 2010 and 2023 at a tertiary referral centre in Sheffield.\nRESULTS: Sixty-two patients were included in the analysis. Patients were grouped based on isolated IRW, suspicion of thyroid eye disease, or the presence of MG characteristics. These characteristics included variable diplopia, ocular motility and ptosis; fatigue on elevation; Cogan's lid twitch; MG-like fatigue; and breathing or swallowing difficulties.Ten patients (16.13%) were diagnosed with MG. Of these, six (60%) had ocular MG (OMG). No patients in the isolated IRW group were found to have MG. All MG patients exhibited weakness of multiple extra-ocular muscles (EOM), ranging from 2 to 12 different muscles affected. Each had one or more characteristic MG symptoms or signs, with variability observed in 80% (n = 8).\nCONCLUSION: No cases of MG were identified in patients with isolated IRW. All MG diagnoses were associated with characteristic signs or symptoms. This highlights the importance of detailed clinical history and orthoptic assessment when MG is suspected and poses further questions of whether isolated IRW needs further MG investigative testing.", "authors": ["Butterworth Emma", "Choi Jessy", "Rhodes Martin", "Simmons Joshua"], "journal": "The British and Irish orthoptic journal", "entry_date": "2026/04/06 06:06", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41937978/", "pub_types": ["Journal Article"], "affiliations": ["Sheffield Teaching Hospitals NHS Foundation Trust, UK."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41936404", "title": "Centrifugal Versus Membrane-Based Therapeutic Plasma Exchange in Pediatric Seronegative Neuroimmune Disorders: Neurologic Outcome and Age Specific Safety Profile.", "abstract": "BACKGROUND: This study evaluated the effectiveness of therapeutic plasma exchange (TPE) modalities in seronegative pediatric neuroimmune disorders, focusing on acute therapy response, 6-month neurological outcomes, and age-stratified adverse events.\nMETHODS: Retrospective observational cohort between 2018 and 2024. Neurological outcomes were assessed at five predetermined set points during 6 months.\nRESULTS: Forty-six children underwent 304 TPE procedures in 49 sessions. Early favorable recovery were 84% for autoimmune-encephalitis, 75% for CNS-demyelinating-disorders, 83.3% for Guillan-Barre-syndrome, 66.7% of Juvenile-Myasthenia-Gravis cases. Six-months neurological outcome showed similar recovery rates irrespective-of-TPE-modality used (F[4169] = 0.53, p = 0.711; F[4470] = 0.69, p = 0.602 for CNS and PNS disorders). Adverse events occurred in 20.1% of TPE sessions, were largely age-dependent rather than disease-category or modality-driven, with a 0.891-fold reduction in the likelihood of AE occurrence for each-year increment (OR = 0.891, 95% CI: 0.825-0.962, p = 0.003).\nCONCLUSION: Centrifugal and membrane-based TPE are associated with good neurological recovery in seronegative pediatric neuroimmune disorders. Patient age, rather than apheresis modality or disease subtype, has emerged as the primary determinant of the adverse event profile.", "authors": ["Ongun Ebru Atike", "Aydın Sultan", "Kıhtır Hasan Serdar", "Çebişli Erdem", "Kutluk Muhammed Gultekin", "Özcanyüz Duygu Güner", "Oz Ayse", "Karakuş Volkan"], "journal": "Therapeutic apheresis and dialysis : official peer-reviewed journal of the International Society for Apheresis, the Japanese Society for Apheresis, the Japanese Society for Dialysis Therapy", "entry_date": "2026/04/05 20:23", "pub_date": "2026-04-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41936404/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatric Intensive Care, University of Health Sciences, Antalya Training and Research Hospital, Antalya, Turkey."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41936334", "title": "Systemic and neurologic autoimmune disorders and antibody seropositivity associated with neurosarcoidosis.", "abstract": "BACKGROUND: Comorbid autoimmune disorders and non-specific antibody seropositivity have been commonly reported in prior studies of systemic rheumatologic disorders and neuroimmune diseases. As a disorder without a reliable diagnostic biomarker with diagnosis further complicated by the need for extensive testing to rule-out alternative etiologies, their prevalence in clinical scenarios concerning for neurosarcoidosis has become increasingly relevant. While data related to systemic sarcoidosis has been published, data specific for neurosarcoidosis has not, which is especially important given the limitations in diagnosis posed by the challenges of neural tissue biopsy.\nMETHODS: Adult patients with probable or definite neurosarcoidosis were included if data pertinent to the patient's medical history and serum autoantibody testing were available for review. The frequencies of 18 comorbid autoimmune disorders and seropositivity for 37 antibodies were calculated for the cohort.\nRESULTS: 151 patients were included, the majority of whom were female (87, 57.6%) and Black (113, 74.8%). Patients were aged on average 45.9 years (SD +/- 11.1 years) at the time of neurosarcoidosis diagnosis. Twenty-nine (29/151, 19.2%) unique patients were diagnosed with at least one other autoimmune disorder, including 27 (27/151, 17.9%) with at least one additional systemic autoimmune disorder (most commonly rheumatoid arthritis and inflammatory bowel disease) and two (2/151, 1.3%) with one other neuroimmune disorder (myasthenia gravis, multiple sclerosis). Three (3/151, 2.0%) patients were diagnosed with multiple other autoimmune disorders. A family history of autoimmunity was present in 31 (31/151, 20.5%) patients, including 12 (12/151, 8.0%) with sarcoidosis. 110 patients (110/151, 72.8%) underwent some form of serologic testing, with 30 (30/151, 19.9%) testing positive. 23 (23/151, 15.2%) of these were not linked to a diagnosed non-sarcoidosis autoimmune disorder.\nCONCLUSION: Comorbid autoimmune disorders and non-specific antibody seropositivity are common in neurosarcoidosis and represent potential opportunities for neuroinflammation misattribution and alteration of treatment selection and intensity.", "authors": ["Pitter Danielle", "Trahair Esme", "Ayele Frehiywot", "Hutto Spencer K"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/05 18:08", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41936334/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Emory University School of Medicine, Atlanta, GA, United States of America."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41936333", "title": "Germinal centers are associated with poor prognosis in patients with thymoma-associated myasthenia gravis.", "abstract": "BACKGROUND: Germinal centers (GCs) can be observed in the thymic tissues of individuals with thymoma-associated myasthenia gravis (TAMG). This study aimed to investigate the association between the presence of GCs in the thymus and the clinical outcomes of patients with TAMG following thymoma resection.\nMETHODS: A retrospective review was conducted on patients diagnosed with TAMG who underwent surgical removal of the thymoma. Upon reviewing thymic tissue slides to determine the presence of GCs, patients were divided into GC-positive and GC-negative groups. The association between the presence of GCs and the achievement of minimal manifestation (MM) or pharmacological remission (PR) was analyzed after adjusting for clinical characteristics.\nRESULTS: Of the 111 patients, 41 (36.9%) with thymic follicular hyperplasia were classified into the GC-positive group, and the remaining patients were classified into the GC-negative group. Initial analyses including the entire patient cohort did not demonstrate a significant association between GC and achieving MM or PR post-thymectomy. However, a refined analysis that excluded patients treated with prednisolone before thymectomy revealed a significantly lower cumulative incidence of MM in the GC-positive group (p = 0.011). The presence of GCs was negatively associated with achieving MM, even after adjusting for confounding variables (hazard ratio = 0.479, 95% confidence interval = 0.237-0.968, p = 0.040).\nCONCLUSION: Ectopic GCs in the thymus may serve as a prognostic factor for poor outcomes in patients with TAMG. Further research is needed to elucidate the role of GCs in the pathogenesis of TAMG and predict clinical outcomes following treatment.", "authors": ["Chung Hye Yoon", "Shin Ha Young", "Park Hyung Jun", "Kim Gi Jeong", "Kim Seung Woo"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/05 18:08", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41936333/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yonsei University College of Medicine, Seoul, Republic of Korea; Department of Neurology, Yongin Severance Hospital, Yonsei University Health System, Yongin, Republic of Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41936007", "title": "Effectiveness and safety of ravulizumab in anti-acetylcholine receptor antibody-positive (AChR-Ab+) generalized myasthenia gravis: a systematic review and meta-analysis.", "abstract": "", "authors": ["Sabet Haneen", "Abbas Abdallah", "AbuHamdia Abrar", "Salama Esraa Y", "Abo-Elnour Dina Essam", "Alanazi Sultan Mohammed", "Saleh Mahmoud G A", "Negida Yasmin"], "journal": "Immunologic research", "entry_date": "2026/04/05 11:03", "pub_date": "2026-04-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41936007/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Faculty of Medicine, South Valley University, Qena, Egypt. haninsabet225@gmail.com."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "4区"}, {"pmid": "41934064", "title": "CAR T cell therapy: Autoimmune neurological uses and neurotoxicities.", "abstract": "Chimeric antigen receptor T cell therapy (CAR-T) represents a growing field of cell therapy for the treatment of a range of oncological and autoimmune conditions. From the neurological perspective, it remains limited by immunotoxicities, in particular immune effector cell-associated neurotoxicity syndrome (ICANS) and non-ICANS neurotoxicities, such as movement disorders (parkinsonism) and neurocognitive toxicity, neuropathies, myelopathies, and tumor inflammation-associated neurotoxicity. Despite these potential adverse effects, CAR-T remains promising for the treatment of refractory autoimmune neurological conditions, including myasthenia gravis, multiple sclerosis, chronic inflammatory demyelinating polyneuropathies, stiff person syndrome, and others. CAR-T use for autoimmune neurological disorders marks an exciting paradigm shift from immune suppression to immune reprogramming. Moreover, given success in several T-cell mediated autoimmune conditions, these successful results extend the therapeutic scope of B-cell-targeted CAR-T approaches.", "authors": ["Friedman Alec R", "Gil-Perotin Sara", "Flanagan Wesley Sarah"], "journal": "Best practice & research. Clinical rheumatology", "entry_date": "2026/04/04 02:12", "pub_date": "2026-04-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41934064/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, New York Medical College, Valhalla, NY, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41929601", "title": "Myasthenia gravis and anxiety-depression states: an integrated clinical and Mendelian randomization study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disease affecting the postsynaptic membrane at the neuromuscular junction. Anxiety disorder and depression are common psychiatric comorbidities in patients with MG. However, the potential causal relationship between MG and these mental health conditions remains unclear.\nMETHODS: A retrospective analysis was first conducted to collect relevant data from 96 patients with MG at the time of their initial definitive diagnosis at our center. The cohort was divided into an anxiety group and a non-anxiety group, and into a depression group and a non-depression group. Statistical methods were employed to examine the relationship between MG scale scores and the presence of anxiety and depression. Subsequently, for the first time, we employed a bidirectional two-sample Mendelian Randomization (MR) approach to explore the causal relationships between MG, anxiety disorders, and depression. We utilized the largest and most recent European population genome-wide association studies available for the three phenotypes to extract genetic variants that could serve as instrumental variables. The inverse variance weighted model was used as the primary analysis method. Multiple sensitivity analyses and pleiotropy tests were conducted to validate the robustness of the primary findings.\nRESULTS: In clinical studies, it was observed that 62.5% of MG patients exhibited anxiety symptoms, while 46.90% presented depressive symptoms with myasthenia gravis (MG). Through univariate regression analysis, no direct associations were identified between gender, age, disease duration, or MGFA classification and the occurrence of anxiety and depression. However, Quantitative Myasthenia Gravis (QMG) Score and Myasthenia Gravis Activities of Daily Living (MG-ADL) score were significantly associated with anxiety and depression among patients with MG (p < 0.05). After adjusting for confounding variables, each one-point increase in the QMG score was associated with a 11.9% higher risk of anxiety and a 15.7% higher risk of depression, and each one-point increase in the MG-ADL score, the risk of anxiety and depression increases by 22.5 and 18.5%. These findings suggest that more severe MG symptoms and reduced quality of life are more likely to be accompanied by anxiety and depression. Further Mendelian randomization (MR) analyses provided no evidence supporting the hypothesis that genetically predicted MG influences the risk of anxiety disorders or depression. Reverse MR analysis also failed to reveal any causal relationship between these psychiatric comorbidities and MG. Sensitivity and pleiotropy analyses confirmed the robustness of our results.\nCONCLUSION: In real-world clinical research, patients with MG who have more severe disease are more likely to present with anxiety and depression, and the two conditions show a clear association. However, from a genetic perspective, Mendelian Randomization (MR) analysis does not support a causal relationship between MG and anxiety or depression in European populations. The correlation observed in our clinical research may reflect non-causal associations not explained by genetic liability, potentially involving shared genetic architecture or non-genetic mechanisms.", "authors": ["Luo Lijun", "Zhu Xinyi", "Chen Wenfeng", "Ye Tong", "Yang Jie", "Wei Dongsheng", "Zeng Yaxin", "Yu Ping"], "journal": "Frontiers in neurology", "entry_date": "2026/04/03 05:01", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41929601/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Wuhan No. 1 Hospital, Wuhan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41928893", "title": "Ectopic Cervical Thymoma with Myasthenia Gravis and Pure Red Cell Aplasia: A Case Report.", "abstract": "INTRODUCTION: Ectopic cervical thymoma is an extremely rare tumor, particularly when associated with myasthenia gravis and pure red cell aplasia.\nCASE PRESENTATION: A 65-year-old female was undergoing treatment for myasthenia gravis and pure red cell aplasia at our hospital. Myasthenia gravis symptoms were controlled with prednisolone, and aplasia was managed using oral cyclosporine A. A gradually increasing cervical mass had been noted previously. Needle biopsy of the mass suggested an ectopic thymoma, and the patient was referred for surgery. Preoperative chest CT revealed a 6.5-cm solid mass within the caudal portion of the left thyroid lobe, which was displacing the trachea to the right. No continuity was noted between the cervical lesion and the thymus. Fluorodeoxyglucose PET showed fluorodeoxyglucose uptake in the mass, with a maximum standardized uptake value of 6.48. No other abnormal uptake was observed, including that in the thymus. The preoperative diagnosis was an intrathyroidal ectopic cervical thymoma associated with myasthenia gravis and pure red cell aplasia. Based on the history of myasthenia gravis, both extended thymectomy and left thyroid lobectomy were performed. The postoperative course was uneventful. Histopathological examination showed that the cervical mass was a type AB thymoma. The examination also revealed an occult type A thymoma (Masaoka stage II) in the thymus.\nCONCLUSIONS: We encountered a rare case of type AB ectopic cervical thymoma associated with myasthenia gravis and pure red cell aplasia. Extended thymectomy and cervical tumor resection revealed the presence of an occult type A thymoma in the thymus.", "authors": ["Narusawa Eiji", "Obayashi Kai", "Obayashi Sayaka", "Nagashima Toshiteru", "Kawatani Natsuko", "Yazawa Tomohiro", "Yoshikawa Ryohei", "Matsumura Nozomi", "Shirabe Ken", "Nakazawa Seshiru"], "journal": "Surgical case reports", "entry_date": "2026/04/03 04:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41928893/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of General Surgical Science, Gunma University Graduate School of Medicine, Maebashi, Gunma, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41928685", "title": "Targeting Autoimmunity in Myasthenia Gravis: From Conventional to Novel Therapeutic Approaches.", "abstract": "Myasthenia Gravis is a chronic autoimmune neuromuscular disorder characterized by fluctuating skeletal muscle weakness, most commonly involving ocular, bulbar, respiratory, and limb muscles. This weakness stems from autoantibodies, predominantly immunoglobulin G, against neuromuscular junction components such as acetylcholine receptors or muscle-specific kinase, which ultimately reduces synaptic transmission. MG causes a severe functional impact on normal patients, which often contributes to the reduced quality of life and life-threatening myasthenic crises. This article provides an extensive review of MG's immunopathogenesis with a focus on T and B lymphocytes, pro-inflammatory cytokine involvement, and the components of the complement cascade. Humoral and innate immune mechanisms cooperate and indirectly result from antibodies and continued neuromuscular dysfunction. Clinical MG approval usually depends on a combination of a clinical approach to testing antibodies, electrophysiological technique trials, and, if necessary, imaging methods for thymoma or thymic fusion abnormalities. Regular MG treatment involves acetylcholinesterase inhibitors, corticosteroids, and steroid-sparing immunosuppressant agents (e.g., azathioprine, mycophenolate mofetil). Rapid treatment of MG exacerbations necessitates a process of rapid immunomodulation, including plasma exchanges and intravenous immunoglobulin to rapidly reduce reversed autoantibodies. Novel drug discovery is aimed at targeted immunomodulation, including clinical application of inhibitors of the complement C5 (eculizumab, ravulizumab, zilucoplan), type I neonatal Fc receptor antagonists (efgartigimod, rozanolixizumab), BTK inhibitors, B-cell-directed monoclonal antibodies, and new dendritic cell T cell antireceptor constructs. They can carve out paradigm shifts as these novel resourcing solutions and therapeutic options allow precision medicine to individual immunopathogenic profiles. Synergistic combinations of conventional and modern medicine are a promising comprehensive strategy for MG patients. Reappraisal driven by the biological mechanism, three may deliver better long-term functional outcomes and quality of life.", "authors": ["Chanalia Vishal", "Narwal Smita", "Singh Gurvirender", "Dushyant", "Dhingra Ashwani K", "Grewal Nisha", "Khushbu", "Ashutosh"], "journal": "Protein and peptide letters", "entry_date": "2026/04/03 04:02", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41928685/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pharmacy, Global Research Institute of Pharmacy, Radaur-135133, Yamuna Nagar, Haryana, India."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41928376", "title": "Use of Therapeutic Plasma Exchange in Autoimmune Neuromuscular Disorders.", "abstract": "Therapeutic plasma exchange (TPE) plays a pivotal role in the management of autoimmune neuromuscular disorders by facilitating the removal of pathogenic autoantibodies, immune complexes, and proinflammatory mediators, often resulting in short-term symptomatic improvement. This monograph provides a comprehensive review of the indications, mechanisms, clinical applications, and evidence supporting TPE across a spectrum of autoimmune neuromuscular conditions. TPE is utilized in both acute and maintenance settings, particularly when rapid immunomodulation is required. However, sustained disease control frequently requires combination therapy with immunosuppressive or immunomodulatory agents. Current recommendations are guided by the American Society for Apheresis (ASFA) guidelines, which categorize disorders into four levels (I-IV) based on quality of evidence and clinical utility, with strength of recommendations graded using the GRADE framework. Strong evidence supports the use of TPE in conditions such as Guillain-Barré syndrome (GBS), chronic inflammatory demyelinating polyneuropathy (CIDP), and myasthenia gravis (MG). In selected refractory cases-including stiff-person spectrum disorders (SPS), paraneoplastic neurologic syndromes (PNHS), and idiopathic inflammatory myopathies (IIMs)-TPE may be considered based on clinical judgment and guideline recommendations. Emerging strategies, including immunoadsorption and targeted biologic therapies, are being explored as adjunctive or alternative approaches. This review aims to provide clinicians with an evidence-based framework to optimize the use of TPE in autoimmune neuromuscular disorders.", "authors": ["Memon Anza B", "Lisak Robert P"], "journal": "Muscle & nerve", "entry_date": "2026/04/03 00:16", "pub_date": "2026-04-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41928376/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Wayne State University, School of Medicine, Detroit, Michigan, USA."], "china_related": false, "study_types": ["Guideline/Consensus"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41926961", "title": "[177Lu]Lu-PSMA-617 in combination with pembrolizumab for treatment of metastatic castration resistant prostate cancer (PRINCE): a single-arm, phase 1b/2 study.", "abstract": "BACKGROUND: Lutetium-177 [177Lu]-prostate-specific membrane antigen (PSMA)-617 improves overall survival and progression-free survival in metastatic castration resistant prostate cancer (mCRPC), whereas immune checkpoint inhibitors (ICIs) have limited activity. Preclinical evidence suggests radioligand therapy might induce immunogenic cell death that can be enhanced with ICIs. This study evaluates the activity and adverse event profile associated with multiple doses of [177Lu]Lu-PSMA-617 with pembrolizumab.\nMETHODS: PRINCE was a multicentre, single-arm, phase 1b/2 trial of [177Lu]Lu-PSMA-617 and pembrolizumab. Eligible participants were aged 18 years or older, had mCRPC, an Eastern Cooperative Oncology Group performance status of 0-1, previous androgen receptor pathway inhibitor therapy with previous docetaxel allowed, and high PSMA expression. Participants received up to six cycles of [177Lu]Lu-PSMA-617 intravenously every 6 weeks with 200 mg of pembrolizumab intravenously every 3 weeks for up to 24 months. Co-primary endpoints were safety and 50% prostate-specific antigen (PSA) response rate. All participants who received treatment were included in the analysis. The trial is registered with ClinicalTrials.gov, NCT03658447, and has been completed.\nFINDINGS: Between Aug 22, 2019 and Dec 16, 2020, 37 participants (median age 72 years, IQR 67-76; 27 [73%] docetaxel pretreated) received a median of six cycles (IQR 4-6) of [177Lu]Lu-PSMA-617 and a median of 12 cycles (IQR 6-24) of pembrolizumab. Median follow up was 30 months (IQR 28-31). A decline in PSA of 50% or greater from baseline was observed in 28 (76%, 95% CI 59-88) of the 37 participants. Common treatment-related adverse events were grade 1-2. Grade 3 adverse events included anaemia in one (3%) participant and immune-related adverse events in 11 (30%) participants, including two cases each of fatigue (5%), colitis (5%), and increased serum amylase (5%), and one case (3%) each of pancreatitis, pneumonitis, type 1 diabetes, nephritis, myasthenia gravis, and mucosal pemphigus attributable to pembrolizumab. One participant had co-occurring myasthenia gravis and colitis. There were no grade 4 adverse events or treatment-related deaths.\nINTERPRETATION: Multicycle [177Lu]Lu-PSMA-617 and pembrolizumab showed encouraging activity with manageable toxicity that was consistent with [177Lu]Lu-PSMA-617 or pembrolizumab, and the combination might provide durable clinical benefit in a subset of patients.\nFUNDING: Victorian Cancer Agency, Merck Sharp & Dohme, and Novartis.", "authors": ["Sandhu Shahneen", "Joshua Anthony M", "Emmett Louise", "Bressel Mathias", "Anton Angelyn", "Spain Lavinia", "Horvath Lisa G", "Pasam Anupama", "Tolmeijer Sofie H", "Akhurst Timothy J", "Alipour Ramin", "Banks Patricia", "Buteau James P", "Cassidy Erin", "Crumbaker Megan", "Dhiantravan Nattakorn", "Xu Wen", "Chan Joanna", "Hitchen Nadia", "Scalzo Mark", "Ravi Kumar Aravind S", "Kong Grace", "Wallace Roslyn", "Williams Narelle", "Williams Scott", "Haynes Nicole M", "Neeson Paul", "Wyatt Alexander W", "Hicks Rodney J", "Hofman Michael S"], "journal": "The Lancet. Oncology", "entry_date": "2026/04/02 18:56", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41926961/", "pub_types": ["Journal Article", "Multicenter Study", "Clinical Trial, Phase I", "Clinical Trial, Phase II"], "affiliations": ["Department of Medical Oncology, Peter MacCallum Cancer Centre, Melbourne, VIC, Australia; Sir Peter MacCallum Department of Oncology, The University of Melbourne, Melbourne, VIC, Australia. Electronic address: shahneen.sandhu@petermac.org."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 35.9, "journal_quartile": "1区"}, {"pmid": "41926836", "title": "Diagnosis of Lambert-Eaton myasthenic syndrome: Muscle fatigue with normal manual muscle testing, areflexia, and electrodiagnostic findings.", "abstract": "OBJECTIVE: This study aimed to identify clinically relevant features for the diagnosis of Lambert-Eaton myasthenic syndrome (LEMS) and to elucidate factors associated with diagnostic delay in LEMS.\nMETHODS: Medical records of 12 patients with LEMS and 20 with acetylcholine receptor antibody-positive generalized myasthenia gravis were retrospectively reviewed. Intervals from symptom onset to first primary care visit and to definitive diagnosis were analyzed. In patients with LEMS, correlations between diagnostic intervals and clinical parameters, including manual muscle testing (MMT) sum scores and ulnar compound muscle action potential (CMAP) amplitudes, were assessed.\nRESULTS: All patients with LEMS reported muscle fatigue or general malaise, yet 58% demonstrated normal strength on MMT. Tendon reflexes were absent or reduced in 91.7% of patients. Diplopia and dry mouth were each observed in 41.7% of cases. Reduced ulnar CMAP amplitudes were identified in 91.7% of patients. The median interval from symptom onset to diagnosis was significantly longer in LEMS than in generalized acetylcholine receptor antibody-positive generalized myasthenia gravis (7.5 months vs. 1.5 months; p < 0.0001). A significant positive correlation was found between MMT sum scores and the interval from symptom onset and diagnosis (rs = 0.6403, p = 0.0338, n = 11).\nCONCLUSION: Diagnostic delay in LEMS was associated with the absence of objective muscle weakness on MMT. Key diagnostic features of LEMS included subjective muscle fatigue, reduced or absent tendon reflexes, and decreased CMAP amplitudes, despite normal MMT findings.", "authors": ["Handa Hideo", "Uzawa Akiyuki", "Shibuya Kazumoto", "Kojima Yuta", "Suichi Tomoki", "Yasuda Manato", "Yoshimura Shunsuke", "Motomura Masakatsu", "Kuwabara Satoshi"], "journal": "Journal of neuroimmunology", "entry_date": "2026/04/02 18:06", "pub_date": "2026-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41926836/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41926519", "title": "Association Between Serum Anti-Acetylcholine Receptor (AChR-Ab) Titers and Clinical Outcomes in Patients with Ocular-Onset Myasthenia Gravis: An Academic Retrospective Cohort Study.", "abstract": "BACKGROUND: Acetylcholine receptor antibodies (AChR-Ab) are established biomarkers in myasthenia gravis (MG). In ocular MG (OMG), their presence has been linked to disease severity, treatment response, and progression to generalized MG (GMG); however, the relevance of AChR-Ab titers or seropositivity to ocular manifestations remains uncertain.\nOBJECTIVE AND METHOD: We retrospectively reviewed OMG patients treated at Rajavithi Hospital (2009-2024). AChR-Ab titers were measured using enzyme-linked immunosorbent assay (ELISA). Clinical and demographic factors associated with AChR-Ab seropositivity (AChR-Ab+) and their titers were evaluated using logistic and linear regression analyses.\nRESULTS: Among the 111 patients with OMG, 51 patients (45.9%) were AChR-Ab+ and 60 patients (54.1%) were AChR-Ab-seronegative (AChR-Ab-). The AChR-Ab+ group demonstrated a trend toward younger age compared to the AChR-Ab- group (43.82 ± 6.55 vs 46.53 ± 7.71 years; p = 0.051). AChR-Ab+ patients were more likely to present with diplopia, a higher risk of progression to GMG, and more prevalence of thymoma, whereas ptosis was commonly observed in the AChR-Ab- group. Gender distribution, autoimmune comorbidities, the use and dosages of pyridostigmine or prednisolones were comparable between groups. Advanced age at onset was associated with lower likelihood of AChR-Ab+ (OR 0.922; 95% CI: 0.864-0.983, p = 0.014). Diplopia (OR 5.394; 95% CI: 1.280-22.723, p = 0.022), progression to GMG (OR 4.640; 95% CI: 1.155-18.639, p = 0.031), and thymoma (OR 9.978; 95% CI: 2.094-47.547, p = 0.004) were positively associated with AChR-Ab+ status. Regarding AChR-Ab titers, the presence of thymoma (β =1.556; 95% CI: 0.353-2.761, p = 0.012) was independent predictors, while titers declined with age, most pronounced after 50 years.\nCONCLUSION: Serostatus of acetylcholine receptor antibodies may be useful for identifying MG patients at higher risk of generalization or thymoma, while antibody titers may provide complementary information, particularly in relation to thymoma, rather than serving as direct markers of disease severity or ocular manifestations.", "authors": ["Kemchoknatee Parinee", "Pakaymaskul Pawin", "Piyawanarat Nathorn", "Srisombut Thansit"], "journal": "Clinical ophthalmology (Auckland, N.Z.)", "entry_date": "2026/04/02 13:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41926519/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, Rajavithi Hospital, Rangsit University, Bangkok, Thailand."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41925914", "title": "Efficacy and safety of complement inhibitors and FcRn blockers in generalized AChR antibody-positive myasthenia gravis: a meta-analysis.", "abstract": "BACKGROUND: Antibody status is increasingly used to inform treatment strategies in generalized myasthenia gravis (gMG). We evaluated the efficacy and safety of complement inhibitors and neonatal Fc receptor (FcRn) blockers versus placebo or standard care in adults with acetylcholine receptor antibody-positive (AChR-Ab⁺) gMG.\nMETHODS: We systematically searched MEDLINE, EMBASE, Cochrane Central Register Controlled Trials, and ClinicalTrials.gov through November 2024. Eligible randomized controlled trials (RCTs) informed short-term analyses while long-term outcomes were extracted from open-label extension (OLE) studies. Pooled mean difference (MD) and odds ratio (OR) were calculated using random-effects model.\nRESULTS: Six RCTs (n = 739) and four OLEs (n = 588) evaluating eculizumab, ravulizumab, zilucoplan, efgartigimod, rozanolixizumab, and batoclimab were included. Both drug classes significantly improved mean changes from baseline versus placebo in Myasthenia Gravis Activities of Daily Living [MD 1.7, 95% confidence interval (CI) 1.1-2.3], Quantitative Myasthenia Gravis [MD 2.7, 95%(CI)1.8-3.5], Myasthenia Gravis Composite [MD 6.3, 95%(CI) 5-7.6], MGQoL15r [MD 3.4, 95%(CI)1.2-5.6], and Neuro-QoL [MD 4.5, 95%(CI)1.2-7.7]. Odds of achieving clinically meaningful MG-ADL and QMG improvements were more than doubled (ORs 2.7 and 3.5). Risks of clinical worsening and rescue therapy use were reduced by 72% and 48%, respectively. Complement inhibitors OLEs showed durable benefit up to 156 weeks; 30% of patients reduced corticosteroid doses. Rates of serious adverse events, discontinuation, and mortality were comparable to placebo.\nCONCLUSION: In AChR-Ab⁺ gMG, complement inhibitors and FcRn blockers yield clinically meaningful improvements with favourable safety profiles. Complement inhibition additionally confers sustained benefits and corticosteroid-sparing effects in this population over long-term.\nPROTOCOL REGISTRATION: PROSPERO ID: CRD42024513406.", "authors": ["Filippakopoulou Eugenia", "Gavriilaki Maria", "Arnaoutoglou Marianthi", "Kimiskidis Vasilios", "Di Giovanni Simone"], "journal": "Journal of neurology", "entry_date": "2026/04/02 11:17", "pub_date": "2026-04-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41925914/", "pub_types": ["Journal Article", "Meta-Analysis", "Systematic Review", "Review"], "affiliations": ["Department of Neurology, Imperial College Healthcare NHS Trust Hospital, London, W6 8RF, UK. e.filippakopoulou@nhs.net."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41925081", "title": "HLA-A*11:01 and HLA-C*03 Binding to FKBP1A Influences the Efficacy of Tacrolimus in Myasthenia Gravis Subgroups.", "abstract": "Tacrolimus (TAC) is recommended for the patients with drug tolerance or respond poorly to other conventional immunosuppressants in myasthenia gravis (MG), but its effectiveness is influenced by dose and genetic polymorphism. Studies suggest that HLA polymorphisms are significantly associated with susceptibility to MG, but the relationship between HLA and TAC efficacy in MG has not been explored. In this paper, we investigated the correlation between TAC therapeutic efficacy and HLA in different MG subgroups. HLA-C*03 was associated with a better response to TAC in patients with early-onset MG, generalized MG, and those with a high concentration of TAC. While HLA-A*11:01 showed poor responsiveness to TAC in generalized MG. Furthermore, computational docking was used to demonstrate the binding situation of HLA-A with the TAC binding protein FKBP1A. It showed that HLA-A*11:01 had a higher binding strength with FKBP1A than HLA-C*03, indicating that the combination of different types of HLA and FKBP1A may be one of the reasons affecting its therapeutic efficacy. This study highlights the influence of HLA on the efficacy of TAC among different MG subgroups, providing clues for precise treatment of MG with TAC.", "authors": ["Lv Yuanzhi", "Chen Kangzhi", "Luo Mengchuan", "Ouyang Yuzhen", "Li Kailin", "Luo Zhaohui", "Yang Huan"], "journal": "HLA", "entry_date": "2026/04/02 07:04", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41925081/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, Hunan, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.1, "journal_quartile": "3区"}, {"pmid": "41922674", "title": "Efgartigimod in Patients with Generalized Myasthenia Gravis Refractory or Intolerant to IVIg.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a rare chronic autoimmune disorder of the neuromuscular junction caused by pathogenic autoantibodies directed against a postsynaptic target. The therapeutic landscape of gMG has recently expanded with the introduction of FcRn inhibitors. This study aimed to assess the real-world effectiveness and safety of efgartigimod (EFG) in AChR-positive gMG patients who failed or were intolerant to intravenous immunoglobulin (IVIg).\nMETHODS: EFG was administered as four consecutive weekly intravenous infusions at 10 mg/kg. Treatment efficacy was evaluated using the Myasthenia Gravis Activity of Daily Living (MG-ADL) and Myasthenia Gravis quantitative (QMG) scales at baseline and after 4 weeks. Incidence of adverse events and prednisone use were collected at each time point.\nRESULTS: Thirteen patients (6 women and 7 men, mean age 52.9 years) received EFG following IVIg therapy. After one treatment cycle, both MG-ADL and QMG scores showed significant clinical improvement. MG-ADL responder rate (MG-ADL reduction > 2) was 84.6% while 69.2% on QMG (QMG reduction > 3). Minimal symptom expression was reached in one patient, accompanied by a mean reduction in daily prednisone dose of 6.9 mg.\nCONCLUSION: In this real-world cohort, efgartigimod demonstrated a rapid and meaningful clinical benefit with a favorable tolerability profile in patients with AChR-positive gMG after IVIg failure or intolerance. These findings support the potential role of EFG as an effective therapeutic option in this difficult-to-treat population.", "authors": ["D'Amico Flora", "Campo Sofia", "Rini Nicasio", "Vinciguerra Claudia", "Bevilacqua Liliana", "Erra Carmen", "Barone Paolo", "Tuccillo Francesco", "Habetswallner Francesco", "Brighina Filippo", "Di Stefano Vincenzo"], "journal": "Neurology and therapy", "entry_date": "2026/04/01 23:28", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41922674/", "pub_types": ["Journal Article"], "affiliations": ["Department of Biomedicine, Neuroscience and Advanced Diagnostics (BiND), University of Palermo, 90127, Palermo, Italy."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41922188", "title": "[Research progress on the application of telitacicept in rheumatism and autoimmune diseases].", "abstract": "Traditional treatment regimens for rheumatism and autoimmune diseases are associated with significant adverse effects, and some patients have a limited response, leading to poor prognosis. Telitacicept, a biologic agent and fusion protein targeting B cell activating factor (BAFF) and a proliferation inducing ligand (APRIL), offers a novel therapeutic strategy for refractory rheumatism and autoimmune diseases. Clinical trials have shown promising efficacy and safety. In systemic lupus erythematosus, telitacicept reduces disease activity and facilitates glucocorticoid sparing, with favorable outcomes also observed in pediatric patients. In Sjögren's syndrome, telitacicept achieves sustained improvement in clinical symptoms and disease activity. In rheumatoid arthritis, telitacicept improves the response rates for the American College of Rheumatology 20% improvement criteria (ACR20) and for the American College of Rheumatology 50% improvement criteria (ACR50) while significantly reducing glucocorticoid requirements. In IgA vasculitis, studies focused on patients with renal involvement, and showed efficacy in reducing proteinuria in both adults and children. In myasthenia gravis, telitacicept reduces disease severity and improves quality of life. Additionally, telitacicept has shown preliminary therapeutic potential in IgG4-related disease and granulomatosis with polyangiitis, warranting further investigation. Existing clinical data indicate a favorable overall safety profile for telitacicept. However, attention should be paid to long-term risks of infection, decreased immunoglobulin levels, potential resistance mechanisms, and its efficacy and safety in special populations. This review summarizes recent research progress on the use of telitacicept in rheumatism and autoimmune diseases, aiming to provide a reference for its clinical application.\n风湿病和自身免疫病传统治疗方案副作用明显，部分患者疗效有限，预后不佳。生物制剂泰它西普（telitacicept）作为靶向B细胞活化因子（BAFF）和增殖诱导配体（APRIL）的融合蛋白，为难治性风湿病和自身免疫病治疗提供了新策略，部分临床试验已展现出较好的临床效果及安全性。在系统性红斑狼疮中，泰它西普可降低患者疾病活动度并有助于减少糖皮质激素使用，在儿童患者中也显示较好的疗效。在干燥综合征中，泰它西普可持续改善患者临床症状及疾病活动度。在类风湿关节炎中，泰它西普能提高美国风湿病学会20%改善标准（ACR20）、美国风湿病学会50%改善标准（ACR50）应答率且显著减少激素使用量。在IgA血管炎中，研究主要集中于肾脏受累的患者，在减少成人及儿童蛋白尿方面均有较好疗效。在重症肌无力中，泰它西普可降低疾病严重程度并改善患者生活质量。此外，泰它西普在IgG4相关疾病及肉芽肿性多血管炎等疾病中也初步显示出治疗潜力，仍需进一步探索。现有临床数据表明，泰它西普整体安全性良好，但仍需关注长期应用的感染风险、免疫球蛋白水平下降、潜在耐药机制及其在特殊人群中的疗效及安全性等问题。本文综述了泰它西普在风湿病和自身免疫病中的应用研究进展，以期为泰它西普的临床应用提供参考。.", "authors": ["Wang Xue", "Xu Yihuai", "Tong Guixia", "Zhang Hongxia"], "journal": "Zhejiang da xue xue bao. Yi xue ban = Journal of Zhejiang University. Medical sciences", "entry_date": "2026/04/01 22:12", "pub_date": "2026-04-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41922188/", "pub_types": ["Journal Article", "Review", "English Abstract"], "affiliations": ["Department of Nephrology, Children's Hospital Affiliated to Shandong University (Jinan Children's Hospital), Jinan 250022, China. 782920442@qq.com."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41922037", "title": "Neuro-Ophthalmic Complications of Immune Checkpoint Inhibitors.", "abstract": "Neuro-ophthalmic complications associated with immune checkpoint inhibitors (ICIs) are rare. These involve adverse events primarily affecting the optic nerve, other cranial nerves, and the neuromuscular junction. Myasthenia gravis-like syndrome (often with concomitant myositis) is the most commonly reported immune-related adverse event, followed by optic neuropathy, of which the most notable is optic neuritis. Symptoms typically present within 6 months of exposure. Prompt and comprehensive evaluation is essential. Diagnostic work-up may include MRI brain and orbits, lumbar puncture, serum, and cerebrospinal fluid antibody testing.", "authors": ["Garcia Catherine R", "Al-Zubidi Nagham"], "journal": "Neurologic clinics", "entry_date": "2026/04/01 21:00", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41922037/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University of Kentucky, Lexington, KY, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41919672", "title": "A population-based legacy study of myasthenia gravis in Iceland: insights from a small Arctic nation.", "abstract": "Myasthenia gravis (MG) is a rare autoimmune neuromuscular disorder for which population-based estimates remain scarce, particularly in small, homogeneous settings. Leveraging Iceland's centralized healthcare, we reassessed MG epidemiology and clinical features in a nationwide legacy cohort. Cases diagnosed from 1981 to 2002 were identified through hospital databases, private neurologists, immunology laboratory records and the national MG association. Inclusion required characteristic symptoms plus at least one confirmatory test (response to acetylcholinesterase inhibitors, abnormal electrophysiology, or positive antibodies). Point prevalence was calculated on 31 December 2002, and incidence for 1997-2002. In 2003, patients were evaluated to document diagnostic delay, treatment patterns and disease severity; descriptive statistics and non-parametric tests were applied. Twenty-six patients met criteria, yielding a prevalence of 9.0 per 100,000 and a mean annual incidence of 0.78 per 100,000. The female-to-male ratio was 1.2:1; mean age at onset was 43 years overall (29 in women, 59 in men). Ocular symptoms predominated at presentation. Nineteen percent experienced diagnostic delays exceeding three years. By 2003, 54% had generalized MG and 27% were in complete remission off medication. This historical cohort aligns with global trends of rising prevalence and illustrates the value of legacy datasets for rare disease surveillance.", "authors": ["Hjaltason Haukur", "Ólafsson Haraldur", "Jakobsson Finnbogi", "Klinke Marianne Elisabeth", "Elíasdóttir Ólöf"], "journal": "International journal of circumpolar health", "entry_date": "2026/04/01 07:33", "pub_date": "2026-12-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41919672/", "pub_types": ["Journal Article"], "affiliations": ["Faculty of Medicine, School of Health Sciences, University of Iceland, Reykjavík, Iceland."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41915176", "title": "Opposing effects of efgartigimod and rozanolixizumab on serum albumin levels in patients with generalized myasthenia gravis.", "abstract": "Although efgartigimod and rozanolixizumab are both neonatal Fc receptor (FcRn) inhibitors for generalized myasthenia gravis (MG), they possess distinct molecular structures: efgartigimod is an engineered immunoglobulin G1 (IgG1) Fc fragment, whereas rozanolixizumab is an IgG4 monoclonal antibody. This study aimed to investigate whether these distinct molecular structures induce differential effects on serum albumin in a real-world setting. We conducted a single-center observational study in patients with generalized MG who newly initiated efgartigimod or rozanolixizumab, measuring serum IgG and albumin levels at baseline and the end of the first treatment cycle. We analyzed 21 treatment cycles (efgartigimod, n = 16; rozanolixizumab, n = 5) from 20 patients, including one who received both therapies. Both drugs induced comparable reductions in serum IgG (median: efgartigimod 671.5 mg/dL vs. rozanolixizumab 734.0 mg/dL, p = 0.59). In contrast, their effects on serum albumin levels were diametrically opposed. In the efgartigimod group, albumin levels increased in 15 (94%) cases (median: + 0.45 g/dL), whereas in the rozanolixizumab group, levels decreased in 5 (100%) cases (median: - 0.40 g/dL). The between-group difference in median albumin change was substantial (p = 0.001). Efgartigimod and rozanolixizumab exert opposing effects on serum albumin levels despite similar IgG-lowering efficacy. This modality-specific pattern suggests distinct pharmacological interactions with the FcRn-albumin recycling pathway, potentially influencing treatment selection in specific patient populations.", "authors": ["Yasuda Manato", "Uzawa Akiyuki", "Handa Hideo", "Ogaya Etsuko", "Kurumada Kentaro", "Takasaka Kyosuke", "Mori Masahiro", "Kuwabara Satoshi"], "journal": "Naunyn-Schmiedeberg's archives of pharmacology", "entry_date": "2026/03/31 11:13", "pub_date": "2026-03-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41915176/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, 1-8-1, Inohana, Chuo-ku, Chiba, 260-8670, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41914338", "title": "Ophthalmoplegia Caused by Non-Aneurysm Neurovascular Conflict: Clinical Cases of Eight Patients.", "abstract": "BACKGROUND: Neurovascular conflict (NVC) is a rare but often overlooked cause of oculomotor cranial nerve (OCN) palsy. In this study, we aimed to enhance understanding of NVC as a potential cause of cranial nerve palsies by summarizing the characteristics of eight OCN palsy cases associated with NVC and reviewing previously reported cases.\nMETHODS: A retrospective case series of eight patients with OCN palsy due to NVC was analyzed. Diagnosis was made using 3.0 Tesla magnetic resonance imaging (MRI) with 3D-fast imaging with steady-state acquisition (3D-FIESTA) sequences. Differential diagnoses like myasthenia gravis, inflammatory diseases, and aneurysms were excluded.\nRESULTS: The study involved eight patients (six males, two females), aged 34-78 years (average 58.4 years). Six had abducens nerve palsy, and two had partial oculomotor nerve palsy, all exhibiting painless partial ophthalmoplegia. Imaging revealed OCN compression by various arteries: abducens nerve palsy was due to the basilar artery (three patients), vertebral artery (one patient), and anterior inferior cerebellar artery (two patients); two cases of partial oculomotor nerve palsy were caused by compression of the superior cerebellar artery and the posterior cerebral artery, respectively.\nCONCLUSION: NVC should be considered in patients with abducens nerve palsy, particularly those with intermittent symptoms and painless ophthalmoplegia, especially if they have atherosclerotic risk factors; in this descriptive single-center cohort, diagnosis was supported by high-resolution MRI, including 3D-FIESTA and magnetic resonance angiography.", "authors": ["Kong Xiuyun", "Cui Shilei", "Wang Jiawei", "Jiang Hanqiu"], "journal": "Revista de neurologia", "entry_date": "2026/03/31 06:03", "pub_date": "2026-03-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41914338/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Beijing Tongren Hospital, Capital Medical University, 100730 Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41913390", "title": "Macrophage Activation Syndrome-Associated Hemophagocytic Lymphohistiocytosis Triggered by Myasthenia Gravis: A Rare Hyperinflammatory Complication in a Young Adult.", "abstract": "Macrophage activation syndrome-associated hemophagocytic lymphohistiocytosis (MAS-HLH) is a rare adult hyperinflammatory syndrome, and its occurrence in myasthenia gravis (MG) is exceptionally uncommon. We describe a 25-year-old woman with acetylcholine receptor antibody-positive MG and antiphospholipid antibody positivity who presented with acute hypoxic respiratory failure, encephalopathy, and polyserositis. Despite antimicrobials and MG-directed therapy, she developed persistent fevers, leukocytosis, and worsening neurologic dysfunction. Laboratory evaluation revealed ferritin >7500 ng/mL, fibrinogen of 151 mg/dL, triglycerides of 339 mg/dL, and soluble interleukin-2 (IL-2) receptor of 5551 pg/mL, yielding an HScore of 238 and a >90% predicted probability of HLH. Bone marrow biopsy demonstrated very rare hemophagocytic histiocytes. Extensive infectious, autoimmune, and paraneoplastic evaluation including cerebrospinal fluid cytology, flow cytometry, multiplex meningoencephalitis polymerase chain reaction, and brain magnetic resonance imaging was unrevealing, supporting a diagnosis of secondary MAS-HLH triggered by MG-associated immune dysregulation. Given progressive hyperinflammation and concern for central nervous system (CNS) involvement, the patient received high-dose corticosteroids followed by etoposide, resulting in rapid clinical improvement, declining ferritin, and normalization of IL-2 receptor. She subsequently completed 4 weekly postdischarge etoposide doses with sustained remission. This case underscores the importance of considering HLH in disorders of autoimmunity and immune dysregulation like MG, in patients who develop disproportionate systemic inflammation or neurologic decline and highlights the critical role of early recognition, multidisciplinary evaluation, and timely cytokine-directed immunosuppression in improving outcomes in adult MAS-HLH.", "authors": ["Samperio Victor M", "Zahidi Hiba", "Lim Anthony", "Tsai Henry T"], "journal": "Journal of investigative medicine high impact case reports", "entry_date": "2026/03/31 01:03", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41913390/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Eisenhower Medical Center, Rancho Mirage, CA, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41912936", "title": "Longitudinal omics reveals immune repertoire remodeling in myasthenia gravis patients post-tacrolimus therapy.", "abstract": "Myasthenia gravis (MG) is a T/B cell-driven autoimmune disease. The immunomodulatory mechanisms of the common immunosuppressant tacrolimus (TAC) on the immune repertoire are unclear. This study investigated TAC's immunomodulatory effects via high-throughput sequencing of peripheral blood mononuclear cells from four MG patients pre- and post-four months of TAC monotherapy, revealing dynamic T-cell receptor (TCR) and B-cell receptor (BCR) repertoire remodeling. The immune repertoire of MG patients was characterized by a skewed usage of TRBV gene families compared to healthy controls, indicating an underlying immune dysfunction. Longitudinal analysis post-TAC therapy revealed potential downregulation of IGHV1-69 and IGHV3-43 gene frequencies (p < 0.05, FDR > 0.1), alongside non-significant trends toward shorter CDR3 lengths and reduced clonal diversity in both IGH and TRB (p > 0.05). The BCR repertoire underwent greater dynamic remodeling, while the TCR repertoire remained relatively stable, as evidenced by the persistence of dominant clones and overlapping TRB clones. BCR diversity and V or J gene usage in TCR and BCR showed potential associations with clinical severity. These data reveal skewed antigen recognition profiles in MG pathogenesis, with TAC orchestrating multimodal immunomodulation through peripheral immune repertoire reshaping.", "authors": ["He Ting", "Wang Liu", "Chen Kangzhi", "Zhou Qian", "Xu Liqun", "Luo Zhaohui", "Yang Huan"], "journal": "Genes and immunity", "entry_date": "2026/03/30 23:29", "pub_date": "2026-03-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41912936/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.5, "journal_quartile": "3区"}, {"pmid": "41909657", "title": "Efficacy and safety of efgartigimod in the treatment of impending myasthenic crisis.", "abstract": "OBJECTIVE: To compare the short-term efficacy and safety of efgartigimod versus intravenous immunoglobulin (IVIg) in patients with impending myasthenic crisis (IMC).\nMETHODS: This single-center, randomized, open-label, prospective comparative cohort study included 38 acetylcholine receptor antibody-positive (AChR-Ab+) patients with IMC, which was defined as rapid progression of bulbar or respiratory symptoms within ≤2 weeks, meeting at least one of the following criteria:Myasthenia Gravis Foundation of America (MGFA) grade IVb, a Quantitative Myasthenia Gravis (QMG) bulbar subscore of 3, a respiratory subscore of 2, or a combined bulbar-respiratory subscore ≥4. The participants were included and categorized into either the efgartigimod group (n=21; 10 mg/kg weekly for 4 weeks) or the IVIg group (n=17; 400 mg/kg/day for 5 days). The primary endpoints were the rate of IMC remission within one month (defined as a QMG score <2 for both the bulbar and respiratory items, or a combined bulbar plus respiratory QMG score <4, or an improvement of the MGFA classification to below class IVb, sustained for at least 24 hours.) and time to remission. Secondary outcomes comprised changes in QMG total, bulbar, and respiratory subscores, and Myasthenia Gravis Activities of Daily Living (MG-ADL) from baseline to remission. Safety was assessed by rates of progression to myasthenic crisis (MC) and treatment-emergent adverse events (TEAEs).\nRESULTS: Between January 2024 and March 2025, 38 patients were randomized. IMC remission rates were 90.48% with efgartigimod and 94.12% with IVIg (P = 1.000). The median time to remission was significantly shorter with efgartigimod (8 days; 95% CI: 5.75-10.67) than with IVIg (12 days; 95% CI: 9.92-13.20; P = 0.009). One patient per group progressed to myasthenic crisis (4.76% vs 5.88%). No TEAEs were reported.\nCONCLUSION: Efgartigimod demonstrated comparable efficacy to IVIg for IMC remission but with a significantly faster onset, supporting its role as a rapid and safe alternative.", "authors": ["Li Ning", "Zhang Yinghui", "Liu Lu", "Jin Yanzi", "Zhao Li", "Zhu Shuhui", "Li Yating", "Ma Boya", "Peng Jiahui", "Yang Juan", "Li Qian", "Yang Xiao"], "journal": "Frontiers in immunology", "entry_date": "2026/03/30 06:37", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41909657/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology, General Hospital of Ningxia Medical University, Yinchuan, China."], "china_related": true, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41908611", "title": "A Case of Cryoglobulinemic Vasculitis: Linking Thymectomy, Autoimmune Disease, and Lymphomagenesis.", "abstract": "This case illustrates the possible interplay between autoimmunity, chronic antigenic stimulation, cryoglobulinemic vasculitis, and lymphoproliferative disorders. The patient's progression from myasthenia gravis and total thymectomy to systemic lupus erythematosus, cryoglobulinemic vasculitis, and marginal zone lymphoma demonstrates a continuum of immune dysregulation. Total thymectomy may impair central tolerance, predisposing to secondary autoimmunity and chronic B-cell activation. A 39-year-old woman presented with acute kidney injury, nephrotic-range proteinuria, and pulmonary edema. Laboratory evaluation revealed hypocomplementemia, positive cryoglobulins, a monoclonal IgM band, and elevated rheumatoid factor, findings consistent with cryoglobulinemic vasculitis and immune complex activity. The kidney biopsy demonstrated immune complex-mediated pseudothrombi. She was managed with high-dose corticosteroids, continuous renal replacement therapy, and rituximab, resulting in recovery of renal and cardiac function. During follow-up, she experienced a relapse of cryoglobulinemic vasculitis requiring further rituximab, after which renal function stabilized. This case highlights the complex relationship between thymectomy, autoimmunity, cryoglobulinemic vasculitis, and lymphomagenesis.", "authors": ["Hameed Zainab", "Carlson Nicholas", "Hornum Mads", "Maartensson Nina Loeth", "Nelveg-Kristensen Karl Emil"], "journal": "Kidney medicine", "entry_date": "2026/03/30 06:27", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41908611/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Nephrology, Copenhagen University Hospital - Rigshospitalet, Copenhagen, Denmark."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41906599", "title": "Selective Depletion of Autoreactive Plasma Cells as a Novel Strategy to Treat Acetylcholine Receptor Antibody-Positive Myasthenia Gravis.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disease mediated by autoantibodies targeting the neuromuscular junction and leading to muscle weakness. Although there are autoantibodies of different specificities, most MG patients have autoantibodies directed against the nicotinic acetylcholine receptor (AChR), in particular against the extracellular domain of the α1 subunit (αECD), containing the main immunogenic region (MIR). Here, we demonstrate an original approach to selectively deplete plasma cells secreting autoantibodies targeting αECD. An antibody-mediated cytotoxicity-engager (ACE) consisting of an anti-hCD38-antibody conjugated to hAChR αECD (αECD) was used to deplete hAChR αECD-specific cells selectively in vivo. The reduction of pathogenic cells was accompanied by lower antibody titers, a reduction of MG disease score, protection of grip strength, and maintenance of body weight. Notably, antibody-secreting cells that are nonspecific for hAChR αECD were not affected. The resulting amelioration of MG pathology in ACE-treated animals highlights the decisive role of αECD-antibodies in the pathogenesis of MG and the clinical relevance of the novel therapeutic strategy.", "authors": ["Khodadadi Laleh", "Puppe Deborah", "Cirillo Dilara S", "Martinez-Cingolani Carolina", "Klotsche Jens", "Pelz Andreas", "Kohler Siegfried", "Cheng Qingyu", "Lazaridis Konstantinos", "Fichtner Michael", "Pille Jan", "Kruglov Andrey", "Bondareva Marina", "Alexander Tobias", "Radbruch Andreas", "Meisel Andreas", "Hiepe Falk"], "journal": "European journal of immunology", "entry_date": "2026/03/30 02:53", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41906599/", "pub_types": ["Journal Article"], "affiliations": ["Department of Rheumatology and Clinical Immunology, Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.7, "journal_quartile": "3区"}, {"pmid": "41904994", "title": "Real-world effectiveness and safety of zilucoplan in patients with anti-AChR myasthenia gravis: A retrospective cohort study in France.", "abstract": "ObjectivesTo evaluate the effectiveness and safety of zilucoplan in the real-world treatment setting in France.MethodsThis retrospective cohort study evaluated patients with generalized anti-AChR myasthenia gravis (MG) failing current therapy enrolled in the French early access program (EAP) for zilucoplan. Patients were evaluated at enrollment and at Months 1, 3 and 6 with the MG-ADL score, the Myasthenic Muscle Score (MMS-Garches), and the MG-quality of life questionnaire (MG-QoL15r). MG crises and on-treatment adverse events were documented. MG medication use was compared between the six months before and after enrollment.ResultsForty-eight patients were enrolled and treated with zilucoplan (mean age: 56.2 years; 50.9% men). Thirty patients achieved six months follow-up before the EAP ended. Three patients discontinued zilucoplan due to lack of efficacy. Mean MG-ADL score decreased from 7.4 ± 4.4 to M0 to 2.5 ± 2.7 at M6 (p < 0.0001). 9/43 patients achieved minimal symptom expression at M3 and 12/30 at M6. Mean MMS-Garches score was 67.5 ± 20.0 at M0 and 87.5 ± 13.2 at M6 (p < 0.0001). Mean MG-QoL15r score was 18.2 ± 8.6 at M0 and 8.7 ± 8.3 at M6 (p = 0.0156). 15 patients experienced adverse events, leading to discontinuation in four cases. The mean oral corticosteroid dose decreased from 28.8 ± 11.8 mg to 17.9 ± 11.8 (p = 0.001). Six patients experienced MG crises on treatment, compared to 22 in the six months preceding enrollment. treatment.DiscussionFollowing initiation of zilucoplan treatment, we observed an improvement in MG symptoms and a reduction in MG crises and in exposure to oral corticosteroids. Overall, zilucoplan was well-tolerated with no major adverse events reported.Trial registration informationThe study was registered in the clinicaltrials.gov trial registry under the number NCT06815133 (https://clinicaltrials.gov/study/NCT06815133) on February 4th, 2025.", "authors": ["Tammam Giulia", "Slioui Abderhmane", "Friedman Diane", "Acket Blandine", "Cavalli Michele", "Bresch Saskia", "Lagrange Emmeline", "Sole Guilhem", "Noury Jean-Baptiste", "Barbat Du Closel Luce", "Marois Clémence", "Pakleza Aleksandra Nadaj", "Tard Céline", "Salort-Campana Emmanuelle", "Merle Philippe-Edouard", "Annane Djillali", "Attarian Shahram", "Duval Fanny", "Frachet Simon", "Svahn Juliette", "Pegat Antoine", "Bouhour Françoise", "Taieb Guillaume", "Praline Julien", "Puma Angela", "Fabry Vincent", "Villa Luisa", "Beltran Stéphane", "Behin Anthony", "Cintas Pascal", "Sacconi Sabrina"], "journal": "Journal of neuromuscular diseases", "entry_date": "2026/03/29 18:02", "pub_date": "2026-03-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41904994/", "pub_types": ["Journal Article"], "affiliations": ["Reference Center for Neuromuscular Disorders, Peripheral Nervous System and Muscle Department, Nice University Hospital, Pasteur 2 Hospital, NICE, France."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41904038", "title": "Clinical characteristics and peripheral immune profile analysis of thymoma-associated myasthenia gravis with anti-titin antibodies: a multicenter, retrospective study.", "abstract": "BACKGROUND AND PURPOSE: Thymoma-associated myasthenia gravis (TAMG) patients with anti-titin antibodies exhibit uncertain clinical and immunological relevance.\nMETHODS: We analyzed 91 TAMG patients (40 Titin + group, 51 Titin- group) treated between 2019 and 2025. Clinical features, severity scores, and peripheral immune markers were compared, and finally tested the correlation between the latter and severity.\nRESULTS: Titin + group had higher rates of MGFA ≥ III (55.0% vs. 25.5%, p = 0.004) and elevated QMG bulbar scores [3.00 (0.75-3.00) vs. 0.00 (0.00-0.00), p = 0.002]. They also showed increased platelets (249.4 ± 62.0 vs. 224.2 ± 48.0 × 109/L, p = 0.033), monocytes (0.59 ± 0.27 vs. 0.46 ± 0.23 × 109/L, p = 0.018), and IL-1β [4.20 (1.85-12.06) vs. 1.13 (0.46-3.13) pg/mL, p = 0.009]. IL-6 correlated with MGFA class (r = 0.67, p = 0.004) and QMG respiratory scores (r = 0.70, p = 0.026); NLR with QMG (r = 0.60, p = 0.018) and MG-ADL (r = 0.53, p = 0.044); TNF-α (r = 0.86, p = 0.014) and IL-8 (r = 0.79, p = 0.036) with MG-QoL15; PLR with QMG gross motor (r = 0.53, p = 0.041) and bulbar scores (r = 0.58, p = 0.025); SII and IL-2 with QMG bulbar (r = 0.53, p = 0.046) and respiratory scores (r = 0.78, p = 0.040), respectively.\nCONCLUSION: Anti-titin antibodies positive TAMG is associated with more severe disease-especially bulbar involvement. NLR, PLR, IL-2, IL-6, IL-8, and TNF-α are candidate biomarkers of severity.", "authors": ["Luo Yeting", "Qiu Yusen", "Chai Jingyan", "Luo Si", "Song Ziwei", "Wu Xiangbin", "Dai Tingmin", "Zhou Meihong", "Liu Xianghong", "Hong Daojun"], "journal": "Journal of the Formosan Medical Association = Taiwan yi zhi", "entry_date": "2026/03/28 22:52", "pub_date": "2026-03-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41904038/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Ganzhou Hospital, Jiangxi Medical College, Nanchang University, Jiangxi, 341000, China; Department of Neurology, The First Affiliated Hospital, Jiangxi Medical College, Nanchang University, Nanchang, 340000, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41903794", "title": "Phonatory assessments in patients with slowly progressive neuromuscular disorders: a new tool for evaluating inspiratory muscle dysfunction.", "abstract": "INTRODUCTION: Neuromuscular diseases (NMD) are a group of pathologies that affect the functionality of skeletal muscles and one of the main causes of morbidity and mortality in these patients is respiratory failure secondary to inspiratory muscle dysfunction. The diagnosis of inspiratory muscle dysfunction requires a combination of vital capacity (VC), maximum inspiratory pressure (MIP) and sniff nasal inspiratory pressure (SNIP). To assess whether it is possible using 3 techniques of peak phonation time (MPT) measurement to define lung function (VC < 50%ref) and inspiratory muscle dysfunction (MIP <80 cm H2O or SNIP < 60 cm H2O in women and < 70 cm H2O in men) in patients with MND.\nMATERIALS AND METHODS: All patients with NMD who underwent pulmonary and respiratory muscle function assessment between June 2020 and May 2024 were selected. Vital capacity (VC), maximal inspiratory pressure (MIP), and sniff nasal inspiratory pressure (SNIP) were measured, in addition to evaluating MPT through A-time, Chrono Phonation Time (CPT), and Maximum Phonation Number (MPN).\nRESULTS: Included were 92 patients with slowly progressive NMD (43 women), age 61 ± 14 years; diagnoses were myasthenia gravis (28.7%), myotonic dystrophy (22.8%), Facioscapulohumeral muscular dystrophy (19.6%). A-time, CPT and MPN correlated positively and statistically significantly with VC. Only A-time correlated positively and statistically significantly with MIP. A-time and MPN correlated positively and statistically significantly with SNIP. A-time ≤ 13 s predicted VC < 50%ref and inspiratory muscle dysfunction (sensitivity 59%-specificity 79%). CPT ≤ 15 s, predicts VC < 50%ref and inspiratory muscle dysfunction (sensitivity 52%-specificity 73%). MPN ≤ 18 s, predicts VC < 50%ref and inspiratory muscle dysfunction (sensitivity 56%-specificity 77%).\nCONCLUSION: A-time, CPT and MPN all have values that allow defining the worsening of pulmonary capacity and inspiratory muscle function, which in turn, indicate the need for home mechanical ventilation in patients with slowly progressive MND.", "authors": ["Balaña Corbero A", "Rubio M Á", "Bertran B", "Bona H", "Vallejo C", "Martinez Llorens J"], "journal": "Neurologia", "entry_date": "2026/03/28 20:15", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41903794/", "pub_types": ["Journal Article"], "affiliations": ["Servicio de Neumología, Hospital del Mar. Barcelona, Cataluña, Spain; Unidad Multidisciplinar de ELA, Hospital del Mar. Barcelona, Cataluña, Spain."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41897632", "title": "Myasthenia Gravis in Pregnancy: Prenatal and Postnatal Diagnostic Challenges-A Narrative Review.", "abstract": "Myasthenia gravis (MG) is a prevalent autoimmune disorder affecting neuromuscular junctions, typically characterized by muscle weakness due to autoantibodies targeting acetylcholine receptors (AChR) or muscle-specific kinase (MuSK). Generalized MG is a more severe form of the condition than ocular MG. Although MG can strike at any age, young adult women are typically affected, especially in their reproductive years. MG is rare during pregnancy, with the first trimester and the postpartum period being the most common times for exacerbations. The influence of MG on pregnancy outcomes remains ambiguous, with some studies finding larger prevalence of issues such as preterm birth and small-for-gestational-age babies, while others indicate results similar to the general population. Management of MG during pregnancy necessitates careful monitoring and drug adjustments. Teratogenic concerns make several immunosuppressive drugs, such mycophenolate mofetil and methotrexate, contraindicated. In contrast, medications like prednisolone and pyridostigmine are generally recognized as safe. Women with MG may have flare-ups after giving birth, and infants may have transient neonatal myasthenia gravis. Comprehensive prenatal treatment and multidisciplinary assistance are crucial for promoting maternal and fetal health during pregnancy in women with MG. This paper examines the relevance of immunological biomarkers, RNAs, and other novel biomarkers in myasthenia gravis (MG). It emphasizes the need for more investigation to determine their role in the pathogenesis of MG, evaluate biomarker profiles across subgroups, and look at changes after treatment. The study also underlines the significance of high-throughput investigations to detect new biomarkers and reveal genetic variables impacting MG pathogenesis.", "authors": ["Gerede Angeliki", "Danavasi Maria", "Oikonomou Efthymios", "Papasozomenou Panayiota", "Kourti Vasiliki", "Potiris Anastasios", "Chatzakis Christos", "Stavros Sofoklis", "Koutlaki Nikoletta", "Eleftheriadis Makarios"], "journal": "Diagnostics (Basel, Switzerland)", "entry_date": "2026/03/28 01:19", "pub_date": "2026-03-18", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41897632/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Obstetrics and Gynecology, Democritus University of Thrace, Alexandroupolis Campus, 69100 Alexandroupolis, Greece."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.8, "journal_quartile": "3区"}, {"pmid": "41895886", "title": "Fluctuating, but Not Forgotten: Recognizing Neuromuscular Junction Disorders.", "abstract": "The neuromuscular junction (NMJ), the connection between nerve and muscle, is an essential anatomic site that warrants careful consideration. Dysfunction at this junction often leads to skeletal muscle weakness with a multitude of clinical manifestations. Disorders of the NMJ primarily encompass myasthenia gravis, Lambert-Eaton syndrome, botulism, and organophosphate poisoning. This article will review diseases and disorders of the NMJ, their clinical presentations, and approach to management.", "authors": ["Lowie Bobbi-Jo"], "journal": "Emergency medicine clinics of North America", "entry_date": "2026/03/27 21:55", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41895886/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Emergency Medicine, University of Maryland School of Medicine, 110 S Paca Street, 6th Floor, suite 200, Baltimore, MD 21201, USA. Electronic address: blowie@som.umaryland.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "41895003", "title": "Prevalence and outcomes of co-occurring psychiatric and neurological disorders: An atlas based on umbrella review of 81 meta-analyses.", "abstract": "Psychiatric and neurological disorders often co-occur, complicating their assessment, management, and outcomes. No umbrella review (UR) has summarized the meta-analytic evidence on the co-occurrence of psychiatric and neurological disorders and assessed its credibility. Meta-analytic systematic reviews of observational studies documenting the prevalence and outcomes associated with the co-occurrence of neurological and psychiatric disorders, indexed from inception through August 25, 2025, and meeting established diagnostic criteria, were included. Meta-analytic prevalence and association estimates were recalculated and graded based on quantitative criteria. The AMSTAR-2 assessed the quality of the meta-analyses, while several subgroup analyses and meta-regressions aimed to explain the heterogeneity. We included 81 meta-analyses (N=42,464,788, k=2,273), yielding 166 meta-analytic estimates. Based on pre-existing meta-analytic evidence, among 90 prevalence estimates, 45 (50%) met moderate/strong credibility criteria. Strong credibility emerged in bipolar disorder for comorbid migraine (34.8%,95%CI=25.54-44.69) and chronic pain (28.9%,95%CI=16.4-43.4), in epilepsy for ADHD (22.3%,95%CI=20.3-24.4), depression (23.1%,95%CI=20.6-28.3), autism (11.1%,95%CI=9.8-12.1), and PTSD (7.7%,95%CI=5.2-11.2), in myasthenia gravis for anxiety (33%,95%CI=25.0-42.0 children), in multiple sclerosis for anxiety (36%,95%CI=30.0-42.0) and depression (27.01%,95%CI=22.80-31.68), in neuropathic chronic pain for depression (37.5%,95%CI=28.7-47.1) and anxiety (33.8%,95%CI=28.5-39.6), in neuromyelitis optica for depression (40%,95%CI=32.0-49.0), in stroke for anxiety (29.3%,95%CI=24.8-33.8) and depression (31%,95%CI=24.0-38.0 children), in dementia for depression (25.01%,95%CI=22.1-28.4). Several additional disorders were comorbid in >5%with lower credibility. No outcomes reached strong credibility criteria. The present study provides an atlas of neurological and psychiatric multimorbidity across varying levels of credibility, reinforcing the need for an integrated, multidisciplinary approach to patient care and for more research on actionable risk/protective factors and outcomes.", "authors": ["Fornaro Michele", "Di Lorenzo Chiara", "Steardo Luca", "Stubbs Brendon", "Miola Alessandro", "Kishi Taro", "Radua Joaquim", "Solmi Marco"], "journal": "European neuropsychopharmacology : the journal of the European College of Neuropsychopharmacology", "entry_date": "2026/03/27 19:07", "pub_date": "2026-03-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41895003/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Psychiatry, Federico II University of Naples, Italy. Electronic address: dott.fornaro@gmail.com."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41892369", "title": "Epigenetics of Genes Displaying High and Preferential Expression in Myoblasts.", "abstract": "BACKGROUND/OBJECTIVES: Genome-wide studies of differential DNA methylation often focus on its role in turning transcription on or off. Here we report some atypical epigenetic/transcription relationships for 92 genes that are highly and preferentially expressed in primary human myoblasts relative to heterologous cell cultures.\nMETHODS: We compared methylomes and myoblast-specific differentially methylated regions (DMRs) with methylomes, chromatin profiles, and transcriptomes for many different cell populations.\nRESULTS: We found that myoblast-associated promoter hypomethylation was unusually prevalent among the 92 myoblast-preferential genes. Sometimes this promoter hypomethylation was seen as a myoblast-associated extension of their constitutively unmethylated region at a CpG island. All 92 genes showed some myoblast-specific hypomethylation, including 32 genes at tissue-specific super-enhancers or broad H3K4-trimethylated promoters. Myoblast hypermethylated DMRs were also associated with almost half of the myoblast-preferential genes. These hypermethylated DMRs were often in intragenic locations embedded in H3K36-trimethylated chromatin in myoblasts.\nCONCLUSIONS: Our analysis suggests that some of the hypermethylated DMRs repress cryptic, alternative, or adjacent promoters. Myoblast hypermethylated DMRs may also downmodulate expression in myoblasts to avoid yet higher RNA levels found in adult or fetal skeletal muscle tissue. The epigenetic insights that were obtained can help elucidate the transcription regulation of some of these genes (e.g., MUSK, RAPSN, HEYL, SYNPO2, SYNPO2L, STAC3, PITX2, and TPPP3) that are implicated in congenital myasthenic syndromes, myasthenia gravis, muscle repair, heart dysfunction, or cancer. This study supports cell type-specific roles for DNA hypo- and hypermethylation as a modulator of transcription levels, in addition to being an on-off switch during differentiation.", "authors": ["Ehrlich Kenneth C", "Lacey Michelle", "Pradhan Sriharsa", "Ehrlich Melanie"], "journal": "Epigenomes", "entry_date": "2026/03/27 11:15", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41892369/", "pub_types": ["Journal Article"], "affiliations": ["Center for Bioinformatics and Genomics, Tulane University Health Sciences Center, New Orleans, LA 70112, USA."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "41890833", "title": "Engineered Bi-Specific AChR CAAR T Cells for Selective Elimination of Myasthenia Gravis B Cells.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder caused by autoantibodies targeting the nicotinic acetylcholine receptor (nAChR), which can lead to severe disability and life-threatening crises. Current therapies rely on broad immunosuppression and fail to achieve sustained remission in the majority of patients. Here, we report the development of AChR chimeric autoantibody receptor (CAAR) T cells engineered to selectively eliminate autoreactive B cells producing anti-AChR autoantibodies. T cells were co-transduced with CAARs expressing extracellular domains of the AChR α1 or β1 subunits, enabling recognition of a broad range of pathogenic antibodies. AChR CAAR T cells selectively secreted effector cytokines upon activation, and efficiently lysed target cells. In vivo, they depleted pathogenic B cell lines and reduced autoantibody levels in the circulation and at the neuromuscular junction. These findings establish AChR CAAR T cells as a precision immunotherapy with the potential to achieve durable remission in refractory MG.", "authors": ["von Wardenburg Niels", "Spagni Gregorio", "Reincke S Momsen", "Wernick Stephanie", "Kornau Hans-Christian", "Zinnow Viktoria", "Keles Amelya", "Li Lucie Y", "Homeyer Marie A", "Blumenau Sonja", "Stecklum Maria", "Schmitz Dietmar", "Pelz Andreas", "Damato Valentina", "Sanderson Nicholas", "Derfuß Tobias", "Pham Minh C", "O'Connor Kevin C", "Meisel Andreas", "Prüss Harald"], "journal": "Research square", "entry_date": "2026/03/27 05:16", "pub_date": "2026-03-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41890833/", "pub_types": ["Journal Article", "Preprint"], "affiliations": ["Department of Neurology with Experimental Neurology, Charité - Universitätsmedizin Berlin, corporate member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null}, {"pmid": "41885156", "title": "Advances in Chimeric Antigen Receptor T Cell Therapy in Neuroimmune Diseases.", "abstract": "Antibody therapy is a crucial modality for the treatment of neuroimmune diseases.While it can regulate disease activity in the majority of patients,several individuals remain unresponsive to antibody therapy;additionally,the blood-brain barrier restricts the bioavailability and effectiveness of antibodies within the central nervous system.Unlike antibody therapies,emerging chimeric antigen receptor(CAR)-T cell therapies integrate the biological functions of antibodies that target specific molecules with the potent immune capabilities of T cells,resulting in enhanced therapeutic efficacy,improved tissue permeability,and a more pronounced capacity to eliminate target cells.This study encapsulated the advancements in CAR-T cell therapy for neuroimmune illnesses,aiming to furnish novel insights for the enhancement of CAR-T cell therapy to facilitate its practical use.\n抗体疗法是目前治疗神经免疫性疾病的重要工具,其虽然可以控制大多数患者的疾病活动度,但仍有不少患者对抗体治疗无反应,而血脑屏障也限制了抗体在中枢神经系统内的生物利用度和疗效。与抗体疗法相比,新兴的嵌合抗原受体(CAR)-T细胞疗法则可将靶向特定分子的抗体生物学功能与T细胞强大的免疫功能相结合,使其在一定程度上拥有更高的疗效、更好的组织渗透性和更强的深度消耗靶细胞的能力。本文总结了CAR-T细胞疗法在治疗神经免疫性疾病中的研究进展,以期为CAR-T细胞疗法的优化提供新思路,从而更好地应用于临床。.", "authors": ["Ma Bian-Jun", "Yang Fu-Wen", "Wang Yan-Hong", "Wang Xin"], "journal": "Zhongguo yi xue ke xue yuan xue bao. Acta Academiae Medicinae Sinicae", "entry_date": "2026/03/26 07:03", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41885156/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Third Hospital of Shanxi Medical University(Shanxi Bethune Hospital,Shanxi Academy of Medical Sciences,Tongji Shanxi Hospital), Taiyuan 030032, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41884848", "title": "Immune-related adverse events in patients with preexisting myasthenia gravis and thymoma following immune checkpoint inhibitor treatment: a retrospective, observational study.", "abstract": "OBJECTIVE: Immune checkpoint inhibitors (ICIs) can induce immune system activation and cause immune-related adverse events (irAEs). This study aimed to assess the incidence and management of irAEs in thymoma patients with preexisting MG who received ICI therapy.\nMETHODS: This was a retrospective observational cohort study. From September 2018 to May 2024, 12,916 patients received ICI therapy at our hospital. Among them, six patients with preexisting MG and thymoma (MGT) received ICI treatment, and ten thymoma patients without MG (TOMA) served as controls. irAEs, MG flares, and treatment outcomes were primarily assessed through retrospective review of medical records. Anti-acetylcholine receptor antibody (AChR-Ab) levels and pathological thymoma tissue features were analyzed to explore the potential mechanisms underlying the irAEs.\nRESULTS: Compared with TOMA patients (n=10), all MGT patients (n=6) had grade 3 or higher irAEs (p=0.034) and experienced ICI-induced myocarditis (p=0.011). All MGT patients experienced symptom exacerbation, including a myasthenic crisis. MGT patients who received immunosuppressive agents before ICI therapy and those who received both steroids and intravenous immunoglobulin (IVIG) during irAE occurrence had better outcomes. AChR-Ab levels markedly increased one month after the onset of irAEs. Furthermore, two TOMA patients with germinal centers (GCs) in their thymus tissues had severe irAEs, whereas two without GCs had no irAEs.\nCONCLUSION: In this study, irAEs were common and severe in patients with preexisting MG and thymoma following ICI therapy. Pretreatment immunosuppressive therapy was associated with better clinical outcomes. The presence of GCs in thymoma patients without MG may serve as a predictive biomarker for the occurrence of irAEs.", "authors": ["Sun Chao", "Guo Rongjing", "Yin Xunliang", "Feng Lanlan", "Guo Yize", "Xu Yueliang", "Hao Sijia", "Huang Xiaoxi", "Song Na", "Gao Ting", "Liu Jie", "Gong Li", "Lu Jiayu", "Lu Qiang", "Zhou Yongan", "Chang Ting"], "journal": "Frontiers in immunology", "entry_date": "2026/03/26 05:08", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41884848/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, Tangdu Hospital, The Fourth Military Medical University, Xi'an, Shaanxi, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41884268", "title": "Cardiopulmonary exercise testing in mild generalized myasthenia gravis: an exploratory pilot feasibility study.", "abstract": "INTRODUCTION: We conducted an exploratory pilot feasibility study to assess the safety and feasibility of cardiopulmonary exercise testing (CPET) in patients with mild generalized myasthenia gravis (gMG), aiming to determine whether test termination results from systemic exertion or MG-specific neuromuscular fatigability and to evaluate short-term effects on fatigue.\nMETHODS: Nine patients with mild gMG (median age of 58 years, IQR 46.0-66.5) were included in this exploratory feasibility study and underwent a single maximal incremental CPET on a cycle ergometer with breath-by-breath gas exchange analysis and blood lactate measurements. Predefined exertion criteria (EC) included respiratory exchange rate (RER; ≥1.1), ventilatory equivalent for O2 (EQO2; ≥30), attainment of age-related maximum heart rate (ARMHR), peak blood lactate concentration (>6 mmol·L-1), and Borg Scale for Rated Perceived Exertion (RPE; ≥17). Repetitive nerve stimulation (RNS) was performed before and after CPET to assess neuromuscular fatigability. Fatigue was assessed using the Chalder Fatigue Scale (CFS) at baseline and 4 weeks after CPET.\nRESULTS: CPET was completed by all participants without adverse events. All reported symptoms resolved within 30 min after exercise termination, and no participant required medical intervention. All participants completed the maximal incremental CPET according to the predefined protocol. Among the predefined EC, 44% of participants achieved an RER ≥1.1, 78% an EQO2 ≥30, 44% an ARMHR, 67% reached a peak blood lactate concentration >6 mmol·L-1-, and 67% an RPE ≥17. A decremental response in RNS was observed in 78% both before and after CPET. No relevant changes in CFS scores were detected over 4 weeks.\nDISCUSSION: CPET appears safe and feasible in mild gMG, with exercise termination primarily driven by systemic exertion rather than MG-specific neuromuscular fatigue. CPET may complement clinical evaluation by supporting individualized training recommendations and the identification of cardiopulmonary limitations.", "authors": ["Stascheit Frauke", "Lauermann Maximilian", "Risch Lucie", "Mayer Frank", "Hoffmann Sarah", "Meisel Andreas", "Roecker Kai", "Cassel Michael"], "journal": "Frontiers in physiology", "entry_date": "2026/03/26 05:03", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41884268/", "pub_types": ["Journal Article"], "affiliations": ["Charité - Universitätsmedizin Berlin, Department of Neurology with Experimental Neurology, Berlin, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "41884016", "title": "The prospects of CAR T-cell therapies in changing the therapeutic algorithm of neurologic autoimmunities.", "abstract": "T cells, genetically modified to express chimeric antigen receptors (CAR T), successfully used in hemato-oncologic malignancies, are showing promising and sustained benefits in refractory autoimmune neurological diseases, including Myasthenia Gravis, stiff-person syndrome, neuromyelitis optica, myositis, autoimmune neuropathies, and multiple sclerosis. Several reported patients with a steadily progressive disease and evolving disability unresponsive to available therapies, including rituximab and new biologics, after 2-3 months of treatment with CARs targeting CD19-positive, antibody-secreting, long-lived plasma cells, and plasmablasts exhibit impressive, long-lasting, and drug-free clinical improvements with the potential for immune reset shifting immunity to a healthy state without the need for continuing more immunotherapy cycles. The review discusses what the unmet needs are with the present neuroimmunotherapeutics pointing out the disease stage and patient subsets for which CAR T-therapy is most suitable highlighting that CAR T should be applied in the early stages of disability development when patients reach early-active/refractory status rather than waiting for very late disease progression when neurological deficits might be irreversible. The future trajectory of CAR T cells is also described as a promising means destined to change the present therapeutic algorithm in all neuro-autoimmunites, even offering a promising path toward a cure, pointing out that, in contrast to currently approved biologics that selectively target one immunoregulatory factor, CD19 CAR T cells exert effects even beyond B cells, cross the blood-brain barrier and lymphoid tissues, and expand as \"living cells\" to memory cells ensuring sustained long-term benefits. Key therapeutic uncertainties and practicalities are however highlighted, including the exact duration of CAR T-cell therapy-induced drug-free remissions, logistical challenges, economic limitations, and the need for extensive collaborative efforts with experts in specialized clinical centers.\nWhy CAR T cells can change the future therapies in autoimmune neurological diseases Because at least 20-25% of patients with common autoimmune neurological diseases, like Myasthenia Gravis, Stiff-Person Syndrome, Neuromyelitis, Myositis, Chronic Autoimmune neuropathies or Multiple Sclerosis, do not adequately respond or have stopped responding to current therapies exhibiting progressive or permanent disability, there is a need for novel therapeutic approaches. For such patients with refractory disease, CAR T cells can reverse the ongoing cumulative disability offering even a path toward a cure, without the need for continuing immunotherapy cycles; CAR T-therapies exert these actions because they can travel within the brain and the lymph nodes being able to modify the disease-specific lymphocytes responsible for the immune process and, most importantly, can expand as “living cells” ensuring their long-term benefits. The study discusses how these unique properties of CAR T cells can change the future treatment armamentarium in patients with autoimmune neurological diseases poorly responding to available therapies; describes the most suitable timing CAR T cells should be used after disease progression has begun; and highlights certain current uncertainties, such as the exact duration of CAR T-induced remissions, and economic or logistical challenges.", "authors": ["Dalakas Marinos C"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/03/26 05:00", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41884016/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Thomas Jefferson University, 901 Walnut Street, Philadelphia, PA 19107, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41883304", "title": "Headache prevalence and types in multiple sclerosis and related neuroimmunological diseases: A multicenter study.", "abstract": "AimSeveral studies have reported a higher prevalence of migraine in patients with multiple sclerosis (MS) than in healthy controls (HCs). The aim of this study was to elucidate the headache prevalence in patients with MS or other neuroimmunological disorders, as well as to investigate the associations between headache characteristics and disease activity.MethodsIn this multicenter study in Japan, a headache questionnaire was distributed to patients with MS (n = 338), aquaporin-4 IgG-positive neuromyelitis optica spectrum disorder (NMOSD; n = 106), myelin oligodendrocyte glycoprotein antibody-associated disease (MOGAD; n = 51) or acetylcholine receptor antibody-positive myasthenia gravis (MG; n = 104), and healthy controls (HCs; n = 407). We included only participants aged 18-65 years in this study. The questionnaire responses were classified according to the International Classification of Headache Disorders, 3rd edition. The questionnaire was designed to systematically capture headache characteristics based on established diagnostic criteria.ResultsIn total, any type of headache was found for 54.1% in MS, 63.2% in NMOSD, 43.1% in MOGAD, 43.3% in MG and 43.5% in HCs. After Holm-Bonferroni correction for comparisons among the five groups, the MS (p = 0.015) and NMOSD (p < 0.001) groups had significantly higher odds of any headache compared to the HC group. No difference was observed for migraine (MS 16.0%, NMOSD 16.0%, MOGAD 9.8%, MG 12.5%, HCs 17.0%). In contrast, patients with MS (24.0%) and NMOSD (37.7%) showed a significantly higher frequency of tension-type headache (TTH) than HCs (16.7%) even after adjusting for age and sex. Neither disease activity nor disease-modifying therapy displayed any association with headache severity in patients with MS, NMOSD, or MOGAD.ConclusionsOur study showed no increased prevalence of migraine in MS and other neuroimmunological disorders, whereas TTH comorbidity was higher in MS and NMOSD than in controls.", "authors": ["Masuda Hiroki", "Uzawa Akiyuki", "Shibata Mamoru", "Mori Masahiro", "Miyazaki Yusei", "Niino Masaaki", "Fujimori Juichi", "Nakashima Ichiro", "Takai Yoshiki", "Yamazaki Naoya", "Misu Tatsuro", "Kinoshita Makoto", "Okuno Tatsusada", "Sekiguchi Koji", "Nakahara Jin", "Takeuchi Hajime", "Mizutani Keisuke", "Matsuyoshi Ayano", "Kira Yuu-Ichi", "Iwao Kazunori", "Tanaka Eizo", "Shinoda Koji", "Watanabe Mitsuru", "Masaki Katsuhisa", "Isobe Noriko", "Muto Mayumi", "Ohtani Ryohei", "Aoyama Shinji", "Misawa Sonoko", "Shibuya Kazumoto", "Suichi Tomoki", "Yasuda Manato", "Aotsuka Yuya", "Morooka Marie", "Otani Ryo", "Onishi Yosuke", "Akamine Hiroyuki", "Handa Hideo", "Ogaya Etsuko", "Ogushi Moeko", "Kurumada Kentaro", "Kuwabara Satoshi"], "journal": "Cephalalgia : an international journal of headache", "entry_date": "2026/03/26 04:43", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41883304/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41882900", "title": "Extrathymic malignancies in patients with myasthenia gravis: A Japanese multicenter study.", "abstract": "Objective Although various studies have investigated the association between myasthenia gravis (MG) and malignancies, a clear consensus has not yet been reached. Therefore, this study investigated the relationship between MG and malignancy in patients who developed malignancies. Methods We collected clinical data from the Japan MG Registry 2021 survey, conducted between April and October 2021. The presence of thymoma, MG severity, and extrathymic malignant complications was examined. For patients with concomitant malignancies, the malignancy type, age at onset of malignancy, and use of immune checkpoint inhibitors were assessed. Cox proportional hazards models were used to identify the predictors of malignancy. Results Of the 1690 patients with MG, 115 (6.8%) had malignancies. A multivariable analysis revealed that age at MG onset (hazard ratio [HR] 1.050, 95% confidence interval [CI] 1.037-1.063, P <0.001) and thymoma presence (HR 1.656, 95% CI 1.123-2.444, P = 0.009) were significantly and positively associated with the occurrence of extrathymic malignancies. Conclusion Thymomas and an older MG onset are risk factors for extrathymic malignancies in patients with MG. The development of malignancy should be carefully monitored, particularly in MG patients with thymoma.", "authors": ["Yoshizumi Kazuki", "Watanabe Shohei", "Kimura Takashi", "Igeta Masataka", "Suzuki Shigeaki", "Uzawa Akiyuki", "Masuda Masayuki", "Minami Naoya", "Kawaguchi Naoki", "Kubota Tomoya", "Takahashi Masanori P", "Suzuki Yasushi", "Watanabe Genya", "Konno Shingo", "Sugimoto Takamichi", "Samukawa Makoto", "Akamine Hiroyuki", "Onishi Yosuke", "Yasuda Manato", "Nagane Yuriko", "Murai Hiroyuki", "Utsugisawa Kimiaki"], "journal": "Internal medicine (Tokyo, Japan)", "entry_date": "2026/03/26 00:58", "pub_date": "2026-03-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41882900/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Hyogo Medical University, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41882752", "title": "Escaped surveillance: tuberculosis masked by severe hyponatremia in an immunocompromised patient: a case report.", "abstract": "BACKGROUND: Tuberculosis in immunosuppressed individuals frequently presents atypically and may produce false-negative screening results, delaying diagnosis. Hyponatremia and features of inappropriate antidiuretic hormone secretion can mimic paraneoplastic processes, further complicating the clinical picture. This case describes the challenges of diagnosing tuberculosis in a patient receiving prolonged corticosteroid therapy.\nCASE PRESENTATION: A 74-year-old East Asian woman with long-standing myasthenia gravis treated with prednisone presented with 1 month of progressive weakness, weight loss, gastrointestinal symptoms, cough, shortness of breath, and persistent hyponatremia. Coronavirus disease screening and tuberculin skin testing were negative. Chest imaging revealed a right upper-lobe mass and diffuse pulmonary nodules concerning malignancy. Lung biopsy demonstrated necrotizing granulomatous inflammation, and acid-fast staining of sputum, stool, and ileal tissue confirmed tuberculosis with extrapulmonary ileal involvement. Shortly after initiation of first-line antituberculosis therapy, she developed significant liver injury requiring modification of the regimen. Although she initially improved, she returned 20 days after discharge with abdominal distension and pain due to tuberculosis-associated peritonitis and small-bowel obstruction, necessitating surgical resection.\nCONCLUSION: Negative screening results cannot reliably exclude tuberculosis in immunosuppressed patients. The combination of hyponatremia, nonspecific constitutional symptoms, and atypical pulmonary imaging should prompt early microbiologic evaluation to prevent delay, dissemination, and severe complications.", "authors": ["Bathula Satyamedha", "Pasupuleti Hemalatha", "Waqar Aeman", "DiCarlo Matthew", "Kadirvelu Jayashree", "Choi Sang H"], "journal": "Journal of medical case reports", "entry_date": "2026/03/26 00:54", "pub_date": "2026-03-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41882752/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Medicine/St. George's University School of Medicine, St. George's, West Indies, Grenada."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41878400", "title": "Usefulness of Early Treatment with Efgartigimod in Patients with Generalized Myasthenia Gravis Complicated by Cardiovascular Disease: A Case Report.", "abstract": "BACKGROUND: Generalized myasthenia gravis (gMG) is an autoimmune disease associated with several autoantibodies that attack neuromuscular junctions. Parenteral fast-acting treatment (FT) using steroid pulses, intravenous immunoglobulin (IVIg) and/or plasmapheresis is beneficial for the initial treatment of gMG. However, some patients with gMG have concomitant cardiovascular diseases, such as cardiac insufficiency and ischemic heart disease, in real-world clinical practice. Thus, conventional FT is sometimes difficult to administer in these patients because of its potential cardiovascular side effects.\nCASE PRESENTATION: We report a case of a patient with gMG complicated by cardiovascular disease who was successfully treated with a new therapy using the neonatal Fc receptor inhibitor efgartigimod instead of conventional early FT with steroid pulses, IVIg, and/or plasmapheresis.\nCONCLUSION: Efgartigimod may represent a feasible alternative to conventional FT for the management of gMG, particularly in patients with significant cardiovascular comorbidities.", "authors": ["Kawakita Rie", "Deguchi Kazushi"], "journal": "Case reports in neurology", "entry_date": "2026/03/25 04:30", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41878400/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Gastroenterology and Neurology, Kagawa University Faculty of Medicine, Takamatsu, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41876876", "title": "Assessing respiratory status in myasthenia gravis: limited value of the MG-ADL as a standalone tool compared with spirometry in a Danish cohort.", "abstract": "BACKGROUND: Patients with generalized Myasthenia Gravis (gMG) may develop respiratory involvement, which can be life-threatening. In clinical practice, the Myasthenia Gravis Activities of Daily Living scale (MG-ADL) is often used to assess patient-reported respiratory impairment, as spirometry can be time-consuming and require specialized equipment and expertise. However, it is unclear whether the MG-ADL is a sufficient screening tool for identifying respiratory insufficiency.\nMETHODS: In this cross-sectional study with a longitudinal subgroup, patients completed the MG-ADL, the Myasthenia Gravis Composite scale (MGC), and the Quantitative Myasthenia Gravis score (QMG). As a part of the QMG, spirometry was conducted. All patients had one evaluation, and a subgroup of patients had an additional evaluation after 3 years.\nRESULTS: One hundred patients were screened, and 70 were included and tested. Of these, 25 were retested 3 years later. Respiratory symptoms were reported by 30 (43%) of the 70 patients, though none reported severe symptoms. There was a poor correlation (r = - 0.24, p = .048) between the respiratory item of the MG-ADL and spirometry. Patients with respiratory insufficiency showed improvement over time, as did the MGC score.\nCONCLUSIONS: Our findings indicate limited agreement between patient-reported respiratory symptoms (MG-ADL) and spirometry measures, suggesting that spirometry remains essential for accurate assessment of respiratory function in gMG.", "authors": ["Andersen Linda Kahr", "Birnbaum Simone", "Missel Malene", "Petersen Kristine Grøsfjeld", "Mohringer Cas", "Deurell Eva", "Witting Nanna", "Vissing John"], "journal": "Journal of neurology", "entry_date": "2026/03/25 00:30", "pub_date": "2026-03-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41876876/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Copenhagen Neuromuscular Center, Department of Neurology, Copenhagen University Hospital - Rigshospitalet, Inge Lehmanns Vej 8, 2100, Copenhagen, Denmark. linda.kahr.andersen@regionh.dk."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41874899", "title": "Cardiac herniation six years after thoracoscopic thymectomy: a case report.", "abstract": "BACKGROUND: Cardiac herniation is a rare but potentially fatal complication that may occur after surgery involving pericardial incision or resection. Most cases develop intraoperatively or in the early postoperative period, and delayed-onset cases after minimally invasive thoracic surgery have not been reported.\nCASE PRESENTATION: A 48-year-old woman developed left shoulder pain and nausea six years after thoracoscopic thymectomy for myasthenia gravis. Electrocardiography indicated ST-segment elevation myocardial infarction. Computed tomography of the chest showed cardiac herniation into the left thoracic cavity and coronary angiography revealed stenosis corresponding to the hernial defect. The patient was diagnosed with coronary artery compression due to cardiac herniation and underwent hernia reduction and coronary artery bypass grafting. The postoperative course was uneventful.\nCONCLUSIONS: Cardiac herniation may occur even long after minimally invasive thoracic surgery and should be considered in patients presenting with chest symptoms or hemodynamic instability.", "authors": ["Ishizuka Yusei", "Hayashida Taiichiro", "Yoshii Tomoaki", "Hasegawa-Moriyama Maiko"], "journal": "JA clinical reports", "entry_date": "2026/03/24 12:23", "pub_date": "2026-03-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41874899/", "pub_types": ["Journal Article"], "affiliations": ["Department of Anesthesiology, Tsuruoka Municipal Shonai Hospital, 4-20 Izumi-Machi, Tsuruoka, Yamagata, 997-8515, Japan. y.ishizuka31@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41874211", "title": "Should Patients With Ocular Myasthenia Gravis Be Started on Immunosuppression to Prevent Generalization?", "abstract": "", "authors": ["Umapathi Thirugnanam N", "Wong Sui H", "Lee Andrew G", "Van Stavern Gregory P"], "journal": "Journal of neuro-ophthalmology : the official journal of the North American Neuro-Ophthalmology Society", "entry_date": "2026/03/24 09:23", "pub_date": "2026-03-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41874211/", "pub_types": ["Journal Article"], "affiliations": ["Singapore National Eye Centre and National Neuroscience Institute (TU), Singapore; Moorfields Eye Hospital (SW); Guy's and St Thomas' Hospitals; Kings College London, United Kingdom; Blanton Eye Institute (AGL), Houston Methodist Hospital, Houston, Texas; and Department of Ophthalmology and Visual Sciences (GPVS), Washington University, St. Louis, Missouri."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41872753", "title": "Complement C5 inhibition with eculizumab or ravulizumab is associated with increased cardiovascular and thromboembolic risk after ST-elevation myocardial infarction: a propensity-matched global retrospective cohort study.", "abstract": "BACKGROUND: Complement-mediated myocardial and vascular injury is a hallmark of ST-elevation myocardial infarction (STEMI). Dysregulated activation of complement component C5 has been implicated in endothelial dysfunction, exacerbated inflammatory responses, and progressive vascular damage during acute ischemia. Experimental data suggest that antagonizing the C5a–C5aR1 axis may attenuate these effects, but clinical evidence regarding the impact of established C5 inhibitors during STEMI remains limited.\nMETHODS: To investigate real-world cardiovascular and thromboembolic outcomes associated with C5 inhibition during STEMI, a propensity score-matched retrospective cohort study using the TriNetX Global Collaborative Network was performed. 174 patients with STEMI who had received Eculizumab or Ravulizumab for pre-existing complement-mediated disorders (paroxysmal nocturnal hemoglobinuria, atypical hemolytic uremic syndrome, neuromyelitis optica, or myasthenia gravis) prior to the index event were compared with 174 matched patients without C5-inhibitor exposure. Outcomes were assessed at 30 days and 365 days after STEMI and included all-cause mortality, stroke or transient ischemic attack (TIA), arrhythmia, thrombotic disorders, major adverse circulatory events (MACE), acute kidney injury (AKI), and cardiomyopathy.\nRESULTS: At 365 days, C5-inhibited patients demonstrated significantly higher risks of death (21.7% vs. 15.8; p < 0.05), stroke/TIA (12.9% vs. 6.8%; p < 0.05), thrombotic disorders (23.8% vs. 11.3%; p < 0.001), MACE (36.8% vs. 22.8%; p < 0.001), and AKI (61.1% vs. 22.5%; p < 0.001). Cardiomyopathy rates were comparable between groups. Arrhythmia occurred less frequently in the C5-inhibition cohort (30.3% vs. 37.4%; p < 0.05). Similar patterns were observed at 30 days, with significantly increased risks for thrombotic disorders, MACE, and AKI in the C5-inhibited group. Hazard ratios confirmed elevated risks for most cardiovascular and thromboembolic outcomes at both time points.\nCONCLUSION: In this global real-world cohort, prior treatment with Eculizumab or Ravulizumab was associated with increased mortality and heightened cardiovascular and thromboembolic risk following STEMI. These findings underscore the need for careful clinical consideration of ongoing C5-inhibitor therapy in the acute management of STEMI and highlight the importance of prospective studies to clarify the mechanistic and clinical implications of complement blockade in acute myocardial ischemia.", "authors": ["Vahldieck Carl"], "journal": "BMC cardiovascular disorders", "entry_date": "2026/03/24 00:53", "pub_date": "2026-03-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41872753/", "pub_types": ["Journal Article"], "affiliations": ["Department of Anesthesiology and Intensive Care Medicine, University Medical Centre Schleswig-Holstein Campus Luebeck, Luebeck, Germany. carl.vahldieck@uksh.de."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "41872575", "title": "Half a century of change: demographic trends and their clinical impact in acetylcholine receptor antibody-positive myasthenia gravis.", "abstract": "BACKGROUND: The impact of myasthenia gravis (MG) changing epidemiology on disease management remains unclear. We investigated how MG subtypes changing over the last 50 years have affected disease prognosis.\nMETHODS: Adult patients with MG onset between 1970 and 2020, followed up at our center for ≥ 2 years, were included in this retrospective study. Demographics, MG subtypes, and antibody (Ab) status over the last 50 years were assessed. Treatment response and adverse events (AEs) were evaluated in acetylcholine receptor (AChR)-MG patients with onset between 2000 and 2020. Treatment goal was defined as Post-Intervention Status of \"minimal manifestations\" or better with corticosteroid dose ≤ 5 mg/day (5 mg-MM-or-better).\nRESULTS: We included 1023 AChR-MG patients, of whom 517 had onset between 2000 and 2020. In the non-thymoma population, the median age at onset increased from 35 years in the 1970 s to 65 in the last decade (p < 0.0001), and the AChR-Ab positivity rate correlated with age at onset (p = 0.0002). Early-onset MG (EOMG) had the highest rate of 5 mg-MM-or-better (62/104, 60%), followed by very late-onset MG (VLOMG, 91/192, 48%; p = 0.0012). Complete stable remission (CSR) was rare in VLOMG (8/192, 4%) and most frequently occurred in EOMG (25/104, 24%; p < 0.0001). At multivariable logistic regression 5 mg-MM-or-better was associated with EOMG, VLOMG, and follow-up duration, while negatively associated with moderate-to-severe MG and treatment-related AEs. VLOMG and late-onset MG, along with the use of steroids plus one or ≥ 2 immunosuppressants, were independent risk factors for AEs.\nDISCUSSION: The increased rate of VLOMG has relevant therapeutic and prognostic implications, mainly related to long-term treatment exposure and high risk of AEs in elderly patients.", "authors": ["Falso Silvia", "Spagni Gregorio", "Monte Gabriele", "Marini Sofia", "Marini Martina", "Alboini Paolo Emilio", "Damato Valentina", "Evoli Amelia", "Iorio Raffaele"], "journal": "Journal of neurology", "entry_date": "2026/03/24 00:31", "pub_date": "2026-03-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41872575/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroscience, Catholic University of the Sacred Heart, Rome, Italy."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41871627", "title": "On the increased prevalence of myasthenia gravis in patients with inflammatory bowel disease.", "abstract": "", "authors": ["Gondim Francisco de Assis Aquino", "Souza Marcellus Henrique Loiola Ponte de", "Braga Lúcia Libanez Bessa Campelo"], "journal": "Arquivos de neuro-psiquiatria", "entry_date": "2026/03/23 20:03", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41871627/", "pub_types": ["Journal Article"], "affiliations": ["Universidade Federal do Ceará, Faculdade de Medicina, Departamento de Medicina Clínica, Serviço de Neurologia, Fortaleza CE, Brazil."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41871626", "title": "Beyond numbers: challenges in assessing myasthenia gravis prevalence in inflammatory bowel disease.", "abstract": "", "authors": ["Messina Christian"], "journal": "Arquivos de neuro-psiquiatria", "entry_date": "2026/03/23 20:03", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41871626/", "pub_types": ["Journal Article"], "affiliations": ["Azienda Sanitaria Provinciale di Catania, Catania, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41870109", "title": "Pediatric Myasthenia Gravis.", "abstract": "Pediatric myasthenia gravis encompasses a heterogenous group of disorders that cause impaired neuromuscular junction transmission. Patients exhibit a characteristic fatigable weakness that can be life-threatening if respiration is affected. In children, myasthenia gravis can be grouped into 3 subtypes: transient neonatal myasthenia (TNM) arising from transplacental antibody transfer, congenital myasthenic syndromes (CMS) related to genetic defects, and juvenile myasthenia gravis (JMG) caused by antibodies to synaptic components. Diagnostic evaluation combines clinical evaluation with serologic and electrophysiologic studies. The condition is managed medically with acetylcholinesterase inhibitors and immunosuppressive agents. Thymectomy is an important part of the treatment of JMG, and intravenous immunoglobulin (IVIG) and plasma exchange (PLEX) play a role in acute, severe exacerbations. Management of the ophthalmic complications, including strabismus and ptosis, is necessary to prevent permanent vision loss from amblyopia.", "authors": ["Fischer Andrew F", "Peragallo Jason H"], "journal": "International ophthalmology clinics", "entry_date": "2026/03/23 09:05", "pub_date": "2026-04-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41870109/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Ophthalmology, Emory University School of Medicine, Atlanta, GA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41869422", "title": "Case Report: Vitiligo and Alopecia Universalis Following Rituximab Therapy in a Patient with Myasthenia Gravis.", "abstract": "Rituximab, an anti-CD20 monoclonal antibody, is being used more frequently to treat refractory autoimmune disorders such as myasthenia gravis. While it is usually well tolerated, rare cases of paradoxical immune-mediated skin reactions have been rarely reported. However, the concurrent development of vitiligo and alopecia universalis following rituximab therapy has not been previously described. We report a rare case of simultaneous vitiligo and alopecia universalis developing during long-term treatment with rituximab in a patient with myasthenia gravis and discuss the clinical course and treatment response. This case report describes a 30-year-old woman with myasthenia gravis who developed vitiligo followed by alopecia universalis during a long term of Rituximab therapy. Cutaneous findings included well-demarcated depigmented patches on the trunks and bilateral arms and diffuse non-scarring alopecia affecting the scalp, eyebrows, eyelashes, and body hair, consistent with 100% score of Severity of Alopecia tool (SALT) indicating Alopecia universalis. Rituximab was discontinued due to a possible drug-reaction. Treatment with oral Baricitinib was initiated to target both vitiligo and alopecia universalis. Within three months, there was significant scalp hair regrowth and re-pigmentation of vitiligo patches with minimal adverse effects. This case highlights a unique temporal association of rituximab therapy and the simultaneous onset of vitiligo and alopecia universalis. Although the relationship between the drug and the onset of the skin diseases cannot be established, it is important to be aware of the possibility of immune-related skin adverse effects during rituximab therapy. Early intervention and the use of Janus kinase inhibitors, such as baricitinib, may lead to good clinical outcomes.", "authors": ["Alzahrani Dhaii", "Niaz Ghassan", "Roblah Tala Musa", "Al-Osaimi Ashwaq Kh", "Alsulaimani Hadeel"], "journal": "Clinical, cosmetic and investigational dermatology", "entry_date": "2026/03/23 06:01", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41869422/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["College of Medicine, King Saud bin Abdulaziz University for Health Sciences, Jeddah, Saudi Arabia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.8, "journal_quartile": "3区"}, {"pmid": "41869344", "title": "Case Report: Dual response to efgartigimod in myasthenia gravis and comorbid autoimmune disorders: a case series.", "abstract": "The coexistence of myasthenia gravis (MG) with other IgG-mediated autoimmune diseases represents a clinically heterogeneous condition, driven by pathogenic autoantibodies. Efgartigimod, a neonatal Fc receptor antagonist, has the ability to clear all IgG subclasses. Here, we report four cases of MG concomitant with IgG-mediated autoimmune diseases, specifically idiopathic inflammatory myopathies (IIM), Isaacs syndrome, autoimmune encephalitis (AE), and IgG4-related disease (IgG4-RD). All of them demonstrated a favorable therapeutic response to efgartigimod, with marked improvement in QMG and MG-ADL scores, along with disease-specific clinical or laboratory manifestations of the overlapping autoimmune conditions. These cases provide preliminary evidence supporting efgartigimod as a promising treatment option for patients with MG complicated by IgG-mediated autoimmune diseases.", "authors": ["Li Yunjia", "Yang Yingying", "Zhu Ying", "Zhu Ruixia"], "journal": "Frontiers in immunology", "entry_date": "2026/03/23 06:01", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41869344/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of China Medical University, Shenyang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41863473", "title": "From Limited Samples to Mechanistic Insights: Exploratory Identification and Functional Validation of a hsa_circ_0062400/hsa_circ_0002397-miR-338-3p-NRP1 Axis in Myasthenia Gravis.", "abstract": "INTRODUCTION: CircRNAs are implicated in various autoimmune diseases, such as Myasthenia Gravis (MG), yet their regulatory mechanisms remain poorly understood. This research investigated the regulatory network of circRNAs, miRNAs, and mRNAs in modulating MG progression.\nMATERIALS AND METHODS: Three MG patients (male: female = 1:2) and three healthy controls were enrolled for microarray analysis. The \"Limma\" package was employed to identify the differentially expressed circRNAs (DECs). Target miRNAs of DECs were predicted via the CircInteractome database, while target genes of miRNAs were predicted utilizing miRWalk, miRTarbase, and TargetScan databases. Cytoscape software was applied to establish the circRNAs-miRNAs-mRNAs network. Thereafter, a dual-luciferase reporter assay was conducted to validate the targeted regulatory relationship between hsa_circ_0062400, hsa_circ_0002397, and miR-338-3p. The expression of NRP1 was measured by qRT-PCR and Western blotting, and the cell viability of Jurkat cells was evaluated via CCK-8 assay. The levels of cytokines (IL-2, IL-6, IFN-γ, TNF-α) after NRP1 knockout were detected by ELISA.\nRESULTS: 4 circRNAs, 2 miRNAs, and 11 target genes associated with MG pathogenesis were identified to construct a ceRNA regulatory network. In-vitro assays validated the targeted interactions between hsa_circ_0062400, hsa_circ_0002397, and miR-338-3p. miR-338-3p negatively regulated both protein and mRNA levels of NRP1. Further, silencing hsa_circ_0062400 or hsa_circ_ 0002397 markedly suppressed NRP1 expression and Jurkat cell proliferation, which was reversed by miR-338-3p inhibitor. Moreover, NRP1 affected the levels of cytokines in Jurkat cells.\nDISCUSSION: The circRNAs were demonstrated to be closely associated with MG etiology, which was also supported by our current discovery that hsa_circ_0062400 and hsa_circ_0002397 regulated the level of NRP1 by sponging miR-338-3p in MG. However, the roles of hsa_circ_0062400 and hsa_circ_0002397 in MG have been rarely reported, which requires further validation. Limitations of this study included a small, gender-imbalanced sample size for microarray analysis and incomplete verification of the ceRNA network. In addition, functional experiments were limited to Jurkat cells, and more in-vivo validation assays were lacking.\nCONCLUSION: Collectively, the present study revealed MG pathogenesis and also provided potential treatment targets for the disease.", "authors": ["Chen Zhimin", "Kong Xiaotong", "He Ping", "Na Risu", "Wang Lihua"], "journal": "Endocrine, metabolic & immune disorders drug targets", "entry_date": "2026/03/21 09:52", "pub_date": "2026-03-18", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41863473/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital, Harbin Medical University, Harbin, 150086, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 8.0, "journal_quartile": "1区"}, {"pmid": "41862942", "title": "Bridging the gap between patient and physician perspectives on management of generalized myasthenia gravis: a Delphi consensus study.", "abstract": "BACKGROUND: There is currently limited data to guide treatment selection, dosing, combination strategies and sequencing in the management of myasthenia gravis (MG). Additionally, MG symptoms are heterogenous between people and with time, requiring an individualized treatment approach. As such, successful patient-physician communication is key. This Delphi project was undertaken by MG specialists and patient representatives to explore their opinion on improving MG management via effective physician-patient communication and collaboration approach.\nMETHODS: This mixed-methods study was conducted in two phases. In Phase I, seven MG specialists and two patient representatives contributed to idea generation. Relevant insights informed the development of the Phase II Delphi survey. A panel of 16 MG specialists and seven patient representatives participated in a two-round Delphi survey. Consensus was defined as ≥ 70% agreement or disagreement on a 6-point Likert scale. Participants responded to the survey from what they considered an ideal scenario, regardless of their real-world experience.\nRESULTS: Consensus was achieved on 89% of all statements. Key areas of alignment were – importance of incorporating patient preferences on quality of life (QoL), sustained symptom control, route of administration, and side effects profile. Both groups agreed that current clinical practices insufficiently integrate mental health considerations and patient engagement remains suboptimal. Two key areas of misalignment were – patient representative and physicians had different perspective on how well physicians understood patient preferences and both groups showed different interpretations of side effects (adverse reaction versus issues of tolerability).\nCONCLUSION: This Delphi consensus found that while physician and patient representatives shared similar perspectives these were not always reflected in current clinical practice due to differences in understanding of patient preferences. Prioritizing structured conversations on QoL, treatment expectations, and side effect were found important for physicians while improving access to information, openly communicating and actively participating in treatment decisions were key outcomes for patients. This study lays a valuable foundation for deepening conversations and alignment on key topics in MG management among the medical, patient and caregiving communities.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s13023-026-04312-7.", "authors": ["Chan Andrew", "Kaempf Monika", "Löscher Wolfgang N", "Vissing John", "Voerman Johan", "Frostell-Pyhäjärvi Eva", "Atula Sari"], "journal": "Orphanet journal of rare diseases", "entry_date": "2026/03/21 00:37", "pub_date": "2026-03-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41862942/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Inselspital, Bern University Hospital, University of Bern, Bern, Switzerland. andrew.chan@insel.ch."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.5, "journal_quartile": "2区"}, {"pmid": "41862926", "title": "Interpretable machine learning model predicts postoperative complications after thoracoscopic mediastinal tumor surgery: a multicenter study.", "abstract": "BACKGROUND: Postoperative complications of mediastinal tumors significantly impact patients’ quality of life and long-term outcomes; however, a notable gap in the development of predictive tools for their occurrence remains. This study aimed to develop and validate a machine-learning model predicting thoracoscopic resection complications.\nMETHODS: Patients who underwent thoracoscopic mediastinal tumor resection at Southwest Hospital (January 2014 to April 2024) were retrospectively enrolled (n = 302) and randomly divided into training (70%) and validation (30%) sets. An additional 21 patients from Banan Hospital who underwent the same procedure (October 2023 to April 2024) were included as an external test set. The primary endpoint was postoperative complications within 90 days, with severe complications (Clavien-Dindo grade ≥Ⅱ) as the secondary endpoint. Fifteen predictive models were constructed using three feature selection methods and five machine learning algorithms. Model performance was assessed by AUC, and interpretability was analyzed using SHAP. The optimal model was selected based on the highest AUC values in validation set.\nRESULTS: Among the 302 patients in the main center, postoperative complications were observed in 92 (43.6%) in the training set and 40 (44.0%) in the test set. The Lasso-random forest model performed best, incorporating features like maximum tumor diameter, past medical history, surgical approach, myasthenia gravis, and hypertension (ranked by SHAP-derived feature importance). It achieved an AUC of 0.799 (95% CI: 0.700–0.897), showing robust discrimination and classification ability.\nCONCLUSION: The first web-based machine learning predictive model was developed to guide perioperative management and intraoperative decision-making for high-risk patients.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s12911-026-03440-1.", "authors": ["Wei Ziyan", "Gao Hanfei", "Lei Haiyan", "Xu Qingyuan", "Zhou Yi", "Liu Shuai", "Liu Xi", "Wu Yi", "Wu Wei", "Wu Tao", "He Ping"], "journal": "BMC medical informatics and decision making", "entry_date": "2026/03/21 00:36", "pub_date": "2026-03-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41862926/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Southwest Hospital, Army Medical University, Third Military Medical University, Chongqing, 400038, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.8, "journal_quartile": "2区"}, {"pmid": "41862279", "title": "The Effect of Thymectomy on the Incidence of Extrathymic Cancers and Autoimmune Diseases in Patients With Non-Thymomatous Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Thymectomy is associated with positive effects on myasthenia gravis (MG), but there is conflicting evidence regarding potential deleterious long-term outcomes, such as increased cancer and autoimmune disease risk. We aimed to assess these outcomes in thymectomized versus non-thymectomized MG patients.\nMETHODS: We retrospectively reviewed the medical records of patients with acquired, autoimmune MG followed at the Prosserman Neuromuscular Clinic, University Health Network (UHN), between January 2000 and July 2025. We excluded patients with malignancy or other autoimmune diseases before MG. We created matched datasets (thymectomy vs. no-thymectomy) and built Cox models to assess the rate of new malignancy or autoimmune disease. We also used inverse probability of treatment weights (IPTW) to balance relevant covariates (age at MG onset, sex, disease duration, medications) in the full sample, and tested Cox models in the weighted dataset for each outcome.\nRESULTS: Of 566 patients, 106 had a thymoma and were excluded. Of the 460 patients included, 161 had a thymectomy. There was no difference in the hazard ratio (HR) for a new malignancy in the matched cohort (HR: 0.94, CI 0.83-1.07) nor in the IPTW model. The incidence of autoimmune disease was slightly higher in the thymectomy group in the matched cohort (HR 1.33 [1.15-1.52]), but there was no difference in the IPTW analyses (HR 1.55, CI [0.40-5.9]).\nDISCUSSION: In this cohort of patients with non-thymomatous MG, thymectomy was not associated with an increased risk of malignancy. Different models for a second autoimmune disease had conflicting findings, requiring further research.", "authors": ["Khateb Mohamed", "Almasri Adnan", "Barnett-Tapia Carolina", "Bril Vera"], "journal": "Muscle & nerve", "entry_date": "2026/03/20 22:02", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41862279/", "pub_types": ["Journal Article"], "affiliations": ["Ellen & Martin Prosserman Centre for Neuromuscular Diseases, University Health Network, University of Toronto, Toronto, Ontario, Canada."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41861184", "title": "Burden of glucocorticoid use in commercially insured adults with generalized myasthenia gravis in the United States: A retrospective claims-based analysis.", "abstract": "Generalized myasthenia gravis (gMG) is a chronic autoimmune condition characterized by muscle weakness. If frontline treatments inadequately manage symptoms, patients may require use of glucocorticoids (GC); however, long-term use of GCs is associated with toxicities. Few studies have examined the incidence of GC-related toxicities and economic burden among patients with gMG. This study aims to describe GC toxicities, healthcare resource utilization, and costs among US adults with gMG, stratified by level of GC use. Adults with gMG were identified using IQVIA PharMetrics® Plus data and classified into 2 mutually exclusive cohorts based on GC use during the most recent 12 months of health plan enrollment (study period): \"no GC use\" (no GC fills) or \"any GC use\" (≥1 GC fill). The \"any GC use\" cohort was stratified into \"≥5 mg/d\" (mean prednisone equivalent daily dose ≥5 mg) and \"≥10 mg/d\" (mean prednisone equivalent daily dose ≥10 mg) subgroups. GC use, incident GC toxicities, and all-cause healthcare resource utilization and costs were described during the study period for each cohort and subgroup. Among 8833 patients with gMG, 5076 (57.5%) had no GC use and 3757 (42.5%) had any GC use (≥5 mg/d: 1537 [40.9%]; ≥10 mg/d: 860 [22.9%]). Use of nonsteroidal immunosuppressants was higher among patients with GC use than those without (37.6% any GC use vs 19.6% no GC use). Incident GC toxicities were higher in patients with any GC use than those without (61.9% vs 52.3%). Common acute toxicities included nausea and vomiting, pneumonia, fungal infections, sepsis, and urinary tract infection; chronic toxicities were dyslipidemia, sleep disturbances, obesity, cardiac arrhythmias, and hypertension. Annual all-cause costs were >2x higher among patients with any GC use than those with no GC use ($76,381 vs $35,309). GC acute and chronic toxicities and costs tended to increase with increasing GC use. Since claims data do not contain reasons for diagnoses, toxicities could not be confirmed to be related to GC use. Additionally, results may be confounded by disease severity or concomitant medications. Effective GC-sparing treatments are needed to mitigate the clinical and economic burden of GC use in adults with gMG.", "authors": ["Silvestri Nicholas J", "Park Jenny Y", "Serra Elizabeth", "Gagnon-Sanschagrin Patrick", "Guérin Annie", "Canales Blanca", "Patterson Kristina R", "Meyers Andrea", "Vu Tuan"], "journal": "Medicine", "entry_date": "2026/03/20 15:43", "pub_date": "2026-03-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41861184/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, University at Buffalo Jacobs School of Medicine and Biomedical Sciences, University at Buffalo, Buffalo, NY."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41860006", "title": "Hsa_circ_0000313/miR-1224-3p/MKNK2 Axis Modulates CD4+ T Cells by Activating p38 MAPK Signaling in Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder in which circular RNAs (circRNAs) are increasingly implicated, with growing evidence supporting their critical role in autoimmune pathogenesis. The role of hsa_circ_0000313 in MG, including its biological functions and mechanisms, remains unknown.\nMETHODS: Agarose gel electrophoresis, RNase R digestion, and Sanger sequencing were employed to verify the circular structure of hsa_circ_0000313, while nucleoplasmic separation experiment was used to determine its subcellular localization. Analysis of hsa_circ_0000313, miR-1224-3p, and MKNK2 expression was conducted via quantitative real-time PCR (qRT-PCR). CCK-8 assay and flow cytometry were employed to evaluate the proliferative capacity and apoptotic rate of Jurkat cells. ELISA detected inflammatory cytokine secretion. Potential interactions involving miR-1224-3p with either hsa_circ_0000313 or MKNK2 were predicted using bioinformatics tools and subsequently validated through dual-luciferase reporter assays. FISH assay was used to detect subcellular colocalization of hsa_circ_0000313 and miR-1224-3p.\nRESULTS: We observed that compared to healthy controls, MG patients exhibited increased expression of hsa_circ_0000313 and MKNK2, along with decreased expression of miR-1224-3p. Knockdown of hsa_circ_0000313 and MKNK2, along with overexpression of miR-1224-3p, inhibited the proliferation and secretion of inflammatory factors in Jurkat cells and promoted their apoptosis. Additionally, miR-144-3p was identified as the target miRNA of hsa_circ_0000313, and MKNK2 was identified as the target gene of miR-1244-3p. Hsa_circ_AA0000313 was confirmed to be circular and resistant to RNase R digestion. There was significant colocalization of hsa_circ_0000313 with miR-1224-3p within the cytoplasm. Inhibition of miR-1244-3p reversed the effects of hsa_circ_0000313 knockdown and MKNK2 knockdown on Jurkat cells proliferation, apoptosis, and inflammatory cytokine secretion. In LPS-stimulated Jurkat cells, hsa_circ_0000313 knockdown suppressed the p38 MAPK pathway via the miR-1224-3p/MKNK2 axis, which reduced inflammatory cytokine secretion and cell proliferation as well as promoted apoptosis.\nCONCLUSION: Hsa_circ_0000313 is involved in MG progression by regulating the miR-1224-3p/MKNK2 axis and can act on the p38MAPK pathway to participate in the progression of MG concomitant inflammatory infections, which may provide a promising therapeutic target in MG.", "authors": ["Li Ying", "Kong Xiaotong", "Cai Hanlu", "Tian Wenqi", "Ren Yingjie", "Xu Fanfan", "Peng Shanshan", "Niu Jingyan", "Xin Guanghao", "Wang Jianjian", "Zhang Huixue", "Wang Lihua"], "journal": "Mediators of inflammation", "entry_date": "2026/03/20 06:52", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41860006/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Harbin Medical University, Harbin, Heilongjiang, 15000, China, hrbmush.edu.cn."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.2, "journal_quartile": "3区"}, {"pmid": "41859574", "title": "Very Late-Onset Generalized Myasthenia Gravis Presenting With Worsening Frailty.", "abstract": "Very late-onset myasthenia gravis, defined as disease onset after 75 years of age, is a rare but increasingly recognized clinical entity due to population aging and improved access to diagnostics. We report the case of a woman who was in her 80s and presented with progressive fatigability, bulbar symptoms, and functional decline, initially misattributed to normal aging and degenerative conditions. Clinical examination revealed fluctuating ptosis and proximal muscle weakness, and bedside ice pack testing supported a diagnosis of myasthenia gravis (MG). Serological testing confirmed elevated acetylcholine receptor antibodies. She responded well to a combination of pyridostigmine, low-dose corticosteroids, and mycophenolate mofetil, with improvement tracked via the Quantitative Myasthenia Gravis (QMG) score. This case illustrates the diagnostic challenges of MG in older adults and emphasizes the importance of recognizing reversible causes of frailty. It also highlights the geriatric principle of aligning care with what matters most to the individual, preserving function, independence, and identity.", "authors": ["Saxena Pankhuri", "Bhutani Parul", "Sachidanand Srishti", "Choudhary Nikhil", "Dhar Minakshi"], "journal": "Cureus", "entry_date": "2026/03/20 04:55", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41859574/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Geriatric Medicine, All India Institute of Medical Sciences, Rishikesh, Rishikesh, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41857630", "title": "Neuro-immune interactions underlying autoimmune diseases: insights from brain imaging data.", "abstract": "Autoimmune diseases (AIDs) result from intricate interactions among genetic, environmental and immune factors, with emerging evidence underscoring the role of the central nervous system (CNS) in their pathogenesis. In this study, we utilized two-sample Mendelian randomization to systematically explore the causal relationships between 3,935 brain imaging-derived phenotypes (IDPs) and eight AIDs, including atopic dermatitis, inflammatory bowel disease, lupus erythematosus, multiple sclerosis, myasthenia gravis, psoriasis, rheumatoid arthritis and type 1 diabetes. We identified nine IDPs with causal associations to eight representative AIDs. Mediation analysis uncovered eight potential immune cells or inflammatory factors bridging IDPs and AIDs. These findings provide compelling evidence for the CNS's involvement in autoimmune progresses through neuro-immune pathways and underscore potential diagnostic and therapeutic targets within the neuro-immune axis. This study introduces a novel framework for investigating interdisciplinary interventions that target CNS-immune interactions in the context of AIDs.", "authors": ["Gu Junxiang", "Xing Zixuan", "Wang Jian", "He Yalong", "Li Juan", "Wu Cong", "Kuo Wenlei", "Yan Xianxia", "Lin Wei", "Chen Tao"], "journal": "Molecular brain", "entry_date": "2026/03/20 00:38", "pub_date": "2026-03-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41857630/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurosurgery, Xijing Hospital, Fourth Military Medical University, Shaanxi, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41857416", "title": "Italian recommendations for the diagnosis and treatment of myasthenia gravis.", "abstract": "", "authors": ["Fionda Laura", "Alboini Paolo Emilio", "Antozzi Carlo", "Bonifati Domenico Marco", "Damato Valentina", "Habetswallner Francesco", "Inghilleri Maurizio", "Iorio Raffaele", "Liguori Rocco", "Maestri Tassoni Michelangelo", "Maggi Lorenzo", "Mantegazza Renato", "Massa Roberto", "Pegoraro Elena", "Rodolico Carmelo", "Pino Mariangela", "Antonini Giovanni", "Evoli Amelia"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/03/20 00:28", "pub_date": "2026-03-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41857416/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular and Rare Disease Centre, Neurology Unit, Sant'Andrea Hospital, Via di Grottarossa 1035-1039, Rome, 00189 , Italy. laura.fionda@uniroma1.it."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41856686", "title": "Morvan syndrome in a patient with progressing metastatic thymoma and myasthenia gravis.", "abstract": "Morvan syndrome (MoS) is a rare paraneoplastic syndrome that is predominantly characterised by autonomic dysfunction, peripheral nerve hyperexcitability and altered mental status. Cases in literature often describe pre-existing autoimmune diagnoses in patients with MoS, alluding to its association with systemic immune dysregulation.We report a woman presenting with hypersomnolence and fluctuating mental status consistent with MoS who had been previously diagnosed with metastatic thymoma, acetylcholine receptor-positive myasthenia gravis and multiple other chronic medical conditions. The report emphasises the importance of prompt recognition of symptoms and accurate diagnosis in rare diseases, allowing for timely initiation of the appropriate immunotherapy that ultimately led to rapid and significant clinical improvement.", "authors": ["Öztosun Gülşen", "Salemme Ryan", "Kaminski Henry J", "Conway Sarah T"], "journal": "BMJ case reports", "entry_date": "2026/03/19 21:52", "pub_date": "2026-03-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41856686/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Neurology, The George Washington University School of Medicine and Health Sciences, Washington, District of Columbia, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "41854135", "title": "Risk of New-Onset Myasthenia Gravis Following COVID-19 Infection and Vaccination: A Population-Based Case-Control Study.", "abstract": "BACKGROUND: The potential link between myasthenia gravis (MG) and COVID-19 infection or vaccination remains unclear. This study aimed to evaluate the relationship between these factors and new-onset MG.\nMETHODS: A case-control study was conducted using Clalit Health Services' database. We applied a ML algorithm to reduce diagnostic misclassification. The study examined adults with new onset MG, aged 18 or older, between January 2020 and December 2022 for COVID-19 infection (Cohort I) and between January 2021 and December 2022 for Pfizer-BioNTech COVID-19 vaccine (Cohort II). For each new MG case, three controls matched by age, sex, and index date were selected. Prior exposure to either infection or vaccination was assessed within 90 and 180 days for cases and controls.\nRESULTS: In cohort I, 253 new MG cases were identified. A multivariate logistic regression model showed an odds ratio (OR) of 1.44 (95% CI 0.708-2.92) within 90 days post-infection and 1.67 (95% CI 0.98-2.84) within 180 days. In cohort II, 177 new MG cases were detected, with an OR of 1.76 (95% CI 1.049-2.95) within 90 days post-vaccination and 2.45 (95% CI 1.51-3.95) within 180 days.\nCONCLUSION: This study suggests no significant increased risk of new-onset MG following COVID-19 infection, but the Pfizer-BioNTech vaccine appears to be associated with a higher risk of developing MG, particularly within 180 days of vaccination.", "authors": ["Kab Tasneem", "Pardo Keshet", "Hellmann Mark A", "Lotan Itay", "Friedman Yitzhak", "Shochat Tzipora", "Wilf-Yarkoni Adi"], "journal": "European journal of neurology", "entry_date": "2026/03/19 07:24", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41854135/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Rabin Medical Center, Petach Tikva, Israel."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41853948", "title": "Minimal Symptom Expression in Generalized Myasthenia Gravis: A Valuable Patient-Centric Treatment Goal.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a chronic autoimmune neuromuscular disorder characterized by fluctuating muscle weakness and exertional fatigue, often requiring long-term immunosuppressive or biologic treatment. Although international guidelines recommend achieving minimal manifestations as the primary treatment goal, the lack of a standardized measurement approach has limited its application in clinical settings and trials. Minimal Symptom Expression (MSE), defined as a Myasthenia Gravis Activities of Daily Living (MG-ADL) score of 0 or 1, has recently emerged as a practical, patient-centric endpoint that reflects minimal functional burden and aligns with regulatory priorities around patient-reported outcomes.\nRESULTS: This position paper examines the rationale for MSE as a clinically meaningful, actionable treatment target in gMG. We summarize the strengths of the underlying MG-ADL scale and highlight phase 3 trial data showing that MSE is attainable with biologic therapies, including complement and neonatal Fc receptor inhibitors. Data also suggest that achieving MSE correlates with improvements in physician-assessed outcomes and quality of life metrics. However, inconsistencies in how sustained MSE is defined and reported limit comparability across trials.\nCONCLUSION: MSE, as a patient-centric endpoint, can be used alongside clinician-assessed measures and safety measures to support an integrated treatment goal that encompasses both efficacy and tolerability for the treatment of gMG. Future research should further define the clinical utility of MSE and sustained MSE and incorporate stakeholder input to validate MSE as a part of an integrated treatment goal in both clinical trials and real-world clinical practice.", "authors": ["Meisel Andreas", "Uzawa Akiyuki", "Qi Cynthia Z", "Nowacek Dustin", "Guptill Jeff", "Howard James F"], "journal": "European journal of neurology", "entry_date": "2026/03/19 05:33", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41853948/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology With Experimental Neurology, Charité - Universitätsmedizin Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41847264", "title": "Effectiveness and Safety of Eculizumab in Highly Active AChR+gMG and Its Therapeutic Response in Different Subtypes of gMG.", "abstract": "BACKGROUND: Eculizumab had been approved for anti-acetylcholine receptor antibody-positive (AChR+) refractory myasthenia gravis (MG), but its effect on the broader group of highly active generalized myasthenia gravis (gMG) in clinical practice has not been fully uncovered.\nMETHODS: We conduct a retrospective multi-center cohort study with prospectively collected data to explore the effectiveness and safety of eculizumab in highly active patients in clinical practice.\nRESULTS: Thirty-three patients from 4 research centers were included in our study treated with eculizumab. This study contains 1 early onset MG (EOMG), 13 late-onset MG (LOMG), and 19 thymoma-associated MG (TAMG) patients. At week 12, the mean Myasthenia Gravis Activities of Daily Living (MG-ADL) score decreased by 7.97 ± 3.96 points and Quantitative Myasthenia Gravis (QMG) score decreased by 12.88±5.82 points,13 (40%) patients achieved minimal symptom expression (MSE) and 78.7% patients were ADL responders (the improvement of MG-ADL score ≥3 points and lasted for at least 4weeks). The improvement was sustained for 24 weeks. Overall, four patients had experienced myasthenic crisis (MC), and the time to wean from mechanical ventilation (MV) was 6.33±3.21 days. In muscle subdomains analysis, QMG score decreased more obviously in the ocular group (66%) and bulbar group (49%) than in other muscle groups at week 4. Moreover, subgroup analysis showed that the TAMG and LOMG groups exhibited a similar degree of therapeutic effect in symptom control and ADL response. The mean prednisone dose was reduced by 12.84±20.36 mg/day at week 24. Patients in our study showed well tolerance to eculizumab, and none of them experienced meningococcal infections.\nCONCLUSION: Our study confirmed the safety and effectiveness of eculizumab in highly active gMG patients with reducing steroid dose. TAMG and MC may be suitable indications for treatment with eculizumab. All the muscle groups achieved improvements, especially for the extraocular muscles.", "authors": ["Ma Tianying", "Liu Yanan", "Zhu Ying", "Gao Yan", "Wang Xue", "Liang Yong", "Wang Benqiao", "Zhu Ruixia"], "journal": "ImmunoTargets and therapy", "entry_date": "2026/03/18 04:39", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41847264/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Hospital, China Medical University, Shenyang, People's Republic of China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.4, "journal_quartile": "3区"}, {"pmid": "41843997", "title": "Letter regarding impact of corticosteroid use on comorbidities in patients with myasthenia gravis in the US National Veterans Affairs Health Network.", "abstract": "", "authors": ["Goraghani Amirreza Saeedi", "Abasi Ali"], "journal": "Journal of the neurological sciences", "entry_date": "2026/03/17 19:04", "pub_date": "2026-06-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41843997/", "pub_types": ["Letter"], "affiliations": ["School of Medicine, Kerman University of Medical Sciences, Kerman, Iran."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41843177", "title": "Thymic epithelial tumors at the crossroads of immunity, autoimmunity, and immunotherapy.", "abstract": "Thymic epithelial tumors (TETs) sit at a unique intersection of cancer, central tolerance, and autoimmunity. These tumors arise in the thymus, an immune-rich organ responsible for T-cell education, and despite their low tumor mutational burden (TMB) and microsatellite stability, they display paradoxical behavior under immune checkpoint inhibition. This review synthesizes data on thymic biology, paraneoplastic autoimmunity, molecular profiling, and clinical trials of immune checkpoint inhibitors (ICIs) in thymoma and thymic carcinoma. We describe how disruption of autoimmune regulator (AIRE)/Fez family zinc finger 2 (FEZF2)-driven tissue-restricted antigen expression and impaired regulatory T-cell generation collectively permit the escape of autoreactive T cells and foster classic paraneoplastic syndromes such as myasthenia gravis, pure red cell aplasia, and Good syndrome. We then link these baseline defects to the high frequency and severity of immune-related adverse events observed in TET patients treated with ICIs, despite only modest response rates. Emerging \"harm axis\" biomarkers, including autoantibody profiles and composite T- and B-cell perturbations, may help stratify risk and guide treatment selection. Finally, we review rational therapeutic strategies such as vascular endothelial growth factor-tyrosine kinase inhibitors-ICI combinations, radiotherapy-ICI approaches, perioperative immunotherapy, and emphasize the need for biomarker-enriched trial design. TETs provide a powerful model to understand how failure of central tolerance can simultaneously sensitize tumors to immune attack and prime patients for catastrophic toxicity, with implications that extend to other low-TMB, immune-infiltrated malignancies.", "authors": ["Canaslan Kübra", "Moeini Nia Fatemeh", "Baez Maria", "Abolhassani Hassan", "Ridge Natalie", "Bou Zerdan Maroun", "Marks Jennifer", "Rangoonwala Hussain", "Jahanbin Behnaz", "Emami Amir Hossein", "O'Reilly Katie", "Gökmen-Polar Yesim", "Badve Sunil S", "Xu Chunwei", "Hao Yue", "Sharma Aparna", "Upadhya Swasthik", "Galateau Salle Francoise", "Pan Kelsey", "El Olsta Badi", "Shin Dong M", "Ardeshir-Larijani Fatemeh"], "journal": "Cancer immunology, immunotherapy : CII", "entry_date": "2026/03/17 12:17", "pub_date": "2026-03-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41843177/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Oncology, Dokuz Eylul University, Izmir, Turkey."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.1, "journal_quartile": "2区"}, {"pmid": "41841320", "title": "Sexual health in neuromuscular diseases: Neglected challenges revealed by a scoping review.", "abstract": "BACKGROUND: Neuromuscular diseases (NMDs) are heterogeneous disorders causing progressive motor decline, multisystem complications, and reduced quality of life. Sexual health, a key component of well-being, remains largely overlooked. This scoping review mapped and synthesized evidence on sexual dysfunction (SD) in adults with NMDs, focusing on prevalence, underlying mechanisms, and research gaps.\nMETHODS: A systematic search of PubMed, Cochrane Library, and Google Scholar (February-March 2025) identified studies reporting original data on SD in adults with genetically or clinically confirmed NMDs. Citation tracking complemented the search. Data were narratively synthesized following PRISMA-ScR guidelines.\nRESULTS: Twenty-seven studies (1983-2024) including 2428 individuals met the inclusion criteria. Most were cross-sectional and questionnaire-based studies. SD was frequent but heterogeneous across conditions. In myotonic dystrophy, erectile dysfunction often related to hypogonadism; in Charcot-Marie-Tooth disease, higher disease severity correlated with altered desire and satisfaction in women; amyloid neuropathies showed autonomic-related erectile and ejaculatory dysfunction in men and multidimensional impairment in women; inflammatory myopathies revealed high SD prevalence in both sexes; amyotrophic lateral sclerosis involved intimacy loss mainly due to disability and psychosocial distress, despite preserved interest; myasthenia gravis displayed SD mainly associated with mental health conditions, X-linked spinal muscular atrophy showed predominantly endocrine-related SD.\nCONCLUSION: SD is common, multifactorial, and under-recognized in adults with NMDs. The available evidence remains limited by non-inclusive approaches to sexual orientation and intimacy, scarce physiological assessments, and substantial gaps regarding female sexual health, longitudinal data. Integrating sexual health assessment into routine care for people with NMDs should be prioritized.", "authors": ["El Kaïm Audrey", "Banos Marjorie", "Decostre Valérie", "Birnbaum Simone", "Hogrel Jean-Yves", "Gargiulo Marcela"], "journal": "Journal of neuromuscular diseases", "entry_date": "2026/03/17 05:43", "pub_date": "2026-03-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41841320/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Institute of Myology, Neuromuscular Investigation Center, Neuromuscular Physiology and Evaluation Laboratory, GH Pitié-Salpêtrière, Paris, France."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41839388", "title": "Neurological immune-related adverse events of immune-checkpoint inhibitors: an updated review.", "abstract": "Immune checkpoint inhibitors (ICIs) have transformed cancer therapy across multiple tumor types and disease stages. By reinvigorating antitumor immune responses, these agents may also lead to the emergence of immune-related adverse events (irAEs), including a distinct spectrum of neurological toxicities. Although rare, neurological irAEs are clinically significant due to their diagnostic complexity, potential severity, and risk of long-term neurological sequelae or death. Neurological complications of ICI therapy involve the central nervous system, peripheral nervous system, and skeletal muscle, with immune-related myositis, polyradiculoneuropathy, and encephalitis representing the most frequent and severe entities. Clinical presentations are often heterogeneous and may mimic classical neurological disorders, posing diagnostic challenges even for experienced neurologists and underscoring the need for early recognition and multidisciplinary management. Prognosis varies according to the underlying pathophysiological mechanisms, with nonspecific inflammatory forms generally responding favorably to immunosuppressive treatment, while paraneoplastic-like syndromes are more frequently associated with persistent disability. Patients with preexisting or latent autoimmune neurological disorders represent particularly complex populations, as ICIs may unmask latent paraneoplastic neurological syndromes, and patients with myasthenia gravis seem at increased risk of ICI-induced myositis and myocarditis. High-dose glucocorticoids remain the cornerstone of nirAE management; however, emerging pathophysiology-driven therapies offer the potential to improve outcomes in severe cases while preserving antitumor efficacy.", "authors": ["Picca Alberto", "Psimaras Dimitri"], "journal": "Presse medicale (Paris, France : 1983)", "entry_date": "2026/03/16 20:12", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41839388/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuro-Oncology Department, DMU Neurosciences, FHU S2C-HOPE, GH Pitié-Salpêtrière, AP-HP, Paris, France; Sorbonne University, UMR S 1127, Inserm U 1127, CNRS UMR 7225, ICM-Paris Brain Institute, Labeled Team LNCC, Paris, France; OncoNeuroTox Group, Center for Patients with Neurological Complications of Oncologic Treatments, GH Pitié Salpêtrière, Paris, France."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.0, "journal_quartile": "4区"}, {"pmid": "41838109", "title": "SEC-based isolation of phosphatidylserine-liposomes from biological samples for preclinical studies.", "abstract": "Autoimmune diseases represent a significant clinical challenge due to their high prevalence, chronic progression, and profound impact on patients' quality of life. Despite advances in understanding their pathophysiological mechanisms, in most cases, only palliative treatments are available. In this regard, a novel therapeutic approach is under development, using phosphatidylserine-liposomes (PS-Liposomes) encapsulating specific antigenic peptides that trigger the autoimmune attack. By varying the encapsulated antigen, this method offers the potential to treat different autoimmune diseases. The development of robust bioanalytical methods to characterize PS-Liposomes in biological fluids is of great importance to evaluate their efficacy and safety in preclinical trials. This presents a significant challenge due to the presence of extracellular vesicles and proteins in blood with similar size and composition to PS-Liposomes. In this study, size exclusion chromatography (SEC) was assessed for the isolation of PS-Liposomes encapsulating acetylcholine receptor peptide (AChR), intended for myasthenia gravis treatment, from minipig serum samples. A home-packed column filled with Sepharose 2B-CL resin and two commercial columns with agarose resin (qEV 35 nm and qEV 70 nm) were tested by using fluorescently labelled PS-Liposomes. Fractions containing PS-Liposomes were monitored by flow cytometry and qEV columns were selected for further experiments. For PS-liposome preconcentration of the obtained fractions, two different methodologies were also evaluated (Centrisart filters and qEV kit). Lipid and antigenic peptide recoveries obtained for each method were determined by HPLC-ELSD and HPLC-MS, and the optimum isolation and preconcentration approach was selected. Finally, the established methodology was successfully applied to spiked minipig serum with unlabelled PS-Liposomes, and the preservation of structural integrity after isolation was demonstrated by nanoparticle tracking analysis (NTA) and scanning electron microscopy (SEM).", "authors": ["El Ouahabi Oumaima", "Mancera-Arteu Montserrat", "López-Godoy Ángeles", "Latorre Irene", "Salvadó Míriam", "Barneda-Zahonero Bruna", "Rodríguez-Vidal Sílvia", "Sanz-Nebot Victoria"], "journal": "Analytical and bioanalytical chemistry", "entry_date": "2026/03/16 12:13", "pub_date": "2026-03-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41838109/", "pub_types": ["Journal Article"], "affiliations": ["Department of Chemical Engineering and Analytical Chemistry, Institute for Research on Nutrition and Food Safety (INSA·UB), University of Barcelona, Martí i Franquès 1-11, 08028, Barcelona, Spain."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.8, "journal_quartile": "2区"}, {"pmid": "41837820", "title": "Double-Filtration Plasmapheresis Versus Efgartigimod for Generalized Myasthenia Gravis: Severity-Stratified Benefits in a Prospective Observational Multicenter Study.", "abstract": "INTRODUCTION: Double-Filtration plasmapheresis (DFPP) and efgartigimod (EFG) are both effective acute exacerbation therapies for generalized myasthenia gravis (gMG), yet real-world comparative evidence remains limited. This study aims to systematically compare their clinical efficacy and safety to guide individualized treatment strategies.\nMETHODS: This prospective multicenter study (Aug 2019-Mar 2025) evaluated gMG patients treated with a cycle of DFPP (3-5 sessions) or EFG (4 weekly infusions). Primary endpoints included changes in Quantitative Myasthenia Gravis (QMG) and Myasthenia Gravis Activities of Daily Living (MG-ADL) scores from baseline (T0) to post-treatment (T1) and 1 month after T1 (T2). Secondary endpoints covered clinical meaningful improvement (CMI), deep improvement rates (defined as ≥ 5-point reduction in MG-ADL or ≥ 9-point in QMG), immunological changes, and safety.\nRESULTS: Among 66 MG patients (EFG = 41, DFPP = 25), both DFPP and EFG significantly reduced QMG and MG-ADL scores at T1 and T2. In moderate-to-severe gMG (MGFA ≥ IIb), 3/5-session DFPP was superior to 4-infusion EFG at T2 (p < 0.05), while efficacy was comparable in mild cases (MGFA ≤ IIa). Sustained CMI rates (through T2) increased with higher treatment intensity; the 5-session DFPP rate was significantly higher than the 3-session DFPP (85% vs. 45%, p = 0.049) and numerically higher than the 4-infusion EFG (85% vs. 70%, p = 0.413). The proportion of patients achieving deep improvement in 5-session DFPP was higher than 4-infusion EFG. DFPP broadly reduced immunoglobulins/complement versus EFG's selective immunoglobulin G (IgG) reduction. Adverse events occurred in 28.0% of the DFPP group (mainly catheter-related thrombosis) and 39.0% of the EFG group (predominantly headache; p = 0.431), with no serious events reported.\nCONCLUSION: Both DFPP and EFG effectively treat gMG, though DFPP offers greater benefit in moderate-to-severe cases, underscoring the need for individualized therapy.", "authors": ["Wang Kan", "Xin Hanyu", "Zhang Mengze", "Li Qiuju", "Wu Yanan", "Li Xia", "Peng Jing", "Xie Chong", "Zhou Xiajun", "Gao Li", "Pei Xuzhong", "Yang Yiwei", "Wang Yuhui", "Zhong Yuan", "Zhang Lu", "Zhu Desheng", "Guan Yangtai"], "journal": "CNS neuroscience & therapeutics", "entry_date": "2026/03/16 10:33", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41837820/", "pub_types": ["Journal Article", "Multicenter Study", "Observational Study", "Comparative Study"], "affiliations": ["Department of Neurology, Renji Hospital, School of Medicine, Shanghai Jiao Tong University, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.0, "journal_quartile": "2区"}, {"pmid": "41836758", "title": "A high-throughput screening platform for acetylcholinesterase inhibitors using a genetically encoded acetylcholine fluorescent sensor.", "abstract": "Acetylcholinesterase (AChE) is a crucial hydrolytic enzyme in the central nervous system, responsible for the rapid degradation of the neurotransmitter acetylcholine (ACh) in the synaptic cleft, thereby maintaining the balance between neuronal excitation and inhibition. AChE is not only the primary target of neurotoxic agents and organophosphorus pesticides but its aberrant activity is also closely associated with various neurodegenerative diseases such as Alzheimer's disease (AD) and myasthenia gravis. The efficient and rapid discovery and screening of AChE inhibitors hold urgent and significant value for chemical toxin detection, toxicological research, and drug development for neurodegenerative diseases. Addressing the limitations of existing methods, such as low biocompatibility, low detection throughput, relative operational complexity, and high cost, this study innovatively utilizes a genetically encoded biosensor to construct a stable cell line co-expressing the ACh probe and AChE, establishing a novel high-throughput screening method for AChE inhibitors. The results demonstrate that this method achieved to detect AChE inhibitors at micromole level. This method eliminates the need for purified enzymes and toxic chemical reagents (e.g., DTNB in Ellman's assay), significantly reduces cost (by approximately two orders of magnitude), and offers a simplified, rapid, and high-throughput compatible workflow for applications in neurotoxin detection and neurotherapeutic drug discovery.", "authors": ["Li Xinxin", "Yu Yueming", "Li Siyu", "Lin Xueyang", "Yang Chen", "Yang Yufeng", "Wang Shengran", "Zhou Mengwei", "Bao Zhenghao", "Sui Xin", "Feng Wenya", "Yang Jun", "Zuo Daiying", "Luo Yuan", "Wang Yongan", "Du Xianli"], "journal": "Frontiers in bioengineering and biotechnology", "entry_date": "2026/03/16 06:10", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41836758/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pharmacology, Shenyang Pharmaceutical University, Shenyang, China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41836305", "title": "The Fiscal Consequences for the Canadian Government of Efgartigimod in the Treatment of Generalized Myasthenia Gravis.", "abstract": "Background: Generalized myasthenia gravis (gMG) severely impacts activities of daily living. Productivity losses and the need for care can impact household finances and consequently government public accounts. This study adopts a governmental perspective framework to assess the fiscal consequences of treating gMG that is inadequately controlled by standard therapy, beyond healthcare costs. Savings in tax revenue loss and benefit payments are considered. Objectives: To value the fiscal consequences of treating adults with acetylcholine receptor-antibody positive (AChR-Ab+) gMG with efgartigimod vs current treatments. The lifetime impact on people living with gMG and their caregivers is considered from the perspective of Canada's public accounts. Methods: A lifetime Markov cohort simulation following adults with gMG according to their Activities of Daily Living (MG-ADL) score was linked to labor and fiscal stages of both patients and care- givers. Based on the MyRealWorld MG study, MG-ADL scores defined the labor market characteristics of both individuals with gMG and their caregivers. National statistics data on sex- and age-specific labor outcomes were used to model patients with minimal symptoms. Benefit payments and tax revenue losses attributable to gMG were estimated and valued according to national official sources. Public healthcare costs were included. The difference between efgartigimod and current treatments was assessed by discounted lifetime incremental fiscal consequences. Sensitivity analyses were applied to the fiscal parameters. Results: Without active treatments, the lifetime fiscal burden associated with individuals with gMG and their caregivers was estimated at CAD 1.24 m i l l i o n i n g o v e r n m e n t e x p e n d i t u r e s . C o m p a r e d w i t h t h e c u r r e n t w e i g h t e d b u n d l e o f t r e a t m e n t s i n C a n a d a , e f g a r t i g i m o d w a s e s t i m a t e d t o s a v e C A D 458 754 per treated adult. Results were sensitive to the distribution of the bundle of treatments. Discussion: Beyond healthcare costs, gMG severely impacts productivity and governmental accounts. Decision-makers should be provided evidence of fiscal consequences when assessing healthcare technologies. The public sector in Canada was estimated to have a return of CAD 1.58 p e r e v e r y C A D 1 spent on efgartigimod for people with gMG compared with the current bundle of treatments. Conclusions: Improving health outcomes and reducing the need for informal caregivers benefits those affected by gMG and governmental accounts.", "authors": ["Paquete Ana Teresa", "Connolly Mark P", "Qi Cynthia", "Katzberg Hans", "Raza Syed", "Kassardjian Charles", "Siddiqi Zaeem A", "Kaprielian Roger", "Locklin Jason", "Phillips Glenn A", "Kotsopoulos Nikos"], "journal": "Journal of health economics and outcomes research", "entry_date": "2026/03/16 06:05", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41836305/", "pub_types": ["Journal Article"], "affiliations": ["Global Market Access Solutions LLC, Mooresville, North Carolina, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "3区"}, {"pmid": "41834075", "title": "Comorbidities and Treatment Patterns in People With Myasthenia Gravis in Denmark, Finland and Sweden: A Population-Based Observational Study.", "abstract": "INTRODUCTION/AIMS: Comorbidities are frequent in myasthenia gravis (MG) and may affect treatment choices. Conversely, MG treatments may impact the risk of comorbidity. Our objective was to examine comorbidity and MG treatment patterns in nationwide MG cohorts in Denmark, Finland, and Sweden.\nMETHODS: We included individuals with ≥ 2 MG diagnoses (ICD codes) in nationwide health registries between 2000 and 2020 and analyzed comorbidities before and after MG diagnosis and MG-related treatments during follow-up.\nRESULTS: Among 8819 people with MG (pwMG), 3159 were incident cases with data available ±5 years from diagnosis. Circulatory diseases were the most frequent comorbidity (19%-29%) before diagnosis, mostly explained by hypertension (13%-24%). After diagnosis, anemia and osteoporosis prevalence increased three to six fold. Mental health disorders were more frequent in younger (0-64 years) than older (≥ 65 years) pwMG. In the first year after diagnosis, acetylcholinesterase inhibitors (AChEIs) were the most used treatment in Finland (41%) and Sweden (34%), and corticosteroids (CSs) with nonsteroidal-immunosuppressive therapy (NS-IST) in Denmark (33%). By year 5, the proportion of pwMG receiving NS-IST, CS, or their combination was similar in the three countries (Denmark 47%, Finland 40%, and Sweden 41%). Only 5%-7% remained treatment-naive throughout follow-up.\nDISCUSSION: MG treatment was broadly similar across the three Nordic countries, while also reflecting nation-specific therapeutic guidelines. Many pwMG required multiple therapies, underscoring risks of long-term immunosuppression and highlighting the need for vigilant management and future research of safer strategies.", "authors": ["Atula Sari", "Piehl Fredrik", "Schager Ingrid", "Berggren Fredrik", "Humle Karin", "Savolainen Mari", "Pitsi Didier", "Mehtälä Juha", "Vesikansa Aino", "Väänänen Riina-Minna", "Ylisaukko-Oja Tero", "Vissing John"], "journal": "Muscle & nerve", "entry_date": "2026/03/16 00:23", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41834075/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, Clinical Neurosciences, Neurology, University of Helsinki and Helsinki University Hospital, Helsinki, Finland."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41832797", "title": "Clinical and quality-of-life outcomes associated with efgartigimod in patients with generalized myasthenia gravis transitioning from intravenous immunoglobulin.", "abstract": "BACKGROUND: Myasthenia gravis (MG) requires long-term therapeutic strategies that control symptoms while minimizing exposure to oral corticosteroids (OCS). Fast-acting treatments (FT), such as intravenous immunoglobulin (IVIG), are commonly used during exacerbations, whereas efgartigimod (EFG) has recently emerged as an alternative outpatient therapy. This study aimed to compare the efficacy and quality of life (QOL) outcomes of IVIG and EFG in patients with MG.\nMETHODS: A retrospective analysis was conducted in 67 patients with MG. Fifty-five patients continued IVIG during exacerbations (IVIG group), whereas 12 patients switched from IVIG to EFG (Switched-EFG group). The primary outcome was the achievement of minimal manifestations (MM) or MM with prednisolone ≤ 5 mg/day (MM-5 mg). The secondary outcomes included changes in the Myasthenia Gravis Activities of Daily Living scale (MG-ADL) scores and reduction of prednisolone (PSL) dose between the two groups. The number of hospitalizations and scores on the Japanese version of the Myasthenia Gravis Quality of Life 15-Item Scale-Revised (MG-QOL15r-J) were compared before and after EFG initiation.\nRESULTS: No significant differences were observed between the groups in MM, MM-5 mg, ΔMG-ADL, or ΔPSL scores. In the Switched-EFG group, the number of hospitalizations was significantly decreased, whereas the MG-QOL scores improved following EFG initiation. The questionnaire responses consistently favored EFG, particularly in supporting family roles, work participation, and social activities.\nCONCLUSION: Notwithstanding the study's limited sample size and observational nature, Switching to EFG yielded notable therapeutic benefits compared with IVIG, while additionally reducing the hospitalization rate and enhancing QOL. Therefore, EFG may be a valuable outpatient treatment option for refractory MG.", "authors": ["Yasaka Aki", "Watanabe Genya", "Saito Moeko", "Tamagake Ayane", "Sasaki Chihiro", "Akao Go", "Ishikawa Amane", "Tsukita Kenichi", "Suzuki Yasushi"], "journal": "Clinical neurology and neurosurgery", "entry_date": "2026/03/15 10:18", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41832797/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, National Hospital Organization Sendai Medical Center, 2-11-12, Miyagino, Miyagino-ku, Sendai, Miyagi Prefecture, Japan; Department of Neurology, Shiga University of Medical Science Hospital, Seta Tsukinowa-cho, Otsu, Shiga Prefecture, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41831296", "title": "Co-occurrence of systemic lupus erythematosus and myasthenia gravis: Insights from a cross-sectional cohort.", "abstract": "OBJECTIVE: Myasthenia gravis (MG) and systemic lupus erythematosus (SLE) share immunopathogenic mechanisms, yet their co-occurrence remains poorly characterized, particularly in non-Western populations. This study investigated SLE prevalence in Egyptian Patients with MG and examined the role of thymectomy in triggering systemic autoimmunity.\nMETHODS: This cross-sectional observational study enrolled 50 consecutive Patients with MG at Mansoura University Hospital, Egypt (April 2024-January 2025). All patients underwent comprehensive clinical evaluation, serological testing (ANA, anti-dsDNA, anti-AChR), and rheumatologic assessment. SLE diagnosis followed ACR revised criteria. Pre- and post-thymectomy inflammatory markers were compared using paired statistical tests.\nRESULTS: SLE was identified in 18% (9/50) of Patients with MG, substantially higher than Western population estimates (0.9-1.4%). SLE-positive patients required significantly higher corticosteroid doses despite shorter treatment duration (p < 0.001). Among 21 thymectomized patients with no pre-operative autoimmune features, 42.9% developed cutaneous manifestations, 33.3% arthritis, and 28.6% became ANA-positive post-operatively. Median ESR increased significantly from 20 to 35 mm/hr following thymectomy (p < 0.001).\nCONCLUSION: SLE is highly prevalent among Egyptian Patients with MG and is associated with a more refractory clinical course. Thymectomy appears to precipitate systemic autoimmunity and inflammation, necessitating long-term post-operative rheumatologic surveillance, particularly in genetically susceptible populations.", "authors": ["Zhran Aya E", "Besar Marwa A", "Abdelkhalek Mostafa", "Abdelnaby Ayman", "Asar Omar", "Elkenany Kareem", "Shobier Faried", "Alkotami Ahmed S"], "journal": "Clinical neurology and neurosurgery", "entry_date": "2026/03/14 14:11", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41831296/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, Faculty of Medicine, Mansoura University, Mansoura 35511, Egypt. Electronic address: aya_zhran@mans.edu.eg."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41827683", "title": "When Central Tolerance Fails: Thymic Malignancies at the Intersection of Cancer Immunity and Autoimmunity.", "abstract": "Thymic malignancies are rare cancers arising from thymic epithelial cells and are characterized by a highly diverse clinical phenotype, substantial histologic and morphologic heterogeneity, and frequent associations with autoimmune syndromes. Although the clinical, immunological, and cytoarchitectural changes associated with thymomas have been increasingly elucidated in the contemporary literature, very few studies have interrogated the direct role of tumor staging and histological grading in shaping autoimmunity burden and infection risk. In this narrative review, we synthesize contemporary clinical, immunological, and morphologic evidence linking thymic architecture and selection defects to the spectrum of paraneoplastic autoimmunity (MG, pure red cell aplasia, Good's syndrome) and to infectious vulnerability. We further appraise emerging therapeutic strategies, including immune checkpoint inhibition and adoptive cellular approaches, through a patient-stratified lens, emphasizing efficacy signals, immune-related adverse events, and practical considerations for selection and monitoring. We conclude by highlighting priorities for future investigation, including refining autoantibody signatures; mapping thymic microenvironments that drive tolerance failure, and prospectively evaluating stratified immunotherapeutic regimens that balance benefit with immune-mediated risk.", "authors": ["Abikenari Matthew", "Choi John", "Enayati Iman", "Tucker Andrew", "Bhatnagar Keshav", "Chen Yijiang", "Himic Vratko", "Liu Justin", "Nageeb George", "Poe James", "Ong Sophia Joy", "Sanker Vivek", "Diehl Markus", "Szeifert Viktoria", "Terasaki Azusa", "Prolo Laura M", "Engleman Edgar", "Okwan-Duodu Derick"], "journal": "Cancers", "entry_date": "2026/03/14 01:03", "pub_date": "2026-02-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41827683/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurosurgery, Stanford University School of Medicine, Stanford, CA 94305, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "41826324", "title": "Shared genetic and neuroimmune architecture links type 1 diabetes with neurocognitive traits.", "abstract": "Type 1 diabetes, particularly with childhood onset, is associated with altered neurocognitive traits, yet the underlying biological mechanisms are unclear. Here, we integrate genome-wide association results with single-cell epigenomic profiles and show that type 1 diabetes heritability is enriched in accessible chromatin of human brain-resident cells, most notably microglia, across neurodevelopment into adulthood. Bonferroni-corrected cross-trait genetic correlation analyses reveal negative correlations of type 1 diabetes with intelligence, executive function, and bipolar disorder, and a positive correlation with myasthenia gravis. Conjunctional false discovery rate analysis identifies pleiotropic loci jointly influencing type 1 diabetes and neurocognitive traits, including the 17q21.31 neurogenomic hub. Mendelian randomization further demonstrates protective effects of educational attainment, intelligence, Alzheimer's disease, and bipolar disorder on type 1 diabetes risk, whereas liability to multiple sclerosis and myasthenia gravis increases type 1 diabetes risk. In the reverse direction, liability to type 1 diabetes is associated with increased risk of myasthenia gravis. We identify several gene expression regulatory variants in brain and immune cells that jointly influence type 1 diabetes and neurocognitive traits, some of which show concordant differential expression in disease-affected versus control tissue. Together, these findings highlight pleiotropic genetic and neuroimmune mechanisms that link type 1 diabetes with cognition and neuropsychiatric disease risk.", "authors": ["Saarah Priscilla", "Syeda Zehra A", "Xu Ziang", "Dong Yikai", "Jiang Habei", "Shanguhyia Michelle", "Roy Sourav", "Zhu Biqing", "Zhang Le", "Dewan Andrew T", "Asgari Samira", "Alagpulinsa David A"], "journal": "Nature communications", "entry_date": "2026/03/14 00:15", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41826324/", "pub_types": ["Journal Article"], "affiliations": ["Yale Center for Molecular & Systems Metabolism, Yale University School of Medicine, New Haven, CT, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 15.7, "journal_quartile": "1区"}, {"pmid": "41824214", "title": "Association between obesity and subsequent risk of myasthenia gravis: a nationwide population-based cohort study.", "abstract": "BACKGROUND: Obesity causes a pro-inflammatory environment and is an established risk factor for a variety of autoimmune diseases. However, the association with the subsequent risk of myasthenia gravis (MG) was unclear.\nMETHODS: This nationwide cohort study evaluated 3,937,214 adults over 20 years old, using data from the Korean National Health Insurance Service. Participants were categorized by body mass index (BMI) into underweight (BMI < 18.5), normal (18.5 ≤ BMI < 23.0), preobese (23.0 ≤ BMI < 25.0), obese class I (25.0 ≤ BMI < 30.0), and obese class II groups (≥ 30.0). The primary outcome was newly diagnosed MG during the follow-up period, identified through the International Classification of Diseases-10th revision, diagnostic codes and enrollment in the Rare Intractable Diseases program of South Korea. Cox proportional hazards models were used to calculate adjusted hazard ratios (aHRs) for MG risk by BMI.\nRESULTS: During about 10-year follow-up, 799 individuals developed MG (mean age 47.3 years old [SD, 14.02 years], male 54.6%, and BMI ≥ 25 kg/m2 32.6%). The incidence rate was highest in the obese class II group (3.39/100,000 person-years). Obese class I (aHR 1.20, 95% CI 1.00-1.43) and class II (aHR 1.88, 95% CI 1.37-2.56) groups demonstrated significantly elevated MG risks compared to the normal BMI group. In subgroup analyses, underweight males had a notably increased risk (aHR 2.16, 95% CI 1.24-3.78).\nCONCLUSION: Obesity has an association with an increased risk of subsequent MG, suggesting a potential risk factor of MG. Further studies are needed to elucidate the association between obesity and MG.", "authors": ["Kwon Soonwook", "Park Ye Bin", "Han Kyung-Do", "Chung Yeon Hak", "Cho Eun Bin", "Shin Dong Wook", "Min Ju-Hong"], "journal": "Acta neurologica Belgica", "entry_date": "2026/03/13 12:21", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41824214/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Inha University Hospital, Inha University College of Medicine, Incheon, South Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41824170", "title": "Estimating the minimal clinically important difference for the Myasthenia Gravis Quality of Life revised scale (MG-QOL15R).", "abstract": "People with Myasthenia Gravis (MG), a rare disease that causes muscle weakness, often face problems that affect their daily lives and overall well-being. To better understand how MG impacts people and whether treatments are working, health professionals use a questionnaire called the MG-QOL15R. This tool captures key aspects of patients’ experiences with MG. However, it is unclear how much a person’s score needs to change for that change to be considered meaningful. This study looked at how much change in the MG-QOL15R score is needed to reflect a real difference in someone’s health. We used data from two international studies involving people living with MG and tested different ways to determine what amount of change matters to patients. We found that a change between 2 and 3 points on the MG-QOL15R is likely to be minimally meaningful. Smaller changes may reflect early improvement, while larger changes are more reliable for guiding treatment decisions. These findings can help doctors, researchers, and policymakers understand whether a treatment is truly helping people with MG feel better.", "authors": ["Ben Ângela Jornada", "Brackx Febe", "Phillips Glenn", "Barnett-Tapia Carolina", "Qi Cynthia", "Rencz Fanni", "Dewilde Sarah"], "journal": "Quality of life research : an international journal of quality of life aspects of treatment, care and rehabilitation", "entry_date": "2026/03/13 12:19", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41824170/", "pub_types": ["Journal Article"], "affiliations": ["Services in Health Economics (SHE), Boulevard Lambermont 418, 1030, Brussels, Belgium. angela@she-consulting.be."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV"}, {"pmid": "41823508", "title": "Who Can Safely Discontinue Treatment in Myasthenia Gravis? Insights From a Long-Term Real-World Study.", "abstract": "BACKGROUND: Optimal timing for treatment discontinuation in myasthenia gravis (MG) patients achieving minimal symptom expression (MSE) remains undefined.\nMETHODS: This prospective cohort study enrolled 196 MG patients from the Huashan MG Registry who achieved MSE and subsequently discontinued all treatments. Cox regression was used to identify prognostic factors for relapse. Among these, 20 patients experienced two discontinuation events and were analyzed separately for their second discontinuation.\nRESULTS: Over a mean follow-up of 111.10 months, 108 patients (55.1%) experienced relapse. Multivariate analysis identified four independent prognostic factors: onset age ≥ 50 years as a risk factor (HR 1.68, 95% CI 1.04-2.70, p = 0.032), and rituximab administration (HR 0.43, 95% CI 0.17-0.89, p = 0.015), treatment duration ≥ 14.3 months (HR 0.54, 95% CI 0.34-0.85, p = 0.008), and time from MSE to discontinuation ≥ 6.1 months (HR 0.51, 95% CI 0.32-0.83, p = 0.007) as protective factors. Infection, fatigue, and psychological stress were common relapse triggers.\nCONCLUSIONS: Complete treatment discontinuation after MSE in MG carries substantial relapse risk. Individualized discontinuation decisions incorporating younger onset age, prior rituximab use, adequate treatment and consolidation duration may optimize outcomes.", "authors": ["He Dingxian", "Yan Chong", "Wang Baitong", "Yang Yanlei", "Gu Shengying", "Xi Jianying", "Luo Sushan", "Zhao Chongbo"], "journal": "European journal of neurology", "entry_date": "2026/03/13 09:33", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41823508/", "pub_types": ["Journal Article"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41823155", "title": "A Decade of Surgical Management of Thymic Tumours in Western Australia.", "abstract": "BACKGROUND: Thymic cancers are exceedingly rare, with an incidence of one to two cases per 100 000 person-years with exceptionally diverse presentations. There is limited literature characterising prognostic factors, surgical management strategies and outcomes in Australian patients with thymic tumours.\nMETHODS: We performed a retrospective analysis of all patients that underwent surgical resection of a thymic tumour from 2013 to 2022 within the two major cardiothoracic surgical units in Western Australia.\nRESULTS: There were 120 patients included in this study, 60 patients with thymoma. There was a higher rate of recurrence in patients with thymoma and concurrent myasthenia gravis. Thoracoscopic surgery was associated with a reduced hospital length of stay (p = 0.04). Of the 40 patients with myasthenia gravis that underwent thymectomy, 30 (75%) had an improvement in their MG symptoms.\nCONCLUSIONS: We describe the referral patterns, diagnostic methods, clinical management and outcomes for 120 patients who underwent resection of a thymic tumour. Our study affirmed that thymic surgery is well tolerated, supports its application in the management of myasthenia gravis and this research may help to further develop guidelines for best management of these tumours in Australian patients.", "authors": ["Bibo Liam", "Agbinya Nathan", "Bayfield Nick", "Jenkinson Charles", "Pannekoek Adrian", "Edelman James", "Joshi Pragnesh"], "journal": "ANZ journal of surgery", "entry_date": "2026/03/13 06:53", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41823155/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cardiothoracic Surgery, Sir Charles Gairdner Hospital, Perth, Western Australia, Australia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41822957", "title": "Old Foundations in a New Era of Myasthenia Gravis Therapy.", "abstract": "", "authors": ["Stavros Kara", "Narayanaswami Pushpa"], "journal": "Muscle & nerve", "entry_date": "2026/03/13 05:03", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41822957/", "pub_types": ["Editorial"], "affiliations": ["Warren Alpert Medical School of Brown University, Providence, Rhode Island, USA."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41822500", "title": "Analysis of adverse drug reactions associated with ravulizumab: a retrospective pharmacovigilance study utilizing the FAERS database.", "abstract": "BACKGROUND: Ravulizumab is a long-acting C5 complement inhibitor that provides sustained suppression of the complement pathway. It is currently approved by the US Food and Drug Administration (FDA) for the treatment of generalized myasthenia gravis, paroxysmal nocturnal hemoglobinuria, and atypical hemolytic uremic syndrome. With its increasing clinical use, concerns regarding Ravulizumab-associated adverse drug reactions have grown.\nMETHODS: This study utilized a dataset extracted from the Adverse Event Reporting System (FAERS) database, comprising adverse event reports from the fourth quarter of 2018 to the second quarter of 2025. Four distinct disproportionality analysis methods-the Reporting Odds Ratio (ROR), Proportional Reporting Ratio (PRR), Multi-item Gamma Poisson Shrinker (MGPS), and Bayesian Confidence Propagation Neural Network (BCPNN)-were applied. Additionally, the time-to-onset profile of adverse events was assessed using the Weibull distribution model.\nRESULTS: A total of 9,090 adverse event reports associated with ravulizumab were included in this analysis. Commonly reported adverse events included fatigue, asthenia, headache, malaise, dyspnea, back pain, feeling abnormal, and diplopia. Furthermore, potential adverse events not listed on the drug label were identified, such as anemia, dysphagia, urinary tract infection, and somnolence.\nCONCLUSION: This investigation identified several adverse events associated with ravulizumab and revealed potential adverse reaction signals that were not previously recognized. Healthcare providers may consider these safety signals to more comprehensively assess potential risks in patients during clinical practice.", "authors": ["Zhou Yue", "Wu Yutong", "Su Yingchao", "Meng Zhaoyou"], "journal": "Frontiers in immunology", "entry_date": "2026/03/13 04:52", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41822500/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Second Affiliated Hospital of Army Medical University, Chongqing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41821629", "title": "Neuro-ophthalmic presentation of leptomeningeal metastasis of thymoma: a case report.", "abstract": "INTRODUCTION: Leptomeningeal disease (LMD) of the brain and spinal cord can present with visual loss or diplopia. Although LMD can occur in many forms of neoplasia, thymoma-related LMD is exceedingly rare.\nPATIENT PRESENTATION: A 53-year-old Hispanic male with a history of chest pain, weight loss, and night sweats was diagnosed with stage 4 thymoma with lung and pleural metastasis. He received chemotherapy for metastatic thymoma. Few months later, patient presented with severe right-sided facial pain and lip numbness, ptosis and double vision.\nPRIMARY DIAGNOSIS: The patient was diagnosed with multiple cranial and spinal nerve involvement due to thymomatous LMD, confirmed on magnetic resonance imaging and lumbar puncture.\nCONCLUSION AND IMPORTANCE: LMD is a rare presentation of a malignant thymoma. Current guidelines for thymoma management emphasize the importance of staging imaging to rule out distant metastasis. Our case highlights the importance of a head-to-mid-thigh positron emission tomography (PET) scan in patients with known metastatic thymomas, with multiple PET scans, if possible, at regular intervals, owing to the aggressive nature of metastatic thymomas. Clinicians should be aware of the neoplastic (e.g., metastatic disease and LMD) and paraneoplastic (e.g., thymoma-related myasthenia gravis) neuro-ophthalmic presentations of thymoma.", "authors": ["Khan Muhammad Hammad", "Abid Syeda Fatima", "Abdelsalam Dina", "Ibrahim Safa", "Lee Andrew G"], "journal": "Frontiers in neurology", "entry_date": "2026/03/13 04:44", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41821629/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Ophthalmology, King Edward Medical University, Lahore, Pakistan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41821047", "title": "CAR T cell therapy in autoantibody-mediated neurological disorders: a promising strategy.", "abstract": "BACKGROUND: Chimeric antigen receptor (CAR) T cell therapy is emerging as a promising approach for B cell-driven neurological autoimmune disorders, particularly those characterized by pathogenic autoantibodies that target key neural structures. These conditions, including neuromyelitis optica spectrum disorder, myasthenia gravis, Lambert-Eaton myasthenic syndrome, MOG antibody-associated disease, anti-NMDA receptor encephalitis, Diacylglycerol lipase alpha antibody associated encephalitis, stiff person syndrome, and multiple sclerosis, can be categorized based on their primary autoantigens into (1) extracellular antigen-associated (e.g., AQP4, AChR, NMDAR, MOG, VGCC), (2) intracellular antigen-associated (e.g., GAD65, DAGLA), or (3) unidentified antigenic origin (as seen in multiple sclerosis). This distinction is essential for guiding therapeutic strategies and exploring novel principles represented in distinct treatment approaches and their corresponding therapeutic outcomes.\nMAIN BODY: In this review, we propose a classification of CAR T cell therapies designed for different target antigens, including: CD19/20/BCMA-directed CAR T cells targeting general B cell-mediated pathogenesis, regulatory T cells modified with CARs, and the design of chimeric autoantibody receptors (CAARs) to selectively deplete pathogenic B cells directly associated with disease progression while preserving immune tolerance. We further discuss preclinical and clinical advancements, key challenges such as safety concerns and neurotoxicity, and the future landscape of CAR T applications in neuromyelitis optica spectrum disorder, myasthenia gravis, Lambert-Eaton myasthenic syndrome, MOG antibody-associated disease, anti-NMDA receptor encephalitis, Diacylglycerol lipase alpha antibody associated encephalitis, stiff person syndrome, and multiple sclerosis according to the latest research, case and trial data.\nCONCLUSION: CAR T cell therapy potentially offers a highly specific and effective method with thorough elimination of autoreactive B cells, representing a rapidly evolving field with the potential to transform the treatment of autoimmune neurological disorders. As CAR T technology advances, it holds the potential to become a groundbreaking immunoablative strategy with so-far disclosed controllable side effects; however, further long-term follow-up data are still needed to validate its application in autoimmune disorders.", "authors": ["Wen Muzi", "Zheng Ruoyi", "Zhang Hanqing", "Goldberg Sophia Y", "Jian Zhiying", "Gao Ye", "Cheng Ruogu", "Wen Linxin", "Zhao Yu", "Kenderian Saad S", "Shang Pei"], "journal": "Journal of neuroinflammation", "entry_date": "2026/03/13 01:07", "pub_date": "2026-03-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41821047/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Nanfang Hospital, Southern Medical University, Guangzhou Road North 1838#, Guangzhou, 510515, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 10.1, "journal_quartile": "1区"}, {"pmid": "41820352", "title": "Elucidating genetic backgrounds of myasthenia gravis in Japanese by genome-wide association studies and multi-omics analyses of thymoma.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder characterized by impaired neuromuscular transmission and motor symptoms. Its genetic background remains unclear, particularly beyond specific subtypes reported in European populations. Here, we perform a genome-wide association study (GWAS) of 1,434 MG cases covering all disease subtypes and 42,913 controls of Japanese, which newly identify the TERT locus (odds ratio [OR] = 1.31, P = 1.7×10-10). Subtype-stratified GWASs show stronger signals for generalized MG (gMG; OR = 1.38, P = 1.6×10-12), anti AChR antibody-positive gMG (g-AChR-Ab(+)MG; OR= 1.49, P = 2.1×10-15), and thymoma-associated gMG (g-TAMG; OR = 1.92, P = 1.1×10-15). Fine-mapping of the major histocompatibility complex region reveal distinct associations of HLA-DRB1 with late onset gMG (g-LOMG) and HLA-A with early onset gMG (g-EOMG). The MG risk TERT lead variant rs2736099 is associated with poor treatment response, especially in g-AChR-Ab(+)MG and g-EOMG (P < 0.0042). The biobank-based phenome-wide association study identify pleiotropic effects on lung cancer, hematological traits, and telomere length. Single cell transcriptomics and immunohistochemistry identified immature lymphocyte-specific TERT expression in thymoma specimens. Full-length transcriptomics reveal allele-specific decreasing effect of rs2736099-A on TERT expression. Our study unveils genetics of MG distinctly across disease subtypes, and involvement of TERT in its pathogenesis.", "authors": ["Ueda Hiroyuki", "Kubota Tomoya", "Goto Risa", "Suzuki Akari", "Ojima Takafumi", "Ogawa Kotaro", "Sonehara Kyuto", "Namba Shinichi", "Naito Tatsuhiko", "Wang Qingbo", "Konno Shingo", "Samukawa Makoto", "Kawaguchi Naoki", "Kimura Takashi", "Sugimoto Takamichi", "Murai Hiroyuki", "Yamawaki Takemori", "Kaida Kenichi", "Tokuyasu Daiki", "Yasuda Manato", "Akamine Hiroyuki", "Onishi Yosuke", "Ogawa Yosuke", "Shirai Yuya", "Edahiro Ryuya", "Yamamoto Kenichi", "Nagata Hideki", "Ose Naoko", "Takayama Jun", "Suzuki Ken", "Higashiue Shinichi", "Kobayashi Shuzo", "Yamaguchi Hiroki", "Okazaki Yasushi", "Matsumoto Naoyuki", "Motomura Kenta", "Koga Hidenobu", "Matsuda Koichi", "Tamiya Gen", "Yamamoto Masayuki", "Yamauchi Toshimasa", "Kadowaki Takashi", "Yamamoto Kazuhiko", "Ohno Akiko", "Okuno Tatsusada", "Morii Eiichi", "Mochizuki Hideki", "Nagane Yuriko", "Minami Naoya", "Uzawa Akiyuki", "Masuda Masayuki", "Suzuki Shigeaki", "Shimomura Iichiro", "Shintani Yasushi", "Utsugisawa Kimiaki", "Takahashi Masanori P", "Okada Yukinori"], "journal": "Nature communications", "entry_date": "2026/03/13 00:17", "pub_date": "2026-03-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41820352/", "pub_types": ["Journal Article"], "affiliations": ["Department of Statistical Genetics, Graduate School of Medicine, The University of Osaka, Suita, Japan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 15.7, "journal_quartile": "1区"}, {"pmid": "41818112", "title": "Myasthenic Crisis Unmasking Myocardial Infarction with Nonobstructive Coronary Arteries in a Patient with Undiagnosed Myasthenia Gravis.", "abstract": "We present a case of a patient with undiagnosed myasthenia gravis presenting in myasthenic crisis. In this case, the patient presented primarily with myocardial infarction with nonobstructive coronary arteries and respiratory failure and was later diagnosed to be in myasthenic crisis. The myasthenic crisis was treated with intravenous immunoglobulin (IVIg) and corticosteroids. Given the inadequate response to IVIg and glucocorticoids, the patient was subsequently administered an anti-CD20 monoclonal antibody in the form of rituximab. The patient responded well to rituximab, and her cardiac function subsequently improved.", "authors": ["Ginwala Abdeali", "Kulkarni Vihita", "Nivargi Varun"], "journal": "The Journal of the Association of Physicians of India", "entry_date": "2026/03/12 13:00", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41818112/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Resident, Department of Internal Medicine, Poona Hospital & Research Centre, Pune, Maharashtra, India, Corresponding Author, Orcid: https://orcid.org/0009-0003-8294-6886."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41817916", "title": "Correction: Assessing the Value Contribution of Vyvgart® (Efgartigimod Alfa) in the Treatment of Generalized Myasthenia Gravis with Acetylcholine Receptor Antibody in Spain Through Multi-criteria Decision Analysis.", "abstract": "", "authors": ["Cortés-Vicente Elena", "Guerrero Antonio", "Díaz Carmina", "Martínez Eva", "Toja-Camba Francisco J", "Abad María R", "Serra José M", "Trillo Jose L", "Martín Machín Celia", "Gil Alicia"], "journal": "Advances in therapy", "entry_date": "2026/03/12 12:22", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41817916/", "pub_types": ["Published Erratum"], "affiliations": ["Hospital Santa Creu i Sant Pau, Barcelona, Spain."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41817915", "title": "Indirect Comparison of Nipocalimab Versus Efgartigimod and Rozanolixizumab in the Treatment of Generalized Myasthenia Gravis.", "abstract": "INTRODUCTION: Nipocalimab, efgartigimod, and rozanolixizumab (the last two cyclically dosed) are approved neonatal Fc receptor (FcRn) blockers for treating generalized myasthenia gravis (gMG). No trials have directly compared these therapies; hence, indirect treatment comparisons (ITCs) were conducted to evaluate their relative efficacy.\nMETHODS: Matching-adjusted indirect comparisons (MAICs) and Bucher ITCs were used to compare nipocalimab vs. efgartigimod and rozanolixizumab for changes from baseline (CFB) in Myasthenia Gravis Activities of Daily Living (MG-ADL) total score observed in their phase 3 registration trials. Bucher ITCs used the relative treatment effect vs. placebo. As there was considerable cross-trial heterogeneity, including uncertainty in using the placebo arm as a common comparator, active treatment arms were used in unanchored MAICs. MG-ADL CFB was compared between trials (1) at multiple timepoints to evaluate onset of action and disease control over time, and (2) using area under the curve (AUC) as a measure of cumulative effect normalized per week of follow-up.\nRESULTS: In both Bucher ITCs and MAICs, nipocalimab had a comparable MG-ADL CFB at week 1 vs. the other FcRn blockers. In MAICs, MG-ADL CFB was significantly greater with nipocalimab vs. efgartigimod at week 8 sustained up to 24 weeks (p < 0.05), and vs. rozanolixizumab at week 10 sustained up to 14 weeks (p < 0.05); results numerically favored nipocalimab in corresponding Bucher ITCs. Using normalized AUC, MG-ADL CFB with nipocalimab was significantly greater in MAICs (p < 0.05) and numerically greater in Bucher ITCs vs. the other FcRn blockers.\nCONCLUSIONS: Sustained disease control is an important consideration in managing chronic diseases with fluctuating symptoms such as gMG. Study results showed that nipocalimab provided a comparable onset of action and consistent and sustained disease control that was numerically or statistically significantly greater (depending on ITC method) when compared with the symptom-based cyclic FcRn blockers efgartigimod and rozanolixizumab.", "authors": ["Jacob Saiju", "Hashim Mahmoud", "Hutton Brian", "Gandhi Kavita", "Van Sanden Suzy", "Slowik Rafal", "Drudge Christopher", "Khoury Antoine C El", "Keng Mi Jun", "Singh Sumeet", "Ramchandren Sindhu", "Gilhus Nils Erik"], "journal": "Advances in therapy", "entry_date": "2026/03/12 12:22", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41817915/", "pub_types": ["Journal Article", "Comparative Study", "Randomized Controlled Trial"], "affiliations": ["University Hospitals Birmingham NHS Foundation Trust, Birmingham, UK."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41817069", "title": "Juvenile Myasthenia Gravis: An Indian Perspective.", "abstract": "BACKGROUND: Myasthenia Gravis is an autoimmune disorder of the neuromuscular junction which is divided into three categories in children: neonatal or transient, congenital myasthenic syndromes, and autoimmune or juvenile myasthenia gravis (JMG). JMG differs from adult MG in many aspects. Characteristics of JMG also vary between children of various ethnic groups.\nOBJECTIVE: Although common, there is scant data about JMG in India. This study was performed to determine the characteristics of JMG in Indian children.\nMATERIALS AND METHODS: We did a retrospective chart analysis of all patients who received a diagnosis of myasthenia at a tertiary care pediatric hospital in Mumbai, India from January 2005 to December 2015. We studied the demographic data, clinical features, investigations, history of crises, and records of hospital stay. Treatment modalities and outcomes were reviewed.\nRESULTS: Fifteen children received a diagnosis of JMG during the study period. This was a pre-pubertal cohort with a mean age of 3.7 years. Nine patients had generalized symptoms at presentation and six had ocular presentation. The seropositivity rate was 73%. Patients were treated with a combination of pyridostigmine, steroids, and additional immunosuppression. Nearly half the patients needed second-line immunosuppression. Four children underwent thymectomy.\nCONCLUSION: MG in Indian children is a severe disease with high rates of seropositivity and a relatively better outcome if identified and treated appropriately. Thymectomy has an important role in management but requires more scrutiny.", "authors": ["Garg Meenal", "Kulkarni Shilpa D", "Hegde Anaita Udwadia", "Gupta Piyush", "Sayed Rafat"], "journal": "Neurology India", "entry_date": "2026/03/12 07:53", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41817069/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatric Neurosciences, Bai Jerbai Wadia Hospital for Children, Mumbai, Maharashtra, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41816389", "title": "Advantages of negative-pressure suction device compared to traditional chest closed drainage in the management of patients after mediastinal mass resection.", "abstract": "BACKGROUND: Mediastinal mass resection commonly requires postoperative drainage to prevent complications including pleural effusion, pneumothorax, and hematoma. Traditional chest closed drainage (TCCD) remains the standard approach, yet limitations in drainage efficiency, patient comfort, and recovery time have prompted exploration of alternatives. Negative-pressure suction devices (NPSD) offer enhanced drainage capabilities and may reduce postoperative complications, but comparative evidence on their clinical effectiveness, safety, and patient outcomes remains scarce. This retrospective cohort study aimed to systematically compare NPSD versus TCCD following mediastinal mass resection, focusing on chest tube duration, length of stay, and patient recovery outcomes.\nMETHODS: A total of 174 patients from a single Chinese center (September 2021 to February 2025) were included and assigned to TCCD group (n=111) or NPSD group (n=63) based on postoperative drainage choice. Outcomes included chest tube duration, length of stay, tube reinsertion, postoperative fever, pain scores, and other drainage parameters; baseline and perioperative variables were systematically collected.\nRESULTS: Groups were similar in demographics and most comorbidities; the NPSD group had higher body mass index (BMI) and fewer myasthenia gravis cases. The NPSD group reduced chest tube duration and length of stay versus TCCD group (57.43±18.99 vs. 66.54±20.40 hours, P=0.002; 3.52±1.02 vs. 4.02±1.21 days, P=0.002). Pain, fever, total drainage, and reinsertion rates were comparable, with no increase in drainage-related complications.\nCONCLUSIONS: The NPSD group shortens drainage duration and length of stay without increasing major complications, supporting its feasibility within enhanced recovery after surgery (ERAS) protocols.", "authors": ["Wang Chen", "Qin Jiayin", "Li Xin"], "journal": "Journal of thoracic disease", "entry_date": "2026/03/12 05:17", "pub_date": "2026-02-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41816389/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cardiothoracic Surgery, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41815330", "title": "Concurrent Nivolumab-Induced Myocarditis and Myasthenia Gravis: A Case Report.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) such as nivolumab have improved 10-year overall survival rates up to 43% in advanced melanoma. They carry a risk of severe immune-related adverse events (irAEs) up to 9%-33%, including cardiotoxicity and neuromuscular complications. Acral melanoma is a rare subtype that is often diagnosed late and requires aggressive therapy with adjunctive immunotherapy. Here, we report a rare case of an elderly male who developed myocarditis and myasthenia gravis 3 weeks after receiving the first dose of nivolumab for stage IIB acral melanoma.\nCASE PRESENTATION: A 72-year-old male with a late diagnosis of Stage IIB acral melanoma of the left great toe underwent toe amputation and received adjuvant therapy with nivolumab as per NCCN guidelines. Within 21 days after the first infusion, he developed chest pressure, fatigue, and diplopia. Workup revealed new-onset heart failure with an EF of 45%-50% with Grade 2 diastolic dysfunction, elevated troponin and NT pro-BNP, and cardiac MRI findings consistent with severe Grade 3, immune-related myocarditis. This presentation was complicated by a Mobitz Type 2 AV block, 10-s asystole, and therefore required permanent pacemaker placement. The symptoms of fatigue and diplopia led to a diagnostic workup with electromyography, confirming Grade 3 nivolumab-induced myasthenia gravis. He was treated with dexamethasone followed by a tapering dose of prednisone, and one cycle of IVIG at 0.4 g/kg for 5 days, leading to symptom resolution and improvement of EF to 60%-65%. However, 2 months later, he developed atrial fibrillation with a rapid ventricular rate, with device check showing 100% burden, therefore requiring hospitalization and subsequent cardioversion.\nCONCLUSION: Nivolumab-induced myocarditis and myasthenia gravis require high clinical suspicion to make an early diagnosis and ICI discontinuation and aggressive immunosuppressive treatment. Due to early onset and rapid progression to conduction abnormalities and the development of new arrhythmogenic foci, immunotherapy-related myocarditis requires close monitoring. This case also highlights the importance of multidisciplinary management and individualized risk-benefit assessment when considering rechallenge with ICIs.", "authors": ["Gupta Rajat", "Plumber Noorine", "Lee Jae", "Sivasubramanian Barath Prashanth", "Kyhan Mohammad Eshaq", "Singh Hardeep", "Gupta Sonu"], "journal": "Case reports in oncological medicine", "entry_date": "2026/03/12 05:05", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41815330/", "pub_types": ["Journal Article"], "affiliations": ["Department of Internal Medicine-GME, Northeast Georgia Medical Center, Gainesville, Georgia, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41812675", "title": "Isolated dysphagia masking myasthenia gravis diagnosis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction characterized by fluctuating skeletal muscle weakness. We report a 61-year-old woman presenting with progressive dysphagia as the sole initial symptom for 15 months, leading to diagnostic delay. Esophageal manometry suggested ineffective motility, and electroneuromyography was normal, reinforcing a non-neurological hypothesis. During hospitalization for worsening dysphagia, cervical magnetic resonance imaging (MRI) incidentally revealed an anterior mediastinal nodule consistent with thymoma. Pulse corticosteroid therapy caused abrupt clinical deterioration, prompting neurological evaluation. Pyridostigmine produced marked improvement within 48 hours, and acetylcholine receptor antibody testing confirmed MG (18.7 nmol/L, radioimmunoassay). Robotic thymectomy revealed a type AB thymoma. The patient remains stable on azathioprine 2.5 mg/kg/day, with oncologic follow-up. This case highlights that MG should be considered in persistent unexplained dysphagia, particularly when symptoms worsen after corticosteroid exposure. Early recognition avoids morbidity and unnecessary invasive procedures.", "authors": ["Lusvarghi Isabella Lopes", "Bernis Eduarda Heringer", "Lopes Rafaela Gatti", "Vieira Rafaela Costa", "Fernandes Breno Franco Silveira", "Queiroz Davi Teixeira Urzêdo"], "journal": "Arquivos de neuro-psiquiatria", "entry_date": "2026/03/11 19:53", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41812675/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Hospital Felício Rocho, Departamento de Gastroenterologia e Hepatologia, Belo Horizonte MG, Brazil."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41811049", "title": "[Clinical characteristics and genetic analysis of a patient with Kennedy disease with secondary infertility as the initial symptom].", "abstract": "OBJECTIVE: To explore the clinical features and genetic basis of a male patient with Kennedy disease(KD) presenting as secondary infertility.\nMETHODS: A male patient who had presented at Yantai Yuhuangding Hospital in August 2023 for secondary infertility for 5 years was selected as the study subject. Clinical data, laboratory findings, and auxiliary examination of the patient were collected. Peripheral blood samples were obtained from the patient and his family members. Following DNA extraction, whole-exome sequencing (WES) was carried out. Pathogenicity of candidate variant was predicted by bioinformatics analysis. Fluorescence probe PCR-capillary electrophoresis was employed to analyze the trinucleotide CAG repeat sequence variation in the AR gene to rule out dynamic mutation. This study was approved by the Ethics Committee of Yantai Yuhuangding Hospital (Ethics No.: 2024-697).\nRESULTS: The patient had presented with non-obstructive azoospermia and elevated androgen sensitivity index. Ultrasound scan indicated small testicular volume and seminal vesicle atrophy. WES and bioinformatics analysis revealed abnormal amplification in the patient's AR gene. Fluorescence probe PCR and capillary electrophoresis confirmed that both the proband and his nephew had harbored 52 CAG trinucleotide repeats in exon 1 of the AR gene, confirming the diagnosis of KD. The proband's mother, elder sister, and daughter were identified as carriers of the variant, while his second elder sister did not carry the mutation.\nCONCLUSION: As a rare X-linked recessive genetic disease, KD mainly manifests with muscle weakness, myasthenia gravis and myofascial tremor, while cases with infertility and non-obstructive azoospermia as the initial symptoms are rare and can be easily missed. Diagnosis made by genetic testing needs to be taken seriously by the clinicians.", "authors": ["Chen Jie", "Jin Yinshan", "Zhang Xuebao", "Cui Yuanqing", "Wang Xiong"], "journal": "Zhonghua yi xue yi chuan xue za zhi = Zhonghua yixue yichuanxue zazhi = Chinese journal of medical genetics", "entry_date": "2026/03/11 09:42", "pub_date": "2025-12-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41811049/", "pub_types": ["Journal Article", "Case Reports", "English Abstract"], "affiliations": ["Reproductive Medicine Center, Yantai Yuhuangding Hospital Affiliated to Qingdao University, Yantai, Shandong 264000, China. wx83905@163.com."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41810408", "title": "Case Report: Positioning head tilt observed in six dogs with meningoencephalitis of unknown origin.", "abstract": "Positioning head tilt (PHT) is a dynamic clinical neurological sign that is characterized by a head tilt to the opposite side of a voluntary lateral turn of the head. Based on recent publications, various etiologies are proposed for the occurrence of PHT in dogs and cats. One suggested cause is a lack of inhibitory input to the vestibular nuclei due to dysfunction of the cerebellar nodulus and uvula (NU). In that category, it has been reported in dogs with hypoplasia of the NU, dogs with lysosomal storage diseases, and in a dog with a cerebellar tumor. Other proposed causes of PHT include reduced input of either proprioceptive information from the spindles of cervical muscles or information about head movement in space from peripheral vestibular apparatus. As examples of the former, it has been observed in feline cases of hypokalemic myopathy and myasthenia gravis. As an example of the latter, it has been observed in a dog and four cats with bilateral peripheral vestibular dysfunction. In this study, we describe and discuss our observations of PHT in six dogs with meningoencephalitis of unknown origin (MUO). Although it was not possible to identify the causative lesion site in these dogs, the possibility of MUO causing the clinical sign of PHT in dogs is deemed to be clinically relevant.", "authors": ["Tamura Shinji", "Santifort Koen M", "Kuwabara Takayuki", "Nakamoto Yuya", "Tamura Yumiko"], "journal": "Frontiers in veterinary science", "entry_date": "2026/03/11 05:30", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41810408/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Tamura Animal Clinic, Hiroshima, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "2区"}, {"pmid": "41809936", "title": "Application of Droplet Digital PCR in Sputum Samples in Myasthenia Gravis Patients with Pneumonia.", "abstract": "BACKGROUND: Due to the rapid progression of the pneumonia in patients with Myasthenia gravis (MG), faster pathogen detection techniques are needed. The droplet digital polymerase chain reaction (ddPCR) has the ability to detect pathogens in about 3 h. Thus, this study focused on application of ddPCR in sputum samples in the MG patients with pneumonia and analyzed the association between ddPCR and other laboratory results.\nMETHODS: We prospectively enrolled 22 MG inpatients with pneumonia and collected 24 sputum samples. All samples were analyzed using traditional culture, ddPCR and metagenomic next-generation sequencing (mNGS) in parallel. Clinical outcomes during hospitalization were documented.\nRESULTS: Among the 24 sputum samples collected from 22 MG patients, ddPCR achieved a 100% positivity rate with the identification of bacteria in all 24 samples, while mNGS also demonstrated a high detection rate, identifying bacteria in 23 of 24 samples (95.8%), and additionally detecting viral and fungal pathogens across multiple cases. In 4 patients with negative sputum culture results, pathogens were identified by both ddPCR and mNGS.\nCONCLUSION: The ddPCR demonstrated rapid and sensitive identification of predefined bacterial targets and drug-resistance genes, making it suitable for initial diagnostic screening and timely clinical decision-making in MG patients with pneumonia. The speed of ddPCR detection is faster than mNGS and traditional culture, and the results are similar to mNGS and culture, with good consistency.", "authors": ["Su Manqiqige", "Luo Yeting", "Huan Xiao", "Xi Caihua", "Yang Lei", "Zhong Huahua", "Liu Fengtao", "Zhang Qiran", "Liu Qihui", "Wang Xuan", "Cao Yilei", "Wang Mengmeng", "Ta Fuxia", "Wang Bingyao", "Ai Jingwen", "Zhao Chongbo", "Zheng Jianming", "Luo Sushan"], "journal": "Infection and drug resistance", "entry_date": "2026/03/11 05:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41809936/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Huashan Rare Disease Centre, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, People's Republic of China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41808843", "title": "Late-Onset Ocular Myasthenia Gravis-Like Symptoms During Erenumab Therapy for Chronic Migraine: A Case Report.", "abstract": "Chronic migraine (CM) is a disabling neurological disorder for which calcitonin gene-related peptide (CGRP)-targeted monoclonal antibodies, such as erenumab, provide effective prophylaxis. Although generally well tolerated, rare neuromuscular complications resembling ocular myasthenia gravis (MG) have been reported. A 46-year-old woman with CM achieved marked improvement with erenumab for over three years before developing diplopia and intermittent ptosis. Laboratory and imaging studies were unremarkable, but clinical suspicion for MG led to pyridostigmine therapy, resulting in rapid improvement. Brief episodes of dysarthria occurred but resolved within one month. Symptoms disappeared after discontinuation of erenumab and continued pyridostigmine. On re-initiation of erenumab, the patient maintained migraine control without recurrence of MG-like symptoms. This case illustrates a rare, late-onset, reversible MG-like complication of erenumab. Clinicians should remain alert to ocular manifestations even as delayed adverse effects of anti-CGRP therapy.", "authors": ["Qaqish Arwa", "Al Anber Arwa", "Abdelhafez Ghada"], "journal": "Biologics : targets & therapy", "entry_date": "2026/03/11 05:15", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41808843/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Biology and Biotechnology, Faculty of Science, the Hashemite University, Zarqa, 13133, Jordan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "41804001", "title": "Single-stage concomitant extended thymectomy for myasthenia gravis and enucleation of a left recurrent laryngeal nerve schwannoma via median sternotomy.", "abstract": "BACKGROUND: Myasthenia gravis (MG) without thymoma is often treated with extended thymectomy to improve symptom control and reduce immunotherapy requirements. Schwannoma of the recurrent laryngeal nerve (RLN) is rare, and surgical resection is usually curative. However, operative manipulation carries a risk of temporary or permanent vocal fold paralysis. When these conditions coexist, choosing staged versus single-stage surgery is non-trivial. A synchronous operation can consolidate perioperative care and recovery but demands careful planning to prevent respiratory complications, particularly if RLN palsy or myasthenic crisis occur.\nCASE PRESENTATION: A 65-year-old woman with generalized, thymoma-negative MG (acetylcholine-receptor antibody positive) had no hoarseness or dysphagia. Flexible laryngoscopy confirmed mobile vocal folds bilaterally. Chest radiography showed mediastinal widening without diaphragmatic paralysis. Contrast-enhanced CT and MRI revealed a right anterior mediastinal cystic lesion and a solid mass in the left tracheoesophageal groove abutting the RLN. ^18F-fluorodeoxyglucose positron emission tomography demonstrated uptake in the solid lesion (SUV_max 4.89). Transesophageal endoscopic ultrasound–guided fine-needle aspiration yielded spindle cells compatible with schwannoma, and the mass was considered RLN-derived. A single-stage median sternotomy was undertaken. Extended thymectomy was performed with bilateral phrenic exposure and en bloc removal of thymic/perithymic fat, followed by nerve-sparing enucleation of the left RLN tumor through a longitudinal epineurial window and meticulous intracapsular dissection, preserving macroscopic neural continuity. The postoperative intensive care unit course was uneventful: no dyspnea or dysphagia, normal voice, and laryngoscopy confirmed intact vocal fold mobility. A chest radiograph on postoperative day 5 was unremarkable, and the patient was discharged on day 7. Histopathology showed alternating Antoni A/B areas with virtually no mitoses; tumor cells were strongly S-100–positive, confirming schwannoma.\nCONCLUSIONS: In carefully selected patients with stable MG and no preoperative vocal fold dysfunction, single-stage median sternotomy enables safe concomitant extended thymectomy and RLN schwannoma enucleation. Success hinges on nerve-sparing technique and proactive perioperative planning for airway protection and potential MG crisis.", "authors": ["Kamimura Go", "Maeda Koki", "Aoki Masaya", "Imamura Satomi", "Morizono Shoichiro", "Nonaka Yuto", "Takeda Aya", "Nagata Toshiyuki", "Ueda Kazuhiro"], "journal": "General thoracic and cardiovascular surgery cases", "entry_date": "2026/03/10 01:00", "pub_date": "2026-03-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41804001/", "pub_types": ["Journal Article"], "affiliations": ["Department of General Thoracic Surgery, Graduate School of Medical and Dental Sciences Kagoshima University, 8-35-1, Sakuragaoka, Kagoshima City, Kagoshima Prefecture, 892-8520, Japan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.4}, {"pmid": "41802783", "title": "Caring beyond the procedure: a qualitative study on thoracic surgery nurses' perspectives on chronic illness experiences of individuals with myasthenia gravis undergoing thymectomy.", "abstract": "OBJECTIVES: To explore how thoracic surgical nurses perceive and respond to the chronic illness needs of individuals with myasthenia gravis undergoing thymectomy.\nMETHODS: Data were collected through four focus group interviews using a semi-structured interview guide. The analysis followed a hermeneutic approach, identifying recurring themes through iterative interpretation and critical reflection. Nineteen thoracic surgical nurses from ward and postanaesthesia care unit settings participated, representing a diverse range of clinical experience. The study followed the Consolidated Criteria for Reporting Qualitative Research (COREQ) checklist for reporting the findings of this study.\nRESULTS: The analysis identified three overarching themes reflecting nurses' experiences of caring for individuals with myasthenia gravis undergoing thymectomy. First, nurses described how the chronic aspects of the illness often 'disappeared' within the surgical care process, with attention focused mainly on procedural recovery, leaving patients' broader illness needs unaddressed. Second, nurses experienced a dilemma between providing acute surgical care and responding to patients' chronic illness understanding, highlighting uncertainty due to limited knowledge and lack of clear guidelines. Third, nurses emphasised the difficulty of managing the invisible and unpredictable symptoms of myasthenia gravis, which created a heightened need for vigilance but also uncertainty in symptom assessment and support. Across all themes, the findings suggest that surgical care practices may insufficiently recognise patients' ongoing illness experiences, emphasising the need for greater knowledge, interdisciplinary collaboration and chronic illness-sensitive care approaches.\nCONCLUSIONS: The study highlights the need for increased attention to chronic illness needs in surgical care, supporting interdisciplinary collaboration and tailored nursing practices that address the lived experiences of patients with chronic conditions.", "authors": ["Missel Malene", "Donsel Pernille Orloff", "Nielsen Trine Fjællegaard", "Secher Erik Lilja", "Medeiros Estephani Birkenfeldt Zeballos", "Rude Katrine", "Højgaard Joan Lilja Sunnleyg", "Viby Niels-Erik", "Birnbaum Simone", "Andersen Linda Kahr", "Petersen Rene Horsleben", "Witting Nanna"], "journal": "BMJ open", "entry_date": "2026/03/09 20:54", "pub_date": "2026-03-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41802783/", "pub_types": ["Journal Article"], "affiliations": ["Cardiothoracic Surgery, Copenhagen University Hospital Rigshospitalet Heart Centre, Copenhagen, Denmark Malene.Missel@regionh.dk."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "41800158", "title": "Quality and reliability of myasthenia gravis-related short videos on TikTok and Bilibili: A cross-sectional study.", "abstract": "OBJECTIVES: TikTok and Bilibili have gradually become important platforms for the public to access health information. This study aims to evaluate the quality and reliability of MG-related videos on these platforms.\nMETHODS: This study collected the top 150 MG-related videos from both platforms. General characteristics, uploader identity, and engagement metrics were extracted. The Global Quality Score (GQS) and modified DISCERN (mDISCERN) were used to evaluate video quality and reliability. Mann-Whitney U-test and Kruskal-Wallis H-test were used for inter-group comparisons, and Spearman's rank correlation analysis was performed to assess correlations.\nRESULTS: A total of 225 videos were included in this study. The content of the videos predominantly focused on symptoms (63.6%) and treatment (49.3%), while diagnosis (25.3%) and prevention (13.3%) were less represented. The median GQS for TikTok was 3 (2-3), and the median mDISCERN was 2 (2-3). For Bilibili, the median GQS was 2 (1-3), and the median mDISCERN was 2 (2-2). Videos uploaded by specialists were of higher quality and reliability compared to those uploaded by individual users (P < 0.05). Engagement metrics showed weak correlations with GQS and mDISCERN (P < 0.05).\nCONCLUSION: MG-related videos on both platforms have incomplete content structures, with low quality and reliability. Videos uploaded by specialists were of higher quality and reliability compared to those uploaded by individual users. Engagement metrics showed weak correlations with video quality and reliability. Future platforms should strengthen content moderation and professional involvement to improve the quality of digital health education.", "authors": ["Liao Qian-Ying", "Guo Wang", "Chu Yu-Hao"], "journal": "Digital health", "entry_date": "2026/03/09 06:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41800158/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Dali University, Dali, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "41798820", "title": "Clinical and electrophysiological characteristics of myasthenia gravis patients with concomitant type 2 diabetes mellitus.", "abstract": "BACKGROUND AND OBJECTIVES: Type 2 Diabetes Mellitus (T2DM) is a common comorbidity in late-onset myasthenia gravis (MG), with pre-existing T2DM in some MG patients hinting at a possible pathogenic connection between the two disorders. This study aims to explore the clinical and neurophysiological features of MG, with a particular focus on the electrophysiological disparities between MG patients with and without T2DM.\nMETHODS: In this retrospective study, 170 MG inpatients were recruited and divided into T2DM (n = 51) and non-T2DM groups. Clinical profiles and electrophysiological characteristics were compared.\nRESULTS: There were no significant differences between the two groups in terms of MG clinical classification, Quantitative MG (QMG) scores, or antibody profiles. Electrophysiologically, the T2DM group exhibited peripheral neuropathy, characterized by prolonged distal motor latencies, decreased compound muscle action potential (CMAP) amplitudes, slowed motor nerve conduction velocities, extended F-wave latencies, and sensory nerve dysfunction. In low-frequency repetitive nerve stimulation (LFRNS) of the facial nerve, the decrement pattern was predominantly \"L-shaped\" (minimal recovery) in T2DM patients, in contrast to the \"U-shaped\" pattern in non-T2DM patients. Accessory nerve LFRNS decrement showed a positive correlation with QMG score, fasting blood glucose levels, and diabetes duration.\nCONCLUSION: Patients with MG and concomitant T2DM demonstrate electrophysiological evidence of peripheral nerve impairment and a unique \"L-shaped\" decrement pattern on LFRNS of the facial nerve. This distinct electrophysiological phenotype likely reflects a complex interplay of metabolic derangements at the neuromuscular junction (NMJ). These results highlight the critical role of glycemic control in the management of MG.", "authors": ["Li Xue-Min", "Liu Yu-Dong", "Yang Chun-Lin", "Zhang Peng", "Gong Yan-Mei", "Duan Rui-Sheng", "Liu Ying"], "journal": "Frontiers in neurology", "entry_date": "2026/03/09 06:13", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41798820/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Shandong Provincial Qianfoshan Hospital, Shandong University, Jinan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41798655", "title": "Cholinergic Crisis Associated With Standard-Dose Pyridostigmine in a Hemodialysis Patient With Ocular Myasthenia Gravis and Marked Weight Loss.", "abstract": "Pyridostigmine is an acetylcholinesterase inhibitor widely used for the symptomatic treatment of myasthenia gravis (MG). Cholinergic crisis is a rare but life-threatening adverse effect caused by excessive cholinergic stimulation. Since pyridostigmine is primarily excreted by the kidneys, standard doses may become excessive in the presence of severe renal impairment. We report a case of cholinergic crisis in an elderly patient on maintenance hemodialysis (HD) who exhibited significant weight loss and severe hypoalbuminemia. An 81-year-old male with acetylcholine receptor antibody-positive ocular MG on maintenance HD developed acute loss of consciousness and severe hypoxemia immediately after his usual pyridostigmine therapy (60 mg twice daily). He presented with marked miosis, profuse secretions, severe bradycardia, and hypotension. Arterial blood gas analysis revealed extreme hypercapnia, and serum cholinesterase (ChE) levels were markedly depressed (17 U/L; reference range: 240-486 U/L). Pyridostigmine was immediately discontinued, and atropine was administered via bolus followed by continuous infusion. During the period of hemodynamic instability, the patient required tracheal intubation and continuous hemodiafiltration (CHDF). Continuous atropine administration was gradually tapered and discontinued on day 12. A tracheostomy was performed on day 12, the patient was successfully weaned from mechanical ventilation on day 16, and he was discharged from the intensive care unit (ICU) on day 22. This case underscores that even standard doses of pyridostigmine can induce a cholinergic crisis in patients with severe renal failure receiving HD. Furthermore, significant weight loss and severe hypoalbuminemia may have increased the patient's vulnerability to severe cholinergic toxicity.", "authors": ["Junki Kinoshita", "Nozaki Yusuke", "Miyake Kentaro"], "journal": "Cureus", "entry_date": "2026/03/09 06:11", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41798655/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Anesthesiology and Critical Care, Kasugai Municipal Hospital, Kasugai, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41797742", "title": "Seizure as an Atypical Presentation of Myasthenia Gravis: A Rare but Critical Diagnostic Challenge.", "abstract": "A 27-year-old male patient with a known case of epilepsy and also recently diagnosed with myasthenia gravis presented with dysphagia, respiratory distress, and seizures. Despite timely intervention, he progressed into septic shock during a myasthenic crisis and succumbed to cardiopulmonary arrest. The underlying autoimmune nature of this condition shows a clinically significant and rare overlap between myasthenia gravis and epilepsy. This case emphasizes the importance of early detection and careful drug selection or management in neuromuscular and neurological disorders.", "authors": ["Faisal Huda", "Chanchan", "Chaman Lal Karan", "Adnan Zahabia", "Zehra Shamyl", "Ahmed Md Faisal"], "journal": "Clinical case reports", "entry_date": "2026/03/09 06:04", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41797742/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine Peoples University of Medical & Health Sciences Nawabshah Sindh Pakistan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41795502", "title": "Astragaloside IV ameliorates experimental autoimmune myasthenia gravis through multi-target regulation of immune-microbiota-metabolism network and ferroptosis inhibition.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder targeting neuromuscular junction proteins, with rising incidence and limited therapies. Astragaloside IV (AS-IV), a bioactive saponin from Astragalus membranaceus, exhibits immunomodulatory properties, but its mechanisms in MG remain unclear.\nMETHODS: We investigated the therapeutic efficacy and underlying mechanisms of AS-IV in an experimental autoimmune myasthenia gravis (EAMG) rat model using an integrated multi-omics approach, including 16S rRNA sequencing, metabolomics, and network pharmacology. Immune cell subsets (Th1, Th17, Treg, Tfh), gut microbiota, metabolic profiles, and ferroptosis-related pathways were analyzed.\nRESULTS: AS-IV treatment significantly alleviated disease severity in EAMG rats by restoring immune homeostasis, evidenced by reduced pro-inflammatory Th1 and Th17 cells, increased regulatory T cells (Tregs), and suppressed T follicular helper (Tfh) cell responses. 16S rRNA sequencing revealed that AS-IV modulated gut microbiota composition, enriching beneficial taxa (Lactobacillus, Duncaniella) while suppressing pathogenic genera (Enterococcus_B). Metabolomic analysis identified AS-IV-mediated correction of metabolic disturbances, particularly in arachidonic acid metabolism pathways. Integrated network pharmacology and molecular docking analyses further identified the regulation of ferroptosis as a potential key mechanism, suggesting that AS-IV may exert its protective effects through inhibition of ferroptosis in EAMG.\nCONCLUSION: AS-IV ameliorates EAMG through multi-target effects involving immune regulation, gut microbiota remodeling, metabolic reprogramming, and the inhibition of ferroptosis, highlighting its potential as a cost-effective adjunct therapy for MG.", "authors": ["Xu Lin", "Li Yan", "He Zhilin", "Chen Wei", "Li Yanbin"], "journal": "Pathology, research and practice", "entry_date": "2026/03/08 06:31", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41795502/", "pub_types": ["Journal Article"], "affiliations": ["The First Clinical Medical College, Shandong University of Traditional Chinese Medicine, Jinan, Shandong 250013, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41795178", "title": "Experience Using Efgartigimod to Treat Juvenile Myasthenia Gravis in China: A Multicenter Retrospective Study.", "abstract": "INTRODUCTION/AIMS: Current therapeutic management of juvenile myasthenia gravis (JMG) predominantly relies on conventional immunosuppressive therapies and expert consensus extrapolated from adult data, creating a critical gap in high-quality, pediatric-specific clinical evidence. The aim of this study was to assess the efficacy and safety of efgartigimod in the pediatric population.\nMETHODS: This multicenter retrospective study enrolled JMG patients (under 18 years), from 12 Chinese centers, who received at least one dose of efgartigimod. Efgartigimod was administered as weekly intravenous infusions. Study visits included W0 (baseline: pretreatment) and W1-W4 (weekly posttreatment follow-ups). Efficacy was assessed via MG-related Activities of Daily Living (MG-ADL) score, Quantitative Myasthenia Gravis (QMG) score, and the MG Composite (MGC) scale.\nRESULTS: Seventeen JMG patients (3 males, 14 females) with a median disease duration of 23 months were included. At W0, 88.2% of patients were classified as Myasthenia Gravis Foundation of America (MGFA) class II-V and were anti-acetylcholine receptor (anti-AchR) antibody positive. After efgartigimod treatment, clinically meaningful improvement (CMI) was observed in 70.6% (W1), 73% (W2), and 91.7% (W4); 66.7% achieved minimal symptom expression by W4. MG-ADL and QMG scores decreased by 30% and 30.1% (W1) and by 87.6% and 71.8% (W4) compared to W0. No treatment-related adverse events occurred.\nDISCUSSION: Our study suggests efgartigimod is an effective therapeutic option for JMG, with favorable efficacy and safety profiles. Further studies are necessary to validate the efficacy and safety of efgartigimod in the pediatric population.", "authors": ["Lin Jing", "Qi Guoyan", "Luo Susan", "Jiang Qilong", "Bu Bitao", "Liu Min", "Wei Yuzhen", "Han Meigui", "Yang Junhong", "Zhao Zhilan", "Zhang Lili", "Zhang Yifan", "Xu Haoyou", "Hao Xingjie", "Li Zhijun"], "journal": "Muscle & nerve", "entry_date": "2026/03/08 01:23", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41795178/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41795172", "title": "Increased Prevalence of Extrathymic Neoplasms in Myasthenia Gravis Patients-A Population-Based, Matched Case-Control Study.", "abstract": "INTRODUCTION/AIMS: Myasthenia gravis (MG) is associated with thymic neoplasms. However, an increased prevalence of extrathymic neoplasms has also been reported. This study aimed to evaluate the rates of malignancy in MG patients while accounting for risk factors such as disease characteristics and immunomodulatory treatments.\nMETHODS: We conducted a case-control study using the Clalit Health Services database, applying a machine learning (ML) algorithm to minimize diagnosis misclassification. We included MG patients aged 18 years and older, with a sex- and age-matched control group in a 1:3 ratio. We compared the prevalence and hazard ratios of extrathymic neoplasms between the groups.\nRESULTS: A total of 1558 patients with a high probability of MG, according to our ML model, were included in the cohort, alongside a control group of 4674 individuals. MG patients had a higher prevalence of malignancy prior to MG diagnosis, with an odds ratio of 1.95 (95% CI, 1.65-2.08), and a higher incidence of malignancy after MG diagnosis, with a hazard ratio of 1.56 (95% CI, 1.38-1.77). The most prevalent extrathymic neoplasms after MG diagnosis were respiratory, intrathoracic, skin (specifically non-melanoma), urinary tract, soft tissue, and myelodysplastic syndrome. Risk factors for malignancy included age, male sex, and thymoma. Immunosuppressive treatment did not increase the risk of malignancy.\nDISCUSSION: MG patients have a higher prevalence of both solid and hematologic neoplasms compared to non-myasthenic controls, regardless of immunosuppressive treatment. This supports the notion that malignancy is related to MG disease itself rather than external factors.", "authors": ["Pardo Keshet", "Kab Tasneem", "Hellmann Mark A", "Lotan Itay", "Shochat Tzippy", "Loebl Nadav", "Yacobi Bar", "Friedman Yitzhak", "Perl Leor", "Shimon Nitai", "Weisband Yiska Loewenberg", "Bieber Liya", "Auriel Eitan", "Wilf-Yarkoni Adi"], "journal": "Muscle & nerve", "entry_date": "2026/03/08 01:23", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41795172/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Rabin Medical Center, Petach Tikva, Israel."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41794683", "title": "Clinical and economic outcomes of therapeutic plasma exchange and intravenous immunoglobulin for treating adults with autoimmune neurological disorders: a systematic review and meta-analysis.", "abstract": "BACKGROUND: Therapeutic plasma exchange (TPE) and intravenous immunoglobulin (IVIG) are high-cost treatments used for relapsed or refractory autoimmune neurological disorders.\nOBJECTIVE: To compare the effectiveness, safety and economic outcomes of therapeutic plasma exchange (TPE) compared with intravenous immunoglobulin (IVIG) for treating autoimmune neurological disorders.\nMETHODS: MEDLINE, Embase, PubMed, The Cochrane Library, Transfusion Evidence Library, ClinicalTrials.gov and WHO ICTRP were searched from inception to 30th April 2025. Only randomised controlled trials (RCTs) involving people diagnosed with any autoimmune neurological disorders and comparing TPE with IVIG were included. Quality of the included studies was assessed via Cochrane risk of bias tool (ROB2). Meta-analysis was performed when feasible. Additionally, a rapid review was conducted on model-based economic evaluations for treating MG, GBS, and CIDP to identify and highlight existing gaps and limitations in included clinical trials for developing an economic model. A review protocol was pre-registered at PROSPERO 2024 CRD42024552257.\nRESULTS: Fifteen RCTs were eligible for inclusion: five for myasthenia gravis (MG) (N = 247), eight for Guillain-Barré Syndrome (GBS) (N = 887) and two for chronic immune-mediated polyradiculoneuropathy (CIDP) (N = 32). No trials were found for any other disorders. The trials were at low to high risk of bias. For MG there was no difference between TPE and IVIG at three weeks on the functional improvement scale (SMD 0.31, 95% confidence interval − 0.01 to 0.64, low-certainty evidence). No significant differences were found with regard to the frequency of serious adverse events (SAEs), any adverse events (AEs), length of hospital stay or quality of life on the MG-QoL60 and MG-QoL15 scales. The mean overall direct medical cost was approximately 1.4 times higher in the IVIG group compared to the TPE group. For GBS, there was no significant difference at three to six weeks on functional improvement scale (SMD = -0.65 95% CI -1.40 to 0.11, low-certainty evidence). Two studies comparing mean and median direct cost between IVIG and TPE for GBS patients showed that IVIG group impose approximately 1.5 times higher costs than TPE. Data on other outcomes were limited and economic evaluation for indirect costs, disutilities due to AEs and carer disutilities were absent. For CIDP, limited data showed a lower level of deficit at 6 weeks with no significant difference between TPE and IVIG (MD 15.00, 95% CI -16.37, 46.37) and no difference regarding SAEs or any other AEs. No trials estimated costing.\nCONCLUSION: The effectiveness and safety of TPE were comparable to IVIG for treating autoimmune neurological disorders, although data are limited. TPE conveys lower overall healthcare costs than IVIG.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s12883-026-04780-1.", "authors": ["Kimber Catherine", "Malouf Reem", "Javan Javad", "Dorée Carolyn", "Howe Elaine", "McDonald Vickie", "Leite M Isabel", "Rinaldi Simon", "Tsiachristas Apostolos", "Desborough Michael", "Estcourt Lise"], "journal": "BMC neurology", "entry_date": "2026/03/07 23:13", "pub_date": "2026-03-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41794683/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Systematic Review Initiative, NHSBT, Oxford, UK. catherine.kimber@ndcls.ox.ac.uk."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41793243", "title": "Cloudy or Clear? Readability and Content Analysis of Patient Education Materials in Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder that requires complex treatment decisions and sustained disease self-management. Health literacy is essential for patient understanding of MG, yet online patient education materials (PEMs) have not been systematically studied. This study aimed to evaluate the readability of MG-related PEMs, assess the inclusion of key topics, and identify characteristics associated with more accessible and comprehensive resources.\nMETHODS: We conducted a cross-sectional analysis of MG-related PEMs identified through Google and Bing, evaluating readability using the Flesch Reading Ease Score (FRES), Flesch-Kincaid Grade Level (FKGL), and Simple Measure of Gobbledygook (SMOG). Content analysis was conducted for inclusion of key MG topics. PEMs were categorized by organization type, target population age, and geographic location. Statistical tests included Wilcoxon signed-rank, Kruskal-Wallis, Mann-Whitney U, and Fisher's exact test.\nRESULTS: All 149 PEMs exceeded the recommended 6th-grade reading level (median FRES 41.8, FKGL 11.4, SMOG 12.9; p < 0.001). Community organization PEMs were more readable than academic PEMs (median FKGL 10.4 vs. 11.6; p = 0.02, median FRES 44.5 vs. 39.4; p = 0.01). Frequently included topics were MG definition (94%), symptoms (93%), and immunotherapy (85%), while medications to avoid (30%), myasthenic crisis (62%), and mental health (10%) were the least included. Readability varied by topic, with immunotherapy and thymectomy sections being the most complex.\nDISCUSSION: MG PEMs are written above recommended readability levels, posing barriers to comprehension. Improving readability and addressing gaps in critical topics, such as medication safety, myasthenic crisis, and mental health could enhance patient understanding and support informed decision-making.", "authors": ["Drakou Eleni", "Aziz Ali", "Brown Amelia", "Holmes Michael", "Delfiner Leslie", "Correa Daniel José"], "journal": "Muscle & nerve", "entry_date": "2026/03/07 06:23", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41793243/", "pub_types": ["Journal Article"], "affiliations": ["Saul R. Korey Department of Neurology, Montefiore Medical Center, Bronx, New York, USA."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41787190", "title": "Myasthenia gravis and pregnancy: a systematic review and meta-analysis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disease with an onset age distribution in women, which peaks within the reproductive age range, leading to a potential interference with pregnancy. In this systematic review, we aim to assess the impact of pregnancy on the course of MG during pregnancy and postpartum period and to identify potential risk factors influencing the postpartum course.\nMETHODS: A systematic literature search was conducted in the two databases PubMed and Epistemonikos on the topic \"Myasthenia gravis and pregnancy\" in October 2025. We included cohort studies and case series with at least 5 cases, reporting the clinical course of MG in women during pregnancy or postpartum period. Quality assessment was performed using the Critical Appraisal Skills Programme (CASP) tool for cohort studies.\nRESULTS: In total, 34 studies were included, covering 3720 pregnancies in women with MG. Of 842 pregnancies worsening myasthenic symptoms was reported in 30% of pregnancies most frequently in the first trimester. Postpartum exacerbations were observed in 27% of the cases. However, incidence of worsening and scoring systems differed vastly. Preterm birth was reported at a rate of 9%. Vaginal delivery and cesarean section were performed in 68% and 32% respectively. Of 1530 infants, 9% developed neonatal myasthenia gravis.\nCONCLUSION: This review confirms that symptom worsening is most common in the first trimester or postpartum. Women with MG were more likely to require cesarean section or operative vaginal delivery compared to general population data. However, the studies' quality varied widely. Prospective studies are needed to better identify risk factors for complicative course during pregnancy and postpartum period.", "authors": ["Miegel Lisa", "Hickstein Julia", "Reibelt Antonia", "Heesen Christoph", "Schubert Charlotte"], "journal": "Journal of neurology", "entry_date": "2026/03/05 23:29", "pub_date": "2026-03-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41787190/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis", "Review"], "affiliations": ["Institute of Neuroimmunology and Multiple Sclerosis, University Medical Center Hamburg-Eppendorf, Hamburg, Germany."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41786016", "title": "Efficacy and safety of telitacicept for myasthenia gravis in real-world practice and exploratory outcomes in the elderly subgroup.", "abstract": "OBJECTIVE: To assess the efficacy and safety of telitacicept in myasthenia gravis (MG), focusing on elderly patients.\nMETHODS: Sixteen MG patients receiving weekly telitacicept (160 mg) for 3 months were retrospectively analyzed.\nRESULTS: Telitacicept significantly improved Myasthenia Gravis Activities of Daily Living (MG-ADL), from 7.31 ± 5.02 to 1.13 ± 1.20 (p < 0.001), and Quantitative Myasthenia Gravis (QMG), from 14.81 ± 7.04 to 4.75 ± 2.27 (p < 0.001). Although not statistically significant, elderly patients showed a trend toward greater reductions in MG-ADL (-5.43 vs -3.56 at 1 month, p = 0.41; -7.29 vs -5.33 at 3 months, p = 0.54) and QMG (-8.86 vs -5.33 at 1 month, p = 0.32; -11.14 vs -9.22 at 3 months, p = 0.65). Minimal symptom expression (MSE) was 81.25%, reaching 100% in elderly patients. Immunoglobulin levels (p < 0.001), CD19+ B-cell percentages (p < 0.01), autoantibody titers (p < 0.01), and corticosteroid dosage (p < 0.05) decreased significantly.\nCONCLUSION: Telitacicept is a safe, effective MG add-on therapy. Elderly patients show a potential trend toward greater improvement, warranting larger studies.", "authors": ["Xiao Xiang", "Zeng Qiuming", "Ouyang Song", "Lu Wei", "Hu Zhaolan", "Liang Yong", "Jin Wanlin", "He Dan", "Jiang Wei", "Li Miao", "Chen Juan", "Yan Jianhui", "Yin Weifan"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2026/03/05 19:12", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41786016/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, Hunan, PR China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41784328", "title": "Neoadjuvant BO-112 and hypofractionated radiation therapy with or without nivolumab in soft tissue sarcoma: preclinical and phase 1 results.", "abstract": "Neoadjuvant immune checkpoint blockade (ICB) and radiation therapy (RT) improve disease-free survival in select patients with soft tissue sarcoma (STS). However, most STS are myeloid-rich and lack pre-existing T cells associated with ICB response. In preclinical models, we observed that intratumoral BO-112 (nanoplexed polyinosinic: polycytidylic acid (poly I:C)) engages myeloid cells that persist after RT, ultimately enhancing T cell-dependent tumor control. We evaluated BO-112 and hypofractionated RT, with or without nivolumab, in fourteen patients with high-risk STS in a phase 1 neoadjuvant trial. Consistent with its immunologic potency, the triple combination induced rare immune-related adverse events (myositis-myocarditis-myasthenia gravis spectrum), mitigated by BO-112 and nivolumab dose adjustment. BO-112 and RT reprogrammed tumor-associated myeloid cells toward antigen-presenting states, promoted clonal replacement by less exhausted T cells, and enhanced malignant cell depletion compared to standard RT. These immunologic changes coincided with encouraging disease control in a small, high-risk cohort, supporting further clinical development.", "authors": ["Deng Jie", "Pal Aastha", "Testa Stefano", "Xu Jingyu W", "Tran Linh M", "Graham Danielle S", "Hargil Aviv", "Subramanian Ajay", "Campbell Katie M", "Limsuwannarot Sam", "Chumpitaz Lavalle Álvaro", "Chin Scott C", "Kremer Sarah", "Tariveranmoshabad Mito", "Ewongwo Agnes", "Silvia Sk Nadia Rahman", "Ogana Heather", "Nemat-Gorgani Neda", "Dubinett Steven M", "Jaycox Jillian R", "Felix Carol", "Schaue Dörthe", "Nelson Scott D", "Levine Benjamin", "Motamedi Kambiz", "Ghazikhanian Varand", "Chmielowski Bartosz", "Reddy Vishruth", "Singh Arun S", "Trnkova Zuzana Jirakova", "Good Zinaida", "Quintero Marisol", "Crompton Joseph G", "Bernthal Nicholas", "Eilber Fritz C", "Moding Everett J", "Kalbasi Anusha"], "journal": "Cancer discovery", "entry_date": "2026/03/05 08:33", "pub_date": "2026-03-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41784328/", "pub_types": ["Journal Article"], "affiliations": ["University of California, Los Angeles Los Angeles United States."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 33.3, "journal_quartile": "1区"}, {"pmid": "41782541", "title": "[Diagnosis of myasthenia gravis in a patient with polymyositis].", "abstract": "In recent years, there has been an increase in publications on rare cases of combined myasthenia gravis and idiopathic inflammatory myopathies, including polymyositis. Such cases complicate the differential diagnosis and worsen patients' prognosis. This article presents a rare case of a patient with two serious autoimmune diseases: myasthenia gravis and polymyositis. A clinical case of the ocular form of myasthenia gravis in a 60-year-old woman with a long history of polymyositis is presented, with a detailed discussion of diagnostic and treatment stages. Clinically, polymyositis was manifested by proximal tetraparesis and confirmed by electromyography and biopsy data, and a good response to glucocorticoid therapy. Decrement test results were within acceptable limits. An increase in creatine phosphokinase up to 1630 U/L was observed. Ocular myasthenia gravis was diagnosed based on clinical criteria, with a positive pharmacological fatigue test (positive proserin test). Literature reviews on this topic are presented, emphasizing the importance of early diagnosis and adequate pathogenetic therapy to improve the prognosis for both polymyositis and myasthenia gravis.\nЗа последние годы увеличивается количество публикаций о редких случаях комбинации миастении с идиопатическими воспалительными миопатиями, включая полимиозит. Такие случаи осложняют дифференциальную диагностику и ухудшают прогноз пациентов. Настоящая статья посвящена редкому случаю одновременного наличия у одной пациентки двух серьезных аутоиммунных заболеваний — миастении и полимиозита. Приведен клинический случай развития глазной формы миастении у женщины 60 лет с длительным анамнезом полимиозита, подробно изложены этапы диагностики и проведенного лечения. Клинически полимиозит проявлялся проксимальным тетрапарезом, был подтвержден данными электромиографии и биопсии и хорошим ответом на терапию глюкокортикоидами. Декремент-тест — в пределах допустимых значений. Наблюдалось повышение креатинфосфокиназы до 1630 ед/л. Глазная миастения установлена на основании клинического критерия диагностики с положительным тестом на утомление и положительной прозериновой пробы. Представлены обзоры литературы по данной тематике, подчеркивающие важность ранней диагностики и адекватной патогенетической терапии, способствующей улучшению прогноза как полимиозита, так и миастении.", "authors": ["Makarova D Yu", "Karnaukh V N"], "journal": "Zhurnal nevrologii i psikhiatrii imeni S.S. Korsakova", "entry_date": "2026/03/05 04:16", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41782541/", "pub_types": ["Journal Article", "Case Reports", "English Abstract"], "affiliations": ["Amur State Medical Academy, Blagoveshchensk, Russia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41781681", "title": "Physical and respiratory training in patients with myasthenia gravis: a systematic review with meta-analysis.", "abstract": "UNLABELLED: Myasthenia gravis is a chronic autoimmune disorder that affects the neuromuscular junction, leading to impaired muscle function. This systematic review aimed to evaluate the current scientific evidence on the effects of training programs on symptom severity, performance in activities of daily living, quality of life, physical fitness, and respiratory function in individuals with myasthenia gravis. A systematic review and meta-analysis were conducted following the PRISMA guidelines. Searches were performed in PubMed, Scopus, Web of Science, and CINAHL Complete databases. Outcomes of interest included symptom severity scores, quality of life, activities of daily living performance, physical fitness, and respiratory parameters. A total of 1564 records were identified. After removing duplicates and screening titles, abstracts, and full texts, 20 studies were included in the qualitative synthesis, with 10 of them contributing to quantitative meta-analyses. Training interventions were associated with reductions in symptoms, as well as improvements in quality of life and performance in activities of daily living. Additionally, enhancements were observed in muscle strength, distance covered, and respiratory parameters. Physical activity and respiratory training may offer multiple benefits for patients with myasthenia gravis. Nevertheless, individualized exercise programs are essential to ensure safety and optimize adherence among this population.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1038/s41598-026-42949-3.", "authors": ["Gutierrez-Del-Val Guillermo", "Serrano-Fernandez Victor", "Mazoteras-Pardo Victoria", "Molina-Madueño Rosa Maria", "Bouzas-Mosquera Carmen", "Carmona-Torres Juan Manuel", "Laredo-Aguilera Jose Alberto"], "journal": "Scientific reports", "entry_date": "2026/03/04 23:25", "pub_date": "2026-03-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41781681/", "pub_types": ["Journal Article"], "affiliations": ["Hospital Universitario de Toledo, Avda. Rio Guadiana s/n, 45007, Toledo, Spain."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41777983", "title": "Early-Onset Immune Checkpoint Inhibitor-Induced Myasthenia Gravis Following First-Cycle Pembrolizumab: Diagnostic Challenges and Management Strategies.", "abstract": "Immune checkpoint inhibitors (ICIs), such as pembrolizumab, represent a novel and effective class of immunotherapy in cancer treatment. However, their use is associated with potentially life-threatening immune-related adverse events; the underlying mechanisms of these negative effects remain incompletely understood. Recently, certain ICIs have been associated with the onset of myasthenia gravis (MG), which is considered a spontaneous autoimmune disorder. Due to the rarity of this presentation, there is a significant risk of delayed or missed diagnosis, which may lead to increased morbidity and mortality. This study aims to identify key clinical features, diagnostic challenges, prognostic factors, and the critical importance of early diagnosis approaches that can facilitate the timely detection of ICI-induced MG, potentially reducing the associated morbidity and mortality. A 74-year-old male with renal cell carcinoma, recently started on pembrolizumab, presented with clinical features suggestive of MG with electrophysiological evidence of mild myopathy, though definitive myositis could not be confirmed. The diagnosis was confirmed after a thorough examination and investigation. High-dose corticosteroids and intravenous immunoglobulin (IVIG) were administered, with close respiratory monitoring and symptomatic support. The patient demonstrated marked improvement in strength, swallowing, and forced vital capacity (FVC) with clinical stabilization prior to discharge, while elevated creatine kinase (7,523 U/L) and troponin (297 ng/L) suggested concurrent muscle and possible cardiac involvement, though definitive myositis and myocarditis could not be confirmed without advanced imaging or biopsy. This case illustrates the diagnostic challenges of ICI-induced MG (IrMG), particularly in the absence of positive serological markers, necessitating a clinical diagnosis based on the temporal relationship and therapeutic response. Early recognition and aggressive immunosuppressive treatment with corticosteroids and IVIG achieved excellent functional recovery, emphasizing the importance of high clinical suspicion for prompt management. While permanent pembrolizumab discontinuation was necessary due to the severity of the condition, this case highlights considerations for future rechallenge protocols under careful monitoring.", "authors": ["Gaafar Ziad", "Ahmed Salma", "Tantush Ayoub", "Hesham Gamal Mohamed", "Al-Badawi Saifaldeen S", "Fahal Lamis", "Abouslima Aly"], "journal": "Cureus", "entry_date": "2026/03/04 04:32", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41777983/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Acute Medicine, University Hospitals Birmingham NHS Foundation Trust, Birmingham, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41777944", "title": "Rapidly Progressive Overlap of Immune Checkpoint Inhibitor-Induced Myositis and Myasthenia Gravis: Diagnostic and Therapeutic Challenges.", "abstract": "Immune checkpoint inhibitors (ICIs) are increasingly used across advanced malignancies but may precipitate severe immune-related neuromuscular toxicities, particularly with combination regimens. We report a fulminant case of overlap syndrome involving ICI-induced myositis and myasthenia gravis in a 72-year-old man receiving ipilimumab-nivolumab for hepatocellular carcinoma and recurrent renal cell carcinoma. Shortly after the second cycle, he developed rapidly progressive ophthalmoparesis, bulbar dysfunction, myalgias, and proximal tetraparesis. Laboratory studies revealed marked elevations of creatine kinase, myoglobin, and troponin, and electromyography demonstrated a myopathic pattern with active denervation. Acetylcholine receptor antibodies were positive, raising suspicion for a concomitant ICI-associated myasthenic component within an overlap neuromuscular syndrome. Despite prompt intensive care admission and treatment with high-dose intravenous methylprednisolone and intravenous immunoglobulin, only partial clinical improvement was achieved. The subsequent development of aspiration pneumonia led to acute respiratory and hepatic failure, culminating in death. This case underscores the aggressive clinical trajectory and high mortality of ICI-related neuromuscular overlap syndromes, highlighting the critical need for early recognition, rapid immunosuppression, and multidisciplinary management.", "authors": ["Sequeira Sofia", "Borges Catarina", "Castro Paulo", "Barros Nelson", "Mendes Michel"], "journal": "Cureus", "entry_date": "2026/03/04 04:32", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41777944/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Hospital de Santo Espírito da Ilha Terceira, Angra do Heroísmo, PRT."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41777516", "title": "Non-Motor Symptoms in Myasthenia Gravis Patients: Evaluation of Auditory and Olfactory Functions.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disease characterized by conduction defects at the neuromuscular junction. Recent studies suggest that impairment in acetylcholine neurotransmission occurs not only at the neuromuscular junction but also in the central and peripheral nervous systems. In this context, we aimed to investigate the presence of auditory and olfactory dysfunction, which are non-motor symptoms (NMS), alongside motor symptoms in patients with MG.\nMETHODS: A total of 30 MG patients and 30 healthy controls were enrolled in the study. Demographic characteristics of all participants were recorded. Olfactory functions were assessed using the Connecticut Chemosensory Clinical Research Center (CCCRC) test, while auditory functions were evaluated through pure tone audiometry (PTA) and tympanometric assessment. Additionally, patients were evaluated with MG Foundation of America (MGFA) Clinical Classification, MG-Composite scoring (MGC) and MG-Quality of Life Questionnaire 15-item scale Turkish version (MG-QOL15-T).\nRESULTS: No statistically significant difference was found between the MG and control groups for the n-Butanol threshold test score, identification test score, and total test score, which are components of the CCCRC test. There was no significant correlation between the age of disease onset and olfactory scores. A statistically significant moderate negative correlation was found between disease duration and both identification and total olfactory scores (r=-0.447, p=0.013 and r=-0.374, p=0.042, respectively). In the PTA test, the hearing threshold at 2000 Hz frequency in the right ear of patients was higher compared to the control group, and this difference was found to be statistically significant. No association was found between the patients' olfactory and auditory functions with the MG-QOL15- T.\nCONCLUSION: This study suggests partial impairment in olfactory and auditory functions, NMS, in MG patients; however, these findings do not seem to effect the patients' quality of life. It should be considered that MG may be accompanied not only by motor symptoms but also by NMS.", "authors": ["Akdoğan Özlem", "Sar Alene", "Eren Tuğrul", "Akdemir Enise", "Boyoğlu Nihal Seden", "Tütüncü Melih", "Toprak Ufuk Emre", "Uysal Ömer"], "journal": "Noro psikiyatri arsivi", "entry_date": "2026/03/04 04:27", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41777516/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Clinic, Istanbul Training and Research Hospital, University of Health Sciences, Istanbul, Türkiye."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41777512", "title": "Evaluation of Muscle Oxygenation by Functional Near-Infrared Spectroscopy in Patients with Myasthenia Gravis During Rest and Exercise.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disease that is caused by autoantibodies targeting the neuromuscular junction. A few studies in the literature show that MG may negatively affect muscle metabolism. However, no current study investigates MG pathophysiology's effect on muscle oxygenation. In this study, we aimed to investigate the difference in muscle oxygenation in MG disease and to evaluate its clinical Pathophysiological implications.\nMETHODS: 19 MG patients and 19 age, gender and body mass index (BMI) matched healthy controls participated in the study. Functional near-infrared spectroscopy (fNIRS) recordings were recorded from six channels over the biceps brachii muscles during the rhythmic elbow flexion-extension task.\nRESULTS: It was observed that oxygenated-hemoglobin (HbO) (p = 0.008) and total hemoglobin (HbT) (p = 0.017) values during exercise were significantly lower in MG patients in the motor point of the biceps brachii muscle. In addition, at rest, deoxygenated-hemoglobin (HbR) levels were significantly lower in patients (p<0.05) in the motor point and the lateral region of the biceps brachii muscles. Additionally, a difference is observed in fNIRS values between the moderate-severe MG group and healthy controls. Also, a negative correlation was observed between exercise-state HbO and rest-state HbR values and disease severity (p<0.05).\nCONCLUSION: MG patients show deterioration in muscle oxygenation values during exercise and rest. Oxygenation values show significant differences in disease severity and negatively correlate with disease severity. Based on these findings, MG disease may affect muscle oxygenation and can be monitored by fNIRS.", "authors": ["Semiz Ebru Coşkun", "Alökten Merve", "Karakulak Ece Zeynep", "Aysal Fikret", "Hanoğlu Lütfü"], "journal": "Noro psikiyatri arsivi", "entry_date": "2026/03/04 04:27", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41777512/", "pub_types": ["Journal Article"], "affiliations": ["Brain and Cognition Research Center (BEYKOG), Istanbul Medipol University, Istanbul, Turkiye."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41776695", "title": "Elevated serum Interleukin-39 in Myasthenia gravis: a possible biomarker.", "abstract": "BACKGROUND: Interleukin-39 (IL-39) is a cytokine implicated in immune regulation and autoimmune diseases, but its role in myasthenia gravis (MG) is unknown. This study aimed to investigate serum IL-39 levels in MG patients.\nMETHODS: Serum IL-39 levels were measured by enzyme-linked immunosorbent assay (ELISA) in 51 acetylcholine receptor (AChR) antibody-positive MG patients without thymoma and 43 healthy controls (HCs). A subset of 20 patients who achieved sustained clinical remission after heterogeneous immunotherapy provided paired samples for longitudinal analysis.\nRESULTS: Serum IL-39 levels were significantly higher in active MG patients compared to HCs [median: 5.09 pg/mL (IQR: 4.12-6.23) vs 1.83 pg/mL (IQR: 0.99-2.76); p < 0.001]. In the paired analysis, IL-39 levels were significantly lower during the remission phase than at the active disease baseline [median: 1.66 pg/mL (IQR: 0.94 ~ 3.31) vs 4.28 pg/mL (IQR: 3.69 ~ 5.33); p < 0.001]. IL-39 demonstrated high discriminatory capacity between active patients and HCs (AUC = 0.922). No correlation was found between baseline IL-39 levels and clinical severity scores (MG-ADL).\nCONCLUSION: Serum IL-39 levels are dynamically associated with disease activity states in AChR + MG, decreasing with clinical remission. Its lack of correlation with symptom severity and its likely non-specific nature suggest it may serve as a marker of general immune activation rather than a specific diagnostic or severity biomarker. Further studies are needed to validate its specificity and define its role in MG immunopathology.", "authors": ["Jia Kun", "Shao Yingzhe", "Liu Xuan", "Zhang Qiuxia", "Yang Li"], "journal": "European journal of medical research", "entry_date": "2026/03/03 23:57", "pub_date": "2026-03-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41776695/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Huanhu Hospital, Tianjin, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "41775153", "title": "Letter to the editor: Impact of corticosteroid use on comorbidities in patients with myasthenia gravis in the US National Veterans Affairs Health Network.", "abstract": "", "authors": ["Qian Fenglei", "Yao Xiaomei"], "journal": "Journal of the neurological sciences", "entry_date": "2026/03/03 18:06", "pub_date": "2026-04-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41775153/", "pub_types": ["Letter"], "affiliations": ["Department of Neurology, The Second People's Hospital of Tongxiang, Tongxiang, Zhejiang 314511, China."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41775150", "title": "Distinguishing pharmacological toxicity from disease severity and lifestyle confounders in myasthenia gravis comorbidity models.", "abstract": "", "authors": ["Zhong Linru"], "journal": "Journal of the neurological sciences", "entry_date": "2026/03/03 18:06", "pub_date": "2026-04-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41775150/", "pub_types": ["Letter"], "affiliations": ["Second School of Clinical Medicine, Zhejiang Chinese Medical University, Hangzhou, 310000 Zhejiang, China. Electronic address: zlr277957@163.com."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41773442", "title": "Giant cell myositis confined to the lower extremities without associated thymoma or myasthenia gravis: a case report.", "abstract": "Giant Cell Myositis (GCMm) is an exceptionally rare inflammatory myopathy, historically reported in association with Myasthenia Gravis (MG), Thymoma, or Giant Cell Myocarditis (GCMc). The prognosis is often dictated by the frequently co-occurring, highly lethal GCMc. We describe the case of a 31-year-old male presenting with a three-month history of progressive, painful, and diffuse pseudohypertrophy of the lower extremities. Laboratory findings, including normal creatine kinase, were largely unremarkable, but a muscle biopsy demonstrated the pathognomonic infiltration by multinucleated giant cells. Extensive work-up, including cardiac magnetic resonance imaging and a full autoantibody panel, showed no evidence of cardiac, ocular, or associated thymic disease or MG. This is, to our knowledge, the first reported case of GCMm presenting as an isolated skeletal muscle disease without any known associated systemic conditions, underscoring the importance of considering GCMm in the differential diagnosis for unexplained limb pseudohypertrophy, even in the absence of typical comorbidities or profound muscle weakness.", "authors": ["Elsaca Enrique", "Álvarez Felipe"], "journal": "Acta myologica : myopathies and cardiomyopathies : official journal of the Mediterranean Society of Myology", "entry_date": "2026/03/03 05:13", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41773442/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, School of Medicine, Pontificia Universidad Católica de Chile, Santiago, Chile."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41772612", "title": "Efficacy and safety of immunosuppressants and immunomodulators in juvenile myasthenia gravis: a systematic review and meta-analysis.", "abstract": "OBJECTIVE: In the present meta-analysis, we aimed to explore the efficacy and safety of immunosuppressants and immunomodulators for the treatment of juvenile myasthenia gravis (JMG).\nMETHODS: We conducted a systematic search for studies published between January 1st, 2000 and July 28th, 2025, in PubMed, Embase, Web of Science, and the Cochrane Library. Statistical analyses were performed using Stata (version 16.0). Cochran's Q test and the I2 statistic were used to assess the heterogeneity among the included studies. If significant heterogeneity existed (I2 ≥50% or P < 0.05), the random effects model was used; otherwise, the fixed effects model was used to calculate the pooled results.\nRESULTS: A total of 3029 articles were retrieved. This meta-analysis included 9 cohort and case-control studies, 11 case series, 3 single-arm studies, and 1 randomized controlled trial, focusing on tacrolimus, glucocorticoids, monoclonal antibodies, and intravenous immunoglobulin. Regarding tacrolimus, 9 studies involving 310 patients assessed the efficacy of tacrolimus for treating JMG. The results showed a significant reduction in both the Quantitative Myasthenia Gravis (QMG) and Myasthenia Gravis Activities of Daily Living (MG-ADL) scores. Moreover, tacrolimus treatment allowed for a reduction in steroid dosage, with a response rate of 0.862 (95% CI: 0.716-0.967). For monoclonal antibodies, 6 studies with 67 patients analyzed the efficacy for JMG. The response rate of monoclonal antibodies was 0.993 (95% CI: 0.935-1.000). Descriptive analyses were conducted for glucocorticoids and IVIG. Besides, 5 studies with 348 patients assessed the efficacy of glucocorticoids for JMG. Included studies showed that the efficacy rate of glucocorticoid monotherapy for isolated ocular myasthenia gravis (OMG) was higher than that for patients with both OMG and generalized myasthenia gravis (GMG). Finally, regarding the use of IVIG, 4 studies reported efficacy for JMG. These investigations reported a response rate ranging from 47.06% to 94.3% for IVIG therapy.\nCONCLUSIONS: In summary, this was the first comprehensive meta-analysis of immunosuppressants and immunomodulators in JMG. However, most included studies were single-center retrospective observational studies. Future prospective multicenter studies are needed to further investigate the efficacy and safety of immunosuppressants and immunomodulators in JMG.", "authors": ["Zhong Xiaoling", "Xie Yu", "Li YanMei", "Yang Hua", "Luo Rong"], "journal": "Journal of translational medicine", "entry_date": "2026/03/02 23:53", "pub_date": "2026-03-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41772612/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis", "Review"], "affiliations": ["Department of Pediatrics, West China Second University Hospital, Sichuan University, Chengdu, PR China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41771246", "title": "Zilucoplan is effective for ravulizumab-refractory generalized myasthenia gravis with the C5 p.Arg885His variant: a case report.", "abstract": "Complement inhibition is highly effective for complement-mediated diseases such as paroxysmal nocturnal hemoglobinuria (PNH) and generalized myasthenia gravis (gMG). However, certain C5 variants impair target engagement. In vitro, eculizumab and ravulizumab fail to achieve complete terminal complement blockade, and, in PNH, clinical efficacy is actually compromised in carriers. We report an anti-acetylcholine receptor antibody-positive gMG patient harboring C5 c.2654G>A (p.Arg885His) who exhibited persistent disease activity and only partial suppression of hemolytic complement activity (CH50) during ravulizumab therapy. Switching to zilucoplan, a C5 inhibitor targeting a distinct epitope, produced same-day clinical improvement and sustained remission thereafter, accompanied by undetectable CH50. This is the first report directly demonstrating ravulizumab nonresponse and a robust zilucoplan response in gMG with this variant. Variant-guided selection of complement inhibitors is essential, and pragmatic use of readily available CH50 testing combined with C5 genotyping may help identify potential nonresponders to eculizumab or ravulizumab.", "authors": ["Itagaki Yuya", "Iguchi Masahiro", "Hattori Kasumi", "Akanuma Haruna", "Koizumi Daisuke", "Kobayashi Saro", "Matsuda Nozomu", "Kanai Kazuaki"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2026/03/02 18:02", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41771246/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Fukushima Medical University, 1 Hikarigaoka, Fukushima City, Fukushima, Japan. Electronic address: yta@fmu.ac.jp."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41769624", "title": "Effective Use of the Thoracolumbar Interfascial Plane Block With Total IV Anesthesia for Laminoplasty in a Patient With Myasthenia Gravis: A Case Report.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction that causes fluctuating muscle weakness and fatigue. The development of myasthenic crisis and respiratory compromise presents significant challenges in the perioperative management of these patients. Surgical pain-induced stress is a substantial risk factor for myasthenic crisis. A 68-year-old man with MG underwent L3-L5 lumbar laminoplasty under total IV anesthesia. A bilateral ultrasound-guided thoracolumbar interfascial plane block (TLIPB) was performed at the L4 level following anesthesia induction. Intraoperative opioid administration was intentionally minimized, and postoperative analgesia was provided using IV patient-controlled analgesia (IV-PCA) with fentanyl. Within 24 hours, 10 boluses (total fentanyl dose: 250 μg) were administered, and the Numerical Rating Scale (NRS) score decreased to 3 by 20 hours postoperatively, at which time IV-PCA was discontinued. The patient exhibited no respiratory deterioration or signs of myasthenic crisis and was discharged on postoperative day 9. Achieving adequate analgesia while minimizing the risk of respiratory depression is critical in the perioperative management of patients with MG. In this case, TLIPB was successfully implemented as part of a multimodal analgesic strategy combined with total IV anesthesia to facilitate an opioid-sparing approach, with postoperative pain managed using IV-PCA and scheduled non-opioid analgesics, without any respiratory compromise.", "authors": ["Tanimoto Shota", "Shakuo Tomoharu", "Yamazaki Yutaro", "Umetani Yumi", "Sakamoto Atsunori", "Shida Kenji"], "journal": "Cureus", "entry_date": "2026/03/02 06:50", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41769624/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Anesthesiology, Showa Medical University Northern Yokohama Hospital, Yokohama, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41769457", "title": "Rapid Symptomatic Improvement and Long-Term Minimal Symptom Expression in a Myasthenia Gravis Patient Treated With Zilucoplan Without Maintenance Cholinesterase Inhibitors, Corticosteroids, or Immunosuppressants: A Case Report.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder, often requiring long-term immunosuppressive treatment. Although complement C5 inhibitors, such as zilucoplan, have shown robust efficacy in clinical trials, evidence of their use without maintenance cholinesterase inhibitors, corticosteroids, or other immunosuppressants remains limited. In this report, I describe a woman in her late 60s with anti-acetylcholine receptor antibody-positive generalized MG, who achieved rapid symptomatic improvement and minimal symptom expression with zilucoplan. Clinical stability was sustained for at least one and a half years without concomitant cholinesterase inhibitors, corticosteroids, or other immunosuppressants. This case suggests that zilucoplan may represent an effective and durable treatment option for generalized MG.", "authors": ["Amano Ryota"], "journal": "Cureus", "entry_date": "2026/03/02 06:49", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41769457/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Fujiyoshida Municipal Hospital, Fujiyoshida, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41769309", "title": "Emergency use of eculizumab in impending and manifest myasthenic crisis: a retrospective case series.", "abstract": "Impending and manifest myasthenic crisis (MC) represent life-threatening neurological emergencies that require immediate intervention. Although eculizumab, a terminal complement C5 inhibitor, has established efficacy in generalized myasthenia gravis, most studies have focused on long-term outcomes, and its potential for rapid onset of effect in acute exacerbations has not been well evaluated. We retrospectively analyzed four acetylcholine receptor (AChR) antibody-positive patients (five acute episodes) who received eculizumab as emergency therapy between January 2024 and July 2025. All patients presented with impending or manifest MC; none had received intravenous immunoglobulin, plasma exchange, or neonatal Fc receptor (FcRn) inhibition within the preceding month. According to the Myasthenia Gravis Foundation of America classification, three patients had class IVb and one had class V. Triggers for exacerbation included COVID-19 infection (n = 2), puerperium (n = 1), PD-1 inhibitor exposure (n = 1), and common infection (n = 1). Within 48 h of eculizumab administration, Quantitative Myasthenia Gravis scores improved from 28.2 ± 4.8 to 15.0 ± 4.1, while Myasthenia Gravis Activities of Daily Living scores decreased from 16.8 ± 2.8 to 6.0 ± 4.3. Notable milestones achieved included arterial blood gas improvement within 7.5 h (one patient), nasogastric tube removal within 48 h (three patients), and successful extubation at 17 h (one patient). No treatment-related adverse events were observed. These preliminary findings suggest that eculizumab may be associated with rapid, temporally related clinical improvement within 48 h with a favorable short-term safety profile in AChR antibody-positive patients with impending or manifest MC, particularly those with complement activation triggers. Larger prospective studies with standardized short-term assessment protocols, including frequent neurological evaluations during the first 48 h, are warranted to further validate its efficacy and define its role as an emergency therapy in the acute management of myasthenic exacerbations.\nUsing eculizumab as an emergency treatment for severe worsening of myasthenia gravis: early experience from four patients with five crises Myasthenia gravis (MG) is a rare disease in which the body’s immune system interferes with communication between nerves and muscles, leading to weakness in the eyes, face, arms, legs, and sometimes breathing muscles. In its most severe form, called “myasthenic crisis,” patients can lose the ability to breathe on their own and require urgent hospital treatment. Standard emergency treatments such as intravenous immunoglobulin (IVIG) and plasma exchange can be effective, but they may take several days to work, leaving patients dependent on ventilators or feeding tubes for longer. Eculizumab is a medication that blocks part of the immune system known as the complement pathway, which plays a role in damaging the muscle–nerve connection in MG. While eculizumab is approved for generalized MG, most studies have examined its long-term benefits. Much less is known about whether it can act quickly enough to help in emergency situations. In this study, we reviewed four patients with MG (five episodes of severe worsening) treated at our hospital who received eculizumab during an emergency crisis. Triggers included infections, pregnancy recovery, cancer immunotherapy, and COVID-19. Within 48 hours of receiving eculizumab, patients showed meaningful improvement in their muscle strength and daily activities. Some were able to breathe without a ventilator or have feeding tubes removed much sooner than expected. Importantly, no serious side effects were observed in the short term. Our findings suggest that eculizumab may provide rapid improvement in patients experiencing life-threatening MG crises, particularly when the immune system is strongly activated. However, this was a very small study, and more research in larger groups of patients is urgently needed to confirm its safety and effectiveness as an emergency therapy.", "authors": ["Huang Ying", "Xiong Yihan", "Zhan Hui", "Wu Futian", "Jiang Yichun", "Zhang Yaqing", "Chen Jiaxun", "Zeng Silin", "Zhang Ting", "Xiong Xiaofeng", "Chen Zhuomin", "Yang Fang", "Li Gang", "Xu Qianhui"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/03/02 06:48", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41769309/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Shenzhen People's Hospital, The Second Clinical Medical College, Jinan University, The First Affiliated Hospital, Southern University of Science and Technology, Shenzhen, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41767003", "title": "The temporal sequence of myasthenia gravis and neuromyelitis optica spectrum disorder: a case report and systematic review of 74 patients.", "abstract": "BACKGROUND: The co-occurrence of myasthenia gravis (MG) and neuromyelitis optica spectrum disorder (NMOSD) is rare, and their temporal sequence and shared pathogenesis remain poorly understood.\nMETHODS: We present the case of a 43-year-old woman with pre-existing acetylcholine receptor antibody (AChR-Ab) positive ocular MG who developed aquaporin-4 antibody (AQP4-Ab) positive NMOSD. Additionally, we conducted a systematic literature review up to July 2024 to identify similar cases.\nRESULTS: Including the present case, 74 patients were analyzed. The cohort showed a marked female predominance (89.2%). MG onset significantly preceded NMOSD onset in most patients (93.2%), with a younger mean age at onset (28.19 vs. 41.02 years, p < 0.001) and a mean interval of 12.56 years. Among tested patients, AChR-Ab was positive in 90.5% and AQP4-Ab in 73.0%. In our case, administration of the complement C5 inhibitor eculizumab led to marked clinical improvement after failure of high-dose steroid therapy.\nCONCLUSION: This study suggests a consistent temporal pattern wherein MG predominantly precedes NMOSD, often by years, suggesting a possible shared autoimmune predisposition. The observed response to eculizumab highlights complement pathway inhibition as a potentially effective therapeutic strategy for this complex overlap syndrome, warranting further investigation.", "authors": ["Niu Zhenyu", "Bao Yi", "Yao Lanqiu", "Ren Jingru", "Wang Jianchun", "Guo Jing", "Zhang Nan", "Gao Feng", "Hao Hongjun", "Chen Siwei", "Liu Ran"], "journal": "Frontiers in neurology", "entry_date": "2026/03/02 06:26", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41767003/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Peking University First Hospital, Beijing, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41766084", "title": "Real-World Evaluation of Efgartigimod in Generalized Myasthenia Gravis: A Single-Center Experience.", "abstract": "", "authors": ["Sharma Roopa", "Sabra Ahmed", "Kumar Navina Magesh", "Putrevu Pravallika", "Nizar Souayah", "Hillen Machteld E"], "journal": "Journal of clinical neuromuscular disease", "entry_date": "2026/03/02 00:13", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41766084/", "pub_types": ["Journal Article"], "affiliations": ["Rutgers New Jersey Medical School, Newark, NJ."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41766080", "title": "A Novel Truncating Pathogenic Variant in RRM2B in a Kurdish Family With Autosomal-Dominant Chronic Progressive External Ophthalmoplegia Plus (PEOA5).", "abstract": "OBJECTIVES: To report a family with autosomal-dominant chronic progressive external ophthalmoplegia due to a novel truncating pathogenic variant in RRM2B and to show the challenges facing clinicians in diagnosing rare neuromuscular diseases.\nMETHODS: Four family members were examined. Muscle biopsy, mitochondrial DNA analysis, next generation sequencing, and targeted mitochondrial gene panel followed by Sanger sequencing and complementary deoxyribonucleic acid analysis were performed.\nRESULTS: A novel heterozygous RRM2B truncating variant c.968_972del p.(Phe323*) was identified. complementary deoxyribonucleic acid analysis showed expression of both RRM2B alleles.\nCONCLUSIONS: The proband was initially misdiagnosed as myasthenia gravis. Based on the phenotype and family history, chronic progressive external ophthalmoplegia was suspected and confirmed by finding of a novel RRM2B variant. The detection of another truncating pathogenic variant in exon 9 of RRM2B further supports this exon as mutation hot spot and underlines the role of the C-terminal highly conserved amino acids for the interaction of the p53R2 dimer with the R1 dimer.", "authors": ["Mayer Demian", "Kartsonaki Emmanouela", "Wilder-Smith Einar", "Schaller André", "Frank Stefan", "Bohlhalter Stephan", "Mihaylova Violeta"], "journal": "Journal of clinical neuromuscular disease", "entry_date": "2026/03/02 00:13", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41766080/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Genetica AG, Human Genetics and Genetic Counselling Unit, Zurich, Switzerland."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41765605", "title": "Isolated bilateral facial palsy as the initial presenting manifestation of generalized myasthenia gravis preceding myasthenic crisis.", "abstract": "", "authors": ["Ghosh R", "León-Ruiz M", "Bole K", "Dubey S", "Benito-León J"], "journal": "Neurologia", "entry_date": "2026/03/01 20:54", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41765605/", "pub_types": ["Letter"], "affiliations": ["Department of General Medicine, Burdwan Medical College and Hospital, Burdwan, West Bengal, India."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41764572", "title": "Successful prehospital resuscitation of a young female patient with myasthenia gravis experiencing cardiopulmonary arrest due to complete airway obstruction: a case report and review of the literature.", "abstract": "INTRODUCTION: Patients with myasthenia gravis are at high risk of fatal airway complications due to impaired swallowing mechanics. We present a prehospital resuscitation case involving complete airway obstruction leading to cardiopulmonary arrest in a young patient with myasthenia gravis.\nCASE PRESENTATION: A 21-year-old Han Chinese female patient with a reported history of myasthenia gravis developed sudden respiratory arrest during oral intake. The diagnosis of myasthenia gravis was initially provided by on-scene witnesses (classmates), and later confirmed by family who reported her medication regimen. Prehospital interventions-including modified Heimlich maneuvers, rapid endotracheal intubation, and advanced cardiac life support-achieved return of spontaneous circulation within 10 minutes. Persistent hypoxia and hemodynamic instability were managed during transport. The patient was transferred to the hospital intensive care unit but subsequently died due to the consequences of prolonged cerebral hypoxia.\nDISCUSSION: Myasthenia-gravis-associated bulbar weakness predisposes patients to catastrophic aspiration events. This case highlights three critical prehospital strategies: (1) modified supine-position Heimlich maneuvers for intubated arrest patients, (2) time-critical airway clearance using direct laryngoscopy, and (3) multidisciplinary coordination between telemedicine dispatchers and field responders.\nCONCLUSION: Our findings highlights the unique challenges of managing airway obstruction in patients with myasthenia gravis and proposes an integrated prehospital strategy for airway management. This case underscores that successful prehospital return of spontaneous circulation is possible in patients with myasthenia gravis with acute airway obstruction; however, prevention remains paramount due to the risk of fatal outcomes. It emphasizes the need for integrated prehospital strategies, patient education on aspiration risk, and protocolized airway algorithms for neuromuscular disorders.", "authors": ["Ruan Ziliang", "Wang Tao", "Luo Wen", "Xia Yubo", "Zhou Xiaohan", "Tian Yuwei", "Li Kaiyun", "Liu Yuan"], "journal": "Journal of medical case reports", "entry_date": "2026/03/01 07:37", "pub_date": "2026-02-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41764572/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Emergency Medicine, The Kunming Hospital of Traditional Chinese Medicine, No. 2628 Xiangyuan Street, Chenggong District, Kunming, Yunnan Province, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41763674", "title": "Triple M syndrome (myasthenia gravis, myocarditis and myositis) following atezolizumab in small cell lung carcinoma.", "abstract": "An older adult in his early 80s with locally advanced small cell lung carcinoma was treated with carboplatin, etoposide and atezolizumab. After two well-tolerated cycles, he developed acute ocular and neuromuscular symptoms. Investigations revealed features consistent with immune checkpoint inhibitor-related myasthenia gravis, myocarditis and myositis (triple M syndrome). The patient responded to high-dose corticosteroids and pyridostigmine but required prolonged rehabilitation. Notably, he demonstrated an excellent radiological response to systemic therapy. This case highlights the need for vigilance for severe neuromuscular and cardiac immune-related adverse events, the importance of prompt multidisciplinary management, and the clinical paradox of balancing cancer control with life-threatening toxicity.", "authors": ["Williams Jenna", "Simela Carl", "Bhaskaran Divyalakshmi"], "journal": "BMJ case reports", "entry_date": "2026/02/28 20:33", "pub_date": "2026-02-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41763674/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Bradford Royal Infirmary, Bradford Teaching Hospitals NHS Foundation Trust, Bradford, UK."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "41762916", "title": "Rethinking rituximab in neuroimmunology: Real-world efficacy, cost-effectiveness, and long-term remission.", "abstract": "This short communication reviews the long-term use of rituximab (RTX) in neuroimmunological disease and presents a case of chronic inflammatory demyelinating polyneuropathy (CIDP) achieving sustained remission after rituximab therapy. A 10-year retrospective review of 40 patients treated with RTX at a South African quaternary neurology unit demonstrated consistent efficacy, durable safety, and significant cost savings compared to conventional immunotherapies. In addition, a patient with refractory childhood-onset CIDP achieved complete and enduring remission following RTX administration, with normal functional recovery and discontinuation of all immunotherapy. This report highlights the clinical and economic rationale for RTX as a long-term disease-modifying therapy in immune-mediated neurological disorders and argues for its earlier integration into standard treatment protocols, especially in resource-limited settings.", "authors": ["Moodley Kaminie"], "journal": "Journal of neuroimmunology", "entry_date": "2026/02/28 18:06", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41762916/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, University of KwaZulu-Natal, Durban, South Africa. Electronic address: Kaminie@live.co.za."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41761996", "title": "Progress in the Treatment of Refractory Myasthenia Gravis.", "abstract": "Myasthenia gravis (MG) is an autoantibody-mediated, cellular immune-dependent and complement system-involved autoimmune disorder characterized by acquired neuromuscular junction transmission dysfunction driven by genetic and environmental factors. Approximately 10% therapies such as cholinesterase inhibitors, glucocorticoids, and immunosuppressants, resulting in the development of refractory MG (RMG). The current emergence of new therapeutic strategies such as targeted biologics (e.g., complement inhibitors, Fc receptor (FcRn) antagonists, etc.), B-cell depletion therapy, and Chimeric Antigen Receptor (CAR)-T cell therapy contribute to the significant improvement in the clinical management of RMG. Accordingly, the present study systematically reviewed the treatment progress of RMG, aiming to provide evidence-based individualized treatment decision-making clinically, alleviate patients' pain, and explore future research directions.", "authors": ["Liu Dan", "Mao Jialing", "Song Jing", "Wang Manxia"], "journal": "Revista de neurologia", "entry_date": "2026/02/28 07:22", "pub_date": "2026-02-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41761996/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Lanzhou University Second Hospital, 730000 Lanzhou, Gansu, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41761565", "title": "The Relationship Between Immune Semaphorins and Myasthenia Gravis.", "abstract": "OBJECTIVE: Myasthenia gravis (MG) is an autoimmune disease involving several immune mechanisms. Recently, semaphorins have emerged as potential diagnostic and prognostic biomarkers in autoimmune neurological and non-neurological diseases. This study investigated the role of immune semaphorins, namely semaphorins 3A, 3F, 4A, 4D, and 7A, in the diagnosis and prognosis of MG and their potential as biomarkers.\nMETHODS: Serum levels of semaphorin 3A, 3F, 4A, 4D, and 7A were compared between 41 patients with MG and 39 healthy controls. Patients were grouped according to the Myasthenia Gravis Activities of Daily Living scale, and differences in semaphorin levels between groups were analyzed.\nRESULT: Semaphorin 4A levels were significantly lower, whereas semaphorin 7A levels were higher in patients with MG than in controls. However, no significant correlation was found between the disease stage and semaphorin levels.\nCONCLUSION: Our findings suggest that the levels of semaphorin 4A and 7A may not only support the diagnosis of MG and aid in differential diagnosis but also shed light on the development of future therapeutic protocols targeting semaphorin proteins and receptors in other autoimmune and inflammatory diseases.", "authors": ["Kotan Dilcan", "Çiçekli Esen", "Aydemir Özlem"], "journal": "Brain and behavior", "entry_date": "2026/02/28 01:03", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41761565/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Department, Sakarya University Faculty of Medicine, Sakarya, Turkey."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41760990", "title": "Early versus late add-on therapy in generalized myasthenia gravis: a multicenter real-world cohort study.", "abstract": "BACKGROUND: This study examined whether the timing of targeted add-on therapy initiation influences clinical outcomes in acetylcholine receptor (AChR) antibody-positive generalized myasthenia gravis (gMG), based on the hypothesis that earlier escalation may improve treatment response by intervening before structural or immunological consolidation occurs.\nMETHODS: In this multicenter, retrospective real-world cohort study, 153 patients with AChR antibody-positive gMG were included from eight German tertiary centers. All received either complement C5 inhibitors (eculizumab, ravulizumab) or the FcRn antagonist efgartigimod as add-on therapy. Patients were grouped by treatment initiation within 24 months of diagnosis (Early Intensified Treatment; EIT) or later (Late Intensified Treatment; LIT). MG-ADL, QMG, and MG-QoL15 scores, as well as daily corticosteroid and pyridostigmine doses, were assessed at baseline and at 1, 3, and 6 months.\nRESULTS: The EIT group (n = 36) showed more pronounced and consistent clinical improvement. Significant differences emerged in maximum MG-ADL (p = 0.013) and QMG (p = 0.002) reductions. Patient-acceptable symptom states (MG-ADL ≤ 2, QMG ≤ 7) were more often reached with EIT (p = 0.038, p = 0.006). QMG worsening occurred only in the LIT group (n = 117) (p = 0.021). Prednisone declined more steeply in EIT patients (p = 0.001).\nCONCLUSION: Initiating add-on therapy within two years of diagnosis was associated with stronger and more consistent clinical responses, fewer deteriorations, and a steeper reduction of treatment burden. These findings support timely escalation as a strategy to enhance both efficacy and tolerability in gMG care.", "authors": ["Oeztuerk Menekse", "Huntemann Niklas", "Gerischer Lea", "Herdick Meret", "Nelke Christopher", "Stascheit Frauke", "Hoffmann Sarah", "Lehnerer Sophie", "Stein Maike", "Schubert Charlotte", "Schneider-Gold Christiane", "Pfeuffer Steffen", "Krämer Heidrun H", "Konen Franz Felix", "Skripuletz Thomas", "Pawlitzki Marc", "Rehmann Robert", "Arat Ercan", "Menskes Christina B", "Glaubitz Stefanie", "Zschüntzsch Jana", "Scherwietes Valerie", "Totzeck Andreas", "Hagenacker Tim", "Meisel Andreas", "Meuth Sven G", "Ruck Tobias"], "journal": "Journal of neurology", "entry_date": "2026/02/27 23:27", "pub_date": "2026-02-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41760990/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, BG University Hospital Bergmannsheil, Ruhr University Bochum, Bürkle de la Camp-Platz 1, 44789, Bochum, Germany. menekse.oeztuerk@bergmannsheil.de."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41758503", "title": "Single-cell RNA-sequencing of myasthenia gravis reveals transcriptional heterogeneity and dysfunction of immune cell populations.", "abstract": "The purpose of this study was to explore the composition and function of immune cell subsets at the single cell level in thymus and peripheral blood of patients with myasthenia gravis (MG). A total of 9701 and 23846 cells respectively originated from the peripheral blood and thymus samples of 2 MG patients, and 6930 cells from the peripheral blood of 2 gender- and aged-matched healthy controls were selected for single-cell RNA sequencing. UMAP, GO, KEGG pathway analysis, Monocle3 and Velcyto were performed to analyze the composition, molecular and functional properties, and developmental trajectory of immune cell subsets. Four major cell populations of T cells, B cells, myeloid cells, and NK cells were identified, as well as their 15 cell subpopulations. An absolute predominance of T cells was found in the thymus and peripheral blood of MG patients, and the proportions of memory B cells in both plasma and thymus showed an increasing trend while the number of naïve B cells demonstrated a decreasing trend in MG patients compared with healthy controls. Besides, the monocytes in the peripheral blood of MG patients had the strongest interactions with other cells. Furthermore, CXCL, GAS, and CD30 signaling pathways were more enriched within MG peripheral blood. Our research clarifies the cellular heterogeneity in the pathogenesis of MG and characterizes the immune microenvironment of thymic tissues in MG patients.", "authors": ["Wu Qingjun", "Guo Yingyu", "Zhou Liying", "Tian Yi", "Yu Hanbo", "Zhou Ting", "Yin Siyuan", "Zou Lihui"], "journal": "International immunology", "entry_date": "2026/02/27 11:23", "pub_date": "2026-02-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41758503/", "pub_types": ["Journal Article"], "affiliations": ["Department of thoracic surgery, Beijing Hospital, National Center of Gerontology; Institute of Geriatric Medicine, Chinese Academy of Medical Sciences, P. R. China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41756288", "title": "Association between vaccination and myasthenia gravis: a systematic review and meta-analysis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune disorder characterized by fluctuating muscle weakness due to impaired neuromuscular transmission. Vaccination remains a cornerstone of infectious disease prevention, yet concerns persist regarding potential autoimmune exacerbation in susceptible individuals. This systematic review and meta-analysis aimed to synthesize available evidence on the association between vaccination and MG, evaluating both vaccine effectiveness and safety in this population.\nMETHODS: Observational studies in cohort or case-control formats were identified through systematic searches of PubMed, Web of Science, Embase, Cochrane Library, SinoMed, CNKI, Wanfang, and VIP databases from inception to June 24, 2025. Study quality was assessed using the Newcastle-Ottawa Scale (NOS). Pooled odds ratios (OR) with 95% confidence intervals (CI) were calculated using fixed- or random-effects models based on heterogeneity. Publication bias was assessed using funnel plots and Egger's test.\nRESULTS: Five studies encompassing 27,193 participants (22,618 vaccinated and 4,575 unvaccinated) met inclusion criteria. Meta-analysis demonstrated a significant protective effect of vaccination against COVID-19 infection (fixed-effects model: OR = 0.23, 95% CI [0.20-0.26], P < 0.001). Conversely, vaccination was not associated with a statistically significant increase in MG exacerbation (random-effects model: OR = 0.67, 95% CI [0.10-4.54], P = 0.68).\nCONCLUSIONS: This study provides quantitative evidence that COVID-19 vaccination effectively reduces infection risk without significantly increasing MG exacerbation. These findings support the safety and clinical utility of vaccination in MG patients, emphasizing the need for individualized risk-benefit assessment and ongoing pharmacovigilance in this population.\nSYSTEMATIC REVIEW REGISTRATION: https://www.crd.york.ac.uk/prospero/, identifier CRD420251078995.", "authors": ["Guan Chang", "Zhang Ruonan", "Zhao Peixi", "Zhang Ying", "Yu Lan", "Cui Huijing", "Jiang Li", "Wu Tong", "Liu Fang", "Wu Yang", "Huang Lin", "Nan Hongmei", "Wang Jian", "Xu Peng"], "journal": "Frontiers in immunology", "entry_date": "2026/02/27 04:59", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41756288/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["College of Traditional Chinese Medicine, Changchun University of Traditional Chinese Medicine, Changchun, Jilin, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41754015", "title": "Adverse Childhood Experiences and Psychological Health in Patients with Myasthenia Gravis: A Study Incorporating an Online Positive Mental Health Learning Program.", "abstract": "Background/Objectives: This study examined the prevalence of adverse childhood experiences (ACEs) among patients with myasthenia gravis (MG) and explored associations between ACE exposure and psychological outcomes. In addition, this study conducted a preliminary evaluation of an online \"Positive Mental Health BMI Learning Program\" and its association with changes in psychological well-being. Methods: A total of 77 patients with MG were included, with data collected between January 2024 and January 2025. Sociodemographic characteristics, ACE exposure, and psychological and disease-related indicators were assessed, including the Myasthenia Gravis Activities of Daily Living Scale (MG-ADL), the Myasthenia Gravis Quality of Life 15-item scale (MG-QOL15), the indicator of mental health BMI on well-being (mBMI), and the Patient Health Questionnaire-9 (PHQ-9). Using a single-group pre-post design, this exploratory pilot study examined associations between ACEs and psychological outcomes, along with pre-post changes among participants who completed the online program. Results: Among the 32 participants who completed the online program, mBMI scores showed an increase, primarily reflecting improvements in emotional stability (21.41 ± 4.70 to 23.03 ± 4.49, p < 0.01); however, in the absence of a control group, these changes cannot be attributed solely to the intervention. In contrast, no significant pre-post changes were observed in PHQ-9, MG-ADL, and MG-QOL15. Across the full sample, higher ACE exposure was associated with greater depressive symptom severity, as measured by the PHQ-9 (p < 0.05). Overall, 42.9% of participants reported at least one ACE, with emotional abuse being the most frequently endorsed, followed by parental separation or divorce and emotional neglect. Conclusions: ACE exposure was common among patients with MG and was associated with greater depressive symptoms. Participation in the online positive mental health BMI learning program was associated with improvements in positive psychological well-being.", "authors": ["Chang Ming-Hsing", "Chang Wen-Han", "Li Yu-Chan", "Yeh Jiann-Horng"], "journal": "Healthcare (Basel, Switzerland)", "entry_date": "2026/02/27 01:16", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41754015/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Shin Kong Wu Ho-Su Memorial Hospital, Taipei 111045, Taiwan."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "4区"}, {"pmid": "41747738", "title": "Single-cell profiling of immune reset in patients with refractory generalized myasthenia gravis receiving autologous CD19/BCMA CAR-T cell therapy.", "abstract": "BACKGROUND: Chimeric antigen receptor (CAR) T cells targeting CD19 or B cell maturation antigen (BCMA) hold great promise to treat neuroimmune disorders, but the efficacy of CD19/BCMA dual-targeting CAR-T cells and their impact on systemic immunity are poorly understood.\nMETHODS: In this phase 1 study (ClinicalTrials.gov: NCT06371040), patients with refractory generalized myasthenia gravis (gMG) received autologous CD19/BCMA CAR-T cells without prior lymphodepletion. The primary endpoint was the frequency and severity of treatment-emergent adverse events at week 4. Secondary endpoints included changes in MG-specific scale scores. Single-cell RNA sequencing and flow cytometry were performed to characterize longitudinal changes in B cell, plasma cell, and T cell compartments following CAR-T cell infusion.\nFINDINGS: CD19/BCMA CAR-T cells expanded in vivo, leading to depletion of B cells and plasma cells. All six patients had a favorable safety profile. Minimal symptom expression (MG Activities of Daily Living Score [MG-ADL] = 0) was achieved in five patients by day 90, with responses sustained through day 120-150, and all patients discontinued glucocorticoids while reducing immunosuppressant use. Immune profiling revealed a transient decline in memory B cells and plasma cells. The repopulated B cells exhibited attenuated B cell receptor signaling and increased inhibitory signals derived from bone marrow niche cells. Further, clonal expansion of T and B cells was significantly reduced.\nCONCLUSIONS: CD19/BCMA CAR-T cell therapy is safe and effective in refractory gMG without lymphodepletion, leading to systemic immune reset that warrants future investigations in larger clinical trials.\nFUNDING: This study was supported by the National Key Research and Development Program and the National Natural Science Foundation of China.", "authors": ["Ruan Zhe", "Ning Fan", "Zhang Wenyan", "Li Shuang", "Su Yue", "Tang Yonglan", "Cao Xiangqi", "Huang Xiaoxi", "Song Na", "Li Zhuyi", "Li Hang", "Luan Xiao", "Yang Naibo", "Li Ying", "Paul Friedemann", "Liu Qiang", "Chang Ting"], "journal": "Med (New York, N.Y.)", "entry_date": "2026/02/26 18:42", "pub_date": "2026-04-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41747738/", "pub_types": ["Journal Article", "Clinical Trial, Phase I"], "affiliations": ["Department of Neurology, Tangdu Hospital, The Fourth Military Medical University, Xi'an, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41744014", "title": "Current status and challenges of biologic targeted therapy for myasthenia gravis in China.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder posing substantial disease burden in China, with significant impacts on patient quality of life. While conventional immunosuppressants remain fundamental therapy, biologic targeted agents-including B-cell targeting drugs, complement C5 inhibitors, FcRn antagonists, and IL-6R inhibitors-have brought major advances, especially for refractory and MuSK-antibody-positive MG. Increasing availability in China has demonstrated promising clinical outcomes, yet substantial barriers remain. Challenges include high drug costs, limited insurance access, insufficient multicenter clinical evidence, and disparities in physician adoption. China's research is improving, exemplified by local innovation with telitacicept and active participation in global trials, though most biologics remain imported. To maximize benefits, clinical application should be guided by antibody subtype and immunopathology, with individualized, dynamic regimens balancing efficacy, safety, and affordability. High-quality randomized trials, updated guidelines, broader insurance coverage, and R&D investment are urgently needed to promote individualized and accessible MG care in China.", "authors": ["Gu Shengying", "Zhao Chongbo"], "journal": "Intractable & rare diseases research", "entry_date": "2026/02/26 04:47", "pub_date": "2026-02-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41744014/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology and Rare Disease Center, Huashan Hospital, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41743715", "title": "Case Report: Thymoma-associated myasthenia gravis, myositis, myocarditis, and anti-GAD65 autoimmune encephalitis: a unique case of paraneoplastic polyautoimmunity.", "abstract": "Neurological and autoimmune muscle comorbidities are rare in thymoma-associated myasthenia gravis (TAMG). The incidence of myositis is likely underestimated due to its clinical similarity. Few cases of autoimmune encephalitis (AE) have been reported in TAMG, most of which are associated with neuronal surface antibodies. We present the case of a 41-year-old woman with weakness and bulbar dysfunction, and elevated muscle and cardiac enzyme levels, who developed seizures and a decreased level of consciousness. Among the complementary tests, electromyography revealed a postsynaptic neuromuscular junction disorder. Muscle biopsy revealed inflammatory myopathy (IM), and cardiac magnetic resonance imaging (MRI) showed myocardial edema. Electroencephalography showed epileptiform activity, while brain MRI revealed bilateral T2/FLAIR hyperintensities in the medial temporal lobe. Neuroimmunological studies detected anti-acetylcholine receptor and anti-glutamic acid decarboxylase 65 (anti-GAD65) antibodies. Chest computed tomography (CT) revealed a mediastinal mass, which was later confirmed as a thymoma. The patient received corticosteroids, intravenous immunoglobulin, plasma exchanges, and rituximab. The simultaneous coexistence of myasthenia, myositis, myocarditis, and AE in a patient with thymoma has not been previously described in the medical literature. The presence of anti-GAD65 in this context is exceptional. In this case, early recognition and aggressive treatment led to a remarkable recovery. Clinicians should maintain a high index of suspicion for the coexistence of autoimmune disorders in patients with TAMG. IM may indicate a more serious disease, and myocarditis can be life-threatening. Neurological signs, such as memory loss, confusion, and seizures, may indicate the development of AE.", "authors": ["Leiva-Murillo Enmanuel A", "Martínez-Hernández Eugenia", "Aldecoa Iban", "Castro Pedro", "Richart Valeria", "Milisenda José C", "Matas-García Ana"], "journal": "Frontiers in immunology", "entry_date": "2026/02/26 04:43", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41743715/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Muscle Research Unit, Department of Internal Medicine, Hospital Clínic, University of Barcelona, Barcelona, Spain."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41741023", "title": "Safety and Effectiveness of Eculizumab in Patients With Refractory Ocular or Ocular-Predominant Myasthenia Gravis: A Case Series.", "abstract": "INTRODUCTION/AIMS: Despite conventional immunosuppressive therapy, approximately 5% of generalized myasthenia gravis (MG) patients experience residual ocular symptoms. We investigated the therapeutic effect of eculizumab, a C5 complement inhibitor, in five patients with refractory ocular myasthenia gravis (OMG) or ocular-predominant MG.\nMETHODS: Five patients with acetylcholine receptor antibody-positive (AChR-Ab) refractory ocular or ocular-predominant MG received eculizumab therapy (induction: 900 mg weekly ×4 weeks; maintenance: 1200 mg biweekly) with baseline immunosuppression. Each patient was followed up for 12 weeks. Clinical assessments included ocular Quantitative Myasthenia Gravis (ocular-QMG), Myasthenia Gravis Composite (MGC), and MG activities of daily living (MG-ADL). Serum AChR-Ab titers were measured before and after treatment.\nRESULTS: All patients experienced rapid symptom improvement within 1 week. After 4 weeks, ocular function normalized in three patients, with four patients achieving MGC ≤ 2 and MG-ADL ≤ 2. The ocular-QMG scores for individual items showed that both ptosis and diplopia improved in most patients. At 12 weeks, four patients maintained stable symptom control. No treatment-related adverse events or significant AChR-Ab+ titer changes were observed.\nDISCUSSION: In patients with refractory ocular or ocular-predominant MG, eculizumab had a rapid onset of therapeutic effect that was sustained after 12 weeks, regardless of the antibody titer. The favorable safety profile supports its use in treatment-resistant cases of refractory OMG or ocular-predominant MG. Larger randomized controlled trials are needed to establish the long-term effectiveness and optimize treatment protocols.", "authors": ["Shi Shiyu", "Zhang Yu", "Yang Wenping", "You Pan", "Cheng Xi", "Niu Qi"], "journal": "Muscle & nerve", "entry_date": "2026/02/25 20:53", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41741023/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Geriatric Neurology, The First Affiliated Hospital of Nanjing Medical University, Nanjing, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41740119", "title": "Immunotherapy Safety in Thymic Epithelial Tumors: Disproportionality Analysis of the Food and Drug Administration Adverse Event Reporting System.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) have revolutionized cancer treatment, but their safety profile in patients with thymic epithelial tumors (TETs) remains poorly characterized due to the rarity of these malignancies.\nOBJECTIVE: This study aims to comprehensively analyze immune-related adverse events (irAEs) profiles in patients with TETs using real-world pharmacovigilance data.\nMETHODS: We conducted a retrospective analysis of the US Food and Drug Administration Adverse Event Reporting System database from the first quarter of 2016 through the fourth quarter of 2024. Cases of TETs with ICI-related adverse events were identified and deduplicated following Food and Drug Administration recommendations. Disproportionality analysis was performed by calculating odds ratios, using the entire US Food and Drug Administration Adverse Event Reporting System database as the reference cohort. Signals were defined as significant with at least 3 cases and a lower 95% CI exceeded 1. Time-to-onset analysis and Weibull Shape Parameter testing were used to characterize the temporal pattern of irAEs. Clinical characteristics between fatal and nonfatal cases and cardiotoxicity specifics were analyzed descriptively.\nRESULTS: Among 152 eligible TET cases with irAEs, males slightly predominated (80/152, 52.6%), with a median age of 58.5 years. Reports originated predominantly from the United States (51/152, 33.6%) and Japan (16/152, 10.5%). PD-1 inhibitors were implicated in 66.4% (101/152) of cases. Disproportionality analysis identified 14 significant irAE signals across 11 System Organ Classes. Myositis (reporting odds ratio [ROR] 113.15, 95% CI 26.65-480.34), myocarditis (ROR 10.96, 95% CI 5.70-21.07), myasthenia gravis (ROR 3.86, 95% CI 1.86-7.85), and febrile neutropenia (ROR 18.33, 95% CI 4.57-73.55) demonstrated the strongest associations. The median time to irAEs onset was 21.0 days, with 73.2% (41/56) occurring within 2 months of treatment initiation. Fatal outcomes were reported in 23.7% (36/152) of cases and were significantly associated with gender distribution (P=.04) and different treatment strategies (P=.01). The utilization of PD-1 inhibitors was higher in the fatal group (29/36, 80.06%) than in the nonfatal group (72/116, 62.1%). Myocarditis was the most frequent cardiotoxicity, accounting for 51.3% (20/39) of cardiac events.\nCONCLUSIONS: This large-scale pharmacovigilance study delineates a distinct and severe irAEs profile for ICIs in patients with TETs, characterized by robust disproportionality signals for myositis, cardiotoxicity, and myasthenia gravis. As a hypothesis-generating analysis, these findings underscore the need for vigilant monitoring and early detection strategies to mitigate irAE risks, particularly in high-risk subgroups such as patients with thymoma. The results provide clinically relevant evidence to guide risk-benefit evaluation and inform tailored surveillance protocols during ICI therapy in this population.", "authors": ["Chen Ruilian", "Chen Hanrui", "Sun Lingling", "Cao Yang", "Lin Lizhu"], "journal": "JMIR cancer", "entry_date": "2026/02/25 16:23", "pub_date": "2026-02-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41740119/", "pub_types": ["Journal Article"], "affiliations": ["Oncology Center, The First Affiliated Hospital of Guangzhou University of Chinese Medicine, 16 Jichang Road, Baiyun District, Guangzhou, 510405, China, 86 020-36596360."], "china_related": true, "study_types": ["Non-randomized controlled cohort"], "evidence_level": "III", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41737895", "title": "A comprehensive electrooculography measurement system and protocols for screening myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is a neuromuscular disorder that can precipitate serious and fatal complications, especially when respiratory muscles are affected. Current electrodiagnostic methods, such as Single Fiber Electromyography (SFEMG) and Repetitive Nerve Stimulation (RNS), have notable limitations. While SFEMG is sensitive to neuromuscular abnormalities rather than being specific for MG, it is also a semi-invasive procedure that requires supervision by specialist clinicians and an expensive clinical setup. Conversely, RNS is highly specific for MG, but its sensitivity decreases in cases of low severity. Prior studies, including our previous work, have demonstrated that the manifestation of MG in affecting eye movements can be indirectly quantified using electrooculography (EOG) signals. This non-invasive method could develop into a widely used and easily deployed screening method, especially for early detection of MG using readily obtainable biomarkers. With this goal in mind, our research team developed data collection protocols using a standardized eye movement protocol that could be implemented in a standard clinical setting to acquire EOG data. In this article, we present the experimental setup, test protocols, sample outcomes, and preliminary analysis approaches. Common artifacts encountered, as well as technical and logistical challenges associated with such a setup, are also discussed.1.An approach to non-invasively detect and quantify MG using eye movement signals.2.Data collection protocols for acquiring eye movement signals designed for MG quantification3.Novel eye movement-based biomarkers in quantifying MG.", "authors": ["Le Tien Loc", "Boulos Mark I", "Yang Donna", "Berger Sarah", "Irannejad Mona", "Figueroa César Morales", "Thorpe Kevin E", "Murray Brian", "Krishnan Sridhar", "Sundaram Arun N E", "Katzberg Hans", "Umapathy Karthikeyan"], "journal": "MethodsX", "entry_date": "2026/02/25 04:55", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41737895/", "pub_types": ["Journal Article"], "affiliations": ["Toronto Metropolitan University, Toronto, Ontario, Canada."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41737228", "title": "Telitacicept for refractory AChR-positive generalized myasthenia gravis: a retrospective real-world study.", "abstract": "BACKGROUND AND AIMS: Treating refractory acetylcholine receptor-positive generalized myasthenia gravis (AChR+ gMG) remains challenging, especially for patients requiring long-term immunosuppressive therapy. Current treatments often lack specificity and pose significant long-term risks, underscoring the need for alternatives. Telitacicept, a novel dual inhibitor of B lymphocyte stimulator (BLyS) and proliferation-inducing ligand (APRIL), offers a promising targeted therapeutic approach. This study aimed to evaluate the efficacy and safety of telitacicept in the treatment of refractory AChR+ generalized myasthenia gravis.\nMETHODS: This retrospective study included 42 patients with refractory AChR+ gMG who received telitacicept. The primary outcomes assessed were changes from baseline in Quantitative Myasthenia Gravis (QMG) scores, analyzed using mixed-effects models. Secondary outcomes comprised cumulative response rates, reductions in concomitant immunosuppressive medications, and safety events.\nRESULTS: A total of 42 refractory MG patients with MGFA class II-IV were enrolled. Significant improvements were observed in the QMG total score (least-squares [LS] mean change at month 5: -2.24, 95% CI -3.34 to -1.15, p<0.001), with sustained benefits across ocular, limb, and bulbar areas. Cumulative response rates reached 69.9% for MGFA-PIS and 73.8% for QMG improvement (≥3-point reduction) by 6 months. Notable decreases in prednisone (LS mean -10.17 mg/day, p<0.001) and immunosuppressant use were also seen. The therapy demonstrated a promising safety profile.\nCONCLUSIONS: Telitacicept demonstrated significant efficacy in refractory AChR+ gMG and may reduce dependence on traditional immunosuppressants. These real-world findings support its use as a valuable treatment choice for this challenging patient group.", "authors": ["Rong Xi", "Sun Xupeng", "Wang Li", "Qu Meijie", "Jiang Liwei", "Liu Min"], "journal": "Frontiers in immunology", "entry_date": "2026/02/25 04:48", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41737228/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Qingdao University, Qingdao, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41737168", "title": "Outcomes of preoperative medical consultations for elective non cardiac surgical procedures at tertiary care center.", "abstract": "OBJECTIVE: To evaluate the outcome of medical consultations requested at the time of pre-operative anaesthesia assessment.\nMETHODOLOGY: After taking exemption from ethical review committee, this descriptive cross-sectional study was conducted for one year at our tertiary care center. All adult patients scheduled for elective surgeries required consultation from anaesthesia physicians were included. Relevant clinical data was recorded prospectively on predesigned Performa. Outcomes were categorized as risk stratification, optimizing medical management or postponement of surgical procedure.\nRESULTS: Among 264 patients (mean age 59.9 years, predominantly male, ASA III), hypertension, diabetes, and IHD were the common comorbid conditions. About 47% of these consultations were requested for intermediate risk procedures, while cardiology opinion was requested in (63%) of cases. Based on these consultations, 87.5% of patients received risk prediction, medical management was advised in 64% and in only 7.2% of patients the planned surgeries were postponed. Comparison between variables showed Myasthenia Gravis (50%), Pulmonary embolism (33%) and IHD (30%) were the common reasons of falling into high-risk group. Most patients with Asthma (69%), IHD (68%) and Hypothyroidism (52%) required medical intervention preoperatively (p = 0.496). IHD was mainly responsible for the reason of delaying surgery (13.6%). Similarly, 69% of cardiac consultations ended up with case postponement, and 53.5% of patients were advised with medical management (p = 0.001).\nCONCLUSION: The substantial disease burden and proposed risk stratification including recommendations regarding medical optimization justified the need of preoperative consultations in our patient populations. However, their impact on improving postoperative outcomes requires further evaluation.", "authors": ["Tariq Fahad", "Shafiq Faraz"], "journal": "Pakistan journal of medical sciences", "entry_date": "2026/02/25 04:48", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41737168/", "pub_types": ["Journal Article"], "affiliations": ["Fahad Tariq Senior Registrar, Department of Anesthesiology, Tabba Heart Institute, Karachi, Pakistan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "41732618", "title": "Simultaneous Diagnosis of Myasthenia Gravis and Neurosyphilis, With Symptoms Improving After Neurosyphilis Treatment: A Case Report.", "abstract": "Simultaneous diagnosis of myasthenia gravis (MG) and early asymptomatic neurosyphilis is extremely rare. There have only been two cases described in the literature. To the best of our knowledge, this was the first case of MG resolving with concurrent treatment of neurosyphilis. Our patient was a 67-year-old male who presented to the hospital with a diffuse rash, bilateral ptosis, bilateral facial weakness, and bulbar symptoms (dysarthria, difficulty with mastication, and difficulty drinking fluids).  After testing positive for syphilis in serum and cerebrospinal fluid (CSF), the patient was diagnosed with neurosyphilis. Thus, it was suspected that his neurological findings were manifestations of early symptomatic neurosyphilis. The patient was treated with intravenous penicillin G for one week, and later, it was switched to intravenous ceftriaxone for two weeks due to cost and convenience. All symptoms resolved after three to four weeks. After being discharged, the patient tested positive for acetylcholine receptor antibodies. Subsequently, the patient underwent an electromyogram (EMG), which revealed a decremental response, confirming a diagnosis of MG. Infections are known to trigger autoimmune diseases and can lead to the development of new-onset MG. Neurosyphilis is relatively highly associated with other central nervous system (CNS) antibodies and can trigger other neurological disorders. Recognizing the differences in presentation and performing an accurate and comprehensive neurological exam can help differentiate early symptomatic neurosyphilis from neuromuscular disorders such as MG.", "authors": ["Ortiz Juan Fernando", "Lannen Nicholas J", "Peralta Maria Daniela", "Lopez Camila D"], "journal": "Cureus", "entry_date": "2026/02/24 04:18", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41732618/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Corewell Health Medical Group, Grand Rapids, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41730437", "title": "High expression of IRF8 in AChR-specific cells regulates the function of B cells.", "abstract": "Myasthenia gravis (MG) is a kind of autoimmune disease. Interferon regulatory factor 8 (IRF8) is an interferon common sequence-binding protein. IRF8 is a key factor involved in the development, maturation, and antimicrobial activity of myeloid cells. Second-generation sequencing of splenocytes at the peak period of disease in experimental autoimmune MG (EAMG) rats and complete Freund's adjuvant (CFA)-treated mice suggested that the expression of IRF8 gene is related to the pathogenesis of EAMG. This study focused on the differential expression of IRF8 in B cell and T cell in EAMG, and the underlying mechanism of the role of IRF8 in the pathogenesis of the disease. We analyzed the gene expression profiles of splenocytes from CFA-treated and EAMG mice. We measured the serum anti-acetylcholine receptor autoantibody titer, IRF8 mRNA and protein level in splenocytes, IRF8 mRNA and protein expression in T and B cells as well as in LPS-stimulated splenocytes, and colocalization of CD45R and IRF8 proteins using confocal microscopy. Finally, we determined the titers of anti-acetylcholine receptor autoantibodies in the supernatants of LPS-stimulated cells. Our findings revealed that the expression of IRF8 in splenocytes increased during the peak period of EAMG, B cells exhibited high IRF8 expression, and that IRF8 expression in B cells was positively correlated with antibody secretion. Taken together, our findings indicate that IRF8 is a potential biomarker for EAMG diagnosis.", "authors": ["Zhao Wei", "Yan Geng", "Wei Bo", "Zhang Yihe", "Yao Xiuhua", "Wang Zhenhai", "Wang Guangyou", "Hou Lixuan", "Zhong Lihua", "Wang Jinghua", "Mu Lili"], "journal": "Immunology letters", "entry_date": "2026/02/23 19:25", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41730437/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurobiology, School of Basic Medical Sciences, Harbin Medical University, Harbin, China; Key Laboratory of Nerve Injury and Immunity of Heilongjiang Province, Harbin Medical University, Harbin, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41729403", "title": "Are you weary of illness? Coping and existential positioning in life with myasthenia gravis.", "abstract": "This article explores what it means to position oneself existentially in relation to illness weariness in myasthenia gravis. Grounded in phenomenology and informed by autoethnographic principles, the study examines how the body's changing disposition shapes lived meaning and coping in chronic illness. Phenomenological vignettes serve as experiential entry points, followed by reflective interpretation inspired by Havi Carel, Maurice Merleau-Ponty, Drew Leder, and Kay Toombs. Two experiential themes emerge. First, When the body doesn't always follow one's lead anymore shows how myasthenia gravis disrupts habitual rhythm and bodily trust. Bodily hesitation and the oscillation between resistance and responsiveness give rise to illness weariness-an existential modality distinct from physical fatigue or mood. Within this terrain, uncompromisingness appears as a quiet, existential stance; a refusal to let illness fully determine the direction of one's life, expressed through a persistent insistence on participation and dignity. Second, Physical activity and relational support as existential coping practices demonstrates how movement and relationship sustain existential positioning. Physical activity becomes an existential practice through which hope, orientation, and embodied rhythm are maintained, not by erasing illness weariness but by placing it alongside an uncompromising insistence on participation. At the same time, relational support, here exemplified by an attuned neurologist, serves as a subtle relational nudge that grounds and strengthens the will to continue. The study conceptualizes illness weariness and uncompromisingness as a continuum of existential responses shaped by bodily fluctuation and relational context. These insights extend beyond myasthenia gravis and point to the importance of existential attentiveness and relational continuity in clinical care.", "authors": ["Missel Malene", "Witting Nanna", "Beck Malene"], "journal": "Medicine, health care, and philosophy", "entry_date": "2026/02/23 11:19", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41729403/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cardiothoracic surgery, Copenhagen University Hospital-Rigshospitalet, Blegdamsvej 9, Copenhagen, 2100, Denmark. malene.missel@regionh.dk."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "1区"}, {"pmid": "41728453", "title": "Real-World Outcomes of Efgartigimod in Adult Myasthenia Gravis.", "abstract": "Efgartigimod (Vyvgart) is used in the management of myasthenia gravis (MG), but real-world data outside controlled trials, particularly regarding flexible dosing intervals and concomitant medication use, remain limited. The objective of this preliminary, single-center, hypothesis-generating case series was to evaluate the clinical effectiveness of efgartigimod, characterize variability in treatment-free dosing intervals, and explore associations between dosing intervals and concomitant immunosuppressive medication use among adult patients with MG in routine clinical practice. This was a retrospective chart review of MG patients at a single academic neuromuscular center who were directly evaluated by the principal investigator. Demographics, treatment dates, dosing intervals, concomitant medications, and myasthenia gravis activities of daily living (MG-ADL) scores were collected. Fixed- and mixed-effects models were used to examine associations between efgartigimod use and changes in prednisone or other immunosuppressant dosing. Nine patients were included (mean age 64 ± 18.1 years, 55.6% male). The average time between cycles was 47 days (SD = 46.5, CI = 34.98-59.01), with wide variability across patients. The average baseline MG-ADL was 8.56 and decreased by 4.44 at 60 days (SD = 3.43), 4.71 at six months (SD = 3.64), and 5.29 at 12 months (SD = 5.06). Reductions were statistically significant at all time points (p = 0.008, 0.016, and 0.031, respectively). Baseline dosing of prednisone, pyridostigmine, and mycophenolate mofetil did not systematically affect cycle length, but higher azathioprine doses were consistently associated with longer subsequent infusion intervals. Given the small sample size and single-center design, these findings should be interpreted as preliminary observations and hypothesis-generating rather than definitive conclusions. Efgartigimod was associated with significant improvements in MG-ADLs in this cohort, supporting its effectiveness under flexible, patient-centered dosing schedules. Findings suggest that concomitant azathioprine dosing may be linked to longer infusion intervals, potentially reflecting more stable disease or clinician comfort with extended cycles, although this requires further investigation. Larger, prospective studies are needed to define optimal scheduling strategies, long-term durability, and the potential for reducing polypharmacy.", "authors": ["Krall Tyler", "Byrne Samuel", "Kelbert James", "Chrisman Christina"], "journal": "Cureus", "entry_date": "2026/02/23 06:45", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41728453/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, University of Arizona College of Medicine - Phoenix, Phoenix, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41726319", "title": "Differential response to ofatumumab in anti-AChR and anti-MuSK positive myasthenia gravis patients: a single-center retrospective study.", "abstract": "BACKGROUND: Ofatumumab (OFA), a humanized anti-CD20 monoclonal antibody, shows potential in myasthenia gravis (MG) with antibody against acetylcholine receptor (AChR-Ab), but comparative efficacy across AChR and muscle-specific kinase (MuSK) subtypes remains uncharacterized.\nOBJECTIVES: To evaluate OFA's clinical and immunological effects in AChR-MG versus MuSK-MG, identify predictors of minimal symptom expression (MSE), and explore the dynamics of B-cell repopulation.\nDESIGN: A retrospective study in a single center.\nMETHODS: Twenty-one refractory MG patients (13 MuSK+, 8 AChR+) received individualized OFA induction (Regimen 1: two 20 mg doses ⩾2 weeks apart; Regimen 2: single 20 mg dose) and maintenance (20 mg upon CD19 + B counts ⩾5 cells/μL repopulation or clinical exacerbation). Outcomes included time-to-MSE, Quantitative Myasthenia Gravis Score (QMGS) dynamics, prednisone reduction, and serial immunophenotyping (B-cell activating factor (BAFF), a proliferation-inducing ligand (APRIL), soluble CD40L (sCD40L), microphage migration inhibitory factor (MIF), and immunoglobulin).\nRESULTS: MuSK-MG achieved faster MSE (median time: 6 vs 15 months, log-rank p = 0.164, age-adjusted Cox p = 0.027), and a higher 3-month improvement (92.3% vs 50.0%; p = 0.047). Earlier achievement of MSE was associated with shorter disease duration (p = 0.038) and concomitant corticosteroid therapy (p = 0.030). Prednisone doses decreased significantly over 6 months (p = 0.029) without difference between groups (p = 0.109). MuSK-MG showed synchronized BAFF/APRIL declines while AChR-MG presents transient BAFF elevation and sustained APRIL. BAFF levels showed a significant positive correlation with QMGS in MuSK-MG, while IgM/IgG positively correlated with QMGS in both subtypes. Median B cell-repopulation time was 47.7 days.\nCONCLUSION: OFA demonstrates superior efficacy in MuSK-MG with distinct immunological modulation. AChR-MG requires combinatorial strategies targeting compensatory pathways.", "authors": ["Zhou Qian", "Ouyang Yuzhen", "Jiang Fei", "Zeng Qiuming", "He Ting", "Wen Zeyi", "Shi Guanzhong", "Dong Xiaohua", "Cai Haobing", "Xiang Wei", "Su Miao", "Li Kailin", "Yang Huan"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/02/23 06:23", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41726319/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, Hunan, P.R. China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41723080", "title": "Immune Dysregulation: Navigating Autoimmune Disorders in Exotic Companion Animals.", "abstract": "Immune-mediated diseases in companion exotic small mammals and birds are recognized but remain poorly defined because of limited case reports and lack of species-specific diagnostic tools. Disorders arising from loss of immune tolerance encompass hypersensitivity reactions, autoimmunity, and immunodeficiencies. The primary focus of this article will be on autoimmune diseases and their documentation in the exotic pet literature. Selected diseases reviewed include idiopathic pulmonary fibrosis, bornavirus associated neuropathy, immune-mediated hemolytic anemia, myasthenia gravis, disseminated idiopathic myofasciitis, sebaceous adenitis, and ulcerative dermatitis. Immunosuppressive therapy and their use in exotic species will also be discussed.", "authors": ["Thielen Lauren"], "journal": "The veterinary clinics of North America. Exotic animal practice", "entry_date": "2026/02/21 21:58", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41723080/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Clinical Sciences, Cornell University College of Veterinary Medicine, 930 Campus Road, Box 31, Ithaca, NY 14853, USA. Electronic address: Lt397@cornell.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.5, "journal_quartile": "3区"}, {"pmid": "41722595", "title": "Current evidence and knowledge gaps in family planning and pregnancy in myasthenia gravis, NMOSD, and MOGAD.", "abstract": "Myasthenia gravis, neuromyelitis optica spectrum disorder (NMOSD), and myelin oligodendrocyte glycoprotein antibody-associated disease (MOGAD) are antibody-mediated neuroimmune disorders that frequently affect women in their reproductive years and require careful treatment planning around pregnancy. Disease exacerbations (for myasthenia gravis) and attacks (for NMOSD and MOGAD) can occur during pregnancy, are common postpartum, and can cause preventable, long-term maternal disability. Many drug labels are conservative or recommend unnecessary prolonged washouts or avoidance of breastfeeding, creating uncertainty for physicians and patients. This Personal View integrates available evidence on conventional immunosuppressants and biological therapies, including complement inhibition, B-cell depletion, and neonatal Fc receptor blockade. Although data on pregnancy safety for newer treatments are few, preliminary data suggest that selected therapies could be continued during pregnancy to maintain disease stability and are compatible with breastfeeding. We offer expert recommendations for therapy choice, infant vaccinations, and fetal and infant monitoring in myasthenia gravis, NMOSD, and MOGAD.", "authors": ["Rotstein Dalia L", "Alroughani Raed", "Arrambide Georgina", "Carnero Contentti Edgar", "Chomba Mashina", "Fujihara Kazuo", "Gilhus Nils E", "Gouider Riadh", "Heckmann Jeannine M", "Kim Ho Jin", "Li Hai-Feng", "Leite Maria Isabel", "Monif Mastura", "Siritho Sasitorn", "Thiel Sandra", "Vishnevetsky Anastasia", "Viswanathan Shanthi", "Vukusic Sandra", "Yamout Bassem", "Kümpfel Tania", "Hellwig Kerstin"], "journal": "The Lancet. Neurology", "entry_date": "2026/02/21 18:52", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41722595/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medicine, University of Toronto, Toronto, ON, Canada; St Michael's Hospital, Toronto, ON, Canada."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 45.5, "journal_quartile": "1区"}, {"pmid": "41722445", "title": "[A drooping gaze, a cold clue: Late-onset presentation of myasthenia gravis].", "abstract": "", "authors": ["Morales Mena Gabriela Ivonne", "Adán-Gurpegui Alicia", "Lacruz Ballester Laura", "Condorhuamán-Alvarado Patricia Ysabel"], "journal": "Revista espanola de geriatria y gerontologia", "entry_date": "2026/02/21 18:08", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41722445/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Servicio de Geriatría, Hospital Universitario La Paz, Madrid, España. Electronic address: gabymor.14@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41721962", "title": "Patient Perceptions of Needs and Expectations Regarding the Current Management of Myasthenia Gravis: A Biopsychosocial Study.", "abstract": "INTRODUCTION: Information on the biopsychosocial needs and healthcare experiences of people living with myasthenia gravis (PwMG) in Spain remains limited. This study aimed to describe self-reported experiences and provide an overview of the condition's physical, psychological, and social impact.\nMETHODS: A multicenter cross-sectional epidemiological study was conducted through a nationwide online survey completed by a geographically stratified sample of PwMG across 13 of Spain's 17 Autonomous Communities.\nRESULTS: A total of 208 valid responses were analyzed (mean age 58.8; SD 15.2 years; range 16-94; 55.8% men). Nearly half (49.5%) reported generalized myasthenia gravis (MG), and 36.4% held a disability certificate. Although most respondents perceived their health as good or very good (45.2%), pain or discomfort affected 51.5%, and half reported emotional symptoms such as anxiety or depression. The mean EQ-VAS score was 66.1 (SD 20.6), reflecting a reduced health-related quality of life (HRQoL) compared with the general population. While satisfaction with access to and quality of medical care was generally high, many patients expressed concerns about limited psychological support and insufficient social care for themselves and their caregivers.\nCONCLUSION: PwMG in Spain generally perceive their health positively, but significant unmet needs persist in psychological care and social protection. These findings underscore the importance of comprehensive patient-centered strategies that integrate medical, emotional, and social support to improve quality of life in MG.", "authors": ["Campos-Lucas Francisco Javier", "Cortés-Vicente Elena", "Guerrero-Sola Antonio", "Álvarez-Velasco Rodrigo", "Pardo-Gómez Raquel", "Gómez-Salgado Juan", "Antón-Rodríguez Cristina", "Caballero-Martínez Fernando"], "journal": "Neurology and therapy", "entry_date": "2026/02/21 11:16", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41721962/", "pub_types": ["Journal Article"], "affiliations": ["Postgraduate Studies and Institutional Relations, Faculty of Medicine, Universidad Francisco de Vitoria., Carretera 515 Pozuelo-Majadahonda Km. 1,800, 28223, Pozuelo de Alarcón, Madrid, Spain. f.campos@ufv.es."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41721543", "title": "Myasthenia Gravis With Acetylcholine Receptor Antibodies in the Very Old: Treatment Challenges and Diagnostic Pitfalls.", "abstract": "BACKGROUND: In myasthenia gravis (MG) with acetylcholine receptor (AChR) antibodies, epidemiology, disease mechanisms, diagnosis, and treatment depend on age. MG with debut after 65 years has an increasing incidence and prevalence but is underrepresented in clinical studies.\nMETHODS: This is a systematic review of very late onset MG and MG in patients above 65 years with focus on epidemiology, pathogenesis, diagnosis, clinical characteristics, and treatment.\nRESULTS: Both innate and adaptive immune responses are influenced by age. The increase in MG incidence in the very old is probably caused by unknown environmental factors. Both patients' and doctors' diagnostic delays are substantial for very late onset MG. Comorbidities are frequent and can lead to misdiagnosis. MG needs to be considered as a potential diagnosis in all elderly patients with newly localized or generalized muscle weakness. AChR antibodies have near 100% diagnostic specificity and 80% sensitivity in this age group. Very late onset MG is often mild and with an excellent response to pyridostigmine and first-line immunosuppressive therapy. One in five has a debut with life-threatening respiratory insufficiency. Rituximab, complement inhibitors, and FcRn blockers can be used on the same indications as for younger MG patients. MG in the very old is a fluctuating disease with the need of frequent adjustments of drug therapy.\nCONCLUSIONS: Very late onset MG and MG in the very old should be treated actively with symptomatic and immunosuppressive drugs, physical activity programs, and general support. The treatment aim should be pharmacological remission or minimal manifestations only.", "authors": ["Gilhus Nils Erik"], "journal": "European journal of neurology", "entry_date": "2026/02/21 03:52", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41721543/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Haukeland University Hospital, Bergen, Norway."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41720335", "title": "Combined adapted physical activity and art-therapy intervention in myasthenia gravis: Study protocol for a randomized crossover pilot trial.", "abstract": "BACKGROUND: Myasthenia Gravis (MG) is a rare autoimmune disorder with fluctuating weakness and substantial impact on quality of life (QoL). Despite advances in pharmacological treatment, patients often experience fatigue, anxiety, and reduced daily functioning. Adapted Physical Activity (APA) has shown benefits in chronic neuromuscular disorders, while Art Therapy (AT) has demonstrated positive psychosocial effects in neurological conditions. However, no studies have investigated the potential synergy of APA combined with AT in MG.\nMETHODS: We designed a monocentric, prospective, randomized crossover pilot trial to evaluate the feasibility and preliminary efficacy of an integrated APA + AT program compared to APA alone. A total of 102 adult patients with MG will be recruited from Lille University Hospital and partner centers. Each participant will undergo two 6-week phases (APA only vs APA + AT), separated by a 46-week washout. Primary outcome is change in QoL (MG-QOL15) at 3 months. Secondary outcomes include fatigue (FSS), anxiety and depression (HADS), activities of daily living (MG-ADL), physical function tests, physical activity (IPAQ, accelerometry), and psychosocial outcomes assessed through qualitative methods (interviews, ethnography, creative elicitation). Quantitative data will be analyzed with repeated-measures models; qualitative data will undergo thematic analysis.\nDISCUSSION: This trial will be the first to explore a combined APA + AT intervention in MG. By addressing both physical and psychosocial dimensions, the study may provide evidence for integrated, patient-centered care strategies in rare neuromuscular disorders. If feasible and effective, results could inform future multicenter trials and clinical practice.\nTRIAL REGISTRATION: ClinicalTrials.gov Identifier: NCT07125105.", "authors": ["Leclercq Célia", "Archer Annie", "Ceccone Fanny", "Davion Jean-Baptiste", "Devanne Hervé", "Tard Céline", "Porrovecchio Alessandro"], "journal": "Contemporary clinical trials", "entry_date": "2026/02/20 19:28", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41720335/", "pub_types": ["Journal Article"], "affiliations": ["Univ. Littoral Côte d'Opale, Univ. Lille, Univ. Artois - ULR 7369 - URePSSS - Unité de Recherche Pluridisciplinaire Sport Santé Société, 62100 Calais, France."], "china_related": false, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41719501", "title": "Low Prevalence and Inconsistency of LRP4-IgG Detection in Suspected Myasthenia Gravis: A Multicenter CBA Comparison.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis (MG) is an autoimmune disorder primarily caused by antibodies targeting neuromuscular junction proteins, particularly the acetylcholine receptor and the muscle-specific tyrosine kinase. However, 10%-20% of patients with MG are double-seronegative (dsMG). Antibodies against low-density lipoprotein receptor-related protein 4 (LRP4-IgG) have been found in a variable proportion of dsMG cases, but their frequency and clinical relevance remain unclear because of differences in assay methodologies and study populations. In this study, we assessed the frequency of LRP4-IgG in patients with suspected MG using different cell-based assay (CBA) protocols.\nMETHODS: In this multicenter observational study, we enrolled consecutive patients presenting with symptoms suggestive of MG. LRP4-IgG was tested by 2 centers using 3 different CBAs: live (l-CBA), methanol-fixed (mf-CBA), and paraformaldehyde-fixed (pf-CBA). Patients were classified as having MG or other disorders (ODs). Positive samples were cross-tested between centers.\nRESULTS: Among 684 patients (302 with MG, 382 with ODs), LRP4-IgG was detected by mf-CBA in 2% (6/302) of MG cases and in 0.52% (2/382) of OD cases. Among patients with MG, 3.9% (4/102) of dsMG and 1% (2/200) of seropositive patients tested positive. Only 50% of mf-CBA-positive cases were confirmed by pf-CBA, and none were detected by l-CBA. Cross-center testing showed partial reproducibility.\nDISCUSSION: LRP4-IgG detection in suspected MG is rare and inconsistent across assays, suggesting that routine testing is not currently warranted and that these antibodies are at present of limited diagnostic value. These findings highlight the need for standardized, validated LRP4-IgG assays. Future studies should focus on direct comparison and harmonization of testing protocols to clarify the clinical utility of LRP4-IgG testing.", "authors": ["Gligora Ilaria", "Businaro Pietro", "Serra Lucrezia", "De Pasqua Silvia", "Ricciardiello Fortuna", "Morelli Luana", "Morandi Chiara", "Masciocchi Stefano", "Malvaso Antonio", "Ballestracci Corrado", "Di Stasi Vitantonio", "Vacchiano Veria", "Fetta Anna", "Rossi Simone", "Kaveh Moghadam Keivan", "Rizzo Giovanni", "Milano Domenica Chiara", "Zini Andrea", "Cordelli Duccio Maria", "Rinaldi Rita", "Donadio Vincenzo", "Liguori Rocco", "Gastaldi Matteo", "Giannoccaro Maria Pia"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2026/02/20 16:03", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41719501/", "pub_types": ["Journal Article"], "affiliations": ["Dipartimento di Scienze Biomediche e Neuromotorie, Università di Bologna, Italy."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41718841", "title": "Nationwide trends in mediastinal tumor and myasthenia gravis surgery in Japan: a decade claims-based analysis (2014-2023).", "abstract": "BACKGROUND: Mediastinal tumor surgery and extended thymectomy for myasthenia gravis (MG) have undergone significant changes with the advancement of minimally invasive techniques. However, nationwide population-based data capturing these trends in Japan remain limited. This study aimed to characterize national surgical trends for mediastinal tumors and MG using a comprehensive administrative claims database.\nMETHODS: We analyzed data extracted from the National Database of Health Insurance Claims and Specific Health Checkups (NDB), covering over 95% of insured procedures in Japan. We classified surgeries from 2014 to 2023 by disease category (benign tumor/malignant tumor/MG) and approach (open/thoracoscopic/robotic-assisted). Crude and age-standardized surgery rates were calculated per 100,000 person-years. Temporal trends were assessed using linear and Poisson regression models.\nRESULTS: In 2023, a total of 6214 surgeries was performed: 54.4% for benign tumors, 41.6% for malignant tumors, and 4.0% for MG. Thoracoscopic approaches accounted for 76.4% of all procedures (29.4% robotic-assisted), while open surgery comprised 23.6%. Over the decade, age-standardized overall mediastinal tumor surgeries increased significantly (P = 0.0001), driven by marked rises in malignant, thoracoscopic, and robotic-assisted surgeries (each P < 0.0001). In contrast, extended thymectomies and open surgeries declined (P = 0.0019, and < 0.0001, respectively). Age-standardized malignant tumor surgery rates rose in both sexes (relative risk = 1.051 for males, 1.065 for females, and 1.058 overall; P < 0.0001), especially among those aged ≥ 40 years in both sexes (P < 0.0024).\nCONCLUSION: This nationwide study reveals growing surgical demand for mediastinal tumors and underscores the widespread adoption of minimally invasive techniques.", "authors": ["Kido Masamitsu", "Okada Satoru", "Furuya Tatsuo", "Ishihara Shunta", "Uchibori Atsuki", "Kameyama Kenji", "Kakibuchi Daichi", "Tsujikawa Takahiro", "Yoshii Kengo", "Shoda Katsutoshi", "Ishii Ryotaro", "Matsui Naoko", "Kido Tetsuo", "Inoue Masayoshi"], "journal": "International journal of clinical oncology", "entry_date": "2026/02/20 11:15", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41718841/", "pub_types": ["Journal Article"], "affiliations": ["Department of Orthopedic Surgery, Inage Hospital, 6-21-3 Konakadai, Inage-ku, Chiba, 2630043, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41717074", "title": "Outcomes following single-level lumbar fusion in patients with myasthenia gravis.", "abstract": "INTRODUCTION: Patients with myasthenia gravis (MG) are at higher risk for postoperative complications after surgery. Knowledge concerning the impact of the condition on outcomes and complications after spine surgery is currently limited. Using a large-scale, national database, the purpose of this investigation was to compare the rate of medical and surgical complications, healthcare utilization, and need for revision surgery following single-level lumbar fusion between patients with and without MG.\nMETHODS: Data was collected using the PearlDiver database and adult patients with and without MG who underwent single-level lumbar spine fusion from 2010 to 2022 were matched 1:4 on age, sex, and baselin comorbidities. Pearson's Chi-squared test and Welch's t-test were used to evaluate differences in demographic and clinical outcomes. Univariate analysis and multivariate logistic regression were performed to calculate odds ratios (ORs) and 95% confidence intervals (CIs) after controlling for potential confounders.\nRESULTS: A total of 537 (20.0%) patients with MG were matched with 2140 (80.0%) patients controls. At 90 days postoperatively, patients with MG experienced significantly higher rates of postoperative arrhythmia, cerebrovascular accident, atelectasis, respiratory failure, pleural effusion, pulmonary embolism, urinary retention, urinary tract infection, and renal failure. At two-year follow up, 27 (5.0%) patients with MG developed pseudoarthrosis compared to 48 (2.2%) controls (OR 2.32; 95% CI: 1.41-3.74; p < 0.001), and 38 (7.1%) MG patients had undergone revision lumbar spine surgery compared to 61 (2.9%) controls (OR: 2.61; 95% CI: 1.70-3.95; p < 0.001). Regarding healthcare utilization, patients with MG were more likely to present to the emergency department and require readmission at both 30 and 90 days postoperatively.\nCONCLUSION: Patients with MG experienced more postoperative complications and higher healthcare utilization after single-level lumbar fusion. These findings highlight the importance of individualized perioperative planning to mitigate risks and inform surgeon counseling of patients and their families.", "authors": ["Heckert Danielle B", "Jezykowski Julia", "Green Clare K", "Wang Joyce En-Hua", "Vengsarkar Ved A", "Novicoff Wendy", "Li Xudong", "Lockey Stephen"], "journal": "Journal of orthopaedics", "entry_date": "2026/02/20 04:54", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41717074/", "pub_types": ["Journal Article"], "affiliations": ["University of Virginia School of Medicine, Charlottesville, VA, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "41716022", "title": "The role and mechanism of IL‑35 in myasthenia gravis (Review).", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by impaired neuromuscular junction transmission, leading to fluctuating muscle weakness and fatigue. This condition is driven primarily by autoantibodies targeting the acetylcholine receptor at the neuromuscular junction. These antibodies are predominantly generated through a T‑cell‑dependent pathway, initiating immunomodulatory responses via complement activation. Cytokines and inflammatory mediators also play pivotal roles in the pathogenesis of MG. Recently, increasing attention has been given to the involvement of cytokines in autoimmune diseases. Interleukin‑35 (IL‑35), an immunoregulatory cytokine, is critical in various inflammatory and autoimmune conditions. It modulates immune responses by promoting Treg proliferation, enhancing their immunosuppressive functions, inhibiting Th17 cell differentiation, and reducing proinflammatory cytokine levels. IL‑35 is thus pivotal in the onset and progression of MG. The present review outlines the key functions of IL‑35 in MG pathogenesis and the impact of IL‑35 on the treatment and prognosis of myasthenia gravis, explores its therapeutic potential, and assesses its prognostic value, offering insights into its mechanisms and implications for treatment.", "authors": ["Mao Jing", "Zhang Lin-Ming", "Zhu Yan-Lin", "Gao Shu-Ji", "Liu Ming-Wei"], "journal": "International journal of molecular medicine", "entry_date": "2026/02/20 03:13", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41716022/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Kunming Medical University, Kunming, Yunnan 650032, P.R. China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "41712474", "title": "Assessment of Voice and Speech Attributes in Adult Patients with Myasthenia Gravis: A Case-Control Study.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a chronic autoimmune disorder that affects neuromuscular junction, resulting in fluctuating muscle weakness. Speech and voice can be affected by MG due to the involvement of bulbar muscles and muscular weakness, resulting in dysarthria. This work aimed to assess speech and voice attributes in adult patients with MG in comparison to normal individuals to highlight the effect of MG on speech and voice and its impact on quality of life.\nMETHODS: This study involved 40 participants (over 18 years old), who were divided into two groups matched for age and sex. Group 1 included 25 patients with MG, and group 2 included 15 normal subjects as a control group. All patients were subjected to detailed medical history and general and neurological examinations. Speech and voice assessment was performed in the form of auditory perceptual assessment, Voice Handicap Index, and acoustic analysis via the Multi-Dimensional Voice Program (MDVP), Computerized Speech Lab (CSL), Real-Time Pitch, and Nasometer II (NMII). The patients' results were compared to those of normal subjects.\nRESULTS: The present study revealed statistically significant differences between the two groups across multiple speech and voice parameters. The Voice Handicap Index revealed that 76% of patients experienced mild handicap, whereas 8% reported severe handicap. Regarding MDVP findings, group 1 presented significantly greater absolute jitter, jitter percent, shimmer (dB), shimmer percent, and noise-to-harmonic ratio values. Regarding CSL findings, group 1 had a greater voice-onset time than did the control group, with significant differences. The Real-Time Pitch results revealed significant differences in the energy and duration parameters. NMII was associated with higher nasalance scores for some sounds, with significant differences between the two groups.\nCONCLUSIONS: MG can lead to many speech and voice issues with changes in acoustic parameters that can affect patients' quality of life.", "authors": ["Abdou Rania Mohamed", "Elfatatry Amr Mohamed", "Qamara Nourhan Saleh", "Gommaa Sabah Saeed"], "journal": "Folia phoniatrica et logopaedica : official organ of the International Association of Logopedics and Phoniatrics (IALP)", "entry_date": "2026/02/19 13:12", "pub_date": "2026-02-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41712474/", "pub_types": ["Journal Article"], "affiliations": ["Otorhinolaryngology Department, Phoniatrics Unit, Faculty of Medicine, Alexandria University, Alexandria, Egypt."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41709922", "title": "Inflammatory biomarker panels in peripheral blood: association with myasthenia gravis onset and severity.", "abstract": "OBJECTIVE: To investigate the association between peripheral blood inflammatory biomarkers and the clinical phenotypes, severity, and prognosis of myasthenia gravis (MG).\nMETHODS: This retrospective study analyzed 134 MG patients (including 23 with myasthenic crisis [MC]) and 58 age- and sex-matched healthy controls hospitalized at the Second Affiliated Hospital of Soochow University (August 2016-March 2024). Peripheral blood inflammatory markers were compared across subgroups. Infection was strictly excluded based on clinical and laboratory criteria. Multivariate logistic regression and receiver operating characteristic (ROC) curve analyses were performed to identify risk factors and diagnostic value.\nRESULTS: Compared to controls, MG patients exhibited significantly elevated neutrophil-to-lymphocyte ratio (NLR), platelet-to-lymphocyte ratio (PLR), systemic immune-inflammation index (SII), and systemic inflammation response index (SIRI) (all p < 0.05). Patients with MC were characterized by a higher prevalence of generalized MG (GMG) and thymoma, as well as elevated leukocyte counts, NLR, and SIRI compared to non-MC patients. Multivariate analysis identified elevated PLR [OR: 1.01, 95% CI: 1.00-1.02] as independent risk factors associated with MG onset, while elevated NLR [OR: 1.20, 95% CI: 1.05-1.41] and the presence of thymoma [OR: 13.44, 95% CI: 4.42-48.54] were independently associated with MC. Furthermore, inflammatory indices (NLR, PLR, and SII) were significantly higher in GMG and moderate-to-severe cases (MGFA III-V) compared to ocular and mild cases.\nCONCLUSION: Systemic inflammatory biomarkers, particularly PLR and NLR, are significantly elevated in MG and correlate with disease severity and clinical subtypes. While PLR is associated with MG onset, NLR and thymoma are potential indicators for myasthenic crisis. These readily available markers may facilitate risk stratification in clinical practice.", "authors": ["Jin Hong", "Cui Yuxin", "Ren Yunya", "Ma Xinmiao", "Wang Yishi", "Fan Qi", "Cao Yulan", "Liu Chun-Feng", "Chen Jing"], "journal": "Frontiers in neurology", "entry_date": "2026/02/19 04:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41709922/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Clinical Research Center of Neurological Disease, The Second Affiliated Hospital of Soochow University, Suzhou, Jiangsu, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41709234", "title": "Monocyte-macrophage SAMHD1 alleviates EAMG by modulating the cGAS-STING pathway.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder whose pathogenesis has not been fully elucidated but is primarily associated with immune system dysregulation. Growing evidence indicates that innate immunity mediated by monocyte-macrophages plays a significant role in the pathogenesis of MG. SAMHD1 is a negative regulator of innate immunity, and its involvement in MG remains unclear. This study aims to clarify the immunoregulatory mechanism of SAMHD1 in MG and to explore its potential therapeutic implications.\nMETHODS: Experimental autoimmune myasthenia gravis (EAMG) rat models were established using purified torpedo acetylcholine receptor (AChR). Peripheral blood samples from MG patients and healthy controls were collected for clinical validation. Single-cell RNA sequencing was performed on peripheral whole blood from EAMG and control rats, as well as on human (GEO database). Serum levels of AChR antibodies were quantified using ELISA, while flow cytometry was employed to detect SAMHD1 expression across different cell types and to analyze the subgroup composition of CD4+ T cells. Immunofluorescence (IF) was performed for C5b-9 and α-BTX at the neuromuscular junctions (NMJ), as well as for γH2AX on macrophages. To investigate the underlying mechanism, macrophages were selectively targeted in vivo via tail vein injection of adeno-associated virus (AAV) vectors driven by the macrophage-specific F4/80 promoter, additionally, macrophages pre-treated with 1 µM STING inhibitor H-151 for 24 h were adoptively transferred into rats. RT-qPCR and western blot analysis techniques were employed to assess mRNA and protein expression levels, respectively.\nRESULTS: Our study revealed a significant reduction of SAMHD1 in monocytes (p = 0.0286) and splenic macrophages (p = 0.0002) of EAMG rats, as well as in monocytes of MG patients (p = 0.0002). Overexpression of SAMHD1 in macrophages significantly increased body weight and grip strength, reduced clinical scores, diminished complement deposition at the NMJ in EAMG rats, and shifted CD4⁺ T cells subset distribution—specifically, decreased frequencies of Th1(5.295 ± 0.2504% v 3.817 ± 1.393%) and Th17 (4.698 ± 1.078% v 2.328 ± 0.8311%) cells and increased frequency of Treg cells (4.087 ± 0.531% v 4.892 ± 0.708%). Mechanistically, SAMHD1 overexpression alleviated macrophage-intrinsic DNA damage, suppressed cGAS-STING pathway activation, and thereby restored the proportions of Th1, Th17 and Treg cells. Conversely, activation of the cGAS-STING pathway increased the proportion of Th1 (2.510 ± 0.4636% v 6.563 ± 1.546%) and Th17 (1.237 ± 0.7205% v 5.368 ± 1.526%) cells again, reduced the number of Treg cells (6.022 ± 0.3579% v 3.908 ± 0.2902%), meanwhile, EAMG rats exhibited progressive weight loss, impaired grip strength, elevated clinical scores, and enhanced complement deposition at the NMJ.\nCONCLUSION: This study uncovered a previously unrecognized mechanism whereby SAMHD1 downregulation impairs DNA damage repair, thereby triggering cGAS-STING pathway activation, immune dysregulation, and subsequent exacerbation of MG pathogenesis. These findings provide new insights into the pathogenesis of MG and identify SAMHD1 and the cGAS-STING axis as promising therapeutic targets for MG intervention.\nGRAPHICAL ABSTRACT: [Image: see text]\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s12974-026-03747-w.", "authors": ["Que Wenjun", "Fan Rui", "Lu Dan", "Liu Linqi", "Dong Jing", "Ke Pingyang", "Jing Sisi", "Gan Yaoqi", "Xiao Fei"], "journal": "Journal of neuroinflammation", "entry_date": "2026/02/19 00:11", "pub_date": "2026-02-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41709234/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Chongqing Key Laboratory of Major Neurological and Mental Disorders, Neurology Key Laboratory of Chongqing Education Commission of China, Chongqing Key Laboratory of Neurology, The First Affiliated Hospital of Chongqing Medical University, 1st Youyi Road, Yuzhong District, 400016, Chongqing, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 10.1, "journal_quartile": "1区"}, {"pmid": "41707811", "title": "Qiangji Jianli Decoction attenuates skeletal muscle injury in rats with experimental autoimmune myasthenia gravis via the GRP78/IRE1α/GPX4 signaling pathway.", "abstract": "ETHNOPHARMACOLOGICAL RELEVANCE: Qiangji Jianli Decoction (QJJLD), a representative multi-herb formula derived from the Traditional Chinese Medicine (TCM) theory that \"the Spleen governs the muscles\" (Pi Zhu Ji Rou), embodies the wisdom of classical Chinese medicine. This prescription has been in continuous clinical use in China for over three decades, consistently demonstrating significant and reproducible efficacy in alleviating symptoms in patients with myasthenia gravis (MG). Although its clinical effectiveness has been well validated, whether QJJLD ameliorates MG skeletal muscle injury by targeting glucose-regulated protein 78 (GRP78) to modulate endoplasmic reticulum stress (ERS) and ferroptosis remains unclear, and no systematic mechanistic studies have been conducted to date.\nOBJECTIVE: This study aimed to evaluate the protective effects of QJJLD against skeletal muscle injury in experimental autoimmune myasthenia gravis (EAMG) rats and to elucidate whether its mechanism involves the synergistic regulation of endoplasmic reticulum stress (ERS) and ferroptosis via the GRP78/IRE1α/GPX4 axis.\nMETHODS: EAMG was induced in Lewis rats using Rat 97-116 peptide. Rats received QJJLD (7.8, 15.6, 23.4 g/kg) or prednisone (5.4 mg/kg) for 28 days. Efficacy was assessed by Lennon score, RNS, serum AChR-Ab, and histopathology (H&E, Masson, and TEM). In vitro, L6 myoblasts were challenged with Tunicamycin (TM) or RSL3. Medicated serum was applied alone or combined with inhibitors (HA15, 4μ8C, or Fer-1). Expression of regeneration (MyoD1, MyoG), degradation (MuRF1), ERS (GRP78/p-IRE1α/XBP1s), and ferroptosis (GPX4, ACSL4, COX2) markers were quantified by WB, qRT-PCR, and immunofluorescence.\nRESULTS: QJJLD significantly ameliorated weight loss, muscle weakness, and NMJ transmission impairment in EAMG rats, while suppressing AChR-Ab levels. QJJLD promoted muscle regeneration (MyoD1, MyoG) and inhibited protein degradation (MuRF1). Histopathologically, QJJLD restored myofiber ultrastructure and attenuated fibrosis. Mechanistically, QJJLD downregulated GRP78 and p-IRE1α, leading to suppressed XBP1s-targeted genes, while simultaneously restoring GPX4 and improving MDA, GSH and Fe2+ levels. In vitro, the GRP78 inhibitor HA15 and the IRE1α inhibitor 4μ8C significantly attenuated the protective effects of QJJLD, with 4μ8C producing an occlusion effect that indicated the hierarchical role of the GRP78/IRE1α/GPX4 axis.\nCONCLUSION: QJJLD exerts dual suppression of ERS and ferroptosis by modulating the GRP78/IRE1α/GPX4 signaling pathway, thereby significantly improving the pathological progression of EAMG. The results offer strong theoretical and experimental support for utilizing QJJLD in the clinical application of MG and provide a modern scientific rationale for the TCM theory of \"the Spleen governs the muscles\".", "authors": ["Cai Xiaoqing", "Fan Shiwen", "Yang Peidan", "Zhao Lina", "Jiao Yingying", "Liang Jian", "Chen Tongkai", "Huang Tingjuan", "Song Yafang"], "journal": "Journal of ethnopharmacology", "entry_date": "2026/02/18 19:27", "pub_date": "2026-05-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41707811/", "pub_types": ["Journal Article"], "affiliations": ["Science and Technology Innovation Center, Guangzhou University of Chinese Medicine, Guangzhou, Guangdong, 510405, PR China. Electronic address: cxqtcm@163.com."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 5.4, "journal_quartile": "2区"}, {"pmid": "41702748", "title": "Clinical response to therapeutic plasma exchange in patients with immune-mediated inflammatory diseases of the central nervous system.", "abstract": "INTRODUCTION: Inflammatory immune-mediated diseases of the central nervous system, such as autoimmune encephalitis, acute disseminated encephalomyelitis or Guillain-Barré syndrome, pose diagnostic and therapeutic challenges in the pediatric population. Therapeutic plasma exchange has emerged as a useful option in these cases. This study evaluated the clinical response to therapeutic plasma exchange in children with these conditions.\nMETHODS: We conducted a retrospective cohort study at Fundación Hospital Pediátrico La Misericordia in Bogotá (2018-2022), including 50 patients with a confirmed diagnosis of antibody-mediated inflammatory disease of the central nervous system who were managed with therapeutic plasma exchange. We collected data on clinical, therapeutic and outcome variables and performed descriptive, survival, and Cox regression analyses.\nRESULTS: The mean age was 10 years, with a uniform sex distribution. The most frequent conditions were autoimmune encephalitis (36%) and acute disseminated encephalomyelitis (14%). At discharge, 56% of patients had persistent neurologic symptoms and 46% had recovered their prior functional status. The mortality was 6%. The use of antiepileptic drugs was significantly associated with a lower risk of relapse (hazard ratio, 0.081; P = .024) and steroid use with increased survival, particularly in patients with autoimmune encephalitis, acute disseminated encephalomyelitis and myasthenia gravis (P < .05).\nCONCLUSION: Therapeutic plasma exchange is a viable and safe treatment strategy for children with immune-mediated inflammatory diseases of the central nervous system. The concomitant use of antiepileptic drugs and steroids showed benefits in reducing relapse and mortality.", "authors": ["Rodríguez Galeano Andrés", "Ruge Joya Erika", "Bravo Guerra Diana", "Roa Giraldo Juan"], "journal": "Anales de pediatria", "entry_date": "2026/02/17 21:56", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41702748/", "pub_types": ["Journal Article"], "affiliations": ["Unidad de Cuidado Intensivo Pediátrico, Fundación Hospital Pediátrico La Misericordia, Bogotá, Colombia; Medicina Crítica y Cuidado Intensivo Pediátrico, Universidad el Bosque, Bogotá, Colombia. Electronic address: consultoriopediakids@gmail.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41700957", "title": "Literature Commentary.", "abstract": "In this issue, Drs. Mark L. Moster and Deborah I. Friedman review the following 5 articles, 3 of which were co-authored by our NANOS colleagues. Lee L, Vemuri JP, Belilos A, Sismanis A, Haines S, Felton W, Gharavi M, Tang Y, Coelho DH. Number of radiologic abnormalities associated with idiopathic intracranial hypertension as a predictor of the presence of pulsatile tinnitus. Otol Neurotol Open. 2025;5:e072. doi: 10.1097/ONO.0000000000000072.Snowden A, Van Stavern GP, Leanne Stunkel L Persistence of pulsatile tinnitus in patients with idiopathic intracranial hypertension following resolution of papilledema. J Neurol Sci. 2025:476:123608. doi: 10.1016/j.jns.2025.123608.Nachira D, Congedo MT, Kuzmych K, Evoli A, Iorio R, Vita ML, Petracca-Ciavarella L, Nocera A, Sassorossi C, Evangelista J, Lyberis P, Comacchio GM, Brandolini J, Aprile V, Zifara CC, Mastromarino MG, Patirelis A, Asteggiano E, Anile M, Venuta F, Imperatori A, Ambrogi V, Solli P, Dell'Amore A, Lucchi M, Melfi F, Ibrahim M, Ruffini E, Rea F, Margaritora S, Meacci E. Thymectomy in ocular myasthenia gravis: results before and after generalization and prognostic predictors of outcomes. J Clin Med. 2025;14:7840. doi: 10.3390/jcm14217840.Clément G, Puisieux S, Pellerin D, Brais B, Bonnet C, Renaud M. Spinocerebellar ataxia 27B (SCA27B), a frequent late-onset cerebellar ataxia. Rev Neurol (Paris). 2024;80:410-416. doi: 10.1016/j.neurol.2024.03.007.Thakolwiboon S, Redenbaugh V, Chen B, Hewitt S, Shah S, Lotan I, Levy M, Forcadela M, Huda S, Pique J, Marignier R, Boutiere C, Audoin B, Poullin P, Champsas D, Choi D, Danesh-Meyer HV, Vasileiou E, Sotirchos ES, Davis JB, Henderson AD, Wilf-Yarkoni A, Stiebel-Kalish H, Maillart E, Bonelli L, Arnold AC, Boudot De La Motte M, Deschamps R, Jitprapaikulsan J, Moss HE, Villarreal Navarro SE, Mao-Draayer Y, Mishra M, Vorasoot N, Cacciaguerra L, Tisavipat N, Tajfirouz DA, Tillema JM, Lopez-Chiriboga SA, Palace J, Hacohen Y, Pittock SJ, Flanagan EP, Chen JJ. Outcomes after acute plasma exchange for myelin oligodendrocyte glycoprotein antibody-associated disease. Neurology. 2025;105:e213903. doi: 10.1212/WNL.0000000000213903.", "authors": [], "journal": "Journal of neuro-ophthalmology : the official journal of the North American Neuro-Ophthalmology Society", "entry_date": "2026/02/17 09:43", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41700957/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41700316", "title": "The Duke MG Patient Registry III. Comparative Effectiveness of Azathioprine and Mycophenolate Mofetil in Generalized Myasthenia Gravis, a Retrospective Single Center Review.", "abstract": "INTRODUCTION/AIMS: Azathioprine (AZA) and mycophenolate mofetil (MMF) are the most commonly used non-steroidal immunosuppressants in patients with generalized myasthenia gravis (gMG) in North America but their relative effectiveness among disease subgroups is not known. We reviewed data in the Duke MG Clinic Registry to compare the effectiveness of AZA and MMF in subgroups of patients with gMG.\nMETHODS: This is a retrospective comparative effectiveness study of patients with acetylcholine receptor positive gMG receiving recommended doses of AZA or MMF for at least 90 days. Treatment goal (TG) was achieving MGFA Post-Intervention Status Minimal Manifestations. Time-to-event analysis, inverse probability of treatment weighting, and Cox proportional hazards (CPH) modeling were performed.\nRESULTS: Among 320 cohort patients, 177 took AZA and 143 took MMF. TG was achieved by 66.1% taking AZA, median time 17.5 months, and 68.5% taking MMF, median time 10.5 months (p = 0.0004). Concomitant prednisone, taken by 2/3 of patients, increased the proportion of patients who reached TG with either drug (p < 0.0001). There was a positive correlation between disease duration at drug initiation and time to TG (Pearson r = 0.32, p = 2.3 × 10-6).\nDISCUSSION: Two-thirds of patients treated with AZA or MMF achieved TG after a median of 14 months. Patients taking MMF achieved TG sooner than those taking AZA, and concomitant prednisone increased the proportion of patients who achieved TG with either drug. Patients with shorter disease duration at drug initiation reached TG sooner with either drug. These results emphasize the value of concomitant prednisone and early immunosuppressive treatment of patients with gMG.", "authors": ["Sanders Donald B", "Lutz Michael W", "Raja Shruti M", "Juel Vern C", "Hobson-Webb Lisa D", "Massey Janice M"], "journal": "Muscle & nerve", "entry_date": "2026/02/17 04:02", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41700316/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Division, Department of Neurology, Duke University Medical Center, Durham, North Carolina, USA."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41700204", "title": "First Paediatric Case of mRNA COVID-19 Vaccine Associated New Onset Systemic Myasthenic Crisis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder characterized by abnormal neuromuscular conduction. The thymus is believed to play a key role in the pathogenesis of MG; therefore, thymectomy is an important treatment option for the disease. As MG exacerbations and new-onset MG cases following Coronavirus Disease 2019 (COVID-19) vaccinations have been previously reported in the literature, various complications highly related to autoimmunity, such as Guillain-Barré syndrome, have also been described after vaccination. A previously healthy girl developed her first life-threatening systemic MG attack following administration of the messenger RNA (mRNA) BNT162b2 COVID-19 vaccine. Despite receiving treatment targeting MG, her clinical status did not show significant improvement, which led to the decision to perform thymectomy via the video-assisted thoracoscopic surgery (VATS) approach. After the procedure, a significant improvement was observed in her clinical condition. We aimed to contribute to the literature on this rarely encountered condition by reporting the first paediatric case in our country presenting with BNT162b2 vaccination-associated generalized weakness and severe respiratory distress, who was diagnosed with MG and thymoma during follow-up, in the light of contemporary literature. This case also serves as a warning for other mRNA vaccines.", "authors": ["Kirik Serkan", "Agar Mehmet", "Akyol Hadice Gurkan", "Kirik Yasemin"], "journal": "Sisli Etfal Hastanesi tip bulteni", "entry_date": "2026/02/17 03:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41700204/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Pediatric Neurology, Elazig Fethi Sekin City Hospital, Elazig, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41700072", "title": "[How to Diagnose Lambert-Eaton Myasthenic Syndrome Patients Early: A Systematic Review of Japanese Case Reports].", "abstract": "A systematic review was conducted on case reports of Lambert-Eaton myasthenic syndrome (LEMS) in Japanese patients published prior to 2023, focusing on clinical features. Particular attention was paid to the interval from LEMS onset to diagnosis, examining the clinical question (CQ): 'How can the time to diagnosis be shortened?' Patient profiles showed a male predominance, with 76 males and 21 females among the total 97 cases, yielding a male-to-female ratio of 3.6:1. The median age of onset (mean±standard deviation) across all cases was 62.0 (59.3±11.7) years, with the age distribution peaking in the 70s. For cases with tumour involvement (n=84), the median age at onset (mean±SD) was 62.5 (60.2±10.8) years, and the median duration of illness prior to LEMS diagnosis (mean±SD) was 3.0 (4.9±5.7) months. Conversely, for cases without tumour involvement (n=13), the median age at onset (mean±SD) was 52.0 (53.5±15.8) years, and the median duration of illness (mean±standard deviation) was 6.0 (21.1±25.7) months. Based on the above CQ responses, LEMS should be actively suspected and electrophysiological testing considered when neurological symptoms include lower limb muscle weakness combined with ocular symptoms such as ptosis and diplopia, and further autonomic symptoms such as dry mouth. Furthermore, it was considered that P/Q-type VGCC antibody testing could potentially be utilised prior to diagnosis by electrophysiological testing. (Received August 12, 2025; Accepted October 3, 2025; Published February 2, 2026).", "authors": ["Motomura Masakatsu", "Ike Kohji", "Kitanosono Hiroko", "Shimizu Etsuro", "Yoshimura Shunsuke", "Yamada Masashi", "Hatanaka Yuki", "Irioka Takashi"], "journal": "Brain and nerve = Shinkei kenkyu no shinpo", "entry_date": "2026/02/17 03:33", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41700072/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Department of Engineering, The Faculty of Engineering, Nagasaki Institute of Applied Science."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41699526", "title": "Clinical outcomes, serum IgG changes, and follow-up observations in the treatment of anti-AChR antibody-positive generalized myasthenia gravis with Efgartigimod.", "abstract": "PURPOSE: To investigate the clinical effects, changes in serum IgG levels, and follow-up observations following treatment with Efgartigimod in patients with anti-acetylcholine receptor (anti-AChR) positive generalized myasthenia gravis (gMG).\nMETHODS: This was a single-center retrospective study. Clinical data and follow-up information were collected for 8 patients with anti-AChR positive gMG treated with Efgartigimod. Clinical severity was assessed before and after treatment using the Quantitative Myasthenia Gravis (QMG) Score and the Myasthenia Gravis Activities of Daily Living (MG-ADL) scale. Serum levels of immunoglobulins IgG, IgA, and IgM were also measured before and after treatment.\nRESULTS: The cohort consisted of 8 patients (4 male, 4 female), aged 21 to 73 years (ages: 55, 21, 63, 72, 62, 69, 64, 73). The clinical manifestations included external ophthalmoplegia in 8 cases, dysphagia in 7, weakness of the neck muscles in 8, weakness of the limbs in 7, pre-crisis status in 2, and one case of a myasthenic crisis. Disease duration ranged from 3 months to 20 years. At admission, the QMG scores ranged from 5 to 29, and the MG-ADL scores ranged from 3 to 19. Three patients had coexisting autoimmune diseases. After Efgartigimod treatment, all patients showed rapid improvement in clinical symptoms. A clinically meaningful reduction (CMR) in the MG-ADL score was achieved in 100% of patients, with 87.5% achieving a CMR in the QMG score. Notably, 87.5% of patients were responders to both measures. Serum IgG, IgA and IgM levels were measured in six patients throughout the treatment period. While IgG levels showed a rapid and marked reduction post-treatment, IgA and IgM levels remained largely unchanged. The follow-up period ranged from 190 to 414 days (median: 380.5 days). During follow-up, 6 patients achieved minimal manifestation status with only grade 1 adverse events according to CTCAE. One patient experienced symptom recurrence after voluntarily discontinuing treatment, and another showed symptom exacerbation due to a concurrent respiratory infection.\nCONCLUSION: Efgartigimod has been shown to rapidly improve clinical symptoms in patients with generalised myasthenia gravis, while also significantly reducing serum IgG levels. When used alongside immunosuppressants, it can help to maintain long-term control of the disease.", "authors": ["Fu Jingting", "Zheng Xianzhao", "Ma Xiaoli", "Qu Qianqian", "Cui Wenhao", "Mao Xing", "Fu Wenhua", "Lyv Haidong"], "journal": "BMC neurology", "entry_date": "2026/02/17 00:07", "pub_date": "2026-02-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41699526/", "pub_types": ["Journal Article"], "affiliations": ["Neurology Department, Jiaozuo People's Hospital Affiliated to Henan Medical University, Shanyang District, Jiaozuo City, Henan Province, 454002, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41699286", "title": "Rapid efficacy of efgartigimod for generalized myasthenia gravis patients in acute exacerbations/worsening: multicenter real-world retrospective study.", "abstract": "BACKGROUND AND OBJECTIVES: Acute exacerbations/worsening of generalized myasthenia gravis (gMG) require urgent intervention to prevent progression to life-threatening myasthenic crisis. This multicenter study evaluate the efficacy and safety of efgartigimod in gMG patients experiencing acute exacerbations/worsening to validate its potential as a rapid-acting therapeutic option.\nMETHODS: In this multicenter retrospective study (Jan 2024-Feb 2025), 61 gMG patients with acute exacerbations/worsening received weekly efgartigimod infusions for 4 weeks. Efficacy was assessed at baseline (W0) and weekly throughout the treatment cycle (W1-W7) using Myasthenia Gravis Foundation of America Post-Intervention Status (MGFA-PIS), Quantitative Myasthenia Gravis (QMG), and Myasthenia Gravis Activities of Daily Living (MG-ADL) scores, along with prednisone dosage reductions. Safety assessments were concurrently performed.\nRESULTS: Median age was 56 years (range: 39-68 years). Pulmonary infection (16/61, 26.2%) was the predominant trigger of myasthenic crisis (MC) red flgs. Median duration from symptom deterioration to efgartigimod initiation was 18 days. Clinical meaningful improvement occurred in 81.9% at W1 (post-single dose), 98.1% at W4, and 91.9% at W7. MG-ADL and QMG scores decreased substantially from baseline (W4: 80.86% and 55.81% reduction; W7: 70.78% and 47.76% reduction), Patients with MC red flags achieved comparable outcomes. Greater MG-ADL imrovements were observed in those with thymoma history, severe MGFA classification, prior MC, or MC red flags. No treatment-related allergic reactions, infections, or serious adverse events were observed.\nCONCLUSION: Efgartigimod demonstrates rapid, significant efficacy in gMG acute exacerbations/worsening, supporting its role as a valuable therapeutic option for this high-risk population.", "authors": ["Lin Jing", "Chang Ting", "Xiao Lianchen", "Hu Jinquan", "Di Li", "Yang Chunsheng", "Wu Yan", "Jiang Yan", "Zhang Juanjuan", "Bu Bitao", "Li Zhijun"], "journal": "Journal of neurology", "entry_date": "2026/02/16 23:30", "pub_date": "2026-02-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41699286/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, 430030, Hubei, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41699220", "title": "[Is it myasthenia gravis?].", "abstract": "", "authors": ["Eilers-Petri Caroline", "Mäurer Mathias"], "journal": "MMW Fortschritte der Medizin", "entry_date": "2026/02/16 23:29", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41699220/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurologie und -neurologische -Frührehabilitation, Klinikum Würzburg Mitte gGmbH, Salvatorstraße 7, 97070, Würzburg, Deutschland. caroline.eilers-petri@kwm-klinikum.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41698381", "title": "Vibostolimab coformulated with pembrolizumab versus pembrolizumab alone as adjuvant therapy for high-risk stage IIB-IV melanoma (KEYVIBE-010): a randomised, double-blind, phase 3 study.", "abstract": "BACKGROUND: Combination therapy with vibostolimab plus pembrolizumab has previously shown promising antitumor activity in melanoma. We aimed to evaluate the efficacy and safety of vibostolimab coformulated with pembrolizumab as adjuvant therapy for high-risk resected melanoma.\nMETHODS: This randomised, double-blind, phase 3 study was done at 205 global sites (hospitals and cancer centres). Participants aged 12 years or older with surgically resected, stage IIB-IV cutaneous melanoma per the American Joint Committee on Cancer Cancer Staging Manual 2017 (8th edition), with no evidence of metastatic disease after resection, were randomly assigned (1:1) to receive vibostolimab 200 mg coformulated with pembrolizumab 200 mg or pembrolizumab 200 mg alone intravenously every 3 weeks. Randomisation was done using an interactive response technology system and was stratified by risk-based staging and geographical region. Participants, investigators, and site staff were masked to group assignment. The primary endpoint was recurrence-free survival assessed in the intention-to-treat population. Safety was assessed in all participants who received at least one dose of the study treatment. The protocol-prespecified first interim analysis was an event-driven nonbinding futility analysis of recurrence-free survival that was planned for when 111 events had occurred (futility bar of observed HR 0·95). This study is registered with ClinicalTrials.gov (NCT05665595), and is closed to recruitment.\nFINDINGS: Between Jan 19, 2023, and March 6, 2024, 1402 participants were randomly assigned to receive coformulated vibostolimab-pembrolizumab (n=701) or pembrolizumab (n=701). At the first interim analysis, median study follow-up, defined as time from randomisation to data cutoff, was 4·2 months (IQR 1·9-6·7). The median age was 61·0 years (IQR 51·0-70·0), 829 (59%) of 1402 participants were male and 573 (41%) were female. 1107 (79%) of participants were White, 273 (19%) were Asian, and 22 (2%) were of other race or race was missing. At the time of the first interim analysis, a total of 119 (8%) of 1402 participants had had a recurrence-free survival event, including 67 (10%) of 701 in the vibostolimab-pembrolizumab group and 52 (7%) of 701 in the pembrolizumab alone group. The median recurrence-free survival was not reached in either group; the hazard ratio for recurrence-free survival in the vibostolimab-pembrolizumab group versus pembrolizumab alone group was 1·25 (95% CI 0·9-1·8). The most common (occurred in more than five participants) grade 3 or higher treatment-related adverse events were adrenal insufficiency in 13 (2%) participants, hepatitis in 11 (2%) participants, rash in 9 (1%) participants, maculopapular rash in 7 (1%) participants, and pruritus in 6 (1%) participants in the vibostolimab-pembrolizumab group and increased alanine aminotransferase in 7 (1%) participants in the pembrolizumab alone group. Treatment-related serious adverse events occurred in 74 (11%) participants and 30 (4%) participants, respectively. Treatment-related adverse events led to death in two (<1%) participants in the vibostolimab-pembrolizumab group (myasthenia gravis and myocarditis) and one participant (<1%) in the pembrolizumab group (myositis). The external data monitoring committee decided to discontinue the study according to prespecified futility criteria.\nINTERPRETATION: Vibostolimab coformulated with pembrolizumab did not provide additional clinical benefit versus pembrolizumab as adjuvant therapy in participants with resected stage IIB-IV melanoma. Pembrolizumab monotherapy remains a standard of care for resected high-risk melanoma.\nFUNDING: Merck Sharp & Dohme, a subsidiary of Merck & Co.", "authors": ["Dummer Reinhard", "Guo Jun", "Luke Jason J", "Carlino Matteo S", "Schadendorf Dirk", "Khattak Muhammad A", "Hauschild Axel", "Ascierto Paolo A", "Chen Yu", "Shin Sang Joon", "Rutkowski Piotr", "Luo Zhiguo", "Chen Jing", "Rivalland Gareth", "Coetzee Corlia", "Ribas Antoni", "Mujika Karmele", "Markel Gal", "Villarroel Rodrigo U", "Dizdar Omer", "Caglevic Christian", "Grebennik Dmitri", "Donovan Kevin", "Krepler Clemens", "Long Georgina V"], "journal": "The Lancet. Oncology", "entry_date": "2026/02/16 18:52", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41698381/", "pub_types": ["Journal Article"], "affiliations": ["Department of Dermatology, University Hospital Zürich, Zürich, Switzerland. Electronic address: reinhard.dummer@usz.ch."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 35.9, "journal_quartile": "1区"}, {"pmid": "41696676", "title": "Thymectomy with or without maintenance therapy for myasthenia gravis patients: a tri-center, real-world study.", "abstract": "BACKGROUND: The necessity and optimal duration of post-thymectomy immunoregulatory medication (IM) in myasthenia gravis (MG) remain unclear.\nOBJECTIVES: This study aimed to evaluate whether IM is required after thymectomy in MG patients and to determine the appropriate duration of IM in patients without postoperative deterioration by comparing long-term clinical outcomes.\nDESIGN: This triple-center, retrospective study included 1248 MG patients who underwent thymectomy. Among these patients, we compared outcomes between 483 patients without post-thymectomy IM and 765 patients receiving IM.\nMETHODS: Efficacy outcomes included post-thymectomy deterioration and minimal manifestation status (MMS) at 1 year. Safety outcomes, tumor growth, and serious complications were assessed between groups. Subgroup analyses were performed in mild cases (Myasthenia Gravis Foundation of America clinical classification (MGFA) ⩽2a at discharge), patients receiving IM for >1 year, and patients receiving IM for >2 years. Propensity score matching (PSM) was conducted for validation.\nRESULTS: Relative to 438 MG patients underwent thymectomy with no-IM therapy, 756 thymectomized MG patients receiving concomitant IM showed significantly superior outcomes, including lower deterioration (hazard ratio (HR) = 0.44, adjusted p < 0.001), lower deteriorated MGFA class (adjusted coefficient = 0.94, p < 0.001), and higher odds of achieving MMS at 1 year (odds ratio = 2.06, adjusted p < 0.001). No significant differences were observed in tumor development (3 years: p = 0.78; 5 years: p = 0.27) or serious complications (p = 0.53). Similar trends were observed across subgroups. Among patients without postoperative deterioration, IM longer than 1 year reduced deterioration risk compared with ⩽1 year (HR = 0.67 (0.50-0.91), p = 0.01), whereas extending IM beyond 2 years offered no additional benefit (p = 0.137). PSM analysis confirmed these findings.\nCONCLUSION: Our real-world analysis of 1248 MG patients suggests that thymectomy alone is not sufficient to achieve satisfactory outcomes. Post-thymectomy IM is recommended for at least 1 year, while extending treatment beyond 2 years appears to offer no further advantage in patients without deterioration.\nA multiple center real-world study looking at whether and for how long patients with myasthenia gravis need to continue immuno regulatory medications after thymectomy surgery to prevent symptoms from returning Why was this study done? For patients with myasthenia gravis (MG)—a chronic condition that causes muscle weakness—undergoing surgery to remove the thymus gland (a procedure called thymectomy) is a common and effective treatment. However, a major question remains for doctors and patients after the operation: Is it necessary to continue using immunoregulatory medications, and if so, for how long? There is a critical balance to be struck. Stopping these medications too early could risk the disease symptoms returning. On the other hand, using them for longer than needed exposes patients to potential side effects, such as a higher risk of infections, without a clear benefit. Currently, there is no strong consensus on the best approach. Therefore, this study was conducted to obtain evidence for this important treatment decision for patients and their doctors. What did the researchers do? To answer this question, we conducted a tri-center study that looked back at the medical records of 1,248 MG patients who had a thymectomy. We specifically compared the long-term health outcomes of 483 patients who did not receive any immunoregulatory medication after surgery to 765 patients who did. We examined key outcomes, including whether the MG symptoms came back (deterioration), the patients’ clinical status one year after surgery, and important safety issues like the risk of developing tumors or other serious complications. To make sure our comparisons were fair, we used adequate statistical methods to account for differences between the patient groups, ensuring the results were robust and reliable. What did the researchers find? Patients who took immunoregulatory medications after thymectomy had significantly better outcomes compared to those who did not. Their risk of the disease returning was less than half. They were also twice as likely to achieve a state of minimal or no symptoms one year after the operation. Reassuringly, we found no evidence that taking these medications increased the risk of tumors or other serious complications over the study period. Furthermore, for patients who showed no signs of the disease returning after surgery, we found that continuing the medication for more than one year was significantly better at preventing future deterioration than stopping within the first year. However, a key finding was that extending the medication beyond two years did not provide enough benefit in preventing recurrence compared to stopping at the two-year mark. What do these findings mean? This study provides evidence that for MG patients, a thymectomy should not be considered a standalone cure. Continuing immunoregulatory medications for at least one year after surgery is crucial to effectively prevent the disease from returning. Importantly, the findings also suggest that for the many patients who remain symptom-free after surgery, continuing these medications for longer than two years may be unnecessary, allowing them to try reducing treatment and avoid potential long-term side effects. This evidence helps doctors and patients create more personalized, safer treatment plans.", "authors": ["Zhang Hao", "Fan Moli", "Shi Yutong", "Huang Xiaoyu", "Cui Ying", "Yu Zihao", "Yang Chun-Sheng", "Li Hui-Ning", "Zhang Xiao-He", "Liu Peng", "Wu Ti", "Shi Fu-Dong", "Qi Guo-Yan"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2026/02/16 06:58", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41696676/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41695242", "title": "Case-Based Lessons on Remote Patient Monitoring in Neurology Using Consumer-Grade Wearables.", "abstract": "Consumer-grade wearables offer promising opportunities for remote patient monitoring (RPM) in neurological disorders, yet their clinical application remains uncertain. In this exploratory analysis, we draw on prospective observational trials using smartwatches in patients with multiple sclerosis, myasthenia gravis, chronic inflammatory demyelinating polyneuropathy, and migraine, who were monitored for 6 to 24 months. Through detailed clinical case narratives, we illustrate both the potential and the limitations of RPM in neurology. Wearable-generated data successfully captured early, clinically meaningful changes, such as the onset of a myasthenic exacerbation, and supported patient engagement in identifying individual triggers, including for migraine. However, external influences such as holidays, infections, or mobility aid use confounded activity signals, underscoring the importance of contextual interpretation. While wearables can enhance neurological care, their integration into clinical workflows is challenged by limited validation and interpretability. Realising their potential requires robust validation in clinical settings and the development of interoperable RPM platforms supported by close collaboration between clinicians, engineers, and patients.\nSmartwatches and fitness trackers are increasingly used to monitor health, but how helpful are they for people with neurological conditions? In this study, we followed patients with multiple sclerosis, myasthenia gravis, chronic inflammatory polyneuropathy, and migraine for up to two years using everyday wearables. By looking at real-life cases, we found that these devices can detect important changes in health, such as early signs of worsening symptoms. They also helped some patients better understand their condition and identify possible triggers, like for migraines. However, the data from wearables can be misleading—for example, during vacations, infections, or when using mobility aids—so it’s important to interpret the results carefully. To truly benefit patients, these tools need to be better tested in clinical settings and integrated into easy-to-use systems that support doctors and patients working together.", "authors": ["Epping Paula Z", "Hagler Ramona", "Werner Noah M", "Voth Jan", "Schmidt Linea", "Huntemann Niklas", "Stern Ariel D", "Ruck Tobias", "Meuth Sven G", "Pawlitzki Marc", "Masanneck Lars"], "journal": "Journal of central nervous system disease", "entry_date": "2026/02/16 06:47", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41695242/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, University Hospital and Medical Faculty University Hospital Düsseldorf, Düsseldorf, Germany."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41693182", "title": "Immune reconstitution for the treatment of myasthenia gravis: the focus on cladribine.", "abstract": "Autoimmune diseases (AID) such as multiple sclerosis, rheumatoid arthritis, type 1 diabetes, inflammatory neuropathies, and some 100 other conditions, affect 5-10% of the global population, and their incidence is increasing, particularly in women. Among these, myasthenia gravis (MG) is a relatively rare but debilitating disease, which represents a prototype antibody-mediated autoimmune condition with well-studied pathogenesis. MG is a neuromuscular junction disorder marked clinically by fatigable muscle weakness and serologically by the presence of pathogenic autoantibodies. In MG pathological B- and T-cell subtypes are implicated, including memory B and plasma cells. In recent years there has been significant progress in the field of therapy, with several novel drugs introduced targeting major components of the pathogenetic pathway. However, there are still unmet needs in the treatment, especially the lack of a curative, upstream approach in contrast to the existing chronic downstream immunomodulatory actions. A nucleoside analog cladribine was primarily developed for the treatment of chronic leukaemias, in particular hairy cell leukaemia. For these indications, the injectable formulation of the drug was registered in 1997, and it has been manufactured in several countries since then. Later the oral formulation of cladribine (Mavenclad, Merck KGaA) was registered worldwide for use as immune reconstitution therapy (IRT) for relapsing multiple sclerosis. In this setting it has gained a strong position in the group of high-efficacy compounds, exerting long-term impact on the immune system. In a pilot clinical study, we found appreciable efficacy and safety profile of a short course of cladribine in MG. Herein, we present the design of a prospective, multicentre, randomised, controlled trial (RCT) using a parenteral preparation of cladribine in MG, currently ongoing in 6 clinical centres in Poland (EudraCT No. 2020-005762-34). In addition, we discuss the concept of immune reconstitution, which seems applicable for MG treatment.", "authors": ["Rejdak Konrad", "Baranowski Dariusz", "Grieb Paweł"], "journal": "Folia neuropathologica", "entry_date": "2026/02/16 01:28", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41693182/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Medical University of Lublin, Lublin, Poland. konrad.rejdak@umlub.edu.pl."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41691323", "title": "Genetic insights into biological aging and myasthenia gravis: a Mendelian randomization study of telomere length, epigenetic clocks, and mitochondrial DNA copy number.", "abstract": "BACKGROUND: Emerging epidemiological evidence shows myasthenia gravis (MG) is associated with age-related biological processes, but its mechanism of causality remains unexplained. This bidirectional Mendelian randomization (MR) study aimed to clarify the causal relationships between quantifiable biomarkers of aging and MG.\nMETHODS: We extracted genetic instrumental variables for three aging biomarkers: telomere length, epigenetic clocks, and mitochondrial DNA copy number (mtDNA-CN) and MG from the public GWAS databases. The main causal effect estimates were obtained by the inverse variance weighted method, and supplementary sensitivity analysis was used to evaluate potential heterogeneity and pleiotropy effects.\nRESULTS: Overall, genetically predicted HannumAge and mtDNA-CN were associated with MG (OR = 0.909, 95% CI 0.834-0.991, P = 0.030; OR = 1.592, 95% CI 1.025-2.473, P = 0.039), though these associations did not survive false discovery rate (FDR) correction. Subgroup analyses showed a negative causal effect of HannumAge on early-onset MG (EOMG) (OR = 0.775, 95% CI 0.667-0.901, P = 0.001, PFDR =0.005), and a potential positive association of mtDNA-CN with late-onset MG (LOMG) (OR = 1.756, 95% CI 1.030-2.995, P = 0.039, PFDR =0.193). Reverse MR identified that EOMG causally increased epigenetic clocks (PhenoAge: OR = 1.056, 95% CI 1.004-1.111, P = 0.036; GrimAge: OR = 1.098, 95% CI 1.055-1.143, P < 0.001; HannumAge: OR = 1.100, 95% CI 1.058-1.144, P < 0.001), with the GrimAge and HannumAge association remaining significant after FDR correction. No evidence supported causal associations of MG/LOMG with aging biomarkers.\nCONCLUSION: Our findings demonstrate a bidirectional causality between EOMG and epigenetic aging clocks, which indicates that there is a self-reinforcing pathophysiological cycle. The epigenetic age acceleration is both a driver and a result of the progression of EOMG. The correlation between mtDNA-CN and LOMG suggests that there may be a potential compensatory adaptation mechanism to combat chronic oxidative stress in age-related autoimmunity. These results highlight the complex and subtype-dependent contributions of biological aging to the autoimmune-mediated pathology of MG, and provide key mechanistic insights into the subtype-specific aging in MG.", "authors": ["Xiang Wei", "Luan Yining", "Chen Kangzhi", "He Ting", "Zhou Qian", "Yang Huan"], "journal": "Clinical epigenetics", "entry_date": "2026/02/14 23:27", "pub_date": "2026-02-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41691323/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, 87 Xiangya Road, Changsha, 410018, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "41687435", "title": "Docosahexaenoic acid supplementation aggravates myasthenia gravis through immune dysregulation.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder characterized by the disruption of immune cell homeostasis and inflammatory processes. However, the impact of metabolic abnormalities on immune regulation in MG has not been well defined. The objective of this study was to identify serum metabolites causally linked to MG and to explore their role in the onset and progression of the disease. This will provide a theoretical foundation for targeted clinical interventions and therapeutic strategies. To establish the causal relationship between serum metabolites and MG, we employed Mendelian randomization. Furthermore, we conducted dietary interventions with docosahexaenoic acid (DHA) to observe its effects on the disease progression and immune cell subpopulations in experimental autoimmune myasthenia gravis (EAMG) rats. We also performed metabolomic and transcriptomic analyses of regulatory T cells (Treg) during MG progression. Our findings suggest that dysregulated lipid metabolism, particularly elevated DHA levels, is a significant risk factor for MG, influencing various markers associated with Treg cells in both MG patients and in EAMG models. The addition of 1% DHA to the diet exacerbated the severity of EAMG, enhanced B cell immune responses, and promoted antibody production. However, it also led to an increase in the proportion of Treg cells. Further in vitro experiments confirmed that DHA accumulation in Treg cells enhances their proliferation but impairs their inhibitory function, partially through the PI3K-Akt signaling pathway. These results imply that modulating lipid metabolism, especially through the PI3K-Akt pathway in Treg cells, could be critical in controlling MG.", "authors": ["Liu Linqi", "Lu Dan", "Que Wenjun", "Fan Rui", "Zheng Wei", "Gan Yaoqi", "Xiao Fei"], "journal": "Journal of neuroimmunology", "entry_date": "2026/02/13 18:08", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41687435/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Chongqing Key Laboratory of Major Neurological and Mental Disorders, Neurology Key Laboratory of Chongqing Education Commission of China, Chongqing Key Laboratory of Neurology, the First Affiliated Hospital of Chongqing Medical University, Chongqing 400016, China; Department of Rare Disease, the First Affiliated Hospital of Chongqing Medical University, Chongqing 400016, China; Key Laboratory of Major Brain Disease and Aging Research (Ministry of Education), Chongqing Medical University, Chongqing 400016, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41686610", "title": "Mendelian randomization followed by single-cell RNA sequencing exploration identifies effector memory CD4+ T cells as a risk factor for myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular junction disease classified as early onset MG (EOMG), which typically occurs before the age of 50 years, and late-onset MG (LOMG), which occurs after the age of 50 years. The contribution of different immune cell subsets to MG pathogenesis is not fully understood. To address this, we conducted 2-sample Mendelian randomization (MR) analyses incorporating 731 peripheral immunophenotypes associated with MG. To further explore cellular mechanisms, we analyzed an existing single-cell RNA sequencing (scRNA-seq) dataset derived from the peripheral blood of patients with MG during and after the myasthenic crisis phase. In MR analyses, IVW results suggested that 42 immunophenotypes were risk or protective factors for LOMG, whereas 28 immunophenotypes were involved in EOMG. Comprehensive sensitivity analyses confirmed the absence of heterogeneity and horizontal pleiotropy. Among these, the proportion of effector memory CD4 + T cells emerged as the most significant factor associated with an increased risk of LOMG. Single-cell analyses revealed an expansion of these cells in patients with LOMG during the myasthenic crisis stage compared with the stable stage, with functional annotations showing strong similarities to activated CD4 + T cells treated with TGF-β and IL-4. This study identified effector memory CD4 + T cells as a significant risk factor for LOMG through MR analyses and further explored an existing scRNA-seq dataset. The role of effector memory CD4 + T cells, potentially mediated by TGF-β and IL-4, in LOMG pathogenesis and disease exacerbation, highlighting the need for further functional studies.", "authors": ["Ren Zhaolin", "He Hao", "Cai Zhichun", "Li Peijun", "Liu Zhou", "Zhou Haihong"], "journal": "Medicine", "entry_date": "2026/02/13 12:34", "pub_date": "2026-02-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41686610/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yuexi Hospital of the Sixth Affiliated Hospital, Sun Yat-sen University (Xinyi People's Hospital), Xinyi, Guangdong, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41684543", "title": "Factors Influencing the Conversion of Ocular Myasthenia Gravis to Generalized Myasthenia Gravis: A Retrospective Cohort Study.", "abstract": "PURPOSE: The conversion rate of ocular myasthenia gravis (OMG) to generalized myasthenia gravis (GMG) lacks definitive predictors.\nMETHODS: This retrospective cohort study analyzed data collected at Siriraj Hospital between January 2007 and December 2019 to identify factors influencing OMG generalization and the time to conversion. The records of 200 OMG patients were reviewed and both acetylcholine receptor antibody (AChR Ab)-positive and AChR Ab-negative patients were included.\nRESULTS: Seventy-eight (39%) developed GMG, with a median conversion time of 16 months (IQR 7.88, 33.75) and a 2-year conversion rate of 25.5%. AChR Ab positivity (adjusted HR 2.88, 95% CI 1.79-4.63), thymic abnormalities (adjusted HR 2.30, 95% CI 1.41-3.74), smoking (adjusted HR 1.78, 95% CI (1.04, 3.03), and pyridostigmine dosages > 180 mg/day (adjusted HR 2.33, 95% CI 1.41-3.87) were significantly associated with shorter conversion time.\nCONCLUSION: Thymic abnormalities and positive AChR Ab warrant routine assessment in all OMG patients. Smoking cessation is crucial, as it may impact conversion risk and time. Unlike previous findings suggesting a protective role of pyridostigmine, our data indicate a strong association between high-dose pyridostigmine and conversion to GMG, likely reflecting underlying disease severity. This underscores the need for individualized risk assessment in OMG management.", "authors": ["Chuenkongkaew Wanicha", "Chirapapaisan Niphon", "Chatchutimakorn Pawimon", "Rattanathamsakul Natthapon", "Joradoln Manassawee", "Kongthanasomboon Pawita", "Eiamsamarng Akarawit"], "journal": "Journal of ophthalmology", "entry_date": "2026/02/13 04:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41684543/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, Faculty of Medicine Siriraj Hospital, Mahidol University, Bangkok, Thailand, mahidol.ac.th."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41683748", "title": "C-Reactive Protein and Neurological Autoimmune Diseases: Bridging the Diagnostic and Pathogenic Gap.", "abstract": "C-reactive protein (CRP) has emerged as a crucial link between systemic and neuroinflammatory processes, though its role across neurological autoimmune disorders remains incompletely understood. Pathologies such as multiple sclerosis (MS), neuromyelitis optica spectrum disorder (NMOSD), Guillain-Barré syndrome (GBS), and myasthenia gravis (MG) share chronic, dysregulated inflammation resulting from loss of immune tolerance. Their pathogenesis arises from interactions among genetic susceptibility, environmental factors, and gut microbiota alterations that trigger autoreactive immune cascades through molecular mimicry, ectopic antigen expression, or paraneoplastic cross-reactivity. These immune pathways sustain inflammation and promote neuroaxonal injury. CRP, synthesized mainly by hepatocytes in response to interleukin-6 (IL-6), functions as both an effector and reporter of inflammation, linking systemic immune activation to neuroinflammatory damage. Elevated CRP levels correlate with unfavorable outcomes, including accelerated disability in MS, IL-6-mediated astrocyte injury in NMOSD, respiratory failure in GBS, and crisis susceptibility in MG. Composite indices such as the CRP-to-albumin ratio are emerging as refined prognostic markers, though interpretation is limited by non-specificity and biological variability. This review integrates current evidence on CRP's mechanistic roles, clinical associations, and translational potential in neuroinflammatory disorders, combining molecular, clinical, and imaging perspectives to refine its role within inflammation-driven neurodegeneration.", "authors": ["Buzgau Patrik", "Slevin Mark", "Barna Ioana Theodora", "Dénes Lóránd", "Tero-Vescan Amelia", "Russo Aurelio Pio", "Pastorello Ylenia"], "journal": "International journal of molecular sciences", "entry_date": "2026/02/13 01:10", "pub_date": "2026-01-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41683748/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Faculty of Medicine, George Emil Palade University of Medicine, Pharmacy, Science and Technology of Târgu Mureș, 540139 Târgu Mureş, Romania."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "41682639", "title": "Long-Term Response Without Immune-Related Adverse Events to Atezolizumab Treatment in TMB-High Thymoma: A Case Report from the KOSMOS-II Study.", "abstract": "Background: Thymic epithelial tumors (TETs), including thymic carcinomas and thymomas, are rare malignancies originating in the mediastinum. Therapeutic options remain limited for patients experiencing disease progression following platinum-based chemotherapy. High tumor mutational burden (TMB) is uncommon in thymic malignancies but may predict response to immunotherapy. We report a patient with TMB-high TET who participated in the KOSMOS-II study in South Korea and achieved a durable response to atezolizumab without developing immune-related adverse events (irAEs). Case presentation: A 73-year-old woman who had been treated for thymoma 20 years ago presented with a left neck mass. A biopsy of the neck mass confirmed recurrent thymoma, type B3, and her disease progressed despite platinum-based chemotherapy and subsequent pemetrexed treatment. TMB-high thymoma is very rare, but based on the next-generation sequencing (NGS) results, she was diagnosed with TMB-high (20.3 mutations/Mb) thymoma. As TMB-based immunotherapy is not approved in Korea, she was enrolled in the KOSMOS-II study and initiated on atezolizumab following molecular tumor board review. She achieved stable disease after three cycles and has remained progression-free for 14 months, completing 20 cycles without significant irAEs. Notably, her underlying myasthenia gravis did not worsen during treatment. Conclusions: This case demonstrates a favorable outcome with biomarker-directed ICI treatment in recurrent thymoma with limited treatment options, highlighting the importance of appropriate molecular markers to predict drug response. Although TMB-based immunotherapy is FDA-approved in the U.S., it remains unavailable in Korea, underscoring the need to explore flexible access pathways, including the potential use of immunotherapy beyond current indications, to improve treatment options for patients with life-threatening conditions.", "authors": ["Lee In Hee", "Kim Moonsik", "Seo An Na", "Lee Soo Jung", "Kim Jee Hyun"], "journal": "Journal of clinical medicine", "entry_date": "2026/02/13 01:06", "pub_date": "2026-01-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41682639/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Oncology/Hematology, School of Medicine, Kyungpook National University, Kyungpook National University Chilgok Hospital, Daegu 41404, Republic of Korea."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41682192", "title": "Perceived Fatigue and Associated Psychological Factors in Patients with Myasthenia Gravis.", "abstract": "Introduction: Myasthenia gravis (MG) is a chronic autoimmune disorder in which fatigue represents one of the most burdensome symptoms. This multidimensional manifestation extends beyond neuromuscular fatigability and has a substantial impact on daily functioning, mental health, and quality of life. The present study aimed to evaluate the perception of fatigue in patients with MG, with particular emphasis on its interference with everyday activities and the extent to which it is understood by others. Methods: The study included 67 MG patients (61.2% women, mean age 53 years) treated at the Neurology Outpatient Department of the University Clinical Center in Gdańsk. Data were collected using an author-developed survey and standardized instruments: Chalder Fatigue Scale (CFQ), MG-ADL, MG-QoL15, HADS-M, Mini-COPE, and ACDS. Results: More than 70% of patients reported constant or frequent fatigue. Higher fatigue severity was positively associated with functional impairment (MG-ADL) and lower quality of life (MG-QoL15). More than 70% of patients reported constant or frequent fatigue. Higher fatigue severity was moderately associated with greater functional impairment and poorer quality of life. The extent to which fatigue interfered with daily life was associated with higher levels of depressive symptoms, poorer self-rated health, and less favorable disease-related perceptions (acceptance and influence). In contrast, perceiving fatigue as being better understood by others was associated with lower anxiety and depression and more favorable disease-related perceptions (acceptance, control, understanding), while it was not significantly related to fatigue severity, functional status, or quality of life. Conclusions: Fatigue in myasthenia gravis is a prevalent symptom, closely related to functional impairment and reduced quality of life. Different aspects of fatigue perception show distinct psychosocial correlates, highlighting the importance of considering subjective and social dimensions of fatigue alongside its severity. These findings support the relevance of psychosocial factors in the comprehensive care of patients with MG.", "authors": ["Jung-Plath Weronika", "Skrzypek-Czerko Marcelina", "Zdun-Ryżewska Agata", "Bilińska Małgorzata", "Mędrzycka-Dąbrowska Wioletta"], "journal": "Healthcare (Basel, Switzerland)", "entry_date": "2026/02/13 01:04", "pub_date": "2026-01-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41682192/", "pub_types": ["Journal Article"], "affiliations": ["Division of Neurological and Psychiatric Nursing, Faculty of Health Sciences, Medical University of Gdańsk, Dębinki 7, 80-211 Gdańsk, Poland."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "4区"}, {"pmid": "41680656", "title": "Associations between myasthenia Gravis and outcomes following cardiac surgery: an analysis of the nationwide inpatient sample.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic neuromuscular disorder associated with increased susceptibility to perioperative complications. However, large population-based studies have not clearly characterized its impact on cardiac surgery outcomes. We therefore aimed to assess the in-hospital outcomes of MG patients undergoing cardiac surgery using a nationally representative database.\nMETHODS: This retrospective cohort study analyzed data from the Nationwide Inpatient Sample (NIS) between 2005 and 2020. Patients ≥ 18 years old who underwent coronary artery bypass grafting (CABG), valve surgery, or aortic repair were identified using ICD-9 and ICD-10 codes. Propensity score matching (PSM) was used to balance baseline characteristics. Multivariable regressions assessed associations between MG and in-hospital outcomes, including length of hospital stay (LOS), non-routine discharge, hospital costs, and complications.\nRESULTS: Following PSM, 823 patients with MG and 3,292 matched controls were included. After adjustment, patients with MG had significantly longer LOS (adjusted Beta [aBeta] = 0.89 days, 95% confidence interval [CI]: 0.56–1.23), greater risk of non-routine discharge (adjusted OR [aOR] = 1.35, 95% CI: 1.12–1.63), and higher total hospital costs (aBeta = 15.21, 95% CI: 11.75–18.68). They also had an increased risk of complications (aOR = 1.30, 95% CI: 1.08–1.56), including dysphagia (aOR = 2.39), respiratory failure (aOR = 1.39), mechanical ventilation (aOR = 1.30), and infection (aOR = 1.46). Furthermore, associations were most pronounced in patients undergoing isolated CABG, whereas estimates for valve and aortic procedures were less precise.\nCONCLUSION: Patients with MG undergoing cardiac surgery—particularly those receiving isolated CABG—experience greater morbidity, extended hospitalization, and increased healthcare costs. These findings support implementing enhanced perioperative protocols and multidisciplinary care pathways to mitigate excess complications, streamline recovery, and optimize resource use in this high-risk population.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s12871-026-03676-4.", "authors": ["Chen Po-Chih", "Masud Jakir Hossain Bhuiyan", "Chung Chen-Chih"], "journal": "BMC anesthesiology", "entry_date": "2026/02/12 23:44", "pub_date": "2026-02-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41680656/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Taipei Medical University-Shuang Ho Hospital, New Taipei City, Taiwan."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "41680628", "title": "Takotsubo cardiomyopathy in myasthenia gravis: a systematic review of case reports with subtype-based analysis.", "abstract": "BACKGROUND: Takotsubo cardiomyopathy (TTC) is a stress-induced cardiac disorder characterized by transient left ventricular dysfunction. Myasthenia gravis (MG), an autoimmune neuromuscular disease, can precipitate TTC during exacerbations such as myasthenic crises. However, the clinical features and outcomes of TTC associated with MG remain unclear.\nMETHODS: We conducted a systematic review by the PRISMA guidelines. A comprehensive search of PubMed, Web of Science, and Google Scholar was performed up to May 31, 2025, using terms related to TTC and MG. Case reports and series were included if they described patients with confirmed diagnoses of both MG and TTC, with MG exacerbation occurring at the time of TTC onset. Data were extracted and compared between apical and non-apical TTC subtypes. Statistical analyses included the Mann-Whitney U test and chi-squared or Fisher's exact test, as appropriate.\nRESULTS: A total of 38 articles comprising 40 cases were included. The median age was 69 years; 67.5% of the participants were female. Apical TTC was the most common subtype (71.8%). Myasthenic crisis was the most frequent TTC trigger (37.5%), while chest pain was reported in only 17.5% of cases. Mechanical ventilation and ICU admission were required in 95% and 97.4% of cases, respectively. Overall mortality was 17.5%. No significant differences were found between TTC subtypes; apical cases showed numerically higher troponin levels, which should be interpreted cautiously.\nCONCLUSIONS: TTC associated with MG exacerbation is a rare but serious condition with high rates of respiratory failure, ICU admission, and mortality. Emergency and critical care physicians should suspect TTC in MG patients presenting with hemodynamic instability or ECG abnormalities, even in the absence of chest pain.", "authors": ["Itagaki Hideya", "Hagino Takuro", "Endo Tomoyuki"], "journal": "International journal of emergency medicine", "entry_date": "2026/02/12 23:43", "pub_date": "2026-02-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41680628/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Division of Emergency and Disaster Medicine, Tohoku Medical and Pharmaceutical University Hospital, 1-12-1 Fukumuro, Miyagino-ku, Sendai, Miyagi, 983-8512, Japan. hideya.itagaki@gmail.com."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.0, "journal_quartile": "3区"}, {"pmid": "41675778", "title": "Postoperative hormonal modulation in a patient with granulosa cell tumor and myasthenia gravis: a gyneco-oncologic perspective.", "abstract": "INTRODUCTION AND IMPORTANCE: Perioperative management of granulosa cell tumors (GCTs) becomes significantly more complex in patients with neuromuscular conditions such as myasthenia gravis (MG). Herein, we describe a case of surgically managed stage I GCT in a woman with MG and hypothyroidism. This case is unique because the patient developed postoperative cardiac instability attributed to abrupt estrogen withdrawal after oophorectomy, which resolved rapidly with estrogen replacement.\nCASE PRESENTATION: A 38-year-old woman (gravida 0, para 0), married for 8 years, and who is a known case of MG and hypothyroidism presented to our center with a 2-week history of dull lower abdominal pain, intensifying during menstruation. The MRI raised a suspicion of malignancy after which the patient was taken for comprehensive staging surgery in which abdominal hysterectomy and bilateral salpingo-oophorectomy were performed. On post-op day 3, she developed palpitations, chest discomfort, progressive fatigue, and drowsiness. The patient was successfully managed with oral estradiol and discharged on post-op day 9.\nCLINICAL DISCUSSION: From a gynecologic oncologic perspective, comprehensive surgical staging remains the standard of care for apparent early-stage AGCT. In our case, the patient's co-morbid MG added significant complexity to the perioperative planning. The cardiac arrhythmia developed as a result of sudden withdrawal of estrogen due to oophorectomy was successfully managed with oral estradiol, and the patient was successfully discharged.\nCONCLUSION: Prompt recognition of post-oophorectomy hormonal withdrawal and judicious use of estrogen therapy may be essential in mitigating postoperative complications in hormone-sensitive tumors like AGCTs.", "authors": ["Mukherjee Manvi", "Mandal Sagar", "Shah Abhishek Kumar", "Malla Aastha", "Khaniya Bishal", "Pun Sunita"], "journal": "Annals of medicine and surgery (2012)", "entry_date": "2026/02/12 05:45", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41675778/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Gynecology and Obstetrics, Tribhuvan University Teaching Hospital, Kathmandu, Nepal."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41674783", "title": "Telitacicept demonstrates high probability of efficacy in myasthenia gravis: a Bayesian real-world study.", "abstract": "OBJECTIVE: This real-world study evaluated the efficacy and safety of telitacicept, a dual BAFF/APRIL inhibitor, in patients with generalized myasthenia gravis (MG).\nMETHODS: In this retrospective study, 17 myasthenia gravis patients on stable background therapy received weekly subcutaneous telitacicept (160-240 mg). Efficacy was evaluated at 12/24 weeks using a primary composite endpoint (≥2-point MG-ADL and ≥3-point QMG reduction). A pre-specified Bayesian analysis, updating a conservative prior with observed data, was employed to determine the posterior probability of treatment success and its 95% credible interval. Safety and steroid-sparing effects were also assessed.\nRESULTS: Of the 15 patients evaluable for efficacy (≥12 weeks treatment), 12 (80.0%) met the composite efficacy endpoint. Significant improvements were observed: mean MG-ADL decreased from 8.0 ± 4.4 to 4.2 ± 3.1 (p < 0.01); mean QMG decreased from 13.8 ± 5.5 to 7.6 ± 4.3 (p < 0.01). A robust steroid-sparing effect was demonstrated: the mean daily prednisone dose decreased by 76.0% (10.41 ± 7.30 mg to 2.50 ± 3.21 mg, p < 0.05), with 3 patients achieving complete withdrawal. Five patients attained Minimal Symptom Expression. Bayesian analysis yielded a posterior mean efficacy rate of 66.67% (95% CrI: 49.99-81.43%), with a probability (P) of exceeding 50% efficacy at 97.49%. Treatment was well-tolerated: only mild, transient AEs occurred (one injection-site reaction, one gastrointestinal event leading to withdrawal), and no serious adverse events (SAEs) were reported.\nCONCLUSION: This real-world study utilizing Bayesian analysis provides evidence supporting a high probability of efficacy for telitacicept in AChR-Ab-positive MG, demonstrating significant symptom improvement, substantial steroid-sparing effects, and favorable safety. These findings complement prior randomized controlled trial data and support the use of telitacicept in clinical practice. Study limitations include retrospective design and small sample size.", "authors": ["Duan Xinyi", "Xiao Haibing"], "journal": "Frontiers in neurology", "entry_date": "2026/02/12 05:36", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41674783/", "pub_types": ["Journal Article"], "affiliations": ["Shenzhen University Medical School, Shenzhen University, Shenzhen, Guangdong, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41671609", "title": "Immuno-deficient features of thymoma-associated myasthenia gravis patients with hypogammaglobulinemia: A condition comparable to Good's syndrome.", "abstract": "Good's syndrome (GS) is a rare immunodeficiency disorder associated with thymoma, characterized by hypogammaglobulinemia and recurrent infections; however, its clinical significance in thymoma-associated myasthenia gravis (TAMG) remains unclear. We retrospectively reviewed 30 patients with TAMG admitted to our center between January 2010 and March 2022. We defined GS-like immunodeficiency as serum IgG below the institutional cutoff of 861 mg/dL and a history of two or more infections requiring antimicrobial treatment; 11 patients (36.7%) met this definition. Compared with the remaining patients, the GS-like group had higher incidences of malignancy (45.5% vs. 5.3%, p = 0.016) and autoimmune diseases other than MG (36.4% vs. 5.3%, p = 0.047), lower peripheral lymphocyte counts (median 1100/μL vs. 2200/μL, p = 0.0051), and more frequent airflow obstruction defined by one second to forced vital capacity ratio of less than 70% (60.0% vs. 5.3%, p = 0.0026). Five deaths occurred in the GS-like group, and none in the other; median survival from the first antimicrobial-treated infection was 5.0 years. These findings imply that TAMG patients with GS-like immunodeficiency have a worse prognosis, underscoring the need for close monitoring and timely adjustments of MG management. (189 words).", "authors": ["Nakashima Saki", "Sakuishi Kaori", "Hara Manato", "Kawasaki Reiko", "Kakumoto Toshiyuki", "Ishiura Hiroyuki", "Toda Tatsushi"], "journal": "Journal of neuroimmunology", "entry_date": "2026/02/11 17:59", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41671609/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, the University of Tokyo, Tokyo, Japan; Department of Neurology, Teikyo University Chiba Medical Center, Chiba, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41669887", "title": "Associated Autoimmunity in Myasthenia Gravis in Denmark: A Nationwide Case-Control Study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoantibody-mediated neuromuscular disease often co-occurring with other autoimmune diseases (ADs). We aimed to determine the temporal relationship between other ADs and MG.\nMETHODS: We conducted a nationwide, population-based case-control study of MG patients and 10 age-, sex-, and index date-matched controls from 1985 to 2020. We used conditional logistic regression to estimate odds ratios (ORs) for AD diagnoses preceding MG, and Cox regression to calculate hazard ratios (HRs) for ADs succeeding MG. Analyses were stratified by sex, age group (≤ 50 and > 50 years), baseline comorbidity, and time intervals (0-5 and 5-10 years) before and after MG.\nRESULTS: Our study population included 2110 MG cases (1060 females) and 21,100 matched controls, with 27.4% ≤ 50 years old. Before the index date, 5.2% of MG patients and 2.7% of controls were diagnosed with another AD, yielding an OR of 1.9 (95% CI 1.5-2.3). After MG diagnosis, 5.0% of MG patients and 2.7% of controls received an AD diagnosis (HR 2.1, 95% CI 1.2-2.6), with an overrepresentation of patients ≤ 50 years or younger, females, and patients with a low comorbidity level. Most diagnoses occurred within 5 years before MG onset. The strongest associations were observed for autoimmune thyroiditis, systemic lupus erythematosus, and pernicious anemia.\nCONCLUSION: MG patients are twofold more likely to be diagnosed with another AD, especially MG patients ≤ 50 years and women, suggesting a shared autoimmune predisposition. Understanding the AD spectrum associated with MG could improve diagnostic accuracy and treatment strategies.", "authors": ["Nielsen Josefine Jul Jarbæk", "Levison Lotte Sahin", "Andersen Henning"], "journal": "European journal of neurology", "entry_date": "2026/02/11 05:23", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41669887/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Aarhus University Hospital, Aarhus, Denmark."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41669610", "title": "Diphtheria Presenting With Cranial Neuropathy: The Patch Unseen.", "abstract": "Diphtheria is a vaccine-preventable disease that remains endemic in several developing countries. Neurological complications, such as polyneuropathy, are rare but serious, often mimicking other neuromuscular disorders and leading to delayed diagnosis. Herein, we report the case of a 20-year-old incompletely immunised woman who presented with bilateral ptosis, multiple cranial neuropathies, and mild limb weakness following a prodrome of fever, headache, and peri-orbital pain. Initial investigations revealed albumin-cytologic dissociation in the cerebrospinal fluid, raising suspicion of Guillain-Barré syndrome, for which intravenous immunoglobulin was administered; however, there was no clinical improvement. Myasthenia gravis and botulism were also considered but excluded based on clinical and laboratory findings. Throat swab culture indicated the presence of Corynebacterium diphtheriae, confirming the diagnosis of diphtheritic polyneuropathy. The patient was treated with diphtheria antitoxin and erythromycin, resulting in an improvement of bulbar symptoms; nonetheless, ptosis persisted at discharge. Prophylaxis was provided to close contacts, and the patient was scheduled for diphtheria vaccination. This case highlights the significance of considering diphtheria in the differential diagnosis of acute cranial neuropathies in endemic regions and the role of vaccination in preventing such life-threatening complications.", "authors": ["Ghosh Sonali", "Hoque Shamsul", "Saha Soumodip", "Sadhukhan Saikat", "Ghosh Kaushik"], "journal": "Cureus", "entry_date": "2026/02/11 04:42", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41669610/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Emergency Medicine and Critical Care, Institute of Post-Graduate Medical Education and Research and Seth Sukhlal Karnani Memorial Hospital, Kolkata, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41668318", "title": "The Differential Diagnosis of Diplopia.", "abstract": "BACKGROUND: Diplopia is a common symptom of interdisciplinary significance that can lead to marked impairment of function. Its causes range from harmless to life-threatening conditions that must be precisely distinguished.\nMETHODS: For this CME review article, a PubMed search was conducted in an interdisciplinary collaboration of ophthalmologists and neurologists.\nRESULTS: Systematic history-taking and a structured clinical examination are the basis for topographic-anatomical diagnosis and the differentiation of peripheral and central causes. It is important to distinguish monocular from binocular diplopia. Monocular diplopia persists when one eye is covered and is not dangerous. Binocular diplopia may arise from disturbances at a variety of anatomical levels that can result from many different causes: disturbances of fusion in strabismus, diseases of the eye muscles such as thyroid eye disease or mitochondropathies, orbital trauma, impaired neuromuscular transmission in myasthenia gravis, fascicular or nuclear lesions of the three nerves that supply the extraocular muscles (oculomotor, trochlear, and abducens), supranuclear lesions \"above\" the cranial nerve nuclei, and cerebellar diseases. The most common causes, together accounting for ca. 70% of cases, are decompensated latent strabismus and cranial nerve palsies, followed by orbital, brainstem, and cerebellar diseases.\nCONCLUSION: Diplopia can be accurately diagnosed through a systematic approach that includes precise history-taking and clinical examination of eye position and eye movements. On this basis, there can be a targeted and specific search for the various underlying causes. When the patient's leading symptom is isolated diplopia, the ophthalmologist is generally the specialist to whom the primary care physician should turn next.", "authors": ["Lagrèze Wolf A", "Lischka Thomas", "Eckstein Anja", "Oeverhaus Michael", "Dieterich Marianne", "Strupp Michael"], "journal": "Deutsches Arzteblatt international", "entry_date": "2026/02/11 01:03", "pub_date": "2026-04-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41668318/", "pub_types": ["Journal Article", "Review"], "affiliations": [], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 7.1, "journal_quartile": "1区"}, {"pmid": "41667558", "title": "Application analysis of transfected cell method for detecting AChR antibodies in MG patients.", "abstract": "This study aimed to establish a technical process for detecting nicotinic acetylcholine receptor (nAChR) antibodies using the transfected cell method and evaluate its application in the serological diagnosis of myasthenia gravis (MG), thereby enhancing diagnostic efficiency. Cell transfection technology was used to introduce various nAChR subunit combinations into HEK293 cells for antibody detection. Indirect immunofluorescence (IIF) was utilized to test nAChR antibodies in serum samples from 85 MG patients, and the results were compared for consistency with those of enzyme-linked immunosorbent assay (ELISA).The combination of fetal and adult AChR subunits in transfected cells exhibited the highest sensitivity for detecting serum antibodies in patients with MG. The prepared cell slides demonstrated excellent consistency with the ELISA kit results for 85 MG patients, yielding a Kappa value of 0.769, indicating excellent agreement between the two methods. Co-transfection of multiple AChR subunits successfully generated a cell expressing clustered nAChRs, establishing a highly sensitive detection technique for nAChR antibodies. This technique is invaluable for serological detection of patients with MG, facilitating early disease detection, condition assessment, and therapeutic guidance.", "authors": ["Liu Wei", "Xia Zhenmin", "Hu Junyong", "Liu Gaijuan", "Zhou Lijing", "Xing Longlong", "Qiang Yaxin", "Lv Guanting"], "journal": "Scientific reports", "entry_date": "2026/02/10 23:25", "pub_date": "2026-02-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41667558/", "pub_types": ["Journal Article"], "affiliations": ["Hebei Gene-Health Biochip Tech. Co., Ltd, Shijiazhuang, 050035, Hebei Province, China. liuwei19850@163.com."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41666468", "title": "Acute Myasthenic-Like Illness: A Common Presentation of Neurotoxic Snakebite in a Tropical Region.", "abstract": "This is a retrospective analysis reviewing 106 neurotoxic snakebite cases that was conducted at a tertiary care hospital in northern India. Patient demographics, clinical presentations, treatment modalities, and outcomes were evaluated using standardized protocols. The study demonstrates the effectiveness of early medical intervention and protocol-based management in reducing snakebite mortality. These findings provide valuable insights in devising the novel terminology \"seasonal myasthenic-like syndrome\" for such a subset of patients. \"Seasonal myasthenic-like syndrome\" is proposed as a clinical descriptor for emergency settings in resource-limited tropical countries to facilitate rapid recognition and treatment initiation during high-risk periods.", "authors": ["Srivastava Saurabh", "Sharma Deepak", "Solanki Preeti", "Laraib Mohd", "Jain Payal", "Garg Ajai", "Jogi Hardeep", "Verma Deepak", "Kumar Ankur"], "journal": "The American journal of tropical medicine and hygiene", "entry_date": "2026/02/10 17:44", "pub_date": "2026-03-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41666468/", "pub_types": ["Journal Article"], "affiliations": ["Department of Internal Medicine, Government Institute of Medical Sciences, Greater Noida, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41664543", "title": "Immune Checkpoint Inhibitor-Related Myositis and Associated Triad Overlap Syndrome.", "abstract": "OBJECTIVE: Immune checkpoint inhibitor (ICI) myositis is a rare but a highly morbid condition, particularly with the ICI myositis triad syndrome of myositis, myocarditis, and myasthenia gravis. We report the clinical characteristics of ICI myositis and all-cause mortality in these patients.\nMETHODS: We performed a national retrospective cohort study of US veterans treated with an ICI between June 2011 and February 2022. Cases were identified by elevated creatinine kinase (CK) following ICI therapy and/or \"myositis\" in notes. Chart review determined if candidates had ICI-associated myositis and were subsequently classified as isolated ICI myositis or ICI triad syndrome.\nRESULTS: Of 29,296 veterans treated with ICIs, 68 (0.2%) ICI-induced myositis cases were identified, including 23 patients with ICI triad syndrome and 45 patients with isolated ICI myositis. Median survival duration for ICI triad syndrome was 2.5 (95% confidence interval [CI] 1.7-18.5) months in comparison to 20.4 (95% CI 6.2-60) months for isolated ICI myositis and 12.6 (95% CI 12.3-12.8) months median survival for patients treated with ICI without myositis. Patients with ICI triad syndrome had 60.0% mortality during the six months following initiation of ICI treatment, in comparison to 30.2% mortality in isolated ICI myositis and 31.5% mortality in patients without myositis. Six months after the first ICI treatment, subsequent mortality trends were similar in the three groups.\nCONCLUSION: ICI triad syndrome is associated with higher overall mortality and shortened median survival times during the first six months after initial ICI therapy, whereas isolated ICI myositis is associated with similar mortality outcomes compared to patients treated with ICI who did not develop myositis.", "authors": ["Rubino Selene", "Cannon Grant W", "Sauer Brian C", "Rojas Jorge", "Stoddard Gregory J", "Kunkel Gary A", "Walsh Jessica A", "England Bryant R", "Baker Joshua F", "Braaten Tawnie J"], "journal": "Arthritis care & research", "entry_date": "2026/02/10 02:44", "pub_date": "2026-02-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41664543/", "pub_types": ["Journal Article"], "affiliations": ["Mayo Clinic, Rochester, Minnesota."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.3, "journal_quartile": "2区"}, {"pmid": "41664151", "title": "Diagnostic performance and safety of the edrophonium test in myasthenia gravis: a retrospective case-control study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction. The diagnosis typically relies on clinical features, serologic testing, and neurophysiological assessment but provocation tests such as the edrophonium test can provide rapid supportive information; however, data on its diagnostic performance are limited. Thus, we aimed to evaluate the diagnostic performance and safety of the edrophonium test in MG.\nMETHODS: We conducted a retrospective case–control study of patients who underwent an edrophonium test at the Department of Neurology of the Medical University of Vienna between January 1991 and January 2024. We calculated sensitivity, specificity, and likelihood ratios and performed a multivariable logistic regression analysis to identify variables associated with a positive edrophonium test. Additionally, we assessed the safety of the edrophonium test.\nRESULTS: We included 182 patients with MG (41.2% female; mean age 55.8 years) and 324 controls (55.2% female; mean age 53.6 years). The edrophonium test had a sensitivity of 83.5% and a specificity of 87.7% in diagnosing MG. Patients with a decrement after repetitive nerve stimulation had higher odds of a positive response to the edrophonium test (OR 3.79, 95% CI 1.48–10.33, p = 0.0067), while odds were lower in patients with MuSK-MG compared to patients with AChR-MG (OR 0.08, 95% CI 0.01–0.82, p = 0.0254). Adverse events were reported in 58 patients (11.5%), in most of whom (53 patients, 91.4%) they were mild.\nCONCLUSIONS: We provide data on the diagnostic performance and safety of the edrophonium test, supporting its use as an adjunctive diagnostic test for the diagnosis of MG.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s42466-026-00468-6.", "authors": ["Keritam Omar", "Kräutler Julia Bettina", "Gharib Diana", "Jabir Elnayer Ahmed", "Weng Rosa", "Jäger Fiona", "Krenn Martin", "Paul Anna", "Rinner Walter", "Cetin Hakan", "Zimprich Fritz", "Zulehner Gudrun", "Rath Jakob"], "journal": "Neurological research and practice", "entry_date": "2026/02/10 00:12", "pub_date": "2026-02-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41664151/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Medical University of Vienna, Waehringer Guertel 18-20, Vienna, 1090, Austria."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41660448", "title": "Comparative outcomes of robotic- and video-assisted thoracoscopic surgery in thymectomy: a systematic review of implications for myasthenia gravis remission and long-term oncology.", "abstract": "BACKGROUND: Thymectomy is a cornerstone in the management of thymic epithelial tumors and myasthenia gravis (MG). While minimally invasive techniques like video-assisted thoracoscopic surgery (VATS) have gained prominence, robotic-assisted thoracoscopic surgery (RATS) has emerged as a technically advanced alternative. However, comparative long-term oncological outcomes between RATS and VATS remain underexplored. This review aims to compare RATS and VATS thymectomy regarding long-term outcomes, perioperative results, and cost.\nMETHODS: A systematic review was conducted following PRISMA guidelines, with a protocol registered in PROSPERO (CRD420251126351). PubMed/MEDLINE, Web of Science, and Cochrane Library were searched for comparative studies reporting long-term outcomes (≥12 months follow-up) of RATS versus VATS thymectomy. Risk of bias was assessed using the Newcastle-Ottawa Scale.\nRESULTS: Three retrospective cohort studies (430 patients: 181 RATS, 249 VATS) were included. No significant differences were found in long-term oncological outcomes: 5-year progression-free survival (RATS 87.7% vs. VATS 90.6%, P=0.504) and overall survival (87.7% vs. 92.2%) were comparable. Recurrence and reoperation rates were low and similar between groups. In MG patients, RATS was associated with a higher rate of complete stable remission (26% vs. 18%, P=0.06) and was an independent predictor of remission (hazard ratio: 0.472, P=0.049). Perioperatively, RATS demonstrated advantages including lower conversion rates (3% vs. 15%, P=0.03), shorter operative time (median 100 vs. 120 min, P=0.039), and reduced hospital stay (mean 1.3 vs. 2.4 days, P=0.01). Complication rates were similarly low. However, RATS was significantly more costly (¥68,122 vs. ¥37,886, P<0.001).\nCONCLUSIONS: RATS and VATS thymectomy yield equivalent long-term oncological outcomes. RATS offers superior perioperative recovery and may enhance neurological remission in MG patients, but at a significantly higher cost. The choice of technique should consider clinical context, surgeon expertise, and economic factors.", "authors": ["Barnawi Anas B", "Hajjar Waseem M", "Almaymuni Adel D", "Almudawi Abdulrahman Abdullah", "Alanazi Abdulmohsen S", "Bazarah Razan S", "AlAhmari Osama Mushabbab", "Al-Ahmari Osama Thamer", "Alhassoun Abdullah Ibrahim", "Alshehri Abdulelah F"], "journal": "Journal of thoracic disease", "entry_date": "2026/02/09 07:01", "pub_date": "2026-01-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41660448/", "pub_types": ["Journal Article", "Review"], "affiliations": ["College of Medicine, Imam Mohammad Ibn Saud Islamic University (IMSIU), Riyadh, Saudi Arabia."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41654846", "title": "AI-driven biomarker learning for the early diagnosis of neurodegenerative diseases: ABLEDx.", "abstract": "BACKGROUND: Tears are an easily accessible biofluid that reflects both emotional states and disease conditions. They are particularly enriched in extracellular vesicles (EVs), which carry proteins and nucleic acids relevant to neurological health. This makes tear EVs a promising source for biomarker discovery. However, limited sample volume and variability pose challenges for identifying reliable biomarkers for clinical diagnosis.\nRESULTS: We present AI-driven Biomarker Learning for the Early Diagnosis of Neurodegenerative Diseases (ABLEDx), which applies a conditional variational autoencoder (cVAE) to enhance proteomic analysis of tear EVs. This approach effectively addresses sample limitations and improves the identification of disease-associated biomarkers. Our results reveal that tear EVs capture molecular signals along the eye-brain axis, reflecting contributions from both ocular and central nervous system cells. ABLEDx identified clinically relevant protein modules, which were consistently elevated in patients with neurodegenerative diseases. Moreover, we recognize that KRAS is highly expressed in patients with Alzheimer's disease, Parkinson's disease, and ocular myasthenia gravis, and tear-EV-associated LRG1 and HSPG2 exhibit differentiation between Alzheimer's disease and Parkinson's disease.\nCONCLUSIONS: ABLEDx demonstrates the utility of combining AI with tear-EV proteomics for non-invasive biomarker discovery. This strategy enables early and real-time detection of neurodegenerative and ocular diseases, offering new opportunities for clinical diagnostics and translational medicine.", "authors": ["Zhu Qingfu", "Wu Songdi", "Huang Peilin", "Sun Qi", "Liu Zhongzhong", "Zhu Xinxi", "Lee Luke P", "Liu Fei"], "journal": "Journal of nanobiotechnology", "entry_date": "2026/02/07 23:26", "pub_date": "2026-02-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41654846/", "pub_types": ["Journal Article"], "affiliations": ["State Key Laboratory of Eye Health, Eye Hospital, Wenzhou Medical University, Wenzhou, 325027, China. qingfu.zhu@wmu.edu.cn."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "41653925", "title": "Lymphocyte alterations and elevated complement signaling are key features of refractory myasthenia gravis.", "abstract": "BACKGROUND: A significant proportion of patients with myasthenia gravis (MG) remain refractory to standard immunosuppressive therapy, and biomarkers to help guide treatment decisions are lacking. We investigated whether refractory disease is associated with a distinct circulating immune profile.\nMETHODS: We performed comprehensive immune phenotyping of peripheral blood from patients with acetylcholine-receptor-antibody-positive MG with differing treatment requirements and compared them with healthy controls. In a subset of refractory patients treated with anti-CD20 therapy, B cell reconstitution and clinical response were evaluated.\nFINDINGS: Refractory MG patients displayed the highest frequency of memory B cells and increased production of interleukin (IL)-6 and tumor necrosis factor alpha (TNF-α) upon Toll-like receptor/CD40 activation in vitro. These changes were accompanied by a dramatic loss of regulatory T cells (Tregs) and dendritic cells. Refractory MG was further characterized by elevated circulating complement proteins (C3, C5, and clusterin) and increased expression of complement receptors on lymphocytes. Following anti-CD20 therapy, residual plasmablasts persisted in circulation. Notably, a low baseline B cell frequency (<3%) was associated with poor clinical response to rituximab in refractory disease, although the sample size was limited.\nCONCLUSIONS: Our findings define a distinct immune signature in refractory MG, identify potential biomarkers of treatment resistance, and highlight plasma cell depletion, IL-6 or complement inhibition, and Treg expansion as promising therapeutic avenues.\nFUNDING: Funding was received from the NorthCare Charity, Myaware, the Academy of Medical Sciences, and the Neuromuscular Study Group.", "authors": ["Dodd Katherine C", "Baillie Kirsten", "Holt James K L", "Leite M Isabel", "Lin Lijing", "West Peter W", "Miller James A L", "Spillane Jennifer", "Viegas Stuart", "Zelek Wioleta M", "Sussman Jon", "Menon Madhvi"], "journal": "Med (New York, N.Y.)", "entry_date": "2026/02/07 18:41", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41653925/", "pub_types": ["Journal Article"], "affiliations": ["The Lydia Becker Institute for Immunology and Inflammation, University of Manchester, Manchester M13 9NT, UK; Manchester Centre for Clinical Neurosciences, the Northern Care Alliance NHS Foundation Trust, Salford M6 8HD, UK. Electronic address: katherine.dodd@manchester.ac.uk."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41653839", "title": "Longitudinal MuSK antibody levels may correlate with disease severity in MuSK myasthenia gravis.", "abstract": "BACKGROUND: In muscle-specific kinase antibody-positive myasthenia gravis (MuSK-MG), the clinical utility of MuSK antibody levels as a biomarker for disease severity is debated, with conflicting reports on its correlation with clinical status. This study aimed to clarify this association by applying a rigorous statistical model to a longitudinal dataset followed from an immunotherapy-naïve state.\nMETHODS: We conducted a retrospective longitudinal study on 6 patients with MuSK-MG tracked from their treatment-naïve baseline. The primary analysis used 103 data points where MuSK antibody levels and MG activities of daily living (MG-ADL) scores were available. A secondary analysis used the subset of 81 data points where total immunoglobulin G (IgG) levels were also concurrently measured. Generalized linear mixed-effects models (GLMM) were used to assess the intrapatient correlation, adjusting for interpatient variability by including a random intercept for each subject.\nRESULTS: First, the GLMM analysis of 103 data points revealed a strong positive intrapatient correlation between MuSK antibody levels and MG-ADL scores (P < 0.001). Second, in the subset analysis (n = 81), MuSK antibody levels remained positively and specifically correlated with MG-ADL scores (P = 0.002), whereas total IgG levels showed no independent correlation (P = 0.61) when included in the same model.\nCONCLUSIONS: MuSK antibody level, unlike total IgG, is a specific and valuable biomarker for monitoring intrapatient disease activity and therapeutic response. These findings strongly support the utility of serial MuSK antibody monitoring within individual patients.", "authors": ["Yasuda Manato", "Uzawa Akiyuki", "Ogaya Etsuko", "Handa Hideo", "Kurumada Kentaro", "Takasaka Kyosuke", "Akamine Hiroyuki", "Ozawa Yukiko", "Kuwabara Satoshi"], "journal": "Journal of neuroimmunology", "entry_date": "2026/02/07 18:10", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41653839/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41653661", "title": "Letter to editor: Early real-life experience on zilucoplan for generalized myasthenia gravis: ZILU25 multicenter observational study.", "abstract": "", "authors": ["Uzair Muhammad", "Momin Ali"], "journal": "Journal of the neurological sciences", "entry_date": "2026/02/07 18:07", "pub_date": "2026-03-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41653661/", "pub_types": ["Letter"], "affiliations": ["Khyber Medical College, Pakistan. Electronic address: muhammaduzair80085@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41648665", "title": "Real-world use of efgartigimod in acetylcholine receptor antibody-positive generalized myasthenia gravis: experience from two centers in Greece and Cyprus.", "abstract": "INTRODUCTION: Efgartigimod, an FcRn antagonist that reduces circulating immunoglobulin G (IgG), is approved for the treatment of acetylcholine receptor (AChR) antibody-positive generalized myasthenia gravis (gMG). While its efficacy has been demonstrated in randomized clinical trials, real-world data describing longitudinal use and management of efgartigimod in routine clinical practice are still emerging.\nMETHODS: We conducted a retrospective observational study across two neuromuscular referral centers, including adults with AChR antibody-positive gMG treated with intravenous efgartigimod between April 2023 and August 2025. Treatment was initiated across a range of real-world clinical scenarios, including refractory disease, non-crisis symptom relapse, corticosteroid tapering, maintenance of minimal-symptom expression, and bridging before thymectomy or initiation of conventional immunosuppression. Retreatment intervals were individualized based on clinical course. Clinical outcomes, corticosteroid use, serological markers, adjunctive therapies, and safety events were analyzed descriptively.\nRESULTS: Thirteen patients received a total of 52 efgartigimod treatment cycles. Most patients experienced repeated improvement in MG-Activities of Daily Living (MG-ADL) during treatment cycles, although clinical status varied over time. Corticosteroid doses were reduced in the majority of patients during follow-up. Episodes of clinically significant worsening occurred outside the setting of myasthenic crisis and were managed with established rescue therapies, after which efgartigimod could often be resumed. Treatment was generally well tolerated.\nCONCLUSION: This study describes how efgartigimod is integrated into routine clinical practice as part of longitudinal disease management for AChR antibody-positive gMG. Real-world use encompassed diverse clinical scenarios and required individualized retreatment decisions and ongoing reassessment. These findings highlight the role of FcRn blockade as a flexible therapeutic option that complements established therapy in everyday care.", "authors": ["Tsokkos Tasos", "Strataki Eleni", "Tzavella Dimitra", "Zamba-Papanicolaou Eleni", "Kleopa Kleopas A", "Zouvelou Vasiliki"], "journal": "Frontiers in neurology", "entry_date": "2026/02/06 06:20", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41648665/", "pub_types": ["Journal Article"], "affiliations": ["Center for Neuromuscular Disorders, The Cyprus Institute of Neurology and Genetics, Nicosia, Cyprus."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41645666", "title": "Myasthenia gravis following the initiation of statin therapy: A multinational self-controlled case series study.", "abstract": "BACKGROUND: Evidence regarding the risk of new-onset myasthenia gravis (MG) following statin therapy initiation is limited.\nOBJECTIVES: To investigate this potential adverse effect using multinational real-world population-based data.\nMETHODS: A self-controlled case series (SCCS) study was conducted using electronic medical records and claims databases from Hong Kong, the United Kingdom (UK) and Japan. Individuals aged ≥18 years with first diagnosis of MG and initiated statins were included. Conditional Poisson regression compared the risk of MG in different risk periods (up to 2 years after initiation) with non-exposure period, adjusted for age. Pooled results based on meta-analysis across all study sites were reported.\nRESULTS: In total, 2267 MG cases were analysed. Combined across all study sites, a significantly increased risk of incident MG was observed during the first year after statin initiation compared to non-exposure period, with a higher risk from Days 0-179 (pooled incidence rate ratio [IRR] [95% CI]: 2.662 [1.276-5.553]) than Days 180-364 (1.407 [1.014-1.954]). No increased risk of MG was observed more than 1 year after statin initiation (1.011 [0.848-1.206]). Moreover, the magnitude of MG risk elevation within the first 180 days after statin initiation was more pronounced with higher intensity statin regimens.\nCONCLUSION: In this multinational SCCS study, statin initiation may be associated with increased risk of new-onset MG during the first 6-12 months, with greater magnitude of risk elevation for higher intensity statin therapy. Consideration of the possibility of new-onset MG may be advisable within first 6-12 months after initiating statins, especially for medium-to-high-intensity statin therapy.", "authors": ["Yan Vincent Ka Chun", "Xu Wanchun", "Taniguchi Yuta", "Fung Kwun Kei", "Chan Koon Ho", "Lau Gary Kui Kai", "Chui Celine Sze Ling", "Lai Francisco Tsz Tsun", "Li Xue", "Iwagami Masao", "Masuda Rie", "Tamiya Nanako", "Dorajoo Sreemanee Raaj", "Neo Jing Wei", "Chan Esther Wai Yin", "Wong Ian Chi Kei", "Wan Eric Yuk Fai"], "journal": "Journal of internal medicine", "entry_date": "2026/02/06 03:04", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41645666/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Centre for Safe Medication Practice and Research, Department of Pharmacology and Pharmacy, Li Ka Shing Faculty of Medicine, The University of Hong Kong, Hong Kong, Hong Kong Special Administrative Region, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 9.2, "journal_quartile": "1区"}, {"pmid": "41644100", "title": "Incidence and clinical characteristics of concurrent thyroid eye disease and ocular myasthenia gravis.", "abstract": "OBJECTIVE: To examine the incidence and clinical characteristics of concurrent thyroid eye disease (TED) and myasthenia gravis (MG) and identify potential diagnostic clues for this rare coexistence.\nMETHODS: A retrospective observational study included 15 patients diagnosed with both TED and MG between May 2013 and July 2025. The diagnosis of TED was based on Bartley's criteria, and MG was diagnosed using criteria from the Japanese Ministry of Health, Labour, and Welfare. Clinical data, including ocular alignment, eyelid position, thyroid function, antibody profiles, imaging findings, treatment, and outcomes, were reviewed.\nRESULTS: Of 6 576 TED patients, 15 (0.23%) were diagnosed with concurrent MG, and 12 (0.18%) had isolated ocular MG (OMG). Ptosis was observed in 9 patients (60.0%), and vertical strabismus was the most common pattern (53.3%). Exotropia, an unusual presentation in TED, was seen in 6 patients (40.0%). Extraocular muscle inflammation was confirmed on magnetic resonance images in 11 patients (73.3%). Steroid pulse therapy, administered to 8 patients (53.3%) for active TED, also improved MG symptoms. At a mean follow-up of 43.8 ± 36.6 months, 10 patients (66.7%) showed significant improvement in ptosis and/or diplopia.\nCONCLUSIONS: Concurrent TED and MG, while rare, present overlapping features that can complicate diagnosis. Atypical signs, such as ptosis with diurnal variability and exotropia with vertical misalignment in TED patients, should raise suspicion for MG.", "authors": ["Abumanhal Muhammad", "Habaluyas Chrisha Faye", "Umezawa Naomi", "Takahashi Yasuhiro"], "journal": "Canadian journal of ophthalmology. Journal canadien d'ophtalmologie", "entry_date": "2026/02/05 19:20", "pub_date": "2026-02-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41644100/", "pub_types": ["Journal Article"], "affiliations": ["Department of Oculoplastic, Orbital and Lacrimal Surgery, Aichi Medical University Hospital, Nagakute, Aichi, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41642475", "title": "Global Research Landscape in T Cells and Myasthenia Gravis: Trends, Collaborations, and Future Directions.", "abstract": "Myasthenia gravis (MG) has emerged as a significant global public health concern. A growing number of studies have focused on T cells in the pathophysiology of MG given that they regulate the immune response and affect autoantibody formation, which leads to the progression of the disease. Currently, there are no comprehensive studies on T cells and MG. Therefore, it is imperative to address this key area through bibliometric analysis and exploration of molecular mechanisms, which will provide essential guidance for investigating fundamental pathological processes and enhancing clinical management. Firstly, we investigated the Web of Science™ Core Collection and the PubMed database for relevant literature, assessing temporal and spatial distribution, the leading research center, key investigators, influential journals, topic hotspot evolution, references, and keywords. CiteSpace and VOSviewer were used for visualizing. Over the past decade, research on T cells and MG has gained curiosity and enthusiasm. Then, we reviewed key research areas which are the roles of T cell subsets, B cell subsets, cytokines, ICI-MG, and new immunotherapy, etc. Notably, we also highlighted emerging T cell-related research fields, such as CAR-T cell therapy and extracellular vesicle-based drug delivery. These cutting-edge directions hold particular promise for promoting interdisciplinary studies and personalized therapies, ultimately bridging the gap between foundational research and clinical implementation.", "authors": ["Jiao Yingying", "Lin Zien", "Fan Shiwen", "Ji Aidong", "Cai Xiaoqing", "Wu Yaoqi", "Song Yafang"], "journal": "Molecular neurobiology", "entry_date": "2026/02/05 12:17", "pub_date": "2026-02-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41642475/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Science, and Technology Innovation Center, Guangzhou University of Chinese Medicine, Baiyun District Airport Road Number 12, Guangzhou, Guangdong, 510006, People's Republic of China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "41642058", "title": "Multisystemic Malakoplakia Revealed by 18F-FDG PET/CT: A Case of Concomitant Bilateral Osteomyelitis and Genitourinary Involvement.", "abstract": "We present the case of a 43-year-old man with a history of myasthenia gravis on immunosuppressive therapy, mycophenolate mofetil, and recent hospitalization for prostatic abscess and recurrent left orchiepididymitis. 18F-FDG PET/CT demonstrated increased uptake in multiple intramedullary bone regions in the lower limbs, in the left testicle, in the prostate and in several retroperitoneal lymph nodes, all presenting with calcifications on CT. Based on PET/CT, prostate biopsy and bone bacterial cultures, a diagnosis of prostatic malakoplakia with concomitant testicular and lymph nodes involvement was made, complicated by bilateral lower limb osteomyelitis. This case highlights the potential value of 18F-FDG PET/CT in characterizing the extent of involvement and guiding the diagnosis of this rare multisystemic entity.", "authors": ["Foufa Yasser", "Maliha Peter George", "Morin Marc-André"], "journal": "Clinical nuclear medicine", "entry_date": "2026/02/05 09:43", "pub_date": "2026-01-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41642058/", "pub_types": ["Journal Article"], "affiliations": ["Department of Nuclear Medicine, Centre Hospitalier de l'Université de Montréal."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 9.6, "journal_quartile": "2区"}, {"pmid": "41639896", "title": "Incidental finding of \"H\"-type duplex gallbladder: a case report.", "abstract": "BACKGROUND: Gallbladder duplication is a rare congenital anomaly resulting from abnormal bifurcation of the caudal bud during embryogenesis. It may cause diagnostic and surgical challenges. Classification systems of gallbladder duplication are based on cystic duct anatomy. Though often asymptomatic, it can be associated with complications such as cholelithiasis.\nCASE PRESENTATION: We report the case of a 22-year-old North African male presenting to the emergency department with a left renal colic episode. He complained of left lumbar pain with typical radiation and no other associated symptoms. The patient has a medical history of myasthenia gravis and major depressive disorder. Physical examination revealed left lumbar and iliac tenderness without any other notable findings. The patient was initially referred to the radiology department for a computed tomography scan to investigate potential renal colic and rule out a surgical emergency. The computed tomography scan identified a nonobstructive left renal calculus and a duplicated gallbladder. An abdominal ultrasound was performed for further evaluation, confirming the gallbladder duplication and ruling out gallstones or cholecystitis. To obtain better visualization of the biliary tree and assess for any additional anatomical anomalies, magnetic resonance imaging with magnetic resonance cholangiopancreatography was conducted. Magnetic resonance cholangiopancreatography confirmed a type H gallbladder duplication.\nCONCLUSION: Diagnostic methods, including ultrasound, computed tomography scan, and magnetic resonance imaging, help identify gallbladder duplication. Magnetic resonance cholangiopancreatography is considered the gold standard for detailed biliary tract imaging.", "authors": ["Chami Khazraji Idriss", "El Houari Zainab", "Charif Saibari Rayhana", "Bennani Samia", "El Hattab Meryem", "Bouknani Nawal", "Rami Amal"], "journal": "Journal of medical case reports", "entry_date": "2026/02/05 00:02", "pub_date": "2026-02-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41639896/", "pub_types": ["Journal Article"], "affiliations": ["Department of Diagnostic and Interventional Radiology, Cheikh Khalifa International University Hospital, Casablanca, Morocco. idriss.chami@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41638015", "title": "Evaluation of neuromuscular blocker use in myasthenia gravis patients undergoing rapid sequence intubation.", "abstract": "PURPOSE: Myasthenia gravis (MG) pathophysiology and drug-drug interactions with cholinesterase inhibitors can make patients both relatively sensitive and resistant to neuromuscular blocking agents (NMBAs). NMBA dose adjustments in MG patients undergoing rapid sequence intubation (RSI) are described in anesthesia literature but not outside of the operating room (OR). This study sought to characterize NMBA use in MG patients undergoing RSI outside of the OR.\nMETHODS: Retrospective, observational, multicenter study of MG patients undergoing RSI outside of the OR from January 2011-September 2023. Patient demographics, NMBA used and dose, and post-intubation monitoring were collected. Data are reported descriptively.\nRESULTS: Forty-four cases were included; median age 74 years (IQR 59.8-81.0), 31.8% receiving pyridostigmine, 88.6% intubated for respiratory failure, 81.8% received rocuronium. Only 11 cases (25%) had an NMBA dose adjustment. No cases experienced inadequate paralysis. Of the 24 cases (54.5%) with monitoring within the expected NMBA recovery timeframe, 75% had documented recovery. Of these, only one case had an NMBA dose adjustment. Five cases (11.4%) experienced possible prolonged paralysis based on study definitions; one case with NMBA dose adjustment.\nCONCLUSIONS: Most cases did not receive an NMBA dose adjustment for MG. There were limited neurologic and neuromuscular assessments available post-intubation. Cases of possible prolonged paralysis were identified. The necessity of adjusting NMBA doses in MG patients undergoing RSI remains unclear and warrants further study. Clinicians should be aware of the potential for unpredictable NMBA response in MG and need for timely monitoring and sedation and analgesia in the immediate post-intubation period.", "authors": ["Polito Nick B", "Fellows Shawn E", "Knapp Andrew S", "Acquisto Nicole M"], "journal": "The American journal of emergency medicine", "entry_date": "2026/02/04 18:08", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41638015/", "pub_types": ["Journal Article"], "affiliations": ["Emergency Medicine Clinical Pharmacist, Department of Pharmacy, Highland Hospital, 1000 South Ave, Rochester, New York 14620, USA. Electronic address: nicholas_polito@urmc.rochester.edu."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41637180", "title": "Neurologists' decision-making in the management of generalised myasthenia gravis: Therapeutic inertia and treatment choices.", "abstract": "The evolving landscape of generalised myasthenia gravis (gMG) treatment with new targeted immunotherapy options presents challenges for neurologists and potentially leads to therapeutic inertia (TI), the failure to initiate or intensify treatment when therapeutic goals are not met. This study aimed to assess neurologists' therapeutic decision-making process in gMG and its influencing factors. A cross-sectional, web-based study was conducted, involving 149 neurologists (mean age [standard deviation]: 39.0 [9.4] years; 54.4% male; median MG experience [interquartile range]: 7 [3-15] years). Participants responded to 8 simulated case scenarios, 7 of which assessed TI. Overall, 79.9% of neurologists (n = 119/149) exhibited TI in at least 2 of the 7 scenarios. Multivariate analysis revealed that lower organisational support (odd ratio [OR] = 0.308, 95%CI:0.109-0.870, p = 0.0262) and greater reluctance to adopt new treatments (OR = 0.015, 95%CI:0.001-0.739, p = 0.0347) were significant predictors of TI. Understanding these factors is crucial for optimising gMG treatment decisions, underscoring the importance of updated guidelines and continued professional education.", "authors": ["Gutiérrez-Gutiérrez Gerardo", "Gómez-Ballesteros Rocío", "Ares Adrián", "Villaverde Ramón", "Reyes Virginia", "Armangué Thaís", "Díaz-Abós Paola", "Rebollo Pablo", "Canal Neus", "Querol Luis", "Maurino Jorge", "Cortés-Vicente Elena"], "journal": "Journal of neuromuscular diseases", "entry_date": "2026/02/04 12:33", "pub_date": "2026-02-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41637180/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Hospital Universitario Infanta Sofía, Madrid, Spain."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41634421", "title": "Delayed recovery following myasthenic exacerbation and subsequent endplate-protecting treatment.", "abstract": "Endplate-protecting therapies have improved treatment of myasthenia gravis and indicate a rapid onset of their treatment effect. Currently, these substances can be used following myasthenic exacerbation (ME). Clinical worsening due to ME however often results in prolonged recovery. We here evaluated the treatment courses of patients having received endplate-protecting treatment following ME. Among 12 patients with ME described here, seven received endplate-protecting therapies. Our findings indicate that acceptable recovery usually takes nine months. In the lights of recent trials for treatment of myasthenia, our findings implicate that the effectiveness of novel substances should be judged only after sufficient observation periods.", "authors": ["Mück Anna", "Genau Sonja", "Emde Julia", "Best Christoph", "Pfeuffer Steffen", "Krämer Heidrun H"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/02/03 23:33", "pub_date": "2026-02-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41634421/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Justus Liebig University, Klinikstrasse 33, D-35392, Giessen, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41633824", "title": "Frequent co-occurrence of AChR-positive myasthenia gravis in facioscapulohumeral muscular dystrophy suggests a novel disease association.", "abstract": "", "authors": ["McMacken Grace", "Ashraghi Mohammad", "Keyes Lucas", "Jacob Saiju", "Hewamadduma Channa", "Carmichael Caroline", "Dodd Katherine C", "Burke Georgina", "Viegas Stuart", "Buckley Camilla", "McKnight Amy Jayne", "Farrugia Maria", "Leite Maria Isabel", "McConville John"], "journal": "Journal of neurology, neurosurgery, and psychiatry", "entry_date": "2026/02/03 21:33", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41633824/", "pub_types": ["Letter"], "affiliations": ["Centre for Public Health, Queen's University Belfast, Belfast, UK g.mcmacken@qub.ac.uk."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41631867", "title": "Improved Neuromuscular Transmission Following Thymectomy in Juvenile Myasthenia Gravis: A Case Series.", "abstract": "INTRODUCTION/AIMS: Juvenile myasthenia gravis (JMG) patients report symptomatic improvement following thymectomy; however, there is a lack of published literature on biomarkers for interval improvement. This study aimed to investigate the utility of single-fiber electromyography to quantify changes post-thymectomy.\nMETHODS: This was a retrospective medical record review of JMG patients who underwent thymectomy at Children's Healthcare of Atlanta between 2014 and 2024. Pre- and post-thymectomy orbicularis oculi jitter values and Myasthenia Gravis Activities of Daily Living (MG-ADL) scores were recorded. A two-sided paired t-test was used to compare results pre- and post-thymectomy and Pearson's correlations were calculated.\nRESULTS: Twelve JMG patients (6 female) with a mean age at diagnosis of 12.9 ± 4.5 (range 1.6-17.1) years, positive acetylcholine receptor antibodies, and normal thymus imaging underwent thoracoscopic thymectomy at 15.2 ± 3.3 (range 7.4-18.2) years. Post-thymectomy, there was a statistically significant decrease in mean jitter (interval 7.3 ± 7.4 months, mean difference -33.2 ± 32.6 μs, p = 0.04, n = 7) and MG-ADL scores (interval 2.5 ± 2.1 years, mean difference -2.2 ± 2.5, p = 0.02, n = 11). There were no significant correlations between timing of thymectomy after diagnosis and the change in mean jitter (r = 0.11, p = 0.8, n = 7) and MG-ADL (r = -0.19, p = 0.58, n = 11). No major post-surgical complications were observed.\nDISCUSSION: Thymectomy is well-tolerated and leads to both objective and subjective improvement in JMG patients.", "authors": ["Givens Natalie", "Verma Soham", "Moghadam Sahar", "Meisel Jonathan", "Hoeting Jennifer A", "Verma Sumit"], "journal": "Muscle & nerve", "entry_date": "2026/02/03 09:13", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41631867/", "pub_types": ["Journal Article"], "affiliations": ["Emory University School of Medicine, Atlanta, Georgia, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41631236", "title": "Successful use of immune checkpoint Inhibition in a patient with myasthenia gravis and recurrent endometrial cancer- expanding access beyond initial clinical trial eligibility.", "abstract": "BACKGROUND:  The use of immune checkpoint inhibitors (ICI) has transformed the treatment of patients with advanced stage or recurrent mismatch repair deficient (dMMR) endometrial cancer. Importantly, however, ICI are commonly contraindicated in patients with preexisting autoimmune conditions. Immune related myasthenia gravis (irMG) is the second most common neurologic immune related adverse event (irAE) with ICIs, and there have been several case reports of ICI induced myasthenia gravis (MG) as well as cases of MG flares associated with ICI treatment.\nCASE PRESENTATION: This case report describes the successful use of pembrolizumab in combination with carboplatin and paclitaxel and then continued as maintenance in a 70-year-old patient with recurrent dMMR endometrial cancer and myasthenia gravis. Utilizing a multidisciplinary treatment team, the patient received plasmapheresis every 3 weeks, preceding pembrolizumab infusion, without clinical evidence of MG symptom flare. The patient remains in clinical remission 8 months following completion of maintenance therapy.\nCONCLUSION: Pembrolizumab was safely administered, without identifiable irAEs, and a robust clinical response in a patient with dMMR EC, where the clinical benefit of immunotherapy has been well established. Historically, patients with MG have been excluded from enrollment and treatment on clinical trials. Real world, pragmatic, clinical data may help inform expanded utilization beyond trial eligibility criteria.", "authors": ["Julian Olivia N", "Christofsen Anika", "Eskander Ramez N"], "journal": "Gynecologic oncology reports", "entry_date": "2026/02/03 04:20", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41631236/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Division of Gynecologic Oncology, Department of Obstetrics, Gynecology and Reproductive Sciences University of California, San Diego, Rebecca and John Moores Cancer Center, 3855 Health Sciences Dr, San Diego, CA 92037, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41630490", "title": "Electrodiagnostic Approach to Defects of Neuromuscular Transmission.", "abstract": "Neuromuscular junction (NMJ) disorders such as myasthenia gravis, Lambert-Eaton myasthenic syndrome, and botulism are characterized by impaired synaptic transmission leading to weakness. This review examines the electrodiagnostic evaluation of these conditions, emphasizing the importance of techniques such as repetitive nerve stimulation (RNS) and single-fiber electromyography (SFEMG) for confirming the diagnosis and distinguishing presynaptic from postsynaptic defects. The reduced safety factor of neuromuscular transmission (NMT) in postsynaptic disorders produces a decrement in compound muscle action potential (CMAP) amplitude and area with low-frequency stimulation, whereas presynaptic disorders show small baseline CMAPs that increase markedly in amplitude and area (postactivation facilitation) after brief exercise or during high-frequency stimulation. SFEMG, the most sensitive test of abnormal NMT, measures neuromuscular jitter-temporal variability in action potential generation-and also reflects a compromised safety factor. Fiber density remains normal in primary NMJ disorders, distinguishing them from conditions with neuropathic reinnervation, such as motor neuron disease. Proper performance and interpretation of these electrodiagnostic studies are essential for accurate diagnosis, assessment of disease severity, and guiding management of NMJ disorders.", "authors": ["Morena Jonathan M"], "journal": "Muscle & nerve", "entry_date": "2026/02/03 02:23", "pub_date": "2026-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41630490/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Duke University, Durham, North Carolina, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41628617", "title": "[Myasthenic syndromes: retrospective analysis of two patient cohorts].", "abstract": "Myasthenia gravis (MG) and Lambert-Eaton myasthenic syndrome (LEMS) are rare autoimmune-mediated neuromuscular diseases characterized by muscle weakness. Although various treatment options are available for MG, a subset of patients may be considered treatment-refractory, with differing definitions of this status present in the scientific literature. This monocentric, retrospective cohort study investigated 200 patients with MG and 15 patients with LEMS. Data on clinical characteristics, antibody status, treatment response, and concomitant diseases were collected. MG patients who received at least three different immunosuppressants during their disease history were categorized as treatment-refractory. Statistical analyses were conducted using SPSS.11.5% of MG patients (n=23) were classified as treatment-refractory. According to the MGFA classification, these patients were more likely to exhibit severe disease, have a higher prevalence of MuSK antibodies, and experience increased cardiovascular comorbidities. The results indicate that patients in the treatment-refractory group exhibited severe disease progression more frequently according to the MGFA classification and required escalation therapies more often. However, a standardized definition of therapy-refractory MG is not yet available.\nMyasthenia gravis (MG) und das Lambert-Eaton-Myasthenie-Syndrom (LEMS) sind seltene, autoimmun-vermittelte neuromuskuläre Erkrankungen, die mit belastungsabhängiger Muskelschwäche einhergehen. Während für MG verschiedene Therapieoptionen existieren, lässt sich eine Untergruppe der Patienten als Therapie-refraktär einstufen, wobei in der wissenschaftlichen Literatur unterschiedliche Definitionen dieser Therapie-Refraktärität existieren. In dieser monozentrischen, retrospektiven Kohortenstudie wurden 200 MG-Patienten und 15 LEMS-Patienten untersucht. Es wurden Daten zu klinischen Merkmalen, Antikörperstatus, Therapieansprechen und Begleiterkrankungen erfasst. Als Therapie-refraktär galten diejenigen MG-Patienten, die in ihrem Krankheitsverlauf mindestens drei verschiedene Immunsuppressiva erhielten. Statistische Analysen wurden mit SPSS durchgeführt.11,5% der MG-Patienten (n=23) wurden als Therapie-refraktär klassifiziert. Diese wiesen häufiger eine schwere Krankheitsausprägung gemäß MGFA-Klassifikation, eine höhere Prävalenz von MuSK-Antikörpern sowie vermehrt kardiovaskuläre Komorbiditäten auf. Die Ergebnisse zeigen, dass Patienten in der Therapie-refraktären Gruppe häufiger schwere Krankheitsverläufe gemäß der MGFA-Klassifikation aufwiesen und häufiger Eskalationstherapien benötigten. Eine einheitliche Definition des Begriffes der Therapie-refraktären MG ist jedoch nicht verfügbar.", "authors": ["Lorenz Felix Maximilian Xaver", "Schoser Benedikt"], "journal": "Fortschritte der Neurologie-Psychiatrie", "entry_date": "2026/02/02 18:43", "pub_date": "2026-02-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41628617/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Friedrich-Baur-Institut, Ludwig-Maximilians-Universität München, München, Germany."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41627711", "title": "Rozanolixizumab-induced aseptic meningitis in AChR-thymoma associated myasthenia gravis.", "abstract": "", "authors": ["Zouvelou Vasiliki", "Patas Kostas", "Strataki Eleni", "Froukala Elisavet", "Dimitrakopoulos Antonios"], "journal": "Acta neurologica Belgica", "entry_date": "2026/02/02 11:23", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41627711/", "pub_types": ["Letter"], "affiliations": ["1st Neurology Department, Eginition Hospital, National and Kapodistrian University of Athens, 74 Vas. Sophias Ave., Athens, 11528, Greece. vzouvelu@med.uoa.gr."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41623245", "title": "Corticosteroid-Refractory Juvenile Myasthenia Gravis: Treatment Responses and Prognosis in a Large Chinese Cohort.", "abstract": "INTRODUCTION/AIMS: Some patients diagnosed with juvenile myasthenia gravis (JMG) have corticosteroid-refractory myasthenia gravis (CRMG). The aim of this study was to evaluate the biomarkers of corticosteroid (CS) responsiveness and refractoriness in children, and the overall prognosis of patients after receiving nonsteroidal immunosuppressants (ISs).\nMETHODS: This cross-sectional study was conducted at the Department of Pediatrics, Xiangya Hospital, Central South University. Data of the patients diagnosed with JMG from 2010 to 2023 were collected and analyzed.\nRESULTS: Two hundred and seventy-five patients were included in this study; 215 utilized CS, of whom 44.2% had CRMG. Ptosis only was an independent predictor of CS responsiveness (OR = 2.13, SE = 0.36, OR 95% CI = 1.05-4.32, p value = 0.003). The presence of acetylcholine receptor antibodies (AChR-Abs) was an independent predictor of CS refractoriness (OR = 2.78, SE = 0.48, OR 95% CI = 1.09-7.05, p value = 0.033). At last follow-up, 65.8% of the CRMG patients responded to ISs including tacrolimus, azathioprine, intravenous immunoglobulin, mycophenolate mofetil, and rituximab. About 71.0% of the patients that received ≤ 2 ISs were responders; however, only 14.3% of the patients that received subsequent ISs responded.\nDISCUSSION: This study provides an approximate prevalence of CRMG in children, as well as predictors of CS responsiveness and refractoriness, which can guide clinicians in prescribing alternative ISs in a timely manner. It can also help researchers understand the burden of CRMG in children when developing promising new therapies.", "authors": ["Kessi Miriam", "Huang Xi", "Wang Guoli", "Zhang Wen", "Zhang Ciliu", "He Fang", "Peng Jing", "Yin Fei", "Yang Lifen"], "journal": "Muscle & nerve", "entry_date": "2026/02/02 06:23", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41623245/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatrics, Xiangya Hospital, Central South University, Changsha, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41622196", "title": "Clinical characteristics and treatment outcomes in thymoma- related aplastic anemia: a case report and literature review.", "abstract": "Thymoma-related aplastic anemia is a rare entity. This article retrospectively analyzes the clinical features and treatment course of a patient who developed aplastic anemia (AA) post-thymectomy, complemented by a systematic review of relevant literature. A 47-year-old female was diagnosed with thymoma, myasthenia gravis (MG), and severe AA (SAA). SAA onset occurred two weeks after total thymectomy, and the patient ultimately succumbed to concurrent COVID-19 infection following allogeneic hematopoietic stem cell transplantation (allo-HSCT). We also reviewed the clinical characteristics, treatment strategies, and prognosis of 47 thymoma-related aplastic anemia patients reported in the literature. AA may present prior to thymoma diagnosis, concurrently with thymoma, or post-thymectomy. Some patients progress to pure red cell aplasia (PRCA) and/or megakaryocytic aplasia, often following prior chemotherapy or radiotherapy. Similar to Good syndrome and PRCA, thymectomy fails to alleviate AA, and spontaneous improvement is rare. Treatment options for thymoma-related aplastic anemia include cyclosporine A (CsA) monotherapy, CsA combined with glucocorticoids, thrombopoietin receptor agonists (TPO-RAs), and allo-HSCT. However, regimens of cyclophosphamide plus methylprednisolone and glucocorticoid monotherapy show limited efficacy. The overall one-year mortality rate is alarmingly high at 29.8%. For young thymoma-related aplastic anemia patients with SAA and suitable donors, allo-HSCT remains the preferred treatment.", "authors": ["Sun Shuxiang", "Zhang Yuanfeng", "Ma Junjie", "Chen Liming", "Wang Yan"], "journal": "Journal of cardiothoracic surgery", "entry_date": "2026/02/01 23:14", "pub_date": "2026-02-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41622196/", "pub_types": ["Journal Article", "Case Reports", "Systematic Review", "Review"], "affiliations": ["Department of Hematology, Yantai Yuhuangding Hospital Affiliated to Qingdao University, 20 Yuhuangding East Road, Shandong Province, 264000, Yantai, China."], "china_related": true, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.1, "journal_quartile": "2区"}, {"pmid": "41621163", "title": "Serum from patients with acetylcholine receptor antibody-positive myasthenia gravis triggers pathogenic changes in human myotube cells.", "abstract": "BACKGROUND: Some patients with myasthenia gravis (MG) are refractory to available treatments, highlighting the need to further understand the pathogenesis of the disease. This study aimed to determine whether components in the serum from patients with acetylcholine receptor (AChR) antibody-positive MG affect myotubes, to explore their possible role in disease pathogenesis beyond the inhibition of acetylcholine signal transmission.\nMETHODS: Serum was collected from 14 patients with AChR antibody-positive MG. The differentiated human myotubes were stimulated with 10% serum from healthy controls or patients with MG. After 24 h, ribonucleic acid extraction/sequencing was performed, and differentially expressed genes (DEGs) were extracted. Pathway analysis was completed using DEGs that were downregulated by stimulation with serum from patients with MG. Expression of genes important for muscle contraction was measured and myotube diameter was determined by immunostaining.\nRESULTS: Approximately 1200 DEGs were extracted by comparing gene expression in cultured human myotube cells stimulated with serum from healthy controls and patients with MG. Gene ontology terms linked with muscle function were suppressed in myotube cells stimulated with patient serum. Suppression of pathways associated with muscle atrophy/weakness, decreased expression of genes associated with muscle contraction, and smaller myotube diameter were confirmed in myotube cells stimulated with serum from patients versus healthy controls.\nCONCLUSION: Factors other than acetylcholine signal transmission inhibition may contribute to the pathogenesis of AChR antibody-positive MG. Further research is needed to clarify the pathways involved, potentially leading to more tailored pharmacotherapies.", "authors": ["Tanaka Keisuke", "Uzawa Akiyuki", "Yasuda Manato", "Onishi Yosuke", "Akamine Hiroyuki", "Handa Hideo", "Ogaya Etsuko", "Miyake Shota", "Baba Masayuki", "Abe Hiroto", "Nagaoka Koki", "Nakatake-Furuie Yuko", "Serizawa Kenichi", "Kuwabara Satoshi"], "journal": "Journal of neuroimmunology", "entry_date": "2026/02/01 18:02", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41621163/", "pub_types": ["Journal Article"], "affiliations": ["Product Research Department, Chugai Pharmaceutical Co., Ltd., 216 Totsukacho, Totsuka-ku, Yokohama-shi, Kanagawa 244-8602, Japan. Electronic address: tanaka.keisuke61@chugai-pharm.co.jp."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41620151", "title": "Response to Letter to the Editor: Letter by Ru and Zhang regarding article, \"Plasma miR-150-5p as a biomarker for immunosuppressive therapy response in acetylcholine receptor positive myasthenia gravis: a long-term prospective longitudinal study\".", "abstract": "", "authors": ["Garai Nemanja", "Madic Sanja", "Ivanovic Vukan", "Palibrk Aleksa", "Pesovic Jovan", "Brkusanin Milos", "Basta Ivana", "Peric Stojan", "Savic-Pavicevic Dusanka"], "journal": "Pharmacological research", "entry_date": "2026/01/31 19:16", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41620151/", "pub_types": ["Letter"], "affiliations": ["University of Belgrade, Faculty of Biology, Center for Human Molecular Genetics, Studentski trg 16, Belgrade 11158, Serbia."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 17.3, "journal_quartile": "1区"}, {"pmid": "41620150", "title": "Comment on \"Plasma miR-150-5p as a biomarker for immunosuppressive therapy response in acetylcholine receptor positive myasthenia gravis: A long-term prospective longitudinal study\".", "abstract": "", "authors": ["Ru Shanshan", "Zhang Yingzhe"], "journal": "Pharmacological research", "entry_date": "2026/01/31 19:16", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41620150/", "pub_types": ["Letter"], "affiliations": ["Department of Pharmacy, Shaoxing Central Hospital, Shaoxing, China. Electronic address: rshanshan2026@163.com."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 17.3, "journal_quartile": "1区"}, {"pmid": "41619069", "title": "Low-dose IL-2 Ameliorates Experimental Autoimmune Myasthenia Gravis in Rats by Restoring the CD4-positive Helper T-cell Balance Via the JAK/STAT5 Pathway.", "abstract": "", "authors": ["Peng Shanshan", "Kong Xiaotong", "Tian Wenqi", "Xu Fanfan", "Cai Hanlu", "Wu Fei", "Li Ying", "Xin Guanghao", "Niu Jingyan", "Ren Yingjie", "Li Lei", "Wang Jianjian", "Zhang Huixue", "Wang Lihua"], "journal": "Journal of neuroimmune pharmacology : the official journal of the Society on NeuroImmune Pharmacology", "entry_date": "2026/01/31 11:15", "pub_date": "2026-01-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41619069/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Harbin Medical University, Harbin, 150081, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null}, {"pmid": "41619021", "title": "Iatrogenic botulism: a risk for botulinum toxin's medical use?", "abstract": "Botulinum toxin (BT) is infamous for its extreme toxicity. If it enters the bloodstream, it can cause botulism presenting with a typical pattern of motor and autonomic dysfunction. An international expert panel organised by IAB-Interdisciplinary Working Group for Movement Disorders explored iatrogenic botulism after BT's medical use (IB), reached conclusions and formulated recommendations. When injected into its target tissue, BT binds to gangliosides on cholinergic nerve terminals before it is internalised permanently. Small amounts of BT, however, are circulating within the bloodstream. When BT type B is applied, IB-B occurs frequently, typically affecting the autonomic nervous system. When BT type A is applied, IB-A only occurs in special circumstances, even when high doses are used. We identified 236 patients with IB-A in the literature. All IB-A was mild or moderate and fully reversible. In 212 patients, it occurred with unapproved BT use. In 116 of them, unapproved BT preparations were used, in 81, unapproved indications were treated and in 15, underlying neuromuscular impairment including myasthenia gravis, Lambert-Eaton myasthenic syndrome, amyotrophic lateral sclerosis and spinal muscle atrophy were contraindications for BT use. In 24 patients, IB-A occurred in approved BT use. Their evaluation was frequently incomplete, so that causes for IB-A often remain unclear. They may include presence of differential diagnosis, subclinical neuromuscular impairment and interference with additional diseases. When IB is suspected, proper evaluation is necessary to verify it and to identify its causes. Off-label use is common in BT therapy. However, it should be performed with caution, especially in children and when high doses are applied. High BT doses should not be applied to low volumes of target tissues, in order not to exceed the BT binding capacity.", "authors": ["Dressler Dirk", "Frevert Jürgen", "Johnson Eric A", "Fink Klaus", "Pellett Sabine", "Pandey Sanjay", "Walter Uwe", "Tacik Pawel", "Kanovsky Petr", "Shahidi Gholam Ali", "Brüggemann Norbert", "Rosales Raymond L", "Relja Maja", "Jin Lingjing", "Rodriguez Jose Alberto Sagastequi", "Pan Lizhen", "Francisco Gerard E", "Shang Huifang", "Bai Xue", "Adib Saberi Fereshte"], "journal": "Journal of neural transmission (Vienna, Austria : 1996)", "entry_date": "2026/01/31 11:13", "pub_date": "2026-01-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41619021/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Movement Disorders Section, Department of Neurology, Hannover Medical School, Carl-Neuberg-Str. 1, 30625, Hannover, Germany. dressler.dirk@mh-hannover.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.4, "journal_quartile": "3区"}, {"pmid": "41617145", "title": "Fc receptor-like proteins and their role in B-cell responses and autoimmune diseases.", "abstract": "Fc receptor-like (FCRL) proteins constitute a receptor family that displays overlapping yet distinct features compared to classical Fc receptors. In a healthy immune system, FCRL proteins play a role in promoting and regulating the immune response through their immunoreceptor tyrosine-based motifs. FCRL proteins are expressed mainly by B cells, suggesting a primary role in B-cell responses. For several autoimmune diseases, studies have shown that particularly FCRL4, which binds to dimeric IgA, and FCRL5, which binds to IgG, may have a role in disease pathology and prognosis. These proteins and their transcripts are often enriched in blood and/or affected tissue of patients with a systemic or organ-specific autoimmune disease like rheumatoid arthritis, Sjögren's disease, systemic lupus erythematous, Graves' disease or myasthenia gravis. The expression of FCRL4 and FCRL5 appears to be disease- and context-specific, and influenced by the tissue microenvironment. Yet, the functions of FCRL proteins are still incompletely understood, and more mechanistic studies are necessary to unravel the contribution of FCRL4 and FCRL5 to pathogenic B-cell responses occurring in autoimmune diseases.", "authors": ["Haroun Christina", "Kroese Frans G M", "Verstappen Gwenny M"], "journal": "Immunology letters", "entry_date": "2026/01/30 19:16", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41617145/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Rheumatology and Clinical Immunology, University of Groningen, University Medical Center Groningen, Groningen, The Netherlands. Electronic address: c.haroun@umcg.nl."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41612506", "title": "Multi-omics profiling reveals intrathymic triggers and novel biomarkers in thymoma-associated myasthenia gravis.", "abstract": "BACKGROUND: The pathogenic mechanisms through which thymoma induces myasthenia gravis (MG) remain incompletely understood. While MG pathogenesis involves neuromuscular junction defects and peripheral immune dysregulation, the specific contribution of thymoma microenvironment is poorly defined.\nMETHODS: We conducted the first comparative multi-omics analysis of MG-associated thymomas (MGTH) versus non-MG thymomas, integrating single-cell transcriptomics, proteomics, and TCR/BCR repertoire sequencing. Key findings were validated across species using TCGA transcriptomic data, tissue microarrays, co-culture and antigen presentation assays, a Cd4CreSocs3fl/fl murine model and flow cytometry to delineate the underlying microenvironmental and molecular drivers.\nRESULTS: We observed broad expression of synaptic genes in MGTH, including elevated acetylcholine receptor (AChR)-encoding gene CHRNA1, in the absence of detectable intratumoral anti-AChR antibodies. Our analysis revealed a pathogenic JUND-SOCS3 axis governing T cell differentiation, wherein pan-T cell JUND overexpression transcriptionally repressed SOCS3, driving proinflammatory Th1/Th17 polarization in both Cd4CreSocs3fl/fl mice and MGTH patients. We further identified a novel neuro-synaptic thymic epithelial cell (nsTEC) subset characterized by markedly reduced HLA-I/II expression and aberrant synaptic gene expression. Functional co-culture assays confirmed that these nsTECs exhibited impaired antigen presentation and failed to efficiently activate T cells. Clonally expanded TTN+ memory B cells were identified in both MGTH stroma and peripheral blood, and their abundance correlated positively with anti-titin antibody titers. Analysis of cellular interactomes revealed rewired stromal-immune crosstalk in MGTH, wherein nsTECs existed as immunologically inert compartments, lacking detectable cytokine responsiveness or cellular interactions. TCR/BCR profiling demonstrated antigen-driven clonal expansion and repertoire restriction in MGTH. Furthermore, we identified the CDR sequences of antigen-specific clones.\nCONCLUSIONS: We demonstrate that thymoma-associated MG arises from three convergent mechanisms: disordered T-cell differentiation, defective thymic antigen presentation, and autoantigen-specific B-cell expansion. This model identifies previously unappreciated, synergistic therapeutic targets for intervention.\nGRAPHICAL ABSTRACT: [Image: see text]\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s40364-026-00900-8.", "authors": ["Ao Yongqiang", "Gao Jian", "Ying Zhen", "Wang Shuai", "Han Zheng", "Xia Mingyu", "Wen Jiazhe", "Zhu Junkan", "Wang Caiying", "Fu Minjie", "Jiang Jiahao", "Wang Haikun", "Dong Jihong", "Fan Hong", "Ding Jianyong"], "journal": "Biomarker research", "entry_date": "2026/01/30 00:08", "pub_date": "2026-01-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41612506/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Zhongshan Hospital, Fudan University, No 180 Fenglin Rd, Shanghai, 200032, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41610721", "title": "Efgartigimod for steroid-resistant autoimmune glial fibrillary acidic protein astrocytopathy: a case report and literature review.", "abstract": "BACKGROUND: Neonatal Fc receptor (FcRn) inhibitors rapidly and specifically clear serum immunoglobulin G (IgG) levels and, therefore, are increasingly used for the treatment of neurological autoimmune diseases, such as myasthenia gravis. However, whether FcRn inhibitors could alleviate steroid-unresponsive glial fibrillary acidic protein astrocytopathy (GFAP-A) has not been reported.\nCASE PRESENTATION: We report a case of a 68-year-old male patient who presented with gait instability and numbness in the left hand. Cranial magnetic resonance imaging (MRI) revealed multiple demyelinating lesions. The initial clinical diagnosis was demyelinating encephalopathy. After 1 month of intravenous methylprednisolone pulse therapy, followed by sequential oral prednisone, the patient's gait instability did not improve. Upon re-examination at our hospital, cranial MRI revealed no significant changes in the lesions. Testing for central nervous system demyelinating antibodies revealed serum anti-GFAP IgG antibody (titer 1:100), cerebrospinal fluid anti-GFAP IgG antibody (titer 1:1), and negative result for oligoclonal bands in blood and the cerebrospinal fluid. The final diagnosis was GFAP-A. Treatment with the FcRn inhibitor efgartigimod significantly improved clinical symptoms and brain lesions.\nCONCLUSIONS: This rare case indicates that efgartigimod is a promising treatment option for steroid-unresponsive GFAP-A.", "authors": ["Lei Peng", "Lu Yun", "Xia Jie", "Wang Tao", "Zhong Ling"], "journal": "Journal of neuroimmunology", "entry_date": "2026/01/29 18:25", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41610721/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Neurology, Yichang Central People's Hospital, The First College of Clinical Medical Science, China Three Gorges University, Yichang, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41607837", "title": "ENGAGE: Analyzing the value of virtual reality in a patient-centric immersive learning program in myasthenia gravis for healthcare professionals.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disease characterized by muscle weakness that can significantly impact patients' lives. Recent patient-led research highlighted a disconnect between healthcare professionals (HCPs) and patients, emphasizing the need for effective and empathetic patient-HCP dialogue and shared decision-making (SDM). The power of virtual reality (VR) to increase empathy and provide impactful learning experiences has been established. This outcome evaluation assessed the ability of VR to improve HCPs' knowledge, attitudes and empathy in MG, aiming to strengthen patient-HCP communication and facilitate SDM.\nMETHODS: The ENGAGE educational pilot program comprised a needs assessment, a VR-based intervention and an outcome evaluation. Content for the VR intervention was developed using a patient-centric approach integrating patient and HCP voices. The VR module simulated \"a day in the life of Julia,\" a virtual patient with MG, allowing HCPs to experience MG symptoms and their impact on a patient's life. The experience was implemented in hospital-based workshops. The outcome evaluation included surveys assessing Moore's Levels 2-4, the Theoretical Domains Framework (TDF), and SDM, and was supplemented by semi-structured interviews. Quantitative and qualitative data were analyzed using SPSS Statistics and thematic analysis, respectively.\nRESULTS: Eighty-seven HCPs completed the VR experience across 12 workshops. Sixty HCPs participated in the outcome evaluation survey, and 10 participated in interviews. HCPs reported high satisfaction with the immersive learning, citing its relevance and ease of use. Based on survey responses, HCPs' most important learnings were a \"better understanding of the impact of MG on patients' lives\" (n/N = 46/60) and \"developing empathy for how a patient with MG might feel\" (n/N = 37/60). HCPs expressed commitment to changing their practice. Quantitative analysis revealed significant improvements in most TDF domains and SDM post-intervention, with the TDF domain \"beliefs about capabilities\" emerging as the strongest predictor of SDM.\nCONCLUSION: Our study found that the immersive VR intervention effectively increased HCP empathy, knowledge and attitudes in MG care. The program's patient-centric design ensured content relevance. These findings suggest that VR-based learning is a valuable tool for medical education and the improvement of SDM, particularly in rare diseases like MG.", "authors": ["Weisshardt Ina", "Reyes Acosta Cornelia", "Chauhan Trishna", "Haralampiev Kaloyan", "Mušura Gabor Andrijana", "Rodriguez Alexis", "Foss Allison", "Pinto Ashwin", "Hewamadduma Channa", "Vissing John", "Silvestri Nicholas J", "Lehnerer Sophie", "De Backer Marc", "Monin Natasha", "Barry Sophie", "Vlaev Ivo"], "journal": "Frontiers in neurology", "entry_date": "2026/01/29 04:49", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41607837/", "pub_types": ["Journal Article"], "affiliations": ["LLH Concepts GbR, Haimhausen, Germany."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41604997", "title": "Letter to the editor: Early real-life experience on Zilucoplan for generalized myasthenia gravis: ZILU25 multicenter observational study.", "abstract": "", "authors": ["Yang Yao", "Hu Ye"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/28 18:09", "pub_date": "2026-03-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41604997/", "pub_types": ["Letter"], "affiliations": ["Department of Pharmacy, Yancheng Third People's Hospital, Yancheng, Jiangsu, China; Department of Pharmacy, The Yancheng School of Clinical Medicine of Nanjing Medical University, Yancheng, Jiangsu, China."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41603484", "title": "Azathioprine Toxicity in Patients With Myasthenia Gravis: A Single Center Experience.", "abstract": "INTRODUCTION/AIMS: Azathioprine (AZA) is a first-line immunosuppressive agent for myasthenia gravis (MG), yet most toxicity data for AZA are from gastrointestinal literature. The aim of the current study is to add a large MG patient cohort with a comprehensive evaluation of the adverse event profile of AZA and associations between patient demographics and drug reactions.\nMETHODS: Patients were identified from the Duke Electronic Medical Record using EPIC's SlicerDicer tool.\nINCLUSION CRITERIA: MG diagnosis confirmed by antibody/electrodiagnostic testing, evaluation by a Duke neuromuscular physician, and AZA use between January 1, 2014 and January 7, 2023. Drug reaction was defined as an abnormal lab result or symptomatic side effect after AZA initiation.\nRESULTS: Among 145 patients, 96 (66%) developed a drug reaction; 63 (43.5%) required AZA dose reduction or discontinuation, and 23 (16%) had symptomatic side effects. Most reactions improved with dose reduction or observation. Leukopenia, macrocytosis, and hepatotoxicity were the most frequent. For every additional comorbidity, the odds of drug reaction increased by 30% (OR 1.3; 95% CI 1.12-1.51; p < 0.001). Flu-like reactions occurred in 10% of patients. Cancer incidence (4.1%) was rare and there were no cases of Pneumocystis jirovecii pneumonia despite rare use of trimethoprim-sulfamethoxazole prophylaxis.\nDISCUSSION: AZA drug reactions were common but infrequently severe or symptomatic. Higher comorbidity burden predicted drug reactions. Most laboratory abnormalities resolved without AZA discontinuation, supporting individualized monitoring and dose adjustment rather than automatic cessation. Lower doses should be considered for balancing efficacy with dose-dependent drug reactions.", "authors": ["Gaini Rahul", "Truong Tracy", "Morena Jonathan"], "journal": "Muscle & nerve", "entry_date": "2026/01/28 08:26", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41603484/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Duke University, Durham, North Carolina, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41602815", "title": "Exploring the impact of age of onset on stereoacuity in patients with myasthenia gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder that can result in fluctuating muscle strength and various ocular manifestations. Common ocular signs and symptoms in MG patients include ptosis, limited eye movement, and diplopia.\nPURPOSE: This study aimed to investigate the association between the clinical characteristics of MG, specifically the age of onset, and stereoacuity in MG patients.\nDESIGN: This was a cross-sectional study that enrolled 150 MG patients.\nMETHODS: Stereoacuity was assessed using the Butterfly Stereo Acuity Test. Main analysis was conducted using multinomial logistic regression to explore the relative risk associated with different levels of stereoacuity.\nRESULTS: This study included 150 MG patients: 58 (38.7%) with normal stereoacuity, 80 (53.3%) with weak stereoacuity, and 12 (8%) unable to identify any stereo chart. Patients with MG onset before age 7 (n = 15) had a significantly higher risk of being unable to identify any stereo chart [relative risk ratio (RRR) = 14.73; p = 0.03]. Among ocular manifestations, ptosis (RRR = 2.33; p < 0.05) and diplopia (RRR = 2.26; p < 0.05) were associated with weak stereoacuity, whereas extraocular movement (EOM) disorder was significantly associated with being unable to identify any stereo chart (RRR = 10.57; p < 0.01).\nCONCLUSION: Findings suggest that an early onset of MG may contribute to impaired stereoacuity. For patients diagnosed with MG before the age of 7, it is advisable to ensure optimal management of MG itself. Future studies should explore the potential long-term implications of early-onset MG on binocular vision, ophthalmoplegia, and the impact of ocular signs and symptoms on patients' quality of life.", "authors": ["Cheng Chen-Yun", "Chiu Hou-Chang", "Hung Chi-Feng", "Yeh Jiann-Horng"], "journal": "Frontiers in ophthalmology", "entry_date": "2026/01/28 05:04", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41602815/", "pub_types": ["Journal Article"], "affiliations": ["Institute of Public Health, School of Medicine, National Yang Ming Chiao Tung University (NYCU), Taipei, Taiwan."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "41602394", "title": "The rare report of unicentric Castleman disease with concurrent myasthenia gravis and paraneoplastic pemphigus: a case report with a focused review of the literature.", "abstract": "RATIONALE: Castleman disease (CD) is a rare lymphoproliferative disorder that can be associated with autoimmune manifestations. While paraneoplastic pemphigus (PNP) and myasthenia gravis (MG) have each been reported with CD, their simultaneous occurrence is extremely uncommon. Here, we describe a case of mixed-type unicentric Castleman disease (UCD) complicated by both MG and PNP.\nPATIENT CONCERNS: A 49-year-old man presented with fluctuating right eyelid ptosis, consistent with ocular MG. Several months later, he developed progressive oral erosions.\nDIAGNOSES: The patient was diagnosed with ocular myasthenia gravis (MG) based on fluctuating ptosis and a positive neostigmine test. Chest imaging revealed an anterior mediastinal mass initially suspected to be thymoma. Biopsy and immunopathology of the lips and oral mucosa confirmed PNP, with direct immunofluorescence showing intercellular IgG deposition and serological positivity for envoplakin and periplakin antibodies. After stabilization of systemic symptoms, the mediastinal mass was surgically removed, and histopathological examination confirmed mixed-type UCD. To date, only four previous cases of this triad have been reported in the literature, and the present case represents a mixed-type UCD subtype.\nINTERVENTIONS: The patient was treated with pyridostigmine for MG, systemic corticosteroids and supportive therapy for PNP, followed by complete surgical excision of the mediastinal mass once symptoms were controlled.\nOUTCOMES: Postoperatively, corticosteroid therapy was continued, resulting in near-complete resolution of oral lesions. During a 20-month follow-up period, the patient remained free of MG recurrence and showed no new PNP lesions.\nLESSONS: This case highlights a rare and diagnostically challenging overlap of CD, MG, and PNP. Accurate recognition required integration of histopathology, immunofluorescence, and serological testing, achieved through multidisciplinary collaboration across thoracic surgery, neurology, dermatology, and pathology. Clinicians should remain vigilant for such complex presentations, as early diagnosis and coordinated management are essential to improving outcomes in rare autoimmune-associated CD.", "authors": ["Cheng Zeyu", "Liu Wenliang", "Hu Yan"], "journal": "Frontiers in oncology", "entry_date": "2026/01/28 05:00", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41602394/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Thoracic Surgery, The Second Xiangya Hospital, Central South University, Changsha, Hunan, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "41598608", "title": "Fracture Occurrence Within FRAX-Defined High-Risk Myasthenia Gravis: An Exploratory Stratification by Age and Activities of Daily Living.", "abstract": "Background/Objectives: Patients with myasthenia gravis (MG) are at increased risk of osteoporotic fractures due to long-term oral corticosteroid use and disease-related muscle weakness. FRAX® estimates 10-year fracture probability but does not incorporate falls or MG-specific functional impairment. To explore heterogeneity of fracture occurrence within MG patients classified as high risk by FRAX major osteoporotic fracture (MOF) probability. Methods: In a single-center retrospective cohort of 68 MG patients assessed in 2012, FRAX MOF with femoral neck BMD was calculable in 54 patients; the 29 patients with FRAX MOF ≥ 9.0% (the median of these 54 patients) comprised the high-FRAX cohort. Patients were stratified by the cohort medians of age (67 years) and MG-ADL (2 points) into four strata (HH, HL, LH, LL). This median-based stratification was exploratory and not intended as a clinically meaningful threshold. The primary outcome was time to first MOF (up to 10 years). We compared fracture occurrence using both proportions and Kaplan-Meier analyses (log-rank test) and performed exploratory univariable Cox models for selected predictors. No multivariable confounder adjustment was performed. Results: Eight of twenty-nine patients (27.6%) experienced an MOF. The proportions with MOF were HH 25.0%, HL 40.0%, LH 57.1%, and LL 0.0% (global p = 0.068). Kaplan-Meier curves differed across strata (log-rank p = 0.03), with separation most evident between LH and LL. For univariable Cox analyses, age was associated with shorter time to MOF (hazard ratio [HR] 1.13 per year, p = 0.041), and baseline difficulty rising from a chair (MG-ADL item) was associated with higher hazard rates (HR 3.45, p = 0.048). Conclusions: In this small, selected high-FRAX MG cohort, fracture events appeared to cluster in patients with impaired ADL and fall-related MG-ADL abnormalities, whereas FRAX values remained strongly age-driven. These findings are exploratory and hypothesis-generating and should not be interpreted as evidence of FRAX miscalibration; confirmation in larger, prospectively followed cohorts is needed.", "authors": ["Uchi Takafumi", "Konno Shingo"], "journal": "Journal of clinical medicine", "entry_date": "2026/01/28 01:18", "pub_date": "2026-01-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41598608/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Toho University Ohashi Medical Center, 2-22-36 Ohashi Meguro-Ku, Tokyo 153-8515, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41598576", "title": "A Shift from Standard Median Sternotomy to Robotic-Assisted Thoracic Surgery for Resection of Anterior Mediastinal Tumors.", "abstract": "Objectives: Robotic-Assisted Thoracic Surgery (RATS) has emerged as a viable alternative to traditional median sternotomy for patients with anterior mediastinal tumors suspected of having thymoma or those with Myasthenia Gravis (MG). While median sternotomy remains a widely accepted standard approach, RATS has gained popularity due to its potential benefits. Methods: We retrospectively reviewed our 5 years' experience of performing 111 surgeries for patients with anterior mediastinal tumors and patients with MG suspected of having thymoma. We performed multivariate regression models to assess the association between main demographic and clinical variables and two primary outcomes: overall complications and hospital stay. Results: Out of 111 patients, 54 were men (48.6%) and 57 were women (51.4%). The majority of surgeries (n = 93) were performed by RATS (83.8%), while the remainder were performed by either median sternotomy (n = 15, 13.5%) or by other approaches (n = 3, 2.7%). Sixty-five patients were diagnosed with thymoma (58.6%), with 96.9% R0 resection. Sixty-five patients underwent left-sided surgery (58.6%), and thirty-one underwent right-sided surgery (27.9%). The conversion rate was 2.5%. The rate of postoperative complications was 8.1 without perioperative mortality. The median hospital stay was 4.62 days, but it was significantly shorter in the RATS compared to the median sternotomy group (mean 3.64 vs. 10.67 days, p = 0.040). Conclusions: Our results suggest that RATS for patients with anterior mediastinal tumors suspected of having thymoma or for those with MG is safe and technically feasible and may be the preferred surgical approach for selected patients, whereas traditional median sternotomy remains the preferred choice for more locally advanced tumors.", "authors": ["Peer Michael", "Azzam Sharbel", "Nesher Nachum", "Kolodii Marina", "Abramov Yaacov", "Verenkin Vladimir", "Shaylor Ruth", "Karni Arnon", "Gadoth Avi", "Pompeo Eugenio", "Matot Idit", "Merimsky Ofer"], "journal": "Journal of clinical medicine", "entry_date": "2026/01/28 01:18", "pub_date": "2026-01-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41598576/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Tel Aviv Medical Center, Faculty of Medicine, Tel Aviv University, Weitzman Street 6, Tel Aviv 6423906, Israel."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41593440", "title": "Gut Microbiota as Neuroimmune Modulators in Myasthenia Gravis: Mechanistic Insights from the Gut-Brain Axis to Therapeutic Innovations.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by an immune-mediated attack on neuromuscular junction acetylcholine receptors (AChRs), and its pathogenesis is closely linked to immune dysregulation. Emerging evidence has highlighted the pivotal role of the gut microbiota in the pathophysiology of MG through immunomodulation, microbial metabolite signaling, and gut-brain axis interactions. This review combines 16S rRNA sequencing, metagenomic, and metabolomic data to reveal distinct gut microbial signatures in patients with MG. These signatures include reduced α-diversity, depletion of beneficial taxa like Bacteroides and Bifidobacterium, enrichment of pathobionts such as Escherichia and Enterococcus, and diminished levels of the short-chain fatty acids (SCFA), which were inversely correlated with disease severity. Experimental models have demonstrated that fecal microbiota transplantation (FMT) and probiotic supplementation with strains like Bifidobacterium ameliorate symptoms by restoring Th17/Treg equilibrium, suppressing the expression of pro-inflammatory cytokines including IL-6 and TNF-α, and enhancing intestinal barrier integrity. Mechanistically, gut dysbiosis exacerbates autoimmunity via NF-αB pathway activation, disrupts tryptophan metabolism and impairs gut-brain signaling. While existing studies have established microbiota-MG associations, further causal validation, personalized therapeutic strategies, and multi-omics integration remain critical priorities. Microbiota-targeted interventions, including precision FMT and metabolite delivery, hold translational potential, but their validation via large-scale randomized controlled trials and interdisciplinary approaches like AI-driven microbiota profiling is essential if they are to advance precision medicine for MG management.", "authors": ["Lv Jie", "Liu Ruichen", "Sun Zhan", "Zhang Jing", "Zhang Yingna", "Zhao Xue", "Liu Jing", "Zhou Xinyue", "Zhang Mengdi", "Liu Qian", "Gao Feng"], "journal": "The American journal of Chinese medicine", "entry_date": "2026/01/27 23:43", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41593440/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41591648", "title": "Assessing the Value Contribution of Vyvgart® (Efgartigimod Alfa) in the Treatment of Generalized Myasthenia Gravis with Acetylcholine Receptor Antibody in Spain Through Multi-criteria Decision Analysis.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a rare, chronic autoimmune neuromuscular disorder that currently lacks a curative treatment. Efgartigimod alfa is the first human IgG1 Fc fragment approved in Spain for the management of this condition. This study aims to evaluate the value of efgartigimod for treating gMG with anti-acetylcholine receptor (gMG AChR+) antibodies compared with ravulizumab, zilucoplan, and rozanolixizumab using a multi-criteria decision analysis (MCDA) framework.\nMETHODS: A multidisciplinary group of eight experts evaluated the value of efgartigimod against ravulizumab, zilucoplan, and rozanolixizumab. The MCDA framework adapted for evaluating orphan drugs (ODs) in Spain, comprising nine quantitative and three qualitative criteria, was used.\nRESULTS: gMG AChR+ has been recognised as a severe and debilitating condition with considerable unmet needs. Efgartigimod achieved favourable average scores compared with ravulizumab, zilucoplan, and rozanolixizumab across all comparative parameters, including efficacy, safety, and patient-reported outcomes (PROs), potentially resulting in cost savings. Efgartigimod was deemed to have a significant therapeutic impact, with supporting data considered high quality. Efgartigimod alfa showed a higher overall value contribution than the three comparators, with the difference being most notable for ravulizumab. Furthermore, it was concluded that efgartigimod aligns well with the specific priorities, objectives, and capacities of the National Healthcare System (NHS).\nCONCLUSION: Efgartigimod has been recognised as a valuable option for gMG AChR+ treatment in Spain by a multidisciplinary panel of experts through the application of MCDA, receiving higher scores compared with ravulizumab, zilucoplan, and rozanolixizumab.", "authors": ["Cortés-Vicente Elena", "Guerrero Antonio", "Díaz Carmina", "Martínez Eva", "Toja-Camba Francisco J", "Abad María R", "Serra José M", "Trillo Jose L", "Martín Machín Celia", "Gil Alicia"], "journal": "Advances in therapy", "entry_date": "2026/01/27 11:22", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41591648/", "pub_types": ["Journal Article"], "affiliations": ["Hospital Santa Creu i Sant Pau, Barcelona, Spain."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41589418", "title": "1-Year Clinical Outcome Post-Myasthenic Crisis: A Multicenter Prospective Study in China.", "abstract": "BACKGROUND: Myasthenic crisis (MC) affects 10%-20% of myasthenia gravis patients and is life-threatening with significant economic burden, yet its long-term outcomes remain poorly understood. This prospective multicentre study aimed to evaluate 1-year clinical outcomes after MC.\nMETHODS: This study enrolled patients with MC between December 2018 and October 2024 and prospectively followed at 1, 2, 3, 6, and 12 months post-MC. Outcome measures included Myasthenia Gravis Foundation of America (MGFA) postintervention status (PIS) classification at 1 year after MC, all-cause mortality, and complications.\nRESULTS: The cohort comprised 277 patients with 282 MC episodes with a follow-up duration of 29.16 ± 15.93 months. The in-hospital mortality was 5.05% (14/277), while the all-cause mortality was 15.16% (42/277). The leading causes of death were septic shock (35.7%) and multiple organ failure (21.4%). Among 247 patients with complete 1-year follow-up, 79.76% (197/247) achieved favorable outcomes. MG-ADL scores reduced from 21.3 ± 2.1 at baseline to 5.5 ± 1.5 at 6 months, and 2.8 ± 1.1 at 1 year post-MC (p < 0.01). Multivariable analysis identified older age at crisis (OR 1.03, p = 0.003), thymoma comorbidity (OR 1.84, p = 0.041), higher comorbidity burden (Charlson Comorbidity Index ≥ 3, OR 2.68, p = 0.003), and prolonged ICU stay (OR 1.03, p = 0.002) as independent predictors for minimal symptom expression non-responders. The most frequent chronic complications included infections (15.2%; predominantly fungal pathogens), gastrointestinal disorders (8.3%), and osteoporosis/fractures (5.1%).\nCONCLUSIONS: This is the first prospective cohort study to report clinical outcomes in MG patients at post-MC stage, highlighting the importance of disease monitoring and early intervention to improve patient-centred care.", "authors": ["Huan Xiao", "Chen Ran", "Jin Lei", "Wang Yuan", "Xu Yafang", "Yang Lei", "Xi Caihua", "Zheng Jianming", "Luo Lijun", "Yang Song", "Shi Jianquan", "Liu Yanping", "Ruan Zhe", "Wu Wanlong", "Li Wei", "Yue Yaoxian", "Li Yarong", "Jia Wenji", "Zhong Huahua", "Yan Chong", "Song Jie", "Xi Jianying", "Tan Song", "Jiang Qilong", "Zou Zhangyu", "Zhao Chongbo", "Luo Sushan"], "journal": "European journal of neurology", "entry_date": "2026/01/27 05:13", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41589418/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Huashan Rare Disease Center and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Center for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41588655", "title": "Aberrant expression of triggering receptor expressed on myeloid cell-1 is involved in the immunopathological mechanism of myasthenia gravis.", "abstract": "Triggering receptor expressed on myeloid cells-1 (TREM-1) and TREM-2, cell surface receptors involved in innate and adaptive immunity, exist in soluble (sTREM-1 and sTREM-2) and membrane-bound forms, with the soluble form serve as biomarkers in many immune diseases. However, the role of TREM-1 and TREM-2 in myasthenia gravis (MG) remains unclear. This study aims to investigate the expression of TREM-1 and TREM-2 in MG, as well as their potential role in the immunopathological mechanism of MG. We enrolled a total of 85 MG patients and 43 healthy controls (HC). Enzyme-linked immunosorbent assay and flow cytometry were used to quantify the expression of TREM-1 and TREM-2 in MG patients and HC. The levels of TREM-1 and TREM-2 mRNA of peripheral blood mononuclear cells were measured by reverse transcription quantitative real-time polymerase chain reaction (RT‒qPCR) in MG and HC. In vitro experiments were performed to explore the functional effects of intervening TREM-1 on CD4+T cells. We found that serum sTREM-1 levels were significantly elevated in MG patients Compared to HC, whereas sTREM-2 showed no difference. Additionally, sTREM-1 levels in MG patients positively correlated with disease severity and memory B-cell proportions. TREM-1 expression was reduced and most significantly on CD4+T and CD8+T cells in MG patients. Inhibition of TREM-1 inhibited Treg cell differentiation but had no significant effect on Th1, Th2, and Th17, indicating its pathogenic role in MG.", "authors": ["Wang Zhouyi", "Luo Tiancheng", "Peng Deyou", "Guo Xinyan", "Ma Tianyu", "Yang Mingjin", "Du Xue", "Wang Yingying", "Li Shengli", "Zhang Zhouao", "Huang Xiaoyu", "Zhang Yong"], "journal": "Autoimmunity", "entry_date": "2026/01/27 00:43", "pub_date": "2026-12-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41588655/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, People's Republic of China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41586099", "title": "Add-on efgartigimod in myasthenic crisis: a promising treatment option.", "abstract": "BACKGROUND: In myasthenia crisis (MC), plasma exchange (PE) and intravenous immunoglobulin (IVIG) are confirmed effective treatment options, but PE may not be available in time, and the response rate to IVIG is not always satisfactory. This study aimed to investigate whether addition of efgartigimod confers benefits in patients with MC.\nMETHODS: This real-world retrospective pilot study examined MC patients admitted to the First Affiliated Hospital of Sun Yat-sen University between August 2023 and May 2024, who were categorized into two groups: the traditional immunotherapy group (n = 14) and the add-on efgartigimod group (n = 9). In the efgartigimod group, patients received 20 mg/kg efgartigimod (n = 9), administered on the first and fifth days.\nRESULTS: Totally 23 patients were recruited in the study. Total hospital stays, MV duration, and non-invasive ventilation time were shorter in the efgartigimod group compared with the traditional immunotherapy group; however, these differences were not statistically significant (p > 0.05). We subsequently applied a generalized estimating equation (GEE) to the patients over an 8-week period and observed a reduction in Myasthenia Gravis Activities of Daily Living (MG-ADL) scores in both groups; however, no significant differences were found within the groups (p > 0.05). Survival analysis was also conducted, revealing that the addition of efgrtigimod allowed patients to reach the MSE state more quickly, which is statistically significant (p = 0.0499). Additionally, three patients with MC who only received high-dose efgartigimod treatment all achieved favorable treatment outcomes.\nCONCLUSION: This suggests that efgartigimod may serve as an alternative option for MC patients or as a rescue treatment option for refractory individuals.", "authors": ["Shi Fangyi", "Wang Jing", "Chen Jiaxin", "Lai Rong", "Feng Li", "Zhou Hongyan", "Sun Xunsha", "Shen Cunzhou", "Feng Jiezhen", "Huang Xin", "Feng Huiyu", "Wang Haiyan"], "journal": "Frontiers in neurology", "entry_date": "2026/01/26 07:08", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41586099/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital, Sun Yat-sen University, Guangzhou, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41583497", "title": "Efgartigimod combined with rituximab helps improve the symptoms and reduce the use of corticosteroids in patients with MuSK antibody-positive MG: a single case report.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder primarily affecting the neuromuscular junction. Muscle-specific receptor tyrosine kinase antibody (MuSK-Ab)-mediated MG often presents with bulbar weakness and is prone to crisis. Currently, conventional treatments show limited efficacy in MuSK-Ab-mediated MG, while rituximab therapy demonstrates favorable outcomes.\nCASE PRESENTATION: We report a case of a patient who initially achieved symptom control with efgartigimod during an acute exacerbation but experienced symptom recurrence after subsequent rituximab treatment. Owing to poor tolerance to pyridostigmine and corticosteroids, and considering the established efficacy of efgartigimod in MuSK-Ab-positive MG, we opted for continued efgartigimod infusions. This approach quickly improved symptoms, achieved minimal symptom expression (MSE), and allowed faster tapering of corticosteroids and pyridostigmine.\nCONCLUSION: While multiple studies have demonstrated the efficacy and safety of efgartigimod, large-scale studies remain necessary to further evaluate the feasibility of combination therapy with rituximab in MuSK-Ab-positive MG.", "authors": ["Zheng Xiujun", "Wang Jing", "Cai Tongtong", "Zhou Houshi"], "journal": "Frontiers in immunology", "entry_date": "2026/01/26 06:48", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41583497/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Shantou Central Hospital, Shantou, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41582708", "title": "Exploring Pembrolizumab-Induced IM3OS in a Patient With Bladder Cancer.", "abstract": "Pembrolizumab, an immune checkpoint inhibitor (ICI), has transformed cancer treatment across various malignancies, including metastatic urothelial cancer. As the use of pembrolizumab becomes increasingly widespread, understanding its potential adverse effects is essential. Here, we present the case of a 79-year-old male with urothelial cancer of the bladder, who experienced local recurrence after surgery and conventional therapies. He subsequently began pembrolizumab treatment. Following the first infusion, the patient developed a series of complications over a span of 26 days, including acute hepatitis, chest pain, and progressive bilateral ptosis. A third-degree atrioventricular block was also detected, necessitating pacemaker implantation. Further neurophysiological evaluations confirmed a diagnosis of myasthenia gravis and myositis. The patient was treated with intravenous methylprednisolone, immunoglobulin therapy, and pyridostigmine bromide. Despite these interventions, his condition deteriorated, requiring intubation and mechanical ventilation 28 days post-treatment. This case highlights that pembrolizumab can trigger rare but severe neurological and cardiovascular adverse events. Prompt and thorough investigations to identify syndromes such as myocarditis-myositis-myasthenia gravis overlap syndrome (IM3OS) are vital for timely diagnosis and intervention.", "authors": ["Chan Ching-Cheng", "Lee Ming-Jen", "Su Jian", "Su Jen-Jen"], "journal": "Pharmacology research & perspectives", "entry_date": "2026/01/26 03:43", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41582708/", "pub_types": ["Journal Article"], "affiliations": ["Department of Internal Medicine, National Taiwan University Hospital, Taipei City, Taiwan."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "41582064", "title": "Heterogeneous response to efgartigimod in real-world experience with myasthenia gravis: Predictors and treatment strategies.", "abstract": "Efgartigimod is an established therapy for acetylcholine receptor antibody-positive generalized myasthenia gravis, yet real-world data on long-term overall responsiveness, response patterns, steroid-sparing effects, bridging therapy use, and predictors of benefit remain limited. In this multicenter retrospective study, we evaluated 46 patients treated across seven tertiary centers between April 2022 and March 2025, collecting demographic, clinical, therapeutic, and outcome data. Patients received 193 treatment cycles (mean 4.3 per patient) with a mean inter-cycle interval of 9.8 weeks. Following the first cycle, 86.9 % achieved a ≥2-point improvement in the Myasthenia Gravis Activities of Daily Living scale and 43.5 % reached minimal symptom expression (MSE); overall, 52.2 % achieved MSE at least once during follow-up. Nonetheless, 35.9 % discontinued efgartigimod due to insufficient efficacy, underscoring heterogeneous and often non-durable responses. Among 29 patients on prednisone, 58.6 % achieved a significant dose reduction (30.9-16.8 mg/day, p = 0.001), with shorter disease duration predicting successful tapering. Bridging therapy was successful in 5 patients, particularly those receiving azathioprine or mycophenolate (p = 0.040), supporting its utility during transitions to slower-acting immunosuppressants. Adverse events occurred in 21.7 % of patients, were generally mild, and led to discontinuation in only one case. Overall, efgartigimod was effective and well tolerated, but treatment responses varied, and cycle-based regimens frequently failed to sustain benefit. The observed steroid-sparing effect and predictors of response highlight the need for personalized treatment strategies and prospective studies to refine long-term use and optimize patient selection.", "authors": ["Fuchs Lior", "Vigiser Ifat", "Kolb Hadar", "Regev Keren", "Drory Vivian E", "Dori Amir", "Magalashvili David", "Caller Tal", "Kenan Gilad", "Mechnik Steen Yana", "Hellmann Mark", "Wilf-Yarkoni Adi", "Friedman Korn Tal", "Vaknin-Dembinsky Adi", "Bsoul Alaa", "Shelly Shahar", "Karni Arnon"], "journal": "Neurotherapeutics : the journal of the American Society for Experimental NeuroTherapeutics", "entry_date": "2026/01/25 21:53", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41582064/", "pub_types": ["Journal Article"], "affiliations": ["Gray Faculty of Medical & Health Sciences, Tel Aviv University, Tel Aviv, Israel."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.6, "journal_quartile": "2区"}, {"pmid": "41581511", "title": "Patient journey and treatment pattern in myasthenia gravis: real-world data from the Brazilian public health system.", "abstract": "", "authors": ["Scola Rosana Herminia"], "journal": "Arquivos de neuro-psiquiatria", "entry_date": "2026/01/25 18:42", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41581511/", "pub_types": ["Journal Article"], "affiliations": ["Universidade Federal do Paraná, Departamento de Medicina Interna, Disciplina de Neurologia, Curitiba PR, Brazil."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41580680", "title": "Social support in Chinese patients with myasthenia gravis and analysis of related factors: a cross-sectional study.", "abstract": "BACKGROUND: Myasthenia gravis (MG), a rare autoimmune neuromuscular disorder, imposes long-term physical and psychological burdens on patients due to its chronicity, recurrence, and limited societal awareness. Social support plays a critical role in mitigating disease-related stressors, yet its status and determinants remain understudied in Chinese MG populations.\nOBJECTIVE: We aimed to explore the current status of social support in patients with myasthenia gravis and analyze the related factors.\nMETHODS: A total of 153 patients with myasthenia gravis were investigated using a general information questionnaire, social support scale, and illness perception scale. One-way analysis of variance and multiple linear regression were used for statistical analysis.\nRESULTS: The total score on the social support scale was 37.69 ± 5.10 points, the objective support score was 7.51 ± 1.92 points, the subjective support score was 24.80 ± 2.97 points, and the support utilization score was 5.38 ± 1.88 point. The results of multiple linear regression showed that marital status, situation of children, number of children, duration of illness, disease severity (MGFA class), personal control, treatment control, and emotional representations in illness perception were the influencing factors of social support.\nCONCLUSION: Our study showed that disease severity is an influencing factor of social support. The level of social support among patients with myasthenia gravis is moderate, indicating a need for improvement in the current social support system. It is suggested that attention should be paid to the level of social support for patients with myasthenia gravis and related security systems should be established for social support to have a role in promoting health.", "authors": ["Xu Le", "Cui Yafeng", "Wang Xia", "Bi Qingquan"], "journal": "BMC neurology", "entry_date": "2026/01/24 23:25", "pub_date": "2026-01-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41580680/", "pub_types": ["Journal Article"], "affiliations": ["School of Nursing, Anhui Medical University, Hefei, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41579003", "title": "Sleep disturbances in patients with myasthenia gravis: A cross-sectional study.", "abstract": "OBJECTIVE: To explore sleep dysfunction in clinically stable patients with myasthenia gravis (MG) and to identify sleep disturbances and uncover their associated risk factors.\nMETHODS: A cross-sectional study was conducted, involving the recruitment of 306 patients with MG from three MG centers. Participants completed an online self-report questionnaire covering demographic variables, clinical characteristics, and assessments using the Pittsburgh Sleep Quality Index (PSQI) scale, STOP-Bang scale, Myasthenia Gravis Quality of Life 15 (MG-QOL 15) scale, Patient Health Questionnaire (PHQ-9), and Self-Rating Anxiety Scale (SAS), to evaluate sleep quality among patients with MG.\nRESULTS: Approximately 68% of patients with MG presented sleep disturbances (PSQI ≥6). Univariate analysis revealed that age, lower education level (≤12 years), being single, late disease onset (>55 years old), generalized subtype, myasthenia crisis, positivity for AChR antibodies, thymoma, thymectomy, and type B thymoma were risk factors for sleep dysfunction in patients with MG. Within the sleep disturbances group, 51% of patients scored ≥3 on the STOP-Bang scale, indicating a higher risk of obstructive sleep apnea. PSQI global scores showed significant linear correlations with MG-QOL 15, STOP-Bang, PHQ-9, and SAS scores (P<.001). Multivariate analysis revealed that sex, marital status, STOP-Bang score, SAS score, and MG-QOL 15 score were correlated with the PSQI score.\nCONCLUSION: Sleep disturbances are prevalent among patients with MG, even in clinically stable cases. Psychological factors such as anxiety and health-related quality of life warrant increased attention in the management of these patients.", "authors": ["Yan J", "Choi K", "Fu P", "Lin J", "Gui M", "Li Y", "Luo L", "Hu Z", "Bu B", "Li Z"], "journal": "Neurologia", "entry_date": "2026/01/24 08:17", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41579003/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, Hubei, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41578337", "title": "Management of large anterior mediastinal mass by video-assisted thoracoscopic surgery.", "abstract": "BACKGROUND: There are controversies regarding managing anterior mediastinal mass greater than 5 cm by video-assisted thoracoscopic surgery (VATS). This study aims to present a single-center experience in using VATS to resect large anterior mediastinal masses using either unilateral or bilateral approach.\nMETHODS: This is a retrospective case series, including consecutive patients referred for surgical management of anterior mediastinal mass, provided the mass was equal to or larger than five centimeters. Only phase I (unilateral VATS) was performed for those with a single approach, while phase one and phase II (bilateral VATS) were performed for those with dual approach.\nRESULTS: The study included eight cases; 4 (50%) were male, and 4 (50%) were female. All of the cases had features of myasthenia gravis. The average diameter of the mass on the computed tomography scan was 7 cm, ranging from 5 to 12 cm. Dual VATS was utilized in three (37.5%) cases, which showed both left and right extension. The average blood loss was 180 ml, ranging from 130 to 250 ml. All of the cases were thymoma. Complete resection was achieved in all cases with R0. Neither mortality nor recurrence was reported in the follow-up period (14 months average ranging from 6 to 36 months).\nCONCLUSIONS: VATS is a safe and effective approach for large anterior mediastinal masses, with satisfactory operative outcomes, minimal morbidity, and promising oncological results. Dual VATS may be particularly useful for lesions with significant bilateral extension.", "authors": ["Kakamad Fahmi Hussein", "Saeed Kaiwan Talib", "Ibrahim Shyar Mohammed", "Ghafur Shad Awat"], "journal": "Journal of cardiothoracic surgery", "entry_date": "2026/01/24 00:04", "pub_date": "2026-01-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41578337/", "pub_types": ["Journal Article"], "affiliations": ["Scientific Affairs Department, Smart Health Tower, Madam Mitterrand Street, Sulaymaniyah, 46001, Iraq. fahmi.hussein@univsul.edu.iq."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "2区"}, {"pmid": "41576890", "title": "Authors' reply to comment letter on ZILU25 study.", "abstract": "", "authors": ["Di Stefano Vincenzo", "Vinciguerra Claudia", "Maestri Tassoni Michelangelo", "Frangiamore Rita"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/23 18:11", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41576890/", "pub_types": ["Letter"], "affiliations": ["Department of Biomedicine, Neuroscience and Advanced Diagnostics (BiND), University of Palermo, 90127 Palermo, Italy. Electronic address: vincenzo.distefano07@unipa.it."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41576642", "title": "Low prevalence of inflammatory bowel disease among patients with seropositive neuromyelitis optica spectrum disorder in two large referral centers.", "abstract": "Patients with Neuromyelitis Optica Spectrum Disorders (NMOSD) have a well-recognized predilection to autoimmune comorbidities, of which systemic lupus erythematosus (SLE), Sjögren's syndrome (SjS), and autoimmune thyroid diseases are the most common. The question of whether some autoimmune diseases, such as inflammatory bowel disease (IBD), may not be overrepresented (or may even be underrepresented) in NMOSD has not received much attention. Here, we retrospectively reviewed the electronic medical records of all patients diagnosed with NMOSD in our two large referral centers (NYU and MGB), as well as patients with two neuroinflammatory disorders as comparator groups (myelin oligodendrocyte glycoprotein antibody disease (MOGAD) and MS), and calculated the rates of IBD, SLE, SjS, autoimmune thyroid disorders, and myasthenia gravis (MG) in these groups. We found that 1 out of 347 NMOSD patients had a diagnosis of IBD (0.3%), and this patient was seronegative for anti-AQP4 autoantibodies, while 4/271 patients in the MS group (1.5%), 2 of whom were exposed to anti-CD20 therapy, had IBD, and 2/366 MOGAD patients (0.8%), neither of whom was exposed to anti-CD20 therapy, had IBD. In contrast, the rate of the other four autoimmune conditions was significantly higher in NMOSD (24%) than in MOGAD (8.5%, p < 0.0001) or MS (5.2%, p < 0.0001). Thus, IBD was not diagnosed in any of our 317 seropositive NMOSD patients, despite the fact that this group had a higher use of B-cell depletion than patients with MS and MOGAD. We discuss the various hypotheses that may explain this observation.", "authors": ["Akers Carolyn", "Bilodeau Philippe A", "Clark Mattia Wruble", "Hashemzadeh Taymour", "Levy Michael", "Bhattacharyya Shamik", "Kister Ilya"], "journal": "Multiple sclerosis and related disorders", "entry_date": "2026/01/23 18:05", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41576642/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["NYU Multiple Sclerosis Comprehensive Care Center, Department of Neurology, New York University Grossman School of Medicine, NY, NY, 10016, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41575277", "title": "Immune dysregulation driven by elevated platelet-to-lymphocyte ratio aggravates myasthenia gravis.", "abstract": "ObjectivePrevious studies have suggested a potential association between the platelet-to-lymphocyte ratio and disease activity in myasthenia gravis. However, the immunological mechanisms underlying this association remain insufficiently elucidated.MethodsA retrospective cohort of 229 patients with myasthenia gravis and a single-cell RNA sequencing dataset were analyzed to investigate the relationship between platelet-to-lymphocyte ratio and disease severity. Clinical associations were assessed using the Myasthenia Gravis Foundation of America classification and multivariable logistic regression, while single-cell RNA sequencing data were integrated to characterize immune alterations associated with elevated platelet-to-lymphocyte ratio.ResultsPatients with severe myasthenia gravis had longer disease duration and higher frequencies of bulbar symptoms, thymoma, and repetitive nerve stimulation positivity (all p < 0.001). Although median platelet-to-lymphocyte ratio values did not demonstrate significant groupwise differences (p = 0.108), multivariate analysis confirmed that an elevated platelet-to-lymphocyte ratio was independently associated with greater myasthenia gravis severity (adjusted odds ratio = 1.027, 95% confidence interval: 1.003-1.052, p = 0.034). Single-cell RNA sequencing revealed immune dysregulation in patients with a high platelet-to-lymphocyte ratio, characterized by increased platelets and neutrophils, reduced natural killer cells, and upregulation of platelet activation, cell-cell adhesion, and integrin-mediated signaling pathways, indicating a shift toward innate immune activation and impaired immune coordination.ConclusionElevated platelet-to-lymphocyte ratio independently predicts myasthenia gravis severity and may reflect immune dysregulation that contributes to disease progression and neuromuscular junction dysfunction.", "authors": ["Luo Si", "Song Ziwei", "Zhawatibai Alina", "Qiu Yusen", "Li Menghua", "Zhu Yu", "Yu Yanyan", "Zhou Meihong", "Hong Daojun"], "journal": "The Journal of international medical research", "entry_date": "2026/01/23 09:33", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41575277/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital, Jiangxi Medical College, Nanchang University, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "41574649", "title": "Myasthenia Gravis Outcomes After Use of Statins and Other Contraindicated Treatments: Results From the French National Insurance Database.", "abstract": "BACKGROUND: Clinical guidelines for treating myasthenia gravis (MG) recommend avoiding certain therapies because of a risk of exacerbating MG. We evaluated use of statins and other classically contraindicated therapies and their impact on healthcare outcomes among patients with MG in France.\nMETHODS: This was an observational, retrospective, longitudinal cohort study using data from the French national health insurance database. Adult patients with MG-related claims from 2013 to 2020 were included. The first MG claim date was the index date, with follow-up until end-of-study or death. Multivariable regression models evaluated the risk of intensive care unit (ICU) admission for MG or death during periods of exposure versus nonexposure to contraindicated treatments.\nRESULTS: Of 14,459 individuals with MG, 12,954 (89.6%) received a contraindicated treatment during follow-up, and 4160 (28.8%) received statins. In multivariable regression analyses, exposure to any contraindicated treatment was not significantly associated with risk of ICU admission for MG (hazard ratio [HR] 1.038; 95% confidence interval [CI] 0.968-1.113; p = not significant) but was associated with significantly higher risk of death (HR 1.167; 95% CI 1.075-1.266; p < 0.001) versus nonexposure. In contrast, statins were associated with a greater risk of ICU admission (HR 1.133; 95% CI 1.065-1.205; p < 0.001) but lower risk of death (HR 0.626; 95% CI 0.565-0.694; p < 0.001).\nCONCLUSION: This large, real-world study suggests that for some contraindicated medications, including statins, longer-term mortality benefits are likely to outweigh short-term risks of exacerbating MG.", "authors": ["Solé Guilhem", "Camdessanché Jean Philippe", "Attarian Shahram", "Ciumas Mariana", "Blein Cécile", "Grenier Benjamin", "Herquelot Eléonore", "Echaniz-Laguna Andoni"], "journal": "European journal of neurology", "entry_date": "2026/01/23 06:22", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41574649/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Neuromuscular Reference Center AOC, Neurology and Neuromuscular Diseases Department, Pellegrin Hospital, Bordeaux University Hospitals, Filnemus, Euro-NMD, Bordeaux, France."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41573440", "title": "Unilateral Ptosis and Bulbar Symptoms as the Initial Presentation of Late-Onset Acetylcholine Receptor Antibody-Positive Myasthenia Gravis Mimicking Acute Ischemic Stroke in an 82-Year-Old Man.", "abstract": "Myasthenia gravis is an autoimmune disorder of the neuromuscular junction. In older adults, it may present with bulbar and ocular symptoms that resemble acute stroke. Ocular myasthenia is typically asymmetric and often bilateral; persistent unilateral ptosis in this context can be misleading. An 82-year-old man with type 2 diabetes mellitus, chronic kidney disease, cataracts, and macular degeneration presented with a two-week history of fatigable dysphagia, slurred speech, and new-onset unilateral left ptosis. Symptoms were worse towards the end of the day. He denied diplopia and limb weakness. On examination, he was alert with marked left ptosis, mild left facial weakness, and normal limb strength and gait. A working diagnosis of ischemic stroke was made. Computed tomography of the head, magnetic resonance imaging of the brain with magnetic resonance angiography, and carotid Doppler ultrasound showed no acute vascular pathology. Speech and language therapy assessment demonstrated moderately dysarthric but functional speech and a safe swallow using compensatory strategies. ENT review was arranged as a safety assessment to exclude structural lesions or throat pathology in view of his recent swallowing difficulty, sensation of food sticking on the left side, and intermittent nasal speech later in the day; flexible nasal endoscopy was normal. Neurology review noted fluctuating bulbar symptoms with isolated unilateral ptosis, normal extraocular movements, and a normal limb examination, raising suspicion for myasthenia gravis. Pyridostigmine was started with rapid improvement in ptosis, speech, and swallowing. By the following day, both eyes were open, and he was seen reading, although transient recurrence of ptosis was observed during reassessment, consistent with fatiguability. Computed tomography of the chest excluded thymoma. During brief withdrawal of pyridostigmine for neurophysiology, unilateral ptosis and dysphagia recurred. Nerve conduction studies and limited single-fibre electromyography were non-diagnostic. Subsequent serology confirmed positive acetylcholine receptor antibodies (13.8) and negative anti-MuSK antibodies. He was treated with pyridostigmine and oral prednisolone with gastric and bone protection and close monitoring of glycaemic control. At follow-up, he remained asymptomatic, with full resolution of unilateral ptosis and bulbar symptoms. Persistent unilateral ptosis with fluctuating bulbar symptoms in an elderly patient, normal neuroimaging, and preserved limb strength should prompt consideration of myasthenia gravis despite an initial stroke pathway. As most cases classically present before the age of 50-60 years, this presentation in an 82-year-old man also illustrates very late-onset acetylcholine receptor antibody-positive disease. This case highlights that unilateral ocular involvement does not exclude myasthenia gravis and that close attention to fatigability and symptom evolution can prevent misdiagnosis and support timely, appropriate treatment.", "authors": ["Mangrio Sughra M", "Faisal Sadia", "Malik Zoya", "Naeem Ahmed", "Saeed Urooj"], "journal": "Cureus", "entry_date": "2026/01/23 04:54", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41573440/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["General Internal Medicine, Russells Hall Hospital, Dudley, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41572859", "title": "Organ-specific autoimmunity in primary Sjögren's disease.", "abstract": "OBJECTIVE: To assess the prevalence of organ-specific autoimmunity (OSA) among patients with primary Sjögren's disease (SjD), and its association with clinical and serological variables and disease activity.\nMETHOD: We included 328 patients with SjD according to ACR/EULAR criteria. We recorded the following types of OSA: gastrointestinal [primary biliary cholangitis (PBC), autoimmune hepatitis (AH), coeliac disease], haematological (pernicious anaemia, haemolytic anaemia, idiopathic thrombocytopenia purpura), neurological (myasthenia gravis), dermatological (vitiligo, alopecia areata), and endocrinological (autoimmune thyroid disease and type 1 diabetes). We also registered demographics, basal Schirmer I test, non-stimulated whole salivary flow, serological variables, treatment (ever), and basal and cumulative EULAR Sjögren's Syndrome Disease Activity Index (ESSDAI) score at last follow-up.\nRESULTS: We found OSA in 122 patients (37.9%), the most frequent being autoimmune hypothyroidism (n = 56), PBC (n = 28), and AH (n = 8). OSA preceded SjD in 37 patients (30.3%), followed it in 62 (50.8%), and was concomitant in 23 (18.8%). In logistic regression analysis comparing patients with OSA (concomitant/post-SjD diagnosis) versus those without OSA, the variables associated with OSA were anti-Ro/SSA [odds ratio (OR) 0.44, 95% confidence interval (CI) 0.20-0.97, p = 0.04], disease duration (OR 1.03, 95% CI 1.005-1.06, p = 0.01), and use of methotrexate (OR 0.32, 95% CI 0.55-0.73, p = 0.007) and azathioprine (OR 2.12, 95% CI 1.14-3.84, p = 0.01).\nCONCLUSION: One-third of patients with primary SjD had OSA, with endocrine involvement being the most common. OSA may precede, follow, or accompany the diagnosis of SjD, and is not associated with higher disease activity. Monitoring for OSA is important as it contributes to comorbidity in these patients.", "authors": ["Garcia-Torralba A", "Hernández-Molina G"], "journal": "Scandinavian journal of rheumatology", "entry_date": "2026/01/23 03:43", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41572859/", "pub_types": ["Journal Article"], "affiliations": ["Department of Immunology and Rheumatology, Instituto Nacional de Ciencias Médicas y Nutrición Salvador Zubirán, Mexico City, Mexico."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41572778", "title": "Efgartigimod in Very-Late-Onset Generalized Myasthenia Gravis: A Real-World Study on Effectiveness and Safety.", "abstract": "INTRODUCTION: This study evaluated the safety and effectiveness of efgartigimod in patients with Very-Late-Onset Generalized Myasthenia Gravis (VLOGMG), a population that often presents with more severe symptoms and limited treatment responses.\nMETHODS: Forty-two patients aged ≥ 65 years were retrospectively included. Clinical assessments, including MG activities of Daily Living (MG-ADL), Quantitative Myasthenia Gravis (QMG) scores, prednisone dosage, laboratory data, and adverse events, were recorded at each follow-up.\nRESULTS: At week 4, 97.6% (41/42; 95% CI, 87.4-99.9) of patients were MG-ADL responders (≥ 2- point improvement). Notably, 83.3% (95% CI, 69.4-92.8) maintained response through week 12 (p < 0.001). Clinically meaningful improvement (CMI, ≥3-point QMG decrease) occurred in 97.6% of patients (41/42; 95% CI, 87.4-99.9), with a mean response time of 6.37 ± 5.46 days (95% CI, 4.63- 8.11). Minimal symptom expression (MSE, MG-ADL score of 0 or 1) was achieved in 45% (95% CI, 30-61%), 60% (95% CI, 44-74%), and 45% (95% CI, 30-61%) of patients at weeks 4, 8, and 12, respectively. Prednisone dosage was tapered from a median of 20 (20, 30) mg/day to 10 (5, 15) mg/day by week 12. Most patients (88.1%) had ≥ 1 comorbidity, and 61.9% had multimorbidity. Efgartigimod was well tolerated, without evidence of worsening of pre-existing conditions.\nDISCUSSION: Efgartigimod provided rapid symptom relief in older adults with VLOGMG and demonstrated steroid-sparing benefits across patients with various comorbidities. The high response rates and sustained improvement suggest that early use of fast-acting therapies may serve as a bridge to conventional long-term treatments. Larger prospective studies are warranted to confirm these findings.\nCONCLUSION: Efgartigimod is associated with clinical benefit in patients with VLOGMG, allowing corticosteroid reduction without compromising comorbidity stability. Early initiation may enable faster disease control and more durable responses.", "authors": ["Ma Chi", "Shen Jingyi", "Zhu Ying", "Wang Benqiao", "Zhu Ruixia"], "journal": "Current neuropharmacology", "entry_date": "2026/01/23 02:08", "pub_date": "2026-01-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41572778/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of China Medical University, Key Laboratory of Neurological Disease Big Data of Liaoning Province, Shenyang Clinical Medical Research Center for Difficult and Serious Diseases of the Nervous System, Shenyang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "41572404", "title": "Myasthenia Gravis and its Rare Association with Castleman's Disease.", "abstract": "", "authors": ["Rao Rindha V", "Chowdary Divya Teja", "Yareeda Sireesha", "Uppin Megha S", "Srivastava Madhur Kumar", "Turaga Surya Prabha", "Shaik Reshma Sultana"], "journal": "Annals of Indian Academy of Neurology", "entry_date": "2026/01/22 23:56", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41572404/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Nizam's Institute of Medical Sciences, Hyderabad, Telangana, India."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "41570772", "title": "Immune-related disorders in patients with Thymic Epithelial Tumors: from pathogenesis to tailored interventions.", "abstract": "BACKGROUND AND OBJECTIVE: Thymic epithelial tumors (TETs) are rare malignancies often associated with immunological disorders (IDs), including autoimmune diseases and paraneoplastic syndromes. Myasthenia gravis (MG) is the most frequently reported condition, although other IDs can manifest across various organ systems. This review aims to give an overview of the current knowledge on the epidemiology, pathogenesis, and management of IDs associated with TETs, emphasizing their prognostic impact and challenges in clinical practice.\nMETHODS: We performed a narrative review using PubMed and Embase databases to identify relevant literature published between January 1971 and October 2024. Keywords included \"thymic epithelial tumors\", \"immunological disorders,\" \"autoimmune diseases,\" and \"paraneoplastic syndromes.\" Only peer-reviewed articles in English were included.\nKEY CONTENT AND FINDINGS: This review examines the association of TETs with the most frequent IDs, including MG, pure red cell aplasia, and Good's syndrome. The prognostic implications of IDs in TETs remain unclear, and the available literature presents conflicting data. While some studies suggest correlations with favourable outcomes, others fail to establish IDs as independent prognostic factors for recurrence-free survival (RFS) or overall survival (OS).\nCONCLUSIONS: The management of TETs with associated IDs requires a multidisciplinary approach that integrates tumor-specific treatments and tailored interventions for immune-related disorders. Advances in understanding molecular mechanisms have shed light on their pathogenesis. Nevertheless, gaps persist regarding prognostic implications and long-term management. Future efforts should focus on identifying predictive biomarkers for immune complications, optimizing therapies, and enhancing international data collection to clarify the impact of IDs on patient outcomes.", "authors": ["Pietroluongo Erica", "Palmieri Giovannella", "Ascierto Paolo Antonio", "Ottaviano Margaret"], "journal": "Lung cancer (Amsterdam, Netherlands)", "entry_date": "2026/01/22 18:11", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41570772/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Clinical Medicine and Surgery, University of Naples Federico II, Naples, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "41567119", "title": "A case of immune-related adverse events, thyroid dysfunction, myocarditis with myositis, and myasthenia gravis overlap syndrome following serplulimab administration for lung adenocarcinoma.", "abstract": "BACKGROUND: Serplulimab is an immune checkpoint inhibitor (ICI) that blocks inhibitors, augmenting anti-tumor immunity but also carrying risks of immune-related adverse events (irAEs). While neuromuscular and cardiac toxicities are rare, their co-occurrence can lead to high mortality. In this article, we report a patient with multiorgan irAEs after treatment with chemoimmunotherapy.\nCASE PRESENTATION: A 49-year-old man with lung adenocarcinoma developed thyroid dysfunction 3 weeks after initial chemoimmunotherapy (carboplatin, pemetrexed, serplulimab). Following the second cycle, he presented with speech difficulty, bilateral ptosis, dysphagia, fatigue, and elevated creatine kinase (2112 U/L) and troponin T (570 ng/L), suggesting ICI-induced thyroid dysfunction, myocarditis, myositis, and myasthenia gravis overlap syndrome. Brain magnetic resonance imaging was negative. He received methylprednisolone with initial improvement, but troponin elevation recurred after premature steroid discontinuation. Successful treatment was achieved with high-dose methylprednisolone and intravenous immunoglobulin, leading to normalized cardiac markers.\nCONCLUSIONS: The serplulimab-induced multiorgan irAEs necessitates enhanced monitoring, biomarker research, and multidisciplinary collaboration to optimize safety and antitumor efficacy.\nThis report describes a serious but rare reaction to a type of cancer immunotherapy in a 49-year-old man with lung cancer. The treatment, designed to help his immune system attack cancer, accidentally caused it to attack several of his own healthy organs. Shortly after his treatment, he developed symptoms like unclear speech, drooping eyelids on both sides, coughing while drinking water, fatigue after activity, and poor mental state. Doctors found that his heart, muscles, and thyroid gland were immune-related adverse events. He was successfully treated by stopping the cancer immunotherapy and giving him medicines to calm down his overactive immune system. However, his symptoms returned when he stopped these medicines too early, showing how important it is to follow the treatment plan closely. This case reminds us that while these immunotherapies are powerful cancer fighters, they require careful monitoring for side effects, and both doctors and patients need to work together to manage them safely.", "authors": ["Li Xiaoliang", "Feng Qi", "Yu Yuan", "Zhao Xudong", "Wang Pengxi", "Tang Dafu", "Yu Hailiang"], "journal": "Immunotherapy", "entry_date": "2026/01/22 04:33", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41567119/", "pub_types": ["Journal Article"], "affiliations": ["Department of Lung Cancer Medical Center, West China Tianfu Hospital, Sichuan University, Chengdu, Sichuan, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "41567052", "title": "[Neurology : what's new in 2025].", "abstract": "In 2025, several major advances have marked the field of neurology. Anti-FcRN and anti-C5 antibodies have confirmed their long-term efficacy in the treatment of myasthenia gravis. Bruton tyrosine kinase inhibitors have expanded the therapeutic arsenal for multiple sclerosis. An antibody targeting α-synuclein appears to slow motor decline in early-stage Parkinson's disease. The efficacy of late thrombolysis in strokes with radiological mismatch has been confirmed. A blood biomarker facilitates early detection of Alzheimer's disease, and Swiss guidelines specify the modality for the use of anti-amyloid therapies in this disease. Finally, in pregnant women with epilepsy, the recommended dose of folic acid has been reduced.\nEn 2025, la neurologie a fait l’objet de nombreuses et importantes nouveautés. Les anti-FcRN et les anti-C5 confirment leur efficacité au long cours dans la myasthénie. Les inhibiteurs de la Bruton kinase viennent renforcer l’arsenal de la sclérose en plaques. Un anticorps ciblant l’α-synucléine semble ralentir le déclin moteur dans la maladie de Parkinson débutante. L’efficacité de la thrombolyse tardive dans les AVC avec mismatch radiologique est confirmée. Un biomarqueur sanguin facilite la détection précoce de maladie d’Alzheimer et des recommandations suisses précisent les modalités des traitements anti-amyloïdes dans cette maladie. Enfin, chez les femmes enceintes souffrant d’épilepsie, la dose recommandée d’acide folique est revue à la baisse.", "authors": ["Tziakouri Andria", "Loser Valentin", "Vicino Alex", "Baumgartner Thomas", "Di Liberto Giovanni", "Pantazou Vasiliki", "Bernard-Valnet Raphaël", "Theaudin Marie", "Pot Caroline", "Castro-Jimenez Mayte", "Hübsch Cecile Alexandra", "Bally Julien", "Strambo Davide", "Hirt Lorenz", "Caranzano Leonardo", "Rouaud Olivier", "Allali Gilles", "Salvioni Paolo", "Sokolov Arseny A", "Pignat Jean-Michel", "Ryvlin Philippe", "Perrenoud Matthieu P", "Rossetti Andrea O", "Novy Jan", "Beuchat Isabelle", "Du Pasquier Renaud", "Michel Patrik"], "journal": "Revue medicale suisse", "entry_date": "2026/01/22 04:03", "pub_date": "2026-01-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41567052/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Service de neurologie, Département des neurosciences cliniques, Centre hospitalier universitaire vaudois et Université de Lausanne, 1011 Lausanne."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41565840", "title": "Letter to the editor: Severe myasthenic crises following infiltration of amide local anesthetics in a patient with myasthenia gravis: an unusual adverse reaction.", "abstract": "", "authors": ["Bouaziz Imen", "Atheymen Rim", "Sahnoun Rym", "Ksouda Kamilia", "Affes Hanen", "Hammami Serria", "Zghal Khaled"], "journal": "European journal of clinical pharmacology", "entry_date": "2026/01/21 23:26", "pub_date": "2026-01-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41565840/", "pub_types": ["Letter"], "affiliations": ["Regional Center of Pharmacovigilance of Sfax, Pharmacology Laboratory, Faculty of Medicine of Sfax, 3029, Sfax, Tunisia. imenbouaziz34@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "41565210", "title": "Cardiac adverse events associated with dual immune checkpoint inhibitors: a pharmacovigilance analysis from the FDA adverse event reporting system.", "abstract": "AIMS: Immune-related adverse events(irAEs) are common among cancer patients receiving dual immune checkpoint inhibitors (ICI). Cardiac adverse events rank among the most severe categories of such reactions. This study aims to investigate the characteristics and influencing factors of cardiac adverse events associated with dual ICIs.\nMETHODS AND RESULTS: We collected data on cardiac adverse events associated to dual ICIs from the US Food and Drug Administration Adverse Event Reporting System database (FAERS), covering the period from the first quarter of 2015 to the fourth quarter of 2024. A disproportionality analysis was performed to assess the association between different dual ICIs and cardiac adverse events, and a comprehensive study was conducted to identify potential influencing factors. Cardiac adverse events accounted for 7.5% of all ICI adverse event reports in the FAERS database. Nivolumab plus ipilimumab was associated with the highest number of significant preferred term (PT) signals, while durvalumab plus tremelimumab had the highest percentage of life-threatening outcomes. The median onset time for cardiac adverse events following dual ICIs therapy was 32 days (IQR 15-77). Myositis and myasthenia gravis were the most commonly co-reported extracardiac conditions in myocarditis cases, whereas complete atrioventricular block and cardiogenic shock were the most frequently reported intracardiac complications. Older patients, males, and those with kidney cancer were at higher risk of developing cardiac adverse events.\nCONCLUSION: This study identified distinct associations between different dual ICIs treatment strategies and various cardiac adverse events. We further identified potential risk factors and co-reported symptoms of cardiotoxicity, which may aid in the early diagnosis and monitoring of ICI-associated cardiac adverse events.", "authors": ["Xia Huang", "Shi Lei", "Luo Shuimei", "Sun Zequn", "Quan Mengru", "Xiao Huazhen", "Chen Yu", "Lin Jing"], "journal": "European heart journal. Cardiovascular pharmacotherapy", "entry_date": "2026/01/21 19:15", "pub_date": "2026-02-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41565210/", "pub_types": ["Journal Article"], "affiliations": ["Department of Phase I Clinical Trial Ward, Clinical Oncology School of Fujian Medical University, Fujian Cancer Hospital, Fuzhou, Fujian Province 350000, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 6.1, "journal_quartile": "1区"}, {"pmid": "41559594", "title": "Double-seronegative myasthenia gravis: clinical characteristics, treatment, and outcomes - a systematic review of case reports and case series.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune condition characterized by muscle weakness caused by antibodies targeting the postsynaptic neuromuscular junction. The majority of patients test positive for antibodies against the acetylcholine receptor (AChR) or muscle-specific kinase (MuSK). A minority of patients test negative for these antibodies and are referred to as double-seronegative MG (dSNMG), a condition that remains inadequately studied and incompletely characterized.\nMETHODS: We conducted a systematic review in accordance with PRISMA guidelines (PROSPERO registration: CRD42022368329). We performed a thorough search of PubMed and Google Scholar through October 2022 for English-written studies reporting confirmed dSNMG cases. Inclusion criteria required confirmed MG diagnosis with negative testing for AChR and MuSK antibodies. Abstract and full-text screening was performed independently by two reviewers. This was followed by data extraction, descriptive analyses, and assessment of the quality of the selected reports.\nRESULTS: We included 40 articles (35 case reports and five case series) accounting for 45 patients with dSNMG. The mean age at diagnosis was 52.4 ± 20.5 years, and the mean age at symptom onset was 50.7 ± 21.4 years, with 51% being female. The most common initial manifestations were ocular (ptosis and/or diplopia) accounting for 82% of cases. Of these, 29% had purely ocular MG, whereas 71% showed generalized MG at onset. Nine patients (20%) were positive for low-density lipoprotein receptor-related protein 4 (LRP4) antibodies. Malignancy was observed in 15 patients (33%), including five cases with thymoma and 10 cases with extrathymic malignancies. Among the latter, eight had been previously treated with immune checkpoint inhibitors (ICIs). Thymoma patients tended to be younger (mean 55.6 years) and more frequently female (60%) compared to patients with extrathymic cancers (mean 69.2 years, 30% female). Those with extrathymic malignancies had higher rates of ocular presentation and myasthenic crisis (40% vs. 20%) for each compared with the thymoma group. Standard MG treatments were administered to all patients, most frequently acetylcholinesterase inhibitors (84%) and corticosteroids (76%), often combined with other immunosuppressants and/or IVIG. Overall outcomes were favorable, especially among those treated with plasmapheresis, rituximab, or tacrolimus. No severe treatment-related adverse events were reported.\nCONCLUSIONS: Patients with dSNMG often present with ocular symptoms and typically respond well to conventional MG therapies. Some patients classified as seronegative may harbor LRP4 or other antibodies. Malignancy, particularly following ICI therapy, was a prevalent comorbidity. Thymoma-related dSNMG was more frequently seen in younger women and involved generalized weakness, while extrathymic malignancy cases tended to occur in older patients with a higher occurrence of ocular MG and myasthenic crisis. These differences highlight the need for thorough malignancy screening in dSNMG patients as well as neuromuscular monitoring in cancer patients on ICIs. Further investigation is warranted to validate these observations and clarify specific clinical implications related to the management of dSNMG.", "authors": ["Abuhammad Aseel", "Ayyad Mohammed", "Albandak Maram", "AbuKhalaf Salsabeel M", "Madia Arein", "Qawasma Basema", "AbuKhalaf Muhammad M", "Thraiee Yazan Abu", "Zuaiter Bashar", "Alamleh Laith"], "journal": "BMC neurology", "entry_date": "2026/01/20 23:45", "pub_date": "2026-01-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41559594/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Faculty of Medicine, Al-Quds University, Jerusalem, State of Palestine."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41555504", "title": "Surgical Management of Unexpected Thymic Anatomical Variations During Thoracoscopic Thymectomy.", "abstract": "OBJECTIVES: Complete thoracoscopic thymic resection is crucial for achieving sternotomy-comparable outcomes in myasthenia gravis patients. Thymic anatomy varies significantly, presenting features like retro-left brachiocephalic vein (LBCV) horns and thymic ring. Surgeons encountering these variations may miss abnormal thymic tissue or face intraoperative challenges. This research aims to report on the thoracoscopic management of thymic variations, illustrating their perioperative outcomes.\nMETHODS: This retrospective observational study was conducted from September 2016 to September 2024. A total of 255 myasthenic patients underwent thoracoscopic thymectomy and were categorized into Normal (n = 227) and Variant (n = 28) groups based on intraoperative anatomical variations. Primary outcomes were operative time and blood loss. Secondary outcomes included hospital stay and postoperative outcomes. Perioperative data were compared between groups.\nRESULTS: In the Variant group, the most commonly identified anatomical variations were thymus with \"more than 2 horns\" (12 patients, 42.9%), followed by retro-LBCV horns (9 patients, 32.2%). The mean operative time was significantly longer in the Variant group (209.36 ± 53.69 minutes) compared to the Normal group (177.26 ± 57.41 minutes) (P = .005). Otherwise, both groups did not exhibit significant differences regarding other perioperative data and neurological outcomes.\nCONCLUSIONS: Thoracoscopic thymectomy can be safely and effectively performed even in the presence of thymic anatomical variations, especially when they are preoriented by the surgeon. While these variations may lead to longer operative times, they do not compromise completeness of resection and other short-term postoperative outcomes.", "authors": ["Abdellateef Amr", "Bastawisy Amir", "Saied Ahmed", "Elsorogy Hatem", "Keshta Mohammed"], "journal": "European journal of cardio-thoracic surgery : official journal of the European Association for Cardio-thoracic Surgery", "entry_date": "2026/01/20 00:11", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41555504/", "pub_types": ["Journal Article"], "affiliations": ["Cardiothoracic Surgery Department, Mansoura University Cardiothoracic and Vascular Surgery Center, Mansoura University Faculty of Medicine, Mansoura 35511, Egypt."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41555182", "title": "[A Case of Robot-Assisted Thoracoscopic Extended Thymectomy for Thymoma Associated with Generalized Myasthenia Gravis].", "abstract": "A 53-year-old male patient presented with dyspnea and was admitted with the diagnosis of bacterial pneumonia.His respiratory condition did not improve despite the resolution of fever with antibiotic therapy, and he was eventually diagnosed with thymoma associated with myasthenia gravis.The patient underwent robot-assisted thoracoscopic extended thymectomy under general anesthesia.The anterior mediastinal tissue was resected en bloc using 5 ports and the port-hopping function of the robotic system.The operation time was 264 min, and the blood loss was 55 g.Histopathologic examination led to the definitive diagnosis of type B2 thymoma.Postoperatively, muscle strength improved, oral intake resumed after extubation, and the patient was transferred to rehabilitation on day 35.Achieving adequate dissection without approaching from both the right and left sides is generally challenging in resecting mediastinal tissue via thoracoscopic extended thymectomy.The subxiphoid approach may pose similar limitations.However, in the present case, the use of the port-hopping function during robot-assisted surgery allowed scope insertion from various positions, enabling excellent visualization.", "authors": ["Yamaguchi Tomoyuki", "Akai Serina", "Uozumi Nozomi", "Yasuda Koji", "Shintani Hiroshi"], "journal": "Gan to kagaku ryoho. Cancer & chemotherapy", "entry_date": "2026/01/19 23:34", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41555182/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Dept. of Surgery, Keiseikai Hospital."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41553721", "title": "Eculizumab as a Fast-Acting Therapy in a Myasthenic Crisis Patient With Poor Response to Efgartigimod: A Case Report.", "abstract": "INTRODUCTION: Myasthenic crisis (MC) is the most serious manifestation of myasthenia gravis (MG) and it poses a big challenge in clinical management. Plasma exchange and intravenous immunoglobulin are the first-line therapy for MC, but a subset of patients exhibit poor response. Recently, neonatal Fc receptor (FcRn) inhibitors and complement inhibitors showed great efficacy in MC. However, there is no report on whether eculizumab can serve as a rescue therapy for patients who have not responded to efgartigimod.\nCASE REPORT: This case report describes a Chinese patient with generalized MG who experienced an acute exacerbation and suffered from MC. Despite poor responsiveness to efgartigimod, the patient was successfully rescued with eculizumab. Under regular treatment with eculizumab once every 2 weeks, the patient achieved a status of minimal symptom expression. However, the efficacy of eculizumab in MC has yet to be confirmed through more clinical trials.\nCONCLUSIONS: This case report hints the potential of complement inhibitors as viable treatments alternative for MC patients who poorly respond to antibody-clearing therapy. Besides, further research is necessary to determine the preferred or suitable treatment option for specific patients.", "authors": ["Zhang Zhouao", "Guo Xinyan", "Luo Tiancheng", "Yang Mingjin", "Ma Tianyu", "Du Xue", "Wang Zhouyi", "Huang Xiaoyu", "Zhang Yong"], "journal": "The neurologist", "entry_date": "2026/01/19 11:23", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41553721/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, Jiangsu."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41552382", "title": "A comment on \"Electrodiagnostic criteria for neuromuscular transmission disorders suggested by a European consensus group\".", "abstract": "", "authors": ["Das Pektezel Leyla", "Pektezel Mehmet Yasir"], "journal": "Clinical neurophysiology practice", "entry_date": "2026/01/19 06:25", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41552382/", "pub_types": ["Letter"], "affiliations": ["Department of Clinical Neurophysiology, Necip Fazil City Hospital, Kahramanmaras, Türkiye."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "4区"}, {"pmid": "41552140", "title": "Seropositive Myasthenia Gravis Triggered by Lyme Disease: A Case Study of Molecular Mimicry.", "abstract": "Lyme disease, caused by Borrelia burgdorferi, is a multisystem infection that rarely produces neuromuscular complications beyond classic neuroborreliosis. Myasthenia gravis (MG) is an autoimmune disorder characterized by fatigable weakness due to acetylcholine receptor (AChR) antibodies. We describe a 74-year-old man with coronary artery disease, chronic kidney disease, and prostate cancer who developed progressive dysphagia, dysphonia, ptosis, and neck weakness. Initial attribution to medication-related angioedema delayed recognition. Neurological examination revealed bulbar weakness and fatigable ptosis. Electrodiagnostic testing confirmed post-synaptic neuromuscular junction dysfunction, and AChR antibody assays were strongly positive across binding, blocking, and modulating subtypes. Concurrent Lyme serologies were positive for immunoglobulin G and immunoglobulin M. The patient required intensive care monitoring and was treated with plasma exchange, intravenous ceftriaxone, prednisone, and pyridostigmine, with marked improvement. This case illustrates a rare coexistence of neuroborreliosis and seropositive MG, highlighting potential molecular mimicry between Borrelia antigens and AChR epitopes.", "authors": ["Sardana Sahil", "Grieco Emily", "MacGavin Samantha", "Shakeel Hassan Abdullah", "Piccinnin Meghan", "Gill Taranjit Singh"], "journal": "Cureus", "entry_date": "2026/01/19 06:23", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41552140/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Allegheny Health Network, Pittsburgh, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41551145", "title": "Case Report: Immune checkpoint inhibitor-associated myocarditis in an esophageal cancer patient with myasthenia gravis following combined radiotherapy and immunotherapy.", "abstract": "Myocarditis associated with immune checkpoint inhibitors is a rare but potentially fatal immune-related adverse event. Esophageal cancer patients with myasthenia gravis, who are recommended to receive radiotherapy combined with immunotherapy, are at risk for ICI-related myocarditis. We report a 69-year-old male esophageal cancer patient with myasthenia gravis who was diagnosed with immune checkpoint inhibitor related myocarditis after receiving radiotherapy combined with immunotherapy. The patient's laboratory test results showed elevated troponin and N-terminal pro-B-type natriuretic peptide. Electrocardiography revealed arrhythmia and complete left bundle branch block. Despite treatment with methylprednisolone, the patient's condition was severe, and clinical and auxiliary examination symptoms continued to deteriorate, leading to his unfortunate demise. In this case, the adverse event of myocarditis induced by radiotherapy combined with immunotherapy in oncology patients with myasthenia gravis is an area that requires further investigation. Clinicians must carefully weigh the potential benefits and risks when considering this combined treatment approach and closely monitor patients for adverse events.", "authors": ["Ren Xue", "Yang Defu", "Xu Ying", "Yan Ying"], "journal": "Frontiers in oncology", "entry_date": "2026/01/19 06:14", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41551145/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Radiation Oncology, General Hospital of Northern Theater Command, Shenyang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "41548740", "title": "Fiber-type-specific architecture and pathophysiology of the neuromuscular junction.", "abstract": "The neuromuscular junction (NMJ) is a specialized synapse essential for translating neuronal signals into muscle contraction. This review examines the complex structural, functional, and molecular differences in NMJs that innervate fast- and slow-twitch skeletal muscle fibers. Fast-twitch fibers, optimized for rapid and powerful contractions, possess elaborate NMJs with deep folds, high neurotransmitter turnover, and greater vulnerability to synaptic fatigue and degeneration. In contrast, slow-twitch fiber NMJs exhibit simpler but more stable architectures that support sustained, fatigue-resistant activity. These differences are not fixed but subject to activity-dependent plasticity and pathological remodeling. Chronic stimulation, injury, and aging influence NMJ morphology, with fast-twitch junctions more prone to degeneration in conditions such as ALS, myasthenia gravis, and diabetic neuropathy. Slow-twitch NMJs often resist early deterioration due to superior trophic support, metabolic stability, and more robust expression of synaptic organizers, such as agrin and PGC-1α. Several key signaling pathways, including agrin-MuSK-LRP4, Wnt/β-catenin, and neuregulin/ErbB, govern NMJ maintenance with fiber-type-specific nuances. These insights underscore the importance of tailoring therapeutic strategies to the muscle fiber phenotype. Gene therapies, neuromuscular electrical stimulation, and biomaterial scaffolds are emerging as promising modalities for preserving or restoring NMJ integrity, especially in fast-twitch fibers at higher risk of degeneration. Understanding fiber-type-specific NMJ biology enhances our understanding of motor control, muscle aging, and neuromuscular disease progression, and it opens pathways for precision therapeutics that target vulnerable synapses with structural and functional specificity. This review introduces a novel perspective by emphasizing fiber-type-specific NMJ differences and their implications for targeted therapies.", "authors": ["Qaisar Rizwan"], "journal": "Neuroscience", "entry_date": "2026/01/18 19:12", "pub_date": "2026-03-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41548740/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Basic Medical Sciences, College of Medicine, University of Sharjah, Sharjah, United Arab Emirates; Cardiovascular Research Group, Sharjah Institute for Medical and Health Sciences, University of Sharjah, Sharjah 27272, United Arab Emirates; Space Medicine Research Group, Sharjah Institute for Medical and Health Sciences, University of Sharjah, Sharjah 27272, United Arab Emirates."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41548480", "title": "Association of sleep disorder with bulbar weakness and short-term outcomes in myasthenia gravis.", "abstract": "BACKGROUND: Sleep disorder is increasingly recognized in myasthenia gravis (MG). However, its specific link to bulbar muscle weakness and short-term outcomes is not well established. This study aimed to investigate the prevalence of subjective sleep disorder (based on Pittsburgh Sleep Quality Index [PSQI] score) in a cohort of acetylcholine receptor (AChR) antibody-positive MG patients, and to explore its associations with bulbar muscle weakness, disease severity, and its value for the short-term outcome of MG.\nMETHODS: We conducted a prospective cohort study of 163 AChR-MG patients. Subjective sleep quality was assessed using the PSQI score. Disease severity was evaluated with MG Specific Activities of Daily Living (MG-ADL) score, the Quantitative MG (QMG) score, and Myasthenia Gravis Foundation of America (MGFA) classification. Univariate and multivariable logistic regression were used to identify independent risk factors and establish prediction model for outcome. The predictive values were evaluated by receiver operating characteristic (ROC) curves. Moreover, calibration analysis and decision curve analysis (DCA) of the model were performed.\nRESULTS: The median PSQI score was 7.0 (5.0, 9.0) and the prevalence of sleep disorder (PSQI > 5) was 73.6 %. Patients with bulbar weakness had significantly higher PSQI scores than those without (P < 0.001). PSQI score showed significant positive correlations with MG-ADL (r = 0.319, P < 0.001),QMG (r = 0.356, P < 0.001) in MG patients. A higher baseline PSQI score was identified as an independent risk factor for poor outcome at 6 months (odds ratio: 1.642 [95 % CI: 1.340-2.014], P < 0.001), with a area under curve (AUC) of 0.797. A predictive model combining PSQI score, bulbar weakness, and female gender demonstrated good discrimination, with a AUC of 0.840, a sensitivity of 0.688, and a specificity of 0.870.\nCONCLUSION: Poor sleep quality is highly prevalent in AChR-MG and was more serious in patients with bulbar weakness. PSQI score was an independent risk factor for poor short-term outcome. Routine assessment of sleep may aid in risk stratification and personalized management.", "authors": ["Xue Nan", "Zhang Wan", "Guo Xinyan", "Ma Tianyu", "Lu Mengwen", "Ye Xinyi", "Jiang Min", "Sun Li", "Yang Mingjin", "Huang Xiaoyu", "Zhang Yong", "Zhang Zhouao", "Wang Yanbo", "Sheng Ying"], "journal": "Journal of clinical neuroscience : official journal of the Neurosurgical Society of Australasia", "entry_date": "2026/01/18 18:07", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41548480/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, Jiangsu 221000, PR China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41547654", "title": "Targeting pathogenic Th17.1 cells via JAK-STAT3 pathway: A novel approach with tofacitinib for refractory myasthenia gravis.", "abstract": "There remains a critical unmet need for effective, accessible, and well-tolerated therapies for myasthenia gravis (MG) who are refractory to current immunotherapies. The janus kinase and signal transducer and activator of transcription (JAK-STAT) signaling pathway plays a pivotal role in maintaining immune homeostasis by regulating cytokine-mediated responses. However, insights into the involvement of the JAK-STAT signaling in MG pathogenesis are still preliminary. In this study, we observed elevated levels of JAK2 in MG and further assessed the clinical efficacy of the pan-JAK inhibitor, tofacitinib, administered over 24 weeks in a cohort of 19 patients with refractory MG (NCT04431895). Tofacitinib significantly reduces the glucocorticoid dose and improves MG-relevant clinical scores and quality of life. The immunomodulatory effects of tofacitinib were mediated through downregulation of p-STAT3, IL-6, and IL-23, resulting in suppression of pathogenic Th17.1 cells in MG. Collectively, our results suggest that a novel approach to suppress pathogenic Th17.1 cells via the JAK-STAT3 signalling pathway with tofacitinib is effective and well-tolerated for treating patients with refractory MG.", "authors": ["Zhao Rui", "Yan Chong", "Zhong Huahua", "Huan Xiao", "Jin Lei", "He Dingxian", "Xi Jianying", "Li Yarong", "Xiao Baoguo", "Luo Feifei", "Zhao Chongbo", "Song Jie", "Luo Sushan"], "journal": "Neurotherapeutics : the journal of the American Society for Experimental NeuroTherapeutics", "entry_date": "2026/01/17 21:53", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41547654/", "pub_types": ["Journal Article"], "affiliations": ["Huashan Rare Disease Center and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Center for Neurological Disorders, Fudan University, Shanghai 200040, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.6, "journal_quartile": "2区"}, {"pmid": "41547250", "title": "Secukinumab versus conventional immunotherapy in myasthenia gravis: A single-Center 24-week retrospective comparative study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) management remains challenged by the delayed onset of conventional immunosuppressants. While B-cell and complement pathways are established therapeutic targets, the role of IL-17 A in human MG is underexplored, and its potential as a target represents a novel therapeutic avenue.\nOBJECTIVES: This study aimed to evaluate, for the first time in a clinical setting, the efficacy and safety of the anti-IL-17 A monoclonal antibody secukinumab compared to conventional immunotherapy in patients with acetylcholine receptor-positive generalized MG (AChR+ gMG).\nMETHODS: In this single-center, retrospective cohort study, 35 patients received subcutaneous secukinumab (150 mg/week for 4 weeks, then monthly) plus standard care, while 32 matched controls received conventional immunosuppressants alone. Outcomes included clinical scores (QMG, MG-ADL, MG-QOL15), AChR antibody (AChR-Ab) titers, and immunologic parameters (Th17/Tfh cells, cytokines) assessed at baseline, week 4, 12, and 24.\nRESULTS: Secukinumab demonstrated significantly superior and rapid efficacy. By week 24, improvement rates in QMG, MG-ADL, and MG-QOL15 scores were significantly greater with secukinumab (44.7%, 45.7%, 46.7%) than controls (27.5%, 25.8%, 32.0%; all p < 0.01). AChR-Ab levels decreased rapidly by 61.1% as early as week 4, achieving a 68.9% reduction at week 24, significantly surpassing the control group's response (21.6%). Immunologically, secukinumab induced rapid and profound suppression of IL-17 A (-84.1% at week 4), Th17 cells (-68.3%), and Tfh cells (-71.7%) over 24 weeks, effects strongly correlated with each other and with AChR-Ab decline. Reductions in key cytokines (IL-6, IL-21) were also more pronounced.\nCONCLUSION: This first clinical investigation of IL-17 A inhibition in AChR+ gMG demonstrates that secukinumab provides rapid, superior clinical and serological efficacy alongside broad immunomodulation, targeting the Th17/Tfh-B cell axis.Further prospective studies are needed to validate these results.", "authors": ["Zhang Shuangmei", "Wang Anrong", "Song Xiaodong", "Zhang Zhaoxu"], "journal": "International immunopharmacology", "entry_date": "2026/01/17 18:09", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41547250/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pain Rehabilitation, Zhejiang Cancer Hospital, Hangzhou 310022, China."], "china_related": true, "study_types": ["Non-randomized controlled cohort"], "evidence_level": "III", "journal_if": 4.7, "journal_quartile": "2区"}, {"pmid": "41546732", "title": "Repetitive nerve stimulation findings in iatrogenic botulism compared with myasthenia gravis.", "abstract": "OBJECTIVE: The widespread use of botulinum toxin has been accompanied by an increase in complications, including iatrogenic botulism (IB). This study investigated repetitive nerve stimulation (RNS) findings in IB and myasthenia gravis (MG) patients.\nMETHODS: Clinical and neurophysiological data were retrospectively reviewed in IB patients negative for both acetylcholine receptor and muscle-specific kinase antibodies, and in MG patients who were positive for either. RNS was performed on the ulnar nerve at 2, 3, 5, and 50 Hz, and on the facial and spinal accessory nerves at 2, 3, and 5 Hz.\nRESULTS: Fifteen IB and 23 MG patients were included. Compound muscle action potential (CMAP) amplitudes of the ulnar and facial nerves were lower in IB (p = 0.014, p = 0.006). A progressive decrement at low-frequency RNS occurred in 60% of IB and 17% of MG patients. At 5 Hz facial RNS, 1st-2nd (p = 0.044) and 1st-4th (p = 0.008) decrements were greater in MG, whereas the 4th-10th decrement was higher in IB (p = 0.031). Ulnar CMAP changes at 50 Hz were greater in IB (p < 0.001); nine patients showed increments > 40%, four > 60%, and one > 100%, while none of the MG patients exceeded 40%.\nCONCLUSION: Reduced CMAP amplitude, an incremental response at high frequency, and a progressive decrement at low frequency were more commonly encountered in IB. In MG, a U-shaped pattern at low frequency and a more pronounced decrement between the 1st and 2nd responses were noted.", "authors": ["Fidancı Halit", "Alaydın Halil Can", "Ertürk Ahmet Yusuf", "Eke Mehmet Necmi", "Önal Orçun"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/01/17 11:05", "pub_date": "2026-01-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41546732/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Division of Clinical Neurophysiology, University of Health Sciences Adana City Training and Research Hospital, Yuregir, Adana, 01370, Turkey. dr.halitfidanci@gmail.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41546683", "title": "Safety of immune checkpoint inhibitors: A systematic review of disproportionality analysis studies.", "abstract": "BACKGROUND: Immunotherapy has fundamentally changed the treatment landscape for both solid and hematologic malignancies over the past decade. However, an evolving body of literature has reported immune-related adverse events (irAEs) involving several organs in patients treated with immune checkpoint inhibitors (ICIs). Our study aimed to systematically review published disproportionality analyses on ICIs, to summarize the current state of methodology and potential strengths of the analysis, while highlighting safety signals generated for these pharmacological groups.\nMETHODS: A PubMed, Scopus, and Google Scholar search was conducted on November 7, 2024, and identified published disproportionality analyses of ICIs. Studies were included if they: 1) employed disproportionality analysis in pharmacovigilance databases; 2) investigations focused exclusively on ICIs; 3) analyses examining ICI-related adverse drug reactions (ADRs) (hypothesis-generating analyses and hypothesis-testing analyses); 4) mixed-methods studies incorporating disproportionality analysis with systematic reviews and meta-analysis. Data on results were categorized by ADR type and further analyzed based on exposure and comparator. We collected data on author name, database used, number of reports, age, gender, case/non-case status, exposure/comparison groups, disproportionality measures, signal definitions, confounder control, and sensitivity/subgroup analyses. We then retrospectively applied the READUS-PV (The REporting of A Disproportionality analysis for drUg Safety signal detection using individual case safety reports in PharmacoVigilance) checklist to all included studies to assess their reproducibility, transparency, and quality. Additionally, we evaluated study quality based on the demographic parameters reported.\nRESULTS: We have identified 2939 published disproportionality analysis studies. Our study included 89 eligible analyses published between 2019 and 2024. Of these, 35 specifically focused on a single irAE. More than 50% studies predominantly employed the Reporting Odds Ratio (ROR) and Proportional Reporting Ratio (PRR) as signal detection standards. The analysis of time to onset of ADR revealed a significant variation in the ICI-related ADRs, with some, such as myocarditis and arrhythmic events, manifesting rapidly within weeks, while others, including uveitis, hypophysitis, and certain endocrine disorders, exhibit a delayed onset. Hypophysitis/hypopituitarism is uniquely associated with combined anti-programmed death-ligand 1 (PD-L1) and anti-cytotoxic T-lymphocyte-associated protein 4 (CTLA-4) therapy, while endocrine and irAEs are common across all ICI treatments. Nivolumab and Pembrolizumab are more frequently associated with Guillain-Barré syndrome, myasthenia gravis, colitis, hepatitis, arthritis, immune-related skin disorders, and endocrinopathies (diabetes mellitus, adrenal insufficiency, and hypophysitis). The included disproportionality studies identified several irAEs that were not detected in pre-marketing clinical trials, including rare life-threatening events like myocarditis, fractures, delayed endocrine irAEs, and hypophysitis. A total of 34 (38.2%) of published disproportionality studies failed to report essential elements needed to understand and reproduce the analyses and results. Additionally, 39 (43.8%) of studies relied on a single disproportionality method for detecting signals. Only 15 studies (16.8%) met our predefined criteria for comprehensive reporting by including all seven critical data elements, while 40 studies (44.9%) demonstrated major reporting deficiencies with three or more missing elements. Concerning gaps persist, as evidenced by 34 recent studies (38.2%) still scoring ≤ 2 points. Furthermore, a quality assessment using the READUS-PV checklist revealed that critical reporting items were frequently missing from these studies, such as information in the title, case-by-case assessments, and comprehensive sensitivity analyses and data availability statements.\nCONCLUSION: The main organs affected due to ICIs are the skin, digestive, hepatic, lungs, rheumatologic, and endocrine. Disproportionality analysis in pharmacovigilance lacks standardised methods and interpretation, hindering reliable signal detection and requiring the development of clear guidelines, rigorous methodology, and collaborative efforts to improve patient safety. Additionally, the adoption of open-science practices, including protocol registration, should be implemented to enhance transparency and rigour.", "authors": ["Rathod Mahesh", "Kadari Maheshwari", "Kadavath Anjana Das", "Thomas Christy", "Raveendran Anjali", "Jagtap Mahesh", "Undela Krishna"], "journal": "European journal of clinical pharmacology", "entry_date": "2026/01/17 11:02", "pub_date": "2026-01-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41546683/", "pub_types": ["Systematic Review", "Journal Article"], "affiliations": ["Department of Pharmacy Practice, National Institute of Pharmaceutical Education and Research (NIPER) Guwahati, Kamrup, 781 101, Assam, India."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "41545286", "title": "Corticosteroids in myasthenia gravis: Rethinking oral corticosteroid therapy.", "abstract": "", "authors": ["Misra U K"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/16 21:52", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41545286/", "pub_types": ["Editorial"], "affiliations": ["T. S. Misra Medical College, Apollo Medics Super Speciality Hospital, and Vivekanand Polyclinic and Institute of Medical Sciences, Lucknow, India. Electronic address: drukmisra@rediffmail.com."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41542987", "title": "Co-Occurrence of Myasthenia Gravis and Facioscapulohumeral Muscular Dystrophy: A Case Series and Review of Literature.", "abstract": "BACKGROUND: Facioscapulohumeral dystrophy (FSHD) and Myasthenia Gravis (MG) are well-known rare neuromuscular diseases of respectively genetic and acquired origin. Among muscular dystrophies, the co-occurrence of MG with FSHD is the most common, representing a non-negligible \"double trouble\". Here, we aim to describe a series of patients with coexistence of these two rare disorders and combine this with a review of the literature to identify common elements which might provide useful clues when evaluating a FSHD patient with uncommon clinical presentation compatible with MG.\nMETHODS: We retrospectively collected demographic, clinical, and laboratory data of patients affected by both FSHD and MG followed at the Nice University Center, and we performed a review of the literature.\nRESULTS: We identified 10 patients in our cohort, 7 females. All patients have a D4Z4 4qA allele of 7-10 RU, a disease onset > 45 years and a mean FSHD score of 9.6 ± 2 at the last evaluation. The mean age of onset of MG was 68.5 ± 7.6 years; all patients presented with anti-AChR antibodies and without thymic pathology, and MG appeared in all but two patients after FSHD. We identified 9 case reports in the literature. All of them presented with AChR positivity. The majority of them presented with a late and very late onset MG and without thymic pathology.\nCONCLUSIONS: Our results underline the need for careful clinical evaluation to identify uncommon features, especially in elderly FSHD patients carrying a D4Z4 4qA allele of 7-10 RU to exclude the coexistence of other treatable neuromuscular conditions.", "authors": ["Tammam Giulia", "Villa Luisa", "Lemmers Richard J L F", "Pini Jonathan", "Slioui Abderhmane", "Bouchareychas Laura", "David Yann", "Ioncea Mihai-Bogdan", "Salviati Leonardo", "Cavalli Michele", "Ezaru Andra", "Puma Angela", "Verschuuren Jan J", "van der Maarel Silvère M", "Sacconi Sabrina"], "journal": "European journal of neurology", "entry_date": "2026/01/16 07:17", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41542987/", "pub_types": ["Journal Article", "Review", "Case Reports"], "affiliations": ["Peripheral Nervous System & Muscle Department, Reference Centre for Neuromuscular Disorders, Pasteur 2 Hospital, Nice University Hospital, Nice, France."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41541962", "title": "Positional Respiratory Distress in Myasthenic Crisis: A Case of Undiagnosed Thymoma.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder that can present with life-threatening complications, including myasthenic crisis (MC). We present the case of a 52-year-old Hispanic male with known MG who presented to a hospital serving an underserved community with respiratory distress after discontinuing azathioprine. He was initially presumed to be experiencing a typical MC but then exhibited positional respiratory compromise, an inability to tolerate the supine position and the inability to have a nasogastric tube placed, which raised concern for dynamic extrinsic compression of mediastinal structures. These atypical findings prompted imaging, which revealed a large anterior mediastinal mass consistent with thymoma. The patient's respiratory status worsened when supine, suggesting posture-dependent mass effect likely exacerbated by gravitational forces and impaired diaphragmatic mechanics. The tumor was found to be abutting both phrenic nerves, contributing to diaphragmatic dysfunction and worsening bulbar symptoms. He underwent successful surgical resection but required prolonged postoperative support, including tracheostomy and gastrostomy tube placement. This case highlights the need for heightened clinical suspicion of thymoma in MG patients presenting with crisis, particularly when positional symptoms suggest dynamic mass effect, as early recognition and intervention are essential for optimizing outcomes.", "authors": ["Diaz Oscar", "Krupnick Noah M", "Hidalgo Jimenez Yadaymis", "Basart Lazaro", "Graham Benjamin", "Jimenez Evelin P"], "journal": "Cureus", "entry_date": "2026/01/16 05:28", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41541962/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Palmetto General Hospital, Hialeah, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41541106", "title": "Stroke unit and Neurocritical Care Unit for acute neurological diseases in the USL Toscana Centro: a pilot model of Santo Stefano Hospital in Prato.", "abstract": "BACKGROUND: Acute neurological diseases are leading causes of disability and death. The need for specialist neurocritical care skills for managing neurological emergencies has increased. Promising opportunities exist to improve outcomes in acute phases of neurological diseases, such as, for example, the concept of a stroke unit for stroke patients. A similar concept was introduced for a neurocritical care unit, which is associated with improved clinical outcomes compared with more traditional management. However, neurocritical care is often not recognized as a separate specialty. Significant progress in neurology has enabled better approaches for the critically ill neurologic patient, in particular those with stroke and hemorrhage, but also with epileptic seizures and epileptic status, traumatic brain injury (TBI), subdural/epidural hematoma, acute inflammatory polyradiculoneuritis, encephalitis, myasthenia gravis, acute myelitis, etc.\nASSESSMENT OF POLICY/GUIDELINES OPTIONS AND IMPLICATIONS: Except for cerebrovascular diseases, for other acute neurological diseases, there is no standardized model care service recognized. A good patient outcome can be obtained by the choice of neurology setting for acute patients including nursing and medical staff with specific training in neurocritical care. As we believe neurocritical care practices should be implemented, we suggest a pilot model on the basis of our experience. In this report, we show a model of the 2A setting of the Santo Stefano Hospital (Prato, USL Toscana Centro), where, as well as stroke units for cerebrovascular events, we have neurocritical care unit and acute-neurology experts for all acute neurological diseases.\nACTIONABLE RECOMMENDATIONS OUR PILOT EXPERIENCE: The 2A setting of Stroke Unit/Neurocritical Care of the Santo Stefano Hospital includes 15 beds; 8 ± 2 beds are monitored by portable multi-parameter monitoring devices. Following acute treatment, diagnostic/etiologic work-up and automated monitoring of vital functions are performed in addition to adapted secondary prevention, early rehabilitation, and prevention of complications in all acute patients. We retrospectively assessed the diagnoses in the hospital discharge forms (HDF) of Stroke Unit/Neurocritical Care (2A) of 249 patients consecutively analyzed between 1 January 2022 and 30 June 2022. Out of the 249 patients affected by acute neurological diseases, 155 had cerebrovascular diseases (62.2%). In particular, 100 (64.5%) were diagnosed with ischemic stroke and 44 (28.4%) with hemorrhagic stroke. Thirty-two patients (12.8%) were hospitalized following a TBI. Sixteen patients (6.4%) had a new diagnosis of epilepsy and three (1.2%) of epileptic status. In our setting, the 3-month modified Rankin Scale (mRS) in the 36 stroke patients treated with recombinant-tissue plasminogen activator (r-TPA) was 0-2 (low disability) in 60% of cases. Additionally, 31% of 44 intracerebral haemorrhage (ICH) patients reported a moderate-severe degree of disability. Regarding TBI patients, the mRS ranged from 1 to 5, with significate difference between patients in Stroke Unit/Neurocritical Care (2A) in comparison with those in other departments (2-3 vs. 3-4, respectively). Globally, the setting discharge of the acute neurological patients were: rehabilitation (26%), intermediate care hospitals (44%), long-term care (5%), and home (25%). The 1-month mortality rate was 1.8%.\nDISCUSSION: We provide a brief description of the cases treated over a 6-month period to draw attention to the possibility of the existence of a ward dedicated exclusively and specifically to all acute neurological diseases. The sample of patients is very varied and interesting. More than 60% of patients had cerebrovascular diseases. The paucity of outcome data makes this report limited, but the diagnostic-therapeutic strategies, the presence of staff trained in specific neurocritical care, and the use of inpatient hospital-based registries are, in our opinion, strengths. Our pilot model of the setting of Stroke Unit/Neurocritical Care (2A) in the Santo Stefano Hospital (Prato, USL Toscana Centro) should be further implemented, also to verify systematically the associations with measurable outcome improvements in patients affected by strokes and other neurological acute diseases.", "authors": ["Valenti Raffaella", "Caruso Alba", "Scotto Di Luzio Anita E", "Accavone Donatella", "Cagliarelli Maria G", "Chiti Guido", "Grassi Enrico", "Briccoli Bati Maria", "Palumbo Pasquale"], "journal": "Frontiers in stroke", "entry_date": "2026/01/16 05:07", "pub_date": "2023", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41541106/", "pub_types": ["Journal Article"], "affiliations": ["S.O.C. Neurologia, Neurofisiopatologia - Stroke and Neurocritical Care Units, Ospedale Santo Stefano, Azienda USL Toscana Centro, Prato, Italy."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.2}, {"pmid": "41540172", "title": "Evaluating AI Research Quality in Myasthenia Gravis: A Longitudinal Study Using the CLARITY Framework (2020-2024).", "abstract": "", "authors": ["Marconi Luca", "Pirovano Efrem", "Cabitza Federico"], "journal": "Journal of medical systems", "entry_date": "2026/01/16 00:00", "pub_date": "2026-01-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41540172/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Informatics, Systems and Communication, University of Milano-Bicocca, Viale Sarca 336, Milan, 20126, Italy. luca.marconi@unimib.it."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.7, "journal_quartile": "3区"}, {"pmid": "41536333", "title": "Clinical Features and Outcomes of Ocular Myasthenia Gravis in a Tertiary Philippine Hospital.", "abstract": "OBJECTIVES: To describe the clinical profile and outcomes of a series of adult patients diagnosed with ocular myasthenia gravis and to evaluate the potential factors affecting the risk of generalization.\nMETHODS: This retrospective cohort study involved a medical chart review of adult patients seen from 2012 to 2019 at the neuro-ophthalmology clinic of a tertiary Philippine hospital with a clinical diagnosis of ocular myasthenia gravis supported by serologic, electrophysiologic, or pharmacologic test results. Outcomes of interest were complete stable remission, pharmacologic remission, minimal manifestations, and generalization. Kaplan-Meier method and log-rank test were used to analyze the probability of generalization.\nRESULTS: The study sample consisted of 16 patients. The female to male ratio was 3:1. Mean age at symptom onset was 39 years. All patients received pharmacologic treatment, while two patients underwent thymectomy. No patient had remission as of last follow-up. Three patients had conversion of ocular myasthenia gravis to generalized myasthenia gravis. Mean time from symptom onset to generalization was 10.7 months. The generalization curves of patients who were symptomatic for less than two years and those who were symptomatic for at least two years prior to consult were significantly different (p = 0.049).\nCONCLUSION: In this single-center study, there was female predominance among adult patients diagnosed with ocular myasthenia gravis. The incidence of generalization was 4 per 100 person-years while the 2-year probability of generalization was 30%. Further study is needed in order to determine the factors affecting the risk of generalization.", "authors": ["Labiano Aubhugn T", "Cruz Franz Marie O", "Mesina Bryan Vincent Q"], "journal": "Acta medica Philippina", "entry_date": "2026/01/15 04:23", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41536333/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology and Visual Sciences, Philippine General Hospital, University of the Philippines Manila, Manila, Philippines."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41534441", "title": "Impact of corticosteroid use on comorbidities in patients with myasthenia gravis in the US National Veterans Affairs Health Network.", "abstract": "BACKGROUND: Corticosteroid use may increase the risk of common comorbidities in patients with myasthenia gravis (MG); however, limited longitudinal data are available to evaluate this risk over time.\nMETHODS: This retrospective cohort study used electronic medical record data from the National Veterans Affairs Health Care Network database (January 1999-March 2024) to evaluate the impact of corticosteroid use on the development of selected comorbidities in patients with and without generalized MG. Index date was the first MG diagnosis for the MG cohort and a randomly chosen date for a propensity score-matched non-MG cohort; patients were followed until disenrollment, end-of-study, or death.\nRESULTS: In total, 10,632 patients with MG and 10,632 matched controls were included; mean follow-up was 7.8 years. Corticosteroids were received by 51.6% of MG and 21.2% of non-MG patients. Both MG and non-MG patients who received corticosteroids had a higher incidence of new-onset comorbidities during follow-up than MG and non-MG patients without corticosteroid use (p < 0.0001). Among MG patients, multivariate analyses showed statistically significant increases in the annualized risk of new-onset diabetes (hazard ratios 1.32-1.76), infections (1.19-1.25), osteoporosis (1.33-1.69), and cardiovascular disease (1.19-1.31) across medium- and high-dose intensities (p < 0.05). Statistically significant increases in annualized risk were observed for glaucoma (hazard ratio 1.81 at high dose; p < 0.05) and depression (1.22 at medium dose; p < 0.05).\nCONCLUSIONS: Increased risks for the development of key comorbidities among patients with MG were associated with corticosteroid use, particularly at higher-dose intensities. Our findings support strategies to minimize corticosteroid usage in MG.", "authors": ["Qi Cynthia Z", "Lin Yilu", "Li Yuebing", "Vu Tuan", "Gelinas Deborah", "Lizarraga Alexis A", "Blein Cécile", "De Ruyck Femke", "Shi Lizheng"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/14 18:08", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41534441/", "pub_types": ["Journal Article"], "affiliations": ["argenx US Inc., Boston, MA, USA. Electronic address: cqi@argenx.com."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41527741", "title": "Health Literacy in Patients With Myasthenia Gravis: A Cross-Sectional Study.", "abstract": "INTRODUCTION/AIMS: Health literacy (HL) can influence self-management and outcomes in chronic diseases, but it remains poorly characterized in the context of rare diseases, including myasthenia gravis (MG). This study aimed to explore general HL levels and specific HL domains and competencies in adults with MG and their associations with sociodemographic, clinical, and organizational factors.\nMETHODS: A multicentre, observational, cross-sectional study was conducted between April and October 2024 in 22 neurology centres located in 11 regions of northern, central, and southern Italy. Eligible participants were adult patients (≥ 18 years) with a confirmed diagnosis of MG. Comparisons across patient groups were explored with non-parametric tests; multivariable linear models were used to estimate adjusted associations.\nRESULTS: A total of 113 participants were enrolled. The median HLS19-Q12 total score was 58.3 (IQR: 41.7-75.0), indicating problematic HL. In adjusted models, higher education was significantly associated with lower appraisal competence (β = -11.1, 95% CI: -20.2, -2.0). Not meeting the Patient Acceptable Symptom State (PASS) was significantly associated with lower scores across multiple domains and competencies, while follow-up in centres with nurses specialized in MG was significantly associated with higher scores in access (β = 8.2, 95% CI: 0.9, 15.6), understanding (β = 10.8, 95% CI: 2.1, 19.4), application (β = 10.6, 95% CI: 2.6, 18.7), health care (β = 11.5, 95% CI: 2.9, 20.0), and health promotion (β = 11.9, 95% CI: 3.5, 20.2).\nDISCUSSION: Symptom-burdened patients and centres without specialized nursing support appear to be priority targets for HL-oriented interventions and organizational redesign.", "authors": ["Pastore Francesco", "Simonetti Valentina", "Milella Giammarco", "Forastefano Barbara", "Domenicone Emanuela", "Ferorelli Davide", "DeTommaso Marina", "Cicolini Giancarlo", "Comparcini Dania"], "journal": "Muscle & nerve", "entry_date": "2026/01/13 04:23", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41527741/", "pub_types": ["Journal Article"], "affiliations": ["Department of Precision and Regenerative Medicine and Jonian Area - (DiMePRe-J), University of Bari Aldo Moro, Bari, Italy."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41526151", "title": "Role of B cells and pathogenic autoantibodies in autoimmune CNS and PNS neurologic diseases.", "abstract": "B cells have an ever-increasing role in the etiopathology of a number of autoimmune neurologic disorders, acting, in addition to their autoantibody-secreting role, as antigen-presenting cells but also as sensors, coordinators, and regulators of the immune response. B cells can regulate the immune response, including T-cell activation through antigen presentation, production of proinflammatory cytokines (either as a bystander activation or suppression), and contribution to ectopic lymphoid aggregates. Such important functions make therapeutic depletion of B cells an attractive treatment strategy. The last decade, anti-B-cell therapies targeting B-cell surface molecules, have evolved into a rational approach for successfully treating autoimmune neurologic disorders, even when T cells seem to be the main effector cells, providing an invaluable therapeutic criterion for appreciating the key role of B cells in neurologic autoimmunities. The chapter is focused on the basic aspects of B-cell biology, addresses the different roles of B cells and autoantibodies in the pathogenesis of autoimmune and inflammatory neurologic disorders and highlights how the currently available or in the developmental stage anti-B-cell therapeutics exert their action. It specifically examines the autoantibodies of different IgG-isotypes and IgG-subclasses stressing the uniqueness of IgG4-neuroautoimmunities, and summarizes the current status of the rapidly evolving B-cell therapeutics, including CD19-CAR-T cell therapies, in multiple sclerosis, neuromyelitis-spectrum disorders, autoimmune encephalitis, stiff-person syndrome spectrum disorders, chronic autoimmune neuropathies, myasthenia gravis, and inflammatory myopathies.", "authors": ["Stathopoulos Panos", "Dalakas Marinos C"], "journal": "Handbook of clinical neurology", "entry_date": "2026/01/12 20:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41526151/", "pub_types": ["Journal Article"], "affiliations": ["First Department of Neurology, National and Kapodistrian University of Athens, Athens, Greece."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41526150", "title": "The future unfolded: CAR T cells and the transformation of treatment algorithms in autoimmune neurology.", "abstract": "Chimeric antigen receptor (CAR) T-cell therapy has revolutionized the treatment of hematologic malignancies, and its application in neuroimmunologic autoimmune diseases is now emerging as a promising therapeutic avenue. Neuroimmunologic diseases such as multiple sclerosis, myasthenia gravis, neuromyelitis optica spectrum disorder, and stiff-person syndrome have shown varying degrees of response to traditional immunomodulatory therapies, but a significant proportion of patients remain refractory to treatment. In recent studies, anti-CD19 CAR T cells have shown encouraging results in targeting B cells, a key driver of autoimmune pathogenesis. CAR T-cells can penetrate the central nervous system and overcome the limitations of conventional B-cell depleting therapies such as rituximab, particularly in accessing ectopic lymphoid follicles that maintain compartmentalized inflammation. In early clinical cases, CAR T-cell treatment has resulted in marked clinical improvements, including significant reductions in symptoms and durable disease remission, with manageable side-effects. In addition, advances in allogeneic CAR T cell constructs and chimeric autoantibody receptor T cells offer additional avenues for precision-targeted therapies. These developments underscore the potential of CAR T cells to reshape the treatment landscape for refractory neuroimmunologic autoimmune diseases and warrant further controlled trials and regulatory exploration.", "authors": ["Mougiakakos Dimitrios", "Dalakas Marinos C"], "journal": "Handbook of clinical neurology", "entry_date": "2026/01/12 20:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41526150/", "pub_types": ["Journal Article"], "affiliations": ["Department of Hematology, Oncology, and Cell Therapy, Otto-von-Guericke University Magdeburg, Magdeburg, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41526148", "title": "Immunotherapies in autoimmune neuromuscular junction disorders: Acute and chronic management.", "abstract": "Myasthenia gravis (MG) is the most common disease of the neuromuscular junction. Conventional immunotherapy based on corticosteroids and immunosuppressants has been in use for several decades and has greatly contributed to the improvement of the disease prognosis. In recent years, several new agents, mostly monoclonal antibodies, have proved effective in randomized controlled trials and are in clinical use. Other biologics are currently under evaluation. Novel therapies, that offer the advantage of more selective effects on the immune system, are not devoid of potentially serious adverse effects. MG subgrouping based on associated autoantibodies is a prerequisite for personalized treatment. Patient-specific selection is especially relevant and includes MG-specific IgG subclasses and B-cell subsets responsible for antibody production. While ever-growing knowledge of the disease pathogenicity and advances in technology have made such therapeutic advances possible, lack of biomarkers of disease activity complicates treatment decisions. On the other hand, treatment of Lambert-Eaton myasthenic syndrome (LEMS) has scarcely changed in recent decades and biologics have been tried in very few patients to date. Its rarity and association with cancer have likely discouraged the exploration of new immunotherapies for LEMS despite disease-related disability.", "authors": ["Evoli Amelia", "Gilhus Nils Erik", "Sanders Donald B"], "journal": "Handbook of clinical neurology", "entry_date": "2026/01/12 20:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41526148/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurosciences, Università Cattolica, Roma, Italy; Neurology Unit, Policlinico Universitario \"A. Gemelli\" IRCCS, Roma, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41526134", "title": "Intravenous immunoglobulin use in neurology.", "abstract": "In the past 3 decades, intravenous immunoglobulin (IVIg) - pooled IgG (IgG) obtained from the plasma of several thousands of healthy donors - has had a major impact in the successful treatment of previously poorly controlled autoimmune neurologic disorders. Based on randomized controlled trials, IVIg is approved for the treatment of Guillain-Barré syndrome, chronic inflammatory demyelinating polyradiculoneuropathy (CIDP), multifocal motor neuropathy (MMN), and dermatomyositis. It has been effective in myasthenia gravis exacerbations and stiff-person syndrome, and exhibits convincing efficacy in autoimmune encephalitides. As maintenance therapy, IVIg and subcutaneous IgG (SCIg) are effective in controlled studies only in CIDP and MMN. The demand for IVIg therapy is ever-growing, resulting in supply shortages, leading to strategies to replace IVIg with recombinant products based on proposed mechanisms that confer its anti-inflammatory activity. This chapter illustrates clinical applications of IVIg in neurologic diseases, discusses the merit of SCIg, and addresses practically important issues, such as the need for dose adjustment, cycling intervals, dependency testing, or treatment discontinuation.", "authors": ["Keller Christian W", "Dalakas Marinos C", "Lünemann Jan D"], "journal": "Handbook of clinical neurology", "entry_date": "2026/01/12 20:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41526134/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Neurophysiology, Medical Center, University of Freiburg, Freiburg, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41526133", "title": "FcRn inhibitors: A new era in neurotherapeutics.", "abstract": "The neonatal Fc receptor (FcRn) is a heterodimeric protein that binds albumin and immunoglobulin G (IgG) to mediate pH-dependent recycling, prevent degradation, and maintain their serum concentrations. The ability to bind IgG means FcRn plays both beneficial and potentially detrimental roles in host immunity. Beneficially, FcRn maintains first-line defenses against invading pathogens by preventing degradation of IgG in mucosal secretions, and is linked with increased tumor protection via IgG immune complex-mediated activation of CD8+ cytotoxic T cells and induction of cytotoxic cytokine secretion. FcRn also maintains serum concentrations of circulating pathogenic IgG autoantibodies associated with neurologic and other autoimmune disorders, including myasthenia gravis, chronic inflammatory demyelinating polyneuropathy, and idiopathic inflammatory myopathies. Traditional immune-based therapies for autoimmune disorders, such as steroidal and nonsteroidal immunosuppressants, intravenous and subcutaneous immunoglobulin therapies, and B cell- and complement-targeting therapies, can be associated with significant side-effects and lack of efficacy in some patients. There is a clear need for alternative strategies to treat antibody-mediated autoimmune diseases. The critical role of FcRn in the pathogenesis of autoimmune disorders makes it an ideal target for novel treatments. Here, we discuss the FcRn receptor, current treatments, and recent clinical developments of FcRn-targeting treatments for autoimmune neurologic disorders.", "authors": ["Howard James F", "Guptill Jeffrey T"], "journal": "Handbook of clinical neurology", "entry_date": "2026/01/12 20:55", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41526133/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University of North Carolina at Chapel Hill, Chapel Hill, NC, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41524776", "title": "Pharmacological and speech-language pathology management of dysphagia in patients with myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is a rare, complex autoimmune neuromuscular disorder characterized by fluctuating muscle weakness. Bulbar involvement, particularly dysphagia (difficulty swallowing), is a common and debilitating symptom that significantly increases the risk of aspiration pneumonia, malnutrition, and dehydration, profoundly impacting quality of life. The management of myasthenic dysphagia requires a sophisticated, interdisciplinary approach. This review aims to provide a comprehensive overview of the current and emerging pharmacological treatments for myasthenia gravis and to detail the specific assessment and management strategies employed by speech-language pathologists (SLPs) for associated dysphagia. A narrative review of the literature was conducted, focusing on the pathophysiology, classification, and treatment of MG, with a specific emphasis on bulbar dysfunction. The review synthesizes evidence for traditional immunosuppressants, novel targeted biologics (complement inhibitors and FcRn antagonists), and evidence-based speech-language pathology interventions. Pharmacological management has evolved from symptomatic treatment (anticholinesterases) and broad immunosuppression (corticosteroids, azathioprine) to highly specific, targeted therapies. Complement inhibitors (e.g., eculizumab, ravulizumab) and neonatal Fc receptor (FcRn) antagonists (e.g., efgartigimod, rozanolixizumab) have demonstrated significant and rapid efficacy in reducing autoantibody load and improving clinical scores (MG-ADL, QMG) in generalized MG, including for patients with refractory disease. Concurrently, SLP management is critical for functional safety and efficacy. This includes precise assessment using clinical (e.g., EAT-10, bedside swallowing evaluations) and instrumental methods (VFSS, FEES) to characterize the pathophysiology of weakness and fatigability. Management is individualized, focusing on compensatory strategies (e.g., postural adjustments, diet modification standardized by the IDDSI framework) and behavioral techniques, all timed to coincide with peak medication efficacy. The treatment landscape for MG has been revolutionized by targeted biologics, offering profound improvements for many patients. Effective management of dysphagia, however, relies on the synergy between optimal medical therapy and specialized SLP intervention. This integrated approach is essential to ensure swallowing safety, nutritional adequacy, and improved quality of life for individuals living with myasthenia gravis.", "authors": ["Ferrara F", "De Berardinis F"], "journal": "Naunyn-Schmiedeberg's archives of pharmacology", "entry_date": "2026/01/12 11:04", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41524776/", "pub_types": ["Journal Article"], "affiliations": ["Pharmaceutical Department, ASL Napoli 3 Sud, Naples, Italy. f.ferrara@aslnapoli3sud.it."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41524248", "title": "Development and External Validation of a Multivariable Model to Predict Early Minimal Symptom Expression Response in Adult Generalized Myasthenia Gravis Patients Treated With Efgartigimod.", "abstract": "BACKGROUND: Efgartigimod, a neonatal Fc receptor (FcRn) blocker, is approved for generalized Myasthenia Gravis (gMG), but predictors of early response are unclear. Using minimal symptom expression (MSE) as the therapeutic target, we developed and externally validated a clinical model to predict early MSE response after starting efgartigimod. This efgartigimod-tailored model estimates the baseline probability of achieving early MSE and may assist in individualized treatment selection at therapy initiation.\nMETHODS: We retrospectively analyzed 118 adults with gMG treated at five tertiary centers in China (efgartigimod 10 mg/kg IV weekly ×4). MSE was defined as Myasthenia Gravis-Activities of Daily Living (MG-ADL) ≤ 1 sustained ≥ 4 weeks; early MSE response was achievement within 4 weeks of initiation. Patients were split into a derivation cohort (n = 64; three centers) and an external validation cohort (n = 54; two centers). Candidate predictors included demographics, baseline severity, and laboratory indices. Variables associated with early MSE in univariable analyses entered multivariable logistic regression to construct a nomogram. Discrimination (AUC-ROC), calibration (curves and Spiegelhalter Z-test), and clinical utility (decision curve analysis, DCA) were assessed, with bootstrap internal validation.\nRESULTS: Early MSE response occurred in 26/64 derivation and 22/54 validation patients. Lower bulbar MG-ADL (OR 0.633, p = 0.040), higher FVC% (OR 1.042, p = 0.048), and lower IgG (OR 0.795, p = 0.036) independently predicted early MSE response. The nomogram showed strong discrimination-derivation AUC 0.869 (95% CI 0.797-0.941), bootstrap AUC 0.880 (0.806-0.954), and external AUC 0.839 (0.760-0.919)-and good calibration (Spiegelhalter Z: 1.03, p = 0.303; 0.94, p = 0.347; 1.17, p = 0.242). DCA indicated net benefit across thresholds 0.05-0.82, with validation curves mirroring derivation.\nCONCLUSIONS: A three-factor nomogram (bulbar MG-ADL, FVC%, and serum IgG) provides an efgartigimod-specific baseline estimate of early sustained-MSE response probability, which may help neurologists select appropriate candidates, counsel expected benefit, and tailor follow-up intensity or alternative escalation strategies.\nTRAIL REGISTRATION: Chinese Clinical Trial Registry (ChiCTR2500101971).", "authors": ["Yang Yufang", "Liang Tao", "Zhao Mingming", "Yang Hongxia", "Zhao Zhilan", "Yu Lu", "Yan Linlin", "Li Siyuan", "Zhang Peng", "Qi Guoyan", "Yin Jian", "Xu Zucai", "Luo Zhong"], "journal": "CNS neuroscience & therapeutics", "entry_date": "2026/01/12 07:53", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41524248/", "pub_types": ["Journal Article", "Multicenter Study", "Validation Study"], "affiliations": ["Department of Neurology, Affiliated Hospital of Zunyi Medical University, Zunyi, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.0, "journal_quartile": "2区"}, {"pmid": "41523534", "title": "Iatrogenic Botulism Following Cosmetic Botulinum Toxin Injection Presenting With Respiratory Distress: A Case Report.", "abstract": "Botulinum toxin (BoNT) is extensively used across a wide range of therapeutic and cosmetic applications due to its efficacy in inhibiting neuromuscular transmission and its well-established safety profile. While adverse effects are typically localized and transient, systemic complications - particularly iatrogenic botulism - are rare but potentially life-threatening events. Iatrogenic botulism results from unintended systemic spread of the neurotoxin, which can occur even at doses commonly used for cosmetic purposes. We report a rare and severe case of iatrogenic botulism in a previously healthy 47-year-old male who developed progressive neurological symptoms following cosmetic BoNT injections to the glabellar region. Within days of the procedure, the patient experienced worsening bilateral ptosis, ophthalmoplegia, dysarthria, and dysphagia, which progressed to respiratory muscle involvement requiring mechanical ventilation in an intensive care setting. Neurophysiological studies demonstrated findings consistent with a presynaptic neuromuscular transmission defect. The case presented several diagnostic challenges, as the early clinical features mimicked other neuromuscular disorders such as myasthenia gravis or brainstem stroke. Despite this, prompt recognition based on clinical suspicion led to the timely administration of heptavalent botulinum antitoxin, which was followed by gradual neurological improvement. This case underscores the importance of early identification and management of systemic BoNT toxicity, even in the context of routine cosmetic use. It also highlights the critical need for clinician awareness, early referral to specialized care, and a high index of suspicion in patients presenting with acute cranial neuropathies following BoNT administration. This report aims to highlight the potential for severe systemic complications associated with BoNT use and to emphasize the importance of early antitoxin administration.", "authors": ["Zahur Haider", "Malik Jawad", "Arshad Laraib"], "journal": "Cureus", "entry_date": "2026/01/12 05:46", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41523534/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Intensive Care, University Hospitals of Leicester NHS Trust, Leicester, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41523127", "title": "Innovation in neuro-ophthalmology: The validation of smartphone-based self-screening for early detection of disorders.", "abstract": "PURPOSE: This diagnosis study evaluated the diagnostic validity of Neuro-ophthalmology Disorder Early Screening (NODES), a telemedicine-based smartphone application that integrates structured anamnesis and simple neuro-ophthalmology examination for early detection of neuro-ophthalmological disorders.\nMATERIALS AND METHODS: This study was conducted at Sardjito Eye Center Neuro-ophthalmology subdivision, assessing the diagnostic validity of the NODES mobile application of 16 neuro-ophthalmology diagnoses compared to confirmative diagnoses of neuro-ophthalmologists. A total of 126 participants meeting inclusion criteria underwent two treatments: simple examination using the NODES application, compared to confirmative examination by neuro-ophthalmologists. Standard protocols were integrated into both treatments to evaluate the diagnosis accuracy of the examination.\nRESULTS: NODES showcase promising results as a new diagnostic tool for these four disorders; myasthenia gravis (MG) with the area under the curve (AUC) =0.951, multicranial nerve palsy orbital apex (MNP OA) with AUC = 0.900, monocranial nerve palsy N.III (MNP N.III) with AUC = 0.824, and monocranial sixth nerve palsy (MNP N.VI) with AUC = 0.764.\nCONCLUSION: The NODES application can be used as a new diagnostic screening tool for several euro-ophthalmology diagnoses including MG, multicranial nerve palsy orbital apex, monocranial nerve palsy N.III, and monocranial sixth nerve palsy. The high specificity of NODES in other neuro-ophthalmology diagnoses can be quite useful to identify individuals without the condition, reducing the occurrence of false positives and crucial in preventing unnecessary stress, further testing, and potential misdiagnoses for those who do not actually have the condition.", "authors": ["Murtadha Milzan", "Widyandana Doni", "Hartono", "Mahayana Indra Tri"], "journal": "Taiwan journal of ophthalmology", "entry_date": "2026/01/12 05:43", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41523127/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, Faculty of Medicine, Public Health, and Nursing, Universitas Gadjah Mada - Dr. Sardjito General Hospital, Yogyakarta, Indonesia."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.2, "journal_quartile": "4区"}, {"pmid": "41522102", "title": "Minimally invasive vs. trans-sternal thymectomy for non-thymomatous myasthenia gravis: a multi-institutional longitudinal study examining neurologic outcomes.", "abstract": "BACKGROUND: Trans-sternal thymectomy has been shown to be an effective treatment for select patients with non-thymomatous myasthenia gravis (MG). The purpose of this study was to evaluate whether similar neuromuscular benefits are achieved when utilizing minimally invasive surgical approaches to thymectomy, as compared to a trans-sternal approach, in patients with non-thymomatous MG.\nMETHODS: Pooled data for all patients undergoing thymectomy from 2012 to 2020 for non-thymomatous MG from four institutions were retrospectively reviewed. Patients were stratified by surgical approach, minimally invasive [robotic or video-assisted thoracoscopic (VATS) vs. trans-sternal]. Clinical neurologic follow-up was ascertained from the medical record by a neurologist at 3-month intervals, for 2 years postoperatively.\nRESULTS: A total of 54 patients were included with 54% (n=29) undergoing minimally invasive thymectomy (MIT) and 46% (n=25) undergoing a trans-sternal approach. There were no differences in baseline disease severity measured by proportion requiring intravenous immunoglobulin (IVIG), quantitative myasthenia scores, or daily prednisone dose. Similarly, there were no significant differences in major comorbidities. There was one conversion to a sternotomy for innominate vein bleeding. Perioperative complications were uncommon and largely similar between groups. Patients undergoing minimally invasive surgery had decreased length of hospital stay (2.5 vs. 5 days, P<0.01). There were no differences observed in prednisone dose or quantitative myasthenia scores during the 2-year follow-up period.\nCONCLUSIONS: Our study confirms the results of the landmark MGTX (Randomized Trial of Thymectomy in Myasthenia Gravis) trial in a real-world multicenter experience. Similar outcomes were achieved regardless of surgical approach. These data support thymectomy for MG either by a minimally invasive or trans-sternal approach. This is the first study to compare disease-specific, rather than perioperative, outcomes of thymectomy via sternotomy vs. minimally invasive approach.", "authors": ["Beller Jared P", "Martin Linda W", "Hall Ryan", "Tatum Peter", "Phillips Joseph D", "Fay Kayla A", "Williams Rachel", "Boys Joshua", "Gundogdu Betul", "Elliot Matthew", "Mehaffey J Hunter", "Walters Dustin M"], "journal": "Journal of thoracic disease", "entry_date": "2026/01/12 05:34", "pub_date": "2025-12-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41522102/", "pub_types": ["Journal Article"], "affiliations": ["Division of Cardiothoracic Surgery, Department of Surgery, University of Virginia Health System, Charlottesville, VA, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41520205", "title": "Health economic evaluations of myasthenia gravis: a systematic review.", "abstract": "AIM: To systematically review the latest pharmacoeconomic evidence regarding the costs associated with myasthenia gravis (MG) care and treatment.\nMETHODS: We searched the National Health Service Economic Evaluation Database and PubMed for articles in English from any country reporting health economic analyses of pharmacological treatments, hospitalization, or surgical procedures related to MG.\nRESULTS: The study included 31 articles showing a considerable variability in the costs and cost-effectiveness of MG treatments across regions, therapies, and health care settings. Traditional therapies such as plasma exchange (PLEX) and intravenous immunoglobulin (IVIg) differ notably in cost, with PLEX generally being less expensive. Newer clinically effective treatments such as efgartigimod and eculizumab raise concerns about their economic sustainability, whereas rituximab might be a more affordable alternative in certain contexts.\nCONCLUSION: Future research should compare cost-effectiveness across health care systems, incorporating local pricing and reimbursement, and collecting real-world data.", "authors": ["Çipi Frenki", "Koloneci Chantal", "Marku Artejana", "Domi Kamila", "Tahiraj Xhoana", "Malaj Visar", "Hoxha Malvina"], "journal": "Croatian medical journal", "entry_date": "2026/01/11 03:43", "pub_date": "2026-01-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41520205/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": [], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "41519534", "title": "The Immune Cost of the Thymus: Navigating Autoimmunity and Tumor Management in Thymic Epithelial Tumors.", "abstract": "", "authors": ["Bertolaccini Luca", "Bardoni Claudia", "Casiraghi Monica", "Guarize Juliana", "Spaggiari Lorenzo"], "journal": "Journal of thoracic oncology : official publication of the International Association for the Study of Lung Cancer", "entry_date": "2026/01/10 20:54", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41519534/", "pub_types": ["Editorial"], "affiliations": ["Department of Thoracic Surgery, IEO, European Institute of Oncology IRCCS, Milan, Italy; Department of Oncology and Hemato-Oncology, University of Milan, Milan, Italy. Electronic address: luca.bertolaccini@gmail.com."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 16.4, "journal_quartile": "1区"}, {"pmid": "41517964", "title": "Post Hoc, Sex-Specific Subgroup Analysis of Efgartigimod in Patients With Generalized Myasthenia Gravis From the ADAPT Trial: A Sex and Gender Equity in Research (SAGER) Guidelines Approach.", "abstract": "INTRODUCTION/AIMS: Sex-specific differences in myasthenia gravis (MG) are widely acknowledged, yet data on sex-based outcomes of MG treatment are scarce. In accordance with Sex and Gender Equity in Research guidelines, this post hoc analysis assessed potential sex-specific differences in treatment outcomes in acetylcholine receptor antibody-positive (AChR-Ab+) generalized (g)MG participants in the Phase 3 ADAPT trial (NCT03669588).\nMETHODS: Participants received four once-weekly efgartigimod infusions (10 mg/kg) or placebo per cycle. Endpoints (primary: proportion of Myasthenia Gravis Activities of Daily Living (MG-ADL) responders (Cycle 1); secondary: proportion of Quantitative Myasthenia Gravis (QMG) and early (Cycle 1) MG-ADL responders, and time with clinically meaningful improvements in MG-ADL score; additional: quality of life outcomes, pharmacodynamics) were assessed according to sex.\nRESULTS: Females were younger (mean age: 42.9 vs. 54.8 years), more likely to have undergone thymectomy (65.1% [56/86] vs. 44.2% [19/43]), and had higher baseline QMG scores (16.3 vs. 14.3) compared with males. Efgartigimod demonstrated homogeneous effects between sexes, with no significant difference in proportions of MG-ADL (p = 0.7014), early (Cycle 1) MG-ADL (p = 1.00), or QMG responders (p = 0.1595). Improvements in quality-of-life assessments, rates of minimal symptom expression, and mean total immunoglobulin G reductions (Cycle 1) were greater with efgartigimod verso placebo in females and males. Efgartigimod was well tolerated, with similar safety profiles across sexes.\nDISCUSSION: In ADAPT, efgartigimod-treated female and male AChR-Ab+ gMG patients had similar efficacy and safety outcomes. These data provide valuable insight for clinicians, given the established sex differences in MG disease course and treatment responses.\nTRIAL REGISTRATION: The ADAPT trial is registered on ClinicalTrials.gov (NCT03669588).", "authors": ["Hoffmann Sarah", "Zhao Sihui", "Callewaert Filip", "Schoppe Silke", "Rózsa Csilla", "Spillane Jennifer"], "journal": "Muscle & nerve", "entry_date": "2026/01/10 03:22", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41517964/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Neuroscience Clinical Research Center (NCRC) and Integrated Myasthenia Gravis Center, Charité-Universitätsmedizin, Berlin, Germany."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41517962", "title": "The Antibody-Microbiota Interface in Autoimmune Diseases.", "abstract": "The human intestine harbors a dense community of commensal microbes that strongly shape humoral immune responses. While secretory immunoglobulin A (sIgA) has long been recognized as a key regulator of microbiota compartmentalization and intestinal homeostasis, recent studies have also highlighted important roles for secretory IgM and systemic IgG in host-microbiota interactions. In this review, we examine critical aspects of the antibody-microbiota interface, first showing the extent to which microbiota and factors influencing microbiota ecosystem such as diet shape sIgA repertoire and binding capacity. We further integrate insights from both murine and human studies to provide a comprehensive overview of how antibody-microbiota interactions are altered in autoimmune diseases and contribute both to the identification of microbial drivers of disease and to the development of new therapeutic approaches. It is noteworthy that myasthenia gravis (MG) patients have a unique microbial signature, different from other autoimmune diseases, suggesting that yet-to-be-identified gut bacteria might specifically drive the host's immune response toward MG. Finally, we discuss the mechanisms through which the microbiota may contribute to the initiation or perpetuation of dysregulated immune responses underlying autoimmunity. Given the presence of IgA autoantibodies in MG patients and the broad homology between the acetylcholine receptor and the microbial proteome, molecular mimicry and epitope spreading should be investigated as potential triggering mechanisms.", "authors": ["Puechberty Solène", "Sterlin Delphine"], "journal": "Muscle & nerve", "entry_date": "2026/01/10 03:13", "pub_date": "2026-01-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41517962/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Centre d'Immunologie et des Maladies Infectieuses (CIMI-Paris), Sorbonne Université, Inserm, CNRS, Paris, France."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41517410", "title": "Spontaneous Pneumomediastinum in COVID-19 and Myasthenic-like Symptom Complications in Two Relatives: A Coincidence or Spike Toxicity with Thymic Response in Predisposed Individuals? Two Clinical Cases with a Comprehensive Literature Review.", "abstract": "Pneumomediastinum (PM) in SARS-CoV-2 infections can have a multifaceted presentation. The most frequently described cases of spontaneous PM (SPM) occurred during the first waves of the SARS-CoV-2 pandemic due to alveolar fragility related to severe cases of interstitial pneumonia and vascular injury that predisposed to alveolar destruction and to the Macklin effect in PM development. Cases of SPM were also reported secondary to non-invasive mechanical ventilation (NIV) and to the increasing use of higher doses of corticosteroid therapy. However, true SPM in COVID-19 patients without any identifiable risk factors and presenting as a \"Hamman syndrome\" (HS) has also been observed, although it represents a very rare clinical entity. Both lung dysbiosis and spike protein toxicity could be implicated in SPM, including cases occurring after COVID-19 vaccination. Furthermore, a variety of clinical entities have been reported that are similar both in COVID-19 infection and after the related COVID-19 vaccination. We present two clinical cases (a 14-year-old boy and his mother), one presenting with SPM and both showing thymic hyperplasia, myasthenic-like symptoms, and long COVID features as a post-vaccination syndrome (PACVS). This report highlights how genetic and familial predisposition could play a role in the thymic response both in COVID-19 infection and after vaccination, involving the toxicity of the spike protein as a common denominator.", "authors": ["Brogna Barbara", "Nunziata Mariagrazia", "Urciuoli Luigi", "Romano Annamaria", "Laporta Antonietta", "Brogna Claudia"], "journal": "Journal of clinical medicine", "entry_date": "2026/01/10 01:15", "pub_date": "2025-12-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41517410/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Unit Interventional and Emergency Radiology, St. Giuseppe Moscati Hospital, Center of National Excellence and High Speciality, 83100 Avellino, Italy."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41514597", "title": "Thymic Hyperplasias in Practice: Clinical Context, Histological Clues, and Management Implications.", "abstract": "BACKGROUND AND OBJECTIVE: Thymic hyperplasias constitute a heterogeneous group of primarily non-neoplastic conditions characterized by either enlargement of the thymic parenchyma or the proliferation of lymphoid follicles. Differentiating these entities is crucial, as they exhibit significant differences in their epidemiology, clinical associations, and implications for patient management. This review aims to synthesize the current knowledge on true thymic hyperplasia, rebound thymic hyperplasia, thymic follicular hyperplasia, and thymic hyperplasia with lymphoepithelial sialadenitis-like features, and to delineate their diagnostic boundaries in histology.\nMETHODS: A systematic literature review of the Medline database was conducted, encompassing all publications available up to November 2025. The search terms included thymic hyperplasia, true thymic hyperplasia, rebound thymic hyperplasia, thymic follicular hyperplasia, and lymphoepithelial-sialadenitis-like thymic hyperplasia. Studies concerning the histopathological, radiological, and clinical presentations as well as reference works concerning age-related thymus size and weight were included. Limitations stem from the scarcity of systematic investigations and heterogeneity of the available studies.\nRESULTS: Thymic hyperplasia encompasses biologically diverse entities unified solely by their benign nature, yet distinguished by distinct histological patterns and clinical scenarios. True thymic hyperplasia and rebound hyperplasia preserve the organ's fundamental architecture and lack association with autoimmunity; however, they differ in age distribution and clinical context. Thymic follicular hyperplasia reflects an immune-mediated process, strongly linked to early-onset myasthenia gravis, and is characterized by germinal-center formation within thymic lobes. Lymphoepithelial-sialadenitis-like thymic hyperplasia, by contrast, represents an epithelial-lymphoid proliferation with pronounced architectural distortion, frequent cystic changes, and notable associations with systemic non-myasthenic autoimmune diseases as well as thymic mucosa-associated-lymphatic-tissue lymphoma.\nCONCLUSIONS: Overall, clinical history, serological data, imaging, and detailed histopathology remain indispensable for differentiating thymic hyperplasias, some of which necessitate further systemic evaluation due to their association with autoimmune diseases or lymphomas.", "authors": ["Porubsky Stefan"], "journal": "Cancers", "entry_date": "2026/01/10 01:01", "pub_date": "2025-12-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41514597/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Institute of Pathology, University Medical Center of the Johannes Gutenberg University Mainz, Langenbeckstraße 1, 55131 Mainz, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "41514217", "title": "Urinary proteomic profiling reveals diagnostic biomarkers and regulatory networks in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular junction disorder mediated by autoantibodies. Existing diagnostic methods mainly rely on serum antibody detection and electrophysiological testing, which are limited by invasiveness and suboptimal sensitivity and specificity. This study aimed to identify potential urinary biomarkers for noninvasive MG diagnosis using proteomics.\nMETHODS: Data-independent acquisition (DIA) proteomic profiling was performed using a high-resolution Orbitrap Astral mass spectrometer on urine samples from 10 MG patients and 10 healthy controls. Differentially expressed proteins (DEPs) were identified and analyzed through Gene Ontology and KEGG pathway enrichment. LASSO regression and support vector machine models were applied to identify hub diagnostic proteins. The expression and diagnostic performance of the hub protein TPD52 were further validated in an independent cohort of 34 participants using ELISA.\nRESULTS: A total of 2,003 urinary proteins were identified between MG patients and healthy controls, among which 216 were significantly differentially expressed (|fold change| ≥ 1.2, p < 0.05). Enrichment analysis revealed that these DEPs were associated with neurodegenerative and neuroinflammatory diseases. Eight key proteins (TPD52, SORL1, PLAU, TSPAN3, CASP14, QPCT, CILP2, and CTHRC1) were identified by both LASSO and SVM algorithms, all exhibiting strong diagnostic performance (AUC > 0.76). In the independent validation cohort, the urinary expression of TPD52 was confirmed to be significantly elevated in MG patients, and ROC analysis yielded an AUC of 0.746, supporting its potential diagnostic value.\nCONCLUSION: This pilot urinary proteomic study provides preliminary evidence for urinary TPD52 as a potential noninvasive biomarker for MG and suggests its possible involvement in MG pathogenesis. These findings offer new insights into the molecular mechanisms of MG and lay a foundation for applying urinary proteomics in neuroimmune disorders.", "authors": ["Yang Jing", "Yang Xi", "Zhu Zhen-Kun", "Shen Liang", "San Shi-Ge", "Xiao Lianchen", "Ye Fan", "Wang Chun-Hua", "Meng Kun"], "journal": "BMC neurology", "entry_date": "2026/01/09 23:53", "pub_date": "2026-01-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41514217/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Central Laboratory, Xiangyang Central Hospital, Affiliated Hospital of Hubei University of Arts and Science, Xiangyang, Hubei, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41514039", "title": "BCMA-directed mRNA CAR-T cell therapy for myasthenia gravis: exploratory biomarker analysis of a placebo-controlled phase 2b trial.", "abstract": "Chimeric antigen receptor (CAR)-T cell therapies have the potential to transform treatment of autoimmune disease by resetting the immune system. However, adoption of cell therapies in the autoimmune space is limited by hurdles such as inpatient administration, lymphodepletion and safety concerns around cytokine release syndrome and non-specific immunosuppression. RNA-based cell therapy has potential to address these limitations. Here we report prespecified exploratory analyses from a successful placebo-controlled, double-blind, randomized phase 2b trial in patients with generalized myasthenia gravis who received Descartes-08, an autologous, RNA-encoded anti-B cell maturation antigen (BCMA) CAR-T cell therapy. In 66.7% of patients (n = 10/15), transient targeting of BCMA with Descartes-08 administered in an outpatient setting without lymphodepletion resulted in durable clinical efficacy. Comparison of Descartes-08-treated (n ≤ 19) and placebo (n ≤ 15) cohorts by flow cytometry, serum profiling, multiplexing cytokine analysis and bulk/single-cell transcriptional analysis reveals a precision retuning of self-reactivity demonstrated by increased pro-immune function, decreased activity of BCMA+ plasma cells and plasmacytoid dendritic cells and reductions in disease-associated cytokines, such as IL-6. Furthermore, antibody and T cell receptor analysis revealed altered circulating repertoires of self-reactive antibodies and T cell clones among Descartes-08 participants. These effects occurred without immune suppression, indicated by the lack of decline in vaccine-specific antibodies or hypogammaglobulinemia. Our findings unveil a new type of immune reset and support the development of BCMA-targeted RNA cell therapies as a more accessible therapy for autoimmune diseases. ClinicalTrials.gov identifier: NCT04146051 .", "authors": ["Fedak Renee R", "Ruggerie Rachel N", "Shan Yufei", "Curvino Elizabeth J", "de Sousa Juliana F", "Daniel Shaji", "Ngo-Casi Minhtran", "Kamboh Hafsa", "Vu Tuan", "Durmuş Hacer", "Mozaffar Tahseen", "Howard James F", "English Emily P", "Benson Albina", "Duvernay Matthew T", "Singer Michael S", "Kalayoglu Murat V", "Brunn Carsten", "Bodansky Aaron", "Anderson Mark S", "DeRisi Joseph L", "Garcia Samantha T", "Yu David J L", "Zorn Kelsey C", "Kurtoglu Metin", "Miljković Miloš D", "Stewart C Andrew", "Jewell Christopher M"], "journal": "Nature medicine", "entry_date": "2026/01/09 23:34", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41514039/", "pub_types": ["Journal Article"], "affiliations": ["Cartesian Therapeutics, Frederick, MD, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 50.0, "journal_quartile": "1区"}, {"pmid": "41514038", "title": "BCMA-directed mRNA CAR T cell therapy for myasthenia gravis: a randomized, double-blind, placebo-controlled phase 2b trial.", "abstract": "Myasthenia gravis (MG) is driven by the secretion of autoantibodies from pathogenic B cell maturation antigen (BCMA)-expressing plasma cells. In this phase 2b randomized, controlled, double-blind trial, we evaluated Descartes-08, an autologous BCMA-directed mRNA chimeric antigen receptor T cell therapy, in patients with generalized MG (gMG). Patients (n = 26) were randomly allocated to receive once-weekly intravenous infusions of Descartes-08 (n = 15) or placebo (n = 11) over 6 weeks. The primary endpoint was a ≥5-point improvement in the MG Composite (MGC) score at month 3. Secondary endpoints included the mean change from baseline in MGC, MG Activities of Daily Living (MG-ADL) and Quantitative MG (QMG) scores by month 12. At month 3, the proportion of patients achieving a ≥5-point improvement in the MGC score was significantly higher for those treated with Descartes-08 compared to placebo in the overall population (66.7% (n = 10/15) versus 27.3% (n = 3/11), P = 0.0472) and in a subpopulation of those positive for autoantibodies to the acetylcholine receptor (63.6% (n = 7/11) versus 12.5% (n = 1/8), P = 0.0258). For patients treated with Descartes-08, the changes from baseline in mean MGC, MG-ADL and QMG scores at month 4 were -7.1, -5.5 and -4.8, respectively, with 83.0% of patients achieving a sustained and clinically meaningful response at month 12. Notably, 33.0% of patients achieved minimum symptom expression (MSE) (MG-ADL score ≤1) by month 6, which was sustained through month 12. Among biologic-naive patients, 55.60% achieved MSE by month 6, which was maintained through month 12 without additional treatment. Descartes-08 was generally safe and well tolerated. Infusion-related reactions were the most common adverse events reported (Descartes-08, 80.0% (n = 16/20); placebo, 56.3% (n = 9/16)). In summary, a single course of six once-weekly infusions of Descartes-08 was well tolerated and resulted in sustained clinically meaningful responses among patients with gMG. ClinicalTrials.gov identifier: NCT04146051 .", "authors": ["Vu Tuan", "Durmus Hacer", "Rivner Michael", "Shroff Sheetal", "Ragole Thomas", "Myers Bennett", "Pasnoor Mamatha", "Small George", "Karam Chafic", "Vullaganti Mithila", "Peltier Amanda", "Sahagian Gregory", "Feinberg Marc H", "Slanksy Adam", "Barnett-Tapia Carolina", "Siddiqi Zaeem", "Gwathmey Kelly", "Badruddoja Michael A", "Kamboh Hafsa", "Ruggerie Rachel N", "Fedak Renee R", "Stewart C Andrew", "Kurtoglu Metin", "Kalayoglu Murat", "Singer Michael", "Jewell Christopher M", "Miljkovic Milos D", "Dimachkie Mazen", "Mozaffar Tahseen", "Howard James F"], "journal": "Nature medicine", "entry_date": "2026/01/09 23:34", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41514038/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase II", "Multicenter Study"], "affiliations": ["University of South Florida, Tampa, FL, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 50.0, "journal_quartile": "1区"}, {"pmid": "41512541", "title": "Comments on ZILU25: Real-world efficacy of Zilucoplan in generalized myasthenia gravis.", "abstract": "", "authors": ["Zheng Bowen"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/09 18:05", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41512541/", "pub_types": ["Letter"], "affiliations": ["Shandong Second Medical University, Weifang, China. Electronic address: zhengbowen1416@outlook.com."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41505161", "title": "Novel Therapies for Generalized Myasthenia Gravis: Insights Into FcRn and Complement Inhibition.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune neuromuscular disorder with significant unmet needs despite conventional therapies. Novel FcRn and complement inhibitors have transformed the treatment paradigm for generalized MG.\nMETHODS: This commentary reviews the clinical efficacy, safety, and practical implications of FDA-approved FcRn inhibitors (efgartigimod, rozanolixizumab, nipocalimab) and complements inhibitors (eculizumab, ravulizumab, zilucoplan), drawing on clinical trial data and literature from 2013 to 2025.\nRESULTS: FcRn inhibitors significantly improve MG-ADL scores in anti-AChR and MuSK antibody-positive patients, with rozanolixizumab and nipocalimab uniquely approved for MuSK-MG. Complement inhibitors show rapid efficacy in refractory anti-AChR MG, with zilucoplan enabling self-administration. Adverse events include infections and hypersensitivity reactions. These medications require vaccination and close monitoring.\nCONCLUSIONS: These therapies offer personalized, effective options for MG management, though challenges in cost and access remain. Future research should address long-term outcomes and biomarkers.", "authors": ["Samara Verena C", "Thottempudi Neeharika", "Franke Olivia", "Tabaac Burton J"], "journal": "American journal of therapeutics", "entry_date": "2026/01/08 11:40", "pub_date": "", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41505161/", "pub_types": ["Journal Article"], "affiliations": ["Reno School of Medicine, University of Nevada, Reno, NV; and."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41504129", "title": "Thymopentin-Induced Myasthenia Gravis: A Case Report Highlighting Clinical Vigilance.", "abstract": "", "authors": ["Zhao Ning", "Yang Li", "Li Ting"], "journal": "Balkan medical journal", "entry_date": "2026/01/08 07:08", "pub_date": "2026-04-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41504129/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Neurological Institute, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.8, "journal_quartile": "3区"}, {"pmid": "41503777", "title": "Association between immune-related adverse events and prognosis in immune checkpoint inhibitor therapy: A bibliometric and visual analysis.", "abstract": "With the gradual improvement in tumor immunotherapy, the incidence of immune-related adverse events (irAEs) has increased. However, according to current research, the relationship between irAEs and prognosis remains a contentious issue. This study used bibliometrics research to investigate hotspots and future trends on the relationship between irAEs and prognosis and to serve as a resource for researchers in this field. In the core literature database of Web of Science, the keywords immune checkpoint inhibitors(ICIs), immune-related adverse events, prognosis were used to search for the articles and reviews in the field of irAEs and prognosis. Set the time parameter to January 2007 to December 2023. Visualization analysis software CiteSpace 6.1.R6, VOSviewer1.6.18 and Carrots2 were used to conduct quantitative statistical and visual research on the author, institution, country, keyword, publication, cited literature, research status, research hotspots and development trends of the relevant research. The analytic research was based on original articles and reviews. 724 articles from 308 countries led by China(147)，the United States(131), and Japan(105) were included. The most popular tumor type is melanoma, small-cell lung cancer, and renal cell carcinoma. The focus topics in this field encompass \"Myasthenia gravis,\" \"neurotoxicity,\" \"liver damage,\" \"head and neck adverse events,\" \"colitis,\" and \"skin adverse events.\" This study has provided a valuable reference for future research in this field. Combination therapy, predictive biomarkers, patients' preexisting conditions, glucocorticoids, prognostic indicators, ICI rechallenge, and other topics could become research hotspots which will help us to identify useful information from complex big data and provide a basis for precise medicine for immune checkpoint inhibitor therapy.", "authors": ["Zhao Jun", "Quan Xianghua", "Liang Yu", "Ni Beibei", "Xing Xiaomin", "Liu Guangwei"], "journal": "Human vaccines & immunotherapeutics", "entry_date": "2026/01/08 05:23", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41503777/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pharmacy, The Affiliated Hospital of Qingdao University, Qingdao, Shandong, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "41503688", "title": "Risk of Infection Following Clearance of Immunoglobulin G by Plasma Exchange in Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Management of myasthenia gravis (MG) includes reduction of pathogenic IgG autoantibodies by intravenous immunoglobulin (IVIg), B-cell depletion, therapeutic plasma exchange (TPE), and neonatal Fc receptor (FcRn) blockers. Concerns exist that chronic IgG reduction could lead to more frequent infections. We assessed the frequency and severity of infection with associated serum IgG levels during infections in MG patients treated with chronic TPE in both inpatient and outpatient settings.\nMETHODS: MG patients treated with chronic TPE at a single center from April 2014 through December 2022 were included. All serum IgG levels from this cohort were recorded. Reported infections were limited to those who had clinically reported symptoms, supportive laboratory findings, necessitated inpatient admission for infection, or were treated with antibiotics/antivirals.\nRESULTS: Twenty-three patients were included. Ninety-seven infections were identified, with the majority of these being respiratory (36%) or urinary (22%). There were no differences in median serum IgG levels found during active infection versus periods of non-infection (657.3 [IQR: 459.5-823.1] and 518 [IQR: 472.9-672.5] mg/dL, respectively, Wilcoxon's p = 0.47). Infections necessitating inpatient admission did not have reduced median serum IgG compared with less severe infections or periods of non-infection (515.75 [IQR: 457.0-799.1], 660.5 [IQR: 472.9-808.4], and 518 [IQR: 467.8-672.5] mg/dL, respectively, pairwise Wilcoxon's p = 0.84). No correlation was identified between the number of reported infections per patient and their median serum IgG levels throughout the study period (Spearman's p = 0.26, p = 0.23).\nDISCUSSION: In this small retrospective study, there was no association between IgG levels and infections in patients with MG treated with chronic TPE.", "authors": ["Creed Eric B", "Rodrigues Amanda Cyntia Lima Fonseca", "Wan Shiyu", "Howard James F", "Karafin Matthew S"], "journal": "Muscle & nerve", "entry_date": "2026/01/08 05:03", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41503688/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University of North Carolina at Chapel Hill School of Medicine, Chapel Hill, North Carolina, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41502595", "title": "Advanced Masaoka-Koga stage as an independent predictor of thymoma recurrence after complete resection: myasthenia gravis was not an independent factor.", "abstract": "BACKGROUND: Although myasthenia gravis (MG) commonly coexists with thymoma, its prognostic role in thymoma recurrence is controversial. Therefore, we aimed to identify clinical and pathological predictors of recurrence after thymectomy in a single-center cohort.\nMETHODS: We retrospectively reviewed adult patients who underwent thymectomy for pathologically confirmed thymoma between January 2000 and December 2023 at a single tertiary center. Patients with at least 12 months of follow-up were included. Clinical, surgical, and pathological features were compared between patients with and without MG. Survival outcomes, including recurrence-free survival (RFS, R0 subgroup), progression-free survival (PFS, overall cohort), and overall survival (OS), were analyzed using Kaplan-Meier methods with log-rank tests. Independent predictors of recurrence were evaluated using Cox proportional hazards regression restricted to patients with R0 resection.\nRESULTS: Patients with MG were significantly younger and more likely to undergo transsternal extended thymectomy than those without MG. Although thymoma recurrence was more frequent in the MG group, MG status was not significantly associated with RFS or OS. Kaplan-Meier analysis showed that advanced-stage thymoma (stage III-IV) was associated with significantly shorter RFS, PFS, and OS compared with early-stage disease. In multivariate Cox regression restricted to R0 resections, advanced Masaoka stage remained an independent predictor of recurrence, while tumor size showed only a borderline association.\nCONCLUSIONS: Advanced Masaoka stage is the strongest independent predictor of thymoma recurrence after complete resection. Tumor size demonstrated a borderline association, suggesting a potential contributory role that requires further validation. MG, although clinically important for peri- and post-operative management, was not independently associated with recurrence.", "authors": ["Yang Jiwon", "Lee Yeong-Bae", "Kim Kun Woo"], "journal": "Gland surgery", "entry_date": "2026/01/08 04:36", "pub_date": "2025-12-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41502595/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Gil Medical Center, Gachon University College of Medicine, Incheon, Republic of Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41500177", "title": "Variations in clinical features and disease burden of myasthenia gravis between racial and ethnic groups: A retrospective cohort study of two national databases.", "abstract": "Previous studies have reported that clinical characteristics and outcomes of myasthenia gravis (MG) vary across racial and ethnic groups. This study leverages two nationwide datasets, the MG Foundation of America Global MG Patient Registry (MGFAPR) and the National Inpatient Sample (NIS) to further examine these reports. We compared clinical characteristics, socioeconomic determinants, therapeutic regimens, and inpatient outcomes across racial/ethnic groups of MGFAPR enrollees between July 2013 and November 2024 that self-reported MG diagnosis by a physician and were US residents over the age of 18. Of 3744 patients, race was reported for: 3099 White, 178 African American (AA), 47 Asian, and 151 Indigenous patients; ethnicity was reported for: 188 Hispanic and 3431 non-Hispanic patients. AA and Hispanic patients had higher frequencies of early-onset MG and generalized symptoms; AA and Indigenous patients had higher MG-ADL and MG-QOL15r scores at enrollment; and White and Indigenous patients had higher frequencies of comorbid cancer. In the MGFAPR, women were 30 % less likely to be hospitalized and anxiety and/or depression was 300 % more common in hospitalized patients. In the NIS, we identified 62,055 hospitalizations for MG worsening from 2012 to 2019. AA and Hispanic MG patients had 1.4 and 1.7-times greater odds of intubation than White patients. Average cost of hospitalization was 150 % higher for AA patients than White patients. Overall, MG presented differently across racial/ethnic groups: we observed a greater disease burden in terms of ability to perform activities of daily life, quality of life, inpatient outcomes, and hospitalization costs in AA, Hispanic, and Indigenous patients.", "authors": ["McLaren Nilay", "Gutierrez Amaia Zurinaga", "Joo Daniel", "Roy Bhaskar", "Park Minjee", "Nowak Richard J"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/07 18:09", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41500177/", "pub_types": ["Journal Article"], "affiliations": ["Yale School of Medicine, Department of Neurology, New Haven, CT, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41499269", "title": "Analysis of infections and malignancy risks among patients with myasthenia gravis compared with matched controls in a US real-world setting.", "abstract": "IntroductionMyasthenia gravis (MG) is a rare, debilitating autoimmune disease associated with pathogenic immunoglobulin G autoantibodies directed against components of the neuromuscular junction. The autoimmune nature of the disease and long-term immunosuppressive treatment may increase susceptibility to infections and malignancies, but studies investigating the association between MG and infections or malignancies remain scarce.MethodsWe conducted a retrospective, observational study using Optum's deidentified Market Clarity Data (Market Clarity) to evaluate the incidence rate (IR) of infections and malignancies in US-based patients with MG in a real-world setting. Adults with ≥2 diagnosis claims of MG were identified over a 2-year period (2016-2019) and propensity score (PS) matched with controls from the general population without MG. Patients with malignancies in the 1-year look-back period were excluded.ResultsPatients with MG (N = 5002) were compared with the PS-matched general population (N = 20,008). The IR of serious infections (primary outcome) was higher in the MG cohort compared with the general population (52.81 vs 31.46 per 1000 person-years [PY], respectively). IRs of opportunistic infections (87.48 vs 57.01 per 1000 PY) and infection-related death (3.98 vs 1.94 per 1000 PY) were also higher in the MG cohort compared with the general population. The overall rate of malignancy was higher in the MG cohort compared with the general population (73.55 vs 50.01 per 1000 PY, respectively).ConclusionsIn this analysis, patients with MG were more susceptible to serious infections, infection-related death, and malignancies.", "authors": ["Podhorna Jana", "Ward Charlotte", "Naik Kushal B", "Lee Ikjae", "Li Yuebing", "Ruck Tobias", "Teperov Elizabeth", "Guptill Jeffrey T"], "journal": "Journal of neuromuscular diseases", "entry_date": "2026/01/07 12:52", "pub_date": "2026-01-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41499269/", "pub_types": ["Journal Article"], "affiliations": ["argenx, Ghent, Belgium."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41497016", "title": "Nipocalimab in the management of generalized myasthenia gravis: a new targeted therapeutic approach.", "abstract": "", "authors": ["Khalid Muddassir", "Haider Ehtisham", "Khan Afzaal", "Haider Noor-Ul-Eman"], "journal": "Annals of medicine and surgery (2012)", "entry_date": "2026/01/07 04:46", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41497016/", "pub_types": ["Letter"], "affiliations": ["Department of Medicine, Nishtar Medical University, Multan, Pakistan."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41496184", "title": "Bridging the gap in sexuality and neuromuscular disorders: a scoping review of an overlooked but crucial topic.", "abstract": "INTRODUCTION: Neuromuscular disorders (NMDs) comprise a group of conditions affecting the muscles and/or the nerves controlling them, resulting in progressive muscle weakness. Beyond the physical limitations, NMDs can significantly impact quality of life (QoL), including sexuality. Sexuality, as defined by the World Health Organization, encompasses physical, psychological, and social dimensions. However, research exploring the multifaceted impact of NMDs on sexual well-being remains limited, despite the potential influence of physical impairments, psychological distress, and social stigma.\nOBJECTIVES: This scoping review aims to synthesize the existing literature on sexuality in individuals with NMDs, identifying the interplay of physical, psychological, and social factors affecting sexual QoL, highlighting research gaps, and informing future research and clinical practice.\nMETHODS: A scoping review was conducted using PubMed, Web of Science, Cochrane Library, Embase, and Scopus databases (up to May 15, 2025) to identify studies examining sexuality in individuals with NMDs. Studies addressing physical, psychological, and social factors influencing sexual health in NMD patients were included. Data were extracted using a standardized form and synthesized narratively. The review was registered on Open OSF (DOI https://doi.org/10.17605/OSF.IO/RP9U2).\nRESULTS: Fourteen studies with various conditions such as Duchenne muscular dystrophy, amyotrophic lateral sclerosis (ALS), myotonic dystrophy type 1, myasthenia gravis, and Charcot-Marie-Tooth disease were included, from interviews to surveys. One key theme that emerged was the extent to which personal narratives reveal the emotional weight of stigma, the struggle with body image, and how intimacy is peripheral in medical institutions. In surveys, many said their sexual activity had declined, particularly among people with progressive diseases like ALS and myotonic dystrophy. Many of these studies also pointed to how sexual health was directly associated with QoL, a good reminder that it's an important aspect of well-being that we need to pay more attention to in care and support.\nCONCLUSION: This scoping review highlights a significant gap in research regarding sexuality in individuals with NMDs. The limited number of studies identified underscores the need for further research to understand the complex interplay of physical, psychosocial, and social factors affecting sexual well-being in this population.", "authors": ["Portaro Simona", "Latella Desirèe", "Manuli Alfredo", "Calderone Andrea", "Calabrò Rocco Salvatore"], "journal": "Sexual medicine reviews", "entry_date": "2026/01/07 01:03", "pub_date": "2026-01-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41496184/", "pub_types": ["Journal Article", "Scoping Review", "Research Support, Non-U.S. Gov't"], "affiliations": ["Department of Physical and Rehabilitation Medicine, University Hospital \"G. Martino\", Messina 98124, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.0, "journal_quartile": "3区"}, {"pmid": "41495972", "title": "Preoperative Management of Patients With Myasthenia Gravis: A Review of the Evidence.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by fatigable weakness and increased perioperative vulnerability. Postoperative myasthenic crisis, defined as respiratory failure requiring prolonged ventilation or re-intubation, remains a feared complication after surgical procedures such as thymectomy. The efficacy of preoperative interventions such as intravenous immunoglobulin (IVIg) and plasmapheresis remains uncertain. This review examines the evidence supporting risk stratification tools and immunomodulatory strategies to prevent postoperative myasthenic crisis. A comprehensive literature review was conducted focusing on studies evaluating the incidence, risk factors and preventive strategies for postoperative myasthenic crisis in MG patients. Particular emphasis was placed on clinical predictive models and randomized trials assessing preoperative IVIg and plasmapheresis. Recent data suggest the incidence of postoperative myasthenic crisis has declined to below 10%, largely due to advances in surgical technique and perioperative care. Established risk factors include bulbar involvement, reduced pulmonary function and prior crises. Risk prediction models such as the Leuzzi and Kanai scores offer clinically useful stratification. While older retrospective studies favored preoperative plasmapheresis, meta-analyses and randomized trials have yielded mixed results. Randomized trials of IVIg have shown no significant benefit in well-controlled patients, and both interventions carry notable risks and costs. Current evidence does not support the routine use of IVIg or plasmapheresis prior to surgery in all MG patients. A targeted, risk-based approach guided by validated predictive models is recommended to minimize unnecessary interventions and health care system costs.", "authors": ["Alhammadi Salwa", "Chalk Colin"], "journal": "The Canadian journal of neurological sciences. Le journal canadien des sciences neurologiques", "entry_date": "2026/01/07 00:32", "pub_date": "2026-01-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41495972/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology & Neurosurgery, McGill Universityhttps://ror.org/01pxwe438, Montréal, QC, Canada."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41494982", "title": "The Incidence of Malignancy and Autoimmune Disorders After Thymectomy: An Exploratory Study.", "abstract": "OBJECTIVES: Thymectomy reportedly increases the risk of cancer, autoimmune disease, and death. Studies are few and data limited. We sought to determine the incidence of postoperative malignancy and autoimmune disease in patients who underwent thymectomy.\nMETHODS: We conducted a retrospective review of adult patients undergoing thymectomy between 2008 and 2020. Postoperative cancers and autoimmune disease were diagnosed after thymectomy. Incidence rates were calculated using patient-years and compared to the National Cancer Institute's (NCI) Surveillance, Epidemiology, and End Results (SEER) programme incidence of cancer for the US general population. Autoimmune disease rates were compared to previously published results.\nRESULTS: There were 226 patients with a median age of 55 years (interquartile range [IQR] = 39-67), mostly female (129, 57%) and non-smokers (132, 58%). At baseline, 117 (52%) had autoimmune disease, including 102 (45%) with myasthenia gravis. Eighty-four (37%) thymomas were identified. Median follow-up was 6.0 years (134 with >5-year follow-up and 44 with >10-year follow-up). We observed 13 (6%) new malignancies for an incidence of 0.87 cases/100 person-years (0.87%) and comparable to the NCI rate of 0.81 cases/100 person-years (0.81%). Incident cancers developed within the first 5 years after surgery at 0.92 cases/100 person-years (0.92%) or 4.6% cumulatively over 5 years, compared to NCI data at 4%. There were 19 (8%) new autoimmune diagnoses with an incidence rate of 1.3 cases/100 person-years (1.3%) and is higher than large population studies (0.7 cases/100 person-years for all ages).\nCONCLUSIONS: Development of new cancers following thymectomy in the United States is similar to the general population. But we identified a higher incidence of autoimmune disease, matching prior studies.", "authors": ["Hanson Chloe E", "White Peter T", "Bograd Adam J", "Mackay Emily M", "Farivar Alexander S", "Vallières Eric", "Louie Brian E"], "journal": "European journal of cardio-thoracic surgery : official journal of the European Association for Cardio-thoracic Surgery", "entry_date": "2026/01/06 22:43", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41494982/", "pub_types": ["Journal Article"], "affiliations": ["Division of Thoracic Surgery, Swedish Medical Center, Seattle, WA 98104, United States."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41494980", "title": "Effect of the Extent of Thymus Excision on the Risk of Subsequent Cancer Development.", "abstract": "OBJECTIVES: Thymus removal can alter immune function and potentially influence cancer development. However, the relationship between the extent of thymus removal and postoperative cancer development remains underexplored. This study aimed to identify risk factors for cancer development post-thymectomy, with particular focus on the extent of thymic resection.\nMETHODS: We reviewed 254 patients who underwent thymectomy between 2005 and 2021. Patients with myasthenia gravis, combined resection of adjacent organs, thymic cancer, or tumour recurrence were excluded. Clinical characteristics and postoperative cancer incidence were compared between the total and partial thymectomy groups.\nRESULTS: This study included 112 patients: 91 (81%) and 21 (19%) in the total and partial thymectomy groups, respectively. Patients in the total thymectomy group were significantly older than those in the partial thymectomy group (median age, 60 vs 44 years; P = .021). No significant differences were observed in sex, smoking history, preoperative cancer history, or observation period between the groups. Postoperative cancer development was significantly more common in the total thymectomy group (21 [23.1%] vs 1 [4.8%], P = .032). The median interval between surgery and cancer development was 2367 days. In the multivariable analysis, total thymectomy was identified as an independent risk factor for cancer development (hazard ratio 6.26, P = .032) after adjusting for potential confounders (age, sex, surgical method, and smoking history).\nCONCLUSIONS: Total thymectomy was identified as the only independent factor associated with increased postoperative cancer risk. These findings suggest the need to consider the extent of thymectomy and long-term cancer surveillance post-surgery.\nIRB INFORMATION: Institutional Review Board of Kitasato University (approval number: B24-079). The need to obtain written informed consent from each patient was waived because the study was retrospective.", "authors": ["Tamagawa Satoru", "Mitsuhashi Shunsuke", "Kondo Yasuto", "Sonoda Dai", "Naito Masahito", "Shiomi Kazu", "Ohta Ryo", "Suzuki Kazuomi", "Maruyama Masahiro", "Chuman Motohiro", "Chino Shinichiro", "Egi Hiroyuki", "Kaizu Takashi", "Satoh Yukitoshi", "Mikubo Masashi"], "journal": "European journal of cardio-thoracic surgery : official journal of the European Association for Cardio-thoracic Surgery", "entry_date": "2026/01/06 22:43", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41494980/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Kitasato University School of Medicine, Kanagawa 252-0374, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41494872", "title": "Jaw-hanging sign in myasthenia gravis: was Saint Mungo the first recorded case?", "abstract": "", "authors": ["Lawden Mark"], "journal": "Practical neurology", "entry_date": "2026/01/06 21:43", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41494872/", "pub_types": ["Journal Article"], "affiliations": ["Retired Neurologist, Leicester, Leicestershire, UK mark.lawden@btinternet.com."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "41494381", "title": "Mechanisms of immune modulation by therapeutic plasma exchange.", "abstract": "Therapeutic plasma exchange (TPE) is a cornerstone extracorporeal therapy with broad immunomodulatory effects across diverse immune-mediated and inflammatory diseases. By removing circulating pathogenic substances such as autoantibodies, immune complexes, complement components, and pro-inflammatory cytokines, TPE rapidly interrupts humoral pathways driving tissue injury. This review summarizes the mechanisms through which plasma exchange modulates immune activity, including both depletion of harmful plasma factors and restoration of normal homeostatic proteins when donor plasma is used. Biomarker analyses demonstrate predictable reductions in immunoglobulins, cytokines, and complement activity, reflecting the profound but transient immune reset achieved with TPE. Comparisons with related apheresis modalities, such as immunoadsorption, double filtration plasmapheresis, and extracorporeal photopheresis, highlight the unique advantages of TPE as a broadspectrum immunomodulatory intervention. Clinically, TPE remains a vital therapeutic option in conditions ranging from thrombotic thrombocytopenic purpura and myasthenia gravis to vasculitis and cytokine storm syndromes. As evidence and technology evolve, plasma exchange continues to exemplify how biophysical removal of pathogenic plasma constituents can effectively restore immune balance and improve patient outcomes in both acute and chronic immune-mediated diseases.", "authors": ["Parisi Nicholas", "Nadim Menatalla", "Akgun Yamac"], "journal": "Transfusion and apheresis science : official journal of the World Apheresis Association : official journal of the European Society for Haemapheresis", "entry_date": "2026/01/06 18:04", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41494381/", "pub_types": ["Journal Article", "Review"], "affiliations": ["University of Miami Miller School of Medicine, Department of Pathology and Laboratory Medicine, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41494305", "title": "Prevalence and trajectories of post-COVID-19 neuromuscular conditions: A systematic-review and meta-analysis.", "abstract": "INTRODUCTION: Neuromuscular diseases (NMDs) are a significant component of the post-acute sequelae of COVID-19. However, their long-term prevalence and trajectories remain poorly defined. This systematic review and meta-analysis aimed to determine the long-term prevalence in COVID-19 survivors of fourteen specific NMDs and related symptoms: cranial nerve diseases, Guillain-Barré syndrome, small fiber neuropathy, (poly)radiculopathies, (poly)neuropathies, plexopathies, motor neuron disease, myasthenia gravis, Lambert-Eaton syndrome, neuropathic pain, sarcopenia, myalgia, myalgia associated with other symptoms, and of other muscle diseases.\nMETHODS: We searched MEDLINE, Embase, and the Cochrane Library (January 2020 through November 2024) for studies with at least 3 months of follow-up. Pooled prevalence estimates were calculated at multiple time points (acute phase to 24 months) using random effects models.\nRESULTS: Among 180 unique studies representing 15,865,322 cases (54 % female, mean age 50.0 years), the pooled prevalence for individuals with at least one NMD or related symptoms decreased from 36 % in the acute phase to 8 % at 24 months. Myalgia prevalence steadily declined from 35 % to 8 % by two years. A trend towards lower prevalences across the time points was observed also for Guillain-Barré syndrome, and other muscle diseases, while other conditions showed a more erratic pattern. The prevalence of neuropathic pain remained high and persisted almost unchanged through the follow-up period (from 31 % in the acute phase to 25 % at 12 months).\nCONCLUSIONS: NMDs and related symptoms are common following COVID-19, but their general prevalence decreases with time. However, trajectories varied depending on the type of NMD or symptom.", "authors": ["Pupillo Elisabetta", "Leone Maurizio A", "Amato Anthony", "Bianchi Elisa", "Damian Maxwell S", "Dyck James", "Garcia-Azorin David", "Giussani Giorgia", "Guekht Alla", "Koike Haruki", "Khadilkar Satish", "Lehmann Helmar", "Pochigaeva Ksenia", "Povolnova Juliya", "Tumurov Dmitri", "Vetrov Fedor", "de Visser Marianne", "Winkler Andrea Sylvia", "Grisold Wolfgang"], "journal": "Journal of the neurological sciences", "entry_date": "2026/01/06 18:03", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41494305/", "pub_types": ["Journal Article", "Meta-Analysis", "Systematic Review", "Review"], "affiliations": ["Istituto di Ricerche Farmacologiche Mario Negri IRCCS, Milan, Italy."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41493641", "title": "Does myasthenia gravis impact cognitive functioning? A systematic review and meta-analysis.", "abstract": "BACKGROUND: Myasthenia Gravis, traditionally known as a purely motor disease, has been recently associated also with non-motor symptoms, including psychological and cognitive symptoms. However, the presence of cognitive impairment in Myasthenia Gravis remains unclear due to limited and heterogeneous findings. This systematic review and meta-analysis aims to clarify the relationship between Myasthenia Gravis and cognitive performances.\nMETHODS: Following PRISMA guidelines, we systematically searched PubMed, Web of Science, and SCOPUS for original researches published between January 2000 and December 2024 assessing cognitive functioning in people with MG compared to healthy controls. Pooled standardized mean differences and 95% confidence intervals were calculated for each cognitive domain using random-effects meta-analysis.\nRESULTS: Six studies comprising 242 Myasthenia Gravis patients and 166 healthy controls met inclusion criteria. Compared to healthy controls, people with Myasthenia Gravis showed significantly lower performance in processing speed (Symbol Digit Modalities Test), phonemic and animal verbal fluency, visuo-spatial memory (visual reproduction), and verbal learning (California Verbal Learning Test). Heterogeneity was low to moderate across most outcomes.\nCONCLUSIONS: This meta-analysis supports the presence of selective cognitive impairments in individuals with Myasthenia Gravis. These findings underscore the need for a multidimensional approach to care in Myasthenia Gravis, that includes cognitive and psychological health.", "authors": ["Marcassoli Alessia", "Trucco Giulia", "Mazzilli Angelica", "Colombo Alice", "Lanza Martina", "Leonardi Matilde", "Frangiamore Rita", "Maggi Lorenzo", "Antozzi Carlo", "Mantegazza Renato Emilio", "Corso Barbara", "Raggi Alberto"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/01/06 13:09", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41493641/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Neurology, Public Health and Disability Unit, Fondazione IRCCS Istituto Neurologico Carlo Besta, Via Celoria 11, Milano, 20133, Italy. alessia.marcassoli@istituto-besta.it."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41493482", "title": "Dropped head syndrome leading to the diagnosis of antisynthetase syndrome: a motor neuron mimicker.", "abstract": "BACKGROUND: Antisynthetase syndrome (ASS) is a rare subtype of idiopathic inflammatory myopathies that may present with muscular and/or extra-muscular features, sometimes delaying diagnosis. Dropped head syndrome (DHS) is an uncommon manifestation of axial muscle weakness and can mimic motor neuron disease or myasthenia gravis.\nCASE PRESENTATION: We report the case of a 64-year-old male presented with dropped head and proximal weakness. Initial electromyography (EMG) revealed fibrillation potentials, positive sharp waves during rest, and signs of reinnervation during voluntary contraction, initially raising concern for a neurogenic process. Because of increased jitter on single-fiber EMG, myasthenia gravis was considered, but pyridostigmine provided no benefit. Although creatine kinase (CK) was only mildly elevated, myositis-specific autoantibodies, inflammatory biopsy changes, and myopathic features on repeat EMG, especially in cervical paraspinals, led to a diagnosis of ASS. Chest Computed Tomography (CT) revealed bibasilar bronchiectasis and micronodules.\nCONCLUSION: This case highlights the diagnostic challenge of distinguishing ASS from motor neuron disease or myasthenia gravis. Inflammatory myopathies should be considered in DHS, with careful selection of muscles and interpretation of EMG findings, especially when CK elevation is modest.", "authors": ["Duman İlki Canan", "Pek Gökhan", "Özaydın Aksun Zerin", "Şener Hüseyin Özden"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/01/06 13:01", "pub_date": "2026-01-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41493482/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, Ankara University Faculty of Medicine, Ankara, Türkiye, Turkey. cananduman-cd@hotmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41491925", "title": "Gender differences in Myasthenia Gravis in a neuromuscular reference center in Belgium.", "abstract": "BACKGROUND: It is well known that scientific literature has a significant gender gap, as gender differences were not considered until very recently. Women were often excluded from studies, and even when included, the results are rarely analyzed separately by gender. This study aims to investigate gender-specific differences in patients with Myasthenia Gravis (MG) by segregating data from our cohort of patients in Antwerp (Belgium).\nMETHODS: We analyzed the data of our previously published cohort of 163 patients with MG visited in the Antwerp University Hospital between 2019 and 2021, segregating the information by gender to observe any significant differences.\nRESULTS: The analysis revealed several notable gender-specific differences. Women experienced a delay in diagnosis of over one year more frequently than men. They also had dysarthria as presenting symptom more often than men. The MGFA scores at maximum severity were higher in women, who also reported more limitations due to the disease and required more treatments to control it. While some differences could be attributed to the younger onset of the disease in women, certain differences were independently influenced by gender.\nCONCLUSIONS: Women experience more limitations due to MG than men and may face a more severe disease course. These differences should be taken into account when determining follow-up and treatment strategies. Additionally, these findings highlight the importance of segregating data by gender in scientific studies to better understand gender-specific differences in disease presentation and management.", "authors": ["Alonso-Jiménez Alicia", "De Ridder Willem", "Van Schil Paul", "Baets Jonathan", "Mercelis Rudy"], "journal": "Acta neurologica Belgica", "entry_date": "2026/01/06 11:35", "pub_date": "2026-01-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41491925/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Antwerp University Hospital, Antwerp, Belgium. alicia.alonso-jimenez@uza.be."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41490161", "title": "Sport Performance as a Diagnostic and Monitoring Tool in Juvenile Myasthenia Gravis.", "abstract": "", "authors": ["Chakrapani Tia L"], "journal": "Journal of child neurology", "entry_date": "2026/01/06 10:33", "pub_date": "2026-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41490161/", "pub_types": ["Journal Article"], "affiliations": ["Catlin Gabel School, Portland, OR, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "3区"}, {"pmid": "41488758", "title": "Sugammadex versus Neostigmine Reversal After Thoracoscopic Thymectomy in Myasthenia Gravis: A Multicenter, Randomized Controlled Trial.", "abstract": "PURPOSE: Rapid and complete reversal of residual neuromuscular blockade (rNMB) is essential for safe postoperative recovery in patients with myasthenia gravis (MG) undergoing video-assisted thoracoscopic (VATS) thymectomy. Although sugammadex provides a novel approach for reversing rocuronium-induced neuromuscular blockade, its efficacy in this high-risk population under routine-practice conditions-where reversal timing relies on clinical judgment-remains incompletely characterized. This multicenter randomized controlled trial (RCT) compared the efficacy of sugammadex versus neostigmine for reversing rNMB in patients with mild MG undergoing VATS thymectomy, specifically under this pragmatic, experience-guided scenario.\nPATIENTS AND METHODS: In this prospective, superiority-design RCT, MG patients scheduled for VATS thymectomy were randomized 1:1 to receive either sugammadex (2 mg/kg) or neostigmine (0.05 mg/kg with atropine 0.02 mg/kg) for reversal of rocuronium-induced neuromuscular blockade. All patients received a standard induction dose of rocuronium (0.6 mg/kg). The attending anesthesiologist, blinded to both the reversal agent and all quantitative neuromuscular monitoring data, managed blockade using a minimal-dose strategy (boluses only for clinical signs of inadequate block). This blinded anesthesiologist determined reversal timing based on clinical judgment, with administration contingent upon independent verification of a TOF count ≥ 2. The primary outcome was recovery time (interval from reversal agent administration to normalized TOF ratio of ≥ 0.9), analyzed with the Mann-Whitney U-test. Secondary outcomes included extubation time, operating room stay duration, and incidence of rNMB at extubation and post-anesthesia care unit (PACU) arrival.\nRESULTS: Among 62 randomized patients (31 per group), all patients received reversal at a train-of-four (TOF) count of ≥2 (median count at reversal: 3 in both groups). Sugammadex achieved significantly faster recovery (median 2.62 [IQR 1.83-3.28] minutes; range 0.92-5.80 minutes) versus neostigmine (14.63 [12.22-16.30] minutes; range 10.97-28.81 minutes), with an estimated median difference of 12.01 minutes (95% CI: 9.50-14.52; P < 0.001). The sugammadex group also demonstrated: shorter extubation time (P < 0.001), reduced operating room (OR) stay (P < 0.001), and lower incidence of rNMB at extubation and PACU arrival (both P < 0.01). The incidence of postoperative complications was similar between groups.\nCONCLUSION: In patients with MG undergoing VATS thymectomy, this pragmatic trial simulating routine practice demonstrates that sugammadex provides faster and more reliable reversal of moderate neuromuscular blockade (median TOF count 3) than neostigmine, leading to clinically meaningful reductions in recovery time (by 12.01 minutes), extubation time, and rNMB incidence.", "authors": ["Hu Chunhua", "Liu Shijiang", "Xi Chunhua", "Du Yingjie", "Su Shaofei", "Wang Yue", "Wu Lili", "Chen Hongya", "Wang Guyan"], "journal": "Drug design, development and therapy", "entry_date": "2026/01/05 05:34", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41488758/", "pub_types": ["Comparative Study", "Journal Article", "Multicenter Study", "Pragmatic Clinical Trial", "Randomized Controlled Trial", "Equivalence Trial"], "affiliations": ["Department of Anesthesiology, Beijing Tongren Hospital, Capital Medical University, Beijing, People's Republic of China."], "china_related": true, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 5.1, "journal_quartile": "2区"}, {"pmid": "41488646", "title": "Toll-like receptors and their role in the pathogenesis of myasthenia gravis: a comprehensive review.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder marked by autoantibody-mediated dysfunction at the neuromuscular junction, resulting in fluctuating muscle weakness. The pathogenesis of MG involves a complex interplay between genetic predisposition, environmental factors, and immune system dysregulation. Among these, the innate immune system, particularly Toll-like receptors (TLRs), has emerged as a critical player in disease progression by influencing both innate and adaptive immunity. TLRs are a family of pattern recognition receptors (PRRs) that detect pathogen-associated molecular patterns (PAMPs) and damage-associated molecular patterns (DAMPs), triggering immune responses. Dysregulation of TLRs expression and signaling in MG has been implicated in chronic inflammation, breakdown of immune tolerance, and activation of autoreactive T and B cells. Overexpression of specific TLRs, such as TLR4 and TLR9, has been reported in MG patients, particularly in thymic tissues and peripheral immune cells, correlating with increased pro-inflammatory cytokine production and autoantibody generation. These aberrant responses contribute to the autoimmune cascade that underlies MG. Emerging evidence highlights the therapeutic potential of targeting TLRs pathways in MG. Strategies include using TLRs antagonists, modulating downstream signaling pathways, and leveraging epigenetic regulators to normalize TLRs activity. This review examines the role of TLRs in MG by exploring their expression profiles, their involvement in inflammatory signaling pathways, their impact on the adaptive immune system, and their potential as therapeutic targets. A better understanding of the role of TLRs in MG pathogenesis could open new avenues for modulating immune responses and precision therapies targeting the innate immune system.", "authors": ["Zheng Xiaoxiao", "Li Ling", "Ma Hongyue", "Zhu Mingxia", "Li Xiuli", "Feng Xinhong"], "journal": "Frontiers in immunology", "entry_date": "2026/01/05 05:33", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41488646/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Beijing Tsinghua Changgung Hospital, School of Clinical Medicine, Tsinghua Medicine, Tsinghua University, Beijing, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41488644", "title": "Differential expression profiles of lncRNAs and a preliminary study on the mechanism of lncRNA FAM225A in triple seronegative myasthenia gravis.", "abstract": "BACKGROUND: Triple-seronegative (Triple-SN) myasthenia gravis (MG) is a subtype of MG, and its diagnosis and treatment are challenging. Our study aims to discover new biomarkers and potential therapeutic targets and explore the preliminary mechanisms of triple-SN MG.\nMETHODS: Peripheral blood mononuclear cells (PBMCs) were collected from 15 patients with triple-SN MG who were newly diagnosed with the disease and 15 healthy controls. Various experimental techniques and analysis methods, such as PBMC isolation, microarray analysis, dual-luciferase reporter assay, quantitative real-time polymerase chain reaction (qRT-PCR), cell culture, and transfection, were used.\nRESULTS: Our study identified 385 differentially expressed genes (DEmRNAs) and 361 differentially expressed lncRNAs (DElncRNAs) in triple-SN MG. Notably, lncRNA FAM225A, one of the top five downregulated DElncRNAs, was verified to decreased and negatively correlated with the clinical severity of triple-SN MG. Functional enrichment analysis, immune infiltration analysis and further experiments revealed that FAM225A affected the imbalance of Th1/Th2 by targeting hsa-miR-150-5p in the pathogenesis of triple-SN MG.\nCONCLUSIONS: This study is the first to provide important clues for understanding the pathological mechanism of triple-SN MG, which might contribute to the discovery of novel diagnostic and therapeutic monitoring biomarkers and new targets for the treatment of triple-SN MG.", "authors": ["Hao Yuehan", "Chen Chen", "Wang Bo", "Yang ChunHua", "Zhu Ying", "Zhu Ruixia"], "journal": "Frontiers in immunology", "entry_date": "2026/01/05 05:33", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41488644/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of China Medical University, Shenyang, China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41487981", "title": "Immune Checkpoint Inhibitor-Associated Myocarditis With Myositis/Myasthenia Gravis Overlap Syndrome: Two Case Reports Highlighting Early Onset, Diagnostic Uncertainty, and Management Considerations.", "abstract": "Immune checkpoint-inhibitors (ICIs) have revolutionized and significantly improved cancer care through remarkable efficacy, but significant adverse effects have been observed. Among these, ICI-induced myocarditis with myositis/myasthenia gravis overlap syndrome represents a life threatening, severe immune-related adverse event that clinicians need to be aware of and be able to diagnose rapidly given its aggressive course. We present two patients who were treated with ICIs and subsequently developed said syndrome. Both patients experienced significant cardiac and neuromuscular manifestations and despite high-dose intravenous steroids, intravenous immunoglobulin, and other adjunctive therapies, both patients rapidly deteriorated and elected to withdraw care. Additionally, we review the pathophysiology, diagnosis and management of ICI-induced myocarditis with myositis/myasthenia gravis overlap syndrome. Overall, the overlap syndrome has a poor prognosis and high mortality rates requiring prompt recognition, discontinuation of ICIs and initiation of immunosuppressive therapies.", "authors": ["Schneider Artur", "Jhawar Nikita", "Reddy Deepica", "Chirila Razvan"], "journal": "Clinical case reports", "entry_date": "2026/01/05 05:25", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41487981/", "pub_types": ["Journal Article"], "affiliations": ["Department of Internal Medicine Mayo Clinic Jacksonville Florida USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41487841", "title": "Double Trouble: Guillain-Barré Syndrome (GBS) Presenting as Overlapping Miller Fisher Syndrome (MFS) and Pharyngeal-Cervical-Brachial (PCB) Variant.", "abstract": "Guillain-Barré Syndrome (GBS) is the leading cause of acute flaccid paralysis in India following the decline of poliomyelitis. Classical GBS typically presents with ascending symmetrical weakness and areflexia, while atypical variants, such as Miller Fisher Syndrome (MFS) and the Pharyngeal-Cervical-Brachial (PCB) variant, show distinct clinical patterns that are often under-recognized, particularly in resource-limited settings. This report describes a rare case of a 45-year-old previously healthy woman who developed progressive ophthalmoplegia, bulbar weakness, neck flexor weakness, and proximal upper limb weakness, along with areflexia, following a mild upper respiratory tract infection. Sensory function and lower limb motor strength remained intact. The differential diagnoses included brainstem stroke, myasthenia gravis, and diphtheritic polyneuropathy. Cerebrospinal fluid analysis revealed albuminocytologic dissociation, and nerve conduction studies showed a demyelinating sensorimotor polyneuropathy predominantly affecting the upper limbs. The presence of anti-GQ1b and anti-GT1a IgG antibodies supported an immune-mediated process. A diagnosis of GBS with overlapping MFS and PCB variants was established. The patient received a five-day course of intravenous immunoglobulin along with supportive management. Her neurological function gradually improved, with complete recovery noted at the three-month follow-up. This case highlights the importance of early recognition of overlapping GBS variants, especially in patients with cranial nerve and upper limb involvement. Greater clinical awareness and improved access to ganglioside antibody testing may facilitate earlier diagnosis and better outcomes. The coexistence of MFS and PCB variants also reinforces the concept of GBS as a spectrum disorder with shared underlying mechanisms.", "authors": ["Kumar Amit", "Garg Sandeep", "Bharti Praveen", "Zutshi Bhvika"], "journal": "Cureus", "entry_date": "2026/01/05 05:23", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41487841/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["General Medicine, Maulana Azad Medical College, New Delhi, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41487432", "title": "Methylprednisolone pulse versus docetaxel in recurrent thymoma with myasthenia gravis.", "abstract": "INTRODUCTION: This study aims to compare the effectiveness and safety of methylprednisolone pulse versus docetaxel in treating recurrent thymoma with myasthenia gravis (MG).\nMETHODS: We conducted a single-center, open-label, retrospective study that included 90 patients with thymoma recurrence accompanied by MG, who were treated with either methylprednisolone pulse or docetaxel. Compared the improvement rate of the Myasthenia Gravis Foundation of America Post-intervention Status (MGFA-PIS) and Quantitative Myasthenia Gravis Score (QMGS), changes in acetylcholine receptor antibodies (AchR-AB), and alterations in thymoma after treatment. Adverse events were also recorded.\nRESULTS: Both treatments significantly reduced QMGS and AchR-AB levels (p < 0.05). For MG, the overall effective rate (ORR1) was similar between groups (p > 0.05). However, the methylprednisolone group showed a higher objective response rate (ORR2) and disease control rate (DCR) for thymoma (p < 0.05). The incidence of adverse reaction incidence was 66.7% for the methylprednisolone group and 44.4% for the docetaxel group (p < 0.05).\nDISCUSSION: Methylprednisolone is more effective against thymoma than docetaxel for recurrent thymoma with MG, but has greater side effects. Docetaxel has similar MG efficacy compared to methylprednisolone, and with fewer side effects. The choice of treatment should be based on the patient's specific clinical situation.", "authors": ["Yang Hongxia", "Wang Yaxuan", "Pan Zulin", "Liu Ze", "Cheng Biqi", "Qi Guoyan"], "journal": "Frontiers in neurology", "entry_date": "2026/01/05 05:19", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41487432/", "pub_types": ["Journal Article"], "affiliations": ["Center of Treatment of Myasthenia Gravis, People's Hospital of Shijiazhuang Affiliated to Hebei Medical University, Shijiazhuang, Hebei, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41484314", "title": "Trends in thymectomy for myasthenia gravis in Japan: analysis of a nationwide surgical registry from 1996 to 2023.", "abstract": "", "authors": ["Nakajima Jun"], "journal": "General thoracic and cardiovascular surgery", "entry_date": "2026/01/04 00:09", "pub_date": "2026-01-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41484314/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, The University of Tokyo Graduate School of Medicine, Bunkyo-ku, Tokyo, Japan. nakajimatky@gmail.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41483344", "title": "Urinary dysfunction in myasthenia Gravis: a cross-sectional case-control study.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a disorder of neuromuscular transmission that primarily affects skeletal muscles, leading to cranial, truncal, and limb weakness. While motor symptoms are well documented, the prevalence and clinical significance of urinary dysfunction particularly urinary incontinence (UI) and overactive bladder (OAB) symptoms remain underexplored in MG, with previous reports limited to small cohorts.\nMETHODS: In this study, 86 MG patients and 90 age- and sex-matched inpatient controls were evaluated. All participants completed the International Consultation on Incontinence Questionnaire-Short Form (ICIQ-UI SF) and the Overactive Bladder Symptom Score (OABSS). MG severity was assessed using the Myasthenia Gravis Activities of Daily Living (MG-ADL) scale. MG patients were further categorized into early-onset (EOMG), late-onset (LOMG), and very late-onset (VLOMG) subgroups. Logistic regression identified predictors of UI, and Kaplan–Meier analysis was used to evaluate time to first UI symptoms.\nRESULTS: MG patients had significantly higher prevalence of UI symptoms (ICIQ-UI SF ≥ 6 in 52.3% vs. 12.2% in controls; p < 0.001). LOMG patients exhibited the highest UI prevalence (63.2%) and progressed most rapidly to UI, while EOMG patients had the latest onset. OAB symptoms were also more prominent in MG, marked by higher OABSS and increased urgency. MG-ADL score independently predicted UI (OR 2.38; 95% CI 1.04–5.46; p = 0.041).\nDISCUSSION: UI and OAB symptoms are more common in MG patients than in controls. MG-ADL score is an independent predictor of UI, and age at disease onset may influence the timing of UI development. Early identification and intervention may improve patient outcomes.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1007/s10072-025-08588-8.", "authors": ["Shihada Kamel", "Gorenshtein Alon", "Wolfe Gil I", "Shelly Shahar"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2026/01/03 11:28", "pub_date": "2026-01-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41483344/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Rambam Medical Center, Haifa, Israel. sh2000.kamel@gmail.com."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41483096", "title": "Telitacicept as a New Therapeutic Avenue for Generalized Myasthenia Gravis and Thymoma-Associated Myasthenia Gravis.", "abstract": "Generalized myasthenia gravis (gMG) is an antibody mediated autoimmune neuromuscular junction disorder characterized by muscle weakness and fatigue as well as acetylcholine receptor antibody (AChR-Ab) as the main presence. A proportion of patients fail to achieve minimal symptom expression (MSE), furthermore 10-20% of them develop into refractory under conventional immunotherapy. We conducted a retrospective study to explore the effectiveness and safety of telitacicept in gMG and thymoma-associated MG (TAMG) patients. The treatment response was assessed by the variation of QMG, MG-ADL and MG-QOL-15 scores. Time to MSE as well as usage of corticosteroid were also evaluated. In this retrospective study, we included 22 AChR-gMG patients (15 women, 7 men), including 7 refractory and 12 TAMG, who were treated with telitacicept by following-up at least 6 months. Compared to the baseline, a significant decrease in QMG, ADL and MG-QOL-15 scores was observed at every visit, especially for the QMG score with at least 3 points decline in all the patients in week 4. Twenty patients attained MSE and the time to MSE was 4 months during the observed period. At the last follow-up, the dose of prednisone of all the patients treated with telitacicept was ≤ 5 mg/d. The AChR-Ab titers and CD19+ B cells significantly decreased from baseline to week 24. Telitacicept is generally well tolerated, the most common (18%) adverse effect was mild and transient injected site swelling. Our study provides evidence to support that telitacicept is beneficial and well tolerated in the management of gMG especially in refractory MG and TAMG. Clinical outcomes showed increased efficacy of telitacicept when used earlier in the disease course, which leads to a sparing of prednisone.", "authors": ["Zhu Ying", "Wang Benqiao", "Hu Chunxiang", "Zhu Ruixia"], "journal": "Journal of neuroimmune pharmacology : the official journal of the Society on NeuroImmune Pharmacology", "entry_date": "2026/01/03 11:09", "pub_date": "2026-01-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41483096/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of China Medical University, NO. 155 Nanjing Bei Street, Heping District, Shenyang, 110001, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "41481736", "title": "BCMA/CD19 CAR T cell therapy for refractory myasthenia gravis: Proteomic signatures and single-cell transcriptomics of disease flares.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder characterized by B cell dysfunction. Here, we designed B cell maturation antigen (BCMA)/CD19 chimeric antigen receptor T cell (CAR T cell) therapy for six refractory MGs, demonstrating favorable safety with grade 1 cytokine release syndrome observed. CAR T cell expansion induced profound B cell depletion, a sustained reduction in acetylcholine receptor (AChR) antibody titers, and symptom improvement. Five patients achieved drug-free remission with minimal manifestations by month 6, persisting through the 12-month follow-up despite B cell reconstitution. Reconstituted B cells showed naïve predominance with diminished AChR specificity and functional capacities. Olink proteomics revealed up-regulation of anti-inflammatory factors, along with down-regulation of proinflammatory molecules. Single-cell sequencing revealed that age-associated B cells (ABCs) were up-regulated in a relapsed patient, and differential gene analysis indicated that Fc receptor-like 5 (FCRL5) expression was elevated in ABCs, whereas CAR T cell responders exhibited a down-regulated trend. Notably, similar ABC expansion and FCRL5 up-regulation occurred in rituximab-relapsed patients. Our findings support BCMA/CD19 CAR T cell therapy as feasible, tolerable, and effective in MG, identifying FCRL5 as a previously unidentified target in relapse.", "authors": ["Huang Xiaoyu", "Zhang Zhouao", "Liu Dan", "Luo Tiancheng", "An Xueting", "Yang Mingjin", "Li Shengli", "Wang Gang", "Li Huizhong", "Cao Jiang", "Sun Zengtian", "Du Xue", "Wang Zhouyi", "Guo Xinyan", "Ma Tianyu", "Peng Deyou", "Qi Guoyan", "Zong Shenghua", "Ding Yanting", "Cui Guiyun", "Shi Ming", "Zheng Junnian", "Zhang Yong"], "journal": "Science advances", "entry_date": "2026/01/02 14:04", "pub_date": "2026-01-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41481736/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, Jiangsu, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 12.5, "journal_quartile": "1区"}, {"pmid": "41480886", "title": "Tocilizumab in immune checkpoint inhibitor-induced myositis, myocarditis, and myasthenic syndrome: a rare case report and review of the literature.", "abstract": "Immune-related adverse events (irAEs) associated with immune checkpoint inhibitors (ICI) are becoming more frequent with the growing use of these agents in routine clinical oncology. This mechanism enhances the anti-tumor immune response, increasing the risk of activating autoreactive T cells, and leading to immune-mediated manifestations. The spectrum of these manifestations is widely variable. ICI-associated myositis is among the most severe irAEs, being a rare but serious complication with significant morbidity and mortality, particularly when accompanied by myocarditis and/or myasthenic crisis, which can all occur concurrently and worsen clinical outcomes. We report the case of a 78-years-old man with metastatic colon adenocarcinoma who developed ICI-associated myositis with concomitant myocarditis and myasthenic syndrome. In the presented case, the use of tocilizumab, an anti-interleukin 6 (IL-6)-receptor monoclonal antibody, was effective in treating the myositis and myocarditis, but not the myasthenic component of this ICI-associated myositis.", "authors": ["Gonçalves Hugo", "Augusto Duarte", "Pereira Paulo", "Ferreira-Campinho Carla", "Correia Ana Margarida", "Ferreira Catarina", "Costa Emanuel", "Silva Joana Leite", "Ribeiro Ana Roxo", "Almeida Diogo Esperança"], "journal": "ARP rheumatology", "entry_date": "2026/01/02 07:43", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41480886/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Rheumatology, Hospital de Braga."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "41479743", "title": "Robotic subxiphoid surgical approach for mediastinal lesions: One-year experience.", "abstract": "BACKGROUND: Median sternotomy has been considered the gold standard approach for anterior mediastinal tumor resection. However, recent advances in video-assisted thoracoscopic surgery and robotic-assisted thoracoscopic surgery with carbon dioxide insufflation have allowed minimally invasive approaches even for large and locally invasive tumors of the upper-anterior mediastinum. The subxiphoid robotic optical approach is a recently developed technique for accessing the mediastinum. The trans-subxiphoid technique offers excellent exposure of the surgical field, reduces postoperative pain, facilitates specimen retrieval even for large tumors, and potentially improves early surgical outcomes.\nAIM: To evaluate the safety, feasibility, and outcomes of a robotic subxiphoid approach for the resecting of large/invasive mediastinal tumors.\nMETHODS: Between July 2024 and September 2025, 12 patients underwent subxiphoid robotic mediastinal resection. The diameter of the operated lesions ranged from 30 mm to 70 mm. A 3 cm subxiphoid incision was made at the subxiphoid level for GelPort placement, allowing for optical port access. Two operating ports were placed at the sixth intercostal space bilaterally. Carbon dioxide insufflations (8-10 mmHg) enlarged the surgical field, improving visualization of critical anatomical landmarks, such as the internal mammary arteries and phrenic nerves. This approach allowed complete resection of large or invasive tumors, preserving thoracic stability and reducing the risk of postoperative myasthenic crisis.\nRESULTS: The mean operating time was 170.2 minutes, and the median hospital stay was 3.5 days. No major postoperative complications occurred. Two conversions were necessary: One with a lateral robotic approach due to previous abdominal surgery, and one with a sternotomy for tumor invasion of the aortic arch. Histopathological analysis identified nine thymomas and one solitary fibrous tumor.\nCONCLUSION: Subxiphoid robotic approach is a safe, effective technique for extended thymectomy, fulfilling both oncological and myasthenia gravis surgical objectives.", "authors": ["Pardolesi Alessandro", "Ferrari Michele", "Leuzzi Giovanni", "Cioffi Ugo", "Cioffi Gerardo", "Solli Piergiorgio"], "journal": "World journal of clinical cases", "entry_date": "2026/01/02 04:38", "pub_date": "2025-12-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41479743/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Istituto Nazionale Tumori, Milan 20133, Lombardy, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.0, "journal_quartile": null}, {"pmid": "41477139", "title": "Treatment of Neurogenic Voice Disorders.", "abstract": "This overview serves as a foundational resource for clinicians caring for neurologically complex patients presenting with voice complaints. Neurogenic voice disorders are diverse in their clinical presentations and therapeutic approaches. A thorough medical history, including family history, detailed laryngeal examination, voice assessments, and neuroimaging, are imperative, as well as a multidisciplinary, collaborative approach with neurologists, speech language pathologists, and patient caregivers. Disorders such as amyotrophic lateral sclerosis (ALS), cerebrovascular accidents (strokes), Huntington's disease, myasthenia gravis (MG), Parkinson's disease (PD), and voice tremor should be understood by otolaryngologists. Each condition presents unique challenges and requires tailored treatment strategies ranging from supportive therapies and pharmacological interventions to surgery. Voice management techniques, including the use of botulinum toxin for hyperkinetic disorders and deep brain stimulation for refractory cases, are highlighted as promising interventions.", "authors": ["Syamal Mausumi"], "journal": "World journal of otorhinolaryngology - head and neck surgery", "entry_date": "2026/01/01 04:45", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41477139/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Philadelphia Voice & Airway Institute Philadelphia Pennsylvania USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "41476989", "title": "COVID-19-associated delayed-onset MuSK-positive myasthenia gravis presenting solely with respiratory failure: a case report.", "abstract": "BACKGROUND: Muscle-specific kinase (MuSK) myasthenia gravis is a rare autoimmune disorder of the neuromuscular junction that predominantly affects the bulbar and respiratory muscles. Although SARS-CoV-2 infection has been implicated as a precipitating factor, post-COVID-19 MuSK-MG remains exceedingly uncommon.\nCASE PRESENTATION: A 29-year-old woman with a six-year history of unexplained exertional dyspnea was hospitalised twice for acute hypercapnic respiratory failure. The first episode, five months earlier, was attributed to severe tricuspid regurgitation; the second occurred eight weeks after mild COVID-19 and was characterized by coma due to hypercapnic respiratory failure without parenchymal lung disease.\nDIAGNOSIS: Standard electrophysiology, neostigmine testing and acetylcholine-receptor antibodies (AChR-Ab) were negative. Given persistent ventilator dependence, MuSK antibodies (MuSK-Ab) were measured and found strongly positive.\nINTERVENTIONS: The patient underwent five plasma-exchange sessions, then received oral prednisone (50 mg day), tacrolimus (1.5 mg q12h) and nebulized salbutamol.\nOUTCOMES: She was weaned from non-invasive ventilation by day 23, discharged on day 27 (mMRC grade I) and remained stable on low-dose prednisone/tacrolimus at three-month follow-up.\nCONCLUSION: SARS-CoV-2 infection may plausibly act as a trigger for late-onset MuSK-MG presenting as isolated hypercapnic respiratory failure. In otherwise unexplained weaning failure, neuromuscular-junction disease should be considered even without limb or ocular weakness. Early antibody testing and prompt immunomodulatory therapy [plasma exchange (PLEX) plus glucocorticoid/tacrolimus] may be life-saving and yield rapid recovery.", "authors": ["Cao Xiao-Guang", "Ni Jun-Xi", "Zhu Xiong-Feng", "Meng Hua-Dong", "Huang Chong-Jian"], "journal": "Frontiers in immunology", "entry_date": "2026/01/01 04:42", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41476989/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Emergency Medical Center, The First Affiliated Hospital of University of Science and Technology of China (Anhui Provincial Hospital), Hefei, Anhui, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41476025", "title": "Add-On Telitacicept Significantly Improves Outcome of Patients With Refractory Ocular Myasthenia Gravis a Real-World Case Series.", "abstract": "INTRODUCTION: Refractory ocular myasthenia gravis (MG) represents a significant therapeutic challenge, as conventional immunotherapies often prove ineffective. Telitacicept, a recombinant B-lymphocyte stimulator receptor-antibody fusion protein, offers a novel immunomodulatory approach. This retrospective study evaluates its efficacy and safety in patients with MG-associated refractory ocular symptoms.\nMETHODS: This is a single-center retrospective cohort study. evaluated patients with refractory ocular symptoms who received telitacicept weekly between August 2024 and January 2025. We evaluated treatment efficacy using Myasthenia Gravis Foundation of America post-intervention status (MGFA-PIS), Myasthenia Gravis Impairment Index-patient-reported outcome (MGII-PRO), quantitative MG (QMG), and MG activity of daily living (ADL) scores, as well as the reduction in daily prednisone dosage at baseline and each month following treatment. The safety assessment was also evaluated.\nRESULTS: Seven MGFA class 1 patients (5 females, 2 males) were enrolled, with a median onset age of 6 years (interquartile range [IQR] 2-21) and a median disease duration of 98 months (IQR 46-121). MG-ADL scores showed significant reduction with prolonged follow-up. 6/7 patients achieved ≥2-point MG-ADL improvement by the third follow-up. 4/6 patients reached minimal symptom expression at the fifth follow-up. The average ocular MG-ADL, MGII-PRO, and QMG scores revealed statistically significant improvements at the third month of follow-up, sustained through the sixth month. The regimen exhibited excellent tolerability, with no severe adverse events (e.g., hypersensitivity reactions, infections) reported.\nCONCLUSION: Our preliminary findings indicate that telitacicept represents a promising and well-tolerated adjunct therapy for refractory ocular symptoms in MG, providing significant clinical evidence to support this novel therapeutic approach.", "authors": ["Lin Jing", "Li Yue", "Gui Mengcui", "Bu Bitao", "Li Zhijun"], "journal": "Brain and behavior", "entry_date": "2025/12/31 22:33", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41476025/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, Hubei, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41473789", "title": "Bulbar Manifestation of Myasthenia Gravis Initially Attributed to Goiter: A Case Report.", "abstract": "", "authors": ["El Zoert Zeina", "Howeiss Pamela", "El Lakis Mustapha", "Hazimeh Yusef"], "journal": "OTO open", "entry_date": "2025/12/31 04:58", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41473789/", "pub_types": ["Journal Article"], "affiliations": ["Faculty of Medicine American University of Beirut Beirut Lebanon."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "41473438", "title": "Case Report: Fatal myocarditis and myasthenia gravis induced by immune checkpoint inhibitors: concurrent dual adverse events in an older adult.", "abstract": "Immune checkpoint inhibitors (ICIs) have revolutionized the treatment of metastatic renal cell carcinoma (RCC), offering significant survival benefits. Their use, however, can come at the expense of severe immune-related adverse events (irAEs) involving the myocardium and nervous system. We report an 86-year-old male with relapsed clear cell RCC (Fuhrman grade 3, pT3aN0M0) who developed concurrent myocarditis and myasthenia gravis (MG) after receiving Pembrolizumab and Axitinib for multifocal mediastinal relapse. Despite early initiation of high-dose IV methylprednisolone within 24 hours, the patient's condition deteriorated rapidly, resulting in pneumonia, acute kidney injury requiring hemodialysis, and death. This case highlights the fulminant course of ICI-induced myocarditis and MG, underscoring the importance of prompt recognition, immediate initiation of corticosteroids and IV immunoglobulin, and early consideration of second-line immunomodulatory therapies in severe cases.", "authors": ["Fakhreddine Omar", "Assaad Wassim", "El Meski Nour", "Kreidieh Firas", "Alam Samir", "Khoury Maurice"], "journal": "Frontiers in oncology", "entry_date": "2025/12/31 04:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41473438/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Division of Cardiology, Department of Internal Medicine, American University of Beirut Medical Center, Beirut, Lebanon."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "41470000", "title": "CAR T cells as novel therapeutic strategy for multiple sclerosis and other neuroimmune disorders.", "abstract": "Chimeric antigen receptor (CAR) T-cell therapy is rapidly emerging as a transformative approach for treating multiple sclerosis (MS) and other neuroimmune disorders such as neuromyelitis optica spectrum disorder (NMOSD), myelin oligodendrocyte glycoprotein antibody-associated disease (MOGAD), and myasthenia gravis (MG), alongside several other rare neuroimmunological conditions currently being evaluated in compassionate-use or early-phase studies. These conditions are driven in part by autoreactive B cells that sustain chronic inflammation and progressive tissue damage. While current immunomodulatory therapies have improved clinical outcomes, they often require lifelong administration and fail to effectively eliminate compartmentalized inflammation within the central nervous system. Recent advances in CD19- and BCMA-directed CAR T-cell therapy, initially developed for hematologic malignancies, demonstrate the potential to achieve targeted, durable B-cell depletion and immune reprogramming in autoimmune diseases. Preclinical models and early-phase clinical trials have shown promising efficacy, including reduced relapse rates, stabilization of disability progression, and decreased autoantibody levels, alongside a favorable safety profile with lower rates of high-grade cytokine release syndrome (CRS) and immune effector cell-associated neurotoxicity syndrome (ICANS) compared to oncologic applications. This review synthesizes the current evidence supporting the use of CAR T-cell therapy in neuroinflammatory diseases and explores its potential to redefine treatment paradigms by shifting from chronic immunosuppression to long-term immune tolerance, creating a favorable environment for repair mechanisms. Realizing the full therapeutic promise of CAR T-cells in autoimmune neurology will require sustained research in heterogeneous populations and across disease spectrums.", "authors": ["Samadzadeh Sara", "Szejko Natalia", "Hamadah Yara", "Tan Wan Ying", "Gluscevic Sanja", "Boldrini Vinícius", "Ricigliano Vito A G", "Hartung Hans-Peter", "Montalban Xavier"], "journal": "Journal of neuroinflammation", "entry_date": "2025/12/31 00:29", "pub_date": "2025-12-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41470000/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Experimental and Clinical Research Center, Charité-Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt- Universität zu Berlin, Berlin, 12203, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 10.1, "journal_quartile": "1区"}, {"pmid": "41467263", "title": "A Case of Anti-MuSK Antibody-positive Myasthenia Gravis Presenting as Limb-Girdle Muscle Atrophy.", "abstract": "To diagnose a case anti-MuSK myasthenia gravis (anti-MuSK MG) is always a challenge in view of a distinct clinical phenotype that differs from typical MG (anti-acetylcholine receptors (antibody positive). We herein report a case of anti-MuSK MG, whose history and clinical phenotype differ from typical MG and are more suggestive of myopathy or anterior horn cell disease. Therefore, testing anti-MuSK antibody is very important if there is suspicion of anti-MuSK MG.", "authors": ["Dhing Hemanga Kumar", "Hussain Masaraf", "Nath Prabal"], "journal": "Acta neurologica Taiwanica", "entry_date": "2025/12/30 04:26", "pub_date": "2025-10-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41467263/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, All India Institute of Medical Sciences, Guwahati, Assam, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41466846", "title": "Shaping the role of plasma exchange in autoimmune neurology: lessons learned from 67 years and over 90,000 procedures.", "abstract": "Therapeutic plasma exchange (PLEX) is a powerful and fast-acting immunomodulating therapy that is underutilized for autoimmune neurological disorders. Here, we present the largest collection of real-world experiences with PLEX procedures to date in the treatment of autoimmune neurological conditions, supporting its safety and clinical benefits with patient cases and corresponding patient videos. Our collective real-world experience with PLEX spans over 67 years, 90,210 procedures, and includes nine double-blind randomized controlled and unblinded studies serving as principal investigators. Case histories and videos of our patients demonstrate when and how PLEX should be used, identify barriers to using PLEX, and ways to overcome these barriers. Specific protocol details are shared of how to treat an acute or chronic phase of a disease. If used appropriately and early in the disease course for both acute and chronic progressive phases, PLEX can safely change the trajectory of many autoimmune neurological disorders in both outpatient and inpatient settings.\nWhat is plasma exchange (PLEX)? PLEX is a procedure that removes and replaces plasma to eliminate harmful antibodies and immune factors in autoimmune and neurological diseases. It can work quickly and does not suppress or deplete the immune system. What did we look at? Our team combined real-world experience from our three centers, over nearly seven decades, including more than 90,000 PLEX procedures in 2,625 people with autoimmune neurological conditions. Most treatments (~89%) were safely treated in the outpatient setting. Who may benefit? We use PLEX for several conditions. Certain clues suggest a higher chance of improvement, such as being younger, having a shorter disease duration, and MRI scans showing active or ring-enhancing lesions. Is PLEX safe? We did not see any major complications caused by PLEX, including in the very young, very old, and critically ill patients. The most common issue was temporary low blood pressure during the procedure, which was easy to treat. Problems are far more likely when permanent central lines are used; we recommend peripheral veins and (when needed) short-term, temporary radial-artery access instead. Why isn’t PLEX used more often? Many people who could benefit do not receive PLEX because of insurance denials, limited local access to the procedure, uncertainty about the “right” protocol, and misunderstandings about safety. How does PLEX compare with treatments? PLEX is often less expensive than many biologic drugs used in these conditions. For example, one PLEX session at our center cost about $5,000 in 2021, compared with much higher per-infusion charges for some biologics. What’s the takeaway? Used early and appropriately and continued as maintenance, PLEX can change the course of autoimmune neurological diseases for many patients, with a safety record that supports outpatient care. It acts fast, avoids long-term immune suppression, and can be tailored to the individual.", "authors": ["Khatri Bhupendra O", "Berkovich Regina", "Raval Jay S", "Dukic Mary", "Sershon Lisa"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/12/30 04:17", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41466846/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Ascension Health Wisconsin, Center for Neurological Disorders, Milwaukee, WI, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41466387", "title": "The Case of a 28-Year-Old Man With Gradually Progressive Proximal Leg Weakness.", "abstract": "This is a case of a 28-year-old man who presented with a 6-month history of gradually progressive proximal leg weakness and pain that worsened on exercise and was relieved by rest. He had no symptoms in his upper limbs. Apart from intermittent mild ptosis and diplopia, he had no other cranial nerve symptoms. Sensation, bladder, and bowel function were normal. His examination revealed fatigable ptosis and diplopia with a positive ice-pack test. His motor examination showed mild fatigable hip flexion weakness and hyporeflexia that recovered on brief exercise. Electrophysiologic studies revealed small motor nerve amplitudes that improved with brief exercise, and a significant decrement on slow repetitive nerve stimulation. He had a positive anti-VGCC antibody. The clinical, electrophysiological, and antibody findings supported a diagnosis of Lambert Eaton Myasthenic syndrome (LEMS). LEMS commonly presents as a paraneoplastic syndrome associated with small cell lung cancer in older male smokers. However, some forms are primarily autoimmune, as was the case in our patient.", "authors": ["Asukile Melody T", "Kapapa Musambo", "Mwingila Emelda", "Kvalsund Michelle"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/12/30 02:46", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41466387/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Internal Medicine, School of Medicine, University of Zambia, Lusaka, Zambia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41462987", "title": "Efgartigimod for Generalized Myasthenia Gravis and Beyond: A Narrative Review of Its Pharmacological Profile, Clinical Utility, and Expanding Applications.", "abstract": "Efgartigimod is a novel neonatal Fc receptor (FcRn) antagonist that reduces pathogenic immunoglobulin G (IgG) autoantibodies, offering a targeted therapeutic approach for generalized myasthenia gravis (gMG) and other antibody-mediated autoimmune diseases. This narrative review synthesizes clinical trial data, pharmacological insights, and real-world evidence to evaluate efgartigimod's efficacy, safety, and emerging applications. Phase 3 randomized controlled trials and extension studies demonstrate rapid and sustained improvements in muscle strength and patient-reported outcomes with a favorable safety profile, including reduced reliance on corticosteroids and intravenous immunoglobulin (IVIg). Additionally, observational studies highlight its expanding utility in diverse IgG-mediated disorders such as immune thrombocytopenia (ITP) and autoimmune encephalitis. Efgartigimod thus represents a paradigm shift in autoimmune disease management, enabling precision immunomodulation with the potential for broad clinical impact and improved patient quality of life (QOL).", "authors": ["Mansour Ghaith K", "Alangari Leen", "Khosyfan Leen", "Alhammad Reem", "Hajjar Ahmad W"], "journal": "Biomedicines", "entry_date": "2025/12/30 01:41", "pub_date": "2025-12-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41462987/", "pub_types": ["Journal Article", "Review"], "affiliations": ["College of Pharmacy, Alfaisal University, Riyadh 11533, Saudi Arabia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41462932", "title": "Bridging the Heterogeneity of Myasthenia Gravis Scores as a Foundational Step Towards the Construction of a Digital Twin.", "abstract": "Background/Objectives: Myasthenia gravis (MG) is a rare autoimmune neuromuscular disease. Clinical trials with rigorously collected data provide valuable opportunities for mathematical modeling of patient outcomes over time. However, for rare diseases such as MG, combining data across multiple trials presents challenges due to heterogeneity in outcome measures. This study aims to address these challenges by investigating relationships among commonly used MG outcome measures to support the development of a standardized \"Myasthenia Gravis Portrait.\" Methods: We integrated three primary data types from multiple clinical studies: (i) laboratory and medication data, (ii) Electronic Health Record (EHR) data (e.g., age, sex, years since diagnosis, BMI), and (iii) disease severity scores. We examined the relationships among several MG-specific scoring systems, including Activities of Daily Living (MG-ADL), Quantitative Myasthenia Gravis (QMG), MG Composite (MG-CE), and MG Quality of Life-15 (MGQOL-15), to evaluate consistency and comparability across studies. Results: Preliminary analyses revealed variable correlations among the different scoring systems, indicating that, while some measures capture overlapping aspects of disease progression, others reflect distinct patient- or clinician-centered perspectives. These findings highlight the need for a harmonized framework that captures both functional and clinical dimensions of MG severity. Conclusions: The proposed \"Myasthenia Gravis Portrait\" provides a standardized approach for representing patient outcomes across diverse clinical datasets. This framework will facilitate the creation of virtual populations of digital twins, enabling a machine-learning-based modeling of MG progression and prediction of individualized disease trajectories.", "authors": ["Garbey Marc", "Lesport Quentin", "Kaminski Henry J"], "journal": "Biomedicines", "entry_date": "2025/12/30 01:41", "pub_date": "2025-11-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41462932/", "pub_types": ["Journal Article"], "affiliations": ["Care Constitution Corp., Houston, TX 77057, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41458125", "title": "Humanistic burden and medical care patterns of real-world patients with myasthenia gravis in Japan.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a rare autoimmune disease characterized by skeletal muscle weakness. As limited real-world data are available in Japan, we aimed to describe the humanistic burden of disease (primary aim), mainly with regards to health-related quality of life (HRQoL), and treatment patterns (secondary aim) in patients with generalized MG (gMG).\nMETHODS: Data were drawn from the Adelphi Real World MG Disease Specific Programme™, a cross-sectional survey of neurologists and their patients in Japan from August 2023 and January 2024. Analyses were descriptive.\nRESULTS: Overall, 40 neurologists reported data for 128 patients, where 29 patients had self-reported data. Mean (standard deviation) patient age was 57.9 (16.0) years and 53.9% were female. At data collection, 98.4% of patients were receiving maintenance therapy (including novel treatments). Nonsteroidal immunosuppressant therapies were used at first-line of therapy in 54.5% of cases (n = 67/123). Oral systemic steroids were most used [78.0% of patients at first-line (n = 96/123), 77.9% at second-line (n = 53/68), and 75.0% at third-line (n = 15/20)]. The median (IQR) duration from symptom onset to diagnosis was 2.0 (0.9-4.3) months. Of 28 patients with EQ-5D-5L data, 46.4% reported difficulties with usual activities, 42.9% with mobility, 21.4% with self-care, 53.6% with pain/discomfort, and 39.3% with anxiety/depression.\nCONCLUSION: Most patients in this Japanese cohort with gMG received maintenance therapy and the time from symptom onset to diagnosis was relatively short. However, impaired HRQoL remained.", "authors": ["Kasahara-Kiritani Mami", "Saga Yosuke", "Watanabe Sayuri", "Webb Thomas", "Herr Keira", "Yu DaeYoung", "Ringland Ciara", "Birija Shiva Lauretta", "Conyers Joe", "Gibson Gregor", "Hatchell Niall", "Li Nan"], "journal": "Frontiers in neurology", "entry_date": "2025/12/29 05:07", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41458125/", "pub_types": ["Journal Article"], "affiliations": ["Integrated Market Access Division, Johnson & Johnson, Tokyo, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41456989", "title": "Autoimmune disorders as predictive factors for oral lichen planus and malignancy risk: real-world data analysis.", "abstract": "OBJECTIVE: Oral lichen planus (OLP) is a T-cell-mediated mucosal disorder with malignant potential and ∼1% prevalence. Its associations with autoimmune diseases and oral squamous cell carcinoma (OSCC), especially among smokers, remain unclear. This study quantified OLP prevalence across 17 autoimmune disorders and evaluated OSCC risk in these cohorts.\nMETHODS: Data from TriNetX research network were analyzed in a retrospective cohort of adults ≥18 years. Patients with one of 17 autoimmune diseases were identified via ICD-10 codes and compared to nonautoimmune controls. OLP prevalence and risk were estimated using 1:1 age- and sex-matched propensity score matching. OSCC risk in autoimmune and OLP patients was assessed via ICD-O/ICD-10 codes, and tobacco impact was evaluated.\nRESULTS: In 4,480,330 patients with autoimmune disorders, OLP prevalence was 2.04%, ranging from 1.19% in multiple sclerosis to 4.57% in Sjögren's. OLP risk was significantly elevated in 13 conditions (OR = 1.06-2.44; P < .05), nonsignificant for scleroderma, myasthenia gravis, and Hashimoto, and inversely associated with multiple sclerosis (OR = 0.78; P < .0001). OSCC risk was 1.39%, with ORs of 15.93 overall and 23.6 in smokers with autoimmune disorders and OLP (P < .0001).\nCONCLUSIONS: Autoimmune interactions in OLP are complex, with robust associations in Sjögren's, vasculitis, Addison's, and intriguing multiple sclerosis protection. The markedly elevated risk of OSCC in patients with autoimmune disease and OLP highlights the need for integrated screening protocols and patient education.", "authors": ["Owosho Adepitan A", "Oyewole Stella O"], "journal": "Oral surgery, oral medicine, oral pathology and oral radiology", "entry_date": "2025/12/28 21:57", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41456989/", "pub_types": ["Journal Article"], "affiliations": ["Oral Medicine, Dental Oncology and Urgent Care Unit, Missouri School of Dentistry and Oral Health, A.T. Still University, Kirksville, MO, USA; The Robert Ebert and Greg Stubblefield Head and Neck Tumor Center, Barnes-Jewish Hospital and Washington University School of Medicine, St. Louis, MO, USA. Electronic address: adepitanowosho@atsu.edu."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "41455493", "title": "Plasma miR-150-5p as a biomarker for immunosuppressive therapy response in acetylcholine receptor positive myasthenia gravis: a long-term prospective longitudinal study.", "abstract": "Insufficient effectiveness and adverse effects of immunosuppressive therapy, seen in around 20 % of acetylcholine receptor (AChR) positive myasthenia gravis (MG) patients, highlight the need for new biomarkers. MicroRNAs (miRNAs), small regulatory non-coding RNAs with tissue-specific expression, have emerged as potential biomarkers due to their abundance and accessibility in body fluids. Several miRNAs involved in immune system and drug metabolism have been associated with improvement of neuromuscular status or response to immunosuppressive therapy in AChR-positive MG patients in cross-sectional studies. Here, we explored miRNAs as plasma biomarkers for immunosuppressive therapy response in a prospective longitudinal study of newly diagnosed, drug-naïve patients. Clinical examination and plasma sampling were performed at three time points: baseline (pre-treatment), 6-month, and 12-month follow-ups. MiRNA levels were quantified by qPCR. Three out of eight analyzed miRNAs (miR-150-5p, miR-27a-3p, and miR-21-5p) showed treatment-related changes. Among them, miR-150-5p level was negatively correlated with patient functionality (MG Activities of Daily Living score - MG-ADL; p = 0.007, ρs=-0.433), muscle strength and weakness (Quantitative MG score - QMG; p = 0.002, ρs=-0.355) and overall symptoms (MG Composite score - MGC; p = 7.814e-5, ρs=-0.457). Pre-treatment miR-150-5p levels showed excellent prognostic ability to discriminate responders from not-responders based on achieved minimal clinical expression (AUC=0.85, p = 0.0076) and MG-ADL (AUC=0.86, p = 0.016) at 12-month follow-up. Predictive performance was also acceptable based on QMG and MGC (AUC=0.74, p = 0.001 and AUC=0.73, p = 0.0002, respectively). Our findings imply plasma miR-150-5p as a potential biomarker for predicting immunosuppressive therapy response in AChR-positive MG, suggesting its further investigation for disease monitoring and a personalized medicine approach.", "authors": ["Garai Nemanja", "Madic Sanja", "Ivanovic Vukan", "Palibrk Aleksa", "Pesovic Jovan", "Brkusanin Milos", "Basta Ivana", "Peric Stojan", "Savic-Pavicevic Dusanka"], "journal": "Pharmacological research", "entry_date": "2025/12/27 19:23", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41455493/", "pub_types": ["Journal Article"], "affiliations": ["University of Belgrade, Faculty of Biology, Center for Human Molecular Genetics, Studentski trg 16, Belgrade 11158, Serbia."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 17.3, "journal_quartile": "1区"}, {"pmid": "41455461", "title": "Serological testing patterns among individuals newly diagnosed with myasthenia gravis.", "abstract": "Serologic antibody testing supports myasthenia gravis (MG) diagnosis and informs appropriate treatment. The research objective was to evaluate real-world MG serostatus testing patterns in the United States. Using insurance claims linked to serological test results, a retrospective, observational cohort study was conducted among adults with newly diagnosed MG between 01-January-2018 and 30-June-2022. Serostatus tests included acetylcholine receptor (anti-AChR), muscle-specific kinase (anti-MuSK), and low-density lipoprotein receptor-related protein 4 (anti-LRP4) antibodies. Of 5788 cases, 2590 (44.7 %) had at least one valid serology test result: 1453 (56.3 %) seronegative, 1094 (42.4 %) anti-AChR+, 28 (1.1 %) anti-MuSK+, and 5 (0.2 %) anti-LRP4+. Among the seronegative, 56.6 % were only tested for anti-AChR antibodies, 33.7 % tested both anti-AChR and anti-MuSK antibodies, and 5.0 % tested all three antibodies. Of the seronegative and untested populations, 40.9 % and 37.4 % initiated ≥2 unique MG treatments, with 699 (69.4 %) and 1267 (64.7 %) initiating acetylcholinesterase inhibitor. Factors associated with a higher likelihood of obtaining serologic testing included diagnosis by neurology, presence of MG-associated symptoms, residence in large metropolitan areas, fewer comorbidities, and Medicare insurance (vs. commercial or Medicaid). Variation in MG serologic testing, including infrequent MuSK and LRP4 autoantibody testing among seronegative patients, highlights a potential need to promote best practices in patient care.", "authors": ["Pesa Jacqueline A", "Liberman Joshua N", "Darer Jonathan D", "Xiaoyun Yang", "Jackson Louis A", "Artem Sergenyenko", "Nolan Campbell", "Nowak Richard J"], "journal": "Journal of the neurological sciences", "entry_date": "2025/12/27 18:11", "pub_date": "2026-01-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41455461/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Johnson & Johnson Innovative Medicine, 1125 Trenton Harbourton Rd, Titusville, NJ 08560, United States of America."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41454201", "title": "Muscle expression of PD1 and PD-L1 may predict the severity and outcomes of neuromuscular immune-related adverse events caused by immune checkpoint inhibitor treatment.", "abstract": "OBJECTIVES: Immune-related adverse events (irAEs) affecting the nervous system, particularly neuromuscular disorders, are severe complications of immune checkpoint inhibitors. However, reports with neuromuscular pathology evidence remain scarce.\nMETHOD: We characterized the clinicopathologic features of a retrospective cohort of 42 patients with neuromuscular irAEs. Immunohistochemical analysis of CD3, CD4, CD8, CD20, CD68, programmed cell death protein 1 (PD-1), programmed death ligand 1 (PD-L1), and programmed death ligand 2 (PD-L2) expression was performed on muscle and/or nerve biopsies from 25 patients. Additionally, immunotherapy responses and clinical outcomes were followed up for prognostic analysis.\nRESULTS: The 42 patients had diagnoses including myositis (n = 21), peripheral neuropathy (n = 6), myasthenia gravis (n = 1), and overlapping syndromes (n = 14). The most prevalent clinical presentations were fatigue (54.8%), ptosis (52.4%), and proximal muscle weakness (52.4%). Muscle pathology exhibited a characteristic pattern of focal necrosis and inflammation with lymphocyte infiltration. PD-1 and PD-L1 were highly expressed on T lymphocytes and myofibers, and their expression was most frequently observed in the group with Common Terminology Criteria for Adverse Events grades 3-5. After follow-up for 3 to 26 months, during which immunotherapy was administered, 53.8% of patients achieved a good outcome (either complete recovery or a ≥ 2-point reduction in modified Rankin Scale score). PD-L1 (P = 0.046) and PD-L2 (P = 0.046) expression were more likely in patients with good outcomes.\nCONCLUSIONS: The muscle pathology of neuromuscular irAEs featured focal necrosis and elevated PD-1 and PD-L1 expression on T lymphocytes and myofibers. PD-1, PD-L1, and PD-L2 expression may be associated with neuromuscular irAE severity and outcomes. Key Points • The muscle pathology of neuromuscular immune-related adverse events includes elevated PD-1 and PD-L1 expression on infiltrating T lymphocytes and muscle fibers. • PD-1, PD-L1, and PD-L2 expression are potential biomarkers for the severity and outcome of neuromuscular immune-related adverse events.", "authors": ["Yang Mengting", "Li Fan", "Chen Zhaoyu", "Gao Feng", "Zhang Wei", "Wang Zhaoxia", "Yuan Yun", "Zhao Yawen"], "journal": "Clinical rheumatology", "entry_date": "2025/12/26 23:20", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41454201/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking University First Hospital, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41452548", "title": "It's you it's about! Exploring existential aspects on quality of life with myasthenia gravis.", "abstract": "This article is grounded in a phenomenological and autoethnographic approach, with the neurologist's remark, It's you it's about!, serving as an existential starting point. The aim of this text is to explore quality of life as an existential challenge and opportunity when living with the chronic illness myasthenia gravis, drawing on lived experience and existential philosophy. Through three existential anecdotes based on the first author's experiences with myasthenia gravis, the tension between the body's limitations and the patient's desire to continue living meaningfully, as well as the role of the clinician in supporting the patient's process, is illuminated. Each anecdote is followed by a philosophical reflection - from glimpse to resonance - which deepens the exploration of the complex dimensions of quality of life. The article examines key themes such as; Running, existential positioning, and holding on to quality of life; The stoic trust that sustains a patient's quality of life; and The restoration of clarity and direction for quality of life - one that is not measured, but felt, held, and sustained in relation. By exploring these dimensions, the article proposes a shift from traditional, measurable outcomes to a broader understanding of quality of life that transcends physical symptoms.", "authors": ["Missel Malene", "Witting Nanna"], "journal": "Medicine, health care, and philosophy", "entry_date": "2025/12/26 11:17", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41452548/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cardiothoracic surgery, Copenhagen University Hospital - Rigshospitalet, Blegdamsvej 9, 2100, Copenhagen, Denmark. malene.missel@regionh.dk."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "1区"}, {"pmid": "41452401", "title": "B cell targeted CAR-T therapy for autoimmune diseases.", "abstract": "Chimeric antigen receptor T (CAR-T) cells demonstrate remarkable effectiveness in targeting and eliminating pathogenic B-cell lineages, showing significant specificity and efficacy against B cell malignancies. In addition, CAR-T cell-mediated B cell depletion and resetting, which showed great potential in treating autoimmune diseases, thereby extending the clinical applicability of adoptive cell therapy. In this review, we examine the progression of CAR-T targeted B cell therapy for autoimmune diseases, encompassing the development of new therapeutic strategies and reports on related clinical outcomes. Furthermore, the article delves into the challenges and potential avenues for enhancement related to the safety aspects and inherent limitations of current technological solutions.", "authors": ["Li Qi", "Zhao Ning", "Hou Ruitao", "Qin Juliang", "Zhang Jiqin", "Liu Mingyao", "Du Bing"], "journal": "Frontiers of medicine", "entry_date": "2025/12/26 11:06", "pub_date": "2025-12-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41452401/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Shanghai Frontiers Science Center of Genome Editing and Cell Therapy, Shanghai Key Laboratory of Regulatory Biology, Institute of Biomedical Sciences and School of Life Sciences, East China Normal University, Shanghai, 200241, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "41451993", "title": "Rituximab in the Intensive Care Unit: A Review of Indications and Clinical Considerations.", "abstract": "Rituximab, a chimeric monoclonal antibody targeting CD20 on B cells, has become an important therapeutic agent in the intensive care unit (ICU) for a range of immune-mediated conditions. This review explores the current indications, pharmacological rationale, and practical considerations for rituximab use in the ICU. Key indications include autoimmune haemolytic anaemia, thrombotic thrombocytopenic purpura, haemophagocytic lymphohistiocytosis, autoimmune encephalitis, myasthenia gravis, and ANCA-associated vasculitis. In these conditions, rituximab often serves as a second-line or salvage therapy, particularly when corticosteroids or conventional treatments fail. Its role in respiratory failure related to inflammatory myopathies, such as anti-synthetase and anti-MDA-5 syndromes, is emerging. While generally well-tolerated, rituximab carries risks of infusion reactions, infectious complications, hematologic toxicity, and rare organ-specific adverse events. Given the increasing use of rituximab across diverse critically ill populations, intensivists must be familiar with its indications, benefits, and risks to optimize patient outcomes.", "authors": ["Lincoln Marc", "McGimsey Thomas", "O'Driscoll David"], "journal": "Journal of intensive care medicine", "entry_date": "2025/12/26 07:43", "pub_date": "2025-12-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41451993/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department Anaesthesiology, Critical Care and Pain Medicine, Children's Hospital of Ireland Temple Street, Dublin, Ireland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "41449450", "title": "Antibody glycosylation in neuroimmune diseases.", "abstract": "BACKGROUND: Glycosylation, a critical post-translational modification of proteins, is particularly evident in immunoglobulins (Ig), also known as antibodies, and plays a significant role in various neuroimmune diseases. Of particular importance is the N-glycosylation of the crystallizable fragment (Fc) of IgG. It has a straightforward structure and directly impacts antibody effector functions, thus making it a focal point in antibody glycosylation studies.\nMETHODS: This review systematically summarizes characteristic IgG glycosylation patterns in neuroimmune disorders, including multiple sclerosis (MS), neuromyelitis optica spectrum disorders (NMOSD), Guillain–Barré syndrome (GBS), chronic inflammatory demyelinating polyradiculoneuropathies (CIDP), and myasthenia gravis (MG).\nRESULTS: A prevailing pattern of reduced IgG galactosylation, sialylation, and core fucosylation has been consistently observed across these diseases, and these alterations are intricately linked to a pro-inflammatory shift in antibody functionality. Beyond pathological mechanisms, this review further explores the potential clinical value of IgG glycosylation, emphasizing its applications as a biomarker and as a target for innovative therapeutic strategies, such as the design of engineered therapeutic monoclonal antibodies and the use of glycosidases.\nCONCLUSIONS: The specific alteration of IgG glycosylation is a hallmark of neuroimmune diseases, contributing to their pathogenesis and offering substantial translational promise. Harnessing this knowledge for the development of glycosylation-based diagnostics and therapeutics represents a significant frontier in the management of neuroimmune diseases.", "authors": ["Li Kailin", "Luo Mengchuan", "Xu Liqun", "Ouyang Yuzhen", "Zhou Qian", "Xiang Wei", "Ren Yijun", "Wen Zeyi", "Shi Guanzhong", "Luo Zhaohui", "Yang Huan"], "journal": "Journal of translational medicine", "entry_date": "2025/12/25 23:16", "pub_date": "2025-12-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41449450/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, 410008, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41442860", "title": "Challenges in myasthenia gravis diagnosis: an analysis of the diagnostic process of myasthenia gravis in a specialized clinic.", "abstract": "Diagnosis of MG can be complicated and consequent delays in diagnosis can lead to potentially life-threatening situations. We designed a retrospective, observational study to review the diagnostic process of patients with suspicion of MG in real-world practice, identifying pitfalls and the most common mimic entities. Of the 561 patients referred with suspected MG, it was ruled out in 167 (29 %). An alternative diagnosis was reached in 53.9 %, showing high heterogeneity among these entities. During the diagnostic process, the cornerstone was the clinical picture, and in 30 % of the mimic group no further studies were needed. Regarding antibodies, 7.9 % of patients in MG mimic group had a previous, positive anti-AChR determination, later confirmed as a false positive result. Up to 19 % of patients in the mimic group showed abnormalities in the single fiber electromyography. This study highlights the diagnostic challenge in patients with suspected MG, especially in seronegative cases. In these patients, it took a mean of >2 years to rule out MG, and up to 23 % of these patients received immunosuppressants during this process.", "authors": ["Vesperinas A", "Rocaspana-Codana J", "Reyes-Leiva D", "Caballero-Ávila M", "Carbayo Á", "Collet-Vidiella R", "Llansó L", "Gallardo E", "Turon-Sans J", "Rojas-García R", "Cortés-Vicente E"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2025/12/24 18:03", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41442860/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Neuromuscular Diseases Unit, Department of Neurology, Hospital de la Santa Creu i Sant Pau, Barcelona, Spain; Centro de Investigación Biomédica en Red de Enfermedades Raras (CIBERER), Madrid, Spain; Department of Medicine, Universitat Autonoma de Barcelona, Barcelona, Spain; Institut de Recerca - Hospital Santa Creu i Sant Pau, Barcelona, Spain."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41442252", "title": "Exploring psychosocial experiences in clinically stable generalised Myasthenia Gravis: A thematic analysis.", "abstract": "Myasthenia Gravis (MG) is a chronic autoimmune neuromuscular condition that significantly impacts patients' lives. Whilst psychosocial challenges are increasingly recognised as important in understanding the lived experience of patients, insight into these experiences during periods of clinical stability remains underexplored. This qualitative study explores the psychological and social aspects of living with MG through thematic analysis of semi-structured interviews with eight adults from a specialist MG care clinic in London, all considered clinically stable for at least three months. Data were derived from participants initially interviewed about their day-to-day experience of physical symptoms to inform development of a symptom monitoring tool. As psychosocial themes emerged strongly but remained unanalysed, this paper presents a secondary analysis focusing on psychosocial themes. Three overarching themes emerged: (1) coping with adaptation - including the burden of planning, struggles to accept diagnosis, therapeutic challenges and fear of the future; (2) social and identity disruption - involving changes in self-image, social withdrawal, and occupational challenges; and (3) emotional and psychological impact - highlighting negative emotions and cognitive fatigue. Uncertainty emerged as a meta-theme underpinning all other themes, reflecting, driving, and being created by MG's fluctuating symptoms. Findings suggest that psychological and social challenges underscored by uncertainty persist independently of symptom stability, highlighting the importance of uncertainty-focused interventions and integrated psychosocial support in MG care.", "authors": ["Maycock Ellie", "Selby Victoria", "Hanna Michael", "Muntoni Francesco", "Ramdharry Gita"], "journal": "Journal of neuromuscular diseases", "entry_date": "2025/12/24 12:22", "pub_date": "2025-12-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41442252/", "pub_types": ["Journal Article"], "affiliations": ["Institute of Neurology, University College London, London, UK."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41440190", "title": "Myasthenia Gravis and Thymectomy at a Tertiary-Care Surgical Centre: A 20-Year Retrospective Review.", "abstract": "Background: Myasthenia gravis (MG) is frequently associated with thymic abnormalities, including thymomas and hyperplasia. This study aims to analyze the clinical and pathological characteristics of thymectomized patients over a 20-year period, focusing on the relationship between thymoma subtype and MG incidence, as well as post-thymectomy remission outcomes. Methods: We retrospectively analyzed 420 patients who underwent thymectomy (open or VATS), with a mean age of 54.4 years and 59% female. Thymic pathology included thymomas (56.2%), thymic cysts (14.3%), and other lesions. 39.5% of patients had MG, of which 48.8% were thymomatous MG. Multivariate regression was used to identify predictors of MG and remission outcomes. Results: MG was significantly associated with younger age (p < 0.005), germinal hyperplasia (p < 0.001), and thymoma, especially WHO B2 subtype (p = 0.016). Six-month complete remission rates did not differ between thymomatous and non-thymomatous MG. In the subgroup undergoing VATS, median length of stay decreased to 3 days compared to 5 days in the overall cohort. The intraoperative complication rate for VATS was 1.5%, compared to 11.6% for open surgery. Conclusions: This is one of the largest single-center studies to evaluate the link between thymoma histology and MG. WHO type B2 thymoma and germinal hyperplasia were more commonly associated with MG. Comparable remission outcomes support the role of thymectomy in both thymomatous and non-thymomatous MG, emphasizing the need for individualized surgical strategies.", "authors": ["Lauk Olivia", "De Oliveira Alexandre Sarmento", "Huynh Caroline", "Sharma Sohat", "Vieira Arthur", "Mezei Michelle", "Chapman Kristine", "Briemberg Hannah", "Jack Kristin", "Yee John", "McGuire Anna L"], "journal": "Current oncology (Toronto, Ont.)", "entry_date": "2025/12/24 09:35", "pub_date": "2025-11-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41440190/", "pub_types": ["Journal Article"], "affiliations": ["Department of Surgery, Division of Thoracic Surgery, Vancouver General Hospital, Vancouver, BC V5Z 1M9, Canada."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "4区"}, {"pmid": "41439572", "title": "The Disparities in Myasthenia Gravis Clinical Trial Enrollment in the United States and Canada.", "abstract": "INTRODUCTION/AIMS: The demographic and geographic representation of participants in myasthenia gravis (MG) trials has yet to be systematically reviewed. The goal of this study was to explore potential disparities in MG interventional clinical trial enrollment.\nMETHODS: We included completed interventional clinical trials from January 2002 to December 2021 that enrolled participants with MG within the United States and Canada. Twenty-eight trials meeting these criteria were identified at Clinicaltrials.gov, and 16 trials contributed data. Study sponsors provided data for age, sex/gender, race, ethnicity, and state/province of site enrollment.\nRESULTS: Pooled data showed the following participant ethno-racial composition across trials: White = 79.9%, Black = 11.9%, Asian = 3.3%, Native American = 1.2%, \"Other\" race = 3.7%; 10.5% of participants identified as Hispanic ethnicity. Male participation was approximately 53%. Average participant age was 55.0 ± 17.0 years. The three highest enrolling US states were Texas, California, and Florida, and the highest enrolling Canadian province was Ontario. There was no enrollment in several Upper Midwest, Northern Rocky Mountain, and Southern US states. Total enrollment among White, Black, and Native American participants was proportional to the US population, whereas Hispanic and Asian participants were under-enrolled.\nDISCUSSION: The geographic distribution of enrollment suggests a possible concern that many patients do not have convenient access to trial centers. Strategies are needed to facilitate greater clinical trial participation among underrepresented and underserved communities that will improve generalization of study results to the overall MG population.", "authors": ["Sanchez Jose A", "Paredes Danelvis", "Guptill Jeffrey T", "Aita Stephen L", "Howard James F"], "journal": "Muscle & nerve", "entry_date": "2025/12/24 07:23", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41439572/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University of South Alabama, Mobile, Alabama, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41439073", "title": "Cavernous Sinus Dural Arteriovenous Fistula Initially Misdiagnosed As Ocular Myasthenia Gravis: A Case Report.", "abstract": "Cavernous sinus dural arteriovenous fistulas (CS-DAVF) can mimic ocular myasthenia gravis (OMG), as both may present with diplopia and ptosis. Differentiating between these conditions is critical because misdiagnosis can delay appropriate vascular treatment. Herein, we present the case of a 63-year-old woman who presented with a one-month history of diplopia and left-sided ptosis. Repeated edrophonium tests were positive, leading to an initial diagnosis of OMG. Immunotherapy led to a transient improvement, with decreased Myasthenia Gravis Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis scores. However, persistent diplopia and a new conjunctival injection raised the suspicion of CS-DAVF. Magnetic resonance imaging and angiography revealed enlargement of the left cavernous sinus, while digital subtraction angiography confirmed a left CS-DAVF. This case demonstrates the diagnostic challenges in distinguishing OMG from CS-DAVF. Even when clinical findings and bedside tests strongly suggest OMG, atypical ocular signs, such as conjunctival injection or chemosis, should prompt consideration of CS-DAVF. Careful interpretation of edrophonium results and timely neuroimaging are essential to avoid misdiagnosis.", "authors": ["Yamamoto Shinnosuke", "Watanabe Genya", "Akao Go", "Sato Kenichi", "Suzuki Yasushi"], "journal": "Cureus", "entry_date": "2025/12/24 04:58", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41439073/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Clinical Training, National Hospital Organization Sendai Medical Center, Sendai, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41431577", "title": "Deceptive Dyspnea: A Dual Pathology of Myasthenia Gravis and Right-to-Left Shunt Masquerading As Status Asthmaticus.", "abstract": "Respiratory failure in myasthenia gravis (MG) can mimic refractory status asthmaticus, leading to misdiagnosis and delayed treatment. We present the case of a 28-year-old female with a history of asthma and a known partial atrioventricular canal defect who was admitted with acute respiratory failure and severe hypoxemia, not responsive to maximum bronchodilator and corticosteroid therapy. Fatigable weakness on bedside examination led to a diagnosis of seropositive generalized MG. Although treated with pyridostigmine and intravenous immunoglobulin to improve her muscle strength, the persistence of severe hypoxemia suggested an underlying pathology. Bubble contrast echocardiography then confirmed a right-to-left shunt via her cardiac defect, along with mild pulmonary hypertension, and thus a double pathophysiology for her respiratory failure. It highlights that a failure of the patient to improve as anticipated should prompt diagnostic reassessment to prevent anchoring bias, and it underscores the crucial role of contrast echocardiography in identifying disproportionate hypoxemia in patients with an underlying cardiac shunt.", "authors": ["Gapizov Abubakar", "Farooq Ayesha", "Jabbar Quratulain", "Subhan Muhammad", "Khalid Ayesha", "Aqil Mehvish"], "journal": "Cureus", "entry_date": "2025/12/23 03:54", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41431577/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Weill Cornell Medicine, New York Presbyterian Brooklyn Methodist Hospital, Brooklyn, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41429676", "title": "Myasthenia Gravis - An Updated Review.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular junction (NMJ) disorder characterized by fatigable weakness in skeletal and ocular muscles. The etiology is the presence of autoimmune antibodies against postsynaptic acetylcholine receptors (AChR) or other muscle-specific proteins. The result is muscle end plate dysfunction and weakness. While symptoms may be limited to ocular muscles (ocular MG/OMG), systemic generalization of symptoms (generalized MG/gMG) can frequently occur. Diagnosis relies on a history of fluctuating weakness, diurnal variation in muscle strength, physical examination signs of fluctuating muscle weakness, supported by serology and electrophysiologic studies. In its most severe form, called myasthenic crisis, weakness can involve respiratory muscles, and can cause life-threatening hypoxemia needing critical care monitoring and invasive ventilation. Management of MG is multimodal and may need a combination of acetyl cholinesterase inhibitors, immunomodulators such as steroids, and steroid-sparing agents, intravenous agents, such as intravenous immunoglobulin, or plasma exchange, rarely needing surgical options such as thymectomy. Recent advances have added novel therapeutics as viable treatment options.", "authors": ["Harish Bindignavile Shruthi"], "journal": "International ophthalmology clinics", "entry_date": "2025/12/22 22:54", "pub_date": "2026-01-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41429676/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Wills Eye Hospital."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41429669", "title": "Neuro-ophthalmic Manifestations of Multiple Sclerosis.", "abstract": "The human body is endowed with an immune system that protects the body from infections, microbes, diseases, and external or foreign elements that could be harmful or disease producing. The human immune system is a complex amalgamation of cells, proteins, organs, and organ systems that fight these harmful agents and defend the body against them. When the immune system turns against itself or the body, it results in the development of autoimmune conditions wherein there is destruction of specific organs or systems, which threaten their normal functioning. Consequently, there is either reduced function or loss of function of the targeted area of the body. Autoimmune conditions can cause disruption of the neuro-ophthalmic pathway and threaten the central or peripheral vision, by targeting the brain, optic nerve, extraocular muscles, neuromuscular junctions, visual pathways, and sometimes spinal cord as well. The most important and common neuro-ophthalmic autoimmune conditions include, but are not limited to, multiple sclerosis (MS), neuromyelitis optica (NMO), myelin oligodendrocyte glycoprotein antibody disease (MOGAD), myasthenia gravis (MG), thyroid eye disease (TED), and giant cell arteritis (GCA).", "authors": ["Verma Rashmi"], "journal": "International ophthalmology clinics", "entry_date": "2025/12/22 22:54", "pub_date": "2026-01-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41429669/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Montefiore Medical Center, Albert Einstein School of Medicine Jericho, NY."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41426979", "title": "Alterations in plasma cytokine profiles in generalized myasthenia gravis following different immunotherapeutic regimens.", "abstract": "BACKGROUND: The pathogenesis of myasthenia gravis (MG) involves an imbalance of various pro-inflammatory and anti-inflammatory cytokines. Currently, there are no clinical studies comparing the effects of hormones and different non-hormonal immunosuppressants on the regulation of plasma cytokines. Hence, there is no unified standard for drug selection. This study aims to explore the associations between glucocorticoid (GC), tacrolimus (TAC), and rituximab (RTX) and plasma cytokine levels in generalized myasthenia gravis, providing an observational overview of how different treatment regimens relate to immune-inflammatory patterns in clinical practice.\nMETHODS: A retrospective collection of 65 GMG patients diagnosed at the Department of Neurology, General Hospital of the People's Liberation Army from July 2022 to May 2024 was conducted. According to treatment regimens, patients were divided into a GC group (n = 17), a TAC group (n = 17), a RTX group (n = 9), and non-medicated patients (NM) group (n = 22), another 30 healthy individuals were selected as the healthy control (HC) group. Clinical data and levels of cytokines such as Interleukin (IL)-1β, IL-2, IL-4, IL-5, IL-6, IL-8, IL-10, IL-12P70, IL-17, Tumor Necrosis Factor (TNF)-α, Interferon (IFN)-α, and IFN-γ in plasma were collected to compare plasma cytokine levels across the three treatment groups and the non-medicated group.\nRESULTS: Compared with the HC group, GMG patients in the NM group showed significantly higher plasma levels of IL-1β, IL-2, IL-4, IL-10, IL-17, TNF-α, IFN-α, and IFN-γ. Relative to the NM group, the GC group exhibited lower levels of IL-1β, IL-4, IL-6, IL-17, and TNF-α, and the RTX group showed lower levels of IL-1β, IL-4, IL-6, IFN-α, and TNF-α. In the comparison across treatment groups, the GC group presented lower IL-17 and IFN-γ levels than the TAC group, while the RTX group presented lower IL-6, IFN-α, and TNF-α levels than the TAC group.\nCONCLUSION: Cytokine levels were markedly elevated in the plasma of patients with GMG, indicating their potential involvement in disease-related immune dysregulation. Distinct treatment groups displayed different cytokine patterns, reflecting heterogeneous immunological states among patients receiving GC, TAC, or RTX. Collectively, these findings provide preliminary immunological insights into GMG and highlight the need for validation in larger, prospective studies.", "authors": ["Ren Zhuangzhuang", "Ma Xihui", "Liu Yudan", "Zhang Yufeng", "Chen Yuping", "Sun Chenjing", "Qiu Feng"], "journal": "Frontiers in neurology", "entry_date": "2025/12/22 06:58", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41426979/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Chinese PLA Hospital, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41426144", "title": "Long-Term Outcomes of Thymoma Treated at a Single Institute.", "abstract": "INTRODUCTION: Thymomas are uncommon tumors that originate from epithelial cells of thymus and may have varying clinical course.\nMATERIALS AND METHODS: A retrospective review of medical records of thymoma patients treated between January 2012 and April 2022 at our institute was conducted.\nRESULTS: There were a total of 23 patients (12 males and 11 females) with median age of 52 years (range, 33-77 years). Eleven patients (47.8%) had associated paraneoplastic syndromes of which 10 (43.5%) had myasthenia gravis and 1 (4.3%) had pure red cell aplasia. Average maximal tumor diameter was 62 mm (28-160 mm). Masaoka-Koga stage distribution was as follows: stage I ( n  = 2, 8.7%), IIA ( n  = 4, 17.4%), IIB ( n  = 1, 4.3%), IIIA ( n  = 2, 8.7%), IIIB ( n  = 4, 17.4%), IVA ( n  = 7, 30.4%), and IVB ( n  = 3, 13.1%). The World Health Organization type B2 was the commonest histology ( n  = 12, 52.17%), followed by B3 ( n =7, 30.4%), B1 ( n  = 2, 8.7%), AB ( n  = 1,4.3%), and A ( n  = 1, 4.3%). Six patients received neoadjuvant chemotherapy with cyclophosphamide regimen, 22 (95.6%) underwent surgery, and 1 patient received adjuvant chemotherapy. R0 resection was attained in 20 (91%) patients, R1 resection in 1 (4.5%) patient, and R2 in 1 (4.5%) patient. All operated patients underwent postoperative radiotherapy (45-60 Gy in 25-30 fractions). Four patients relapsed at a median duration of 14 months (2-26 months). At a median follow-up of 6 years, 5-year overall survival was 67.1% and 5-year progression-free survival was 66.6%. Local control at 5 years was 86.6%.\nCONCLUSION: Despite majority of our patients presenting at an advanced stage, the local control rates are encouraging and reinforce multimodality approach.", "authors": ["Shishak Sorun", "Kataria Tejinder", "Bisht Shyam Singh", "Banerjee Susovan", "Gupta Deepak", "Kaliyaperumal Venkatesan", "Narang Kushal", "Mayank Mayur", "Selvaraj Rajesh", "Abraham Susan K", "Goyal Shikha"], "journal": "South Asian journal of cancer", "entry_date": "2025/12/22 06:51", "pub_date": "2025-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41426144/", "pub_types": ["Journal Article"], "affiliations": ["Division of Radiation Oncology, Medanta The Medicity, Gurugram, Haryana, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41425833", "title": "Robotic thymectomy for ocular myasthenia gravis: a case series from a UK tertiary centre.", "abstract": "BACKGROUND: Ocular myasthenia gravis (oMG), characterised by ptosis and diplopia, may progress to generalised MG (gMG). Thymectomy is established for seropositive gMG, but its role in oMG remains unclear. Robotic-assisted thoracoscopic surgery (RATS) offers minimally invasive advantages, yet outcomes in oMG are understudied. This case series describes the outcomes of seven patients at University College London Hospitals (UCLH) (2019-2025) undergoing robotic thymectomy for oMG.\nMETHODS: We describe seven oMG patients undergoing robotic thymectomy at UCLH (2019-2025), focusing on improvement in daily life using the MG activities of daily living (MG-ADL) score and medication reduction.\nRESULTS: Patients showed significant pyridostigmine reduction (mean decrease: 246 mg) and improved MG-ADL scores (mean=4.00 to 0.57) with no major complications. No patients progressed to gMG.\nCONCLUSION: We saw robotic thymectomy (RATS) reduce pyridostigmine dependence and improve quality of life (MG-ADL) in the seven oMG patients, with no complications. These cases demonstrated successful cases of RATS as a transformative, minimally invasive option for early MG. While thymectomy may reduce the risk of generalisation, further multicentre studies are needed. Careful patient selection remains critical, but RATS may expand feasibility in oMG.", "authors": ["Roberts Thomas", "Cone Stephen", "Spillane Jennifer", "Lawrence David", "Maraschi Alessandro", "Bhakhri Kunal"], "journal": "BMJ neurology open", "entry_date": "2025/12/22 06:48", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41425833/", "pub_types": ["Journal Article"], "affiliations": ["University College London, London, England, UK."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41425574", "title": "Autoimmune thyroid disease and human health: a systematic review of Mendelian randomization studies.", "abstract": "UNLABELLED: We systematically summarized current Mendelian randomization (MR) evidence on the causal relationships between autoimmune thyroid disease (AITD) and a wide range of human health outcomes. Original MR studies related to AITD published up to March 1, 2025, were retrieved from PubMed and Embase. For studies investigating the same exposure-outcome associations, meta-analyses were performed to synthesize the evidence after excluding overlapping samples where applicable. The methodological quality of the included studies was assessed using the STROBE-MR checklist. A total of 123 MR publications met the inclusion criteria. MR analyses indicated that AITD significantly increased the risk of coronary atherosclerosis, deep venous thrombosis, chronic obstructive pulmonary disease, major depression, diabetic neuropathy, carpal tunnel syndrome, neuromyelitis optica spectrum disorder, diabetic retinopathy, childhood absence epilepsy, rheumatoid arthritis, systemic lupus erythematosus, psoriatic arthritis, inflammatory bowel disease, crohn's disease, vitiligo, myasthenia gravis, alopecia areata, type 1 and type 2 diabetes, sarcoidosis, frozen shoulder, drug eruptions, cataract, early age-related macular degeneration, pernicious anemia, Helicobacter pylori infection, temporomandibular disorders, migraine, frailty, primary biliary cholangitis, knee osteoarthritis, gout, and osteoporosis, while decreasing the risk of lung cancer, polyneuropathies, allergic rhinitis, telomere length, and serum vitamin A levels. The included MR studies were of high methodological quality and provided robust evidence supporting the bidirectional relationships between AITD and various health outcomes. These findings emphasize the importance and necessity of preventing and managing AITD while offering new perspectives and directions for future research on its prevention and treatment.\nSYSTEMATIC REVIEW REGISTRATION: https://www.crd.york.ac.uk/prospero/, identifier CRD42023469038.", "authors": ["Li Peijin", "Wang Qian", "Yang Yan", "Ding Zhiguo"], "journal": "Frontiers in immunology", "entry_date": "2025/12/22 06:45", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41425574/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Department of Thyropathy, Dongzhimen Hospital of Beijing University of Chinese Medicine, Beijing, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41423716", "title": "Remote Monitoring in Myasthenia Gravis: Exploring Symptom Variability.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare, autoimmune disorder characterized by fluctuating muscle weakness and potential life-threatening crises. While continuous specialized care is essential, access barriers often delay timely interventions. To address this, we developed MyaLink, a telemedical platform for MG patients. This study evaluated whether frequently assessed clinical outcomes via MyaLink can capture symptom variability between clinical visits.\nMETHODS: In this randomized, controlled, 12-week study, 45 MG patients received either standard care (control, N = 15) or standard care with additional telemedical treatment (intervention, N = 30) including assessment of patient-reported outcome measures, sensor-based data, and patient-physician messaging via a mobile application. Physicians performed telemedical check-ups (TCUs) via a web-based platform, adjusting treatment as needed.\nRESULTS: In the intervention group, variability in clinical scores and sensor-derived data was observed, particularly among those who experienced MG-related hospitalizations or exacerbations (H&E subgroup). This subgroup showed larger MG-ADL score fluctuations (mean range: 5.8 vs. 2.6 points), sent more messages, had more steroid dose adjustments (40% vs. 0%), and more frequent TCU interventions (93.3% vs. 60%) than the Non-H&E subgroup.\nINTERPRETATION: Telemedical platforms in MG might detect early signs of worsening. High-risk patients (H&E subgroup) require increased medical support, which can be effectively addressed through MyaLink.\nTRIAL REGISTRATION: The study was registered under the German clinical trial registry (DRKS00029907).", "authors": ["Stein Maike", "Mönch Maximilian", "Herdick Meret", "Stascheit Frauke", "Hoffmann Sarah", "Preßler Hannah", "Mergenthaler Philipp", "Dusemund Carla", "Doksani Paolo", "Sun Haoqi", "Narayanaswami Pushpa", "Meisel Andreas", "Gerischer Lea", "Lehnerer Sophie"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/12/21 23:33", "pub_date": "2025-12-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41423716/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology With Experimental Neurology, Charité-Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41422493", "title": "Body weight distribution of US patients with myasthenia gravis.", "abstract": "OBJECTIVE: Several novel therapies have been approved for treatment of generalized myasthenia gravis (gMG). The dosing requirements of certain therapies (efgartigimod intravenous, nipocalimab, ravulizumab, rozanolixizumab, zilucoplan) are based on patient's body weight. To determine costs of weight-based gMG treatments to payers, accurate assessment of the body weight distribution of patients with MG is required. However, little is known about these patients' weight profile. The current study aims to provide robust weight data in multiple cohorts of patients with MG and elucidate the cost of gMG therapies based on weight.\nMETHODS: Body weight distribution of patients with MG was analyzed using Optum's de-identified Market Clarity Data and data from the efgartigimod patient support program (PSP). Adult patients with MG with available body weight were included. Additionally, a literature review of clinical trials of gMG therapies that reported patient body weight was conducted. An analysis of the annual cost of weight-based dosing was also performed.\nRESULTS: Patients from the Optum database (N = 5,033) had mean body weight = 86.6 kg (standard deviation [SD] = 23.1 kg) and median weight = 83.7 kg (interquartile range [IQR] 70.3-99.9 kg). Patients from the PSP (N = 4,539) had mean weight = 92.1 kg (SD = 25.6 kg) and median weight = 89.0 kg (IQR = 74.0-106.1 kg). In each cohort, most patients weighed ≥80 kg (58.0% Optum, 66.2% PSP). Across clinical trials of patients with gMG, mean body weights ranged from 79.1-91.2 kg and median weights from 74.4-90.0 kg. The annual cost of health-care-provider-administered treatment for patients with gMG was estimated at $223,272-$648,960 depending on drug and body weight; annual cost was highest for patients who weighed >80 kg (up to $648,960 versus up to $467,044 for patients who weighed <80 kg).\nCONCLUSION: Our findings demonstrate that patients with MG may be heavier on average than previously assumed, which may influence the cost-effectiveness of gMG therapies with weight-based dosing.", "authors": ["Tse Kevin", "Sato Mai", "Menon Rohit R", "Yang Hongbo", "Du Mandy", "Qi Cynthia Z"], "journal": "Journal of medical economics", "entry_date": "2025/12/21 12:02", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41422493/", "pub_types": ["Journal Article"], "affiliations": ["argenx US Inc., Boston, MA, USA."], "china_related": false, "study_types": ["HEOR"], "evidence_level": null, "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "41420885", "title": "Co-existence of Myasthenia Gravis and Addison's Disease Without Thymoma: A Case Report.", "abstract": "INTRODUCTION: Myasthenia Gravis (MG) and Addison's Disease (AD) co-existing is very rare. The estimated prevalence of this co-occurrence is less than 1 in 100 000, underscoring its clinical significance. We present a female case with coexisting AD and MG. A 45-year-old female arrived at our clinic complaining of breathing difficulties for a month, a drooping left eyelid, and swallowing difficulties for 10 days. She has been treated with 5 mg/day prednisone for AD for three years. Long-term corticosteroid therapy may modulate immune responses and influence the timing of MG onset. Neurological evaluation revealed partial ptosis in the left eye and mild tetraparesis (4/5 strength).\nCASE REPORT: Cortisol level was 0.8 µg/dL, and adrenocorticotropic hormone (ACTH) level was 987 ng/L, an adrenal crisis was excluded. The anti-acetylcholine receptor antibody (anti-AChR antibody) level was 8.37 nmol/L (> 0.4 nmol/L). Repetitive nerve stimulation, neostigmine, and Simpson tests were compatible with MG. Therefore, she was diagnosed with MG.\nCONCLUSIONS: Acetylcholine antibodies in MG may indicate that other autoimmune diseases may be added to the clinic in these patients. Keeping in mind the presence of the underlying MG may be life-saving for those who do not react well to therapy or in the case of newly added findings in AD patients.", "authors": ["Varoglu Asuman Orhan", "Aslan Ezgi", "Aksoy Asude"], "journal": "Neuro endocrinology letters", "entry_date": "2025/12/20 17:48", "pub_date": "2025-12-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41420885/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Medical School, Istanbul Medeniyet University, Istanbul, Turkey."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41418342", "title": "Sleep disorders in myasthenia gravis: A systematic review on prevalence, clinical associations, and the accuracy of assessment methodologies.", "abstract": "BACKGROUND: Sleep disorders are a frequently reported yet poorly characterized aspect of myasthenia gravis (MG), contributing significantly to fatigue and reduced quality of life. The accuracy of standard screening tools in this population remains a major clinical challenge.\nOBJECTIVES: This systematic review synthesizes evidence on the prevalence, types, and assessment challenges of sleep disorders in MG.\nMETHODS: A systematic search of PubMed, Embase, and PsycInfo was conducted from inception to April 2025. Observational studies reporting on sleep disorders in patients with clinically diagnosed MG were included. Study quality was assessed using the Joanna Briggs Institute (JBI) tools.\nRESULTS: Of 812 unique records, 27 studies (n = 4135 participants) were included. The prevalence was 5-64 % for obstructive sleep apnea (OSA) and 38-77 % for poor sleep quality (PSQI >5). Restless leg syndrome (10.5-47.6 %) and excessive daytime sleepiness (12-75 %) were also highly prevalent. Higher body mass index and male sex were significant risk factors for OSA and sleep-disordered breathing. A critical finding was the significant discrepancy between subjective questionnaires and objective polysomnography. Subjective questionnaires overestimated OSA risk due to symptom overlap, while objective polysomnography provided more specific diagnoses. Sleep disorders were strongly correlated with worsened MG-specific quality of life, fatigue, and depression scores.\nCONCLUSION: Sleep disorders are exceedingly common in MG, but the inherent limitations of subjective questionnaires confound their assessment. The dissociation from disease severity suggests a distinct, multifactorial pathophysiology.", "authors": ["Yakubu Aliu Opeyemi", "Lawal Farouk Ishola", "Nwaze Chukwuma Emmanuel", "Egede Favour", "Olalude Oluwakemi Eunice", "Anifalaje Olorungbami Kolade"], "journal": "Sleep medicine", "entry_date": "2025/12/19 18:00", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41418342/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Department of Neurology, University of Texas Medical Branch, Galveston, TX, USA. Electronic address: aoyakubu@UTMB.edu."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41416001", "title": "Appropriate use of steroids for patients with generalized Myasthenia Gravis: an international Delphi study.", "abstract": "BACKGROUND: Oral corticosteroids (OCS) are commonly used in the management of autoimmune Myasthenia Gravis (MG), often in high doses for prolonged periods. Exposure to OCS is associated with significant and cumulative adverse effects. There is currently no universal consensus on the approach to OCS use in MG.\nOBJECTIVES: To reach a multinational consensus on the appropriate use of OCS in MG, including the role of treatment approaches to minimize dose and support tapering.\nDESIGN: This modified Delphi study established consensus among a panel of 70 general neurologists/neuromuscular specialists from eight countries over two rounds of survey to establish best practice principles regarding the use of OCS in MG.\nMETHODS: The current literature on OCS use in MG was reviewed. Topics of interest were identified, and a modified Delphi consensus process was created. A steering committee of six experts in MG proposed statements for testing with the wider panel over two rounds of surveys. Consensus was reached if at least 75% agreed or strongly agreed on a 4-point Likert scale.\nRESULTS: Consensus was achieved for all 37 final statements. These statements covered principles of OCS use, including a target for long-term use of ⩽5 mg/day; the role of biologic treatments in minimizing required OCS dose; the need for individualization of approach according to patient factors; and the need for detailed guidance regarding how and when to taper OCS dose.\nCONCLUSION: These findings reinforce a shift in the management of MG, advocating for the judicious and sparing use of OCS against the backdrop of expanding therapeutic options. As additional evidence-based data emerge, these recommendations should be updated.\nAn international Delphi consensus on the use of steroids in Myasthenia Gravis A steering committee of 6 Myasthenia Gravis (MG) experts proposed statements for testing with a wider panel of 70 neurologists/neuromuscular specialists from 8 countries, as part of a modified Delphi process. Consensus was reached for 37 statements covering principles of oral corticosteroid (OCS) use, including a target for long-term use of no more than 5 mg/day; the role of biologic treatments in minimizing required OCS dose and supporting a fast OCS taper (within 4 months); the need for individualization of approach; and the need for greater guidance regarding how and when to taper OCS dose. Key findings include agreement that OCS target dose should be 5 mg/day or lower for most patients with MG, and where OCS use is necessary to maintain symptom control. Alternative treatments with steroid-sparing effects should be used to achieve this target.", "authors": ["Wiendl Heinz", "Murai Hiroyuki", "Narayanaswami Pushpa", "Saccà Francesco", "Silvestri Nicholas J", "Howard James F"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/12/19 04:57", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41416001/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Neurophysiology, University Medical Center, Freiburg, Breisacher Strasse 64, Freiburg 79106, Germany University of Muenster, Muenster, Germany."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41412962", "title": "In-Depth Profiling Highlights the Effect of Efgartigimod on Peripheral Innate and Adaptive Immune Cells in Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder characterized by antibody-mediated complement activation. Efgartigimod, a neonatal Fc receptor (FcRn) antagonist, is approved for treating generalized MG (gMG). However, its modulatory effects on upstream innate and adaptive immune cells remain largely unexplored.\nMETHODS: We first quantified FcRn expression in peripheral immune subsets from acetylcholine receptor antibodies (AChR-Ab) positive gMG. Then we assessed efgartigimod's impact on immune cells via in-depth profiling in vitro and later validated these findings in a prospective real-world cohort treated with efgartigimod.\nRESULTS: High FcRn expression was abundantly expressed on monocytes and lymphocytes in an exploratory MG cohort (n = 29), with notable intracellular presence. In vitro studies showed efgartigimod significantly decreased intracellular FcRn in monocytes (p < 0.001) and lymphocytes (p = 0.019). After efgartigimod treatment, non-classical monocytes (CD14lowCD16+, 17.89 ± 9.60 vs. 14.58 ± 9.89 cells/μl, p < 0.001; 3.20 ± 2.06 vs. 2.61% ± 2.12%, p < 0.001) and Th17.1 cells (CXCR3+CCR6+, 95.83 ± 66.56 vs. 84.06 ± 61.70 cells/μl, p = 0.010; 10.42 ± 4.82 vs. 9.06% ± 4.46%, p = 0.000) were significantly downregulated. In contrast, antibody-producing B cells and effector-memory CD4+ and CD8+ T cells were expanded. Longitudinal assessments in the gMG cohort displayed similar findings, which likely reflect the direct inhibitory effect of efgartigimod on monocytes, coupled with negative feedback due to decreased IgG levels.\nCONCLUSIONS: By integrating in vitro and clinical findings, we demonstrate that efgartigimod modulates peripheral immune cell populations, highlighting its significant immunomodulatory effects and clinical potential.", "authors": ["Jin Lei", "Dong Liu", "Wang Ying", "He Dingxian", "Yan Chong", "Xi Jianying", "Jiang Haoqin", "Shi Yu", "Guan Ming", "Zhao Chongbo", "Song Jie", "Luo Sushan"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/12/18 22:52", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41412962/", "pub_types": ["Journal Article"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41412256", "title": "Eculizumab as a new option for perioperative treatment in thymoma-associated myasthenia gravis.", "abstract": "The efficacy of eculizumab as a perioperative treatment in patients with thymoma-associated myasthenia gravis (TAMG) has not been evaluated. This prospective study included patients with TAMG who received standard-of-care therapy (Soc group, n = 20) or combined with eculizumab (Ecu group, n = 13). At 1 week, the Ecu group showed a marked improvement compared to the Soc group, as evidenced by a reduction in Quantitative Myasthenia Gravis (QMG) (7.39 ± 3.47 vs 0.25 ± 5.13, P = 0.0001), Manual Muscle Test (MMT) (6.39 ± 4.66 vs 0.15 ± 3.96, P = 0.0003), and MG Activities of Daily Living (MG-ADL) (4.85 ± 3.16 vs 0.30 ± 3.47, P = 0.0006). No significant differences were observed in operative time, or intraoperative blood loss. The rate of postoperative myasthenic crisis was 9.1 % (1/13) in the Ecu group, compared to 20 % (4/20) in the Soc group (P = 0.33). This study highlights the role of eculizumab in TAMG as a rapid symptom-control treatment before thymomectomy.", "authors": ["Wu Hui", "Chu Xianglin", "Zhong Huahua", "Huang Ying", "Yang Hongxia", "Qi Guoyan", "Jin Lei", "Chen Ran", "Jia Wenji", "Xiong Ji", "Pang Liewen", "Zhao Chongbo", "Song Jie", "Luo Sushan"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2025/12/18 19:31", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41412256/", "pub_types": ["Journal Article"], "affiliations": ["Huashan Rare Disease Center and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Center for Neurological Disorders, Fudan University, Shanghai 200040, China; Department of Neurology, Jing'an District Centre Hospital of Shanghai, Shanghai 200040, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41411760", "title": "Humoral correlates of clinical response to thymectomy in myasthenia gravis.", "abstract": "Mechanisms by which thymectomy confers its clinical benefit in patients with AChR-antibody (Ab) positive myasthenia gravis (MG) remain poorly understood. We used a systems-level approach combined with high-dimensional characterization of Ab-associated immune features to identify Ab-features that track with clinical response to thymectomy in 78 patients with AChR-Ab positive MG, recruited during the MGTX trial, an NIH-sponsored randomized, controlled study of thymectomy plus prednisone versus prednisone alone. Clinically meaningful improvement was defined as a change of at least 3 points on the quantitative MG scale at month 36 compared to baseline. AChR-specific immunoglobulin G (IgG) titers decreased in patients experiencing clinical improvement but remained stable in patients with poor response to therapy. Thymectomized patients showed an accelerated decline in AChR-specific IgG titers. At month 36, the frequency of digalactosylated and monosialylated total IgG Fc-glycans was increased in thymectomized responders compared to non-responders. Fc-glycosylation profiles were unchanged in prednisone only treated patients with or without clinically meaningful improvement. Clinical benefit achieved by thymectomy is strongly associated with an anti-inflammatory IgG Fc-glycosylation profile.", "authors": ["Sousa Carla D F", "Terroba-Navajas Paula", "Tzartos John", "Orešković Ivana D", "Pučić-Baković Maja", "Lauc Gordan", "Bartsch Yannic C", "Kaminski Henry J", "Lünemann Jan D"], "journal": "Journal of autoimmunity", "entry_date": "2025/12/18 18:03", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41411760/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology, University Hospital Münster, Germany."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41410951", "title": "Myasthenia gravis - new, improved treatment.", "abstract": "", "authors": ["Gilhus Nils Erik", "Maniaol Angelina Hatlø"], "journal": "Tidsskrift for den Norske laegeforening : tidsskrift for praktisk medicin, ny raekke", "entry_date": "2025/12/18 11:39", "pub_date": "2025-12-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41410951/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41409222", "title": "Complement activation in immunological neurological disorders: mechanisms and therapeutic strategies.", "abstract": "Recent advances in the understanding of immune-mediated neurological disorders have led to a paradigm shift toward pathophysiology-directed therapies. Central to this progress is a deeper appreciation of the complement system, a key component of innate immunity, and its role in neuroinflammation. Complement activation, while essential for host defense and tissue homeostasis, has been implicated increasingly in a spectrum of central and peripheral neurological disorders where complement dysregulation contributes to inflammation, cellular damage, and disease progression. Breakthroughs in conditions such as myasthenia gravis and aquaporin-4 IgG-positive neuromyelitis optica spectrum disorder underscore the therapeutic potential of targeting complement pathways to improve patient outcomes. In this review, we provide a comprehensive overview of complement activation pathways, regulatory controls, and their involvement in various autoimmune neurological diseases. We also highlight current and emerging complement-targeted therapies, many of which are now completing or entering clinical trials. Together, these insights offer a holistic perspective on the complement system as both a contributor to and a target for intervention in neurological diseases.", "authors": ["Chen Jin Y", "Sanghani Nirav", "Palmer Kaitlyn", "Li Yuebing", "Lin Feng", "Abbatemarco Justin R"], "journal": "Frontiers in neurology", "entry_date": "2025/12/18 04:28", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41409222/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Immunity and Inflammation, Lerner Research Institute, Cleveland Clinic, Cleveland, OH, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41408204", "title": "Physical activity and its effects in myasthenia gravis: a patient-reported study on habits and impact.", "abstract": "BACKGROUND: Physical activity and exercise have been classified as safe and effective in mild to moderate cases of myasthenia gravis (MG) across various studies. Subsequently, adequate physical activity is generally recommended. Nevertheless, individuals with MG remain less physically active than the general population, without a precise definition of the low-activity group so far.\nMETHODS: In this prospective single-center study, individuals with MG completed a questionnaire assessing general mobility, weekly physical activity levels, and beliefs toward specific statements about physical exercise. These data were contextualized with clinical parameters and MG-specific scores.\nRESULTS: Among 84 individuals (50% female), 73.8% reported general positive effects, and 77.4% noted improvements in mood and well-being due to physical activity. No significant differences in physical activity levels were found depending on sex, BMI or age. Weekly physical activity averaged 94.6 min (SD: 85.6), falling below current recommendations. Physical activity was inversely correlated with lower QMG (p = 0.019) and MG-ADL scores (p = 0.004). Despite the reported positive impact of physical activity on quality of life, no relevant connection was detected between physical activity and MG-QoL15 scores. Barriers preventing individuals affected by MG from engaging in physical activity included muscle pain (35.4%) and motivational challenges (22%). Individuals with motivational problems were younger (mean age 55.5 vs. 66.6 years, p = 0.011) and more frequently reported depressive symptoms; no other significant differences were observed in gender or disease severity in this subgroup.\nCONCLUSION: Individuals with MG perceive physical activity as beneficial to their physical well-being, mood, and overall quality of life. Those with less severe disease tend to be more active. However, barriers such as motivational issues and post-exercise pain must be addressed. Clinicians should aim to identify individuals with low activity levels, encourage engagement in physical activity, highlight its benefits, and alleviate patient concerns.\nTRIAL REGISTRATION: Study approval by the Ethics Committee of the University Medical Center Göttingen was granted (number 33/12/21). The study was retrospectively registered at the German Clinical Trial Registry (DRKS) under the study ID DRKS00033171 (Date of trial registration December 1st, 2023).", "authors": ["Glaubitz Stefanie", "Meyer Stefanie", "Loris Johanna", "Zeng Rachel", "Kummer Karsten", "Garfias-Veitl Tania", "Seraji Ariana", "Hassoun Lina", "Rohleder Denise", "Hunger Ina", "Zschüntzsch Jana"], "journal": "BMC neurology", "entry_date": "2025/12/17 23:42", "pub_date": "2025-12-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41408204/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University Medical Center Göttingen, Robert-Koch-Straße 40, Göttingen, 37075, Germany. stefanie.glaubitz@med.uni-goettingen.de."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41406247", "title": "Perioperative Management of Minimally Invasive Thymectomy in a Pediatric Patient With Myasthenia Gravis After Respiratory Crisis: A Case Report.", "abstract": "We report the anesthetic management of a 10-year-old girl with treatment-refractory, acetylcholine receptor antibody-positive juvenile myasthenia gravis (JMG) undergoing minimally invasive thymectomy after a recent myasthenic crisis. Anesthetic planning focused on avoiding neuromuscular blockers, minimizing stress, and preserving respiratory function. Paravertebral blocks with intercostal cryoablation provided postoperative analgesia-an approach not previously reported in pediatric JMG. This case illustrates the complexity of anesthetic care in JMG and the value of individualized, multidisciplinary planning to ensure safe and effective minimally invasive thymectomy in children. .", "authors": ["Bratton Roscoe H", "Le Hai H", "Chin Laura E W"], "journal": "A&A practice", "entry_date": "2025/12/17 14:03", "pub_date": "2025-12-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41406247/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["From the Department of Anesthesiology and Critical Care Medicine, Johns Hopkins University School of Medicine, Baltimore, Maryland."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": null}, {"pmid": "41405829", "title": "Formative Research in the Codesign of a Discrete Choice Experiment with Patients with Myasthenia Gravis: Selecting and Refining Attributes, Levels and Scenarios.", "abstract": "INTRODUCTION: Given the substantial burden faced by patients with myasthenia gravis (MG), including the disease itself, treatment-related side effects, the invasiveness of certain interventions and the time spent in seeking and receiving care, it is essential to understand patient preferences to inform resource allocation and enhance patients' quality of life.\nOBJECTIVE: The aim of this study was to co-design the MG treatment choice tasks with patients for a discrete choice experiment (DCE) using a multi-stage, mixed-methods approach involving the nominal group technique (NGT) and focus groups.\nMETHODS: MG patients in Australia were invited to participate in two of eight 1-hour online sessions in July and August 2024. Each session included four to six patients and was facilitated by three researchers. Participants were presented with three MG scenarios: 'mild exacerbation', 'severe exacerbation' and 'maintenance phase'. During NGT sessions, patients shared their experiences with MG treatments, proposed DCE attributes and ranked their importance for each scenario. Attribute rankings were normalised to a 0-1 scale, averaged within each session and combined using a weighted mean adjusted for group size. The rankings were used to prioritise attributes for inclusion in DCEs. In subsequent focus groups, patients reviewed draft DCE scenario descriptions and provided feedback on the clarity and relevance of attribute descriptions and levels. Throughout the process, research team discussions were held to discuss clinical and methodological relevance of the emerging results.\nRESULTS: Nineteen patients with MG aged 35-82 years (12 females, 7 males) participated in four online NGT and four focus group sessions, identifying 31 attributes across treatment administration (n = 10), side effects (n = 16) and treatment outcomes (n = 5). Attribute rankings varied by scenario, with 'recommended by neurologist', health care workers' knowledge of the treatment' and 'easy access to treatment' being consistently top-ranked among treatment administration attributes. Side effects ranged broadly, from gastrointestinal issues to skin cancer. For treatment outcome attributes, 'chance to improve' was most highly ranked for mild and severe exacerbation scenarios, whereas 'risk of getting severely worse' and 'duration of effectiveness' were equally top-ranked for the maintenance scenario. Attribute rankings and patient perspectives were balanced with DCE methodological considerations and clinician input to finalise attributes for each scenario, including grouping similar side effects to describe a few attributes and retaining the 'cost to patient' attribute despite it being a low patient priority to allow trade-off analysis in the resulting choice data. A final list of seven attributes was selected for both the mild exacerbation and maintenance scenarios. Discussions from focus groups and research team deliberation further refined scenario descriptions and attribute levels to enhance relevance and clarity.\nCONCLUSION: This study reinforces the value of a blended and staged approach of combining NGT and focus group sessions with multidisciplinary research team discussions to shape the development of patient-centred research in DCE design.", "authors": ["Aydin Gozde", "Zhang Xin", "Petrie Dennis", "Van der Walt Anneke", "Reddel Stephen", "Buzzard Katherine", "Windle Natalie", "White Susan", "Bergin Catherine", "Fanning Laura"], "journal": "The patient", "entry_date": "2025/12/17 11:22", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41405829/", "pub_types": ["Journal Article"], "affiliations": ["Centre for Health Economics, Monash Business School, Monash University, Caulfield, VIC, Australia. gozde.aydin@monash.edu."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV"}, {"pmid": "41405535", "title": "ST-Segment Elevation Myocardial Infarction in a Patient With Myasthenia Gravis After Intravenous Immunoglobulin Infusion.", "abstract": "BACKGROUND: Acute coronary syndrome is rare in patients with myasthenia gravis, with only limited literature available. We report an atypical case of ST-segment elevation myocardial infarction (STEMI) that occurred after intravenous immunoglobulin (IVIg) infusion in a patient with myasthenia gravis.\nCASE SUMMARY: A 36-year-old woman with a longstanding history of myasthenia gravis developed acute chest pain and ST-segment elevation on electrocardiogram after IVIg administration. Emergent coronary angiography revealed total thrombotic occlusion of the left anterior descending artery. Percutaneous coronary intervention with thrombectomy was successfully performed, and stenting was not required. The patient was discharged in stable condition after hospitalization for an additional 17 days.\nDISCUSSION: This report highlights an atypical case of STEMI in a young patient without conventional atherosclerotic risk factors, presumably triggered by an IVIg infusion.\nTAKE-HOME MESSAGE: Clinicians should be aware of the potential risk of thrombotic cardiac events associated with IVIg administration during the treatment of myasthenia gravis.", "authors": ["Lee Jeong Geon", "Seok Jin Myoung", "Park Sang-Ho"], "journal": "JACC. Case reports", "entry_date": "2025/12/17 10:30", "pub_date": "2026-02-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41405535/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Medicine, Soonchunhyang University College of Medicine, Cheonan, South Korea."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41405018", "title": "Somatic Mutations of Thymic Epithelial Tumors Identified in the Prospective THYMOGENE Trial.", "abstract": "BACKGROUND: The molecular landscape of thymic epithelial tumors has been partially elucidated. GTF2I mutation drives the pathogenesis in approximately 50% of tumors; however, the key molecular aberrations in the other cases remain unclear.\nMETHODS: We designed a panel including the most frequently mutated genes in thymic epithelial tumors and sequenced tumor and normal DNA from 70 patients prospectively accrued at a single institution in the Thymogene trial. Moreover, 19 neoplastic samples were dissociated to isolate tumor cells using flow cytometry.\nRESULTS: GTF2I mutations were the most common, being present in 41% of patients. GTF2I mutations were prevalent in type A and AB thymomas, in Stage I-II tumors, and in patients without myasthenia gravis. The unique pattern of mutually exclusive and co-occurring mutations suggests a distinct pathogenesis for thymomas with and without GTF2I mutation. In 39% of patients, no mutations were found in the 77 genes evaluated. The absence of epithelial cells in some dissociated tumors highlights the challenge of identifying mutations in a subset of thymic epithelial tumors that lack the GTF2I mutation. Mutational signatures, including COSMIC 1, 19, and 25, were enriched, possibly linked to 5'-methylcytosine deamination and the effects of chemotherapy.\nCONCLUSIONS: GTF2I mutations drive the growth of a significant portion of thymic epithelial tumors, often in conjunction with other gene mutations. Somatic mutations are not commonly found in many GTF2I wild-type tumors, where the underlying genomic abnormalities remain elusive, even when using a dedicated tool for sequencing thymic epithelial tumors.", "authors": ["Pardini Eleonora", "Cucchiara Federico", "Barachini Serena", "Montali Marina", "Sardo Infirri Gisella", "Burzi Irene Sofia", "Maestri Michelangelo", "Guida Melania", "Ricciardi Roberta", "Nicolì Vanessa", "Coppedè Fabio", "Bacchin Diana", "Zafira Carmelina Cristina", "Aprile Vittorio", "Melfi Franca", "Lucchi Marco", "Petrini Iacopo"], "journal": "Thoracic cancer", "entry_date": "2025/12/17 08:17", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41405018/", "pub_types": ["Journal Article"], "affiliations": ["Department of Translational Research and New Surgical and Medical Technologies, University of Pisa, Pisa, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "41404264", "title": "Post-COVID Myoclonus-Ataxia Syndrome: A Case Report of Successful Recovery With Intravenous Immunoglobulin (IVIG) Treatment.", "abstract": "The SARS-CoV-2 virus responsible for COVID-19 can trigger multisystemic syndromes that persist beyond the acute infection. Among these, neurological complications have become increasingly recognized. Reported outcomes include headaches, encephalitis, encephalopathy, anosmia, ageusia, Guillain-Barré syndrome, and skeletal muscle involvement such as myalgia and myasthenia gravis. Myoclonus-ataxia syndrome has emerged as a rare post-infectious complication. We describe an immunocompetent adult who developed post-COVID-19 myoclonus-ataxia with a distinct post-infectious timeline. The patient had minimal response to corticosteroids but experienced rapid and marked recovery with intravenous immunoglobulin (IVIG). Delayed access to IVIG due to insurance limitations prolonged disease progression. This case underscores the importance of individualized treatment strategies in post-COVID neurological syndromes and highlights the impact of systemic healthcare barriers. Given the rarity of this presentation and the variable treatment responses observed, this report contributes to the understanding of post-COVID neurological complications and their management.", "authors": ["Babar Maryam", "Arain Aymen", "Hamide Ali", "Rashid Razi"], "journal": "Cureus", "entry_date": "2025/12/17 04:42", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41404264/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["College of Medicine, Edward Via College of Osteopathic Medicine, Monroe, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41403966", "title": "Ectopic thymoma arising in the pleura: Diagnostic challenges and clinical implications: A case report.", "abstract": "Thymoma is a rare tumor originating from the thymic epithelium, typically located in the anterior mediastinum. Ectopic thymomas are extremely uncommon and may occur in the neck, middle or posterior mediastinum, lung, or pleura. We report the case of a 62-year-old woman presenting with cough, weight loss, and asthenia. Chest computed tomography (CT) revealed a right pleural mass. Complete surgical resection was performed, and the postoperative diagnosis confirmed a WHO Type AB thymoma, classified as Masaoka-Koga stage IIa. Following surgery, she underwent adjuvant radiotherapy, and no recurrence was observed during follow-up.", "authors": ["Dezio Michele", "De Lucia Diletta", "Diego Mario Di", "Dattoli Roberta", "Laterza Fabio", "Marini Stefania", "Calabrese Angela", "Cozzolino Monica", "Pisani Antonio Rosario", "Laera Letizia", "Calbi Roberto"], "journal": "Radiology case reports", "entry_date": "2025/12/17 04:39", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41403966/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Radiology Unit, Ente Ecclesiastico Ospedale Generale Regionale \"F.Miulli\" Acquaviva delle Fonti, Bari, Italy."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41402829", "title": "The prognosis of MG patients with different thymic pathology: a multicenter retrospective cohort study.", "abstract": "BACKGROUND: To identify the associations between thymic pathology and the prognosis of myasthenia gravis (MG) patients.\nMETHODS: In this multicenter retrospective study, 1,254 myasthenia gravis (MG) patients who underwent thymectomy across four clinical centers were included. Participants were categorized by thymic pathology into thymomatous and non-thymomatous groups. Primary outcome was postoperative deterioration. Secondary outcomes comprised the proportion of patients achieving minimal manifestation status (MMS) within the first year after surgery and conversion from ocular MG (OMG) to generalized MG (GMG) within 2 years of symptom onset. Subgroup analyses assessed associations between world health organization (WHO) pathological type (both groups) or Masaoka stage (thymoma patients) and prognosis.\nRESULTS: Thymomas were associated with an increased risk of deterioration in both Cox regression (adjusted HR = 1.40 [1.18, 1.66], p < 0.001) and logistic regression analyses (1-year deterioration: adjusted OR = 1.59 [1.15, 2.20], p = 0.005; 3-year deterioration: adjusted OR = 1.40 [1.01, 1.94], p = 0.047). Additionally, thymomas were linked to a higher conversion rate (adjusted OR = 2.37 [1.15, 4.86], p = 0.019). However, thymoma showed no significant association with MMS (adjusted p = 0.682). In the thymoma subgroup, neither pathological type nor Masaoka stage was significantly associated with deterioration (pathological type: 1-year p = 0.069, 3-year p = 0.220; Masaoka stage: 1-year p = 0.944, 3-year p = 0.909), first-year MMS attainment (pathological type: p = 0.067; Masaoka stage: p = 0.579), or conversion rate (pathological type: p = 0.606; Masaoka stage: p = 0.163). Similarly, in the nonthymomatous group, WHO pathological type was not significantly correlated with deterioration (1-year p = 0.806, 3-year p = 0.654), MMS achieved (p = 0.940), or conversion (p = 0.755).\nCONCLUSIONS: This study demonstrated an association between thymoma and higher risks of clinical deterioration, which was independent of WHO pathological type or Masaoka stage.", "authors": ["Fan Moli", "Zhang Hao", "Shi Yutong", "Huang Xiaoyu", "Cui Ying", "Yu Zihao", "Zhang Xiao-He", "Zhang Xiao-Jing", "Xue Ying-Ping", "Huang Lei", "Shi Fu-Dong", "Qi Guo-Yan"], "journal": "BMC medicine", "entry_date": "2025/12/16 23:42", "pub_date": "2025-12-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41402829/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.3, "journal_quartile": "1区"}, {"pmid": "41399565", "title": "Collapsing Focal Segmental Glomerulosclerosis With Anti-nephrin Antibody Following Minimal Change Disease Possibly Triggered by COVID-19 Infection: A Case Report.", "abstract": "A man in his forties experienced foamy urine after COVID-19 infection and received a kidney biopsy. He received tacrolimus for myasthenia gravis; no kidney disease was noted before COVID-19 infection, and he had no family history of kidney disease. The biopsy showed minimal change disease, characterized by IgG deposition in the podocyte and mesangial areas. Prednisone was started at 70 mg, but he required hemodialysis three months after COVID-19 infection. A second biopsy 15 months after the COVID-19 infection showed collapsing focal segmental glomerulosclerosis (FSGS) with IgG deposition in the podocytes and mesangium. Immunofluorescence imaging of the second biopsy using structure illumination microscopy showed decreased nephrin expression and punctuate IgG deposition colocalized with nephrin. Thereafter, his serum was positive for anti-nephrin antibodies (367 IU/ml, cut-off 226 U/ml). To the best of our knowledge, no other reports of collapsing FSGS or minimal change disease with anti-nephrin antibodies triggered by COVID-19 infection have been published. This case summarizes a novel case of collapsing FSGS with IgG-positive podocytes associated with anti-nephrin antibodies following minimal change disease, possibly triggered by COVID-19 infection. Further study is needed to clarify the mechanism by which anti-nephrin antibodies are produced by COVID-19 infection.", "authors": ["Oguchi Hideyo", "Shirai Yoko", "Miura Kenichiro", "Hattori Motoshi", "Hamasaki Yuko", "Muramatsu Masaki", "Honda Kazuho", "Mikami Tetuo", "Tochigi Naobumi", "Sakai Ken"], "journal": "Cureus", "entry_date": "2025/12/16 04:06", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41399565/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Deparment of Nephrology, Faculty of Medicine, Toho University, Tokyo, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41396134", "title": "Portuguese Consensus Guidelines for the Diagnosis and Treatment of Myasthenia Gravis.", "abstract": "Myasthenia gravis is an autoimmune disease that affects the neuromuscular junction, mainly through the action of pathogenic antibodies such as those directed against the nicotinic acetylcholine receptor or, more infrequently, against the muscle specific kinase. Other important components of the autoimmune process include the complement pathway and B and T cell populations. Diagnosis is based on the finding of fatigable muscle weakness, which can affect several muscle groups, either in isolation or in variable combinations. Neurophysiological techniques and/or the detection of pathogenic antibodies in serum are also essential for the diagnosis of myasthenia gravis. Maintenance treatment was traditionally based on corticosteroids and non-steroidal immunosuppressants. Recently approved drugs, such as the terminal complement pathway inhibitors and the neonatal Fc receptor antagonists, are reshaping the treatment landscape, supported by robust evidence of an excellent combination of efficacy and safety. Although several international guidelines have been published in the last decade, some key questions remain without precise guidance. Hence, a group of nine experts from the Portuguese Neuromuscular Society has elaborated consensus guidelines that aim to provide detailed guidance on diagnostic workup and treatment, grounded both in published evidence and in clinical experience. Key novel aspects include step-by-step instructions for diagnostic workup, a set of diagnostic criteria, guidance on the use of complement inhibitors and neonatal Fc receptor antagonists, and tailored treatment algorithms according to antibody subgroup and clinical severity.", "authors": ["Cruz Simão", "Matos Anabela", "Braz Luís", "Falcão Campos Catarina", "Cerqueira João", "Medeiros Luísa", "Santos Ernestina", "Santos Luís", "Veiga Andreia"], "journal": "Acta medica portuguesa", "entry_date": "2025/12/15 10:43", "pub_date": "2026-01-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41396134/", "pub_types": ["Journal Article", "Practice Guideline", "Consensus Statement"], "affiliations": ["Serviço de Neurologia. Unidade Local de Saúde Amadora/Sintra. Amadora. Portugal."], "china_related": false, "study_types": ["Guideline/Consensus"], "evidence_level": null, "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41395551", "title": "Atezolizumab-induced myasthenia gravis and myositis: a fatal case report and review of the literature.", "abstract": "Immune checkpoint inhibitors can cause immune-related adverse events, with neurologic manifestations such as myasthenia gravis (MG) and myositis predominantly reported with PD-1 inhibitors, while cases linked to PD-L1 inhibitors remain rare. An 84-year-old man with hepatocellular carcinoma developed severe MG and myositis after atezolizumab treatment. Despite intensive therapy, including corticosteroids, plasma exchange, and intravenous immunoglobulin, his condition worsened, and he died. MG in cancer patients poses treatment challenges due to tumor progression and functional decline. Given the limited reports on atezolizumab-induced MG, further case accumulation is essential to improve understanding of its clinical course and optimize management strategies.", "authors": ["Kobayashi Yuya", "Nagamatsu Kiyoshiro", "Shimizu Yusaku", "Nakayama Ataru", "Sekijima Yoshiki"], "journal": "International cancer conference journal", "entry_date": "2025/12/15 06:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41395551/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Ina Central Hospital, 1313-1 Koshirokubo, Ina, 396-0033 Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 6.0, "journal_quartile": "2区"}, {"pmid": "41395452", "title": "Nipocalimab-aahu in generalised myasthenia gravis: A new Fc receptor-targeted option for antibody-positive patients.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder driven by pathogenic IgG autoantibodies, leading to muscle weakness and impaired quality of life. Conventional immunosuppressant therapies are often limited by side effects and incomplete efficacy. Nipocalimab-aahu (N-a), recently FDA-approved, is a novel neonatal Fc receptor (FcRn) antagonist that reduces circulating IgG levels, targeting the underlying disease mechanism. This review synthesizes evidence on N-a's efficacy, safety, and clinical positioning. Phase 2 and 3 trials (Vivacity-MG/MG3) demonstrated that N-a significantly improves the Myasthenia Gravis Activities of Daily Living (MG-ADL) score compared to placebo, with a favorable safety profile. The most common adverse events were nasopharyngitis and headache, with no increased serious infection risk or clinically significant hypoalbuminemia. Compared to other biologics, N-a offers a distinct mechanism, selective IgG reduction without broad immunosuppression and a convenient bi-weekly dosing regimen. While it shows promise for reduced systemic immunosuppression and potentially greater efficacy in MG-ADL improvement than some alternatives, cross-trial comparisons are limited. Key limitations include the need for long-term safety data and more research in underrepresented populations, including pediatric and seronegative patients. In conclusion, N-a represents a significant advancement in generalized MG (gMG) treatment, providing a targeted, effective, and well-tolerated option that addresses a key unmet need for patients with acetylcholine receptor (AChR) or muscle-specific kinase (MuSK) antibody-positive disease.", "authors": ["Hussain Jawairya Muhammad", "Ashfaq Anoosha", "Shahid Azka", "Mudassir Fatima"], "journal": "Ibrain", "entry_date": "2025/12/15 06:32", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41395452/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine Karachi Medical and Dental College Karachi Pakistan."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 0.4, "journal_quartile": "3区"}, {"pmid": "41394837", "title": "Rituximab for refractory ocular symptoms in myasthenia gravis with thyroid eye disease: a case report with quantitative MRI assessment.", "abstract": "AIMS: To report a case with concurrent myasthenia gravis (MG) and thyroid eye disease (TED) showing response to rituximab (RTX) through both clinical evaluation and quantitative MRI assessment.\nMETHODS: A 31-year-old female patient with refractory ocular symptoms from concurrent MG and TED received RTX after failing multiple conventional treatments. Treatment response was evaluated through clinical scores and quantitative T2 mapping of extraocular muscles (EOMs) before and after RTX administration.\nRESULTS: Following RTX treatment, the patient achieved corticosteroid-free remission by six months post-RTX, with Myasthenia Gravis Activities of Daily Living score decreasing from 5 to 0, complete resolution of ptosis, and improvement in ocular motility and exophthalmos. Quantitative T2 mapping demonstrated significant reductions in T2 relaxation times (10.6%-20.9%) across all EOM regions of interest, with decreased standard deviations indicating restored tissue homogeneity.\nCONCLUSIONS: This case suggests potential therapeutic benefit of RTX for refractory ocular symptoms in concurrent MG and TED. Quantitative T2 mapping revealed pathologically elevated values that normalized post-treatment, providing preliminary objective evidence of treatment response. As a single case, the relative contributions of MG versus TED pathology cannot be definitively separated. Integrating clinical assessment with quantitative T2 mapping may offer an objective approach for monitoring treatment response in such complex dual autoimmune disorders.", "authors": ["He Dingxian", "Li Xiangwen", "Wang Baitong", "Wang Yaqi", "Yan Chong", "Liu Mengxiao", "Hibert Tom", "Luo Sushan", "Zhao Chongbo", "Xi Jianying"], "journal": "Frontiers in immunology", "entry_date": "2025/12/15 06:27", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41394837/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41394836", "title": "Efgartigimod for the treatment of immune checkpoint inhibitor-associated myocarditis complicated with impending crisis state of myasthenia gravis: a case report.", "abstract": "Immune checkpoint inhibitor (ICI)-associated myocarditis is a rare yet life-threatening immune-related adverse event (irAE), whose management is even more challenging when complicated by an impending crisis of myasthenia gravis (MG). This article presents a case of a 69-year-old woman with bladder malignancy, coexisting MG, diabetes, hypertension, and coronary artery disease. On day 16 after tislelizumab (PD-1 inhibitor) therapy, she exhibited aggravated MG symptoms, with an impending crisis, alongside asymptomatic ICI-associated myocarditis. Clinical manifestations included generalized fatigue, anorexia, bilateral ptosis, dysarthria, neck and limb weakness, shortness of breath, and dyspnea. Laboratory tests revealed elevated troponin T, troponin I, creatine kinase (CK), creatine kinase-myocardial band (CK-MB), aspartate aminotransferase (AST), and alanine aminotransferase (ALT) levels, suggesting a diagnosis of ICI-associated myocarditis and liver injury. Doppler ultrasound indicated thrombosis in the left calf muscle space. Treatment with efgartigimod (10 mg/kg) significantly improved myasthenic symptoms, with Myasthenia Gravis-Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG) scores decreasing from 11 to 5 and 26 to 11, respectively. Treatment with prednisone acetate (60 mg once daily) resulted in gradual reductions in myocardial enzymes, troponins, and transaminases. Efgartigimod demonstrated notable efficacy as salvage therapy for ICI-associated myocarditis, myositis, liver injury, and impending crisis of MG. Early recognition and tailored treatment strategies are crucial for improving patient outcomes in such complex cases.", "authors": ["Lu Mingjia", "Muhetaer Ayikemaier", "Su Chenxi", "Dong Meng", "Aili Kariman", "Sha Jing", "Aimudula Kaidierya", "Abudureheman Kailibinuer", "Mamat Maynur", "Li Hongyan"], "journal": "Frontiers in immunology", "entry_date": "2025/12/15 06:27", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41394836/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neuroimmunology Department, Neurology Diagnosis and Treatment Center, People's Hospital of Xinjiang Uygur Autonomous Region, Urumqi, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41394288", "title": "CAR T-cell therapy for neurological disorders: scientific rationale and mechanistic insights.", "abstract": "The development and successful clinical application of engineered T cells expressing synthetic chimeric antigen receptors (CARs) represents a milestone in cancer therapy. This approach optimizes physiological in vivo T-cell activation against specific target antigens expressed on defined cell subsets with the goal of their deep and sustained depletion. Significant progress has been made in redesigning CAR T-cell constructs to improve patient safety, therapeutic efficacy, and accessibility. Efforts have also focused on streamlining manufacturing to improve availability and reduce costs, two critical challenges to widespread adoption. Beyond hematologic malignancies, CAR T-cell therapies are now increasingly being repurposed to tackle B-cell-mediated autoimmune diseases (AIDs). This is primarily achieved through broad B-cell depletion, but more targeted approaches-such as the selective elimination of autoantibody-producing B-cell subpopulations-are also being explored. Important considerations in their implementation are identifying the most pertinent patient groups, tailoring their treatment up to the point of CAR-infusion, and following up on their unique toxicity-profile. In the context of neurological AIDs-including refractory myasthenia gravis, Lambert-Eaton syndrome, multiple sclerosis, and stiff-person syndrome-early clinical experience suggests promising efficacy and tolerability, leading to a growing number of registered clinical trials. In this review, we provide an overview of the mechanism and evolution of CAR T-cell therapy, highlighting why its application in AIDs, particularly in neurology, represents a highly promising therapeutic strategy.\nHow CAR T-cell therapy could help treat neurological disorders CAR T-cell therapy has revolutionized cancer treatment by engineering a patient’s own immune cells to recognize and destroy harmful cells. Initially developed for blood cancers, this therapy is now being explored for autoimmune diseases, particularly neurological disorders like multiple sclerosis, myasthenia gravis, and stiff-person syndrome. The main way CAR T-cells work in autoimmune diseases is by targeting and eliminating B cells, which play a key role in driving these conditions. Unlike traditional treatments, which often require continuous medication, CAR T-cell therapy has the potential to reset the immune system with long-lasting effects. Early clinical experiences have been promising, showing that CAR T-cell therapy can lead to deep and sustained disease remission. Importantly, the therapy appears to be well tolerated, with fewer severe side effects than in cancer patients. Research is now focusing on optimizing safety, accessibility, and effectiveness to bring this innovative therapy to more patients. By learning from cancer immunotherapy, scientists aim to refine CAR T-cell treatment for neurological autoimmune diseases, potentially offering a transformative new option for patients who have not responded to conventional therapies.", "authors": ["Katsaros Dimitrios E", "Mougiakakos Dimitrios"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/12/15 06:17", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41394288/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Hematology, Oncology, and Cell Therapy, Otto-von-Guericke University Magdeburg, Magdeburg, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41394139", "title": "Ofatumumab-mediated CD20+ B-cell depletion promotes neuromuscular junction functional recovery and sustains long-term efficacy in refractory generalized myasthenia gravis.", "abstract": "OBJECTIVE: This study aimed to evaluate the long-term efficacy and safety of the fully human anti-CD20 monoclonal antibody ofatumumab in refractory generalized myasthenia gravis, with focus on its potential to promote recovery of neuromuscular junction transmission function.\nMETHODS: Fourteen refractory patients treated at the Eighth Medical Center of the Chinese PLA General Hospital from March 2023 to June 2024 were included. All had relapsed after maintaining Minimal Manifestation Status for over 1 year and showed inadequate response to immunosuppressants. Ofatumumab 20 mg was administered at weeks 0, 1, 2, and 4, followed by additional doses every 4-6 months according to symptoms and CD19-positive B-cell reconstitution. Low-frequency 3-Hz repetitive nerve stimulation of the facial, accessory, and axillary nerves was conducted at baseline and month 12. MG-ADL, QMG, MGC scores and B-cell and T-cell levels were monitored.\nRESULTS: The compound muscle action potential (CMAP) decrement of the predominantly involved nerve and the mean decrement across the three tested nerves improved at month 12, indicating enhanced neuromuscular junction transmission. MG-ADL, QMG, and MGC scores declined from month 1, with earlier improvement in bulbar, limb, and neck muscle groups. All patients discontinued corticosteroids by month 12 while remaining clinically stable. B cells stayed at low levels, whereas T-cell counts showed no significant change. Treatment was well tolerated.\nCONCLUSION: Ofatumumab provides durable clinical benefit and steroid-sparing effects, and its sustained depletion of CD20-positive B cells may facilitate recovery of neuromuscular junction transmission. These findings support its potential application within the field of regenerative pharmacology.", "authors": ["Ren Zhuangzhuang", "Chen Yuping", "Liu Yudan", "Wang Yan", "Xu Shengjie", "Yang Yanhua", "Qiu Feng"], "journal": "Frontiers in pharmacology", "entry_date": "2025/12/15 06:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41394139/", "pub_types": ["Journal Article"], "affiliations": ["Senior Department of Neurology, Chinese PLA Hospital, Beijing, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41393996", "title": "Clinical characteristics of myasthenia gravis patients with coexistence of AChR and titin antibodies.", "abstract": "OBJECTIVE: This study aimed to investigate the clinical characteristics of patients with myasthenia gravis (MG) who are double-seropositive for acetylcholine receptor antibodies (AChR-Ab+) and titin antibodies (Titin-Ab+).\nMETHODS: A retrospective analysis was conducted on MG patients hospitalized in the Department of Neurology between March 2020 and June 2024. Patients were categorized into two groups based on antibody profiles: those with AChR antibody positivity alone and those with dual positivity for AChR and titin antibodies. Clinical features, MG classification, and treatment outcomes were compared between the two groups.\nRESULTS: A total of 35 MG patients were included, comprising 18 with single AChR-Ab+ and 17 with AChR-Ab+/Titin-Ab+. The dual antibody-positive group showed a significantly higher proportion of patients with MGFA classification above Class II (47.1%) and a higher rate of thyroid dysfunction (50%) compared to the single antibody-positive group (p = 0.001). The median age of onset in the dual antibody-positive group was older than that in the single antibody-positive group (67.0 years vs. 58.5 years), although this difference was not statistically significant (p > 0.05). No significant differences were observed between the two groups in terms of gender, initial symptoms, clinical manifestations, thymic hyperplasia, proportion of thymoma, treatment regimens, or therapeutic outcomes (all p > 0.05).\nCONCLUSION: This study provides the first systematic characterization of the clinical profile of AChR-Ab+/Titin-Ab+ myasthenia gravis patients in Southwest China. Our findings indicate that dual antibody-positive MG patients are more prone to generalized disease involvement and have a higher susceptibility to thyroid dysfunction.", "authors": ["Wang Siqi", "Shi Difang", "Wu Shanshan", "Zhang Qijie", "Xiao Weiwei", "Qian Fang", "Zheng Yan", "Bao Jianjian", "Liu Jia", "Chu Xujun", "Du Kang"], "journal": "Frontiers in neurology", "entry_date": "2025/12/15 06:14", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41393996/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Pharmacy, Yunnan Qujing Central Hospital (Qujing First People's Hospital), Qujing, Yunnan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41393647", "title": "Triple M Syndrome After Immune Checkpoint Inhibition: A Rare and Life-Threatening Triad of Myocarditis, Myositis, and Myasthenia Gravis.", "abstract": "Triple M syndrome is a well-known complication of pembrolizumab and other immune checkpoint inhibition (ICI) therapy that entails three components, namely, myocarditis, myositis, and myasthenia gravis, which can present independently or as part of an overlap syndrome.  We present the case of an 80-year-old patient with stage 3C non-small cell lung carcinoma who complained of bulbar and ocular symptoms after the second cycle of pembrolizumab. Based on the integrated clinical picture and comprehensive biochemical markers, a provisional diagnosis of triple M syndrome was established. The patient was initiated on immunomodulatory therapy consisting of intravenous methylprednisolone and intravenous immunoglobulin (IVIG), administered over a five-day course. Despite first-line immunotherapy, the patient's condition deteriorated within four days of hospital admission. Plasmapheresis was considered but deemed unfeasible due to being too unstable to transfer to the tertiary centre to provide this. Given the lack of therapeutic response, the multidisciplinary team, in agreement with the patient's family, elected to transition the goals of care toward palliation and symptom-focused management. This case report, together with previous reports, underscores the critical importance of maintaining a high index of suspicion for triple M syndrome and initiating prompt intervention in patients receiving ICI therapy. Early identification and timely management are essential for optimizing clinical outcomes and are pivotal in preventing mortality.", "authors": ["Albastaki Eman", "Rishu Rishu", "Tun Yati", "Abdullah Alend", "Bhattacharjee Shakya"], "journal": "Cureus", "entry_date": "2025/12/15 06:11", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41393647/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Acute Medicine, The Dudley Group NHS Foundation Trust, Dudley, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41389129", "title": "Oral Corticosteroid and Nonsteroidal Immunosuppressant Therapy Use in Patients with Myasthenia Gravis Receiving Ravulizumab, Eculizumab, or Efgartigimod in the USA.", "abstract": "INTRODUCTION: Oral corticosteroids (OCSs) and nonsteroidal immunosuppressant therapies (NSISTs) remain widely used for the clinical management of patients with generalized myasthenia gravis (gMG), despite well-documented risks. Newer targeted biologic therapies have demonstrated concomitant immunosuppressant therapy reduction; however, long-term comparative real-world evidence remains limited. This retrospective, observational study compared OCS and NSIST use in patients in the USA receiving one of the following US Food and Drug Administration-approved therapies for gMG treatment: ravulizumab or eculizumab (complement protein C5 inhibitor therapies [C5ITs]) or efgartigimod (neonatal Fc receptor antagonist).\nMETHODS: Patients were identified using the IQVIA PharMetrics® Plus claims database from January 1, 2015 to March 31, 2024. Eligible patients had ≥ 2 MG claims filed ≥ 30 days apart by a nonophthalmologic specialist. Treatment index date was the date of first ravulizumab, eculizumab, or efgartigimod claim. All patients assessed were continuously treated with ravulizumab, eculizumab, or efgartigimod during the 12-month follow-up period. Baseline OCS dose was estimated using claims data 3 months before the index date. Change from baseline in OCS average daily dose (ADD), OCS tapering, and NSIST use were assessed over 3-month intervals during the 12-month post-index follow-up period.\nRESULTS: After 12 months of continuous treatment, the C5IT cohort experienced a significantly greater mean reduction from baseline in OCS ADD compared to the efgartigimod cohort (C5IT, - 11.2 mg/day; efgartigimod, - 3.6 mg/day; P = 0.034), and fewer patients were taking OCS ADD > 30 mg/day (C5IT, 7.5%; efgartigimod, 22.2%). The percentage of patients with NSIST claims decreased by 28.3% within the first 12 months in the C5IT cohort (baseline, 55.2%; month 12, 39.6%) and remained stable in the efgartigimod cohort (baseline, 48.9%; month 12, 48.9%).\nCONCLUSION: These results from US clinical practice suggest greater reductions in OCS and NSIST concomitant therapy for patients treated with ravulizumab or eculizumab compared with efgartigimod.", "authors": ["Saccà Francesco", "Lee Justin", "Yee Karen S", "Silvestri Nicholas J", "Sabatella Guido"], "journal": "Neurology and therapy", "entry_date": "2025/12/13 11:05", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41389129/", "pub_types": ["Journal Article"], "affiliations": ["GENESIS Department, Federico II University of Naples, Via Sergio Pansini, 5, 80131, Naples, Italy. francesco.sacca@unina.it."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41388640", "title": "Prognosis After Discontinuation of Azathioprine or Mycophenolate Mofetil in Well-Controlled Myasthenia Gravis: A Retrospective Analysis.", "abstract": "INTRODUCTION/AIMS: Azathioprine (AZA) and mycophenolate mofetil (MMF) are generally used for long periods when treating myasthenia gravis. In well-controlled patients, discontinuation of AZA/MMF may be a cause for concern because of the possibility of relapse. We aimed to evaluate relapse and relapse-related parameters after discontinuation of AZA/MMF.\nMETHOD: Patients who had discontinued AZA or MMF monotherapy were retrospectively reviewed. We reviewed relapse, whether in pharmacological remission (PR) or exhibiting minimal manifestations (MM 1), disease duration, duration of AZA/MMF use, and other clinical parameters.\nRESULTS: A total of 32 patients were included who either discontinued AZA (n = 28) or MMF (n = 4) treatments. Relapse was detected in 11 (34%). Patients in PR had fewer relapses than those with MM 1 (p = 0.023). Intravenous immunoglobulin was required in four. All patients who relapsed were stabilized with AZA/MMF. No significant association was found between relapse and age of disease onset, duration of disease, duration of AZA/MMF use, thymectomy status, or maximum Myasthenia Gravis Foundation of America score during active disease.\nDISCUSSION: The results of this study suggest that patients in PR are less likely to relapse compared to those in MM 1. In well-controlled MG patients, AZA/MMF may be discontinued.", "authors": ["Ozer Inci Sule", "Kaya Ergi", "Ertürk Ahmet Yusuf", "Sengun Ihsan Sukru"], "journal": "Muscle & nerve", "entry_date": "2025/12/13 01:46", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41388640/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Dokuz Eylul University Medical School, Izmir, Turkey."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41387932", "title": "Human in vitro neuromuscular junction model to functionally dissect the pathogenic mechanism of anti-AChR autoantibody-positive myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis is a rare autoimmune disease mediated by autoantibodies directed against acetylcholine receptors (AChRs) at the neuromuscular junction. These autoantibodies cause dysfunction through AChR blockade, AChR degradation due to crosslinking and internalisation, and complement activation.\nMETHODS: A novel in vitro model of the human neuromuscular junction was established on a microfluidic platform to investigate the effect of anti-AChR autoantibodies on complement activation and neuromuscular transmission and the mechanism of action of complement inhibition in myasthenia gravis. The NeuroMuscleTM platform enabled the connection of human induced pluripotent stem-cell-derived motor neuron spheroids with three-dimensional cultures of skeletal muscle fibres, forming functional neuromuscular junctions. Functional connectivity was assessed by glutamate stimulation of motor neuron spheroids and monitoring of calcium transients in genetically encoded calcium indicator protein 6 (GCaMP6)-transduced muscle fibres.\nRESULTS: Incubation of in vitro neuromuscular junction tissues with sera from patients with anti-AChR autoantibody-positive myasthenia gravis, in contrast to healthy controls, induced a significant increase in membrane attack complex (MAC) deposition and complement split products, accompanied by a notable reduction in calcium transients. Treatment with zilucoplan, a complement component 5 (C5) inhibitor, prevented complement activation and preserved neuromuscular junction functional integrity. The model demonstrated that complement-mediated damage is a major driver of neuromuscular junction functional impairment in the myasthenia gravis patient sera tested in this study. Furthermore, the study explored the reversibility of neuromuscular junction damage, revealing that shortening the delay before initiating complement inhibitor treatment in the in vitro neuromuscular junction tissues enhances the reversibility of neuromuscular transmission.\nCONCLUSIONS: These findings offer a mechanistic rationale for the observed clinical response in patients with anti-AChR autoantibody-positive myasthenia gravis treated with C5 inhibitors. The in vitro neuromuscular junction model provides a robust platform for studying the mechanistic pathways of complement-mediated damage and evaluating therapeutic interventions for myasthenia gravis.", "authors": ["Shin Baehyun", "Wang Monica", "Yim John", "Kwon Elisa", "Magdesian Margaret H", "Sayegh Camil E", "Ekert Jason E", "Vadysirisack Douangsone D"], "journal": "BMC pharmacology & toxicology", "entry_date": "2025/12/12 23:40", "pub_date": "2025-12-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41387932/", "pub_types": ["Journal Article"], "affiliations": ["UCB, 87 Cambridgepark Dr, Cambridge, MA, 02140, USA. baehyun.shin@ucb.com."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41383535", "title": "The Use of Parabulbar and Sub-Tenon Injections to Correct Isolated Resistant Diplopia in Patients With Generalized Myasthenia Gravis: A Long Road to Clinically Meaningful Success.", "abstract": "Parabulbar betamethasone provided rapid and durable relief of isolated, treatment-resistant diplopia in seronegative myasthenia gravis after multiple systemic therapy failures, suggesting that targeted periocular corticosteroid delivery may be a steroid-sparing option for carefully selected patients when standard treatments are ineffective and close ophthalmic monitoring is available.", "authors": ["Marchuk M", "Sanin V", "Mamilov V", "Zinchenko M"], "journal": "Clinical case reports", "entry_date": "2025/12/12 04:28", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41383535/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology Bogomolets National Medical University Kyiv Ukraine."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41379101", "title": "Discovery of Zilucoplan: A Complement C5 Inhibitor for Treatment of Anti-Acetylcholine Receptor (AChR) Antibody-Positive Generalized Myasthenia Gravis (gMG).", "abstract": "Complement component 5 (C5) is a protein in the complement cascade and a part of the innate immune system that has been clinically validated as a therapeutic target for several immune-mediated diseases including generalized myasthenia gravis (gMG). In this paper, we discuss the early discovery of zilucoplan, a macrocyclic peptide drug, which was identified via innovative extreme diversity mRNA display (Ma, Z.; Hartman, M. C. T. In Vitro Selection of Unnatural Cyclic Peptide Libraries via mRNA Display. In Ribosome Display and Related Technologies: Methods and Protocols; Douthwaite, J. A., Jackson, R. H., Eds.; Springer: New York, 2012; pp 367-390.) against C5 and approved for the treatment of gMG. We highlight the key steps and rationale behind the peptide medicinal chemistry optimization of the initial screening hits, that led to improved potency, stability, and pharmacokinetic properties.", "authors": ["Ye Ping", "Hammer Robert P", "Wang Zhaolin", "Dhamnaskar Ketki", "Hoarty Michelle", "Ma Zhong", "Tang Guo-Qing", "DeMarco Steven J", "Ricardo Alonso"], "journal": "Journal of medicinal chemistry", "entry_date": "2025/12/11 10:53", "pub_date": "2025-12-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41379101/", "pub_types": ["Journal Article"], "affiliations": ["UCB Bioscience, Cambridge, Massachusetts 02140, United States."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 6.8, "journal_quartile": "1区"}, {"pmid": "41377446", "title": "Nipocalimab: a significant milestone in the treatment of myasthenia gravis approved by the FDA.", "abstract": "Nipocalimab is a newly approved therapeutic agent that modulates a distinct immune transport pathway and has shown considerable promise in treating patients with motor impairment stemming from dysregulated antibody responses. Cleared for use in individuals aged 12 and older, this biology marks a notable advancement in managing many autoimmune conditions, including myasthenia gravis which exists in 150-200 individuals per million. The results of nipocalimab in patients with the latter condition were read in peer-reviewed literature and clinical trial data and key outcomes were extracted. The disease in focus is characterized by fluctuating muscular weakness and reduced endurance due to immune system disruption at the neuromuscular interface. While existing interventions offer some relief, many are limited by side effects or suboptimal long-term control, underscoring the need for better-targeted therapies. Interrupting the mechanism that prolongs the circulation of specific immune proteins presents a refined strategy to lower pathogenic activity while maintaining overall immunological integrity. This compound disrupts the cellular routing system involved in antibody preservation, leading to a selective decline in disease-associated immunoglobulins while leaving protective antibodies largely unaffected. Clinical studies across healthy and affected populations have demonstrated a favorable safety record and meaningful biological responses, including enhanced physical functioning. Late-stage trials have confirmed significant improvements in key health parameters, reinforcing the agent's therapeutic value. This biology introduces a more precise, well-tolerated, and durable option for treating myasthenia gravis.", "authors": ["Irfan Sonia", "Sana Mawiya", "Haque Md Ariful"], "journal": "Annals of medicine and surgery (2012)", "entry_date": "2025/12/11 05:21", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41377446/", "pub_types": ["Editorial"], "affiliations": ["Shaikh Khalifa Bin Zayed Al Nahyan Medical and Dental College, Lahore, Punjab, Pakistan."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41376973", "title": "Feasibility of establishing a nude mouse model of thymoma-associated myasthenia gravis.", "abstract": "BACKGROUND: The pathogenesis of thymoma-associated myasthenia gravis (TAMG) remains unclear, and one of the key problems is the lack of an appropriate animal model. The present study aimed to investigate the feasibility of establishing an animal model of TAMG.\nMETHODS: Patient thymoma tissue specimens were transplanted into the left renal subcapsules of BALB/c nude mice under sterile conditions. The content of T lymphocytes and subsets, as well as total complement, in the mouse peripheral blood was detected using flow cytometry and enzyme-linked immunosorbent assay (ELISA) prior to and following transplantation. Furthermore, the tumor tissues were analyzed by immunohistochemistry (IHC).\nRESULTS: Transplanted thymoma tissues survived in the mice with a success rate of 61%. Flow cytometry results indicated that the percentage of cluster of differentiation CD3+ and CD4+ T cells in the peripheral blood post-transplantation was significantly higher compared with pre-transplantation. By contrast, the percentage of CD8+ T cells and total complement cells was significantly reduced post-transplantation compared with pre-transplantation (P<0.05).\nCONCLUSIONS: This preliminary study demonstrates the feasibility of establishing an animal model for thymoma and myasthenia gravis (MG) pathogenesis research by transplanting human thymoma tissues into BALB/c nude mice. Nevertheless, several issues and challenges must be resolved and investigated in future research.", "authors": ["Zhang Jun", "Yan Yijie", "Guan Zhiyu"], "journal": "Journal of thoracic disease", "entry_date": "2025/12/11 05:18", "pub_date": "2025-11-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41376973/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, The Second Hospital of Tianjin Medical University, Tianjin, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41373880", "title": "Autoimmune Neuromuscular Disorders at a Molecular Crossroad: Linking Pathogenesis to Targeted Immunotherapy.", "abstract": "Myasthenia gravis, chronic inflammatory demyelinating polyneuropathy, and idiopathic inflammatory myopathies are among the most widely recognized autoimmune neuromuscular disorders. Although they differ in clinical presentation, shared immunopathogenic mechanisms place them at a molecular crossroads. Evidence of overlapping pathways has led to the development of targeted strategies including complement inhibition, FcRn antagonism, B-cell depletion, and the CAR-T cell approach. In this review, we analyze current knowledge regarding pathogenic mechanisms and their link to immunotherapy, extensively outlining both similarities and distinctions. We further discuss existing challenges, including diagnostic limitations and refractory disease variants, how technological advances have already addressed some of these issues, and where further progress is still needed.", "authors": ["Florea Anca-Maria", "Luca Dimela-Gabriela", "Davidescu Eugenia Irene", "Popescu Bogdan-Ovidiu"], "journal": "International journal of molecular sciences", "entry_date": "2025/12/11 01:03", "pub_date": "2025-12-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41373880/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Clinical Neurosciences, \"Carol Davila\" University of Medicine and Pharmacy, 050474 Bucharest, Romania."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "41368056", "title": "Myasthenia Gravis in a Child With Schimke Immuno-Osseous Dysplasia: A Case Report.", "abstract": "We report a rare association between Schimke immune-osseous dysplasia and myasthenia gravis. Clinicians should be aware of potential autoimmune neuromuscular complications in SIOD, as early recognition and tailored immunosuppression may improve prognosis.", "authors": ["Al Riyami Mohamed S", "Al Alawi Intisar", "Al Riyami Maisa", "Al Gaithi Badria", "Al Saidi Suliman", "Al Shuaili Ibtisam", "Al Kalbani Naifain", "Al Maki Nabil"], "journal": "Clinical case reports", "entry_date": "2025/12/10 04:50", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41368056/", "pub_types": ["Journal Article"], "affiliations": ["Pediatric Nephrology Unit, Department of Child Health Royal Hospital Muscat Oman."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41368047", "title": "Use of rituximab for fulminant and refractory cases of immune checkpoint inhibitor induced myocyte injury clinically presenting with features of myasthenia gravis: a case series.", "abstract": "BACKGROUND: Immune checkpoint inhibitor-related overlap syndromes are serious and potentially life-threatening complications of immunotherapy. The available evidence is scarce to guide treatment for refractory cases, and patients often experience poorer outcomes.\nCASE SUMMARY: We describe two patients who presented with non-specific symptoms of fatigue and weakness. Both exhibited biomarker evidence of skeletal muscle and myocardial injury, along with clinical features suggestive of myasthenia gravis. The patients rapidly deteriorated, requiring admission to the intensive care unit and eventual intubation due to worsening respiratory status. Despite treatment with high-dose intravenous steroids, there was no significant clinical improvement, although early reductions in biomarker levels were observed. This led to the administration of additional therapies, including intravenous immunoglobulin and plasmapheresis, but these interventions were also ultimately ineffective. All testing for myasthenia gravis returned negative, highlighting how patients with primary myositis or overlap myositis with myocarditis can present with bulbar symptoms that closely mimic those of myasthenia gravis. Following multidisciplinary discussions, rituximab was initiated in both cases, which led to successful weaning from mechanical ventilation and eventual discharge.\nDISCUSSION: Our case series highlights how patients with primary myositis or overlap myositis with myocarditis may present with bulbar symptoms that can mimic those of myasthenia gravis. Their clinical course was refractory to initial treatments but improved significantly with rituximab. While current guidelines typically recommend biologic therapies targeting T-cell-mediated immunity, our review of literature found a biological basis for targeting antibody-mediated immunity as well. This approach proved effective, enabling both patients to achieve successful discharge after a prolonged and complex hospitalization, highlighting the importance of considering treatment directed at both T-cell and B-cell immunity.", "authors": ["Aziz Imran Naeem", "Gajjar Rohan", "Nandyal Shreyas", "Oredipe Omotola", "Qaddorah Seba", "Amdetsion Gedion Yilma", "Valencia Javier Gomez", "Tottleben Jonathan"], "journal": "European heart journal. Case reports", "entry_date": "2025/12/10 04:50", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41368047/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, John H Stroger Hospital of Cook County, 1969 W Ogden Avenue, Chicago, IL 60612, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41368039", "title": "Exploring rituximab for the treatment of refractory myasthenia gravis: a single-centre experience.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune disorder that affects neuromuscular transmission, leading to muscle weakness. While most patients respond to standard treatments, approximately 15% remain refractory, prompting interest in alternative therapies. This study examined the use of rituximab in patients with refractory MG at a single centre in Latvia, intending to broaden discussions on treatment strategies.\nMATERIALS AND METHODS: The prospective cohort study was conducted at Pauls Stradiņš Clinical University Hospital from November 2022 to March 2024. Refractory MG was defined as failure to achieve adequate disease control despite standard immunosuppressive therapy, including patients with persistent symptoms, recurrent crises or intolerance to medications. Myasthenia Gravis Composite Score (MGCS), Myasthenia Gravis Activities of Daily Living and Myasthenia Gravis Quality of Life (scores at baseline and monthly for 6 months) were completed. Glucocorticosteroid doses were also recorded. Data were analysed using descriptive statistics and Wilcoxon signed-rank test, considering p<0.05 significant.\nRESULTS: 98 patients with MG were evaluated to identify treatment-refractory cases. A total of nine patients with refractory MG (median disease duration 7 years, range 1-12) were included and received a single low dose of rituximab. Among the nine patients treated, seven were acetylcholine receptor-positive and two were muscle-specific kinase antibody-seropositive. 6 months after treatment, the median MGCS decreased from 11.5 (IQR 7.3-17.8) to 7.5 (IQR 3.8-8.0) (p=0.025). The median daily corticosteroid dose decreased from 15.0 mg (IQR 10.0-20.9) to 8.5 mg (IQR 5.0-12.5) (p=0.036). There were no exacerbations of MG or significant adverse reactions.\nCONCLUSIONS: Our findings suggest that rituximab may be a promising treatment option for refractory MG. The notable clinical benefits and safety profile make rituximab a valuable addition to this challenging autoimmune disorder treatment options. Further research is needed to refine patient selection and dosing for optimal treatment outcomes.", "authors": ["Roddate Marija", "Žukova Violeta", "Grosmane Arta", "Ķauķe Gundega", "Glāzere Ieva", "Punga Anna Rostedt", "Ķēniņa Viktorija"], "journal": "BMJ neurology open", "entry_date": "2025/12/10 04:50", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41368039/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Paul Stradins Clinical University Hospital, Riga, Latvia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41365187", "title": "Steroid-sparing in myasthenia gravis: How much is efgartigimod, and How much is carryover?", "abstract": "", "authors": ["Messina Christian"], "journal": "Journal of the neurological sciences", "entry_date": "2025/12/09 18:09", "pub_date": "2026-01-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41365187/", "pub_types": ["Letter"], "affiliations": ["Azienda Sanitaria Provinciale Catania, Via Santa Maria La Grande, 95100 Catania, Italy. Electronic address: chry.messina@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41364463", "title": "Syncope as a Presenting Symptom of MuSK-Associated Myasthenia Gravis: A Case Report.", "abstract": "ObjectiveDysautonomia in neuromuscular junction disorders is not frequently reported and is not widely recognized. It has been linked to thymoma and several novel antibodies. Yet, autonomic instability can be found even when these features are absent. In MuSK-related myasthenia gravis, clinical autonomic signs have been found in a significant percentage.CaseWe present a report of MuSK-related myasthenia gravis in a teen that presented with strong dysautonomic symptoms, most notably orthostatic intolerance prior to onset of neuromuscular symptoms. The patient experienced a severe disease course because of concurrent autonomic and myasthenic crises, requiring intensive treatment for recovery.DiscussionThe patient is unique in syncopal and autonomic burden prior to myasthenia gravis diagnosis. It is difficult to explain dysautonomia in MuSK. However, current evidence along with this case suggests yet unknown roles with broader systemic effect tied to the MuSK protein.", "authors": ["Akinsanmi Danielle", "Srinivasan Roshan", "Anziska Yaacov", "Pavlakis Steven"], "journal": "Journal of child neurology", "entry_date": "2025/12/09 11:42", "pub_date": "2025-12-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41364463/", "pub_types": ["Journal Article"], "affiliations": ["Department of Child Neurology, State University of New York Downstate Health Sciences University, Brooklyn, NY, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.6, "journal_quartile": "3区"}, {"pmid": "41364388", "title": "U.S. health plan coverage of Neuromuscular Disease Therapies: An assessment of policy availability and restrictions.", "abstract": "BACKGROUND: Health plan policies managing neuromuscular disease (NMD) therapies may impose burdensome requirements on patients and providers. While prior research has explored payer restrictions for rare NMD treatments, limited evidence exists on policies specifically governing therapy initiation and reauthorization.\nOBJECTIVES: To examine initial and reauthorization coverage policies for therapies targeting five NMDs-Duchenne muscular dystrophy, amyotrophic lateral sclerosis, spinal muscular atrophy, generalized myasthenia gravis, and Lambert-Eaton myasthenic syndrome-across all U.S. state Medicaid programs and leading commercial health plans.\nMETHODS: We constructed a database of coverage decisions issued by 50 states and DC Medicaid programs and 35 major commercial insurers, including both fee-for-service and managed care organizations. We analyzed (1) policy availability and coverage frequency, (2) initial coverage requirements (e.g., subgroup restrictions, step therapy, prescriber type), (3) reauthorization criteria, and (4) approval durations.\nRESULTS: Of 1204 potential decisions, 908 (75%) had publicly available policies. Of these, 558 (46%) included reauthorization criteria. Among covered therapies, 96% imposed restrictions beyond FDA label indications. Requirements varied by payer type, NMD, and therapy. Average approval durations were 6 months for initial coverage and 10 months for reauthorization.\nCONCLUSIONS: Many plans lacked publicly accessible policies, and most covered therapies were subject to restrictive requirements. These barriers-such as step therapy, narrow prescriber criteria, and short approval periods-may delay treatment and disrupt care continuity. Findings underscore the need for greater transparency and reform in prior authorization and pharmacy benefit design to support timely access to NMD therapies.", "authors": ["Levine A Alex", "Rucker Julia A", "Cockerham Alex", "Cartner Joel", "Chambers James D"], "journal": "Journal of neuromuscular diseases", "entry_date": "2025/12/09 11:23", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41364388/", "pub_types": ["Journal Article"], "affiliations": ["The Center for the Evaluation of Value and Risk in Health, Institute for Clinical Research and Health Policy Studies, Tufts Medical Center, Boston, MA, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41364382", "title": "Longitudinal treatment patterns in myasthenia gravis: An analysis from the prospective Dutch-Belgian patient registry.", "abstract": "BACKGROUND: Understanding treatment patterns in myasthenia gravis (MG) is crucial for clinical practice. However, longitudinal data are limited.\nOBJECTIVE: This study aimed to provide an overview of treatment patterns in different subgroups throughout the disease course.\nMETHODS: All adult patients with acetylcholine receptor (AChR), muscle-specific kinase (MuSK), or seronegative MG enrolled in the Dutch-Belgian myasthenia registry were included. AChR-MG patients were classified into early-onset (EOMG) (≤50 years) and late-onset (LOMG) (>50 years) MG. Mixed-effects regression was used to compare differences between the different subgroups.\nRESULTS: A total of 506 patients were included (147 AChR EOMG, 265 AChR LOMG, 26 MuSK, and 94 seronegative MG patients). Data were available within a year of diagnosis for 84 patients. Most patients initially started treatment with pyridostigmine (93%; 78/84), followed by corticosteroids (52%; 44/84) and azathioprine or mycophenolate mofetil (30%; 25/84). After ten years, the use of pyridostigmine (65%; 54/83) and corticosteroid use (36%; 30/83) declined, whereas the use of azathioprine and mycophenolate mofetil increased (55%; 46/83). Seronegative patients received fewer treatments than AChR MG patients, independent of functional status and disease duration (OR 0.38, 95% CI 0.17-0.84, p = 0.018), and were less likely to use corticosteroids (OR 0.15, 95% CI [0.05-0.41], p < 0.001). Patients with LOMG reported more frequently immunosuppressive use compared to patients with EOMG (OR 4.69, 95% CI 1.16-19.02, p = 0.031).\nCONCLUSIONS: This analysis offers valuable insights into treatment patterns in different subgroups of patients with MG. A substantial proportion of patients continues to rely on corticosteroids, suggesting an ongoing need for alternative treatment options.", "authors": ["Remijn-Nelissen Linda", "Tannemaat Martijn R", "Verschuuren Jan Jgm"], "journal": "Journal of neuromuscular diseases", "entry_date": "2025/12/09 11:22", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41364382/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Leiden University Medical Center, Leiden, the Netherlands."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41363919", "title": "Postherpetic Abdominal Pseudohernia Possibly Associated With Myasthenia Gravis: A Case Report.", "abstract": "Herpes zoster, caused by the reactivation of the varicella-zoster virus, predominantly affects individuals over the age of 65 and those with compromised immune systems. It may result in both sensory and motor neurological complications. Approximately 95% of postherpetic complications are sensory, whereas motor neuropathy involving abdominal muscles is rarely reported, affecting only 0.17% of cases. We present a case of a 74-year-old male diagnosed with postherpetic right abdominal pseudohernia, due to affection of the motor fibers of the spinal nerves. The dermatological examination revealed a characteristic vesicular rash in the Th 9-11 dermatomal distribution, along with a visible abdominal bulge on the right abdominal flank. The coexistence of myasthenia gravis may have predisposed VZV reactivation. It is essential to distinguish this condition from more common causes such as true abdominal hernias that often require surgical intervention. Continued follow-up is crucial to ensure complete resolution and prevent long-term complications.", "authors": ["Temelkova Petra", "Polozhani Nora", "Popovski Simona", "Dimitrievska-Chuleva Marija", "Dimitrovska Irena", "Angjelov Martin", "Damevska Katerina"], "journal": "Prilozi (Makedonska akademija na naukite i umetnostite. Oddelenie za medicinski nauki)", "entry_date": "2025/12/09 09:33", "pub_date": "2025-11-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41363919/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["PHI University Clinic for Dermatology, Skopje, RN Macedonia, Faculty of Medicine, \"Ss. Cyril and Methodius\" University in Skopje, RN Macedonia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41361909", "title": "Paraneoplastic Lambert-Eaton myasthenic syndrome associated with non-small cell lung cancer: data from the European LEMS registry and systematic review.", "abstract": "BACKGROUND: Paraneoplastic Lambert-Eaton myasthenic syndrome (pLEMS) is well-established in small-cell lung cancer (SCLC), but data on other malignancies are limited. We aimed to define the clinical phenotype of pLEMS in non-SCLC cancers (non-SCLC-pLEMS) relative to SCLC-associated LEMS (SCLC-pLEMS) and autoimmune LEMS (aiLEMS).\nMETHODS: Retrospective analysis was conducted to compare patients with SCLC-pLEMS, aiLEMS and non-SCLC-pLEMS from the European LEMS registry, and further non-SCLC-pLEMS cases were identified by a systematic review following the Preferred Reporting Items for Systematic Reviews and Meta-Analyses (PRISMA) guidelines.\nRESULTS: The registry included 72 aiLEMS, 12 SCLC-pLEMS, and 11 non-SCLC-pLEMS patients. LEMS preceded cancer diagnosis in 33% of SCLC-pLEMS (median 2 months) and 30% of non-SCLC-pLEMS (median 15 months), was concurrent in 25% and 30% and followed tumor diagnosis in the remainder. At study enrollement, Quantitative Myasthenia Gravis (QMG) scores were higher in SCLC-pLEMS (median 12, range 1-24) with recent tumor therapy initiation (median 3 months), and lower in non-SCLC-pLEMS (median 6, range 0-19), with longer (median 12 months) or completed tumor therapy, and aiLEMS (median 5, range 0-23). During follow-up, QMG improved with tumor therapy, and worsened with recurrence/progression in pLEMS groups. After completion of cancer treatment, QMG values in SCLC-pLEMS (median 6, range 0-19) and non-SCLC-pLEMS (median 5, range 1-22) were comparable to each other and to aiLEMS (median 7, range 0-29). Ataxia was significantly more frequent in SCLC-pLEMS (64%) and non-SCLC-pLEMS (55%) than in aiLEMS (19%, p = 0.006 and p = 0.024). Another 115 literature-reported non-SCLC-pLEMS cases were identified (total n = 126, comprising 137 tumors). Most common were non-small cell lung cancer (NSCLC) (n = 25, 18%), Merkel cell carcinoma (n = 18, 13%) and lymphoproliferative disorders (n = 15, 11%). In 52 literature-reported LEMS patients with outcome data, 88% partially or fully recovered after tumor therapy, leaving the paraneoplastic origin uncertain in many.\nCONCLUSIONS: Our results suggest that, beyond SCLC, other tumors can trigger pLEMS. Compared with aiLEMS, non-SCLC-pLEMS and SCLC-pLEMS showed a higher frequency of ataxia, and LEMS severity tended to reflect tumor treatment status, while disease severity becomes comparable across subtypes after cancer therapy. The frequent improvement of symptoms with tumor-directed treatment supports extended screening beyond SCLC and timely management.", "authors": ["Preßler Hannah", "Haddy Imène", "Daugherty Claire", "Postila Ville", "Meisel Andreas"], "journal": "Neurological research and practice", "entry_date": "2025/12/09 00:46", "pub_date": "2025-12-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41361909/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology With Experimental Neurology, Charité-Universitätsmedizin Berlin, Charitéplatz 1, 10117, Berlin, Germany."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41361129", "title": "Swallowing Impairments in Patients with Myasthenia Gravis: A Scoping Review.", "abstract": "This scoping review aims to describe the oropharyngeal and esophageal swallowing profiles of individuals with Myasthenia Gravis (MG). Given the high prevalence of dysphagia in this population, this review seeks to synthesize existing literature on swallowing impairments and highlight the need for early identification in dysphagia management. This scoping review was conducted in accordance with Joanna Briggs Institute methodology for scoping reviews. Four databases were systematically searched to identify studies that examined swallowing impairments in MG using instrumental assessments. Studies were screened and selected if they utilized instrumental assessments, including Videofluoroscopic Swallowing Study (VFSS), Fiberoptic Endoscopic Evaluation of Swallowing (FEES), and/or esophageal manometry. Included studies were analyzed by two independent reviewers to provide a comprehensive overview of dysphagia across oral, pharyngeal, and esophageal domains using Covidence. A total of 4,305 manuscripts were identified; 1,959 remained after removing duplicates. Following screening titles, abstracts, and full texts, 13 remained. Findings indicate that MG-associated dysphagia affects all domains of swallowing. Disease severity, classified using the Myasthenia Gravis Foundation of America (MGFA) and Osserman classification, was associated with increased dysphagia severity. Studies reported a significant prevalence of silent aspiration, with 75% of silent aspirators developing aspiration pneumonia. This review highlights the high prevalence of dysphagia in MG and the importance of objective assessments in identifying swallowing impairments. Routine instrumental evaluations are essential for managing dysphagia and preventing serious complications such as aspiration pneumonia and myasthenic crisis. Future research should focus on standardizing dysphagia screening and assessment tools for MG.", "authors": ["Arrese Loni", "Di Meglio Maria", "Byrne Laura", "Kantarcigil Cagla"], "journal": "Dysphagia", "entry_date": "2025/12/08 23:29", "pub_date": "2025-12-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41361129/", "pub_types": ["Journal Article"], "affiliations": ["Department of Speech and Hearing Science, College of Arts and Sciences, The Ohio State University, Pressey Hall, 1070 Carmack Rd., Columbus, OH, 43210, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.0, "journal_quartile": "2区"}, {"pmid": "41359492", "title": "Natural experiment on neuroinflammatory disease incidence and infection links pre- and post-COVID-19.", "abstract": "Infections are recognized triggers for several neuroinflammatory disorders. The coronavirus disease 2019 (COVID-19) pandemic's non-pharmaceutical interventions sharply curtailed pathogen exposure, creating a natural experiment to test infection-disease links. Using Japan's National Claims Database, we first validated the nationwide decline with two strictly infection-dependent conditions-epidemic keratoconjunctivitis and influenza-associated encephalopathy-whose monthly incidences fell by >60% after April 2020. Next, we applied an interrupted time series design, a causal-inference method for longitudinal data, to nine immune-mediated inflammatory diseases. Unsupervised clustering of model-derived level and slope changes identified three data-driven clusters. The first cluster, comprising Guillain-Barré syndrome and acute disseminated encephalomyelitis, showed large, statistically significant level reductions (P < 0.001), particularly in women, consistent with infection-susceptible pathophysiology. The second cluster, including myasthenia gravis and optic neuritis, exhibited transient declines followed by significant positive post-intervention slopes (P < 0.001), suggesting deferred diagnosis, treatment interruption or immune rebound. The third cluster, consisting of sarcoidosis, neuromyelitis optica, multiple sclerosis, Vogt-Koyanagi-Harada disease and Behçet's disease, remained stable, suggesting limited or complex infectious links. These data-driven trajectories mirror clinical pathophysiology and demonstrate that reduced pathogen exposure affects neuroinflammatory disease onset to varying degrees. This framework supports infection-related risk stratification, preventive strategies and continuity planning in neuroimmunology practice.", "authors": ["Akada Masahiro", "Hata Masayuki", "Miyake Masahiro", "Ishihara Kenji", "Muraoka Yuki", "Morooka Satoshi", "Tamura Hiroshi", "Tsujikawa Akitaka"], "journal": "Brain : a journal of neurology", "entry_date": "2025/12/08 13:04", "pub_date": "2026-03-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41359492/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology and Visual Sciences, Kyoto University Graduate School of Medicine, Kyoto 606-8507, Japan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41357573", "title": "Clinical features and HLA typing of immune checkpoint inhibitor-associated myasthenia gravis, myocarditis and myositis.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICI) have significantly improved the therapeutic outcomes for various malignant tumors, but they may also trigger severe immune-related adverse events (irAEs), such as myositis, myocarditis and myasthenia gravis (MG). The mechanisms underlying these adverse reactions remain unclear and may be related to an individual's genetic background. Human Leucocyte Antigen (HLA) genes play a crucial role in immune regulation, and their polymorphism is closely related to the occurrence of various autoimmune diseases.\nMETHOD: To clarify whether irAEs is associated with specific HLA typing, we analyzed 23 patients diagnosed with myositis, myocarditis and/or MG after receiving ICI therapy, and conducted HLA high-resolution typing detection using the PCR-SBT method.\nRESULTS: Among the 14 patients with MG combined with myositis and myocarditis, the frequencies ofHLA-DQB1*03:03 and HLA-C*01:02 loci were higher than those in the normal population. In 9 patients with myositis and myocarditis, the frequency of HLA-B*52:01 locus was higher than that in the normal population.\nCONCLUSION: Our research findings reveal that patients carrying autoimmune susceptibility genes have a higher risk of developing irAEs when treated with ICI, specific HLA alleles may be associated with the risk of ICI-related MG/myositis/myocarditis, but further large-scale, multi-center validation is needed.", "authors": ["Lin Xiaoting", "Liu Peng", "Jin Min", "Qi Guoyan"], "journal": "Frontiers in oncology", "entry_date": "2025/12/08 06:21", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41357573/", "pub_types": ["Journal Article"], "affiliations": ["Treatment Center of Myasthenia Gravis, People's Hospital of Shijiazhuang, Shijiazhuang, Hebei, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "41357547", "title": "Ravulizumab in the Management of Refractory Myasthenic Crisis: Clinical and Ventilatory Evidence of Early Recovery-A Case Report.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is an autoimmune disorder impairing neuromuscular transmission, most commonly through anti-AChR antibodies that activate the complement cascade. This can lead to severe complications such as myasthenic crisis (MC), which often requires intensive care. While plasma exchange (PLEX) and intravenous immunoglobulins (IVIG) are standard first-line therapies, approximately 30% of patients may show suboptimal response. Ravulizumab, a long-acting C5 complement inhibitor, has been approved for anti-AChR-positive gMG, but data on its use in MC remain limited.\nCASE PRESENTATION: We report a 62-year-old male with late-onset, anti-AChR-positive gMG who presented with refractory MC, unresponsive to five PLEX sessions and IVIG. After infectious disease evaluation, meningococcal prophylaxis, and antibiotic coverage, a single intravenous loading dose of ravulizumab (2700 mg) was administered on ICU Day 9.\nCLINICAL RESPONSE: Marked clinical improvement was observed within 48 h, including reduction in ventilatory support (pressure support decreased from 16 to 6 cmH2O over five days), improved cough, secretion management, and eventual successful extubation on Day 17. By Day 21, the patient resumed oral feeding and was transferred out of ICU with stable respiratory function and neurological improvement.\nCONCLUSION: This case suggests that ravulizumab may provide rapid and sustained benefit in anti-AChR-positive patients experiencing refractory MC. Complement inhibition led to early ventilatory and neuromuscular recovery despite prior treatment failure. These findings support further investigation of ravulizumab as rescue therapy in acute, treatment-resistant gMG exacerbations.", "authors": ["Manlio Sgarzi", "Paolo Paone", "Paolo Gritti", "Emanuela Agazzi", "Giorgia Camera", "Dario Alimonti"], "journal": "Case reports in neurological medicine", "entry_date": "2025/12/08 06:21", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41357547/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurosciences, Neurology Unit, Papa Giovanni XXIII Hospital 24127, Bergamo, Italy."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "41357059", "title": "Thymic Hyperplasia-Associated Myasthenia Gravis in the Setting of Coexisting Graves' Disease.", "abstract": "", "authors": ["Thewjitcharoen Yotsapon", "Veerasomboonsin Veekij", "Himathongkam Thep"], "journal": "Journal of the ASEAN Federation of Endocrine Societies", "entry_date": "2025/12/08 06:16", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41357059/", "pub_types": ["Journal Article"], "affiliations": ["Theptarin Diabetes, Thyroid, and Endocrine Center, ViMUT-Theptarin Hospital, Bangkok, Thailand."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.2, "journal_quartile": "4区"}, {"pmid": "41356884", "title": "Thyrotoxic Periodic Paralysis in an Asian Male With Graves' Disease.", "abstract": "Thyrotoxic periodic paralysis (TPP) is a rare but potentially life-threatening complication of hyperthyroidism. We present the case of a 27-year-old Asian male with long-standing, untreated hyperthyroidism who presented with recurrent episodes of sudden, reversible muscle weakness. These episodes involved acute flaccid paralysis predominantly affecting the lower limbs and hypokalemia, which improved rapidly with careful potassium replacement. Further investigation confirmed a diffuse toxic goiter consistent with Graves' disease. Interestingly, anti-acetylcholine receptor antibodies were found in the absence of any clinical findings of myasthenia gravis, suggesting a possible autoimmune predisposition. This case underscores the importance of early recognition of TPP to ensure timely management, prevent recurrence, and reduce the risk of complications.", "authors": ["Wardah Basimah Mehmood", "Ahmad Ans", "Nuri Muhammad Masudul Hasan"], "journal": "Cureus", "entry_date": "2025/12/08 06:15", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41356884/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Nephrology, Tahir Heart Institute, Chenab Nagar, PAK."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41356363", "title": "Proteomic and Machine Learning Analysis Predicts Treatment Response Signatures in Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a prototypical antibody-mediated autoimmune disease with variable treatment responses with a need for biomarkers to guide therapeutic decision making. Proteomic profiling, coupled with machine learning, offers a powerful approach to identify biomarkers that may predict treatment response.\nMETHODS: We analyzed sera collected at entry (baseline) from participants in a phase 3 trial randomized trial comparing thymectomy plus prednisone versus prednisone alone, along with matched controls using liquid chromatography-mass spectrometry. We derived disease-specific proteomic signatures and evaluated associations between baseline proteins and 6-month clinical outcomes using multiple machine-learning approaches with internal validation.\nRESULTS: Baseline serum proteomes distinguished MG from controls, with pathway enrichment implicating complement activation, immunoglobulin production, and T-cell receptor signaling. Distinct protein panels predicted 6-month clinical improvement within each treatment arm. In the thymectomy-plus-prednisone group, models captured non-linear relationships of predictive proteins in contrast with the predominant additive patterns observed in the prednisone-alone group. Predictive proteins were enriched for T-cell signaling and leukocyte trafficking functions, providing insight into treatment-specific biology.\nCONCLUSIONS: Baseline serum proteomics captures core disease characteristics of MG and predicts short-term clinical response in a treatment-specific manner. If validated in independent cohorts, these findings could enable biomarker-guided selection of thymectomy, refine risk stratification, and furnish mechanistic readouts for future MG trials and clinical care.", "authors": ["Gilbert Karli Faith", "Cheema Amrita K", "Kaminski Henry", "Kusner Linda"], "journal": "Research square", "entry_date": "2025/12/08 06:10", "pub_date": "2025-11-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41356363/", "pub_types": ["Journal Article", "Preprint"], "affiliations": ["George Washington University."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II"}, {"pmid": "41356249", "title": "Clinical and economic outcomes of myasthenia gravis and myasthenic crisis when treated with PLEX and IVIG.", "abstract": "INTRODUCTION: Myasthenia gravis is an autoimmune disorder characterized by muscle weakness, with myasthenic crisis representing a life-threatening exacerbation requiring respiratory support. Acute treatment options include plasmapheresis (PLEX) and intravenous immunoglobulin (IVIG). Prior studies have reported mixed results regarding the relative effectiveness of these therapies, although recent evidence suggests that PLEX may provide faster and more noticeable clinical improvement. The objective of this study was to evaluate differences in clinical and economic outcomes among U.S. patients hospitalized for myasthenia gravis or crisis who received PLEX, IVIG, both, or neither treatment.\nMETHODS: Myasthenia gravis and crisis admissions from 2017 to 2022 were collected using the National Inpatient Sample. Admissions were categorized by treatment: IVIG, PLEX, both, or neither. To minimize selection bias, admissions were propensity-matched for IVIG and PLEX. Differences in mortality were evaluated using logistic regression models. Length of stay and inflation-adjusted total charge were assessed using linear regression models.\nRESULTS: Most admissions received neither PLEX nor IVIG. Compared to treatment with neither, treatment with IVIG, PLEX, or both were not associated with significant differences in mortality; however, they were linked to longer hospital stays and higher total charge. A direct comparison of PLEX vs. IVIG revealed similar mortality and total charges, although length of stay was longer for PLEX. Older age was associated with increased mortality.\nDISCUSSION: Although PLEX has been advocated as first-line therapy due to rapid clinical improvement, national data do not clearly indicate a superior treatment option, with similar mortality and total charges observed across therapies.", "authors": ["Maroney Makenzie", "Diehl Tabitha", "Blaney Eli", "Zurob Saif", "Tauseef Abubakar", "Mirza Mohsin", "Abdul Jabbar Ali Bin"], "journal": "Frontiers in neurology", "entry_date": "2025/12/08 06:09", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41356249/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine, Creighton University School of Medicine, Omaha, NE, United States."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41350408", "title": "Incidence and outcomes of neuromuscular immune-related adverse events in head and neck cancer patients treated with checkpoint inhibitors.", "abstract": "Immune checkpoint inhibitors (ICIs) are a transformative therapy for many cancers, including head and neck cancer (HNC). However, their unique mechanism can trigger immune-related adverse events. Rare but significant are immune-related neuromuscular complications, impacting quality of life and prognosis. Using the TriNetX Global Health Research Network, 17,112 HNC patients treated with ICIs were analyzed for neuromuscular complications (inflammatory myopathies, myocarditis, myasthenia gravis, and neuropathies) identified via ICD-10 codes. Frequencies, timing, and survival probabilities were compared between patients with and without complications. The vast majority of the cohort received anti-PD-1 therapy. Neuromuscular complications occurred in 2.09% of patients (355/17,112), with 437 total diagnoses indicating multiple complications per patient. Inflammatory myopathies were most common (54.23%), followed by myocarditis (27.92%), neuropathy (9.38%), and myasthenia gravis (8.47%). Patients with Myasthenia gravis complications were older (76 vs. 69 years), while neuropathy was more frequent in men, and inflammatory myopathies skewed toward women. Complications typically emerged within the first few months of treatment, though inflammatory myopathies also developed after 12 months. Survival analysis showed no significant difference between patients with and without complications, except for myocarditis, which was associated with worse survival. With our very large cohort of patients treated with immune checkpoint inhibitors (ICIs), we can demonstrate that neuromuscular complications of ICI therapy are rare but clinically significant. Cardiac involvement, particularly myocarditis, carries the worst prognosis. Prompt recognition and multidisciplinary management by oncologists and neurologists are essential to optimize outcomes in affected patients.", "authors": ["Glaubitz Stefanie", "Zschüntzsch Jana", "Sakkas Andreas", "Scheurer Mario", "Wilde Frank", "Schramm Alexander", "Ebeling Marcel"], "journal": "Scientific reports", "entry_date": "2025/12/05 23:21", "pub_date": "2025-12-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41350408/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University Medical Center Göttingen, Robert-Koch-Straße 40, 37075, Göttingen, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41349566", "title": "Oropharyngeal dysphagia: a narrative review towards an integrated neurogeriatric perspective.", "abstract": "Oropharyngeal dysphagia, prevalent in neurogeriatric populations, increases the risks of malnutrition, pneumonia, and mortality. Oropharyngeal dysphagia manifests as a multi-aetiological syndrome with diverse phenotypes. We advocate for a neurogeriatric perspective that integrates specific neurological insights with geriatric care principles to improve dysphagia management. This approach highlights the diagnostic value of disease-specific neurological dysphagia manifestations and recognises the condition as a potential target for neurological therapies, as shown by the benefits that acetylcholinesterase inhibitors in myasthenia gravis and dopaminergic agents in Parkinson's disease have against the syndrome. Age-related factors such as presbyphagia, which includes reduced pharyngeal sensation, sarcopenia, and decreased neuroplasticity, further contribute to the pathophysiology of oropharyngeal dysphagia. Cross-disease treatment strategies encompass oral hygiene, nutritional support, dietary modifications, individualised interventions to improve swallowing physiology, and emerging neurostimulation techniques that are currently under investigation. Current research aims to refine assessment protocols tailored to these interventions, identify outcome predictors to contextualise dysphagia findings, and evaluate the potential of neurostimulation or pharmacological agents, with the aim to improve quality of life and reduce mortality.", "authors": ["Labeit Bendix", "Lapa Sriramya", "Lueg Gero", "Joebges Rebecca", "Hofacker Jule", "Muhle Paul", "Suntrup-Krueger Sonja", "Werner Cornelius J", "Schreiber Stefanie", "Wirth Rainer", "Warnecke Tobias", "Dziewas Rainer", "Meuth Sven G"], "journal": "The lancet. Healthy longevity", "entry_date": "2025/12/05 18:55", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41349566/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Medical Faculty, University Hospital Düsseldorf, Heinrich Heine-University Düsseldorf, Düsseldorf, Germany. Electronic address: Bendix.Labeit@med.uni-duesseldorf.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 14.6, "journal_quartile": "1区"}, {"pmid": "41349278", "title": "Real-world evidence supporting orphan drugs approvals for rare neuromuscular disorders in the European Union and the United States: Review of public assessment reports (2015-2025).", "abstract": "Real-world data (RWD) and real-world evidence (RWE) are becoming essential complements to conventional clinical trials for drug assessment, particularly for rare neuromuscular disorders where small patient populations heighten outcome uncertainty. Robust RWE could reduce that uncertainty and inform regulatory decisions on orphan drugs (ODs). To review how the European Medicines Agency (EMA) and the US Food and Drug Administration (FDA) have incorporated RWE into OD approvals for neuromuscular diseases from January 2015 to January 2025. We reviewed all publicly available EMA European Public Assessment Reports and FDA review packages for ODs targeting neuromuscular indications. Each document was screened for mention of RWD sources and by the regulatory weight assigned to the resulting RWE. We identified 14 OD approvals by the EMA and 13 by the FDA, with greater use of RWE by the FDA. Indications comprised spinal muscular atrophy (3/3 EMA/FDA), amyotrophic lateral sclerosis (1/3), amyloid neuropathies (2/2), Friedreich ataxia (1/1), Lambert-Eaton syndrome (1/1), myasthenia gravis (2/2), myotonic disorders (1/0), and Duchenne muscular dystrophy (2/1). Among 18 evaluable dossiers, clinical outcome assessments (COA) were reported as follows: patient-reported outcomes - 39.1%, clinician-reported outcomes - 34.7%, observer-reported outcomes - 13.1 %, and performance outcomes - 13.1%. Only tofersen incorporated all COA types. The use of RWE for the evaluation of ODs is increasing for both the FDA and the EMA, more so for the former than for the latter. Harmonized methodological standards and transparent reporting frameworks are urgently needed to generate quality evidence that benefits stakeholders.", "authors": ["García-Parra Beliu", "Guiu Josep M", "Povedano Mónica", "Modamio Pilar"], "journal": "Current opinion in pharmacology", "entry_date": "2025/12/05 18:04", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41349278/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Doctoral Program in Drug Research, Development and Control, Faculty of Pharmacy and Food Sciences, University of Barcelona, Barcelona, Spain; Clinical Neurophysiology Section - Neurology Service, Bellvitge University Hospital - Bellvitge Health Sciences Campus, University of Barcelona, L'Hospitalet de Llobregat, Barcelona, Spain. Electronic address: beliu.bellvitge@gmail.com."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.2, "journal_quartile": "2区"}, {"pmid": "41341567", "title": "Successful Surgical Repair of Ventricular Septal Defect in a Child With Ocular Myasthenia Gravis and History of Myeloid Sarcoma Post-HSCT: A Multidisciplinary Approach.", "abstract": "A 3 year-old child with ocular myasthenia gravis and a history of hematopoietic stem cell transplantation underwent successful ventricular septal defect repair through carefully coordinated multidisciplinary management. The tailored anesthetic approach and infection-control strategy enabled smooth recovery without neuromuscular or immunologic complications. This case demonstrates the feasibility of safe cardiac surgery in pediatric patients with rare, high-risk comorbidities.", "authors": ["Rong Shuhan", "Xu Wanyu", "Li Xin"], "journal": "Clinical case reports", "entry_date": "2025/12/04 04:55", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41341567/", "pub_types": ["Journal Article"], "affiliations": ["Cardiothoracic Surgery Department Children's Hospital of Soochow University, Suzhou Jiangsu Province China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41341518", "title": "Correction: The short-term prognosis of very late onset generalized myasthenia gravis: a single-center retrospective cohort study.", "abstract": "[This corrects the article DOI: 10.3389/fneur.2025.1641701.].", "authors": ["Liampas Ioannis", "Veltsista Dimitra", "Batzikosta Paraskevi", "Lazarou Lefteris", "Kefalopoulou Zinovia Maria", "Chroni Elisabeth"], "journal": "Frontiers in neurology", "entry_date": "2025/12/04 04:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41341518/", "pub_types": ["Published Erratum"], "affiliations": ["Neuromuscular Center, Department of Neurology, University Hospital of Patras, Patras, Greece."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41341320", "title": "Respiratory Failure Due to Bilateral Vocal Fold Paralysis Following Laparoscopic Cholecystectomy: A Rare Presentation of Myasthenia Gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder affecting the neuromuscular junctions. A 50-year-old woman with well-controlled MG developed stridor and respiratory failure on the first postoperative day after undergoing laparoscopic cholecystectomy with total intravenous anesthesia and sugammadex reversal. During orotracheal intubation, bronchoscopy revealed bilateral vocal fold paralysis in the adducted position. After failed extubation attempts, tracheostomy was required. The patient improved with optimized MG management and was discharged after three weeks. This rare MG manifestation emphasizes the importance of early stridor recognition, difficult airway preparedness, and adherence to American Society of Anesthesiologists guidelines for airway management and bronchoscopy.", "authors": ["Santiago Bruno", "Felippe Vitor A", "Sousa Gustavo M", "Machado Claudia R", "Lessa Marcos A"], "journal": "Cureus", "entry_date": "2025/12/04 04:52", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41341320/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Anesthesia, College of Medical Science, Rio de Janeiro State University, Rio de Janeiro, BRA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41338982", "title": "Generalized Myasthenia Gravis with Anti-acetylcholine Receptor Antibodies during the Clinical Course of Spinal and Bulbar Muscular Atrophy: A Case Report.", "abstract": "A 44-year-old man with spinal and bulbar muscular atrophy (SBMA) and an anterior mediastinal tumor presented with ptosis and diplopia with diurnal variation. Dysarthria, dysphagia, and limb weakness deteriorated acutely, and developed respiratory failure. Repetitive nerve stimulation resulted in a decremental response. Ice pack and edrophonium tests were positive. Myasthenia gravis (MG) was diagnosed based on the presence of anti-acetylcholine receptor (AChR) antibodies. Immunotherapy improved the myasthenic symptoms. Although a few cases of SBMA exhibiting myasthenic symptoms have been reported, none of these patients had anti-AChR antibodies. This is the first report of seropositive MG with comorbid SBMA.", "authors": ["Kawasaki Tomoki", "Tsuzaki Koji", "Uehara Naoko", "Wada Shinichi", "Hamano Toshiaki"], "journal": "Internal medicine (Tokyo, Japan)", "entry_date": "2025/12/03 21:33", "pub_date": "2025-12-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41338982/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Kansai Electric Power Hospital, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41338910", "title": "Lung adenocarcinoma presenting with dual paraneoplastic manifestations: dermatomyositis and Lambert-Eaton myasthenic syndrome.", "abstract": "Dermatomyositis (DM) is an autoimmune inflammatory myopathy characterised by proximal muscle weakness and distinctive cutaneous findings, frequently linked to malignancy. Lambert-Eaton myasthenic syndrome (LEMS) is a paraneoplastic disorder of neuromuscular transmission, most commonly associated with small-cell lung carcinoma. We describe a woman in her early 70s presenting with progressive proximal muscle weakness, dysphagia and a characteristic rash. Initial evaluation confirmed DM according to the 2017 European League Against Rheumatism/American College of Rheumatology classification criteria, based on clinical, serological and MRI findings. Persistent weakness and atypical facial involvement prompted further evaluation, revealing electrophysiological evidence of presynaptic neuromuscular junction dysfunction and positive P/Q-type voltage-gated calcium channel antibodies, confirming coexisting LEMS. Chest imaging identified a left upper lobe lesion, and positron emission tomography-computed tomography confirmed metastatic lung adenocarcinoma. This case illustrates the diagnostic complexity of overlapping paraneoplastic syndromes.", "authors": ["Qadeer Rabia", "Al-Bashir Alawia", "Marri Beenish"], "journal": "BMJ case reports", "entry_date": "2025/12/03 21:13", "pub_date": "2025-12-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41338910/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Acute Medicine, Bedfordshire Hospitals NHS Foundation Trust, Luton, UK rabia.qadeer@bedsft.nhs.uk."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "41338899", "title": "VATS thymectomy in left atrial isomerism.", "abstract": "Thymectomy is performed for the treatment of myasthenia gravis (MG) and the removal of thymic lesions. Minimally invasive techniques such as video-assisted thoracoscopic surgery (VATS) have now become a standard of care for thymectomies. We present the case of a woman in her early 50s with non-thymomatous MG and left atrial isomerism. As part of left atrial isomerism, she had bronchial isomerism with no right middle lobe, hemiazygous vein continuation of the inferior vena cava, bilateral superior vena cavae and no left brachiocephalic vein. A bilateral VATS approach provided a safe and effective technique for the removal of the thymus and the patient was discharged on postoperative day 2. While considerations must be taken from both the anaesthetist (altered bronchial anatomy) and operator (aberrant venae cavae and brachiocephalic veins), minimally invasive techniques can provide an effective alternative to open thymectomy in patients with anomalous anatomy.", "authors": ["Staniforth Edward", "Jain Anchal", "Taberham Rhona", "Stavroulias Dionisios"], "journal": "BMJ case reports", "entry_date": "2025/12/03 21:13", "pub_date": "2025-12-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41338899/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["General Surgery, Mid Yorkshire Teaching NHS Trust, Wakefield, UK edward.staniforth@nhs.net."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "41336098", "title": "Tracking Eyelid Movement in Cogan's Lid Twitch Syndrome.", "abstract": "Ocular myasthenia gravis (OMG) is a challenging condition to diagnose, with Cogan's lid twitch (CLT) serving as a key clinical sign. Early and accurate diagnosis of OMG is crucial for timely intervention and improved patient outcomes. However, current diagnostic methods for CLT rely primarily on visual assessment by clinicians, which is inherently subjective and prone to interobserver variability, highlighting the need for more objective diagnostic tools. This pilot study was the first to investigate the potential of video-based eyelid tracking for simplified diagnosis of Cogan's lid twitch (CLT), a key sign of ocular myasthenia gravis (OMG). The importance of this research lies in its potential to enhance diagnostic accuracy, enable earlier treatment initiation, and improve the overall management of OMG patients. We analyzed pixel value changes and eyelid position in a video recording of CLT, employing preprocessing techniques to stabilize footage and reduce lighting artifacts. Eyelid tracking was performed using contour detection and polynomial fitting. Our results showed detectable variations in eyelid position during CLT occurrences, though with inconsistent accuracy. Challenges included distinguishing subtle CLT movements from normal blinks and addressing issues like double eyelids. While further refinement is needed, this research suggests the potential of video-based tracking as a non-invasive tool for OMG diagnosis, offering significant clinical implications.Clinical Relevance- This study suggests the potential for simplified diagnosis of Cogan's lid twitch through video-based tracking, indicating significant clinical implications.", "authors": ["Lee Nayeon", "Lee Woonhee", "Lee Youngro", "Seo Jongmo", "Hwang Jeong-Min"], "journal": "Annual International Conference of the IEEE Engineering in Medicine and Biology Society. IEEE Engineering in Medicine and Biology Society. Annual International Conference", "entry_date": "2025/12/03 13:44", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41336098/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "41335310", "title": "Advancing Care in Myasthenia Gravis: What Can We Learn From the Multiple Sclerosis Community?", "abstract": "Myasthenia gravis (MG) is a chronic, autoimmune, neurological condition characterized by fluctuating muscle weakness and fatigue, driven by autoantibodies against the neuromuscular junction (NMJ). Real-world evidence studies of patient registry data show that conventional treatments do not provide sufficient disease control for some patients and that, for them, significant health, quality of life, and economic burdens remain. In recent years, several new, targeted treatments for MG have become available. In light of this evolution of the MG treatment landscape, patients and clinicians have the opportunity to elevate their treatment goals, moving from previously accepted residual symptoms to targeting complete symptom resolution and prioritizing preservation of the NMJ to minimize damage. Patients with MG can now all aim for a fully functional life well into old age, but this requires a concerted and multi-stakeholder approach to disease management. Insights from other neurological diseases in which the availability of new therapies has sparked a shift in patient care could drive faster improvements in MG care. Here, we examine how the multiple sclerosis (MS) community evolved its approach to disease management with the availability of new treatments around a decade ago. In reflecting on the multi-faceted approach taken by the MS community to drive change and improve healthcare outcomes for patients with MS, we ask the questions 'What could constitute best practice care and good outcomes for patients with MG in the future?' and 'How do we, as an MG community, get there?'.", "authors": ["Howard James F", "Sadeghian Mona", "Savic Natasa", "Giovannoni Gavin"], "journal": "Neurology and therapy", "entry_date": "2025/12/03 11:15", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41335310/", "pub_types": ["Editorial"], "affiliations": ["Department of Neurology, The University of North Carolina at Chapel Hill, UNC School of Medicine, 2200 Houpt Building, CB#7025, Chapel Hill, NC, 27599-7025, USA. howardj@neurology.unc.edu."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41334672", "title": "Characterizing Perinatal Treatment Patterns and Outcomes in Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Studies on pregnancy in myasthenia gravis (MG) are limited by small sample sizes or examine a limited number of outcomes. The objective of this study was to estimate the prevalence of perinatal and infant outcomes and characterize perinatal treatment patterns in MG.\nMETHODS: We conducted a retrospective cohort study in Merative MarketScan Commercial Claims and Encounters (CCAE) and two other United States health insurance claims databases. Pregnancies in females aged 18-49 years were identified and maternal and infant records were linked. MG was defined by ≥ 1 inpatient or ≥ 2 outpatient diagnoses within a 365-day period. The prevalence of six perinatal outcomes was calculated in the MG and total populations. Treatments were summarized by class.\nRESULTS: In pregnancies from CCAE between 2000-2023, preeclampsia (10.7% vs. 7.1%), Cesarean section (42.9% vs. 36.7%), preterm birth (18.0% vs. 9.9%), and small for gestational age (4.3% vs. 1.7%) were more frequent among MG (n = 900) than the age-adjusted total population (n = 5,185,726). Lack of treatment for MG was common across the perinatal period: 54.3% were untreated in the 6 months preconception, 61.2% in pregnancy, and 57.8% in the 6 months postpartum. Of those taking acetylcholinesterase inhibitors or corticosteroids in pregnancy, 21.8% and 33.1% had not been taking them before pregnancy, respectively.\nDISCUSSION: MG was associated with a greater prevalence of certain perinatal outcomes, occurring in both mother and infant. In parallel, though most patients did not receive treatment in pregnancy those who did showed variation over time, suggesting a potential need for this population.", "authors": ["Jacobson Melanie H", "Makadia Rupa", "Anderson Ashley E L", "Choudhry Zia", "Hall Nathan", "Hardin Jill", "Huang Sicong", "Massey Janice M", "Ostropolets Anna", "Sun Ran", "Zaha Rebecca", "Krumme Alexis A"], "journal": "Muscle & nerve", "entry_date": "2025/12/03 06:32", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41334672/", "pub_types": ["Journal Article"], "affiliations": ["Johnson & Johnson, Horsham, Pennsylvania, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41331968", "title": "\"Hit Hard, Hit Early\"-Should We Apply This in Myasthenia Gravis?", "abstract": "", "authors": ["Watson-Fargie Taylor", "Carmichael Caroline", "Hayes Samuel Alexander", "Farrugia Maria Elena"], "journal": "Journal of clinical neuromuscular disease", "entry_date": "2025/12/03 00:35", "pub_date": "2025-12-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41331968/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Institute of Neurological Sciences, Queen Elizabeth University Hospital, Glasgow, United Kingdom."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41331966", "title": "What is in the Neuromuscular Junction Literature?", "abstract": "The review begins with epidemiology studies that show an increased incidence of later onset myasthenia gravis (MG) and higher short-term mortality rates, especially in females, compared with the general population in Denmark. In the United States, a study showed increased mortality especially in older patients, and there was racial disparity. In France, a study showed higher mortality with male gender, older age, and higher comorbidities. Economic burden is addressed in another article. Regarding clinical features, light sensitivity in MG is discussed along with differentiating thyroid eye disease symptoms and signs from those of ocular MG. MG-specific measures are highlighted with consensus recommendations for their use. Several articles contain data regarding diagnostic laboratory assays and test sensitivity and specificity among other measures. The role of thymectomy in older patients with MG is considered. The medical treatment section addresses corticosteroid regimens, intravenous immunoglobulin as maintenance therapy, a phase 3 study of the recently approved neonatal Fc receptor (FcRN) blocker nipocalimab, use of complement inhibitors and FcRN blockers in general, regimens for efgartigimod, and positive studies on the interleukin-16 receptor monoclonal antibody (Ab) satralizumab and the CD19 B-cell-depleting monoclonal Ab inebilizumab.", "authors": ["Smith Joshua", "Lacomis David"], "journal": "Journal of clinical neuromuscular disease", "entry_date": "2025/12/03 00:35", "pub_date": "2025-12-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41331966/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Departments of Neurology, University of Pittsburgh School of Medicine, Pittsburgh, PA; and."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41328708", "title": "Association of Individual or Family History of Autoimmune Disease With Future Development of Type 1 Diabetes.", "abstract": "Timely diagnosis of type 1 diabetes (T1D), especially in high-risk populations, is crucial for preventing serious health complications. T1D is a chronic progressive autoimmune disease that has presymptomatic stages that can be identified through the detection of islet autoantibodies. Given that T1D is associated with other autoimmune diseases, having either those diseases or a family history of them will represent a risk of T1D. From a search of the literature conducted in August 2024, we review here the evidence for the risk of either T1D or the development of T1D in association with other autoimmune diseases or a family history of those diseases. Increased risk of subsequent T1D development was identified for individuals with autoimmune diseases, including coeliac disease, autoimmune thyroid disease, autoimmune Addison's disease, juvenile idiopathic arthritis, primary biliary cholangitis, ulcerative colitis, vitiligo, and myasthenia gravis. Increased prevalence of diabetes-associated autoantibody positivity was found among non-diabetic individuals with coeliac and autoimmune thyroid diseases compared with individuals without these autoimmune diseases. Increased risk of T1D was also found for individuals with a family history of autoimmune diseases, including coeliac disease, thyroid disease, Addison's disease, rheumatoid arthritis, systemic lupus erythematosus, Sjögren's syndrome, autoimmune liver disease, pernicious anaemia, inflammatory bowel disease, multiple sclerosis, and granulomatosis with polyangiitis. This review highlights how certain individuals at risk of T1D can be identified to offer them islet autoantibody screening and, thereby, early detection of T1D.", "authors": ["Thomas Nick", "Vaidya Bijay", "Leslie Richard David", "Agardh Daniel", "Oram Richard", "Dabelea Dana", "Singh Arunjot", "Chantzichristos Dimitrios", "Rewers Marian"], "journal": "Diabetes/metabolism research and reviews", "entry_date": "2025/12/02 06:53", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41328708/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Institute of Biomedical and Clinical Science, University of Exeter Medical School, Devon, UK."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 6.0, "journal_quartile": "2区"}, {"pmid": "41327586", "title": "Using Subcutaneous Hyoscine Butylbromide in A Terminal Patient with Myasthenia Gravis: A Case Report.", "abstract": "Management of \"death rattle\" at the end of life typically involves the use of anticholinergic agents to reduce airway secretions. However, in patients with myasthenia gravis - an autoimmune condition affecting acetylcholine receptors, causing fatigability and weakness of the skeletal muscles - the use of such agents poses a challenge. Anticholinergic agents antagonize the effects of acetylcholinesterase inhibitors, which are critical for treating myasthenia gravis, and may exacerbate symptoms. We report the case of a terminal patient with underlying myasthenia gravis who had concomitant death rattle. A trial of hyoscine butylbromide was effective in treating the death rattle, while the myasthenic symptoms remained quiescent. To our knowledge, this has not been reported previously.\nIn this article, we report the successful use of a common anticholinergic agent, hyoscine butylbromide, in a patient with myasthenia gravis who developed “death rattle” at the end of life. The use of this agent has not been previously documented in literature involving patients with myasthenia gravis.", "authors": ["Ong King Jane", "Abool Ryan Lester Rabe"], "journal": "Journal of pain & palliative care pharmacotherapy", "entry_date": "2025/12/02 00:33", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41327586/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Palliative Care Service, Department of Geriatric Medicine, Changi General Hospital, Singapore."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "41326745", "title": "Long-term impact of newly-proposed clinical obesity on autoimmune disease incidence: insights from the UK Biobank.", "abstract": "BACKGROUND/OBJECTIVES: The definition of clinical obesity was newly announced. The aim of our study was to investigate the association of preclinical obesity and clinical obesity either at baseline or determined during follow-ups with the risk of autoimmune diseases (s) incidence.\nSUBJECTS/METHODS: Data were collected from 229,190 participants in the UK Biobank. Dysfunctions caused by obesity, in combination with anthropometric parameters, were used to diagnose clinical obesity. Seven prevalent ADs were analysed, including seropositive rheumatoid arthritis (PRA), psoriasis (PSO), multiple sclerosis (MS), systemic lupus erythematosus (SLE), myasthenia gravis (MG), Crohn's disease (CD), and ulcerative colitis (UC). According to obesity and dysfunction status, participants were categorized into six clusters. Time-dependent Cox model was used to compare hazard ratios (HRs) for ADs incidence across six clusters.\nRESULTS: In a total of 4938 ADs incidence events over a mean follow-up of 13.3 years, participants in Cluster 6 (clinical obesity at baseline; HR = 2.48, 95% CI: 2.222.78) and Cluster 3 (non-obesity and dysfunction at baseline; HR = 2.16, 95% CI: 1.83-2.55) exhibited the highest multivariable-adjusted mortality risk compared with participants without obesity and dysfunction at baseline and during follow-up (Cluster 1). Specific ADs analyses showed consistently higher incidence risks in Cluster 6, notably in PSO and PRA (HR = 4.31, 95% CI: 3.58-5.19 and HR = 3.63, 95% CI: 2.54-5.18, respectively).\nCONCLUSION: Clinical obesity was significantly associated with elevated ADs incidence risk. These findings underscore the importance of early screening and intervention of clinical obesity and dysfunctions due to obesity.", "authors": ["Xu Manrong", "Li Menghan", "Zhang Yawen", "Li Lianxi", "Shen Yun", "Hu Gang"], "journal": "International journal of obesity (2005)", "entry_date": "2025/12/01 23:32", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41326745/", "pub_types": ["Journal Article"], "affiliations": ["Department of Endocrinology and Metabolism, Shanghai Sixth People's Hospital Affiliated to Shanghai Jiao Tong University School of Medicine, Shanghai Clinical Center for Diabetes, Shanghai Diabetes Institute, Shanghai Key Laboratory of Diabetes Mellitus, Shanghai Key Clinical Center for Metabolic Disease, Shanghai, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.4, "journal_quartile": "2区"}, {"pmid": "41324784", "title": "Interconnection between myasthenia gravis and type 2 diabetes: emerging role of metformin in modulating PI3K/AKT/mTOR/AMPK axis.", "abstract": "Myasthenia gravis (MG) represents the commonest autoimmune disorder affecting the neuromuscular junction (NMJ). The pathophysiology of MG is mainly linked to the formation of IgG autoantibodies directed against acetylcholine receptors (AChRs) in the NMJ. Besides, type 2 diabetes (T2D) is observed as a conceivable risk factor for the development and progression of MG. Also, T2D is further related with late-onset MG than early-onset MG. Nevertheless, there are no differences in the levels of autoantibodies in T2D patients with MG compared to T2D patients without MG. It has been proposed that increasing the production of advanced glycation end-products (AGEs) proteins and the expression of receptor glycation end-products (RAGE) in early T2D provokes the autoimmunity in MG. Additionally; AGE/RAGE signaling is augmented and contributes in the progression of autoimmunity in MG. Nonetheless, the fundamental association between MG and T2D is not totally elucidated. Therefore, this review aims to discuss and explain the link between T2D and MG. Findings of the present review highlighted that metformin mitigates the pathogenesis of both T2D and MG by regulating of PI3K/AKT/mTOR/AMPK axis and enhancing autophagy.", "authors": ["Al-Dhahi Ahmed Salem", "Al-Kuraishy Hayder M", "Al-Gareeb Ali I", "Albuhadily Ali K", "Mustafa Aya M", "Ismail Alaa", "Alexiou Athanasios", "Papadakis Marios", "El-Saber Batiha Gaber"], "journal": "Metabolic brain disease", "entry_date": "2025/12/01 11:19", "pub_date": "2025-12-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41324784/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Consultant Neurology, Department of Neuroscience, King Fahad Specialist Hospital, Tabuk, Saudi Arabia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "41323224", "title": "Expanding the phenotypic and imaging spectrum of GFPT1-related congenital myasthenic syndromes: a Brazilian case series.", "abstract": "INTRODUCTION: GFPT1-related congenital myasthenic syndrome (CMS) is a rare, autosomal recessive disorder that impairs neuromuscular transmission due to defective glycosylation of the neuromuscular junction. While typically presenting with limb-girdle weakness, tubular aggregates on biopsy, and a favorable response to acetylcholinesterase inhibitors, the full phenotypic and imaging spectrum remains incompletely defined.\nMETHODS: We evaluated five Brazilian patients from two unrelated families, all with pathogenic variants in homozygosity in GFPT1 c.41G>A (p.Arg14Gln). Clinical, electrophysiological, and imaging assessments included nerve conduction studies, electromyography, repetitive nerve stimulation (RNS), and muscle ultrasound graded using the modified Heckmatt scale. Functional severity was estimated using the Myasthenia Gravis Foundation of America (MGFA) classification.\nRESULTS: All patients showed early-onset proximal weakness, distal lower limb weakness, and frequent falls. One patient exhibited atypical features, including neonatal onset epilepsy, and cognitive impairment. RNS revealedmarked decrements in proximal upper-limb muscles (deltoid 43.6%, trapezius 37.3%) and in the distal lower-limb tibialis anterior (36.5%), consistent with foot dorsiflexion weakness. Muscle ultrasound revealed varying degrees of myopathic echogenicity. A strong positive correlation was found between MGFA severity and mean Heckmatt score (p = 0.028), suggesting alignment between functional severity and muscle structural changes.\nDISCUSSION: Our findings expand the clinical spectrum of GFPT1-CMS to include possible central nervous system involvement and demonstrate the value of integrating electrophysiology and muscle ultrasound into diagnostic evaluation. Muscle ultrasound may serve as a structural biomarker for phenotypic stratification in CMS, and distal involvement-particularly foot dorsiflexion weakness-represents an additional diagnostic clue for GFPT1-CMS.", "authors": ["Camelo-Filho Antonio Edvan", "Gomes Gustavo Rodrigues Ferreira", "Lima Pedro Lucas Grangeiro Sá Barreto", "Peixoto Vitória Maria Torres", "Mariano Tamiris", "Lopes Ellen Mourão Soares", "Alencar Raquel Diógenes", "Nóbrega Paulo Ribeiro", "Pessoa André Luiz Santos"], "journal": "Frontiers in neurology", "entry_date": "2025/12/01 06:32", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41323224/", "pub_types": ["Journal Article"], "affiliations": ["Division of Neurology, Department of Clinical Medicine, Universidade Federal do Ceará, Fortaleza, Ceará, Brazil."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41322400", "title": "Circular RNAs and their emerging roles in muscular immune-related diseases.", "abstract": "Circular RNAs (circRNAs) have recently emerged as a highly stable and versatile class of non-coding RNAs that play critical roles in gene regulation, yet their involvement in immune-mediated muscle disorders remains largely underexplored. This review synthesizes how circRNAs influence key processes in both skeletal muscle and immune cells, from myogenesis, regeneration, and muscle stem cell function to inflammatory signaling and muscle wasting. Our aim was to identify circRNA insights across muscle immune-mediated diseases. However, we found no idiopathic inflammatory myopathy-focused circRNA studies, only a limited body of work in Duchenne muscular dystrophy, and predominantly peripheral blood mononuclear cell-based evidence in myasthenia gravis. These gaps highlight clear priorities: subtype-resolved circRNA atlases for idiopathic inflammatory myopathy; paired muscle-biofluid and cell-type-resolved profiling (including infiltrating immune populations); rigorous in vivo functional validation beyond correlative expression; fuller mechanistic delineation beyond miRNA competition (e.g., RNA binding protein interactions, translation, epigenetic regulation); and longitudinal cohorts linking circRNA dynamics to disease activity and treatment response. We particularly noted lack of in-depth studies addressing the interplay between muscle and immune cells in these conditions. Furthermore, we examine pioneering efforts to engineer circRNAs as therapeutic agents, capable of either neutralizing pathogenic pathways that drive muscle atrophy or restoring dystrophin expression in genetic disease models. Finally, we outline future directions for circRNA profiling in patient tissues and biofluids, rigorous functional validation in vivo, and the development of circRNA-based diagnostics. This positions circRNAs at the forefront of next-generation strategies for understanding and combating immune-related muscular disorders.", "authors": ["Urzi Felicita", "Srpčič Anja", "Lakota Katja"], "journal": "Frontiers in immunology", "entry_date": "2025/12/01 06:25", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41322400/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Faculty of Mathematics, Natural Sciences and Information Technologies, University of Primorska, Koper, Slovenia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41322303", "title": "Myasthenia gravis and community-acquired pneumonia: therapeutic challenges.", "abstract": "Myasthenia gravis (MG) patients are highly susceptible to community-acquired pneumonia (CAP) due to the need for immunosuppressive therapies and aspiration risks, with CAP representing the leading infectious cause of mortality in this population. The intersection of MG and CAP poses unique challenges for the management of anti-infective agents and immunosuppressants. There is currently no systematic literature review addressing these issues, as previous reviews have been limited to one of these aspects. This review synthesizes evidence on the pharmacotherapeutic challenges associated with MG-CAP comorbidity, focusing on three key areas: avoiding antibiotics that exacerbate neuromuscular junction symptoms, minimizing drug interactions, and managing infection-adjusted immunosuppressants. Through a comprehensive synthesis of literature, we provide recommendations for optimizing antibiotic selection and immunosuppressants while tailoring immunosuppressive strategies according to CAP severity grading. This facilitates optimal management of both MG and infection control, highlighting the need for dynamic, patient-centered approaches. This clinical decision-making tool serves as a practical reference for physicians in the absence of established guidelines or expert consensus for managing this complex patient population.", "authors": ["Chen Xueying", "Ding Jianbo", "Zhang Jiali", "Dai Haibin", "Yu Lingyan"], "journal": "Frontiers in pharmacology", "entry_date": "2025/12/01 06:24", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41322303/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pharmacy, The Second Affiliated Hospital, School of Medicine, Zhejiang University, Hangzhou, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41322084", "title": "Development and Feasibility Assessment of a Multimodal Digital Health Technology for Remote Monitoring of Symptoms in Myasthenia Gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disease. Patients with MG are typically evaluated by neuromuscular experts through in-person neurologic examinations. These assessments are time-consuming, require significant disease expertise, and capture only a snapshot of disease.\nMETHODS: Given this need, we developed a multimodal digital health technology (DHT) called BioDigit MG, for monitoring MG symptoms and objectively measuring disease severity. BioDigit MG includes tablet-guided speech and video-based assessments, electronic patient-reported outcomes relevant to MG, and a wearable sensor to measure physical activity and posture during activities of daily living.\nRESULTS: We assessed the feasibility and acceptability of BioDigit MG by conducting a clinical study with 20 participants with MG who used the DHT. During the study, a total of 219 speech tasks and 119 videos were collected by the DHT, achieving 100% reliability in data collection and transfer. To evaluate technology acceptance and usability, we conducted face-to-face interviews with the 20 MG patients and 5 expert clinicians. Participants found the DHT highly effective, easy to use, and well-suited to their needs. Efficient and reliable data transfer capabilities of BioDigit MG ensured that patient-generated data were promptly and securely delivered to healthcare providers.\nCONCLUSION: These feasibility findings demonstrate that BioDigit MG is capable of reliable multimodal data collection and is acceptable to both patients and clinicians, supporting its potential for use in future larger scale validation studies.", "authors": ["Mishra Ram Kinker", "Potter İlkay Yıldız", "Enriquez Ana", "Stafstrom Carina L", "Sheitman Zoe", "Lindsay Abigail", "Barchard Gregory", "Nunes Adonay S", "Duda Petra W", "Vaziri Ashkan", "Guidon Amanda C"], "journal": "Digital biomarkers", "entry_date": "2025/12/01 06:22", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41322084/", "pub_types": ["Journal Article"], "affiliations": ["BioSensics LLC, Newton, MA, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41321499", "title": "Effects of resistance training on preventing muscle atrophy and bone loss in simulated weightless population: a systematic review and meta-analysis.", "abstract": "OBJECTIVE: This systematic review and meta-analysis examined the effects of resistance training on preventing muscle atrophy and bone loss under simulated weightlessness, and identified moderating factors influencing these outcomes.\nMETHODS: PubMed, Web of Science, Scopus, and SPORTDiscus were searched for articles up to October 2024. Study quality was assessed with the PEDro scale, publication bias with funnel plots and Egger's test, and certainty of evidence with the GRADE approach. A multilevel random-effects meta-analysis and moderator analyses were performed in R.\nRESULTS: Eighteen studies (297 participants) were included. Resistance training significantly increased muscle cross-sectional area (CSA) with a large effect (g = 0.95, 95% CI: 0.50-1.39, p < 0.01), with the triceps surae showing the largest CSA gains (g = 2.29). Muscle volume also improved (g = 0.84, 95% CI: 0.57-1.12, p < 0.01), moderated by sex, training type, frequency, and muscle tested. Larger effects were seen in women (g = 2.33), concurrent training (g = 2.33), 2-3 weekly sessions (g = 2.33), and quadriceps (g = 1.62). Muscle strength increased substantially (g = 2.26, 95% CI: 1.42-3.11, p < 0.01), with greater gains in women (g = 3.49), concurrent training (g = 3.08), and 60-70 days of training (g = 2.92). For bone health, resistance training increased bone mineral content (g = 0.73, 95% CI: 0.41-1.05, p < 0.01) and bone formation markers (g = 0.69, 95% CI: 0.31-1.07, p < 0.01), but had no significant effect on bone resorption (g = 0.15, p > 0.01).\nCONCLUSION: Resistance training effectively attenuates muscle atrophy and improves strength, particularly in women, with concurrent training, moderate training frequencies, and 60-70 days programs. Benefits are most evident in the quadriceps and triceps surae. Resistance training also enhances bone mineral content and bone formation, though effects on bone resorption are negligible.", "authors": ["Chen Aona", "Guo Chenggen", "Zhou Yingcong"], "journal": "Frontiers in physiology", "entry_date": "2025/12/01 06:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41321499/", "pub_types": ["Journal Article", "Review"], "affiliations": ["School of Physical Education, Wuhan University of Technology, Wuhan, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "41319836", "title": "Long COVID as an independent predictor of myasthenia gravis exacerbation: A prospective cohort study integrating machine learning for risk stratification.", "abstract": "OBJECTIVES: This study evaluates the impact of long coronavirus disease (Long COVID) on disease exacerbation in patients with myasthenia gravis (MG) and leverages machine learning (ML) approaches to identify high-risk patients.\nMETHODS: Patients with MG and COVID-19 co-infection were recruited from December 5, 2022, to January 20, 2023, at the Second Affiliated Hospital of Guizhou University of Traditional Chinese Medicine (ChiCTR2400087937). Participants underwent structured interviews at 1, 6, and 12 months post-COVID-19 to assess the incident Long COVID and MG exacerbation. The primary outcomes included the incidence and severity of MG exacerbation; the secondary outcome was 12-month mortality. Cox proportional hazards regression was employed to explore the correlation between Long COVID and MG exacerbation. ML algorithms were implemented for predictive modeling.\nRESULTS: Among 180 patients, 62 (34.4 %) experienced MG exacerbation within 12 months, and severe exacerbations (MG-ADL ≥6 points) accounted for 43.5 % of cases. Among those with initial MG exacerbations, 14.4 % continued to exhibit persistent symptoms without full recovery by the 12-month follow-up. Six fatalities (3.3 %) were recorded. Long COVID served as the strongest predictor of exacerbation (aHR = 2.55, 95 % CI 1.47-4.42, P = 0.001), followed by acetylcholinesterase (AChE) inhibitor use (aHR = 2.38) and severe COVID-19 classification (aHR = 2.30). The Random Forest model (RF) outperformed other algorithms, achieving an AUC of 0.83, with Long COVID as the top predictive feature.\nCONCLUSIONS: Long COVID is associated with MG exacerbation over time. RF model shows potential as a scalable tool for MG exacerbation risk stratification.", "authors": ["Li Yan", "Tao Yimin", "Zhao Zhilan", "Zhong Pei", "Zhong Liyan", "Yang Hui", "Yu Mingjie", "Liu Sisi", "Lei Kawai", "Zhao Qiong", "Wang Rui", "Wang Jun", "Zeng Qibing", "Kuang Shixiang", "Li Ting"], "journal": "Respiratory medicine", "entry_date": "2025/11/30 19:12", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41319836/", "pub_types": ["Journal Article", "Research Support, Non-U.S. Gov't"], "affiliations": ["Faculty of Chinese Medicine & State Key Laboratory of Quality Research in Chinese Medicine, Macau University of Science and Technology, Macau, China; Macau Institute for Applied Research in Medicine and Health, Macau University of Science and Technology, Macau, China; The Second Affiliated Hospital of Guizhou University of Traditional Chinese Medicine, Guiyang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41319444", "title": "Diversity of childhood-onset myasthenia gravis: pathophysiology and treatment.", "abstract": "Myasthenia gravis (MG) is a signaling disorder caused by immune abnormalities at the neuromuscular junction, resulting in symptoms such as muscle weakness and fatigue. Groundbreaking research since the 1970s has revealed the pathophysiology of this disease to be a T cell-dependent, B cell-associated antibody-producing disease. Half a century ago, many patients died of the disease, Today, the mortality rate has declined with many patients achieving remission. Here, I review MG pathophysiology, issues in treatment considerations specific to childhood and adolescence, and examine how racial, cultural, and geographic differences impact the clinical phenotype and treatment practices in childhood-onset MG across East Asia and Western Europe.", "authors": ["Hayashi Masatoshi"], "journal": "Journal of neuroimmunology", "entry_date": "2025/11/30 18:03", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41319444/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pediatrics, Uwajima City Hospital, Goten-Machi, Ehime 798-8510, Japan. Electronic address: mas_hayashi@outlook.jp."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41319378", "title": "Patient journey in generalized myasthenia gravis in the United States: Barriers to timely diagnosis and proposed solutions.", "abstract": "PURPOSE: Project ASPIRE aimed to identify barriers to timely diagnosis for patients with generalized myasthenia gravis (gMG), assess whether certain subgroups of patients are disproportionately affected, and propose solutions to mitigate barriers.\nMETHODS: Quantitative surveys and qualitative interviews were conducted (January-May 2023) in patients with gMG (n = 71 surveys; n = 47 interviews) and clinicians in the United States treating patients with gMG (n = 12 surveys and interviews). Data on demographics, gMG diagnostic journey, barriers, and proposed solutions were collected.\nRESULTS: Patients had mean (SD) age of 55.1 (16.0) years; 62.0 % of patients were female; 76.1 % self-reported as White and 23.9 % as racial and ethnic minorities (REM; e.g., Black [12.7 %], Hispanic/Latinx [5.6 %]). Patients had mean (SD) diagnostic journey time of 11.8 (22.5) months from symptom onset to seeking care and 15.5 (36.7) months from seeking care to diagnosis. REM and female patients reported seeing more HCPs (mean [SD]: 4.8 [2.9] and 4.9 [3.5]) than White and male patients (4.1 [3.0] and 3.0 [1.1]), respectively. Sources of diagnostic journey delay (≥9.9 % patients) were: clinicians mistaking gMG symptoms as female health issues, difficulty accessing specialty care, and lack of gMG knowledge among HCPs. Proposed solutions included increasing patient/care navigator availability, patient/HCP knowledge about gMG, and medical records access across providers.\nCONCLUSION: Patients with gMG experienced longer diagnostic journeys from seeking care to diagnosis than from symptom onset to seeking care, and faced barriers to diagnosis based on race, ethnicity, and gender. We propose that solutions should prioritize interactions between healthcare system and patients rather than patient education.", "authors": ["Jiang Nan", "Morgan Marla B", "Everett Wendy", "McNeil-Posey Kelly", "Tatroe Stacey", "Mitchell Kristi R", "Fifer Sheila", "Kielhorn Adrian"], "journal": "Journal of the neurological sciences", "entry_date": "2025/11/30 18:01", "pub_date": "2025-12-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41319378/", "pub_types": ["Journal Article"], "affiliations": ["University of Alabama at Birmingham, Birmingham, AL, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41317518", "title": "Experience of bortezomib use in refractory autoimmune neurological disorders.", "abstract": "BACKGROUND: Bortezomib (BTZ) is a proteasome inhibitor depleting plasma cells. We share experience of BTZ use in patients with refractory autoimmune-mediated neurological disorders and its safety characteristics.\nMETHODS: This single-center (AIMS, Kochi, India) retrospective cohort study included 29 patients (aged 44±21 years, 15 males) with refractory and aggressive course of autoimmune encephalitis (anti-NMDAR (n = 8), seronegative (n = 2), anti-DR2 (n = 1), Hashimoto encephalopathy (n = 1)), neuromyelitis optica spectrum disorder (n = 2), seronegative optic neuritis (n = 1), myasthenia gravis (n = 2), myelitis (n = 3), postinfectious demyelination (n = 1), vasculitic peripheral neuropathy (n = 1), autoimmune atypical parkinsonism (n = 5), autoimmune ataxia (n = 1), cramp-fasciculation syndrome (n = 1). We used Wilcoxon signed rank test and univariate binary logistic regression to assess outcomes.\nRESULTS: The median mRS-9Q score was 4 at BTZ initiation; 3 at 60 days after (z=-3.59; p< .001) and the last documented mRS-9Q score in patients having a longer follow-up (n = 27 [93 %]; z=-2.40; p=.016). Out of 28 patients who had a follow-up, 13 (46 %) patients had no registered adverse events (AE), 4 (14 %) had mild and moderate AE, 8 (29 %) had severe but not immediately life-threatening AE, 1 (4 %) - life-threatening AE, and 2 died of SARS-CoV2 infection. However, this could not be attributed to BTZ use alone, as the number of BTZ doses and the duration on active treatment including BTZ did not correlate with having any grade of an adverse event.\nCONCLUSIONS: In our cohort bortezomib appeared to improve mRS-9Q scores, especially in the cohort of anti-NMDAR encephalitis; infection was the most common side effect which, however, could not be attributed to bortezomib use alone.", "authors": ["Popova Ekaterina", "Kannoth Sudheeran", "Girish Venkitesh", "Jiju Jeeva Premaja", "Umesh Saraf Udit", "Unnikrishnan Gopikrishnan", "Gopinath Siby", "Nambiar Vivek", "Anandakuttan Anandkumar"], "journal": "Multiple sclerosis and related disorders", "entry_date": "2025/11/29 18:04", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41317518/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Amrita Institute of Medical Sciences (AIMS), Amrita Vishwa Vidyapeetham, Amrita University, Ponekkara PO, Kochi, 682041, Kerala, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41314979", "title": "JAK inhibitors for the treatment of life-threatening and refractory immune-related adverse events secondary to immune checkpoint inhibitors: a prospective cohort study.", "abstract": "BACKGROUND: Immune checkpoint inhibitors have revolutionized cancer treatment but can induce immune-related adverse events (irAEs), which are sometimes severe, life-threatening, or refractory to corticosteroids. Current management is largely empirical and adapted from autoimmune disease protocols. Dysregulation of the Janus kinase (JAK)-signal transducer and activator of transcription (STAT) pathway has been implicated in irAE pathogenesis, positioning JAK inhibitors (JAKi) as potential therapeutic agents. We hypothesized that JAKi may offer therapeutic benefit in treating corticosteroid-refractory or life-threatening irAEs.\nMETHODS: We conducted a prospective cohort study at the Jewish General Hospital (Montreal, Canada) within the Montreal Immune-Related Adverse Events biobank, enrolling patients who developed grade ≥3 or persistent grade 2 irAEs unresponsive to corticosteroids or life-threatening irAEs requiring urgent intervention.\nRESULTS: 29 patients received JAKi; 5 were excluded due to death within 30 days of initiation, leaving 24 evaluable patients (median age 69 years; 37.5% female). The majority received anti-programmed cell death protein-1 (PD-1) monotherapy (79.2%), with some receiving combination anti-cytotoxic T-lymphocyte antigen-4/PD-1 therapy (16.7%). Indications for JAKi use included myocarditis (n=8), arthritis (n=4), colitis (n=3), hepatitis (n=3), encephalitis (n=2), pneumonitis (n=2), myasthenia gravis (n=1), and sicca syndrome (n=1). JAKi were employed as second-line therapy in 7 patients, third-line in 11, and fourth-line or later in 6. Clinical response, defined as irAE resolution to grade ≤1 while on ≤10 mg prednisone equivalent without relapse for ≥30 days, was observed in 17 patients (70.8%), with median time to resolution of 41 days. Response rates were highest for myocarditis (75%) and arthritis (100%). No opportunistic infections or JAKi-related hepatotoxicity occurred; thrombotic events were identified in three individuals (10.3%).\nCONCLUSIONS: These findings suggest that JAKi are a promising, well-tolerated option for managing corticosteroid-refractory or life-threatening irAEs. Further randomized studies are warranted to confirm their efficacy and safety in this setting.", "authors": ["Habib Rami", "Miller Wilson H", "Papadopoulos Theodore", "Del Rincon Sonia V", "Berger Claudie", "Molina Manuel Flores", "Hudson Marie", "Esfahani Khashayar"], "journal": "Journal for immunotherapy of cancer", "entry_date": "2025/11/28 21:59", "pub_date": "2025-11-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41314979/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine, Division of Oncology, Jewish General Hospital, Montreal, Québec, Canada."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 10.6, "journal_quartile": "1区"}, {"pmid": "41314023", "title": "Early real-life experience on Zilucoplan for generalized myasthenia gravis: ZILU25 multicenter observational study.", "abstract": "BACKGROUND AND OBJECTIVES: Generalized Myasthenia gravis (gMG) is a rare chronic autoimmune disease affecting the postsynaptic membrane of the neuromuscular junction. New treatment options, such as the C5 inhibitors, are growing with promising results. In this study we investigated the real-world use of Zilucoplan for AChR-positive gMG in Italy.\nMATERIALS AND METHODS: Zilucoplan was self-administered by daily subcutaneous injections. Efficacy was assessed by Myasthenia Gravis Foundation of America Post-intervention status (MGFA-PIS), Myasthenia Gravis Activity of Daily Living (MG-ADL), Myasthenia Gravis Composite (MGC), Myasthenia Gravis quantitative (QMG) scales and 15-items Myasthenia Gravis Quality of Life (MG-QOL-15) questionnaire at baseline and after 1, 4, 12, 24 and 48 weeks.\nRESULTS: 54 patients (37 females, aged 57.3) received zilucoplan with a mean follow-up of 26.4 weeks. We observed a clinical meaningful and significant reduction of MG-ADL, QMG, MGC and MG-QOL-15 scores from W4 to W12 and sustained at W24 of follow-up. The MG-ADL responder rate was 75.6 % at W12 and 82.9 % at W24. Minimal symptoms expression (MSE) was obtained in 55.6 % of patients at W48 with a mean reduction of the daily prednisone dose of 8.3 mg at W24. Chronic IVIg was associated to a better response to MG-ADL at W12 at multivariate analysis.\nDISCUSSION AND CONCLUSIONS: Zilucoplan was well-tolerated and effective in most patients with AChR-positive gMG. A clinical meaningful effect was reported since the first week and was sustained after 24 weeks. Further studies are needed to confirm these preliminary real-life data.", "authors": ["Di Stefano Vincenzo", "Rini Nicasio", "Antozzi Carlo", "Alboini Paolo Emilio", "Alonge Paolo", "Bevilacqua Liliana", "Biasini Fiammetta", "Bisecco Alvino", "Bonanno Silvia", "Brighina Filippo", "Codeluppi Luca", "D'Alvano Giulia", "Damato Valentina", "Erra Carmen", "Fionda Laura", "Florio Lucia", "Guida Melania", "Habetswallner Francesco", "Iorio Raffaele", "Luppino Pietro", "Tassoni Michelangelo Maestri", "Maggi Lorenzo", "Marini Martina", "Marini Sofia", "Morino Stefania", "Pugliese Alessia", "Rossini Elena", "Saccà Francesco", "Sarnataro Alessio", "Tuccillo Francesco", "Vanoli Fiammetta", "Verza Massimiliano Ugo", "Vinciguerra Claudia", "Frangiamore Rita"], "journal": "Journal of the neurological sciences", "entry_date": "2025/11/28 18:06", "pub_date": "2025-12-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41314023/", "pub_types": ["Journal Article", "Multicenter Study", "Observational Study"], "affiliations": ["Department of Biomedicine, Neuroscience and Advanced Diagnostics (BiND), University of Palermo, 90127 Palermo, Italy. Electronic address: vincenzo.distefano07@unipa.it."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41312342", "title": "Quality of life and social support as key determinants of anxiety and depression in Myasthenia Gravis: evidence from a Chinese cohort.", "abstract": "BACKGROUND: Myasthenia Gravis (MG) is a chronic autoimmune disorder frequently accompanied by anxiety and depression, which aggravate disease burden. Evidence on the relationship between clinical characteristics and psychological symptoms in MG remains inconsistent.\nMETHODS: We conducted a cross-sectional study of 93 Chinese MG patients. Clinical and demographic data were collected, and anxiety and depression were assessed using the Hospital Anxiety and Depression Scale (HADS). Associations were examined by correlation, chi-square tests, and logistic regression with false discovery rate (FDR) correction. Multivariable models adjusted for age and sex. ROC curve analyses evaluated the predictive performance of (MG Activities of Daily Living) MG-ADL, (15-item Myasthenia Gravis Quality of Life scale) MG-QOL-15, and (Social Support Rating Scale) SSRS.\nRESULTS: Anxiety and depression were present in 30.1 and 35.5% of patients, respectively. In multivariable analysis, reduced quality of life (MG-QOL-15, OR = 0.85, 95% CI: 0.78-0.92, p < 0.001) and insufficient social support (SSRS, OR = 1.08, 95% CI: 1.00-1.16, p = 0.03) independently predicted psychological distress, whereas MGFA classification was not significant. Supplementary linear regression confirmed these findings. ROC analysis showed MG-QOL-15 had the best performance in detecting both anxiety (AUC = 0.884) and depression (AUC = 0.837), while SSRS had moderate value and MG-ADL limited discrimination.\nCONCLUSION: Psychological distress in MG is more closely linked to quality of life and social support than to conventional disease severity. Routine psychological screening with MG-QOL-15 and SSRS may facilitate early identification of high-risk patients.", "authors": ["Li Xiang", "Li Zhipeng", "Zhang Chaoyue", "Li Long", "Liang Yimin", "Zhang Xuxiang", "Liu Fengbin", "Lin Xinfeng", "Jiang Qilong"], "journal": "Frontiers in neurology", "entry_date": "2025/11/28 04:49", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41312342/", "pub_types": ["Journal Article"], "affiliations": ["The First Clinical Medical College of Guangzhou University of Chinese Medicine, Guangzhou, Guangdong, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41310415", "title": "Olink Proteomics Analysis Reveals Heterogeneous Responses to FcRn Blockade in Anti-AChR Antibody-Positive Myasthenia Gravis: FGF-19 as a Novel Biomarker.", "abstract": "OBJECTIVE: This study aimed to systematically observe the clinical manifestations, immune cell subsets, and dynamic changes in serological indicators in patients with myasthenia gravis (MG) before and after efgartigimod (EFG) treatment.\nMETHODS: We analyzed the baseline data, laboratory parameters, and lymphocyte subset proportions in MG patients before and after EFG treatment. Serum levels of 92 inflammation-related proteins were measured using Olink Target 96 proteomics in MG patients before and after EFG treatment. Validation was performed by enzyme-linked immunosorbent assay in an expanded cohort and followed by in vitro experiments to evaluate the effects of novel biomarkers on peripheral blood mononuclear cells from MG patients.\nRESULTS: Following EFG treatment, patients showed significant reductions in MG Activities of Daily Living (MG-ADL) scores and serum IgG levels, along with remodeling of immunocyte subset distribution. Olink proteomics analysis identified six differentially expressed inflammatory cytokines, among which fibroblast growth factor-19 (FGF-19) exhibited the most notable downregulation. Validation in an independent cohort demonstrated that serum FGF-19 levels were elevated and positively correlated with disease severity in MG patients. Furthermore, in EFG responders, the expression level of FGF-19 decreased after treatment. In vitro experiments demonstrated that FGF-19 promotes B-cell to plasma cell differentiation in MG patients.\nINTERPRETATION: EFG treatment can alleviate the clinical symptoms and decrease IgG levels in patients with MG. The downregulated expression following EFG treatment, along with the findings of in vitro experiments, indicates that FGF-19 may not only act as a biomarker for the efficacy of EFG, but also play a role in promoting the differentiation of B cells into plasma cells, thereby offering a novel target for therapeutic interventions.", "authors": ["Luo Tiancheng", "Peng Deyou", "Zhang Zhouao", "Yang Mingjin", "Guo Xinyan", "Ma Tianyu", "Huang Xiaoyu", "Xu Mingming", "Fu Linlin", "Zhang Yong"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/11/28 00:02", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41310415/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, Jiangsu, China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41307955", "title": "Cellular immune endophenotypes separating early and late-onset myasthenia gravis.", "abstract": "The 2 main subgroups of autoimmune myasthenia gravis, a neuromuscular junction disorder associated with muscle weakness, are early- and late-onset forms, defined by onset before or after 50 years of age. Both carry acetylcholine-receptor autoantibodies but differ in sex ratios, genetics, and occurrence of disease-specific thymus inflammation. To distinguish the 2 forms by cellular immune phenotyping, we applied multimodal techniques, including deep spectral cytometric phenotyping and single-cell sequencing. Analysis of 2 independent cohorts identified immunological differences driven by 3 main lymphocyte populations. Lower frequencies of mucosa-associated invariant T cells and naive CD8+ T cells were observed in late-onset myasthenia, suggesting enhanced immune senescence. A highly differentiated, canonical NK cell population was reduced in early-onset myasthenia and negatively correlated with the degree of thymic hyperplasia. Using only the frequency of these 3 populations, correct myasthenia subgroup assignment could be predicted with 90% accuracy. These distinct immunocellular endophenotypes for early- and late-onset disease suggest differences in immunopathogenic processes. Along with demographic factors and other disease subgroup-specific features, the frequency of the identified cell subpopulations may improve clinical classification.", "authors": ["Theorell Jakob", "Ruffin Nicolas", "Fower Andrew", "Sorini Chiara", "Ambrose Philip", "Damato Valentina", "Handunnetthi Lahiru", "Leite Isabel", "Irani Sarosh R", "Brauner Susanna", "Handel Adam E", "Piehl Fredrik"], "journal": "JCI insight", "entry_date": "2025/11/27 12:02", "pub_date": "2026-01-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41307955/", "pub_types": ["Journal Article"], "affiliations": ["Department of Medicine Huddinge, Karolinska Institutet, Stockholm, Sweden."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 6.1, "journal_quartile": "1区"}, {"pmid": "41307599", "title": "The Potential Implications of Neutrophil to Albumin Ratio for Short-term Prognosis in Myasthenia Gravis Patients.", "abstract": "Studies have shown that inflammation plays an important role in the pathogenesis of Myasthenia gravis (MG). The neutrophil to albumin ratio (NAR) stands out as a novel inflammatory biomarker; however, its relationship with MG has not been explored. This study aims to investigate the ability of NAR to monitor disease severity and predict the short-term prognosis in patients with MG. This retrospective study included 134 patients with MG. Multivariate regression and subgroup analyses were used to comprehensively explore the association between NAR and short-term prognoses. A prediction model was then built and visualized using a nomogram. Three approaches were used to evaluate the performance of the proposed nomogram. The NAR was significantly higher in patients with more severe disease conditions at baseline (p < 0.001). After adjusting for confounding factors, NAR was still independently associated with short-term prognosis of patients with MG (OR = 5.376, 95%CI = 1.321-21.881, p = 0.019). Prehospital infection, thymectomy, Myasthenia Gravis Foundation of America classification and NAR were included to establish the final short-term prognosis prediction model. The good performance of the model was verified by the receiver operating characteristic curve (AUC = 0.782, p < 0.05), calibration curve (chi-square = 8.492, p = 0.387) and decision curve analysis plot. Our study found that NAR can effectively monitor disease severity in patients with MG and is independently associated with short-term prognosis. The nomogram visualizes the prediction model and is beneficial for clinical application.", "authors": ["Lin Hai", "Lin Shenyi", "Pan Shengli", "Li Shengqi", "Zhu Jinrong", "Wang Yukai", "Chen Siyao", "Wang Lingsheng", "Zhu Zhangjing", "Wang Shiyue", "Huang Suwen", "Weng Yiyun"], "journal": "Molecular neurobiology", "entry_date": "2025/11/27 11:04", "pub_date": "2025-11-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41307599/", "pub_types": ["Journal Article"], "affiliations": ["Department of Endocrinology, The Third Affiliated Hospital of Wenzhou Medical University, Wenzhou, Zhejiang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "41303240", "title": "Complement Inhibitors in Generalized Myasthenia Gravis: Comparison of Administration Schedules, Efficacy, and Safety.", "abstract": "Background: Eculizumab, Ravulizumab, and Zilucoplan are inhibitors of terminal complement protein C5 (C5IT) approved for the treatment of generalized Myasthenia Gravis (gMG). The aim of this study is to compare the administration schedules, efficacy, and safety of these new biological therapies in a real-life setting. Methods: We enrolled 31 patients with gMG who received C5IT (Eculizumab: 7 patients; Ravulizumab: 11 patients; Zilucoplan: 13 patients). We gathered demographic, clinical data by the difference between scores at baseline (T0) and after follow-up for the MG-ADL, QMG, and MGC scales. Results: All C5IT demonstrated similar clinical efficacy, resulting in a statistically significant reduction in clinical scales scores for the MG-ADL (F = 14.7; p < 0.001), QMG (F = 14.78; p < 0.001), and MGC (F = 9.466; p < 0.001), with no significant differences among drugs (p > 0.05). No significant differences were highlighted in terms of MSE (p > 0.05). There was a decrease in the mean dose of steroid taken by patients in all three treatment groups (Eculizumab: -37%; Ravulizumab: -62%; Zilucoplan: -37%, at W34 compared to baseline). No myasthenic crises requiring hospitalization occurred during follow-up. Most of the reported adverse events were mild to moderate; the more severe events included one case of Stevens-Johnson syndrome (Ravulizumab) and episodes of pneumonia (Eculizumab, Ravulizumab). Conclusions: The comparison of C5IT did not bring out significant differences in terms of clinical efficacy and safety, representing a valid therapeutic option when traditional therapies fail to control disease symptoms.", "authors": ["Di Martino Giuseppe", "Rini Nicasio", "Bonaventura Alessia", "Trovato Mauro", "Maccora Simona", "Lima Salvatore Maria", "La Seta Concetta", "Brighina Filippo", "Di Stefano Vincenzo"], "journal": "Journal of clinical medicine", "entry_date": "2025/11/27 01:13", "pub_date": "2025-11-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41303240/", "pub_types": ["Journal Article"], "affiliations": ["Department of Biomedicine, Neuroscience and Advanced Diagnostics (BiND), University of Palermo, 90129 Palermo, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41297576", "title": "Comparison of Oncologic Outcomes After Partial and Total Thymectomy for Stage I Thymomas.", "abstract": "BACKGROUND: Total thymectomy (TT) has been the standard treatment for thymoma. However, many thymomas may be amenable to partial thymectomy (PT), which can achieve similar R0 resection frequency with favorable perioperative outcomes. We sought to determine whether PT results in oncologic outcomes similar to TT for noninvasive thymomas.\nMETHODS: We queried the International Thymic Malignancy Interest Group retrospective database from 2000 to 2014 for patients with stage I thymomas without myasthenia gravis undergoing TT or PT. Outcomes were freedom from recurrence (weighted for age and T category 1a vs 1b) and overall survival, with inverse probability weights of patient factors as predictors of TT.\nRESULTS: Included were 692 patients, with 158 PT (23%) and 534 TT (77%). PT patients were younger with better performance status. R0 resection and histology were similar. The PT group had more T1b thymomas. Adjuvant chemotherapy and radiotherapy were more frequent after PT. There was no difference in new-onset myasthenia gravis. Weighted freedom from recurrence (hazard ratio, 1.09; P = .81) and overall survival (hazard ratio, 0.62; P = .11) was similar for PT compared with TT.\nCONCLUSIONS: PT for stage I thymomas without myasthenia resulted in statistically similar recurrence and survival, and no difference in the development of new-onset myasthenia gravis, compared with TT. These results add to a growing body of literature around PT, suggesting it may be considered for stage I thymomas when R0 resection can reasonably be achieved. Surgeons performing PT are encouraged to report their outcomes to continue this discussion.", "authors": ["Campbell John M", "Chansky Kari", "Fang Wentao", "Vallières Eric", "Detterbeck Frank C", "Huang James", "Louie Brian E"], "journal": "The Annals of thoracic surgery", "entry_date": "2025/11/26 19:11", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41297576/", "pub_types": ["Journal Article", "Comparative Study", "Research Support, Non-U.S. Gov't"], "affiliations": ["Divison of Thoracic Surgery, Swedish Cancer Institute, Seattle, Washington."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41293163", "title": "Gut microbiota-derived metabolites modulate Treg/Th17 balance: novel therapeutic targets in autoimmune diseases.", "abstract": "Dysregulation of the homeostasis between regulatory T cell (Treg) and T helper 17 cell (Th17) is increasingly recognized as a pivotal mechanism in the pathogenesis of autoimmune diseases. Emerging evidence indicates that gut microbiota-derived metabolites, including short-chain fatty acids, secondary bile acids, and aromatic metabolites, modulate Treg/Th17 balance by shaping immune cell differentiation and function, thereby revealing novel therapeutic opportunities. This Review synthesizes recent clinical and preclinical findings on the influence of microbial communities and their metabolites on Treg/Th17 dynamics and examines the underlying mechanisms in representative autoimmune disorders, such as rheumatoid arthritis, systemic lupus erythematosus, Graves' disease, autoimmune hepatitis, and myasthenia gravis. We critically evaluate current microbiome-targeted interventions and discuss their translational potential, highlighting both promises and challenges. Finally, we outline priorities for future research, focusing on multi-omic integration, the development of individualized therapeutic strategies, and rigorous clinical evaluation, to facilitate the development of safe and effective microbiota-based therapies for autoimmune diseases.", "authors": ["Li Guolin", "Xiong Yu", "Li Zhimin", "Yu Qin", "Li Shiran", "Xie Jingxian", "Zeng Siyu", "Yu Dongke", "Yang Yong", "Yu Jiangping"], "journal": "Frontiers in immunology", "entry_date": "2025/11/26 04:45", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41293163/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pharmacy, Mianyang Central Hospital, School of Medicine, University of Electronic Science and Technology of China, Mianyang, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41290422", "title": "Mills' syndrome and myasthenia gravis: a case report.", "abstract": "A 50-year-old man with hypothyroidism was referred for refractory myasthenia gravis (MG). He developed progressive, painless right-sided shoulder and leg weakness, dysphagia, and fatigable diplopia. Acetylcholine receptor (AChR) antibodies were positive. Immunosuppressive therapies provided only transient improvement in oculo-bulbar symptoms, while hemiparesis progressed. Examination showed fatigable ptosis with curtain sign, vertical gaze limitation, and diplopia localizing to left lateral rectus weakness. Upper motor neuron signs included brisk masseteric reflex, right spastic hemiparesis, and hyperreflexia. EMG demonstrated chronic reinnervation in right cervical and lumbosacral regions. MRI revealed T2 hyperintensity in the left upper cervical cord and adjacent medulla without enhancement. A diagnosis of AChR+ MG and Mills' syndrome was made. While MG has previously been reported to coexist with ALS, this is the first known case associated with Mills' syndrome. This highlights the importance of recognizing overlapping autoimmune and neurodegenerative disorders and the need for further research into shared mechanisms.", "authors": ["Morena Jonathan", "Hiana James", "Naum Ryan", "Juel Vern"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2025/11/25 21:51", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41290422/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Duke University Medical Center 40 Duke Medicine Circle Durham, NC 27710, US. Electronic address: Jonathan.morena@duke.edu."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41290420", "title": "Evaluating inebilizumab in the treatment of generalized myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is the most common neuromuscular junction disorder. Despite the recent advances in the field, there are still unmet needs. Novel treatments based on new mechanisms of action are now available, including complement inhibitors, neonatal FcRn inhibitors and more recently, B cell-targeted therapies. This review provides a comprehensive overview of inebilizumab, emphasizing its clinical efficacy, safety profile, and potential role in managing MG. Inebilizumab targets CD19 B cells, thereby extending beyond conventional CD20-targeted therapies. Recent results from MINT study suggests that inebilizumab may provide meaningful and sustained disease control, with a potentially favorable safety profile. However, long-term data remains uncertain. Head-to-head comparisons with other B cell therapies, complement inhibitors or FcRn inhibitors are lacking. Patient selection will be critical, with inebilizumab best suited for refractory MG or those who have not responded adequately to existing biologics. As the treatment options for MG expands, choosing the right treatment for the patient will rely on thoroughly evaluating the efficacy, time to achieve minimal symptomatic state, comparative effectiveness, treatment burden, side effects, and cost. Ultimately, data from clinical practice and ongoing phase III trials will be essential to define the best role of inebilizumab in treatment of MG.\nWhat is this article about?This article discusses a new treatment option called inebilizumab for generalized myasthenia gravis, a chronic autoimmune disease that causes muscle weakness and fatigue. In myasthenia gravis, the body’s immune system produces antibodies that attack the connection between nerves and muscles, making it difficult for muscles to contract normally. The article explains how inebilizumab works, reviews recent research, and explores how it compares with other available therapies.What were the results?Inebilizumab is a type of medicine known as a monoclonal antibody that targets a protein called CD19 on certain immune cells known as B cells. By removing these cells, inebilizumab helps reduce the production of harmful antibodies that contribute to myasthenia gravis. Results from a large phase III study (the MINT trial) showed that people who received inebilizumab had greater improvements in their daily activity and muscle-strength scores compared with those who received a placebo. The medicine was generally well tolerated, with most side effects being mild to moderate, such as headache or mild infection.What do the results of the study mean?These findings suggest that inebilizumab may be a promising and effective treatment option for individuals whose myasthenia gravis does not respond well to existing therapies. Ongoing research and long-term follow-up will help to confirm its safety and determine its best use among the different treatment options available for this condition.", "authors": ["Carbunar Olimpia"], "journal": "Immunotherapy", "entry_date": "2025/11/25 21:43", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41290420/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurology Department, University of Miami, Miami, FL, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "41289971", "title": "Myasthenia gravis induced by encorafenib and binimetinib for metastatic melanoma.", "abstract": "", "authors": ["Groussin V", "Moumy H", "Coltoiu C", "Quéreux G", "Piroth M"], "journal": "Annales de dermatologie et de venereologie", "entry_date": "2025/11/25 18:10", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41289971/", "pub_types": ["Letter"], "affiliations": ["Department of Dermatology, Nantes University Hospital, Nantes, France. Electronic address: victoire.groussin@gmail.com."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "4区"}, {"pmid": "41287707", "title": "Immune Checkpoint Inhibitor-Induced Central and Peripheral Neurotoxicity: Case Series and Literature Review.", "abstract": "Immune checkpoint inhibitors (ICIs) have been instrumental in the management of primary thoracic and non-thoracic metastatic malignancies, making them a mainstay of cancer therapy due to their long-term clinical benefits. However, they are also associated with several immune-related adverse events (irAEs), including neurological irAEs (nirAEs). Central neurotoxicities induced by ICI use include meningoencephalitis, focal encephalitis, myelitis, and aseptic meningitis, whereas peripheral neurotoxicities include ICI-associated myopathy, myasthenia gravis, and inflammatory neuropathy. The occurrence of irAEs and nirAEs can have long-term effects on survival due to the development of cognitive impairment, aphasia, physical debility, and potential dependence on tracheostomy and gastrostomy in the long term, and should be anticipated at any time following ICI therapy. Discontinuation of ICIs and administration of high-dose corticosteroids are first-line treatment options; however, cessation of ICIs increases the risk of malignancy progression. Rechallenging with ICIs therefore warrants a careful risk-benefit analysis. In this case series, we present four cases of central and peripheral neurotoxicity induced by ICI therapy to illustrate the diverse clinical presentations, prognoses, and outcomes, and to advance the discussion on discontinuation and rechallenging of ICIs in cancer patients.", "authors": ["Dhar Shuvangee", "Mullaguri Naresh", "Sivakumar Sanjeev", "Cortez-Garcia Eduardo"], "journal": "Cureus", "entry_date": "2025/11/25 04:44", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41287707/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Prisma Health-Upstate/University of South Carolina School of Medicine Greenville, Greenville, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41287506", "title": "Diagnostic Performance of Three Serological Assays in Myasthenia Gravis: A Prospective Multicentre Study.", "abstract": "Anti-acetylcholine receptor (AChR) and anti-muscle-specific tyrosine kinase (MuSK) autoantibody detection is crucial in the diagnosis and choice of treatment of myasthenia gravis (MG). We conducted a multicentre prospective study comparing radioimmunoprecipitation assay (RIPA), enzyme-linked immunosorbent assay (ELISA) and fixed cell-based assay (F-CBA) for anti-AChR and anti-MuSK antibody detection in 78 patients with suspected MG with at least 6 months of clinical follow-up. In the diagnosis of seropositive MG (anti-AChR+anti-MuSK abs), RIPA was most sensitive (82.8%) compared to ELISA (81.0%) and F-CBA (70.7%). F-CBA exhibited the highest specificity overall (95.0%). For anti-AChR detection, F-CBA demonstrated a sensitivity of 73.6% and specificity of 95.0%; ELISA showed sensitivity and specificity of 81.1% and 85.0%, respectively; and RIPA yielded sensitivity and specificity of 81.1% and 95.0%. Sensitivity of F-CBA improved when sera were tested at lower dilution (1:5) versus the manufacturer's recommended 1:10, without compromising specificity. Agreement among methods was almost perfect for anti-AChR detection (Cohen's Kappa > 0.81). For anti-MuSK detection, agreement was substantial between ELISA and RIPA, moderate between ELISA and F-CBA, and fair between RIPA and F-CBA. Higher anti-AChR antibody levels were found in generalised versus ocular MG by both RIPA and ELISA. F-CBA confirmed its optimal specificity while the sensitivity seems to be influenced by sample dilution. In conclusion, given the radioactive nature of RIPA and consequent limitations, F-CBA may represent a valid alternative in anti-AChR and anti-MuSK antibody detection in MG diagnosis. We suggest that the use of live-CBA or RIPA could be reserved for inconclusive cases.", "authors": ["Cuomo Laura", "De Giglio Laura", "Isgrò Maria Antonietta", "Totaro Maria", "Pratali Matteo", "Fragomeli Caterina", "Cosmi Lorenzo", "Annunziato Francesco", "Palterer Boaz", "Altavista Maria Concetta", "Antonini Giovanni", "Brienza Marianna", "Cambieri Chiara", "Cortese Francesca", "Fionda Laura", "Gragnani Francesca", "Inghilleri Maurizio", "Morino Stefania", "Petrucci Antonio", "Piantadosi Carlo", "Anastasiadou Eleni", "Vitillo Marina", "Trivedi Pankaj", "Pennisi Elena Maria"], "journal": "Scandinavian journal of immunology", "entry_date": "2025/11/25 04:30", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41287506/", "pub_types": ["Journal Article", "Multicenter Study", "Comparative Study"], "affiliations": ["U.O.C. Clinical Pathology, San Filippo Neri Hospital, ASLRoma1, Rome, Italy."], "china_related": false, "study_types": ["Historical Control"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41285577", "title": "Optimising well-being in myasthenia gravis: a multidisciplinary approach.", "abstract": "Although myasthenia gravis (MG) primarily manifests as weakness of oculo-bulbar, axial and appendicular muscles, the disease and its treatments are associated with many comorbid conditions that impact patients' quality of life. Patients frequently experience secondary autoimmunity, cardiovascular and endocrine dysfunction, fatigue, sleep and mental health disorders. MG and its treatments can also be an important source of social and economic burden on patients. This review aims to elaborate on the multi-morbid nature of MG and to provide an approach for recognising and managing relevant comorbidities with an emphasis on preventative health.", "authors": ["Beland Benjamin", "Kang Min", "Dhawan Priya", "Paul Pritikanta"], "journal": "Practical neurology", "entry_date": "2025/11/24 21:24", "pub_date": "2026-05-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41285577/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University of California San Francisco, San Francisco, California, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "41284500", "title": "Decrement patterns analysis in neuromuscular junction disorders facilitates the early recognition of MuSK-myasthenia gravis.", "abstract": "", "authors": ["Pegat Antoine", "Gavoille Antoine", "Rodriguez Nicolas", "Cluse Florent", "Moussy Martin", "Fortanier Etienne", "Bouhour Françoise"], "journal": "Neurophysiologie clinique = Clinical neurophysiology", "entry_date": "2025/11/24 13:03", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41284500/", "pub_types": ["Letter"], "affiliations": ["Service ENMG et de pathologies neuromusculaires, centre de référence des maladies neuromusculaires PACA-Réunion-Rhône Alpes, Hôpital Neurologique P. Wertheimer, Hospices Civils de Lyon, France. Electronic address: antoine.pegat@chu-lyon.fr."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41283202", "title": "Effects of Thymectomy in Late-Onset Myasthenia Gravis: A Multi-Center Longitudinal Retrospective Study.", "abstract": "OBJECTIVE: Limited evidence has led to ongoing debate about the benefits of thymectomy for late-onset myasthenia gravis (LOMG). This study aims to compare the outcomes of patients with LOMG who underwent thymectomy versus those who received medical treatment alone, and evaluate the incidence of surgical adverse events.\nMETHODS: Non-thymomatous acetylcholine-receptor antibody positive patients with LOMG were selected from a multi-center longitudinal clinical database. Rates of and time to response (remission and minimal manifestations status) were compared between 2 groups by propensity score matching (PSM), Kaplan-Meier analysis, and Cox regression models. Additionally, the incidence of adverse events about thymectomy was compared between LOMG and younger patients with myasthenia gravis (MG) aged 40 to 50 years old.\nRESULTS: A total of 55 and 210 patients with LOMG were enrolled in the thymectomy and medical treatment groups, respectively. The thymectomy group exhibited significantly younger onset age (56.31 ± 6.15 vs. 62.04 ± 7.83, p < 0.001). After PSM adjustment, thymectomy demonstrated a greater cumulative probability (p < 0.001), and the 2.356-fold (95% confidence interval [CI] = 1.537-3.612, p < 0.001) higher chance of better outcomes compared to medical treatment. In subgroup analysis, thymectomy showed significantly higher response rates compared to medical treatment alone at 24 ± 2 months (48.9%, 95% CI = 33.7-64.1% vs 23.8%, 95% CI = 14.2-33.3%, p = 0.004), and 36 ± 2 months (59.5%, 95% CI = 42.9-76.1% vs 28.9%, 95% CI = 18.5-39.4%, p = 0.002). The incidences of adverse events were comparable between patients with LOMG and younger patients with MG (32.0% vs 22.4%, p = 0.286).\nINTERPRETATION: Thymectomy may be an effective therapeutic option for LOMG. Our findings highlight the need for further development of a randomized trial targeting patients with LOMG. ANN NEUROL 2026;99:629-638.", "authors": ["Chen Jiaxin", "Su Chunhua", "Feng Li", "Wang Haiyan", "Chen Pei", "Cheng Chao", "Huang Xin", "Di Li", "Chen Hongxi", "Ruan Zhe", "Chang Ting", "Zhou Hongyu", "Da Yuwei", "Feng Huiyu"], "journal": "Annals of neurology", "entry_date": "2025/11/24 09:20", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41283202/", "pub_types": ["Journal Article", "Multicenter Study", "Research Support, Non-U.S. Gov't"], "affiliations": ["Department of Neurology, The First Affiliated Hospital, Sun Yat-sen University, Guangzhou, China."], "china_related": true, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 7.7, "journal_quartile": "1区"}, {"pmid": "41281548", "title": "Efgartigimod non-responders after the first treatment cycle in generalized myasthenia gravis: a retrospective analysis of predictive factors.", "abstract": "OBJECTIVE: This study aimed to identify predictors of suboptimal response to efgartigimod in patients with generalized myasthenia gravis (gMG).\nMETHODS: In this single-center retrospective study, 35 gMG patients treated with efgartigimod were categorized into responders (n = 25) and non-responders (n = 10). Responders were defined by a reduction of >2 points in MG-ADL or >3 points in QMG score after one cycle, whereas non-responders showed improvement below these thresholds and subsequently responded to eculizumab. Demographic, clinical, and serological features were compared using univariate and multivariate analyses.\nRESULTS: Non-responders had higher baseline gross motor and respiratory sub-scores. Univariate analysis revealed that thymoma, non-thymoma tumors, thyroid disease, and other autoimmune diseases were more common in non-responders. Multivariate analysis indicated that combinations of these factors were associated with a high predicted probability of poor response (up to 97.9%).\nINTERPRETATION: Comorbidities including thymoma, other tumors, thyroid disease, and additional autoimmune disorders may predict reduced response to efgartigimod in gMG patients. Systematic evaluation of these factors could help optimize treatment selection.", "authors": ["Niu Zhenyu", "Wang Jianchun", "Ren Jingru", "Liu Ran", "Guo Jing", "Zhang Nan", "Zheng Yiming", "Hao Hongjun", "Gao Feng", "Jin Haiqiang"], "journal": "Frontiers in neurology", "entry_date": "2025/11/24 09:05", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41281548/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking University First Hospital, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41280898", "title": "Efgartigimod for generalized myasthenia gravis in the extreme elderly (≥80 years): a multicenter retrospective real-world study.", "abstract": "BACKGROUND: Target-specific immunotherapies have been shown to effectively treat myasthenia gravis (MG) with less side effects. One such immunotherapy is efgartigimod, a neonatal Fc receptor antagonist, promotes degradation of pathogenic IgG antibodies. However, data specifically focusing on elderly, especially for those over 80 years, remain limited.\nMETHODS: This study included generalized MG patients over 80 years old from four neuromuscular centers who were treated with efgartigimod. Data regarding MG history, treatment regimens, and scores from the MG-ADL, QMG, and MGC scales, as well as adverse events, were prospectively recorded.\nRESULTS: Twelve patients with mean age of 82.9 ± 2.5 years were included. Anti-AChR antibodies were positive in 11 patients and anti-MuSK antibodies were detected in 1 patient. All patients received at least one cycle of efgartigimod treatment, for the following indications: myasthenia gravis acute exacerbation (MGAE, n=8), mild/moderate disease (n=3), and myasthenic crisis (MC, n=1). At week 4 (1week after the final infusion), the study showed significant reductions in all efficacy measurements: MG-ADL scores decreased by 52.2% ± 30.8% (from 10.9 ± 2.7 to 3.6 ± 2.1), QMG scores by 36.6% ± 28.4% (from 18.2 ± 7.0 to 11.7 ± 8.3), MGC scores by 48.2% ± 33.4% (from 17.8 ± 7.5 to 9.0 ± 8.6). The greatest improvement was observed in the MGAE subgroup, with reductions of 69.8% ± 16.9% in MG-ADL, 51.8% ± 20.6% in QMG, 66.5% ± 20.2% in MGC. Clinically meaningful improvement (CMI) was rapidly achieved by 91.7% (11/12) of patients at 1.3 ± 0.5 weeks, with 8.3% (1/12) reaching minimal symptom expression (MSE) by week 4. However, two patients in the mild/moderate group failed to sustain CMI through week 4, resulting in nine responders overall (8 MGAE, 1mild/moderate). These responders maintained symptom control throughout the 24-week follow-up with subsequent therapies. Treatment-related adverse events were mild: two patients experienced transient minor headache and one patient had mild upper respiratory tract infection.\nCONCLUSIONS: This multicenter study demonstrated that efgartigimod was efficacious and safe in the elderly MG over 80 years of age. Elderly patients with MGAE presented to benefit the most from efgartigimod treatment.", "authors": ["Hong Ye", "Yuan Chang-Wen", "Lu Jie", "Kong Ping-Ping", "Huang Shi-Qi", "Yang Rui-Yuan", "Yuan Zhen-Hua", "Zhao Hong-Dong", "Jiang Teng", "Chen Jing", "Shi Jian-Quan"], "journal": "Frontiers in immunology", "entry_date": "2025/11/24 09:00", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41280898/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, Nanjing First Hospital, Nanjing Medical University, Nanjing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41274039", "title": "Psychopathology in myasthenia gravis: Results from a multicenter Italian study.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by neuromuscular impairment. While its motor symptoms are well-documented, its neuropsychological impact remains underexplored. This multicenter retrospective case-control study explores the prevalence of psychopathology in MG patients compared to healthy controls (HCs), analyzing correlations between disease severity and psychiatric disorders.\nMETHODS: We retrospectively analyzed 116 MG patients and 119 HCs from three Italian MG centers. Neuropsychological assessment included the Frontal Assessment Battery (FAB) for executive functions, the Beck Depression Inventory (BDI-II) for depression, the 12-Item Short-Form Health Survey (SF-12) for quality of life, the Insomnia Severity Index (ISI) for sleep disturbances, and the Symptom Checklist-90 Revised (SCL-90-R) for psychological distress. Group differences were assessed using ANOVA. In MG patients, correlations between clinical and neuropsychological measures were explored through Pearson's coefficient, while multivariate logistic regression identified predictors of psychiatric involvement.\nRESULTS: MG patients exhibited significantly higher SCL-90 total scores and all subdomains (p ≤ 0.001), more frequent sleep disturbances (p = 0.028), and higher BDI-II scores (p ≤ 0.001) than HCs. Increased steroid dosage correlated with anxiety (r = 0.39, p = 0.04), psychoticism (p = 0.021), and depression (p = 0.015). Regression analysis identified disease severity (OR = 2.14, 95 % CI: 1.30-3.51, p = 0.002) and corticosteroid dosage (OR = 1.78, 95 % CI: 1.12-2.83, p = 0.015) as independent predictors of psychiatric symptoms.\nCONCLUSIONS: MG patients show a significantly higher psychiatric burden, with disease severity and corticosteroid exposure as key contributors. These findings highlight the need for integrated neuropsychiatric monitoring in MG care.", "authors": ["Vinciguerra Claudia", "Montalbano Giuseppe", "Virzì Valentina", "Rini Nicasio", "Messina Christian", "Bevilacqua Liliana", "Barone Paolo", "D'Apolito Maria", "Liberatoscioli Eliana", "Di Muzio Antonio", "Monastero Roberto", "Brighina Filippo", "Di Stefano Vincenzo"], "journal": "Journal of neuroimmunology", "entry_date": "2025/11/22 18:18", "pub_date": "2026-01-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41274039/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Neurology Unit, University Hospital \"San Giovanni di Dio e Ruggi d'Aragona, Salerno, Italy. Electronic address: claudia.vinciguerra@sangiovannieruggi.it."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "41274033", "title": "Myasthenic crisis associated with invasive thymoma successfully treated with ravulizumab: A case series.", "abstract": "BACKGROUND: Myasthenia gravis (MG) can cause life-threatening respiratory failure due to exacerbation known as myasthenic crisis. Thymoma-associated MG (TAMG), accounting for 10-15 % of MG cases, often poses significant therapeutic challenges, particularly with invasive tumors. Ravulizumab, a long-acting complement C5 inhibitor, is effective for generalized MG but has not been studied specifically in TAMG.\nOBJECTIVE: To assess the clinical efficacy and safety of ravulizumab in patients with invasive thymoma (Masaoka stage IVa) presenting with myasthenic crisis refractory to conventional therapy.\nMETHODS: We retrospectively analyzed clinical data from three patients with TAMG and invasive thymoma who developed myasthenic crises and were treated with ravulizumab.\nRESULTS: All patients showed clinical improvement following ravulizumab administration. Two patients experienced rapid symptom resolution, achieving extubation and stabilization. One patient required additional immunotherapy due to incomplete response. No adverse events occurred during follow-up.\nCONCLUSION: Ravulizumab may offer an effective and safe therapeutic option for myasthenic crisis in TAMG patients who respond inadequately to standard therapies, although further studies are necessary.", "authors": ["Mitsutake Akihiko", "Suzuki Anna", "Murai Hiroyuki", "Iwata Nobue K"], "journal": "Journal of the neurological sciences", "entry_date": "2025/11/22 18:18", "pub_date": "2025-12-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41274033/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, International University of Health and Welfare Mita Hospital, Tokyo, Japan. Electronic address: mitsutake-tky@umin.ac.jp."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41271088", "title": "Blockage of the peri-synaptic Schwann cell nicotinic α7 receptor inhibitory drive increases the neuromuscular performance in rats with experimental autoimmune Myasthenia gravis: repurposing dipyridamole usage in myasthenics.", "abstract": "Acetylcholine spillover from the neuromuscular synapse triggers an inhibitory drive via the activation of nicotinic α7 receptors (α7nAChRs) on perisynaptic Schwann cells (PSCs). This mechanism involves the outflow of adenosine from PSCs via ENT1 transporters and subsequent activation of presynaptic inhibitory A1 receptors. Reinforcement of this sensing inhibitory pathway by cholinesterase (AChE) inhibitors may partially attenuate their efficacy for Myasthenia gravis treatment. Here, we investigated whether this neuromuscular break is still operative in an experimental autoimmune Myasthenia gravis (EAMG) rat model and if it is prone to pharmacological manipulation. Phrenic nerve-hemidiaphragm preparations were isolated from control and EAMG male Wistar rats. We used fluorescence video-microscopy with FM4-64 to assess nerve-evoked (50 Hz-bursts) transmitter exocytosis. Myographic recordings were used to evaluate muscle fatigue. Transmitter exocytosis was depressed in diaphragms of EAMG rats compared to controls. Direct activation of PSCs α7nAChRs with PNU282987 or pretreatment with AChE inhibitors, like neostigmine and ambenonium, exaggerated the neuromuscular transmission deficits in EAMG animals. The α7nAChR antagonist, methyllycaconitine, reversed the neuromuscular transmission deficits caused by PNU282987, neostigmine and ambenonium. Inhibition of ENT1-mediated adenosine outflow from PSCs with dipyridamole attenuated the paradoxical inhibitory effect of neostigmine on nerve-evoked transmitter exocytosis and, thus, the neuromuscular tetanic fade in EAMG rats. In conclusion, breaking the PSC-mediated α7nAChRs inhibitory drive with methyllycaconitine and dipyridamole may synergistically improve the neuromuscular performance and prevent fatigue in EAMG rats treated with AChE inhibitors. Therefore, we suggest repurposing the old antiplatelet vasodilator, dipyridamole, as a relatively safe add-on therapy for drug-resistant Myasthenia gravis.", "authors": ["Noronha-Matos José Bernardo", "Sousa-Soares Carlos", "Alves-Oliveira Beatriz", "Carvalho Liliana", "Moutinho Magda", "Neiva Rafael", "Correia-de-Sá Paulo"], "journal": "Neuropharmacology", "entry_date": "2025/11/21 19:18", "pub_date": "2026-02-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41271088/", "pub_types": ["Journal Article"], "affiliations": ["Laboratório de Farmacologia e Neurobiologia, 4050-313, Porto, Portugal; Center for Drug Discovery and Innovative Medicines (MedInUP)/RISE-Health: Health Research Network, Instituto de Ciências Biomédicas Abel Salazar - Universidade do Porto (ICBAS-UP), 4050-313, Porto, Portugal. Electronic address: jbmatos@icbas.up.pt."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41270472", "title": "The CXCL13-CXCR5 axis and follicular cytotoxic T cells: Linking T-B crosstalk in autoimmune diseases.", "abstract": "Follicular cytotoxic T (Tfc) cells, a distinct subset of CXCR5⁺CD8⁺ T lymphocytes, have recently gained attention for their dual roles in cytotoxicity and immune regulation within lymphoid follicles. Unlike conventional cytotoxic T cells, Tfc cells exhibit a follicular phenotype that enables close B cell interaction, influencing germinal center dynamics and antibody production. Accumulating evidence suggests that Tfc cells participate in a wide spectrum of pathological processes, including chronic infection, tumor immunity, and autoimmune diseases. In autoimmune settings, such as multiple sclerosis (MS), myasthenia gravis (MG), and rheumatoid arthritis (RA), aberrant CXCR5/CXCL13 signaling axis activation may promote excessive T-B cell collaboration and persistent autoantibody generation. However, the functional significance of Tfc cells in these conditions remains incompletely understood. CXCR5/CXCL13 axis disruption or modulation alters Tfc and Tfh cell activity, underscoring its central role in sustaining autoimmune inflammation. This review summarizes the current knowledge of Tfc cell phenotypes, signaling pathways, and their emerging roles across autoimmune diseases, with a particular focus on the CXCR5/CXCL13 axis as a potential therapeutic target. Understanding how this pathway regulates Tfc differentiation and function may open new avenues for precision immunotherapy in autoimmune disorders.", "authors": ["Yao Shun-Yu", "Peng Yong", "Zhang Xiuli", "Yang Huan", "Kazuo Sugimoto", "Liu Jia", "Du Miao-Qiao", "Lin Lan-Xin", "Chen Quan", "Jin Hong"], "journal": "Biomedicine & pharmacotherapy = Biomedecine & pharmacotherapie", "entry_date": "2025/11/21 18:06", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41270472/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Affiliated First Hospital of Hunan Traditional Chinese Medical College, Zhuzhou, Hunan 412000, China; Department of Neurology, Affiliated Provincial Traditional Chinese Medical Hospital of Hunan University of Chinese Medicine, Zhuzhou, Hunan 412000, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 10.8, "journal_quartile": "1区"}, {"pmid": "41269534", "title": "Initial results of the \"lateral view preceding method\" and subxiphoid robot-assisted extended thymectomy for patients with thymomatous myasthenia gravis.", "abstract": "OBJECTIVES: This study evaluates the initial surgical results of our proposed minimally invasive extended thymectomy procedure using the \"lateral view preceding method,\" which precedes dissection of the lower poles of the thymus and mediastinal fat around the cardiophrenic angles with lateral thoracoscopic views, followed by a robot-assisted subxiphoid approach for the remaining extended thymectomy.\nMETHODS: The lateral view preceding method was introduced in October 2020. We retrospectively reviewed patients with suspected thymomas in the anterior mediastinum having anti-acetylcholine receptor antibodies who underwent minimally invasive extended thymectomy between April 2011 and April 2025. Surgical outcomes were analyzed and compared with those of conventional bilateral video-assisted thoracic surgery.\nRESULTS: Nine patients, seven of whom had myasthenia symptoms, underwent the lateral view preceding approach. Mean operative, pre-robot, and robot console times were 261 ± 43, 79 ± 20, and 144 ± 28 min, respectively. No postoperative complications were observed. All patients with myasthenic symptoms showed improved minimal manifestations and better status. Compared with patients who underwent the lateral view preceding method, those who underwent the conventional approach (21 patients) had more ports (mean, 8.4 ± 1.3 and 4.2 ± 0.5, respectively, p < 0.001) and longer operative time (mean, 346 ± 117 min and 261 ± 43 min, respectively, p  = 0.024). Postoperative complications occurred in five (31%) patients who underwent the conventional approach.\nCONCLUSION: Extended thymectomy using the lateral view preceding method resulted in safe and effective initial surgical outcomes. We believe that this is a promising and minimally invasive approach.", "authors": ["Mori Shohei", "Li Lulu", "Suyama Yu", "Tsukamoto Yo", "Oh Maki", "Shigemori Rintaro", "Shibazaki Takamasa", "Nakada Takeo", "Toya Naoki", "Ohtsuka Takashi"], "journal": "General thoracic and cardiovascular surgery", "entry_date": "2025/11/21 11:21", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41269534/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Surgery, The Jikei University Kashiwa Hospital, 163-1 Kashiwashita Kashiwashi, Chiba, 277-8567, Japan. shoheijapan@jikei.ac.jp."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41269450", "title": "Exploring the Role of B-Cell Biotherapy in Myasthenia Gravis from a Genetic Perspective: A Mendelian Randomization Study.", "abstract": "Myasthenia gravis (MG) is an autoimmune disease caused by dysfunction at the neuromuscular junction. Current studies on MG are increasingly focusing on the involvement of B cell immunophenotypes in the development of the disease. Nonetheless, the specific correlation between B cells and MG still needs to be fully clarified. From published GWAS studies, we gathered summary results on B cell immunophenotypes and MG. We performed a Two-sample Mendelian randomization (MR) analysis to investigate the potential causal relationship between B cells and MG. The primary estimation was done by using IVW and the Wald ratio. To assess pleiotropy and heterogeneity, a range of tests were utilized, including the Cochran Q test, MR-Egger intercept analysis, and the MR-PRESSO test. Next, we explored the potential for a reverse connection between B cells and MG using reverse MR analysis. Subsequently, in order to control for any potential confounding variables among the B cells, we carried out a multivariable MR analysis. Finally, we conducted co-localization analysis to examine the correlation between B cells and MG. Additionally, we repeated the above analysis process for two different MG subtypes. A total of 15 B cells were found to be significantly associated with MG, 7 B cells showed significant association with Early-onset MG, and 13 B cells showed significant association with Late-onset MG, as identified by MR analysis. We verified the reliability of the results by examining heterogeneity or pleiotropy. The Reverse MR analysis showed that there is bidirectional causality between 4 B cells and Early-onset MG, as well as between 2 B cells and Late-onset MG. To prevent confusion among B cells, we utilized multivariable MR analysis and identified that only 7 B cell immunophenotypes had independent effects on MG, while 4 B cell immunophenotypes had independent effects on Late-onset MG. None of the B cells had independent effects on Early-onset MG. Through colocalization analysis, it was found that two B-cell variants (rs75787009, rs354026) were associated with MG, along with two variants (rs138791329, rs11882257) were linked to Late-onset MG. Our results indicate a connection between B cells and the risk of MG, underscoring the possibility of using B-cell depletion therapy as a treatment option for MG patients based on genetic factors. Nevertheless, further research is needed to explore the specific mechanisms involved in this association.", "authors": ["Zhang Mengyuan", "Yue Cen", "Fang Jie", "Tang Jiahui", "Chen Caihong", "Zhou Caili", "Yang Wanli", "An Xingkai", "Lin Qing", "Zhang Jiawei"], "journal": "Molecular neurobiology", "entry_date": "2025/11/21 11:19", "pub_date": "2025-11-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41269450/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology and Department of Neuroscience, The First Affiliated Hospital of Xiamen University, School of Medicine, Xiamen University, Xiamen, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "41268175", "title": "Reporting patterns of multiple sclerosis with immune checkpoint inhibitors: analysis of the FDA Adverse Event Reporting System.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) improve cancer survival but can provoke new or worsening autoimmune disease.\nOBJECTIVES: To explore the association of ICIs with multiple sclerosis (MS) using the U.S. Food and Drug Administration's Adverse Event Reporting System (FAERS) database, and to compare the disproportionality signal of MS with that of other autoimmune neurological adverse events.\nDESIGN: Secondary analysis of the FAERS database.\nMETHODS: We performed a disproportionality analysis of FAERS between 2003-Q4 and 2024-Q2. Outcomes were MS, myasthenia gravis (MG), Guillain-Barré syndrome (GBS), and autoimmune encephalitis (AIE). A signal required ⩾3 reports, proportional reporting ratio ⩾2, and χ² ⩾ 4.\nRESULTS: There were 48 reports of MS or MS relapse associated with ICIs. The reporting odds ratio (ROR) for MS or MS relapse was 0.09 (95% confidence interval (CI): 0.068-0.12). In comparison, RORs were 21.05 (95% CI: 19.287-22.974) for MG, 8.075 (95% CI: 6.677-9.766) for GBS, and 29.03 (95% CI: 23.564-35.764) for AIE.\nCONCLUSION: We found no significant safety signal for MS with ICIs, in contrast to MG, GBS, and AIE. This heterogeneity underscores the need for continued pharmacovigilance and mechanistic research.\nWhat FDA reports reveal about MS and immune checkpoint inhibitors Immune checkpoint inhibitors (ICIs) are a type of cancer treatment that help the immune system recognize and attack cancer cells. While these therapies have significantly improved survival for many cancer patients, they can sometimes cause the immune system to mistakenly attack healthy tissue—a group of side effects known as immune-related adverse events (irAEs). Some of these irAEs affect the nervous system. This study looked at whether ICIs are linked to multiple sclerosis (MS), a chronic autoimmune disease that affects the brain and spinal cord. Researchers used a large government database—the FDA Adverse Event Reporting System (FAERS)—to investigate whether MS or MS relapses are reported more often in people receiving ICIs, compared to other neurological autoimmune conditions like myasthenia gravis (MG), Guillain-Barré syndrome (GBS), and autoimmune encephalitis (AIE). The results showed that MS was not reported more frequently than expected after ICI treatment. In fact, the reporting rate for MS was much lower than for MG, GBS, or AIE. This suggests that ICIs are unlikely to significantly increase the risk of MS flare-ups or onset.", "authors": ["Shirani Afsaneh", "Goldlust Samuel A", "Stuve Olaf"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/11/21 04:20", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41268175/", "pub_types": ["Journal Article"], "affiliations": ["Saint Luke's Marion Bloch Neuroscience Institute, 4401 Wornall Rd, Kansas City, MO 64111, USA Department of Neurology, University of Missouri-Kansas City, Kansas City, MO, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41264893", "title": "Outcomes in Relation to the Age at Onset in Patients With Myasthenia Gravis.", "abstract": "BACKGROUND AND OBJECTIVES: Patients with myasthenia gravis (MG) exhibit significant heterogeneity based on age at disease onset. However, existing retrospective studies in China remain confined to single-center settings with limitations in sample size adequacy. The aim of this study was to compare clinical characteristics, treatment responsiveness, and long-term postintervention status of patients with MG across different onset ages.\nMETHODS: This was an observational, cross-sectional, multicenter, retrospective study. We reviewed the medical records of patients diagnosed with MG who were hospitalized in 3 MG centers of China from January 2012 to December 2022. Demographic information, clinical characteristics, and therapeutic data were extracted from the electronic medical record system, and responsiveness to treatment was followed up. Patients were classified into 3 age subgroups: juvenile MG (age at onset <18 years), early-onset MG (onset ≥18 and <50 years), and late-onset MG (onset ≥50 years). Time to minimal manifestation (MM) or better status was assessed using Kaplan-Meier curves and Cox proportional hazards regression models.\nRESULTS: Among 2,574 patients with MG meeting inclusion criteria, 1,023 (39.7%) had juvenile MG, 568 (22.1%) had early-onset MG, and 983 (38.2%) had late-onset MG. Juvenile MG showed a peak onset at 0-4 years (61.9%), predominantly affecting female individuals (58.3%) and presenting mainly with ocular symptoms (90.2%). While most juvenile patients responded well to treatment, pubertal onset (OR 5.2 [95% CI 2.75-9.98]), thymic hyperplasia (OR 11.4 [95% CI 5.64-22.99]), and positive acetylcholine receptor antibodies (OR 3.1 [95% CI 1.65-5.65]) were risk factors of secondary generalization. In adults, late-onset MG was more common than early-onset MG, with male predominance (53.0%) and greater comorbidity burden (40.6%), including hypertension, diabetes mellitus, and coronary heart disease. The proportion of patients with late-onset MG (66.7%) achieving MM or better status was lower than that of patients with early-onset MG (74.7%) (p < 0.001). Multivariable analysis identified late-onset MG (HR 0.8 [95% CI 0.69-0.91]), thymic abnormalities (HR 0.8 [95% CI 0.67-0.91]; HR 0.7 [95% CI 0.61-0.88]), and generalized MG (HR 0.8 [95% CI 0.71-0.96]) as factors associated with poorer outcomes.\nDISCUSSION: This large cohort study highlights distinct clinical and prognostic differences in MG by age at onset. Pubertal-onset juvenile MG and late-onset MG represent vulnerable groups, with late-onset MG demonstrating poorer prognosis.", "authors": ["Huang Xiaoyu", "Yu Zi-Hao", "Cui Ying", "Zhang Hao", "Fu Min", "Zhao Yishi", "Liu Peng", "Fan Moli", "Wu Ti", "Zhang Chao", "Qi Guoyan", "Shi Fu-Dong"], "journal": "Neurology", "entry_date": "2025/11/20 16:02", "pub_date": "2025-12-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41264893/", "pub_types": ["Journal Article", "Observational Study", "Multicenter Study"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41263248", "title": "Building a Quantitative Telemedicine Platform for Myasthenia Gravis: Augmenting the Physical Examination.", "abstract": "Myasthenia gravis (MG), a fluctuating autoimmune neuromuscular disease, presents unique challenges for remote assessment due to its reliance on detailed physical examination. To address this, we developed a quantitative telemedicine platform that augments traditional neurological assessments using computer vision, signal processing, and augmented intelligence. In response to the COVID-19 pandemic that motivated a shift to telemedicine evaluations, the Myasthenia Gravis Core Exam (MGCE) was developed by the rare disease consortium MGNet, to provide guidance in the performance of telemedicine clinical encounters. The MGCE includes eight sentinel tasks such as ptosis assessment, sit-to-stand, and speech-based respiratory measures, all amenable to digital capture. To assess the reproducibility and reliability of the MGCE, videos of 52 MG patients across six centers were performed with each having examinations performed twice. We utilized this unique resource to apply machine learning algorithms to extract clinically relevant features from video and audio data, enabling quantitation of continuous variation, in contrast to the categorical measures (mild, moderate, and severe) used in standard clinical assessments. Inter-rater variability prompted the development of a reproducibility of score metric and revealed that variations in examiner instructions and video quality significantly affect reliability. Our findings suggest that a digital examination framework can enhance MG assessment precision, reduce variability in physical examination evaluation, and support the telemedicine examination. This scalable approach has the potential to integrate digital biomarkers into neuromuscular disease care and clinical trials.", "authors": ["Garbey Marc", "Lesport Quentin", "Öztosun Gülşen", "Kaminski Henry J"], "journal": "Muscle & nerve", "entry_date": "2025/11/20 06:32", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41263248/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology & Rehabilitation Medicine, School of Medicine & Health Sciences, George Washington University, Washington, DC, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41262791", "title": "Utility of Serial Repetitive Nerve Stimulation in Differentiating Pharmacological From Immunological Exacerbation of Myasthenia Gravis: A Case Report.", "abstract": "Myasthenia gravis (MG) can be exacerbated by certain medications. However, the contribution of many suspected medications remains uncertain, often based on case reports and confounded by variable drug responses and the fluctuating nature of MG. Objective drug evaluations are needed to establish causation. This report examines cibenzoline, an antiarrhythmic suspected of exacerbating MG, and proposes a method for assessing the causal role of medications in MG exacerbations through daily repetitive nerve stimulation (RNS) correlated with drug levels. We present a case of a 78-year-old man with stable ocular MG, treated with prednisolone and cibenzoline, who developed a myasthenic crisis requiring intubation. The patient's worsening chronic kidney disease raised concerns about potentially increased cibenzoline levels and their role in the crisis. Serial co-evaluation of RNS studies and cibenzoline blood levels over three consecutive days demonstrated a strong correlation between cibenzoline levels and the severity of neuromuscular junction fatigue. Rapid clinical and electrophysiological recovery within a day following withdrawal, and subtle improvement after the drop in blood cibenzoline level, suggested a primary pharmacological mechanism rather than an immunological one, as immunological improvement usually requires at least several days. This case highlights the importance of serial electrophysiological assessments combined with drug-level monitoring to evaluate the causality in suspected medication-induced MG exacerbations. Given the increasing number of elderly patients with MG or chronic kidney disease and the potential for undiagnosed MG, the risk of iatrogenic adverse events could increase. The proposed methodology, which utilizes serial RNS with blood concentration monitoring of the suspected drug, can facilitate an accurate evaluation of the causal relationship in pharmacological versus immunological exacerbations of MG.", "authors": ["Hanazono Akira", "Yasuda Keita", "Takahashi Yoshiko", "Sanpei Yui"], "journal": "Cureus", "entry_date": "2025/11/20 05:01", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41262791/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Akita University Graduate School of Medicine, Akita, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41261682", "title": "Assessing the potential causal influence of myasthenia gravis on neurodegenerative diseases via multivariable Mendelian randomization.", "abstract": "Myasthenia gravis (MG), an autoimmune condition known for impairing neuromuscular signaling, has increasingly been implicated in broader neurological dysfunctions. Recent studies point toward a possible connection between autoimmune and neurodegenerative processes. However, whether MG contributes causally to the onset of major neurodegenerative disorders such as Alzheimer disease (AD), Parkinson disease (PD), and amyotrophic lateral sclerosis (ALS) remains unclear. This study utilizes Mendelian randomization (MR) to explore the potential causal influence of MG on these disorders from a genetic standpoint. A univariable Mendelian randomization (UVMR) framework was employed using summary-level data from genome-wide association studies (GWAS) to evaluate the effect of MG on the risk of AD, PD, and ALS. To confirm the robustness of the association between MG and AD, 2 independent AD GWAS datasets were incorporated for external replication, followed by a meta-analysis to combine the evidence. Additionally, multivariable Mendelian randomization (MVMR) was conducted to adjust for smoking behavior as a potential confounding factor. The UVMR analysis revealed a statistically significant causal relationship between MG and increased susceptibility to AD (odds ratio (OR): 1.037; 95% confidence interval (CI): 1.007-1.068; P = .016). No significant causal effects were observed for PD (OR: 1.019; 95% CI: 0.964-1.077; P = .509) or ALS (OR: 1.055; 95% CI: 0.977-1.140; P = .171). The association between MG and AD was consistently validated in 2 independent datasets (ieu-a-297: OR = 1.084; 95% CI: 1.017-1.156; P = .013; ieu-b-2: OR = 1.054; 95% CI: 1.006-1.104; P = .027). Meta-analysis reinforced the evidence supporting MG as a risk factor for AD (OR: 1.047; 95% CI: 1.023-1.072; P < .001). Furthermore, MVMR adjusting for smoking confirmed that MG independently contributes to AD risk (OR: 1.037; 95% CI: 1.006-1.069; P = .020). This study provides robust genetic evidence suggesting that MG is a causal and independent risk factor for AD. These findings highlight a novel link between autoimmunity and neurodegeneration, offering new directions for mechanistic and therapeutic research.", "authors": ["Huang Xingwang", "Wang Xiuqi", "Yang Yi", "Chen Hua"], "journal": "Medicine", "entry_date": "2025/11/20 01:01", "pub_date": "2025-10-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41261682/", "pub_types": ["Journal Article", "Meta-Analysis"], "affiliations": ["Department of Cardiothoracic Surgery, The First Hospital of Nanchang, Nanchang, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41261589", "title": "Low-dose rituximab in AChR antibody-positive ocular myasthenia gravis: Efficacy and safety-A preliminary study.", "abstract": "This study evaluates the efficacy and safety of low-dose rituximab (RTX) in patients with acetylcholine receptor antibody (AChR-Ab)-positive ocular myasthenia gravis (OMG). This was a single-center retrospective observational study that included 9 patients with AChR-Ab-positive OMG who received low-dose RTX treatment (200 mg, once every 6 months to 1 year) between January 2023 and January 2024. Evaluation indicators included MGFA-PIS status, MG-ARS score, Quantitative Myasthenia Gravis Score, peripheral blood B-cell levels (CD19+), corticosteroid usage, and adverse events at 1, 3, 6, and 12 months before and after treatment. The Wilcoxon signed-rank test was used for statistical analysis, with Z-values and effect size r calculated. A P-value < .05 was considered statistically significant. All patients showed varying degrees of clinical improvement within the 12-month follow-up period. MGFA-PIS indicated complete remission in 5 cases (55.6%), pharmacologic remission in 3 cases (33.3%), and improvement in 1 case (11.1%). The median MG-ARS score decreased significantly from 10 at baseline to 0 at 12 months (Z = 2.71, P < .001); the median Quantitative Myasthenia Gravis Score decreased from 4 to 0 (Z = 1.36, P < .001). Eight patients reduced corticosteroid use by 100%, and one patient by 83.3%. The percentage of peripheral B cells significantly decreased from 0.1543% at baseline to 0.0103% (Z = -2.52, P = .0078); absolute B-cell count decreased from 303.0/μL to 16.5/μL (Z = -2.49, P = .0078). Ptosis resolved within 2 to 8 weeks in 66.7% of patients; diplopia was less common and took longer to resolve. No serious adverse reactions were observed, and treatment was well tolerated. Low-dose rituximab demonstrates good clinical efficacy and safety in AChR antibody-positive OMG patients, effectively alleviating symptoms, reducing corticosteroid dependence, and sustainably suppressing B-cell activity through targeted depletion and functional exhaustion of B cells, thereby interrupting the antibody-mediated autoimmune response. This treatment offers a feasible and well-tolerated immunotherapeutic option for OMG patients and warrants further prospective validation with larger sample sizes.", "authors": ["Mao Baoyi", "Wang Rui", "Liu Xiaoling", "Ping Doudou", "Xu Yanan", "Ning Liangxia"], "journal": "Medicine", "entry_date": "2025/11/20 01:01", "pub_date": "2025-10-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41261589/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, Yuncheng Central Hospital Affiliated to Shanxi Medical University Yuncheng, Shanxi Province, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41261588", "title": "Vesicocolic fistula in myasthenia gravis patient: A case report.", "abstract": "RATIONALE: Vesicocolic fistula is a rare disease, and surgical intervention is the only available treatment, while complications can arise when patients also suffer from myasthenia gravis, a neuromuscular disease that can be exacerbated by the stress of surgery.\nPATIENT CONCERNS: We report a 60-year-old male with a history of heart disease, myasthenia gravis, and other comorbidities who was admitted with complaints of fecaluria for the past 18 months.\nDIAGNOSES: Computed tomography showed bladder cancer involving the distal descending colon, with a high suspicion of a vesicocolic fistula. In addition, multiple diverticula were observed in both the descending and sigmoid colon.\nINTERVENTIONS: In this case, a multidisciplinary approach and careful perioperative management enabled the successful resolution of the fistula while minimizing risks associated with the patient's underlying condition. Finally, the fistula was successfully solved by laparoscopic surgery.\nOUTCOMES: At 3 months postoperatively, the patient recovered well and did not reappear with the previous symptom.\nLESSONS: Vesicocolic fistula complicated by myasthenia gravis poses unique challenges in surgical management. We summarized the clinical features and treatment methods of this vesicocolic fistula, hoping to contribute to the development of the surgical treatment strategies for vesicocolic fistula and provide insights for others experiencing similar conditions.", "authors": ["Liu Xiaohui", "Meng Jiao", "Huang Baosu", "Jin Peng"], "journal": "Medicine", "entry_date": "2025/11/20 01:01", "pub_date": "2025-10-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41261588/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["General Surgery Department, Affiliated Hospital of Shandong Second Medical University, School of Clinical Medicine, Shandong Second Medical University, Weifang, Shandong Province, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41261457", "title": "Inhibition of Classical and Alternative Complement Pathway by Ravulizumab and Eculizumab.", "abstract": "OBJECTIVE: To explore the feasibility of classical (CH50) and alternative (AH50) complement pathway activity as potential biomarkers for treatment guidance and monitoring during therapy with ravulizumab in patients with generalized myasthenia gravis (gMG) and compare these to therapeutic drug monitoring under eculizumab.\nMETHODS: In this prospective, exploratory real-world study CH50 and AH50, eculizumab and ravulizumab blood levels were assessed in patients with acetylcholine-receptor-antibody (AChR-ab) positive gMG. Patients were either pretreated with eculizumab or C5-inhibitor naïve. Samples were collected before the next infusion (end-of-dose). Laboratory data were correlated with patient-reported subjective duration of the ravulizumab effect.\nRESULTS: Overall, 61 patients were enrolled. At the end of their respective dosing interval, median AH50 levels were more strongly suppressed with eculizumab than with ravulizumab (1% [0%-2%] versus 5% [3%-9%]; Cohen's d 2.2 [95% CI 1.5-2.8]). Patients who discontinued ravulizumab due to insufficient effects (n = 19; 33%) had higher median AH50 levels than those who continued (7% [4%-13%] versus 5% [3%-8%]; Cohen's d -0.9 [95% CI -1.3 to -0.4]). In 81% (n = 46) of patients, the therapeutic effect of ravulizumab diminished before the subsequent infusion after the standard 8-week interval. Higher AH50 levels were correlated with earlier symptom recurrence.\nINTERPRETATION: Our results indicate potential differences in the ability of eculizumab and ravulizumab to suppress complement pathway activity through their respective dosing intervals. Additionally, higher AH50 levels might be a potential biomarker to predict poor therapy response and faster wearing off of ravulizumab's effect. However, these findings need to be validated in large multicenter studies.", "authors": ["Gerischer Lea", "Stascheit Frauke", "Mönch Maximilian", "Doksani Paolo", "Dusemund Carla", "Herdick Meret", "Mergenthaler Philipp", "Stein Maike", "Suboh Amani", "Schröder-Braunstein Jutta", "Wabnitz Guido", "Lünemann Jan D", "Lehnerer Sophie", "Hoffmann Sarah", "Meisel Andreas"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/11/20 00:05", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41261457/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology With Experimental Neurology and Integrated Myasthenia Center, Charité-Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität Zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41261388", "title": "Prediction of Myasthenia Gravis Worsening: A Machine Learning Algorithm Using Wearables and Patient-Reported Measures.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare disorder characterized by fluctuating muscle weakness with potential life-threatening crises. Timely interventions may be delayed by limited access to care and fragmented documentation. Our objective was to develop predictive algorithms for MG deterioration using multimodal telemedicine data.\nMETHODS: In this 12-week randomized controlled study, 30 MG patients recorded symptoms using patient-reported outcome measures (PROMs) and patient-performed measures via a mobile app, alongside data from wearables. MG deterioration was defined as a ≥ 3-point worsening in the Quantitative Myasthenia Gravis score, occurrence of MG-related hospitalization or exacerbation. A machine learning linear classifier was trained to predict deterioration and cross-validated. The area under the receiver operator characteristic curve (AUROC) was calculated, accepting 1-2 false alarms (FAs) per week.\nRESULTS: The model achieved the best predictive performance when using all input signals (AUROC 0.85 (95% confidence interval 0.77-0.91)) and remained stable across look-back windows of 4-10 days. Model sensitivity was 0.65 (0.48-0.83) to 0.82 (0.60-1.00) (1 and 2 FAs per week, respectively). PROMs reflected worsening symptoms before deterioration; wearables alone showed higher AUROCs.\nINTERPRETATION: Multimodal self-monitoring via MyaLink predicted MG deterioration with good performance at acceptable FA rates. This approach may enable earlier clinical interventions of MG worsening.\nTRIAL REGISTRATION: The study was registered under the German Clinical Trial Registry (DRKS00029907).", "authors": ["Stein Maike", "Sun Haoqi", "Lehnerer Sophie", "Gerischer Lea", "Mönch Maximilian", "Meisel Christian", "Meisel Andreas", "Narayanaswami Pushpa"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/11/19 23:53", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41261388/", "pub_types": ["Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology With Experimental Neurology, Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Berlin, Germany."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41258618", "title": "CAR T Cell Therapy for Rheumatoid Arthritis.", "abstract": "Chimeric Antigen Receptor (CAR) T cell therapy has revolutionised the treatment of relapsed/refractory B cell leukaemia, lymphoma and multiple myeloma through targeting of CD19 and BCMA antigens on the surface of these cells. A growing body of evidence has recently demonstrated that these cell-based therapies can also target autoimmune diseases including systemic lupus erythematosus, systemic sclerosis, neuromyelitis optica spectrum disorder, myasthenia gravis, idiopathic inflammatory myositis, multiple sclerosis and rheumatoid arthritis. To date, ten patients with rheumatoid arthritis have been treated with CAR T cells targeting CD19/CD20 or BCMA antigens on B cells. Nine patients with seropositive disease have shown remarkable responses, including depletion of circulating B cells, ablation of autoantibody levels and drug-free remission. A tenth patient with seronegative disease initially responded to CAR T cell therapy but later relapsed. This review provides in-depth analysis of these single case studies and highlights emerging in-vitro and animal model studies where T cell subsets have been engineered with CARs to fine-tune their immune responses for the treatment of rheumatoid arthritis, including targeting of autoreactive B cells, autoreactive T cells or fibroblasts. CAR T cell therapy holds enormous promise for the treatment of difficult-to-treat rheumatoid arthritis, but more research and large clinical trials are needed to confirm its efficacy and safety.", "authors": ["Freeley Michael"], "journal": "Clinical reviews in allergy & immunology", "entry_date": "2025/11/19 09:45", "pub_date": "2025-11-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41258618/", "pub_types": ["Journal Article", "Review"], "affiliations": ["School of Biotechnology, Dublin City University, Glasnevin, Dublin 9, Ireland. Michael.Freeley@dcu.ie."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.2, "journal_quartile": "2区"}, {"pmid": "41258323", "title": "Efgartigimod as Fast-Acting Rescue Therapy in Very Late-Onset Myasthenia Gravis.", "abstract": "Myasthenic crisis (MC) is a potentially fatal complication of myasthenia gravis (MG), often requiring intensive care and rescue therapies such as intravenous immunoglobulin (IVIG) and corticosteroids. Efgartigimod, a neonatal Fc receptor (FcRn) antagonist, offers a novel approach by selectively reducing circulating pathogenic IgG. We describe a 77-year-old man with anti-AChR-positive generalized MG who developed a severe MC, with little response to IVIG and high-dose corticosteroids. Intravenous efgartigimod was administered as rescue therapy with rapid and sustained clinical improvement. This case supports the utility of efgartigimod in MC unresponsive to conventional therapies, including in older patients with significant comorbidities.", "authors": ["Rini Nicasio", "D'Amico Flora", "Portera Valentina", "Brighina Filippo", "Di Stefano Vincenzo"], "journal": "Neurology and therapy", "entry_date": "2025/11/19 09:28", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41258323/", "pub_types": ["Journal Article"], "affiliations": ["Department of Biomedicine, Neuroscience, and Advanced Diagnostic (BIND), University of Palermo, Via del Vespro 143, 90129, Palermo, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41258322", "title": "Efgartigimod Combined with Glucocorticoids in the Treatment of Severe Generalized Myasthenia Gravis: A Single-Center, Retrospective Cohort Study.", "abstract": "INTRODUCTION: High-dose intravenous methylprednisolone (IVMP) is effective in treating generalized myasthenia gravis (gMG), but early-stage transient aggravation and MG crisis can occur. This study evaluated the safety and efficacy of efgaitigimod in combination with different doses of IVMPs in patients with severe gMG.\nMETHODS: This was a single-center, retrospective cohort study that retrospectively collected patients with myasthenia gravis who presented to Hebei Myasthenia Gravis Diagnosis and Treatment Center from December 2023 to May 2024, divided into IVMP monotherapy (1000 mg, Group A, n = 20) or efgartigimod combined with IVMP: 1000 mg (Group B, n = 7), 500 mg (Group C, n = 10), or 250 mg (Group D, n = 20). Patients received efgartigimod (10 mg/kg) intravenously on days 1 and 8 while receiving IVMP. Efficacy was assessed via quantitative myasthenia gravis (QMG) scores at baseline, week 2, and week 12.\nRESULTS: Groups A, C, and D demonstrated progressive QMG reductions over 12 weeks. Group B showed a week 12 QMG rebound (vs. week 2) but remained below baseline. At week 2, Group A had significantly less QMG improvement than Group B (p = 0.004), which was not different from group C/D. After 12 weeks, no significant difference was found among the groups (p = 0.639). Transient exacerbations and adverse events were significantly higher in Group A versus C/D.\nCONCLUSION: Efgartigimod combined with 250 mg IVMP is associated with improvement of symptoms, reduction of transient exacerbations, and adverse event rates compared with higher IVMP doses or IVMP monotherapy, offering a promising regimen for severe gMG.\nTRIAL REGISTRATION: Chinese Clinical Trial Registry (Chictr2400080921).", "authors": ["Gu Shanshan", "Li Yongzhao", "Dong Huimin", "Yang Hongxia", "Ma Mei", "Li Mengna", "Yan Congya", "Jia Pei", "Wang Yaxuan", "Qi Guoyan"], "journal": "Neurology and therapy", "entry_date": "2025/11/19 09:28", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41258322/", "pub_types": ["Journal Article"], "affiliations": ["Center of Treatment of Myasthenia Gravis, Shijiazhuang People's Hospital, Shijiazhuang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41257845", "title": "Elevated triglyceride-glucose index and risk of thymoma-associated myasthenia gravis: a prospective analysis from the UK Biobank.", "abstract": "BACKGROUND: Thymoma-associated myasthenia gravis (MG) is a clinically significant but uncommon condition, affecting up to half of thymoma patients and associated with worse outcomes than either disease alone. Reliable biomarkers for early risk stratification remain scarce. The triglyceride-glucose (TyG) index and triglyceride-to-high-density lipoprotein cholesterol (TG/HDL-C) ratio are established biomarkers reflecting insulin resistance and dyslipidemia. However, their clinical associations with thymoma-associated MG remain incompletely characterized.\nMETHODS: A total of 501,954 UK Biobank participants were included. After exclusions, 422,397 (313 cases) were analyzed for TyG index and 422,691 (314 cases) for TG/HDL-C ratio. Exposures were stratified into quartiles, and assessed continuously per unit increase. Cox proportional hazards models estimated hazard ratios (HRs), restricted cubic splines (RCS) assessed non-linear associations, and subgroup analyses were stratified by body mass index (BMI). Sensitivity analyses examined TyG index and MG alone.\nRESULTS: An elevated TyG index was associated with increased risk of thymoma-associated MG. Compared to Q1, Q4 had higher risk (HR = 1.66, 95% CI: 1.20-2.31, P = 0.003); the overall HR per unit increase was 1.42 (95% CI: 1.17-1.73, P = 0.0005). TG/HDL-C ratio showed similar patterns: Q4 vs Q1 HR = 1.54 (95% CI: 1.11-2.15, P = 0.01); overall HR per unit increase was 1.06 (95% CI: 1.02-1.10, P = 0.002). Non-linear relationships were observed, with suggested inflection points at TyG index 8.7 and TG/HDL-C ratio 2.8, rather than strict thresholds. Subgroup analyses revealed stronger associations in normal-weight and obese participants, although tests for interaction were not statistically significant. Sensitivity analyses confirmed consistent associations between TyG index and MG risk, including for isolated MG.\nCONCLUSION: Elevated TyG index and TG/HDL-C ratio were independently associated with higher thymoma-associated MG risk in this large prospective cohort, with evidence of non-linear relationships and BMI-related heterogeneity. These findings provide novel epidemiologic evidence linking metabolic markers of insulin resistance with thymoma-associated MG, but clinical translation requires further validation.", "authors": ["Zhu Kangle", "Shi Jingwei", "Zhao Jingwei", "Zhao Yi", "Zhang Yao", "Zhang Wuji", "Wei Mingjun", "Zhou Chu", "Yang Rusong", "Liu Zhengcheng", "Liu Zhuo", "Shen Zhixiang"], "journal": "Cardiovascular diabetology", "entry_date": "2025/11/19 08:52", "pub_date": "2025-11-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41257845/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Nanjing Drum Tower Hospital Clinical College of Nanjing Medical University, Nanjing Medical University, Nanjing, 211166, Jiangsu Province, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 10.6, "journal_quartile": "1区"}, {"pmid": "41256960", "title": "The Effect of Apomorphine Therapy in the Coexistence of Parkinson's Disease and Myasthenia Gravis: A Case Report and Review of the Literature.", "abstract": "BACKGROUND: The simultaneous occurrence of Parkinson's disease (PD)-a progressive neurodegenerative disorder marked by the loss of monoaminergic neurons in the substantia nigra-and Myasthenia gravis (MG)-a neuromuscular junction disease-is exceptionally rare. Although these conditions have different pathophysiological foundations, literature reports at least 29 cases of individuals diagnosed with both disorders.\nCASE REPORT: We present the case of a 66-year-old patient treated for Parkinson's disease for four years before being diagnosed with MG, following the onset of dysphagia and bilateral ptosis. Apomorphine infusion, an advanced treatment option, was safely initiated.\nCONCLUSION: This case highlights the coexistence of PD and MG and illustrates the potential benefits of apomorphine infusion therapy. Apomorphine was effective in reducing symptoms, improving motor function, and enhancing the patient's quality of life.", "authors": ["Demir Fidel", "Acar Abdullah", "Akkus Sema"], "journal": "Journal of clinical practice and research", "entry_date": "2025/11/19 05:35", "pub_date": "2024-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41256960/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Selahaddin Eyyubi State Hospital, Diyarbakir, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.2, "journal_quartile": "4区"}, {"pmid": "41255784", "title": "Ocular myasthenia gravis management.", "abstract": "Ocular myasthenia gravis (OMG) has no agreed-upon diagnostic and management criteria, leading to misdiagnoses and often misguided treatments. The purpose of this minireview is to provide guidance to clinicians who encounter possible OMG patients. We cite relevant literature and the recommendations for diagnosis and therapy based on the authors' extensive experience in OMG. This report provides sound recommendations based on the authors' successes and failures, coupled with relevant literature in the myasthenia gravis field.", "authors": ["Kupersmith Mark J", "Wolfe Gil I", "Kaminski Henry"], "journal": "Frontiers in neurology", "entry_date": "2025/11/19 05:18", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41255784/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Ophthalmology, Icahn School of Medicine at Mount Sinai, New York Eye and Ear Infirmary and Union Square Eye Care, New York, NY, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41252449", "title": "Long-Term Outcomes of Surgical Resection for Thymic Epithelial Tumour With Intrathoracic Dissemination.", "abstract": "OBJECTIVES: The treatment of metastatic thymic epithelial tumours (TET) remains challenging with no established protocol, particularly regarding the feasibility of complete surgical resection. This study aimed to elucidate the long-term outcomes and identify risk factors influencing overall survival (OS) and progression-free survival (PFS) following surgical intervention.\nMETHODS: Between July 2000 and November 2021, 149 patients underwent surgery for metastatic TET with intrathoracic metastases at a single centre. Of these patients, 121 met the inclusion criteria. Among them, 93 had thymoma including World Health Organization (WHO) types A, AB, and B1-B3, and 28 had thymic carcinoma. While 73 patients had pleural or pericardial seeding, 48 had lymph node or pulmonary metastasis. Synchronous metastasis was present in 72 patients, whereas 49 had metachronous metastasis.\nRESULTS: The 5- and 10-year OS rates for the entire cohort were 76.4% and 55.1%, respectively. Multivariable analysis identified WHO type as a significant factor affecting OS (HR, 4.260; 95% CI, 2.139-8.482; P < .001). The 5- and 10-year PFS rates were 32.4% and 20.1%, respectively. In multivariable analysis, myasthenia gravis (MG) (HR, 0.362; 95% CI, 0.185-0.851; P = .018), WHO cell type (HR, 3.071; 95% CI, 1.857-5.079; P < .001), and number of metastases (HR, 2.396; 95% CI, 1.273-4.512; P = .007) emerged as risk factors for PFS.\nCONCLUSIONS: Surgical resection for metastatic TET with intrathoracic dissemination demonstrated favourable OS; however, high progression rates necessitated repeated treatments. Factors including the number of metastases, WHO cell type, and the presence of MG were identified as significant determinants influencing PFS.", "authors": ["Kim Eun Chae", "Park Ji Hyeon", "Na Bubse", "Na Kwon Joong", "Park Samina", "Lee Hyun Joo", "Park In Kyu", "Kim Young Tae", "Kang Chang Hyun"], "journal": "Interdisciplinary cardiovascular and thoracic surgery", "entry_date": "2025/11/18 13:44", "pub_date": "2026-03-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41252449/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic and Cardiovascular Surgery, Seoul National University Hospital, Seoul National University College of Medicine, Seoul 03080, Republic of Korea."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41250193", "title": "How should immune checkpoint inhibitor myocarditis be treated?", "abstract": "Immune checkpoint inhibitors (ICIs) have significantly advanced cancer therapy. However, these therapies can disrupt immune self-tolerance, leading to immune-related adverse events, among which immune checkpoint inhibitor-related myocarditis (ICIrM) is associated with the highest mortality rates. Clinical presentation of ICIrM varies widely, ranging from asymptomatic cardiac biomarker elevation to fulminant heart failure. As such, uniform treatment guidelines may not be appropriate, and a personalized approach is essential. There is no universal consensus on routine screening; however, baseline ECG and echocardiography are recommended by most cardio-oncology guidelines. Serial cardiac biomarker monitoring may aid in early detection and intervention. Both cardiac troponin T and cardiac troponin I are sensitive for the diagnosis of ICIrM and prognosis of increased risk of major adverse cardiovascular events. Two diagnostic frameworks for ICIrM help clinicians in establishing diagnosis. Echocardiographic global longitudinal strain measurement provides a more sensitive risk assessment than traditional measures like ejection fraction. Cardiac MRI plays a critical role, offering high diagnostic accuracy. Endomyocardial biopsy confirms ICIrM and provides both diagnostic and prognostic information based on the presence or absence of myocyte necrosis. For confirmed ICIrM, corticosteroids remain the cornerstone of therapy, with high-dose regimens shown to reduce major adverse cardiovascular events. In steroid-refractory or severe cases, adjunctive immunomodulators such as mycophenolate mofetil, janus kinase inhibitors, and notably abatacept are utilized, although evidence is largely case-based. Abatacept, a CTLA-4 fusion protein, is the only drug under investigation in a randomized trial as a targeted therapy for ICIrM. In conclusion, ICIrM represents a diagnostic and therapeutic challenge due to its rarity, heterogeneous presentation, and the limitations of current tools. By describing the management of three illustrative real-life cases, this article aims to provide a framework for individualized management of ICIrM in adults, integrating current guidelines, literature, and clinical experience. Continued research and prospective trials are critical to refine diagnostic algorithms and improve patient outcomes.", "authors": ["Badaan Sally", "Abbass Adi", "Tov Svetlana", "Bar-Sela Gil", "Bisharat Naiel"], "journal": "Cardio-oncology (London, England)", "entry_date": "2025/11/18 00:16", "pub_date": "2025-11-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41250193/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medicine, Emek Medical Center, Clalit Health Services, Afula, Israel."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41248446", "title": "Promising Effects of CAR T-Cell Therapy in Refractory Stiff Person Syndrome and a Hopeful Future for All Neuroautoimmunities.", "abstract": "Chimeric antigen receptor (CAR) T cells are genetically modified T cells expressing CARs, initially developed to recognize tumor antigens and kill cancer cells that evade T-cell recognition. Because of their impressive success in hemato-oncologic malignancies, CAR T cells are being repurposed with redesigned constructs for safety and sustained efficacy to target refractory systemic autoimmune or neurologic diseases. The CD19 CAR T cells-targeting those CD19-positive, antibody-secreting, long-lived plasma cells, and plasmablasts-are now extensively explored in refractory neuroautoimmunities with promising benefits based on case series in patients with myasthenia gravis (MG), stiff person syndrome (SPS), neuromyelitis, myositis, and multiple sclerosis; some patients with MG and SPS with steadily progressive and disabling disease refractory to all available therapies, including rituximab and new biologics, exhibit impressive clinical improvements with long-lasting benefits. The review, triggered by these early results and ongoing trials, addresses what these cells are and why they show effectiveness not only in antibody-mediated B-cell neurologic diseases unresponsive to available anti-B-cell agents but also in patients with nonpathogenic antibodies, implying effects even beyond B cells; points out that CARs are \"living cells\" penetrating physiologic barriers, such as the blood-brain barrier, expanding within tissues to memory cells ensuring sustained effects; describes the process and challenges of preparing and administering CAR T cells and their safety profile stressing the differences in toxicities when treating autoimmunites vs malignancies; and highlights that CD19 CAR T cells can successfully target even 2 different autoimmune diseases in the same patient, such as SPS and MG, offering promising prospects of changing the therapeutic algorithm in all neuroautoimmunities with potential for achieving even an immune reset shifting immunity to a healthy state.", "authors": ["Dalakas Marinos C"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/11/17 16:03", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41248446/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Thomas Jefferson University, Philadelphia, PA; and."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41245608", "title": "The clinical characteristics and treatment response of myasthenia gravis with positive thyroid peroxidase antibody or thyroid globulin antibody.", "abstract": "BACKGROUND AND PURPOSE: Myasthenia gravis (MG) frequently associates with thyroid peroxidase antibody (TPOAb) and thyroglobulin antibody (TgAb), indicating shared autoimmunity. This study investigated the impact of TPOAb/TgAb on MG severity and pathogenesis, to inform improved management.\nMETHODS: We retrospectively analyzed 144 MG patients (Jan 2022-Dec 2024), stratified into four groups by TPOAb/TgAb status. We compared demographic and clinical profiles, analyzed the effects of disease duration, stage, and onset age on TPOAb/TgAb titers, and evaluated treatment responses across groups.\nRESULTS: Among 144 included patients, 55.6 % were thyroid antibody (TAb) - positive (TPOAb + TgAb-: 18.8 %; TgAb + TPOAb-: 9.7 %; TPOAb + TgAb+: 27.1 %). Median onset age was 61 years, 67.5 % were female. TPOAb + TgAb- MG primarily presented as MGFA I (70.4 %), initial onset (63.0 %), with low thymoma (3.7 %) and no TitinAb/RyRAb. TPOAb + TgAb + MG exhibited a severe phenotype: higher MGFA III (30.8 %), relapsed (71.8 % vs 50.0 % in TPOAb-TgAb-, P = 0.030), thymoma (43.6 %), and TitinAb/RyRAb positivity (43.6 %/25.6 %). TgAb titers were significantly higher in relapsed MG (P = 0.001). Both TPOAb + TgAb+ and TPOAb-TgAb- MG responded better to pyridostigmine 90 mg/day, TPOAb + TgAb + MG showed superior response to high-dose glucocorticoids (40-60 mg/day) compared to TPOAb-TgAb- (P = 0.006). However, multivariate analysis indicated TPOAb + TgAb + status itself was not an independent predictor (OR = 0.077, 95 % CI: 0.000-23.487; P = 0.380).\nCONCLUSIONS: This study demonstrates the clinical significance of TPOAb/TgAb in MG. TPOAb + TgAb + status identifies a clinical subgroup with a \"triple-high\" profile. TgAb may show potential as a disease activity biomarker. These findings inform precision treatment strategies, pending validation in large prospective studies.", "authors": ["Xin Hanyu", "Lu Mingou"], "journal": "Journal of translational autoimmunity", "entry_date": "2025/11/17 06:21", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41245608/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Dalian Medical University, Dalian, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "41245531", "title": "Anti-BCMA/CD19 CAR T cell therapy in patients with refractory generalized myasthenia gravis: a single-arm, phase 1 trial.", "abstract": "BACKGROUND: Treating refractory generalized myasthenia gravis is still a big challenge, so new treatments are needed. Several studies have shown the potential of chimeric antigen receptor (CAR) T cell therapy in the treatment of autoimmune diseases. However, no clinical trial of bispecific CAR T cells targeting refractory myasthenia gravis has been done. We developed autologous anti-B-cell maturation antigen (BCMA) and CD19 bispecific CAR T cells to evaluate the safety and efficacy in refractory myasthenia gravis.\nMETHODS: This single-arm, phase 1 trial (ChiCTR2200061267) was conducted at the Affiliated Hospital of Xuzhou Medical University in refractory generalized myasthenia gravis patients (Myasthenia Gravis Activities of Daily Living [MG-ADL] ≥6-point, and Quantitative Myasthenia Gravis scale [QMG] ≥8-point). Anti-BCMA/CD19 bispecific CAR T cells were administered at 1.0 × 106, 3.0 × 106, and 5.0 × 106 CAR T cells per kg. Primary endpoints assessed safety (dose-limiting toxicities, maximum tolerated dose, and adverse events); secondary endpoints assessed disease severity and other related indexes.\nFINDINGS: Between May 3, 2023, and June 19, 2024, 18 patients were enrolled and received apheresis and a single CAR T cell infusion. Mean age was 41 years (SD 12) and 12 (67%) participants were female. The anti-BCMA/CD19 bispecific CAR T cells were generally safe, with no dose-limiting toxicities, no immune effector cell-associated neurotoxicity syndrome, and only grade 1 cytokine release syndrome (39% of patients). The most common grade 3 or worse adverse events within 28 days were hematological toxicities, including three leukopenia, three neutropenia, one anaemia, and one thrombocytopenia. All were transient and manageable. 17 participants completed follow-up. Clinical improvements by day 180 were -8.6 (95% CI -10.2 to -7.0) for MG-ADL score and -15.4 (-17.6 to -13.2) for QMG score. 14 participants (82%) achieved minimal manifestations, 15 (88%) stopped glucocorticoids, all stopped non-steroidal immunosuppressants, and eight (47%) had anti-acetylcholine receptor antibody negative seroconversion.\nINTERPRETATION: Anti-BCMA/CD19 CAR T cells showed good safety and efficacy in refractory generalized myasthenia gravis. A large proportion of participants had a minimal manifestation status and discontinued glucocorticoids and non-steroidal immunosuppressants, and a certain proportion of anti-acetylcholine receptor antibodies turned negative.\nFUNDING: National Natural Science Foundation of China, Basic Research Program of Jiangsu, Young academic leaders of Jiangsu Qinglan Project, and Construction Project of High Level Hospital of Jiangsu Province.", "authors": ["Zhang Yong", "Liu Dan", "Zhang Zhouao", "Huang Xiaoyu", "Cao Jiang", "Wang Gang", "Li Huizhong", "Li Shengli", "Zhang Shenyang", "Zhang Wei", "Chen Hao", "Du Xue", "Wang Zhouyi", "Yang Mingjin", "Luo Tiancheng", "Guo Xinyan", "Ma Tianyu", "Peng Deyou", "Qi Guoyan", "Zong Shenghua", "Cui Guiyun", "Zheng Junnian", "Shi Ming"], "journal": "EClinicalMedicine", "entry_date": "2025/11/17 06:20", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41245531/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Affiliated Hospital of Xuzhou Medical University, Xuzhou, Jiangsu, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 10.0, "journal_quartile": "1区"}, {"pmid": "41245252", "title": "Cryptococcosis in patients with myasthenia gravis: clinical characteristics and management strategy.", "abstract": "BACKGROUND: Cryptococcosis, while well-documented in immunocompromised hosts, remains a rare complication in myasthenia gravis (MG) patients undergoing immunosuppressive therapy.\nMETHODS: We reported three cases of cryptococcal infection in MG patients diagnosed via cryptococcal antigen (CrAg) testing and/or histopathology, coupled with a comprehensive literature review of 14 additional cases that highlights the diagnostic and therapeutic challenges in this population. We also explored potential immunodeficiency by whole-exome sequencing (WES).\nRESULTS: The comibined cohort (median age 57.1 years) demonstrated predominant central nervous system (52.9%), pulmonary (47.1%), and cutaneous (23.5%) involvement, with disseminated disease correlating with markedly decreased CD4+ T cells counts. Diagnostic complexity arose from imaging findings mimicking malignancies. A heterozygous FAS mutation (p.S19L) was identified by WES in one of our patients; however, its association with cryptococcal infection remains unclear. Management required tailored antifungal regimens (amphotericin B, fluconazole, flucytosine) and careful therapeutic drug monitoring to address immunosuppressant interactions. Four patients received surgical management targeting the local lesions. Most cases achieved clinical resolution.\nCONCLUSION: The management of cryptococcal infection in patients with MG poses significant challenges in the context of underlying immune dysfunction and the use of immunosuppressive therapy. Within this complex clinical scenario, early recognition, multidisciplinary care, and individualized treatment strategies are paramount. They underscore the need for heightened clinical vigilance and further research to optimize outcomes in this vulnerable patient population.", "authors": ["Zhang Ce", "Lv Mengyao", "Zhang Xiaotong", "Wang Shu", "Yang Chengshuai", "Wang Qiuting", "Ma Luyuan", "Li Ziyue", "Zhao Caiyan", "Zhao Qian", "Shen Chuan"], "journal": "Frontiers in cellular and infection microbiology", "entry_date": "2025/11/17 06:17", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41245252/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Infectious Disease, Hebei Medical University Third Hospital, Shijiazhuang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41244193", "title": "Effectiveness and safety of therapeutic plasma exchange in neurological disorders; measuring the response to treatment using Modified Rankin Scale - A single-center study.", "abstract": "INTRODUCTION: Therapeutic plasma exchange (TPE) is commonly used as a treatment modality in varying neurological disorders. Response to TPE in neurological disorders is usually noted in \"subjective\" terms. We, measured response to treatment, objectively, using Modified Rankin Scale (MRS).\nMATERIALS AND METHODS: This was an observational prospective study in patients diagnosed with autoimmune neurological disorders (AND) who underwent TPE, in addition to intravenous immunoglobulin, and/or prednisolone. This study was carried out at a tertiary care center. Demographic data, procedure details including adverse reactions, and clinical responses were collated. Clinical response was assessed by applying MRS, in different neurological disorders, before (pre-TPE) and after TPE (post-TPE). Pre- and post-TPE clinical conditions were compared using the Wilcoxon matched-pairs signed-ranks test.\nRESULTS: Fifty-three patients were included, with 15 females and 38 males, who had a median age of 48 years. Seven different AND were; myasthenia gravis (n = 11), Guillain-Barre syndrome (n = 18), neuromyelitis Optica spectrum disorders (n = 6); chronic inflammatory demyelinating polyneuropathy (n = 5); autoimmune encephalitis (n = 6); transverse myelitis (n = 6); and multiple sclerosis (n = 1). Patients received a median of 5 cycles of TPE and a mean 1.5 plasma volume was exchanged. The improvement in the MRS scale was significant when post-TPE scores were compared with pre-TPE scores. The most common adverse reaction was shivering (n = 5; 1.85%), which was managed conservatively.\nCONCLUSION: TPE was shown to be an effective and safe treatment modality in providing relief to patients with neurological disorders.", "authors": ["Gupta Shubham", "Tiwari Aseem Kumar", "Aggarwal Geet", "Bhardwaj Gunjan", "Pawar Samruddhi", "Goyal Vinay", "Garg Arun", "Sehgal Jyoti"], "journal": "Asian journal of transfusion science", "entry_date": "2025/11/17 06:06", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41244193/", "pub_types": ["Journal Article"], "affiliations": ["Department of Transfusion Medicine, Medanta-The Medicity, Gurugram, Haryana, India."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41244179", "title": "Role of therapeutic plasma exchange in myasthenia gravis with thymoma: A case series.", "abstract": "Autoimmune myasthenia gravis (MG) is sometimes associated with thymic abnormalities. Thymectomy is performed in cases of MG with a thymoma or general MG that is resistant to medical therapy. The aims and objectives of the study are to assess the survivability and response to plasma exchange in patients planned for thymectomy in unstable disease activity status of MG. Plasma exchange is indicated before and after thymectomy in unstable disease activity status. Here, we are presenting case summary of five patients undergoing plasma exchange for unstable disease activity status. The outcome was poor in patients having Masoka staging III and Iva, respectively. The survival rate was 60% during an unstable state of MG with thymoma in our study.", "authors": ["Parashar Rashmi", "Bundas Sunita", "Sharma Amit"], "journal": "Asian journal of transfusion science", "entry_date": "2025/11/17 06:06", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41244179/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Immunohematology and Transfusion Medicine, SMS Medical College and Hospital, Jaipur, Rajasthan, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41244175", "title": "Therapeutic plasma exchange for COVID-19 acute respiratory distress syndrome complicated by myasthenia gravis.", "abstract": "The role and safety of therapeutic plasma exchange (TPE) in COVID-19-induced severe acute respiratory distress remains unclear, especially in the wake that a specific and effective treatment modality has not been discovered for the treatment of COVID-19. Here, we report a case where a patient presenting with severe COVID-19 acute respiratory distress syndromes (ARDS) complicated by myasthenia gravis showed significant improvement after the third session of TPE and was subsequently weaned off from the ventilator and shifted to the ward from intensive care unit. TPE can be considered an efficient and safe treatment modality in severe COVID-19 ARDS.", "authors": ["Krishna Aparna", "Pandey Hem Chandra", "Coshic Poonam", "Nair Parvathy Ramachandran", "Haritha Damarla", "Rajan Roopa", "Mehta Vikas"], "journal": "Asian journal of transfusion science", "entry_date": "2025/11/17 06:06", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41244175/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Transfusion Medicine, All India Institute of Medical Sciences, New Delhi, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41243249", "title": "Sclerosing Cholangitis and Multiple Liver Abscesses in a Patient with Thymoma, Myasthenia Gravis, and Immune Deficiency (Good's Syndrome).", "abstract": "BACKGROUND Thymoma is associated with immune deficiencies and can predispose to infections and autoimmune disorders, both of which can lead to hepatobiliary structural disease and infection. CASE REPORT We report the case of a 77-year-old woman with relapsed metastatic thymoma, myasthenia gravis, and hypogammaglobulinemia (Good's syndrome), who developed multiple liver abscesses and sclerosing cholangitis. She presented initially with gram-negative bacteremia with an undetermined source, and rapidly developed multiple liver abscesses. This injury pattern subsequently transformed into clinical and radiologic features of sclerosing cholangitis, with repeated episodes of bacteremia associated with biliary inflammation, identified by PET-CT, while persistent multiple hepatic filling defects remained quiescent. The unique clinical and radiologic features of this patient with both forme fruste liver abscesses and sclerosing cholangitis, are outlined, and the association of thymoma and immune deficiencies with this pattern of hepatobiliary disorder is discussed. Using the TriNetX federated global health research network that enables retrospective analysis of real-world clinical data from multiple health care organizations, we found that thymoma is associated with an increased risk of developing cholangitis. CONCLUSIONS This is the first report of both multiple liver abscesses and infected sclerosing cholangitis complicating thymoma in a patient with acquired immune deficiencies, suggesting that thymoma can predispose to infective hepatobiliary disorders, conceivably through its association with altered immunity and structural changes within the biliary system.", "authors": ["Yaari Shaul", "Stokar Joshua", "Bar Moshe Yehonatan", "Hiller Nurith", "Zuckerman Elena", "Heyman Samuel N"], "journal": "The American journal of case reports", "entry_date": "2025/11/17 01:23", "pub_date": "2025-11-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41243249/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Internal Medicine, Hadassah Hebrew University Hospital, Mt. Scopus, Jerusalem, Israel."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41243030", "title": "The overlooked side of myasthenia gravis: the non-motor manifestations-a comprehensive review.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder of the neuromuscular junction characterized by fluctuating muscle weakness due to antibody-mediated impairment of acetylcholine receptor (AChR) function. Traditionally, MG has been regarded as a disease primarily affecting skeletal muscles, and most research has focused on its motor manifestations. However, increasing evidence suggests that MG is a systemic disorder that can also present with a wide range of non-motor symptoms, which may significantly affect both quality of life and disease outcomes. This review provides a comprehensive overview of the non-motor manifestations of MG, including autonomic, cognitive, psychiatric, sensory, and gastrointestinal disturbances, as well as cardiovascular and sleep abnormalities. We discuss the underlying pathophysiological mechanisms that may explain these symptoms, focusing on immune dysregulation, autonomic imbalance, and potential antibody cross-reactivity with nicotinic acetylcholine receptor subtypes in non-skeletal tissues. Moreover, diagnostic and therapeutic implications are addressed, emphasizing the need for multidisciplinary management to adequately assess and treat these often-overlooked aspects of the disease. Although current evidence remains limited, mainly derived from small cohorts or case reports, the recognition of non-motor symptoms in MG represents an essential step toward a more holistic understanding of the disease. Future research should aim to elucidate their prevalence, underlying mechanisms, and treatment strategies through well-designed, prospective studies. Overall, this review highlights the importance of incorporating the assessment of non-motor manifestations into routine MG care to improve patient outcomes and quality of life.", "authors": ["Messina Christian"], "journal": "Journal of neurology", "entry_date": "2025/11/16 23:15", "pub_date": "2025-11-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41243030/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Azienda Sanitaria Provinciale Catania, Catania, Italy. chry.messina@gmail.com."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41235764", "title": "AXIN1, STAMBP, ST1A1, CDCP1, and SIRT2 Validated as Myasthenia Gravis Biomarkers: A Comparative Proteomic Study With MS, CIDP, and Controls.", "abstract": "BACKGROUND AND PURPOSE: Myasthenia gravis (MG) lacks disease-specific biomarkers that can support monitoring of disease activity or guide treatment decisions. This study aimed to validate serum inflammatory proteins as MG-specific biomarkers by comparing their specificity to controls and individuals with other autoimmune neurological disorders, including multiple sclerosis (MS) and chronic inflammatory demyelinating polyneuropathy (CIDP).\nMETHODS: In this multicentre cross-sectional study, serum from 200 acetylcholine receptor antibody seropositive (AChR+) MG patients, 192 matched controls, 93 MS patients, and 51 CIDP patients was analyzed using a 92-plex inflammation panel (Olink PEA). Logistic regression, principal component analysis, and Boruta machine learning algorithms identified differentially expressed proteins. MG subgroups were defined by age at onset, disease severity, and immunosuppressive treatment.\nRESULTS: Fourteen proteins significantly distinguished MG from controls, including AXIN1 (OR: 0.24), IL7 (OR: 9.38), ST1A1 (OR:0.42), IL10 (OR:3.62), CASP-8 (OR:1.61), and TNFSF14 (OR:0.50) (Bonferroni-corrected p < 0.00135). AXIN1, ST1A1, STAMBP, CDCP1, and SIRT2 were specific for MG, separating it from MS and CIDP. Shared markers across disorders included IL6, IL8, STAMBP, and TNFSF14. A 15-protein profile, including FGF-23 and CXCL9, correlated with MG severity. Subgroup analyses revealed distinct protein patterns by age and treatment. TRANCE and CD6 were reduced in immunosuppressed patients, whereas EN-RAGE, IL10, and TNFRSF9 varied in those receiving biologicals.\nCONCLUSIONS: This study validates the MG-specific serum proteomic biomarkers AXIN1, STAMBP, ST1A1, CDCP1, and SIRT2 and identifies signatures associated with severity, onset, and treatment. These findings support the use of blood-based biomarkers for monitoring and stratification in MG clinical trials and care.", "authors": ["Bhandage Amol K", "Hoffmann Sarah", "Dusemund Carla", "Stascheit Frauke", "Huang Yu-Fang", "Eriksson Niclas", "Gabrysch Katja", "Meisel Andreas", "Punga Anna Rostedt"], "journal": "European journal of neurology", "entry_date": "2025/11/14 07:43", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41235764/", "pub_types": ["Journal Article", "Multicenter Study", "Comparative Study"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41234393", "title": "Exploring the therapeutic potential of IL-17A inhibition in myasthenia gravis: a retrospective study on secukinumab.", "abstract": "OBJECTIVE: Targeting interleukin-17A (IL-17A) represents a potential therapeutic strategy for myasthenia gravis (MG), but its clinical effects and immunomodulatory mechanisms remain incompletely defined. This study investigated the multidimensional efficacy and immune kinetic profile of secukinumab (SEC) in patients with MG.\nMETHODS: We retrospectively enrolled acetylcholine receptor (AChR) antibody-positive (AChR-Ab+) generalised patients with MG (MG Foundation of America class IIa-IVb) treated at the Department of Neurology, Peking University People's Hospital between February 2023 and November 2024. All patients received SEC therapy (150 mg weekly for 4 weeks, followed by 150 mg every 4 weeks as maintenance for 24 weeks). Stable doses of conventional therapies (pyridostigmine, corticosteroids or immunosuppressive agents) were permitted. Longitudinal assessments were performed to evaluate changes in clinical scores (Quantitative MG (QMG) score, 15-item MG Quality of Life (MG-QOL15) scale, MG Activities of Daily Living (MG-ADL) scale), serum AChR-Ab titres, Th17/Tfh (T helper 17 cell/T follicular helper) cell frequencies and cytokine levels at multiple time points.\nRESULTS: A total of 29 patients with MG completed the study and were matched with 29 healthy controls. Following SEC treatment: (a) clinical outcomes: showed that by week 24, significant reductions from baseline were observed in QMG, MG-QOL15 and MG-ADL scores (reductions of 60.7%, 58.3% and 64.1%, respectively; all p<0.01). Significant clinical efficacy emerged by week 8 (25.0% reduction in QMG, p<0.01). (b) Correlations: the reduction in AChR-Ab titres strongly correlated with improvements in clinical scores (r=0.435-0.542, p<0.05). Furthermore, the decrease in Tfh cells showed a significant association with the decline in IL-6 levels (r=0.568-0.591, p<0.001).\nINTERPRETATION: In this study, SEC treatment was associated with rapid and sustained clinical improvement, as well as enhanced quality of life in patients with AChR-Ab+ MG. These benefits were correlated with modulation of the Th17/Tfh cell axis, downregulation of the IL-17A/IL-6 pathway and a reduction in autoantibody levels. These preliminary findings highlight the potential of IL-17A inhibition as a therapeutic strategy worthy of further investigation in MG.", "authors": ["Zhang Zhaoxu", "Zhang Shuang Mei", "Wang Anrong", "Song Xiaodong", "Xu Pingbo"], "journal": "BMJ neurology open", "entry_date": "2025/11/14 04:35", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41234393/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking University People's Hospital, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41233813", "title": "Common features of rare disease patients in the emergency department: a systematised literature review.", "abstract": "BACKGROUND: Patients with rare diseases (RD) may present to the emergency department (ED) with an acute manifestation of an undiagnosed RD. If not identified, some of these patients may suffer from increased morbidity, mortality and worse outcomes compared to patients with more common diseases. Unfortunately, patients with RD often present with common symptoms, e.g. abdominal pain, making it even more difficult for ED physicians to identify those patients. Thus, strategies are needed to determine when certain RD should be suspected in the ED. We aimed to identify common features of RD through a systematised literature review of a predefined set of RD.\nMETHODS: Embase and MEDLINE were searched for eligible studies published in all years up to November 2023. Studies reporting clinical characteristics of patients who presented to the ED with one out of a predefined set of eight RD were included: acute hepatic porphyria, Fabry disease, familial Mediterranean fever, hereditary angioedema, hereditary hemorrhagic telangiectasia, myasthenia gravis, paroxysmal nocturnal hemoglobinuria and thrombotic thrombocytopenic purpura. Clinical characteristics, symptoms and family history were extracted to explore potential common features. Database searches, title, abstract and full-text screening and data extraction were conducted by a single reviewer.\nRESULTS: Of the 4 732 articles identified, 18 were included in the review. For two RD no articles and for three RD only one article could be included. All but two prospective studies were retrospective chart reviews or case series reporting on small patient cohorts (n = 3 - 75 patients). The common features of patients were: age under 65 years, recurrent symptoms affecting multiple organ systems, normal or nonspecific findings in routine laboratory tests and imaging, presence of trigger factors and a positive family history of similar symptoms or RD.\nCONCLUSION: This review highlights the limited knowledge about RD in the ED setting. Some common features of RD patients were identified that could aid future research in developing risk stratification algorithms to facilitate early detection and treatment of RD in the ED. To our knowledge, this is the first literature review to explore the common features of patients with RD in the ED.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s13023-025-04111-6.", "authors": ["Pflock Sandra", "Mücke Hannah Carolina", "Somasundaram Rajan", "Diehl-Wiesenecker Eva"], "journal": "Orphanet journal of rare diseases", "entry_date": "2025/11/13 23:46", "pub_date": "2025-11-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41233813/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Emergency Medicine, Campus Benjamin Franklin, Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Hindenburgdamm 30, 12203, Berlin, Germany. sandra.pflock@charite.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.5, "journal_quartile": "2区"}, {"pmid": "41230121", "title": "Chimeric antigen receptor T-cell therapy for stiff-person syndrome: bridging innovation and clinical challenges in neuroimmunology.", "abstract": "Chimeric antigen receptor T-cells (CAR T-cells) have revolutionized the treatment of hematologic malignancies and are now being explored in autoimmune diseases, including neuroimmunological disorders. The first clinical applications of CAR T-cell therapy for autoimmune diseases have demonstrated promising efficacy, particularly in systemic lupus erythematosus and myasthenia gravis. While CAR T-cell therapy can induce profound B-cell depletion, leading to durable remission, concerns remain regarding cytokine release syndrome and immune effector cell-associated neurotoxicity syndrome. However, neuroimmunological conditions with lower target cell burdens may carry a reduced risk of these adverse events. Recent evidence suggests CAR T-cells could offer a transformative approach for stiff-person syndrome (SPS), a rare but debilitating autoimmune neurological disorder characterized by muscle rigidity and spasms. The first reported case of anti-CD19 CAR T-cell therapy in a treatment-refractory SPS patient resulted in substantial clinical improvement, including increased mobility and reduced dependence on symptomatic medication. A newly launched phase II clinical trial (NCT06588491) aims to further evaluate the safety and efficacy of anti-CD19 CAR T-cell therapy in SPS. In this review, we examine the current evidence supporting the use of CAR T-cells in neuroimmunological conditions, discuss the clinical picture and pathophysiological processes associated with stiff person spectrum disorders (SPSD), and elaborate on perspectives and limitations of CAR T-cell therapy in SPSD and beyond.\nCAR T-cells for stiff-person syndrome CAR T-cell therapy is an innovative treatment originally developed for blood cancers but now being tested for autoimmune diseases. These genetically modified immune cells can precisely target harmful B-cells, potentially offering long-term remission. The first reported use of CAR T-cells in a patient with Stiff-Person Syndrome showed significant improvements in mobility and symptoms without severe side effects. A new clinical trial is investigating whether this therapy could become a standard treatment for this rare neurological disorder.", "authors": ["Wickel Jonathan", "Motte Jeremias", "Ayzenberg Ilya", "Vlad Benjamin", "Gold Ralf", "Geis Christian", "Faissner Simon"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/11/13 04:41", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41230121/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Section Translational Neuroimmunology, Department of Neurology, Jena University Hospital, Jena, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41229873", "title": "Construction of a multimodal artificial intelligence model for differentiating benign and malignant anterior mediastinal tumors.", "abstract": "BACKGROUND: Multimodal data fusion approaches not only capture the multidimensional characteristics of diseases but also compensate for the limitations of single-modality data in clinical diagnostics. These methods are increasingly utilized in clinical practice to significantly improve diagnostic accuracy. Artificial intelligence (AI), particularly in the domain of machine learning, has demonstrated a strong ability to extract meaningful features from large-scale datasets and is now widely applied in medical research. Differentiating benign from malignant anterior mediastinal tumors remains challenging in clinical settings. This study aimed to develop a multimodal AI model to accurately distinguish benign from malignant anterior mediastinal tumors.\nMETHODS: We retrospectively analyzed patients with anterior mediastinal tumors treated at a single hospital between 2021 and 2025. Clinical data, laboratory test results, imaging studies, and final pathological diagnoses were collected. Radiomics features were extracted from chest computed tomography (CT) images and analyzed. Machine learning techniques were used to select key variables. Four predictive models were constructed: a model based solely on clinical variables, a model based solely on imaging features, a multimodal model integrating variables via logistic regression, and a multimodal model based on a random forest algorithm. The performance of each model was evaluated through receiver operating characteristic curve analysis and comprehensive performance metrics to identify the optimal model.\nRESULTS: A total of 104 patients met the inclusion criteria, including 58 cases of benign and 46 cases of malignant anterior mediastinal tumors. Five clinical features and seven imaging features were identified as predictive variables. The logistic regression-based multimodal model achieved the best performance [area under the curve (AUC) =0.94], followed by the clinical-only model (AUC =0.899), the random forest-based fusion model (AUC =0.881), and the imaging-only model (AUC =0.844).\nCONCLUSIONS: The logistic regression-based multimodal model demonstrated superior performance in differentiating benign and malignant anterior mediastinal tumors compared to models based on clinical data alone, imaging data alone, or the random forest approach. This method holds promise for aiding preoperative diagnosis in clinical settings. Notably, features such as tumor cross-sectional diameter, short-axis length on CT, history of myasthenia gravis, lactate dehydrogenase, and carcinoembryonic antigen showed significant clinical value in differentiating tumor types. These findings suggest that clinicians should pay closer attention to these indicators during differential diagnosis of anterior mediastinal tumors.", "authors": ["Zhang Yunxi", "Yang Pingshan", "Zhu Qingyi", "Zeng Kangyao", "Cai Songwang"], "journal": "Journal of thoracic disease", "entry_date": "2025/11/13 04:38", "pub_date": "2025-10-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41229873/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, the First Affiliated Hospital of Jinan University, Guangzhou, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 1.9, "journal_quartile": "3区"}, {"pmid": "41229181", "title": "Pharmacovigilance analysis of FcRn antagonists in the treatment of myasthenia gravis: A disproportionality analysis based on the FAERS database.", "abstract": "This study aimed to evaluate the safety profiles of FcRn antagonists, efgartigimod alfa and rozanolixizumab, in the treatment of myasthenia gravis using real-world adverse event data from the FAERS database. A disproportionality analysis was conducted employing Reporting Odds Ratio (ROR) and Proportional Reporting Ratio (PRR) methods on reports from Q1 2022 to Q2 2025. The most frequently reported adverse events for efgartigimod alfa included falls, urinary tract infections, and symptom recurrence, with signals also detected for atrial fibrillation, peripheral neuropathy, and prostate cancer. For rozanolixizumab, common events were headache, diarrhea, and vomiting, with potential signals such as meningitis, hypersomnia, and feeding disorder. Subgroup analysis revealed gender-specific differences in adverse reactions. Most events occurred within 30 days of treatment initiation, though efgartigimod alfa showed a sustained risk beyond 180 days. The study identifies novel safety signals and highlights clinically relevant risk patterns, supporting enhanced monitoring in clinical use. It is crucial to emphasize that this disproportionality analysis is exploratory in nature and identifies potential associations, which do not establish causality and require confirmation through further dedicated studies.", "authors": ["Liu Boyi", "Zhang Wenchao", "Chen Yuxin", "Han Ao", "Chen Danna"], "journal": "Human vaccines & immunotherapeutics", "entry_date": "2025/11/13 02:33", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41229181/", "pub_types": ["Journal Article"], "affiliations": ["The First Clinical College, Changsha Medical University, Changsha, Hunan, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.5, "journal_quartile": "3区"}, {"pmid": "41229055", "title": "A rare outcome following a bee sting: Total alopecia.", "abstract": "Following bee stings, multiple case reports have described the onset of autoimmune-related conditions, including myasthenia gravis, nephrotic syndrome, Henoch-Schönlein purpura, myocardial infarction, cerebrovascular events, and localized alopecia, typically within a few days, indicating that bee venom may play a role in triggering autoimmunity. We report a rare case of total alopecia occurring within ten days after a bee sting. While the literature includes one prior case of total alopecia following bee sting-induced anaphylaxis, our case is distinct in that the patient developed total alopecia in the absence of any hypersensitivity reactions, suggesting a potential immunomodulatory or exacerbating effect of the bee sting on the immune system.", "authors": ["Kaplankıran Ceren", "Akın Begüm Görgülü", "Soyyiğit Şadan"], "journal": "Allergologia et immunopathologia", "entry_date": "2025/11/13 01:13", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41229055/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Immunology and Allergy, Ankara Bilkent City Hospital, Ankara, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.1, "journal_quartile": null}, {"pmid": "41227236", "title": "Thymectomy in Ocular Myasthenia Gravis: Results Before and After Generalization and Prognostic Predictors of Outcomes.", "abstract": "Background: The role of thymectomy in ocular myasthenia gravis (OMG) remains controversial, particularly before secondary generalization. Methods: We conducted a multicenter retrospective study on 174 OMG patients who underwent thymectomy (112 OMG, 62 generalized OMG [g-OMG]). The primary endpoint was complete stable remission (CSR; MGFA-PIS criteria). Multivariable analyses identified predictors of CSR and generalization. Results: Mean age at surgery was 42.3 ± 13.0 years; 53.4% were male. Thymoma was present in 29.3%. CSR was achieved in 18.9% overall, significantly higher in OMG (23.2%) compared to g-OMG (11.3%, p = 0.036), with 5-year CSR probabilities of 43% vs. 22% (p = 0.017). In non-thymomatous patients, 5-year CSR remained higher in OMG (41% vs. 17%, p = 0.010). Postoperative myasthenic crisis occurred exclusively in g-OMG (8.1%, p = 0.004). Multivariable analysis identified preoperative cholinesterase inhibitor monotherapy as an independent predictor of CSR (HR = 31.776, 95% CI: 4.188-241.111, p = 0.001; non-thymomatous: HR = 19.746, 95% CI: 2.518-154.849, p = 0.005). Minimally invasive techniques (78.6%) were associated with low morbidity (5.2%). Conclusions: Thymectomy during the purely ocular stage is associated with higher CSR rates and lower perioperative neurological risk than after generalization, particularly in non-thymomatous disease. Use of cholinesterase inhibitors as sole therapy prior to thymectomy independently predicts CSR. These findings support earlier surgical consideration in selected OMG patients and highlight the safety of minimally invasive approaches.", "authors": ["Nachira Dania", "Congedo Maria Teresa", "Kuzmych Khrystyna", "Evoli Amelia", "Iorio Raffaele", "Vita Maria Letizia", "Petracca-Ciavarella Leonardo", "Nocera Adriana", "Sassorossi Carolina", "Evangelista Jessica", "Lyberis Paraskevas", "Comacchio Giovanni Maria", "Brandolini Jury", "Aprile Vittorio", "Zifara Carmelina Cristina", "Mastromarino Maria Giovanna", "Patirelis Alexandro", "Asteggiano Elena", "Anile Marco", "Venuta Federico", "Imperatori Andrea", "Ambrogi Vincenzo", "Solli Piergiorgio", "Dell'Amore Andrea", "Lucchi Marco", "Melfi Franca", "Ibrahim Mohsen", "Ruffini Enrico", "Rea Federico", "Margaritora Stefano", "Meacci Elisa"], "journal": "Journal of clinical medicine", "entry_date": "2025/11/13 01:06", "pub_date": "2025-11-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41227236/", "pub_types": ["Journal Article"], "affiliations": ["Department of General Thoracic Surgery, Fondazione Policlinico Universitario \"A. Gemelli\", IRCCS, Università Cattolica del Sacro Cuore, 00168 Rome, Italy."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41223006", "title": "Robotic thoracic surgery: what is different in anesthesia?", "abstract": "PURPOSE OF REVIEW: Robotic-assisted thoracic surgery (RATS) has emerged as a transformative approach in thoracic surgery, enabling enhanced precision and minimally invasive treatment for lung, esophageal, and mediastinal resections. These advances introduce unique anesthetic challenges requiring tailored strategies to ensure patient safety and surgical success.\nRECENT FINDINGS: Key challenges include intrathoracic carbon dioxide insufflation, prolonged one-lung ventilation, and complex positioning. Special considerations apply to high-risk groups such as patients with myasthenia gravis, obesity, and frailty. Advances in anesthetic management include individualized lung isolation with double-lumen tubes or bronchial blockers, protective ventilation with permissive hypercapnia, and restrictive fluid strategies supported by invasive monitoring. Deep neuromuscular blockade is often needed to maintain stability during robotic manipulation. Multimodal regional anesthesia and enhanced recovery after surgery (ERAS) pathways are increasingly applied, improving analgesia, reducing opioid exposure, and facilitating early extubation and mobilization. Novel approaches such as subpleural anesthetic infusion, continuous airway visualization devices, and perioperative artificial intelligence (AI) applications are being explored.\nSUMMARY: RATS present distinct anesthetic challenges and opportunities. Integration of tailored airway and ventilation strategies, vigilant hemodynamic management, regional analgesia, and ERAS principles is essential. Future priorities include AI-supported monitoring, simulation-based training, and global consensus frameworks to standardize anesthetic practice.", "authors": ["Szegedi Laszlo L", "Tuna Turgay", "Samara Evangelia", "Tzimas Petros", "El Tahan Mohamed R"], "journal": "Current opinion in anaesthesiology", "entry_date": "2025/11/12 12:03", "pub_date": "2026-02-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41223006/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Anesthesiology, Université Libre de Bruxelles, H.U.B Hôpital Erasme, Brussels, Belgium."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "41221456", "title": "Pembrolizumab-induced fulminant triple M syndrome presenting with severe bradycardia.", "abstract": "Immune checkpoint inhibitors have markedly transformed cancer treatment paradigms but are frequently associated with immune-related adverse events (irAEs) affecting multiple organ systems. Among the rare and severe complications is the \"triple M syndrome\", encompassing myositis, myocarditis, and myasthenic syndrome. We present the case of an 83-year-old male with stage IIc melanoma who received pembrolizumab as adjuvant therapy following surgical excision of the primary tumor and regional lymph nodes, with no evidence of neoplastic invasion. Approximately one month post-infusion, the patient experienced episodes of syncope, leading to the diagnosis of a second-degree atrioventricular block. Despite normal findings on echocardiography, the patient subsequently developed profound proximal muscle weakness, dysphonia, and dysphagia. Pembrolizumab was promptly discontinued, and the patient was initiated on high-dose intravenous methylprednisolone; however, his clinical course rapidly deteriorated, culminating in the necessity for palliative care due to progressive respiratory failure. This case underscores the potential for severe, life-threatening irAEs associated with pembrolizumab therapy, particularly in the form of triple M syndrome. Notably, the manifestations of myocarditis and myasthenia gravis (MG) within this context may occur in the absence of typical autoantibody markers, thereby complicating the diagnostic process and contributing to poor prognostic outcomes. This case highlights the imperative for heightened clinical vigilance and a proactive approach to monitoring for irAEs in patients receiving immune checkpoint inhibitors. Early recognition, coupled with the prompt initiation of therapeutic interventions, is paramount in mitigating morbidity and improving clinical outcomes in these critical scenarios.", "authors": ["Mihon Maia Ioana", "Pamfil Cristina", "Beyer Ruxandra", "Tomoaia Raluca", "Gherasim Anca Roxana", "Deac Andrada", "Zdrenghea Mihnea Tudor", "Poltorac Virgil-Ioan", "Fodor Dana Marieta", "Mariş Adrian", "Damian Laura Otilia", "Rednic Simona"], "journal": "Medicine and pharmacy reports", "entry_date": "2025/11/12 04:35", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41221456/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Rheumatology, Emergency County Clinical Hospital Cluj, Cluj-Napoca, Romania."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41219665", "title": "Clinical Impact of High-Dose Corticosteroids on Healthcare Resource Utilization and Steroid-Related Complications in Patients with Myasthenia Gravis in Japan.", "abstract": "INTRODUCTION: Oral corticosteroids (OCS) are commonly used to control symptoms in patients with myasthenia gravis (MG). Long-term high-dose OCS use is associated with serious side effects, but the real-world clinical impact of high-dose OCS in patients with MG is not well understood. The main objectives of this study were to evaluate healthcare resource utilization and clinical complications associated with high-dose versus low-dose OCS use in Japanese patients with MG.\nMETHODS: A retrospective cohort study was performed using JMDC, a Japanese claims database. Patients with newly diagnosed MG (incident cases) were identified, and the date of the first diagnosis of MG was defined as the index date. Patients were stratified into two groups by OCS dose level (high-dose OCS ≥ 7.5 mg/day; low-dose OCS < 7.5 mg/day; based on the average dose in the population during the follow-up). Patient characteristics, treatments, long-term hospitalization (≥ 10 days cumulative per year), and corticosteroid-related complications were assessed.\nRESULTS: Of 2107 patients with an incident MG diagnosis, 576 were on OCS (high-dose OCS, 210; low-dose OCS, 366) during the follow-up period. There were no obvious differences in baseline comorbidities between the high- and low-dose OCS groups. A significant increase in long-term hospitalization was observed in the high-dose OCS versus the low-dose OCS group (adjusted odds ratio [95% CI], 1.832 [1.180, 2.845], P = 0.007). A greater proportion of patients in the high-dose OCS group versus the low-dose OCS group received ≥ 1 course per year of in-hospital intravenous immunoglobulin (34.8% vs. 15.3%), plasma exchange therapy (16.2% vs. 8.2%), and intravenous methylprednisolone pulse therapy (33.3% vs. 24.0%). The incidence of new complications such as diabetes, osteoporosis, osteoporotic fractures, neuropsychiatric disease, and sepsis was significantly (P < 0.05) higher with high- versus low-dose OCS.\nCONCLUSION: Use of high-dose OCS in patients with MG was associated with adverse outcomes, including increased rates of long-term hospitalizations and clinical complications.", "authors": ["Numajiri Naoki", "Yamamoto Takanori", "Waratani Miina", "Takahashi Masanori P"], "journal": "Neurology and therapy", "entry_date": "2025/11/11 23:38", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41219665/", "pub_types": ["Journal Article"], "affiliations": ["Alexion Pharma GK, AstraZeneca Rare Disease, Tokyo, Japan. naoki.numajiri@alexion.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41217187", "title": "Successful treatment of rheumatoid arthritis complicated with myasthenia gravis by telitacicept: a case report.", "abstract": "So far cases of rheumatoid arthritis (RA) complicated with myasthenia gravis (MG) are rare in reports, and specific treatment measures remain unclear. Therefore, this paper presents a case of a 57-year-old female patient with a history of MG who currently has rheumatoid arthritis. After conventional treatment failed, the patient started subcutaneous injection of telitacicept, which led to rapid and sustained clinical improvement. This is the first report on the treatment of RA complicated with MG by telitacicept. Meanwhile, the application of telitacicept in the treatment of this disease deserves further research and attention.", "authors": ["Qiu Sheng", "Ying Zhenhua"], "journal": "Modern rheumatology case reports", "entry_date": "2025/11/11 09:03", "pub_date": "2025-07-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41217187/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["The Second School of Clinical Medicine, Zhejiang Chinese Medical University, Zhejiang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "41213488", "title": "IMPDH2 facilitates CD4+ T cell activation through AKT/mTOR pathway by upregulating SRPK1 in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a T cell-mediated autoimmune disease characterized by abnormal immune responses, particularly the hyperactivation of CD4+ T cells, which may disrupt signal transmission at the neuromuscular junction. Inosine-5'-monophosphate dehydrogenase-2 (IMPDH2) has been reported to participate in immune activation and is likely associated with T cells, but its role in the pathogenesis of MG remains unclear. Therefore, the present study aimed to elucidate the mechanism through which IMPDH2 regulates CD4+ T cells in MG.\nMETHODS: In this study, IMPDH2 expression was measured by qRT-PCR in peripheral blood mononuclear cells (PBMCs) collected from 60 MG patients and 60 healthy controls. Western blotting was additionally performed to detect IMPDH2 protein expression in six MG patients (three ocular and three generalized), compared with six healthy controls matched by age, gender, and sample collection time. CD4+ T cells were then isolated from PBMCs of MG patients and healthy controls by immunomagnetic bead sorting, and IMPDH2 expression was further analyzed by qRT-PCR. Subsequently, correlations between IMPDH2 expression levels and clinical indices (neutrophil and lymphocyte counts) as well as disease severity (Myasthenia Gravis Activities of Daily Living scores and Quantitative Myasthenia Gravis scores) were assessed. Additionally, flow cytometry, EdU assays, and CCK-8 assays were employed to evaluate the effects of IMPDH2 knockdown or overexpression on CD4+ T cell apoptosis and proliferation. The expression of apoptosis-related proteins was detected by western blotting. Mass spectrometry (MS), co-immunoprecipitation (Co-IP), and kinase inhibitor-based Co-IP validation assays were used to screen and verify proteins potentially interacting with IMPDH2 in CD4+ T cells. The colocalization of IMPDH2 and its binding proteins in CD4+ T cells was confirmed by confocal fluorescence microscopy and quantitative analysis. Furthermore, western blotting was performed to assess regulatory interactions between IMPDH2 and its binding proteins upon knockdown of either molecule. Western blotting was also used to detect protein levels within MG-related signaling pathways following IMPDH2 knockdown or overexpression.\nRESULTS: IMPDH2 expression was significantly elevated in PBMCs and CD4+ T cells from MG patients compared with healthy controls. Clinical data analysis demonstrated a positive correlation between IMPDH2 expression and both lymphocyte and neutrophil counts in MG patients. Additionally, IMPDH2 expression positively correlated with MG disease severity. Functionally, upregulation or downregulation of IMPDH2 correspondingly promoted or suppressed CD4+ T cell proliferation and apoptosis. Mechanistically, direct interactions between IMPDH2 and SRPK1 were confirmed in vitro, and IMPDH2 was found to regulate SRPK1 expression, subsequently affecting CD4+ T cell proliferation and apoptosis in MG. Furthermore, IMPDH2 was shown to activate the AKT/mTOR signaling pathway by modulating SRPK1 expression.\nCONCLUSIONS: This study revealed that IMPDH2 is highly expressed in PBMCs and CD4+ T cells from MG patients, implicating its role in aberrant T cell activation during MG pathogenesis. IMPDH2 potentiates the AKT/mTOR signaling pathway in CD4+ T cells through its interaction with and upregulation of SRPK1 expression, thereby inhibiting CD4+ T cell apoptosis and promoting their proliferation in MG. These findings provide novel insights and potential therapeutic targets for modulating autoimmune responses in MG.", "authors": ["Ren Yingjie", "Wu Tao", "Liu Zhaojun", "Li Lifang", "Li Ying", "Xin Guanghao", "Peng Shanshan", "Niu Jingyan", "Chen Biying", "Cai Hanlu", "Tian Qinghua", "Wang Lihua", "Zhang Huixue"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2025/11/10 19:14", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41213488/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Harbin Medical University, Harbin, Heilongjiang, China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41211783", "title": "Rozanolixizumab as rescue therapy in triple-seronegative refractory generalized myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disease affecting the neuromuscular junction, most commonly associated with anti-acetylcholine receptor antibodies, less frequently with muscle-specific kinase antibodies, and occasionally with low-density lipoprotein receptor-related protein 4 antibodies. However, a subset of patients with MG tests negative for all of these three antibodies - termed triple-seronegative MG - posing significant diagnostic and therapeutic challenges. Fast-acting therapies, such as intravenous methylprednisolone (IVMP), intravenous immunoglobulin (IVIG) and plasma exchange (PLEX), are typically recommended during disease exacerbation. However, some patients are refractory to these interventions. For refractory patients with triple-seronegative MG, the efficacy of a recent monoclonal antibody therapy as rescue therapy remains uncertain. We report a case of triple-seronegative MG refractory to repeated IVIG, IVMP and PLEX, in which clinical improvement was achieved following treatment with rozanolixizumab. This case, with long-term follow-up, suggests the potential utility of rozanolixizumab as rescue therapy in a patient subgroup which is typically excluded from randomized controlled trials. Larger studies specifically including patients with triple-seronegative MG are warranted.", "authors": ["Takenobu Yohei", "Kikuchi Takayuki", "Ishikawa Daiki", "Nomura Noriko", "Tamaki Shunsuke", "Yukawa Kayoko", "Inoue Mari", "Hatano Karen", "Miyahara Junichi", "Yamakawa Kentaro", "Higuchi Osamu", "Inoue Manabu"], "journal": "Immunological medicine", "entry_date": "2025/11/10 07:43", "pub_date": "2026-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41211783/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, Osaka Red Cross Hospital, Osaka, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41211059", "title": "Sepsis complicated by haemophagocytic lymphohistiocytosis triggered by methicillin-resistant Staphylococcus aureus and human herpesvirus 8 in an immunocompromised elderly patient: A case report.", "abstract": "Sepsis is a life-threatening organ dysfunction caused by a dysregulated host response to infection. A rare but severe complication is haemophagocytic lymphohistiocytosis (HLH), an aggressive syndrome of excessive immune activation. Managing both conditions is particularly challenging in patients with multiple comorbidities. A 78-year-old male with a complex history, including myasthenia gravis and chronic kidney disease, was admitted with sepsis. Investigations confirmed infection with methicillin-resistant Staphylococcus aureus and human herpesvirus 8. He was subsequently diagnosed with HLH based on bone marrow findings of haemophagocytosis and elevated soluble CD25 levels. He was treated with a combination of antibiotics, immunomodulatory agents, and supportive care. After 21 days of treatment, the patient's condition improved significantly. This case highlights the importance of early recognition and timely intervention in the management of sepsis and HLH in patients with multiple comorbidities. A multidisciplinary approach and individualised treatment strategies are crucial for improving patient outcomes.", "authors": ["He Min", "Chen Yanni", "Huang Shanbo", "Wang Yongqin", "Lin Guanrong", "Huang Chaoling"], "journal": "Open life sciences", "entry_date": "2025/11/10 06:13", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41211059/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Endocrinology, Shishi General Hospital, Fujian Province, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "41210436", "title": "Management of stage IVa thymoma with coexistence of Lambert-Eaton myasthenic syndrome and myasthenia gravis in a postpartum female case report.", "abstract": "BACKGROUND: Thymoma is a rare malignancy accounting for less than 2% of annual cancer diagnoses. While commonly associated with myasthenia gravis (MG), its association with Lambert-Eaton myasthenic syndrome (LEMS), a paraneoplastic syndrome typically linked to small cell lung cancer, is rare. Even rarer are cases with overlapping features of both syndromes.\nCASE DESCRIPTION: We report a 36-year-old postpartum Asian woman with overlapping clinical features of LEMS and MG attributed to her stage IVa thymoma, and minimally responsive to chemotherapy, thus requiring aggressive surgical debulking with cardiopulmonary bypass (CPB). She presented 2.5 weeks postpartum with dyspnea and right pleuritic chest pain. Computed tomography (CT) imaging demonstrated a >20 cm heterogeneous right pleural mass, and a separate 10 cm anterior mediastinal mass invading the superior vena cava (SVC) and innominate vein. Biopsy confirmed thymoma type B2. Further positron emission tomography (PET)/CT imaging showed no distant metastasis. The Multidisciplinary Tumor Board recommended neoadjuvant chemotherapy due to vascular invasion, followed by surgical resection. A month later, she developed worsening dyspnea, diplopia, dysphagia, and generalized extremity weakness with serologic testing positive for acetylcholine receptor (AChR) blocking antibodies. She was diagnosed with a paraneoplastic neuromuscular syndrome attributed to her stage IVa malignant thymoma. She was started on pyridostigmine, an acetylcholinesterase inhibitor, improving her symptoms. Restaging CT showed minimal response to chemotherapy, necessitating palliative debulking surgery, including right extrapleural pneumonectomy, thymectomy, SVC repair, and pericardial and diaphragm reconstruction. Pathology confirmed diffuse thymoma type B2 with R1 resection. She recovered uneventfully and underwent adjuvant radiation therapy, and remains disease-free on interval surveillance imaging.\nCONCLUSIONS: This rare case of stage IVa thymoma in a postpartum Asian woman with overlapping features of LEMS and MG highlights the role of acetylcholinesterase inhibitors for symptom management, and the role of aggressive radical debulking surgery with CPB, in a young, otherwise healthy patient.", "authors": ["Gochi Andrea M", "Liang Elaine", "Guha Shreya", "Velotta Jeffrey B"], "journal": "AME case reports", "entry_date": "2025/11/10 06:08", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41210436/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Surgery, University of California San Francisco-East Bay, Oakland, CA, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41209955", "title": "Thymoma in Ectopic Thymus: An Overlooked Differential and a Pathologist's Dilemma.", "abstract": "Thymomas arising in thymic tissue located in an abnormal location are rarely described in medical literature and present with a wide range of diagnostic dilemmas. Amongst the abnormal locations for ectopic thymus, the thyroid serves as the most common site; however, case reports of ectopic thymic tissue have also been seen in rarer locations, such as the middle ear, base of the skull, submandibular gland, and tonsils. Myasthenia gravis (MG), a paraneoplastic syndrome associated with thymomas, is very rare in cases of ectopic site thymomas. In this report, we present one such case of a 44-year-old female patient who initially presented with generalised weakness, difficulty breathing, and loss of appetite for one week. Differential diagnoses of tuberculosis, lymphoma, and metastatic malignancies were considered clinically. A contrast-enhanced computed tomography of the neck, thorax, and abdomen indicated the presence of a mild homogenously enhancing mediastinal mass (6.6x5.4x4.0 cm) in the right para-tracheal region abutting the left distal brachio-cephalic vein and the superior vena cava. Prompt laboratory examination, specifically fine needle aspiration cytology and cell block evaluation of the mediastinal mass, helped categorise the lesion as type B2 thymoma. The patient was advised of a thymectomy but refused and presented months afterwards with a diagnosis of MG. Ectopic thymic foci along with the thymus were removed, and a diagnosis of type B2 thymoma in the mediastinal mass was substantiated. The reported case highlights the rarity of MG in patients with ectopic thymoma and the importance of a strong clinical suspicion and laboratory findings in making a correct diagnosis, eventually leading to better patient management.", "authors": ["Kalita Pranjal", "Mawlong Alexandra K", "Suiam Neoky", "Bhattacharjee Mainak", "Raphael Vandana"], "journal": "Cureus", "entry_date": "2025/11/10 06:04", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41209955/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Pathology, North Eastern Indira Gandhi Regional Institute of Health and Medical Sciences, Shillong, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41209176", "title": "Inpatient Utilization of Therapeutic Plasma Exchange in the United States: 2016-2021.", "abstract": "RATIONALE & OBJECTIVE: Therapeutic plasma exchange (TPE) is used in a variety of autoimmune, inflammatory, hematological, and metabolic disorders. We described the contemporary scope of inpatient utilization of TPE in the United States.\nSTUDY DESIGN: A cross-sectional study.\nSETTING & PARTICIPANTS: The national inpatient sample dataset from year of 2016 to 2021.\nEXPOSURES: Inpatient utilization of TPE.\nOUTCOMES: We described demographics, associated comorbid conditions, hospital characteristics, and hospital costs by comparing patients treated with those not treated by TPE. We reported the top 25 clinical conditions treated by TPE. We described the top 10 diseases or conditions for the first discharge diagnosis as acute kidney injury (AKI) (International Classification of Diseases, Tenth Revision code: N17.9) treated by TPE.\nANALYTICAL APPROACH: All descriptive and multivariable analyses considered the complex survey design for every calendar year sampling of national inpatient sample; the results were weighted to reflect national estimates.\nRESULTS: During 2016-2021, a total of 106,035 hospitalizations (∼0.051% of the total hospitalizations) were treated by TPE. The 5 most common conditions treated by TPE were myasthenia gravis with (acute) exacerbation (9.53%), Guillain-Barre syndrome (6.19%), thrombotic microangiopathy (6.18%), kidney transplant rejection (5.42%), and sepsis, unspecified organism (3.62%). AKI was the 13th most common condition, accounting for 1.82% of all cases treated by TPE, while the most common underlying condition for AKI was multiple myeloma (without achieving remission). The temporal trend of indications used by TPE in the US practice from 2016 to 2021 aligns well with the updated guideline by the American Society of Apheresis. The TPE utilization was associated with higher inpatient costs after accounting for length of stay; odds ratio ranges: 3.47 (2.99-4.03)-11.07 (10.19-12.03).\nLIMITATIONS: Lack of laboratory data.\nCONCLUSIONS: The TPE continues to be used to treat a variety of serious autoimmune and inflammatory diseases, in accordance with published clinical practice guidelines.\nThe national inpatient sample (NIS) captures ∼96% of hospitalizations in the United States by sampling 20% of inpatient discharges. We identified patients from the NIS who received inpatient therapeutic plasma exchange from 2016 to 2021. The analysis accounted for the complex survey design of the NIS for each calendar year. We described patient demographics and comorbid conditions, analyzed trends in clinical indications over time, and used multivariable weighted logistic regression models to examine the costs associated with utilization, stratified by length of stay. In addition, we identified the top 10 secondary diagnoses most commonly associated with a primary diagnosis of acute kidney injury requiring inpatient therapeutic plasma exchange.", "authors": ["Tao Jianling", "Zheng Sijie", "Agolli Lusilda", "Alvarez Luis", "Ahearn Patrick", "Rehkopf David H", "Chertow Glenn M", "Kamdar Neil S"], "journal": "Kidney medicine", "entry_date": "2025/11/10 05:57", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41209176/", "pub_types": ["Journal Article"], "affiliations": ["Division of Nephrology, Department of Medicine, Stanford University School of Medicine, CA."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "41208643", "title": "Chimeric Antigen Receptor T-Cell Therapy and Autoimmune Diseases in the Nervous System.", "abstract": "INTRODUCTION: Chimeric antigen receptor T-cell (CAR-T) therapy, a revolutionary immunotherapy originally developed for hematologic malignancies, has recently gained attention for its potential in treating autoimmune diseases. Increasing evidence suggests that CAR-T cells can precisely target pathogenic immune populations, offering durable remission and immune homeostasis restoration in neuroimmunological disorders such as myasthenia gravis (MG), neuromyelitis optica spectrum disorder (NMOSD), and multiple sclerosis (MS).\nMETHODS: Relevant publications and clinical trial data up to September 2025 were systematically reviewed to summarize the mechanisms, therapeutic targets, safety profiles, and translational applications of CAR-T therapy in autoimmune diseases of the nervous system.\nRESULTS: Preclinical and early clinical studies demonstrate that CD19- and BCMA-directed CAR-T therapies effectively deplete autoreactive B cells with significant symptom improvement and minimal cytokine release syndrome or neurotoxicity. Novel constructs such as chimeric autoantibody receptor (CAAR)-T and CAR-regulatory T (CAR-Treg) cells enhance specificity and immune tolerance. Innovations including allogeneic \"off-the-shelf\" CAR-T, in vivo CAR engineering, and CRISPR-based safety switches further optimize therapeutic potential and accessibility.\nCONCLUSION: CAR-T therapy represents a promising frontier for refractory neuroautoimmune diseases. By precisely modulating immune networks, it offers a pathway toward long-term remission and personalized immunotherapy in clinical neuroimmunology.", "authors": ["Yao Shun-Yu", "Du Miao-Qiao", "Yang Huan", "Zeng Qiu-Ming", "Zhou Hao", "Zhang Xiuli", "Kazuo Sugimoto", "Liu Jia", "Lin Lan-Xin", "Kang Xu-Hui", "Jiang Dai-Yi", "Peng Yong"], "journal": "Immunity, inflammation and disease", "entry_date": "2025/11/10 04:52", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41208643/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Affiliated First Hospital of Hunan Traditional Chinese Medical College, Zhuzhou, Hunan, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41205003", "title": "Measuring the effect of rozanolixizumab using the Myasthenia Gravis Impairment Index: analyses from the randomized phase 3 MycarinG study.", "abstract": "BACKGROUND: Generalized myasthenia gravis (gMG) is an autoimmune disease characterized by fluctuating muscle weakness. The MG Impairment Index (MGII) incorporates patients' perspectives (22 items) and physician evaluation (6 items) of impairment. We evaluated the effect of rozanolixizumab using the MGII in the randomized, double-blind, placebo-controlled, Phase 3 MycarinG study.\nMETHODS: Adult patients with gMG were randomized 1:1:1 to once-weekly rozanolixizumab 7 mg/kg, 10 mg/kg or placebo for 6 weeks. MGII assessment was optional. Exploratory MGII analyses included change from baseline (CFB) to Day 43 in total score and ocular/generalized subscores; higher scores reflect greater impairment. Post hoc analyses included responder rates (≥ 5.5-point improvement) and achievement of patient-acceptable symptom state (PASS; ≤ 10 points, patient-reported items only).\nRESULTS: Overall, 200 patients received rozanolixizumab 7 mg/kg (n = 66), 10 mg/kg (n = 67) or placebo (n = 67). The MGII was completed by 144/200 (72.0%) patients. Mean CFB in MGII total score was greater in the rozanolixizumab groups versus placebo; mean CFB in ocular and generalized subscores was consistent with the total score. At Day 43, 57.1%, 83.3% and 40.4% of patients, respectively, were responders, and 30.8%, 39.2% and 7.7%, respectively, achieved MGII PASS. Responsiveness correlations between MGII total score CFB and MG-ADL anchor at Day 43 demonstrated a Spearman's correlation coefficient of 0.5991 (p < 0.0001).\nCONCLUSION: These findings further support efficacy analyses from MycarinG to highlight the benefit of rozanolixizumab in patients with gMG and demonstrate the utility of the MGII in evaluating patient-relevant symptoms following treatment.\nTRIAL REGISTRATION: NCT03971422 (registered May 29, 2019).", "authors": ["Barnett-Tapia Carolina", "Cortés Vicente Elena", "Pascuzzi Robert M", "Utsugisawa Kimiaki", "Bloemers Jos", "Grimson Fiona", "Tarancón Thaïs", "Bril Vera"], "journal": "Journal of neurology", "entry_date": "2025/11/08 11:24", "pub_date": "2025-11-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41205003/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase III", "Multicenter Study"], "affiliations": ["Ellen and Martin Prosserman Centre for Neuromuscular Diseases, Toronto General Hospital, University of Toronto, Toronto, ON, Canada. c.barnetttapia@utoronto.ca."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41200447", "title": "Anti-ALDOA antibody: a novel diagnostic-associated autoantibody in myasthenia gravis.", "abstract": "This study identified novel autoantibodies in patients with seronegative myasthenia gravis (SNMG).Autoantibodies in SNMG sera were screened using a targeted binding assay (TBA). The target antigen was identified via immunoprecipitation and mass spectrometry, and validated by western blotting using a commercial antigen. A cell-based assay (CBA) employing HEK293 cells expressing the identified antigen was established to detect specific antibodies in 676 MG patients and 20 controls.Aldolase A (ALDOA) was identified as a novel autoantigen. Anti-ALDOA antibodies (ALDOA-Ab) demonstrated high diagnostic specificity in SNMG and were also detected in seropositive MG patients, with positivity rates of 4.89% in AChR-Ab' and 2.86% in MuSK-Ab' subgroups. ALDOA-Ab was predominantly of the IgG1 subclass. ALDOA-Ab may serve as a potential diagnostic biomarker for MG. Further studies are needed to investigate its pathogenic role.", "authors": ["Zhang Mengdi", "Zhang Yingna", "Liu Peipei", "Gao Qingye", "Liu Qian", "Zhou Xinyue", "Liu Ruichen", "Zhao Xue", "Zhang Jing", "Hu Jia", "Dong Haiyan", "Liu Jing", "Yang Junhong", "Ruan Zhe", "Chang Ting", "Lv Jie", "Gao Feng"], "journal": "Frontiers in neurology", "entry_date": "2025/11/07 04:23", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41200447/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41200446", "title": "Safety profile and efficacy of secukinumab in the treatment of autoimmune myasthenia gravis: a single-center retrospective study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic autoimmune disease caused by autoantibodies attacking the neuromuscular junction. Traditional treatments are often accompanied by side effects and lack specificity. Recent studies have found that Th17 cells and the inflammatory factor IL-17, which they secrete, play a key role in the pathogenesis of MG and have become potential therapeutic targets. Secukinumab, an IL-17 inhibitor, has shown efficacy in other autoimmune diseases, but its role in MG remains unexplored.\nOBJECTIVE: This study aimed to evaluate the clinical efficacy and immunomodulatory effects of secukinumab in acetylcholine receptor antibody-positive generalized MG (AChR+ gMG).\nMETHODS: In this single-center retrospective study, 29 AChR+ gMG patients received subcutaneous secukinumab (150 mg weekly for 4 weeks, then monthly for 24 weeks). Clinical outcomes (QMG, MG-QOL15, MG-ADL scores), AChR antibody titers, Th17 cell frequency, and IL-17 levels were assessed at baseline and during treatment. Correlations between biomarkers and clinical improvements were analyzed.\nRESULTS: By week 24, secukinumab treatment led to significant reductions in disease severity scores (QMG: 60.7%; MG-QOL15: 58.3%; MG-ADL: 64.1%) and AChR antibody levels (69.23%). Th17 cell frequency and IL-17 levels decreased by 68 and 84.47%, respectively. Strong baseline correlations were observed between IL-17, Th17, and clinical scores (r = 0.642-0.970, p < 0.001), with progressive uncoupling of these relationships during treatment. No severe adverse events were reported.\nCONCLUSION: Secukinumab demonstrated rapid and sustained clinical benefits in AChR+ gMG, linked to suppression of the Th17/IL-17 pathway. These findings highlight IL-17 inhibition as a promising targeted strategy for MG. Limitations include small sample size and retrospective design, warranting validation in larger randomized trials.", "authors": ["Zhang Shuangmei", "Song Xiaodong", "Wang An Rong", "Zhang Zhaoxu"], "journal": "Frontiers in neurology", "entry_date": "2025/11/07 04:23", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41200446/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pain Rehabilitation, Cancer Hospital of the University of Chinese Academy of Sciences (Zhejiang Cancer Hospital), Hangzhou, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41200439", "title": "Disease burden of myasthenia gravis in relation to oral corticosteroid dose: an insurance claims database study in Japan.", "abstract": "INTRODUCTION: Oral corticosteroids (OCS) are used for maintenance treatment of myasthenia gravis (MG). Prolonged use of higher-dose OCS may provoke serious adverse events. Therefore, Japanese clinical guidelines recommend an OCS dose target of ≤5 mg/day. This retrospective study aimed to compare the burden of MG between patients achieving this target and non-achievers.\nMETHODS: Data were obtained from three Japanese healthcare databases (JMDC, NHI and LSEHS) between 2014 and 2021. Patients with MG starting immunotherapy were enrolled and data were collected over 2 years following start of immunotherapy. Exposure to OCS was determined from medication delivery records; achievers and non-achievers of the ≤5 mg/day target during follow-up were identified. Outcomes evaluated were confirmed incident diabetes, new osteoporotic fracture, and total and MG-related costs.\nRESULTS: Overall, 459 patients were analyzed. Of these, 94 patients (58.4%) in the JMDC population, 96 (64.0%) in the NHI population and 119 (80.4%) in the LSEHS population achieved the ≤5 mg/day target. Incident confirmed diabetes in the JMDC population and new osteoporotic fractures in the LSEHS population were less frequent in target achievers than in non-achievers (p = 0.01 and p < 0.05, respectively). In target achievers in the JMDC and LSEHS populations, total and MG-related costs were lower (both p ≤ 0.01) than in non-achievers.\nDISCUSSION: OCS dose target non-achievers carry a higher burden than achievers. Broader implementation of effective treatment strategies is required to reduce long-term use of higher-dose OCS and the associated burden.", "authors": ["Samukawa Makoto", "Konno Shingo", "Uzawa Akiyuki", "Taki Kentaro", "Todaka Hiroshi", "Mishiro Izumi", "Quelen Céline", "Łukowicz Zuzanna", "Majewska Renata", "Ohashi Yohei"], "journal": "Frontiers in neurology", "entry_date": "2025/11/07 04:23", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41200439/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Kindai University Faculty of Medicine, Osaka, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41200184", "title": "The efficacy, safety, and pharmacokinetics/pharmacodynamics of telitacicept following efgartigimod in generalized myasthenia gravis: protocol of a randomized controlled trial.", "abstract": "INTRODUCTION: Several biologic agents have emerged as novel therapeutic options for patients with generalized myasthenia gravis (gMG); however, no clinical studies have yet explored the efficacy and safety of sequential biologic therapy in gMG.\nMETHODS AND ANALYSIS: This multicenter, open-label, randomized controlled, exploratory clinical trial plans to enroll 60 patients with acetylcholine receptor antibody-positive gMG, randomized in a 1:1:1 ratio to receive one of the following treatment regimens: (1) E + 1w+T: efgartigimod 10 mg/kg weekly for 4 weeks, followed by telitacicept 240 mg weekly starting 1 week after the last efgartigimod dose, continued for 25 weeks; (2) E + 2w+T: efgartigimod as above, followed by telitacicept 240 mg weekly starting 2 weeks after the last efgartigimod dose, continued for 24 weeks; or (3) T only: telitacicept monotherapy for 30 weeks. The primary endpoint is the change in the Quantitative Myasthenia Gravis (QMG) score from baseline to week 30. Secondary endpoints include changes in the Myasthenia Gravis Activities of Daily Living (MG-ADL) score from baseline, proportion of patients achieving minimal manifestation status (MMS), changes in dosages of corticosteroid and other immunosuppressant, rates of MG relapse/acute exacerbation and MG crisis, and safety outcomes. The pharmacokinetics/pharmacodynamics (PK/PD) of telitacicept will also be assessed. Recruitment is currently ongoing, but no participants have been enrolled as of yet.\nETHICS AND DISSEMINATION: The study has been approved by the Ethics Committee in Clinical Research of the First Affiliated Hospital of Wenzhou Medical University. Results of the study will be disseminated to the relevant scientific, clinical and patient communities on trial closure. Trial registration number: The study was registered at ClinicalTrials.gov (NCT06827587).", "authors": ["Li Jia", "Zhang Yuan", "Deng Yan", "Li Wenyu", "Wang Yiqi", "Qi Feiteng", "Zhang Qiaoyi", "Wan Bingbing", "Li Xiang", "Weng Yiyun", "Fang Zheyu", "Zhang Yu", "Qu Xi", "Pan Shengli", "Yang Shiyin", "Zhang Xu"], "journal": "Frontiers in immunology", "entry_date": "2025/11/07 04:21", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41200184/", "pub_types": ["Journal Article", "Clinical Trial Protocol"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Wenzhou Medical University, Wenzhou, Zhejiang, China."], "china_related": true, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41197538", "title": "Association of baseline acetylcholine receptor antibody levels with efgartigimod treatment efficacy for patients with myasthenia gravis.", "abstract": "BACKGROUND: Efgartigimod is effective for many patients with acetylcholine receptor (AChR) antibody-positive generalized myasthenia gravis (gMG). To help identify patients most likely to benefit from efgartigimod, we examined the correlation between baseline AChR antibody levels and clinical response.\nMETHODS: This retrospective observational study included 10 AChR antibody-positive MG patients receiving efgartigimod at a single center. Clinical responses were assessed by MG Activities of Daily Living (MG-ADL) scores before treatment as well as 15 and 29 days after treatment initiation.\nRESULTS: Patients demonstrated clinical improvement by day 15 as indicated by improved total MG-ADL score (mean, 3.6; range, -1 to 9; p = 0.0055), and condition improved further by day 29 (mean, 5.2; range, 2-10; p = 0.0003). Serum AChR antibody levels at baseline were positively correlated with MG-ADL score improvement on day 29 (r = 0.6483, p = 0.0426).\nCONCLUSIONS: Generalized MG patients with high baseline AChR antibody levels may exhibit a superior response to efgartigimod.", "authors": ["Handa Hideo", "Uzawa Akiyuki", "Yasuda Manato", "Akamine Hiroyuki", "Onishi Yosuke", "Ogaya Etsuko", "Kurumada Kentaro", "Takasaka Kyosuke", "Kuwabara Satoshi"], "journal": "Journal of the neurological sciences", "entry_date": "2025/11/06 18:09", "pub_date": "2025-12-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41197538/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41194820", "title": "A Diagnostic Challenge in Progressive Limb Weakness: A Case of Myasthenia Gravis With Atypical Distal and Cranial Nerve Involvement.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder commonly characterised by fatigable muscle weakness, often presenting with ocular symptoms and proximal weakness, though atypical presentations can also occur, especially in patients with overlapping autoimmune conditions. Prompt diagnosis is essential to initiate effective treatment and prevent complications. We report a case of a 39-year-old male with type 1 diabetes mellitus (T1DM) who presented with a six-week history of progressive limb weakness, imbalance, and intermittent diplopia. Examination revealed bilateral distal upper limb weakness, a possible fourth left cranial nerve palsy, and generalised areflexia, without fatigable ptosis or bulbar involvement. MRI showed only minor cervical disc protrusions, and initial differential diagnoses included diabetic neuropathy, demyelinating disease, and mononeuritis multiplex. Neurophysiological testing confirmed a neuromuscular junction disorder, and acetylcholine receptor antibodies were significantly elevated, leading to a diagnosis of seropositive generalised MG. The patient was started on pyridostigmine and oral prednisolone, with clinical improvement. Further testing revealed autoimmune thyroiditis, and a CT of the thorax excluded thymoma. This report underscores the importance of recognising atypical presentations of MG, as distal limb weakness is not a usual manifestation and can mimic neuropathic disorders. Colinicians should consider MG as a differential diagnosis in patients with atypical neuropathy to ensure timely evaluation and management.", "authors": ["Hafeez Mohammad I", "Krishnamoorthy Kasturi", "Kakkar Nidhi", "Odedara Dhaval"], "journal": "Cureus", "entry_date": "2025/11/06 04:03", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41194820/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Medicine for Older People, Stockport NHS Foundation Trust, Stockport, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41194516", "title": "Rituximab in New-Onset Generalized Myasthenia Gravis: Long-Term Follow-Up of the RINOMAX Clinical Trial.", "abstract": "BACKGROUND: The placebo-controlled RINOMAX trial (NCT02950155) demonstrated superiority up to 12 months of rituximab over standard-of-care in new-onset generalized myasthenia gravis (MG), but benefit-risk over longer time frames remains unknown.\nMETHODS: RINOMAX included 47 participants with a Quantitative Myasthenia Gravis (QMG) score ≥ 6. Twenty-five patients were randomized to a single intravenous infusion of 500 mg rituximab, and 22 to placebo of which 16 received rituximab after the double-blinded phase (7 ± 2.9 months). Data were extracted from the Swedish MG registry to track hospitalizations, treatments including rescue, and disease activity scores.\nRESULTS: Compared to the placebo arm, lower mean time-weighted QMG scores at 12 months (mean difference [MD]: 2.9, 95% CI: 0.9, 4.9; p = 0.005) and 24 months (MD: 2.6, 95% CI: 0.3, 4.9; p = 0.027) were observed in the RTX arm. The incidence rate of rescue from 48 weeks up to 5 years was numerically higher in the placebo arm than RTX (0.16 vs. 0.09/person-year; p = 0.121). Compared to delayed RTX, early exposure displayed lower QMG, risk of hospitalization (HR 0.24, 95% CI 0.07, 0.83), and rescue (HR 0.46, 95% CI 0.14, 1.57), but also the six patients never receiving RTX showed lower hospitalization risk (HR 0.08, 95% CI 0.01, 0.96). Corticosteroid doses were low globally throughout. Overall, 12.5% and 18.8% and of patients with early and delayed RTX, respectively, suffered a severe infection.\nCONCLUSION: Disease activity and treatment burden, including hospitalization and rescue treatments, remained low, indicating a potential benefit of rituximab on the long-term disease trajectory. Infection risk with B cell depletion, however, remains a concern.", "authors": ["Wu Jing", "Eriksson-Dufva Ann", "Budzianowska Anna", "Feresiadou Amalia", "Hansson William", "Hietala Max Albert", "Håkansson Irene", "Johansson Rune", "Jons Daniel", "Kmezic Ivan", "Lindberg Christopher", "Lindh Jonas", "Lundin Fredrik", "Nygren Ingela", "Punga Anna Rostedt", "Press Rayomand", "Samuelsson Kristin", "Sundström Peter", "Wickberg Oskar", "Frisell Thomas", "Brauner Susanna", "Piehl Fredrik"], "journal": "European journal of neurology", "entry_date": "2025/11/06 02:13", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41194516/", "pub_types": ["Clinical Trial, Phase III", "Journal Article", "Multicenter Study", "Randomized Controlled Trial"], "affiliations": ["Institute of Environmental Medicine, Karolinska Institutet, Stockholm, Sweden."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41193658", "title": "Mitochondrial proteins contribute to the pathogenesis of myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder mediated by B-cells, characterized by muscle weakness and fatigue. Mitochondria, essential for energy production and muscle function, have been implicated in MG. Despite their importance, the exact relationship between mitochondrial proteins (MPs) and MG remains unclear. This study utilized two-sample Mendelian Randomization (TSMR) to investigate potential causal associations between MPs and MG. Data from the largest available genome-wide associated study (GWAS), comprising 1873 acetylcholine receptor (AchR) antibody-positive MG patients (1278 late-onset MG [LOMG] and 595 early-onset MG [EOMG]), were analyzed. A total of 66 MPs were selected as exposure variables, with MG and its subtypes as outcomes. Analyses employed inverse variance weighted (IVW), MR-PRESSO, MR-Egger, and weighted median methods, with heterogeneity assessed using Cochran's Q statistic. Significant causal associations were found between MPs and MG subtypes. For LOMG, GrpE protein homolog 1, oligoribonuclease, protein SCO1 homolog, and rRNA methyltransferase 3 were linked to increased risk. Cytochrome c oxidase subunit 7A1 was associated with higher EOMG risk, while [pyruvate dehydrogenase (acetyl-transferring)] kinase isozyme 1, dihydrolipoyl dehydrogenase, and NFU1 iron-sulfur cluster scaffold were linked to reduced EOMG risk. MPs such as dihydrolipoyl dehydrogenase and NAD-dependent protein deacylase sirtuin-5 showed protective effects against MG, while GrpE protein homolog 1, mitochondrial glutamate carrier 2, oligoribonuclease, and protein SCO1 homolog were associated with increased risk. This MR analysis suggests potential causal relationships between MPs and MG, highlighting the need for further research to validate these findings and explore the mechanisms underlying these associations.", "authors": ["Cao Fangzheng", "Zhang Houwen", "Xu Bin", "Wang Juan", "Wu Bin", "Zhou Yu", "Yu Jialin", "Li Chunrong"], "journal": "Scientific reports", "entry_date": "2025/11/05 23:29", "pub_date": "2025-11-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41193658/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xinhua Hospital of Zhejiang Province, The Second Affiliated Hospital of Zhejiang Chinese Medical University, Hangzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41190556", "title": "Robotic Extended Thymectomy in Late-Onset Myasthenia Gravis: A 21-Year Retrospective Cohort Study of 172 Patients.", "abstract": "BACKGROUND: The safety and feasibility of robotic-assisted (RATS) thymectomy for myasthenia gravis (MG) with onset age ≥ 50 years remain unverified, particularly in very late-onset MG (V-LOMG).\nMETHODS: Patients were classified into late-onset MG (LOMG, 50-64) and very late-onset MG (V-LOMG ≥ 65) based on age of onset. Composite neurological remission (CNR) included complete stable remission (CSR), pharmacologic remission (PR), and minimal manifestations-0 (MM-0), while favorable outcomes comprised CNR and MM1-3.\nRESULTS: Among 1041 patients, 172 with MG onset at ≥ 50 years who underwent RATS extended thymectomy were included in the final analysis. The LOMG group comprised 104 patients (45.2% male), while the V-LOMG group included 68 patients (60.3% male). V-LOMG patients had more preoperative MG crises, shorter onset-to-thymectomy intervals, heavier thymic specimens, and less hyperplasia. In ocular-onset MG, generalization was more frequent in LOMG than in V-LOMG. No significant differences were found in other baseline characteristics, perioperative parameters, postoperative complications, and adverse composite outcomes. At a 5.1-year mean follow-up, the V-LOMG group had slightly higher CSR (7.4% vs. 6.7%), CNR (16.2% vs. 11.5%), and favorable outcome rates (52.9% vs. 45.2%) than the LOMG group, with no statistical significance. Both groups, especially V-LOMG (16.0 mg vs. 2.1 mg, p < 0.001), showed a significant corticosteroid dose reduction at the last follow-up, confirming the steroid-sparing effect of thymectomy.\nCONCLUSIONS: RATS extended thymectomy appears to be a safe and feasible treatment for patients with MG of onset at age ≥ 50 years, including those with V-LOMG, demonstrating a significant steroid-sparing effect while maintaining favorable neurological outcomes.", "authors": ["Huang Luyu", "Li Feng", "Li Zhongmin", "Zhang Hongbin", "Elsner Aron", "Strauchmann Julia", "Andreas Marco Nicolas", "Dziodzio Tomasz", "Lask Aina", "Neudecker Jens", "Xie Daipeng", "Yao Lintong", "Wu Shaowei", "Zhou Haiyu", "Meisel Andreas", "Rueckert Jens-C"], "journal": "European journal of neurology", "entry_date": "2025/11/05 06:23", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41190556/", "pub_types": ["Journal Article"], "affiliations": ["Department of Surgery, Competence Center of Thoracic Surgery, Charité Universitätsmedizin Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41189824", "title": "Severe Seronegative Myasthenia Gravis Revealed by Rapidly Progressive Dysphagia.", "abstract": "Dysphagia as the initial symptom of a severe myasthenic crisis is an atypical but well-documented presentation in the literature. A woman in her 40s presented to the emergency department with rapidly progressive dysphagia, initially misdiagnosed as gastro-oesophageal reflux. Two weeks earlier, she had completed eradication therapy for Helicobacter pylori. Within 24 hours of admission, she developed bulbar symptoms, dyspnoea, proximal muscle weakness, diplopia, and ptosis. Electromyography confirmed a neuromuscular junction disorder consistent with a myasthenic syndrome. Despite initiation of pyridostigmine, her condition deteriorated, requiring orotracheal intubation and intensive care. She received plasmapheresis, intravenous immunoglobulins, corticosteroids, and mycophenolate mofetil, with significant clinical improvement. The final diagnosis was severe, acute, seronegative myasthenia gravis without any clearly evident etiologic factor. This case highlights the importance of considering myasthenic crisis in the differential diagnosis of atypical dysphagia and acute respiratory failure with neurological signs, particularly in the emergency setting.", "authors": ["Ramos Huamancondor Christopher", "Bronchain Maroussia", "Petit Jonathan"], "journal": "Cureus", "entry_date": "2025/11/05 04:16", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41189824/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Emergency Department, Cliniques Universitaires Saint-Luc (CUSL), Brussels, BEL."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41189178", "title": "Association between serum uric acid levels and myasthenia gravis: A meta-analysis.", "abstract": "BACKGROUND: Serum uric acid (UA) levels may be involved in the development of myasthenia gravis (MG) by inhibiting oxidative stress, but the relationship remains unclear. This meta-analysis aimed to assess the association between serum UA levels and MG patients.\nMETHODS: According to the established protocol, researchers searched 9 databases for studies on UA levels in MG patients, assessed using the Newcastle-Ottawa Scale. Heterogeneity was evaluated with the I2 statistic and chi-square test. Publication bias was analyzed using funnel plots and Egger test.\nRESULTS: This meta-analysis included 9 case-control studies from China, with 2112 participants (955 MG patients, 1157 healthy controls). All studies had Newcastle-Ottawa Scale quality scores of 7 or above. Results showed significantly lower serum UA levels in MG patients compared to controls (I2 = 58%, mean difference [MD]: -43.86, 95% confidence interval [CI]: [-54.98, -32.74], P < .00001). Age differences were identified as a source of heterogeneity, confirmed by subgroup analysis. Subgroup analyses showed that in age-comparable groups, MG and healthy controls had lower heterogeneity in UA levels (I2 = 18%, MD: -36.57, 95% CI: [-44.62, -28.50], P < .00001), and in age-disparate groups (I2 = 0%, MD: -73.78, 95% CI: [-94.13, -53.44], P < .00001). Gender analyses showed UA levels in men (I2 = 69%, MD: -60.29, 95% CI: [-81.75, -38.83], P < .00001) and women (I2 = 1%, MD: -29.80, 95% CI: [-38.03, -21.57], P < .00001).\nCONCLUSION: Lower serum levels of UA are associated with an increased risk of MG, although further large-scale, well-controlled studies are needed to confirm the potential clinical relevance.", "authors": ["Liu Lang", "Yang Tong", "Sun Xingli", "Zhang Xi", "Ou Jiangqin"], "journal": "Medicine", "entry_date": "2025/11/05 01:00", "pub_date": "2025-10-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41189178/", "pub_types": ["Journal Article", "Meta-Analysis"], "affiliations": ["Guizhou University of Traditional Chinese Medicine, Guiyang, P.R. China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "41188651", "title": "Characterization of the neuromuscular manifestations in patients with IgG4-related disease: a systematic review.", "abstract": "Immunoglobulin G4-related disease (IgG4-RD) neurological involvement typically presents as pachymeningitis. However, there have been reports of neuromuscular manifestations. To review the involvement of the peripheral nerves, neuromuscular junction, and muscles in IgG4-RD, we conducted a systematic review of case reports and case series of patients with IgG4-related disease (IgG4-RD) presenting with neuromuscular manifestations, using the PubMed/MEDLINE, Embase, and Scopus databases. Articles were analyzed for demographic characteristics, neurological presentations, systemic involvement, and investigative findings (laboratory, electrophysiological, and pathological). A total of 38 articles, encompassing 42 cases of neuromuscular manifestations in patients with IgG4-RD, were included. Peripheral nerve involvement was frequently reported (25/42, 60%). The most common clinical presentations were mononeuritis multiplex (48%) and polyneuropathy (20%). Electrodiagnostic studies revealed an axonal pattern in 88% of cases, while nerve biopsies were compatible with vessel and nerve infiltration by IgG4-positive cells in 46% (6/13) of cases. Involvement of the neuromuscular junction was infrequently reported (n = 4), presenting as Lambert-Eaton syndrome (25%) or myasthenia gravis (75%), with all cases being negative for anti-acetylcholine receptor antibodies. Muscle involvement (n = 13) manifested as focal myositis in 53% and a limb-girdle muscle weakness pattern in 47%. Creatine kinase levels were elevated in 53%, and muscle biopsy demonstrated IgG4-positive cell infiltration in all focal myositis cases. Our review suggests that typical neuromuscular manifestations in patients with IgG4-RD include mononeuritis multiplex, polyneuropathy, and focal myopathy. However, comorbid conditions should also be considered as potential contributors to neuromuscular manifestations.", "authors": ["Rosenstein Renan Fabri", "Baima José Pedro", "Giardini Henrique Ayres Mayrink", "Mendonça Leonardo Oliveira", "Silva Guilherme Diogo"], "journal": "Immunologic research", "entry_date": "2025/11/04 23:41", "pub_date": "2025-11-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41188651/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Division of Neurology, Faculdade de Medicina, Hospital das Clínicas HCFMUSP, Universidade de São Paulo, São Paulo, SP, Brazil."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.1, "journal_quartile": "4区"}, {"pmid": "41188194", "title": "Myocarditis and Myasthenia Gravis Induced by Camrelizumab in a Patient With Metastatic B2 Thymoma: A Case Report.", "abstract": "Thymoma is a rare malignant tumor originating from the thymus epithelium. In recent years, immune checkpoint inhibitors have become an indispensable treatment for cancer. However, the efficacy and adverse events of immunotherapy for thymoma have not been widely evaluated. A 53-year-old Chinese man who was diagnosed with metastatic B2 thymomas since March 2023. He received chemotherapy plus anlotinib for four cycles since May 5, 2023, and underwent radiotherapy from May 23, 2023 to June 30, 2023. However, the treatment was not satisfactory. Thus, we detected PD-L1 expression in tumors; immunohistochemical examination on the tumor revealed a high PD-L1 expression in 60% of tumor cells. He presented symptoms of palpitation, gasping, fatigue, diplopia, and eyelid ptosis. Additionally, he was found to have significantly elevated levels of serum cardiac troponin, creatine kinase, creatine kinase isoenzymes, N-terminal pro brain natriuretic peptide, and anti-acetylcholine receptor antibody. He was eventually diagnosed with immune-related myocarditis and myasthenia gravis. Finally, the patient was discharged after treatment with glucocorticoids, immunoglobulin, and pyridostigmine. Although immune checkpoint inhibitors have achieved similar anti-tumor effects in thymomas as in other solid tumors, they may be closely associated with serious immune-related adverse events, so special caution is required when using immune checkpoint inhibitors in thymoma patients.", "authors": ["Zhao Lingling", "Yang Bo", "Li Yuzhi", "Wang Yu", "Zhu Ting"], "journal": "Thoracic cancer", "entry_date": "2025/11/04 22:22", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41188194/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Wannan Medical College, Wuhu, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "41182210", "title": "Boom or Bust: Clinical Trials in Pemphigus and Other B-Cell-Mediated Autoimmune Diseases.", "abstract": "Pemphigus vulgaris (PV) is a B-cell-mediated autoimmune blistering disease characterized by autoantibodies targeting skin cell adhesion proteins. Despite the well-defined pathophysiology and unmet need for safe and effective therapies for pemphigus, multiple therapeutics have failed to advance through clinical development. Prednisone and rituximab are clinically approved for PV, but the neonatal Fc receptor inhibitor efgartigimod and Bruton's tyrosine kinase inhibitor rilzabrutinib failed to receive clinical approval in pemphigus, despite success in other autoantibody-mediated diseases. Conversely, the success of rituximab for PV has not been reproduced for several other B cell-mediated autoimmune diseases. We review learnings from the successes and failures of rituximab, efgartigimod, and rilzabrutinib across B-cell-mediated autoimmune diseases and compare trial designs and endpoints to identify key issues affecting clinical outcomes.", "authors": ["Rujitharanawong Chuda", "Werth Victoria P", "Payne Aimee S"], "journal": "The Journal of investigative dermatology", "entry_date": "2025/11/03 10:28", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41182210/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Dermatology, Columbia University, New York, New York, USA; Department of Dermatology, Faculty of Medicine Siriraj Hospital, Mahidol University, Bangkok, Thailand and."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.7, "journal_quartile": "2区"}, {"pmid": "41180124", "title": "Open-label study of efgartigimod in seronegative myasthenia gravis.", "abstract": "BACKGROUND: The ADAPT trial demonstrated the benefit of efgartigimod, a neonatal Fc receptor (FcRn) inhibitor, in acetylcholine receptor antibody (AChRAb) positive patients with generalized myasthenia gravis (MG). Information regarding the benefits in those lacking pathogenic antibodies is sparse.\nOBJECTIVES: We aimed to investigate the safety and efficacy of efgartigimod in patients with double-seronegative (SN) generalized MG.\nDESIGN: An open-label 6-month prospective study, conducted at our center.\nMETHODS: Patients aged at least 18 years with clinical and electrodiagnostic features of MG and negative results for AChRAb and muscle-specific tyrosine kinase antibodies were included. Efgartigimod was administered weekly for 4 weeks and then biweekly for 5 months followed by an observation period. The primary endpoint was the change in MG impairment index (MGII) at 6 months compared to baseline. Secondary endpoints include the change in MG activities of daily living (MG-ADL), other MG scores, overall responders, and early responders. The safety analysis included all patients who received at least one dose of efgartigimod.\nRESULTS: We enrolled 30 patients with SN MG who were resistant to other treatments and had unacceptable MGII scores. The MGII decreased by 11.92 points (p < 0.01) with efgartigimod treatment. The MG-ADL also improved. Seventy-two percent of patients were responders with 31% being early responders. Adverse events were reported in 83.3% of patients, and in 90.6%, they were mild. Headache was the most common, reported in 26.7%, followed by flu/common cold in 20%, and urinary tract infection in 13.3%.\nCONCLUSION: Efgartigimod was well tolerated and efficacious in patients with SN MG. Future randomized, placebo-controlled studies are needed.\nTRIAL REGISTRATION: This trial is registered at ClinicalTrials.gov (NCT06587867), accessed via https://clinicaltrials.gov/study/NCT06587867?locStr=Toronto,%20ON,%20Canada&country=Canada&state=Ontario&city=Toronto&cond=Myasthenia%20Gravis&intr=efgartigimod&rank=1.\nThe safety and efficacy of the novel treatment efgartigimod in myasthenia gravis with negative antibodies We enrolled 30 patients with myasthenia gravis with negative antibodies. All patients received the new treatment Efgartigimod and we compared the severity of their myasthenia symptoms with the treatment, compared to the baseline (before giving it). The severity of the myasthenia was significantly reduced (observed in multiple clinical scores for myasthenia gravis). Adverse events were reported in 83.3% of patients, and in 90.6% they were mild. Headache was the most common, reported in 26.7%, followed by flu/common cold in 20%, and urinary symptoms in 13.3%. To conclude, in this study, we showed, for the first time that the novel treatment of Efgartigimod is well tolerated and efficacious in patients with Myasthenia gravis with no antibodies. Future prospective and placebo-controlled studies are needed.", "authors": ["Khateb Mohamed", "Sivadasan Ajith", "Barnett-Tapia Carolina", "Daniyal Lubna", "Fernando Lahiru", "Chen Shiyi", "Lovblom Leif Erik", "Katzberg Hans", "Bril Vera"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/11/03 07:06", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41180124/", "pub_types": ["Journal Article"], "affiliations": ["Ellen and Martin Prosserman Centre for Neuromuscular Diseases, University Health Network, University of Toronto, Toronto, ON, Canada."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "41175252", "title": "Facile and label-free electrochemical detection of myasthenia gravis-associated AChR antibodies using a laser-induced graphene immunoplatform.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder characterized by progressive muscle weakness that can severely impact patient quality of life and may lead to life-threatening complications if not diagnosed in a timely manner. Traditional serological diagnostic methods are often complex, time-consuming, and less accessible. To address these limitations, we developed a novel label-free electrochemical immunosensor. It uses laser-induced graphene (LIG) electrodes co-functionalized with gold nanoparticles (AuNPs) and copper ferrite nanoparticles (CuFe₂O₄) for the rapid, sensitive, and accurate detection of MG-related acetylcholine receptors (AChR) antibodies. Comprehensive characterization by Fourier-transform infrared spectroscopy (FTIR), X-ray photoelectron spectroscopy (XPS), scanning electron microscopy (SEM), and energy-dispersive X-ray spectroscopy (EDS) confirmed the successful fabrication and structural integrity of the sensor. Differential pulse voltammetry (DPV) measurements revealed a broad linear detection range (10 pg/mL to 100 µg/mL) and an ultra-low detection limit of 10 pg/mL. The sensor demonstrated excellent selectivity, reproducibility, repeatability, and stability. Recovery studies with human serum yielded high recoveries (90%-110%) with low relative standard deviation (RSD) (0.277%-0.482%). Furthermore, preliminary clinical testing showed the immunosensor could reliably distinguish MG patient samples from healthy controls, supporting its practical diagnostic utility. Overall, these results highlight the sensor's strong potential as a rapid, reliable, and cost-effective tool for MG diagnosis in clinical and point-of-care applications.", "authors": ["Lin Peng", "Lal Nand", "Yao Haixu", "Sui Hongjing", "Sun Yilei", "Wang Yanling", "Wang Guangtian", "Ge Zhongqiao", "Gao Yuan", "Ibupoto Zafar Hussain", "Zhou Qin", "Cui Feiyun"], "journal": "Mikrochimica acta", "entry_date": "2025/11/01 12:14", "pub_date": "2025-11-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41175252/", "pub_types": ["Journal Article"], "affiliations": ["School of Basic Medical Sciences, Harbin Medical University, Harbin, 150081, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41172986", "title": "Structural basis of VAChT inhibition by spiroindolines and alkylsulfones.", "abstract": "Cholinergic signaling relies on the vesicular acetylcholine transporter (VAChT) to package acetylcholine (ACh) into synaptic vesicles. VAChT dysfunction is implicated in neurological and neuromuscular disorders, including Alzheimer's disease and myasthenia gravis, yet current inhibitors such as vesamicol suffer from off-target effects. Here, we present cryo-EM structures of human VAChT bound to two inhibitors, spiroindoline and alkylsulfone, revealing their divergent binding modes that converge in occupying the central substrate pocket. Mutagenesis studies identify conserved residues critical for inhibitor binding. These findings elucidate the molecular mechanisms by which VAChT binds structurally distinct inhibitors, providing a blueprint for designing optimized therapeutics. Furthermore, species-specific structural variations identified here suggest opportunities to develop selective insecticides through ortholog-targeted inhibition. Taken together, this work bridges mechanistic insights with therapeutic and agricultural applications, advancing precision tools for modulating the cholinergic system.", "authors": ["Zhang Yang", "Zhang Zhe"], "journal": "Structure (London, England : 1993)", "entry_date": "2025/10/31 19:41", "pub_date": "2026-01-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41172986/", "pub_types": ["Journal Article"], "affiliations": ["State Key Laboratory of Membrane Biology, School of Life Sciences, Peking University, Beijing 100871, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41170262", "title": "Myasthenic Crisis in a Patient Initially Treated for Transient Ischaemic Attack and Infection: A Case Report.", "abstract": "Myasthenia gravis (MG) is the most common disorder of the neuromuscular junction and may present with fluctuating ocular, bulbar, or limb weakness. Myasthenic crisis represents a life-threatening complication characterised by respiratory failure requiring ventilatory support. We report the case of a 46-year-old South Asian man who initially presented with fluctuating bilateral ptosis, intermittent diplopia, and fatigue, and was managed as a transient ischaemic attack and respiratory tract infection. He subsequently deteriorated with hypoxia, extensive secretion burden, and pneumonia, necessitating intubation and intensive care admission. Despite broad-spectrum antibiotics and supportive care, ventilatory requirements persisted. Following neurological review and a more detailed history, together with multidisciplinary discussion, a myasthenic crisis was suspected, and treatment with intravenous immunoglobulin and corticosteroids was initiated. Acetylcholine receptor antibodies later returned positive, and electromyography demonstrated a decremental response, confirming the diagnosis. The patient improved gradually, was extubated on Day 14, and discharged with immunosuppressive therapy and neurology follow-up. This case underscores the importance of thorough neurological examination and careful history-taking to support early diagnosis, alongside timely multidisciplinary team input to guide management.", "authors": ["Adhikarla Aditya K"], "journal": "Cureus", "entry_date": "2025/10/31 04:55", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41170262/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Manchester Royal Infirmary, Manchester, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41169950", "title": "Adverse events beyond the RUBY trial: reporting immunotherapy-associated myocarditis, myositis, and myasthenia gravis in a real-world endometrial cancer case.", "abstract": "OBJECTIVES: To report a rare case of immune checkpoint inhibitor (ICI)-associated myocarditis, myositis, and myasthenia gravis (MMM syndrome) in a patient with advanced endometrial cancer treated with dostarlimab, highlighting the diagnostic and therapeutic challenges, in addition to the importance of biomarker-informed treatment selection.\nMETHODS: We report the case of a 75-year-old woman with unresectable stage IIIC2 endometrial adenocarcinoma and mismatch repair (MMR) deficiency treated with carboplatin and paclitaxel, followed by dostarlimab. After initiation of dostarlimab, the patient presented with neuromuscular and cardiac symptoms, leading to the diagnosis of myocarditis, myositis, myasthenia gravis (MMM) syndrome requiring hospitalization. A multidisciplinary care including neurologic, cardiac, and critical care management was required.\nRESULTS: The patient developed MMM syndrome 81 days after starting dostarlimab, presenting with bilateral ptosis, dysphagia, diplopia and respiratory compromise. Evaluation revealed elevated troponins, elevated creatine kinase, and a positive acetylcholine receptor antibody. Cardiac MRI confirmed myocarditis. Management included high-dose steroids, mycophenolate, IVIG, abatacept, and tofacitinib, with initial stabilization.\nCONCLUSIONS: MMM syndrome is a rare but life-threatening complication of ICI therapy. Early recognition and multidisciplinary management are crucial. This case underscores the importance of weighing the risks and benefits of initiating immunotherapy and utilizing biomarker-driven clinical decisions.", "authors": ["Abozenah Yasmin", "McNamara Blair", "Greenman Michelle", "Daigle Emily", "Mikhaiel John Paul", "DiCapua Daniel", "Kwan Jennifer", "Azodi Masoud", "Altwerger Gary"], "journal": "Gynecologic oncology reports", "entry_date": "2025/10/31 04:52", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41169950/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Yale University School of Medicine, Department of Obstetrics, Gynecology and Reproductive Science, Division of Gynecologic Oncology, New Haven, CT 06520, United States."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "41169734", "title": "Good's Syndrome Presenting With Weaning Failure From Ventilation and Myasthenia Gravis in a Post-Thymectomy Patient.", "abstract": "Good's syndrome is a rare adult-onset immunodeficiency associated with thymoma, hypogammaglobulinemia, and cellular immune dysfunction. We report a man in his 50s with a prior thymectomy who presented with recurrent pneumonia, chronic diarrhoea, and failure to wean from non-invasive ventilation. Flow cytometry revealed absent B cells and an inverted CD4/CD8 ratio, confirming Good's syndrome. He also developed myasthenia gravis, which contributed to ventilatory failure but improved with pyridostigmine. The patient responded well to monthly intravenous immunoglobulin therapy and remained clinically stable at follow-up. This case emphasises the importance of suspecting Good's syndrome in patients with thymoma and unexplained infections, as early recognition and timely immunoglobulin replacement are essential for improving outcomes.", "authors": ["Mehta Asmita Anilkumar", "Ashok Aditya", "Valathara Pradeep Lakshmi Priya", "Sivadas Suchitra", "Mothi George Justin"], "journal": "Respirology case reports", "entry_date": "2025/10/31 04:49", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41169734/", "pub_types": ["Journal Article"], "affiliations": ["Department of Respiratory Medicine Amrita Institute of Medical Sciences, Amrita Vishwa Vidyapeethem Kochi India."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41169356", "title": "Impacts of tacrolimus and glucocorticoids on peripheral blood T and B lymphocyte subsets in myasthenia gravis.", "abstract": "BACKGROUND: This study aimed to investigate the impact of tacrolimus on peripheral T and B lymphocyte subsets in myasthenia gravis (MG) patients compared to glucocorticoid treatment.\nMETHODS: This study retrospectively included MG patients at the First Affiliated Hospital of Fujian Medical University between January 2021 and December 2024. Patients were grouped based on immunotherapy received: tacrolimus (TAC) or glucocorticoids (GC). Peripheral blood samples were assessed for T lymphocyte subsets (CD3+, CD4+, CD8+) and B lymphocyte subsets (CD19+), alongside clinical parameters.\nRESULTS: A total of 46 MG patients were included, with 23 patients in each treatment group. Baseline characteristics, including sex, age at onset, antibody profile, and thymic pathology, were comparable between the two groups (all P > 0.05), except for a significantly higher proportion of generalized MG in the TAC group (P = 0.017). Following treatment, the TAC group demonstrated a significantly lower absolute count of CD3+CD4+ T cells compared to the GC group (663.4 ± 345.5 × 106/L vs. 952.5 ± 513.9 × 106/L, P = 0.030). Additionally, the percentage of peripheral B cells in the tacrolimus group decreased significantly after treatment (from 11.8 ± 4.7% to 9.4 ± 4.4%, P = 0.006). In contrast, patients treated with glucocorticoids showed significant post-treatment increases in the absolute counts of CD3+, CD3+CD4+, and CD3+CD8+ T cells (all P = 0.001).\nCONCLUSION: Compared with patients receiving glucocorticoid therapy, those treated with tacrolimus exhibited significantly lower levels of peripheral CD3+CD4+ T cells after treatment. These findings provide insight into the differential immunomodulatory effects of these therapies in MG.", "authors": ["Wu Xuan", "Chen Wei", "Song Huanhuan", "Xu Guorong"], "journal": "Frontiers in immunology", "entry_date": "2025/10/31 04:44", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41169356/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Fujian Medical University, Fuzhou, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41169211", "title": "Interferon regulatory factor 1 enhances T cell differentiation in patients with myasthenia gravis.", "abstract": "", "authors": ["Luo Yuebei", "Ren Yijun", "Wen Zeyi", "Luo Zhaohui", "Yang Huan", "Xu Liqun"], "journal": "Neural regeneration research", "entry_date": "2025/10/31 04:03", "pub_date": "2026-07-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41169211/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, Hunan Province, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 6.7, "journal_quartile": "2区"}, {"pmid": "41164399", "title": "The study of social participation and its influences on young and middle-aged patients with myasthenia gravis.", "abstract": "OBJECTIVE: To describe the social participation of young and middle-aged patients with myasthenia gravis and explore the main influences to provide a basis for improving social participation behavior.\nMETHODS: From January 2020 to December 2022, 145 patients with myasthenia gravis aged between 18 and 60 years who were recruited from a Grade A tertiary hospital in Shenzhen were selected via a convenience sampling method. A total of 145 patients with nonmyasthenia gravis aged between 18 and 60 years who received physical examination at the same hospital at the same time as the control group were included. A general information questionnaire, Assessment of Life Habits, the Beck Depression Inventory, the Family Assessment Device, and the Perceived Social Support Scale were used to evaluate the survey. The results The total social participation score of young and middle-aged patients with myasthenia gravis was 88.90 ± 33.05. Among them, three dimensions with higher scores were independent participation in social life and social relations, activity, and self-care. Compared with those of the same age group, the social participation scores of young and middle-aged patients with myasthenia gravis were higher than those of the control group, who were in activities, independently participated and helped and supported others, indicating that their level of social participation was lower than that of the control group. Multiple linear regression revealed that the level of social participation in female patients who were unemployed, lived in rural areas, needed daily care, had a long disease course, had weak daily activity ability, had depression, and had poor family functioning was relatively low (p < 0.001, R2 = 0.527).\nCONCLUSION: The level of social participation of young and middle-aged myasthenia gravis patients was relatively low and far lower than that of the control group, especially in terms of independent participation in social life and social interactions, activities and self-care, which needs to be improved.", "authors": ["Chen Juan", "Wang Lengmeng", "Fang Yan", "Pan Yanhong", "Lin Lin", "Zhang Lifeng"], "journal": "Frontiers in neurology", "entry_date": "2025/10/30 05:06", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41164399/", "pub_types": ["Journal Article"], "affiliations": ["The First Affiliated Hospital of Fujian Medical University, Fuzhou, Fujian, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41164186", "title": "Thymus research in relation to myasthenia gravis: a new perspective on cell subpopulations and future directions.", "abstract": "The thymus generates T cells from immature thymocytes and prevents autoimmune diseases through negative selection and the generation of FOXP3+ regulatory T cells (Tregs). The thymic architecture is typically divided into two distinct microenvironments, the cortex and the medulla. These microenvironments are characterized by the presence of cortical thymic epithelial cells (cTECs) and medullary thymic epithelial cells (mTECs), respectively. Recent single-cell and spatial transcriptomic analyses have revealed the expanding diversity of TEC subpopulations in mice and humans. Myasthenia gravis (MG) is an autoimmune disorder characterized by fatigue resulting from muscle weakness, which is caused by antibodies toward structures within the neuromuscular junction. The most common target of pathogenic autoantibodies in MG is the acetylcholine receptor (AChR). MG patients are prone to thymic abnormalities, including thymic follicular hyperplasia and thymoma. Previous studies have suggested that mTECs expressing major histocompatibility complex (MHC)/AChR-peptide complexes are involved in the intrathymic pathogenesis of this MG type. However, the exact mechanisms are unknown. This review provides an update on the diversity of TEC subpopulations and other cellular alterations in the MG thymus. Additionally, we present hypotheses on the pathogenetic pathways leading to MG and suggest potential future directions in thymus research.", "authors": ["Matsui Naoko", "Ohigashi Izumi", "Marx Alexander"], "journal": "Frontiers in immunology", "entry_date": "2025/10/30 05:02", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41164186/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Tokushima University Graduate School of Biomedical Sciences, Tokushima, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41163855", "title": "Maintaining Surgical Principles While Transitioning From Multiport to Single-port Robotic Thymectomy.", "abstract": "Thymectomy is a treatment option for new-onset or treatment-resistant myasthenia gravis in patients with muscle-type acetylcholine receptor autoantibodies, and it is the standard treatment of early-stage thymomas. However, patients with severe forms, particularly those with titin and ryanodine receptor antibodies, may require long-term immunosuppressive therapy instead. The optimal approach to thymectomy remains debated, with minimally invasive techniques like video-assisted and robot-assisted thoracoscopic surgery offering better perioperative outcomes. Single-port robot-assisted thymectomy has emerged as a safe alternative, allowing a single subxiphoid incision and affording the inherent benefits of the robotic platform. This study describes our approach to single-port robot-assisted thymectomy using a subxiphoid incision.", "authors": ["Perez Claire", "Weiser Lucas", "Bolster Drew", "Razavi Allen", "Fuller Charles", "Soukiasian Sevannah", "Knabe Kellie", "Rocco Raffaele", "Soukiasian Harmik J", "Brownlee Andrew R"], "journal": "Annals of thoracic surgery short reports", "entry_date": "2025/10/30 04:56", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41163855/", "pub_types": ["Journal Article"], "affiliations": ["Division of Thoracic Surgery, Department of Surgery, Cedars-Sinai Medical Center, Los Angeles, California."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41163359", "title": "Utility of the Predictive Summary Index for Comparison of Diagnostic Protocols in Myasthenia Gravis With Repetitive Nerve Stimulation and Concentric Needle Jitter.", "abstract": "INTRODUCTION: As sensitivity of a test can be increased at the expense of specificity, a quality measure taking into account both parameters is desirable. The \"predictive summary index\" (PSI) is calculated from the prevalence of the disease, sensitivity and specificity. We characterize diagnostic yield of repetitive nerve stimulation (RNS) and stimulated concentric needle jitter (CNJ) in the diagnosis of myasthenia gravis (MG) with PSI. From PSI, the number of tests that is required for the prediction of one correct diagnosis (\"number needed to predict\" [NNP] in analogy to the number needed to treat) can be calculated as 1/PSI.\nMETHODS: Among patients consecutively referred to the electrophysiology laboratory for a workup of a disorder of the neuromuscular junction (NMJ), we identified 35 patients with MG (clinical diagnosis supported by antibody findings or treatment response) and 85 patients with diagnosis unrelated to the NMJ in whom both RNS and stimulated CNJ had been performed.\nRESULTS: The PSI was 0.82 and 0.53 for CNJ and RNS, respectively. The NNPs were 1.22 for CNJ and 1.89 for RNS. This means that 1.49 patients have to be tested with CNJ instead of RNS to arrive at one correct diagnosis. In data from the literature, PSI illustrates that 7% as a cut-off in RNS can be helpful and that amplitude decrement is more reliable than area decrement.\nCONCLUSION: CNJ was more reliable in the diagnosis of MG than RNS. PSI provides a rational quantitative framework to discuss both the validity of different techniques and their cost in terms of time spent to arrive at a correct diagnosis.", "authors": ["Trillenberg Peter", "Ohlen Daphne Schepers-von"], "journal": "Brain and behavior", "entry_date": "2025/10/30 02:23", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41163359/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Neurology, University Hospital of Schleswig-Holstein, Campus Lübeck, Lübeck, Germany."], "china_related": false, "study_types": ["Historical Control"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "41163004", "title": "Diabetes exacerbates myasthenia gravis by enhancing pathological thymic output via the GPR183-7α,25-OHC axis.", "abstract": "BACKGROUND: Diabetes mellitus (DM) could exacerbate experimental autoimmune myasthenia gravis (EAMG) by affecting both the innate and adaptive immune systems, although the specific mechanism remains unclear. GPR183, a G protein-coupled receptor predominantly expressed on immune cells, contributes to autoimmune disease development by directing immune cell migration to secondary lymphoid organs. However, the correlation between GPR183 and MG has not been reported.\nMETHODS: Researchers established a combined DM and EAMG model. Thymic immune cell and cytokine changes were assessed by flow cytometry. Transcriptomic profiles of sorted CD4+CD8− and CD4−CD8+ thymic T cells were analyzed via RNA sequencing. Serum steroid hormones were quantified by LC-MS/MS. The GPR183-7α,25-OHC pathway was evaluated using PCR, immunohistochemistry, and western blotting. In vivo blockade of GPR183 with inhibitor NIBR189 assessed its immune effects in EAMG rats with/without DM.\nRESULTS: Our study indicated that EAMG rats with DM exhibited more severe weight loss, thymus atrophy, and immune microenvironment alterations. Specifically, DM increased the percentages of mature and exported CD62L+ T cells in the thymus and peripheral blood of EAMG rats. RNA sequencing revealed that diabetes promotes GPR183 expression on thymic T cells, primarily in the CD62L⁺ T cell subset in EAMG rats. DM activates the GPR183 ligand, elevates serum 7α,25-hydroxycholesterol levels, and enhances hepatic cholesterol metabolism. GPR183 inhibition induces thymic T cell retention by selectively blocking CD62L⁺ T cell migration to the periphery. Moreover, GPR183 inhibitors weaken the adaptive immune function in DM + EAMG rats by expanding Treg cells, inhibiting Tfh/ASC differentiation, and reducing CD62L⁺ B cells.\nCONCLUSION: Diabetes significantly upregulates thymic GPR183 (especially on CD62L⁺ T cells) and promotes synthesis of its ligand 7α,25-OHC via hepatic cholesterol reprogramming, accelerating thymic T cells egress. This provides a novel therapeutic approach and a new perspective on how metabolic disorders reshape immune cell dynamics.\nSUPPLEMENTARY INFORMATION: The online version contains supplementary material available at 10.1186/s12974-025-03571-8.", "authors": ["Dong Jing", "Shi Xin", "Gu Xu-Dong", "Yang Ying", "He Yi-Lin", "Zhou Yang", "Li Heng", "Du Tong", "Si Wei-Yue", "Wei Shu-Li", "Liu Chang", "Yang Bing", "Li Yan-Bin", "Duan Rui-Sheng", "Yang Chun-Lin", "Zhang Peng"], "journal": "Journal of neuroinflammation", "entry_date": "2025/10/30 00:51", "pub_date": "2025-10-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41163004/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Shandong First Medical University & Shandong Provincial Qianfoshan Hospital, Jinan, 250014, People's Republic of China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 10.1, "journal_quartile": "1区"}, {"pmid": "41161959", "title": "Miscellaneous neurologic conditions with a few or no available data.", "abstract": "In this chapter, we will review the available literature on the nature of the placebo effect in conditions that are not well studied in terms of their response to the placebo intervention such as fatigue in general and in the context of myasthenia gravis and chronic fatigue syndrome, insomnia, restless leg syndrome, and central conditions such as multiple sclerosis. The clinical trials are either small or lack a natural history arm or a real placebo arm, therefore no definitive conclusions can be drawn regarding the magnitude and possible mechanisms of the placebo effect in these conditions. In addition, we will review some studies in conditions other than neurology, such as cardiovascular, respiratory, gastrointestinal, and genitourinary diseases that can be of some interest to neurologists. Overall, we know very little, if any, about the psychobiological underpinnings in these medical conditions, and this lack of knowledge must be the stimulus for the pursuit of new future research.", "authors": ["Benedetti Fabrizio", "Shaibani Aziz"], "journal": "Handbook of clinical neurology", "entry_date": "2025/10/29 21:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41161959/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neuroscience, University of Turin Medical School, Turin, Italy; Innovative Clinical Trials, Training and Healthcare Initiative, Zermatt, Switzerland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41161212", "title": "Reconsidering the electrophysiological signature of myasthenia gravis.", "abstract": "", "authors": ["Péréon Yann"], "journal": "Neurophysiologie clinique = Clinical neurophysiology", "entry_date": "2025/10/29 19:09", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41161212/", "pub_types": ["Editorial"], "affiliations": ["CHU Nantes, Centre de Référence Maladies Neuromusculaires Rares AOC, Filnemus, Euro-NMD, Hôtel-Dieu, Nantes, France. Electronic address: yann.pereon@univ-nantes.fr."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41160183", "title": "Association between antibody status and exacerbation in patients with myasthenia gravis who achieved minimal manifestation or better status.", "abstract": "OBJECTIVE: This study aimed to investigate the rate of exacerbation and risk factors associated with exacerbation in patients with myasthenia gravis (MG) who had achieved minimal manifestation or better status (MMS).\nMETHODS: This was a single-center retrospective cohort study. This study included patients with MG aged > 15 years who had attained MMS between July 2015 and June 2020. The outcome was defined as exacerbation occurring after the patient had achieved MMS. The enrolled patients were followed up until the outcome occurred or up to 60 months. To account for potential confounding variables, a stratified multivariate Cox proportional hazards model and propensity-score analyses were used.\nRESULTS: A total of 238 patients were enrolled in the study, including 199 (83.6%) antibody-positive and 39 (16.4%) double-seronegative patients. Overall, 134 (56.3%) patients experienced exacerbation during the follow-up period, with a median time to the outcome of 33 months. Double seronegativity was associated with a lower risk of exacerbation in the stratified Cox model (hazard ratio [HR] 0.412, 95% confidence interval [CI] 0.225-0.754) and in propensity score analyses (HR 0.501, 95% CI 0.274-0.917 in the adjusted analysis and HR 0.540, 95% CI 0.297-0.982 in the overlap-weighted analysis). Similar results were observed in the sensitivity analysis. Subgroup analyses implied that the presence of thymoma and the performance of thymectomy were identified as negative prognostic factors in seronegative patients.\nCONCLUSION: More than half of the patients with MG experienced exacerbation after achieving MMS in this Chinese population. Double seronegativity was an independent protective factor against exacerbations.", "authors": ["Li Yi", "Zhou Qian", "Dong Xiaohua", "Duan Weiwei", "Jiang Fei", "Cai Haobin", "Yang Huan"], "journal": "Journal of neurology", "entry_date": "2025/10/29 12:15", "pub_date": "2025-10-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41160183/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tangdu Hospital, Fourth Military Medical University, 569 Xinsi road, Xi'an, 710000, Shaanxi, China."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41159035", "title": "Case Report: Efgartigimod demonstrates significant clinical efficacy in double seropositive myasthenia gravis: a case report of a rare variant and analysis of pathomechanisms.", "abstract": "Double Seropositive Myasthenia Gravis (DSP-MG), a rare variant of Myasthenia Gravis (MG), is defined by the simultaneous presence of both anti-acetylcholine receptor (AChR) antibodies and anti-muscle-specific tyrosine kinase (MuSK) antibodies in the serum of affected individuals. Currently, no standardized therapeutic protocol exists for DSP-MG due to its scarcity and clinical heterogeneity. Herein, we report a case of a 68-year-old female patient with DSP-MG who showed significant clinical improvement during an acute exacerbation after treatment with the FcRn antagonist efgartigimod, following the failure of conventional therapy. After a cycle of efgartigimod treatment, complete resolution of myasthenic symptoms was observed. During the 6-month follow-up, with sustained clinical remission and attainment of Minimal Manifestation Status (MMS). This case represents the first documented use of efgartigimod in a DSP-MG patient, providing preliminary clinical evidence for its potential efficacy in this rare and poorly understood subtype. Our findings contribute to the limited literature on DSP-MG and suggest that FcRn inhibition may offer a viable treatment option where conventional therapies fail. Efgartigimod may represent a potential therapeutic agent for DSP-MG.", "authors": ["Huang Xiaohui", "Wan Yue", "Chen Yu", "Lei Keqi"], "journal": "Frontiers in immunology", "entry_date": "2025/10/29 04:47", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41159035/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Jianghan University, Wuhan, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41158935", "title": "Checkpoint Inhibitor-Associated Myasthenia-Myositis Overlap With Neuromuscular Respiratory Failure After Dual PD-L1 Plus CTLA-4 Checkpoint Blockade for Hepatocellular Carcinoma.", "abstract": "Immune checkpoint inhibitors are standard therapy for unresectable hepatocellular carcinoma (HCC), but rare immune-related adverse events may be life-threatening. We describe an 80-year-old man with unresectable HCC who received dual durvalumab and tremelimumab on a non-STRIDE schedule. Within four weeks, he developed ptosis, diplopia, and bulbar weakness that rapidly progressed to neuromuscular respiratory failure. Laboratory evaluation revealed markedly elevated creatine kinase, troponin, and aldolase levels, along with a strongly positive acetylcholine receptor antibody. Despite treatment with high-dose corticosteroids, intravenous immunoglobulin, and plasma exchange, neurologic recovery was limited, and he experienced recurrent respiratory decline. After confirming decision-making capacity, he chose to discontinue life-prolonging therapy and transitioned to hospice. This case highlights the fulminant potential of myasthenia-myositis overlap after programmed death-ligand 1 (PD-L1) plus cytotoxic T-lymphocyte-associated protein 4 (CTLA-4) blockade, underscores the importance of early biomarker surveillance and rapid escalation to immunomodulatory therapy, and illustrates the need for early goals-of-care discussions in patients facing severe immune-related toxicities.", "authors": ["Bowen Adam M", "Baraka Dania", "Thulluri Ramalakshmi", "Lantis Miller", "Russell Claire", "Patterson Taylor", "Pierce Shannon", "Alshaikhli Alfarooq"], "journal": "Cureus", "entry_date": "2025/10/29 04:45", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41158935/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Hematology and Oncology, Upstate University Hospital, Syracuse, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41156105", "title": "Innate Immunity in the Pathogenesis of Selected Autoimmune Neurological Diseases.", "abstract": "The human immune system consists of two main components: innate and adaptive immunity. To date, research on the pathogenesis of autoimmune neurological diseases has primarily focused on the role of adaptive immunity. However, growing evidence highlights the significant contribution of innate immune mechanisms in the development of neurological disorders. The aim of this article is to present the current state of knowledge regarding the involvement of innate immunity in the pathogenesis and treatment of selected autoimmune neurological diseases: multiple sclerosis (MS), neuromyelitis optica spectrum disorder (NMOSD), MOG antibody-associated disease (MOGAD), myasthenia gravis (MG), and chronic inflammatory demyelinating polyneuropathy (CIDP). A literature review was conducted, including both experimental and clinical data on the activity of innate immune effector cells-such as dendritic cells, macrophages, microglia, and natural killer (NK) cells-as well as plasma proteins, including the complement system. Relevant clinical and preclinical studies on targeted therapies affecting these components were also identified. All analyzed diseases demonstrate the involvement of innate immune elements in the initiation and maintenance of the inflammatory process. Furthermore, it has been shown that therapies targeting these components may offer clinical benefits.", "authors": ["Rudnicka-Czerwiec Julia", "Bartosik-Psujek Halina"], "journal": "Journal of clinical medicine", "entry_date": "2025/10/29 01:17", "pub_date": "2025-10-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41156105/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Faculty of Medicine, University of Rzeszów, al. Tadeusza Rejtana 16C, 35-959 Rzeszów, Poland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41153571", "title": "Personalized Management and Timing of Thymectomy in Juvenile Myasthenia Gravis: Insights from Routine Clinical Scale Use in a Single-Center Retrospective Cohort-A Case Series.", "abstract": "Introduction: Juvenile myasthenia gravis (JMG) is a rare autoimmune disorder with a variable clinical course and limited pediatric-specific treatment guidelines. Objective clinical scales, such as the Quantitative Myasthenia Gravis (QMG) Score and the Pediatric Myasthenia Gravis Quality of Life 15 (PM-QOL15), may support individualized management, but their role in routine practice remains underexplored. Methods: We retrospectively reviewed 10 seropositive JMG patients followed at a single tertiary neuromuscular clinic between 2014 and 2024. All patients underwent a systematic assessment with QMG at each visit, while PM-QOL15 was administered at the final visit. Clinical data, comorbidities, antibody status, treatment modalities, and outcomes were analyzed. Associations between treatment strategies, comorbidities, and scale scores were explored using appropriate statistical methods. Results: Seven patients (70%) underwent thymectomy, resulting in a reduction in mean QMG scores from 7.7 to 2.4, though residual relapses were observed. Chronic intravenous immunoglobulin (IVIG) therapy, administered to 70% of patients, did not significantly reduce relapse rates or steroid exposure and was associated with higher QMG scores in the second year, suggesting use in more severe phenotypes rather than therapeutic efficacy. Prolonged corticosteroid therapy did not improve remission time or relapse frequency and was complicated by major adverse effects in two patients. Timing of azathioprine initiation showed no significant correlation with relapse frequency. PM-QOL15 correlated strongly with mean QMG (r = 0.88, p < 0.001), reflecting cumulative disease burden. Patients with comorbidities required longer stabilization, although differences were not statistically significant. Conclusions: The routine integration of QMG and PM-QOL15 into follow-up may facilitate the earlier recognition of subclinical deterioration, provide objective measures of treatment response, and guide personalized management in JMG. Thymectomy showed benefit in selected patients, while the long-term roles of IVIG and corticosteroids remain uncertain. Larger multicenter prospective studies are warranted to confirm these findings and refine evidence-based strategies for pediatric JMG.", "authors": ["Ozturk Gulten", "Unver Olcay", "Acar Arslan Elif", "Ermerak Nezih Onur", "Bıkmazer Bilgihan", "Akbeyaz Hakkı", "Karakayali Burcu", "Aksoy Ozcan Sermin", "Akyuz Gulcan", "Ergenekon Pınar", "Gokdemir Yasemin", "Erdem Eralp Ela", "Kahraman Koytak Pınar", "Uluc Kayıhan", "Turkdogan Dilsad"], "journal": "Children (Basel, Switzerland)", "entry_date": "2025/10/29 01:02", "pub_date": "2025-10-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41153571/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatric Neurology, Marmara University Pendik Education and Research Hospital, Istanbul 34899, Turkey."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41151937", "title": "Effective Subcutaneous Efgartigimod Treatment in a 90-Year-Old Female With Myasthenia Gravis.", "abstract": "", "authors": ["Nosaki Yasunobu", "Yokoi Takamasa", "Iwai Katsushige"], "journal": "Journal of clinical neurology (Seoul, Korea)", "entry_date": "2025/10/28 21:34", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41151937/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Toyohashi Municipal Hospital, Toyohashi, Japan. nozaki-yasunobu@toyohashi-mh.jp."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41151932", "title": "Olfactory Dysfunction in Patients With Acetylcholine-Receptor-Antibody-Positive Myasthenia Gravis.", "abstract": "BACKGROUND AND PURPOSE: Myasthenia gravis (MG) is an antibody-mediated disease characterized by fluctuating muscle weakness and fatigue due to impaired neuromuscular junction transmission. Although primarily considered a motor dysfunction disorder, there is emerging evidence that MG can also present with nonmotor symptoms, including olfactory impairment. However, the prevalence and clinical relevance of olfactory dysfunction in MG remain poorly understood. This study compared olfactory function between MG patients and healthy controls with the aim of identifying clinical factors associated with olfactory impairment in MG.\nMETHODS: Acetylcholine receptor (AChR)-antibody-positive MG patients and healthy controls were recruited from a single-center outpatient clinic. Olfactory function was assessed using the KVSS II (Korean version of the Sniffin' Sticks II) test, comprising odor threshold, discrimination, and identification subtests. We compared olfactory function and clinical factors between MG patients and healthy controls after adjusting and matching for age and sex.\nRESULTS: This study enrolled 51 MG patients and 43 healthy controls. Logistic regression analyses revealed that the MG patients had a significantly increased risk of olfactory dysfunction (odds ratio=3.6, 95% confidence interval=1.4-9.1, p=0.008), which remained after adjusting for age and sex. Among the MG patients, those with olfactory dysfunction were older (p=0.002) and had lower AChR antibody titers (p=0.029).\nCONCLUSIONS: Olfactory dysfunction was significantly more prevalent in the MG patients than in the healthy controls. These findings highlight the need for further research into the underlying mechanisms and potential clinical implications of olfactory impairment in MG.", "authors": ["Han Hee Jo", "Lyou Hyun Ji", "Kim Seung Woo", "Lee Jung Hwan", "Shin Ha Young"], "journal": "Journal of clinical neurology (Seoul, Korea)", "entry_date": "2025/10/28 21:34", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41151932/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Severance Hospital, Yonsei University College of Medicine, Seoul, Korea."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41149784", "title": "Management of Myasthenic Crisis and Emerging Roles of Molecularly Targeted Therapies: A Narrative Review.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by fluctuating skeletal muscle weakness. Myasthenic crisis (MCr), a severe and potentially life-threatening complication, presents with respiratory failure and requires intensive care and rapid immunomodulatory intervention. Conventional MCr treatments-such as plasma exchange (PLEX), intravenous immunoglobulin (IVIG), and intravenous methylprednisolone (IVMP)-remain standard treatments; however, they present significant limitations, including delayed onset of action, adverse effects, and inconsistent efficacy. Recent therapeutic advances have led to the development of molecularly targeted therapies based on MG pathophysiology, particularly neonatal Fc receptor (FcRn) inhibitors and complement inhibitors, which have shown efficacy in refractory or maintenance settings. This review explores the potential application of these agents in MCr. We review published case reports involving FcRn inhibitors (efgartigimod, efgartigimod-SC, rozanolixizumab) and complement inhibitors (eculizumab, ravulizumab, zilucoplan), highlighting their rapid onset of action and safety profiles in MCr. While efgartigimod and eculizumab are the most commonly reported agents in MCr, data remain limited to small case series. Emerging evidence suggests these agents may offer effective alternatives to conventional therapies, with favorable safety and potential for rapid symptom resolution. We also discuss strategic considerations for therapy selection, including antibody subtype, coexisting autoimmune conditions, genetic factors, and transition to long-term maintenance. Though the current evidence is promising, large-scale randomized studies are needed to establish definitive roles for these therapies in MCr management.", "authors": ["Takahashi Seiya", "Kinno Ryuta"], "journal": "Neurology international", "entry_date": "2025/10/28 12:45", "pub_date": "2025-10-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41149784/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Showa Medical University Fujigaoka Hospital, 1-30 Fujigaoka Aoba-Ku, Yokohama-Shi 227-8501, Kanagawa, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "41149478", "title": "Incidence of Hypothyroidism and Thyroid Function Monitoring After Immune Checkpoint Inhibitor Therapy Completion for Lung Cancer: A Nationwide Analysis of a Japanese Claims Database.", "abstract": "Immune checkpoint inhibitors (ICIs) improve lung cancer prognosis but are associated with immune-related adverse events, most commonly thyroid dysfunction. While prior studies and guidelines have focused on thyroid dysfunction during ICI therapy, data on hypothyroidism and its monitoring after ICI therapy remain limited. We aimed to investigate hypothyroidism incidence and implementation of thyroid function monitoring after ICI therapy completion in patients with lung cancer. We conducted a retrospective observational study using the DeSC claims database of approximately 12 million individuals in Japan. Patients with lung cancer who received ICI therapy between April 2014 and August 2023 were included; those with a history of thyroid hormone replacement or insufficient follow-up were excluded. Among 6883 eligible patients, 277 (4.0%) developed hypothyroidism requiring hormone replacement post-ICI therapy completion (median onset, 67.0 d). Risk factors included ICI plus bevacizumab therapy and a history of myasthenia gravis, while steroid use for ≥28 d during ICI therapy lowered the risk. Post-ICI therapy completion thyroid monitoring was performed in 73.7% of patients, with test date distribution showing a median of 126.0 d and mode of 21.0 d. Hypothyroidism was frequently found to develop within 2 months post-ICI therapy completion, highlighting the need for continued thyroid monitoring and prospective studies to establish optimal surveillance strategies.", "authors": ["Ohta Hiroaki", "Tsugane Hinako", "Yasu Takeo"], "journal": "Current oncology (Toronto, Ont.)", "entry_date": "2025/10/28 12:37", "pub_date": "2025-10-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41149478/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Education and Research Unit for Comprehensive Clinical Pharmacy, Department of Medicinal Therapy Research, Meiji Pharmaceutical University, Tokyo 204-8588, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "4区"}, {"pmid": "41147199", "title": "IgA autoantibodies demonstrate a novel mechanism of MuSK myasthenia gravis pathology.", "abstract": "Patients with muscle-specific tyrosine kinase (MuSK) myasthenia gravis (MG) develop muscle weakness due to functionally monovalent immunoglobulin (Ig) G4 autoantibodies (Abs) that target MuSK and disrupt acetylcholine receptor (AChR) clustering. Emerging evidence from other autoimmune conditions suggests that Abs of the IgA class-the archetypal immunoglobulin isotype at mucosal sites-may synergize with IgG Abs, contributing to pathology. In MuSK MG, however, the presence of disease-specific IgA Abs has not yet been recognized, limiting a broader understanding of IgG4-driven autoimmunity. To address this knowledge gap, we leveraged cell-based binding assays, patient-derived recombinant monoclonal autoantibodies (mAbs), high-throughput B-cell receptor sequencing, C2C12 mouse myotube cultures and passive immunization experiments. Among 112 sera collected from 25 patients with MuSK MG (discovery cohort), MuSK-specific IgA Abs were detected in eight samples, corresponding to 3/25 (12%) patients. This finding was validated in a second, independent cohort (validation cohort; n = 14 individuals), wherein one additional patient (1/14; 7.1%) harboured MuSK IgA Abs. Across all cases, MuSK IgA Abs coexisted with MuSK IgG Abs, while domain mapping demonstrated a polyclonal IgA response in 2/4 (50%) patients. Notably, in a paradigmatic case with longitudinal samples spanning over a decade, MuSK IgA seropositivity was persistent, and clonally expanded MuSK IgA B cells showed remarkable resistance to therapeutic B-cell depletion. We generated three patient-derived MuSK-specific IgA mAbs for in-depth molecular profiling. These mAbs were highly hypermutated, bound to distinct MuSK domains and shared target epitopes with MuSK IgG4 mAbs. Two IgA mAbs cross-reacted with murine MuSK, enabling functional studies with C2C12 myotubes. Mechanistically, individual IgA mAbs promoted AChR clustering (indicative of MuSK agonism) and partially antagonized the pathogenic effects of MuSK IgG4 monovalency. When modelling a polyclonal response, however, the combination of the same IgA mAbs significantly impaired cluster formation, demonstrating cooperative pathogenic potential. Consistent with this, passive transfer of both IgA clones into mice induced a myasthenic phenotype characterized by progressive weight loss, muscle weakness and structural disruption of the neuromuscular junction (effects similar to those elicited by a functionally monovalent MuSK IgG4 mAb). These findings uncover a previously unrecognized pathogenic Ab isotype in a subset of patients with MuSK MG and show a mechanism through which bivalent MuSK Abs may synergize to induce pathology. The identification of MuSK-specific IgA B cells could signal a role of mucosal or environmental factors in the pathogenesis of MuSK MG and other IgG4-mediated diseases, offering a worthy avenue for future research.", "authors": ["Masi Gianvito", "Chen Kangzhi", "Bayer Alexandra C", "Bayarri-Olmos Rafael", "Pham Minh C", "Wallace Annabel", "Falso Silvia", "Evoli Amelia", "Iorio Raffaele", "Hoehn Kenneth B", "Iwasaki Akiko", "Nowak Richard J", "O'Connor Kevin C"], "journal": "Brain : a journal of neurology", "entry_date": "2025/10/28 05:23", "pub_date": "2026-06-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41147199/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT 06511, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41146809", "title": "Third Nerve Palsy: A Case of Bilateral Eyelid Ptosis, Normal Pupils, and Vertical Diplopia With Multiple Intracranial Lesions.", "abstract": "Bilateral eyelid ptosis presents a rare and diagnostically challenging clinical scenario, particularly when accompanied by multiple intracranial lesions. We present the case of a 68-year-old woman with bilateral ptosis, vertical diplopia, and progressive confusion. Imaging revealed a dorsal midbrain lesion and bilateral frontal lobe masses. Clinical examination ruled out common causes of ptosis, such as myasthenia gravis and muscular dystrophies. The patient's constellation of symptoms, bilateral ptosis without pupillary involvement and vertical diplopia, localized the lesion to the midbrain rather than the cortex. This case highlights the importance of integrating clinical examination with neuroimaging to refine localization in challenging presentations of cranial nerve pathology.", "authors": ["Dragomir Roxana M", "Carranza-Rentería Octavio", "Swerdloff Marc A", "Kay Matthew"], "journal": "Cureus", "entry_date": "2025/10/28 04:06", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41146809/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Florida Atlantic University Charles E. Schmidt College of Medicine, Boca Raton, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41145132", "title": "Patient journey and treatment pattern in myasthenia gravis: real-world data from the Brazilian public health system.", "abstract": "Myasthenia gravis (MG) is a rare neurological disease and the most common autoimmune disorder, characterized by muscle weakness. In Brazil, there is limited data on these patients within the Brazilian public healthcare system (SUS, from Sistema Único de Saúde, in Portuguese).To assess patients with MG in the Brazilian public healthcare system to understand their characteristics, patient journey, and treatment patterns.A retrospective observational study using real-world data from SUS to analyze patients with MG from January 2010 to December 2023. Data were extracted from the DATASUS, focusing on the Outpatient Procedure (SIA) and Hospital Admissions (SIH) information systems. Probabilistic record linkage compiled longitudinal patient data, assessing epidemiology, demographics, clinical characteristics, and treatment patterns, including medications, doses, and lines of treatment (LOT).A total of 13,476 patients with MG were identified. Admissions in healthcare units increased over the years, with 30.4% experiencing exacerbations and 9% crises. The mean age was 45.6 years, with a majority being female (65.4%) and white (53.4%). The case-fatality rate rose from 0.76% in 2011 to 1.90% in 2023. Treatment patterns showed frequent transitions between LOT, indicating constant instability and inadequate symptom control, with azathioprine and pyridostigmine being the most used medications. Some patients started treatment with intravenous immunoglobulin (IVIg), used in combination with other medications, and continued it continuously.The study highlights the increasing burden of MG on SUS, emphasizing the challenges of disease management and the need for continuous advancements in diagnostic and therapeutic strategies to improve patient outcomes.", "authors": ["Andrade Renata", "Marques Junior Wilson", "Vasconcelos Luiza", "Pungartnik Paula", "Berra Thaís Zamboni", "Cortez Lucas Vieira", "Beneduzzi Daiane"], "journal": "Arquivos de neuro-psiquiatria", "entry_date": "2025/10/27 19:53", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41145132/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Hospital Metropolitano Oeste Pelópidas Silveira, Real Hospital Português, Divisão de Doenças Raras, Recife PE, Brazil."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "41142446", "title": "Rehabilitation for functional enhancement of myasthenia gravis: A systematic review and meta-analysis.", "abstract": "Myasthenia gravis (MG) is a rare neuromuscular disorder that causes muscle weakness and fatigue. This review evaluated the current evidence on the efficacy, tolerance and adherence of rehabilitative interventions. Based on the PRISMA guidelines, 445 articles were identified from major scientific databases. After applying the inclusion and exclusion criteria, 6 studies were included in the final analysis. Two primary rehabilitative strategies - physical and respiratory training - were identified. The results of the systematic review and meta-analysis showed that both interventions improved functional capacity and enhanced the quality of life, with good tolerance and high adherence. This review summarizes the effects of rehabilitative interventions on improving 6-min walk distance (6MWD), quality of life (MG-QOL15), and respiratory function (FEV1 and FVC) in MG patients. One study was rated as high quality (OCEBM level 1b), and five as moderate quality (OCEBM level 2b). Five findings were established and rated as Grade B, according to the OCEBM recommendations. This review demonstrated the potential of structured rehabilitation programs to improve functioning and quality of life in patients with MG, while highlighting the need for further research to optimize and standardize these interventions.", "authors": ["Xiangxiang Wen", "Mengjiao Shen", "Shoumei Jia", "Kaitao Yu", "Yafang Xu", "Jie Jia"], "journal": "eNeurologicalSci", "entry_date": "2025/10/27 07:18", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41142446/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Rehabilitation Medicine, Huashan Hospital, Fudan University, 12 Urumqi Road (M), Shanghai 200040, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41142144", "title": "Treatment patterns and impact of glucocorticoids on health outcomes in generalized myasthenia gravis: a retrospective observational study based on the Medical Data Vision database in Japan.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a rare, chronic, autoimmune disorder with a substantial disease burden. Oral glucocorticoids (GCs) are one of the common early-line treatments used globally, but there are growing concerns regarding risks associated with GC adverse effects, which can have serious medical consequences. In Japan, an important gMG treatment goal is minimal disease manifestation with a low target GC dose (≤5 mg/day) to minimize GC exposure. This study aimed to assess gMG treatment patterns in Japan, with a focus on GC exposure and incident comorbidities associated with long-term GC use.\nMETHODS: This was a retrospective, observational database study of patient data from the Medical Data Vision (MDV) database (2008-2022) in Japan. Adults (aged ≥18 years) with ≥2 gMG diagnosis records were considered. First gMG diagnosis (ocular MG excluded) between 2018 and 2021 was considered the index date. All available follow-up was considered if the patient had ≥1 activity in the database annually after the index date.\nRESULTS: Of 9,687 patients with gMG (mean age: 65 years; 56% female; follow-up period: 3.2 years) included in the study, 3,696 (38.2%) were newly diagnosed (2018 onwards) and 5,991 (61.8%) were previously diagnosed (before 2018). Acetylcholinesterase inhibitor (AChEi) and GC monotherapy were the most common initial therapies after index, and most patients were treated with combinations of AChEi, GC, and/or nonsteroidal immunosuppressive therapies (NSISTs). The average daily GC dose was 8.5 mg/day (newly diagnosed: 10.6 mg/day; previously diagnosed: 7.5 mg/day). The target daily dose of 5 mg/day was exceeded by 70% of GC-treated patients, and 26% exceeded 10 mg/day (newly diagnosed: 35%; previously diagnosed: 21%). Compared to patients with no GC exposure, GC use was dose-dependently associated with osteoporosis, thrombosis, diabetes, and hyperlipidemia/hypercholesterolemia, even at GC doses ≤5 mg/day.\nCONCLUSION: Most patients were treated with AChEi, GC, or NSIST monotherapy or combination therapies and received GCs exceeding 5 mg/day, which was associated with developing several GC-associated comorbidities in a dose-dependent manner. To achieve treatment goals, patients with gMG may benefit from additional treatment approaches to reduce GC usage.", "authors": ["Teranishi Hirofumi", "Tsuda Koichi", "Harada Daisuke", "Yachendra Challa", "Nguyen Anthony", "Sato Mai", "Takahashi Masanori P", "Blein Cécile"], "journal": "Frontiers in neurology", "entry_date": "2025/10/27 07:13", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41142144/", "pub_types": ["Journal Article"], "affiliations": ["argenx Japan, Tokyo, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41141095", "title": "Constipation in a Patient With Thymoma: A Diagnostic Mimic of Myasthenia Gravis.", "abstract": "Constipation is a common complaint, but may present atypically in patients with underlying malignancies. We present a 54-year-old man with metastatic thymoma who was admitted with a one-week history of constipation, abdominal discomfort, and nausea. Imaging showed proximal colonic fecal loading with sparing of the descending colon, raising suspicion of dysmotility possibly secondary to a paraneoplastic syndrome. Myasthenia gravis (MG), a known thymoma-associated disorder, was suspected. However, acetylcholine receptor and muscle-specific tyrosine kinase (MuSK) antibodies were negative, and no neuromuscular symptoms were present. The patient responded well to conservative management and was discharged. Two months later, he was readmitted with rapidly progressive bulbar and generalized weakness, severe dysphagia, diplopia, and ptosis, raising renewed concern for MG. Despite persistently negative antibodies, he improved with pyridostigmine and corticosteroids. This case illustrates the evolving nature of paraneoplastic MG, the need to consider both common and rare causes of gastrointestinal symptoms in thymoma patients, and the importance of avoiding premature diagnostic anchoring.", "authors": ["Maali Nirmeen", "Ghanim Amro", "Gowda Sathyanarayana"], "journal": "Cureus", "entry_date": "2025/10/27 07:02", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41141095/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Acute Medicine, Southend University Hospital, Mid and South Essex NHS Foundation Trust, Southend-on-Sea, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41141066", "title": "Immune Checkpoint Inhibitor-Induced Myocarditis, Myositis, and Concern for 3-Ms Syndrome in a Patient With Metastatic Melanoma: A Case Report.", "abstract": "Immune checkpoint inhibitors (ICIs), including ipilimumab and nivolumab, have revolutionized treatment for advanced malignancies such as metastatic melanoma. While effective, these agents can trigger immune-related adverse events (irAEs) that may involve multiple organ systems. Myocarditis, myositis, and myasthenia gravis - collectively referred to as the \"3 Ms\" overlap syndrome - are rare but potentially fatal irAEs. These conditions can present concurrently, often with nonspecific symptoms, making diagnosis challenging and potentially delayed. This case describes a 79-year-old male with stage IV metastatic melanoma who developed myocarditis and myositis following a single cycle of combination ICI therapy, with clinical features raising concern for an overlapping myasthenia-like syndrome, although a definitive diagnosis was not made. Early recognition and prompt initiation of high-dose corticosteroids resulted in clinical improvement and stabilization. This case underscores the importance of maintaining a high index of suspicion for severe irAEs in patients receiving ICIs, as timely intervention is critical to preventing life-threatening complications.", "authors": ["Daw Jad", "Padron Michael J", "Dutta Ishaan", "Stecko Hunter", "Haddad Abdo"], "journal": "Cureus", "entry_date": "2025/10/27 07:02", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41141066/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Cleveland Clinic, Cleveland, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41141054", "title": "Chimeric Antigen Receptor (CAR) T Cell Therapy for Neuromuscular Disorders: A Systematic Review.", "abstract": "Case reports and case studies increasingly demonstrate that chimeric antigen receptor (CAR) T cell therapy (CTCT) is beneficial not only in hematologic malignancies but also in immunologic diseases, including neuromuscular disorders. The aim of this review is to provide an overview of the current status of CTCT in immune-mediated neuromuscular disorders. This is a systematic review of relevant literature recruited using PubMed, Embase, Scopus, and Google Scholar search terms. Neuromuscular disorders for which CTCT has been used to date include myasthenia gravis (n = 4), Lambert-Eaton syndrome (n = 1), myasthenia/Lambert-Eaton overlap (n = 2), dermatomyositis (n = 2), immune-mediated necrotizing myositis (n = 2), idiopathic inflammatory myopathy (n = 1), anti-synthetase syndrome (n = 4), and chronic inflammatory demyelinating polyneuropathy (n = 2). In most cases, CTCT was directed against CD19-positive lymphocytes and in some cases against B cell maturation antigen. In all reported patients, there was a significant improvement in motor function and quality of life, with some even making a full recovery several months after the application of CTCT. In conclusion, CTCT appears to be a promising therapeutic option for patients with severe immune neuromuscular disorders in whom previous treatment with multiple immunomodulatory therapies has been ineffective. CTCT should be considered in patients with immune neuromyopathy who do not respond to immunomodulatory therapies.", "authors": ["Finsterer Josef"], "journal": "Cureus", "entry_date": "2025/10/27 07:02", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41141054/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurology, Neurology and Neurophysiology Center, Vienna, AUT."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41139802", "title": "Cost-Effectiveness Analysis of Efgartigimod vs Chronic Immunoglobulin for the Treatment of Myasthenia Gravis in Canada.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a chronic neuromuscular disease that causes muscle weakness and fatigue, severely impairing quality of life. Efgartigimod is a novel drug that is recently approved for treatment of acetylcholine receptor antibody-positive (AChR-Ab+) gMG patients in Canada. In clinical practice, it is expected to be used in AChR-Ab+ gMG patients who continue to experience symptoms despite conventional therapy and primarily replace chronic immunoglobulins.\nMETHODS: A Markov model was developed to estimate costs and benefits (measured as quality-adjusted life years [QALYs]) of efgartigimod and chronic immunoglobulins for AChR-Ab+ gMG patients. The analysis was conducted from the perspective of the Canadian publicly funded healthcare system over a lifetime horizon. The model comprised six health states based on Myasthenia Gravis Activities of Daily Living (MG-ADL) scores: MG-ADL < 5, MG-ADL 5-7, MG-ADL 8-9, MG-ADL ≥ 10, myasthenic crisis or death. Health state transition probabilities were estimated from the ADAPT and ADAPT+ studies, plus a network meta-analysis that compared efgartigimod against chronic immunoglobulins. The MyRealWorld MG study informed utility values. Modeled costs included treatment and administration, disease monitoring, complications from chronic corticosteroid use, exacerbation/crisis management, adverse events and end-of-life care.\nRESULTS: Over a lifetime horizon, efgartigimod and chronic immunoglobulins were predicted to have total discounted QALYs of 16.80 and 13.35 and total discounted costs of $1,913,294 and $2,170,315, respectively. Efgartigimod dominated chronic immunoglobulins with incremental QALYs of 3.45 and cost savings of $257,020.\nCONCLUSIONS: Efgartigimod provides greater benefit in terms of lower costs than chronic immunoglobulins for AChR-Ab+ gMG patients in Canada.", "authors": ["Siddiqi Zaeem A", "Qi Cynthia Z", "Zhou Allen", "Kaprielian Roger", "Locklin Jason", "Garcia David", "Hughes Tom", "Genge Angela"], "journal": "The Canadian journal of neurological sciences. Le journal canadien des sciences neurologiques", "entry_date": "2025/10/27 00:32", "pub_date": "2025-10-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41139802/", "pub_types": ["Journal Article"], "affiliations": ["University of Alberta, Edmonton, AB, Canada."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41138653", "title": "Neurologic complications of immune checkpoint inhibitors: A comprehensive review.", "abstract": "Cancer is characterized by uncontrolled cell proliferation, often leading to invasion of adjacent tissues and onset of metastasis. Therapeutic options include surgical intervention, chemotherapy, radiotherapy, and targeted therapies, with immune checkpoint inhibitors (ICIs) emerging as a revolutionary approach. ICIs, like anti-CTLA-4 (e.g., ipilimumab) and anti-PD-1/PD-L1 (e.g., pembrolizumab and nivolumab), enhance antitumor immune responses by blocking inhibitory mechanisms within T-cells. Despite benefits, ICIs can elicit immune-related adverse effects (irAEs), manifested by dermatologic, gastrointestinal, endocrine, and neurological toxicities. Although neurological complications are relatively uncommon, they are becoming increasingly noted and range from mild symptoms to life-threatening states. These are categorized into central nervous system (CNS) disorders, such as encephalitis, meningitis, and demyelination, and peripheral nervous system (PNS) manifestations, including neuropathies, myasthenia gravis, and Guillain-Barré syndrome. Early diagnosis and treatment are vital to prevent undue morbidity, as delay can lead to permanent disability. This study seeks to clarify immunological mechanisms of ICI function, epidemiological features of related disorders, clinical presentation, diagnostic tests, therapy, and future directions of investigation, and highlights clinical implications and potential avenues for active clinical and translational research.", "authors": ["Lashkajani Saeed Zivari", "Azad Yasaman Sadat", "Nami Mohammad Taha", "Darzi Ali", "Shokouhfar Mahla", "Faizabadi Sina Naddaf", "Diansaei Maryam", "Aghazadeh-Habashi Komeil", "Tabrizi Zahra Azimzadeh", "Vanan Ahmad Ghorbani"], "journal": "Biomedicine & pharmacotherapy = Biomedecine & pharmacotherapie", "entry_date": "2025/10/25 18:10", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41138653/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Student Research Committee, Kashan University of Medical Sciences, Kashan, Iran."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 10.8, "journal_quartile": "1区"}, {"pmid": "41132658", "title": "An atypical presentation of immune checkpoint inhibitor associated myositis with normal creatine kinase: a case report.", "abstract": "Immune checkpoint inhibitors (ICIs) have been revolutionary in the field of cancer therapeutics. Myositis is a known rheumatic immunotherapy related adverse event with a fatality rate of 26.8% when associated with myasthenia gravis and 51.3% when associated with myocarditis. Typically, creatine kinase (CK) is elevated in ICI-myositis, thus normal CK levels in such cases may delay diagnosis and treatments in such patients. We report 2 cases of patients diagnosed with ICI-myositis after ipilimumab/nivolumab treatment for metastatic renal cell carcinoma and metastatic melanoma. Their lab studies showed normal CK values but elevated aldolase, which led to the ICI-myositis diagnosis and steroid treatment. Early recognition and treatment with steroids led to symptom improvement. These 2 cases highlight an atypical presentation of ICI-myositis with normal CK but elevated aldolase levels, suggesting aldolase may be a sensitive parameter in diagnosing ICI-myositis.", "authors": ["Satoskar Monika A", "Mansour Anthony G", "Wu Richard", "Yang Yuanquan", "Caldwell Mary H", "Meara Alexa S"], "journal": "Frontiers in immunology", "entry_date": "2025/10/24 04:50", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41132658/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, College of Medicine, The Ohio State University, Columbus, OH, United States."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41132654", "title": "Safety profile of complement C5 inhibitors and FcRn inhibitors in the treatment of myasthenia gravis: analysis of the FAERS database and disease-gene interaction network.", "abstract": "OBJECTIVE: To integrate pharmacovigilance and network pharmacology methods for a comprehensive analysis of the potential adverse reactions of complement C5 inhibitors (eculizumab, ravulizumab, zilucoplan) and neonatal Fc receptor (FcRn) inhibitors (efgartigimod, rozanolixizumab), and to explore their toxicity mechanisms, thereby providing a reference for rapidly understanding the safety of these two novel classes of biologics in the treatment of myasthenia gravis (MG).\nMETHODS: We extracted adverse event (AE) reports for these five drugs from the FDA Adverse Event Reporting System (FAERS) database, limited to the period since their FDA approval for the treatment of MG. Reports were further restricted to those where the drug was listed as the primary suspect (PS) and the indication (INDI) was \"MG\". Signal detection was performed using the Reporting Odds Ratio (ROR) method, the UK Medicines and Healthcare products Regulatory Agency (MHRA) method, and the Bayesian Confidence Propagation Neural Network (BCPNN) method. Additionally, network pharmacology was employed to analyze the toxicity mechanisms of the system organ categories (SOCs) specifically associated with complement C5 inhibitors and FcRn inhibitors.\nRESULTS: Signal detection of AE reports associated with these five drugs revealed previously unlabeled positive signals, including: eculizumab (gastric cancer, embolic stroke), ravulizumab (psoriatic arthropathy, hypoacusis, peripheral vascular disorders), zilucoplan (weight increased, weight decreased), efgartigimod (metastases to liver, hepatic failure, nephrolithiasis, dysuria, Prostatitis, prostate cancer, Angina pectoris, congestive cardiac failure) and rozanolixizumab (vomiting, dyspepsia). However, the gastric cancer, liver metastasis and prostate cancer were reported within the first 30 days, causal associations cannot be established based on the data presented. Potential toxicity analysis was conducted on noteworthy SOCs for complement C5 inhibitors and FcRn inhibitors, revealing key targets and pathways.\nCONCLUSION: This study elucidated the safety profiles of complement C5 inhibitors and FcRn inhibitors in clinical practice through pharmacovigilance analysis, confirming known adverse reactions and identifying several previously unreported ones. Furthermore, network pharmacology analysis revealed potential mechanisms underlying these adverse reactions. These findings provide valuable insights for monitoring and managing risks during treatment with two novel classes of biologics.", "authors": ["Wang Luqiong", "Chen Jiaojiao", "Li Huixiang", "Wang Lin", "Liu Feiyu", "Jiang Xiaoli"], "journal": "Frontiers in immunology", "entry_date": "2025/10/24 04:50", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41132654/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pharmacy, Yantai Yuhuangding Hospital Affiliated to Qingdao University, Yantai, Shandong, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41131267", "title": "Clinical Status, Treatment, and Disease Burden of Generalised Myasthenia Gravis in the Asia-Pacific.", "abstract": "INTRODUCTION: Generalised myasthenia gravis (gMG) is a rare autoimmune disorder presenting as variable skeletal muscle weakness and fatigue. Comorbidities are common and symptoms are unpredictable and fluctuating. Many patients rely on immunosuppressive treatments including corticosteroids in their disease management, despite adverse events (AEs) associated with extended or high-dose use. We aimed to investigate clinical characteristics, treatment patterns, and disease burden of patients diagnosed with gMG across the Asia-Pacific region.\nMETHODS: Data were drawn from the Adelphi Real World gMG Disease Specific Programme™, a cross-sectional survey of neurologists and their patients with gMG in Australia, China, Japan, South Korea, Malaysia, and Taiwan, from July 2023 to January 2024. Neurologists reported clinical characteristics from diagnosis, current maintenance treatment initiation, and at survey completion.\nRESULTS: Neurologists (n = 173) reported data on 407 patients with gMG. At the time of survey, mean (standard deviation) patient age was 51.5 (15.3) years and 58.2% were female. Also at survey, 77.6%, 20.1%, and 2.2% of patients had a Myasthenia Gravis Foundation of America class of II, III, or IV, respectively. Since diagnosis, myasthenic crises (22.5%) or exacerbations (37.2%) were reported for most patients (52.7%). Acetylcholinesterase inhibitors (82.8%) and corticosteroids (69.5%) were most commonly prescribed gMG treatments at survey completion, and 65.1% of patients were not in pharmacological remission. AEs were experienced by 71.0% of those prescribed corticosteroids. Joint effects of corticosteroid dose and duration on the increased number of comorbidities and AEs was significant (p = 0.0319).\nCONCLUSION: Across the Asia-Pacific, most patients did not achieve pharmacological remission despite prescribed treatments, and experienced treatment-related AEs, indicating significant unmet clinical needs. It is suggested that corticosteroid overreliance in maintenance treatment could be associated with increases in comorbidities and AEs. Further research is needed to understand how novel treatments could impact clinical outcomes and reduce corticosteroid reliance for patients with gMG in the Asia-Pacific.", "authors": ["Webb Thomas", "Kasahara-Kiritani Mami", "Herr Keira", "Yu DaeYoung", "Lee Bolam", "Barlow Sophie", "Birija Shiva Lauretta", "Conyers Joe", "Connolly Hannah", "Gibson Gregor", "Hatchell Niall", "Ringland Ciara", "Hong Yoon Ho"], "journal": "Neurology and therapy", "entry_date": "2025/10/23 23:41", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41131267/", "pub_types": ["Journal Article"], "affiliations": ["Market Access (Asia Pacific), Johnson & Johnson, Singapore, Singapore."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "41129501", "title": "Myasthenia gravis and autoimmune overlap: Prognostic insight.", "abstract": "BACKGROUND: Autoimmune diseases (ADs) frequently coexist with myasthenia gravis (MG), suggesting shared genetic and immunological mechanisms. However, the impact of comorbid ADs on MG prognosis remains unclear. This study aimed to investigate the prevalence, clinical characteristics, and prognosis of MG patients with comorbid ADs in a Turkish cohort.\nMETHODS: We retrospectively analyzed 302 MG patients treated at a tertiary center between 2010 and 2024. Patients were grouped based on the presence of comorbid ADs. Clinical characteristics, disease severity, treatment response, and prognosis were compared.\nRESULTS: Among 302 MG patients, 41 (13.6%) had at least one comorbid AD, with autoimmune thyroid disease (AITD) being the most common (10.6%). ADs were more frequent in females. Patients with and without comorbid ADs showed no significant differences in MG severity, thymectomy rates, myasthenic exacerbations, or overall outcomes (p > 0.05). However, female patients with ADs experienced more frequent myasthenic exacerbations and had a higher rate of rituximab use (p < 0.05).\nCONCLUSIONS: Comorbid ADs do not significantly impact MG severity or prognosis. Female MG patients with ADs have a higher frequency of myasthenic exacerbations and rituximab use, warranting further research. Early identification of ADs remains essential for optimal patient management.", "authors": ["Oguz-Akarsu Emel", "Lazrak Sarra El Hamida", "Sigirli Deniz", "Gullu Gizem", "Dinç Yasemin", "Saridas Furkan", "Karli Necdet"], "journal": "PloS one", "entry_date": "2025/10/23 13:32", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41129501/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Uludag School of Medicine, Bursa Uludag University, Bursa, Turkey."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "41126943", "title": "Coexistence of Acute Demyelinating Polyneuropathy and LRP4-Positive Myasthenia Gravis.", "abstract": "INTRODUCTION: Guillain-Barré syndrome (GBS) and myasthenia gravis (MG) are rare autoimmune disorders that may share overlapping features such as ophthalmoparesis, limb weakness, and bulbar symptoms, complicating the differential diagnosis. Coexistence of GBS and MG or chronic inflammatory demyelinating polyneuropathy and MG, particularly the low-density lipoprotein receptor-related protein 4 (LRP4) antibody-positive subtypes, is extremely rare. We present such a case to highlight diagnostic challenges.\nCASE PRESENTATION: A 46-year-old man presented with distal weakness, sensory loss, facial diplegia, and dyspnea. Nerve conduction studies revealed demyelinating features, and cerebrospinal fluid analysis showed albuminocytologic dissociation. An acute demyelinating polyneuropathy, most likely GBS, was suspected, and clinical improvement was observed following plasmapheresis. Three weeks later, new symptoms including dysarthria and worsening bulbar weakness emerged. Repetitive nerve stimulation showed a decremental response. LRP4 antibodies were positive, confirming MG. The patient improved with intravenous immunoglobulin, corticosteroids, pyridostigmine, and azathioprine.\nCONCLUSION: This case underscores the rare coexistence of acute demyelinating polyneuropathy and LRP4-positive MG. In acute demyelinating polyneuropathy patients with relapsing or worsening symptoms, coexisting MG should be considered. Comprehensive electrophysiological evaluation and antibody testing, including LRP4, are essential for the accurate diagnosis of both conditions.", "authors": ["Fidancı Halit", "Turhan Sevgi", "Alaydın Halil Can", "Ertürk Ahmet Yusuf", "Öztürk İlker"], "journal": "Case reports in neurological medicine", "entry_date": "2025/10/23 04:45", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41126943/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Division of Clinical Neurophysiology, University of Health Sciences Adana City Training and Research Hospital, Adana, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.9, "journal_quartile": "4区"}, {"pmid": "41123841", "title": "Mental Health Experiences and Challenges Among Individuals with Myasthenia Gravis: Insights from Patient-Centered, Qualitative Analyses.", "abstract": "INTRODUCTION: Historically, anxiety and depression rates have been higher among individuals with myasthenia gravis (MG) than the general population, and self-reported sentiments and experiences of mental health impairment may be more common than formal diagnoses. Patient-centered research can provide insight into self-described anxiety and depressive symptoms and stressors experienced by those with MG in the United States (US) and improve understanding of the current prevalence of anxiety and depression.\nMETHODS: Insights were collected from three sources. First, a literature review of quantitative and/or real-world studies of anxiety/depression among individuals with gMG in the US. Second, a secondary, qualitative analysis of the transcripts from focus groups conducted with 12 individuals with self-reported generalized MG. Third, analysis of thousands of online conversations between people with self-reported ocular or generalized MG using search, data extraction, and artificial intelligence-powered algorithms. No statistical analyses were performed.\nRESULTS: The literature review identified three studies (precluding a meta-analysis): prevalence estimates for depression were 19% (diagnosed), 31% (receiving antidepressants), and 75% (self-reported sentiments), and for anxiety were 17%, 19% (both diagnosed), and 82% (self-reported sentiments). Unique stressors and triggers were identified, classified into four categories: experience of symptoms/uncontrolled symptoms; burden of medical care; daily life functioning, responsibilities, and aspirations; and social support needs. The relative prominence of each stressor and its induced emotion varied by stage in the disease journey: fear and anxiety were discussed more frequently prior to MG diagnosis, whereas hopelessness and depression became more prominent later, during ongoing disease monitoring and management. Patients felt that stress worsened symptoms in a positive feedback loop.\nCONCLUSION: This qualitative, hypothesis-generating study found that individuals with MG in the US were more likely to report experiencing anxiety and depression than the general population due, at least in part, to their MG-specific disease journey and the uncontrolled symptoms experienced.", "authors": ["Rodriguez Rachelle D", "Anderson Ashley E L", "Gwathmey Kelly G", "Brethenoux Caroline R", "Shea Lisa M", "Govindarajan Raghav", "Souayah Nizar", "Peters Wesley D", "Jackson Louis A", "Choudhry Zia U"], "journal": "Advances in therapy", "entry_date": "2025/10/22 11:25", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41123841/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Johnson & Johnson, Raritan, NJ, USA. rachelle.d.rodriguez@gmail.com."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "41118207", "title": "Therapeutic IgG- and IgM-specific proteases disarm the acetylcholine receptor autoantibodies that drive myasthenia gravis pathology.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder caused mainly by autoantibodies against the acetylcholine receptor (AChR), leading to muscle weakness. While treatments targeting AChR autoantibodies benefit many, some patients remain refractory, highlighting the need for personalized therapies. This study evaluates the therapeutic potential of S-1117, a pan-IgG-specific protease, in AChR autoantibody-mediated pathology. Using live cell-based assays, we examined AChR-specific monoclonal IgG autoantibodies (mAbs) and patient-derived serum samples for their effects on receptor binding, blockade, internalization, and complement activation, before and after treatment with S-1117. S-1117 effectively removed the crystallizable fragment (Fc)γ from both mAbs and serum IgG, impairing Fcγ-mediated complement activation in both soluble and antigen-bound forms. In cases with partial complement reduction, AChR-specific IgM contributed to complement deposition. AChR-IgM acted in concert with IgG in some patients to enhance complement deposition, while acting as main complement driver in others. An IgM-specific protease completely suppressed the pathogenic effects of AChR-IgM in two independent patient cohorts. These findings highlight the therapeutic potential of S-1117 in neutralizing AChR-IgG Fcγ-mediated effector functions and reveal an MG subset driven by IgM pathology. Our study shows that targeting both IgG- and IgM-mediated mechanisms with therapeutic proteases provides an approach to MG treatment and establishes a framework for patient stratification based on disease mechanisms, advancing precision medicine in MG.", "authors": ["Bayer Alexandra C", "Sanmarco Liliana M", "Pellerin Alex", "Masi Gianvito", "Plasencia Agustin", "Anderson Jordan M", "Nowak Richard J", "Damato Valentina", "Massacesi Luca", "Pham Minh C", "Khani-Habibabadi Fatemeh", "Vital Heather", "Higginson-Scott Nathan", "Otipoby Kevin L", "Xing Yi", "Mascanfroni Ivan D", "O'Connor Kevin C"], "journal": "Proceedings of the National Academy of Sciences of the United States of America", "entry_date": "2025/10/21 11:44", "pub_date": "2025-10-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41118207/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT 06511."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "41118002", "title": "Long-term effectiveness of thymectomy in late-onset myasthenia gravis.", "abstract": "BACKGROUND: Thymectomy is a well-established treatment in anti-AChR generalized myasthenia gravis (gMG) patients aged 18-50 years. However, the MGTX trial failed to prove an additional benefit of thymectomy in late-onset MG (LOMG) patients and studies conducted so far have shown controversial results. The primary aim of this study was to assess the safety and effectiveness of thymectomy in LOMG patients compared to medical therapy alone.\nMETHODS: This was an observational retrospective case-control study of LOMG patients followed at the MG Clinic of Pisa University Hospital from 1996 to 2024. Inclusion criteria were: diagnosis of non-thymomatous gMG with anti-AChR antibodies; age at onset ≥ 50 years, and minimum follow-up of 12 months. The cumulative incidence of disease remission between the thymectomy and the conservative group was compared with Kaplan-Meier analysis with log-rank test and the Cox regression model was used to estimate the effect of thymectomy on achieving remission after adjustment for confounding variables.\nRESULTS: Among our population of 127 LOMG patients, 87 patients underwent thymectomy, while 40 patients received medical treatment only. When evaluating neurological outcomes at the last follow-up, the thymectomy group had a 3.25-fold (HR = 3.25, 95% CI 1.31-8.1) increased probability of achieving disease remission than the conservative group, after adjustment for confounding variables.\nCONCLUSION: Our findings suggest that thymectomy may be a feasible and potentially beneficial therapeutic option in this MG subgroup, possibly increasing the likelihood of disease remission without ongoing immunosuppressive therapy.", "authors": ["Latini Ester", "Guida Melania", "Zirafa Carmelina Cristina", "Rizzo Stefania", "Cepele Alba", "Romano Gaetano", "Aprile Vittorio", "Lucchi Marco", "Siciliano Gabriele", "Ricciardi Roberta", "Maestri Tassoni Michelangelo"], "journal": "Journal of neurology", "entry_date": "2025/10/21 11:17", "pub_date": "2025-10-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41118002/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Experimental and Clinical Medicine, Division of Geriatric and Intensive Care Medicine, University of Florence, Viale Brambilla, 3, Firenze, Italy. ester.latini@unifi.it."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41114975", "title": "Medicare Part D Use and Costs for Immune-Mediated Neurologic Therapies.", "abstract": "IMPORTANCE: The expansion in the number of disease-modifying therapies (DMTs) for immune-mediated neurologic diseases raises critical questions about trends in their use and cost over time and whether this growth could be contributing to escalating financial burdens within the Medicare system.\nOBJECTIVE: To examine trends in claims and Medicare Part D payments for DMTs for immune-mediated neurologic diseases.\nDESIGN AND SETTING: This retrospective economic evaluation analyzed Medicare Part D Prescriber Public Use Files from January 1, 2013, to December 31, 2022, restricting to prescription drug claims categorized under the clinician-defined neurology taxonomy. Only prescription drugs used as DMTs for multiple sclerosis, neuromyelitis optica spectrum disorder, and other immune-mediated neurologic disorders were included. To ensure accuracy, these medications were validated by 2 pharmacists. The data were analyzed between October 1, 2023, and November 12, 2024.\nMAIN OUTCOMES AND MEASURES: Ten-year trends in total payments, number of claims, and payment per claim for DMTs were assessed for their contribution to overall cost increases. Inflation adjustments were applied using both medical care-specific and prescription drug-specific indices.\nRESULTS: Between 2013 and 2022, 63 unique drugs used as DMTs for multiple sclerosis, neuromyelitis optica spectrum disorder, and other immune-mediated neurologic disorders (eg, autoimmune encephalitis, myasthenia gravis) accounted for 6 526 278 claims and contributed $35 billion in Medicare drug expenditures. Between 2013 and 2022, annual claims for DMTs increased by 3.8% (from 549 766 to 570 298 claims). However, total payments for DMTs saw a disproportionate increase of 70.3% (95% CI, 13.5%-130.3%) from 2013 to 2022. After adjusting for medical care or prescription drug inflation, 2022 payments per claim increased by 29.1% (95% CI, 15.6% to 51.6%) and 35.9% (95% CI, 29.5%-50.3%), respectively, indicating that the rise in drug costs exceeded adjustments for medical care or prescription drug inflation rates. For the 29 DMTs available over the entire 10-year period, total claims decreased by 14.8% (from 546 026 to 465 089). Despite this reduction in claims, total payments increased by 60.5% (95% CI, 50.9%-90.6%). After adjusting for medical care inflation, the total payment increased significantly by 26.2% (95% CI, 10.5%-49.4%).\nCONCLUSIONS AND RELEVANCE: Over the past decade, Medicare Part D expenditures for DMTs targeting immune-mediated neurologic diseases have increased substantially, despite relatively stable claim volumes. These findings show that increases have consistently outpaced inflation rates, adding substantial economic pressure to federally funded neurologic care.", "authors": ["Wong Ka-Ho", "Zeng Esther", "Smith Tammy L", "King Jordan B", "Marini Erica", "Sorenson Abigail", "Hwang Heewon", "Stein Chloe", "Francis Trieste", "Rose John W", "Reddy Vivek K", "de Havenon Adam Helme", "Clardy Stacey L"], "journal": "JAMA network open", "entry_date": "2025/10/20 11:33", "pub_date": "2025-10-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41114975/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, University of Utah School of Medicine, Salt Lake City."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 9.7, "journal_quartile": "1区"}, {"pmid": "41114833", "title": "Characteristics of ventilator weaning in patients intubated for Guillain-Barré syndrome or myasthenia gravis: a nationwide multicenter study.", "abstract": "PURPOSE: Severe forms of Guillain-Barré syndrome (GBS) and myasthenia gravis (MG) may result in prolonged mechanical ventilation in ICUs. Data on weaning from mechanical ventilation are scarce, and our objective was to assess ventilator weaning characteristics in a large-scale multicenter study.\nMETHODS: Multicenter retrospective cohort study including all patients intubated for at least 48 h for GBS or MG over a 10-year period (from January 2014 to December 2023). The primary outcome was the proportion of patients having experienced prolonged weaning (at least 7 days).\nRESULTS: Some 886 patients admitted to 47 ICUs in France were retained in the analysis, including 513 (58%) with GBS and 373 (42%) with MG. Patients with GBS were more likely to experience prolonged weaning than those with MG (64% vs. 35%, p < 0.001). An extubation attempt was performed in only 46% of patients with GBS and in 88% patients with MG (p < 0.001). Reintubation rates were 26% in patients with GBS and 29% in patients with MG (p = 0.440). Patients with GBS were more likely to undergo tracheostomy than those with MG (57% vs. 17%, p < 0.001). Patients with GBS required a longer duration of mechanical ventilation and ICU stay. Mortality rates were similar (9.4% for patients with GBS and 9.7% for patients with MG, p = 0.882).\nCONCLUSIONS: Patients with GBS were more likely to experience prolonged weaning and to undergo tracheostomy than patients with MG. More than one-fourth of patients required reintubation after an extubation attempt. Despite prolonged duration of mechanical ventilation, mortality remained relatively low.", "authors": ["Thille Arnaud W", "Bayon Constance", "Gauvrit Marie", "Saccheri Clément", "Labruyere Marie", "Beduneau Gaetan", "Wattecamps Guilhem", "Henry Matthieu", "Bendiab Eddine", "Swinyard Benjamin", "Gacouin Arnaud", "Celier Adam", "Foucou Benjamin", "Champion Suzanne", "Haudebourg Anne-Fleur", "Dangers Laurence", "Plateker Olivier", "Daubin Cedric", "Fromont Lucie", "Guesdon Charlotte", "Vivier Emmanuel", "Volkov Lev", "Potier Cyril", "Bourenne Jeremy", "Chiquet Charlotte", "Pointurier Valentin", "Chauvelot Louis", "Bailly Pierre", "Schnell David", "Sedillot Nicholas", "Reizine Florian", "Argaud Laurent", "Reynaud Faustine", "Pelle Juliette", "Lesieur Olivier", "Auvet Adrien", "Lacave Guillaume", "Kernevez Marion", "Contou Damien", "Grillet Guillaume", "Delahaye Arnaud", "Badie Julio", "Devaquet Jerome", "Chauvin Hermine", "Beurton Alexandra", "Turbil Emanuel", "Rigaud Jean-Philippe", "Ragot Stéphanie", "Chamblet Louis", "Coudroy Rémi", "Le Pape Sylvain"], "journal": "Intensive care medicine", "entry_date": "2025/10/20 11:14", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41114833/", "pub_types": ["Journal Article", "Multicenter Study", "Research Support, Non-U.S. Gov't"], "affiliations": ["Service de Médecine Intensive Réanimation, CHU de Poitiers, Poitiers, France. aw.thille@gmail.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 21.2, "journal_quartile": "1区"}, {"pmid": "41113248", "title": "Robot-assisted extended thymectomy in juvenile myasthenia gravis: first case performed in Ecuador.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by fatigable muscle weakness, typically caused by antibodies against acetylcholine receptors (AChR) or muscle-specific kinas. While it primarily affects adults, juvenile cases represent a significant minority and often pose greater therapeutic challenges. Extended thymectomy has proven beneficial in AChR-positive MG, reducing symptoms and immunosuppressive needs. Robotic-assisted thymectomy offers enhanced precision with lower morbidity. We report the first such procedure in Ecuador, performed on a 21-year-old woman with recurrent myasthenic crises. The surgery was uneventful, and follow-up showed marked clinical improvement without recurrence, highlighting the feasibility of advanced techniques in low-resource settings.", "authors": ["Gagliardo Enrique", "Aguaguiña Toainga Luis", "Pérez Cedeño Janneth Alejandra", "Barrera Delgado Luis Alberto", "Munoz Andrade Luis"], "journal": "Journal of surgical case reports", "entry_date": "2025/10/20 07:10", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41113248/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["National Oncology Institute SOLCA Guayaquil, Department of Thoracic Surgery, Guayaquil, Guayas 090505, Ecuador."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41112289", "title": "Efgartigimod for patients with thymoma associated generalized myasthenia gravis during the perioperative period: a four-case report.", "abstract": "BACKGROUND: Thymectomy is one of the main treatments for thymoma associated myasthenia gravis, but there is a risk of acute exacerbation of myasthenia gravis symptoms during the perioperative period of thymoma. Therefore, perioperative management is very important. We reported four cases of thymoma associated generalized myasthenia gravis who were treated with efgartigimod before and after the perioperative period. The myasthenic symptoms of the patients were quickly controlled before surgery, and the patients successfully completed the surgery without experiencing myasthenic crisis or respiratory failure after surgery.\nCASE REPORT: Four patients diagnosed with thymoma associated generalized myasthenia gravis were all acetylcholine receptor(AChR) antibody-positive, with case 2 also positive for Titin and anti-RyR antibodies. Prior to surgery, all patients exhibited varying degrees of myasthenic symptoms, with case 2 experiencing a myasthenic crisis induced by glucocorticoid pulse therapy before the operation. Admitted to our multidisciplinary treatment group for myasthenia gravis, all four patients received 1 to 2 treatments with efgartigimod before thymoma surgery, which led to an improvement in myasthenia symptoms and a significant reduction in MG-ADL and QMG scores. All four patients underwent video-assisted thoracoscopic mediastinal tumor resection under general anesthesia, followed by the 3rd to 4th treatments with efgartigimod postoperatively, with no perioperative myasthenic crisis occurring in any of the patients. Apart from case 1, who developed a new pulmonary infection postoperatively and experienced a temporary fluctuation in myasthenia symptoms, the other three patients had no severe complications. Follow-up visits at one month and three months postoperatively showed that three of the patients achieved minimum symptom expression (MG-ADL score ≤1).\nDISCUSSION: Efgartigimod provides new insights into the perioperative management of thymomas in patients with thymoma associated generalized myasthenia gravis.", "authors": ["Ren Liuli", "Wei Ling", "Jiang Song", "Li Hongru", "Chen Anguo", "Zhang Juanjuan"], "journal": "Frontiers in immunology", "entry_date": "2025/10/20 07:01", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41112289/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Pharmacy, First Affiliated Hospital of Anhui Medical University, Hefei, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "41109821", "title": "A case report of atypical anaphylaxis in an immunosuppressed myasthenic patient.", "abstract": "Anaphylaxis is a life-threatening systemic hypersensitivity reaction characterized by rapid onset and potential for airway, respiratory, or circulatory compromise. Early recognition and treatment with intramuscular epinephrine are critical to improve outcomes However, atypical or delayed presentations may occur, especially in patients on chronic immunosuppressive therapies such as corticosteroids, which can blunt or delay inflammatory responses. Additionally, patients with autoimmune conditions like myasthenia gravis (MG) present unique diagnostic and therapeutic challenges due to overlapping symptomatology and medication sensitivities We report a case of a 49-year-old male with MG maintained on high-dose weekly prednisone (200 mg) presenting with progressive urticaria, dyspnea, dizziness, and hypotension two days after hot tub exposure. The delayed onset of symptoms, coupled with a muted systemic response likely from chronic steroid use, complicated the recognition of anaphylaxis. Despite administration of multiple doses of antihistamines and intramuscular epinephrine, the patient remained hypotensive and required vasopressor support. He responded to an epinephrine infusion and was stabilized in the critical care unit. This case underscores the diagnostic complexity of anaphylaxis in immunosuppressed individuals. Delayed or incomplete presentations may hinder timely intervention. A high index of suspicion should be maintained for atypical anaphylactic shock in patients with autoimmune disorders on chronic steroids, with early consideration for vasopressor support when IM epinephrine is insufficient.", "authors": ["Nepal Nirajan", "Thomas Virginia", "Guerra Cayla M", "Harnly Allison"], "journal": "The American journal of emergency medicine", "entry_date": "2025/10/18 21:59", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41109821/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Madigan Army Medical Center, 9040A Jackson Ave Joint Base Lewis-McChord, WA 98431, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41104507", "title": "Survival Outcomes of Medicare-Covered Elderly US Population With Myasthenia Gravis.", "abstract": "INTRODUCTION/AIM: Survival outcomes have been inadequately studied among people with myasthenia gravis (MG) in the United States (US). We examined the impact of MG and comorbid conditions on longevity.\nMETHODS: We performed a longitudinal study using Medicare claims data (2006-2019). Incident MG cohort was identified based on the following criteria: age ≥ 65 years; ≥ 1 month of fee-for-service Parts A and B coverage; no health maintenance organization coverage; initial and subsequent MG claims within 2010-2011 separated by ≥ 28 days. A non-MG cohort of five times the number of the MG group was selected, matching for age, sex, region, and Medicare coverage duration. Overall and cause-specific mortality were compared between cohorts in the subsequent 8-10 Years using Kaplan-Meier plots and Cox proportional hazard models, adjusted for the Charlson Comorbidity Index (CCI).\nRESULTS: Cohorts of 6024 incident MG and 30,083 control beneficiaries were Included. The mortality rate was higher in the MG cohort compared to controls (66.8 vs. 57.1 per 1000-person-year, p < 0.0001). After adjusting for time-varying CCI, no significant difference in survival was observed between two cohorts (adjusted hazard ratio 1.09 [0.87-1.36], p = 0.47). Sixteen percent of deaths in the MG cohort were attributed to MG. Compared to the non-MG cohort, mortality rates (per 1000-person-year) specific to infections were higher among the MG cohort (2.0 vs. 1.2) while malignancies and dementia-specific mortality rates were lower (10.3 vs. 12.5 and 4.7 vs. 7.2), all p < 0.01.\nDISCUSSION: Long-term mortality is increased in elderly MG patients compared to non-MG counterparts, driven by their higher comorbidity burden.", "authors": ["Li Yuebing", "Bruckman David", "Schold Jesse D", "Claytor Benjamin", "Silvestri Nicholas", "Hehir Michael K", "Lee Ikjae"], "journal": "Muscle & nerve", "entry_date": "2025/10/17 05:23", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41104507/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Cleveland Clinic, Cleveland, Ohio, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "41103821", "title": "A Hospitalist's Challenge: Systemic Botulism Following a Cosmetic Injection Requiring Antitoxin Therapy and Percutaneous Endoscopic Gastrostomy (PEG).", "abstract": "Botulinum toxin type A (BoNT-A) is widely used in cosmetic practice and generally considered safe, with adverse effects usually limited to transient local reactions. Rarely, systemic spread or counterfeit formulations can cause iatrogenic botulism, presenting with bulbar weakness and generalized neuromuscular dysfunction. We report the case of a 53-year-old woman who developed progressive dysphagia, bilateral ptosis, bifacial weakness, and proximal muscle weakness following cosmetic BoNT-A injections to the face and masseter muscles. Imaging and endoscopic evaluations were unremarkable, and myasthenia gravis (MG) was excluded. Despite initial partial improvement on pyridostigmine, her bulbar dysfunction worsened, necessitating administration of botulinum antitoxin and eventual percutaneous endoscopic gastrostomy (PEG) placement for nutritional support. Over subsequent weeks, she demonstrated gradual recovery, though mild ptosis persisted at discharge. This case underscores the potential for systemic botulism after cosmetic BoNT-A, particularly in the setting of unregulated or counterfeit products. Physicians must maintain a high index of suspicion in patients with recent cosmetic injections presenting with cranial or bulbar symptoms, as timely recognition and antitoxin therapy are essential to optimize outcomes and reduce morbidity.", "authors": ["Patel Parag N", "Kalpana Fnu", "Singh Didar", "Patel Sandipkumar", "Oyewole Kolawole K"], "journal": "Cureus", "entry_date": "2025/10/17 04:51", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41103821/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Medicine, Gujarat Medical Education and Research Society (GMERS) Medical College and Hospital, Patan, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41101827", "title": "Traditional treatments and different geographical approaches.", "abstract": "Therapies for myasthenia gravis (MG) include symptomatic and immunosuppressive/ immunomodulatory treatment. The application of one or more treatments should be based on known efficacy, particularly for specific disease subtypes, disease activity, adverse effect profile, and patient co-morbidities. Traditional treatments include symptomatic treatment and disease- modifying therapy, such as steroids, immunosuppressants, plasmapheresis, intravenous immunoglobulin and thymectomy. Most patients are started with pyridostigmine and steroids but depending on severity or specific type of MG the immunosuppressant or other therapy are added. There is some variability in current recommendations in different MG management guidelines (e.g. Japanese compared to North American), mainly in the selection of glucocorticoids and the first-line non-steroidal immunosuppressants. In this chapter we carry out a review and comparison of all these treatments and compare the different international and national guidelines and consensus, and regional approaches. Approvals of novel therapeutics in MG should not deter clinicians from looking at older interventions, as these still play a key role in the treatment of MG.", "authors": ["Salutto Valeria L", "Shin Ha Young", "Cea Gabriel"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101827/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Instituto de Investigaciones Médicas Alfredo Lanari, Universidad de Buenos Aires, Buenos Aires, Argentina; Centro de Asistencia, Docencia e Investigación en Miastenia Gravis, Buenos Aires, Argentina."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101826", "title": "Clinical outcome measures.", "abstract": "The typical fluctuating skeletal muscle weakness in myasthenia gravis can make measuring disease severity challenging. Multiple measures have been developed to assess the signs and symptoms of myasthenia, from pure examination measures to fully patient-reported measures to combinations. There are also measures aimed at assessing quality of life and satisfaction. Electrophysiology and serology have also been used in some studies as surrogate outcomes. In this chapter, we review outcomes specifically developed to assess disease severity in myasthenia, as well as quality of life, and data on electrophysiology and serology as outcome measures.", "authors": ["Matic Alexandria", "Campman Yvonne", "Tannemaat Martijn Rudolf", "Barnett-Tapia Carolina"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101826/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Division of Neurology, Department of Medicine, Prosserman Family Neuromuscular Clinic, University of Toronto, Toronto, ON, Canada."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101825", "title": "Myasthenia gravis in women.", "abstract": "Myasthenia Gravis (MG) often affects young women, in whom reproductive issues are of importance, including the possibility of MG exacerbation during pregnancy, potential obstetric risks in pregnancy and treatment-related risks to the fetus. Apart from pregnancy, hormonal changes throughout a woman's lifespan may also affect MG symptoms. In this chapter, we discuss the role of sex hormones in MG and the disease burden in women. We also review the effects of pregnancy on MG, the evidence regarding pregnancy outcomes and current recommendations regarding MG treatments during pregnancy.", "authors": ["O'Connor Laura", "Barnett-Tapia Carolina"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101825/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden; Division of Neurology, Department of Medicine, Univerity of Toronto and University Health Network, Toronto, Ontario, Canada."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101824", "title": "The clinical evaluation of myasthenia gravis.", "abstract": "The diagnosis of myasthenia gravis (MG) is strongly considered in a patient complaining of fatigable weakness and in whom muscle fatigability is demonstrated during bedside examination. This chapter will be dedicated to the history-taking and clinical examination of patients with MG and we will also touch upon other myasthenic syndromes and mimics. Most patients first experience fatigable ocular symptoms. The symptoms may remain isolated to the eyes (ocular MG) or later involve the limb, bulbar or respiratory muscles (generalized MG). The examination of the myasthenic patient serves to demonstrate fatigability and distinguish this from non-specific central fatigue or lack of energy. This chapter presents a focused discussion by a neuro-ophthalmologist and neurologists, largely based on their clinical experience.", "authors": ["Europa Tarin A", "Wong Sui H", "Heckmann Jeannine M"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101824/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neurology Research Group, UCT Neuroscience Institute, University of Cape Town, Cape Town, South Africa."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101823", "title": "Diagnosis of MG and differential diagnoses.", "abstract": "The diagnostic workup for myasthenia gravis extends beyond the objective evaluation of skeletal muscle fatigue during neurological examinations. It incorporates antibody testing, electrophysiological studies to confirm neuromuscular transmission impairment, and chest imaging to detect thymoma. Positive clinical response to acetylcholinesterase inhibitors may also support diagnosis. Key clinical assessments focus on symptoms of skeletal muscle fatigability, particularly in ocular, bulbar, and limb-girdle muscles. While the ice-pack test is commonly used to assess ptosis, the global availability of acetylcholinesterase inhibitors for testing remains limited. Radioimmunoassay is the most sensitive diagnostic method for MG-specific antibodies, such as AChR and MuSK, followed by cell-based assays that utilize clustered receptors. Enzyme-linked immunosorbent assay (ELISA) is another option, though with reduced specificity. Electrophysiological evaluation begins with repetitive nerve stimulation (RNS) to detect postsynaptic transmission failure, with single-fiber electromyography (SFEMG) employed in cases where RNS results are inconclusive. All patients with MG, regardless of subtype, should undergo chest imaging (CT or MRI) to screen for thymoma. Differential diagnoses to consider include congenital myasthenic syndromes, cranial nerve disorders such as Horner syndrome or third nerve palsy, autoimmune demyelinating polyneuropathy, mitochondrial myopathy, and motor neuron disorders.", "authors": ["Habib Ali A", "Punga Anna Rostedt"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101823/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University of California, Irvine, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101822", "title": "Future perspectives on myasthenia gravis and related disorders.", "abstract": "The diagnostic precision of MG, along with the emergence of novel treatments targeting the autoimmune response, has ushered the field into a new era, moving MG management closer to personalized medicine. However, critical gaps remain, including the absence of approved treatments for seronegative MG, limited attention to Lambert-Eaton myasthenic syndrome and congenital myasthenic syndromes, and the need for more precise biomarkers. Current clinical trials primarily rely on outcomes that measure symptoms and/or muscle weakness/fatigability; however, there is a need for biomarkers that better reflect disease activity, enable early diagnosis in seronegative MG, and identify the underlying antibodies in these patients. Predictive biomarkers are also needed to assess the risk of generalization from ocular MG and the likelihood of relapses. Furthermore, despite their efficacy, novel treatments such as complement and FcRn inhibitors are costly and inaccessible in many countries. Future MG research must, therefore, prioritize socioeconomic considerations alongside therapeutic advancements. Also, a better understanding of the fatigue in MG, with differences in men and women, is essential to better design treatment over time.", "authors": ["Tapia Carolina Barnett", "Punga Anna Rostedt"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101822/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Division of Neurology, Department of Medicine, University of Toronto, Toronto, Ontario, Canada."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101821", "title": "Exercise and myasthenia gravis.", "abstract": "The role of non-pharmacological management in MG is currently underdeveloped and underutilized. Exercise training has been shown to be both feasible and beneficial in improving function and strength in individuals with MG. Observational studies indicate that physical activity is associated with reduced perceived fatigue. Barriers to exercise persist in MG, and should be addressed by healthcare professionals. Maintaining or increasing muscle strength and endurance as well as cardiorespiratory fitness should be prioritized regardless of current level of function. In the general population, exercise has the potential to reduce anxiety and depression although studies in MG are still lacking. Exercise programs should be individualized and progressive, with a clear emphasis on reducing sedentary behavior. Current research has primarily focused on individuals with mild-moderate MG. Further studies are needed to understand the potential impact of exercise training on enhancing pharmacological therapies and the potential role of exercise in immunomodulation in MG. This chapter reviews the existing literature on exercise in MG.", "authors": ["Birnbaum Simone", "Andersen Linda Kahr"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101821/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuromuscular Physiology and Evaluation Laboratory, Institute of Myology, Paris, France. Electronic address: s.birnbaum@institut-myologie.org."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101820", "title": "Measuring treatment related side effect burden in myasthenia gravis.", "abstract": "Treatment options for patients with myasthenia gravis (MG) are rapidly increasing. Seven new MG therapies across 2 novel classes have been approved by the FDA to treat MG; a robust treatment pipeline spans at least 7 novel therapeutic classes. International MG Consensus Guidance define successful treatments as those that result in minimal disease manifestations or remission with no more than minimal adverse events (AE). The MG community has a number of disease specific outcome measures to evaluate treatment response and patient quality of life. Treatment efficacy only represents one important way to assess treatment value; side effects, burden of therapy, and cost all reduce treatment value. Indeed, patients and clinicians both rate treatment safety as a key consideration when choosing among treatment options. Despite this concern, we have not established the best way to measure side effect burden in MG clinical trials or clinics. To date, the MG community has been focused on the negative side effects associated with corticosteroids, despite well documented, unique side effect profiles that are associated with both traditional and new generation non-steroid MG treatments, some of which can be serious and life threatening. Careful measurement of side effect burden and comparison of this burden among MG therapies will be critical as we attempt to optimize treatment for our patients. This chapter focuses on the importance of measuring MG treatment side effect burden and three measures that may facilitate measuring this burden in future comparative effectiveness trials and in the clinic.", "authors": ["Hehir Michael K", "Howard James F"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101820/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurological Sciences, College of Medicine, University of Vermont, Burlington, VT, United States. Electronic address: Michael.Hehir@uvmhealth.org."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101819", "title": "Novel treatments for myasthenia gravis.", "abstract": "Advances in immunology over the last several years have provided insights into the pathophysiology of autoimmune diseases such as generalized myasthenia gravis (gMG). This has translated into the development of effective, rapidly acting, and targeted novel immune therapies. The two categories of new therapies available at present include the complement C5 inhibitors and the neonatal Fc receptor (FcRn) antagonists. The place of these drugs in the algorithm of MG treatment continues to evolve. Simultaneously, drug development proceeds, with other complement inhibitors, new B cell inhibitor therapy, chimeric antigen therapies and immune tolerizing therapies are in the pipeline. The treatment of gMG will continue to evolve; treatments for subgroups of patients including MuSK- ab+, seronegative and thymoma-associated MG are important areas for future development.", "authors": ["Narayanaswami Pushpa", "Verity Ryan", "Vissing John"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101819/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Beth Israel Deaconess Medical Center, Harvard Medical School, Boston, MA United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101818", "title": "Rescue therapy in myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune disorder characterized by fluctuating muscle weakness due to impaired neuromuscular transmission. Despite therapeutic advances, acute exacerbations and myasthenic crises remain significant challenges. This chapter offers an in-depth overview of rescue therapies for MG, detailing the mechanisms, efficacy, and safety of established treatments such as IVIG and PLEX, and discussing the potential of novel therapies like eculizumab and efgartigimod in acute MG management. We emphasize the importance of personalized treatment approaches tailored to factors such as antibody status, disease severity, and comorbidities. Strategies for monitoring treatment response and managing complications are also discussed. By synthesizing current evidence and expert recommendations, this chapter aims to equip clinicians with the knowledge needed to optimize rescue therapy in MG, ultimately improving outcomes during acute exacerbations and crises.", "authors": ["Bril Vera", "Saedi Elham"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101818/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Ellen and Martin Prosserman Centre for Neuromuscular Disease, University Health Network, Toronto, Ontario, Canada. Electronic address: vera.bril@utoronto.ca."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41101817", "title": "Typical and atypical clinical presentations.", "abstract": "Myasthenia gravis (MG) is the prototypical disorder of the neuromuscular junction. The clinical hallmarks of MG are fatigability and fluctuating voluntary muscle weakness. Although MG can potentially affect any muscle, some muscle groups are involved preferentially and an important clinical distinction can be made between the disease localized exclusively to the extraocular muscles and the disease affecting other muscle groups, called \"generalized\", with relevant therapeutic and prognostic implications. The clinician should be familiar with both common and uncommon patterns of weakness associated with MG and actively search for suggestive anamnestic cues when this disease is suspected. This chapter will focus on the different clinical presentations of MG, encompassing both the detailed clinical complaints and the anamnestic aspects, with a focus on the specific muscular distribution, and the clinical features associated with myasthenic crisis. Lastly, the most described atypical presentations and their differential diagnostic work-up will be reviewed.", "authors": ["Damato Valentina", "Beretta Francesca"], "journal": "International review of neurobiology", "entry_date": "2025/10/16 20:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41101817/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurosciences, Psychology, Drug Research and Child Health (NEUROFARBA), University of Florence, Florence, Italy. Electronic address: valentina.damato@unifi.it."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "41100007", "title": "Associations of child and adolescent obesity with the risk of neuroinflammatory diseases: analysis of data from a global health-care database.", "abstract": "INTRODUCTION: The prevalence of child and adolescent obesity has increased globally. Research has associated obesity-induced immune dysregulation with neurological autoimmune diseases. This study investigated whether obesity-driven inflammation and immunomodulation increase the risk of neuroinflammatory diseases in children and adolescents.\nMETHODS: This retrospective cohort study collected deidentified data from individuals aged 6-18 years from the TriNetX platform. The study cohort was stratified by body mass index (BMI). The outcome measure was the incidence of neuroinflammatory diseases. Covariate-adjusted cox proportional-hazards models were used to assess neuroinflammatory disease risk across the BMI groups.\nRESULTS: Children and adolescents with obesity (BMI: 85th-95th percentile range) and those with severe obesity (BMI: 95th-100th percentile range) had 1.76- and 1.90-fold higher risks of multiple sclerosis (MS), respectively, than did their normal-weight peers. Subgroup analysis revealed that girls and adolescents (age: 12-18 years) were particularly susceptible to MS. The risk of acute disseminated demyelination was elevated in children with obesity but not in those with severe obesity. Notably, no significant association was observed between obesity and myasthenia gravis, inflammatory polyneuropathy, or inflammatory myositis.\nCONCLUSION: Our findings associate child and adolescent obesity with MS; the associations are likely mediated by systemic inflammation and immune dysregulation. The absence of significant associations between child and adolescent obesity and other neuroinflammatory diseases suggests disease-specific mechanisms, underscoring the need for targeted interventions to mitigate the neurological effects of obesity. Overall, child and adolescent obesity significantly modulate immune function, increasing the risk of certain autoimmune neurological diseases, particularly MS. Early interventions are crucial for reducing long-term health risks.", "authors": ["Lee Hsun-Hua", "Yang Tien-Chun", "Chung Cheng-Chih", "Hong Chien-Tai", "Tai Ying-Hsuan"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2025/10/16 11:22", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41100007/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Shuang Ho Hospital, Taipei Medical University, No. 291, Zhongzheng Rd., Zhonghe District, New Taipei City, 23561, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41099443", "title": "Exacerbation and myasthenic crisis in generalized myasthenia gravis: real-world healthcare resource utilization and cost burden in the United States.", "abstract": "OBJECTIVES: Healthcare resource utilization (HCRU) and cost assessments for generalized myasthenia gravis (gMG) rarely include matched controls. HCRU and costs of acute MG-related events (MG exacerbation and myasthenic crisis) have been examined, but aggregation or comparison between studies is limited by heterogeneity. The study aim was to provide comprehensive, real-world data about gMG patients in the United States, including those experiencing MG-related events. A claims database analysis assessed (i) incremental HCRU and cost burden among adults with gMG versus non-gMG controls, (ii) occurrence of MG-related events, (iii) HCRU and cost burden of MG-related events, and (iv) factors associated with MG-related events.\nMETHODS: In this retrospective cohort study, adults with gMG in the United States were identified from Optum's de-identified Clinformatics® Data Mart Database (1 January 2017-31 March 2023). Rates of MG-related events during follow-up were calculated. Regression models assessed associations between occurrence of MG-related events and baseline demographic/clinical variables using a nested case-control design embedded within the existing gMG cohort. Incremental HCRU and healthcare costs were compared between cohorts with/without gMG using the propensity score method with inverse probability of treatment weighting for confounding controls. Incremental HCRU and healthcare costs were also reported for gMG subgroups with/without MG-related events.\nRESULTS: Analyses included 16,561 gMG patients (12,813 prevalent and 3748 incident) and 105,716 non-gMG controls. Among prevalent and incident gMG patients, respectively, MG exacerbation occurred during follow-up in 12.2 and 22.0% and myasthenic crisis in 6.0 and 12.4%. Patients with prior MG-related events were more likely to experience future events (odds ratio range 1.76-7.05). After weighting, gMG patients (median follow-up 696 days) experienced more frequent all-cause HCRU encounters and >4-fold higher healthcare costs ($5420 PPPM or ∼$65,000 per annum) versus non-gMG controls ($1298 PPPM or ∼$15,500 per annum). Among MG patients, those with MG exacerbation/myasthenic crisis, respectively, experienced means of 3.02/3.35 hospitalizations, 1.91/2.13 emergency department encounters, 12.70/13.39 skilled nursing facility encounters, and 67.86/75.52 outpatient encounters during follow-up; associated costs were $17,113/$18,640 PPPM (or ∼$205,000/$224,000 per annum).\nCONCLUSION: The total healthcare cost of gMG was higher than some previous estimates at $5420 PPPM, driven primarily by inpatient care. MG exacerbation and myasthenic crisis occurred at a notable rate, could be recurrent, and were associated with high HCRU and costs. Findings can inform treatment decision-making with the aim of improving symptom control and reducing the likelihood of MG-related acute events.", "authors": ["Jackson Louis", "Liu Zhiwen", "Pesa Jacqueline", "Campbell Alicia K", "Choudhry Zia", "Batista Alberto E", "Souayah Nizar"], "journal": "Current medical research and opinion", "entry_date": "2025/10/16 08:33", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41099443/", "pub_types": ["Journal Article"], "affiliations": ["Johnson & Johnson, Titusville, NJ, USA."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41099132", "title": "Myelin Oligodendrocyte Glycoprotein-Associated Optic Neuritis in a Patient With Systemic Myasthenia Gravis.", "abstract": "", "authors": ["Fijardo Mackenzie", "Xie Jim S", "Rotstein Dalia", "Margolin Edward"], "journal": "The Canadian journal of neurological sciences. Le journal canadien des sciences neurologiques", "entry_date": "2025/10/16 05:12", "pub_date": "2025-10-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41099132/", "pub_types": ["Journal Article"], "affiliations": ["University of Toronto, Faculty of Medicine, Toronto, ON, Canada."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41098798", "title": "Pembrolizumab-induced myasthenia gravis: A rare immune-related adverse event in a patient treated for bladder cancer.", "abstract": "Immune checkpoint inhibitors (ICIs) targeting programmed cell death protein 1, such as pembrolizumab, are widely used for the treatment of various malignancies. These therapies, while typically less toxic than traditional chemotherapy, are associated with immune related adverse events which may affect the gastrointestinal tract, lungs, skin, liver, and less commonly the nervous system. Neurologic irAE are rare but carry high mortality rates. We present a case of seronegative myasthenia gravis in a patient treated with pembrolizumab for refractory bladder cancer. This case highlights the importance of early recognition of neurologic manifestations of irAE in patients receiving therapy with ICIs.", "authors": ["Bedore Stacy R", "Shin Danielle H", "van der Eerden Joshua", "Town Morgan V", "Terris Martha K"], "journal": "Urology case reports", "entry_date": "2025/10/16 04:46", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41098798/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Medical College of Georgia, 1120 15th St, Augusta, GA 30912, United States of America."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.4, "journal_quartile": "4区"}, {"pmid": "41098393", "title": "Pathogenesis of thymoma-associated myasthenia gravis: a narrative review.", "abstract": "BACKGROUND AND OBJECTIVE: Patients with thymomas often develop autoimmune neuromuscular diseases, including myasthenia gravis (MG). Autoantigen expression in thymomas plays an important role in disease pathogenesis. Since thymomas are mainly composed of the cortex, with few medullae, MG may be caused by immature thymoma-derived T cells that fail to undergo negative selection and have not yet acquired sufficient self-tolerance. However, due to the complexity and diversity of thymoma cell populations, a comprehensive understanding of the mechanisms underlying its association with MG has yet to be achieved. The purpose of this article is to provide an overview of the normal thymus function and the pathogenesis of thymoma associated with MG and other autoimmune diseases, with the aim to highlight newly identified mechanisms that may offer novel insights into their development.\nMETHODS: To address the lack of information regarding the MG-thymoma association, we applied a bioinformatics approach to thymomas.\nKEY CONTENT AND FINDINGS: By analyzing bulk RNA-sequencing (RNA-seq) and single-cell RNA-seq (scRNA-seq) data from thymomas, we identified neuromuscular medullary thymic epithelial cells (nmTECs) as neuromuscular antigen-expressing cell populations. Medullary structures, although much smaller than those of the normal thymus, are present in thymomas with MG and MG-susceptible genes are clustered. We observed spatial nmTEC colocalization and an immune niche, inferring an interaction and suggesting a pathological role of nmTECs in MG.\nCONCLUSIONS: After providing an up-to-date overview of normal thymus function, along with data and hypotheses regarding the association between thymoma and MG, we present bioinformatic findings regarding the thymoma.", "authors": ["Okuno Tatsusada", "Koizumi Naoshi", "Yasumizu Yoshiaki"], "journal": "Mediastinum (Hong Kong, China)", "entry_date": "2025/10/16 04:38", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41098393/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Graduate School of Medicine, University of Osaka, Suita, Osaka, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41093554", "title": "Microscopic Polyangiitis with Alveolar Hemorrhage Complicated by Myasthenia Gravis.", "abstract": "This case report describes the case of an 80-year-old man with ocular myasthenia gravis, who developed microscopic polyangiitis with alveolar hemorrhage. This rare co-occurrence of the two autoimmune diseases presented significant diagnostic and therapeutic challenges. Despite the initial improvement with glucocorticoids, the patient relapsed and died before receiving additional immunosuppressive agents. Thus, the balance between therapeutic efficacy and adverse effects, such as infections, must be carefully considered, especially in elderly patients. This case underscores the importance of recognizing rare overlaps of autoimmune diseases and highlights the need for individualized treatment strategies, especially in older individuals, in whom aggressive immunosuppression carries additional risks.", "authors": ["Suzuki Eiji", "Sumichika Yuya", "Imaizumi Mai", "Kanno Takashi"], "journal": "Internal medicine (Tokyo, Japan)", "entry_date": "2025/10/15 21:13", "pub_date": "2026-06-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41093554/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Rheumatology, Ohta Nishinouchi Hospital, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.1, "journal_quartile": "4区"}, {"pmid": "41090479", "title": "Immunoglobulin for myasthenia gravis.", "abstract": "RATIONALE: Immunoglobulin has long been used to treat neuroimmunological conditions, including myasthenia gravis (MG). However, the evidence supporting its benefits in MG remains uncertain.\nOBJECTIVES: To assess the benefits and harms of immunoglobulin in people with generalized MG. Specifically, we aimed to compare 1) intravenous immunoglobulin (IVIg) versus subcutaneous immunoglobulin (SCIg), and 2) immunoglobulin administered via either route (irrespective of treatment duration, dosage, and regimen) versus no treatment, placebo, plasma exchange (PLEX), corticosteroids, acetylcholinesterase inhibitors, or any other treatment.\nSEARCH METHODS: On 17 September 2024, we searched the Cochrane Neuromuscular's Specialised Register, Cochrane Central Register of Controlled Trials, MEDLINE, Embase, and ClinicalTrials.gov. We also searched the World Health Organization's International Clinical Trials Registry Platform to May 2022. Additionally, we reviewed the references of included studies.\nELIGIBILITY CRITERIA: We included parallel and cross-over randomized controlled trials (RCTs) comparing IVIg with SCIg or immunoglobulin versus other interventions in participants with acute exacerbations or chronic active MG, undergoing steroid tapering, or preparing for surgery. We excluded trials without a comparison group.\nOUTCOMES: We measured critical outcomes over three time intervals: short-term (up to two weeks), medium-term (2 to 24 weeks), and long-term (beyond 24 weeks). They included physician-evaluated change in severity of symptoms and signs, measured by scales such as the Quantitative Myasthenia Gravis (QMG) score and the Myasthenia Muscle Score (MMS); patient-reported change in functional capacity, measured by scales such as the MG Activities of Daily Living (MG-ADL) scale, the MG Quality of Life (MG-QOL), and MG-QOL15 questionnaire, and change in measures that incorporate both physician-evaluated and patient-reported items, such as the Myasthenia Gravis Composite (MGC) scale. Prioritized important outcomes were length of hospitalization, incidence of MG-related hospitalizations, and specific treatment-related adverse events.\nRISK OF BIAS: We used the risk of bias 2 (RoB 2) tool (and its extension for cross-over trials) to assess the risk of bias.\nSYNTHESIS METHODS: We conducted meta-analyses for each of the possible comparisons using a random-effects model when different scales were used for the measurement of the same outcome or when studies in an analysis included different types of participants. We calculated mean differences (MDs) or standardized mean differences (SMDs) for continuous outcomes, and risk differences (RDs) for dichotomous outcomes, with 95% confidence intervals (CIs). We used GRADE to assess the certainty of evidence.\nINCLUDED STUDIES: We included 12 RCTs (11 with usable data; 515 participants) conducted between 1997 and 2025 in Europe, North America, and Asia. All studies assessed IVIg; none assessed SCIg. Comparators included PLEX (six trials), placebo (five trials), and corticosteroids (one trial).\nSYNTHESIS OF RESULTS: IVIg versus placebo IVIg did not differ from placebo in physician-evaluated medium-term change in symptom severity. However, a sensitivity analysis excluding one high-risk study showed a small improvement in the QMG score with IVIg (MD -1.86, 95% CI -3.44 to -0.29; I2 = 0%; 2 studies, 113 participants; low-certainty evidence), though this did not reach the commonly used threshold for clinical significance. Similarly, we found no difference in patient-reported medium-term change in functional capacity, but a sensitivity analysis excluding one high-risk study showed improvement in the MG-QOL15 score with IVIg (MD -5.50, 95% CI -9.80 to -1.20; 1 study, 62 participants; low-certainty evidence). We found no differences in medium-term change in the MGC scale, length of hospitalization, or MG-related hospitalizations. IVIg increased the incidence of headache compared to placebo (RD 0.32, 95% CI 0.03 to 0.61; I2 = 59%; 4 studies, 188 participants; moderate-certainty evidence) with a number needed to treat for an additional harmful outcome (NNTH) of three people. No data were available for hypotension requiring vascular expansion. Immunoglobulin versus PLEX IVIg and PLEX did not differ in physician-evaluated short-term change in symptom severity. However, a sensitivity analysis excluding high-risk studies showed a smaller improvement in the QMG score with IVIg compared to PLEX (MD 2.92, 95% CI 0.42 to 5.41; I2 = 81%; 2 studies, 124 participants; very low-certainty evidence). We found no difference in patient-reported short-term change in functional capacity. We found no data for combined measures (e.g. MGC). IVIg was associated with longer hospital stays than PLEX (MD 2.90, 95% CI 2.58 to 3.22; 1 study, 40 participants; low-certainty evidence), while no MG-related hospitalizations occurred. No significant differences were found in adverse events, including hypotension requiring vascular expansion, and headache. Immunoglobulin versus corticosteroids We observed no difference between IVIg and corticosteroids in physician-evaluated short-term change in symptom severity, assessed with the QMG score (MD -0.66, 95% CI -2.58 to 1.26; 1 study, 33 participants; very low-certainty evidence). No data were available for patient-reported changes in functional capacity, combined measures, length of hospitalization, MG-related hospitalizations, or adverse events. Certainty of evidence The certainty of evidence was often low or very low, primarily due to study limitations (risk of bias), small sample sizes, inconsistency, and imprecision. No eligible studies compared IVIg with SCIg or with acetylcholinesterase inhibitors.\nAUTHORS' CONCLUSIONS: We found low-certainty evidence that IVIg may improve symptoms and functional capacity in the medium term in people with MG, compared to placebo, though the effects did not reach commonly used thresholds for clinical significance and were based on sensitivity analyses. Based on moderate-certainty evidence, IVIg probably also increases the incidence of headache. Based on very low to low-certainty evidence, IVIg may be less beneficial than PLEX for short-term improvement in symptoms and may prolong hospital stay, though we found no differences in adverse events. No firm conclusions can be drawn for the comparison of IVIg with corticosteroids. Overall, due to the low or very low certainty of evidence, high-quality trials are needed, including evaluations of SCIg and newer therapies.\nFUNDING: This Cochrane review was supported in part by the Intramural Research Program of the National Institute on Aging, National Institutes of Health (NIH), and by the National Institute for Health Research (NIHR) via Cochrane Infrastructure funding to Cochrane Neuromuscular.\nREGISTRATION: Protocol (2020) available via doi.org/10.1002/14651858.CD013801.", "authors": ["Manolopoulos Apostolos", "Alzuabi Muayad", "Elmashala Amjad", "Cashwell Jennifer", "Murad M Hassan", "Naddaf Elie"], "journal": "The Cochrane database of systematic reviews", "entry_date": "2025/10/15 06:43", "pub_date": "2025-10-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41090479/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Laboratory of Clinical Investigation, Intramural Research Program, National Institute on Aging, NIH, Baltimore, MD, USA."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 9.4, "journal_quartile": "1区"}, {"pmid": "41087990", "title": "Myasthenia gravis complicated by intestinal pseudo-obstruction: a case report and literature review.", "abstract": "PURPOSE: Myasthenia gravis (MG) is an autoimmune disease characterized by fluctuating weakness of skeletal muscles, usually without involvement of gastrointestinal muscle groups. However, when accompanied by intestinal pseudo-obstruction (IPO), patients may present with gastrointestinal symptoms, complicating prompt diagnosis. We report two new cases of MG complicated by IPO, detailing their clinical course and management.\nMETHODS: A case report and review of the literature.\nRESULTS: We report two new cases of young male MG complicated by IPO. Both patients were admitted with symptoms indicative of intestinal obstruction and achieved clinical remission following thymectomy. We identified a total of 14 cases of MG complicated by IPO, including 12 previously reported in the literature. Of these cases, IPO was the initial clinical manifestation in 64.3% (9/14). 12 (85.7%) of them were correlated with thymoma, and only one patient did not undergo thymectomy. Ten patients showed clinical improvement, while the remaining four succumbed to the disease progression or complications.\nCONCLUSIONS: It is challenging to diagnose MG complicated by IPO at the initial presentation. We should be careful to avoid unnecessary colectomies in the treatment process.", "authors": ["Lin Yangtao", "Zhang Chaoyue", "Zhong Zhishan", "Deng Yufei", "Luo Haocheng", "Yang Xiaojun", "Jiang Qilong"], "journal": "BMC neurology", "entry_date": "2025/10/14 23:54", "pub_date": "2025-10-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41087990/", "pub_types": ["Journal Article"], "affiliations": ["Guangzhou University of Chinese Medicine, Dayuan at No. 14 Airport Road, Guangdong, 510405, Guangzhou, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "41085805", "title": "Bibliometric analysis reveals global thymoma research trends collaborations and emerging frontiers from 2010 to 2024.", "abstract": "OBJECTIVE: To map global thymoma research trends (2010-2024) through bibliometric analysis.\nMETHODS: Analysis of 2,078 publications from Web of Science/PubMed using Bibliometrix, VOSviewer, and CiteSpace. Metrics included productivity (countries/institutions/authors), thematic evolution, collaboration networks, and citation impact.\nRESULTS: The analysis reveals a steady increase (6.2% CAGR) in the volume of thymoma-related publications over the past decade. Key journals included Journal of Thoracic Oncology and Annals of Thoracic Surgery. Prolific authors like Marx Alexander (25 publications) and institutions such as Fudan University (67 publications) dominated the field. Keyword analysis revealed sustained focus on \"myasthenia gravis,\" \"surgery,\" and \"thymectomy,\" with emerging interest in \"immunotherapy\" and \"molecular biology.\" High-impact articles addressed autoimmune associations and novel therapies (e.g., sunitinib). Global collaboration networks highlighted strong partnerships among the U.S., Europe, and Asia, though logistical and policy barriers may have limited China's broader international engagement.\nCONCLUSION: Thymoma research has evolved toward molecular and therapeutic innovation, emphasizing immunotherapy and precision medicine. Despite growth, geographical disparities and understudied areas (e.g., long-term outcomes) persist. Future efforts should prioritize multidisciplinary collaboration, biomarker discovery, and multicenter trials to optimize clinical strategies.", "authors": ["Yu Zhen", "Li Yu-Han", "Han Qi", "Wang Xin-Peng", "Yu Xin-Tao", "Cui Jian", "Gao Xiang", "Yang Xing-Guo", "Yu Lei"], "journal": "Discover oncology", "entry_date": "2025/10/14 11:19", "pub_date": "2025-10-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41085805/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Beijing Tongren Hospital, Capital Medical University, No.2 Xihuan Road, Daxing District, Beijing, 100176, China. dr.zhenyu@hotmail.com."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "41085161", "title": "Nano Vitamin A Enhances Muscle Function and Exercise Performance in Mice Through Modulated Fiber-Type Transition.", "abstract": "The global increase in muscle weakness poses a critical public health concern. Nutritional interventions that improve muscular function hold promise as a therapeutic potential. Vitamin A (VA) and its active metabolites have been implicated in muscle development and the transformation of muscle fiber types. However, conventional VA formulations are restricted by poor stability and low bioavailability. In this study, a stable Nano VA was utilized to systematically evaluate its effects on muscle development and exercise performance in mice, as well as to explore its underlying mechanisms. A total of 44 male C57BL/6J mice were randomly divided into four groups: (i) normal control (NC), (ii) 5 mg/kg Nano VA (5 NVA), (iii) 10 mg/kg Nano VA (10 NVA), and (iv) 10 mg/kg VA (10 VA). The 10 NVA group demonstrated significantly improved muscle strength and swimming endurance, compared with the NC group. Further examination suggested a significant increase in myofiber diameter, cross-sectional area, and the content of fast-twitch fibers. Additionally, Nano VA treatment improved glucose tolerance and insulin sensitivity. To elucidate the mechanism by which Nano VA enhances muscle locomotor ability, transcriptomics and metabolomics data identified 111 differentially expressed genes and 253 differential metabolites. Of these, Angptl4, Ppp1r3a, and Cyp26b1 were identified as candidate regulators of muscle development and myofiber type transformation. In conclusion, Nano VA regulates muscle development and promotes muscle fiber type conversion, thus improving muscle strength and endurance in mice. Moreover, Nano VA facilitates mitigating and improving myasthenia gravis-related conditions.", "authors": ["Li Ruotong", "Zhao Wenye", "Zhang Jiaxin", "Chen Jiayi", "Cai Wenrun", "Rong Xiaoyin", "Yang Yang", "Li Bugao", "Li Meng", "Guo Xiaohong"], "journal": "FASEB journal : official publication of the Federation of American Societies for Experimental Biology", "entry_date": "2025/10/14 08:24", "pub_date": "2025-10-31", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41085161/", "pub_types": ["Journal Article"], "affiliations": ["College of Animal Science, Shanxi Agricultural University, Taigu, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV"}, {"pmid": "41084449", "title": "[Mechanism of Jianpi Bushen Yiqi Decoction in promoting AChR clustering and improving neuromuscular junction function in EAMG mice based on Agrin/LRP4/MuSK signaling pathway].", "abstract": "This study investigated the mechanism by which Jianpi Bushen Yiqi Decoction promotes acetylcholine receptor(AChR) clustering in myasthenia gravis through the Agrin/low-density lipoprotein receptor-related protein 4(LRP4)/muscle-specific receptor tyrosine kinases(MuSK) signaling pathway. A total of 114 female C57BL/6J mice were divided into the normal group, modeling group, and solvent control group. The normal group and the solvent control group were immunized with phosphate-buffered saline(PBS), while the modeling group was established as an experimental autoimmune myasthenia gravis(EAMG) model using the murine-derived AChR-α subunit R97-116 peptide fragment. After successful modeling, the mice were randomly assigned to the model group, the low-, medium-, and high-dose Jianpi Bushen Yiqi Decoction groups, and the prednisone group. After four weeks of continuous treatment, muscle strength was assessed using Lennon scores and grip strength tests. Immunofluorescence staining was conducted on differentiated C2C12 myotubes incubated with a drug-containing serum to observe the number of AChR clusters. The integrity of AChR on myofilaments in mouse gastrocnemius muscles was further assessed by immunofluorescence staining. Hematoxylin-Eosin(HE)staining was applied to examine pathological changes in the gastrocnemius muscles of EAMG mice treated with Jianpi Bushen Yiqi Decoction. Western blot was utilized to detect the expression of key proteins in the Agrin/LRP4/MuSK signaling pathway in both C2C12 myotubes and mouse gastrocnemius muscles. The results demonstrated that compared to the model group, the prednisone group exhibited a significant decrease in the body weights of mice, whereas no significant differences in the body weights of mice were observed among the low-, medium-, and high-dose Jianpi Bushen Yiqi Decoction groups. All treatment groups showed significantly improved grip strength and Lennon scores. Additionally, the formula promoted AChR clustering on myotubes and enhanced AChR integrity in gastrocnemius myofilaments and reduced inflammatory infiltration between muscle tissue and fibrous hyperplasia. Furthermore, Jianpi Bushen Yiqi Decoction upregulated the protein expression of AChRα1, Agrin, and p-MuSK in C2C12 myotubes and increased the protein expression of AChRα1, Agrin, MuSK, p-MuSK, LRP4, and docking protein 7(Dok-7)in gastrocnemius tissue. In conclusion, Jianpi Bushen Yiqi Decoction may promote AChR clustering by targeting key proteins in the Agrin/LRP4/MuSK signaling pathway, thereby improving neuromuscular junction function and enhancing muscle strength.", "authors": ["Wang Jia-Hui", "Liu Ru-Ge", "Liu Han-Bin", "Wei Jia-Hao", "Zhang Jie", "Liu Xue-Ying", "Gao Feng", "Yang Jun-Hong"], "journal": "Zhongguo Zhong yao za zhi = Zhongguo zhongyao zazhi = China journal of Chinese materia medica", "entry_date": "2025/10/14 03:53", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41084449/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["the First Clinical Medical College of Henan University of Chinese Medicine Zhengzhou 450046, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null}, {"pmid": "41084336", "title": "Dynamic Changes in Peripheral Immune Cells During Efgartigimod Treatment in Naive Generalized Myasthenia Gravis.", "abstract": "BACKGROUND: Efgartigimod is a neonatal Fc receptor (FcRn) antagonist that reduces pathogenic IgG and improves clinical symptoms in generalized myasthenia gravis (gMG). However, its immunomodulatory effects on innate and adaptive immune cells beyond IgG depletion are rarely reported.\nOBJECTIVE: This study aimed to investigate clinical and immunological responses during the initial treatment cycle of efgartigimod in naive acetylcholine receptor antibody-positive (AChR-Ab+) gMG patients, with a focus on peripheral immune cell dynamics.\nMETHODS: We conducted a longitudinal study between October 23, 2023, and December 10, 2024, based on the database of the Clinical Cohort Study of Myasthenia Gravis at Xuanwu Hospital, Capital Medical University. Seventeen naive AChR-Ab+ gMG patients were enrolled after applying strict inclusion and exclusion criteria and received a four-dose regimen of efgartigimod. Clinical efficacy was evaluated using Myasthenia Gravis Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG) scores. Serum total IgG and AChR antibody levels were measured. Peripheral immune cell profiling included leukocytes, neutrophils, monocytes, platelets, and natural killer (NK) cells, as well as T and B cell subsets analyzed by flow cytometry. Longitudinal changes were assessed using linear mixed-effects models.\nRESULTS: All patients achieved clinical improvement, accompanied by significant reductions in serum total IgG and AChR antibody levels. Neutrophil and leukocyte counts progressively increased and peaked at Week 3 (p < 0.05), whereas monocyte and platelet counts remained relatively stable throughout all visits. CD4+ and CD8+ T cells decreased transiently at Week 2 and partially recovered by Week 3 (p = 0.091 and p = 0.005). The CD4/CD8 ratio remained stable. NK cells showed a temporary decrease at Week 2 with a borderline significant time effect (p = 0.050), followed by partial recovery. Plasmablast proportions significantly increased at Week 2 (p < 0.05), with a parallel trend in memory B cells. A transient increase in regulatory T cells was observed at Week 1 (p < 0.05). Similar immune changes were observed in sensitivity analysis without corticosteroid use.\nCONCLUSION: This study provides the first longitudinal evidence of dynamic changes in innate and adaptive immune compartments during efgartigimod therapy in naive gMG patients. Beyond IgG clearance, efgartigimod might exert targeted immunoregulatory effects on neutrophils and lymphocyte subsets. These findings offer new insights into the broader immunological impact of FcRn-targeted therapy in gMG and underscore the need for further mechanistic and functional studies.", "authors": ["Wang Yaye", "Zhu Wenjia", "Liu Qing", "Wen Xinmei", "Xie Nairong", "Liu Haoran", "Geng Zhangyan", "Jiang Yuting", "Di Li", "Wang Min", "Lu Yan", "Duo Jianying", "Huang Yue", "Qian Yu", "Liu Qinyao", "Lv Congwen", "Da Yuwei"], "journal": "CNS neuroscience & therapeutics", "entry_date": "2025/10/14 02:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41084336/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xuanwu Hospital, Capital Medical University, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.0, "journal_quartile": "2区"}, {"pmid": "41084143", "title": "Decreased Serum 5-HT: Clinical Correlates and Regulatory Role in NMJ of MG.", "abstract": "OBJECTIVE: Although 5-Hydroxytryptamine (5-HT) indirectly stimulates muscle contraction and participates in regulating Acetylcholine receptor (AChR) cluster homeostasis in cellular, animal, and clinical studies, evidence regarding its potential to modulate muscle contraction in myasthenia gravis (MG) remains limited. We aim to determine the levels of 5-HT in MG and investigate its potential role as a regulatory neurotransmitter in promoting muscle contraction.\nMETHODS: We collected serum from 109 patients with MG and 110 healthy volunteers, and recorded clinical variables, including myasthenia gravis classification (MGFA), quantitative myasthenia gravis score (QMG), and serological examination. The effects of 5-HT on the neuromuscular junction (NMJ) were further identified using cellular and molecular experiments.\nRESULTS: In this study, we observed that serum 5-HT levels decrease in patients with MG (p < 0.0001) compared with disease-free control. The thymoma-associated complications alleviated this reduction (p < 0.0001). Our functional studies showed that 5-HT promotes the development of motor (cholinergic) neuron-like axons and increases intracellular calcium peaks, which is proportional to the amount of neurotransmitter released (p < 0.0001). AChR-autoantibody treatment increases the expression of 5-HT2R mRNA in muscle tube cells (p < 0.001), and the downstream signaling pathway of 5-HT2R is involved in the regulation of AChR cluster homeostasis.\nINTERPRETATION: This first report of clinical characteristics and serum 5-HT levels from a cross-sectional cohort study on MG suggests that 5-HT plays a critical role in maintaining NMJ homeostasis. Additional cross-sectional data on more MG phenotypes and longitudinal monitoring data are needed to explore the role of 5-HT in the pathophysiological mechanisms of MG.", "authors": ["Shen Xinru", "Zhang Jing", "Zhou Xinyue", "Yu Xiaoxiao", "Shang Haodong", "Chen Shufan", "Zhen Lulu", "Wu Jinru", "Hu Guanlian", "Zhu Xiaoyan", "Sun Zhan", "Wang Yiren", "Wang Jiahui", "Lv Jie", "Zhao Xue", "Zhang Yingna", "Guo Wei", "Peng Ying", "Gao Feng"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/10/14 00:37", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41084143/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "41082365", "title": "Superficial Parasternal Intercostal Plane Block for Pain Control Following Thymectomy via Midline Sternotomy: A Case Report.", "abstract": "We report a case of a 53-year-old male with myasthenia gravis who underwent thymectomy via a full-length median sternotomy. To minimize opioid exposure and enhance postoperative recovery, a bilateral ultrasound-guided superficial parasternal intercostal plane (S-PIP) block was administered using 15 mL of 0.25% bupivacaine on each side before incision. Postoperative analgesia was maintained with paracetamol and dexketoprofen. No systemic opioids were required, and pain scores remained below 4 during the first 24 hours. The patient recovered uneventfully in the postoperative period. This case highlights the utility of S-PIP block as a safe and opioid-sparing technique in high-risk patients undergoing sternotomy.", "authors": ["Baran Onur", "Şahin Ayhan", "Arar Cavidan"], "journal": "A&A practice", "entry_date": "2025/10/13 12:32", "pub_date": "2025-10-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41082365/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["From the Department of Anesthesiology and Reanimation, Medical Faculty, Tekirdağ Namik Kemal University, Tekirdağ, Turkey."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": null}, {"pmid": "41080406", "title": "Corrigendum to A multicentre, prospective, double-blind study comparing the accuracy of autoantibody diagnostic assays in myasthenia gravis: the SCREAM study Lancet Reg Health West Pac (2023) 38: 100846.", "abstract": "[This corrects the article DOI: 10.1016/j.lanwpc.2023.100846.].", "authors": ["Li Zhiguo", "Zhang Chao", "Chang Ting", "Zhang Xinghu", "Yang Huan", "Gao Feng", "Feng Jinzhou", "Liu Hongbo", "Chen Sheng", "Wang Lihua", "Yang Chunsheng", "Li Huining", "Pan Yuesong", "Palace Jacqueline", "Shi Fu-Dong"], "journal": "The Lancet regional health. Western Pacific", "entry_date": "2025/10/13 07:34", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41080406/", "pub_types": ["Published Erratum"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 13.0, "journal_quartile": "1区"}, {"pmid": "41080361", "title": "Beyond the Blot: Diagnostic Challenges in Atypical Dermatomyositis With Overlapping Myasthenia Gravis.", "abstract": "Dermatomyositis (DM) is a rare autoimmune inflammatory myopathy characterized by both cutaneous and muscular involvement, often associated with specific autoantibodies and systemic manifestations. This case report presents a young male patient in the United Kingdom with DM, who had a negative myositis blot, panel of autoantibodies, and also had features of myasthenia gravis (MG). Despite trials of multiple immunosuppressive therapies, severe dysphagia persisted. This case underscores the diagnostic complexity of autoimmune neuromuscular disorders and the importance of early consideration of overlap syndromes when clinical features deviate from the classical DM phenotype and bulbar involvement is present. In a healthcare setting where patients may present with diverse and complex autoimmune profiles, this case highlights the need for vigilance and early recognition of rare overlaps such as DM and MG, which is crucial for optimizing patient care.", "authors": ["Iqbal Syed Mashood", "Jayaramu Veena", "Ragasankar Sankar Ram", "Khan Sadiya", "Dubey Vivek"], "journal": "Cureus", "entry_date": "2025/10/13 07:34", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41080361/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Acute Medicine, Queen Elizabeth Hospital Birmingham, Birmingham, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41080268", "title": "The Possible Unveiling of Myasthenia Gravis via Allergy Shots.", "abstract": "This case report discusses subcutaneous allergen immunotherapy (SCIT) for allergic rhinoconjunctivitis and explores whether myasthenia gravis symptoms developed in a patient due to subcutaneous allergen immunotherapy treatment. SCIT is known to induce immune tolerance through the generation of allergen-specific regulatory T and B cells, increased allergen-specific IgG4, and suppression of effector cell responses, resulting in sustained clinical benefit for allergic disease. Although SCIT is considered safe and is not associated with an increased risk of autoimmune disease in large population studies, rare case reports have raised concerns about its potential to trigger autoimmune conditions. The most common triggers for autoimmune diseases, including myasthenia gravis, remain unclear, but allergic diseases themselves may confer an increased risk. This case report highlights the need for further research into the immunological mechanisms and potential triggers of autoimmunity in the context of allergen immunotherapy.", "authors": ["Thakor Philipp Ami", "Anderson Lorraine"], "journal": "Cureus", "entry_date": "2025/10/13 07:33", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41080268/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Allergy and Immunology, University of California Los Angeles, Los Angeles, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41079342", "title": "Effects of respiratory muscle training on respiratory function and functional outcomes in patients with myasthenia gravis: a systematic review.", "abstract": "BACKGROUND: Respiratory muscle training is a structured intervention designed to enhance respiratory muscle function, but robust evidence on its effects in myasthenia gravis remains limited. This systematic review evaluates the impact of respiratory muscle training on respiratory function and functional outcomes in patients with myasthenia gravis.\nMETHODS: A comprehensive search of six databases was conducted without date restrictions until May 1, 2025, to identify studies meeting inclusion criteria: (1) myasthenia gravis patients aged ≥18 years, (2) respiratory muscle training involving inspiratory and expiratory muscle training, (3) outcomes on respiratory muscle strength, respiratory muscle endurance, pulmonary function tests, and functional outcome, (4) study designs like randomised controlled trials (RCTs), cohort studies, case-control trials, and quasi-experimental studies. Two reviewers independently screened studies, extracted data, and assessed methodological quality and evidence level using appropriate tools. Due to limited RCTs and heterogeneity in participants, interventions, and outcomes, a descriptive synthesis was performed.\nRESULTS: Seven studies involving 223 participants (99 males and 124 females) with a mean age of 57.5 years were systematically reviewed, including two RCTs, one quasi-controlled study, one case-control study, and three cohort studies, all of which demonstrated moderate-to-high methodological quality (evidence levels 2-4). Respiratory muscle training programs involved inspiratory-expiratory training and inspiratory-only training, with parameters varying widely: intensity ranged from 15 to 75% of maximal respiratory pressures or 50 to 60% of maximal voluntary ventilation, frequency spanned from 3 to 10 sessions weekly, sessions lasted 10 to 30 min, and total intervention periods extended from 4 weeks to 12 months. Devices included threshold and variable resistance trainers, all applied under supervised conditions alongside conventional myasthenia gravis medications. All five studies evaluating respiratory muscle endurance and functional outcomes reported statistically significant enhancements (p < 0.05). Respiratory muscle strength and pulmonary function results were inconsistent. Maximal inspiratory pressure improved significantly in two of six studies (p < 0.01), while maximal expiratory pressure improved in two of three studies (p < 0.05). Among six studies measuring forced expiratory volume in 1 s, three measuring forced vital capacity, and three measuring peak expiratory flow, only two studies reported significant improvements in forced expiratory volume in 1 s and forced vital capacity (p < 0.05), while others found no effects. Adverse events reported in three studies were attributed to comorbidities rather than interventions.\nCONCLUSION: Respiratory muscle training can enhance respiratory muscle endurance and functional outcomes in patients with myasthenia gravis. However, evidence regarding its effects on respiratory muscle strength and pulmonary function remains inconsistent and is constrained by methodological limitations. Higher-quality trials are warranted to validate these findings and optimize intervention protocols.\nSYSTEMATIC REVIEW REGISTRATION: CRD42024516112.", "authors": ["Bi Zi-Ting", "Xiao Jing-Hua", "Wei Jing-Xue", "Huang Lang", "Li Ying-Dong", "Zhang Yue-Mi", "Huang Jian", "Luo Chao-Song", "Zhang Jia-Mei", "Zhang Yun-Shan"], "journal": "Frontiers in neurology", "entry_date": "2025/10/13 07:25", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41079342/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Department of Rehabilitation Medicine, The First Affiliated Hospital of Guangxi Medical University, Nanning, China."], "china_related": true, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41078519", "title": "Gut microbiota analysis reveals microbial signature for multi-autoimmune diseases based on machine learning model.", "abstract": "INTRODUCTION: Human microbiota is a major factor contributing to the immune system, offering an opportunity to develop non-invasive methods for disease diagnosis. In some research on Autoimmune Diseases (AIDs), gut microbiota variation has been observed. However, there remains a paucity of research that explores the potential of gut microbiota as a microbial signature for the classification and diagnosis of multi-AIDs.\nMETHODS: In this study, we analyzed 1,954 gut microbiota sequencing datasets from public databases collected from 1,043 patients with 10 AIDs to identify common or unique microbial signatures for AIDs through differential abundance testing and machine learning techniques. We evaluated five popular algorithms: Random Forest (RF), Support Vector Machine (SVM), K-Nearest Neighbors (KNN), Multilayer Perceptron (MLP), and eXtreme Gradient Boosting (XGBoost) models. Five-fold cross-validation and grid search were used to select the model parameters.\nRESULTS: After comparing the performance of five models, the XGBoost model showed superior performance and achieved an area under the receiver operating characteristic curve (AUROC) ranging from 0.75 to 0.99 when predicting different diseases in the test set. At a specificity of 0.7 to 0.96, the sensitivity ranged from 0.66 to 1. By correlating the top 77 microbiota genera with the disease phenotypes, 126 significant associations were identified [false discovery rate (FDR) < 0.05]. We improved the detection accuracy and disease specificity for AIDs and revealed microbiota features specific to 10 different AIDs. Moreover, we found changing trends in shared microbiota features across some AID phenotypes, such as Crohn's Disease (CD) and Ulcerative Colitis (UC). At the same time, opposite changing trends were observed in the shared microbial signatures, such as Psoriasis and Myasthenia Gravis (MG). These results suggest that specific gut microbiota genera may affect the host immunity and induce different AID phenotypes.\nDISCUSSION: This research holds potential for clinical application in the auxiliary diagnostic evaluation and monitoring of treatment responses. Simultaneously, it provides important clues for research on the characteristics of the intestinal immune microenvironment for different AIDs.", "authors": ["An Tianfeng", "Zhang Shuya", "Li Jinjin", "Wang Hui", "Chen Li", "Shi Yiran", "Wang Jingyi", "Han Sirui", "Wang Ruoxi", "Wang Linyuan", "Huan Zijing", "Yang Ruiqi", "Hao Desong", "Liu Yanfang", "Liu Xuehua", "Yuan Chao"], "journal": "Frontiers in microbiology", "entry_date": "2025/10/13 07:15", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41078519/", "pub_types": ["Journal Article"], "affiliations": ["The School of Public Health, Tianjin Medical University, Tianjin, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.5, "journal_quartile": "2区"}, {"pmid": "41078500", "title": "Case Report: Dropped head syndrome as a main clinical sign of suspected myasthenia gravis in two dogs.", "abstract": "Drop head syndrome (DHS), characterized by pronounced cervical ventroflexion, is a clinical syndrome that can be found associated with neuromuscular disorders, particularly myasthenia gravis. In this case series, we describe two dogs, an 8-year-old Basset Hound and a 3-year-old Zwergpinscher, presenting with DHS as the main clinical sign. In both cases, a presumptive diagnosis of myasthenia gravis was made and were empirically treated with pyridostigmine. Telephone follow-ups at 6 and 4 months after diagnosis, respectively, were consistent with clinical remission. These cases highlight the diagnostic challenges of DHS, emphasizing the need for thorough evaluation to exclude numerous differential diagnoses. In cases where myasthenia gravis is strongly suspected despite negative tests, trial treatment with anti-cholinesterase drugs may be considered, with caution to avoid potential side effects.", "authors": ["Reyes Henry Mendo", "Galli Greta", "Fiorentino Erica", "Gardini Anna", "Bravaccini Beatrice", "Menchetti Marika"], "journal": "Frontiers in veterinary science", "entry_date": "2025/10/13 07:15", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41078500/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["San Marco Veterinary Clinic and Laboratory, Neurology and Neurosurgery Division, Veggiano, Padua, Italy."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "2区"}, {"pmid": "41074934", "title": "Self-administration of rozanolixizumab via manual push and infusion pump methods in patients with generalised myasthenia gravis: a randomised, phase 3, open-label, crossover study.", "abstract": "BACKGROUND: The phase 3, open-label, randomised, crossover MG0020 study investigated rozanolixizumab self-administration, efficacy, and safety in patients with generalised myasthenia gravis (gMG) using infusion pump and manual push methods.\nMETHODS: Adults with gMG received once-weekly rozanolixizumab for 18 weeks, comprising a 6-week Training Period and two 6-week Self-Administration Periods where patients were randomised 1:1 to Sequence 1 (infusion pump then manual push) or Sequence 2 (manual push then infusion pump). The primary endpoint was successful rozanolixizumab self-administration (choosing correct infusion site, administering subcutaneously, delivering intended dose), evaluated by a healthcare professional (HCP) at weeks 12 and 18. Secondary endpoints included treatment-emergent adverse events (TEAEs). Additional endpoints included change from baseline in total immunoglobulin G (IgG) and Myasthenia Gravis Activities of Daily Living (MG-ADL) score, and patients' administration method preference.\nRESULTS: Sixty-two patients received treatment; 55 were randomised (Sequence 1: n = 28; Sequence 2: n = 27). The self-administration success rate was 100% with both methods. Decreases from baseline in IgG and MG-ADL score were maintained during self-administration with both methods. TEAEs occurred in 47/62 (75.8%) patients; most events (161/165 [97.6%]) were mild or moderate. Incidence was comparable for both methods. Most patients (35/55 [63.6%]) preferred self-administration to HCP administration (5/55 [9.1%]); more preferred manual push (25/55 [45.5%]) to infusion pump (17/55 [30.9%]).\nCONCLUSIONS: All patients successfully self-administered rozanolixizumab; more patients preferred manual push. Efficacy and safety were consistent with the known HCP-administered profile. These results support rozanolixizumab self-administration and manual push administration in patients with gMG.\nTRIAL REGISTRATION: NCT05681715 (registered 4 January 2023).", "authors": ["Bril Vera", "Antozzi Carlo", "Berkowicz Tomasz", "Drużdż Artur", "Gandhi Mehta Rachana K", "Mahuwala Zabeen K", "Zschüntzsch Jana", "Boehnlein Marion", "Kerbusch Virginie", "Lavrov Andreea", "Morris Mark", "Singh Puneet", "Leite M Isabel"], "journal": "Journal of neurology", "entry_date": "2025/10/11 11:03", "pub_date": "2025-10-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41074934/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase III", "Multicenter Study"], "affiliations": ["Ellen and Martin Prosserman Centre for Neuromuscular Diseases, Toronto General Hospital, University of Toronto, Toronto, ON, Canada. vera.bril@utoronto.ca."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "41072489", "title": "DELAYED ONSET OF MYASTHENIA GRAVIS FOLLOWING COLECTOMY FOR ULCERATIVE COLITIS: A CASE STUDY.", "abstract": "The issue of concomitant autoimmune disorders is an acute problem in neurology, with a diversity of conditions co-existing, and hampering diagnosis or prompt therapeutic interventions. We discuss the case of a middle age Caucasian male suffering from ulcerative colitis of a severity warranting surgery and pharmacological therapy, which has been complicated with neurological symptomatology. The co-existence of ulcerative colitis and myasthenia gravis might be a rarity, although the autoimmune background of both occurrences should lead the clinicians to considering such a setting, and treat accordingly both diseases. Unexplained cranial nerve involvement should be regarded as a red flag, necessitating neurological consultancy and appropriate intervention among patients with inflammatory bowel diseases.", "authors": ["Gorica H", "Djamandi P", "Vyshka G"], "journal": "Georgian medical news", "entry_date": "2025/10/10 19:22", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41072489/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["1Service of Neurology, Trauma University Hospital Center of Tirana, Albania."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "41072251", "title": "Comparative analysis of the tumor immune microenvironment between thymoma and thymic carcinoma.", "abstract": "BACKGROUND: Thymic epithelial tumors (TETs) often linked with autoimmune syndromes such as myasthenia gravis (MG), have an underexplored tumor immune microenvironment (TIME), limiting the effective use of Immune Checkpoint Inhibitors. This study aims to address the immunology of TETs, focusing on the prognostic significance of TIME and its association with MG. This study investigates the TIME in TET subtypes, thymic carcinoma (TC) and thymoma, assesses their prognoses, and examines the relationship between thymoma's immune microenvironment and MG.\nMETHODS: This study included 157 patients with TET who underwent surgical resection at Juntendo Hospital between January 2012 and September 2020. Immune cell densities of tissue specimens were analyzed using multiplex fluorescence immunohistochemical staining.\nRESULTS: Thymoma and TC were diagnosed in 145 and 12 patients, respectively. Thymoma types B1 and B2 showed elevated CD4+ and CD8+ T cells, while TC had decreased T cells and increased Foxp3+ T cells. Thymoma with MG had higher CD20+CD79a- cells counts in the stromal area compared to those without MG (p = 0.0165). Elevated CD4+ T cells (p = 0.0310), CD8+ T cells (p = 0.0215), and CD68+ cells (p = 0.0432) in the tumor area were linked to good prognosis, while higher CD20+CD79a- cells in the stromal area indicated poor prognosis (p = 0.0088).\nCONCLUSIONS: Thymomas had a higher prevalence of T cells compared to TC. CD4+ T cells, CD8+ T cells, and CD68+ cells in the tumor area were favorable prognostic markers, while B cells in the stromal area indicated a poor prognosis for thymoma.", "authors": ["Shimamura Shoko Sonobe", "Shukuya Takehito", "Yamashita Makiko", "Ikarashi Daiki", "Hayashi Takuo", "Ohtsu Hiroshi", "Xu Shiting", "Kanamori Koichiro", "Matsunaga Takeshi", "Fukui Mariko", "Hattori Aritoshi", "Takamochi Kazuya", "Suzuki Kenji", "Kitano Shigehisa", "Takahashi Kazuhisa"], "journal": "Lung cancer (Amsterdam, Netherlands)", "entry_date": "2025/10/10 18:08", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41072251/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Division of Clinical Chemotherapy, Cancer Chemotherapy Center, The Cancer Institute of Japanese Foundation for Cancer Research, Tokyo, Japan; Department of Respiratory Medicine, Juntendo University Graduate School of Medicine, Tokyo, Japan."], "china_related": false, "study_types": ["Historical Control"], "evidence_level": "IV", "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "41071972", "title": "Temporal Association Between Dengue Outbreaks and Neurologic Autoimmune Diseases in French Guiana.", "abstract": "BACKGROUND AND OBJECTIVES: Recent decades have witnessed the emergence of arbovirus infections, such as dengue, chikungunya, and Zika viruses, which are responsible for neurologic complications such as Guillain-Barré syndrome (GBS). To date, it has mainly been demonstrated that these neurologic complications occur concomitantly with infectious processes. We hypothesized that arbovirus infections may also influence the incidence of autoimmune diseases of the central or peripheral nervous system.\nMETHODS: This was a retrospective, observational, single-center study conducted between January 2002 and January 2024 at the Cayenne Hospital in French Guiana including patients with autoimmune encephalitis, neuromyelitis optica spectrum disorders (NMOSDs), GBS, chronic inflammatory demyelinating polyneuropathy, and myasthenia gravis (MG). This series was compared with the incidence of arbovirus infections recorded by the French Public Health Agency during the same period.\nRESULTS: We observed a significant correlation between dengue infection and the incidence of NMOSD (Spearman rho = 0.88 [p = 0.03]) and MG (Spearman rho = 0.82 [p = 0.048]). GBS was significantly associated with chikungunya (Spearman rho = 0.97 [p = 0.01]), but not with other arbovirus infections. In addition, the mean estimated incidence of NMOSD was high at 5.08 (95% CI 3.03-7.13) per million person-year, approaching the world's highest incidence observed in the French West Indies.\nDISCUSSION: This study reports the epidemiology of neurologic autoimmune diseases in French Guiana. We found a high incidence of NMOSD, like that reported in the French West Indies. Multicenter studies involving countries in the tropical zone are needed to better elucidate the relationship between dengue outbreak and NMOSD and MG.", "authors": ["Deschamps Nathalie", "Nacher Mathieu", "Chaumont Hugo", "Montcuquet Alexis", "Montagnac Clementine", "Succo Tiphanie", "Epelboin Loic", "Devos Sophie", "De Toffol Bertrand"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/10/10 16:03", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41071972/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Neurology Department, University Hospital of Guyane, Cayenne, French Guiana."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41066833", "title": "Clarifying the diagnostic utility of decrement patterns in MuSK- and AChR-positive myasthenia gravis.", "abstract": "", "authors": ["Aphale Parth", "Shekhar Himanshu", "Dokania Shashank"], "journal": "Neurophysiologie clinique = Clinical neurophysiology", "entry_date": "2025/10/09 18:00", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41066833/", "pub_types": ["Letter"], "affiliations": ["Dr. D.Y. Patil Vidyapeeth (Deemed to be University), Pimpri, Pune, Maharashtra, India. Electronic address: parth.aphale@dpu.edu.in."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41066347", "title": "Comparative study of Japanese nationwide epidemiological studies of myasthenia gravis using datasets of 2006 and 2018.", "abstract": "OBJECTIVE: This study aimed to identify changes in the clinical presentation and treatment patterns of myasthenia gravis (MG) in Japan by comparing data from nationwide epidemiological surveys conducted in 2006 and 2018.\nMETHODS: We analyzed data from nationwide epidemiological surveys of MG performed across Japan in 2006 (n = 729) and 2018 (n = 1,357). Both surveys adhered to the Survey Manual of Study on Continuous Epidemiological Data Collection of Intractable Diseases established by the Ministry of Health, Labour, and Welfare. We compared the following variables between the two-time points: age of onset, gender distribution, initial symptoms, anti-acetylcholine receptor antibody (AChRAb) status, physiological test results (repetitive nerve stimulation test, edrophonium test), Myasthenia Gravis Foundation of America (MGFA) Clinical Classification, Myasthenia Gravis Activities of Daily Living Profile (MG-ADL) score, and treatment modalities.\nRESULTS: Our analysis revealed a significantly older age of onset in the 2018 cohort compared to 2006. The MGFA Clinical Classification was higher in 2018, and bulbar weakness was more frequently reported as an initial symptom. Conversely, the occurrence of myasthenic crisis and current MG-ADL scores were lower in 2018. Regarding treatment, the utilization of tacrolimus, plasma exchange (PE), and intravenous immunoglobulin (IVIg) significantly increased between 2006 and 2018. In contrast, the rates of thymectomy and both maximum and current oral steroid dosages decreased during this period.\nCONCLUSION: These findings underscore notable shifts in the clinical characteristics and, particularly, the treatment strategies for MG in Japan over the twelve-year interval. This information is crucial for informing future patient care protocols and healthcare policy development in the management of MG. We emphasize the importance of conducting regular nationwide epidemiological surveys to monitor the evolving landscape of MG and its treatment continuously.", "authors": ["Yoshikawa Hiroaki", "Adachi Yumi", "Nakamura Yosikazu", "Kuriyama Nagato", "Murai Hiroyuki", "Nomura Yoshiko", "Sakai Yasunari", "Iwasa Kazuo", "Furukawa Yutaka", "Matsui Makoto", "Kuwabara Satoshi"], "journal": "PloS one", "entry_date": "2025/10/09 13:34", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41066347/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Health Service Center, Kanazawa University, Kanazawa, Ishikawa, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "41063964", "title": "Restoration of skeletal muscle function via mesenchymal stem cells: mechanistic insights and therapeutic advances in myasthenia gravis.", "abstract": "Mesenchymal stem cells (MSCs) have demonstrated distinct advantages in skeletal muscle repair owing to their self-renewal capacity, multidirectional differentiation potential, and immunomodulatory functions. As a critical regulator of skeletal muscle regeneration, MSCs have been shown to ameliorate skeletal muscle injury induced by factors such as wasting and metabolic disorders through the activation of satellite cell function, inhibition of myofiber atrophy, and regulation of protein metabolic balance. In the treatment of myasthenia gravis (MG), the therapeutic effects of MSCs are exerted through dual mechanisms: first, autoantibody production is reduced via immunomodulation, thereby alleviating immune-mediated attacks at neuromuscular junctions; second, secondary muscle atrophy is delayed by preserving the integrity of neuromuscular signaling. Notably, MSC function is closely associated with acetylcholine metabolism, neuromuscular junction stability, and the aging microenvironment, in which aging-induced MSC decline may exacerbate intramuscular fat infiltration and impair regenerative capacity. In this paper, the biological properties of mesenchymal stem cells (MSCs) and their regulatory roles in skeletal muscle metabolic and injury-related abnormalities are systematically reviewed, and the fundamental significance of MSCs in skeletal muscle repair and myasthenia gravis (MG) therapy is elucidated through multiple mechanisms, including immunomodulation, neuroprotection, and muscle fiber regeneration. Furthermore, the bottlenecks of clinical translation (including cell source selection, phenotypic stability, and efficacy heterogeneity) are analyzed, and the challenges and optimization strategies for clinical application are discussed, with the aim of providing theoretical references for regenerative medicine research in neuromuscular diseases. However, clinical translation studies have indicated that the actual efficacy of most MSC-based therapies is considerably lower than that observed in in vitro experiments. This discrepancy may be attributed to low post-transplantation cell survival, inadequate homing efficiency, and the adverse influence of a senescent microenvironment that impairs cellular function. It has been indicated by recent studies that strategies, including optimization of cell sources and preparation protocols (e.g., the use of allogeneic MSCs derived from adipose tissue or umbilical cord with standardized production), incorporation of biomaterial supports (such as hydrogel-based encapsulation), and adoption of combination therapies (e.g., co-administration with neurotrophic factors or targeted drugs), can effectively improve the delivery efficiency and therapeutic outcomes of MSCs.", "authors": ["Zhang Xinyi", "Zhang Dongmei", "Zhang Ying", "Wang Jian", "Lu Jing"], "journal": "Frontiers in cell and developmental biology", "entry_date": "2025/10/09 04:57", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41063964/", "pub_types": ["Journal Article", "Review"], "affiliations": ["College of Chinese Medicine, Changchun University of Chinese Medicine, Changchun, Jilin, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "41063857", "title": "Primary Mucoepidermoid Carcinoma of the Masticator Space Presenting with Myasthenia Gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is a neuromuscular autoimmune disorder, commonly associated with thymomas in the context of paraneoplastic syndromes. There are limited reports describing MG in the setting of non-thymic malignancies. Mucoepidermoid carcinoma (MEC), a malignancy of the salivary glands, has been underrecognized as a trigger for paraneoplastic MG. We present a case of a woman with new-onset MG and concurrent MEC of the left masticator space, representing a rare instance of paraneoplastic MG.\nCASE PRESENTATION: A 24-year-old woman presented with a 9-month history of left-sided hemifacial twitching and facial and neck weakness, which progressed to drooling and dysphagia. Examination was notable for bilateral ptosis and fatigable weakness of bulbar and proximal limb muscles. During hospitalization, she developed worsening respiratory insufficiency, necessitating intubation for airway protection. Given concern for myasthenic crisis, empiric plasma exchange was initiated, with significant clinical improvement. Computerized tomography (CT) imaging of the neck revealed a mass within the left masticator space, and core needle biopsy established the diagnosis of MEC. Chest CT demonstrated no evidence of thymoma. Serologic evaluation revealed positive acetylcholine receptor binding and blocking antibodies, confirming a diagnosis of MG.\nCONCLUSION: The temporal relationship between MG symptoms and tumor discovery supports a paraneoplastic etiology in this patient. The occurrence of MG associated with non-thymic malignancies - particularly head and neck cancers - has only been reported twice. In MEC, the tumor may express antigens similar to those found in the neuromuscular junction in a process known as molecular mimicry. The immune system, in its attempt to target the tumor, inadvertently generates autoantibodies against these neuromuscular junction proteins, leading to the symptoms of MG. Whether resection of the tumor will lead to resolution of MG remains uncertain. Although no direct pathogenic link has been established between MEC and MG, this case suggests a need for increased clinical awareness and further investigation.", "authors": ["Boshkos Mitchell", "Rahman Sreya", "Narendra Dharani"], "journal": "Case reports in oncology", "entry_date": "2025/10/09 04:56", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41063857/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Hospital Medicine, MD Anderson Cancer Center Track, Baylor College of Medicine, Houston, TX, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "41063713", "title": "Management of refractory generalized myasthenia gravis with eculizumab during pregnancy and puerperium: a case report.", "abstract": "Myasthenia gravis (MG) mostly affects women of childbearing age. Since the disease course may be affected during pregnancy and postpartum, monitoring and appropriate treatment of MG in pregnant women are crucial. Current treatment options for pregnant women with refractory MG are limited by possible teratogenicity and inadequate lactation data. This case report describes a successful pregnancy in a patient who received eculizumab for refractory generalized MG that was difficult to manage during the pre-pregnancy period. We also report the experience of preterm labour and neonatal MG and the 1-year follow-up of the neonate. Considering the risk-benefit balance, eculizumab can be recommended during pregnancy and postpartum, especially in women with refractory generalized MG.", "authors": ["Karaman Bedriye", "Tunçel Rasim", "Ekmekci Özgül", "Adatepe Nurten Uzun", "Yüceyar Nur"], "journal": "Drugs in context", "entry_date": "2025/10/09 04:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41063713/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Ege University Hospital, Department of Neurology, Izmir, Türkiye."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41061184", "title": "Serum Neurofilament Light Chain Correlates With Clinical Severity and Predicts Mortality in Anti-IgLON5 Disease.", "abstract": "BACKGROUND AND OBJECTIVES: Anti-IgLON5 disease manifests by various neurologic symptoms, the severity of which can be evaluated using the anti-IgLON5 composite score (ICS). This study assessed the correlation of neurofilament light chain (NfL) and glial fibrillary acidic protein (GFAP) with the ICS and investigated these biomarkers as predictors of long-term clinical severity and mortality in anti-IgLON5 disease.\nMETHODS: Patients diagnosed with anti-IgLON5 disease at a national reference center (2016-2024) with available serum and CSF samples were included. NfL and GFAP concentrations were measured in these samples using Simoa assay Neurology 2-Plex B Kit. The severity of symptoms was classified according to the ICS, which was retrospectively evaluated at diagnosis, at last clinical evaluation, and at any other timepoint when samples were collected.\nRESULTS: Thirty patients (60% male, median age 72 years) were included. Serum NfL concentration was significantly correlated with the total ICS (rho = 0.38, p = 0.025) and its partial bulbar score (rho = 0.39, p = 0.020); serum GFAP concentration was significantly correlated only with the bulbar ICS (rho = 0.34, p = 0.044). CSF NfL and GFAP concentrations were not significantly correlated with the total ICS nor any of its partial scores. Anti-IgLON5 antibody CSF titers, but not serum titers, showed a significant inverse correlation with the total ICS (rho = -0.44, p = 0.04). In 26 patients sampled <4 months after diagnosis, neither NfL nor GFAP predicted the total or partial ICS at last clinical evaluation (median 18 months after diagnosis), but serum NfL increased the risk of 1-year mortality independently of age (hazard ratio for each 10 pg/mL increase: 2.05, 95% CI [1.21-3.45], p = 0.007). In patients with bulbar involvement (n = 22), serum NfL concentration was lower than in 10 controls with bulbar amyotrophic lateral sclerosis (median interquartile range [IQR] 26 pg/mL [21-51] vs 158 pg/mL [100-340], p < 0.001) and higher than in 10 controls with bulbar myasthenia gravis (median [IQR] 15 pg/mL [8-26], p = 0.040).\nDISCUSSION: In anti-IgLON5 disease, serum NfL and GFAP are elevated and correlate with the clinical severity, especially of bulbar symptoms. In clinical practice, serum NfL could be useful for disease monitoring and to predict the risk of death.", "authors": ["Farina Antonio", "Villagrán-García Macarena", "Abichou-Klich Amna", "Benaiteau Marie", "Bernard Emilien", "Bouhour Françoise", "Desestret Virginie", "Joubert Bastien", "Picard Geraldine", "Pinto Anne-Laurie", "Pons Lea", "Smolik Krzysztof", "Thobois Stephane", "Trouillet-Assant Sophie", "Honnorat Jerome"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/10/08 16:02", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41061184/", "pub_types": ["Journal Article"], "affiliations": ["French Reference Centre on Paraneoplastic Neurological Syndromes and Autoimmune Encephalitis, Hospices Civils de Lyon, Hôpital Neurologique, Bron, France and MeLiS-UCBL-CNRS UMR 5284, INSERM U1314, University Claude Bernard Lyon 1, Lyon, France."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41059311", "title": "Single-cell RNA sequencing reveals cell immune status and dysregulated monocytes in patients with myasthenia gravis.", "abstract": "OBJECTIVES: As an autoimmune disorder, myasthenia gravis (MG) manifests as an autoimmune attack on postsynaptic neuromuscular junction proteins by pathogenic autoantibodies. This immune attack disrupts neurotransmission, resulting in fatigable skeletal muscle weakness with diurnal fluctuation. However, functional cure biomarkers for patients remain limited.\nMETHODS: Peripheral blood collection was performed at three time points in patients with MG: before treatment (Pre), 1 month after treatment (Post) and functional cure (long-term follow-up, LF). Single-cell RNA sequencing was performed. The clinical examination results were collected and summarised.\nRESULTS: In general, patients with MG exhibited dynamic changes in immune cell composition and inflammatory features. In particular, monocytes were enriched in the LF group, and further subgroup analysis revealed enrichment of CD14+S100A12+ monocytes and depletion of CD14+FOS+ monocytes in the LF group. Moreover, inflammation scores were significantly different in the Pre, Post and LF groups.\nCONCLUSION: Our study provides a comprehensive cell landscape for patients with MG, identifies two dysregulated monocytes, elucidates the inflammation status and offers a new perspective on understanding the aetiology of functional cure and potential therapeutic strategies for patients with MG.", "authors": ["Guo Yufan", "Gu Yu", "Jin Yuting", "Wu Xintao", "Lou Yuting", "Miao Pu", "Wang Ye", "Zhang Bijun", "Lin Xueting", "Zhang Chudi", "Feng Jianhua"], "journal": "Clinical & translational immunology", "entry_date": "2025/10/08 05:33", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41059311/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatrics The Second Affiliated Hospital of Zhejiang University School of Medicine Hangzhou China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.8, "journal_quartile": "2区/3区"}, {"pmid": "41058183", "title": "Manifestation of morphea in a patient with myasthenia gravis under therapy with zilucoplan.", "abstract": "", "authors": ["Wellmann Phoebe", "Zschüntzsch Jana", "Schön Michael P", "Mössner Rotraut"], "journal": "Journal der Deutschen Dermatologischen Gesellschaft = Journal of the German Society of Dermatology : JDDG", "entry_date": "2025/10/08 02:32", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41058183/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Dermatology, Venereology and Allergology, University Medical Center Göttingen, Göttingen, Germany."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.8, "journal_quartile": "3区"}, {"pmid": "41053529", "title": "Two paths for turning the tide: complement and FcRn inhibition to overcome refractory myasthenia gravis.", "abstract": "", "authors": ["Falso Silvia", "Marini Sofia", "Morroni Jacopo", "Marini Martina", "Iorio Raffaele"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2025/10/06 23:48", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41053529/", "pub_types": ["Letter"], "affiliations": ["Department of Neuroscience, Università Cattolica del Sacro Cuore, 00168, Rome, Italy."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41052541", "title": "[Adherence to the Mediterranean diet and anthropometric characteristics in patients with myasthenia gravis: a retrospective cohort study].", "abstract": "Myasthenia gravis (MG) is a chronic neuromuscular autoimmune disease characterized by muscle weakness in which both genetic and environmental factors play a role. A positive influence of the Mediterranean diet (MedD) has been demonstrated for some autoimmune diseases. Whether such a connection also exists in patients with MG has not yet been investigated.In a monocentric, retrospective cohort study, anthropometric data were collected from 200 patients with MG. In addition, adherence to MedD was assessed in a subgroup (n=43) using the validated Mediterranean Diet Adherence Screener (MEDAS) questionnaire. The MG cohort was stratified into a treatment-refractory group (≥3 immunosuppressants in the course; n=23) and a non-refractory group (n=177). Statistical analysis was performed using SPSS.31.6% of patients were obese, with a median BMI of 27.2 kg/m². The median MEDAS score of the overall group was 7.0 points. In the treatment-refractory group, the median score was 8.0 points; in the non-refractory group, 6.0 points. However, no significant difference was found between the groups (p=0.69). The values determined were within the range of previous comparative studies on other autoimmune diseases.MG patients showed moderate adherence to the MedD. The observation of a higher MEDAS score in the refractory group requires further investigation. The results of our study did not show any statistical evidence of a positive effect of a MedD on the course of MG.\nMyasthenia gravis (MG) ist eine durch belastungsabhängige Muskelschwäche gekennzeichnete, chronische neuromuskuläre Autoimmunerkrankung, bei der sowohl genetische als auch Umweltfaktoren eine Rolle spielen. Für einige Autoimmunerkrankungen konnte ein positiver Einfluss der mediterranen Ernährung (MedE) nachgewiesen werden. Ob ein solcher Zusammenhang auch bei MG besteht, wurde bislang nicht untersucht.In einer monozentrischen, retrospektiven Kohortenstudie wurden anthropometrische Daten von 200 MG-Patienten erhoben. Zusätzlich wurde die Adhärenz an eine MedE mithilfe des validierten Fragebogens „Mediterranean Diet Adherence Screener“ (MEDAS) bei einer Teilgruppe (n=43) erfasst. Die MG-Kohorte wurde in eine Therapie-refraktäre (≥3 Immunsuppressiva im Verlauf; n=23) und eine nicht-refraktäre Gruppe (n=177) unterteilt. Die statistische Auswertung erfolgte mittels SPSS.31,6 % der Patienten waren adipös, der mittlere BMI lag bei 27,2 kg/m². Der mediane MEDAS-Score der Gesamtgruppe betrug 7,0 Punkte. In der Therapie-refraktären Gruppe lag der Median bei 8,0 Punkten, in der nicht-refraktären bei 6,0 Punkten. Ein signifikanter Unterschied zwischen den Gruppen konnte nicht festgestellt werden (p=0,69). Die ermittelten Werte zum MEDAS-Score lagen im Bereich bisheriger Vergleichsstudien zu anderen Autoimmunerkrankungen.MG-Patienten zeigten eine moderate Adhärenz an die MedE. Die Beobachtung eines höheren MEDAS-Scores in der refraktären Gruppe bedarf weiterer Untersuchung. Die Ergebnisse unserer Studie konnten keine statistischen Hinweise auf einen positiven Effekt der MedE auf den Verlauf der MG zeigen.", "authors": ["Lorenz Felix Maximilian Xaver", "Seethaler Benjamin", "Schoser Benedikt"], "journal": "Fortschritte der Neurologie-Psychiatrie", "entry_date": "2025/10/06 19:02", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41052541/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["LMU Klinikum Friedrich-Baur-Institut, Munich, Germany."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41052399", "title": "Anti-CD19 CAR T-Cell Therapy in Advanced Stiff-Person Syndrome and Concomitant Myasthenia Gravis.", "abstract": "BACKGROUND: Autologous chimeric antigen receptor (CAR) T-cell therapy has recently gained interest in the treatment of rheumatic and neuroimmunologic diseases.\nMETHODS: We report a 62-year-old female patient with a 14-year history of treatment-refractory anti-GAD-positive stiff-person syndrome (SPS) and concomitant anti-AChR-positive myasthenia gravis. Despite a relatively stable disease course in the first 8 years, SPS dramatically progressed afterward. In 2023, she was able to walk less than 10-15 m and suffered from severe persistent stiffness in the left arm superimposed with painful muscle spasm attacks (MSAs). Numerous immunotherapies, including intravenous immunoglobulins, plasma exchange, steroids, azathioprine, and rituximab, were ineffective. Consequently, she was escalated to compassionate use of autologous anti-CD19 CAR T-cell therapy (KYV-101).\nRESULTS: From the third month post-CAR-T, we observed a substantial improvement in walking distance, pain, anxiety, and MSAs in the arm. By the sixth month, she was able to walk 500 m. The anti-GAD titers declined from 1:320 to 1:32. Side effects included grade 2 cytokine release syndrome and moderate leukopenia, without serious infections.\nDISCUSSION: CAR T-cell therapy was effective at mitigating SPS symptoms, despite the long history and severe refractory disease course in our patient. Controlled trials are needed to evaluate its potential in SPS.", "authors": ["Ayzenberg Ilya", "Aloizou Athina-Maria", "Lohmann Clarissa", "Faissner Simon", "Schneider-Gold Christiane", "Borie Dominic", "Mika Thomas", "Schroers Roland", "Motte Jeremias", "Gold Ralf"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/10/06 16:12", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41052399/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, St. Josef-Hospital, Ruhr University Bochum, Germany."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "41050272", "title": "Editorial: Autoantibodies and autoimmune neuromuscular disorders.", "abstract": "", "authors": ["Paul Pritikanta", "Fan Qihua"], "journal": "Frontiers in neurology", "entry_date": "2025/10/06 07:32", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41050272/", "pub_types": ["Editorial"], "affiliations": ["Department of Neurology, University of California, San Francisco, San Francisco, CA, United States."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41049926", "title": "Myasthenia Gravis as a Manifestation of Aicardi-Goutières Syndrome Due to a SAMHD1 Variant Successfully Treated With Baricitinib.", "abstract": "Aicardi-Goutières syndrome (AGS) is a rare inherited disorder that mainly affects the brain, immune system, and skin. It is caused by mutations that lead to calcium buildup in the brain, which is thought to trigger an immune response. Autoimmune features, such as chilblains, overlap with those seen in systemic lupus erythematosus. We describe a case of a male toddler with an AGS phenotype and a heterozygous mutation in the SAMHD1 gene, who developed juvenile myasthenia gravis (MG) and was successfully treated with baricitinib. To our knowledge, this is the first reported case of AGS associated with MG. The patient showed significant clinical improvement, including resolution of myasthenic symptoms and normalization of autoimmune markers over an 18-month follow-up period. This case highlights the importance of considering broader autoimmune manifestations in AGS and the potential efficacy of Janus kinase (JAK) inhibitors such as baricitinib.", "authors": ["Kollia Maria", "Mouskou Stella", "Mentesidou Lida", "Syggelou Angeliki", "Anagnostopoulou Katherine", "Maritsi Despoina N"], "journal": "Cureus", "entry_date": "2025/10/06 07:29", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41049926/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["2nd Department of Pediatrics, 'Panagiotis and Aglaia Kyriakou' Children's Hospital, National and Kapodistrian University of Athens, Athens, GRC."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41049242", "title": "A Comprehensive Approach to Myasthenia Gravis With Thymoma: A Case Report Highlighting Management of Myasthenic Crisis and Post-Crisis Care.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder that leads to muscle weakness and rapid fatigue, often exacerbated by thymoma, a tumor of the thymus gland. This case report presents the clinical management of a 40-year-old female with MG complicated by thymoma, who presented with a severe myasthenic crisis. The patient required intensive care, including respiratory support, plasmapheresis, and immunosuppressive therapy. Initial evaluations confirmed the diagnosis of MG through the detection of high levels of anti-acetylcholine receptor antibodies, and a CT scan revealed a thymic mass, indicative of thymoma. The management strategy included acetylcholinesterase inhibitors, immunosuppressive agents, and supportive therapies to stabilize the patient. The patient responded positively to plasmapheresis, which significantly improved her condition. Follow-up CT imaging confirmed the presence of thymoma, reinforcing the need for further investigation into surgical interventions such as thymectomy. The report also emphasizes the critical role of a multidisciplinary approach in managing MG with thymoma, underscoring the importance of early diagnosis and timely intervention to prevent recurrent crises. Additionally, it discusses the evolving role of thymectomy in MG patients with thymoma and the potential of newer treatments, such as complement inhibitors, for refractory cases. This case highlights the complexities of managing MG complicated by thymoma and stresses the importance of ongoing research into therapeutic strategies. Early diagnosis, effective management, and continuous monitoring remain essential to optimizing outcomes for patients with these complex conditions.", "authors": ["Abrar Sakib", "Ahmed Shah Tanvir", "Khalil Ibrahim", "Hossain Md Imran"], "journal": "Clinical case reports", "entry_date": "2025/10/06 07:18", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41049242/", "pub_types": ["Journal Article"], "affiliations": ["Dhaka Medical College and Hospital Dhaka Bangladesh."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41049031", "title": "Incidental Finding of Azygous Vein Aneurysm on the Background of Myasthenia Gravis-Is It a Wolf in Sheep's Coat?", "abstract": "Azygous vein aneurysm is an extremely rare clinical manifestation and often an incidental diagnosis. This could be idiopathic or secondary to a sinister pathology causing increasing central venous pressure. There is no definitive treatment guidance available due to its rare nature. Vascular interventions and anticoagulation are suggested in complex situations.", "authors": ["Wickramasinghe Sugeesha", "Howells John", "Mehdi Syed"], "journal": "Respirology case reports", "entry_date": "2025/10/06 07:16", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41049031/", "pub_types": ["Journal Article"], "affiliations": ["Department of Respiratory Medicine Royal Preston Hospital Preston UK."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "41041682", "title": "Serum interleukin-40 increases in anti-AchR antibody-positive myasthenia gravis and correlates with disease activity.", "abstract": "BACKGROUND: Interleukin-40 (IL-40), as an immune regulatory factor discovered in recent years, mainly plays a role in B-cell-related immune responses and is involved in the pathological processes of various inflammatory diseases, autoimmune disorders, and infectious diseases. However, its role in myasthenia gravis (MG) has rarely been reported.\nMETHODS: We used enzyme-linked immunosorbent assay (ELISA) to measure the serum IL-40 levels in 58 MG patients and 55 healthy controls, and conducted a detailed analysis of the clinical data.\nRESULTS: The serum IL-40 level in MG patients was significantly higher than that in healthy controls (p < 0.0001). After immunotherapy, the serum IL-40 level in MG patients significantly decreased (p < 0.0001). In MG, the IL-40 level of severe patients was significantly higher than that of mild patients (p < 0.0001). The ROC curve determined that the cut-off value for distinguishing IL-40 in MG from healthy controls was 15.63 pg/mL, with an AUC of 0.846 (95% CI: 0.773-0.919), 74.1% specificity, and 85.5% sensitivity.\nCONCLUSION: The serum IL-40 level in MG patients is elevated and is correlated with the severity of the disease. High levels of IL-40 may serve as a specific indicator for monitoring disease activity, which supports its potential as a non-invasive biomarker for disease monitoring.", "authors": ["Jia Kun", "Shao Yingzhe", "Tan Taofeng", "Liu Xuan", "Zhang Qiuxia", "Zhao Ning", "Yang Li"], "journal": "Frontiers in neurology", "entry_date": "2025/10/03 05:34", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41041682/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Huanhu Hospital, Tianjin, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41040990", "title": "The Value of Combined Detection of Systemic Inflammation Response Index and Prognostic Nutritional Index in Predicting Short-Term Prognosis of Myasthenia Gravis.", "abstract": "PURPOSE: Although systemic inflammation response index (SIRI) and prognostic nutritional index (PNI) are associated with prognosis in various diseases, their role in myasthenia gravis (MG) remains unclear. This study aims to evaluate the predictive value of SIRI combined with PNI for MG prognosis.\nMETHODS: 260 MG patients were enrolled in this retrospective study and were categorized into clinical improvement and non-improvement groups based on changes in MG-ADL and QMG scores after 6 months' treatment. Lymphocyte-to-monocyte ratio (LMR), platelet-to-lymphocyte ratio (PLR), neutrophil-to-lymphocyte ratio (NLR), SIRI and PNI were calculated from admission blood indices. Clinical differences between groups were compared. Logistic regression was used to identify independent predictors of clinical non-improvement. The ROC curve was utilized to assess the prognostic predictive value of SIRI, PNI, and their combination. Interaction effects and stratified analyses were used to explore the relationship between SIRI, PNI and MG prognosis across distinct subgroups.\nRESULTS: Patients without clinical improvement exhibited significantly elevated SIRI, NLR, and PLR, whereas LMR and PNI were reduced (p < 0.001). Multivariate logistic regression demonstrated that both SIRI and PNI significantly predicted clinical non-improvement (OR = 9.108, 95% CI: 3.412-24.317, p < 0.001; OR = 0.695, 95% CI: 0.601-0.804, p < 0.001). The area under the curve (AUC) of SIRI combined with PNI for predicting clinical non-improvement in MG was 0.928 (95% CI:0.896-0.961, sensitivity: 0.873, specificity: 0.851), which is higher than SIRI (AUC: 0.841, 95% CI: 0.783-0.899, sensitivity: 0.772, specificity: 0.845) and PNI (AUC: 0.822, 95% CI: 0.770-0.875, sensitivity: 0.759, specificity: 0.740) alone. A statistically significant interaction was identified between SIRI and thymoma (p = 0.009).\nCONCLUSION: SIRI and PNI are independently associated with MG prognosis, particularly in thymoma cases, where SIRI shows a stronger correlation. Furthermore, the combination of SIRI and PNI can serve as a valuable predictor of clinical non-improvement in MG.", "authors": ["Chen Ting", "Chen Hui", "Wen Yishuang", "Huang Yanzhen", "Lin Ziqun", "Liang Qing", "Huang Wen"], "journal": "Journal of inflammation research", "entry_date": "2025/10/03 05:26", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41040990/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, the First Affiliated Hospital of Guangxi Medical University, Nanning, Guangxi, People's Republic of China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.0, "journal_quartile": "2区"}, {"pmid": "41040424", "title": "Overlapping Syndrome of Myocarditis, Myositis, Transaminitis, and Myasthenia Gravis in a Patient with Hepatocellular Carcinoma after Treatment with Immune Checkpoint Inhibitors: A Case Report and Literature Review.", "abstract": "INTRODUCTION: Immune checkpoint inhibitors (ICIs) are widely used to treat various cancers but can induce immune-related adverse events (irAEs) in patients. Herein, we report the case of a 68-year-old patient with hepatocellular carcinoma who developed an overlapping syndrome of irAEs after receiving ICIs.\nCASE PRESENTATION: The patient received transcatheter arterial chemoembolization for hepatocellular carcinoma, followed by immunotherapy of 200 mg of camrelizumab every 3 weeks and 12 mg of lenvatinib mesylate daily. After receiving the second dose of camrelizumab treatment, the patient developed gradually worsening left eyelid ptosis and general weakness. One week later, the patient developed bilateral eyelid ptosis and suffocated while drinking water. Unfortunately, the patient was eventually diagnosed as ICI-related myocarditis, myositis, transaminitis, and myasthenia gravis based on a series of physical examinations. Subsequently, the patient was actively provided life support and symptomatic treatment. His symptoms greatly improved after treatment with methylprednisolone sodium succinate 40 mg once daily intravenously for 7 days, with gradually decreasing doses.\nCONCLUSIONS: IrAEs are common after ICI treatment. After ICI treatment initiation, close monitoring, early detection, and treatment of irAEs is required to improve clinical outcomes.", "authors": ["Kalifu Baheti", "Meng Yuan", "Aishanjiang Kedeerya", "Ma Chao", "Tian Guang-Lei", "Wang Jin-Guo", "Ma Zhi-Gang", "Chen Xiong"], "journal": "Case reports in gastroenterology", "entry_date": "2025/10/03 05:20", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41040424/", "pub_types": ["Journal Article"], "affiliations": ["Department of Hepatobiliary Surgery, People's Hospital of Xinjiang Uygur Autonomous Region, Urumqi, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "41039703", "title": "Real-world outcomes of myasthenia gravis management: a cross-sectional study at a Korean tertiary center.", "abstract": "INTRODUCTION: The clinical course and treatment response of myasthenia gravis (MG) vary widely, requiring a comprehensive understanding of treatment outcomes. However, real-world data on Korean MG patients remain limited. This study aimed to evaluate treatment outcomes in Korean MG patients at a specific cross-sectional time point.\nMETHODS: This retrospective analysis included MG patients who had outpatient visits between October 2023 and September 2024. We assessed treatment outcomes at the index date, including the proportion achieving MM-5-defined as minimal manifestations or better with corticosteroid use ≤5 mg/day - and the proportion meeting criteria for refractory MG.\nRESULTS: A total of 668 patients were included. At the index date, 16.3% were in pharmacologic remission, 45.1% in minimal manifestation, and 4.9% showed worsening disease. Overall, 48.1% achieved MM-5. The MM-5 rate was 51.9% among those treated with one immunosuppressant but declined to 17.1% in those who had been treated with three. MM-5 was achieved in 41.7% of patients with a history of myasthenic crisis and 49.0% of those without. The median MG-ADL score was 2.0; 33.7% scored 0, while 13.9% scored ≥6. The median prednisolone dose was 5.0 mg/day; 67.2% received ≤5 mg, and 9.0% received ≥15 mg. Depending on the definition used, 1.0% to 22.8% were classified as refractory.\nCONCLUSION: This study provides real-world insights into treatment outcomes in Korean MG patients. While about half achieved stable disease with conventional therapies, a substantial proportion remained inadequately controlled, underscoring ongoing treatment challenges.", "authors": ["Jung Ye Joon", "Shin Ha Young", "Park Hyung Jun", "Kim Seung Woo"], "journal": "Neurological research", "entry_date": "2025/10/03 00:23", "pub_date": "2025-10-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41039703/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School, Yonsei University College of Medicine, Seoul, Republic of Korea."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41039345", "title": "Ptosis: an uncommon manifestation to autoimmune disease activity in systemic lupus erythematosus.", "abstract": "BACKGROUND: Systemic lupus erythematosus (SLE) is an autoimmune disease with diverse manifestations, including rare neuro-ophthalmic complications. Isolated unilateral ptosis as a presenting sign of SLE is uncommon and diagnostic uncertainty often exists.\nCASE PRESENTATION: A 30-year-old woman with a 16-year history of SLE presented with acute right-sided ptosis without other neurological deficits while on stable maintenance immunosuppressive therapy. MRI of the brain and orbits, along with other relevant investigations, excluded common structural causes and showed no abnormalities. Serological testing indicated moderately active SLE, supporting an autoimmune flare as the likely mechanism. Myasthenia gravis-specific testing was not performed, a recognized limitation, but was considered clinically unnecessary given the absence of fatigability, diurnal variation, or generalized weakness. The ptosis resolved completely within 24 h of initiating high-dose systemic corticosteroid therapy.\nCONCLUSIONS: Isolated unilateral ptosis may represent a rare neuro-ophthalmic manifestation of SLE, though alternative diagnoses cannot be definitively excluded. The rapid steroid response may suggest an inflammatory or autoimmune mechanism, underscoring the importance of considering such etiologies and initiating timely immunosuppressive therapy when appropriate.", "authors": ["Al-Battashy Aisha", "Ghaithi Houda Al", "Al Lawati Batool Sh", "Al-Mujaini Abdullah S"], "journal": "BMC ophthalmology", "entry_date": "2025/10/02 23:44", "pub_date": "2025-10-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41039345/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["PGY3, Ophthalmology Residency Program, Medical Specialty Board, Muscat, Sultanate of Oman."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "41038808", "title": "Platelet activation plays a pro-inflammatory role in myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder that disrupts neuromuscular junction function through autoantibodies. Platelets are emerging as key players in the pathogenesis of MG, bridging innate and adaptive immunity. We analyze platelet transcriptome signatures and their interactions with the immune system in AChR+ immunotherapy-naïve MG (nMG) patients using bulk and single-cell RNA sequencing on peripheral blood mononuclear cells (PBMC). nMG patients exhibit upregulation of genes related to activation, inflammation, and cytoskeletal regulation. Increased platelet count, activation, altered morphology, enhanced CD62P expression, and elevated plasma CD40L levels are observed in PBMCs, which diminish with minimal clinical status (MMS). Functionally, platelets show heightened interactions with leukocytes, forming aggregates that correlate with disease severity. These features return to baseline after intravenous immunoglobulin or prolonged immunosuppressive therapy. This study underscores platelet activation's critical role in MG and supports platelet-targeted therapy.", "authors": ["Wen Qi", "Zhang Shu", "Wang Yaye", "Liu Haoran", "Wang Jingsi", "Su Shengyao", "Xie Nairong", "Lu Yan", "Di Li", "Xu Min", "Wang Min", "Chen Hai", "Wang Suobin", "Zhu Wenjia", "Wen Xinmei", "Han Jinming", "Wan Dongshan", "Zhao Shufang", "Lu Wanting", "Tao Zhen", "Duo Jianying", "Huang Yue", "Chai Guoliang", "Duan Ruisheng", "Li Xiaoli", "Hao Junwei", "Da Yuwei"], "journal": "Nature communications", "entry_date": "2025/10/02 23:13", "pub_date": "2025-10-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41038808/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xuanwu Hospital, Capital Medical University, Beijing, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 15.7, "journal_quartile": "1区"}, {"pmid": "41037175", "title": "Botulism, Lambert-Eaton Myasthenic Syndrome, and Congenital Myasthenic Syndromes.", "abstract": "OBJECTIVE: This article covers the clinical presentations, investigations, differential diagnosis, and principles of management of botulism, Lambert-Eaton myasthenic syndrome (LEMS), and congenital myasthenic syndromes.\nLATEST DEVELOPMENTS: Well-recognized guidelines exist for the management of botulism and LEMS, but resource limitations may affect implementation globally. Several genes recently reported to cause congenital myasthenic syndromes are involved in ubiquitously expressed proteins and present with a complex non-neuromuscular junction phenotype, wherein abnormal neuromuscular junction transmission is only one component of the gene defect. There have been a few promising preclinical studies on novel treatments in congenital myasthenic syndromes, including gene replacement therapy, raising the prospect of clinical trials in the near future.\nESSENTIAL POINTS: Early recognition, diagnosis, and initiation of treatment are crucial in managing all three disorders to reduce morbidity and mortality. Congenital myasthenic syndromes should be considered in patients with seronegative myasthenia gravis. Tumor screening is essential in patients with LEMS. Botulism can mimic other cranial neuropathies.", "authors": ["Ramdas Sithara"], "journal": "Continuum (Minneapolis, Minn.)", "entry_date": "2025/10/02 11:15", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41037175/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": [], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41037173", "title": "Autoimmune Myasthenia Gravis.", "abstract": "OBJECTIVE: This article reviews the diagnosis and management of autoimmune myasthenia gravis (MG), encompassing epidemiology, clinical features including disease heterogeneity, pathophysiology, and therapeutic approaches.\nLATEST DEVELOPMENTS: Recent advances in MG pathophysiology and clinical outcome measures have catalyzed the development of novel therapies, including complement and neonatal Fc receptor inhibitors, which target specific components of the autoimmune attack on the muscle endplate.\nESSENTIAL POINTS: Patients with MG exhibit fluctuating muscle weakness. Diagnosis is confirmed by acetylcholine receptor or muscle-specific kinase (MuSK) antibodies, electrodiagnostic testing, or both. Management involves tailored combinations of therapies based on patient and MG-specific factors. The treatment of patients with MG with exclusively ocular weakness, thymoma, child-bearing potential, myasthenic crisis, or MG related to cancer immunotherapy has unique considerations. Prompt diagnosis and treatment are crucial to restore neuromuscular function and minimize treatment-related complications.", "authors": ["Juel Vern C"], "journal": "Continuum (Minneapolis, Minn.)", "entry_date": "2025/10/02 11:15", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41037173/", "pub_types": ["Journal Article", "Review", "Case Reports"], "affiliations": [], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "41033145", "title": "Reassessing the steroid-sparing potential of efgartigimod in gMG.", "abstract": "", "authors": ["Yuan Jie", "Li Xuemei", "Liu Yuan"], "journal": "Journal of the neurological sciences", "entry_date": "2025/10/01 18:07", "pub_date": "2025-11-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41033145/", "pub_types": ["Letter"], "affiliations": ["Department of Pharmacy, First People's Hospital of Shangqiu, Henan, China."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41032229", "title": "Thymomas under the radiomic lens: preliminary evidence of CT-radiomics signatures for histological grading and disease staging.", "abstract": "Thymomas are the most common primary tumors of the anterior mediastinum, frequently associated with paraneoplastic syndromes like myasthenia gravis. This preliminary study investigated the correlation between radiomic features extracted from venous-phase CT images, histological grading (WHO), and disease staging (Masaoka-Koga and TNM) in patients with thymomas. A total of 37 patients were analyzed, with 107 radiomic features extracted using PyRadiomics module. Statistical analysis revealed 11 significant radiomic features distinguishing early and advanced thymomas according to Masaoka-Koga/TNM staging (p < 0.05), with shape_Sphericity, shape_Maximum3DDiameter, and firstorder_Skewness being the most predictive. For WHO classification, 7 significant features differentiated low-risk and high-risk thymomas (p < 0.05), with shape_Sphericity, firstorder-Range, and firstorder_RootMeanSquared showing the highest performance. LASSO models demonstrated high accuracy, with an AUC of 0.9 for Masaoka-Koga/TNM staging and 0.82 for WHO classification. These findings suggest that radiomic features can effectively distinguish thymoma stages and risk levels, potentially aiding in treatment planning and prognosis. By enabling noninvasive tumor characterization, radiomic features could support more personalized treatment strategies and improve decision-making in clinical practice.", "authors": ["Cozzi Diletta", "Lugli Bianca", "Paolucci Sebastiano", "Bongiolatti Stefano", "Voltolini Luca", "Miele Vittorio"], "journal": "La Radiologia medica", "entry_date": "2025/10/01 11:18", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41032229/", "pub_types": ["Journal Article"], "affiliations": ["Department of Emergency Radiology, Careggi University Hospital, Largo Brambilla 3, 50127, Florence, Italy. dilettacozzi@gmail.com."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "41029312", "title": "Autoimmune retinopathy in patients with myasthenia gravis: cases series and literature review.", "abstract": "BACKGROUND: Previous studies showed a higher frequency of concurrent autoimmune disease (AD) in patients with Myasthenia gravis (MG), but very few cases on MG patients complicated with AIR have been reported in preview literature. The goal of this study was to present three cases of autoimmune retinopathy (AIR) with myasthenia gravis (MG), conduct a literature search, and summarize the clinical characteristics of this entity.\nMETHODS: Case series and literature review.\nRESULTS: The seven AIR patients with MG were six females and a male with a mean age of 41.29(± 15.22)years old. Five had thymoma, and two had no tumor. Their symptoms of MG improved after treatment. The main ocular manifestations of AIR were bilateral, subacute, painless vision loss. The fundus examinations showed diffuse pigmentary retinopathy and atrophy of retina. Electroretinography (ERG) showed dysfunction of rod and cone cell. Hereditary retinopathy was ruled out. ARA (anti-retinal antibody) testing showed positive result for anti-retinal antibodies (ARAs), confirming the diagnosis of AIR.\nCONCLUSIONS: There is a certain frequency of concurrent MG and AIR. Patients with AIR have distinct features in the course of the disease, multimodal auxiliary examination and ARA testing. Suspected cases of MG should be comprehensively screened for early diagnosis and treatment of AIR.", "authors": ["Chen Yiqiao", "Zhang Yexin", "Luo Jia", "Liu Miaomiao", "Lin Min", "Zhu Wenhua", "Xiong Wenjun", "Zhao Peiquan", "Xi Jianying", "Fei Ping"], "journal": "BMC ophthalmology", "entry_date": "2025/10/01 01:17", "pub_date": "2025-09-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41029312/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Ophthalmology, Xinhua Hospital, Shanghai Jiao Tong University School of Medicine, Shanghai, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.7, "journal_quartile": "4区"}, {"pmid": "41026991", "title": "Obstetric and Neonatal Outcomes in Patients With Maternal Myasthenia Gravis: A Nationwide Cohort Study.", "abstract": "BACKGROUND AND OBJECTIVES: Muscle weakness, autoantibodies, and medication use in myasthenia gravis (MG) can complicate pregnancy and delivery. Vaginal delivery is encouraged despite increased risk of acute operative delivery. Our aim was to assess childbirth outcomes related to MG in a current, unselected, nationwide birth cohort.\nMETHODS: This cohort study included all singleton births in the Medical Birth Registry of Norway from 1999 to 2022. Maternal MG, defined as MG diagnosis or pyridostigmine use, was identified from current and previous pregnancies. We compared adverse pregnancy, delivery, and neonatal outcomes between MG and non-MG births, with mode of delivery as the main outcome. Odds ratios (ORs) with 95% CIs, adjusted for year of birth, maternal age, parity, civil status, and autoimmune comorbidities, were estimated with logistic regression. In subanalyses, we investigated cesarean section (C-section) rates within Robson-10 subgroups and C-section indications.\nRESULTS: There were 134 MG births and 1,351,032 non-MG births. Elective C-section was twice as likely if the mother had MG (adjusted OR [aOR] 1.8, 95% CI 1.1-3.1), but emergency C-section and operative vaginal delivery were not more common. MG increased the risk of induction (aOR 1.5, 1.0-2.3), neuraxial anesthesia (aOR 1.5, 1.1-2.1), episiotomy (aOR 1.8, 1.1-3.0), preterm prelabor rupture of membranes (aOR 2.7, 1.1-6.6), prolonged hospitalization after delivery (aOR 1.8, 1.3-2.7), low birthweight (aOR 2.4, 1.3-4.4), feeding problems (aOR 4.9, 2.5-9.5), and transfer to a neonatal unit (aOR 5.1, 3.6-7.2). Transient neonatal MG (TNMG) was diagnosed in 5 of 134 children (4%). In subanalyses, the crude C-section rate was increased in preterm MG births (50% in MG vs 19% in non-MG) and in MG births after previous C-section (75% in MG vs 47% in non-MG).\nDISCUSSION: In this registry-based study, the higher rate of elective interventions suggests a proactive management of MG deliveries. The lower C-section threshold for MG births with relative obstetric indications may be justified, but most vaginal deliveries were uncomplicated. Adverse outcomes were generally not increased in the MG group compared with the general population, although episiotomy and prolonged hospitalizations were more frequent. Notably, 40% of MG-exposed infants had feeding difficulties and hypotonia or required neonatal care, suggesting underdiagnosis of TNMG.", "authors": ["Lindroos Jenny Linnea Victoria", "Bjørk Marte-Helene", "Cohen Jacqueline M", "Danielsson Kim Christian", "Hikmat Omar", "Hoff Jana Midelfart", "Gilhus Nils Erik"], "journal": "Neurology", "entry_date": "2025/09/30 16:14", "pub_date": "2025-10-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41026991/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Medicine, University of Bergen, Norway."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41025281", "title": "Feasibility study of dose de-escalation in postoperative intensity-modulated radiation therapy for locally advanced thymoma.", "abstract": "PURPOSE: This study aimed to investigate retrospectively the feasibility of reducing the standard postoperative radiation therapy (PORT) dose of 45-50 Gy for locally invasive thymoma to shorten treatment duration and minimize side effects, while preserving disease-specific survival (DSS) and progression-free survival (PFS).\nMATERIALS AND METHODS: Between January 2016 and June 2022, 150 locally advanced thymoma patients underwent surgery followed by intensity-modulated radiation therapy, with a median follow-up of 40.8 months; the standard regimen was 45-50 Gy in 25 fractions (median biological effective dose [BED] 60 Gy), compared to a de-escalation regimen of 30-35 Gy in 10 fractions (median BED 47.25 Gy), with PFS as the primary endpoint, and overall survival (OS), DSS, and toxicity as secondary endpoints.\nRESULTS: No significant differences were found between standard and de-escalation groups in 3-year PFS (p = 0.406), with both groups achieving 100% 3-year DSS; two deaths in the de-escalation group were due to double primary cancers. All locoregional recurrences occurred outside the radiation field. Factors including age, initial tumor size, myasthenia gravis, and pathological type showed no correlation with PFS or OS. No grade II toxicities occurred in the de-escalation group, whereas the standard group had three cases of grade II toxicity, specifically radiation pneumonitis.\nCONCLUSION: Radiation dose de-escalation in locally advanced thymoma patients undergoing PORT showed comparable survival outcomes with reduced toxicity and shorter treatment duration, but requires longer follow-up to confirm efficacy and safety.", "authors": ["Hur Youn Ji", "Kim Eun Hwa", "Choi Hyeok", "Min Sun Ho", "Lee Jaiwo", "Lee Chang Geol"], "journal": "Radiation oncology journal", "entry_date": "2025/09/30 05:20", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41025281/", "pub_types": ["Journal Article"], "affiliations": ["Department of Radiation Oncology, Yonsei University College of Medicine, Seoul, Republic of Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "41025042", "title": "Mendelian Randomization Analysis of the Relationship Between Immune-Related Diseases and Alzheimer's Disease.", "abstract": "OBJECTIVE: Emerging evidence suggests a genetic link between immune-related diseases and Alzheimer's disease (AD), though the underlying mechanisms remain unclear. This Mendelian randomization (MR) study investigates the genetic relationship between six immune-related diseases-type 1 diabetes (T1DM), systemic lupus erythematosus (SLE), asthma, myasthenia gravis (MG), endometriosis, and idiopathic thrombocytopenic purpura (ITP)-and AD.\nMETHODS: Summary-level data were obtained from publicly available genome-wide association studies (GWAS) for the six immune-related diseases and AD. MR-estimation was conducted utilizing the inverse variance weighted (IVW), MR-Egger, and WM methods. Additionally, sensitivity analyses were performed, encompassing Cochran's Q test, MR-Egger intercept, MR-Pleiotropy residual sum and outlier (MR-PRESSO) method, leave-one-out analysis, and funnel plots.\nRESULTS: A statistically significant association was identified between asthma and a slightly lower risk of AD (odds ratio [OR] = 0.996, 95% CI: 0.994-0.997, P = 0.001); however, the effect size was negligible and likely lacks clinical significance. No significant genetic associations were found between T1DM, SLE, MG, endometriosis, or ITP and AD. Reverse MR analyses indicated no evidence of reverse causality from AD to these immune-related conditions.\nCONCLUSION: Although a nominal association was observed, this MR analysis does not support a causal relationship between genetic liability to asthma and Alzheimer's disease. This relationship underscores the specificity of the association, as no causal connections were found between other studied immune-related diseases conditions-T1DM, SLE, MG, endometriosis, and ITP-and AD.", "authors": ["Huang Dong-Hong", "Zhang Yue-Ling", "Shi Sheng-Liang", "Liang Tian-Jia", "Chen Jun-Jian", "Li Guo-Qiao", "Chen Zhao-De"], "journal": "Journal of multidisciplinary healthcare", "entry_date": "2025/09/30 04:17", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41025042/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Guangxi Medical University, Guangxi, 530000, People's Republic of China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "41024342", "title": "Atrioventricular block and myastenia gravis. A case report and review of the literature.", "abstract": "OBJECTIVES: Myasthenia gravis (MG) is a chronic autoimmune disease primarily affecting skeletal muscles, though cardiac involvement, particularly arrhythmias, may occur, especially in severe cases or in patients with thymoma.\nCASE PRESENTATION: We report the case of a 62-year-old male with AchR-Ab-positive MG, without thymoma, who developed an advanced atrioventricular block requiring pacemaker implantation. Cardiac manifestations in MG can result from either the disease itself - through myocarditis, autoantibodies and autonomic dysfunction - or as a side effect of treatments such as pyridostigmine and immunosuppressants. Management strategies include considering discontinuation of pyridostigmine or using hyoscyamine to assess potential drug-induced bradyarrhythmias before proceeding with permanent pacing.\nCONCLUSIONS: This case highlights the diagnostic challenges in distinguishing iatrogenic from autoimmune cardiac complications and emphasizes the importance of cardiovascular monitoring in MG patients, especially those presenting with cardiac symptoms or EKG abnormalities. Early recognition and appropriate intervention are crucial to improve outcomes and quality of life.", "authors": ["Lombardi Anna", "Murru Francesco", "Atripaldi Luigi Giuseppe", "D'Argenzio Carmine", "Verdoliva Rita", "Iannibelli Giordana G", "Canitano Claudia", "De Luca Mariarosaria", "Cudemo Giuseppe", "Lucci Rosa", "Salzano Andrea", "Marra Alberto M", "Arcopinto Michele", "Cittadini Antonio"], "journal": "Journal of basic and clinical physiology and pharmacology", "entry_date": "2025/09/30 00:49", "pub_date": "2025-11-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41024342/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Translational Medical Sciences, \"Federico II\" University, Naples, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.3, "journal_quartile": "4区"}, {"pmid": "41021867", "title": "Subunit-Specific Immunodominance in Clinically Distinct Populations With AChR+ Myasthenia Gravis: A Multiparametric Cross-Sectional Analysis.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis (MG) is a chronic antibody-mediated autoimmune neuromuscular disorder causing fluctuating muscle weakness due to autoantibodies that target the acetylcholine receptor (AChR) in the neuromuscular junction (NMJ). Despite extensive research, MG remains unpredictable and heterogeneous, underscoring the need for better insight into disease pathogenesis and clinical course. The objective of this study was to identify clinical and immunologic disease-related parameters that correlate with disease severity.\nMETHODS: This large-scale, multicenter, cross-sectional study included prospectively recruited patients with MG and MG serum samples procured from reputable biobanks. Inclusion criteria required an MG clinical presentation and a positive anti-AChR immunoglobulin G (IgG) titer (≥0.5 nM), confirmed by 2 independent tests. Enrolled patients underwent profiling of subunit-specific anti-AChR IgG titers. Disease severity patterns and their relation to age, sex, disease onset, thymic involvement, anti-AChR titer, and anti-AChR subunit immunodominance were investigated.\nRESULTS: The study included 513 patients with MG (50.5% female) with a median age of 64 years (range 14-98.5). Extended clinical data were available for 232 patients. Anti-AChR titers increased monotonically with disease severity (ρ = 0.31, 95% CI 0.17-0.44, p < 0.0001) and were higher in female patients (median 14.6 nM vs 7.7 nM, 95% CI for Δ 2.1-7.3 nM, p < 0.0001) in whom higher antibody titers decreased monotonically with age. Male patients' titers were predominantly alpha-immunodominant (male 23.2% vs female 16.6%, 95% CI for Δ 0%-7.6%, p = 0.031), while female patients' titers were gamma-immunodominant (female 30% vs male 24.5%, 95% CI for Δ 2%-11%, p = 0.0027). Gamma immunodominance correlated with higher anti-AChR titer (ρ = 0.25, 95% CI 0.16-0.33, p < 0.0001) and severe (Myasthenia Gravis Foundation of America IV-V) disease (44% vs 27%, 95% CI for Δ 4%-34%, p = 0.0141). Unsupervised principal component analysis disclosed 2 distinct disease endotypes: female patients with moderate to severe early-onset MG, gamma subunit immunodominance, high anti-AChR titers, and frequent thymic hyperplasia (endotype A) and the remaining patients, mostly patients with late-onset MG, alpha subunit immunodominance, and low anti-AChR titers (endotype B).\nDISCUSSION: Two distinct MG endotypes emerge based on sex, age, thymic involvement, autoantibody titer, and immunoglobulin AChR subunit immunodominance-suggesting different underlying etiologies with potential implications for sex-dependent precision medicine, women's health, and the development of new therapeutic modalities for MG.", "authors": ["Oved Kfir", "Denkberg Galit", "Pinzur Lena", "Chroni Elisabeth", "Zouvelou Vasiliki", "Arman Inbar", "Mazor Roei David", "Reef Sharon", "Harel Ofer", "Ntoukaki Eleni", "Pechlivanidou Maria", "Ninou Elpinickie", "Tzanetakos Dimitrios", "Salakou Stavroula", "Chondrogianni Maria", "Daponte Ariadne", "Rentzos Michail", "Parisis Dimitrios", "Zamba-Papanicolaou Eleni", "Pantzaris Marios", "Kleopa Kleopas A", "Dardiotis Efthimios", "Vadikolias Konstantinos", "Heliopoulos Ioannis", "Koutsouraki Euphrosyni", "Voumvourakis Konstantinos I", "Konitsiotis Spyridon", "Giannopoulos Sotirios", "Grigoriadis Nikolaos C", "Kab Tasneem", "Friedman Yitzhak", "Hellmann Mark A", "Alon Tayir", "Olmer Liraz", "Tsivgoulis Georgios", "Lazaridis Konstantinos", "Wilf-Yarkoni Adi", "Tzartos John", "Tzartos Socrates"], "journal": "Neurology", "entry_date": "2025/09/29 16:03", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41021867/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Canopy Immuno-Therapeutics, Haifa, Israel."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41021216", "title": "An evaluation of nipocalimab for the treatment of generalized myasthenia gravis.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disease caused by autoantibodies targeting the neuromuscular junction. MG, characterized clinically by fluctuating muscle weakness and fatigability, is traditionally treated primarily with corticosteroids and nonspecific immunosuppressive drugs. Despite their documented efficacy in a proportion of patients, current standard-of-care treatments are associated with moderate-to-severe side effects that underline the need for new targeted therapies. Nipocalimab, a fully human monoclonal antibody, binds to the neonatal Fc receptor (FcRn) with high affinity and specificity, causing selective reduction of circulating IgG and pathogenic IgG autoantibodies. The phase 3 study Vivacity-MG3 confirmed nipocalimab as an efficacious and safe treatment providing sustained disease control in seropositive patients with generalized MG (gMG).\nAREAS COVERED: The efficacy and safety of nipocalimab in gMG from the phase 2 study Vivacity-MG (NCT03772587) and the phase 3 study Vivacity-MG3 (NCT04951622).\nEXPERT OPINION: Clinical studies have demonstrated that nipocalimab provided rapid and sustained reduction of total IgG and pathogenic IgG autoantibodies together with sustained disease control over 6 months in a broad population of seropositive patients with gMG, with an acceptable safety profile. The long-term impact of nipocalimab on the course of gMG needs to be further investigated in real-world settings.", "authors": ["Antozzi Carlo", "Fitzgibbon Marie"], "journal": "Expert opinion on biological therapy", "entry_date": "2025/09/29 11:26", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41021216/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Immunotherapy and Apheresis Departmental Unit, Fondazione IRCCS Istituto Neurologico C. Besta, Milan, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.0, "journal_quartile": "3区"}, {"pmid": "41020460", "title": "Clinical Features and Outcome in Myasthenia Gravis Patients with Antimuscle-specific Tyrosine Kinase Antibody: A Retrospective Study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) patients with anti-MuSK (muscle-specific tyrosine kinase) antibody (MuSK-MG) are uncommon. Compare with MG patient with anti-ACh (acetylcholine) receptor antibody (AChR-MG), MuSK-MG exhibit unique features.\nOBJECTIVES: The aim of this study is to analyze the difference of the clinical characteristics and electrophysiological features between MuSK-MG and AChR-MG.\nMATERIALS AND METHODS: We retrospectively review the medical records of generalized MG patients from 2004 to 2019 at Shin Kong Memorial Wu Ho-Su Hospital. We enrolled 47 MuSK-MG patients (33 females and 14 males), and 48 AChR-MG patient (23 females and 25 males).\nRESULTS: MuSK-MG patients have a female predominance (70.2% vs. 47.9%, P = 0.027) and no significant difference to AChR-MG in onset age (44.02 ± 15.06 vs. 47.52 ± 15.85, P = 0.273). MuSK-MG are more likely to involve facial (76.6% vs. 16.7%, P < 0.001), bulbar (100% vs. 50%, P < 0.001), neck (55.3% vs. 22.9%, P = 0.001), and respiratory muscles (61.7% vs. 10.4%, P < 0.001). MuSK-MG tent to experience more severe symptoms with MGFA Class III or greater (72.3% vs. 50.0%, P = 0.032). The thymic pathology in MuSK-MG is likely to be normal (55.3% vs. 18.8%) or thymic hyperplasia (44.7% vs. 25%). The overall positive rate for repetitive nerve stimulation (RNS) in MuSK-MG patients is less than AChR-MG patients (66.0% vs. 85.4%, P = 0.027). Further analysis shows the difference is mainly by recording from trapezius muscles (51.1% vs. 79.2%, P = 0.004), whereas there is no difference in nasalis muscles (60% vs. 67.6%, P = 0.544) and abductor digiti minimi muscles (13% vs. 18.4%, P = 0.582). The positive rate for single fiber electromyography (SFEMG) recording from orbicularis oculi is very high in both MuSK-MG and AChR-MG (100% vs. 97.2%, P = 0.289). Both MuSK-MG and AChR-MG patients achieved good outcome after proper treatment (68.1% vs. 75%, P = 0.4455).\nCONCLUSIONS: MuSK-MG patients have a female predominance and more facial, bulbar, neck, and respiratory muscles involvements. The electrodiagnostic features of MuSK-MG are lower positive rate of RNS at trapezius and high positive rate of SFEMG at facial muscles. Although MuSK-MG patients are associated with a more progressive course, proper diagnosis and treatment still can lead to a favorable outcome.", "authors": ["Chung Yi-Chun", "Yeh Jiann-Horng", "Chiu Hou-Chang", "Lien Li-Ming", "Chen Wen-Hung"], "journal": "Acta neurologica Taiwanica", "entry_date": "2025/09/29 07:43", "pub_date": "2025-07-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41020460/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, New Taipei City Hospital, New Taipei, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "41015758", "title": "Validation and optimisation of a commercial cell-based assay for detection of nodo-paranodal antibodies.", "abstract": "A minority of patients fulfilling diagnostic criteria for chronic inflammatory demyelinating polyradiculoneuropathy (CIDP) have been found to have autoantibodies against components of nodal and paranodal structures in peripheral nerves. These autoantibodies may confer distinct clinical features, including a lower likelihood of response to treatment with intravenous immunoglobulin (IVIg). There are currently limited options available for the detection of these autoantibodies in the diagnostic setting. We tested serum samples from 30 patients with CIDP, 40 disease controls [20 with myasthenia gravis and 20 with systemic lupus erythematosus (SLE)] and 52 healthy controls for the presence of antibodies against neurofascin 155 (NF155), neurofascin 186 (NF186), contactin-1 (CNTN1) and the contactin-1/contactin-associated protein 1 (CNTN1/CASPR1) complex using a commercial transfected HEK293 cell-based indirect immunofluorescence immunoassay (EUROImmun). We detected nodo-paranodal antibodies in six of 30 CIDP patients, including five who had previously tested positive for nodo-paranodal antibodies using enzyme-linked immunosorbent assay (ELISA). There was one positive test for anti-CNTN1 in a disease control with SLE and membranous glomerulonephritis, with no positive tests in healthy controls. We modified the manufacturer's staining protocol by using biotinylated anti-IgG and streptavidin-FITC labelling, which increased the analytical sensitivity of the assay. Our modified assay retained its robustness in the presence of interfering substances (haemolysed, lipaemic and icteric samples) and serum with high non-specific background immunofluorescent staining. We successfully modified and validated a commercial indirect immunofluorescence immunoassay for the qualitative detection of antibodies against NF155, NF186, CNTN1 and CNTN1/CASPR1. This could lead to more rapid diagnosis of patients with these autoantibodies, avoiding costly and ineffective treatments.", "authors": ["Leto Julian", "Spies Judith", "Tran Linda", "Luo Irene", "Stoyanov Alex", "Bradhurst Peter", "Urriola Nicolás"], "journal": "Pathology", "entry_date": "2025/09/27 23:18", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41015758/", "pub_types": ["Journal Article", "Validation Study"], "affiliations": ["Department of Clinical Immunology, Royal Prince Alfred Hospital, Pathology East, NSW Health Pathology, Camperdown, NSW, Australia."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "41014942", "title": "Letter to the editor: Steroid-sparing implications of efgartigimod in generalized myasthenia gravis.", "abstract": "", "authors": ["La Nav", "Rattanapitoon Schawanya K", "Rattanapitoon Nathkapach K"], "journal": "Journal of the neurological sciences", "entry_date": "2025/09/27 18:09", "pub_date": "2025-11-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41014942/", "pub_types": ["Letter"], "affiliations": ["Faculty of Medicine, International University, Phnom Penh, Cambodia."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "41008338", "title": "Immunological Targets in Generalized Myasthenia Gravis Treatment: Where Are We Going Now?", "abstract": "BACKGROUND: Generalized myasthenia gravis (gMG) is a heterogeneous autoimmune disorder marked by antibody-mediated disruption of neuromuscular transmission. Despite advancements in immunosuppressive therapies and biologics, a subset of patients remains refractory, necessitating more targeted and personalized treatment strategies.\nOBJECTIVE: This review aims to synthesize current knowledge of the immunopathological mechanisms across gMG subtypes and to explore emerging therapeutic targets tailored to these diverse disease phenotypes.\nMETHODS: A narrative review was conducted, integrating recent findings from clinical trials, immunogenetic studies, and preclinical research to describe subtype-specific immune mechanisms and corresponding therapeutic innovations.\nRESULTS: gMG subtypes-characterized by autoantibody profiles (AChR, MuSK, LRP4, or seronegative), thymic histopathology, and age of onset-demonstrate distinct immunological pathways. Early-onset MG is associated with thymic hyperplasia and Th17-driven inflammation; thymoma-associated MG involves central tolerance breakdown; late-onset MG shows immune senescence and altered T-cell regulation. MuSK- and LRP4-positive MG exhibit unique cytokine and antibody signatures. Novel therapeutic strategies include B cell- and T cell-targeted therapies (e.g., anti-CD19, anti-CD38, JAK inhibitors), cytokine inhibitors (IL-6, IL-17, IL-23), FcRn antagonists, complement inhibitors, and gene- or cell-based therapies such as CAR-T and CAAR-T cells.\nCONCLUSION: The evolving landscape of gMG treatment reflects a shift toward immunopathology-based precision medicine. Better characterization of subtype-specific molecular signatures and immune dysfunctions is essential to guide clinical decision-making and improve outcomes for treatment-refractory patients.", "authors": ["Rossini Elena", "Leonardi Luca", "Morino Stefania", "Antonini Giovanni", "Fionda Laura"], "journal": "Brain sciences", "entry_date": "2025/09/27 01:08", "pub_date": "2025-09-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41008338/", "pub_types": ["Journal Article", "Review"], "affiliations": ["NESMOS Department, Sapienza University of Rome, 00185 Rome, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "41006369", "title": "Refinement of the rat acetylcholine receptor-specific passive transfer myasthenia gravis model using subcutaneous injections: an update to the guidelines.", "abstract": "The passive transfer model of myasthenia gravis (PTMG) reflects the effector phase of the human condition and is induced in female rats using monoclonal antibodies. The current guideline recommends administration of monoclonal antibodies (mAb) such as mAb35 via intraperitoneal (I.P.) or intravenous (I.V.) injection, offering rapid absorption, but posing challenges such as injection placement and, in the case of I.P., animal discomfort. In this study, we investigated the suitability of subcutaneous (S.C.) administration as an alternative to I.P. in the rat PTMG model. Female rats were injected with 20 pmol mAb35 /100 g body weight (BW), either I.P. or S.C. and euthanized 48 h post-immunization, or S.C. with 20 or 40 pmol mAb35 /100 g BW and euthanized 48- or 72-hours post-immunization. Control animals received 0.5 mg/kg IgG1 isotype control S.C. or I.P. Muscle weakness, weight loss and clinical manifestations were assessed daily. Additionally, decrement-inducing curare dose and AChR content in the tibialis anterior (TA) were determined using electromyography and radioimmunoassay (RIA) respectively. S.C. mAb35 administration induced body weight loss and MG symptoms comparable to I.P. administration. However, I.P. injection presented a risk of misplacement, making it potentially a less reliable administration method. While MG characteristics were observed regardless of mAb35 dose and route, variability of clinical parameters and TA AChR content differed between approaches. S.C. induction of disease was verified using a different batch of mAb35 with a dose of 40 pmol/100 g BW S.C administered. We demonstrated that S.C. injection offers a consistent induction of PTMG, establishing it as a refined, effective alternative to I.P. administration by reducing procedural invasiveness and improving consistency in symptom onset.", "authors": ["Arets Britt", "Mané-Damas Marina", "Schöttler Anja K", "Sikorski Patricia M", "Kusner Linda L", "Kaminski Henry J", "Losen Mario", "Martinez-Martinez Pilar"], "journal": "Scientific reports", "entry_date": "2025/09/26 23:32", "pub_date": "2025-09-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41006369/", "pub_types": ["Journal Article"], "affiliations": ["Department of Psychiatry and Neuropsychology, School for Mental Health and Neuroscience, Maastricht University, Maastricht, The Netherlands."], "china_related": false, "study_types": ["Guideline/Consensus"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "41005701", "title": "Comparing Psychometric Properties of 6 of the 5-Level and 3-Level EQ-5D Bolt-Ons in a Large, Multinational, Longitudinal General Population Sample.", "abstract": "OBJECTIVES: This study systematically compared the psychometric properties of 6 of the 5-level and 3-level EQ-5D bolt-ons (vision, breathing, tiredness, sleep, social relationships, and self-confidence).\nMETHODS: Population Norms Study (POP-UP) is a longitudinal survey collecting general population data from United States, Canada, United Kingdom, Italy, Spain, Germany, the Netherlands, and Belgium. Respondents entered demographics and health conditions data and completed the EQ-5D-5L/3L with bolt-ons, Myasthenia Gravis Activities of Daily Living (MG-ADL), and Health Utility Index-3 (HUI-3). Psychometric properties included ceiling/floor, informativity, divergent and convergent validity, reliability, known-groups validity, and responsiveness.\nRESULTS: A total of 9,758 respondents completed the survey in 2021, and 4,839 respondents in 2023. The 5-level bolt-ons reduced ceiling effects by 35% and floor effects by 55% compared with the 3-level, with the largest reductions for vision and sleep (42%/57%) and the smallest for breathing (29%/44%). Informativity was higher for the 5-level bolt-ons (3%-11%) than 3-level (2%-9%), except for breathing (-2%). Most bolt-ons showed weak to moderate correlations with EQ-5D dimensions, except for social relationships, which correlated strongly with anxiety/depression (r = 0.61). Both measures showed strong convergent validity for breathing (5-level r = 0.68; 3-level r = 0.66) and lower for vision (5-level r = 0.37; 3-level r = 0.32). EQ-5D + 5-level and EQ-5D-5L + 3-level bolt-ons had excellent reliability (Intraclass Correlation Coefficients = 0.92-0.97). Adding bolt-ons did not significantly improve known-groups validity, except for breathing (relative efficiency EQ-5D + 5-level = 1.12; EQ-5D-5L + 3-level = 1.10). The 5-level bolt-ons improved responsiveness, detecting 47.1% more improvements and 55.7% more worsening over time.\nCONCLUSIONS: All 6 of the 5-level EQ-5D bolt-ons outperformed the 3-level bolt-ons by reducing ceiling and floor, enhancing informativity, demonstrating divergent validity, and improving responsiveness.", "authors": ["Dewilde Sarah", "Janssen Mathieu F", "Phillips Glenn", "Mulhern Brendan", "Rencz Fanni"], "journal": "Value in health : the journal of the International Society for Pharmacoeconomics and Outcomes Research", "entry_date": "2025/09/26 19:40", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41005701/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Services in Health Economics (SHE), Brussels, Belgium. Electronic address: sd@she-consulting.be."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV"}, {"pmid": "41004697", "title": "Screening for Congenital Myasthenic Syndromes in Adults With Seronegative Myasthenia Gravis Using Next-Generation Sequencing.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis (MG) is a disorder of the neuromuscular junction, typically associated with autoantibodies (Abs) that impair neuromuscular transmission. However, approximately 10% of cases are seronegative. Emerging evidence suggests that seronegative MG (SNMG) may be mimicked by hereditary conditions, particularly congenital myasthenic syndromes (CMSs), which require different treatments. In this study, we aimed to determine the proportion of CMS among patients diagnosed with SNMG.\nMETHODS: We used whole-exome sequencing (WES) in adult patients (aged ≥18 years) diagnosed with SNMG who were enrolled at 3 Austrian tertiary neuromuscular centers between August 2022 and January 2024. Genetic testing was conducted in individuals who remained seronegative after comprehensive serologic testing to exclude Abs against (clustered) acetylcholine receptors, muscle-specific kinase, lipoprotein receptor-related protein 4, and voltage-gated calcium channels. Moreover, we aimed to analyze clinical and demographic factors associated with the likelihood of receiving a molecular diagnosis.\nRESULTS: A total of 50 patients with SNMG (35 [70%] female) were referred for exome-based genetic screening. The median age at disease onset was 35 years (interquartile range 24.0-46.0 years). Seven patients (14%) were genetically diagnosed with CMS through WES (4 with CHRNE and 3 with RAPSN variants). In addition, findings of uncertain clinical significance were reported in 4 cases, implicating CACNA1S, DOK7, DPAGT1, and RAPSN. Although patients with CMS tended to have a younger age at disease onset in univariate analysis (p = 0.04, r = 0.29), no clinical or demographic factors remained significantly associated with a molecular diagnosis after correction for multiple testing. Only 1 patient with a confirmed CMS diagnosis reported a positive family history. Six individuals with CMS (86%) had either received immunomodulatory treatments (n = 4) or undergone thymectomy (n = 4). Of the 4 patients with CMS receiving immunotherapies, 3 were reported to have experienced at least a partial response.\nDISCUSSION: Our findings provide evidence that a considerable proportion of patients diagnosed with SNMG have an underlying hereditary etiology. Notably, a (subjective) response to immunotherapies does not exclude a molecular CMS diagnosis. In conclusion, offering genetic testing to seronegative patients with myasthenic syndromes may have profound therapeutic implications.", "authors": ["Krenn Martin", "Wagner Matias", "Schuller Helena", "Pugna Isabel", "Rath Jakob", "Zulehner Gudrun", "Keritam Omar", "Weng Rosa", "Koneczny Inga", "Schiavo Ebe", "Damato Valentina", "Kleinveld Vera E A", "Kiss Christian", "Gold Valeriu", "Quasthoff Stefan", "Masi Gianvito", "O'Connor Kevin C", "Canning Jake", "Waters Patrick J", "Lenz Dietlind", "Blüthner Martin", "Pavlov Martin", "Graf Elisabeth", "Winkelmann Juliane", "Löscher Wolfgang N", "Zimprich Fritz", "Cetin Hakan"], "journal": "Neurology", "entry_date": "2025/09/26 16:03", "pub_date": "2025-10-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41004697/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Medical University of Vienna, Austria."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "41002027", "title": "Angel wing: a class of alternative splicing regulators in animals.", "abstract": "Alternative splicing (AS) regulates the diversity and level of the proteome. The specificity in AS is in turn regulated by RNA-binding proteins, but our understanding of how they act is far from complete. Here, we identify the Angel wing (Anw) protein, previously CG10948, as a novel AS regulator. Loss of Anw in Drosophila disrupts splicing in muscle genes and subsequently muscle function. Based on a mini-gene assay in which Anw and its RNA targets are co-expressed in cultured cells, we demonstrated orthologous splicing regulation of the mini-gene transcripts, interaction between Anw and its RNA targets, and a remarkable functional conservation among Anw homologs. Anw forms nuclear foci, and genetic ablation of Anw domains suggests that maintaining distinctive features of these foci is important for its function. The evolution of Anw is dynamic with gene gains and losses, but as others suggested, preserves a cross-phyla \"ultra conserved element\" as an alternative exon that potentially regulates its own level by nonsense-mediated mRNA decay. As the human anw homolog is a candidate gene for myasthenia gravis, our work suggests a mechanism for cellular dysfunction in this disease.", "authors": ["Zhang Ting", "Li Kaili", "Xiao Ying", "Tan Xiaoyan", "Tan Xionghong", "Cui Min", "Rong Yikang S"], "journal": "Nucleic acids research", "entry_date": "2025/09/26 08:03", "pub_date": "2025-09-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41002027/", "pub_types": ["Journal Article"], "affiliations": ["Hengyang College of Medicine, University of South China, 420001 Hengyang, China."], "china_related": true, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 13.1, "journal_quartile": "1区"}, {"pmid": "41001321", "title": "Blink and You'll Miss It: Diagnostic Pitfalls in a Case of Missed Ocular Myasthenia Gravis in the Emergency Department.", "abstract": "Ocular myasthenia gravis (MG), a subtype of MG limited to the eyelids and extraocular muscles, is diagnostically challenging in the emergency department (ED). In the absence of generalized weakness, subtle symptoms such as ptosis and diplopia are more easily overlooked or misattributed to stroke or other neurologic pathologies. We present a case of a 69-year-old male whose diagnosis of ocular MG was delayed due to limited neurologic examination, underuse of simple bedside tools, and incidental imaging findings that initially suggested alternative endocrine pathology. Despite classic signs, including fatigable ptosis and diplopia, treatment with pyridostigmine was not initiated until 31 hours after ED arrival, at which point the patient experienced near-complete resolution of ocular symptoms within one hour. This case highlights the importance of maintaining clinical suspicion for MG in cranial nerve presentations. Incorporating accessible bedside tests, such as the ice pack test or acetylcholinesterase inhibitor trial, can expedite diagnosis and treatment in the ED.", "authors": ["Neumann Joshua", "Aqil Mohammad S", "Singh Simran P", "Fawaz Dema"], "journal": "Cureus", "entry_date": "2025/09/26 05:45", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41001321/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Medical School, Oakland University William Beaumont School of Medicine, Rochester, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "41000735", "title": "Myasthenia thymus reprograms class-switched B cells into BAFF-dependent survivors.", "abstract": "Myasthenia gravis (MG) presents a clinical challenge where autoantibody titers against the neuromuscular junction fail to predict disease severity or treatment response, and thymectomy provides inconsistent benefit despite removing the source of autoreactive B cells. We hypothesized that thymic B cells acquire survival mechanisms that bypass normal tolerance checkpoints, enabling persistence independent of antigen-specific selection. Using single-cell RNA sequencing, V(D)J repertoire analysis, and spatial transcriptomics from human thymic samples, representing the largest MG atlas to date (237,661 cells), we discovered a previously unrecognized tolerance checkpoint swap in MG pathogenesis. Pathological class-switched B cells within thymic germinal centers exhibited reduced antigen presentation capacity (decreased CD74, CD1C expression) and diminished CD40 co-stimulation while upregulating TNFRSF17 to engage BAFF survival signals. This shift from T cell-dependent activation to BAFF-driven survival allowed polyclonal autoreactive B cells to persist without stringent selection and seed peripheral sites. T follicular helper cells supported this reprogramming through increased TNFSF13B and CHGB expression, the latter enabling dopamine-mediated acceleration of B cell synapses. These findings resolve longstanding clinical paradoxes in MG and identify the BAFF-BCMA axis as an actionable therapeutic target. Measuring serum BAFF and soluble BCMA could provide superior biomarkers to antibody titers, while BAFF inhibition or CD40 agonism could restore normal tolerance checkpoints, offering new therapeutic strategies for MG and potentially other autoimmune diseases.", "authors": ["Yan Yuanqing", "Patino Diego Avella", "Zhao Yimeng", "Wu Xin", "Budinger G R Scott", "Bharat Ankit"], "journal": "bioRxiv : the preprint server for biology", "entry_date": "2025/09/26 05:35", "pub_date": "2025-09-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/41000735/", "pub_types": ["Journal Article", "Preprint"], "affiliations": ["Department of Surgery, Division of Thoracic Surgery, Feinberg School of Medicine, Northwestern University, Chicago, IL, 60611."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40999366", "title": "Perioperative Efgartigimod treatment for acute myasthenia gravis exacerbation with retroperitoneal mass: a case report.", "abstract": "OBJECTIVE: This case demonstrates the efficacy and safety of efgartigimod in managing an acute exacerbation of myasthenia gravis (MG) with comorbid Castleman disease, particularly during the perioperative care of retroperitoneal mass resection.\nMETHODS: A 23-year-old female was admitted with the discovery of a retroperitoneal Mass, confirmed via abdominal enhanced CT and MRI. The patient had generalized MG since 2017, with controlled but fluctuating symptoms.\nRESULTS: Preoperative assessment showed albumin levels were slightly reduced and respiratory function demonstrated severe restrictive ventilation impairment. There was acute exacerbation of muscle weakness (MG Foundation of America (MGFA) class IVb, MG-activities of daily living (ADL) score 8, and quantitative MG (QMG) score 20) with respiratory and medullary symptoms. Treatment with efgartigimod (10 mg/kg/week), prednisone 15 mg/day and pyridostigmine 270 mg/day was initiated. The symptoms improved substantially after four infusions (MG-ADL score 0, QMG score 6), and the lung function recovered. The patient continued efgartigimod treatment and underwent retroperitoneal mass resection. The mass showed massive lymph node hyperplasia (Castleman's disease, mixed type). Postoperatively, the patient experienced no infection, MG exacerbation, or other complications.\nDISCUSSION: Efgartigimod had a rapid onset of action, swiftly improved symptoms during acute MG exacerbation, and maintained symptom stability during the perioperative care.", "authors": ["Yan Jinyi", "Choi Kalam", "Fu Peicai", "Li Yue", "Li Zhijun"], "journal": "BMC neurology", "entry_date": "2025/09/26 00:03", "pub_date": "2025-09-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40999366/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, 430030, Hubei, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "40998189", "title": "When myasthenia gravis meets autoimmunity: cause or confounder?", "abstract": "", "authors": ["Messina Christian"], "journal": "The American journal of medicine", "entry_date": "2025/09/25 19:42", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40998189/", "pub_types": ["Editorial"], "affiliations": ["Azienda Sanitaria Provinciale Catania, Catania, Italy. Electronic address: chry.messina@gmail.com."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "40996884", "title": "A Rare Autoimmune Quartet: Immune Thrombocytopenia in a Patient with Autoimmune Polyglandular Syndrome Type 3.", "abstract": "", "authors": ["Ataş Ünal", "Doğruel Hakan"], "journal": "Turkish journal of haematology : official journal of Turkish Society of Haematology", "entry_date": "2025/09/25 12:35", "pub_date": "2026-02-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40996884/", "pub_types": ["Journal Article"], "affiliations": ["Akdeniz University Faculty of Medicine, Department of Internal Medicine, Division of Hematology, Antalya, Türkiye"], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40995903", "title": "Risk factors for generalization of ocular myasthenia gravis.", "abstract": "PURPOSE: To identify potential risk factors for the generalization of ocular myasthenia gravis (OMG).\nDESIGN: Retrospective cohort study.\nMETHODS: This study was conducted at a tertiary neurology clinic between January 2007 and January 2018. A total of 209 patients with myasthenia gravis (MG) presenting with initial ocular involvement were included. Multivariable binary logistic regression was performed to assess the relationship between potential risk factors and disease generalization.\nRESULTS: Generalization occurred in 65.6% of patients, while 34.4% remained with pure OMG during a median follow-up period of 74 months (range, 24-206 months). Among those who developed generalized MG (GMG), 84.7% did so within the first two years. The overall regression model was statistically significant (p < 0.001), with a Nagelkerke R² value of 0.536, indicating a good model fit. Female sex, elevated acetylcholine receptor (AChR) antibody titers, and a positive repetitive nerve stimulation (RNS) test were identified as statistically significant predictors of disease generalization.\nCONCLUSIONS: The majority of patients with OMG develop generalized disease within the first two years. Major risk factors for generalization include female sex, elevated AChR antibody titers, and abnormal findings on RNS testing.", "authors": ["Djordjevic Ivana S", "Peric Stojan", "Djordjevic Stefan A", "Lavrnic Dragana", "Marasevic Kristina", "Apostolski Slobodan", "Kosac Ana", "Basta Ivana"], "journal": "Indian journal of ophthalmology", "entry_date": "2025/09/25 07:23", "pub_date": "2025-10-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40995903/", "pub_types": ["Journal Article"], "affiliations": ["University Clinical Center of Serbia, Neurology Clinic, Belgrade, Serbia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.8, "journal_quartile": "4区"}, {"pmid": "40995750", "title": "Single-Cell Immune Profiling Reveals Neutrophils Promote Myasthenia Gravis Exacerbation Through BAFF Secretion.", "abstract": "Neutrophils play a critical role in the pathogenesis of autoimmune diseases, including myasthenia gravis (MG), but their specific function in MG exacerbations remains unclear. This study utilizes single-cell RNA sequencing (scRNA-seq) of bone marrow and peripheral blood from MG patients during acute exacerbations, combined with experimental autoimmune myasthenia gravis (EAMG) mouse models and clinical cohort analyses, to investigate the potential involvement of a neutrophil-B-cell activating factor (BAFF) -plasma cell axis. The results reveal that, during MG acute exacerbation, bone-marrow neutrophils exhibit significantly enhanced maturation. Upon migration to the peripheral blood, these neutrophils secrete increased amounts of BAFF, further promoting pathological B-cell differentiation and plasma cell activation. Moreover, gene knockout models and serum cytokine analyses reveal that the IFN-γ signaling pathway is a key driver of this excessive BAFF secretion, supporting the existence of a neutrophil-BAFF-plasma cell interaction relevant to MG exacerbation. Clinical data analysis shows that MG patients with high baseline neutrophil levels derive greater benefit from treatment with the BAFF/APRIL dual-target inhibitor telitacicept. Collectively, this study reveals the mechanistic link between neutrophil activation and MG exacerbation, providing insights that may inform precision-targeted immunotherapy.", "authors": ["Zhang Zhaoxu", "Dong Jingya", "Qiu Mengyuan", "Bai Jie", "Cheng Xufeng", "Song Xiaodong"], "journal": "Advanced science (Weinheim, Baden-Wurttemberg, Germany)", "entry_date": "2025/09/25 06:04", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40995750/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Peking University People's Hospital, Beijing, 100044, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 14.1}, {"pmid": "40995701", "title": "Lymphocytic colitis as a new disease possibly associated with autoimmune polyendocrine syndrome type 2 (APS-2).", "abstract": "Not required for Clinical Vignette.", "authors": ["Ziobro Lidia", "Suchy Wiktoria", "Płaczkiewicz-Jankowska Ewa", "Trofimiuk-Müldner Małgorzata", "Hubalewska-Dydejczyk Alicja"], "journal": "Endokrynologia Polska", "entry_date": "2025/09/25 05:52", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40995701/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Students' Scientific Group, Chair and Department of Endocrinology, Jagiellonian University Medical College, Krakow, Poland."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "40988756", "title": "Serum neurofilament light chain levels in myasthenia gravis patients with and without symptoms.", "abstract": "This study aimed to investigate serum neurofilament light chain (sNFL) levels in patients with myasthenia gravis (MG) and explore its potential as a biomarker for disease stratification. A total of 60 MG patients and 29 normal controls (NCs) were enrolled, with no significant differences in age or gender between the two groups. MG patients were stratified by MGFA classification, QMG scores, antibody status, phenotypic subtypes, onset age, and gender. Results showed that MG patients had significantly higher sNFL levels (median: 12.7 pg./mL) compared to NCs (median: 9.1 pg./mL; p = 0.0176). Subgroup analyses revealed that sNFL levels in MGFA-II patients (median: 13.1 pg./mL) were significantly elevated compared to NCs (p = 0.0437), with no statistical difference in MGFA-I. Patients with QMG scores 7-15 (median: 13.4 pg./mL) had higher sNFL levels than those with scores 0-6 (p = 0.0207) and showed significant differences from NCs (p = 0.0023). Late-onset MG (LOMG) patients (median: 13.4 pg./mL) had higher sNFL levels than early-onset cases (p = 0.0368), and age was mildly correlated with sNFL in MG (p = 0.0477). ROC analysis showed moderate diagnostic performance of sNFL for distinguishing LOMG vs. NCs (>50 years) was 0.9464 (specificity 89.29%, sensitivity 90%), and for female MG vs. female NCs was 0.8091. In conclusion, sNFL levels are elevated in MG patients, particularly in severe and late-onset cases, suggesting its potential as a biomarker for disease stratification and severity assessment.", "authors": ["Lv Jie", "Liu Ruichen", "Sun Zhan", "Zhang Jing", "Zhang Yingna", "Zhao Xue", "Liu Jing", "Zhou Xinyue", "Zhang Mengdi", "Liu Qian", "Gao Feng"], "journal": "Frontiers in medicine", "entry_date": "2025/09/24 05:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40988756/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "40985852", "title": "Identification of High-Risk Population for Mortality and Severe Clinical Outcomes Among Patients With Myasthenia Gravis: A Nationwide Population-Based Cohort Study in Korea.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare chronic neurological condition characterized by skeletal muscle weakness and fatigue. Some patients with MG have poorly controlled symptoms with conventional treatments. While new treatments could be considered in patients with poorly controlled MG, their costs are considerably higher and may impose a financial burden on patients and the national health insurance system. Therefore, we sought to identify high-risk populations for mortality and severe clinical outcomes among MG patients to effectively allocate health resources.\nMETHODS: A population-based cohort study was conducted using the Health Insurance Review and Assessment database from South Korea (2007-2023). Among patients with incident MG, we defined six clinical criteria expected to be associated with poor prognosis of MG. Separate study cohorts were constructed for the history of each criterion within two years of the first MG diagnosis to compare the risk of mortality, myasthenic crisis (MC), intensive care unit (ICU) admission, and MG-related hospitalization between patients. To adjust for any potential confounding, each covariate was assessed for inclusion in a multivariate Cox proportional hazards model, and findings were presented using hazard ratios (HRs) and 95% confidence intervals (CIs).\nRESULTS: We identified 10,458 patients with incident MG (54.2% aged over 60 years; 56.8% female), of whom 361 and 319 were defined as MG patients with history of MC and refractory MG, respectively. Among MG patients, patients with history of any of the predefined clinical criteria showed worse prognosis than those without. Patients with a history of MC had a significantly higher risk of mortality compared to those without (54.0 vs. 17.9 per 1,000 person-year; HR, 2.33; 95% CI, 1.87-2.89). Similarly, across six different criteria, including refractory MG, the risk of serious clinical outcomes, defined MC, ICU admission, and MG-related hospitalization were increased in patients who met the criteria versus those who didn't.\nCONCLUSION: Our study identified high-risk populations among patients with MG. Patients with a history of certain clinical criteria, including MC or refractory MG, had elevated risk of mortality and severe clinical outcomes. These findings may be utilized to establish the reimbursement strategy by identifying MG patients with a priority need for new treatments.", "authors": ["Woo Jieun", "Kim Seung Woo", "Kim Ju Hwan", "Yuk Jayeon", "Jung Kyungyeon", "Cho Yongtai", "Park Yeongmin", "Shin Ju-Young", "Shin Ha Young"], "journal": "Journal of Korean medical science", "entry_date": "2025/09/23 09:54", "pub_date": "2025-09-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40985852/", "pub_types": ["Journal Article"], "affiliations": ["Department of Biohealth Regulatory Science, Sungkyunkwan University, Suwon, Korea."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "40983285", "title": "Management of Autoimmune Conditions Associated With Thymic Epithelial Tumors.", "abstract": "Thymic epithelial tumors are associated with diverse autoimmune manifestations, with 30% to 50% of patients developing at least one autoimmune condition. The pathogenesis involves thymic dysfunction leading to impaired T-cell development and self-tolerance. Myasthenia gravis is the most common, followed by less frequent but notable conditions including pure red cell aplasia, Good's syndrome, and various neurologic, dermatologic, and systemic autoimmune disorders. Management requires a coordinated multidisciplinary approach focusing on both the underlying thymoma and the specific autoimmune manifestations. Surgical intervention through thymectomy remains a cornerstone of treatment, particularly for myasthenia gravis, where it can lead to considerable symptomatic improvement. However, autoimmune conditions may persist or even develop after thymectomy, necessitating disease-specific approaches with systemic immunosuppression. In this review, we discuss the various autoimmune manifestations of thymoma, along with respective information on patient outcomes and treatment strategy. Recent advances in targeted therapies and immunomodulation offer new treatment options, though further research is needed to establish optimal management strategies for this complex patient population.", "authors": ["Haque Waqas", "Pietroluongo Erica", "Fatima Juwairiyyah", "De Placido Pietro", "Imran Hiba", "Rana Iemaan", "Haque Eman", "Bestvina Christine", "Garassino Marina"], "journal": "Journal of thoracic oncology : official publication of the International Association for the Study of Lung Cancer", "entry_date": "2025/09/22 19:39", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40983285/", "pub_types": ["Journal Article", "Review", "Research Support, Non-U.S. Gov't"], "affiliations": ["Department of Medicine, Section of Hematology Oncology, Thoracic Oncology Program, The University of Chicago Medicine, Chicago, Illinois. Electronic address: Waqas.Haque@uchicagomedicine.org."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 16.4, "journal_quartile": "1区"}, {"pmid": "40979273", "title": "Thymolipoma as a Rare Cause of Myasthenia Gravis.", "abstract": "We present two cases of a rare thymic tumor presenting with ocular myasthenia gravis. Patient A was a male in his 40s who presented with bilateral diplopia. Investigations revealed negative myasthenic antibodies and positive jitter on single fiber electromyography. Patient B was a female in her 20s who presented with bilateral and fluctuating ptosis and diplopia, and was found to have positive acetylcholine receptor antibodies. Both patients demonstrated thymic hyperplasia on computed tomography chest and underwent robotic thymectomy. Pathology of the excised thymic tissue confirmed thymolipoma. We discuss the incidence, presentation, and management of thymolipomatous myasthenia gravis and present robotic thymectomy as a minimally invasive surgical treatment for thymolipoma.", "authors": ["Lee Natalie Si-Yi", "Bassin Levi", "Ahmad Kate"], "journal": "Neuro-ophthalmology (Aeolus Press)", "entry_date": "2025/09/22 08:02", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40979273/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Royal North Shore Hospital, Sydney, Australia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6}, {"pmid": "40977954", "title": "Post-Marketing Safety Concerns with Efgartigimod alfa: A Pharmacovigilance Analysis Based on the Food and Drug Administration Adverse Event Reporting System Database.", "abstract": "AIM: Efgartigimod alfa (EA) is a novel US Food and Drug Administration (FDA) approved neonatal Fc receptor-targeting drug; however, its real-world adverse event (AE) profile remains underexplored.\nMETHODS: AE reports primarily related to EA were retrieved from the US FDA Adverse Event Reporting System database for the fourth quarter of 2021 to the third quarter of 2024. Disproportionality analysis using Reporting Odds Ratio (ROR), Proportional Reporting Ratio (PRR), Bayesian Confidence Propagation Neural Network, and Multi-item Gamma Poisson Shrinker algorithms was employed to detect signals of AEs.\nRESULTS: Our study processed 3,182 AE reports related to EA, revealing 57 signals that met the criteria of the ROR, PRR, Bayesian Confidence Propagation Neural Network, and Multi-item Gamma Poisson Shrinker algorithms across 14 system organ classes. Notably, the most significant signal in the System Organ Class was \"Surgical and medical procedures\", whereas the most significant signal in Preferred Term was \"Bulbar Palsy\". Some unexpected over-the-counter AEs, including falls, choking, sepsis, nephrolithiasis, and atrial fibrillation, were also observed. The median onset time of EA-related AEs was 101.5 d (interquartile range 27-260). The AE risk model associated with EA should be referred to as \"early failure\", with the likelihood of AEs decreasing over time.\nCONCLUSION: This study highlights the potential AEs and risks associated with the clinical use of EA; the analysis provides significant evidence regarding the clinical safety of EA.", "authors": ["Huang Jinlong", "Ye Hanyun", "Lin Jingyang", "Luo Dan", "Huang Ping", "Zheng Xiaochun"], "journal": "Clinical epidemiology", "entry_date": "2025/09/22 07:40", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40977954/", "pub_types": ["Journal Article"], "affiliations": ["Center for Clinical Pharmacy, Cancer Center, Department of Pharmacy, Zhejiang Provincial People's Hospital (Affiliated People's Hospital), Hangzhou Medical College, Hangzhou, Zhejiang, People's Republic of China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "40971137", "title": "Treatment Preferences of Neurologists in Generalized Myasthenia Gravis: A Conjoint Analysis Study.", "abstract": "INTRODUCTION: Generalized myasthenia gravis (gMG) is a chronic autoimmune neuromuscular disorder for which treatment decision-making is increasingly complex due to the emergence of biologic targeted therapies. This study aimed to evaluate neurologists' treatment preferences in acetylcholine receptor seropositive gMG using conjoint analysis to simulate real-world clinical decision-making.\nMETHODS: We conducted a cross-sectional, web-based study among neurologists involved in the management of gMG in collaboration with the Spanish Society of Neurology. Participants were presented with eight hypothetical treatment scenarios comprising five key attributes: intensity of improvement, onset of action, duration of effect, adverse events, and route/frequency of administration. Utility values and importance of each attribute were estimated using ordinary least squares regression. Demographic, professional, and behavioral characteristics were assessed to explore variability in preference patterns.\nRESULTS: A total of 149 neurologists participated in the study. The mean age was 39.0 (SD 9.4) years, and 54.4% were male. Participants had a mean of 9.9 years (8.4) of experience treating patients with MG. The most valued treatment attribute was intensity of improvement (mean relative importance: 38.6%), followed by onset of action (21.5%) and duration of effect (17.4%). At the individual level, route and frequency of administration accounted for up to 21.9% of decision weight in some participants. Preferences were consistent across neuromuscular specialists and general neurologists but differed based on empathy and conscientiousness. Model fit was robust (Pearson's R = 1.000, p < 0.001).\nCONCLUSIONS: Neurologists treating gMG placed the highest value on rapid and clinically meaningful symptom improvement, consistent with the therapeutic goals of emerging targeted therapies. However, substantial heterogeneity in preferences, especially regarding administration burden, emphasizes the need for individualized approaches and shared decision-making.", "authors": ["Querol Luis", "Gómez-Ballesteros Rocío", "Gutiérrez-Gutiérrez Gerardo", "Ares Adrián", "Villaverde Ramón", "Reyes Virginia", "Armangué Thaís", "Salas Elisa", "Díaz-Abós Paola", "Rebollo Pablo", "Sarmiento Mònica", "Canal Neus", "Maurino Jorge", "Cortés-Vicente Elena"], "journal": "Neurology and therapy", "entry_date": "2025/09/19 11:24", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40971137/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Hospital de la Santa Creu i Sant Pau, Barcelona, Spain."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "40970182", "title": "Pyridostigmine improves hand grip strength in patients with myalgic encephalomyelitis/chronic fatigue syndrome.", "abstract": "BACKGROUND: Myalgic encephalomyelitis/chronic fatigue syndrome (ME/CFS) is a multisystemic disease characterized by exertional intolerance and fatigue which is often accompanied by muscle weakness and fatiguability. A study showed efficacy of the acetylcholinesterase inhibitor pyridostigmine on cardiac output in ME/CFS patients. Pyridostigmine is currently used off-label in ME/CFS and postural orthostatic tachycardia syndrome.\nMETHODS: We evaluated the effect of pyridostigmine on hand grip strength in 20 patients with post-infectious ME/CFS. Hand grip strength testing was performed ten times using an electric dynamometer and was repeated after 1 h. In a second test, 30 mg of pyridostigmine was given immediately after the first measurement. Orthostatic function was assessed using a passive standing test. Neurological examination and autoantibody testing were performed to rule out a diagnosis of myasthenia gravis.\nRESULTS: All patients had reduced maximum hand grip strength with a median of 16.45 kg (IQR: 11.45 kg-22.8 kg). Hand grip strength was diminished by a median of 4.65 kg after 1 h. In contrast, 1 h after pyridostigmine administration, patients showed an improvement in maximum hand grip strength with a median increase of 2.6 kg. The maximum hand grip strength after exertion was about 1.5-fold higher with then without pyridostigmine (p = 0.01). The increase in heart rate from lying to standing was median 17 beats per minute without pyridostigmine (IQR: 13 beats per minute - 23 beats per minute) and 13 beats per minute (IQR: 9 beats per minute - 20 beats per minute) (p = 0.017) with pyridostigmine. None of the patients tested positive for myasthenia gravis specific autoantibodies.\nCONCLUSION: Pyridostigmine exerts an immediate effect on muscle strength and orthostatic function. This may be attributed to increased acetylcholine availability at neuromuscular junctions, and its augmentation of parasympathetic tone.", "authors": ["Schlömer Ella", "Stein Elisa", "Kedor Claudia", "Rust Rebekka", "Brock Anna", "Wittke Kirsten", "Scheibenbogen Carmen", "Kim Laura"], "journal": "Frontiers in neuroscience", "entry_date": "2025/09/19 05:12", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40970182/", "pub_types": ["Journal Article"], "affiliations": ["Institute of Medical Immunology, Charité-Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt-Universität zu Berlin, Augustenburger Platz, Berlin, Germany."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "40968776", "title": "Feasibility of Subcutaneous Immunoglobulin Therapy as the Maintenance Therapy in Patients with Autoimmune Neuromuscular Disease: A Prospective Study.", "abstract": "Long-term immunoglobulin therapy is crucial for several neuromuscular disorders (NMD). Recently, subcutaneous immunoglobulin (SCIg) has become an alternate to intravenous immunoglobulin (IVIg) for maintenance therapy to address limitations. This prospective study assessed the feasibility of SCIg as maintenance therapy for various NMDs after transitioning from IVIg. Overall, the mean monthly immunoglobulin dose remained stable or reduced after transition while maintaining efficacy. Participants reported significantly fewer side effects (29.2 % vs. 66.7%) with SCIg. Compliance with self-infusion and dosing regimen with SCIg was high, with no product wastage. The study shows SCIg therapy has distinct advantages over IVIg and should be considered for NMD patients requiring maintenance therapy.", "authors": ["Hussain Faraz S", "Siddiqi Zaeem A"], "journal": "The Canadian journal of neurological sciences. Le journal canadien des sciences neurologiques", "entry_date": "2025/09/19 04:13", "pub_date": "2025-09-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40968776/", "pub_types": ["Journal Article"], "affiliations": ["Division of Neurology, Department of Medicine, Faculty of Medicine and Dentistry, University of Albertahttps://ror.org/0160cpw27, Edmonton, Canada."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.2, "journal_quartile": "4区"}, {"pmid": "40966533", "title": "Correlation of C-Reactive Protein With Severe Fatigue in Patients With Myasthenia Gravis.", "abstract": "BACKGROUND AND OBJECTIVES: Most patients with myasthenia gravis (MG) suffer from fatigue, which can be defined as a subjective lack of energy and difficulty in initiating or sustaining voluntary activities. This is conceptually different from muscle weakness or muscle fatigability. Fatigue is one of the most reported symptoms in MG and has been hypothesized to be an innate mechanism to minimize muscle activity in order to protect muscles from (further) damage. The exact pathophysiology of fatigue remains unclear, and it is very likely a multifactorial phenomenon. The aim of this study was to provide a better understanding on the pathophysiology of fatigue in MG.\nMETHODS: We analyzed 38 serum biomarkers including various cytokines and myokines in a cohort of 116 anti-acetylcholine receptor-positive patients with MG. A multivariate linear regression analysis for each biomarker was performed in search for a correlation with fatigue. The following preselected covariates were included in the primary analysis: sex, age, disease severity, depression and anxiety scores, nonsteroid immune suppressive medication, and cumulative prednisone dosage in the past 6 months.\nRESULTS: Severe fatigue was present in 64% of patients. Results show a robust correlation between fatigue and C-reactive protein (CRP) in the primary analysis. This correlation persisted when additionally adjusting for BMI, strenuous physical activities, and hemoglobulin levels.\nDISCUSSION: Our findings suggest that chronic low-grade inflammation, mediated by CRP, contributes to the pathogenesis of fatigue in MG. This aligns with the hypothesis that local peripheral inflammatory processes induce systemic inflammatory cascades responsible for fatigue.", "authors": ["Ruiter Annabel M", "van Meijgaarden Krista E", "Joosten Simone A", "Spitali Pietro", "Huijbers Maartje G", "van Zwet Erik W", "Badrising Umesh A", "Tannemaat Martijn", "Verschuuren Jan J"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/09/18 16:03", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40966533/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Leiden University Medical Center, the Netherlands."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "40963855", "title": "Surgical management of suspected paraneoplastic myasthenia gravis in rectal cancer during neoadjuvant immunotherapy: a case report.", "abstract": "Colorectal cancer is among the most common malignancies of the gastrointestinal tract. Immune checkpoint inhibitors (ICIs) have become a key component in the treatment of locally advanced rectal cancer (LARC), offering promising therapeutic outcomes. However, ICIs can occasionally cause significant adverse effects. Herein, we report a case of rectal cancer with suspected paraneoplastic myasthenia gravis (pMG) induced by immune checkpoint inhibitors (ICIs). Unfortunately, the patient lacked anti-acetylcholine receptor (AChR)/muscle-specific kinase (MuSK) antibody testing and muscle biopsy, which precluded a definitive diagnosis of pMG. Remarkably, following surgical resection, the patient not only achieved complete tumor eradication but also experienced full remission of myasthenia gravis (MG).", "authors": ["Xia Zhiyuan", "Chen Haining", "Qiu Ming", "Huang Wei", "Li Hui", "Lin Minglin", "Zhang Sen"], "journal": "Frontiers in oncology", "entry_date": "2025/09/18 04:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40963855/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Colorectal and Anal Surgery, The First Affiliated Hospital of Guangxi Medical University, Nanning, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "40960093", "title": "Nipocalimab Dose Selection in Generalized Myasthenia Gravis.", "abstract": "Nipocalimab is a fully human immunoglobulin G (IgG)1 monoclonal antibody (mAb) designed to selectively block the IgG binding site of neonatal fragment crystallizable receptor (FcRn) to inhibit IgG recycling and decrease circulating IgG, including pathogenic IgG autoantibodies (such as antiacetylcholine receptor, anti-muscle-specific kinase, and anti-low-density lipoprotein-related protein 4 antibodies in generalized myasthenia gravis [gMG]). A mechanistic model, integrating serum nipocalimab concentrations, FcRn occupancy, and total serum IgG data from five phase 1 studies in healthy adult participants and one phase 2 (Vivacity-MG) study in adult participants with gMG, was developed. The relationship between total serum IgG reduction and placebo-corrected MG-Activities of Daily Living score change from baseline in participants with gMG was also characterized. Nipocalimab exhibited nonlinear target (FcRn)-mediated disposition, causing rapid, reversible, and concentration-dependent FcRn occupancy and IgG reduction (up to 85%) in healthy participants and participants with gMG. The PK of nipocalimab after a single intravenous (IV) administration is consistent with that after repeated IV administrations, with no accumulation following every 2 weeks (Q2W) dosing. The PK of nipocalimab and its effect on IgG reduction were similar between healthy participants and participants with gMG. Model-based simulations indicated that the IV dose of 15 mg/kg Q2W, starting 2 weeks after a 30 mg/kg IV loading dose, was the lowest Q2W maintenance dose predicted to achieve the target of 70% median of the average change in IgG reduction in participants with gMG and was the recommended dose for the pivotal phase 3 Vivacity-MG3 study in a gMG population.", "authors": ["Valenzuela Belén", "Neyens Martine", "Zhu Yaowei", "Ramchandren Sindhu", "Dosne Anne-Gaëlle", "Leu Jocelyn H", "Faelens Ruben", "Ling Leona E", "Pérez-Ruixo Juan-José"], "journal": "CPT: pharmacometrics & systems pharmacology", "entry_date": "2025/09/17 07:03", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40960093/", "pub_types": ["Journal Article", "Clinical Trial, Phase I"], "affiliations": ["Johnson & Johnson, Madrid, Spain."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.0, "journal_quartile": "3区"}, {"pmid": "40958409", "title": "Anxiety in Myasthenia Gravis Patients Throughout the COVID-19 Pandemic-Prevalence, Risk Factors, and Association With Vaccination Status.", "abstract": "INTRODUCTION: A high prevalence of COVID-19-related anxiety was observed among the general population during the COVID-19 pandemic. Patients with myasthenia gravis (MG) might be at higher risk for COVID-19-related anxiety due to immunosuppressive therapy in the majority of cases and risk of myasthenic exacerbation in case of an infection. This prospective longitudinal study assessed COVID-19-related anxiety in MG patients over 2 years of the pandemic and its association with MG-specific factors (e.g., disease severity, immunosuppressive medication) and with vaccination status.\nMETHODS: A three-wave longitudinal online survey was conducted from May 2020 to February 2022, including a total of 648 adult MG patients. Descriptive, univariate, and multivariate analyses were performed to assess COVID-19-related and MG-related anxiety, associated MG-specific factors, and association with vaccination status.\nRESULTS: COVID-19-related anxiety was frequent, with the most pronounced fear being risk for one's own health (overall 83.9%). Anxiety was influenced by MG diagnosis (overall 75.1%), especially by fear of exacerbation of myasthenic symptoms and greater risk of infection due to immunosuppressive therapy. Female sex and treatment with immunosuppressive medication, including rituximab, were associated with an increased concern for one's own health. Fear for one's own health was the only factor associated with vaccination status.\nCONCLUSIONS: COVID-19-related anxiety was prevalent among MG patients. An ongoing psychological impact is likely and highlights the need for anxiety screening in clinical practice. Our findings emphasize the importance of addressing mental health challenges during future pandemics.", "authors": ["Beckmann Janna", "Petzold Moritz", "Betzler Felix", "Ströhle Andreas", "Bendau Antonia", "Dusemund Carla", "Petzold Gabor C", "Meisel Andreas", "Hoffmann Sarah"], "journal": "Brain and behavior", "entry_date": "2025/09/17 01:34", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40958409/", "pub_types": ["Journal Article"], "affiliations": ["Department of Vascular Neurology, University Hospital Bonn, Bonn, Germany."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40955898", "title": "Anagen Effluvium as an Early Sign of Azathioprine Toxicity.", "abstract": "Azathioprine is a purine analog which is Food and Drug Administration (FDA) approved for organ transplant and severe rheumatoid arthritis (RA). Off-label use in dermatological diseases like immunobullous diseases, atopic dermatitis, autoimmune connective tissue disorders like systemic lupus erythematosus (SLE) and dermatomyositis, and other medical conditions like Crohn's disease, Churg-Strauss syndrome, and myasthenia gravis has long been in the picture.1-3 The active metabolite of this prodrug is 6-thioguanine (6-TG), which gets incorporated into DNA/RNA structure, causing decreased purine metabolism resulting in its immunosuppressive effect. Thiopurine methyltransferase (TPMT) converts 6-mercaptopurine (6-MP) to an inactive metabolite. TPMT deficiency will cause increased conversion of 6-MP to active metabolite 6-TG, which increases the risk of myelosuppression, one of the life-threatening side effects of the drug.1,2.", "authors": ["Kaur Sehtaj", "Mittal Asit Kumar", "Jain Shaifali", "Kumar Laxman"], "journal": "The Journal of the Association of Physicians of India", "entry_date": "2025/09/16 07:50", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40955898/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Postgraduate Junior Resident, Department of Dermatology, RNT Medical College, Udaipur, Rajasthan, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "40950289", "title": "YiQiWenShen formula ameliorates myasthenia gravis through T follicular helper cells/T follicular regulatory cells immune rebalancing.", "abstract": "BACKGROUND: Myasthenia gravis (MG), a chronic autoimmune neuromuscular disorder characterized by muscle weakness, remains a therapeutic challenge. This study aimed to evaluate the efficacy of the traditional Chinese herbal formulation YiQiWenShen (YQWS) in comparison with prednisone in a rat model of experimental autoimmune myasthenia gravis (EAMG), with the goal of exploring new therapeutic strategies.\nMETHODS: EAMG was induced in rats, who were subsequently treated with different doses of YQWS and prednisone. Clinical severity was assessed using the Baggi scoring system, alongside measurements of body weight, serum acetylcholine receptor antibody (AChR-Ab) levels, and splenic lymphocyte proliferation in response to the rat AChRα97-116 peptide and concanavalin A. Cytokine profiles, proportions of T follicular helper (Tfh) cells, T follicular regulatory (Tfr) cells, and germinal center B (GC)-B cells in lymph nodes were analyzed using enzyme-linked immunosorbent assay and flow cytometry. The expression levels of B-cell lymphoma 6 (Bcl-6) mRNA and protein were analyzed using quantitative real-time polymerase chain reaction and western blot, respectively.\nRESULTS: After EAMG induction, the rats exhibited significant weight loss, elevated clinical scores, and increased AChR-Ab levels. Both YQWS and prednisone treatments significantly improved body weight and clinical scores, and reduced serum AChR-Ab levels. YQWS also attenuated the increased splenic lymphocyte proliferation. Cytokine dysregulation observed in EAMG rats was partially corrected following YQWS treatment. Furthermore, both YQWS and prednisone effectively normalized the Tfh/Tfr cell ratio, decreased GC-B cell populations, and downregulated Bcl-6 expression.\nCONCLUSION: YQWS exerts therapeutic effects in EAMG comparable to those of prednisone, demonstrating its potential as an alternative treatment for MG. Its efficacy is associated with the normalization of body weight, modulation of immune responses, correction of cytokine imbalances and reestablishment of Tfh/Tfr and GC-B cell homeostasis.", "authors": ["Rao Kaihua", "Li Zhengfeng", "Huang Chunhua"], "journal": "American journal of translational research", "entry_date": "2025/09/15 07:54", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40950289/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Affiliated Hospital of Jiangxi University of Traditional Chinese Medicine Nanchang 330006, Jiangxi, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "40949470", "title": "Atezolizumab-induced neuromuscular syndrome mimicking myasthenia gravis in a patient with hepatocellular carcinoma - an area of concern.", "abstract": "BACKGROUND: Atezolizumab is an immune checkpoint inhibitor that has been approved for several neoplasms including advanced hepatocellular carcinoma. It is also capable of inducing adverse events involving the nervous system in susceptible individuals.\nCASE PRESENTATION: We report a case of myasthenia gravis, occurring in a 64-year-old patient diagnosed with hepatocellular carcinoma, who within a few months of the first-line combination use of Atezolizumab and Bevacizumab, developed worsening muscular weakness. She was managed with plasma exchange and intravenous immunoglobulin with minimal response initially, but later on, deteriorated and succumbed to the condition.\nCONCLUSION: Although uncommon, the use of Atezolizumab can either give rise to or worsen a pre-existing, latent neurological condition. These neurological immune-mediated adverse events can prove to be debilitating or even life-threatening if not timely treated, thus warranting prompt investigation by the physicians for proper diagnosis and management.", "authors": ["Samar Mirza Rameez", "Naviwala Mohammad Saad Salim", "Abdy Faryal Raza", "Shahzadi Mehwish"], "journal": "Ecancermedicalscience", "entry_date": "2025/09/15 07:42", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40949470/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Oncology, The Aga Khan University, Karachi 74600, Pakistan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "40949050", "title": "Practitioner's perception of myasthenia gravis management recommendations in clinical practice: a cross-sectional survey study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic, fluctuating disease whose unique natural history complicates designing therapeutic trials. The evidence on which many MG management recommendations are based is limited.\nOBJECTIVE: To determine the degree of knowledge, agreement, and application of internationally recognized recommendations for managing MG in actual practice.\nDESIGN: A cross-sectional survey was conducted among Spanish neurologists specializing in MG.\nMETHODS: The survey assessed knowledge, agreement, and application of recommendations, along with the degree of agreement with international consensus definitions from the Myasthenia Gravis Foundation of America.\nRESULTS: Fifty-three neurologists (mean age 45.4 years, 53% men) attended an average of 3.6 patients with MG daily. In 40 out of 61 recommendations, at least 90% of the neurologists were aware of the recommendation. The least known recommendations dealt with juvenile MG and MG in pregnancy. There was no majority agreement in two recommendations (for MG in pregnancy and the use of intravenous immunoglobulin in mild or ocular MG). The implementation of the recommendations was high except for the ones related to plasma exchange, thymectomy, methotrexate, or eculizumab.\nCONCLUSION: The recommendations are well-known, agreed upon, and applied. However, the evidence, consensus, and knowledge dissemination need reinforcement regarding aspects such as the management of juvenile MG, MG in pregnancy, or the use of certain treatments.\nHow healthcare professionals understand and use treatment guidelines for myasthenia gravis in everyday medical practice Myasthenia gravis (MG) is a long-term disease that comes and goes, making it hard to design treatment studies. Many treatment guidelines for MG are based on limited scientific evidence. This study asked neurologists in Spain how well they know, agree with, and use international MG treatment recommendations in their daily work. Fifty-three neurologists who regularly treat MG patients completed a survey. Most were familiar with the guidelines—over 90% knew about 40 of the 61 recommendations. However, some topics, like MG in children and during pregnancy, were less well-known. There was also some disagreement about when to use certain treatments, like intravenous immunoglobulin in mild cases. Most recommendations were widely followed, but a few, such as those involving plasma exchange, thymectomy, or certain drugs like methotrexate and eculizumab, were used less often. In summary, most neurologists know and follow the MG treatment guidelines, but more research and clearer guidance are needed for specific situations like treating children, pregnant women, and using certain therapies.", "authors": ["Cortés-Vicente Elena", "Guerrero-Sola Antonio", "Caballero-Martínez Fernando", "Campos-Lucas Francisco Javier", "Gómez-Salgado Juan", "Monge-Martín Diana", "Álvarez-Velasco Rodrigo"], "journal": "Therapeutic advances in chronic disease", "entry_date": "2025/09/15 07:39", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40949050/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Diseases Unit, Department of Neurology, Hospital de la Santa Creu i Sant Pau, Barcelona, Spain."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40949001", "title": "Aseptic Meningitis Following Rozanolixizumab in a Patient With Refractory Anti-MuSK Positive Myasthenia Gravis: A Case Report.", "abstract": "Rozanolixizumab is a neonatal Fc receptor (FcRn) blocker recently approved for treating generalized myasthenia gravis (gMG), particularly in patients who are anti-AChR or anti-MuSK antibody positive. Although clinical trials have demonstrated a favorable safety profile, rare adverse neurological effects remain underreported. A 36-year-old woman with refractory anti-MuSK-positive generalized myasthenia gravis received an infusion of rozanolixizumab after failing to respond to corticosteroids and azathioprine. 5 days post-infusion, she presented with an acute-onset headache, nausea, vomiting, photophobia, phonophobia, and neck stiffness. Cerebrospinal fluid (CSF) analysis revealed a white blood cell count of 150 cells/μL with 90% neutrophils, normal protein, and glucose levels. The infectious meningitis and encephalitis panel was negative. She was managed supportively, and her symptoms resolved over the following week without antimicrobial therapy. This case suggests a possible link between Rozanolixizumab and aseptic meningitis. Clinicians should be aware of this potential adverse effect and consider drug-induced etiologies in similar clinical scenarios. Early recognition may prevent unnecessary treatment and hospitalizations.", "authors": ["Maqsood Hamza", "Fleming James"], "journal": "The Neurohospitalist", "entry_date": "2025/09/15 07:38", "pub_date": "2025-09-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40949001/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, University of Tennessee Health Science Center, Chattanooga, TN, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40948685", "title": "Possible effects of anti-interleukin-17 agents on erythrodermic psoriasis with thymoma: A case report.", "abstract": "", "authors": ["Jia Qiuyu", "Hu Jian", "Zhang Jianzhong", "Wang Xiaojie", "Li Houmin"], "journal": "JAAD case reports", "entry_date": "2025/09/15 07:35", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40948685/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Dermatology, Peking University People's Hospital, Beijing, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "40946449", "title": "The management of Lambert Eaton syndrome in the setting of hypertensive disorders of pregnancy: A literature review.", "abstract": "OBJECTIVE: To review the literature regarding the management of Lambert Eaton Myasthenic Syndrome (LEMS) in pregnancy, with a focus on the clinical challenges posed by coexisting hypertensive disorders, including preeclampsia and the routine use of magnesium sulfate for seizure prophylaxis.\nDATA SOURCES: A systematic search of PubMed, Embase, Web of Science, and Scopus was conducted through May 2024 using combinations of keywords and MeSH terms including \"Lambert Eaton Myasthenic Syndrome,\" \"LEMS,\" \"pregnancy,\" \"preeclampsia,\" \"magnesium sulfate,\" and \"hypertensive disorders of pregnancy.\"\nSTUDY ELIGIBILITY CRITERIA: Studies were included if they reported pregnancy outcomes, maternal complications, or management considerations in patients with LEMS or related myasthenic syndromes. Exclusion criteria included non-English language publications, animal studies, and review articles without case-level data. Study appraisal and synthesis methods Studies were appraised based on relevance to Lambert-Eaton Myasthenic Syndrome in pregnancy, with particular attention to hypertensive complications and seizure prophylaxis strategies. Due to the rarity of this condition, included articles were primarily case reports and case series. Data were synthesized using a qualitative narrative approach, focusing on clinical presentation, interventions, and maternal-neonatal outcomes. Studies involving myasthenia gravis were also reviewed for comparison, given overlapping neuromuscular risks. No formal risk-of-bias assessment or statistical pooling was conducted due to heterogeneity and limited sample size.\nRESULTS: Twenty-four citations were included, encompassing case reports, case series, and retrospective analyses. Of these, 5 (21%) specifically involved LEMS during pregnancy, and 2 (8%) reported transient neonatal LEMS. Magnesium sulfate was discussed in 3 (13%) studies, with at least one case documenting exacerbation of neuromuscular symptoms. Two cases involved the co-occurrence of preeclampsia and LEMS, highlighting the dilemma of balancing seizure prophylaxis with neuromuscular safety. No standardized treatment protocols were identified. Multidisciplinary care and individualized decision-making were emphasized across reports.\nCONCLUSIONS: The intersection of LEMS and hypertensive disorders of pregnancy is clinically complex and underreported. The use of magnesium sulfate-a cornerstone of preeclampsia management-poses a potential risk for patients with LEMS, underscoring the need for heightened awareness, individualized treatment plans, and multidisciplinary collaboration. Further research is needed to establish safe, evidence-based guidelines for managing this rare but high-risk patient population.", "authors": ["Friedlich Nicole", "Slear Elizabeth", "Faszholz Alicia", "Bleich April"], "journal": "Pregnancy hypertension", "entry_date": "2025/09/14 18:06", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40946449/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Kaiser Permanente Medical Center Los Angeles Medical Center, Department of Obstetrics and Gynecology, Los Angeles, CA, USA. Electronic address: Nicole.X.Friedlich@kp.org."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "40945804", "title": "Regarding the \"Efgartigimod versus standard of care in new-onset AChR subtype generalized myasthenia gravis: A prospective cohort study\".", "abstract": "", "authors": ["Li Hai-Feng", "Hu Shi-Min", "Han Wei", "Guo Yan-Su"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2025/09/13 19:17", "pub_date": "2025-09-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40945804/", "pub_types": ["Letter"], "affiliations": ["Department of Neurology, Xuanwu Hospital, Capital Medical University, No. 45 Changchun Road, Xicheng District, Beijing 100053, China. Electronic address: drlhf@163.com."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "40945233", "title": "Repetitive nerve stimulation normalization after FcRn inhibitor therapy in refractory myasthenia gravis: A case report.", "abstract": "", "authors": ["Wijesinghe Rajiv", "Shao Richard Yitong", "Lin Gaven", "Silsby Matthew"], "journal": "Clinical neurophysiology : official journal of the International Federation of Clinical Neurophysiology", "entry_date": "2025/09/13 18:07", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40945233/", "pub_types": ["Letter"], "affiliations": ["Neurophysiology and Neurology Departments, Westmead Hospital, Sydney, Australia."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "40945202", "title": "A Rare Case of Juvenile Myasthenia Gravis With Low-Density Lipoprotein Receptor-Related Protein 4 Antibodies in a Seven-Year-Old Boy.", "abstract": "", "authors": ["Kandilakis Charalampos L", "Gkentzi Despoina", "Pelekouda Polyxeni"], "journal": "Pediatric neurology", "entry_date": "2025/09/13 18:06", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40945202/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pediatrics, University General Hospital of Patras, Medical School, University of Patras, Patras, Greece. Electronic address: up1084138@ac.upatras.gr."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "40940171", "title": "Association of British Neurologists (ABN) autoimmune myasthenia gravis management guidelines (2025 update).", "abstract": "The 2025 update of the Association of British Neurologists guidelines for the management of autoimmune myasthenia gravis (MG) emphasises several points that are distinct from the 2015 guidelines based on recent research and publications. The main differences from the previous guidelines are: (1) The recommendation to prescribe daily steroids rather than the alternate day regimen is now standard practice. (2) There is a clear emphasis on the beneficial effects of early thymectomy. (3) Randomised controlled trial evidence now supports early use of rituximab (within 1 year of generalised disease onset), although the evidence is less robust, but still likely to be useful, in established treatment-refractory MG. (4) Finally, several clinical trials have been published for newer targeted therapies in MG, predominantly those that inhibit the complement and neonatal Fc gamma receptor pathways, the roles of which are being slowly established especially in patients unresponsive to conventional therapy.", "authors": ["Jacob Saiju", "Farrugia Maria Elena", "Hewamadduma Channa", "Norwood Fiona", "Hill Marguerite", "Leite Maria Isabel", "McConville John Paul", "Pinto Ashwin Arnold", "Spillane Jennifer", "Sussman Jon", "Viegas Stuart"], "journal": "Practical neurology", "entry_date": "2025/09/12 21:22", "pub_date": "2025-09-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40940171/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Institute of Immunology and Immunotherapy, University of Birmingham, Birmingham, UK s.jacob@bham.ac.uk."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "40937032", "title": "Juvenile Myasthenia Gravis Simulating Bell's Palsy in a 3-year-old Female - A Unique Clinical Presentation.", "abstract": "Myasthenia gravis (MG) is an autoimmune condition affecting the neuromuscular junction. Juvenile MG (JMG) is a subtype of pediatric MG and is reported to be a rare neurological disorder with variable presentation and difficult diagnosis. MG has been described as a great neurological mimicker having resemblance with a wide spectrum of neurological disorders. The present case is a distinctive and compelling example of JMG that manifested at a young age with a disguised presentation. Bilateral ptosis was the principal presenting symptom with mild facial droop which simulated Bell's palsy initially. The patient was finally diagnosed as JMG based on acetylcholine receptor antibody test along with ophthalmological, electrophysiological, and imaging findings. She was managed for JMG and concurrent hyperthyroidism and is being regularly monitored for the effectiveness of the treatment. This report highlights the relevance of extensive clinical history, meticulous clinical examination, and awareness of similar neurologic disorders with overlapping characteristics in order to facilitate correct diagnosis, appropriate management, and effective treatment of this condition, often described as the \"great imitator.\"", "authors": ["Gupta Sangeeta", "Gupta Mamata", "Singh Neha"], "journal": "International journal of applied & basic medical research", "entry_date": "2025/09/12 04:39", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40937032/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Physiology, All India Institute of Medical Sciences, Gorakhpur, Uttar Pradesh, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40936795", "title": "Effect of Therapeutic Plasma Exchange on Apixaban Plasma Levels.", "abstract": "Objective: Therapeutic plasma exchange (TPE) may enhance the elimination of drugs from human plasma. Removal of apixaban during TPE has not been extensively described previously. Case: This is a retrospective report of a 76-year-old man admitted to the hospital on apixaban with acute worsening of respiratory and bulbar symptoms due to myasthenia gravis. On hospital day (HOD) 1, TPE was initiated for management of myasthenic crisis. Apixaban levels were obtained before and after a TPE session on HOD 3. On HOD 3, the patient's apixaban plasma level decreased from 88 ng/mL before TPE to 81 ng/mL after. Apixaban displayed an elimination half-life of 65.5 hours with intervening TPE. Discussion/conclusions: We report no clinically significant apixaban removal in a patient undergoing TPE for myasthenic crisis. This differs from previous reports. Supplemental dosing or rescheduling of apixaban doses around TPE sessions may be unnecessary, though more data are needed.", "authors": ["Hensler David", "Burghardt Danielle"], "journal": "The Journal of pharmacy technology : jPT : official publication of the Association of Pharmacy Technicians", "entry_date": "2025/09/12 04:37", "pub_date": "2025-09-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40936795/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Pharmacy Services, Michigan Medicine, Ann Arbor, MI, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "40936410", "title": "Association of Race and Social Determinants of Health With Exacerbations in Generalized Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: While racial/ethnic disparities exist across many disease states, their influence on the risk of adverse clinical outcomes in large populations of generalized myasthenia gravis (gMG) patients has not been extensively studied. This study assessed the association between race/ethnicity and MG exacerbation risk and examined the potential role of social determinants of health (SDOH).\nMETHODS: This retrospective cohort study utilized data from HealthVerity; a large, de-identified, US insurance claims database. Eligible patients were adults with gMG (≥ 2 MG diagnosis code claims, excluding patients with only ophthalmologic specialist visits on/before index date). Inverse probability of treatment weighting using baseline variables was constructed with multinomial distribution for race/ethnicity (Asian/Black/Hispanic/White). Incidence rate ratio (IRR) for ≥ 1 MG exacerbation (defined as an inpatient episode with MG as admitting diagnosis) during follow-up was assessed using a generalized estimating equations model, using \"White\" as the reference. A subset of patients was linked with SDOH variables by residential ZIP code (income-per-capita and percentage of population without health insurance coverage) using the Agency for Healthcare Research and Quality database, and MG exacerbation risk adjusted.\nRESULTS: Of 10,981 gMG patients, 5147 had linked SDOH data. Weighted risk of MG exacerbations was significantly higher among Black versus White patients (IRR 1.21; 95% confidence interval 1.05-1.39). The association remained after controlling for income and/or health insurance coverage.\nDISCUSSION: Potential racial disparities exist in the occurrence of MG exacerbations. Further investigation of potential drivers is warranted. At-risk populations should be a focus for healthcare and patient support provision.", "authors": ["Jackson Louis", "Liu Zhiwen", "Pesa Jacqueline", "Campbell Alicia K", "Anderson Ashley E L"], "journal": "Muscle & nerve", "entry_date": "2025/09/12 03:43", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40936410/", "pub_types": ["Journal Article"], "affiliations": ["Johnson & Johnson, Horsham, Pennsylvania, USA."], "china_related": false, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40934847", "title": "Neuromyelitis optica spectrum disorders and their overlap with myasthenia gravis in a single center in Argentina.", "abstract": "BACKGROUND: The incidence of neuromyelitis optica spectrum disorder (NMOSD) in association with other autoimmune diseases is frequent. The coexistence of myasthenia gravis (MG) and NMOSD has been reported, showing a higher-than-expected likelihood of co-occurrence. The aim of this study is to describe the overlap between NMOSD and MG and to analyze these cases within two large real-world cohorts of patients with AQP4 antibody-positive NMOSD and AChR antibody-positive MG in Argentina.\nMETHODS: A cross-sectional, retrospective study was conducted at a referral center in Buenos Aires, Argentina, including patients with AQP4-Ab-positive NMOSD and AChR-Ab-positive MG.\nRESULTS: A total of 389 medical records were reviewed: 108 NMOSD and 281 MG cases. Among them, 77 patients were AQP4-IgG positive, and 207 were AChR-Ab positive. Three out of 77 AQP4-IgG-positive patients had MG with AChR-Ab positivity, accounting for 3.89% of NMOSD cases. Conversely, three out of 207 AChR-Ab-positive MG patients (1.45 %) had AQP4-IgG-positive antibodies. Patients with concurrent MG and NMOSD were female, had a late onset of NMOSD, and experienced MG onset before NMOSD. They also showed a good response to NMOSD treatment with immunosuppressive therapy. Two patients had undergone thymectomy before NMOSD onset. No patient was receiving immunosuppressive treatment at the time of NMOSD onset.\nCONCLUSIONS: A total of 3.89 % of AQP4-Ab-positive NMOSD patients had overlapping AChR-Ab-positive MG. This is the first report assessing the association between NMOSD and MG in Argentinian and Latin American (LATAM) patients.", "authors": ["Villa Andrés M", "Analisa Manin", "Guerrero Diego Alarcon", "Seimandi Carla", "Simison Conrado", "Saffe Valentina", "Aguirre Florencia"], "journal": "Multiple sclerosis and related disorders", "entry_date": "2025/09/11 18:09", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40934847/", "pub_types": ["Journal Article"], "affiliations": ["Sección de Neuroinmunología. División Neurología. Hospital Gral. de Agudos Dr. José María Ramos Mejía, Buenos Aires, Argentina; Centro Argentino de Neuroinmunología (CADENI). Facultad de Medicina, Universidad de Buenos Aires. Argentina. Electronic address: andresmariavilla@gmail.com."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "40929933", "title": "Calprotectin and neurofilament serum levels correlate with treatment response in myasthenia gravis under intensified therapy-A pilot study.", "abstract": "OBJECTIVE: New therapeutic options have recently emerged for patients with highly active, acetylcholine receptor antibody-positive (AChR-Ab+) generalized myasthenia gravis (gMG), including fast-acting, endplate-protective agents such as complement C5 inhibitors (C5-I) and neonatal Fc receptor inhibitors (FcRn-I). However, objective biomarkers beyond clinical scoring systems are lacking to guide individualized treatment decisions.\nMETHODS: In this exploratory, prospective real-world study, we assessed serum calprotectin (sCLP) and serum neurofilament light chain (sNfL) levels in a total of 22 AChR-Ab+ gMG patients, who were treatment-naïve for either C5-I or FcRn-I. Changes in biomarker levels were correlated with clinical response, as measured by the Myasthenia Gravis-Activities of Daily Living (MG-ADL) score.\nRESULTS: We observed a correlation of changes in sCLP and sNfl with clinical treatment response to C5-I and FcRn-I therapies. Specifically, rising levels of sNfL and sCLP were associated with a poor treatment response, as measured by the MG-ADL score.\nCONCLUSION: Our preliminary findings suggest that markers of systemic inflammation (such as sCLP) and local destruction of the neuromuscular junction (such as sNfL) may assist in treatment decision-making for gMG patients. Larger, multicenter studies are warranted to validate these results and define their clinical utility.", "authors": ["Stascheit Frauke", "Schulze Daniel", "Lehnerer Sophie", "Gerischer Lea", "Stein Maike", "Doksani Paolo", "Herdick Meret", "Dusemund Carla", "Mergenthaler Philipp", "Triller Paul", "Lünemann Jan D", "Hoffmann Sarah", "Meisel Andreas"], "journal": "Journal of autoimmunity", "entry_date": "2025/09/10 18:06", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40929933/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology with Experimental Neurology, Charité - Universitätsmedizin Berlin, corporate Member of Freie Universität Berlin and Humboldt Universität zu Berlin, Berlin, Germany; Neuroscience Clinical Research Center, Charité - Universitätsmedizin Berlin, corporate Member of Freie Universität Berlin and Humboldt Universität zu Berlin, Berlin, Germany. Electronic address: frauke.stascheit@charite.de."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40925732", "title": "[Expert consensus on the diagnosis and treatment of sleep-disordered breathing related to neuromuscular diseases].", "abstract": "Neuromuscular diseases are often accompanied by various types of sleep-related breathing disorders, which can exacerbate the underlying condition and are associated with a poor prognosis. Early identification is essential, and interventions such as non-invasive ventilation, oxygen therapy, and respiratory rehabilitation should be initiated promptly to mitigate disease progression and improve outcomes. Nevertheless, the rates of missed and misdiagnosed cases remain common in clinical practice. Currently, there are no standardized guidelines for the diagnosis and treatment of sleep-disordered breathing related to neuromuscular diseases in China. Therefore, based on the latest domestic and international research progress, and combined with domestic clinical diagnosis and treatment experience, the Sleep Disorder Group of Chinese Thoracic Society has brought together multidisciplinary experts to develop this expert consensus. This consensus provides a comprehensive overview of the epidemiology, clinical manifestations, diagnostic approaches, assessment strategies, and treatment of sleep-disordered breathing related to neuromuscular diseases. It formulates evidence-based recommendations to guide clinical practice, with the aim of providing standardized recommendations for their diagnosis and management.Statement 1: The neuromuscular disorders that are most frequently associated with sleep-disordered breathing include: myasthenia gravis (1A), amyotrophic lateral sclerosis (2B), post-polio syndrome (2B), myotonic dystrophy (2B), peripheral neuropathies (2C), and metabolic myopathies, among other neuromuscular conditions.Statement 2: Patients with neuromuscular disorders frequently develop multiple types of sleep-disordered breathing concurrently or sequentially, with obstructive sleep apnea (OSA) being the most prevalent manifestation. Distinct clinical manifestations of OSA are observed across different neuromuscular disease subtypes (1A).Statement 3: Neuromuscular disorders predispose to central sleep apnea (CSA), with clinical manifestations varying significantly across disease subtypes, stages of progression, and severity levels (1A).Recommendation 1: In patients with neuromuscular disorders exhibiting progressive hypercapnia or worsening hypoxemia, clinicians should investigate potential comorbid nocturnal alveolar hypoventilation and/or sleep-associated hypoxemia (1A).Recommendation 2: When sleep-disordered breathing is suspected, patients with neuromuscular disorders should be evaluated for symptoms of sleep-disordered breathing. Meanwhile, sleep monitoring, non-invasive CO2 monitoring, and related examinations should be actively performed according to the actual situation (1A). A polysomnography should be performed when there is a high clinical suspicion of sleep-disordered breathing but a negative result on a portable sleep monitor (1A).Recommendation 3: (1) Noninvasive positive pressure ventilation (NPPV) titration under polysomnography is the standard method to determine the effective treatment parameters for neuromuscular diseases with sleep-disordered breathing (1A). (2) Positive airway pressure titration in OSA patients with neuromuscular diseases should follow American Academy of Sleep Medicine (AASM) guidelines (1A). (3) For neuromuscular disorders with CSA or Cheyne-Stokes respiration, bi-level positive airway pressure (BPAP) with ST pattern is recommended (1A); When BPAP is not tolerated or accompanied by severe Cheyne-Stokes respiratory and heart failure in patients, adaptive support ventilation (ASV) should be used (2B). (4) Patients with neuromuscular disease and sleep-related alveolar hypoventilation should be treated with BPAP or variable assurance pressure support (VAPS) (1A). (5) BPAP with alternate frequency is preferred for neuromuscular disorders with \"pseudo-central events\" (1A).Recommendation 4: Oxygen therapy alone is not recommended for neuromuscular disease patients combined with sleep-disordered breathing (2D). Oxygen therapy with monitoring of CO2 level is recommended when non-invasive ventilation therapy cannot effectively correct hypoxemia (2C). Diaphragmatic pacing should not be routinely used in amyotrophic lateral sclerosis patients with respiratory failure (2B). Transvenous phrenic nerve stimulation is not currently applied to CSA caused by neuromuscular disorders (2D). Respiratory rehabilitation may improve respiratory muscle strength in a subset of patients with neuromuscular disorders (2B). Protiline can be used for REM-associated alveolar hypoventilation, and daytime sleepiness could be addressed with methylphenidate and modafinil (2C).Recommendation 5: Neuromuscular disease combined with sleep-disordered breathing is a chronic disease requiring patient-centered, individualized education and long-term follow-up management (1A).\n神经肌肉疾病易合并不同类型的睡眠呼吸障碍，使患者病情加重、预后不佳，需要早期识别，并尽早启动无创通气、氧疗、呼吸康复等治疗，但是临床上漏诊率、误诊率高。目前国内尚无神经肌肉疾病相关睡眠呼吸障碍的诊疗规范，为此，中华医学会呼吸病学分会睡眠呼吸障碍学组组织相关多学科专家，参考国内外最新研究进展和指南共识，结合临床诊治实践经验，制定《神经肌肉疾病相关睡眠呼吸障碍诊治专家共识》，旨在对神经肌肉疾病相关睡眠呼吸障碍的流行病学、临床表现、诊断思路、评估和治疗进行详细阐释，共形成3条陈述及5条推荐意见，为神经肌肉疾病相关睡眠呼吸障碍诊断和治疗提供规范化建议。陈述1：最易合并睡眠呼吸障碍的神经肌肉疾病包括重症肌无力（1A）、肌萎缩侧索硬化（2B）、脊髓灰质炎后遗症（2B）、强直性肌营养不良（2B）、周围神经病变（2C）、代谢性肌病等。陈述2：神经肌肉疾病患者常同时出现或序贯发生多种类型的睡眠呼吸障碍，合并睡眠呼吸暂停（OSA）最常见，不同类型的神经肌肉疾病合并OSA时有各自的临床特点（1A）。陈述3：神经肌肉疾病易伴有中枢性睡眠呼吸暂停（CSA），其临床表现与疾病的类型、病程及严重程度相关（1A）。推荐意见1：当神经肌肉疾病所致CO2潴留/低氧进一步加重时，应注意是否合并睡眠相关肺泡低通气症/低氧血症（1A）。推荐意见2：神经肌肉疾病患者疑似合并睡眠呼吸障碍时，应评估睡眠呼吸障碍相关症状，并根据实际情况积极进行睡眠呼吸监测、无创CO2监测和相关检查（1A）。如果临床高度怀疑有睡眠呼吸障碍但便携式睡眠监测结果为阴性，应进行全面的多导睡眠监测（PSG）检查（1A）。推荐意见3：①神经肌肉疾病合并睡眠呼吸障碍，PSG下进行无创正压通气滴定是确定有效治疗参数的标准方法（1A）；②神经肌肉疾病合并OSA，滴定应遵循美国睡眠医学会（AASM）关于OSA患者气道正压通气滴定的临床指南（1A）；③神经肌肉疾病伴有CSA或陈-施呼吸时，推荐使用带有ST模式的双水平气道正压通气（BPAP）（1A）；患者不能耐受BPAP时或伴有严重的陈-施呼吸、心力衰竭，应用伺服通气设备（2B）；④神经肌肉疾病合并睡眠相关肺泡低通气症使用BPAP或容量保证压力支持（VAPS）设备，同步监测CO2水平（1A）；⑤神经肌肉疾病合并“伪中枢事件”，首选具有备用频率的BPAP（1A）。推荐意见4：神经肌肉疾病合并睡眠呼吸障碍时不推荐单独氧疗（2D），建议在无创通气治疗不能有效纠正低氧血症时辅以氧疗，建议同时监测CO2水平（2C）。膈肌起搏不作为肌萎缩侧索硬化症呼吸衰竭患者的常规治疗（2B）。经静脉膈神经刺激尚未应用于神经肌肉疾病引起的CSA（2D）。呼吸康复可能改善一部分神经肌肉疾病患者的呼吸肌力量（2B）。快速眼动（REM）睡眠期相关肺泡低通气可应用普罗替林，日间嗜睡可应用哌醋甲酯和莫达非尼（2C）。推荐意见5：神经肌肉疾病合并睡眠呼吸障碍是一种慢性疾病，需要开展以患者为中心的个体化教育，并进行长期随访管理（1A）。.", "authors": [], "journal": "Zhonghua jie he he hu xi za zhi = Zhonghua jiehe he huxi zazhi = Chinese journal of tuberculosis and respiratory diseases", "entry_date": "2025/09/09 21:25", "pub_date": "2025-09-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40925732/", "pub_types": ["English Abstract", "Journal Article", "Consensus Statement"], "affiliations": [], "china_related": false, "study_types": ["Guideline/Consensus"], "evidence_level": null}, {"pmid": "40923143", "title": "Potential Causal Relationships Between Circulating Micronutrient Levels and Multiple Neuroimmune Diseases: A Genetic Association Analysis.", "abstract": "BACKGROUND: Growing evidence suggests a close association between circulating micronutrient levels and neuroimmune diseases. Nevertheless, the causal relationship between them remains unclear. Furthermore, due to confounding factors, many micronutrients implicated in these diseases remain unidentified. This study aimed to determine the causal relationship between circulating micronutrients and neuroimmune diseases through genetic association analysis, and to analyze the regulatory role of circulating micronutrients in neuroimmune diseases.\nMETHOD: In this study, we used a two-sample mendelian randomization (MR) analysis to explore the causal relationship between micronutrients levels and neuroimmune disease. Fourteen micronutrients were screened from a published genome-wide association study (GWAS). Neuroimmune diseases include multiple sclerosis (MS), Guillain-Barre syndrome (GBS), acute disseminated encephalomyelitis (ADEM), acute poliomyelitis (AP), sequelae of poliomyelitis (SP), optic neuritis (ON), and myasthenia gravis (MG). Data on these seven neuroimmune diseases came from the FinnGen database and included 5523 cases and 2,860,006 controls. The inverse variance weighting (IVW) method was used as the main MR analysis method, and sensitivity analysis was performed to determine MR hypotheses.\nRESULTS: Through MR analysis and sensitivity testing, we identified significant causal relationships between four neuroimmune diseases and micronutrient levels. Specifically, MS was causally associated with magnesium levels (OR: 0.467, 95% CI: 0.269-0.809, p = 0.007), ADEM with folate levels (OR: 0.022, 95% CI: 0.001-0.957, p = 0.047), ON with vitamin B6 levels (OR: 0.382, 95% CI: 0.187-0.778, p = 0.008), and MG with iron levels (OR: 0.194, 95% CI: 0.043-0.867, p = 0.032). Sensitivity analysis showed that there was no level pleiotropic or heterogeneity in our study results.\nCONCLUSION: This study established the causal relationship between micronutrients and neuroimmune diseases. These findings provide new insights into the etiology of neuroimmune diseases and provide a theoretical basis for micronutrient regulation, prevention, and treatment of neuroimmune diseases.", "authors": ["Chen Longhao", "Wu Xuzhou", "Wang Kaizheng", "Zhou Xingchen", "Mou Yika", "Liu Zhen", "Shen Zhifang", "Lv Zhizhen", "Lv Lijiang"], "journal": "Brain and behavior", "entry_date": "2025/09/09 04:43", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40923143/", "pub_types": ["Journal Article"], "affiliations": ["The Third Affiliated Hospital of Zhejiang Chinese Medical University, Hangzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40921886", "title": "Factors associated with early response to efgartigimod in patients with generalized myasthenia gravis: a multicenter retrospective observational study.", "abstract": "BACKGROUND AND PURPOSE: Efgartigimod has demonstrated efficacy in generalized myasthenia gravis (gMG) in both clinical trials and real-world studies. However, factors influencing early response have been less reported. This study aimed to evaluate the efficacy of efgartigimod in a multicenter gMG cohort and to identify the clinical factors associated with early therapeutic response.\nMETHODS: This multicenter, real-world, retrospective, observational study included 115 gMG patients administered efgartigimod across four myasthenia gravis (MG) centers. Responders were defined as patients with a ≥ 2-point Myasthenia Gravis Activities of Daily Living (MG-ADL) or ≥ 3-point Quantitative Myasthenia Gravis Score (QMG) score reduction, while early responders were those achieving score reductions after the first infusion. Subgroup analyses were conducted based on immunosuppressant (IST) use. Logistic regression analysis was performed to identify factors associated with response to first efgartigimod infusion according to MG-ADL or QMG scores reduction. Variables were compared between responders and non-responders to identify early response factors.\nRESULTS: After the first infusion, 72.5% of patients achieved improvement in MG-ADL and 60.5% in QMG, with these rates increasing to 93.3% and 87.5% respectively by the fourth infusion. Efgartigimod demonstrated the most significant improvement in bulbar, limb, and ocular symptoms; however, there was no statistically significant improvement in respiratory symptoms occurred during the initial 4-week treatment period. Multivariate logistic analysis showed that short disease duration and high MG-ADL bulbar score at baseline indicated early response. High QMG bulbar score at baseline also indicated early response. Efficacy was independent of IST use. No patients discontinued treatment due to severe adverse events; minor side effects were not recorded.\nCONCLUSIONS: Efgartigimod demonstrated robust efficacy in gMG patients. Early response was linked to shorter disease duration and severe bulbar symptoms, which promotes the identification of patients who are likely to benefit quickly from efgartigimod.", "authors": ["Zhu Wenjia", "Chen Yuping", "Tian Cong", "Wang Jingsi", "Wen Xinmei", "Lou Hua", "Jiang Yuting", "Di Li", "Gu Shanshan", "Wang Yan", "Wang Yaye", "Lu Yan", "Wang Min", "Xu Min", "Chen Hai", "Zhao Yuying", "Qi Guoyan", "Da Yuwei"], "journal": "Journal of neurology", "entry_date": "2025/09/08 23:18", "pub_date": "2025-09-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40921886/", "pub_types": ["Journal Article", "Multicenter Study", "Observational Study"], "affiliations": ["Department of Neurology, Xuanwu Hospital, National Center for Neurological Disorders, Capital Medical University, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "40921232", "title": "Cytoreductive surgery with radical pleurectomy/Decortication and intraoperative photodynamic therapy as a treatment for stage IVa and pleural recurrence thymic tumors.", "abstract": "BACKGROUND: Managing stage IV thymoma with pleural spread or recurrence remains a complex clinical challenge. While complete resection is considered essential for achieving long-term survival, its feasibility and outcomes vary. Inspired by surgical strategies used in malignant pleural mesothelioma, we applied a multimodal approach combining extensive thymectomy, cytoreductive lung-preserving pleurectomy/decortication, and intraoperative photodynamic therapy (PDT) to enhance local control and survival outcomes.\nMETHODS: We retrospectively analyzed cases from April 2006 to December 2010 involving patients who underwent extended thymectomy, lung-sparing pleurectomy/decortication, and adjunctive intraoperative photodynamic therapy (PDT) for pleural thymic malignancies at our institution. The surgical technique was adapted from the methodology established by Dr. Friedberg at the Presbyterian Medical Center of the University of Pennsylvania. Intravenous sodium porfimer (2 mg/kg) was administered 48 h prior to surgery, and the entire pleural cavity was illuminated with 630 nm light at a total dose of 30 J/cm² during the procedure. Each patient received only a single PDT session intraoperatively.\nRESULTS: Fifteen patients (4 men and 11 women; mean age: 43.9 years) were included, comprising six with de novo stage IVa disease and nine with pleural recurrence after initial thymoma resection. Histologically, 14 had thymoma and one had thymic carcinoma. Myasthenia gravis coexisted in 11 cases and was managed preoperatively with plasmapheresis. Six patients underwent upfront surgery; the others received neoadjuvant chemoradiotherapy. Surgical access was determined by tumor distribution: VATS (n = 1), thoracotomy (n = 9), sternotomy (n = 4), and clamshell incision (n = 1). In 11 patients, radical P/D was supplemented by pericardial and diaphragmatic resection. All patients underwent intraoperative PDT following gross total resection. Postoperative complications included two cases of chylothorax, both successfully managed conservatively, and one perioperative death due to hemorrhage. One patient was lost to follow-up; the remaining 13 patients received adjuvant chest wall irradiation and systemic chemotherapy. Local or pleural recurrence occurred in six patients and was managed with salvage surgery and/or additional oncologic treatments. One patient died from complications related to a repeat procedure, while another patient with thymic carcinoma subsequently developed distant metastases. No cases of skin burn injury were observed; only transient skin hyperpigmentation was noted. Over a mean follow-up of 106.8 ± 65.4 months, median recurrence-free survival was 75 ± 34.4 months (61.5 % at 5 years, 36.9 % at 10 years), and median overall survival reached 104 ± 23.4 months (69.2 % at 5 years, 38.5 % at 10 years). Three individuals remain alive: one with no recurrence for 205 months, and two with recurrent disease who are alive at 172 and 186 months, respectively, following additional treatment.\nCONCLUSIONS: A comprehensive surgical approach combined with intraoperative photodynamic therapy may offer improved regional disease control and extended survival in patients with advanced or pleural recurrent thymoma.", "authors": ["Yeh Jiann-Horng", "Hsieh Yei-San"], "journal": "Photodiagnosis and photodynamic therapy", "entry_date": "2025/09/08 19:11", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40921232/", "pub_types": ["Journal Article"], "affiliations": ["School of Medicine, Fu Jen Catholic University, New Taipei City, Taiwan; Department of Neurology, Shin Kong Wu HoSu Memorial Hospital, Taipei City, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40919881", "title": "Identification of Novel Protein Biomarkers for Myasthenia Gravis by Integrating Human Proteomics with Genetic Instruments.", "abstract": "Myasthenia gravis (MG) presents significant health and economic challenges. To identify novel biomarkers, we analyzed proteomic data from 52,704 UK Biobank individuals, focusing on 1463 baseline proteins with follow-up >10 years. Baseline and potential MG cases were 1:5 matched to controls by using propensity score matching. We identified 38 consistently up-regulated differentially expressed proteins (DEPs) in both the baseline and potential MG groups compared to controls, categorized into cardiometabolic, inflammation, neurology, and oncology panels. These DEPs showed potential diagnostic value for distinguishing MG from other neuromuscular disorders, with the area under curves ranging from 0.616 to 0.735 across three models (logistic regression, support vector machine, and random forest). To further investigate causality, two-sample Mendelian Randomization (2SMR) and Cox proportional hazard regression were conducted, and we confirmed 18 potential causal proteins associated with MG, including those in the cardiometabolic panel (CEACAM8, OLR1, PGLYRP1, S100A11, and TNC), inflammation panel (CST7, HGF, IL1RN, IL-6, JCHAIN, OSM, PLAUR, and TGFA), neurology panel (CTSS, MMP8, TBC1D17, and VCAN), and oncology panel (S100A12). Currently, no approved drugs for MG specifically target these identified potential causal proteins and ligands. This comprehensive proteomic analysis highlights novel biomarkers associated with MG, suggesting potential targets for identifying risk proteins and future therapeutic interventions.", "authors": ["Chen Hong-Xi", "Lin Xue", "Zhang Na-Na", "Shi Zi-Yan", "Zhang Ying", "Du Qin", "Kong Ling-Yao", "Sun Dong-Ren", "Wang Rui", "Mou Zi-Chao", "Zhang Yang-Yang", "Mo Yun-Tao", "Wang Xiao-Fei", "Zhou Hong-Yu"], "journal": "Journal of proteome research", "entry_date": "2025/09/08 08:42", "pub_date": "2025-10-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40919881/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, West China Hospital, Sichuan University, Chengdu 610207, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "40918919", "title": "Utility of Breath-Holding Time in Monitoring Acute Neuromuscular Respiratory Failure in Bulbar-Onset Myasthenia Gravis: A Case Report.", "abstract": "We report the management of a 64-year-old male with newly diagnosed bulbar-onset myasthenia gravis (MG) who was hospitalized with acute neuromuscular respiratory insufficiency. This case highlights the challenges in monitoring respiratory function in MG patients, especially in the presence of bulbar and nuchal weakness, and emphasizes the potential utility of single breath-hold time (SBHT) over forced vital capacity (FVC) as a reliable bedside monitoring tool. Despite initial stabilization with intravenous immunoglobulin (IVIG), the patient deteriorated, requiring escalation to the intensive care unit (ICU), and the clinical worsening corresponded with the SBHT rather than with FVC.", "authors": ["Zulfiqar Saboor", "Ugurlu Aylin", "Moore Vicky", "Mukherjee Rahul"], "journal": "Cureus", "entry_date": "2025/09/08 07:16", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40918919/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Respiratory Medicine, Birmingham Heartlands Hospital (Part of University Hospitals Birmingham NHS Trust), Birmingham, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40917658", "title": "CD19+CD11c+T-bet+ B cells in myasthenia gravis: a potential biomarker.", "abstract": "BACKGROUND: Myasthenia gravis (MG), an autoimmune disorder characterized by B cell-driven autoantibody production, exhibits heterogeneous B cell subsets dysregulation and incompletely defined signaling mechanisms.\nMETHODS: A cohort of 20 naïve MG patients positive for anti-acetylcholine receptor (AChR) antibodies and 15 healthy controls was analyzed. Peripheral blood mononuclear cells underwent proteomic profiling, flow cytometry (age-associated B cells (ABCs), plasma cells, T follicular helper cells, and regulatory B cells), and western blot validation of nuclear factor kappa-B (NF-κB)/cellular reticuloendotheliosis oncogene homolog (c-Rel) expression. Clinical severity was assessed using quantitative MG (QMG) scores. Statistical analyses included differential protein expression, pathway enrichment, and receiver operating characteristic (ROC) curve evaluation.\nRESULTS: Proteomics revealed significant activation of the B cell receptor and NF-κB/c-Rel signaling pathways in MG patients, validated by upregulated NF-κB/c-Rel expression (p < 0.01). Flow cytometry demonstrated elevated ABCs (CD19+CD11c+T-bet+), plasma cells, and T follicular helper cells, alongside reduced regulatory B cells in MG (p < 0.001). The proportion of ABCs correlated positively with QMG scores (r = 0.5015, p = 0.024) but not with AChR antibody titers, suggesting antibody-independent mechanisms. ROC analysis identified moderate diagnostic utility of ABCs for moderate-to-severe MG (QMG scores ≥ 6; area under the curve = 0.68, 95% confidence intervals: 0.42-0.94).\nCONCLUSION: This study establishes ABCs and NF-κB/c-Rel signaling as central contributors to AChR-MG immunopathology. Therefore, ABCs may serve as complementary biomarkers for clinical stratification.", "authors": ["Lu Yaru", "Shen Huimin", "Wang Yiye", "Ma Kai", "Sun Ruihua", "Zhao Ying", "Li Yaqiong", "Ma Qian", "Zhang Jiewen"], "journal": "Frontiers in neurology", "entry_date": "2025/09/08 07:02", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40917658/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Zhengzhou University People's Hospital, Henan Provincial People's Hospital, Zhengzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40915254", "title": "Treatment strategy for myasthenia gravis with GAD65-IgG associated neurological disorders: A case report.", "abstract": "We present a clinically instructive case of a 50-year-old woman with acetylcholine receptor (AChR) antibody-positive generalized myasthenia gravis (MG) who subsequently developed glutamic acid decarboxylase 65 (GAD65) antibody-associated neurological disorders alongside a type B2 thymoma. This rare coexistence highlights the profound immune dysregulation induced by thymomas, wherein loss of self-tolerance emergence multiple concurrent autoimmune phenomena. The patient's favorable response to multimodal immunotherapy-including efgartigimod, high-dose corticosteroids, and rituximab-underscores the therapeutic imperative for early, targeted immunomodulation in such complex neuroimmunological syndromes. As no standardized treatment currently exists for MG with GAD65-IgG-associated neurological disorders, this case provides critical clinical insights into both the diagnostic and therapeutic approach for this complex disease.", "authors": ["Xu Xiao-Na", "Luo Wen-Jun", "Li Hui-Ning", "Li Xin", "Wang Jun-Ping", "Jiang Wei", "Yang Shu", "Yang Chun-Sheng"], "journal": "Journal of neuroimmunology", "entry_date": "2025/09/07 18:09", "pub_date": "2025-12-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40915254/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Neurology, Tianjin Medical University General Hospital, Tianjin 300052, China; Tianjin Neurological Institute, Tianjin Medical University General Hospital, Tianjin 300052, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "40914739", "title": "Efficacy and safety of efgartigimod versus intravenous immunoglobulin in early intervention of acetylcholine receptor antibody-positive impending myasthenic crisis: A retrospective cohort study.", "abstract": "Early intervention in impending myasthenic crisis (IMC) is critical to avert life-threatening progression. This study compared the clinical effectiveness and safety of the novel FcRn antagonist efgartigimod versus intravenous immunoglobulin (IVIg) in IMC management. In this retrospective cohort study, we analyzed 51 acetylcholine receptor antibody-positive (AChR-Ab+) IMC patients who received either efgartigimod (n ​= ​30) or IVIg (n ​= ​21) from June 2023 to November 2024. Efficacy was assessed based on changes in Myasthenia Gravis Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG) scores over four weeks. From weeks 2-4, the efgartigimod group showed significantly greater improvements in MG-ADL and QMG scores (both P ​< ​0.05), with a similar trend after baseline adjustment. By week 4, the results of the clinically meaningful improvement (CMI) analysis indicated that a higher proportion of patients in the efgartigimod group achieved MG-ADL improvement ≥7 points (90.0 ​% vs. 57.1 ​%) and greater QMG scores improvement. The proportion of patients reaching minimal symptom expression (MSE) was 80.0 ​% in the efgartigimod group compared to 14.3 ​% in the IVIg group, with mean improvement rates of 91.5 ​% vs. 60.7 ​%, respectively. One case of myasthenic crisis-related death occurred in the IVIg group, while no severe adverse events were reported in the remaining patients. Efgartigimod has been shown to effectively alleviate IMC symptoms, prevent progression to myasthenic crisis (MC), and significantly reduce in complications without substantially increasing the economic costs. These findings suggest its potential as a first-line therapeutic option for AChR-Ab-positive IMC patients.", "authors": ["Guo Rongjing", "Sun Chao", "Huang Xiaoxi", "Hao Sijia", "Wang Qingqing", "Ruan Zhe", "Gao Ting", "Tang Yonglan", "Cao Xiangqi", "Liu Yu", "Li Zhuyi", "Chang Ting"], "journal": "Neurotherapeutics : the journal of the American Society for Experimental NeuroTherapeutics", "entry_date": "2025/09/06 21:55", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40914739/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Neurology, Tangdu Hospital, The Fourth Military Medical University, Xi'an, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.6, "journal_quartile": "2区"}, {"pmid": "40913424", "title": "A Distinct Immunological Signature in Late-Onset Myasthenia Gravis: Insights from an Exploratory Proteomics Study.", "abstract": "OBJECTIVE: Approximately 80% of patients with myasthenia gravis (MG) have autoantibodies against acetylcholine receptor, and clinical characteristics may vary between early-onset (symptom onset age <50 years) and late-onset MG (EOMG and LOMG), but the pathophysiological differences between EOMG and LOMG are not well established.\nMETHODS: We performed an exploratory in-depth proteomics analysis examining 768 inflammatory proteins utilizing the baseline serum samples from the BeatMG study (NCT02110706). We performed pathway enrichment analysis to assess the pathways involved in LOMG. A total of 15 selected proteins from the initial analysis were further examined using the UK Biobank and further quantified in a separate validation cohort.\nRESULTS: A total of 21 patients with EOMG (age 38.3 ± 12.1 years, 16 women [76.2%]) and 28 patients with LOMG (age 67.3 ± 8.6 years, 7 women [25%]) from the BeatMG study were included in the exploratory analysis. Several proteins involved in the regulation of leukocyte differentiation and myeloid leukocyte differentiation and migration pathways were more abundant in the LOMG group. Among them, 7 were significantly different in the UK Biobank cohort. A total of 80 participants (39 MG patients (age 54.33 ± 18.9 years, 17 women [43.6%]) and 41 healthy controls (age 49.56 ± 17.06 years, 21 women [66.1%]) were included in the validation cohort, and IL18R1, CXCL17, and CCL11 were validated to be specific for LOMG.\nINTERPRETATION: Growing evidence supports that LOMG has a distinct immune pathomechanism. Further prospective studies are warranted to confirm the utility of these proteins as biomarkers of LOMG, and the feasibility of using them for more precise therapeutic targets to improve patient outcomes. ANN NEUROL 2026;99:198-210.", "authors": ["Roy Bhaskar", "Chen Jiaxin", "Khani-Habibabadi Fatemeh", "McLaren Nilay", "Soliven Betty C", "Juel Vern C", "O'Connor Kevin C", "Nowak Richard J", "Kusner Linda L", "Kaminski Henry J"], "journal": "Annals of neurology", "entry_date": "2025/09/06 04:43", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40913424/", "pub_types": ["Journal Article", "Research Support, N.I.H., Extramural"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 7.7, "journal_quartile": "1区"}, {"pmid": "40912936", "title": "Sterilizable autoantigen immobilized column platform for broad-spectrum removal of pathogenic autoantibodies in autoimmune diseases.", "abstract": "Blood purification using immunoadsorbent columns is a therapeutic strategy for removing pathogenic autoantibodies in autoimmune diseases. Currently available columns have limitations: Trp/Phe columns offer cost-effectiveness and sterilizability, but lack antigen specificity and have limited capacity to remove diverse pathogenic autoantibodies; whereas Protein A/peptide/anti-human IgG columns target all antibodies, regardless of pathogenicity, limiting specificity, and often require sterile production due to low stability under sterilization conditions, except for peptide ligands. Full-length autoantigen-immobilized immunoadsorbent columns have great potential to specifically adsorb targeted autoantibodies, because autoantibodies recognize diverse epitopes that vary among individuals. However, it is challenging to prepare biologically active autoantigens on a large scale and maintain the quality of antigen-immobilized columns after sterilization. This study introduced a novel approach for preparing sterilizable antigen-immobilized columns that target autoantibodies, excluding those with conformational epitope specificity. Two type I transmembrane protein-coding extracellular domains associated with autoimmunity and their rabbit antisera were used as models. Recombinant human contactin-associated protein-like 2 (Caspr2) and muscle-specific tyrosine-protein kinase receptor (MuSK) were expressed as bacterial inclusion bodies. These compounds were solubilized and purified using Cys-specific chemical cationization. Columns immobilized with water-soluble S-cationized Caspr2 or MuSK effectively captured specific antibodies from rabbit antisera against each antigen, retaining their capacity after standard sterilization. This approach offers a promising solution for developing immunoadsorbent columns with enhanced specificity and sterilizability and is applicable to various autoantibody-related disorders.", "authors": ["Futami Midori", "Kurozumi Eri", "Kamo Masaya", "Taguchi Soudai", "Nakai Tomoaki", "Futami Junichiro"], "journal": "Journal of bioscience and bioengineering", "entry_date": "2025/09/05 21:51", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40912936/", "pub_types": ["Journal Article"], "affiliations": ["Department of Bioscience, Faculty of Life Science, Okayama University of Science, Okayama 700-0005, Japan. Electronic address: mfutami@ous.ac.jp."], "china_related": false, "study_types": ["HEOR"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "40909041", "title": "Congenital Myasthenic Syndrome in Pregnancy: A Case Report and Literature Review on Peripartum Management Strategy.", "abstract": "Congenital myasthenic syndromes (CMS) are a group of rare inherited neuromuscular disorders caused by defects in neuromuscular transmission. Unlike autoimmune myasthenia gravis, CMS typically presents in childhood with variable severity and symptoms, and does not involve autoantibodies. This report presents the management of a primigravida diagnosed with CMS who was generally stable on pyridostigmine therapy but experienced a severe exacerbation during pregnancy. The diagnosis of CMS was made on clinical grounds, but the genetic testing for confirmation of the exact mutation was not available. The patient experienced intermittent mild exacerbations before pregnancy, managed with short courses of prednisolone. A severe exacerbation at 20 weeks of gestation required intensive care unit admission for respiratory support. Despite plans for a vaginal delivery, she developed exhaustion and desaturation during labour, followed by foetal distress, necessitating emergency caesarean section. Postpartum, the patient returned to her baseline functional status, and the neonate showed no signs of neuromuscular weakness. This case highlights that pregnancy in women with CMS can be safely managed with careful monitoring, multidisciplinary planning, and readiness to escalate care when needed. Delivery plans should be flexible, and management should be tailored to the individual's clinical course. Since the neonatal outcome is unpredictable in the absence of genetic testing, follow-up care is necessary in all cases.", "authors": ["Gnanarathne Sampath", "Ratnayake Ashani", "Thennewatte Dilum", "Isurindi U A"], "journal": "Cureus", "entry_date": "2025/09/05 04:56", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40909041/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Obstetrics and Gynaecology, Faculty of Medicine, University of Peradeniya, Kandy, LKA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40907058", "title": "An observational longitudinal study of congenital myasthenic syndromes.", "abstract": "Congenital Myasthenic Syndromes (CMS) are a group of inherited disorders characterised by fatigable muscle weakness. There are currently no validated outcome measures in CMS. We conducted a prospective exploratory observational study in 49 CMS patients. The primary aim was to explore relevant and reliable outcome measures for assessing and monitoring change. Assessments included Quantitative Myasthenia Gravis score, Myasthenia Gravis Activities of Daily Living, six-minute-walk-test and sit to stand in one minute, in addition to others. Patients were seen 2-4 times over a 2-year period. Median age was 25.5 (range 1-72) years. Subtypes included AChR-deficiency (n = 15), AGRN-DOK7 clustering complex (n = 15), RAPSN (n = 6), COLQ (n = 5), others (n = 8). Ptosis was highest in AChR-deficiency and limb fatigue was highest in AGRN-DOK7 and COLQ. Median sit to stand in one minute was 22 (range 6-45), median total distance walked in six-minute-walk-test was 434 metres (range 0-711 m). A correlation was noted between sit to stand and six-minute-walk-test (R² = 0.291, p-value <0.001) and between total Quantitative Myasthenia Gravis and Myasthenia Gravis Activities of Daily Living scores (R² = 0.2851, p-value <0.001). This is the first study exploring the use of outcome measures in a CMS population, highlighting the variability in fatigue across CMS subtypes and the limitations of outcome measures validated in myasthenia gravis for CMS.", "authors": ["Ramjattan Hayley", "Henehan Leighann", "Ramdas Sithara", "Palace Jacqueline"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2025/09/04 17:59", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40907058/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Children's Therapies & Gait, Oxford Children's Hospital, John Radcliffe Hospital, Oxford, UK. Electronic address: hayley.ramjattan@ouh.nhs.uk."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40906015", "title": "A case of myasthenia gravis with takotsubo cardiomyopathy presenting with respiratory and cardiac arrest.", "abstract": "", "authors": ["Hu Chunhua", "Bao Suya", "Lin Jianwen", "Li Shumin", "Wang Lu", "Liu Wenxin", "Han Ziqi", "Liu Yi"], "journal": "Clinical autonomic research : official journal of the Clinical Autonomic Research Society", "entry_date": "2025/09/04 11:05", "pub_date": "2026-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40906015/", "pub_types": ["Letter"], "affiliations": ["Department of Neurology, Central Hospital of Dalian University of Technology, Dalian, China."], "china_related": true, "study_types": ["Letter"], "evidence_level": null, "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "40904272", "title": "Rapid and sustained response to tofacitinib in a patient with anal pyoderma gangrenosum under immunosuppression and bone marrow suppression.", "abstract": "AIM: To evaluate the therapeutic efficacy and safety of the Janus kinase (JAK) inhibitor tofacitinib in the management of refractory perianal pyoderma gangrenosum (PG) under conditions of baseline immunosuppression and bone marrow suppression.\nMETHODS: We present a 62-year-old male with a 4-month history of painful, progressive symmetrical perianal ulcerations diagnosed as PG, coexisting with condyloma acuminatum. The patient had a background of pure red cell aplasia and myasthenia gravis, and was undergoing chronic immunosuppressive therapy with prednisolone and tacrolimus. Previous interventions including topical agents, antibiotics, phototherapy, and surgical debridement were ineffective. Oral tofacitinib (5 mg/day) was introduced following multidisciplinary evaluation.\nRESULTS: Marked pain reduction was achieved by day two of tofacitinib therapy, with near-complete ulcer healing observed within two weeks. Hematologic parameters remained stable throughout the 4-month treatment course, which was well tolerated with no adverse effects. The patient remained relapse-free during a 1-year follow-up.\nCONCLUSIONS: Tofacitinib may offer a rapid, effective, and well-tolerated treatment alternative in cases of refractory PG, even when layered onto preexisting immunosuppressive regimens. This case highlights the potential of JAK inhibitors as targeted therapy in complex PG presentations and supports their further clinical evaluation.", "authors": ["Zhou Yuting", "Zhang Long", "Wang Wenhui"], "journal": "The Journal of dermatological treatment", "entry_date": "2025/09/04 04:03", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40904272/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Dermatology, Peking University Third Hospital, Beijing, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40903999", "title": "[Effect of mouse nerve growth factor combined with neostigmine on nerve repair after envenoming bites by Bungarus multicinctus].", "abstract": "Objective: To evaluate the efficacy and clinical application value of mouse nerve growth factor combined with neostigmine in the treatment of nerve injury in patients bitten by Bungarus multicinctus by a prospective single-blind controlled clinical study. Methods: In June 2020, a prospective, single-blindness, randomized grouping method was used to select patients with bungarus multicinctus saurogobio dabryi subsp. dabryi bite injuries admitted to the Emergency Department of Ganzhou People's Hospital in Jiangxi Province as the study subjects. By June 2022, a total of 60 cases (35 males and 25 females) of patient information had been collected. The patients were divided into two groups <4 h and ≥4 h after being bitten by bungarus multicinctus. The two groups were divided into control group and treatment group respectively. The treatment group was given an intramuscular injection of neostigmine 1mg q8 h and mouse nerve growth factor 18 μg/d based on conventional treatment. The control group was only given conventional treatment. Myasthenia Gravis Composite Scale (MGC) scores were performed for all patients at admission, 4 hours, 8 hours, and 24 hours. Muscle strength was continuously assessed and the recovery time of muscle strength was recorded. Quantitative data comparisons between groups at admission were analyzed using one-way ANOVA, while qualitative data comparisons were conducted using χ2 tests. Variables showing intergroup differences in baseline measurements (Parazacco spilurus subsp. spilurus) were treated as covariates, with treatment outcomes post-admission compared via analysis of covariance (ANCOVA). Pairwise comparisons of quantitative data between groups employed the Bonferroni method. Baseline quantitative data correlation analysis utilized Pearson correlation, followed by partial correlation analysis after controlling for grouping variables. Results: The MGS scores of the treatment group in both the ≥4 h and <4 h patient groups were lower than those of the control group at the same time points (P<0.05). After adjusting for the influence of MGS scores at admission, the muscle strength recovery time in the ≥4 h treatment group was significantly shorter compared to the control group, with a statistically significant difference (P<0.001). MGS scores at 4 h, 8 h, and 24 h after admission were positively correlated with muscle strength recovery time (r=0.540, 0.720, 0.640, respectively, P<0.001). Muscle strength recovery time was positively correlated with disease duration (r=0.910, P<0.001). Disease duration was positively correlated with MGS scores at admission (r=0.908, P<0.001) and with muscle strength recovery time (r=0.757, P<0.001). After controlling for grouping, the correlation coefficient increased, showing a strong correlation (r=0.892, P<0.001) . Conclusion: The combination of mouse nerve growth factor and neostigmine can shorten the time of muscle weakness after the bite of Bungarus multicinctus, promote the recovery of injured nerves, and improve the clinical symptoms caused by nerve snake venom.\n目的： 通过前瞻性单盲临床对照研究评价鼠神经生长因子联合新斯的明在银环蛇咬伤患者神经损伤中的疗效及临床应用价值。 方法： 于2020年6月，用前瞻性、单盲、随机分组方法，选择赣州市人民医院急诊科收治的银环蛇咬伤患者作为研究对象，共60例（男性35例，女性25例）。按银环蛇咬伤至接受规范医疗救治时间以4 h为节点，将患者分为咬伤<4 h组、咬伤≥4 h组。两组患者再分别分为对照组和治疗组。咬伤<4 h组患者29例，其中治疗组15例，对照组14例；咬伤≥4 h组患者31例，其中治疗组18例，对照组13例。治疗组在常规治疗基础上给予新斯的明肌肉注射1 mg/8 h（3次/d）、鼠神经生长因子肌肉注射18 μg/d；对照组仅给予常规治疗。所有患者在入院时、入院4 h、入院8 h、入院24 h进行《重症肌无力复合量表》（MGC）评分，持续评估肌力，并记录肌力恢复时间。入院时组间定量资料比较用单因素方差分析，定性资料比较用χ(2)检验。将基线时存在组间差异的变量作为协变量，用协方差分析比较入院后的治疗结局。两组间定量资料的比较用Bonferroni法。基线定量资料关联性分析用Pearson相关分析，控制分组变量后用偏相关分析。 结果： 咬伤≥4 h组和咬伤<4 h组患者的治疗组MGS评分均低于相同时间的对照组（P<0.05）。剔除入院时MGS评分的影响后，与对照组比较，咬伤≥4 h治疗组患者肌力恢复时间缩短,差异有统计学意义（P<0.001）。入院4 h、入院8 h及入院24 h MGS评分与肌力恢复时间均呈正相关（r=0.540、0.720、0.640，P<0.001）；肌力恢复时间与发病时长呈正相关（r=0.910，P<0.001）。发病时长与入院MGS评分呈正相关（r=0.908，P<0.001）；发病时长与肌力恢复时间呈正相关（r=0.757，P<0.001），控制分组后，两者呈强相关（r=0.892，P<0.001）。 结论： 鼠神经生长因子联合新斯的明能缩短银环蛇咬伤后肌无力时间，促进损伤神经的恢复，改善因神经蛇毒引起的临床症状。.", "authors": ["Peng J L", "Xiao X L", "Song C J"], "journal": "Zhonghua lao dong wei sheng zhi ye bing za zhi = Zhonghua laodong weisheng zhiyebing zazhi = Chinese journal of industrial hygiene and occupational diseases", "entry_date": "2025/09/04 02:15", "pub_date": "2025-08-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40903999/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "English Abstract"], "affiliations": ["Department of Emergency, The Affiliated Ganzhou Hospital of Nanchang University, Ganzhou 341000, China."], "china_related": true, "study_types": ["RCT"], "evidence_level": "II"}, {"pmid": "40897168", "title": "[Diseases of the Thymus in domestic mammals: Significance and diagnosis].", "abstract": "In contrast to human medicine, thymic disorders receive little attention as differential diagnoses in veterinary medicine. The aim of this overview is to provide information on the current state of knowledge concerning the topographical anatomy, physiological development, and involution, function, and diseases of the thymus as well as the diagnosis of thymic disorders in various domestic mammals. Therefore, literature on this topic was searched and summarized. The anatomical extent and developmental/involutionary processes differ significantly from species to species. The thymus reaches its maximum size at the beginning of sexual maturity whereas it is largely absent or persists in mere residual form in adult animals. Dogs and goats represent an exception, as functional thymus tissue may also be found in adults. Imaging is often difficult, depending on the size of the animal and the location of the organ. Due to the poor visualization and mostly unspecific clinical signs, disorders of the thymus pose a diagnostic challenge. The thymus may change in size and structure in response to stress or disease. This can lead to impaired immune function and subsequently to infectious diseases. Neoplasia of the thymus has been widely described in domestic mammals. Most reports are found for dogs and goats. Clinical signs usually appear when the tumor becomes space-occupying due to its size or they become apparent in consequence to the occurrence of paraneoplastic syndromes. These may for example include myasthenia gravis. More than 50% of dogs with a thymoma develop a paraneoplastic syndrome. With the availability of modern imaging, assessing the thymus may in future become simpler and may prove useful in evaluating the health status of young animals.\nIm Gegensatz zur Humanmedizin finden Thymuskrankheiten in der Veterinärmedizin wenig differentialdiagnostische Beachtung. Ziel dieser Übersicht ist es, den Kenntnisstand zu topographischer Anatomie, physiologischer Entwicklung und Involution, Funktion und Krankheiten des Thymus sowie der Diagnostik von Thymuskrankheiten bei den verschiedenen Haussäugetieren darzustellen. Dafür wurde die Literatur, die sich mit dem Themenkomplex beschäftigt, durchsucht und zusammengefasst. Die anatomische Ausdehnung und Entwicklungs-/Involutionsprozesse unterscheiden sich von Tierart zu Tierart deutlich. Allgemein gilt, dass der Thymus zu Beginn der Geschlechtsreife seine maximale Ausdehnung hat und beim adulten Tier nicht oder nur in Residuen vorhanden ist. Eine Ausnahme bilden Hund und Ziege, bei denen auch beim Adulten funktionelles Thymusgewebe gefunden werden kann. Die Darstellung durch bildgebende Verfahren erweist sich je nach Größe des Tieres und durch die Lage des Organs häufig als schwierig. Aufgrund der schlechten Darstellbarkeit und die oft unspezifische Symptomatik stellen Krankheiten des Thymus eine diagnostische Herausforderung dar. Der Thymus kann sich als Reaktion auf Stress oder Krankheiten in seiner Größe und Struktur verändern. In diesem Zusammenhang kann es zu einer gestörten Immunfunktion kommen und in der Folge zu Infektionskrankheiten. Neoplasien des Thymus sind bei Haussäugetieren vielfach beschrieben. Die meisten Berichte finden sich für den Hund und die Ziege. Symptome treten meist auf, wenn der Tumor durch seine Größe raumfordernd wird oder durch das Auftreten von paraneoplastischen Syndromen. Dazu gehört beispielsweise die Myasthenia gravis. Mehr als 50% der Hunde mit einem Thymom entwickeln ein paraneoplastisches Syndrom. Durch die Verfügbarkeit moderner Bildgebung könnte die Untersuchung des Thymus in Zukunft vereinfacht und bei Jungtieren als ein guter Indikator zur Überprüfung des Gesundheitsstatus genutzt werden.", "authors": ["Diel Emilia", "Wehrend Axel"], "journal": "Tierarztliche Praxis. Ausgabe G, Grosstiere/Nutztiere", "entry_date": "2025/09/02 18:32", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40897168/", "pub_types": ["Journal Article", "Review", "English Abstract"], "affiliations": ["Tierklinik für Reproduktionsmedizin und Neugeborenenkunde, Justus-Liebig-Universität Gießen."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "40896927", "title": "Electrophysiological findings in immune checkpoint inhibitor-related neuromuscular events.", "abstract": "INTRODUCTION: Immune checkpoint inhibitors (ICIs) have become key therapies for various malignancies by restoring antitumor immunity. However, they may trigger immune-related adverse events (irAEs), including neurological irAEs (n-irAEs), which, though rare, can be severe. Among these, neuromuscular disorders affecting peripheral nerves, the neuromuscular junction (NMJ), and muscle are the most frequent and carry the highest mortality risk, warranting prompt recognition.\nOBJECTIVE: To describe the clinical and electrodiagnostic features of ICI-related neuromuscular disorders in 38 patients.\nMETHODS: We retrospectively analyzed patients treated with ICIs referred for electrodiagnostic evaluation due to suspected n-irAEs. Patients were categorized into two phenotypes: (1) ir-Neuropathies (cranial/peripheral neuropathies, radiculopathies) and (2) ir-MG/myositis (myasthenia gravis and/or myositis). Studies included motor/sensory conduction, F-waves, needle EMG, and, when indicated, single-fiber EMG, repetitive stimulation, and evoked potentials.\nRESULTS: Of 38 patients, 27 (71%) had ir-MG/myositis and 11 (29%) ir-Neuropathies. Myositis with spontaneous activity was the most frequent ir-MG/myositis pattern. In ir-Neuropathies, acute sensory-motor demyelinating polyradiculoneuropathy predominated.\nCONCLUSIONS: Myositis is the most common ir-MG/myositis pattern, while demyelinating polyradiculoneuropathy is typical of ir-Neuropathies. NMJ dysfunction often coexists with myositis and may be missed electrophysiologically.\nSIGNIFICANCE: Electrodiagnosis is essential for early detection and management of ICI-related neuromuscular complications.", "authors": ["Lainez E", "Llauradó A", "Gratacòs-Viñola M", "Seoane J L", "Trallero-Araguás E", "Ariño H", "Roca-Herrera M", "Juntas R", "Raguer N"], "journal": "Clinical neurophysiology : official journal of the International Federation of Clinical Neurophysiology", "entry_date": "2025/09/02 18:03", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40896927/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Neurophysiology. Vall d'Hebron University Hospital. Passeig de la Vall d'Hebron, 119 Barcelona, Spain. Electronic address: melena.lainez@vallhebron.cat."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "40894412", "title": "Acupuncture Treatment for Individuals With Myasthenia Gravis - A Pilot Randomized Clinical Trial.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune disease resulting in muscle weakness. Although pharmacologic treatments are typically effective at managing symptoms, prolonged use is associated with safety issues. Acupuncture treatment may have a significant positive effect in treating MG symptoms and may enhance the efficacy of medications.\nOBJECTIVE: The overall goal was to examine the feasibility and safety of a pilot randomized controlled trial of acupuncture treatment in individuals with MG.\nMETHODS: Participants were randomized into 2 arms: (1) immediate start and (2) delayed start. Participants in the immediate start arm underwent twice weekly acupuncture for 12 weeks, whereas participants in the delayed start arm underwent a 12-week delay period, followed by twice weekly acupuncture for 12 weeks. A base treatment of 21 acupoints was used for all study participants. Acupuncturists made a Traditional Chinese Medicine differential diagnosis to determine whether the patient was yang deficient, yin deficient, or stagnation pronounced, and could add up to 9 additional acupoints. Participants received the same acupuncture protocol for all 24 treatments.\nRESULTS: Twenty-four individuals with MG were enrolled in the study. The average age of participants was 62 (SD = 13) with an average of 8 years (SD = 9) between diagnosis and enrollment. Seventeen of the 24 individuals who signed the consent form completed 100% of acupuncture treatment sessions and completed the full study. Only 17 adverse events were determined to be definitely or probably related to treatment, which were mostly mild site reactions. Barriers to participation included transportation issues, travel time, and the overall time commitment.\nCONCLUSION: The results demonstrated that acupuncture treatment was overall feasible and safe in individuals with MG. Participants also self-reported improvements in MG symptoms. Next steps will include development of an efficacy RCT with a rigorous study design to examine the clinical significance and efficacy of acupuncture for MG.", "authors": ["Herrmann Amanda A", "Chrenka Ella A", "Chung Lap Pui", "Bouwens Sophia G", "Tansey Ellie K", "Qin Lixin", "Wolf Ayla A", "Farrell Marny T", "Sherman Samantha J", "Svitak Aleta L", "Hanson Leah R", "Guliani Gaurav K"], "journal": "Global advances in integrative medicine and health", "entry_date": "2025/09/02 16:48", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40894412/", "pub_types": ["Journal Article"], "affiliations": ["HealthPartners Institute, Bloomington, MN, USA."], "china_related": false, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 2.1}, {"pmid": "40894336", "title": "Myasthenia Gravis-Like Symptoms Following Immune Checkpoint Inhibitor Therapy for Hepatocellular Carcinoma: A Case Report.", "abstract": "We describe the case of an older male patient with hepatocellular carcinoma and a history of hepatitis B virus-related cirrhosis and type 2 diabetes mellitus. At 12 weeks after treatment with transcatheter arterial chemoembolization (TACE) combined with systemic therapy using lenvatinib and camrelizumab, the patient was found to have progressive disease, based on the modified Response Evaluation Criteria in Solid Tumors (mRECIST) criteria. He also exhibited symptoms such as left eyelid ptosis and limitations in inward, upward, and downward movements of the left eye. The possibility of immune checkpoint inhibitor-induced myasthenia gravis was considered. After relevant examinations including electromyography and repetitive nerve stimulation, a diagnosis of oculomotor nerve palsy induced by diabetes-related microvascular dysfunction was ultimately considered. Subsequently, the patient was treated with camrelizumab combined with regorafenib and TACE therapy and was concurrently subjected to stricter glycemic control and neurotrophic treatment. Three months later, the ocular symptoms disappeared, and the mRECIST assessment revealed the achievement of a partial response. At the time of manuscript submission, the overall survival of the patient had reached 81 months.", "authors": ["Ha Fushuang", "Wang Haoyu", "Cai Junjun", "Liang Jing", "Liu Hua"], "journal": "Cancer management and research", "entry_date": "2025/09/02 16:46", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40894336/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Hepatology and Gastroenterology Department, The Third Central Hospital of Tianjin, Tianjin, People's Republic of China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40893460", "title": "Mediastinal cryptococcoma as part of disseminated cryptococcosis in HIV-negative pregnant woman with Myasthenia Gravis: Autopsy case report.", "abstract": "Cryptococcosis is a fungal infection commonly found in immunocompromised individuals, but it can also affect immunocompetent individuals. A pregnant woman with myasthenia gravis, HIV-negative, died after a diagnosis of tuberculosis. An autopsy revealed a mediastinal mass and organ involvement, indicating a disseminated cryptococcal infection. This case highlights the importance of maintaining a high index of suspicion for cryptococcal infection in immunosuppressed individuals, even without HIV/AIDS. Early detection is achieved by measuring serum cryptococcal antigen.", "authors": ["Samy Bianca Ponnamma", "Thobakgale Nosipho Maria", "Khaba Moshawa Calvin"], "journal": "Medical mycology case reports", "entry_date": "2025/09/02 16:29", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40893460/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Anatomical Pathology, Dr George Mukhari Academic Laboratory, National Health Laboratory Service, Sefako Makgatho Health Sciences University, South Africa."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "40892711", "title": "Predictors of Quality of Life in Myasthenia Gravis Patients from Southwestern China: Validation of Clinical and Socioenvironmental Determinants.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) presents a substantial clinical burden, characterized by increased incidence of myasthenic crises, heterogeneity in treatment response, significant functional impairment, and gradually increasing mortality rates with marked geographical heterogeneity across China. While improving quality of life (QOL) is the focus of MG management, multifactorial determinants of QOL impairment remain unclear, especially in socioeconomically underrepresented regions, particularly Southwestern China. This study aimed to explore myasthenia-specific risk factors for QOL and develop a parsimonious prediction model.\nMETHODS: This study performed univariate and multivariate regression analyses on 310 MG patients diagnosed at the First Affiliated Hospital of Chongqing Medical University between January 2022 and February 2025 from Southwestern China. The QOL of patients was evaluated with the 15-item Myasthenia Gravis Quality of Life (MG-QOL15). Disease severity was evaluated with current Myasthenia Gravis Foundation of America (MGFA) classification, MG-related activity of daily living (MG-ADL) score and quantitative myasthenia gravis (QMG) score. Relevant clinical and demographic data were included in the analysis.\nRESULTS: In the analysis of basic characteristics, higher ADL (p < 0.001), worse MGFA classification (p < 0.001), lower education level (p = 0.006), thymic abnormalities (p = 0.004), and treatment (p = 0.003) were significantly correlated with poor QOL. However, factors such as age of onset, gender, and antibody status showed no significant impact. The multivariate models (Model 1-6) further confirmed that MG-ADL (OR = 8.397), QMG score (OR = 4.357), MGFA classification, and thymus histology (thymic hyperplasia OR = 4.505, thymoma OR = 2.472) were independent risk factors for QOL. Corticosteroids combined with immunotherapy were found to significantly improve QOL compared to monotherapy. Model validation indicated that Model 5, which incorporates MG-ADL, MGFA classification, thymus histology, and education level, had the optimal overall performance (area under the curve = 0.835, specificity 0.917), balancing predictive accuracy and clinical applicability.\nCONCLUSION: By identifying key predictors, including clinical severity, thymic abnormalities, and education level, this study developed a multidimensional prediction model for QOL in MG patients.", "authors": ["Jing Sisi", "Zhang Zhihan", "Zhou Yuchuan", "Zheng Wei", "Fan Rui", "Que Wenjun", "Liu Linqi", "Lu Dan", "Liu Shiyi", "Gan Yaoqi", "Xiao Fei"], "journal": "Neuroepidemiology", "entry_date": "2025/09/02 13:24", "pub_date": "2025-09-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40892711/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Chongqing Key Laboratory of Major Neurological and Mental Disorders, Neurology Key Laboratory of Chongqing Education Commission of China, Chongqing Key Laboratory of Neurology, The First Affiliated Hospital of Chongqing Medical University, Chongqing, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.0, "journal_quartile": "3区"}, {"pmid": "40889171", "title": "Distribution of Ectopic Germinal Centers in Thymic Epithelial Tumors and Their Relationship With Thymic Involution.", "abstract": "Ectopic germinal centers (GCs) are often formed in the thymus of patients with anti-acetylcholine receptor antibody (anti-AChR Ab)-positive thymic epithelial tumors (TETs) and are considered sites where B cells undergo affinity maturation to produce high-affinity anti-AChR Abs, contributing to the development of myasthenia gravis. To evaluate the clinical relevance of these ectopic GCs, we analyzed their distribution and associations with thymic involution and anti-AChR Ab titers using paraffin-embedded surgical specimens from 79 TET patients. Thymic involution was scored, and immunohistochemistry was performed to identify cells involved in GC formation. GCs were identified in 32 of the 79 cases. The anti-AChR Ab+ group had significantly higher frequencies of GCs in the residual thymus compared to the Ab- group. In all cases with GCs in the residual thymus, GCs were found both near the tumor and at distances greater than 1 cm from the tumor. Within the anti-AChR Ab+ group, GC+ patients were significantly younger and showed milder thymic involution than GC- patients. The number of GCs per unit area positively correlated with serum antibody titer. In Ab+ cases, AChR-α1 antigens were significantly more frequent in GC+ cases. In mildly involuted thymus, AChR antigens, antigen-presenting cells, and B cells were detected in the medulla, whereas these were rarely observed in severely involuted thymus. These findings suggest that GC formation occurs preferentially in a less involuted thymus and that surgical resection of at least the extent of a total thymectomy may be indicated in younger patients with anti-AChR Ab+ TETs.", "authors": ["Furuya Tatsuo", "Tando So", "Ogi Hiroshi", "Shimomura Masanori", "Okada Satoru", "Ishihara Shunta", "Nakazono Chiaki", "Itoh Kyoko", "Inoue Masayoshi"], "journal": "Cancer science", "entry_date": "2025/09/01 12:42", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40889171/", "pub_types": ["Journal Article"], "affiliations": ["Division of Thoracic Surgery, Department of Surgery, Kyoto Prefectural University of Medicine, Graduate School of Medical Science, Kyoto, Japan."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "40886290", "title": "CircularRNA and Musculoskeletal Diseases.", "abstract": "The skeletal muscle is the largest organ in the human body and plays a crucial role in the locomotion, metabolism, and homeostasis. Myogenesis is regulated by a complex molecular network and is kept finely balanced under physiological conditions. The disorder of muscular homeostasis results in musculoskeletal diseases, including myositis, dystrophy, sarcopenia, atrophy, and cachexia. These diseases severely affect the life quality of humans. In recent years, with the progress of high-throughput sequencing technology and the development of bioinformatics, a large number of noncoding RNAs (ncRNAs) have been identified in the skeletal muscle, and numerous experiments to date have shown that those ncRNAs are widely involved in multiple pathophysiological process of skeletal muscle. Circular RNAs (circRNA) are a class of noncoding RNAs formed by covalently closed loops through back-splicing and exon skipping. circRNAs have been confirmed to play a vital role in various biological functions, acting as microRNA sponges and reservoirs, as well as combining with RNA-binding proteins during the progression of myogenesis. In this chapter, we will summarize the progress of circRNA in regulating skeletal muscle and provide new information to better understand muscle diseases development and therapeutic strategy.", "authors": ["Yu Pujiao", "Qi Yuan", "Huang Hui", "Wang Hairong", "Xu Jiahong"], "journal": "Advances in experimental medicine and biology", "entry_date": "2025/08/31 11:13", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40886290/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Cardiology, Gongli Hospital, School of Medicine, Shanghai University, Shanghai, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "40884033", "title": "Incidence and risk factors of immune checkpoint inhibitor myocardial and muscle toxicity: a French nationwide study.", "abstract": "BACKGROUND AND AIMS: Immune checkpoint inhibitor (ICI)-induced (cardio)-myotoxicities, including myocarditis and myositis, are uncommon but frequently severe adverse drug reactions seen in cancer patients. Real-life ICI myotoxicity incidence estimates span from limited-size cohorts, with risk factors and prognosticators poorly established, as well as their impact on survival.\nMETHODS: This retrospective French National Health Data System cohort study included all adult patients starting ICI between 1 January 2012 and 30 September 2022. A 'narrow' and a 'broad' code combination (based on International Classification of Diseases-10 codes) were used for studied outcomes. The primary outcome was the occurrence of myotoxicities and secondary outcomes of myocarditis and myositis. Risk factors of these outcomes at 6 months were identified with Fine and Gray multivariable models, considering demographics, comorbidities, co-treatments, and cancer. Immune checkpoint inhibitor myotoxicity (as a time-dependent variable) association with overall survival was tested using Cox models. Risk factors of 1- and 3-month letality in ICI myotoxicity cases were assessed by multivariable logistic regression.\nRESULTS: In 172 363 ICI-treated adult patients, incidence of ICI myotoxicities at 6 months ranged between 0.7% and 0.9% (narrow or broad definitions, respectively), with up to 7.1% in patients with thymic cancer. Immune checkpoint inhibitor myocarditis and ICI myositis incidence ranged between 0.3% and 0.6%, co-occurring in ∼13%-23% of cases. The main risk factors for developing ICI myotoxicities (broad, n = 1520) were thymic tumour (sub-distribution hazard ratio [sHR] 12.94, 95% confidence interval [CI] 5.22-32.03), melanoma (2.41 [2.06-2.83]) and other skin cancers (2.07 [1.55-2.76]), history of thymic disorders (5.61 [2.66-11.86]), history of myasthenia gravis (2.50 [1.45-4.32]), combination of ICI (2.44 [1.99-2.98]), and age > 85 [1.79 [1.24-2.59] vs <45 years. Immune checkpoint inhibitor myotoxicity occurrence was the factor impacting most mortality after ICI start (HR 3.51 [95% CI 3.17-3.89] at 1 month), over metastatic status (1.55 [1.52-1.58]). In ICI myotoxicity patients, 1-month fatality was 20.3% and increased if severe arrhythmia (risk ratio 1.64 [95% CI 1.03-2.61]), heart failure (1.49 [1.06-2.07]), and respiratory failure (1.50 [1.05-2.15]) were reported. Additionally, results were consistent with secondary outcomes, using narrow and broad definitions.\nCONCLUSIONS: This pharmaco-epidemiological study assessed >170 000 French patients treated by ICI in real life, establishing the incidence and identifying risk factors of developing ICI myotoxicities, with severity surrogates associated with fatality.", "authors": ["Salem Joe-Elie", "Ajrouche Aya", "Rozes Antoine", "Pinto Sandrine", "De Rycke Yann", "Tubach Florence"], "journal": "European heart journal", "entry_date": "2025/08/30 02:22", "pub_date": "2026-03-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40884033/", "pub_types": ["Journal Article"], "affiliations": ["Sorbonne Université, INSERM, Department of Pharmacology, CIC-1901, AP-HP, Hôpital Pitié-Salpêtrière, 47 Boulevard de l'Hopital, Paris 75013, France."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 35.6, "journal_quartile": "1区"}, {"pmid": "40883381", "title": "Hock immunization, a refined alternative for developing experimental autoimmune myasthenia gravis (EAMG) in mice.", "abstract": "Experimental autoimmune myasthenia gravis (EAMG) is an active-immunization model that was first discovered by coincidence when rabbits injected with purified acetylcholine receptor for neuromuscular junction physiology studies, suddenly developed muscle weakness. In mice, this model typically involves bilateral subcutaneous injections of purified torpedo acetylcholine receptor (tAChR) in the hind footpads and the scapular regions, followed by one or two booster immunizations in the thighs and over the scapulas. However, footpad injections can cause severe discomfort and progressive debilitation. Hock immunization has shown to be a viable alternative in other models, offering comparable efficacy without impairing mobility caused by inflammation, thus reducing discomfort. To investigate the use of hock immunization in the mouse EAMG model, 7-week-old female C57BL6/6J (B6) mice were bilaterally injected over the scapulas and either in the hocks or footpads for the primary immunization. All animals received a booster immunization 4 weeks later, following standard guidelines. Inverted mesh measurements demonstrated that tAChR-immunized animals whether receiving hock or footpad injections, exhibited similar muscle weakness. This weakness correlated with reduced body weight, which reached statistical significance, only in the hock-immunized group. tAChR antibodies were detectable in both groups 4 weeks after primary immunization and continue raising until the end of the experiment. Additionally, tAChR immunized mice required significantly less curare to induce a decremental response of compound muscle action potentials. Notably, hock-immunized mice displayed consistent mechanical sensitivity over time, which was significantly lower compared to footpad-immunized mice. In conclusion, hock-immunization is a refined and effective alternative for developing the EAMG mouse model. It results in similar disease incidence and severity while minimizing immunization-related discomfort compared to the standard footpad method.", "authors": ["Mané-Damas Marina", "Schöttler Anja K", "Mohile Tanya", "Arets Britt", "Tüzün Erdem", "Losen Mario", "Martinez-Martinez Pilar"], "journal": "Scientific reports", "entry_date": "2025/08/29 23:24", "pub_date": "2025-08-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40883381/", "pub_types": ["Journal Article"], "affiliations": ["Department of Psychiatry and Neuropsychology, Mental Health and Neuroscience Research Institute, Faculty of Health, Medicine and Life Sciences, Maastricht University, Maastricht, The Netherlands."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40881456", "title": "Early-onset bull's eye maculopathy due to hydroxychloroquine in rheumatoid arthritis and myasthenia gravis.", "abstract": "", "authors": ["Kasiri Ali", "Feghhi Mostafa", "Ansari Ali", "Kasiri Rozhin", "Mirdehghan Mohammad Sadegh", "Mohammadi Abbas", "Kasiri Mohammad Armin"], "journal": "International journal of ophthalmology", "entry_date": "2025/08/29 14:27", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40881456/", "pub_types": ["Letter"], "affiliations": ["Department of Ophthalmology, School of Medicine, Infectious Ophthalmologic Research Center, Ahvaz Jundishapur University of Medical Sciences, Ahvaz 6193673166, Iran."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "40879277", "title": "Sensitivity of Repetitive Nerve Stimulation Performed in Early and Later Stages of Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Repetitive nerve stimulation (RNS) is a valuable tool in the diagnostic evaluation of myasthenia gravis (MG). However, there are conflicting reports of its sensitivity when performed ≤ 30 days from symptom onset. We aim to compare the sensitivity of RNS performed in the early versus later stages of MG.\nMETHODS: Data from patients with MG who underwent RNS testing from 2017 to 2021 at Cleveland Clinic and from 1975 to 2001 at Duke University Medical Center were reviewed.\nRESULTS: A total of 525 patients with MG underwent RNS testing. RNS was performed ≤ 30 days after symptom onset in 32 patients (Early RNS) and in 493 patients > 30 days after onset (Late RNS). RNS was abnormal in 56.3% of patients in the Early RNS group and 59.4% of those in the Late RNS group (p = 0.72). There was no difference in RNS positivity rates for either group between the institutions.\nDISCUSSION: We found no significant difference in the sensitivity of RNS performed within or after 30 days from the onset of MG. Our findings support the use and value of RNS in the diagnostic evaluation of MG in patients presenting both early and late.", "authors": ["Heber Morgan E", "Hill Jeremy", "Massey Janice M", "Juel Vern C", "Raja Shruti M", "Li Yuebing", "Sanders Donald B"], "journal": "Muscle & nerve", "entry_date": "2025/08/29 08:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40879277/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Neurological Institute, Cleveland Clinic, Cleveland, Ohio, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40877497", "title": "The Etiology Analysis of Myasthenia Gravis with In-Hospital Mortality in the Neurocritical Care Unit.", "abstract": "BACKGROUND: Our objective was to investigate the characteristics and causes of death in deceased patients with myasthenia gravis (MG).\nMETHODS: This study conducted a retrospective analysis of data from patients with MG in the neurocritical unit at two large general hospitals in China spanning 10 years, from January 2014 to December 2023. Detailed demographic and clinical information were collected for deceased patients. Experienced physicians determined both the underlying and direct causes of death.\nRESULTS: Among 3723 patients, the overall hospitalized mortality was 79 (2.12%). Thymoma was present in 52 (65.82%) of these patients. Compared with the nonthymomatous MG (NTMG) group (n = 27), patients with thymomatous MG (TMG) (n = 52) were significantly younger at death (53.71 ± 14.01 years vs. 65.37 ± 14.61 years, p = 0.001). Septic shock was the most common underlying cause of death, affecting 32 (40.51%) patients, followed by myasthenic crisis in 18 (22.78%) patients. This trend was observed in both the TMG and NTMG groups. In the TMG group, fulminant myocarditis was the third leading underlying cause of death in 9 (17.31%) patients, whereas no cases of fulminant myocarditis were reported in the NTMG group. Among all deceased patients (n = 79), pneumonia was the most common infection, affecting 55 (69.62%) patients, followed by urinary tract infections in 14 (17.72%) patients, bloodstream infections in 13 (16.46%) patients, and intracranial infections in 7 (8.86%) patients.\nCONCLUSIONS: The study suggests that thymoma may increase the risk of death, with septic shock and myasthenic crisis being the most frequent underlying causes in patients with MG.", "authors": ["Chen Hongxi", "Wang Yuan", "Zhang Nana", "Song Jie", "Lin Xue", "Yan Chong", "Huan Xiao", "Shi Ziyan", "Wang Xiaofei", "Zhang Ying", "Du Qin", "Kong Lingyao", "Sun Dongren", "Wang Rui", "Wang Ziya", "Zhang Yangyang", "Xi Jianying", "Zhao Chongbo", "Zhou Hongyu", "Luo Sushan"], "journal": "Neurocritical care", "entry_date": "2025/08/28 23:35", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40877497/", "pub_types": ["Journal Article", "Research Support, Non-U.S. Gov't"], "affiliations": ["Department of Neurology, West China Hospital, Sichuan University, Chengdu, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "2区"}, {"pmid": "40876077", "title": "Serum from patients with MuSK antibody-positive myasthenia gravis triggers transcriptomic changes leading to muscle atrophy and weakness in human myotube cells.", "abstract": "Myasthenia gravis (MG) is an autoimmune disease characterized by autoantibodies targeting the acetylcholine receptor (AChR) or muscle-specific tyrosine kinase (MuSK). These autoantibodies inhibit ACh signal transmission at the neuromuscular junction, leading to muscle weakness and fatigue. Anti-MuSK antibody-positive MG (MuSK+MG) appears more rarely than anti-AChR antibody-positive MG but more frequently results in muscle atrophy. However, the underlying mechanism is unknown. In this study, we analyzed whether serum from MuSK+MG patients has any pathogenic effect on cultured myotube cells. Primary human skeletal muscle myoblasts were differentiated into myotubes, which were then treated with serum from healthy control individuals or MuSK+MG patients. After one day, RNA-seq analysis and Western blotting were performed and myotube diameters were measured. Calcium dynamics following caffeine stimulation was also assessed. Comparing myotube cells treated with healthy control serum with those treated with serum from MuSK+MG patients, RNA-seq analysis showed suppression of pathways associated with muscle function and Western blotting analysis revealed reduced expression of Type II myosin heavy chain. These changes are consistent with muscle atrophy and weakness, although myotube diameter remained unchanged. Caffeine stimulation induced higher cytoplasmic calcium levels. Expression of sarcomere components was significantly reduced. Serum from MuSK+MG patients directly affected gene and protein expression in cultured human myotube cells, leading to changes associated with muscle atrophy and weakness. These findings suggest that there are mechanisms in addition to impaired ACh signal transmission at the neuromuscular junction that can cause muscle weakness and fatigue in MG patients.", "authors": ["Tanaka Keisuke", "Uzawa Akiyuki", "Yasuda Manato", "Onishi Yosuke", "Akamine Hiroyuki", "Handa Hideo", "Ogaya Etsuko", "Miyake Shota", "Baba Masayuki", "Abe Hiroto", "Nagaoka Koki", "Nakatake-Furuie Yuko", "Katsura Yoshichika", "Serizawa Kenichi", "Kuwabara Satoshi"], "journal": "Journal of neuroimmunology", "entry_date": "2025/08/28 18:00", "pub_date": "2025-11-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40876077/", "pub_types": ["Journal Article"], "affiliations": ["Product Research Department, Chugai Pharmaceutical Co., Ltd., 216 Totsuka-cho, Totsuka-ku, Yokohama-shi, Kanagawa 244-8602, Japan. Electronic address: tanaka.keisuke61@chugai-pharm.co.jp."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "40874431", "title": "Multiple concurrent opportunistic infections in patient with myasthenia gravis: A case report.", "abstract": "Myasthenia gravis (MG), a rare autoimmune disorder with poor prognosis, especially when complicated by opportunistic infections, which pose significant risks in clinical practice. We aimed to analyse a clinical case of a middle-aged male patient with MG, who developed severe lower gastrointestinal bleeding and multiple opportunistic infections post-immunosuppressive therapy. This case report is based on comprehensive clinical evaluations, including colonoscopy, histopathological examination, bronchoscopy, bronchoalveolar lavage (BAL), and metagenomic next-generation sequencing (mNGS). The patient exhibited persistent ptosis and pulmonary infection, and was treated with Meropenem 12 mg once daily (qd), Tacrolimus 2 mg qd, and Bromhexine 60 mg three times daily (tid). Due to ongoing lower gastrointestinal bleeding, surgery was performed. Colonoscopy revealed multiple ulcers, with histopathology confirming Cytomegalovirus (CMV) and Histoplasmosis infections. Bronchoalveolar lavage fluid (BALF) identified infections with Aspergillus fumigatus, Talaromyces, and Stenotrophomonas maltophilia. mNGS further detected Pneumocystis jirovecii. Based on these findings, the treatment plan was adjusted to include Amphotericin B complex 25 mg via intravenous (IV) qd, Tigecycline 100 mg q12h, and Sulfamethoxazole (SMZ) 0.96 g q6h for anti-infection, along with Ganciclovir 250 mg IV q12h. The patient continues to receive infusions of immunoglobulins and albumin. This case underscores the importance of monitoring MG patients on immunosuppressive therapy for opportunistic infections, emphasizing the complexity of managing multiple pathogens simultaneously.", "authors": ["Chen Jingrou", "Fang Jingchun", "Sun Li", "Zhang Zongjun", "Ma Qinghua", "Wu Jiahao", "Chen Yili", "Liao Kang", "Long Tiandi", "Xu Hongxu"], "journal": "Virulence", "entry_date": "2025/08/28 06:33", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40874431/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Laboratory Medicine, the First Affiliated Hospital, Sun Yat-sen University, Guangzhou, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.4, "journal_quartile": "1区"}, {"pmid": "40873839", "title": "Clinical and Serological Profile of Myasthenia Gravis in the O'Higgins Region of Chile: A Regional Study.", "abstract": "Myasthenia gravis (MG) is a rare, chronic, and progressive autoimmune disorder that can lead to significant disability in its advanced stages. This retrospective observational study aimed to estimate the prevalence of MG in the O'Higgins Region of Chile and provide a comprehensive characterization of patients' clinical profiles, including medical history, diagnostic findings, and therapeutic responses. A female predominance (n=47, 66.2%) was observed, and most patients showed abnormalities in electrophysiological studies. In nearly all cases, diagnosis was established through autoantibody testing, with acetylcholine receptor antibodies being the most frequently identified. The most frequent comorbidities included mood disorders, hypertension, and thyroid dysfunction. Most patients received cholinesterase inhibitors; corticosteroids were used in 74.6% of cases, and one-third were treated with conventional immunosuppressants. A smaller group received biological therapies such as rituximab or other newer agents, ravulizumab. Despite the range of available treatments, approximately 20% of patients exhibited a refractory disease course. MG is a disease with a multifaceted impact on patients' personal, social, and occupational lives. The findings of this study may support the development of targeted health policies aimed at improving comprehensive care for MG patients in Chile.", "authors": ["Orellana Manuel", "González Miguel", "Muñoz José", "Maragaño Felipe"], "journal": "Cureus", "entry_date": "2025/08/28 04:29", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40873839/", "pub_types": ["Journal Article"], "affiliations": ["Neurology, Dr. Franco Ravera Zunino Hospital, Rancagua, CHL."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40873568", "title": "CAR T-cell therapy in autoimmune diseases: a promising frontier on the horizon.", "abstract": "Although current treatments for autoimmune diseases can effectively control symptoms, they rarely lead to cures and often require lifelong use, accompanied by considerable adverse effects. This emphasizes the urgent need for more targeted therapies that offer long-term efficacy and curative potential. Chimeric antigen receptor (CAR) T-cell therapy presents a promising option by specifically targeting and eliminating autoreactive B cells, with the potential to reset the patient's immune system and promote long-term immune balance. Originally developed for treating hematologic malignancies, where it has achieved remarkable success, recent studies have demonstrated substantial promise of CAR T-cell therapy, such as systemic lupus erythematosus (SLE) and myasthenia gravis. This article provides an overview of the current progress in CAR T-cell therapy for autoimmune diseases, focusing on five key approaches: CD19-targeted CAR T cells, CAR T cells targeting long-lived plasma cells, CAR T cells targeting specific autoantibodies, organ-specific CAR regulatory T cells (Treg cells), and mRNA-engineered CAR T cells. Additionally, this article discusses strategies for optimizing CAR T-cell therapy, including \"off-the-shelf\" allogeneic CAR T-cell therapy, combined CAR T-cell therapy, establishing timely consensus guidelines for their application in autoimmune diseases, and risk stratification strategies aimed at enhancing the personalization of treatments and minimizing adverse effects. While current research results are promising, further large-scale clinical trials and long-term follow-up are essential to thoroughly evaluate the safety and efficacy of CAR T-cell therapy in autoimmune diseases.", "authors": ["Wu Dehong", "Xu-Monette Zijun Y", "Zhou Jia", "Yang Kepeng", "Wang Xinchang", "Fan Yongsheng", "Young Ken H"], "journal": "Frontiers in immunology", "entry_date": "2025/08/28 04:25", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40873568/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Division of Hematopathology, Department of Pathology, Duke University Medical Center, Durham, NC, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40873092", "title": "[Clinical characteristics and prognosis of immune checkpoint inhibitor-associated myasthenia gravis].", "abstract": "The clinical data and follow-up outcomes of 9 patients diagnosed with immune checkpoint inhibitor (ICI)-associated myasthenia gravis (MG) admitted to Henan Provincial People's Hospital from January 2021 to October 2024 were collected retrospectively to analyze their clinical characteristics and prognosis. Nine patients were enrolled, including 4 males and 5 females, aged [M (Q1, Q3)] 69 (55, 77) years. All patients had tumors and had received ICI treatment. The time from the start of ICI treatment to the occurrence of MG symptoms or aggravation of the condition was 26 (20, 39) d. Seven patients were classified Myasthenia Gravis Foundation of America Clinical Classification (MGFA) Ⅲ-Ⅴ. All 9 patients had increased creatine kinase and transaminase. Troponin was measured in 5 patients, and all showed elevated levels. ICI therapy was discontinued in all patients at the onset or exacerbation of MG symptoms, and they subsequently received immunomodulatory therapy with pyridostigmine combined with glucocorticoids and/or intravenous immunoglobulin. Symptoms improved in 7 patients and 2 patients showed poor therapeutic effect. The follow-up time was 12.0 (4.5, 16.5) months, and 2 patients died due to the progression of MG superimposed on underlying diseases at the end of the follow-up. ICI-related MG mostly occurs in the early stage of ICI treatment, and is characterized by severe symptoms, rapid progression, and easy complications with myositis/myocarditis. Active initiation of acetylcholinesterase inhibitors combined with immunotherapy can significantly improve outcomes.\n回顾性收集河南省人民医院2021年1月至2024年10月诊治的9例免疫检查点抑制剂（ICI）相关重症肌无力（MG）患者的临床资料及随访情况，分析患者临床特点及预后。共纳入9例患者，其中男4例，女5例，年龄［M（Q1，Q3）］为69（55，77）岁，所有患者均为肿瘤患者，并接受了ICI治疗。从ICI治疗开始到出现MG症状或病情加重的时间为26（20，39）d，MGFA Ⅲ~Ⅴ型患者7例，9例患者均合并肌酸激酶及转氨酶增高，其中5例患者完善肌钙蛋白检测，结果均增高，所有患者在出现症状或病情加重后停止ICI治疗，并接受了溴吡斯的明联合激素和（或）丙种球蛋白免疫调节治疗，7例患者症状改善，2例患者治疗效果差。随访时间12.0（4.5，16.5）个月，随访结束时2例患者因MG叠加基础疾病进展死亡。ICI相关MG多发生在ICI治疗的早期，且表现为症状重、进展快、易并发肌炎/心肌炎的特点，积极采取乙酰胆碱酯酶抑制剂联合免疫治疗可显著改善预后。.", "authors": ["Meng Q", "Zhu M F", "Huang Z", "Hao X D", "Sun Z Y", "Tan L L", "Li P H", "Zhang Y K", "Zhang J W", "Huang Y"], "journal": "Zhonghua yi xue za zhi", "entry_date": "2025/08/28 02:08", "pub_date": "2025-09-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40873092/", "pub_types": ["English Abstract", "Journal Article"], "affiliations": ["Department of Neurology, Henan Provincial People's Hospital,People's Hospital of Zhengzhou University, Zhengzhou 450003, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.0, "journal_quartile": null}, {"pmid": "40870896", "title": "Machine Learning in Myasthenia Gravis: A Systematic Review of Prognostic Models and AI-Assisted Clinical Assessments.", "abstract": "Background: Myasthenia gravis (MG), a chronic autoimmune disorder with variable disease trajectories, presents considerable challenges for clinical stratification and acute care management. This systematic review evaluated machine learning models developed for prognostic assessment in patients with MG. Methods: Following PRISMA guidelines, we systematically searched PubMed, Embase, and Scopus for relevant articles published from January 2010 to May 2025. Studies using machine learning techniques to predict MG-related outcomes based on structured or semi-structured clinical variables were included. We extracted data on model targets, algorithmic strategies, input features, validation design, performance metrics, and interpretability methods. The risk of bias was assessed using the Prediction Model Risk of Bias Assessment Tool. Results: Eleven studies were included, targeting ICU admission (n = 2), myasthenic crisis (n = 1), treatment response (n = 2), prolonged mechanical ventilation (n = 1), hospitalization duration (n = 1), symptom subtype clustering (n = 1), and artificial intelligence (AI)-assisted examination scoring (n = 3). Commonly used algorithms included extreme gradient boosting, random forests, decision trees, multivariate adaptive regression splines, and logistic regression. Reported AUC values ranged from 0.765 to 0.944. Only two studies employed external validation using independent cohorts; others relied on internal cross-validation or repeated holdout. Of the seven prognostic modeling studies, four were rated as having high risk of bias, primarily due to participant selection, predictor handling, and analytical design issues. The remaining four studies focused on unsupervised symptom clustering or AI-assisted examination scoring without predictive modeling components. Conclusions: Despite promising performance metrics, constraints in generalizability, validation rigor, and measurement consistency limited their clinical application. Future research should prioritize prospective multicenter studies, dynamic data sharing strategies, standardized outcome definitions, and real-time clinical workflow integration to advance machine learning-based prognostic tools for MG and support improved patient care in acute settings.", "authors": ["Chung Chen-Chih", "Wu I-Chieh", "Bamodu Oluwaseun Adebayo", "Hong Chien-Tai", "Chiu Hou-Chang"], "journal": "Diagnostics (Basel, Switzerland)", "entry_date": "2025/08/28 01:17", "pub_date": "2025-08-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40870896/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Taipei Medical University Shuang Ho Hospital, New Taipei City 235, Taiwan."], "china_related": true, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 3.8, "journal_quartile": "3区"}, {"pmid": "40867301", "title": "Clinicopathological Features and Pathogenesis of Thymoma Complicated with Alopecia Areata: A Multicenter, Matched Case Analysis.", "abstract": "BACKGROUND: Thymoma is a malignant tumor originating from the thymic epithelium and can be associated with over 100 paraneoplastic syndromes (PNSs). Due to the low incidence of thymoma and the relative rarity of alopecia areata (AA) as an associated autoimmune disease, patients with thymoma combined with AA are relatively uncommon in clinical practice. As a result, the clinicopathological features and pathogenesis of such patients have been rarely investigated.\nMETHODS: This study retrospectively analyzed the clinical records of thymoma patients who underwent surgical treatment at Peking Union Medical College Hospital and Beijing Tongren Hospital from August 2014 to July 2019, with a focus on the clinicopathological features of thymoma patients with AA. Propensity score matching (PSM) was employed to create a 1:5 matched comparison group with thymoma patients without AA.\nRESULTS: A total of 428 thymoma patients were included, among which 9 had AA. Using PSM, we matched 45 control patients without AA based on age and gender. The analysis revealed that thymoma patients with AA had a significantly higher proportion of myasthenia gravis (MG) [100.00% (9/9) vs. 66.67% (30/45), p = 0.049], although there were no significant differences between the AChR antibodies, Titin antibodies, MG severity, and the incidence of postoperative myasthenic crisis. However, the proportion of thymoma patients with AA who also had other PNSs besides MG was significantly higher [88.89% (8/9) vs. 6.67% (3/45), p < 0.001]. Additionally, CD4+/CD8+ T-cell inversion in the serum was observed at a much higher rate in thymoma patients with AA [100.00% (9/9) vs. 24.44% (11/45), p < 0.001].\nCONCLUSIONS: We hypothesize that the pathogenesis of thymoma with AA differs from that of thymoma with MG, though there may be a correlation. The etiology of thymoma with AA may be attributed to abnormal autoimmune CD8+ T lymphocytes produced by the thymoma, which can also lead to other cytotoxic T-cell-mediated autoimmune diseases.", "authors": ["Du Xin", "Gao Xuehan", "Cui Jian", "Yu Xintao", "Huang Cheng", "Chen Yeye", "Guo Chao", "Zhang Ye", "Gao Chao", "Diao Xiayao", "Yu Lei", "Li Shanqing"], "journal": "Cancers", "entry_date": "2025/08/28 01:02", "pub_date": "2025-08-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40867301/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, Peking Union Medical College Hospital, Chinese Academy of Medical Science & Peking Union Medical College, Beijing 100730, China."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "40867040", "title": "Artificial Intelligence Diagnosis of Ocular Motility Disorders From Clinical Videos.", "abstract": "BACKGROUND: Multimodal artificial intelligence (AI) models have recently expanded into video analysis. In ophthalmology, one exploratory application is the automated detection of extraocular movement (EOM) disorders. This proof-of-concept study evaluated the feasibility of using Gemini 2.0 to recognize EOM abnormalities, identify the affected eye, and recognize specific movement limitations from publicly available, real-world clinical videos.\nMETHODS: We retrospectively collected 114 YouTube videos of EOM disorders, including cranial nerve (CN) palsies, internuclear ophthalmoplegia (INO), supranuclear disorders, nystagmus, and ocular myasthenia gravis (MG), alongside 15 control videos demonstrating normal EOMs. Videos were trimmed to include only the pertinent clinical examinations, and audio was removed to avoid diagnostic cues. Using a standardized zero-shot prompt, Gemini 2.0 analyzed each video via the Google AI Studio platform. Gemini 2.0 was evaluated based on its ability to provide the correct diagnosis, identify the affected eye, and recognize the specific movement limitation (if any). Descriptive statistics, Spearman correlations, and comparative analyses were used to assess performance.\nRESULTS: Gemini 2.0 correctly identified the primary diagnosis in 43 of 114 videos, yielding an overall diagnostic accuracy of 37.7%. Diagnostic performance varied by condition, with the highest accuracies observed in third nerve palsy (81.1%), INO (80.0%), sixth nerve palsy (66.7%), and ocular MG (20.0%), whereas normal EOMs were correctly classified in 93.3% of cases. In misclassified cases, the correct diagnosis appeared in the differential diagnosis in 15.5% of instances. Laterality was correctly identified in 26.5% of eligible cases overall, 73.1% among correctly diagnosed cases vs. 9.6% in misclassified ones. Similarly, movement limitations were accurately identified in 30.3% of eligible cases overall, with a marked increase to 88.5% accuracy in correctly diagnosed cases compared to 9.6% in misclassified cases. Longer videos moderately correlated with longer processing time (ρ = 0.55, P < 0.001). Significant correlations were observed between correct diagnosis and correct laterality identification (ρ = 0.45, P < 0.001), correct diagnosis and correct movement limitation identification (ρ = 0.61, P < 0.001), and laterality and movement limitation (ρ = 0.51, P < 0.001). Processing time averaged 11.0 seconds and correlated with video length (ρ = 0.55, P < 0.001).\nCONCLUSIONS: This proof-of-concept study demonstrates the feasibility of using Gemini 2.0 for automated recognition of EOM abnormalities in clinical videos. Although performance was stronger in overt cases, overall diagnostic accuracy remains limited. Substantial validation on standardized, clinician-annotated datasets is needed before clinical application.", "authors": ["Mikhail David", "Balas Michael", "Micieli Jonathan A"], "journal": "Journal of neuro-ophthalmology : the official journal of the North American Neuro-Ophthalmology Society", "entry_date": "2025/08/28 00:03", "pub_date": "2026-03-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40867040/", "pub_types": ["Journal Article"], "affiliations": ["Temerty Faculty of Medicine (DM), University of Toronto, Toronto, Canada; Department of Ophthalmology and Vision Sciences (MB, JAM), University of Toronto, Toronto, Canada; Division of Neurology (JAM), Department of Medicine, St. Michael's Hospital, University of Toronto, Toronto, Canada; Kensington Vision and Research Centre (JAM), Toronto, Canada; Department of Ophthalmology (JAM), St. Michael's Hospital, Unity Health, Toronto, Canada; and Department of Ophthalmology (JAM), Toronto Western Hospital, University Health Network, Toronto, Canada."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "40865505", "title": "Da Vinci Xi robot -assisted subxiphoid resection of thymoma and reconstruction of the left brachiocephalic vein: A case report.", "abstract": "BACKGROUND: Thymomas are the most common anterior mediastinal malignancies, typically requiring surgical resection. While median sternotomy has been the traditional approach, robotic-assisted thymectomy using the Da Vinci Xi system is reshaping minimally invasive surgery. Its 12× magnification, 3D visualization, and articulating instruments with tremor suppression allow precise dissection in anatomically constrained areas, particularly in tumors with vascular invasion, compared with the more aggressive classical approach.\nCASE PRESENTATION: A 67-year-old man presented with ptosis and muscle weakness, indicative of myasthenia gravis. CT imaging revealed a 4.5 × 3.0 cm anterior mediastinal mass invading the left brachiocephalic vein, superior vena cava, pericardium, and right upper lung lobe. Robotic-assisted thymectomy via a subxiphoid approach using the Da Vinci Xi system was performed. The tumor and the invaded left brachiocephalic vein were resected en bloc, followed by vascular reconstruction using a 10-mm Gore-Tex graft anastomosed end-to-end to the right atrial appendage. Robotic assistance enabled meticulous dissection and intracorporeal anastomosis. Pathology confirmed stage IVB thymic carcinoma. Recovery was uneventful, with resolution of myasthenic symptoms and graft patency on follow-up.\nDISCUSSION: This case demonstrates the feasibility of robotic thymectomy with vascular reconstruction. The Da Vinci Xi system enhanced surgical precision and control. Despite a prolonged operative time and need for anticoagulation, the approach may reduce morbidity and improve tumor control, though further evaluation in advanced-stage cases is needed.\nCONCLUSIONS: Robotic-assisted resection of invasive thymoma with vascular reconstruction is feasible and safe, enabling radical excision in anatomically complex scenarios.", "authors": ["Xie Fengwen", "Yin Sui", "Wu Hao", "Peng Lei", "Pei Xu", "Xu Quan"], "journal": "International journal of surgery case reports", "entry_date": "2025/08/27 18:11", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40865505/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Thoracic Surgery, Jiangxi Provincial People's Hospital, The First Affiliated Hospital of Nanchang Medical College, Nanchang, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 10.1, "journal_quartile": "2区"}, {"pmid": "40865296", "title": "Clinical heterogeneity, treatment patterns, and outcomes of advanced-age-onset myasthenia gravis in China: a retrospective cohort study.", "abstract": "OBJECTIVES: The clinical characteristics and outcomes of myasthenia gravis (MG) with onset at age 50 years or older, which commonly referred to as late-onset MG (LOMG), in elderly patients remain incompletely understood. This study aimed to address the clinical heterogeneity within LOMG and to clarify whether very-late-onset MG (≥70 years) constitutes a distinct phenotype requiring tailored management approaches.\nMETHODS: We analyzed data from 2783 patients enrolled in the MG Registry between April 1, 2009, and December 31, 2020. Patients with LOMG were further stratified into two subgroups: those with MG onset at age 50-69 years (referred to as Early-LOMG), and those with onset at age ≥70 years (referred to as advanced-onset MG, AOMG). Clinical features, diagnostic tests, treatments, and outcomes were compared across subgroups.\nRESULTS: Of the 982 patients with LOMG, 191 (19.4 %) were classified as AOMG. Compared to patients with MG onset at age 50-69 years, those with onset at age ≥70 years (AOMG) had a higher proportion of females (57.6 % vs 48.7 %, p = 0.027), and were more frequently positive for AChR-Ab (81.2 % vs 70.4 %, p = 0.001) and Titin-Ab (32.5 % vs 22.5 %, p = 0.004), and were more likely to present with bulbar muscle involvement at onset (25.3 % vs 14.8 %) and during disease progression (53.7 % vs 38.6 %). The positive rate of repetitive nerve stimulation (RNS) testing was also higher in the AOMG group (57.1 % vs 35.8 %, p = 0.018). Thymoma was less frequent (12.1 % vs 29.6 %, p = 0.006), and fewer AOMG patients underwent thymectomy (2.6 % vs 31.0 %, p < 0.001). AOMG patients generally required fewer immunosuppressive therapies and achieved comparable functional outcomes. However, the mortality rate was significantly higher in the AOMG group (p = 0.020), primarily due to MG crisis.\nCONCLUSIONS: AOMG exhibits distinct clinical features compared to Early-LOMG, characterized by a higher frequency of bulbar involvement, lower thymoma prevalence, less aggressive treatment, and higher mortality. Tailored management strategies are warranted for elderly patients with MG.", "authors": ["Ji Ying", "Zhou Shuxian", "He Xiaoxiao", "Li Wenbo", "Zhao Xue", "Zhang Yingna", "Zhang Jing", "Lv Jie", "Liu Peipei", "Cui Weike", "Yang Junhong", "Gao Feng"], "journal": "Journal of clinical neuroscience : official journal of the Neurosurgical Society of Australasia", "entry_date": "2025/08/27 18:06", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40865296/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Second Affiliated Hospital of Zhengzhou University, Zhengzhou 450014, China; Department of Neuroimmunology, Henan Institute of Medical and Pharmaceutical Sciences, Zhengzhou University, Zhengzhou 450052, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "40860974", "title": "The short-term prognosis of very late onset generalized myasthenia gravis: a single-center retrospective cohort study.", "abstract": "OBJECTIVE: To explore the short-term prognosis of generalized very-late-onset myasthenia gravis (vloMG, symptom onset ≥65 years) in comparison with early- and late-onset MG (eloMG, <65 years).\nMETHODS: A single-center retrospective cohort study was conducted based on the medical records of patients with laboratory confirmed generalized MG, monitored in the specialized Unit of Neuromuscular Disorders of the University Hospital of Patras. Measures of clinical severity were compared at baseline and over the short term (2-year) follow-up.\nRESULTS: There were 42 eligible patients (42.1 ± 13.2 years, 50% women, 19.5 ± 6.0 months follow-up) in the eloMG and 26 (72.4 ± 5.0, 50% women, 13.9 ± 7.9 months follow-up) in the vloMG group. In the vloMG group, AchR antibody positivity (89% vs. 57%, p = 0.007) and oculo-bulbar symptoms at onset (88% vs. 53%, p = 0.002) were more common, whereas thymus pathology (0% vs. 40%, p < 0.001) and generalized weakness at onset (12% vs. 38%, p = 0.018) were less frequent. Intubation within the first month from diagnosis was required only in patients with vloMG (5/26) (p = 0.006). Over the follow-up: the unadjusted incidence rate ratio (IRR) of relapses was lower in the vloMG group [IRR = 0.49, 95% CI = (0.26, 0.92), p = 0.026], the unadjusted odds (OR) of being classified as <IIb on the MGFA classification were higher in the vloMG group [OR = 2.27 95% CI = (1.02, 5.05), p = 0.043] and the average unadjusted difference in corticosteroid intake was lower in the vloMG group by approximately 6.9 mg [(-10.6, 3.3), p < 0.001] in equivalent doses of prednisolone [6.1 mg (-10.0, -2.2), p = 0.002, according to adjusted estimations].\nCONCLUSION: Despite its more aggressive onset, vloMG has a more favorable prognosis than eloMG.", "authors": ["Liampas Ioannis", "Veltsista Dimitra", "Batzikosta Paraskevi", "Lazarou Lefteris", "Kefalopoulou Zinovia Maria", "Chroni Elisabeth"], "journal": "Frontiers in neurology", "entry_date": "2025/08/27 06:35", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40860974/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Center, Department of Neurology, University Hospital of Patras, Patras, Greece."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40857039", "title": "Comparison of the Quantitative Myasthenia Gravis and Myasthenia Gravis Activity of Daily Living Scores From a Clinical Practice Perspective.", "abstract": "INTRODUCTION/AIMS: Myasthenia gravis (MG) is characterized by fluctuating symptoms, making the assessment of disease activity challenging. Discordance between the clinician-reported quantitative myasthenia gravis (QMG) score and the patient-reported MG activity of daily living (MG-ADL) has previously been observed. We aimed to compare QMG and MG-ADL in a clinical practice setting and to relate to the quality-of-life instrument myasthenia gravis quality of life 15 (MG-QoL-15).\nMETHODS: MG patients simultaneously assessed by QMG, MG-ADL, and MG-QoL-15 (n = 177) identified in the Swedish MG registry were included. The distribution of total scores for QMG and MG-ADL and per-item score discordance was investigated using the Chi-squared test and paired t-tests. Multivariate linear regression models were constructed to identify factors associated with QMG and MG-ADL.\nRESULTS: MG-ADL exhibited a lower floor effect compared to QMG (14% vs. 28%, p = 0.002) and patients reported significantly worse scores with MG-ADL than QMG, particularly in bulbar and respiratory items (for breathing item 38% MG-ADL > QMG vs. 5% MG-ADL < QMG score). Multivariate analysis revealed that new-onset status, MG-QoL-15 score, and a history of prednisolone treatment were significantly associated with QMG scores, whereas only MG-QoL-15 was significantly associated with MG-ADL. These associations were driven by symptom-associated questions in MG-QoL-15, while the emotional well-being questions were associated with neither QMG nor MG-ADL.\nDISCUSSION: We observed that MG-ADL more readily identified residual symptoms in patients with mild disease activity compared to QMG; however, with a stronger influence of quality of life, suggesting a complementarity of the two scores in clinical practice.", "authors": ["Wu Wanqing", "Petersson Malin", "Piehl Fredrik", "Brauner Susanna"], "journal": "Muscle & nerve", "entry_date": "2025/08/26 11:34", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40857039/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Clinical Neuroscience, Karolinska Institutet, Stockholm, Sweden."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40856578", "title": "Effect of the COVID-19 Pandemic on the Quality of Life of Pediatric Patients with Myasthenia.", "abstract": "BackgroundThe symptoms of myasthenia can fluctuate with a variety of environmental factors such as anxiety, depression, and stress. Studies in adults with myasthenia gravis have identified changes in rating of quality of life during the COVID-19 pandemic although no evaluation has been performed in pediatric populations. This study sought to evaluate the effect of the COVID-19 pandemic on quality of life (QOL), as measured by MG-QOL15r and MG-ADL scores in a cohort of pediatric patients with myasthenia.MethodsA single-center, retrospective review of children with myasthenia (congenital or acquired) was performed. Individuals were included if they had MG-QOL15r or MG-ADL documented between March 2020 and December 2021 as well as at least 1 prior MG-QOL15r or MG-ADL score documented between January 2019 and February 2020. QOL scores, grip or pinch strength on physical examination, physician impressions, disease duration and treatments, and demographic information were collected. Scores were analyzed using paired t tests.ResultsOf 35 individuals with myasthenia, 8 (23%) met inclusion criteria. Although there was no statistically significant difference in MG-QOL15r score (t = 2.31, P = .054), MG-ADL score (t = 2.09, P = .08), or gross grasp strength (t = 0.78, P = .46) between the 2 time points on paired t-testing, MG-QOL15r scores trended upward on visits conducted in March 2020 or afterward.DiscussionIn a small cohort of children with myasthenia, measures of quality of life were not impacted by the pandemic although trends toward decreased quality of life emerged. Further investigation into the effects of the pandemic on pediatric populations is warranted.", "authors": ["Sosa Natasha N", "Pascual Marielle", "Paquin Yvette", "Dawoud Adina", "David Jed", "Santoro Jonathan D", "Tiongson Emmanuelle", "Ramos-Platt Leigh"], "journal": "Journal of child neurology", "entry_date": "2025/08/26 09:53", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40856578/", "pub_types": ["Journal Article"], "affiliations": ["Division of Neurology, Department of Pediatrics, Children's Hospital Los Angeles, Los Angeles, CA, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.6, "journal_quartile": "3区"}, {"pmid": "40856088", "title": "Durability of Response to B-Cell Maturation Antigen-Directed mRNA Cell Therapy in Myasthenia Gravis.", "abstract": "OBJECTIVE: We report the 12-month follow-up outcomes from a Phase 2 clinical trial (NCT04146051) evaluating Descartes-08, a BCMA-directed RNA chimeric antigen receptor T-cell (rCAR-T) therapy for refractory generalized myasthenia gravis (MG). These findings provide insight into the potential applicability of BCMA-targeted rCAR-T therapy for antibody-mediated autoimmune diseases.\nMETHODS: In the Phase 2a part of the study, Descartes-08 was administered at 52.5 × 106 CAR+ cells/kg per infusion with varying dosing frequencies as an outpatient treatment and without lymphodepletion chemotherapy. A subset of participants received Descartes-08 as six weekly infusions and were followed long term with assessments conducted at 2, 3, 6, 9, and 12 months.\nRESULTS: All seven participants who received six weekly infusions of Descartes-08 exhibited clinically meaningful improvement in common MG severity scales (MG Composite, MG Activities of Daily Living, Quantitative MG scores, and Quality of Life 15-revised) at Month 3 without significant toxicity. At Month 9 follow-up, all participants continued to experience marked clinically meaningful improvements. Five out of seven participants maintained the response at Month 12. A third participant experienced a relapse approximately 6 months after completing on-study follow-up. All three participants who experienced loss of clinical effects were retreated. Two had rapid improvement in clinical scores with minimal symptom expression at Week 8, which was maintained through 12 months of retreatment follow-up. The third participant experienced similar improvement in MG severity scores to their initial treatment.\nINTERPRETATION: These data support continued development of Descartes-08 in myasthenia gravis and other autoantibody-associated autoimmune disorders.", "authors": ["Chahin Nizar", "Sahagian Gregory", "Feinberg Marc H", "Stewart C Andrew", "Jewell Christopher M", "Kurtoglu Metin", "Miljković Miloš D", "Vu Tuan", "Mozaffar Tahseen", "Howard James F"], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/08/26 05:43", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40856088/", "pub_types": ["Clinical Trial, Phase II", "Journal Article", "Randomized Controlled Trial"], "affiliations": ["Department of Neurology, Oregon Health and Sciences University, Portland, Oregon, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40854024", "title": "Recognition and Treatment of Concurrent Amyotrophic Lateral Sclerosis and Myasthenia Gravis.", "abstract": "", "authors": ["Stiles Katherine", "LaBarbera Vincent"], "journal": "Rhode Island medical journal (2013)", "entry_date": "2025/08/25 14:12", "pub_date": "2025-09-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40854024/", "pub_types": ["Journal Article"], "affiliations": ["Staff Physician, Southcoast Physicians Group, Dartmouth, MA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40852525", "title": "Surgical treatment of myasthenia gravis: 10 years of single center experience.", "abstract": "OBJECTIVE: To evaluate a 10-year experience in the surgical treatment of patients with myasthenia gravis, focusing on clinical and pharmacological outcomes.\nMETHODS: A retrospective single-center study was conducted based on prospective data collection from the Redcap® maintained by the Thoracic Surgery Department in a Brazilian tertiary hospital. Patients with myasthenia gravis (AchR positive), who underwent surgical treatment as an adjuvant to clinical therapy were included.\nRESULTS: The study comprised 85 patients with a mean age of 43 years; 75% were female. Regarding the type of surgery, 24.7% underwent sternotomy and 75.3% minimally invasive approach. The median hospital stay was 4.0 days (p25 = 3.0; p75 = 5.5), and the median ICU stay was 1.0 days (p25 = 0.40, p75 = 2). Postoperative outcomes showed a corticosteroid reduction in 52 participants (61%), and 30 (35%) showed anticholinesterase reduction. The median dose of corticosteroids before surgery was 40.00 mg, and after surgery, 20.00 (p-value < 0.001). Based on Osserman classification, before surgery, it was observed that 4% had grade I, 15% grade IIa, 32% grade IIb, 31% grade III, and 18% grade IV. After surgery, it was observed that 28.5% were asymptomatic, 28% had grade I, 34% had grade IIa, 3.6% had grade IIb, and 5.9% had grade III. There was no statistical difference in clinical and pharmacological response in the analysis with and without thymoma and myasthenia (p-value 0.403; p-value 0.104). About the surgical approach, patients undergoing thymectomy by sternotomy have longer hospital and ICU stays with statistical significance (p-value <0.001; p-value 0.005).\nCONCLUSION: This study demonstrated that surgical treatment for myasthenia gravis is safe and effective for symptom control and medication reduction, regardless of the surgical approach, with shorter ICU and hospital stays through the minimally invasive approach.", "authors": ["Moraes Neto José De Sá", "Fonini Jaqueline Schaparini", "De Assis Cavalcanti Neto Francisco", "De Oliveira Fernanda Aquino", "Aranha Gabriel Lunardi", "Zambon Antonio Alberto", "Estephan Eduardo De Paula", "Zanoteli Edmar", "Pêgo-Fernandes Paulo Manuel", "Mariani Alessandro Wasum"], "journal": "Frontiers in neurology", "entry_date": "2025/08/25 05:15", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40852525/", "pub_types": ["Journal Article"], "affiliations": ["University of São Paulo, São Paulo, Brazil."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40849050", "title": "Efgartigimod versus standard of care in new-Onset AChR subtype generalized myasthenia gravis: A prospective cohort study.", "abstract": "Efgartigimod (EFG) is usually used to treat generalized myasthenia gravis (gMG) with long disease duration; the benefit in new-onset gMG remained unknown. This study included 87 new-onset gMG patients who received either oral steroid and immunosuppressive treatment (Conventional group, n = 30) or combined with EFG (EFG group, n = 57). The primary outcome was minimal symptom expression (MSE) responders, as denoted by a Myasthenia Gravis Activities of Daily Living (MG-ADL) of 0 or 1 for over 4 weeks. At 12 weeks, the proportion of MSE responders was significantly higher in the EFG group (45.61 %, 26/57 vs. 13.33 %, 4/30, p = 0.0026). With the EFG group, patients with late-onset gMG had greater reductions in MG-ADL than those associated with thymoma (7.06 ± 3.25 vs. 4.96 ± 3.40, p = 0.040). EFG may be a promising treatment for rapid disease control in new-onset gMG, but future studies are still required to assess the cost-effectiveness and long-term safety.", "authors": ["He Dingxian", "Jin Lei", "Wang Shuangshuang", "Zhong Huahua", "Chen Hongxi", "Zhou Hongyu", "Zou Zhangyu", "Zhao Chongbo", "Huan Xiao", "Song Jie", "Xi Jianying", "Yan Chong", "Luo Sushan"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2025/08/23 19:25", "pub_date": "2025-08-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40849050/", "pub_types": ["Journal Article"], "affiliations": ["Huashan Rare Disease Centre and Department of Neurology, Huashan Hospital, Shanghai Medical College, National Centre for Neurological Disorders, Fudan University, Shanghai 200040, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "40847050", "title": "Safety and effect of topical neostigmine ophthalmic solution in animal models.", "abstract": "The study aimed to evaluate the safety and effect of various dosages of topical neostigmine ophthalmic solution (TNOS) in animal models and establish a recommended dosage for further studies on myasthenia gravis (MG) diagnosis. A placebo-controlled, sequential ascending dose study was conducted in healthy rabbits. Eighteen eyes were randomized to receive one of three concentrations (1.0, 1.5, and 2.5 mg/mL) of TNOS. Pupillary sizes over time were compared with control group that received normal saline solution (NSS). Mean pupillary size of the 1.5 mg/mL group was significantly smaller than control at 30 to 180 min after instillation (maximal mean difference (TNOS - NSS); mMD - 2.58, 95% confidence interval (95% CI) -4.24 to -0.93, p = 0.006). The mean pupillary size of the 2.5 mg/mL group was significantly smaller than the control at 60 to 90 min (mMD - 3.13, 95% CI -5.07 to -1.18, p = 0.005). No significant difference in pupillary size between 1.5 and 2.5 mg/mL groups was observed at any time points. No systemic or ocular complications were observed in any concentration. The 1.5 mg/mL TNOS was the lowest efficacious dose in this study without adverse effects and was considered a promising starting dose for further MG studies.", "authors": ["Ongprakobkul Chuthamas", "Jariyakosol Supharat", "Apinyawasisuk Supanut", "Rattanapinyopituk Kasem", "Chariyavilaskul Pajaree", "Meesilpavikkai Kornvalee", "Chongpison Yuda"], "journal": "Scientific reports", "entry_date": "2025/08/22 23:44", "pub_date": "2025-08-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40847050/", "pub_types": ["Journal Article"], "affiliations": ["Department of Ophthalmology, Faculty of Medicine, Chulalongkorn University, Bangkok, Thailand."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40845416", "title": "Reduction in oral glucocorticoid use after efgartigimod initiation in clinical practice among patients with generalized myasthenia gravis.", "abstract": "This study evaluated changes in oral glucocorticoid (GC, prednisone equivalent) use among patients with generalized myasthenia gravis (gMG) previously using chronic GCs, who initiated and continued efgartigimod for ≥12 months, identified retrospectively from a US claims database. Myasthenia Gravis Activities of Daily Living (MG-ADL) scores were retrieved from a patient support program. The primary outcome was GC average daily dose (GC ADD) assessed during the 3 months before and 3, 6, 9, and 12 months after efgartigimod initiation. Overall, 266 patients were included (mean age: 59.8 years; 45 % female). Mean (95 % CI) GC ADD was significantly reduced at 3 (14.3 [12.6, 16.0] mg/day), 6 (13.4 [11.5, 15.4] mg/day), 9 (11.6 [10.0, 13.3] mg/day), and 12 (10.2 [8.8, 11.6] mg/day) months post-efgartigimod initiation compared to baseline (17.9 [15.7, 20.1] mg/day) (p < 0.001). At 12 months, 66 % (n = 176/266) reduced steroid dose. Among those, 68 % and 51 % achieved ≥50 % and ≥ 75 % ADD reduction, respectively. The proportion of patients using GC ADD of ≤5 mg/day increased from 13 % at baseline to 42 % at 12 months. Among 126 patients (47 %) who had MG-ADL scores available, there was a significant reduction from baseline in best follow-up mean (95 % CI) MG-ADL (from 7.9 [7.2, 8.5] to 3.1 [2.6, 3.6]), while mean GC ADD remained significantly reduced (p < 0.05). Thus, in patients with gMG using chronic GCs at baseline, GC use substantially reduced following efgartigimod initiation, while retaining improved MG-ADL scores, underscoring the potential steroid-sparing effect of efgartigimod in gMG treatment.", "authors": ["Goyal Neelam", "Qi Cynthia", "Stone John", "Ruck Tobias", "Wolfe Gil I", "Smith A Gordon", "Gelinas Deborah", "Jefferson Matthew", "Brauer Edward", "Suthagar Tharun Balaji", "Menon Rohit R", "Sato Mai", "Phillips Glenn", "Narayanaswami Pushpa"], "journal": "Journal of the neurological sciences", "entry_date": "2025/08/22 17:59", "pub_date": "2025-10-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40845416/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology & Neurological Sciences, Stanford Medicine, 213 Quarry Rd, Palo Alto, CA 94304, USA. Electronic address: neelamji@stanford.edu."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "40843812", "title": "FcRn inhibitors for myasthenia gravis.", "abstract": "This is a protocol for a Cochrane Review (intervention). The objectives are as follows: To evaluate the benefits and harms of FcRn inhibitors for the maintenance treatment of myasthenia gravis in adult participants compared with control treatment (placebo, standard-of-care therapy, an alternative FcRn inhibitor, or an alternative immunomodulatory therapy). We will evaluate the efficacy of the treatment by the effect on disease severity and functional impairment, as assessed using a measurement tool validated for use in myasthenia gravis. Where possible, we will assess whether the effects of FcRn inhibitors differ according to different participant subgroups or different treatment regimens, or both. These data will be used to inform policymakers on the participant subgroups most likely to benefit from treatment and the most efficacious treatment regimen.", "authors": ["White Laura M", "Clay Fiona J", "Forbes Anne-Marie", "Keh Ryan Yann Shern", "Lilleker James B", "Spillane Jennifer", "Storms Karen", "Dodd Katherine C", "Sussman Jon"], "journal": "The Cochrane database of systematic reviews", "entry_date": "2025/08/22 06:44", "pub_date": "2025-08-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40843812/", "pub_types": ["Journal Article", "Research Support, Non-U.S. Gov't"], "affiliations": ["Lancaster Medical School, Lancaster University, Lancaster, UK."], "china_related": false, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 9.4, "journal_quartile": "1区"}, {"pmid": "40843740", "title": "Plasma Biomarkers of Mitochondrial Dysfunction in Patients with Myasthenia Gravis.", "abstract": "Background. Myasthenia gravis is an autoimmune neuromuscular disease characterized by fatigue of striated muscles due to impaired neuromuscular transmission. Mitochondrial dysfunction, according to published data, contributes significantly to metabolic abnormalities, oxidative stress and, as a consequence, the persistence of inflammation. MicroRNAs, which are post-transcriptional regulators of expression, are able to contribute to the aberrant functioning of mitochondria. In this study, with the aim of searching for biomarkers at the level of circulating microRNAs and proteins, the expression of three microRNAs was analyzed and the concentration of mitochondrial proteins was measured in the blood plasma of patients with myasthenia gravis (n = 49) in comparison with healthy volunteers (n = 31). Methods. Expression analysis was performed by RT-PCR, mathematical data processing was carried out using the Livak method, and protein concentration was determined by enzyme immunoassay. Results. Our plasma expression analysis revealed a statistically significant increase in hsa-miR-194-5p expression (Log10 Fold Change = 1.46, p-value < 0.0001) and a statistically significant decrease in hsa-miR-148a-3p expression (Log10 Fold Change = -0.65, p-value = 0.02). A statistically significant decrease in plasma COQ10A concentration was also found (0.911 [0.439; 1.608] versus 1.815 [1.033; 2.916] for myasthenia gravis and controls, respectively, p-value = 0.01). Conclusion. Our data suggest hsa-miR-148a-3p and hsa-miR-194-5p, as well as COQ10A, as potential biomarkers of mitochondrial dysfunction in myasthenia gravis.", "authors": ["Timechko Elena E", "Severina Marina I", "Yakimov Alexey M", "Vasilieva Anastasia A", "Paramonova Anastasia I", "Isaeva Natalya V", "Prokopenko Semen V", "Dmitrenko Diana V"], "journal": "Medical sciences (Basel, Switzerland)", "entry_date": "2025/08/22 06:43", "pub_date": "2025-08-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40843740/", "pub_types": ["Journal Article"], "affiliations": ["Russian National Research, V.F. Voyno-Yasenetsky Krasnoyarsk State Medical University, 660022 Krasnoyarsk, Russia."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9}, {"pmid": "40843677", "title": "FcRn Blockade as a Targeted Therapeutic Strategy in Antibody-Mediated Autoimmune Diseases: A Focus on Warm Autoimmune Hemolytic Anemia.", "abstract": "Antibody-mediated autoimmune diseases are common, can involve any organ system, and pose a large burden for patients and healthcare systems. Most antibody-mediated diseases are mediated by IgG antibodies. Selective targeting of pathogenic antibodies is an attractive treatment option which has already proven to be effective in antibody-positive generalized myasthenia gravis, maternal-fetal alloimmune cytopenias, and immune thrombocytopenic purpura. Warm autoimmune hemolytic anemia (wAIHA) is an autoimmune disorder mediated by pathogenic antibodies mainly of the IgG class with no approved therapy. Current treatment includes non-specific immunosuppression with corticosteroids, rituximab, and other immunosuppressive agents. With most therapies, time to response can be delayed and transfusions may be needed. Neonatal Fc receptor (FcRN) therapies provide rapid and sustained reduction of pathogenic IgG levels providing potential for fast, effective therapy in antibody-mediated autoimmune diseases including warm autoimmune hemolytic anemia. This review focuses on the emerging role of FcRn inhibition in autoimmune hematologic diseases, and their therapeutic potential in wAIHA.", "authors": ["Sandhu Michael", "Murakhovskaya Irina"], "journal": "Antibodies (Basel, Switzerland)", "entry_date": "2025/08/22 06:43", "pub_date": "2025-08-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40843677/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Montefiore Medical Center, Albert Einstein College of Medicine, Bronx, NY 10461, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.3}, {"pmid": "40843319", "title": "Acquired Myasthenia Gravis in a Juvenile Australian Shepherd Dog and Efficacy of Leflunomide Treatment.", "abstract": "Myasthenia gravis is a disorder of neuromuscular transmission characterized by muscle weakness and exercise intolerance that is rarely diagnosed in dogs younger than 6 months. We report a case of juvenile-onset myasthenia gravis in a 5-month-old, intact male Australian Shepherd with onset of clinical signs at 4 months of age. The dog presented with a 4-week history of progressive weakness and regurgitation. Diagnosis was confirmed by an elevated serum acetylcholine receptor antibody concentration. Treatment with pyridostigmine provided only partial improvement. Leflunomide was added to achieve immunosuppression while avoiding the side effects of corticosteroids, such as muscle weakness. This treatment combination was well-tolerated; the dog went into clinical remission, including resolution of megaesophagus, and progressive reduction in acetylcholine receptor antibody concentration was noted. This report highlights the importance of considering myasthenia gravis in juvenile dogs and emphasizes the utility of measuring acetylcholine receptor antibodies in suspected cases regardless of age. The safe and possibly efficacious use of leflunomide in a dog with this disease is also demonstrated. Further studies are needed to characterize the juvenile presentation of this disease and to evaluate the efficacy of treatment with leflunomide as the sole immunosuppressant medication in a larger canine population.", "authors": ["Mondino Alejandra", "Fefer Gilad", "Tauro Anna", "Olby Natasha J", "Lewis Melissa J", "Mariani Christopher L"], "journal": "Case reports in veterinary medicine", "entry_date": "2025/08/22 04:47", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40843319/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Clinical Sciences, North Carolina State University, Raleigh, North Carolina, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40842502", "title": "Partial Response to Nivolumab and Ipilimumab in a Patient With Malignant Pleural Mesothelioma and Pre-Existing Myasthenia Gravis Without Severe Flares or Immune-Related Adverse Events: A Case Report.", "abstract": "Detailed clinical data on the combination immune checkpoint inhibitor (ICI) therapy in patients with myasthenia gravis (MG) remain limited. We report a case of malignant pleural mesothelioma with previously undiagnosed ocular MG. Owing to hepatic dysfunction, reduced doses of nivolumab and ipilimumab were administered before confirmation of anti-acetylcholine receptor (AChR) antibody positivity. MG was diagnosed based on subtle ocular symptoms and serological tests. Prophylactic intravenous immunoglobulin and an acetylcholinesterase inhibitor were administered; combination therapy was discontinued owing to the risk of MG flare, but a partial tumour response was achieved. With disease progression, nivolumab monotherapy was reintroduced, and early steroid pulse therapy was administered owing to elevated creatine kinase, again inducing a partial response. Serological screening for anti-AChR antibodies may help prevent severe MG flares and immune-related adverse events. With caution, dose-reduced and limited-exposure ICI combination therapy may be feasible in selected patients with MG under appropriate prophylactic management.", "authors": ["Higa Mariko", "Kuda Tomoya", "Ohya Yuichiro", "Kawasaki Hidenori"], "journal": "Respirology case reports", "entry_date": "2025/08/22 04:34", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40842502/", "pub_types": ["Journal Article"], "affiliations": ["Division of Pulmonary Medicine NHO Okinawa Hospital Ginowan Okinawa Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40842122", "title": "A Cross-Sectional Study of Quality of Life and Body Image in Myasthenia Gravis Patients: A Novel Approach Using the Individualized Neuromuscular Quality of Life Questionnaire.", "abstract": "INTRODUCTION/AIMS: Many generic and disease-specific quality of life (QoL) measures have been used to understand the perspectives of patients with myasthenia gravis (MG). However, there is limited data regarding the use of the Individualized Neuromuscular Quality of Life Questionnaire (INQoL) and the impact of body image in patients with MG.\nMETHODS: This was a cross-sectional cohort of 258 patients with MG who completed several QoL measures, including the INQoL, 36-Item Short Form Survey (SF-36) and 15-Item Myasthenia Gravis Quality of Life Scale (MG-QoL15). We compared scores of different QoL measures with each other and also compared SF-36 scores to the general population. Linear regression models were built to investigate factors associated with QoL and body image in MG patients.\nRESULTS: MG patients had lower SF-36 scores compared to the general population. Of the different QoL measures, the INQoL correlated the strongest with the MG-QoL15 (r = 0.80, p < 0.05). Worse QoL (measured by the INQoL) was significantly correlated with increased disease severity (p = 0.0054) and fatigue (p = 0.0019), younger age (p = 0.0471), and retirement (p = 0.0450). Worse INQoL body image scores were significantly associated with increased fatigue (p = 0.0189) and ptosis severity (p = 0.0298).\nDISCUSSION: The INQoL showed that body image is negatively affected in people with MG, suggesting it poses a burden and may be worth considering when measuring QoL. Further studies are needed to assess other factors associated with reduced body image, besides ptosis and fatigue, in people living with MG.", "authors": ["Chou Michael", "Mendoza Meg", "Katzberg Hans", "Bril Vera", "Barnett-Tapia Carolina"], "journal": "Muscle & nerve", "entry_date": "2025/08/22 01:23", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40842122/", "pub_types": ["Journal Article"], "affiliations": ["Toronto General Hospital, Ellen and Martin Prosserman Centre for Neuromuscular Disease, Toronto, Canada."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40842108", "title": "Factors Influencing Quality of Life in Myasthenia Gravis Patients: Results From a Cross-Sectional Study in South of Iran.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction characterized by fatigue and muscle weakness, often leading to significant impairments in quality of life (QOL). This single-center cross-sectional study investigated factors influencing QOL among MG patients.\nMETHODS: Fifty-two participants diagnosed with MG were assessed using the MG Foundation of America (MGFA) classification and the MG composite (MGC) scale for disease severity. Patients completed validated questionnaires, including the Fatigue Severity Scale (FSS), Beck Depression Inventory (BDI), MG Activities of Daily Living (MG-ADL), and the MG Quality of Life 15-item scale (MG-QOL). Family stress levels were self-reported and categorized as \"Rarely/Never,\" \"Sometimes,\" \"Often,\" or \"Always.\"\nRESULTS: The analysis revealed no significant differences in QOL scores based on sex, disease type, presenting symptoms, thymectomy status, or BMI. Employed or freelance patients exhibited significantly lower QOL and higher fatigue compared to retired or housewife groups. Higher family stress correlated with increased fatigue, worse MGC scores, and poorer QOL. Regression analysis identified the MG-ADL and FSS scores as the strongest predictors of QOL.\nCONCLUSION: QOL in MG is influenced by complex interactions among functional, social, and occupational factors. These findings emphasize the need for tailored interventions to address fatigue and support occupational and familial well-being in MG patients. Further research with larger cohorts is warranted to refine these insights and guide clinical strategies.", "authors": ["Khodakarami Fatemeh", "Mallahzadeh Arashk", "Fararouei Mohammad", "Jaberi Abbas Rahimi", "Owjfard Maryam"], "journal": "Brain and behavior", "entry_date": "2025/08/22 01:12", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40842108/", "pub_types": ["Journal Article"], "affiliations": ["Clinical Neurology Research Center, Shiraz University of Medical Sciences, Shiraz, Iran."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40839911", "title": "Neurological adverse events of ICI therapy: A ten-year comprehensive management from a multidisciplinary team.", "abstract": "BACKGROUND: The unique mechanism of action of immune checkpoint inhibitors (ICI) can lead to auto-inflammatory events, potentially involving any organ. Among those, different rare immune related adverse events (irAEs) have also been identified, with Neurological irAEs (NirAEs) accounting for 1-5 %. In this scenario, we here report the 10-year experience of the multidisciplinary team at the University Hospital of Siena, Italy, in the diagnosis and clinical management of NirAEs.\nMETHODS: A case series of ICI-treated patients with clinical suspect of Nir-AEs were evaluated by an experienced neurologist team. Neurological specific antibodies were tested in central/peripheral toxicities. In case of suspicious of CNS NirAEs, lumbar puncture was utilized to exclude infectious/paraneoplastic causes. In patients with signs and symptoms suggestive for myositis, a diagnostic muscular biopsy was performed.\nRESULTS: From January 2012 to December 2022, 1328 patients with solid tumors were treated with ICI, and 24 (1,8 %) were diagnosed with NirAEs: peripheral, central, or both in 20, 1, and 3 cases respectively. The most representative neurotoxicity was muscular/neuromuscular junction involvement. Histological examination of muscle biopsies depicted two main pathological patterns: highly inflammatory or necrotizing. NirAEs were Grade (G) 1-2 (11), G3-4 (10), G5 (3) and were treated with steroids, immunoglobulins and/or plasma exchange. Treatment led to complete or partial recovery of NirAEs in 11 (46 %) and 10 patients (42 %), respectively. In 3 cases NirAEs progressively worsened and patients died thereafter.\nCONCLUSIONS: Our long-term experience indicates that a multidisciplinary approach avoids worsening of NirAEs leading to clinical recovery in the large majority of ICI-treated patients.", "authors": ["Di Giacomo Anna Maria", "Bartalini Sabina", "D'Alonzo Vincenzo", "Cerase Alfonso", "Cutarella Serena", "Rossi Giulia", "Simonetti Elena", "Valente Monica", "Ravara Matteo", "Colucci Maura", "Gibilisco Giulia", "Insana Laura", "Bocci Silvia", "Croce Valentina", "Sani Tommaso", "Carbonari Eleonora", "Covre Alessia", "Giannini Fabio", "Volpi Nila", "Ginanneschi Federica", "Maio Michele"], "journal": "European journal of cancer (Oxford, England : 1990)", "entry_date": "2025/08/21 17:59", "pub_date": "2025-10-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40839911/", "pub_types": ["Journal Article"], "affiliations": ["University of Siena, Siena, Italy; Center for Immuno-Oncology, Medical Oncology and Immunotherapy, Department of, Oncology, University Hospital of Siena, Siena, Italy; Italian Network for Tumor Biotherapy (NIBIT) Foundation Onlus, Italy. Electronic address: annamaria.digiacomo@unisi.it."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 7.9, "journal_quartile": "1区"}, {"pmid": "40837976", "title": "Therapeutic plasma exchange using apheresis: Clinical experience and outcomes in neurological and non-neurological cases at a tertiary care center in western India.", "abstract": "INTRODUCTION: Therapeutic plasma exchange (TPE) is a procedure used to treat various neurological and non-neurological disorders by removing and replacing a patient's plasma to eliminate disease-causing substances. Here, we present our experience using TPE to treat various diseases with an apheresis machine.\nAIM: To evaluate the safety and efficacy of TPE as a treatment modality in various patients with neurological and non-neurological diseases admitted in tertiary care center in western India.\nMETHODOLOGY: A retrospective analysis of 152 TPE procedures was conducted over 3 years (April 2021-April 2024) in a Western Indian tertiary care hospital. The study involved 39 patients aged 7-72 years. Clinical improvement was assessed through relevant investigations before, during, and after TPE procedures.\nRESULTS: Thirty-nine patients were studied, with Guillain-Barre Syndrome (GBS) being the most common indication for TPE, followed by acute liver failure (ALF) and myasthenia gravis (MG). Clinical improvement was seen in 76.19% (16/21) of GBS patients, 12.5 (1/8) of ALF, and 100% (5/5) of MG patients. 13/18 (72.22%) patients in the neurological category showed complete recovery even after replacement of 0.5-0.9 plasma volume (n = 18). The adverse reaction rate for TPE was 5.92% (9 events in 152 cycles), most common being allergic reactions and paresthesia.\nCONCLUSION: TPE is safe and efficient treatment modality for the treatment of neurological and non-neurological diseases. Our experience highlights TPE's safety and efficacy. One group in the neurological category showed improvement even with low-volume exchanges (0.5-0.9 PV). Further research is required to enhance the understanding and use of TPE in patient care.", "authors": ["Patil Shashikant Baraku", "Gill Satyajit Singh", "Borse Sandeep", "Bhandari Nilesh", "Kurade-Aher Sulaxmi"], "journal": "Asian journal of transfusion science", "entry_date": "2025/08/21 05:23", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40837976/", "pub_types": ["Journal Article"], "affiliations": ["Department of Transfusion Medicine, Jehangir Hospital, Pune, Maharashtra, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "40837899", "title": "Median Sternotomy for Mediastinal Mass Removal: Thymoma of Unknown Cause.", "abstract": "Thymoma is a rare mediastinal malignancy. Although it may often be associated with paraneoplastic syndromes such as hypogammaglobulinemia, pure red cell aplasia, or myasthenia gravis (MG), some thymomas may also be idiopathic in origin. Although thymoma is the most common mass found in the anterior mediastinum, its rarity still proves difficult in swift diagnosis and subsequent treatment. This case presents a patient with an unknown anterior mediastinal mass incidentally found on imaging, with the final diagnosis of thymoma made from a pathologic investigation that was performed post-sternotomy and resection.", "authors": ["Murphy Kaitlin N", "Hoodfar Arian", "Katkic Mitchell", "Purut Cemil"], "journal": "Cureus", "entry_date": "2025/08/21 05:21", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40837899/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Edward Via College of Osteopathic Medicine (VCOM), Roanoke, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40832342", "title": "B Cell Tolerance and BCR Signaling Dysregulation in NF155-Mediated Autoimmune Nodopathies.", "abstract": "OBJECTIVE: Autoimmune nodopathies (AINs) are a group of rare, acquired autoimmune neuropathies with distinct clinical features and the presence of circulating autoantibodies - often of the immunoglobulin G4 (IgG4) subclass - targeting proteins at the node of Ranvier. Defects in B cell tolerance checkpoints have been implicated in several autoimmune diseases. Prior work identified defective B cell tolerance-reflected by a high frequency of self-reactive naïve B cells-in patients with MuSK-positive myasthenia gravis (MG), mediated by IgG4 autoantibodies. Here, we investigated whether tolerance defects exist in neurofascin-155-mediated AIN (NF155-AIN), similar to MuSK+ MG. Additionally, we analyzed B and T cell transcriptomics and interactions at the single-cell level to explore the underlying pathomechanism.\nMETHODS: Using a well-established assay, we assessed B cell tolerance fidelity by generating recombinant antibodies from new emigrant (NE) and mature naïve (MN) B cell populations- directly downstream of key tolerance checkpoints-from three NF155-AIN patients, and testing these antibodies for polyreactivity and autoreactivity, thereby determining the frequency of polyreactive and autoreactive B cells. The transcriptome of peripheral blood mononuclear cells (PBMC) was studied, with a special focus on naïve B cells and CD4+ T cells at the single-cell level, along with characterization of cell-cell interactions.\nRESULTS: NF155-AIN patients have an elevated frequency of polyreactive B cells in the NE (37.4% compared to 9.7% in healthy controls (HCs), p = 0.03) and MN (31.5% compared to 10.5% in HCs, p = 0.03) compartments with increased B cell clones expressing autoreactive antibodies, consistent with a breach in early tolerance checkpoints. We observed abnormal B cell receptor (BCR) signaling characterized by low CD79B, CSK, BLNK, and BTK expression, which may contribute to a breach in B cell tolerance. We also observed evidence of impaired follicular helper T cells (Tfh) and regulatory T cells (Treg), which may limit the normal development and suppression of autoreactive B cells. Moreover, comparative gene expression analysis of B cells and CD4+ T cells from three patients with chronic inflammatory demyelinating polyneuropathy (CIDP) -a related autoimmune neuropathy- confirmed that these differences are largely specific to NF155-AIN, supporting a distinct pathophysiology in this subset.\nCONCLUSION: These findings demonstrated a breach in early B cell tolerance checkpoints, defective BCR signaling, and disrupted T cell-B cell interactions in NF155-AIN, all of which may contribute to the development of pathogenic autoreactivity. These immunologic abnormalities appear distinct from those seen in CIDP, supporting NF155-AIN as a unique immunopathologic entity.", "authors": ["Roy Bhaskar", "Obaid Abeer H", "Wang Zhenjian", "Kovacs Kristof G", "Ohashi Sarah", "Kalayci F Naz Cemre", "Joo Daniel", "Masi Gianvito", "Coppola Carmina", "Das Sameeran", "Hernandez Amanda L", "Martin-Aguilar Lorena", "Lleixà Cinta", "Nowak Richard J", "Querol Luis", "O'Connor Kevin C"], "journal": "bioRxiv : the preprint server for biology", "entry_date": "2025/08/20 05:11", "pub_date": "2025-08-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40832342/", "pub_types": ["Journal Article", "Preprint"], "affiliations": [], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40831557", "title": "Inflammatory imbalance and activation deficits in T cells of myasthenia gravis patients revealed by proteomic profiling.", "abstract": "Myasthenia gravis (MG) is a heterogeneous autoimmune disorder characterized by neuromuscular transmission failure and skeletal muscle fatigability, with a pathophysiology involving both cellular and humoral immune components. Despite growing interest in the immunological etiology of MG, few functional studies have addressed the role of T cells, and most existing work has focused on quantifying immune cell subsets using flow cytometry. In this study, a comparative in vitro analysis of resting and activated CD4+ and CD8+ T cells from MG patients and healthy controls (HC) was performed using the multiplex Proximity Extension Assay (PEA) proteomics to assess the secretion of inflammatory proteins, including cytokines and chemokines, and to define the inflammatory status of T cells in MG. Data analysis was performed using the Boruta algorithm to detect both linear and non-linear patterns, followed by multiple testing corrections, and correlation analyses. The results revealed distinct alterations in the secretion profiles of several inflammatory proteins in MG compared to HC across both T cell subsets, regardless of activation state. Notably, resting CD4+ T cells from MG patients secreted higher levels of VEGFA, TNFRSF9, TWEAK, CCL20, HGF, CCL19, TRAIL, IL18, and TNF-β whereas resting CD8+ T cells secreted higher levels of IL-12B, TRAIL, CCL23, CD244, CXCL11, CCL20, VEGFA, PD-L1, and OSM relative to HC. In contrast, activated CD4+ and CD8+ cells from MG patients exhibited a blunted secretion profile compared to HC, suggesting functional exhaustion. Furthermore, MG-ADL scores correlated with the secretion levels of 14 proteins from resting CD4+ cells, including seven cytokines, five chemokines, and two matrix metalloproteins. Some of the CD4+ T cell secreted proteins also correlated with their corresponding serum or plasma levels in vivo. Overall, these findings indicate that T cells in MG exhibit a skewed inflammatory profile characterized by heightened basal activation and impaired inducibility, suggestive of an exhausted phenotype. The interplay between these altered T cell functions and aberrant B cell responses in MG warrants further investigation and may provide novel insights into disease immunopathophysiology as well as opportunities for targeted immunomodulatory therapies.", "authors": ["Bhandage Amol K", "Punga Anna Rostedt"], "journal": "Frontiers in immunology", "entry_date": "2025/08/20 04:56", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40831557/", "pub_types": ["Journal Article"], "affiliations": ["Clinical Neurophysiology, Department of Medical Sciences, Uppsala University, Uppsala, Sweden."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40830529", "title": "The efficacy and safety of efgartigimod for refractory myasthenia gravis: a systematic review and meta-analysis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a chronic autoimmune disorder affecting the neuromuscular junction, where autoreactive immunoglobulin G (IgG) plays a key role in disease pathogenesis. The novel biologic Efgartigimod is a neonatal Fc receptor (FcRn) antagonist, promotes the lysosomal degradation of IgG, and may offer a targeted approach for managing MG. Despite the growing interest in efgartigimod, there remains a lack of comprehensive evaluation of its efficacy and safety in different MG subtypes.\nMETHODS: Comprehensive retrieval and screening were conducted on Pubmed, Embase, Web of Science, and Cochrane library to search studies on efgartigimod treatment. The data on response rates and adverse events were extracted, and the pooled effect size (ES) with the 95% confidence interval (CI) was calculated by fixed or random effect models. Sensitivity analysis and subgroup analysis were employed to test the heterogeneity. Funnel plots and trim-and-fill methods were used to test for publication bias.\nRESULTS: Data from 10 studies involving 305 patients were analyzed. The overall treatment response rate was 78% (95% CI: 67%-87%, I2 = 73.4%). Subgroup analysis revealed pooled response rates of 79.2% (95% CI: 68.5%-88.4%, I2 = 25.08%) in acetylcholine receptor antibody-positive MG (AChR+MG) patients and 76.2% (95% CI: 56.8%-91.5%, I2 = 85.95%) in group that did not differentiate auto-antibody types. The pooled incidence of adverse events was 38% (95% CI: 17%-51%, I2 = 92.59%), with infections (7%, 95% CI: 2%-14%, I2 = 62.5%), headache (7%, 95% CI: 1%-18%, I2 = 82.69%) and other (16%, 95% CI: 7%-28%, I2 = 71.81%). Among them, grade 3-4 adverse events are 1% (95% CI: 0%-2%, I2 = 0%).\nCONCLUSION: Our study demonstrates that efgartigimod is highly effective and well-tolerated in patients with refractory MG. These findings suggest that efgartigimod is a promising drug for the treatment of MG.", "authors": ["Cheng Jia-Jun", "Wang Fu-Qiang", "Dai Zhang-Yi", "Wang Xin-Wei", "Wang Yun"], "journal": "European journal of medical research", "entry_date": "2025/08/19 23:40", "pub_date": "2025-08-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40830529/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Department of Thoracic Surgery, West China Hospital, Sichuan University, No. 37 Guoxue Alley, Chengdu, 610041, Sichuan, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 3.4, "journal_quartile": "3区"}, {"pmid": "40828747", "title": "Neuroimmunological Crossroads: A Rare Co-occurrence of Myasthenia Gravis and IgLON-related Amyotrophic Lateral Sclerosis.", "abstract": "", "authors": ["Vijayaraghavan Asish", "Nair Sruthi S", "Poyuran Rajalakshmi", "Sukumaran Sajith", "Sundaram Soumya"], "journal": "Neurology India", "entry_date": "2025/08/19 13:23", "pub_date": "2026-01-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40828747/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Sree Chitra Tirunal Institute for Medical Sciences and Technology, Trivandrum, Kerala, India."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40827839", "title": "Neurological manifestations of chronic graft versus host disease.", "abstract": "INTRODUCTION: Allogeneic haemopoietic stem cell transplant (allo-HSCT) is an established therapy for many malignant and non-malignant conditions, with an increasing number of uses and indications in recent decades. Complications including graft versus host disease (GvHD) carry significant morbidity and mortality. Chronic GvHD can affect multiple organs, including skin, gastrointestinal, respiratory and eyes. Neurological involvement is less common and can be a diagnostic and therapeutic challenge for patients and clinicians.\nMETHODS: A retrospective analysis was conducted of patients who underwent allo-HSCT for a haematological malignancy with an established diagnosis of chronic GvHD at a major Australian institution.\nRESULTS: Out of 455 allo-HSCT cases, 228 (50%) had chronic GvHD, seven (3.1%) of which were identified to have neurological complications. Four cases, each consisting of myasthenia gravis, Bickerstaff brainstem encephalitis, acute disseminated encephalomyelitis and inflammatory meningitis, were selected to illustrate peripheral and central neurological manifestations of chronic GvHD. Presentations, management and outcomes were discussed and contrasted to similar cases available in the literature.\nCONCLUSION: Chronic GvHD infrequently presents with neurological manifestations. Understanding the similarities and differences of these and their idiopathic counterparts allows an enhanced understanding of their pathophysiology within the context of GvHD, as well as some significant differences to conventional management of these neurological conditions.", "authors": ["Koren Tal", "Kwok Alice", "Stevenson William", "Ahmad Kate", "Nogajski Joseph", "Parratt John", "Kerridge Ian", "Ng Karl"], "journal": "Internal medicine journal", "entry_date": "2025/08/19 08:34", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40827839/", "pub_types": ["Journal Article"], "affiliations": ["Deparment of Neurology, Royal North Shore Hospital, Sydney, New South Wales, Australia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.5, "journal_quartile": "4区"}, {"pmid": "40825554", "title": "[Myasthenia Gravis Treated with Zilucoplan Prior to Extended Transsternal Thymectomy for the Prevention of Myasthenic Crisis: A Case Report].", "abstract": "A 50year-old female was diagnosed with myasthenia gravis (MG) following aspiration pneumonia. Despite treatment with prednisolone (5mg/day) and intravenous immunoglobulin (IVIg), the bulbar palsy persisted. Additionally, chest CT revealed findings suggestive of invasive thymoma or thymic carcinoma, leading to a planned thymectomy with median sternotomy. This case presents a high-risk of myasthenic crisis due to thymoma-associated MG, persistent bulbar palsy, and the need for highly invasive surgery. Therefore, enhanced immunotherapy was required to prevent this crisis, and zilucoplan was chosen because of its rapid onset of action and compatibility with IVIg. Following the initiation of zilucoplan, there was prompt improvement in the symptoms of MG. Effective preoperative control of MG led to a good clinical course, with no significant postoperative myasthenic crisis or exacerbation of symptoms. This is the first report on the use of zilucoplan for the prevention of perioperative myasthenic crisis. (Received April 14, 2025; Accepted June 3, 2025, Published August 1, 2025).", "authors": ["Yamanaka Nanami", "Honda Masaya", "Kanda So", "Tanaka Toshiki", "Shimizu Fumitaka", "Koga Michiaki", "Nakamori Masayuki"], "journal": "Brain and nerve = Shinkei kenkyu no shinpo", "entry_date": "2025/08/18 20:03", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40825554/", "pub_types": ["Journal Article", "Case Reports", "English Abstract"], "affiliations": ["Department of Neurology and Clinical Neuroscience, Yamaguchi University Graduate School of Medicine."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40824132", "title": "Histopathological assessment of thymoma based on the World Health Organization 2021 classification with emphasis on transcapsular invasion: experience from a tertiary care center.", "abstract": "Histological classification and staging are crucial in the management and prognostication of thymoma. With different staging systems used, the significance of transcapsular invasion is debatable, especially in light of pathological tumor-node-metastasis (pTNM) staging (American Joint Committee on Cancer, 8th edition). The objective of this study was to analyze the histological subtypes, transcapsular invasion, and clinical outcome of thymoma with regard to the World Health Organization (WHO) 2021 classification. This retrospective study included all thymectomy specimens diagnosed as thymoma over a period of 10 years, from 2013 to 2023. Clinical details and histopathology slides were reviewed and histologically subtyped as per the WHO 2021 classification. Transcapsular invasion was assessed, and pTNM and modified Masoka staging were done. Descriptive statistics were used to summarize data. A total of 45 thymoma cases were identified; two with extensive infarction were excluded. The mean age was 46.5 years (range 25-68 years); in this study, there were 28 males and 15 females with a male-to-female ratio of 1.8:1. Myasthenia gravis was the presenting feature in 31 (72.9%) cases. B2 and B3 subtypes constituted half of the cases (22/43), with mixed patterns in 4 (9.3%). A total of 9 cases showed macroscopic invasion, 80% being the B3 subtype, and out of the 23 cases that showed transcapsular invasion, the three most common subtypes are listed here, with B3 being the most common, followed by AB and B2. Masaoka staging showed 11 (25.5%) stage I, 22 stage IIa (51.1), 6 stage IIb (13.9%), 1 stage III (2.3%), 2 stage IVa (4.6%), and 1 stage IVb (2.3%). Follow-up available in 38 out of 43 cases (range 4-127 months) showed recurrence in one case of the B3 subtype, stage IVb. None of the stage I and stage II (as per Masoka staging) patients had recurrence. The Masaoka stage is a widely used staging system where transcapsular invasion is an important parameter for upgrading stage I to stage II. However, in the present study, Masaoka stage I and II patients had no recurrence, questioning the significance of capsular invasion for staging. Accurate histological subtyping in thymoma is challenging but can be achieved by adherence to the morphological criteria of the WHO 2021 classification.", "authors": ["Saloni Saloni", "Malipatel Renuka", "Balasundaram Sreekar"], "journal": "Monaldi archives for chest disease = Archivio Monaldi per le malattie del torace", "entry_date": "2025/08/18 09:42", "pub_date": "2025-08-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40824132/", "pub_types": ["Journal Article"], "affiliations": ["Department of Pathology, Guru Gobind Singh Medical College, Faridkot, Punjab."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40823470", "title": "Immune Checkpoint Inhibitor-Induced Myositis Myocarditis and Myasthenia Gravis (MMM) Overlap Syndrome in a Rural District General Hospital: An Institutional Case Series Involving Four Patients.", "abstract": "Immune checkpoint inhibitors (ICIs) are commonly used for the treatment of some advanced cancers. Although effective, they can cause side effects. This case series describes four patients treated for ICI-induced myositis, myocarditis and myasthenia gravis (MMM) overlap syndrome at a rural general hospital in the United Kingdom between 2023 and 2025. To the best of our knowledge, this is the first open-access case series describing its management specifically in a rural, low-resource setting. Patients were exclusively male with a mean age of 68.9 years and had received either dual nivolumab/ipilimumab or pembrolizumab monotherapy for metastatic melanomas, renal cell carcinoma or synchronous oesophageal and lung cancer. Symptoms included fatigue, proximal muscle weakness, dysphagia, diplopia, and dyspnea. High-dose intravenous methylprednisolone was the mainstay of treatment, with additional immunomodulators like mycophenolate mofetil, tocilizumab, tacrolimus and intravenous immunoglobulins added based on clinical progression and specialist input. Two patients recovered with treatment and remained progression free following ICI discontinuation, while two patients died due to respiratory failure, likely related to delayed initiation of myasthenia gravis-directed therapy. Prominent bulbar symptoms at presentation and high myasthenia gravis composite scores appear to correlate with poor outcomes. Early access to diagnostics such as autoantibodies for MG, tissue biopsy and electrodiagnostics was often limited by logistical barriers. However, biomarkers like creatine kinase, troponins and imaging modalities were consistently available. This series highlights the challenges of managing MMM syndrome in non-specialist resource-limited settings and the potential dangers of delayed immunosuppression. A high index of suspicion, early multidisciplinary involvement, and rapid initiation of therapies are critical to improving outcomes. Furthermore, this case series supports the need for simplified, context-appropriate guidelines that prioritise clinically impactful investigations and also highlights the emerging potential of the neutrophil-to-lymphocyte ratio as a practical prognostic tool. As ICI indications expand, awareness of MMM overlap syndrome among frontline clinicians is essential to reduce treatment delays and prevent avoidable mortality.", "authors": ["Ismail Umar", "Both Elisabeta E", "Brown Helen"], "journal": "Cureus", "entry_date": "2025/08/18 07:15", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40823470/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Withybush General Hospital, Hywel Dda University Health Board, Haverfordwest, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40821799", "title": "Case Report: Eculizumab in highly active myasthenia gravis complicated by severe infections.", "abstract": "Highly active myasthenia gravis refers to a subset of refractory patients who exhibit recurrent exacerbations and crises. Eculizumab, a complement C5 inhibitor, has shown its efficacy and safety for patients with anti-acetylcholine receptor antibody-positive(AchR +)refractory generalized myasthenia gravis(gMG) in the REGAIN trial. However, the efficacy and safety of eculizumab in treating MG patients with severe infections have not yet been supported by clinical evidence. This is a case series reporting four patients with highly active myasthenia gravis complicated by severe infections. Changes in Myasthenia Gravis-Activities of Daily Living (MG-ADL) and Quantitative Myasthenia Gravis (QMG) scores were recorded before and after 12 injections of eculizumab to assess efficacy. Pathogen characteristics of infections were summarized using bacterial culture and next-generation sequencing (NGS) results, presented as a heatmap to illustrate pathogen species and abundance. Inflammatory markers, including Procalcitonin (PCT), C-Reactive Protein (CRP), neutrophil count, and total lymphocyte count, were monitored to evaluate the safety. Treatment regimens were retrospectively analyzed to further assess clinical outcomes and safety. The baseline ADL data for the four patients was 22 ± 2.31 (Mean ± SD), and the baseline QMG data was 30.5 ± 8.23. After 12 injections of eculizumab treatment, the scores decreased to ADL 4.75 ± 3.3 and QMG 14 ± 3.37. During the treatment, no apparent worsening of infections related to Eculizumab was noted. Three patients successfully had their tracheostomy tubes removed, and none of the four patients experienced further myasthenic crises. Eculizumab demonstrated clinical improvement in this series, and the treatment was well-tolerated. This case series addresses the need for data on complement inhibitors in highly active myasthenia gravis patients with severe infections, provides clinical reference support for the expanded application of eculizumab.", "authors": ["Deng Yufei", "Luo Haocheng", "Zhang Chaoyue", "Yang Li", "Wang Shuangshuang", "Zhang Xuxiang", "Yan Xianni", "Yang Xiaojun", "Jiang Qilong"], "journal": "Frontiers in immunology", "entry_date": "2025/08/18 06:52", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40821799/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neuromuscular Diseases, The First Affiliated Hospital of Guangzhou University of Chinese Medicine, Guangzhou, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40821191", "title": "Coincidental Coexistence of Human T-lymphotropic Virus Type 1 (HTLV-1)-Associated Myelopathy/Tropical Spastic Paraparesis and Myasthenia Gravis in a Patient With Chronic HTLV-1 Infection: A Case Report.", "abstract": "Human T-lymphotropic virus type 1 (HTLV-1) infection profoundly alters central immune regulation via molecular mechanisms involving the viral proteins transactivator X and HTLV-1 basic leucine zipper factor, which promote the proliferation of autoreactive T lymphocytes and the dysfunction of regulatory T cells, resulting in persistent inflammation of the central nervous system. These alterations not only explain the occurrence of HTLV-1-associated myelopathy/tropical spastic paraparesis (HAM/TSP) but have also been associated with the development of autoimmune diseases such as myasthenia gravis (MG). While the connection between chronic HTLV-1 infection and MG is still anecdotal, a small number of case studies and limited molecular research suggest a potential link. Recent investigations have identified HTLV-1 tax and pol gene sequences in thymic tissue from MG patients, supporting the idea that the virus can persistently infect the thymus and interfere with the negative selection of T lymphocytes. Here, we present the case of a patient with HAM/TSP for over 12 years who subsequently experienced a myasthenic crisis, confirmed by the detection of anti-acetylcholine receptor autoantibodies. The patient responded favorably to treatment with acetylcholinesterase inhibitors. The absence of thymoma, together with a history of chronic retroviral infection, reinforced the potential role of HTLV-1 as a trigger for autoimmunity in the absence of structural abnormalities. This case illustrates the clinical and molecular convergence between retroviral infection and immune dysfunction, providing further support for a model of virally induced autoimmunity.", "authors": ["Garma-Solis Ignacio J", "Zapata-Arceo Fanny S", "Ayuso-Diaz Victor M", "Moreno-Enriquez Angelica"], "journal": "Cureus", "entry_date": "2025/08/18 06:46", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40821191/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, Institute for Social Security and Services for State Workers (ISSSTE) - Regional Hospital \"Elvia Carrillo Puerto\", Mérida, MEX."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40816827", "title": "Myocarditis, Myositis, and Myasthenia Gravis: The Complexities of Treating Steroid-Refractory Triple M Syndrome.", "abstract": "BACKGROUND: Triple M syndrome is the combination of myocarditis, myositis, and myasthenia gravis secondary to immune checkpoint inhibitor (ICI) treatment. Traditionally managed with high-dose steroids, ICI myocarditis may benefit from early initiation of nonsteroidal immunosuppression.\nCASE SUMMARY: A man with hepatocellular carcinoma presented with double vision and an elevated high-sensitivity troponin after receiving his first dose of tremelimumab (CTLA-4 inhibitor) and durvalumab (PD-L1 inhibitor). He was diagnosed with steroid-refractory ICI myocarditis and treated with abatacept and ruxolitinib. Early recognition of triple M syndrome and initiation of nonsteroidal immunosuppression are described.\nDISCUSSION: Management of ICI myocarditis is evolving. Nonsteroidal immunosuppression may become an essential component of management as ICI use, and therefore occurrence of triple M syndrome, increases.\nTAKE-HOME MESSAGES: If there is recent initiation of ICI therapy, elevated troponin, and concomitant ICI toxicities, providers should suspect ICI myocarditis despite negative cardiac magnetic resonance imaging. Nonsteroidal immunosuppression with CTLA-4 agonists may be effective in patients treated with CTLA-4 inhibitors.", "authors": ["Halloran Sean", "Patel Ruchi", "Tilkens Blair", "Alban Juan", "Zubenko Alexandra", "Mohindra Nisha", "Lomasney Jon", "Akhter Nausheen"], "journal": "JACC. Case reports", "entry_date": "2025/08/15 20:57", "pub_date": "2025-08-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40816827/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Medicine, McGaw Medical Center of Northwestern University, Chicago, Illinois, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40813187", "title": "Targeting the neonatal Fc receptor (FcRn) in hematologic conditions with a focus on warm autoimmune hemolytic anemia.", "abstract": "Warm autoimmune hemolytic anemia (wAIHA) is the most prevalent form of autoimmune hemolytic anemia, where in most patients extravascular hemolysis is driven by immunoglobulin G (IgG) autoantibodies, with or without complement activation. While standard-of-care treatment with corticosteroids provides a high initial response rate, relapses are frequent, and most patients require additional immunosuppressive therapies. A high unmet medical need remains for patients with refractory or chronic relapsing wAIHA. Neonatal Fc receptor (FcRn) blockers are novel biologic therapies designed to provide a rapid, sustained decrease in circulating concentrations of IgG antibodies, including autoantibodies, and have been investigated in hematologic conditions like immune thrombocytopenia and hemolytic anemia of the fetus and newborn and other autoimmune conditions, such as generalized myasthenia gravis. FcRn blockade is currently under evaluation in patients with wAIHA to determine its potential as a safe, effective treatment option.", "authors": ["Fattizzo Bruno", "Ling Leona E", "Barcellini Wilma"], "journal": "Blood reviews", "entry_date": "2025/08/14 21:58", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40813187/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Fondazione IRCCS Ca' Granda Ospedale Maggiore Policlinico, Milan, Italy; Department of Oncology and Hematology-Oncology, University of Milan, Milan, Italy. Electronic address: bruno.fattizzo@unimi.it."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 23.1, "journal_quartile": "1区"}, {"pmid": "40812271", "title": "First analysis of the Myasthenia Gravis SPOTLIGHT Registry: outcomes with eculizumab and ravulizumab.", "abstract": "BACKGROUND: Complement component 5 inhibitors are indicated for the treatment of anti-acetylcholine receptor antibody-positive generalized myasthenia gravis (gMG). Clinical trials have demonstrated improved functional ability, muscle strength, and quality of life (QOL) in patients treated with eculizumab or ravulizumab. Evidence for their effectiveness and safety in clinical practice is reported here.\nMETHODS: Data from the global MG SPOTLIGHT Registry were collected from patients with gMG currently or previously treated with eculizumab or ravulizumab in routine clinical practice. Effectiveness was evaluated among patients with ≥3 outcome measurements using MG Activities of Daily Living (MG-ADL) and MG-QOL 15-revised (MG-QOL15r) patient-reported outcomes and/or Myasthenia Gravis Foundation of America Clinical Classification (MGFA class) physician assessments. Safety data were also assessed.\nRESULTS: 189 patients were treated with eculizumab. Mean (95% CI) MG-ADL scores (n=110) decreased by 4.2 (-5.0, -3.4) points and MG-QOL15r scores (n=40) decreased by 7.5 (-9.9, -‍5.0) points from before eculizumab initiation to first assessment during/after treatment (median eculizumab treatment duration: 18.0 months). 45/103 (43.7%) patients were MGFA class 0-II before eculizumab versus 89/103 (86.4%) at first assessment. After transitioning to ravulizumab, improvements in MG-ADL scores (n=37), MG-QOL15r scores (n=14), and MGFA class (n=34) were maintained (median ravulizumab treatment duration: 8.7-11.4 months). Few treatment-related serious adverse events (eculizumab: Aspergillus infection, nervous system disorder [n=1 each]; ravulizumab: anaphylactic reaction [n=1]) and no meningococcal infections were reported with eculizumab or ravulizumab treatment.\nCONCLUSIONS: In routine clinical practice, eculizumab was well tolerated and effective for patients with gMG. Treatment benefits were maintained after transition to ravulizumab.", "authors": ["Howard James F", "Dodig Dubravka", "Zeinali Lida", "Macwan Samir P", "Yegin Ashley", "Pulley Michael T", "Rodrigues Ema", "Narayanaswami Pushpa"], "journal": "Journal of the neurological sciences", "entry_date": "2025/08/14 18:27", "pub_date": "2025-09-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40812271/", "pub_types": ["Journal Article"], "affiliations": ["The University of North Carolina at Chapel Hill School of Medicine, Chapel Hill, NC, USA. Electronic address: howardj@neurology.unc.edu."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "40811489", "title": "Predicting achievement of clinical goals using machine learning in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia Gravis (MG) is an autoimmune disease characterized by the production of autoantibodies against neuromuscular junctions, leading to varying degrees of severity and outcomes among patients. This variability makes clinical evaluation crucial for determining appropriate treatment targets. However, accurately assessing Minimal Manifestation (MM) status is challenging, requiring expertise in MG management. Therefore, this study aims to develop a diagnostic model for MM in MG patients by leveraging their clinical scores and machine learning approaches.\nMETHODS: This study included 1,603 MG patients enrolled from the Japan MG Registry in the 2021 survey. We employed non-negative matrix factorization to decompose three MG clinical scores (MG composite score, MGADL scale, and MG quality of life (QOL) 15r) into four distinct modules: Diplopia, Ptosis, Systemic symptoms, and QOL. We developed a machine learning model with the four modules to predict MM or better status in MG patients. Using 414 registrants from the Japan MG Registry in the 2015 survey, we validated the model's performance using various metrics, including area under the receiver operating characteristic curve (AUROC), sensitivity, specificity, accuracy, F1 score, and Matthews Correlation Coefficient (MCC).\nRESULTS: The ensemble model achieved an AUROC of 0.94 (95% CI: 0.94-0.94), accuracy of 0.87 (95% CI: 0.86-0.88), sensitivity of 0.85 (95% CI: 0.85-0.86), specificity of 0.89 (95% CI: 0.88-0.91), precision of 0.93 (95% CI: 0.92-0.94), F1 score of 0.89 (95% CI: 0.88-0.89), and MCC of 0.74 (95% CI: 0.72-0.75) on the validation dataset.\nCONCLUSIONS: The developed MM diagnostic model can effectively predict MM or better status in MG patients, potentially guiding clinicians in determining treatment objectives and evaluating treatment outcomes.", "authors": ["Akamine Hiroyuki", "Uzawa Akiyuki", "Kuwabara Satoshi", "Suzuki Shigeaki", "Onishi Yosuke", "Yasuda Manato", "Ozawa Yukiko", "Kawaguchi Naoki", "Kubota Tomoya", "Takahashi Masanori P", "Suzuki Yasushi", "Watanabe Genya", "Kimura Takashi", "Sugimoto Takamichi", "Samukawa Makoto", "Minami Naoya", "Masuda Masayuki", "Konno Shingo", "Nagane Yuriko", "Utsugisawa Kimiaki"], "journal": "PloS one", "entry_date": "2025/08/14 14:03", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40811489/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Graduate School of Medicine, Chiba University, Chiba, Japan."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40804363", "title": "A nurse-led nomogram for predicting the risk of myasthenic crisis in patients with myasthenia gravis and bulbar weakness.", "abstract": "BACKGROUND: The present study aimed to develop and validate a nurse-led clinical prediction model for assessing the risk of myasthenic crisis (MC) in myasthenia gravis (MG) patients with bulbar weakness.\nMETHODS: A retrospective analysis was conducted on MG patients meeting the inclusion criteria from January 2022 to June 2024. The training group included 308 patients (January 2022-January 2024), and the validation group included 77 patients (February 2024-June 2024). The primary outcome was MC occurrence. A binary logistic regression model was constructed and presented as a nomogram. Model performance was evaluated using the area under the receiver operating characteristic curve (AUC) values, calibration curves, and decision curve analysis (DCA). Internal validation was performed by bootstrap resampling, while external validation was conducted using a validation cohort.\nRESULTS: The study included 385 MG patients. Logistic regression analysis identified Myasthenia Gravis Foundation of America classification, presence of thymoma, body position, partial pressure of carbon dioxide, oxygenation index, and oropharyngeal secretions as the independent predictors of MC. The nomogram showed good discrimination, with AUC values of 0.806 (sensitivity: 76.0%, specificity: 71.7%) in the training group and 0.832 (sensitivity: 60.0%, specificity: 95.2%) in the validation group. The model also exhibited good calibration, and the results of DCA confirmed the clinical utility of the model across a range of risk thresholds.\nCONCLUSION: This nomogram can serve as an effective tool for nurses to identify MG patients at a high risk of developing MC. Because this study was a single-center retrospective study, future multicenter validation studies are required to further verify and expand the clinical applicability of this model.", "authors": ["Dong Huimin", "Li Mengna", "Ma Mei", "Qi Guoyan"], "journal": "BMC neurology", "entry_date": "2025/08/13 23:43", "pub_date": "2025-08-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40804363/", "pub_types": ["Journal Article"], "affiliations": ["Center of Treatment of Myasthenia Gravis, People's Hospital of Shijiazhuang, Shijiazhuang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "40802145", "title": "Clinical characteristics, treatment and prognosis of pembrolizumab induced myocarditis.", "abstract": "To explore the regularity and clinical characteristics of pembrolizumab induced myocarditis, and to provide a reference for the diagnosis and treatment of myocarditis. Clinical reports of pembrolizumab induced myocarditis were collected by searching the database as of May 31, 2025. Clinical data were extracted and analyzed statistically. A total of 97 patients were enrolled in the study, with a median age of 70 years (range 25, 89), of which 53(54.6%) were male. The median time for diagnosis of myocarditis was 25 days (range 3, 4050). The common clinical symptoms were dyspnoea (23.7%), shortness of breath (16.5%), and thoracic pain (13.4%). Myositis and/or myasthenia gravis occurred in 43.3% of the patients. These patients with myocarditis may be accompanied by abnormalities in myocardial biomarkers, electrocardiograms, cardiac magnetic resonance and echocardiograms. After the patients discontinued pembrolizumab and received steroid-based immunotherapy, 72.2% of the patients recovered and 26.8% of the patients died. Myocarditis is a rare and fatal immune-related adverse event of pembrolizumab. Cardiac biomarkers, electrocardiograms and echocardiograms should be monitored during the use of Pembrolizumab. Cardiac magnetic resonance or myocardial biopsy can be used to further confirm myocarditis.", "authors": ["Wu Zhaoquan", "Sun Wei", "Wang Chunjiang"], "journal": "Investigational new drugs", "entry_date": "2025/08/13 11:28", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40802145/", "pub_types": ["Journal Article"], "affiliations": ["College of Pharmacy, Changsha Medical University, No. 1501 Leifeng Avenue, Xiangjiang New District, Changsha, 410219, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40800691", "title": "AI-based thematic exploration to understand patients with myasthenia gravis by serological subtype.", "abstract": "OBJECTIVE: Myasthenia gravis (MG) is challenging to diagnose and appropriate treatment is informed by serological versus diagnostic testing. Digital conversations can reveal insights into patient perceptions and concerns that may differ across autoantibody subtypes. The purpose of this study was to describe MG-related sentiments, barriers, and drivers by describing digital conversations by serostatus/serotype.\nMETHODS: US-based public-domain conversations focusing on MG and posted within topical sites, message boards, social networks, and blogs from August 2022 to August 2023 were mined. Content contributors self-identified by MG serostatus (seropositive/seronegative/AChR+/MuSK+/LRP4+) within the conversations or on public profiles. Advanced search techniques and AI-powered algorithms were used to extract/organize data by topics into a large, unstructured dataset. Natural language processing identified frequent topics, sentiments, mindsets, and drivers/barriers to treatment.\nRESULTS: In total, 8,784 conversations were mined from seropositive patients and/or their caregivers (including 1,058 AChR+, 589 MuSK+, and 537 LRP4+) and 2,261 were mined from seronegative patients and/or their caregivers. All conversations revealed an uncertain mindset, with a struggling mindset more prevalent among seronegative posts and ~40% of seropositive posts deemed utilitarian/indomitable. Positive drivers of sentiment were not seen for any subgroup. Negative drivers centered on misdiagnosis and symptoms more frequently in seronegative posts, and on impact on life in seropositive posts. Instability of symptom control in all subgroups impacted quality of life.\nCONCLUSION: Conversations revealed the burden of misdiagnosis for the seronegative group, negative impact on life for the seropositive group, and overall difficulty of the MG diagnostic journey. Digital conversations across MG serostatus subgroups related to the patient/caregiver experience of living with MG might provide useful insights for healthcare professionals seeking to improve patient care.", "authors": ["Jackson Louis", "Brethenoux Caroline", "DeLuca Alyssa", "Pesa Jacqueline", "Choudhry Zia", "Furey Patrick", "Alvarez Rosario", "Gonzalez Laura", "Lorenzo Alex", "Govindarajan Raghav", "Anderson Ashley E L"], "journal": "Frontiers in neurology", "entry_date": "2025/08/13 06:07", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40800691/", "pub_types": ["Journal Article"], "affiliations": ["Johnson & Johnson, Horsham, PA, United States."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40800064", "title": "Diagnosing myasthenia gravis versus congenital myasthenia gravis in British Shorthair cats: A case study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an acquired autoimmune disorder characterized by autoantibodies targeting the neuromuscular junction of skeletal muscles. In contrast, congenital myasthenic syndromes (CMSs) represent a clinically diverse group of genetic disorders affecting the neuromuscular junctions, with early onset and autosomal recessive inheritance. CMSs are particularly prevalent in Devon Rex and Sphynx cats. The gold standard for diagnosing MG in cats involves detecting neuromuscular junction autoantibodies by measuring acetylcholine receptor autoantibodies using radioimmunoassay. For CMS, a definitive diagnosis requires the identification of a causative genetic mutation in addition to clinical signs of skeletal muscle weakness and fatigue. With the Sphynx and Devon Rex breeds, data collected have identified a candidate disease region on the feline C2 chromosome, discovered by employing a genome-wide single-nucleotide polymorphism-based homozygosity mapping strategy. Given that MG is an autoimmune condition, it is treated with steroids, immunosuppressive drugs, and sometimes a thymectomy (surgical removal of the thymus gland). CMS is a set of genetic conditions that do not respond to these treatments. Hence, accurate differential diagnosis is critical.\nCASE PRESENTATION: Presented in this case study was a British Shorthair feline which was anamnetically, clinically, paraclinically, and pharmacologically assessed. Genetic testing revealed a positive result for the COLQ gene mutation.\nCONCLUSION: This case study clarified and added criteria to the differential diagnosis between MC and CMS, allowing for more accurate prognostic evaluations and appropriate treatment planning. It also underscores the importance of genetic testing in British Shorthair cats to differentiate between these conditions.", "authors": ["Amfim Adriana", "Cartacuzencu Maria"], "journal": "Journal of biological methods", "entry_date": "2025/08/13 05:58", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40800064/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Veterinary Medicine, Faculty of Veterinary Medicine, Spiru Haret University, Bucharest 030045, Romania."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.9, "journal_quartile": "4区"}, {"pmid": "40795646", "title": "Immune checkpoint inhibitor-related neurotoxicity: Incidence and management. A systematic review and meta-analysis.", "abstract": "BACKGROUND: Immune checkpoint inhibitors (ICIs) have improved outcomes for various malignancies. However, serious immune-related adverse events (irAEs), including neurologic complications (NAEs), may occur. The aim of this study was to examine the incidence and spectrum of NAEs and evaluate management strategies for reducing their impact.\nMETHODS: Two studies were conducted: 1) A meta-analysis of phase I-IV clinical trials involving adults with malignancies treated with ICIs, either as monotherapy, in combination with other ICIs, or with chemotherapy. The primary outcome was the incidence of (ir)NAEs, summarized using a meta-analysis with a random-effects model. 2) A systematic review of the literature addressing the clinical manifestations and treatment of irNAEs.\nRESULTS: The meta-analysis included 657 unique trials with 91,340 participants. For all ICIs, the incidence of all-grade NAEs was 0.24% (95% CI, 0.15-0.32%). Cerebral events, cerebrovascular accidents, were increased post-treatment and accounted for 54% of all grade-5 events in clinical trials. Among 991 reported irNAE cases, 77% of patients improved with treatment; however, 42% experienced unresolved sequelae and the overall mortality rate was 17.1%. Among patients with overlapping myasthenia gravis, myositis, and myocarditis (\"Triple M\"), the mortality reached 38%; primarily due respiratory failure (50%) or cardiotoxicity (41%).\nCONCLUSIONS: Although the incidence of ICI-related NAEs is low such side effects may lead to severe morbidity and mortality. In patients with Triple M syndrome intensive respiratory function monitoring and support are essential parameters to improve the outcome. PROSPERO Protocol # CRD42023463750.", "authors": ["Nielsen Dorte Lisbet", "Juhl Carsten Bogh", "Chen Inna Markovna", "Wang Yinghong", "Nielsen Ole Haagen", "Santomasso Bianca Denise"], "journal": "Cancer treatment reviews", "entry_date": "2025/08/12 18:12", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40795646/", "pub_types": ["Journal Article", "Meta-Analysis", "Systematic Review"], "affiliations": ["Department of Oncology, Herlev and Gentofte Hospital, University of Copenhagen, Copenhagen, Denmark. Electronic address: dorte.nielsen.01@regionh.dk."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 10.5, "journal_quartile": "1区"}, {"pmid": "40795619", "title": "Clinical utility of autoantibodies in the diagnosis and management of Myasthenia gravis.", "abstract": "Myasthenia gravis is an autoimmune neuromuscular disease characterised by fatigable muscle weakness. The disease is caused by autoantibodies targeting components of the post-synaptic neuromuscular junction, which are identifiable in 90 % of cases. The most well-known and best-characterised of these is acetylcholine-receptor (AChR) antibody, which is present in approximately 50 % of ocular and 85 % of generalised MG patients. Other recognised pathogenic autoantibodies in MG target muscle specific kinase (MuSK) and low-density lipoprotein-receptor related protein 4 (LRP4), present in approximately 5-10 % and 1-5 % of MG cases respectively. Some autoantibodies are not directly pathogenic but inform disease severity and thymic status. Many other autoantibodies are described in MG, although their pathogenic role and clinical significance is yet to be determined. These include autoantibodies targeting COLQ, cortactin, rapsyn, AChE, and Kv1.4. In this review, we discuss the clinical utility of all autoantibodies implicated in MG to date, including their role in the diagnosis, management, and monitoring of the disease.", "authors": ["El-Wahsh Shadi", "Ramanathan Sudarshini", "Reddel Stephen"], "journal": "Journal of neuroimmunology", "entry_date": "2025/08/12 18:10", "pub_date": "2025-10-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40795619/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Faculty of Medicine and Health, University of Sydney, Sydney, NSW, Australia; South Western Sydney Clinical School, University of New South Wales, Sydney, NSW, Australia; Neurology Department, Concord Repatriation General Hospital, Sydney, NSW, Australia. Electronic address: ShadiMedhat.ElWahsh@health.nsw.gov.au."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "40795579", "title": "Generation of an induced pluripotent stem cell line from a malignant melanoma patient who developed the immune checkpoint inhibitor-related myasthenia gravis, myositis, and myocarditis overlap syndrome.", "abstract": "Immune checkpoint inhibitors (ICI) are a pivotal class of immuno-oncology therapeutics that have improved survival rates for patients with cancer. Their widespread usage, however, is limited due to the development of serious and potentially deadly ICI-related side effects. To develop novel diagnostic and therapeutic strategies to identify and treat patients at risk, we need a better understanding of the underlying mechanisms mediating these potentially deadly side effects. To reach this goal, we have generated and validated induced pluripotent stem cells from the peripheral blood mononuclear cells of a melanoma patient who developed ICI-related myasthenia gravis, myositis, and myocarditis overlap syndrome.", "authors": ["Huynh Diem Thi Ngoc", "Noishiki Chikage", "Lai Jacquelyn", "Yarahmadi Pourya", "Le Thao", "Tripathi Dipti", "Tacco Ines Ross", "Manhas Amit", "Sallam Karim", "Chen Ian Y", "Sayed Nazish", "Nguyen Patricia K"], "journal": "Stem cell research", "entry_date": "2025/08/12 18:08", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40795579/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Stanford Cardiovascular Institute, Stanford University School of Medicine, Stanford, CA 94305, USA; Division of Cardiovascular Medicine, Stanford University School of Medicine, Stanford, CA 94305, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40793909", "title": "[Hemodynamic monitoring during anesthetic induction in a patient with myasthenia gravis in septic shock].", "abstract": "", "authors": ["Prado Eduardo M", "Coronel Carolina", "Sinner Jorge F"], "journal": "Medicina", "entry_date": "2025/08/12 09:44", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40793909/", "pub_types": ["Journal Article"], "affiliations": ["Terapia Intensiva de Adultos, Hospital Italiano de Buenos Aires, Buenos Aires, Argentina. E-mail: eduardo.prado@hospitalitaliano.org.ar."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "40787486", "title": "Breaking chains: IMAAVY redefines generalized myasthenia gravis treatment.", "abstract": "", "authors": ["Shahid Kamran", "Shahid Syeda Rabiah", "Khalid Maliha", "Waafira Aminath"], "journal": "Annals of medicine and surgery (2012)", "entry_date": "2025/08/11 06:31", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40787486/", "pub_types": ["Letter"], "affiliations": ["Shaikh Khalifa Bin Zayed Al-Nahyan Medical And Dental College,Lahore, Pakistan."], "china_related": false, "study_types": ["Letter"], "evidence_level": null, "journal_if": 1.6, "journal_quartile": "4区"}, {"pmid": "40787458", "title": "A pilot study of the immunological profile and efficacy of rituximab in muscle-specific kinase antibody-positive myasthenia gravis.", "abstract": "PURPOSE: This study summarized the clinical and immunological characteristics of patients with muscle-specific kinase (MuSK) antibody-positive myasthenia gravis (MG), compared their difference with acetylcholine receptor (AChR) antibody-positive MG, and evaluated the therapeutic efficacy of rituximab (RTX) in MuSK-MG.\nMETHODS: This study included 10 MuSK-MG patients and 10 new-onset AChR-MG patients. Clinical and immunological data were collected from medical records before RTX treatment. The efficacy of RTX in MuSK-MG was evaluated by MG-specific activities of daily living (MG-ADL) and quantitative MG (QMG) scores.\nRESULTS: All 10 MuSK-MG patients were female with a mean onset age of 44.3 ± 12.0 years, predominantly presenting with bulbar muscle weakness (90%) and limb weakness (80%). Compared to AChR-MG, MuSK-MG showed higher MG-ADL and QMG scores (P < 0.05), along with more frequent bulbar involvement at disease onset (P = 0.036). Immunological analyses revealed elevated CD19+B cells and memory B cells in MuSK-MG (P < 0.05). CD4+T cells and CD19+B cells showed positive correlations with QMG score (r = 0.766, P = 0.027; r = 0.767, P = 0.026), while natural killer (NK) cells were negatively correlated (r = -0.803, P = 0.005) in MuSK-MG. MuSK-MG patients had a mean MG-ADL score of 8.7 ± 2.5 at baseline. Following RTX treatment, MG-ADL score showed significant improvement, decreasing by -5.1 (95% CI: -7.6 to -2.6) at month 1 and -8.0 (95% CI: -11.0 to -5.0) at month 24. Nine patients took prednisone before RTX, with a median daily dosage of 40.0 mg, which decreased to 2.5 mg/day at month 6, and 8 of 9 (88.7%) patients discontinuing prednisone since month 12.\nCONCLUSION: MuSK-MG showed distinct clinical and immunological features, including predominant bulbar/limb onset, elevated CD19+B and memory B cells, and disease severity associated CD4+T, CD19+B and NK-cell alterations. In patients with MuSK-MG, low-dose RTX may be associated with long-term and sustained clinical improvement.", "authors": ["Li Fengzhan", "Zhang Zhouao", "Ma Tianyu", "Li Yuting", "Su Luyao", "Wang Zhouyi", "Luo Tiancheng", "Peng Deyou", "Guo Xinyan", "Yang Mingjin", "Du Xue", "Huang Xiaoyu", "Zhang Yong"], "journal": "Frontiers in immunology", "entry_date": "2025/08/11 06:30", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40787458/", "pub_types": ["Journal Article"], "affiliations": ["People's Hospital of Jiawang of Xuzhou, Jiawang Branch of Xuzhou Medical University Affiliated Hospital, Xuzhou, Jiangsu, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40783336", "title": "Eminectomy performed through an innovative digital workflow.", "abstract": "Eminectomy has been a well-established surgical procedure for the management of recurrent temporomandibular joint (TMJ) dislocation for over seven decades. This paper presents a digital workflow designed to enhance the surgical precision and safety of eminectomy. A 22-year-old female patient with recurrent TMJ dislocation underwent bilateral eminectomy. The patient's medical history included myasthenia gravis, which was considered in the surgical planning. A digitally designed cutting guide and depth template were created using Dolphin Imaging 11.95 software and subsequently produced via 3D-printing. The eminectomy was performed using a piezoelectric device, with the cutting guide ensuring a precise osteotomy and the depth template limiting bone removal to the necessary extent. The use of these digitally planned instruments facilitated a more efficient procedure compared to previous eminectomies performed by the same surgeon. Furthermore, the preoperative digital workflow enhanced the surgical safety by protecting the adjacent neurovascular structures through the customized cutting guide and depth template. In conclusion, digitally planned and 3D-printed surgical guides are valuable tools that may significantly improve the precision, efficiency, and safety of eminectomy.", "authors": ["Melhem-Elias F", "Reis B A Q", "de Oliveira N K", "Grillo R"], "journal": "International journal of oral and maxillofacial surgery", "entry_date": "2025/08/09 21:57", "pub_date": "2025-12", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40783336/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Oral and Maxillofacial Surgery, School of Dentistry, University of São Paulo, São Paulo, Brazil."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40781689", "title": "Mesenchymal stromal cells conditioned by peripheral blood mononuclear cells exert enhanced immunomodulation capacities and alleviate a model of Myasthenia Gravis.", "abstract": "BACKGROUND: Mesenchymal Stromal Cells (MSC) possess innate immunomodulatory properties, which can be significantly enhanced through co-culture with peripheral blood mononuclear cells (PBMC), making them attractive tools for the treatment of autoimmune and inflammatory diseases.\nMETHODS: Leveraging a multi-omics approach encompassing RNA sequencing, flow and mass cytometry, secretome analysis, completed by functional evaluations, we investigated the mechanisms underpinning PBMC conditioning of MSC in vitro and their benefits in an animal model of Myasthenia gravis. MSC derived from human adipose tissue were left untreated in resting state (rMSC), conditioned by PBMC (cMSC), or activated by the pro-inflammatory molecule interferon (IFN)-γ (γMSC), then compared for their gene expression profiles, phenotypes and functional capacities.\nRESULTS: RNA sequencing identified 244 differentially expressed genes in cMSC compared to rMSC, highlighting key immune mediators such as CCL2, CCL11, DPP4, ICAM1, IL6, PDCD1LG2, TNFRSF11B, TNIP1, TNIP3 and ZC3H12A and pinpointing genes involved in matrix remodeling, paracrine and autocrine communications. Comparatively, 2089 genes were differentially expressed between rMSC and γMSC, highlighting host defense, anti-viral response, NFκB signaling pathways modulated by IFN-γ. Flow and mass cytometry analyses revealed upregulation of the surface markers CD26, CD54, and CD273 and intracellular molecules IDO1 and PTGS2 in cMSC. In contrast, IFN-γ activation predominantly increased HLA-related markers while also enhancing the homogeneity of the populations. Together, these results underlined the treatment dependence of transcriptomic and phenotypic signatures. Secretome profiling identified 6 categories of modulated proteins, out of which 22 molecules potentially involved in PBMC conditioning and 40 implicated in cMSC-mediated immunomodulation. Functionally, cMSC induced modulation in PBMC subsets, raising the proportions of lymphocyte populations (CD4 Treg, CD8, B memory), underlining the multimodal effect of conditioning. Also, both a direct cell-cell contact and cMSC supernatants significantly suppressed activated T-cell proliferation in vitro. To confirm immunomodulation efficacy in vivo, cMSC were administrated to our humanized mouse model of Myasthenia Gravis and the treatment significantly halved disease severity from 2 weeks post-injection.\nCONCLUSIONS: This integrative study establishes distinct conditioning signatures, suggests molecular mechanisms, and underscores the therapeutic potential of cMSC, offering a robust framework for advancing cell-based therapies in autoimmune diseases.", "authors": ["Bayer Alexandra C", "Pinzón Natalia", "You Axel", "Bergman Cinthia", "Dragin Nadine", "Corneau Aurélien", "Truffault Frédérique", "Noël Danièle", "Martinaud Christophe", "Le Panse Rozen", "Berrih-Aknin Sonia", "Vilquin Jean-Thomas"], "journal": "Stem cell research & therapy", "entry_date": "2025/08/09 00:34", "pub_date": "2025-08-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40781689/", "pub_types": ["Journal Article"], "affiliations": ["Sorbonne Université, INSERM, Institut de Myologie, GH Pitié-Salpêtrière, Centre de Recherche en Myologie, Paris, F-75013, France."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40780820", "title": "Fatiguable camptocormia as a presenting feature of myasthenia gravis in the elderly.", "abstract": "", "authors": ["Poh Mervyn Qi Wei", "Lim Christen", "Vijayan Joy"], "journal": "Practical neurology", "entry_date": "2025/08/08 21:03", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40780820/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, National Neuroscience Institute, Singapore mervyn.poh@gmail.com."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "40779124", "title": "Nipocalimab: First Approval.", "abstract": "Nipocalimab (nipocalimab-aahu; IMAAVY™) is a fully human monoclonal antibody that binds to and blocks the neonatal fragment crystallizable (Fc) receptor (FcRn) resulting in the reduction of circulating IgG levels. It is being developed by Johnson & Johnson for the treatment of a number of autoimmune disorders. On 29 April 2025, nipocalimab received its first approval in the USA for the treatment of generalized myasthenia gravis in adult and pediatric patients ≥ 12 years of age who are anti-acetylcholine receptor or anti-muscle specific tyrosine kinase antibody positive. Regulatory review of nipocalimab is underway for generalized myasthenia gravis in Japan and the European Union. This article summarizes the milestones in the development of nipocalimab leading to this first approval for generalized myasthenia gravis.", "authors": ["Fung Simon"], "journal": "Drugs", "entry_date": "2025/08/08 11:15", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40779124/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Springer Nature, Private Bag 65901, Mairangi Bay, Auckland, 0754, New Zealand. dru@adis.com."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 14.4, "journal_quartile": "1区"}, {"pmid": "40776639", "title": "A Prospective Clinical Trial of Efgartigimod for New-Onset Generalized Myasthenia Gravis.", "abstract": "INTRODUCTION: Numerous studies have demonstrated that efgartigimod is effective in treating myasthenia gravis (MG) across various patient populations. However, there is limited evidence regarding its use in patients with new-onset acetylcholine receptor antibody-positive generalized MG (AChR-gMG). Therefore, this study aimed to investigate the real-world safety and effectiveness of efgartigimod in Chinese patients with new-onset anti-cholinergic receptor (AChR)- gMG.\nMETHODS: This prospective study was conducted in 29 patients with new-onset AChR-gMG, with a three-month follow-up. The Myasthenia Gravis Activities of Daily Living (MG-ADL) score, Quantitative Myasthenia Gravis score, prednisone dose, laboratory data, and adverse events were assessed at every follow-up visit.\nRESULTS: At 4, 8, and 12 weeks, the mean change in MG-ADL scores was 8.13 ± 3.66, 7.41 ± 4.22, and 6.37 ± 4.67, respectively. Compared with the baseline, 96% (28/29) of patients achieved an MG-ADL response (defined as a decrease of ≥2 points), with a mean response time of 0.81 ± 0.53 weeks (5.67 ± 3.71 days). After one cycle, 52% (15/29) of patients achieved minimal symptom expression (MSE), while 41% maintained MSE at 12 weeks. Moreover, 89% and 72% of MG-ADL responders sustained for 8 and 12 consecutive weeks, respectively. Additionally, patients with thymomatous MG exhibited a poorer response to efgartigimod and required two infusion cycles. All patients were able to reduce their daily steroid dose, and the mean daily prednisone dose decreased by 10.73 mg per day. The treatment was well tolerated, and a few mild adverse events were reported.\nDISCUSSION: These results demonstrate the clinical significance of efgartigimod in patients with newonset AChR-gMG, achieving rapid symptom relief and steroid reduction. Additionally, the potential of efgartigimod to serve as a bridge treatment, facilitating a steady transition to long-term conventional immunosuppressive therapy, was demonstrated. Due to limitations in this study, such as a small sample size, larger randomized controlled trials are needed to validate.\nCONCLUSION: Our study showed that efgartigimod is clinically beneficial and offers rapid symptom control in patients with new-onset AChR-gMG. A more aggressive application of efgartigimod in combination with corticosteroids may lead to a smoother therapeutic transition, which will further maintain favorable conditions.", "authors": ["Ma Chi", "Shen Jingyi", "Zhu Ying", "Zhu Ruixia"], "journal": "Current neuropharmacology", "entry_date": "2025/08/08 03:24", "pub_date": "2026", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40776639/", "pub_types": ["Journal Article", "Clinical Trial"], "affiliations": ["Department of Neurology, The First Hospital, China Medical University, Shenyang, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.3, "journal_quartile": "2区"}, {"pmid": "40775651", "title": "Spectrum and epidemiology of rare diseases in a Chinese natural population of 14.31 million residents, 2012-2023.", "abstract": "BACKGROUND: Rare diseases, though individually uncommon, collectively affect a significant portion of the population. However, their epidemiology in China remains underexplored. A population-based rare disease registry comprising 14.31 million individuals was conducted between 2012 and 2023 by the Beijing Municipal Health Big Data and Policy Research Center. Rare disease cases were identified via ICD-10 codes mapped to China's national rare disease lists (2018 and 2023) and international databases. Age-standardized incidence rates (ASIR) were calculated per 100,000 person-years with 95% confidence intervals.\nRESULTS: Our analysis identified 12,371 rare disease cases, with the overall ASIR increasing from 6.109 in 2012 to 7.394 in 2023. Rare neurologic diseases accounted for 52.12% of cases, followed by systemic and rheumatologic diseases (16.89%) and rare neoplastic diseases (9.99%). The most frequently diagnosed rare diseases included generalized myasthenia gravis, ANCA-associated vasculitis, and malignant melanoma. Significant sex-based differences were observed, with female patients more affected by systemic and rheumatologic conditions, while male patients showed a higher incidence of respiratory disorders. Pediatric patients predominantly presented with inborn errors of metabolism and rare immune diseases. Comparisons with global data revealed notable disparities, such as a higher prevalence of Wilson's disease and a lower incidence of amyotrophic lateral sclerosis (ALS) in China.\nCONCLUSIONS: This study represents the first large-scale, population-based analysis of rare diseases in China, revealing distinct epidemiological patterns. These findings underscore the critical need for healthcare policies that address the unique challenges posed by rare diseases in China.", "authors": ["Li Ming-Jia", "Li Qi", "Zhao Miao-Miao", "Kim Hanna", "Feng Ruo-Qi", "Guo Mo-Ning", "Heng Jian-Peng", "Yang Jin-Kui", "Liu Chang"], "journal": "Orphanet journal of rare diseases", "entry_date": "2025/08/08 00:21", "pub_date": "2025-08-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40775651/", "pub_types": ["Journal Article"], "affiliations": ["Department of Endocrinology, Beijing Tongren Hospital, Capital Medical University, Beijing, 100730, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.5, "journal_quartile": "2区"}, {"pmid": "40775536", "title": "Impact of disease activity on quality of life and EQ-5D-3L score in myasthenia gravis: results from the Swedish MG registry.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disease causing motor fatiguability. The impact of MG on quality of life (QoL) is incompletely studied. Here, we explore the impact of disease activity on QoL.\nMETHODS: Using the Swedish nationwide MG registry, 150 MG cases with concomitant EQ-5D-3L and MG-ADL, QMG and/or MG-QoL-15 scores were identified. An EQ-5D score was derived from EQ-5D-3L using the UK time trade-off tariff and compared to a Swedish reference population. Longitudinal analysis assessing the impact of change in MG-ADL on QoL was performed on data from the randomized-controlled RINOMAX trial.\nRESULTS: EQ-5D score was negatively correlated with MG-ADL, QMG and MG-QoL-15 (R =  - 0.48, - 0.33, and - 0.66, respectively; p < 0.01). The usual activities dimension deviated most from reference population, although all dimensions were significantly impacted. Lower EQ-5D score was observed already at low-to-moderate disease activity, MG-ADL 3-5 points, compared to reference (0.71 [SD 0.23] vs. 0.81 [SD 0.04]; p = 0.01), and was further decreased with higher disease activity. Longitudinal analyses revealed a significant decrease of EQ-5D score per point increase in MG-ADL (β -0.050 [95%CI -0.077, -0.023]; p < 0.001). Most impact on EQ-5D score was observed by limb and respiratory items (limb β - 0.17 [95%CI - 0.26, - 0.071]; p = 0.001, respiratory β - 0.21 [95%CI - 0.39, - 0.031]; p = 0.022), while bulbar symptoms showed no effect on EQ-5D score.\nCONCLUSIONS: We observed a considerably decreased EQ-5D score already at low disease activity in MG patients, worsening with increasing disease activity. This indicates an unmet medical need that warrants improved treatment and care.", "authors": ["Petersson Malin", "Wu Jing", "Berggren Fredrik", "Schager Ingrid", "Piehl Fredrik", "Brauner Susanna"], "journal": "Journal of neurology", "entry_date": "2025/08/08 00:02", "pub_date": "2025-08-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40775536/", "pub_types": ["Journal Article"], "affiliations": ["Neuroimmunology Unit, Department of Clinical Neurosciences, Karolinska Institutet, 17176, Stockholm, Sweden. malin.petersson@ki.se."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "40772172", "title": "Atypical Ocular Myasthenia-Like Presentation in a Patient With a Heterozygous SQSTM1 Variant.", "abstract": "We report the case of a patient presenting with diplopia, ptosis, and blurred vision who was found to have a heterozygous SQSTM1 gene variant (c.1175C>T) following electrophysiological evidence of a postsynaptic neuromuscular junction disorder. The patient had negative antibody testing, mildly elevated creatine phosphokinase (CPK), and abnormal organic acid analysis. Repetitive nerve stimulation demonstrated a decremental response consistent with impaired postsynaptic transmission. Given the atypical presentation and systemic findings, genetic testing was pursued, revealing a variant of uncertain significance in SQSTM1, despite the variant being classified as pathogenic in genetic databases. This case raises the possibility of a broader neuromuscular phenotype associated with SQSTM1 mutations and underscores the value of genetic testing in seronegative neuromuscular disorders. It also highlights the need to consider SQSTM1 variants in the differential diagnosis of seronegative neuromuscular presentations.", "authors": ["Sanchez-Cordero Milaris M", "Rosado Josean M", "Rivera Troia Felix", "Ocasio Villa Fernando J"], "journal": "Cureus", "entry_date": "2025/08/07 05:15", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40772172/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Mayaguez Medical Center, Mayaguez, PRI."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40770830", "title": "Single-cell atlas reveals heterogeneous response to FcRn blockade in anti-AChR antibody-positive generalised myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disease predominantly driven by autoantibodies targeting acetylcholine receptor (AChR), resulting in muscle weakness. Efgartigimod, a neonatal Fc receptor (FcRn) blocker, reduces pathogenic immunoglobulin G in anti-AChR antibody-positive generalised MG (gMG). This study aimed to identify immune mechanisms underlying MG pathology and response to efgartigimod.\nMETHODS: We constructed a single-cell atlas of peripheral immune cells from treatment-naïve and efgartigimod-treated patients with gMG. Comprehensive immunophenotyping was performed to compare the clonal diversity of B- and T-cell populations, alongside experimental validation to assess the activation of Th17-related pathways before and after FcRn blockade.\nRESULTS: B cells in patients with gMG exhibit heightened activation and differentiation, while T cells display distinct pro-inflammatory phenotypes. Enhanced intercellular signalling contributed to the pathogenicity associated with gMG. Efgartigimod mitigated upregulated antigen processing and presentation pathways in MG. Additionally, B-cell clonal diversity and IGHG1-bearing B-cell receptors increased. Transcriptional factor alterations were noted in suboptimal responders. Regulation of T-cell activity, particularly within Th17-related pathways, was associated with remission rates.\nCONCLUSIONS: These findings underscore immune heterogeneity and dynamics during efgartigimod treatment, providing mechanistic insights into therapeutic response in gMG.\nKEY POINTS:   Aberrant B cells and pro-inflammatory T cells contribute critically to generalised myasthenia gravis (gMG) pathogenesis. Neonatal Fc receptor (FcRn) blockade induces immunoglobulin G (IgG) depletion feedback, reflected by increased class-switched BCRs. Th17 cell proliferation is attenuated following FcRn blockade. Antigen processing and presentation pathways are downregulated after FcRn blockade in gMG.", "authors": ["Li Hui-Ning", "Liu Jingjing", "Huang Xiao-Yu", "Zhu Lijie", "Liu Zhirui", "Yang Chun-Sheng", "Zhang Bo", "Huang Shixiong", "Shi Fu-Dong", "Cai Zhigang", "Zhang Chao"], "journal": "Clinical and translational medicine", "entry_date": "2025/08/07 01:15", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40770830/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tianjin Neurological Institute, Tianjin Medical University General Hospital, Tianjin, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 6.8, "journal_quartile": "2区"}, {"pmid": "40769629", "title": "A Novel Strategy to Optimize Surgical Outcomes in Thymoma-Associated Myasthenia Gravis: Perioperative Use of Efgartigimod.", "abstract": "", "authors": ["Hishida Tomoyuki"], "journal": "Journal of thoracic oncology : official publication of the International Association for the Study of Lung Cancer", "entry_date": "2025/08/06 20:56", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40769629/", "pub_types": ["Editorial"], "affiliations": ["Department of General Thoracic Surgery, Saitama Medical University International Medical Center, Saitama, Japan. Electronic address: thishida@saitama-med.ac.jp."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 16.4, "journal_quartile": "1区"}, {"pmid": "40766205", "title": "National guidelines for diagnosis, treatment, and management of myasthenia gravis in Israel.", "abstract": "Myasthenia gravis (MG) is a chronic autoimmune neuromuscular disorder characterized primarily by fluctuating skeletal muscle weakness affecting ocular, bulbar, truncal, limb, and respiratory muscles. The disease is typically mediated by anti-acetylcholine receptor (AChR) antibodies, and less commonly by anti-muscle-specific kinase) or anti-low-density lipoprotein receptor-related protein 4 antibodies. Despite significant advancements in diagnostics and immunotherapy, disparities in treatment access and practice variability remain prevalent in Israel. To address these gaps, updated national guidelines have been developed, integrating the latest international evidence and adapting it to the local healthcare landscape, regulation, and population diversity. This national guideline emphasizes precise diagnostic evaluation through comprehensive clinical assessment, standardized antibody testing, neurophysiological studies, and mediastinal imaging for thymic pathology assessment. Utilizing standardized scales, including MG activities of daily living, quantitative MG score, and MG Foundation of America post-intervention status, is crucial for disease staging and therapeutic decision-making. Therapeutic goals prioritize achieving full remission or a state of minimal manifestations of disease with negligible treatment-related side effects. Guidelines for treatment strategies are based on antibody status, disease severity, patient age, and comorbidities. Thymectomy is recommended for patients with generalized AChR antibody-positive MG, ideally within 2 years of disease onset. Pregnant women, older adults, children, and patients with cancer need specific immunotherapy approaches. Multidisciplinary care, structured patient education, and psychosocial support are integral to managing MG effectively. These national guidelines aim to standardize clinical practices, enhance patient outcomes, and reduce healthcare disparities in the management of MG across Israel.\nNational guidelines for management of myasthenia gravis in Israel Myasthenia gravis (MG) is a chronic disease where the body’s immune system mistakenly attacks the proteins on muscles, eventually causing weakness effecing the eyes, face, arms, legs, and breathing. Occuring most often due to auto-antibodies against a molecule called the acetylcholine receptor (AChR). Although medical care for MG has improved a lot, people in Israel still face differences in how the disease is diagnosed and treated. Best of our county experts created updated national guidelines. These new guidelines combine the latest global research with the realities of healthcare in Israel. They recommend using clear steps for diagnosis, including physical exams, blood tests for antibodies, nerve tests, and chest imaging to look for problems with the thymus gland. Doctors are encouraged to use scoring systems, like the MG-ADL and QMGS, to track how patients are doing and guide treatment decisions. The main goal is to help patients reach full recovery or to have very few symptoms, with as few side effects from treatment as possible. Treatment plans are based on things like which antibodies a patient has, how severe the disease is, age, and other health conditions. Surgery to remove the thymus is suggested for certain patients, especially early in the disease. Special care plans are needed for pregnant women, children, older adults, and people with cancer. The guidelines also stress the importance of teamwork among different health specialists, teaching patients about their disease, and providing emotional support. Overall, these national guidelines are meant to ensure that all MG patients in Israel get better, more equal care.", "authors": ["Shelly Shahar", "Gotkine Marc", "Wilf Yarkoni Adi", "Lotan Itay", "Abraham Alon", "Dori Amir", "Wolfe Gil I", "Regev Keren", "Vaknin Adi", "Ben-Hur Tamir"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/08/06 05:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40766205/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Ruth and Bruce Rappaport Faculty of Medicine, Technion, Israel Institute of Technology, Haifa 3525408, Israel."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "40762789", "title": "Use of Corticosteroids in Myasthenia Gravis: Expert Opinion for Daily Management.", "abstract": "INTRODUCTION: Myasthenia gravis, a rare autoimmune disorder characterized by muscle weakness and fatigue, it is a mainly B-cell mediated condition with antibodies directed against the acetylcholine receptor or functionally related molecules at the neuromuscular junction. Corticosteroids are still the most used treatment, as they are cheap and characterized by a rapid response. However, their long-term administration is associated with frequent and often severe side effects.\nMETHODS: We used the Expert Opinion methodology: a panel of eight neurologists, known to be experts in the management of MG patients, and one specialist in pharmacoeconomics, were brought together to discuss clinical relevant issues about the use of corticosteroids in MG.\nRESULTS: Increasing doses of corticosteroids may temporarily exacerbate the symptoms of MG and clinical exacerbations can lead to severe consequences. In addition, prolonged chronic corticosteroid therapy carries a burden in terms of indirect costs due to side effects, which has prompted strategies to obtain the maximum benefits with minimal side effects.\nCONCLUSION: The panel concludes that, in the near future, therapeutic strategies based on the use drugs with better tolerability and potentially lower direct and indirect costs, will be necessary.", "authors": ["Mantegazza Renato", "Antonini Giovanni", "Gastaldi Matteo", "Liguori Rocco", "Maestri Michelangelo", "Pegoraro Elena", "Polistena Barbara", "Rodolico Carmelo", "Habetswallner Francesco"], "journal": "Neurology and therapy", "entry_date": "2025/08/05 11:16", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40762789/", "pub_types": ["Journal Article"], "affiliations": ["Neuroimmunology and Neuromuscular Diseases Unit, Fondazione IRCCS Istituto Neurologico Carlo Besta, Milan, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 4.8, "journal_quartile": "2区"}, {"pmid": "40761829", "title": "Efgartigimod following plasma exchange in the treatment of subjects with generalised myasthenia gravis: study protocol for a multicentre, three-arm, open-label study.", "abstract": "INTRODUCTION: Myasthenia gravis (MG), an IgG-mediated autoimmune disorder targeting neuromuscular junctions, shows refractory in 12-20% of generalised MG (gMG) patients despite immunotherapies. Plasma exchange (PLEX) transiently depletes pathogenic mediators, while neonatal Fc receptor antagonists (eg, efgartigimod) offer novel therapeutic potential. Both PLEX and efgartigimod require adjunctive non-steroidal immunosuppressive therapy (NSIST) for sustained remission. This study aims to evaluate the effectiveness and safety of efgartigimod working as a bridge treatment after PLEX but before NSIST taking effect, while concurrently conducting a comparative analysis of clinical outcomes between PLEX and efgartigimod in gMG.\nMETHODS AND ANALYSIS: This multicentre, open-label, three-arm trial (n=45 gMG patients) assigns cohorts to PLEX+efgartigimod, PLEX alone or efgartigimod alone. The intervention comprises PLEX and/or efgartigimod. Oral glucocorticoids and cholinesterase inhibitors are allowed during this study. NSIST starts the day after completing PLEX or the second dose of efgartigimod. Outcomes are assessed at weeks 4, 8, 12, 16, 20, 24, 36 and 48. Primary endpoint: proportion achieving minimal symptom expression (MSE) at week 48. Secondary endpoints: median time to first MSE, adverse events (AE) incidence/severity, exacerbation rates, neurological functional assessment scores, cholinesterase inhibitor/corticosteroid usage, serological evolution of immunological markers. All AEs are systematically documented and causality-assessed.\nETHICS AND DISSEMINATION: Ethical clearance for this investigation was granted by the Institutional Review Board of Punan Hospital in accordance with Declaration of Helsinki principles. All enrolled participants will provide written informed consent through standardised documentation processes prior to study enrolment. The results will be accessible in peer-reviewed publications.\nTRIAL REGISTRATION NUMBER: ChiCTR2500104662.", "authors": ["Wang Kan", "Li Qiuju", "Wu Yanan", "Zhang Mengze", "Wang Xiaokun", "Peng Jing", "Xie Chong", "Xue Chunran", "Gao Song", "Gao Li", "Yang Yiwei", "Wang Yuhui", "Zhang Lu", "Hao Yong", "Guan Yangtai"], "journal": "BMJ neurology open", "entry_date": "2025/08/05 04:55", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40761829/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Renji Hospital, Shanghai Jiaotong University School of Medicine, Shanghai, China."], "china_related": true, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40757701", "title": "Diaphragmatic Palsy Due to a Paraneoplastic Autoimmune Syndrome Revealed by Checkpoint Inhibitors.", "abstract": "Background and Clinical Significance: Immune checkpoint inhibitors (ICIs) have revolutionized cancer treatment but may underlie diverse and potentially life-threatening immune-related adverse events (irAEs). They may cause various conditions leading to respiratory failure, including myasthenic syndromes and myositis. However, diaphragmatic paralysis (DP) has rarely been reported. To describe patients with diaphragmatic paralysis in a pharmacovigilance registry, we searched the prospective REISAMIC registry at the Gustave Roussy Cancer Center (Villejuif, France) for cases of diaphragmatic palsy (DP) occurring from September 2014 to December 2021. Case Presentation: We identified three patients, in whom DP was confirmed by diaphragmatic ultrasonography, pulmonary function tests, and/or diaphragmatic electroneuromyogram. Diaphragmatic palsy was life-threatening in all patients, as it caused respiratory failure requiring mechanical ventilation. In all cases, a pre-existing subclinical paraneoplastic syndrome was detected. Onconeural antibodies (anti-titin and anti-VGCC) were detected in these patients before and after the initiation of ICI therapy, suggesting a mixed paraneoplastic syndrome with features overlapping those of myasthenic syndrome (myasthenia gravis in one patient and Lambert-Eaton syndrome in another) and myositis. Conclusions: Diaphragmatic palsy is a severe irAE potentially resulting from different mechanisms, including myositis and neuromuscular junction involvement (myasthenia gravis, Lambert-Eaton). Antineuronal antibodies associated with such conditions were already present in our patients prior to immunotherapy initiation, suggesting ICIs could trigger flare-ups of pre-existing silent paraneoplastic autoimmune conditions.", "authors": ["Destival Jean-Baptiste", "Michot Jean-Marie", "Cauquil Cécile", "Noël Nicolas", "Hacein-Bey-Abina Salima", "Chrétien Pascale", "Lambotte Olivier"], "journal": "Reports (MDPI)", "entry_date": "2025/08/04 08:03", "pub_date": "2024-10-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40757701/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Service de Médecine Interne et Immunologie Clinique, Hôpital Bicêtre, Assistance Publique-Hôpitaux de Paris, Groupe Hospitalier Universitaire Paris Saclay, 94270 Le Kremlin-Bicêtre, France."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40757546", "title": "Eculizumab as Additional Rescue Therapy in Myasthenic Crisis.", "abstract": "Eculizumab is a monoclonal antibody blocking the terminal complement protein C5. As demonstrated in the phase III randomized, placebo-controlled, REGAIN clinical trial, eculizumab is efficacious in acetylcholine receptor antibody (AChR-Ab)-positive refractory generalized myasthenia gravis (gMG) (Myasthenia Gravis Foundation of America-MGFA class II-IV). It has not been studied in severe myasthenic exacerbation or myasthenic crisis (MGFA V). A 73-year-old man diagnosed with myasthenia gravis AChR-Ab positivity came to our observation for symptoms of bulbar and ocular weakness and unresponsiveness or intolerability to conventional immunosuppressive therapies (prednisone and azathioprine). Due to the recurrent clinical worsening with intubation over a short-term period, the patient was treated with eculizumab. After 15 days of eculizumab treatment, we observed a significant recovery of clinical condition. We discharged the patient to an outpatient regimen, where he is continuing with maintenance doses of eculizumab and slowly tapering steroid intake. The use of eculizumab in myasthenic crises is still anecdotal. Our case aims to provide eculizumab benefit for refractory severe gMG in a practical, real-world setting beyond the criteria of the REGAIN study. Further studies are needed to evaluate the efficacy and safety of eculizumab in myasthenic crises.", "authors": ["Crescenzo Francesco", "Zanoni Mattia", "Ferigo Laura", "Rossi Francesca", "Grecò Matteo", "Lupato Angelica", "Danese Alessandra", "Ajena Domenico", "Turazzini Michelangelo"], "journal": "Muscles (Basel, Switzerland)", "entry_date": "2025/08/04 07:04", "pub_date": "2024-02-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40757546/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology Unit, \"Mater Salutis\" Hospital, AULSS 9 Scaligera, 37045 Verona, Italy."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.6}, {"pmid": "40757225", "title": "The Diagnostic Maze: Challenges in Autoimmune Hepatitis Lab Interpretation.", "abstract": "Autoimmune hepatitis (AIH) is a chronic inflammatory liver disease characterized by the presence of circulating autoantibodies. The spectrum of disease manifestations extends from asymptomatic cases to mild symptoms and, in rare instances, acute liver failure. AIH is a diagnosis of exclusion, supported by the detection of autoantibodies such as anti-smooth muscle antibody (ASMA). This case describes a 43-year-old female with myasthenia gravis, receiving monthly intravenous immunoglobulin (IVIG) infusions, who presented with persistently elevated liver enzymes and mildly elevated ASMA titers across multiple clinical encounters. A liver biopsy revealed severe acute hepatitis. While drug-induced liver injury (DILI) secondary to IVIG was initially considered the leading diagnosis, the persistence of elevated liver enzymes over two months despite discontinuation of IVIG made the diagnosis of AIH more likely and brought attention to the diagnostic challenges associated with AIH. Although ASMA is a hallmark serologic marker for AIH, it only has a moderate sensitivity of 59 %. Furthermore, IVIG administration may interfere with autoimmune testing, potentially leading to false-negative results. This case illustrates the complexity of interpreting autoimmune serologies and emphasizes the need for comprehensive diagnostic approach. It also highlights the importance of recognizing cognitive biases, such as premature diagnostic closure, that can hinder accurate diagnosis.", "authors": ["Phan Tina C L", "Blondeau-Lecomte Esther", "Jackson Christopher D"], "journal": "Journal of community hospital internal medicine perspectives", "entry_date": "2025/08/04 06:24", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40757225/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Medicine, University of Pennsylvania, Philadelphia, PA, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "40756927", "title": "Multidisciplinary Management of Aggressive Giant Cell Tumour of the Mandible Using Denosumab, Virtual Surgical Planning, and Patient-Specific Implants: A Case Report with Myasthenia Gravis Considerations.", "abstract": "INTRODUCTION: This report describes the management of an aggressive mandibular giant cell tumour (GCT) in a 59-year-old male with comorbid myasthenia gravis (MG).\nCASE REPORT: A multidisciplinary approach incorporating neoadjuvant Denosumab, virtual surgical planning, and patient-specific implants enabled precise tumour resection and reconstruction while minimising anaesthesia-related risks.\nRESULTS AND CONCLUSION: The use of advanced techniques significantly reduced surgical time and enhanced functional and aesthetic outcomes. This case highlights the feasibility and effectiveness of integrating modern chemotherapeutics and digital technologies in surgically managing complex maxillofacial tumours, particularly in patients with high perioperative risk due to systemic conditions like MG.", "authors": ["S Moorthy Raghav", "Balaraman Kannan", "Thangaraju Sunilkumar", "Ramani Vimalambiga", "R Bhat Keerthana", "Venkatramani Hari", "Shanmuganathan Raja Sabapathy"], "journal": "Journal of maxillofacial and oral surgery", "entry_date": "2025/08/04 06:20", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40756927/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Plastic, Hand and Microsurgery, Ganga Medical Centre and Hospital, Coimbatore, 641043 India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40755994", "title": "A Rare Case of Chronic Lymphocytic Leukemia Complicated by Myasthenia Gravis.", "abstract": "INTRODUCTION: About 10-25 % of chronic lymphocytic leukemia (CLL) patients experience complications related to autoimmune activity. Although less common, non-hematological autoimmune manifestations have been observed. Myasthenia gravis (MG) is rarely found in association with CLL. Since 1967, only 27 publications have reported the association between CLL and MG, encompassing just 15 cases. Our case is particularly notable for the refractory nature of the patient's MG.\nCASE PRESENTATION: A 56-year-old male with Rai Stage II CLL and myasthenia gravis presented to the emergency department with respiratory distress, dysphagia, and weakness. He was admitted for treatment with intravenous immune globulin, pyridostigmine, and intravenous solumedrol. Notably, the patient was diagnosed with CLL approximately three months prior and MG just one week before presentation. Despite aggressive treatment, the patient's myasthenia gravis symptoms persisted, prompting suspicion of CLL-related complications. Due to the patient's refractory myasthenia gravis, weekly rituximab 375 mg/m2 was initiated. He was given the first dose of rituximab during the hospital admission after which his dysphagia clinically improved.Outpatient management included obinutuzumab and Ventoclax for CLL control, resulting in gradual resolution of MG symptoms over a few months.\nDISCUSSION: Patients with myasthenia gravis (MG) generally do not require routine leukemia screening unless factors such as lymphadenopathy, splenomegaly, or refractory MG warrant further evaluation. Conversely, symptoms like ptosis in chronic lymphocytic leukemia (CLL) should prompt MG assessment. Early CLL treatment, as seen in this case, can resolve neurological symptoms and achieve remission, highlighting the need for a timely diagnosis and intervention to enhance patient outcomes.", "authors": ["Khan Eiraj", "Ilyas Rimal", "Shah Shivani", "Jiwani Rahim", "Samhouri Yazan", "Khan Cyrus"], "journal": "Journal of community hospital internal medicine perspectives", "entry_date": "2025/08/04 06:07", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40755994/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, Allegheny General Hospital, United States."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "40755985", "title": "Case With Refractory Myasthenia Gravis Caused by Pembrolizumab.", "abstract": "Nowadays, checkpoint inhibitors play a major role in the management of different types of cancers. However, we have seen variants of immune therapy-related adverse events, which usually are variables from fatigue, to neuropathy to severe devastating complications such as respiratory failure due to myasthenia gravis (MG), as we saw in our case. Our patient was started on pembrolizumab, and they developed severe respiratory failure attributed to MG after three weeks from treatment initiation. Also, the patient presented with myositis, mild myocarditis and hepatitis, which were all related to pembrolizumab.", "authors": ["Amer Bushra", "Hawshab Fatima D", "Hawshab Lateefah D", "Darwesh Khaled M"], "journal": "Journal of community hospital internal medicine perspectives", "entry_date": "2025/08/04 06:07", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40755985/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Berkshire Medical Center, Pittsfield, MA, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "40755780", "title": "CAR T-cells meet autoimmune neurological diseases: a new dawn for therapy.", "abstract": "Autoimmunity and autoimmune diseases arise when the immune system erroneously targets self-antigens leading to tissue damage. Consequently, immunomodulatory and mainly immunosuppressive drugs comprise the conventional treatment in conditions such as systemic lupus erythematosus, rheumatoid arthritis and multiple sclerosis. However, many of these agents often fall short of providing a cure and have a limit on symptom management. This underscores the urgent need for even more advanced therapies for patients to constrain progressive disability. Therefore, currently, researchers explore the potential of chimeric antigen receptor (CAR) T-cell therapy for autoimmune diseases considering its success in cancer treatment and specifically in hematological malignancies. This review will examine recent advancements in CAR T-cell therapy for autoimmune disorders, highlighting how CAR T cells can be engineered to precisely target and eliminate autoreactive immune cells that drive these debilitating diseases, particularly those affecting the nervous system such as Multiple sclerosis, Myasthenia gravis, Neuromyelitis optica, Stiff-person syndrome, Autoimmune encephalitis, MOG-antibody disease and Chronic inflammatory demyelinating polyneuropathy. Also, through an analysis of preclinical and clinical data, we will assess the efficacy, safety, potential side effects and limitations of these innovative therapies. Lastly, we will underline the transformative potential of CAR T-cells in Autoimmune Neurology, offering a promising new hope for treatment where conventional therapies have failed.", "authors": ["Chinas Nikolaos A", "Alexopoulos Harry"], "journal": "Frontiers in immunology", "entry_date": "2025/08/04 06:05", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40755780/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Cell Biology and Biophysics, Faculty of Biology, National and Kapodistrian University of Athens, Athens, Greece."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40755069", "title": "Improvement in Patient-Reported Symptoms of Generalised Myasthenia Gravis With Rozanolixizumab in the Randomised Phase 3 MycarinG Study Using the MG Symptoms PRO.", "abstract": "BACKGROUND: In the Phase 3 MycarinG study (NCT03971422), rozanolixizumab improved myasthenia gravis (MG)-specific outcomes versus placebo in patients with generalised MG, including those measured by the five independent MG Symptoms patient-reported outcome (PRO) scales: Muscle Weakness Fatigability (MWF), Physical Fatigue (PF) and Bulbar Muscle Weakness (BMW) as secondary endpoints and Ocular Muscle Weakness and Respiratory Muscle Weakness (exploratory endpoints). This research aimed to provide further insights into these improvements.\nMETHODS: Post hoc analyses evaluated correlation (Pearson coefficient) between MG Symptoms PRO and subdomain scores of MG Activities of Daily Living (MG-ADL) and Quantitative MG (QMG) at baseline. Proportions of responders reaching clinically meaningful thresholds and analyses at the item level (observed mean change and Rasch modelling of predicted change from baseline) are reported for MWF, PF, and BMW with rozanolixizumab versus placebo at Day 43.\nRESULTS: Correlation coefficients between MG Symptoms PRO and MG-ADL were strong (≥ 0.7) for ocular and bulbar scores and moderate (0.5 to < 0.7) for other scores. Correlations with clinician-assessed QMG scores were generally weak (< 0.5). For MWF, PF, and BMW, greater proportions of responders were observed with rozanolixizumab 7 mg/kg (46.9%, 31.3% and 26.6%, respectively) or 10 mg/kg (56.5%, 48.4% and 32.3%) versus placebo (28.1%, 26.6% and 10.9%). Item-level analyses demonstrated rozanolixizumab benefit at a symptom-specific level.\nDISCUSSION: MG Symptoms PRO scales correlate well with concepts in MG-ADL while assessing additional concepts, such as PF and MWF. Results from the MG Symptoms PRO in MycarinG reflected improvements from baseline in patient-relevant symptoms, including fatigue, with rozanolixizumab.", "authors": ["Kaminski Henry J", "Antozzi Carlo", "Habib Ali A", "Pascuzzi Robert M", "Sacconi Sabrina", "Utsugisawa Kimiaki", "Vissing John", "Regnault Antoine", "Hareendran Asha", "Grimson Fiona", "Tarancón Thaïs", "Bril Vera"], "journal": "European journal of neurology", "entry_date": "2025/08/04 03:23", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40755069/", "pub_types": ["Journal Article", "Randomized Controlled Trial", "Clinical Trial, Phase III", "Multicenter Study"], "affiliations": ["Department of Neurology & Rehabilitation Medicine, George Washington University, Washington, District of Columbia, USA."], "china_related": false, "study_types": ["RCT"], "evidence_level": "II", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40751639", "title": "Salbutamol in the management of congenital myasthenic syndrome (CMS) and associated IgA and IgG Deficiency.", "abstract": "A 13-month-old girl, diagnosed with congenital myasthenic syndrome due to CHRNE and GMPPB mutation, presented with involuntary movement of muscles and ptosis along with lethargy, having a poor response to Pyridostigmine and improved symptoms with Salbutamol. This case report highlights the significance of genetic testing and the clinical response to Salbutamol, emphasising its potential role in the continued treatment of CMS and providing a more economical and feasible therapeutic approach.", "authors": ["Abdullah Abia", "Ashraf Sana", "Chand Prem"], "journal": "JPMA. The Journal of the Pakistan Medical Association", "entry_date": "2025/08/02 08:44", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40751639/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["3rd Year MBBS Student, Aga Khan University Hospital, Karachi, Pakistan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40751533", "title": "Bilateral Mydriasis in a Post-parotidectomy Patient: A Case Report.", "abstract": "Anticholinergic agents, such as atropine and glycopyrrolate, are commonly utilized during anesthesia for their effects on secretion reduction and vagal activity. However, substantial dosages can induce mydriasis, which poses diagnostic challenges, particularly in head and neck surgeries. Despite their clinical relevance, limited studies explore these effects. A 35-year-old female presented with a left parotid mass and scheduled for a left superficial parotidectomy. Preoperatively, the patient exhibited normal ocular and neurological function. Postoperatively, fine bilateral ptosis, predominantly on the left side, and bilateral unresponsive mydriasis were noted. Anticholinergic-induced pupillary changes may mimic neurological pathology, underscoring the necessity for meticulous postoperative evaluation and awareness among clinicians.", "authors": ["Daneshi Ahmad", "Mohebbi Saleh", "Shemshadi Milad", "Ghanbari Hadi"], "journal": "Archives of Iranian medicine", "entry_date": "2025/08/02 06:28", "pub_date": "2025-06-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40751533/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Head & Neck Research Department, Hazrat Rasoul Hospital, Iran University of Medical Sciences, Tehran, Iran."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40748491", "title": "Immune Modulatory Effects of PD-1/PD-L1 in Myasthenia Gravis: Insights From Peripheral Blood Mononuclear Cell Analysis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disease characterized by the production of antibodies targeting acetylcholine receptor (AChR)-associated proteins. The disorder involves various immune cells, including T cells, B cells, and dendritic cells (DCs). Programmed cell death protein 1 (PD-1) is one of the immune checkpoints and plays a crucial role in regulating immune cell activation and cell death. PD-L1, the ligand of PD-1, is critical for immune suppression through the transmission of inhibitory signals. These molecules are implicated in the pathogenesis of MG, prompting further investigation into the expression and functional roles of PD-1/PD-L1 in this disease. To investigate the role of PD-1/PD-L1 in MG pathogenesis, we collected peripheral blood mononuclear cells (PBMCs) from MG patients and analyzed PD-1/PD-L1 expression in various immune cells using flow cytometry (FACs). Our findings revealed that PD-1/PD-L1 expression was elevated in PBMCs from MG patients compared to healthy controls. We conducted a correlation analysis to examine the relationship between PD-1/PD-L1 expression and MG, based on measurements of anti-AChR-IgG levels, MG-specific cytokines, and routine blood tests. Our results showed that PD-1 expression in CD8+ T cells and PD-L1 expression in DCs were positively correlated with anti-AChR-IgG levels in MG serum. Additionally, PD-1/PD-L1 expression was correlated with parts of associated cytokines. Furthermore, PD-1 expression in B cells was positively correlated with lymphocyte counts in the peripheral blood. Moreover, exogenous recombinant human PD-L1 protein (rhPDL1) was found to suppress the expression of IL-1β and IL-4. Our findings underscore the potential therapeutic role of PD-1/PD-L1 agonists in the treatment of MG.", "authors": ["Li Jianing", "Liu Xinyue", "Qi Feiteng", "Ren Yan", "Zhang Yuanting", "Shen Yaoyang", "Liu Hua", "Wang Yixuan", "Zheng Rou", "Ou Yangxiang", "Wang Geng", "Li Na"], "journal": "FASEB journal : official publication of the Federation of American Societies for Experimental Biology", "entry_date": "2025/08/01 11:23", "pub_date": "2025-08-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40748491/", "pub_types": ["Journal Article"], "affiliations": ["Health Science Center, Ningbo University, Ningbo, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40746607", "title": "Immune checkpoint inhibitor-associated autoimmune encephalitis and other neurological immune-mediated adverse events: a pharmacovigilance study using the FAERS and JADER.", "abstract": "BACKGROUND: Immune checkpoint inhibitor (ICI)-associated neurological immune-related adverse events (NAEs) are rare but serious side effects, of which autoimmune encephalitis (AIE) is a potentially fatal central nervous system disorder requiring more attention.\nMETHODS: We performed a retrospective disproportionality analysis of NAE reports in the FDA Adverse Event Reporting System (FAERS) and the Japanese Adverse Event Reporting Database (JADER) from 2004 to 2024, utilizing reporting odds ratio (ROR), proportional reporting ratio (PRR), the Bayesian confidence propagation neural network BCPNN, and the multi-item gamma Poisson shrinker (MGPS) for signal detection.\nRESULTS: In total, 3,999 reports of ICI-associated NAEs were identified from the FAERS database, of which 1,998 reports were AIE. 1,558,251 reports of AEs were collected from the JADER database, which contained 890 AIE reports. ICIs, including pembrolizumab, nivolumab, atezolizumab, ipilimumab, and durvalumab, were identified among the top 30 agents in both databases, demonstrating significant signals across all 4 algorithms. Except for noninfectious myelitis, acute disseminated encephalomyelitis, and multiple sclerosis, positive signals were detected in all other preferred terms (PTs). These NAEs accounted for 23.7% of total mortality, with myasthenia gravis (MG) exhibiting the highest mortality rate at 30.63%. Specific PTs, such as aseptic meningitis, AIE, chronic inflammatory demyelinating polyradiculoneuropathy, Guillain-Barré syndrome, MG, myelitis, and immune-related myopathy, were associated with the severity of outcomes, showing significant statistical differences between severe and non-severe cases (p < 0.05).\nCONCLUSION: Our study found a notable correlation between ICIs and AIE and other specific NAEs, highlighting the demographic characteristics, time to onset, and disease severity of ICI-induced NAEs, thereby facilitating the timely recognition and treatment of these ICI therapy-related complications.", "authors": ["Di Xiaomeng", "Shi Xiaohong", "Gai Feng", "Wang Jiawei"], "journal": "Frontiers in oncology", "entry_date": "2025/08/01 05:00", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40746607/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Beijing Tongren Hospital, Capital Medical University, Beijing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.3, "journal_quartile": "3区"}, {"pmid": "40745672", "title": "The Diagnostic Yield of Antiacetylcholine Receptor Antibodies Versus Antimuscle Kinase Antibodies in Ocular Myasthenia Gravis: A Meta-Analysis.", "abstract": "BACKGROUND: Ocular myasthenia gravis (OMG) is an autoimmune disease characterized by autoantibodies targeting postsynaptic proteins at the neuromuscular junction, leading to weakness and fatigability of the levator palpebrae superioris, orbicularis oculi and extraocular muscles. Although OMG is primarily a clinical diagnosis, serological antibody testing, predominantly acetylcholine receptor (AChR) antibodies, is usually performed. The clinical utility of muscle-specific kinase (MuSK) antibodies is less well established in OMG. This meta-analysis evaluates the use of anti-AChR and anti-MuSK in patients with OMG and the relative costs of simultaneous vs sequential testing.\nMETHODS: Studies were extracted from Cumulative Index to Nursing and Allied Health Literature (CINAHL), Embase (Ovid), Medline (Ovid), and additional gray literature. A systematic review was conducted using Covidence with 2 independent reviewers for study selection and data extraction. The meta-analysis was conducted with R version 4.4.1 on RStudio, and the meta package. Depending on the level of heterogeneity, either a fixed-effects or random-effects model was used to pool the data. Funnel plots were used to assess publication bias.\nRESULTS: The pooled analysis of 44 studies (n = 4,937 patients with OMG) revealed 59% (95% confidence interval [CI]: 52%-66%) positivity for anti-AChR, whereas the pooled analysis of 34 studies with (n = 3,380) showed 5% (95% CI: 2%-9%) positivity for anti-MuSK. From 62 studies (n = 5,180), 4 patients (0.1%) were doubly seropositive for anti-AChR and anti-MuSK. In patients with OMG positive for AChR antibodies, 5 studies (n = 527) reported a thymoma prevalence of 35% (95% CI: 3%-90%), underscoring the clinical value of anti-AChR testing. Four studies (n= 259) showed that anti-AChR positive patients had a 1.82 (95% CI: 1.15-2.88) times greater risk of progressing from OMG to generalized myasthenia gravis.\nCONCLUSIONS: Almost two-thirds (59%) of the patients with OMG tested positive for AChR antibodies, but MuSK antibodies were only detected in 5% of patients. Positivity for anti-AChR in OMG was associated with a worse prognosis, including a higher prevalence of thymomas and an increased risk of disease generalization. Given the relatively low prevalence of anti-MuSK and the higher cost of anti-MuSK testing, clinicians could consider a stepwise approach to the serological diagnosis of OMG, where anti-MuSK is ordered only if the initial anti-AChR returns negative.", "authors": ["Tran Edward", "Nair Gautham", "Bursztyn Lulu L C D", "Fraser J Alexander", "Ing Edsel B"], "journal": "Journal of neuro-ophthalmology : the official journal of the North American Neuro-Ophthalmology Society", "entry_date": "2025/08/01 00:48", "pub_date": "2026-06-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40745672/", "pub_types": ["Journal Article", "Meta-Analysis", "Systematic Review", "Review"], "affiliations": ["Western University (ET, GN), Schulich School of Medicine, London, Canada; Departments of Ophthalmology (LLCDB, JAF), and Clinical Neurological Sciences (LLCDB, JAF), Western University, London, Canada; Department of Ophthalmology and Visual Sciences (EI), University of Alberta, Edmonton, Canada; and Department of Ophthalmology and Vision Sciences (EI), University of Toronto, Toronto, Canada."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I"}, {"pmid": "40745651", "title": "Overlap of limited cutaneous systemic sclerosis with ocular myasthenia gravis- report of a case and a brief review of literature.", "abstract": "A 39-year-old woman with a 4-year history of limited cutaneous systemic sclerosis (lcSSc) and no prior exposure to D-penicillamine presented with bilateral fluctuating ptosis of 1 week duration. On evaluation, she was found to have elevated acetylcholine receptor antibody levels and a positive neostigmine test confirming the diagnosis of ocular myasthenia gravis (MG). The patient was treated with oral prednisolone and pyridostigmine resulting in significant improvement within 2 weeks. The co-occurrence of systemic sclerosis (SSc) and MG is rare and when such an association is seen, it is usually seen in the background of D-Penicillamine therapy for SSc. The presence of fluctuating ptosis in SSc is a valuable clinical clue to suspect co-existence of neuromuscular junction disorder like MG.", "authors": ["Gangadharan Harikrishnan", "Babu Sandra Pulickal", "Kumar Rohit Ram", "Nair Aditya", "Ps Manjit", "George Jacob"], "journal": "The journal of the Royal College of Physicians of Edinburgh", "entry_date": "2025/08/01 00:42", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40745651/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Rheumatology, Government Medical College Kottayam, Kottayam, KL, India."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.4, "journal_quartile": "3区"}, {"pmid": "40743586", "title": "Is the decrement pattern in myasthenia gravis due to muscle-specific kinase antibodies different to that due to acetylcholine receptor antibodies?", "abstract": "OBJECTIVE: A decrement on repetitive nerve stimulation (RNS) is essential for the diagnosis of myasthenia gravis (MG). The decrement pattern is typically \"U-shaped\" in MG caused by acetylcholine receptor antibodies (AChR-MG) but is less well described in MG caused by muscle-specific kinase antibodies (MuSK-MG). The aim of this study was to investigate RNS abnormalities in MuSK-MG, and to describe the differences in the decrement pattern as compared to AChR-MG.\nMETHODS: This retrospective case-control study included patients diagnosed with generalized MuSK-MG, compared to a control group of generalized AChR-MG. The five most frequently explored nerve-muscle pairs in RNS were analyzed: radial-anconeus, fibular nerve-tibialis anterior (TA), XI-trapezius, XII/V-submental complex (SMC), and VII-orbicularis oculi (OO). Decreased amplitude between the 1st and 4th responses (early decrement) and the late/early ratio were calculated (late/early ratio <100 %=U-shaped pattern, and ≥100 %=progressive pattern).\nRESULTS: For MuSK-MG, 25 patients were included and compared to 35 AChR-MG patients. An early decrement was present in 38/83 (54.2 %) muscles in MuSK-MG compared to 88/130 (67.7 %) muscles in AChR-MG; and in MuSK-MG was less frequently found in anconeus (4/22 [18.2 %] vs 27/31 [87.1 %], p < 0.001) and in TA (0/12 [0.0 %] vs 9/30 [30 %], p = 0.04). A progressive pattern was more frequent in MuSK-MG (19/38 [50.0 %] of muscles vs 15/88 [17.0 %], p < 0.001). The late/early ratio was greater in MuSK-MG (median value was 98.4 % [IQR, 86.8-106.8] vs 89.7 % [IQR, 79.5-96.5]). The first response with minimal amplitude during the RNS (Amin) was significantly different between the two groups (p < 0.001).\nCONCLUSION: Compared to AChR-MG, RNS in MuSK-MG showed fewer affected muscles, with less frequent involvement of anconeus and TA in particular; and a more progressive decrement pattern.", "authors": ["Pegat Antoine", "Gavoille Antoine", "Bonjour Maxime", "Cluse Florent", "Moussy Martin", "Svahn Juliette", "Kouton Ludivine", "Grapperon Aude-Marie", "Verschueren Annie", "Delmont Emilien", "Salort-Campana Emmanuelle", "Attarian Shahram", "Fortanier Etienne", "Bouhour Françoise"], "journal": "Neurophysiologie clinique = Clinical neurophysiology", "entry_date": "2025/07/31 18:01", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40743586/", "pub_types": ["Journal Article"], "affiliations": ["Service ENMG et de pathologies neuromusculaires, centre de référence des maladies neuromusculaires PACA-Réunion-Rhône Alpes, Hôpital Neurologique P. Wertheimer, Hospices Civils de Lyon, France. Electronic address: antoine.pegat@chu-lyon.fr."], "china_related": false, "study_types": ["Case-Control"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40743488", "title": "Unknown Immunoregulatory Effects of FcRn Inhibition by Efgartigimod in Myasthenia Gravis: A New Mechanism of Action Beyond IgG Reduction.", "abstract": "BACKGROUND AND OBJECTIVES: Efgartigimod (EFG), a biological drug targeting the IgG recycling neonatal Fc receptor (FcRn), leads to clinical improvements in patients affected by myasthenia gravis (MG), a prototypic autoantibody (Ab)-mediated autoimmune disease affecting neuromuscular junction. Because FcRn is a multifunctional protein expressed in different immune system cells, including B cells, we investigated whether FcRn blockade by EFG may have further immunologic effects, other than IgG reduction, in patients with MG.\nMETHODS: Anti-acetylcholine receptor Ab-positive (AChR-MG) patients were treated with EFG according to the GENERATIVE protocol. Clinical evaluation, IgG and autoAb quantification, and circulating T-cell and B-cell subpopulation analyses by flow cytometry were performed at different time points. The expression of regulatory plasma cell-related candidate genes (CD38, lymphocyte-activation gene 3 [LAG3], IL-12a, Ebi3) was assessed by real-time PCR in peripheral blood mononuclear cells (PBMCs) from patients on treatment and in PBMCs either untreated or in vitro treated with an EFG-mimicking anti-FcRn monoclonal Ab (mAb) or with EFG (Vyvgart).\nRESULTS: A significantly increased percentage of CD19+/CD27+ memory B cells and CD27+/CD138+ plasma cells was observed at the end of EFG treatment cycle 1 and cycle 2 in patients with AChR-MG. Plasma cell increase, maintained up to cycle 3, significantly correlated with Quantitative Myasthenia Gravis score improvement. Moreover, PBMCs from EFG-treated patients showed overexpression of CD38, LAG3, and IL-12a genes, suggesting EFG's ability to induce non-pathogenic regulatory plasma cells. This ability was confirmed in vitro, because anti-FcRn mAb-treated and EFG-treated PBMCs displayed an up-regulation of CD38 and LAG3 compared with untreated cells.\nDISCUSSION: Our findings indicate an unknown immunoregulatory action of EFG in patients with AChR-MG, by unraveling a drug effect on B-cell differentiation, and suggest the induction of regulatory plasma cells as a further mechanism, beyond IgG reduction, associated with clinical improvement. A deep understanding of the immunologic effects of EFG can help to optimize its usage over time in individual patients and disclose biomarkers suitable for monitoring the long-term patient-specific response.", "authors": ["Tarasco Maria Cristina", "Rinaldi Elena", "Frangiamore Rita", "Vanoli Fiammetta", "Berni Alessia", "Iacomino Nicola", "Canciello Amalia", "Andreetta Francesca", "Ciusani Emilio", "Bonanno Silvia", "Maggi Lorenzo", "Baggi Fulvio", "Mantegazza Renato", "Antozzi Carlo", "Cavalcante Paola"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/07/31 16:03", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40743488/", "pub_types": ["Journal Article"], "affiliations": ["Neurology 4-Neuroimmunology and Neuromuscular Diseases, Fondazione IRCCS Istituto Neurologico Carlo Besta, Milan, Italy."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "40735819", "title": "Evaluating the Educational Value and Content Quality of YouTube Videos on Myasthenia Gravis.", "abstract": "INTRODUCTION/AIMS: Although numerous YouTube videos on myasthenia gravis (MG) are available, the educational quality and comprehensiveness of this digital health information have not been assessed. This study addresses that gap using structured scoring tools to evaluate informational value for both patients and healthcare professionals.\nMETHODS: A systematic search on December 3, 2024, retrieved the top 50 English-language YouTube videos on MG. The videos were assessed using the modified DISCERN scale (1-5), Global Quality Scale (GQS; 1-5), and a custom comprehensiveness checklist (0-5). Descriptive, comparative, and inter-rater analyses were performed. Group comparisons used the Kruskal-Wallis test; associations were analyzed with Spearman's correlation.\nRESULTS: Substantial agreement was observed (κ = 0.79). The median video duration was 8 min with a median of 53,459 views. The mean DISCERN score was 3.18 (±1.06), indicating moderate quality of treatment-related information; the mean GQS score was 2.88 (±1.02), reflecting moderate overall usefulness and coherence; and the mean comprehensiveness score was 2.78 (±1.11), showing moderate coverage of educational content. Higher comprehensiveness was positively associated with longer duration, more likes, and professional orientation (p < 0.05). The educational content varied: symptoms (84%) and treatments (70%) were commonly covered, whereas rehabilitation (8%) and long-term management (10%) were rarely included.\nDISCUSSION: Although the mean scores indicated moderate quality, significant variability in educational depth was observed. The limited representation of rehabilitation and chronic care content suggests the need for more comprehensive and balanced digital resources on MG.", "authors": ["Meral Hatice Betigül", "Aliyeva Tehran", "Toplutaş Eren"], "journal": "Muscle & nerve", "entry_date": "2025/07/30 05:22", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40735819/", "pub_types": ["Journal Article"], "affiliations": ["Department of Physical Medicine and Rehabilitation, Faculty of Medicine, Istanbul Medipol University, Istanbul, Turkey."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40734191", "title": "Myasthenia gravis complicated by Graves' disease: a case report.", "abstract": "INTRODUCTION: Myasthenia gravis is a neuromuscular autoimmune condition characterized by the presence of antibodies against acetylcholine receptors. It may present as a generalized disorder or remain limited to specific muscle groups. Myasthenia gravis can occur independently or alongside other autoimmune conditions, including Hashimoto's thyroiditis and Graves' disease. Although the co-occurrence of these disorders is recognized, it is an extremely rare clinical phenomenon.\nCASE PRESENTATION: A 20-year-old woman of Muganda ethnicity, with a 2-year history of Graves' disease confirmed by thyroid scintigraphy, developed a myasthenic syndrome leading to acute respiratory failure. Her condition improved with the administration of Prostigmine. Further investigations, including electrophysiological studies and immunological tests, confirmed a diagnosis of myasthenia gravis. The patient demonstrated a positive response to medical therapy.\nCONCLUSION: This case highlights the importance of recognizing the rare association between myasthenia gravis and Graves' disease. Accurate diagnosis and effective treatment require a coordinated, multidisciplinary approach, particularly given the challenges posed by overlapping symptoms and the exacerbating effects of hyperthyroidism on myasthenia gravis.", "authors": ["Kamabu Larrey Kasereka", "Oboth Ronald", "Kataka Louange Maha", "Baruani Albert Yemba", "Lekuya Hervé Monka", "Kangitsi Charles Kahindo"], "journal": "Journal of medical case reports", "entry_date": "2025/07/30 01:20", "pub_date": "2025-07-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40734191/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Faculty of Medicine, Neurosurgery Division, Catholic University of Graben, P.O. Box 29, Butembo, Democratic Republic of the Congo. kamabularry@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40726281", "title": "Beyond the Surface: Investigating the Potential Mechanisms of Non-Motor Symptoms in Myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder affecting the neuromuscular junction (NMJ), driven by T cells, mediated by B cells, and dependent on autoantibodies. In addition to the typical motor symptoms of fluctuating weakness, the non-motor symptoms are also prevalent among MG patients. This review aims to present the non-motor symptoms of MG and their potential pathogenesis, hoping to contribute to personalized diagnosis and treatment.\nMETHODS: This review elaborates the non-motor symptoms of MG and systematically detail, for the first time, their potential pathogenic mechanisms, offering a new perspective for clinical evaluation.\nRESULTS: The non-motor symptoms of MG include autonomic disorders (urinary, gastrointestinal, cardiovascular and ocular dysfunction), sensory disability (olfactory abnormalities, gustatory reduction and headaches), cognitive impairment, sleep disturbances, psychological problems (depression and anxiety), and TAMG-associated specific syndromes. Due to their insidious onset and lack of awareness, these symptoms are often overlooked. We review the non-motor symptoms of MG and first provide a systematic and detailed discussion on their potential mechanisms, including the influence of MG-specific antibodies (cross-reactivity of AChR-Ab, expression of MuSK-Ab, and striational antibodies at related functional sites), dysregulation of inflammatory factors and immune cells, collateral effects of motor symptoms, impacts of MG comorbidities, and paraneoplastic syndromes caused by thymoma.\nCONCLUSION: Non-motor symptoms are common in MG patients. Given a series of potential mechanisms probably involved exploring these non-motor symptoms will not only enhance our understanding of MG but also aid in diagnosis and the development of precise, personalized treatments, ultimately improving the overall life quality of patients.", "authors": ["Wang Benqiao", "Liu Dan", "Yang Yingying", "Zhu Ruixia"], "journal": "European journal of neurology", "entry_date": "2025/07/29 04:08", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40726281/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of China Medical University, Shenyang, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40725661", "title": "Differential Scanning Calorimetry as a Monitoring Tool for the Effectiveness of Therapeutic Plasma Exchange in Anti-AChR Myasthenia Gravis, Anti-MuSK Myasthenia Gravis, and Myasthenic Syndrome: A Case Series.", "abstract": "Background/Objectives: Myasthenia Gravis (MG) and myasthenic syndrome (MSyn) are neurological disorders induced by different types of autoantibodies, characterized by generalized muscle weakness, sometimes involving the respiratory muscles and necessitating ventilatory support. One therapeutic option for severe Myasthenia Gravis (MG) is total plasma exchange (TPE). This procedure reduces the concentration of autoantibodies by extracting the patient's plasma and replacing it with donor plasma. The TPE efficacy varies among different types of MG, and patient response to TPE is evaluated solely through clinical markers, such as muscle strength. So far, no laboratory method is available for monitoring TPE treatment progress. Objective: In this study, we aimed to determine whether differential scanning calorimetry (DSC) of blood plasma from myasthenic patients is an appropriate tool to monitor and evaluate their condition and the TPE effect. Methods: We performed DSC prior to and after TPE course on blood plasma from three patients with different types of MG: Case 1. Patient with Acetylcholine Receptor Myasthenia Gravis (AChR MG); Case 2. Patient with Muscle-specific tyrosine kinase Myasthenia Gravis (MuSK MG); Case 3. Patient with Myasthenic syndrome (MSyn). Results: DSC thermogram examination revealed increased plasma protein fractions, primarily immunoglobulins (IG), as well as to some extent fibrinogen, relative to a suppressed serum albumin fraction. Successive TPE procedures resulted in IG fraction decline in AChR MG (Case 1) and MSyn (Case 3), and upsurge of the IG fraction in MuSK MG (Case 2). These findings aligned with the clinical presentation of all three cases. Conclusions: DSC revealed distinct, very significant differences in the heat capacity profiles of blood plasma from MG patients relative to healthy controls, as well as strong TPE influence on the plasma thermal behavior. DSC showed promise as a reliable and informative technique for the monitoring of myasthenia and TPE effects across diverse myasthenic patient populations. Further research is needed to confirm and expand on these findings.", "authors": ["Ilieva Viktoria", "Tenchov Boris", "Virovska Daniela", "Nencheva Denitsa", "Kalayanov Maksim", "Farfarov Alexandar", "Yamakova Yordanka", "Abarova Silviya"], "journal": "Journal of clinical medicine", "entry_date": "2025/07/29 01:17", "pub_date": "2025-07-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40725661/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Anesthesiology and Intensive Care, University Hospital \"Alexandrovska\", Georgi Sofiiski Str. No. 1, 1000 Sofia, Bulgaria."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "40721896", "title": "Clinicopathological profiling and prognosis of idiopathic inflammatory myopathy overlapping with myasthenia gravis: a retrospective cohort study.", "abstract": "BACKGROUND: The clinicopathological spectrum of idiopathic inflammatory myopathy (IIM) overlapping with myasthenia gravis (MG) remains poorly defined. This study aimed to investigate the clinicopathological characteristics and outcomes of patients with IIM-MG to establish early diagnostic clues for the timely recognition of this unique subgroup and optimize therapeutic strategies.\nMETHODS: The clinical, serological, and histopathological data of 682 consecutive patients with IIM diagnosed between 2016 and 2024 were retrospectively analyzed. Seven (1.03%) IIM-MG cases were identified.\nRESULTS: Six patients exhibited simultaneous onset of IIM and MG, while one developed MG 2 years post-IIM diagnosis. Two patients were classified as dermatomyositis, and the other five as necrotizing autoimmune myopathy. Notably, four patients experienced dyspnea without interstitial lung disease, of whom three required mechanical ventilation. Three patients had thymomas, two had ocular symptoms and only one had myocarditis. The mean creatine kinase (CK) level was 887.69 ± 247.37 U/L. None of the patients tested positive for myositis-specific antibodies (MSAs), while all were positive for the anti-acetylcholine receptor antibody (AChR-Ab). Muscle biopsies showed CD3+ T cell infiltration and major histocompatibility complex-I expression in all cases. All patients were treated with glucocorticoids plus other immunotherapies. Five patients showed marked improvement, of whom one experienced relapse, and two patients died within 3 months due to severe infection.\nCONCLUSIONS: IIM-MG is a rare overlap syndrome characterized by dyspnea, mild CK elevation, anti-AChR-Ab seropositivity, and T-cell-mediated damage in muscle. Early MG screening in MSA-negative patients with IIM is critical. Although immunotherapy shows efficacy, infection-related mortality remains a concern.", "authors": ["Hou Ying", "Zhao Bing", "Zheng Jinfan", "Dai Tingjun", "Zhang Lining", "Li Wei", "Zhao Yuying", "Yan Chuanzhu", "Wang Qinzhou"], "journal": "Journal of neurology", "entry_date": "2025/07/28 23:54", "pub_date": "2025-07-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40721896/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Shandong Key Laboratory of Mitochondrial Medicine and Rare Diseases, Research Institute of Neuromuscular and Neurodegenerative Diseases, Qilu Hospital of Shandong University, No. 107 West Wenhua Road, Jinan, 250012, Shandong, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "40721277", "title": "Severe cutaneous adverse reactions and risk of autoimmune disease, including psoriasis and inflammatory bowel disease: a cohort study.", "abstract": "BACKGROUND: Limited evidence exists about the association between autoimmune disease risk and patients with severe cutaneous adverse reactions (SCARs).\nOBJECTIVES: To estimate the risks of a set of incident autoimmune outcomes in patients with SCARs.\nMETHODS: We used the Taiwan National Health Insurance Research Database to build a cohort of 21 170 eligible individuals with SCARs and a matched non-SCARs cohort comprising 211 700 individuals. We analysed the autoimmune outcomes of interest through a Cox proportional hazards model.\nRESULTS: During a mean follow-up period of 5.2 years (SD 2.6 years), 459 of 21 170 (2.2%) individuals with and 299 of 211 700 (0.1%) without SCARs developed incident autoimmune disease, respectively. The incidence rate of any autoimmune disease was 418.5 events per 100 000 person-years among patients with SCARs and 27.0 events per 100 000 person-years among those without SCARs and the adjusted hazard ratio of any autoimmune disease was 15.5 (95% confidence interval 13.4-17.9). Furthermore, there was increased risk of an array of incident autoimmune disease, including systemic vasculitis, type 1 diabetes mellitus, Henoch-Schönlein purpura, primary Sjögren syndrome, Addison disease, systemic lupus erythematosus, systemic sclerosis, inflammatory bowel disease (ulcerative colitis and Crohn disease), myasthenia gravis, Hashimoto thyroiditis, psoriasis, rheumatoid arthritis, ankylosing spondylitis, Graves disease and autoimmune haemolytic anaemia.\nCONCLUSIONS: This study suggests that patients with SCARs have a higher risk of developing autoimmune diseases than patients without SCARs. Further research investigating the underlying mechanisms is warranted. Physicians should be attentive to potential sequelae that may arise following SCARs resolution during long-term follow-up.", "authors": ["Lin Tzu-Min", "Chang Yu-Sheng", "Shen Yu-Chuan", "Hsu Hui-Ching", "Chen Wei-Sheng", "Lee Hsiang-Yen", "Kuo Tzu-Tung", "Chen Shu-Chuan", "Chen Jin-Hua", "Chang Chi-Ching"], "journal": "Clinical and experimental dermatology", "entry_date": "2025/07/28 21:03", "pub_date": "2025-11-25", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40721277/", "pub_types": ["Journal Article"], "affiliations": ["Division of Allergy, Immunology, and Rheumatology, Department of Internal Medicine, School of Medicine, College of Medicine, Taipei Medical University, Taipei City, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "4区"}, {"pmid": "40720448", "title": "Outcomes of myasthenia gravis patients admitted to the Intensive Care Unit: Experience from a tertiary care center in Saudi Arabia.", "abstract": "BACKGROUND: Myasthenia gravis is an autoimmune disorder that affects the neuromuscular junction resulting in muscle weakness and fatigue. The aim of this study was to investigate the indications for and frequency of intensive care unit admissions in people with myasthenia gravis in addition to exploring the clinical presentations and outcomes during their admission.\nMETHODS AND FINDINGS: This retrospective study included all adult patients diagnosed with myasthenia gravis who were admitted to the intensive care unit in a six year period. Twenty-four patients with a diagnosis of myasthenia gravis were included in this study, with a total of 60 admissions. The median age at their first admission was 45 years with female predominance. Majority of the patients (87.5%) were acetylcholine antibody positive and 66.7% of patients had thymectomy. Myasthenic crisis was the most common reason for intensive care unit admission (63.3%). 80.5% of patients admitted with myasthenic crisis were treated with plasma exchange. During their admission, 45% of patients required mechanical ventilation. Complications during hospitalization were reported in 18.3% of patients, with mortality rate of 5% of all admissions.\nCONSLUSION: People with myasthenia gravis are commonly admitted to the intensive care unit due to myasthenic crises, however, there were minimal complications reported and a low mortality rate.", "authors": ["Attar Ahmed", "Alshaikh Hatoon", "Alharbi Ghadi", "Aletani Tala", "Alghamdi Sara", "Alzahrani Sarah", "Khojah Osama", "Alqthmi Rahma", "Althobaiti Abdulrahman", "Alaifan Thamer"], "journal": "PloS one", "entry_date": "2025/07/28 13:43", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40720448/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Ministry of the National Guard-Health Affairs, Jeddah, Saudi Arabia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40718253", "title": "Early Myasthenia Gravis Activities of Daily Living (MG-ADL) Response to Ravulizumab in Acetylcholine Receptor-Positive Generalized Myasthenia Gravis Refractory: A Case Report From Latin America.", "abstract": "This case report details the first use of ravulizumab in Chile for a patient with acetylcholine receptor (AChR)-positive myasthenia gravis (MG) who did not respond to rituximab (RTX). A 26-year-old female presented with progressive MG symptoms, including fatigue and bilateral ptosis. Despite conventional treatment and thymectomy, she experienced multiple myasthenic crises. Following the lack of response to RTX, ravulizumab was initiated, resulting in a significant improvement in the Myasthenia Gravis Activities of Daily Living (MG-ADL) score in less than two weeks. Ravulizumab, a monoclonal antibody that inhibits complement component C5, was approved for MG in 2022 and is being assessed for efficacy in neurological disorders. This report highlights its potential as a therapy for MG in the absence of robust local evidence, offering a novel therapeutic option for managing this debilitating condition.", "authors": ["Orellana Manuel", "Bustamante Gabriel"], "journal": "Cureus", "entry_date": "2025/07/28 05:00", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40718253/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Hospital Dr. Franco Ravera Zunino, Rancagua, CHL."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40718168", "title": "A Case of Isaacs Syndrome Developed After Thymectomy for Myasthenia Gravis.", "abstract": "A 54-year-old man was referred to our hospital due to calf pain and gait disturbance. Two years earlier, he had developed ptosis of the left eye. A routine health check conducted two years later revealed a thymoma with positive anti-acetylcholine receptor antibodies. He was diagnosed with myasthenia gravis and underwent thymectomy. Eight days after the surgery, he experienced involuntary calf muscle movements and pain, leading to worsening gait disturbance. Upon admission, he presented with cold toes, ptosis of the left eye, and continuous myokymia of both legs, which persisted during sleep. Laboratory tests revealed the presence of anti-contactin-associated protein 2 (anti-CASPR2) and anti-leucine-rich glioma-inactivated protein 1 (anti-LGI1) antibodies in the serum, along with myokymic discharges observed in electromyography. A diagnosis of Isaacs syndrome was made. The patient was treated with plasmapheresis and methylprednisolone pulse therapy, followed by intravenous immunoglobulin therapy, leading to the resolution of his symptoms. To our knowledge, this is the first reported case of Isaacs syndrome developing soon after thymectomy.", "authors": ["Sakaguchi Hiroka", "Tsutsui Shunsuke", "Aohara Kenta", "Tamura Akiko", "Itoh Yoshiaki"], "journal": "Cureus", "entry_date": "2025/07/28 04:59", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40718168/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Osaka Metropolitan University, Osaka, JPN."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40716765", "title": "Retraction of: Volrustomig/Rilvegostomig related \"triple M\"-myasthenia gravis and overlap syndrome.", "abstract": "", "authors": [], "journal": "Postgraduate medical journal", "entry_date": "2025/07/27 20:13", "pub_date": "2025-07-28", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40716765/", "pub_types": ["Journal Article", "Retraction Notice"], "affiliations": [], "china_related": false, "study_types": ["Comment"], "evidence_level": null, "journal_if": 2.7, "journal_quartile": "4区"}, {"pmid": "40714827", "title": "One Patient with 3 Antibody-Confirmed Neurological Autoimmune Syndromes: A Case Report and Review of the Literature.", "abstract": "BACKGROUND The occurrence of multiple autoimmune neurological disorders in one patient is rare. Here, we present the case of a woman who exhibited clinical features and antibody titers consistent with myasthenia gravis (MG), neuromyelitis optica (NMO), and anti-N-methyl-D-aspartate receptor (NMDAR) encephalitis. CASE REPORT A 37-year-old woman with a 10-year history of MG presented with a sudden loss of central vision in her right eye. Magnetic resonance imaging (MRI) revealed new enhancement of the right optic nerve, and additional cervical and thoracic spine scans showed continuous demyelination of the central cord. Given these findings, a primary demyelinating condition was suspected, and an NMO antibody test confirmed the diagnosis. Two years later, the patient developed significant behavioral changes, including neglecting her usual activities and displaying diminished responsiveness. She became mute and uncooperative with commands. Based on clinical suspicion of anti-NMDAR encephalitis, a comprehensive work-up revealed the presence of NMDAR antibodies, confirming the diagnosis. The patient was treated with plasma exchange, resulting in a marked improvement in her encephalopathy. CONCLUSIONS Over 12 years, this patient developed clinical manifestations of 3 distinct neurological autoimmune disorders. This case underscores the critical need for clinicians to remain alert to overlapping neurological conditions, enabling timely diagnoses and interventions that can help improve clinical outcomes and prevent unnecessary delays in treatment.", "authors": ["Nguyen Lauren A", "Paulo Frishan Rocel O", "Petersen Jordan J", "Miles J Douglas"], "journal": "The American journal of case reports", "entry_date": "2025/07/27 01:45", "pub_date": "2025-07-27", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40714827/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Department of Medicine, John A. Burns School of Medicine, University of Hawaii at Manoa, Honolulu, HI, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40706637", "title": "Exploration of the relationship between autoimmune neurologic diseases and mental disorders: evidence from Mendelian randomization study.", "abstract": "INTRODUCTION: Traditional epidemiologic studies suggest that autoimmune neurologic diseases may be associated with mental disorders (MDs). We used Mendelian randomization (MR) studies to explore the causal relationship between autoimmune neurologic diseases and MDs from the genetic perspective.\nMETHODS: In our study, autoimmune neurologic diseases include multiple sclerosis (MS), neuromyelitis optica (NMO), and myasthenia gravis (MG); MDs include anxiety, major depressive disorder (MDD), attention deficit/hyperactivity disorder (ADHD), schizophrenia, and bipolar affective disorder (BIP). A two-sample MR approach was used to explore causal relationships. The inverse variance weighted (IVW) method was the primary method for MR analysis. In addition, we included all MG datasets for meta-analysis after MR analysis with ADHD.\nRESULTS: Regarding the causal effects of MDs on autoimmune neurologic diseases, our analyses revealed a causal relationship between genetically predicted ADHD and MG (OR 2.250; 95% CI 1.267-3.998; p = 0.006), and no potential genetic causal relationships were found between the other diseases. However, according to the MR‒Egger analysis, there was no indication of directional pleiotropy. For the causal effects of autoimmune neurologic diseases on MDs, no potential genetic causal relationships were identified between any of the diseases. We performed a meta-analysis for MG and ADHD, there was no significant genetic causal relationship between ADHD and MG (OR 1.30 (95% CI 0.95-1.79); p = 0.10).\nCONCLUSION: This study revealed that there was no genetic mechanism linking autoimmune neurologic diseases and MDs to each other. These findings provide a foundation for the prevention and treatment of comorbid conditions in clinical research.", "authors": ["Shen Yu", "Xiang WenWen", "Xiong Qun", "Luo Si", "Chen Hao", "Song Ziwei", "Qiu Yusen", "Pang Lijun", "Hong Daojun"], "journal": "Neurological research", "entry_date": "2025/07/24 19:32", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40706637/", "pub_types": ["Journal Article", "Meta-Analysis"], "affiliations": ["Department of Neurology, the First Affiliated Hospital, Jiangxi Medical College, Nanchang University, Nanchang, China."], "china_related": true, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40706450", "title": "Algorithm for jitter measurement in neuromuscular junction disease.", "abstract": "The objective of this work was to extend the evaluation of a recently proposed method for estimating neuromuscular jitter within motor unit potential (MUP) trains extracted from muscles suffering neuromuscular junction disease. The method detects, within the MUP duration, \"single-fiber\" intervals that have likely been produced by single muscle fibers. Jitter is then estimated between pairs of these \"single-fiber\" intervals using an algorithm which incorporates the traditional mean consecutive difference (MCD) parameter. Electromyographic (EMG) recordings from facial muscles of 15 patients with symptoms related to myasthenia gravis were obtained. MUP trains were extracted using DQEMG software and manual jitter measures were obtained using an ad-hoc graphical interface, which emulates single fiber EMG protocols. Automatic measures for two different values of an internal threshold parameter were obtained and compared to manual measures. 5 %, 25 %, 75 % and 95 % percentiles for the differences between the automatic and manual jitter measurements were [-3.74, -1.47, 1.24, 3.47 μs] and [-6.45, -2.07, 1.65, 7.16 μs], for the two threshold values, respectively. Therefore, very small statistical and clinical differences were found between the automatic and manual jitter measures, supporting the method as an accurate tool for jitter assessment or as a guiding aid for manual procedures.", "authors": ["Malanda Armando", "Stashuk Daniel", "Valle César", "Rodríguez-Falces Javier", "Navallas Javier", "de Carvalho Mamede", "Castro José", "Garnés-Camarena Oscar"], "journal": "Journal of electromyography and kinesiology : official journal of the International Society of Electrophysiological Kinesiology", "entry_date": "2025/07/24 18:10", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40706450/", "pub_types": ["Journal Article"], "affiliations": ["Public University of Navarra, Spain. Electronic address: malanda@unavarra.es."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40704537", "title": "Assessing Gallbladder Wall Thickening due to Systemic Venous Congestion Using the VExUS Score With Point-Of-Care Ultrasound.", "abstract": "Gallbladder wall thickening is commonly associated with acute cholecystitis but can also result from systemic venous congestion. Point-of-care ultrasound (POCUS) plays a crucial role in distinguishing between these conditions, especially in critically ill patients. We report the case of a 35-year-old woman with myasthenia gravis and a mediastinal tumor who required mechanical ventilation following tumor resection. During her intensive care unit stay, she developed gallbladder wall thickening indicative of systemic venous congestion, as assessed by POCUS using the Venous Excess Ultrasound (VExUS) score. This finding resolved with diuretic therapy. This case underscores the value of POCUS in differentiating gallbladder wall thickening caused by systemic venous congestion from acute cholecystitis in critically ill patients.", "authors": ["Cheong Issac", "Tamagnone Francisco Marcelo"], "journal": "Journal of clinical ultrasound : JCU", "entry_date": "2025/07/24 06:34", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40704537/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Critical Care Medicine, Sanatorio de Los Arcos, Buenos Aires, Argentina."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40704307", "title": "Myasthenia gravis and nutrition.", "abstract": "Myasthenia gravis is an autoimmune neurological disease characterized by a disorder of nerve transmission at the neuromuscular junction. In this disease, antibodies attack acetylcholine receptors and their associated molecules, disrupting nerve transmission and impairing normal muscle contraction. Myasthenia gravis is diagnosed through physiological and neurological examinations, blood antibody tests, and electronic methods. Various approaches are used for symptom management, including immunosuppressive drugs, acetylcholinesterase inhibitors, and thymectomy. Previous literature has focused primarily on symptoms and medical treatment. However, resources related to nutrition and Myasthenia gravis are limited. This study bridges this gap by examining the effects of different nutritional interventions on the disease and the importance of nutrition in the treatment process.", "authors": ["Uçak Merve Nur", "Arıtıcı Çolak Gözde"], "journal": "Frontiers in nutrition", "entry_date": "2025/07/24 05:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40704307/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Nutrition and Dietetics, Institute of Health Sciences, Acibadem Mehmet Ali Aydinlar University, Istanbul, Türkiye."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.1, "journal_quartile": "2区"}, {"pmid": "40703512", "title": "Correction: Identification of potential prognostic biomarkers of thymoma with myasthenia gravis based on serum proteomics.", "abstract": "[This corrects the article DOI: 10.3389/fimmu.2025.1580219.].", "authors": ["Lin Xiaoting", "Liu Peng", "Qi Guoyan"], "journal": "Frontiers in immunology", "entry_date": "2025/07/24 05:08", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40703512/", "pub_types": ["Published Erratum"], "affiliations": ["Department of Oncology, Hebei Medical University, Shijiazhuang, Hebei, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40702923", "title": "In silico and NMR studies on pharmaceutical compounds with therapeutic action against Myasthenia Gravis.", "abstract": "Myasthenia Gravis, a chronic autoimmune disease, is primarily treated with acetylcholinesterase inhibitors. However, these drugs are not specific, and their mechanism of action against the disease has not been elucidated. They have a propensity to act on different targets, and their therapeutic action is symptomatic. For this reason, we have studied the interactions of commercially available drugs against Myasthenia Gravis to various enzyme targets to examine if there is any selectivity in their action and possibly to reveal any potential use for other diseases. In particular, the Computational Chemistry programs, AutoDock and Maestro, were used to assess the binding of azathioprine, prednisone, and pyridostigmine to different classes of enzymes, such as: cyclooxygenases (COX-1, COX-2), monoamine oxidases (MAO-A, MAO-B), angiotensin receptors (AT1, AT2), and lipoxygenases (LOX-1, 5-LOX). Molecular Dynamics simulations were employed to further analyze the stability and interactions of the most effective compounds. Using in silico platforms it was found that these drugs are not toxic, they do not produce unwanted adverse eaffects, and that pyridostigmine seems to be the best compound according to the ADME results. Additionally, Saturation Transfer Difference NMR experiments were carried out and confirmed the binding of azathioprine to LOX-5 at both the molecular and atomic levels. The in vitro evaluation of azathioprine and prednisone also revealed important inhibition of human 15-LOX-1 over general lipoxygenase activity. Finally, it was found that these drugs have potential for use in various biological and pharmacological applications such as CNS drugs.", "authors": ["Petsas Errikos", "Massios Eleftherios", "Georgiou Nikitas", "Cheilari Antigoni", "Papadimitriou Panagiotis Konstantinos", "Kakava Margarita Georgia", "Apostolou Ektoras Vasileios", "Angelonidis Ioannis", "Eleftheriadis Nikolaos", "Tzeli Demeter", "Mavromoustakos Thomas"], "journal": "Journal of biomolecular structure & dynamics", "entry_date": "2025/07/24 03:52", "pub_date": "2025-07-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40702923/", "pub_types": ["Journal Article"], "affiliations": ["Laboratory of Organic Chemistry, Department of Chemistry, National and Kapodistrian University of Athens, Athens, Greece."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40700243", "title": "Neuromyelitis Optica Diagnosis in Two Elderly Patients with Systematic Lupus Erythematosus: A Case Series.", "abstract": "Background and Clinical Significance: Neuromyelitis optica (NMO) is a chronic demyelinating inflammatory disease of the central nervous system (CNS), mediated by autoantibodies against aquaporin-4 (AQ4) receptors. In the spectrum of NMO, other autoimmune diseases also coexist, though their association with systemic lupus erythematosus (SLE) is rare. Case Presentation: We present two cases of patients in their 70s who were diagnosed with NMO in the context of SLE. The first case concerns a 78-year-old woman with drug-induced SLE and thoracic myelitis who developed T4-level incomplete paraplegia over three weeks. The second case involves a 71-year-old woman with a history of SLE and myasthenia gravis, presenting with cervical myelitis with progressive worsening of walking and C4-level paraparesis over two months. In both cases, elevated serum anti-AQ4 titers were detected, establishing the diagnosis of NMO and differentiation from an atypical manifestation of SLE-related myelitis. High doses of intravenous corticosteroids with gradual tapering, along with cyclophosphamide, followed by rituximab, were administered in both patients. The first patient showed a poor response, while the second showed improvement. Conclusions: The coexistence of NMO with SLE is rare, but the occurrence of myelitis in patients with connective tissue diseases should raise the suspicion of NMO, especially in elderly women and several years after the diagnosis of SLE. Time to treatment is critical, as delays in treating NMO can result in cumulative and disabling damage.", "authors": ["Astara Kyriaki", "Lypiridou Maria", "Kalafatakis Konstantinos", "Nikolaou Georgios", "Stouraitis Georgios"], "journal": "Reports (MDPI)", "entry_date": "2025/07/23 13:05", "pub_date": "2025-07-16", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40700243/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Army Share Fund Nursing Institution (NIMTS), 11521 Athens, Greece."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40698586", "title": "Predictors of Outcome in Myasthenic Crisis.", "abstract": "INTRODUCTION/AIMS: The impact of maintenance steroid sparing immunosuppression (SSIS) and prednisone dosage on myasthenic crisis (MC) outcomes and their effects on the development of sepsis have not been well described. This study aimed to investigate the predictive value of these variables on MC outcomes.\nMETHODS: This retrospective, multi-center study examined the potential predictors of MC outcomes using univariate and multivariate analyses through mixed-effect logistic regression and Cox proportional hazards regression.\nRESULTS: We included 57 MCs that occurred in 52 patients with a median age of 55 years (interquartile range [IQR]: 33-66), 26 of whom (45.6%) were male. Multivariate analysis showed that sepsis was associated with prolonged length of intensive care unit (ICU) stay (hazard ratio [HR] for time to discharge from the ICU: 0.27, 95% confidence interval [CI]: 0.11-0.71) and duration of ventilation (HR for time to extubation: 0.28, 95% CI: 0.12-0.67). Predictors of sepsis development were age > 50 years (odds ratio [OR]: 7.74, 95% CI: 1.29-46.53) and prednisone use of ≥ 60 mg/day during ICU stay (OR: 13.07, 95% CI: 2.17-86.73). The presence of maintenance SSIS at MC onset predicted a shorter length of ICU stay (HR for time to discharge from the ICU: 2.23, 95% CI: 1.13-4.42) and duration of ventilation (HR for time to extubation: 2.73, 95% CI: 1.37-5.43).\nDISCUSSION: The presence of maintenance SSIS at MC onset and the prevention of sepsis are measures that could improve MC outcomes. The use of lower doses (< 60 mg/day) of prednisone, when feasible, could mitigate the risk of sepsis in MC.", "authors": ["Abuzinadah Ahmad R", "Alanazy Mohammed H", "Butt Nadeem Shafique", "Alzabidi Ziad H", "Alrehaili Marwa L", "Alqahtani Laila", "Bushnag Areej Abdulrahman", "Alkully Hussien Salem", "Beck AlBaraa Ali", "Makkawi Seraj", "Maglan Alaa", "Alsolaihim Alanood", "Alshehri Ali", "Alyahya Mossaed Mohammed", "Alotaibi Muteb Khidhran", "Aljasir Shahad Jamal", "Alshareef Aysha A", "Bamaga Ahmed K", "Abulaban Ahmad Abdulaziz"], "journal": "Muscle & nerve", "entry_date": "2025/07/23 06:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40698586/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Department of Neurology, Faculty of Medicine, King Abdulaziz University, Jeddah, Saudi Arabia."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40698227", "title": "Challenges of a Pregnant Woman With Untreated Myasthenia Gravis: Delivery and Puerperium.", "abstract": "Myasthenia gravis (MG) is a rare autoimmune neurological disorder. Pregnancy, labor, and puerperium are risk factors for a myasthenic crisis. This case reports a late 20s pregnant woman evacuated from Guinea-Bissau with the diagnosis of generalized and severe MG, tetraparetic, at 38 weeks of gestation. She had never been treated for MG. After multidisciplinary assessment and despite current recommendations, intensive therapy with IV immunoglobulin and pyridostigmine was started and labor was induced. There were no neonatal complications. There was a worsening of symptoms during puerperium and therapy intensification with additional corticosteroids being needed. Labor in women with non-treated MG carries a high risk for serious and even fatal complications both for mother and child. Despite being a rare condition, it is more frequent in women of childbearing age, and guidelines on this topic are scarce.", "authors": ["Plancha Marta", "Miguel Andreia", "Magno Francisca", "Silva Dias Margarida", "Machado Ana Isabel"], "journal": "Cureus", "entry_date": "2025/07/23 05:05", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40698227/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Obstetrics and Gynecology, Unidade de Saúde Local de São José, Maternidade Dr. Alfredo da Costa, Lisboa, PRT."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40695604", "title": "Myasthenic syndromes: mistaking genetic for acquired.", "abstract": "Congenital myasthenic syndromes (CMS) are a rare, heterogeneous group of disorders caused by pathogenic variants in genes encoding proteins essential for neuromuscular transmission. DOK7 variants are among the most common causes of CMS and one of the subtypes that may worsen with pyridostigmine. We report two patients who presented in adulthood with fatigable limb girdle weakness, initially diagnosed with seronegative myasthenia gravis, who slowly progressed over time despite escalating treatment and eventually needed intensive care admission. Revisiting the history led to the diagnosis of DOK7 CMS. Both patients improved after stopping immunosuppressants and pyridostigmine and starting salbutamol. These cases highlight the importance of considering CMS in patients with seronegative myasthenia gravis.", "authors": ["Henehan Leighann", "Rossini Elena", "Platt Isobel Sarah", "Dong Yin Yao", "Beeson David", "Fuller Geraint N", "Leite Maria Isabel", "Palace Jacqueline"], "journal": "Practical neurology", "entry_date": "2025/07/22 21:32", "pub_date": "2026-03-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40695604/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Clinical Neurology, Neurology Department, John Radcliffe Hospital, Oxford, UK Leighann.henehan@ouh.nhs.uk."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.3, "journal_quartile": "4区"}, {"pmid": "40692342", "title": "Cervical ventroflexion in cats: 86 cases (2003-2024).", "abstract": "ObjectivesThe aim of this study was to characterise cervical ventroflexion in cats, investigate which diseases are associated with its occurrence and evaluate treatment outcome.MethodsThis retrospective, two-centre study spans the period from 2003 to 2024. The inclusion criteria consisted of complete medical records, presence of cervical ventroflexion, baseline clinicopathological testing and a diagnosis. A descriptive statistical analysis was performed for all cats. Univariable and multivariable analyses were used to compare the feline hypokalaemic myopathy (FHM) group vs all other diagnoses.ResultsA total of 86 cats met the inclusion criteria. The most common diagnoses associated with cervical ventroflexion were FHM (42/86, 48.8%), hyperthyroidism (10/86, 11.6%), thiamine deficiency (9/86, 10.5%), immune-mediated polyneuropathy (6/86, 7%), cervical ischaemic myelopathy (5/86, 5.8%), acquired myasthenia gravis (3/86, 3.5%) and feline infectious peritonitis (FIP) meningoencephalomyelitis (3/86, 3.5%). Absence of additional neurological deficits (P = 0.020) was significantly associated with a diagnosis of FHM, whereas lateralisation of neurological signs (P = 0.004) was negatively associated with FHM. In most of the cats (65/86, 75.6%) that received treatment depending on the diagnosis, cervical ventroflexion had been reversible upon discharge.Conclusions and relevanceCervical ventroflexion is a neurological sign associated with either FHM when present as the sole sign, or another diagnosis when accompanied by additional neurological signs. It is usually reversible with treatment. This information may further assist clinicians in decision-making, especially when time or financial constraints exist.", "authors": ["Karpozilou Athina", "De Stefani Alberta", "Liatis Theofanis"], "journal": "Journal of feline medicine and surgery", "entry_date": "2025/07/22 03:13", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40692342/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Southern Counties Veterinary Specialists, Ringwood, UK."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "40690397", "title": "Active Immunization for Inducing Autoimmune Muscle-Specific Kinase (MuSK) Myasthenia Gravis in Mice.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder affecting the neuromuscular junction. While most MG patients produce autoantibodies against the acetylcholine receptor (AChR), a subset of patients exhibits autoantibodies targeting the muscle-specific kinase (MuSK). MuSK MG is characterized by severe muscle weakness, treatment-resistant clinical manifestations, and myasthenic crises, often necessitating mechanical ventilation. Consequently, patients frequently require prolonged use of immunosuppressants, which are associated with long-term adverse effects. Given the severity and rarity of MuSK-MG, developing an experimental animal model is crucial for advancing new treatment modalities and a deeper understanding of the underlying pathophysiological mechanisms. Experimental autoimmune myasthenia gravis (EAMG) serves as an animal model for MuSK-MG, effectively but partly mimicking the clinical and immunological features of human MG. The induction of autoimmune animal models can be achieved through active or passive immunization. In the herein presented experimental protocol, active immunization was employed by subcutaneously administering the purified extracellular domain of human MuSK emulsified in complete Freund's adjuvant with heat-killed Mycobacterium tuberculosis. Immunization was performed at four sites, followed by a booster injection of MuSK on the 28th day. This adjuvant with M. tuberculosis enables activation of the immune system through TLR4 and enhanced phagocytosis of the administered antigen. This article comprehensively details the development and characterization of MuSK-EAMG from inception to conclusion.", "authors": ["Koral Gizem", "Yılmaz Vuslat", "Ulusoy Canan Aysel", "Lazaridis Konstantinos", "Tüzün Erdem"], "journal": "Journal of visualized experiments : JoVE", "entry_date": "2025/07/21 13:14", "pub_date": "2025-07-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40690397/", "pub_types": ["Journal Article", "Video-Audio Media"], "affiliations": ["Department of Neuroscience, Aziz Sancar Institute of Experimental Medicine, Istanbul University; gizemkoral@ogr.iu.edu.tr."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40689326", "title": "Serum cytokine profiles in patients with myasthenia gravis.", "abstract": "BACKGROUND: Cytokines play a crucial role in instigating inflammation and generating pathogenic autoantibodies at the neuromuscular junction in individuals suffering from myasthenia gravis (MG). The objective of this study is to investigate the cytokine profiles among patients grappling with MG.\nMETHODS: This study recruited patients with unstable MG and healthy controls from the First Affiliated Hospital of Fujian Medical University during the period spanning January 2021 to December 2022. We evaluated IL-1β, IL-2, IL-4, IL-5, IL-6, IL-8, IL-10, IL-12P70, IL-17, IFN-γ, IFN-α, and TNF-α in the serum using the Flow Cytometric Bead Array (CBA) technique.\nRESULTS: A total of 104 patients and 54 healthy controls were included in the study. Notably, serum levels of interleukin (IL)-1β, IL-2, IL-10, and IL-17 exhibited significant elevation in unstable MG patients when compared to the healthy control group. Furthermore, levels of IL-1β and IL-5 were notably higher in unstable MG patients who tested negative for acetylcholine receptor (AChR) antibodies when compared to their AChR-antibody positive counterparts (P < 0.05). In AChR-antibody positive patients, there was a statistically significant decrease in IL-1β, IL-2, IL-4, IL-6, IL-8, IL-10, IL12-P70, IFN-γ, and IFN-α upon improvement. There was no discernible variation in MG patients at an unstable stage regardless of their onset time. Additionally, there was no statistically significant differences between pre- and post-thymectomy in thymoma-associated MG (TAMG).\nCONCLUSION: Individuals with unstable MG appear to demonstrate elevated levels of serum IL-1β, IL-2, IL-10, and IL-17 compared to healthy individuals. Furthermore, among MG subgroups, those testing negative for antibodies, tend to display increased levels of IL-1β and IL-5. These serum cytokine profiles may hold promise as potential biomarkers for stratifying MG patients in clinical settings.", "authors": ["Wu Xuan", "Song Huan Huan", "Xu Guo Rong", "Li Run Yun", "Ye Xiao Bin"], "journal": "Frontiers in neurology", "entry_date": "2025/07/21 07:40", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40689326/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Fujian Medical University, Fuzhou, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40688837", "title": "A Rare Case of Myasthenia Gravis With Underlying Aldolase A Deficiency: Diagnostic and Therapeutic Challenges.", "abstract": "We report one of the first documented cases globally of a 24-year-old female presenting with recurrent episodes of muscle pain, weakness, and rhabdomyolysis. Although she initially improved with conservative management, her symptoms recurred, warranting further investigation. Comprehensive serologic and metabolic evaluations revealed a rare dual diagnosis of seropositive myasthenia gravis (MG) and aldolase A deficiency. MG, an autoimmune neuromuscular junction disorder, contributed to her characteristic diurnal fatigue and acetylcholine receptor antibody positivity, while aldolase A deficiency, a rare metabolic myopathy, was responsible for impaired glycolysis and exertional rhabdomyolysis. This case underscores the importance of considering overlapping autoimmune and metabolic neuromuscular conditions in young adults with unexplained muscle breakdown.", "authors": ["Ottu Para Niyas Khalid", "Ramanathan Nagarajan Divyashri", "Mani Jacob Daya", "Viju Diya"], "journal": "Cureus", "entry_date": "2025/07/21 07:34", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40688837/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Burjeel Medical City, Abu Dhabi, ARE."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40688189", "title": "Neurological Immune-Related Adverse Events in Patients Treated with Anti-Programmed Death 1 Agent, Pembrolizumab: A Case Series.", "abstract": "BACKGROUND: This case series highlights the various clinical manifestations of pembrolizumab-induced neurological adverse events, offering insights into the spectrum of immune-related neurological adverse events associated with immune checkpoint inhibitor (ICI) therapy.\nCASE PRESENTATION: We present 5 patients who received pembrolizumab as a part of their treatment. They exhibited a variety of clinical manifestations, which included central nervous system involvement and necrotizing myopathy, each responding differently to therapeutic interventions. Among the participants, there were two cases of myopathy, one case of demyelinating polyneuropathy, one individual whose myasthenia gravis had worsened, and 1 patient diagnosed with encephalitis. The patients experienced symptoms with varying degrees of severity, leading to different responses in their clinical treatment, and 1 patient ultimately passed away due to complications.\nCONCLUSION: Neurological immune-related adverse effects (n-irAEs) are rare, and their identification poses a challenge due to their complexity and the presence of underlying autoimmune and paraneoplastic disorders. The expected prognosis for n-irAEs is unclear, presenting a range of complete recovery rates and differing mortality outcomes. The increased frequency of ICI usage increases the probability of an immune response, necessitating healthcare professionals to identify new symptoms in immunotherapy patients. Side effects differ from conventional chemotherapy and necessitate different therapeutic approaches.", "authors": ["Khosravi Sepehr", "Khoeini Tara", "Rahattalab Fateme", "Ashtiani Bahram Haghi"], "journal": "Case reports in neurology", "entry_date": "2025/07/21 07:24", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40688189/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, School of Medicine, Iran University of Medical Sciences, Tehran, Iran."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40686281", "title": "Repetitive Nerve Stimulation (RNS) Studies in Infants: Are Infants Just \"Little Adults\" or Do They Deserve Their Own Parameters (or Cut-Off Values) for RNS?", "abstract": "", "authors": ["Wright Sarah E", "Lehky Tanya J"], "journal": "Muscle & nerve", "entry_date": "2025/07/21 05:43", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40686281/", "pub_types": ["Editorial"], "affiliations": ["Department of Neurology, Children's National Hospital, Washington, DC, USA."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40684089", "title": "Comparative safety of nivolumab plus ipilimumab versus nivolumab plus relatlimab in advanced melanoma: a pharmacovigilance study based on the FDA adverse event reporting system (FAERS).", "abstract": "BACKGROUND: Nivolumab combined with ipilimumab (NIVO-IPI) and nivolumab combined with relatlimab (NIVO-RELA) are approved treatments for advanced melanoma. However, the data on the differential adverse event (AE) risks associated with these two regimens are lacking.\nMETHODS: We performed a disproportionality analysis using the FDA Adverse Event Reporting System (FAERS) database for NIVO-IPI and NIVO-RELA from the fourth quarter (Q4) of 2015 to Q4 of 2024. We calculated the reporting odds ratios (ROR) and information component (IC) with 95% confidence intervals (CIs).\nRESULTS: A total of 7,482 records for NIVO-IPI and 185 records for NIVO-RELA were extracted from FAERS. NIVO-IPI showed significantly higher risks for gastrointestinal (ROR = 1.39), endocrine (ROR = 3.10), hepatobiliary (ROR = 2.32), metabolism and nutrition (ROR = 1.44), and respiratory, thoracic, and mediastinal disorders (ROR = 1.18), particularly in preferred terms (PTs) such as colitis, hypophysitis, pneumonia, and hepatitis. NIVO-RELA was associated with increased risks for cardiac (ROR = 2.84) and vascular disorders (ROR = 2.04), notably in PTs like myocarditis, troponin elevation, and myasthenia gravis. 80% of AEs occurred within three months for both regimens. The median time-to-onset was 42 days for NIVO-IPI compared to 57 days for NIVO-RELA, with no statistically significant difference (p = 0.66).\nCONCLUSION: NIVO-IPI is linked with a broader range of immune-related toxicities, whereas NIVO-RELA presents higher cardiac-specific risks. These findings emphasize the need for tailored AE monitoring based on treatment selection.", "authors": ["Xu Shanshan", "Song Zhihui", "Wang Dong", "Wang Ente", "Wang Jiawei"], "journal": "BMC cancer", "entry_date": "2025/07/19 23:28", "pub_date": "2025-07-19", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40684089/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Pharmacy, Beijing Tongren Hospital, Capital Medical University, No.1 Dongjiaomin Lane, Dongcheng District, Beijing, China."], "china_related": true, "study_types": ["Historical Control"], "evidence_level": "IV", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "40681713", "title": "Genetic and molecular underpinnings of the link between rheumatoid arthritis and myasthenia gravis: Insights from GWAS and transcriptomic analyses.", "abstract": "BACKGROUND: Although studies have shown that patients with rheumatoid arthritis (RA) are at a higher risk of developing myasthenia gravis (MG), the causal relationship and shared genetic basis between these two diseases have not been fully investigated. The purpose of this study is to uncover the potential bidirectional causality between RA and MG, and to explore their shared genetic factors and possible pathogenic mechanisms.\nMETHODS: First, we utilized genome-wide association (GWAS) data from the IEU Open GWAS project, employing the online analysis platform MRBASE and applying four Mendelian randomization (MR) methods (Inverse Variance Weighted regression, Weighted Median, MR-Egger, and Weighted Mode) to explore the bidirectional causal relationship between RA and MG. Subsequently, we extracted transcriptomic data for RA and MG from the GEO database and used differential expression analysis, weighted gene coexpression network analysis (WGCNA), machine learning, and gene set enrichment analysis (GSEA) to identify key hub genes and their associated pathways. Furthermore, we employed the CIBERSORT method to analyze the immune cell infiltration in both diseases. Ultimately, based on these identified hub genes, we constructed a diagnostic model-nomogram-to aid in the diagnosis and prediction of the diseases.\nRESULT: RA is significantly associated with an increased risk of MG (Odds Ratio [OR]: 1.353, 95% Confidence Interval [CI]: 1.081 to 1.693, P = 0.008). However, there is insufficient evidence to support the hypothesis that MG increases the risk of RA. Through differential expression analysis and WGCNA methods, we collectively identified 18 key shared genes. Further, using two machine learning approaches, we ultimately identified 4 core hub genes (CDC42EP2, FKBP5, CD79A, and TDP1), which have great value in the diagnosis of RA and MG and are closely related to immune cell infiltration.\nCONCLUSION: Our study has unveiled the bidirectional causality between RA and MG, and identified shared molecular characteristics, highlighting the potential for developing targeted therapeutic strategies. Key Points • Our study shows a significant link between RA and increased MG risk, suggesting a bidirectional causal relationship. • We identified 18 key shared genes between RA and MG through differential expression and WGCNA, and pinpointed 4 core hub genes (CDC42EP2, FKBP5, CD79A, TDP1) using several machine learning algorithms. These genes are valuable for diagnosis and associated with immune cell infiltration. • We developed a diagnostic nomogram based on the hub genes, which could aid in diagnosing and predicting RA and MG, guiding clinical practice and personalized medicine.", "authors": ["Huang Jian", "Wang Lu", "Hu Xiaodong", "Wang Tianrui", "Zhang Yingze"], "journal": "Clinical rheumatology", "entry_date": "2025/07/18 23:30", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40681713/", "pub_types": ["Journal Article"], "affiliations": ["Department of Orthopedics, The Affiliated Hospital of Qingdao University, Qingdao, Shandong, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40681684", "title": "A cross-sectional study on fear of progression in patients with myasthenia gravis.", "abstract": "Patients with myasthenia gravis (MG) are prone to resulting in a significant psychological burden. This study aims to investigate the condition of fear of progression (FoP) and identify factors associated with FoP among MG patients. This cross-sectional study included 83 patients with MG admitted to the First Affiliated Hospital of Nanchang University from January to November 2024. Data were collected through clinical records and questionnaires, including demographic details, disease duration, comorbidities, current drug regimen, and the fear of progression questionnaire-short form (FoP-Q-SF). The simplified fear of progression scale score for 83 MG patients was 31.36 ± 10.22. Among these participants, 38.6% exhibited dysfunction FoP. There was no significant difference concerning age, marital status, course of the disease, crisis of MG, STAI score, and TAI score in the total score of fear of disease progression in MG patients. However, gender, progress of MG and MGFA classification were positively correlated with the fear of progression (P < 0.05), which was statistically significant. Furthermore, gender and disease progression were identified as factors influencing FoP in MG patients (P < 0.05). FoP among MG patients varies according to their socio-demographic and clinical characteristics. Gender and progress history of MG are associated with Fop.", "authors": ["Luo Si", "Xiong Ying", "Song Ziwei", "Lian Jia", "Qiu Yusen", "Zhu Min", "Li Menghua", "Zhou Meihong", "Hong Daojun"], "journal": "Scientific reports", "entry_date": "2025/07/18 23:29", "pub_date": "2025-07-18", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40681684/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital, Jiangxi Medical College, Nanchang University, Nanchang, China."], "china_related": true, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40680581", "title": "The number of apheresis procedures to treat immune-mediated neurological diseases is on the rise.", "abstract": "Apheresis is used for the treatment of many different diseases, especially when conventional therapy lacks efficacy. There are however some diseases in which apheresis is accepted as first line therapy. The aim of this analysis was to investigate the use of apheresis for the treatment of neurological diseases and the changes over two decades in the World Apheresis Association registry. During the period 2003-2023, a total of 23,699 apheresis procedures in 2963 patients with a neurological disease were performed. Data were collected during different periods by 44 centers, out of which 22 centers had been registering continuously over the latest 10 years. An increase in the proportion of neurological diseases developed over the period (p < 0.001) while the overall apheresis procedures remained stable (p = 0.46). Most procedures were due to myasthenia gravis (MG; n = 11,049 (31 % of patients), Guillain-Barré Syndrome (GBS; n = 3247 (30 %), multiple sclerosis (MS; n = 2665 (18 %)), chronic inflammatory demyelinating polyradiculoneuropathy (CIDP; n = 2367 (3 %)), and neuromyelitis optica (NMO; n = 650 (2 %)). A change in the proportion of these diseases was noted over time. Adverse events (AEs) differed significantly between the diseases. Patients with GBS had most moderate and severe AEs. Hypotension was the most common severe AE. The panorama of different neurological diseases may cause different AEs based on the variation in neurological response to the apheresis procedure and replacement fluid. It is important to expand this knowledge among those who are prescribing and those performing the apheresis procedures.", "authors": ["Le Poole Kaatje", "Vrielink Hans", "Aandahl Astrid", "Glatt Tanya Nadia", "Skosana Yona", "Hridlickova Radomira", "Blahutova Sarka", "Lanska Miriam", "Deeren Dries", "Griscevicius Antanas", "Audzijoniene Judita", "Newman Elizabeth", "Gasova Zdenka", "Ludvikova Zdenka Bhuiyanova", "Witt Volker", "Berlin Gösta", "Kielstein Jan", "Seval Guldane Cengiz", "Ott Michael", "Svenningsson Anders", "Stegmayr Bernd"], "journal": "Transfusion and apheresis science : official journal of the World Apheresis Association : official journal of the European Society for Haemapheresis", "entry_date": "2025/07/18 18:09", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40680581/", "pub_types": ["Journal Article"], "affiliations": ["Sanquin Blood Supply Foundation, Unit of Medical Affairs, Amsterdam, the Netherlands."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV"}, {"pmid": "40680253", "title": "Editors' Note: Effect of Immunosuppression in Risk of Developing Generalized Symptoms in Ocular Myasthenia Gravis: A Retrospective Cohort Study.", "abstract": "", "authors": ["Siegler James E", "Galetta Steven L"], "journal": "Neurology", "entry_date": "2025/07/18 16:12", "pub_date": "2025-08-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40680253/", "pub_types": ["Journal Article"], "affiliations": [], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "40680252", "title": "Author Response: Effect of Immunosuppression in Risk of Developing Generalized Symptoms in Ocular Myasthenia Gravis: A Retrospective Cohort Study.", "abstract": "", "authors": ["Menon Deepak", "Bril Vera", "Barnett-Tapia Carolina"], "journal": "Neurology", "entry_date": "2025/07/18 16:12", "pub_date": "2025-08-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40680252/", "pub_types": ["Journal Article"], "affiliations": ["(Bangalore, India)."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "40680250", "title": "Reader Response: Effect of Immunosuppression in Risk of Developing Generalized Symptoms in Ocular Myasthenia Gravis: A Retrospective Cohort Study.", "abstract": "", "authors": ["Xu Lingyu", "Zhou Bin", "Xu Yan"], "journal": "Neurology", "entry_date": "2025/07/18 16:12", "pub_date": "2025-08-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40680250/", "pub_types": ["Journal Article"], "affiliations": ["(Qingdao, China)."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 8.5, "journal_quartile": "1区"}, {"pmid": "40680247", "title": "AChR Autoantibody Pathogenic Properties Are Heterogeneously Distributed and Undergo Temporal Changes Among Patients With Myasthenia Gravis.", "abstract": "BACKGROUND AND OBJECTIVES: Acetylcholine receptor (AChR) autoantibodies contribute to myasthenia gravis (MG) pathogenesis through 3 mechanisms: complement activation, receptor internalization, and acetylcholine (ACh) binding site blocking. Recently approved therapies target these autoantibodies by inhibiting the complement pathway or blocking the neonatal Fc receptor, reducing IgG autoantibody levels. However, these approaches have limitations: complement inhibitors do not address complement-independent mechanisms, and FcRn blockers only target IgG. Understanding how different pathogenic mechanisms, isotypes, and IgG subclasses are represented in the AChR autoantibody repertoire could lead to more precise application of therapeutics. To address this, we used advanced live cell-based assays to study autoantibody heterogeneity in longitudinally collected patient samples.\nMETHODS: Serum samples (N = 210) from 50 AChR IgG+ generalized MG patients collected longitudinally over 2 years were evaluated using a set of cell-based assays to measure complement activation, receptor internalization, ACh binding site blocking, and the frequency of the IgM and IgA isotypes and IgG subclasses.\nRESULTS: In cross-sectional samples, IgA and IgM autoantibodies co-occurred with IgG in 10% and 12% of patients, respectively. In addition, 4% of patients had all 3 isotypes (IgA, IgM, and IgG) present simultaneously. AChR-IgG1 was found in 67.4%, followed by IgG3 (21.7%) and IgG2 (17.4%). Complement was active in 84.8%, followed by AChR internalization (63%) and blocking (30.4%). Complement and AChR internalization were simultaneously active in 45.6%, complement and blocking were active in 10.8%, and all 3 pathomechanisms were active in 17.4%. Blocking alone was active in only 2.1%; AChR internalization alone was not found. Autoantibody binding capacity was associated with the magnitude of complement activation and AChR internalization. Temporal fluctuations of autoantibody binding capacity and the associated pathogenic mechanisms were observed. Pathogenic mechanisms were not associated with disease severity in cross-sectional analyses. However, longitudinally, disease severity measures followed a similar trend to the AChR autoantibody repertoire and mediated pathogenic mechanisms in some individuals, but not others.\nDISCUSSION: These findings highlight subsets of patients with MG with autoantibodies that can mediate pathogenic mechanisms or include isotypes that some therapeutics may not effectively target. Consequently, we suggest incorporating comprehensive autoantibody profiling into future MG clinical trials to further investigate potential associations with treatment outcomes.", "authors": ["Khani-Habibabadi Fatemeh", "Roy Bhaskar", "Pham Minh C", "Obaid Abeer H", "Filipek Beata", "Nowak Richard J", "O'Connor Kevin C"], "journal": "Neurology(R) neuroimmunology & neuroinflammation", "entry_date": "2025/07/18 16:03", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40680247/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 7.5, "journal_quartile": "1区"}, {"pmid": "40679699", "title": "MicroRNAs as Diagnostic Biomarkers of Myasthenia Gravis: A Systematic Review and Meta-Analysis.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by fluctuating muscle weakness. MicroRNAs (miRNAs) have emerged as potential biomarkers for MG diagnosis, offering noninvasive and reliable detection. This systematic review and meta-analysis evaluated the diagnostic accuracy of miRNAs in MG. A comprehensive search of PubMed, Embase, and Google Scholar was conducted up to March 9, 2025. Eligible studies assessing miRNAs as MG biomarkers were selected on the basis of predefined criteria. Pooled sensitivity, specificity, and diagnostic odds ratios (DORs) were calculated via random effects model. Heterogeneity was assessed via I2, and publication bias was evaluated via Deeks' funnel plot. Nine studies including 1,797 participants were analysed. The pooled sensitivity and specificity were 0.80 (95% CI: 0.75-0.84) and 0.71 (95% CI: 0.65-0.77), respectively, with an area under the curve (AUC) of 0.83. Bivariate heterogeneity analysis indicated moderate variability, the cause of which were identified using subgroup analysis with region, clinical subtypes and seropositivity as subgroups. miRNAs demonstrate strong diagnostic potential for MG, with good sensitivity and specificity. However, standardized methodologies and further validation in large, multicentre studies is warranted.", "authors": ["Paudel Prayash", "Sah Asutosh", "Paudel Poonam"], "journal": "Cellular and molecular neurobiology", "entry_date": "2025/07/18 11:19", "pub_date": "2025-07-18", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40679699/", "pub_types": ["Systematic Review", "Journal Article", "Meta-Analysis"], "affiliations": ["Bachelor of Medicine and Bachelor of Surgery, Maharajgunj Medical Campus, Institute of Medicine, Tribhuvan University Teaching Hospital, Maharajgunj Rd, Kathmandu, 44600, Bagmati, Nepal. prayash.784401@mmc.tu.edu.np."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.8, "journal_quartile": "3区"}, {"pmid": "40675742", "title": "Autoantibodies in myasthenia gravis.", "abstract": "Autoimmune Myasthenia Gravis (MG) is a disease characterized by fatigable muscle weakness and autoantibodies. It can be divided by the presence of serum autoantibodies into two major categories where Immunoglobulin G (IgG) against either the acetylcholine receptor (AChR), or muscle specific kinase (MuSK) causes fatigable muscle weakness. The clinical relevance of Low-density lipoprotein-receptor related protein-4 IgG (LRP4) is debated. These antibodies disrupt neuromuscular transmission via different mechanisms: AChR antibodies, mostly of IgG1 and IgG3 subclass, can activate complement leading to a simplification of the NMJ architecture, block acetylcholine binding to its receptor to prevent channel opening, and internalize AChR. By contrast, MuSK antibodies, mostly of the IgG4 subclass, impair MuSK-LRP4 interactions, and LRP4 antibodies may interfere with agrin-induced clustering. Once these antibody targets were identified the development of antibody assays began. Patrick and Lindstrom made the landmark discovery that antibodies against soluble AChR caused acute flaccid paralysis in immunized rabbits which kickstarted test development. The first, and until recently, most useful test was the radioimmunoassay (RIA) where AChR radiolabeled with toxin from venomous snakes allowed quantitative measurement of AChR-IgG. Most recently the clustered AChR cell-based assays (CBA) provide a significant improvement in test sensitivity over all other methods. MuSK assays followed a similar but shorter path. The accurate detection of AChR and MuSK antibodies has a crucial role in supporting the clinical diagnosis and management of MG which includes a diverse population of patients with a wide range of clinical manifestations, disease severity and response to standard and new therapies. In this chapter we highlight how distinct target-specific IgG autoantibodies cause neuromuscular transmission defects, and subsequently shape disease manifestations in the different MG antibody subgroups. We review the evolution of diagnostic assays, from early RIA to modern CBA, and addresses interpretative pitfalls, particularly in borderline or \"seronegative\" cases. Finally, the authors address the significance of accurate autoantibody detection in the diagnosis and management of patients with one of the antibody MG subtypes, as well as in patients with other autoimmune conditions and thymic malignancies.", "authors": ["Fichtner Miriam L", "Horstkorte Lillith", "Sánchez Navarro Blanca G", "Schmidt Hellen", "Cabraal Isobel", "Waters Patrick J", "Leite Maria Isabel"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675742/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology and Experimental Neurology, Charité Universitätsmedizin Berlin, Berlin, Germany."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675741", "title": "Thymic physiology and pathophysiology in Myasthenia Gravis.", "abstract": "The thymus is a central lymphoid organ responsible for T-cell development and maturation and is crucial in adaptive immunity. This organ creates a specialized environment for thymocyte differentiation and positive/negative selection, ensuring the survival of functional and self-tolerant T cells while eliminating autoreactive clones. This process, which is known as T-cell education, involves interactions between developing T cells and stromal cells, primarily thymic epithelial cells, which present tissue-specific antigens. Proper thymus function remains vital for maintaining immune homeostasis. However, thymic abnormalities have been implicated in Myasthenia Gravis (MG), where the thymus often exhibits lymphofollicular hyperplasia or thymomas, which may trigger an autoimmune response against the acetylcholine receptor at the neuromuscular junction. This leads to impaired neuromuscular transmission and characteristic muscle weakness. Understanding the etiological mechanisms underlying thymic alterations associated with MG is crucial for elucidating immune dysregulation resulting from an abnormal thymus, which may persist even post-therapeutic thymectomy.", "authors": ["Dragin Nadine", "Le Panse Rozen"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675741/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Sorbonne University, INSERM, Institute of Myology, Center of Research in Myology, Paris, France."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675740", "title": "Contribution of cellular immune dysregulation to myasthenia gravis pathology.", "abstract": "Myasthenia gravis (MG) is an autoimmune disorder in which autoantibodies attack proteins at the neuromuscular junction, resulting in impaired neuromuscular transmission. Like other autoimmune diseases, MG arises when the immune system fails to distinguish self from non-self, attacking and damaging normal tissues. The pathological response involves not only B cells, responsible for autoantibody production, but also T cells, which provide essential support for B cell pathogenicity. While the precise triggers of this abnormal immune response remain undefined, MG is recognized as a multifactorial disease influenced by immune dysregulation along with genetic and environmental factors. This chapter explores the complex immunopathology of MG, highlighting how these factors collectively contribute to disease development. We examine the physiological development of T and B cell compartments, the tolerance checkpoints designed to prevent autoimmunity, and the consequences of their failure. Finally, we discuss the dysregulation of these cellular compartments in MG, emphasizing their roles in disease progression, the persistence of autoimmunity, and responses to treatment.", "authors": ["Bayer Alexandra C", "Nowak Richard J", "O'Connor Kevin C"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675740/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT, United States; Department of Immunobiology, Yale School of Medicine, New Haven, CT, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675738", "title": "Lambert Eaton Myasthenic Syndrome.", "abstract": "Lambert Eaton Myasthenic Syndrome (LEMS) is a pre-synaptic neuromuscular junction disorder characterised clinically by leg-predominant proximal weakness with spread of weakness distally and cranially with increasing severity as well as reduced reflexes and autonomic symptoms such as a dry mouth. Typical electrophysiological findings include small compound muscle action potentials at rest that augment following short exercise, decrement at low frequency (2-5 Hz) repetitive nerve stimulation, and increment at high frequency (20-50 Hz) repetitive nerve stimulation. Immunologically, antibodies to voltage gated calcium channels are present in the majority of patients. LEMS is associated with small cell lung cancer (SCLC), or rarely other tumours, in approximately 50 % of cases, for which patients should be carefully screened. The synaptic physiology of LEMS demonstrates a reduction in the probability of pre-synaptic acetylcholine vesicle release. This results in a reduced number (reduced quantal content) of miniature endplate potentials such that the post-synaptic summative endplate potential is insufficient to trigger myofiber contraction, manifesting as weakness. The clinical electrophysiological findings reflect normal rate-dependent changes at a neuromuscular junction, in the context of a reduction in quantal release. Treatment of LEMS comprises symptomatic treatments such as 3,4 diaminopyridine (amifampridine), which increases quantal release; immunotherapy; and treatment of underlying malignancy if present. The life expectancy of non-tumour LEMS is normal, although complete remission is uncommon. Progression of SCLC determines prognosis in tumour-associated LEMS, which is nonetheless better than in SCLC without LEMS.", "authors": ["El-Wahsh Shadi", "Reddel Stephen"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675738/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Brain and Mind Centre, University of Sydney, Camperdown, NSW, Australia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675737", "title": "Neuromuscular junction and the complement system.", "abstract": "Nearly 90 % of generalized myasthenia gravis (MG) patients have IgG1 or IgG3 antibodies against the acetylcholine receptor (AChR). Acetylcholine receptor antibodies induce neuromuscular transmission defect by various potential mechanisms including internalisation of AChR, receptor blockade and by activation of the classical complement pathway. Membrane attack complex (MAC) which is the final end product of complement activation leads to architectural destruction of the neuromuscular junction (NMJ). Several experimental models (EAMG) have shown evidence for complement in the pathogenesis of MG, with demonstration of prevention or reversal of the disease using complement inhibitory therapies. Various molecules that target the complement system have been developed to treat myasthenia gravis. Most of the currently studied molecules inhibit complement protein 5 (C5), which prevents the formation of MAC and subsequent NMJ destruction. The currently studied anti-complement therapies for MG include eculizumab, zilucoplan, ravulizumab, pozelimab, cemdisiran, gefurilimab, danicopan and few others in the pipeline. Many of these have also been shown to have long term benefit in different sub-groups of patients with MG. Given the risk of Gram-negative septicaemia (especially by meningococcus), patients would need vaccination prior to initiation of treatment and in some countries prophylactic antibiotics during treatment is recommended, although no major safety signatures have been noted in the studies so far. Future studies identifying specific biomarkers might help clinicians select the most appropriate patients who are more likely to respond to complement inhibitory therapies.", "authors": ["Jacob Saiju", "Howard James F"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675737/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Institute of Immunology and Immunotherapy, University of Birmingham, United Kingdom; University Hospitals Birmingham, Birmingham, United Kingdom."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675736", "title": "Blood and digital biomarkers in MG.", "abstract": "Biomarkers are measurable indicators to assess physiological processes, disease states, or therapy responses. In myasthenia gravis (MG), biomarkers are critical for diagnosis, monitoring, and treatment optimization. Despite advances in MG diagnostics and therapies, predictive biomarkers to personalize treatment remain underdeveloped. Key diagnostic blood biomarkers include antibodies against acetylcholine receptors (AChR) or muscle-specific tyrosine kinase (MuSK), confirming MG diagnosis and guiding treatment decisions. Prognostic markers, such as microRNAs (e.g., miR-150-5p and miR-30e-5p), show promise in predicting disease progression. Pharmacodynamic biomarkers enhance treatment precision, including CD20+ B cell counts for Rituximab and the CYP3A5 gene for Tacrolimus. Emerging research on metabolites, T and B-cell markers, complement factors, and proteomics may help distinguish MG's autoimmune profile. Digital biomarkers, using wearables and sensors, offer innovative patient monitoring. Future efforts integrating multi-omics and big data could revolutionize biomarker discovery, advancing personalized care and improving outcomes for MG patients.", "authors": ["Bhandage Amol K", "Chen Jiaxin", "Kaminski Henry J", "Punga Anna Rostedt"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675736/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden. Electronic address: amol.bhandage@uu.se."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675735", "title": "Special populations in myasthenia gravis: Early, late, and very late-onset MG.", "abstract": "The age at disease onset significantly influences the clinical course, pathophysiology, and treatment response in Myasthenia Gravis (MG). This chapter examines how immunological profiles, autoantibody prevalence, thymic pathology, genetic associations, treatment responses, and disease severity vary across early-onset (EOMG), late-onset (LOMG), and very late-onset MG (VLOMG). EOMG often presents with distinct immunological and genetic profiles, a predominance of female patients, and a higher incidence of thymic hyperplasia. In contrast, LOMG and VLOMG are characterized by thymic atrophy, differing genetic associations, and milder long-term disease courses with variable treatment responses. Recognizing these age-related variations is essential for optimizing diagnostic approaches and therapeutic strategies, highlighting the need for individualized patient management across different age groups.", "authors": ["Hoffmann Sarah"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675735/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology with Experimental Neurology and Neuroscience Clinical Research Center (NCRC) Charité - Universitätsmedizin Berlin, Corporate Member of Freie Universität Berlin and Humboldt Universität zu Berlin, Berlin, Germany. Electronic address: sarah.hoffmann@charite.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675734", "title": "Epidemiology of myasthenia gravis.", "abstract": "MG epidemiology may provide clues to disease etiology and pathogenesis. It is crucial for health planning and to estimate societal needs for health care resources. Recent high-quality studies have found an annual MG incidence of approximately 20 per million person-years, and a prevalence of approximately 25 per 100,000 population. Geographical variation reflects differences in case finding and diagnostic tools, but also a multitude of genetic and environmental etiological and risk factors. MG prevalence has increased in recent years because of more elderly people in the general population, improved case finding, and improved MG treatment with reduced mortality. In populations with optimal treatment, there is only a slightly increased mortality risk with MG. There are marked variations among MG disease subgroups regarding epidemiology. MuSK MG is more common in the Mediterranean area, juvenile MG is most common in China, whereas late onset MG with AChR antibodies is a subtype that has increased in incidence and prevalence globally.", "authors": ["Gilhus Nils Erik", "Breiner Ari"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675734/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Clinical Medicine, University of Bergen, Bergen, Norway; Department of Neurology, Haukeland University Hospital, Bergen, Norway. Electronic address: nils.gilhus@uib.no."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675733", "title": "Animal models of myasthenia gravis.", "abstract": "Animal models offer a platform to advance our understanding of myasthenia gravis (MG), an autoimmune disorder characterized by impaired neuromuscular transmission. Experimental autoimmune MG models (EAMG) actively induce autoimmunity through antigen immunization, aiding in understanding the immune response to self. Passive transfer models (PTMG) involve the injection of pathogenic antibodies into animals, providing insights into antibody-mediated mechanisms and complement-driven damage to the neuromuscular junction (NMJ). The pathogenic effect of autoantibodies targeting acetylcholine receptors (AChR), muscle-specific kinase (MuSK), and low-density lipoprotein receptor-related protein 4 (Lrp4) results in changes to the NMJ that are mechanistically distinct. These models validate therapeutic interventions preclinically, with methodologies ranging from antibody transfer to genetic modifications. Despite the translational challenges, these models bridge preclinical research and clinical applications, enabling the development of targeted treatments for MG.", "authors": ["Sikorski Patricia M", "Kusner Linda L"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675733/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Pharmacology and Physiology, Department of Neurology, George Washington University, Washington, DC, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675732", "title": "Cell models for studying myasthenia gravis.", "abstract": "Understanding the pathophysiology of Myasthenia Gravis (MG) and developing effective treatments requires using cell models that replicate key features of the disease, particularly those involved in the autoimmune response and neuromuscular dysfunction. This chapter reviews the various cell-based models used in MG research and those with potential for preclinical MG studies, including muscle cells and co-culture models to form neuromuscular junctions (NMJ). We discuss the strengths and limitations of these models, further outline methods for characterizing these, and provide an outlook on the future refinement and abilities of cell models for advancing MG research.", "authors": ["Huang Yu-Fang", "Verpalen Robyn L K", "Punga Anna Rostedt", "Huijbers Maartje G"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675732/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden. Electronic address: yu-fang.huang@uu.se."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40675731", "title": "Structure and function of the neuromuscular junction in health and myasthenia gravis.", "abstract": "The neuromuscular junction (NMJ) connects a motor neuron to a skeletal muscle cell. Cholinergic synaptic transmission enables muscle contraction, which is crucial for survival. Although synaptic communication at the NMJ is robust, with an inherent safety margin, it becomes hampered in the neuro-immunological disorder myasthenia gravis (MG). The synaptic dysfunction underlies the (fatigable) muscle weakness, which hallmarks this disease. In this chapter, we will review normal NMJ physiology and the pathophysiological consequences of autoimmune attacks in MG, focusing on recent insights and developments.", "authors": ["Plomp Jaap J", "Webster Richard G"], "journal": "International review of neurobiology", "entry_date": "2025/07/17 20:59", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40675731/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Leiden University Medical Centre, Leiden, The Netherlands. Electronic address: J.J.Plomp@lumc.nl."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 0.0, "journal_quartile": "3区"}, {"pmid": "40673289", "title": "Immune Checkpoint Inhibitor-Induced Myositis, Myocarditis, and Myasthenia Gravis Overlap Syndrome Following Nivolumab and Ipilimumab Combination Therapy in a 60-Year-Old Male With Metastatic Renal Cell Carcinoma.", "abstract": "Immune checkpoint inhibitors (ICIs) are in widespread use for the treatment of some metastatic cancers. While generally well tolerated, these agents can elicit a spectrum of unintended effects due to indiscriminate immune system activation. These side effects may impact multiple organs simultaneously and can become life-threatening if not promptly addressed. One complication of ICI therapy presents with a combination of myasthenia gravis (MG) symptoms and inflammation of both skeletal and cardiac muscles. This report describes a 60-year-old male with metastatic clear cell renal cell carcinoma on nivolumab and ipilimumab combination therapy post-nephrectomy who presented to our emergency department with fatigue and shortness of breath. Although he reported swallowing difficulties on further enquiry, other classic neuromuscular deficits were absent. The MG composite score was 5, and vital signs were stable. Initial creatine kinase and troponin T were 6,376 U/L and 1,694 ng/L, respectively, and the electrocardiograph (ECG) and echocardiogram were unremarkable. Magnetic resonance imaging (MRI) of the thighs and myocardium showed changes consistent with myositis and myocarditis, respectively. Although an autoantibody screen for MG was requested and later came back negative, the initial diagnosis of MG was clinical. The patient was treated with IV methylprednisolone, IV immunoglobulin, pyridostigmine, and mycophenolate (MMF). The decision to pursue an aggressive multi-pronged immunosuppressive strategy was to minimise the risk of rapid deterioration due to inadequate treatment in a patient with a good functional baseline. Symptoms resolved by the third day of admission, and laboratory markers continued to improve steadily. He was successfully discharged on reduced-dose oral prednisolone and MMF with a plan for outpatient follow-up with twice weekly CK, troponins, and ECG. ICIs were permanently discontinued. Myositis, myocarditis, and MG (MMM) overlap syndrome is an uncommon but potentially fatal immune-related adverse event (irAE) associated with ICI therapy and requires urgent medical attention. Clinicians should maintain a high index of suspicion for rapid diagnosis, as symptoms can be vague. Patient education is also strongly recommended for awareness, as the incidence will likely rise with the expanding use of ICIs. Early and aggressive immunosuppression may help prevent morbidity and mortality.", "authors": ["Ismail Umar"], "journal": "Cureus", "entry_date": "2025/07/17 05:46", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40673289/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Medicine, NHS Wales, Wales, GBR."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40670126", "title": "Thymoma without Myasthenia Gravis Showing Size Fluctuation in Parallel to Alopecia Areata Activity: A Case Report.", "abstract": "Thymomas are commonly associated with autoimmune diseases such as myasthenia gravis (MG), pure red cell aplasia, and hypogammaglobulinemia, while those associated solely with alopecia areata (AA) are extremely rare. A 55-year-old woman with AA underwent chest computed tomography, which revealed a 33-mm anterior mediastinal cystic mass with fluctuating size. She was referred to our department for evaluation of a suspected cystic thymoma. The patient underwent thoracoscopic tumor resection under general anesthesia with isolated lung ventilation in the left lateral decubitus position. The operation lasted 81 minutes with minimal blood loss, and her postoperative course was uneventful. Histopathology confirmed a type B2-dominant thymoma. Notably, the patient's AA improved rapidly after surgery and did not recur for at least 3 years. This case strongly suggests a potential immunological relationship between AA and thymoma, though further research is needed to confirm this relationship.", "authors": ["Fujimoto Keisuke", "Kenzaki Koichiro", "Kubo Takako", "Sawada Toru", "Norimura Shoko", "Miura Kazumasa", "Yamamoto Akiyoshi"], "journal": "Annals of thoracic and cardiovascular surgery : official journal of the Association of Thoracic and Cardiovascular Surgeons of Asia", "entry_date": "2025/07/16 21:24", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40670126/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Chest Medical Center, Takamatsu Red Cross Hospital, Takamatsu, Kagawa, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": "4区"}, {"pmid": "40669205", "title": "A case of silent myasthenia gravis with bilateral vocal cord paralysis' onset after thyroidectomy.", "abstract": "INTRODUCTION AND IMPORTANCE: Vocal cord paralysis is one of the most fearsome complications following thyroidectomy surgery. It can be unilateral or bilateral and in this case it could cause a life threatening respiratory distress which requires an emergency tracheostomy (1). Literature demonstrates a spontaneous recovery of vocal cord motility is possible in 79-87,5 % of the patients. Huge multinodular goiter that overturn the normal anatomy or an excessive bleeding that obscure the surgical field can make the intraoperative identification on both laryngeal nerves difficult. The tumoral invasion of the nerves following thyroid carcinoma could be a factor as well. For this reason the intra-operative nerve monitoring (IONM) is a great resource in this type of surgery.\nCASE PRESENTATION: We report the case of patient with bilateral laryngeal nerves paralysis after thyroidectomy with two failed extubating attempts which required the transfer to the intensive care unit. Two days after the patient was extubated and taken under O2 therapy. After a more detailed interview with the patient he reported a well-known history of exertional dyspnea which led to the suspect of latent form of Myasthenia gravis started to rise.\nCLINICAL DISCUSSION: The electromyography (EMG) resulted alternated so that the diagnosis of Myasthenia Gravis was confirmed. The patient started a therapy protocol with corticosteroids and Pyridostigmine with progressive improvements of the symptoms.\nCONCLUSION: In the suspect of a MG patient a careful preoperative evaluation as well as an appropriate intra-operative setting is demanded.", "authors": ["Donniacuo A", "Mezzedimi C", "Viberti F", "Salerni L", "Mandalà M", "Brindisi L"], "journal": "International journal of surgery case reports", "entry_date": "2025/07/16 18:03", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40669205/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["DSMCN University of Siena, Otolaryngology Department, Viale Bracci 16, 53100 Siena, Italy. Electronic address: nellodonniacuo@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 10.1, "journal_quartile": "2区"}, {"pmid": "40666682", "title": "Female gender and quality of life outcomes in myasthenia gravis: a systematic review and meta-analysis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a rare autoimmune neuromuscular disease characterized by fluctuating muscle weakness and a variable clinical course. While sex differences in MG onset and progression are well documented, the extent to which these disparities affect quality of life (QoL)-particularly through fatigue and psychological burden-remains unexplored.\nOBJECTIVES: To systematically evaluate gender differences in QoL among MG patients and assess whether psychological factors and fatigue contribute to these disparities.\nDESIGN: A systematic review and meta-analysis were conducted in accordance with Preferred Reporting Items for Systematic Review and Meta-Analyses guidelines.\nDATA SOURCES AND METHODS: Searches were performed in PubMed, Embase, and PsycINFO from inception through February 2025. Eligible studies included adult MG patients with QoL outcomes stratified by gender. QoL scores were synthesized using a random-effects model. Psychological and fatigue-related variables were examined qualitatively.\nRESULTS: Twelve studies (N = 4744; 2889 women, 1855 men) met the criteria for the systematic review, and five studies (N = 3765) were included in the meta-analysis. Women consistently reported lower QoL compared to men. The initial pooled analysis showed a moderate but non-significant effect (Hedges' g = 0.319, p = 0.0812; I² = 94.96%). Sensitivity analysis (excluding an outlier study) reduced heterogeneity (I² = 0%) and revealed a significant gender effect (Hedges' g = 0.440, p < 0.001), with women experiencing significantly poorer QoL. Psychological comorbidities-particularly depression and anxiety-and higher levels of fatigue were more prevalent among female patients and consistently associated with lower QoL.\nCONCLUSION: Women with MG experience significantly reduced QoL, partially attributable to higher fatigue and psychological burden. These findings underscore the need for gender-sensitive approaches in MG management, including routine psychological screening and fatigue interventions. Future research should adopt standardized assessment tools and explore the impact of hormonal life stages on MG outcomes.\nTRIAL REGISTRATION: PROSPERO CRD420251011446.\nGender differences affect quality of life in myasthenia gravis Researchers Beeching et al. conducted a systematic review and meta-analysis of the scientific literature, examining the quality of life (QoL) in patients with Myasthenia Gravis (MG), a rare neurological condition that causes muscle weakness and fatigue, making everyday activities more challenging. This study focused on gender differences in QoL and explored how psychological factors and fatigue, two key aspects that tend to affect women more than men, influence the quality of life in MG patients, offering a deeper understanding of gender-related differences. The results suggest that there are disparities in QoL between men and women with MG, with women reportedly experiencing lower QoL. However, the limited number of studies the researchers managed to include in the analysis prevents drawing any definitive conclusions. Very few studies also explored the role of psychological factors and fatigue in predicting QoL, but those that did found that both of these aspects had a negative impact on QoL in MG. Future studies should prioritize collecting gender-sensitive outcomes and using a standardized set of tools to assess QoL, fatigue, and psychosocial factors. This would enhance comparability, ensure more reliable data, and help establish a foundation for tailored psychotherapeutic interventions in MG.", "authors": ["Beeching Francesca", "Lecchi Alessandro", "Riccitelli Gianna Carla"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/07/16 05:32", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40666682/", "pub_types": ["Journal Article"], "affiliations": ["Non-Invasive Brain Stimulation Research Unit, Institute of Clinical Neuroscience of Southern Switzerland, Regional Hospital of Lugan-Civic (EOC), Lugano, Switzerland."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "40666538", "title": "Thymic hyperplasia in myasthenia gravis: a narrative review.", "abstract": "BACKGROUND AND OBJECTIVE: Thymic pathology is observed in approximately 80% of patients with acetylcholine receptor antibody-positive myasthenia gravis (AChR-MG). Among these thymic abnormalities, thymic follicular hyperplasia (TFH) is commonly associated with early-onset MG (EOMG). TFH is characterized by the presence of lymphoid follicles and germinal center (GC) formation, which are closely linked with the breakdown of tolerance to the AChR. GCs promote the development of autoreactive plasma cells that secrete autoantibodies against the AChR, contributing to the disease pathology. In this review, we examine current knowledge on thymic pathology in EOMG, immunological and environmental factors contributing to the development of thymic hyperplasia and highlight avenues for future research.\nMETHODS: A comprehensive literature search was conducted using PubMed without restriction on publication date. Articles were included if they discussed the function of the thymus, thymic pathology in MG, thymic hyperplasia in EOMG, or focused on cellular or molecular mechanisms associated with TFH in EOMG.\nKEY CONTENT AND FINDINGS: TFH is a hallmark of EOMG, characterized by GC formation and intrathymic production of AChR autoantibodies. The hyperplastic thymus exhibits heightened interferon (IFN) signaling, toll-like receptor (TLR) activation, altered chemokine expression, accumulation of B and T cells, and expression of AChR by thymic epithelial cells, creating a pro-autoimmune environment. Sex-related differences, particularly estrogen's effects on autoimmune regulator gene (AIRE) expression and immune tolerance, may contribute to the female predominance in EOMG. Emerging technologies such as single-cell and spatial transcriptomics, along with thymic organoid models, offer new avenues to study the mechanisms driving TFH.\nCONCLUSIONS: TFH reflects the convergence of immune dysregulation and structural abnormalities that together promote the loss of tolerance in EOMG. The interindividual variability in thymic pathology and treatment response underscores the need for more personalized therapeutic strategies. Advances in high-resolution profiling and experimental modeling will be essential to uncover the underlying drivers of thymic hyperplasia and to guide the development of targeted therapies for MG.", "authors": ["Sikorski Patricia M", "Kaminski Henry J", "Kusner Linda L"], "journal": "Mediastinum (Hong Kong, China)", "entry_date": "2025/07/16 05:31", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40666538/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology & Rehabilitation Medicine, George Washington University, Washington, DC, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "40666537", "title": "Intraoperative complications during robotic thymectomy and their management: a narrative review.", "abstract": "BACKGROUND AND OBJECTIVE: Complete thymectomy is the established treatment for thymic epithelial tumors (TET) and often included in the management of myasthenia gravis. Minimally invasive approaches, including robotic-assisted techniques, have gained acceptance for their benefits in reducing postoperative pain and recovery time. Thymectomy poses risks due to the proximity of the thymus to critical mediastinal structures, and intraoperative complications confronted on the robotic platform can be precarious. Current literature on intraoperative complications is fragmented and limited, and lacks emphasis on the nuance brought about by the robotic platform specifically. The aim of this narrative review is to comprehensively explore such possible complications and to discuss their distinct management strategies in a systematic manner.\nMETHODS: We review the literature by examining the PubMed database between 2000 and 2024 for relevant studies that report the intraoperative and postoperative complications of robotic thymectomy. The technique of robotic thymectomy is also described.\nKEY CONTENT AND FINDINGS: Robotic thymectomy offers a safe and oncologically effective approach to treatment. It is met with a low complication rate that is not increased compared to the open approach. Common complications include injury to nearby structures such as the internal mammary vessels, brachiocephalic vein (BCV), superior vena cava (SVC), phrenic nerve, and recurrent laryngeal nerve. Each complication requires a distinct management strategy that is concordant with an understanding of the limitations of the robotic platform.\nCONCLUSIONS: This narrative review focuses on the intraoperative complications encountered during robotic thymectomy and provides an in-depth review of strategies for managing these complications, emphasizing the importance of preoperative planning, understanding the robotic platform's limitations, and the need for a well-coordinated surgical team. Reviewing the complexity of such complications and their nuanced management strategies is not only beneficial for surgeons in their clinical practice, but also to develop scientific curiosities surrounding this topic to ultimately improve patient outcomes. As such, studies elaborating on the details of such complications while on the robotic platform are necessary.", "authors": ["Wathieu Natacha", "Ajouz Hana", "Abbas Abbas E"], "journal": "Mediastinum (Hong Kong, China)", "entry_date": "2025/07/16 05:31", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40666537/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Thoracic Surgery, Brown University Health Rhode Island Hospital/The Warren Alpert Medical School of Brown University, Providence, RI, USA."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI"}, {"pmid": "40664087", "title": "Potential relationship between MuSK-MG and autologous hematopoietic stem cell transplantation: a case report.", "abstract": "A 61-year-old woman developed anti-muscle-specific tyrosine kinase antibody positive myasthenia gravis (MuSK-MG) three years after autologous hematopoietic stem cell transplantation (HSCT) for multiple myeloma. Symptoms improved following methylprednisolone pulse therapy, intravenous immunoglobulin, plasma exchange, and the addition of efgartigimod. A review of the literature revealed that all four previously reported cases of myasthenia gravis after autologous HSCT were MuSK-MG, although none were positive for anti-acetylcholine receptor (AChR) antibodies. This frequency differs significantly from the reported incidence of MuSK-MG in the general population and in patients following allogeneic HSCT, suggesting a potential association between autologous HSCT and MuSK-MG. Hypothesized mechanisms include a paraneoplastic mechanism and changes of IgG4 production following immune reconstitution after autologous HSCT. We suggest that clinicians should be aware of this possibility and consider MuSK-MG in the differential diagnosis of neurological symptoms that arise after autologous HSCT, even though autologous HSCT can be used as a therapeutic option for MuSK-MG.", "authors": ["Sasaki Ryo", "Nakamura Ryoma", "Takahashi Yoshiaki", "Morimoto Mizuki", "Kubo Yukiko", "Morimoto Nobutoshi"], "journal": "Neuromuscular disorders : NMD", "entry_date": "2025/07/15 18:08", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40664087/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Kagawa Prefectural Central Hospital, Takamatsu, Kagawa, Japan. Electronic address: ryosasaki@okayama-u.ac.jp."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.7, "journal_quartile": "3区"}, {"pmid": "40661339", "title": "Mycobacterium abscessus Pulmonary Disease in a Myasthenia Gravis Patient: A Case Report.", "abstract": "There is limited guidance on managing Mycobacterium abscessus pulmonary disease in Myasthenia Gravis patients. Macrolides and aminoglycosides form the backbone of M. abscessus pulmonary disease treatment but are avoided in Myasthenia Gravis patients due to the risk of precipitating myasthenic crisis. A 29-year-old female, with a history of anti-acetylcholine receptor antibody-positive Myasthenia Gravis and bronchiectasis, was diagnosed with M. abscessus pulmonary disease. She was commenced on a macrolide-based regime safely with close monitoring, pretreatment with intravenous immunoglobulin (1 g/kg),10 mg prednisolone, 500 mg rituximab and augmentation of the neuromuscular junction with pyridostigmine and 3,4-Diaminopyridine. She was safely discharged to the hospital in the home program and achieved clinical, radiological and microbiological response.", "authors": ["Lu Daisy", "Tong Steven Y C", "Cruse Belinda", "Singh Kasha P", "Denholm Justin T", "Rees Megan"], "journal": "Respirology case reports", "entry_date": "2025/07/15 04:59", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40661339/", "pub_types": ["Journal Article"], "affiliations": ["Department of Respiratory and Sleep Disorders Medicine Royal Melbourne Hospital Melbourne Victoria Australia."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40660289", "title": "Impact of body mass index on clinical presentation and prognosis in myasthenia gravis.", "abstract": "BACKGROUND: The literature lacks consistent information on the correlation between baseline body mass index (BMI), clinical presentation, and prognosis in patients with myasthenia gravis (MG). This observational multicenter prospective cohort study included patients with MG from February 2017 to June 2023, categorizing them by baseline BMI. The primary outcome was the time to generalization of ocular MG. Secondary outcomes included the time to Activities of Daily Living (ADL) response and Minimal Symptom Expression (MSE). Kaplan-Meier curves and multivariable Cox proportional hazards regression models were used to assess the impact of BMI on these outcomes.\nRESULTS: Out of 940 MG patients (510 women) included, 524 had a low BMI and 416 had a high BMI, with a median age of 50.00 years. Patients in the high BMI group were significantly older (p < 0.001), had a lower percentage of females (p < 0.001), and had a shorter disease duration (p = 0.014) compared to those with a low BMI. They also had higher rates of ocular onset (p < 0.001), ocular MG classification (p = 0.001), and acetylcholine receptor antibody seropositivity (p = 0.007), but a lower incidence of thymectomy (p = 0.027). During a median follow-up of 33.00 months, the adjusted Cox models revealed that a higher baseline BMI was associated with an increased risk of ocular MG generalization (HR 1.06; 95% CI 1.01-1.11; p = 0.026), but not with ADL response (HR 0.99; 95% CI 0.95-1.04; p = 0.779) or MSE (HR 0.97; 95% CI 0.92-1.02; p = 0.240).\nCONCLUSIONS: A higher baseline BMI was associated with an increased risk of ocular MG generalization but not with ADL response or MSE.", "authors": ["Chen Hong-Xi", "Wang Zi-Ya", "Zhang Na-Na", "Lin Xue", "Shi Zi-Yan", "Wang Xiao-Fei", "Zhang Ying", "Du Qin", "Kong Ling-Yao", "Sun Dong-Ren", "Wang Rui", "Zhang Yang-Yang", "Li Shuang-Jie", "Da Yu-Wei", "Feng Hui-Yu", "Zhou Hong-Yu"], "journal": "Orphanet journal of rare diseases", "entry_date": "2025/07/14 23:46", "pub_date": "2025-07-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40660289/", "pub_types": ["Journal Article", "Observational Study", "Multicenter Study"], "affiliations": ["Department of Neurology, West China Hospital, Sichuan University, Guo Xue xiang #37, Chengdu, 610041, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.5, "journal_quartile": "2区"}, {"pmid": "40659410", "title": "Postmarketing adverse events of efgartigimod alfa: a real-world pharmacovigilance study based on the FAERS database.", "abstract": "OBJECTIVE: Efgartigimod alfa is an important novel drug for the treatment of myasthenia gravis. However, postmarketing safety data for this drug is limited, underscoring the need for comprehensive safety evaluations in real-world populations.\nDESIGN AND SETTING: This study aims to identify adverse event (AE) signals associated with efgartigimod alfa using the Food and Drug Administration Adverse Event Reporting System (FAERS) database, with a focus on evaluating unexpected AEs not previously observed in clinical trials. AE reports with efgartigimod alfa as the primary suspect from the first quarter of 2022 to the fourth quarter of 2023 were extracted.\nOUTCOME MEASURES: Signal strength was assessed using Reporting Odds Ratio, Proportional Reporting Ratio, Empirical Bayes Geometric Mean and Bayesian Confidence Propagation Neural Network methods at the Preferred Term level.\nRESULTS: A total of 1403 valid cases were retrieved. Urinary tract infection was the most reported AE, while procedural headache demonstrated the strongest signal across all four algorithms. Sepsis, atrial fibrillation and transient ischaemic attack were significant unexpected AEs. The median onset time for AEs was 57.00 days, with cumulative incidence of AEs reaching 37.31% at 30 days and 64.25% at 100 days post-treatment initiation.\nCONCLUSIONS: Our analysis of real-world data from the FAERS database revealed that most significant AEs were consistent with clinical trials, but some unexpected AEs were additionally identified, warranting further investigation.", "authors": ["Ju Yaxin", "Qin Xiaohong"], "journal": "BMJ open", "entry_date": "2025/07/14 20:53", "pub_date": "2025-07-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40659410/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The First Affiliated Hospital of Chongqing Medical University, Yuzhong, Chongqing, China."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "40658304", "title": "Weaning from mechanical ventilation in myasthenic crisis according to WEAN safe: most patients experience intermediate or prolonged weaning with no differences between early and late-onset compared to very-late onset myasthenia Gravis.", "abstract": "BACKGROUND: Myasthenic crisis often requires prolonged mechanical ventilation and complex weaning, yet data remain scarce. The objective of this study was to describe the weaning characteristics in patients with myasthenic crisis using the WEAN Safe classification. Secondary aims included assessment of long-term outcome and comparison between early- and late-onset (< 65 years) versus very-late-onset MG (≥ 65 years) myasthenia gravis.\nMETHODS: This single-center retrospective study included patients admitted for myasthenic crisis to a tertiary neuro-intensive care unit between January 2008 and December 2023. Clinical characteristics, ventilatory support parameters, timing of weaning events, complications, and outcomes were recorded. Weaning was classified according to WEAN Safe definitions: no separation attempt, short wean (successful weaning within 1 day), intermediate wean (2-6 days), prolonged wean (≥ 7 days), or failed wean (persistent invasive ventilation at discharge or death).\nRESULTS: Among 698 ICU hospitalizations (405 patients) for myasthenia gravis, 131 (120 patients) received invasive mechanical ventilation. Fifty hospitalizations (39 patients) were excluded due to non-MC-related intubation, insufficient weaning data or patients with multiple ICU admissions. The final analysis included 81 patients (median age 70 years [54-81]; 43% female; 64% with very-late-onset myasthenia gravis (≥ 65 years). The median duration of mechanical ventilation was 20 days [11-38], and the median time from the first separation attempt to successful weaning was 7 days [3-19]. According to the WEAN Safe classification, 3% had a short wean, 40% intermediate, 55% prolonged, and 3% failed weaning. Four patients (5%) required reintubation within 48 h. Ventilator-associated pneumonia occurred in 15% of patients before the first separation attempt. In multivariate analysis, the presence of thymoma (OR 3.02, 95% CI 1.01-9.07) and absence of MG-specific immunosuppressive treatment at ICU admission (OR 3.70, 95% CI 1.22-11.23) were independently associated with prolonged weaning. Intensive care unit mortality was 7%, and 12-month mortality was 19%. The median myasthenic muscle score at 1 year was 94/100 [80-100]. No significant differences in weaning parameters nor outcome were found between early- and late-onset versus very-late-onset MG, despite more comorbidities in the very-late-onset group.\nCONCLUSIONS: In this retrospective study from a single expert center, most patients with myasthenic crisis underwent intermediate or prolonged weaning, but extubation failure rate was very low. Thymoma and lack of MG-specific immunosuppressive treatment at ICU admission are associated with prolonged weaning, while age alone is not. Despite initial challenges, long-term outcomes are generally favorable, highlighting the reversibility of myasthenic crisis with expert care.", "authors": ["Marois Clémence", "Combes Arthur", "Bouguerra Meriem", "Grinea Alexandra", "Meglio Lucas Di", "Rambaud Thomas", "Guennec Loïc Le", "Bolgert Francis", "Rohaut Benjamin", "Demeret Sophie", "Weiss Nicolas"], "journal": "Annals of intensive care", "entry_date": "2025/07/14 11:18", "pub_date": "2025-07-14", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40658304/", "pub_types": ["Journal Article"], "affiliations": ["Sorbonne Université, AP-HP.Sorbonne Université, Hôpital de la Pitié-Salpêtrière, Médecine Intensive Réanimation à orientation neurologique, Paris, France. clemence.marois@aphp.fr."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 5.5, "journal_quartile": "1区"}, {"pmid": "40656929", "title": "Myasthenia Crisis as First Presentation of MuSk Positive Myasthenia Gravis: A Case Report.", "abstract": "We report a unique presentation of a 57-year-old female presented with severe respiratory acidosis, which was found to be a case of Musk-positive Myasthenia Gravis. Patient presented with depressed level of consciousness and respiratory failure, mandating urgent ventilatory support. She responded well with positive pressure ventilation. However, she persistently failed to maintain adequate ventilation after extubation and had to be reintubated. At presentation, the absence of classical symptoms typical of Myasthenia Gravis posed a diagnostic dilemma, initially obscuring the underlying etiology. However, since there was no other identifiable cause for the inability to maintain ventilation, antibody panels were sent which turned out positive for Muscle specific kinase. This case thus highlights the significance of considering atypical neuromuscular presentations, particularly when respiratory compromise is the predominant manifestation, highlighting the necessity for comprehensive neurological evaluation even in the absence of classical symptoms for timely diagnosis and management of Myasthenia Gravis.", "authors": ["Chhetri Dipesh", "Bhattarai Amit Sharma", "Joshi Pankaj", "Thapa Kriti"], "journal": "JNMA; journal of the Nepal Medical Association", "entry_date": "2025/07/14 07:55", "pub_date": "2025-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40656929/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Chirayu National Hospital and Medical Institute, Basundhara, Kathmandu, Nepal."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40656332", "title": "Magnesium Sulfate-Induced Ophthalmoplegia: A Rare Postnatal Complication.", "abstract": "Magnesium sulfate (MgSO4) is widely used in managing eclampsia, but its neurological side effects are often overlooked. A 25-year-old woman with a second gravida pregnancy developed eclampsia in her third trimester and underwent an emergency cesarean section. In the immediate postoperative period, she presented with bilateral ophthalmoplegia, ptosis, and neck flexion weakness, though her pupillary reflexes remained intact. Initial concerns included myasthenia gravis and Miller-Fisher syndrome, but further investigations, including repetitive nerve stimulation (RNS), acetylcholine receptor (AChR), and muscle-specific kinase (MuSK) antibody testing, were negative. Three Tesla MRI brains with constructive interference in steady state (CISS) sequences of III, IV, and VI were normal, and laboratory results revealed elevated serum magnesium levels (5.5 meq/L). A diagnosis of hypermagnesemia-induced ophthalmoplegia was confirmed, and MgSO4 therapy was promptly discontinued. Within 36 hours, her symptoms began to resolve, highlighting the transient yet significant neuromuscular effects of magnesium toxicity. This case underscores the importance of recognizing early signs of magnesium toxicity in postpartum patients receiving MgSO4 therapy. While mild hypermagnesemia can cause headache and diminished reflexes, severe cases may progress to muscle paralysis, respiratory failure, and even cardiac arrest. Ophthalmoplegia, though rare, should raise suspicion, prompting timely magnesium level monitoring and treatment adjustments. Withholding MgSO4 at the appropriate time can prevent further complications, ensuring safer management of eclampsia and postpartum neurological health.", "authors": ["Khandait Pranit", "Hatwar Himali"], "journal": "Cureus", "entry_date": "2025/07/14 07:47", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40656332/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neurology, Midas Multispeciality Hospital, Nagpur, IND."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40652498", "title": "Grace Face Sign in Generalized Myasthenia Gravis (MG).", "abstract": "", "authors": ["Shaik Reshma S", "Manorenj Sandhya"], "journal": "Neurology India", "entry_date": "2025/07/13 12:23", "pub_date": "2025-01-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40652498/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Princess Esra Hospital, Deccan College of Medical Sciences, Hyderabad, Telangana, India."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40651910", "title": "Opioid-Free and Green Anesthesia for Myasthenia Gravis: KeLiDex Infusion with Epidural Analgesia.", "abstract": "", "authors": ["Sandeep Gade", "Singha Subrata K", "Nazir Sharek Abdul", "Yadavalli Swetha"], "journal": "Journal of cardiothoracic and vascular anesthesia", "entry_date": "2025/07/12 21:58", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40651910/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["All India Institute of Medical Sciences, Raipur, India. Electronic address: sandeepgade96@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.1, "journal_quartile": "3区"}, {"pmid": "40651620", "title": "Myasthenia gravis with antibodies against the AChR, current knowledge on pathophysiology and an update on treatment strategies with special focus on targeting plasma cells.", "abstract": "Myasthenia gravis (MG) is an antibody-mediated autoimmune disorder where the neuromuscular transmission is impaired, causing symptoms of skeletal muscle weakness and fatigue. The presence of autoantibodies against the muscle nicotinic acetylcholine receptor (AChR) is the most prevalent cause of MG. Abnormalities in the thymus are common in AChR-MG, and thymectomy has proven to be therapeutically beneficial. Up to 30 % of AChR-MG patients have also thymoma. Moreover, patients with thymoma without MG are more prompt to develop MG compared to the general population. Autoantibodies in AChR-MG damage the postsynaptic membrane of the neuromuscular junction (NMJ) and cause muscle weakness by impairing synaptic transmission because of the depletion of the AChRs and destruction of the NMJ. The pathogenic autoantibody levels vary greatly between patients. In contrast, in individual patients changes in autoantibody levels correlate well with disease severity. A small selection of patients has been used to exemplify the individual relationship between autoantibody levels and disease progression. The study of the effector functions of the autoantibodies and the compensatory mechanisms at the NMJ are important to select the best treatment strategy for each patient. Even though classical immunomodulatory treatments are effective in many patients, around 10-20 % of patients do not respond to current therapies. This may be attributed to the production of autoantibodies by different circulating cells including mature B and long-lived plasma cells, which are resistant to most commonly used immunosuppressive drugs. Hence, novel therapies specifically targeting plasma cells might be a suitable therapeutic approach for selected refractory patients.", "authors": ["Mané-Damas M", "Schöttler A K", "Marcuse F", "Molenaar P C", "Mohile T", "Hoeijmakers J G J", "Hochstenbag M", "Damoiseaux J", "Maessen J G", "Abdul-Hamid M", "Zur Hausen A", "de Baets M H", "Losen M", "Martinez-Martinez P"], "journal": "Autoimmunity reviews", "entry_date": "2025/07/12 19:34", "pub_date": "2025-09-24", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40651620/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Psychiatry and Neuropsychology, Mental Health and Neuroscience Research Institute, Faculty of Health, Medicine and Life Sciences, Maastricht University, Maastricht, the Netherlands."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40651295", "title": "N-type voltage-gated calcium channel antibody testing lacks diagnostic value in Lambert-Eaton myasthenic syndrome.", "abstract": "INTRODUCTION/AIMS: Diagnostic evaluation for Lambert-Eaton myasthenic syndrome (LEMS) includes serological testing for voltage-gated calcium channel antibodies (VGCC-P/Q-type [VGCC-PQ] and VGCC-N-type [VGCC-N]). While VGCC-PQ antibodies are well-established biomarkers in LEMS, the clinical utility of VGCC-N antibody testing remains obscure. We aimed to determine the diagnostic value of VGCC-N antibody testing.\nMETHODS: A retrospective cross-sectional study was performed. The Mayo Clinic electronic medical record from 1995 to 2021 was reviewed for inclusion of patients fitting clinical electrodiagnostic criteria for LEMS, who were evaluated for serum VGCC antibodies (n = 123). Available sera were additionally tested for SOX1 antibodies (n = 68). Healthy adults were tested for VGCC-PQ and VGCC-N antibodies (n = 122). Clinical performance of each antibody test was evaluated statistically.\nRESULTS: Among adult LEMS cases, 84.6 % (n = 99/117) tested positive for VGCC-PQ antibody while none of the healthy controls did. In contrast, 20.5 % (n = 24/117) were VGCC-N antibody positive, of which 95.8 % (n = 23/24) co-occurred with VGCC-PQ antibodies. The frequency of isolated VGCC-N antibody positivity was higher in controls than in LEMS (2.5 % [n = 3/122] vs. 0.9 % [n = 1/117]), and pediatric patients had no VGCC-N antibody reactivity. Neither VGCC-N antibody positivity nor titer was predictive of an associated small-cell lung cancer (SCLC-LEMS). By contrast, SOX1-IgG seropositivity associated significantly with SCLC-LEMS.\nDISCUSSION: Inclusion of VGCC-N antibody testing does not improve diagnostic accuracy for LEMS, nor does it serve as a predictor of LEMS-associated cancers in contrast to SOX1-IgG testing. We recommend the exclusion of VGCC-N antibody testing given its non-specific disease associations and poor positive predictive value in LEMS screening.", "authors": ["Arlt Friederike A", "Majed Masoud", "Wu Jack", "Zekeridou Anastasia", "Shelly Shahar", "Lennon Vanda A", "Pittock Sean J", "McKeon Andrew", "Klein Christopher J", "Dubey Divyanshu", "Mills John R"], "journal": "Journal of neuroimmunology", "entry_date": "2025/07/12 18:10", "pub_date": "2025-09-15", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40651295/", "pub_types": ["Journal Article"], "affiliations": ["Department of Laboratory Medicine and Pathology, Mayo Clinic, Rochester, MN, United States of America."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 2.5, "journal_quartile": "4区"}, {"pmid": "40649780", "title": "Perspectives on the Parathyroid-Thymus Interconnection-A Literature Review.", "abstract": "The parathyroid and thymus glands are key components of the endocrine and immune systems, respectively, with intriguing developmental, anatomical, and functional interrelationships. This study starts from the hypothesis that, given their shared embryological origin, it is plausible that the thymus and parathyroid glands interact functionally and may share pathological pathways. The present study explores the developmental pathways, spatial proximity, and potential cross-talk between these glands. Recent studies suggest that parathyroid hormone (PTH) may influence thymic function, including T-cell maturation and immune regulation, while thymic signaling molecules could impact calcium homeostasis and parathyroid activity. Understanding the functional and etiopathogenical relations between these endocrine glands offers new insights into endocrine-immunological crosstalk, and therapeutic approaches targeting disorders such as hypoparathyroidism, thymomas, myasthenia gravis and thymic hypoplasia. Perspectives and conclusion: Future research is essential to discover the molecular mechanisms underpinning this dynamic interrelation and its broader implications for health and disease. Because there is still very little data on this interaction, in-depth studies are necessary on large groups of patients. This research proposes a cross-study of the receptors for the main substances secreted by the two categories of endocrine glands. At the same time, it is essential to carry out an in-depth study on the cervico-pericardial ligaments through the lens of this glandular interaction. These ligaments could contain the main blood and nerve communication pathway between the parathyroids and the glands.", "authors": ["Comănescu Maria-Paula", "Boișteanu Otilia", "Hînganu Delia", "Hînganu Marius Valeriu", "Grigorovici Roxana", "Grigorovici Alexandru"], "journal": "International journal of molecular sciences", "entry_date": "2025/07/12 01:20", "pub_date": "2025-06-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40649780/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Surgery I, Faculty of Medicine, Grigore T.Popa University of Medicine and Pharmacy, University Street No. 16, 700115 Iași, Romania."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.9, "journal_quartile": "3区"}, {"pmid": "40647363", "title": "Management of Triple M Syndrome: A Narrative Review of Immune Checkpoint Inhibitor-Induced Myasthenia Gravis, Myositis and Myocarditis.", "abstract": "Background: The advent of immunotherapy has revolutionised cancer treatment by harnessing the immune system to target tumour cells. However, there is increasing awareness of immunotherapy-related adverse events, which can be severe and even fatal. While system-specific immune-related adverse events (ir-AEs) are well documented, growing evidence suggests the existence of overlap syndromes-distinct clusters of immune-mediated complications. One such syndrome is the overlap of myasthenia gravis, myositis and myocarditis, collectively known as Triple M (3M) syndrome. This syndrome is complex, varying in presentation and severity, with in-hospital mortality rates approaching 40%. Whilst there is consensus on the management of system-specific complications, there is no consensus guidance for the management of these overlap syndromes. Methods: In this paper, we conduct a review of the literature, analysing reported cases of 3M syndrome, focusing on treatment approaches and patient outcomes at an individual level. Conclusions: This review highlights the complexity of diagnosing and managing 3M syndrome due to inconsistent reporting, lack of standardised criteria for diagnosis, and treatment variability. While evidence remains limited, we offer broad clinical recommendations and underscore the urgent need for consensus definitions, prospective data collection, and structured treatment guidance.", "authors": ["Furlepa Martin", "Watts Isabella", "Carr Aisling S"], "journal": "Cancers", "entry_date": "2025/07/12 01:07", "pub_date": "2025-06-20", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40647363/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, University College Hospital, London NW1 2BU, UK."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.4, "journal_quartile": "2区"}, {"pmid": "40645888", "title": "Patient perspectives on Lambert-Eaton myasthenic syndrome.", "abstract": "To better understand what it's like to live with Lambert-Eaton myasthenic syndrome (LEMS), we spoke to two individuals who have been living with non-tumor LEMS for years. They graciously shared stories that shed light on the day to day impact of this rare condition extending from mobility and daily functioning to identity, relationships, and mental health. In sharing their experiences, they also offered insights and advice for others newly diagnosed with LEMS or managing its challenges long-term.", "authors": ["Randall Matthew C"], "journal": "Disease-a-month : DM", "entry_date": "2025/07/11 22:01", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40645888/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["SUNY Upstate Medical University, 750 E Adams St, Syracuse, NY, 13210, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "40645852", "title": "Effect of Intravenous Immunoglobulin or Plasmapheresis in Myasthenic Crisis and Worsening Myasthenia Gravis Compared to Without Rescue Treatment.", "abstract": "PURPOSE: There is a paucity of studies on intravenous immunoglobulin (IVIg)/plasmapheresis (PLEX) compared with no rescue treatment (NRT) in myasthenic crisis (MC) and worsening myasthenia gravis (WMG). We report the efficacy of RTs (IVIg and PLEX) compared with NRT in MC/WMG.\nMETHODS: Patients with MC and those having worsening in the MG Foundation of America classification by ≥2 grades were included. Their clinical findings, precipitating causes, and MG Activity of Daily Living (MGADL) and MG Quality of Life (MGQoL)-15 scores were noted. Patients were either treated with IVIg (400 mg/kg/d for 5 days) or PLEX (20-25 mL/kg × 5 sessions), and nonaffording patients received only standard care. The primary outcome was improvement in MG Foundation of America classification by ≥2 grades, and the secondary outcomes included MG Activity of Daily Living score, MG Quality of Life-15 score, Myasthenia Muscle Score, and days of mechanical ventilation (MV), hospital stay, and reaching pre-worsening status at 1 month.\nFINDINGS: Forty-four patients were included; 19 had MC and 25 had WMG. They were treated for MG for 2 to 19 years. Forty-one (93.2%) patients achieved the primary end point; 22 (95.7%) in RT and 19 (90.5%) in NRT (P = 0.60). The overall odds ratio of RT for the primary outcome was 1.20 (95% CI, 0.70-23.50; P = 0.13). The RT group had an overall hazard ratio of 0.93 (95% CI, 0.37-2.40; P = 0.96) for duration of MV, had hospital stay of 0.78 days (95% CI, 0.34-1.94; P = 0.80), and achieved pre-worsening MG status in 0.99 days (95% CI, 0.40-2.40; P = 0.72) compared with NRT after adjusting for age, triggers, dose of acetylcholine esterase inhibitors (AChEIs), and azathioprine at baseline. PLEX had an edge over IVIg in reducing the duration of MV and hospital stay, but overall hazard ratio was not significant. The RT group, however, required a lower dose of AChEIs (P = 0.04). Ten patients had mild adverse effects.\nIMPLICATIONS: All the patients with MC and WMG improved irrespective of RT or NRT, and the RT group required a lower dose of AChEIs at 1 month. A multicenter randomized controlled trial may confirm these observations.", "authors": ["Kalita Jayantee", "Gutti Nagendra B", "Ahamed Faim", "Mahajan Roopali", "Singh Varun Kumar"], "journal": "Clinical therapeutics", "entry_date": "2025/07/11 21:59", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40645852/", "pub_types": ["Journal Article", "Comparative Study"], "affiliations": ["Department of Neurology, Sanjay Gandhi Post Graduate Institute of Medical Sciences, Lucknow, India. Electronic address: jayanteek@yahoo.com."], "china_related": false, "study_types": ["Historical Control"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "40643637", "title": "[Treatment of neuroimmunological diseases with chimeric antigen receptor (CAR) T cells : Experience and new developments].", "abstract": "BACKGROUND: Chimeric antigen receptor (CAR) T cell therapies were originally developed for the treatment of hematological malignancies; however, they are gaining increasing importance in the treatment of selected individuals with severe, treatment-refractory courses of neuroimmunological diseases. This article discusses the available treatment experiences to date and the potentially promising biotechnological developments in the context of the underlying neuroimmunological pathophysiology.\nOBSERVATIONS: The spectrum of immunopathology in neuroimmunological diseases ranges from classical autoantibody-mediated autoimmune diseases, such as myasthenia gravis to immunologically complex conditions like multiple sclerosis. The CAR T cell products currently in use target B cells, leading to complete B cell depletion, including autoreactive B cell clones. The therapeutic response, measured by disease activity and biomarkers, varies depending on the underlying immunopathology. The use of CAR T cells in different disease entities has shown a favorable safety profile concerning acute toxicity.\nCONCLUSION: Currently available and emerging CAR T cell therapy approaches open new therapeutic perspectives for neuroimmunological diseases. Larger studies are needed to assess safety, efficacy and long-term effects and to identify individual disease courses that may be suitable for the application of these forms of treatment.\nZUSAMMENFASSUNG: HINTERGRUND: CAR(chimärer Antigenrezeptor)-T-Zell-Therapien wurden ursprünglich zur Behandlung hämatologischer Neoplasien entwickelt. Jedoch gewinnen sie zunehmend an Bedeutung in der Behandlung ausgewählter Personen mit schweren, therapierefraktären Verläufen neuroimmunologischer Erkrankungen. In diesem Beitrag werden die bisher gewonnenen Behandlungserfahrungen und die möglichen richtungsweisenden biotechnologischen Entwicklungen im Kontext der zugrunde liegenden neuroimmunologischen Pathophysiologie diskutiert.\nBEOBACHTUNGEN: Das Spektrum der Immunpathologie neuroimmunologischer Erkrankungen reicht von klassischen Autoantikörper-vermittelten Autoimmunerkrankungen wie Myasthenia gravis zu immunologisch komplexen Erkrankungen wie der multiplen Sklerose. Die bisher in der Anwendung befindlichen CAR-T-Zell-Produkte sind gegen B‑Zellen gerichtet und führen zur vollständigen B‑Zell-Depletion einschließlich autoreaktiver B‑Zell-Klone. Das Therapieansprechen, gemessen an Erkrankungsaktivität und Biomarkern, variiert entsprechend der zugrunde liegenden Immunpathologie. Die Anwendung von CAR-T-Zellen in verschiedenen Erkrankungsentitäten zeigte ein gutes Sicherheitsprofil in Bezug auf Akuttoxizität.\nSCHLUSSFOLGERUNG: Aktuell verfügbare und in Entwicklung befindliche CAR-T-Zell-Therapieansätze eröffnen neue therapeutische Perspektiven für neuroimmunologische Erkrankungen. Größere Studien sind erforderlich, um Sicherheit, Wirksamkeit und langfristige Auswirkungen zu bewerten und individuelle Krankheitsverläufe zu identifizieren, die sich für die Anwendung dieser Therapieformen eignen.", "authors": ["Fischbach Felix", "Pfeffer Lena Kristina", "Heesen Christoph", "Friese Manuel A"], "journal": "Zeitschrift fur Rheumatologie", "entry_date": "2025/07/11 11:14", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40643637/", "pub_types": ["English Abstract", "Journal Article", "Review"], "affiliations": ["Klinik und Poliklinik für Neurologie, Universitätsklinikum Hamburg-Eppendorf, Hamburg, Deutschland. f.fischbach@uke.de."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40642632", "title": "Univent tube for thoracoscopic thymectomy in myasthenic patients anesthetized without neuromuscular blocking agents: An observational study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) patients undergoing surgery may opt for general anesthesia without neuromuscular blocking agents (NMBAs). The univent tube, featuring a single lumen with bronchial blockers, is known for its flexibility and preference in challenging intubations, reducing airway damage during one-lung ventilation. This study assesses the safety and feasibility of utilizing the univent tube for thoracoscopic thymectomy in MG patients under general anesthesia without NMBAs, complemented by airway topical anesthesia.\nMETHODS: In this single-center, prospective observational study, 83 consecutive MG patients underwent thoracoscopic thymectomy with univent tube intubation. General anesthesia without NMBAs and airway topical anesthesia were administered. Emphasis was placed on intubation conditions, surgical aspects, intraoperative respiratory, and airway complications.\nRESULTS: Clinically acceptable intubation conditions were achieved in 99% of patients, with 80% rated as 'excellent' and 19% as 'good.' No cases experienced intubation failure, and 2% exhibited reactions to tracheal tube insertion. Higher MG stages correlated with more favorable intubation conditions, particularly during laryngoscopy. Surgical conditions were excellent in 89%, and blocking the right lung increased total lung collapse, enhancing surgical conditions. Intraoperative ventilation was sufficient for all cases. Incidences of bronchial and vocal cord injuries were 6% and 10%, respectively, with no hematoma cases. Postoperative sore throat (12%) and hoarseness (6%) resolved within three days.\nCONCLUSIONS: Despite the potential benefits of NMBAs, the univent tube proved safe and effective for thoracoscopic thymectomy in MG patients without NMBAs, with higher MG stages associated with improved intubation conditions and enhanced surgical conditions with right-side bronchial blockage.", "authors": ["Hien Vo Van", "Tu Nguyen Huu", "Thu Nguyen Dang"], "journal": "Saudi journal of anaesthesia", "entry_date": "2025/07/11 05:20", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40642632/", "pub_types": ["Journal Article"], "affiliations": ["Department of Anesthesiology, Military Hospital 103, Vietnam Military Medical University, Ha Dong District, Hanoi, Vietnam."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "40641501", "title": "True Thymic Hyperplasia: An Extremely Rare Incidental Finding.", "abstract": "Thymic hyperplasia is a rare and benign cause of mass in the anterior mediastinum in adults. This pathology is characterized by an increase in the size and weight of the thymus while preserving its architecture and histology. In most cases, it is asymptomatic, and routine imaging exams are used to make the diagnosis. Thymic hyperplasia can be divided into reactive and true hyperplasia based on morphological characteristics. The main differential diagnosis of this pathology is thymoma, an epithelial neoplasm of the thymus. True thymic hyperplasia is the rarest subtype, and, unlike reactive or lymphofollicular, it does not present histologically with lymphoid follicles and is not associated with autoimmune diseases, such as myasthenia gravis and Graves' disease. Here we present the case of an adult patient with thymic hyperplasia incidentally diagnosed in imaging exams. The established treatment was complete surgical resection, which is indicated as the first-line treatment. Subsequent histopathological analysis confirmed a diagnosis of true thymic hyperplasia.", "authors": ["Salvado de Carvalho Inês", "Baldo Maria João"], "journal": "Cureus", "entry_date": "2025/07/11 05:03", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40641501/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Hospital Sousa Martins, Unidade Local de Saúde da Guarda, Guarda, PRT."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40639531", "title": "Measuring efficacy for myasthenia gravis treatments: A review of biomarkers used in clinical trials.", "abstract": "Myasthenia gravis is an autoimmune disease that impairs neuromuscular transmission through autoantibodies, most commonly targeting acetylcholine receptors (AChR). While clinical scores like the Quantitative Myasthenia Gravis Score (QMGS) and the Myasthenia Gravis Activities of Daily Living Scale (MG-ADL) are commonly used in trials, there is no gold standard biomarker for evaluating treatment efficacy. This scoping review aimed to identify which biomarkers are most frequently used in randomized controlled trials (RCTs) for non-surgical treatments of generalized myasthenia gravis. We searched five databases for English-language RCTs published before May 9, 2024. Of 6685 screened texts, 33 met inclusion criteria. A total of 33 distinct biomarkers were tracked across studies, with AChR antibodies, IgG, and IL-2 most frequently reported. Biomarkers were measured inconsistently and at varied intervals, limiting cross-study comparability. The lack of standardized biomarker use hinders the ability to assess treatment efficacy and perform meta-analyses. We recommend developing consensus guidelines to improve future trial quality.", "authors": ["Wesley Taylor", "Rose Callie", "Ding Jessica", "Parkin Kirstin"], "journal": "Clinical immunology (Orlando, Fla.)", "entry_date": "2025/07/10 19:33", "pub_date": "2025-11", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40639531/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Michigan State University College of Human Medicine, 804 Service Rd Suite A112, East Lansing, MI 48824, USA. Electronic address: wesleyta@msu.edu."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.0, "journal_quartile": "2区"}, {"pmid": "40636272", "title": "Successful Management of Immune-Mediated Myelitis in a Renal Cancer Patient: A Case Report.", "abstract": "INTRODUCTION: Immune checkpoint inhibitors (ICIs) have revolutionized metastatic renal cell carcinoma treatment, significantly improving survival outcomes. However, ICIs are linked to immune-related adverse events (irAEs), which can impact multiple organs. Neurological irAEs, such as myelitis, are rare but potentially severe.\nCASE PRESENTATION: We describe a 54-year-old male with high-grade clear cell renal carcinoma treated with nivolumab and ipilimumab. After four cycles, he developed hypophysitis, adrenal insufficiency, and hypothyroidism, managed with hydrocortisone and levothyroxine, while continuing nivolumab monotherapy. In August 2022, he experienced right eyelid ptosis and right hand weakness. Cranial magnetic resonance imaging (MRI) showed improvement in the sellar lesion, and chronic sensorimotor polyneuropathy was diagnosed, ruling out myasthenia gravis. Nivolumab treatment continued. By December 2022, after seven cycles, the patient developed back pain and dysesthesias, with MRI confirming transverse myelitis from C7 to T3. Nivolumab was discontinued, and high-dose corticosteroids (1 g methylprednisolone daily for 5 days) led to clinical improvement. A 12-week taper followed, with no symptom recurrence. Disease progression in April 2023 led to a switch to pazopanib, maintaining a partial response for 6 months.\nCONCLUSION: This case emphasizes the serious nature of neurological irAEs from ICIs and the critical need for early detection and management. It also highlights the increased risk of subsequent irAEs after an initial event, underscoring the importance of vigilant monitoring.", "authors": ["Payá Paula Rodríguez", "Abad Álvaro Muñoz", "Mirete Beatriz Grau", "Arias Asia Ferrández", "Rivilla Miguel Borregón", "Benítez Fuentes Javier David", "Vázquez Mazón Federico J"], "journal": "Case reports in oncology", "entry_date": "2025/07/10 05:01", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40636272/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Medical Oncology, Hospital General Universitario de Elche, Elche, Spain."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.7, "journal_quartile": "4区"}, {"pmid": "40636243", "title": "Good's Syndrome Revealed by Recurrent Sigmoid Diverticulitis.", "abstract": "UNLABELLED: Thymus is a primary lymphoid organ whose main function is the education of the T lymphocytes. Thymoma is uncommon neoplasia derived from epithelial cells of the thymus. Patients with thymoma frequently present with autoimmune disorders, mostly myasthenia gravis. Good's syndrome (GS) is an acquired adult-onset combined immunodeficiency typically characterised by the triad of thymoma, hypogammaglobulinaemia and increased susceptibility to recurrent infections. Immunoglobulin replacement is the main therapeutic strategy. Our knowledge of thymoma-associated immunodeficiency is predominantly derived from case reports or small series. We report the case of a patient with recurrent sigmoid diverticulitis that appeared after a thymectomy, who was subsequently found to have severe hypogammaglobulinaemia.\nLEARNING POINTS: Good's syndrome is a rare, acquired, adult-onset immunodeficiency.Good's syndrome remains an enigmatic disease.Immunoglobulin replacement is the main therapeutic strategy.", "authors": ["Attout Hassene", "Constant Jade", "Abdellatif Amal", "Barry Guillaume", "Halle Olivier"], "journal": "European journal of case reports in internal medicine", "entry_date": "2025/07/10 05:01", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40636243/", "pub_types": ["Journal Article"], "affiliations": ["Internal Medicine Department, Les Cevennes Hospital, Alès, France."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40636113", "title": "Case Report: Immune checkpoint inhibitor-induced myositis without elevated creatine kinase.", "abstract": "Immune checkpoint inhibitors (ICIs) have revolutionized the treatment of advanced cancers like malignant melanoma. However, they can lead to a range of immune-related adverse events (irAEs), impacting various organ systems. Among these, myositis is a rare but serious irAE, typically characterized by myalgia, muscle weakness, and elevated creatine kinase (CK) levels. Herein, we report the case of a 58-year-old female with advanced melanoma, who presented a delayed-onset of ICI-induced myositis accompanied by severe muscle weakness. Interestingly, the CK levels remained normal throughout her disease course. Neurological examination, MRI, and electromyography were pivotal in diagnosing myositis. Differential diagnoses, including myasthenia gravis, myocarditis, and paraneoplastic syndromes or idiopathic inflammatory myopathies, were systematically ruled out through clinical evaluation, serological testing, and imaging. The patient responded favorably to high-dose corticosteroid therapy, leading to a gradual improvement of symptoms and no relapse after stopping treatment. This case report emphasizes a multimodal diagnostic approach and underscores the importance of clinical awareness for such atypical irAE presentations.", "authors": ["Begaj Klajdi", "Wilhelm Raphael", "Lepper Alisa", "Kaufhold Maike", "Veeser Jakob", "Grabbe Stephan", "Stege Henner"], "journal": "Frontiers in immunology", "entry_date": "2025/07/10 05:00", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40636113/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Dermatology, University Medical Center of the Johannes Gutenberg University, Mainz, Germany."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40635622", "title": "COVID-19 Vaccination and Infection in Myasthenia Gravis: A Longitudinal Patient Survey.", "abstract": "INTRODUCTION/AIMS: Patients with myasthenia gravis (MG) often receive immunosuppressive treatments. While approved COVID-19 vaccines effectively prevent severe infections, the impact of vaccination among immunocompromised MG patients remains unclear. This study explored vaccination status, adverse events, and post-vaccination outcomes among MG patients.\nMETHODS: A REDCap survey was conducted between September 21, 2021 and November 18, 2021 through the Myasthenia Gravis Foundation of America to collect data on demographic and disease characteristics, COVID-19 infections, vaccination status, and precaution strategies. A follow-up survey was available from January 11, 2022 to March 8, 2022.\nRESULTS: A total of 1205 participants [65.7% female, average age 59.6 ± 15.4 years] completed the survey. Most were White or Caucasian (87.9%), 63.6% held a bachelor's degree or higher, and 41.9% were retired. Acetylcholine receptor (AChR) antibody positivity was reported by 47%, MuSK-Ab positivity by 6.1%, and 19.6% were seronegative. Most (75%) were on immunosuppressive therapy, and the vaccination rate was 91.5%. Among COVID-19 vaccine recipients, 61.5% reported adverse effects, while 8.5% of participants remained unvaccinated due to concerns about side effects (65%) and potential worsening of MG symptoms (70.9%). Post-vaccination COVID-19 infection rates dropped from 9.7% to 2.4%. Hospitalization decreased from 2.3% to 0.3%, and MG exacerbation rates from 5.5% to 1.4%.\nDISCUSSION: COVID-19 vaccination acceptance is high among MG patients. Reported side effects in MG patients were comparable to those in the general population, and vaccination was associated with a reduced COVID-19 infection rate. Addressing concerns about vaccine side effects and providing efficacy data specific to MG could aid unvaccinated individuals in decision-making.", "authors": ["Li Yingkai", "Muppidi Srikanth", "Unnithan Shakthi", "Al-Khalidi Hussein R", "Masterson Samantha", "Huff Wendi", "Juel Vern C", "Guptill Jeffrey T", "Raja Shruti M"], "journal": "Muscle & nerve", "entry_date": "2025/07/10 04:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40635622/", "pub_types": ["Journal Article"], "affiliations": ["Neuromuscular Division, Department of Neurology, Duke University Medical Center, Durham, North Carolina, USA."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 3.1, "journal_quartile": "3区"}, {"pmid": "40634627", "title": "Familial myasthenia gravis: characterization of an Israeli cohort and systematic review of the literature.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction, most commonly associated with autoantibodies against the acetylcholine receptor (AChR). While familial clustering of autoimmune MG (fMG) has been described, its prevalence and clinical characteristics remain uncertain. This study aimed to characterize autoimmune fMG cases in an Israeli cohort and describe global data through a systematic literature review.\nMETHODS: We retrospectively analyzed the medical records of MG patients treated at Rabin Medical Center from 2000 to 2022. The clinical and demographic features of autoimmune fMG cases-defined by compatible clinical, serological, and electrophysiological features-were compared to those of sporadic MG. Additionally, a systematic review of published autoimmune fMG cases was performed according to PRISMA guidelines.\nRESULTS: Among 281 MG patients, 16 patients (5.7%) from eight families met criteria for autoimmune fMG. Compared to sporadic MG, fMG cases had a significantly younger age of onset (median 44.5 vs. 58 years, p = 0.04) and more frequently presented with severe generalized disease (MGFA class IV-V, 43.8% vs. 15%, p = 0.008). The antibody profiles, sex distribution, ocular involvement, and comorbid autoimmune diseases did not differ significantly. All fMG patients responded to immunotherapy. The systematic review identified 73 additional fMG cases, with similar trends toward earlier onset and generalized presentation. Patients with fMG in our cohort had higher rates of severe initial presentation (43.8% vs. 16.4%, p = 0.03) and underwent thymectomy less frequently (19% vs. 49.3%, p = 0.03).\nCONCLUSIONS: Autoimmune familial MG occurs in 5-6% of MG cases and is associated with a younger onset and more severe initial presentation compared to sporadic MG, but shows similar long-term treatment response. These findings suggest that genetic factors may contribute to disease susceptibility and phenotypic expression in familial MG, highlighting the need for further research into the underlying genetic and immunological mechanisms.", "authors": ["Hellmann Mark A", "Steiner Israel", "Mermelstein Maor", "Friedman Itzhak", "Wilf-Yarkoni Adi", "Lotan Itay"], "journal": "Journal of neurology", "entry_date": "2025/07/09 23:35", "pub_date": "2025-07-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40634627/", "pub_types": ["Journal Article", "Systematic Review"], "affiliations": ["Department of Neurology, Rabin Medical Center, Beilinson Hospital, Beilinson Campus, 49100, Petach Tikva, Israel."], "china_related": false, "study_types": ["Systematic Review"], "evidence_level": "I", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "40631640", "title": "Unmasking Anti-CASPR2 Syndrome in a Patient Treated for Myasthenia Gravis in the Era of New Treatments.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder characterised by autoantibodies against the acetylcholine receptor (AChR-Ab). Morvan syndrome (MoS) is a rarer autoimmune disease with neuromyotonia, dysautonomia and encephalopathy, associated with antibodies targeting contactin-associated protein-like 2 (CASPR2) and may coexist with MG, particularly in patients with thymoma.\nCASE REPORT: A 57-year-old man with AChR-Ab MG was treated with pyridostigmine and prednisone for one year and then presented with a severe exacerbation. The symptoms were not controlled despite intravenous immunoglobulins and plasmapheresis. Chest CT revealed a thymoma. Zilucoplan (a C5 complement inhibitor) was started, with rapid improvement. Efgartigimod (a neonatal Fc receptor (FcRn) antagonist) was added to stabilise residual symptoms prior to thymectomy. Three weeks after the third and final efgartigimod cycle, the patient had no symptoms of MG but began to develop profuse sweating, then generalised hypertonia, fasciculations, myoclonus and dysautonomia, consistent with MoS, which were confirmed by the presence of anti-CASPR2 antibodies. Symptoms improved markedly after resumption of efgartigimod.\nCONCLUSION: This case provides the first evidence of the efficacy of efgartigimod in the treatment of MoS and suggests that FcRn inhibition may be beneficial in IgG4-mediated disorders beyond MG. It also highlights the importance of considering coexisting autoimmune conditions in thymoma, particularly when new symptoms occur under selective immune modulation. Finally, it emphasises the need to understand immunopathological mechanisms when choosing immunomodulatory treatment.", "authors": ["Fabry Vincent", "Rual Celso", "Bost Chloé", "Acket Blandine", "Maquet Julien", "Cintas Pascal"], "journal": "European journal of neurology", "entry_date": "2025/07/09 07:33", "pub_date": "2025-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40631640/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Neurology, Toulouse University Hospital, Toulouse Cedex 9, France."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40630912", "title": "Malignancy in neuromuscular patients on chronic IVIG.", "abstract": "BACKGROUND: Intravenous immunoglobulin (IVIG) has been widely used to treat immune-mediated neuromuscular disorders. The relationship between IVIG and cancer is unclear. Preclinical studies have suggested that IVIG may influence cellular mechanisms pertinent to cancer development. This hypothesis is supported by clinical evidence, predominantly through case reports, although these findings are limited in scope and methodological rigor.\nMETHODS: A retrospective review was conducted on patients receiving chronic IVIG treatment for Myasthenia Gravis (MG) and chronic immune demyelinating polyradiculoneuropathy (CIDP), at our tertiary medical center between 2000 and 2023.\nRESULTS: We identified 436 patients with MG and 102 patients with CIDP. Patients were divided into IVIG and non-IVIG treated in each of the disease groups. Seventy-five and 64 patients received IVIG in MG and CIDP groups, respectively. Cancer incidence was counted if it appeared at least 1 year after the diagnosis of MG or CIDP. In the MG group, cancer incidence was 12 / 75 (16%) among IVIG-treated patients compared to 87/350 (25%) in the MG-non-IVIG group (p = 0.09). Excluding mild MG cases, who were treated only by pyridostigmine, cancer incidence in the MG-non-IVIG group increased to 72/250 (28.8%), significantly higher than in the IVIG-MG group, p = 0.01. For CIDP patients receiving IVIG, incidence of cancer was 6/59 (10%), while in the non-IVIG-treated CIDP group, it was 9/34 (26%) (p = 0.03). Analyzing all IVIG-treated patients together (of both disease groups) showed a negative correlation between \"time on IVIG treatment\" and cancer (p = 0.001). Using logistic regression, we observed a negative coefficient for IVIG exposure (-0.03, p = 0.004), indicating that an increase in time from diagnosis is associated with a decreased likelihood of developing cancer in the IVIG-treated group.\nCONCLUSION: Chronic IVIG therapy may be associated with a reduced incidence of cancer, particularly among patients with CIDP. Additionally, we found a negative correlation between duration of IVIG treatment and cancer incidence, suggesting a potential protective effect of long-term IVIG exposure. To our knowledge, this is the first study to explore the relationship between sustained IVIG therapy and long-term cancer risk in neuromuscular autoimmune diseases.", "authors": ["Khateb Mohamed", "Bahous Elian", "Abu Zant Mai", "Shelly Shahar"], "journal": "Frontiers in neurology", "entry_date": "2025/07/09 05:05", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40630912/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Rambam Medical Center, Haifa, Israel."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.8, "journal_quartile": "3区"}, {"pmid": "40626411", "title": "Complement inhibitors for myasthenia gravis in adults.", "abstract": "This is a protocol for a Cochrane Review (intervention). The objectives are as follows: To evaluate the benefits and harms of complement inhibitors for treating myasthenia gravis in adults compared with control treatment (placebo or standard care).", "authors": ["White Laura M", "Clay Fiona J", "Forbes Anne-Marie", "Keh Ryan Yann Shern", "Lilleker James B", "Spillane Jennifer", "Storms Karen", "Sussman Jon", "Dodd Katherine C"], "journal": "The Cochrane database of systematic reviews", "entry_date": "2025/07/08 06:42", "pub_date": "2025-07-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40626411/", "pub_types": ["Journal Article"], "affiliations": ["Lancaster Medical School, Lancaster University, Lancaster, UK."], "china_related": false, "study_types": ["Protocol"], "evidence_level": null, "journal_if": 9.4, "journal_quartile": "1区"}, {"pmid": "40624254", "title": "A patient with myasthenia gravis showing lower sensitivity to rocuronium and earlier recovery of train-of-four responses on electromyography compared to acceleromyography: a case report.", "abstract": "BACKGROUND: Although newly developed electromyographic devices have been introduced in anesthetic practice, reports on their use in patients with myasthenia gravis (MG) are lacking. We describe electromyographic monitoring combined with acceleromyography in a myasthenic patient.\nCASE PRESENTATION: A 55-year-old female underwent robot-assisted thoracoscopic thymothymectomy due to MG associated with thymoma. At general anesthesia induction, 0.13 mg/kg of rocuronium completely suppressed the acceleromyographic train-of-four (TOF) response, enabling tracheal intubation. However, the electromyographic TOF count remained at 4. Intraoperatively, rocuronium was administered whenever the acceleromyographic TOF count reached 1, which was consistently delayed compared to the electromyographic TOF count of 1. After surgery, sugammadex 2 mg/kg was administered following confirmation of a TOF count of 2 on both monitors, which enabled successful extubation in the operating room.\nCONCLUSIONS: This case suggests that combining electromyography with acceleromyography might be more beneficial than electromyography or acceleromyography alone in myasthenic patients, until further evidence is available.", "authors": ["Murakami Yoshiko", "Fujimoto Masafumi", "Hirata Naoyuki"], "journal": "JA clinical reports", "entry_date": "2025/07/07 23:34", "pub_date": "2025-07-07", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40624254/", "pub_types": ["Journal Article"], "affiliations": ["Department of Anesthesiology, Kumamoto University Hospital, 1-1-1, Honjyo, Cyuoku, Kumamoto‑City, 860-8556, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.0, "journal_quartile": "4区"}, {"pmid": "40622977", "title": "Circadian rhythm genes and immune cell infiltration in myasthenia gravis: A comprehensive analysis.", "abstract": "The fluctuating weakness in myasthenia gravis (MG) is clinically described as the \"morning improvement and evening worsening\" pattern; MG is commonly associated with sleep disorders. However, there remains a paucity of research investigating the relationship between MG and circadian rhythms. This study seeks to identify pivotal circadian rhythm genes (CRGs) and characterize immune cell infiltration in MG, while exploring their potential roles in MG pathogenesis. MG data were obtained from the Gene Expression Omnibus (GEO) database. Initially, differentially expressed circadian rhythm genes between MG and control samples were identified through differential expression analysis. Subsequently, to elucidate the functional roles of differentially expressed CRGs, we conducted Gene Ontology (GO) and Kyoto Encyclopedia of Genes and Genomes (KEGG) pathway analyses. Finally, weighted gene co-expression network analysis (WGCNA) and least absolute shrinkage and selection operator (LASSO) regression were applied to identify the hub CRGs. The diagnostic utility of hub genes was evaluated using the receiver operating characteristic curve, and their protein expression levels in the serum of patients with MG were assessed utilizing enzyme-linked immunosorbent assay. Additionally, we examined the extent of immune cell infiltration in MG and explored its relationship with the identified hub genes. We analyzed the immune infiltration profile in MG and their correlation with the identified hub genes. The GO enrichment analysis revealed significant enrichment of differentially expressed genes in circadian rhythm-related biological processes. Our investigation identified two hub CRGs that exhibit high diagnostic specificity and sensitivity and are significantly upregulated in serum samples from MG patients. Furthermore, Immune cells were correlated with hub genes. Our findings suggest a potential circadian rhythm disorder in MG, which may offer novel biomarkers and therapeutic strategies for future research.", "authors": ["Wang Ke", "Xu Peng", "Lu Jing", "Ji Xinchen", "Zhang Ying", "Zhang Yibin", "Li Dongxu", "Zhang Dongmei", "Lan Tianye", "Wang Jian"], "journal": "PloS one", "entry_date": "2025/07/07 13:43", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40622977/", "pub_types": ["Journal Article"], "affiliations": ["College of Traditional Chinese Medicine, Changchun University of Chinese Medicine, Changchun, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.6, "journal_quartile": "3区"}, {"pmid": "40620733", "title": "Switching to subcutaneous zilucoplan from intravenous complement component 5 inhibitors in generalised myasthenia gravis: a phase IIIb, open-label study.", "abstract": "BACKGROUND: Zilucoplan, a peptide complement component 5 (C5) inhibitor, is self-administered as a subcutaneous (SC) injection, which offers an alternative to intravenous infusion of antibody-based complement C5 inhibitors.\nOBJECTIVE: To evaluate subcutaneous zilucoplan in adults with acetylcholine receptor autoantibody-positive generalised myasthenia gravis (gMG) who switched from intravenous complement C5 inhibitors to zilucoplan.\nDESIGN: MG0017 (NCT05514873) was a phase IIIb, open-label, single-arm study.\nMETHODS: Eligible patients had clinically stable gMG on an intravenous complement C5 inhibitor and were willing to switch to zilucoplan. Patients received a 12-week treatment period of daily subcutaneous zilucoplan 0.3 mg/kg. Incidence of treatment-emergent adverse events (TEAEs) was the primary endpoint. Change from baseline in the Myasthenia Gravis Activities of Daily Living (MG-ADL) score at Week 12 was a secondary endpoint. Treatment preference (Week 12) and treatment satisfaction (9-item Treatment Satisfaction Questionnaire for Medication (TSQM-9)) were both exploratory endpoints. Assessments by prior intravenous complement C5 inhibitor were conducted post hoc.\nRESULTS: Twenty-six patients enrolled and received zilucoplan; 16 switched from eculizumab and 10 from ravulizumab. TEAEs occurred in 19/26 (73.1%) patients and were mostly mild in severity. At Week 12, least squares (LS) mean (95% confidence interval) MG-ADL scores improved from baseline by -1.15 (-2.11, -0.19), p = 0.0217 and Quantitative MG (QMG) scores by -1.24 (-2.64, 0.16), p = 0.0802. Clinically meaningful improvement from baseline in mean MG-ADL and QMG scores was observed at Week 12 among patients who switched from ravulizumab (-2.41 (-4.52, -0.30; p = 0.0307) and -3.52 (-6.14, -0.90; p = 0.0149), respectively). At Week 12, 76.9% (n = 20) patients preferred subcutaneous injection compared with intravenous infusion. Mean (standard deviation) changes from baseline in the TSQM-9 Global Satisfaction, Effectiveness and Convenience subscores at Week 12 were +19.410 (27.429), +13.889 (21.534) and +21.739 (19.955), respectively. Complement inhibition increased from baseline and was complete (>95%) by Week 2 and maintained to Week 12.\nCONCLUSION: Zilucoplan demonstrated a favourable safety profile. gMG symptoms improved during zilucoplan treatment; this was clinically meaningful for those switching from ravulizumab.\nTRIAL REGISTRATION: ClinicalTrials.gov (NCT05514873); 22 August 2022. https://clinicaltrials.gov/study/NCT05514873.\nExperiences of patients with myasthenia gravis who switched their treatments from intravenous infusions of ravulizumab or eculizumab to self-administered daily injections of zilucoplan: effects on symptoms, safety, and patient preference Myasthenia gravis (MG) is a chronic autoimmune disease. Complement, part of the immune system, is overactive in MG. This damages the connections between muscles and nerves, causing muscle weakness. Symptoms can be reduced by blocking complement activity. Ravulizumab and eculizumab are complement inhibitors that are given as intravenous (into a vein) infusions by a healthcare professional in a hospital or clinic. Zilucoplan is another type of complement inhibitor, which patients can inject subcutaneously (under the skin) themselves. This study followed patients with MG who wanted to switch from ravulizumab or eculizumab to zilucoplan. Side effects were recorded throughout the study. Patients’ symptoms were measured to see if there was any change since switching treatment. All 26 patients who enrolled in the study had stable symptoms with their current treatment (which was ravulizumab in 10 patients, and eculizumab in 16 patients). Once enrolled, patients switched to daily zilucoplan for 12 weeks. Their main reasons for wanting to switch treatment were challenges with intravenous infusions, including travelling to hospital and long infusion times. Some patients also felt their current treatment was wearing off. After 12 weeks of zilucoplan treatment, symptoms across the group as a whole had improved. Symptoms had either improved or stayed the same in approximately 75% of patients. Symptom improvements were greatest in patients who switched from ravulizumab to zilucoplan. At the end of the study, 76.9% (20 out of 26) patients said they preferred injections with zilucoplan to intravenous infusions of their previous treatment. Side effects occurred in 73.1% of patients, which were mostly mild. Although the study was short and limited to a small number of patients, the results suggest that switching to zilucoplan is an option for patients with MG who would prefer self-injections to intravenous infusions. Longer-term studies are needed to confirm these findings.", "authors": ["Freimer Miriam", "Desai Urvi", "Govindarajan Raghav", "Kang Min K", "Khan Shaida", "Khatri Bhupendra", "Levine Todd", "Macwan Samir", "Shieh Perry B", "Weiss Michael D", "Bloemers Jos", "Boroojerdi Babak", "Delicha Eumorphia Maria", "Lavrov Andreea", "Singh Puneet", "Howard James F"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/07/07 05:11", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40620733/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, The Ohio State University Wexner Medical Center, 395 West 12th Avenue, 7th Floor, Columbus, OH 43210, USA."], "china_related": false, "study_types": ["Cross-Sectional"], "evidence_level": "IV", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "40619040", "title": "Shengxian decoction alleviates experimental autoimmune myasthenia gravis by enhancing the immunosuppressive activity of regulatory T cells via Hippo pathway.", "abstract": "ETHNOPHARMACOLOGICAL RELEVANCE: Myasthenia gravis (MG) is an autoimmune disease mediated by autoantibodies, the pathogenesis of which is well defined but for which safe and effective drugs are still lacking. Shengxian Decoction (SXD) is a classical Chinese herbal formula that has been shown to improve qi deficiency and fatigue syndrome, which is also one of the key pathomechanisms in myasthenia gravis. However, the potential of this formula to treat myasthenia gravis (MG) and its underlying mechanisms remains to be fully elucidated.\nAIM OF THE STUDY: To investigate the therapeutic effect of the traditional Chinese medicine formula, Shengxian Decoction (SXD) on MG and its potential mechanism of action.\nMETHODS AND MATERIALS: Employing prednisone (PDN) as a positive control, the experimental autoimmune myasthenia gravis (EAMG) rat model induced by recombinant acetylcholine receptor (AChR) α subunit 97-116 peptide was used to reveal and confirm the therapeutic effect of SXD on MG. Model evaluation was performed based on animal behavioral performance combined with repeated nerve stimulation (RNS) experiments. Hematoxylin-Eosin (HE) staining and enzyme-linked immunosorbent (ELISA) assay were used to detect the level of inflammatory cytokines. The alterations in T-cell immunity were observed using flow cytometry (FCM). Immunohistochemistry (IHC) and immunofluorescence (IF) experiments were used to detect the molecular expression of TAZ, TEAD, and FOXP3. The ex vivo and in vivo mechanisms were validated by Western blot (WB) and Co-immunoprecipitation (Co-IP).\nRESULTS: The results showed that SXD significantly reversed loss of weight and muscle strength in EAMG rats, reducing the inflammation level and repairing the damage of thymic tissues in the model rats. Furthermore, SXD altered the trend observed in EAMG rats by markedly increasing the proportion of pro-inflammatory Th1 and Th17 cells and reducing the expression of Regulatory T cells (Treg), which plays a pivotal role in regulating the immune response in EAMG rats. SXD was shown to upregulate the expression of FOXP3 and TEAD, downregulate the expression of TAZ, and inhibit the binding of TAZ and TEAD in this research. This phenomenon was subsequently validated in vitro, which may elucidate the potential mechanism of SXD in the treatment of EAMG.\nCONCLUSION: SXD has been demonstrated to possess the capacity to treat EAMG. The underlying mechanism of action may be achieved by promoting the degradation of TAZ through the TAZ/TEAD pathway and inhibiting the binding of TAZ and TEAD, thereby restoring the balance of the body's immune function.", "authors": ["Wang Shida", "Zhang Xiangrui", "Bai Yu", "Shi Jun", "Sun Yan", "Wu Haoxin"], "journal": "Journal of ethnopharmacology", "entry_date": "2025/07/06 19:39", "pub_date": "2025-08-29", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40619040/", "pub_types": ["Journal Article"], "affiliations": ["Nanjing University of Chinese Medicine, Nanjing, 210023, Jiangsu, PR China; Key Laboratory of Integrative Biomedicine for Brain Diseases, School of Chinese Medicine, Nanjing University of Chinese Medicine, Nanjing, 210023, PR China; National Famous Chinese Medicine Expert Inheritance Studio (Meng Jingchun), Nanjing University of Chinese Medicine, School of Chinese Medicine, Nanjing, 210023, PR China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 5.4, "journal_quartile": "2区"}, {"pmid": "40615948", "title": "Efgartigimod therapy for immune checkpoint inhibitor-associated myasthenia gravis with myositis: a case report.", "abstract": "The advent of immune checkpoint inhibitors (ICIs) has transformed cancer therapy, but their association with immune-related adverse events presents a new and complex challenge for clinicians. In this report, we present the case of a 60-year-old Han Chinese woman who developed myasthenia gravis (MG) with myositis after pembrolizumab treatment for breast cancer. The patient presented with ptosis, slurred speech, limb weakness, and ocular fixation. Her creatine kinase level was elevated but she reported no muscle pain. The patient was diagnosed with ICI-associated MG with myositis. Before presenting to us, the patient had received low doses of intravenous methylprednisolone followed by oral prednisone, but her symptoms had continued to worsen. Her muscle strength improved significantly after we treated her with efgartigimod. This report is the first description of efgartigimod use in the treatment of ICI-associated MG with myositis, a new strategy for the treatment of this disease.", "authors": ["Qi Feiteng", "Sun Qi", "Wang Haifeng", "Zhang Yong"], "journal": "BMC neurology", "entry_date": "2025/07/04 23:44", "pub_date": "2025-07-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40615948/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Ningbo Medical Center Lihuili Hospital, Ningbo, 315000, China."], "china_related": true, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "40615537", "title": "The role of regulatory B cell/T follicular helper cell balance in thymoma and thymoma-associated myasthenia gravis.", "abstract": "Thymoma is often associated with myasthenia gravis (MG). Abnormal lymphocyte differentiation often occurs in the thymoma tumor microenvironment (TME), leading to thymoma-associated autoimmune diseases. Thymoma is closely related to MG, although the underlying mechanisms remain unclear. Patients diagnosed with thymoma were selected and divided into three groups on the basis of MG diagnosis and severity: thymoma alone (T), thymoma-associated MG with mild and moderate clinical symptoms (T + MGL), and severe thymoma-associated MG (T + MGH). Tumor tissue and peripheral blood samples were collected from each group of patients. In the thymoma TME, CD19+ B cells, CD19+CD5+CD1d+ regulatory B cells (Bregs), CD4+ T cells, and CD4+CXCR5+ T follicular helper cells (Tfhs) were localized via multilabel immunofluorescence staining to clarify the relationship between local immune infiltration in the TME and MG severity. Bregs, Tfhs, and other immune cells in the peripheral blood were assessed by flow cytometry. B-cell-enriched regions were detected around blood vessels in the thymoma TME. Breg infiltration in the TME decreased with MG aggravation, whereas the opposite trend was observed for Tfh cells. The Breg/Tfh ratios in the peripheral blood and TME were broadly consistent, and the levels of both types of cells were significantly lower in patients with aggravated MG. Our findings revealed a balance among the Breg/Tfh ratio, immune hyperactivity, and immune tolerance in thymoma-associated MG in both the peripheral blood and the TME. These observations provide new perspectives regarding disease pathogenesis and immunotherapy.", "authors": ["Zhang Peng", "Liu Yuxin", "Tao ZiYou", "Zhang Xinyu", "Wang Yuanguo", "Zhang Hui", "Li Jian", "Yang Zhaoyu", "Xiong Kai", "Duan Shuning", "Zhang Zeyang", "Wang Yan", "Wang Huan"], "journal": "Scientific reports", "entry_date": "2025/07/04 23:25", "pub_date": "2025-07-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40615537/", "pub_types": ["Journal Article"], "affiliations": ["Department of Cardiovascular Thoracic Surgery, Tianjin Medical University General Hospital, Tianjin, China. zhangpengtjgh@126.com."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40614598", "title": "FcRn inhibition with efgartigimod ameliorates muscle weakness and modulates dendritic cell subsets in an experimental autoimmune myasthenia gravis mouse model.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an IgG-mediated autoimmune neuromuscular disorder characterized by exercise-induced skeletal muscle weakness. Reducing circulating IgG levels is a critical therapeutic strategy. Here, we evaluated efgartigimod, a novel neonatal Fc receptor (FcRn) inhibitor that lowers IgG levels, in an experimental autoimmune myasthenia gravis (EAMG) mouse model.\nMETHODS: EAMG was induced in mice by immunization with recombinant acetylcholine receptor (AChR). Serum anti-R97-116 IgG titers were quantified by ELISA. Electromyography assessed compound muscle action potentials (CMAPs) in the gastrocnemius muscle using repetitive nerve stimulation. The EAMG+EF group (n = 12) received intraperitoneal efgartigimod (10 mg/kg/week) starting after the third immunization and continuing for 4 weeks, while the EAMG group (n = 12) remained untreated. Control mice (n = 12) underwent mock immunization with CFA. Clinical assessments included body weight, grip strength, and inverted grid test. The proportion of cDC1s, cDC2s, and pDCs, along with their antigen-presenting and co-stimulatory molecules, was analyzed with flow cytometry.\nRESULTS: Compared with controls, repetitive nerve stimulation in EAMG mice revealed a > 10 % reduction in gastrocnemius muscle response, accompanied by elevated anti-R97-116 IgG titers and aggravated myasthenia symptoms, confirming successful AChR peptide-induced EAMG. Efgartigimod treatment improved disease severity, significantly decreasing anti-R97-116 IgG levels, mitigating weight loss, enhancing grip strength, and partially restoring performance on the inverted screen test. Additionally, EAMG mice exhibited a significant increase in the cDC1 subset and a decrease in the cDC2 subset compared to controls. The expression of MHCII was reduced in the cDC1 subset, and the expression of MHCII and CD86 were downregulated in cDC2s in EAMG mice. Efgartigimod treatment normalized cDC1 and cDC2 proportions, restoring MHCII expression to control levels in cDC1s and cDC2s. Furthermore, it significantly upregulated CD80, CD86, and CD40 expression on cDC2s compared to EAMG mice. These findings indicate that efgartigimod modulates the frequencies of dendritic cell subsets as well as their surface expression of antigen presentation (via MHCII) and co-stimulatory signaling molecules (CD40/CD80/CD86).\nCONCLUSION: It is indicated that efgartigimod not only alleviates MG symptoms but also exerts immunomodulatory effects on different dendritic cell subsets.", "authors": ["Shi Danli", "Wu Yu", "Liang Xiaole", "Xie Shenxia", "Liang Manli", "Lu Ting", "Huang Yanzhen", "Que Xianting", "Mo Xuean", "Huang Wen"], "journal": "International immunopharmacology", "entry_date": "2025/07/04 18:10", "pub_date": "2025-09-23", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40614598/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, the First Affiliated Hospital of Guangxi Medical University, Nanning 530021, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 4.7, "journal_quartile": "2区"}, {"pmid": "40607605", "title": "Rituximab for myasthenia gravis.", "abstract": "RATIONALE: Myasthenia gravis (MG) is an autoimmune disease which causes muscle weakness due to disruption in neuromuscular transmission. Rituximab is a medication increasingly used in the treatment of MG, but its potential benefits, and optimal use in terms of patient subgroup and dosing, are unclear. It is important to bring together high-quality evidence to determine how rituximab would be best used in treatment algorithms for MG.\nOBJECTIVES: To assess: - the effects of rituximab (including biosimilar variants) for the treatment of MG in adults; and - the benefits and harms of rituximab in different patient subgroups, and treatment strategies, in order to aid treatment choice for individuals, and inform policymakers about those most likely to benefit.\nSEARCH METHODS: We searched CENTRAL, MEDLINE, Embase, and two trials registries (Clinicaltrials.gov and the World Health Organization trials registry) up to November 2024.\nELIGIBILITY CRITERIA: We included randomised controlled trials (RCTs) or quasi-RCTs in adults (aged 16 years and over) with MG (all subtypes and severity), comparing rituximab (any dosing regimen) with placebo, no treatment, or alterative therapy. We excluded cluster-RCTs and nonrandomised studies, studies in those previously treated with rituximab, and studies analysing juvenile MG (under 16 years of age).\nOUTCOMES: Critical outcomes were improvement in symptom severity or functional ability (as measured by Quantitative MG (QMG) and MG-Activities of Daily Living (ADL) scores), reduction in the burden of alternative treatment (steroid-sparing effect and relapse requiring rescue therapy), and serious adverse events (SAEs) in the long term (beyond nine months). Important outcomes included MG Composite (MGC) score, quality of life, hospital admissions and antibody titre, at short-term (two months or less), medium-term (two to nine months), and long-term (beyond nine months) time points. Achievement of a clinically significant improvement in QMG, MG-ADL and MGC scores was analysed dichotomously. We examined safety by looking at adverse events (AEs), treatment-related AEs, and AEs leading to discontinuation of treatment. We also analysed critical outcome measures at the short- and medium-term time points.\nRISK OF BIAS: We used the Cochrane risk of bias 1 tool RoB 1 to assess potential bias.\nSYNTHESIS METHODS: We synthesised results for each outcome using meta-analysis where possible, with random-effects models to calculate mean difference (MD) or risk ratios (RRs) and 95% confidence intervals (CI). Where this was not possible due to the nature of the data, we synthesised results by summarising effect estimates. Data were analysed on an intention-to-treat basis. We used GRADE to assess the certainty of evidence for each outcome. Sensitivity analysis examined whether a fixed-effect model or the use of odds ratios would alter conclusions.\nINCLUDED STUDIES: We included two RCTs with a total of 99 participants. One study was conducted in Europe and one in North America, and both were published in 2022. The study populations and treatment strategies differed; one administered rituximab at low doses in new or early-onset generalised MG, and the other at high repeated doses as add-on therapy.\nSYNTHESIS OF RESULTS: The evidence has limitations. Beyond nine months, the evidence is very uncertain on the effects of rituximab on symptom severity as assessed with QMG score (MD 1.62 lower (favouring rituximab), 95% CI 3.53 lower to 0.29 higher; 2 studies, 94 participants; very low-certainty evidence), and functional ability as assessed by MG-ADL (MD 1.16 lower (favouring rituximab), 95% CI 2.48 lower to 0.16 higher; 2 studies, 95 participants; very low-certainty evidence). The evidence suggests that rituximab results in little to no difference in its steroid-sparing effect beyond nine months (RR 1.00, 95% CI 0.92 to 1.09; 2 studies, 94 participants; low-certainty evidence), but probably results in a large reduction in relapse requiring rescue therapy (220 out of 1000 people with rituximab, compared with 490 out of 1000 people with placebo, favouring rituximab, RR 0.45, 95% CI 0.26 to 0.78; 2 studies, 98 participants; moderate-certainty evidence). Rituximab may reduce SAEs, but the evidence is very uncertain (RR 0.81 (favouring rituximab), 95% CI 0.47 to 1.41; 2 studies, 99 participants; very low-certainty evidence). The main limitation of this review is that only two studies were included, which used rituximab in different ways (low dose at onset of generalisation compared with high dose as add-on therapy). The studies mainly assessed acetylcholine-receptor antibody MG. There were differences in co-administered steroid dosing between studies. We considered the studies to be at low risk of bias, apart from possible bias from differences in characteristics between treatment arms. There was serious to extremely serious imprecision in the certainty of evidence when assessing several outcomes due to wide confidence intervals, and serious indirectness in all outcomes as not all forms of MG were studied.\nAUTHORS' CONCLUSIONS: Rituximab's effects on symptom severity and functional ability in the long-term are uncertain. The evidence suggests that rituximab results in little to no difference in its steroid-sparing effect; however, it probably results in a large reduction in relapse requiring rescue therapy over nine months, based on results from two studies. The available data about the effects of rituximab on SAEs are of very low certainty, and so we are not able to draw conclusions. There are inadequate data to determine optimal dosing regimen or patient characteristics. Further studies examining rituximab, and other B cell-depleting therapies, in different MG patient subgroups are warranted.\nFUNDING: This Cochrane review had no dedicated funding.\nREGISTRATION: Protocol (2023) available via DOI: 10.1002/14651858.CD014574.", "authors": ["Dodd Katherine C", "Clay Fiona J", "Forbes Anne-Marie", "Handley Joel", "Keh Ryan Yann Shern", "Miller James Al", "Storms Karen", "White Laura M", "Lilleker James B", "Sussman Jon"], "journal": "The Cochrane database of systematic reviews", "entry_date": "2025/07/03 07:12", "pub_date": "2025-07-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40607605/", "pub_types": ["Journal Article", "Systematic Review", "Meta-Analysis"], "affiliations": ["Manchester Centre for Clinical Neurosciences, Northern Care Alliance NHS Foundation Trust, Salford, UK."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 9.4, "journal_quartile": "1区"}, {"pmid": "40607384", "title": "Subtype-specific atypical B cell profiles in myasthenia gravis reveal distinct immunopathological pathways.", "abstract": "INTRODUCTION: Atypical B cell (atBC) subsets display significant heterogeneity across autoimmune diseases, complicating efforts to define their role and therapeutic potential. We hypothesized that this heterogeneity reflects the responses to specific immunopathology, resulting in disease-specific profiles. The myasthenia gravis (MG) subtypes acetylcholine receptor (AChR)-positive MG and muscle-specific kinase (MuSK)-positive MG provide an ideal model to explore atBCs due to the distinct immune mechanisms driven by IgG1-3 and IgG4 autoantibodies, respectively in the disease.\nMETHODS: CD11c+ and IgD-CD27- double-negative (DN) B cells were analyzed by spectral flow cytometry in non-autoimmune controls, AChR-MG, and MuSK-MG. Results were correlated with clinical parameters and antibody levels. In MG subtypes, atBC subsets were further examined for the impact of disease onset and prior rituximab treatment. CD11c+ B cells were stimulated in vitro to assess antibody secreting cell (ASC) differentiation.\nRESULTS: CD11c+ and DN2 B cells were increased in late-onset AChR-MG, while MuSK-MG featured expanded DN3 B cells linked to disease severity. CD20 expression in atBCs was differentially expressed between MG subtypes, with higher levels in late-onset AChR-MG and significantly reduced levels in MuSK-MG. CD11c+ B cells were reduced after anti-CD20 treatment in MuSK-MG, whereas DN B cells were unaffected. Functionally, CD11c+ B cells from MuSK-MG exhibited greater ASC differentiation and autoantibody production.\nDISCUSSION: MG subtypes exhibit distinct atBC profiles linked to immunopathology and disease onset. These findings reveal subtype-specific pathways that regulate atBCs and highlight their potential as therapeutic targets in both IgG1-3- and IgG4-mediated autoimmunity.", "authors": ["Sikorski Patricia M", "Kaminski Henry J", "Vincent Angela", "Bauman Taylor", "Jacobson Leslie", "Kusner Linda L"], "journal": "Frontiers in immunology", "entry_date": "2025/07/03 06:04", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40607384/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology & Rehabilitation Medicine, George Washington University, Washington, DC, United States."], "china_related": false, "study_types": ["In Vitro"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40605600", "title": "[Myasthenic crisis with respiratory failure caused by COVID-19].", "abstract": "Myasthenic crisis is a severe complication of myasthenia gravis (MG) characterized by respiratory failure. This case report presents a 24-year-old woman admitted with respiratory distress, eventually diagnosed with myasthenic crisis triggered by COVID-19. Initial symptoms included throat pain and dysphagia with no evident pathology. Elevated acetylcholine receptor antibodies confirmed MG. The case underscores the importance of considering neuromuscular diseases in unexplained respiratory failure, highlighting early diagnosis and treatment as key to reducing the need for invasive ventilation.", "authors": ["Eliasen Troels Ulrik", "Jensen Troels Bek", "Leth Steffen", "Dey Nilanjan"], "journal": "Ugeskrift for laeger", "entry_date": "2025/07/03 04:03", "pub_date": "2025-06-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40605600/", "pub_types": ["Journal Article", "Case Reports", "English Abstract"], "affiliations": ["Operation og Intensiv, Regionshospitalet Gødstrup."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40604668", "title": "Assessment of functioning using the WHODAS 2.0 among people with myasthenia gravis-associated disability: a nationwide follow-up study.", "abstract": "BACKGROUND: Advancements in treatment have increased the life expectancy of patients with Myasthenia Gravis (MG), yet the understanding of functional changes in these individuals remains limited. In our study, we explored the functional abilities of individuals with MG using the World Health Organization Disability Assessment Schedule 2.0 (WHODAS 2.0).\nMETHODS: This observational study analyzed data from 286 patients with MG, acquired from the Data Bank of Persons with Disabilities (TDPD) in Taiwan between July 11, 2012, and December 31, 2021. Participants were diagnosed with MG after the acute phase. The functional disability outcome was assessed using the WHODAS 2.0. Due to non-normal distribution of variables, we used the Wilcoxon rank sum and chi-square tests for group comparisons by age. Longitudinal associations between functional changes and demographic characteristics were assessed using generalized estimating equations (GEE), adjusting for age, sex, educational level, and respiratory dysfunction.\nRESULTS: The average follow-up period was three years. At the initial evaluation, younger individuals (< 65 years) generally demonstrated less severe disability across most functional domains, with the exception of social participation. Patients with a single disability in a specific function performed better than those with multiple disabilities. The provision of technical aids or other environmental interventions resulted in significant functional improvements across all domains. During follow-up, significant functional improvements were observed, especially among patients residing in institutions, those without respiratory disabilities, and those with reduced mobility at the time of initial assessment. The GEE analysis indicated that younger patients with MG experienced functional changes comparable to older patients. Notably, respiratory disability was identified as a key factor contributing to cognitive decline. Additionally, only 10.5% of patients aged 18-64 were employed at the time of the study.\nCONCLUSIONS: Our findings highlight the complexity of disabilities associated with MG, with social participation emerging as a particularly vulnerable domain. Although younger patients initially exhibited better functional performance, their long-term functional changes were comparable to those observed in older patients. Given the impact of functional limitations on employment, future research may focus on return-to-work interventions, as labor market participation plays a crucial role in fostering social engagement for individuals with MG.", "authors": ["Hong Jia-Pei", "Lee Chih-Hong", "Hong Chien Tai", "Chan Lung", "Chung Chen-Chih", "Charoenpong Prangthip", "Chiu Hou-Chang", "Liou Tsan-Hon"], "journal": "BMC public health", "entry_date": "2025/07/03 00:30", "pub_date": "2025-07-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40604668/", "pub_types": ["Journal Article", "Observational Study"], "affiliations": ["Department of Physical Medicine and Rehabilitation, Taipei Medical University Shuang Ho Hospital, Taipei, Taiwan."], "china_related": true, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.6, "journal_quartile": "2区"}, {"pmid": "40601074", "title": "Therapeutic strategies targeting complement in myasthenia gravis patients.", "abstract": "Myasthenia gravis (MG) is an acquired autoimmune disorder characterized by impaired neuromuscular junction transmission, leading to fluctuating muscle weakness. With the progressive identification of MG-related antibodies, such as acetylcholine receptor (AChR) antibodies and muscle-specific kinase (MuSK) antibodies, coupled with advancements in antibody detection technology, the use of these diagnostic markers has become widely accessible in clinical practice. This has facilitated the detection of key biomarkers and enabled the study of targeted therapeutic interventions aimed at addressing the underlying production of MG pathogenic antibodies and their various stages of pathogenicity. Among the emerging therapeutic strategies, complement-targeting drugs have garnered significant attention from medical researchers because of their ability to reduce complement activation and inhibit autoimmune-mediated tissue damage. Inhibition of the terminal complement cascade has demonstrated efficacy in reducing disease severity and improving clinical outcomes, particularly in refractory cases of MG. This review summarizes the underlying mechanisms of complement activation in MG, evaluates the current therapeutic landscape, including both approved and investigational complement inhibitors and discusses the safety considerations of their application.", "authors": ["Wang Yinxiang", "Nao Jianfei", "Duan Yingjie", "Li Zijian", "Feng Juan"], "journal": "Journal of neurology", "entry_date": "2025/07/02 11:16", "pub_date": "2025-07-02", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40601074/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Neurology, Shengjing Hospital of China Medical University, No. 36 Sanhao Street, Heping District, Shenyang, 110004, Liaoning, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.6, "journal_quartile": "2区"}, {"pmid": "40599774", "title": "Identification of potential prognostic biomarkers of thymoma with myasthenia gravis based on serum proteomics.", "abstract": "BACKGROUND: Thymoma is often associated with myasthenia gravis (MG), and the resection of thymoma improves myasthenic symptoms in patients with thymoma and MG (TMG), but some patients still have no relief. Through proteomic analysis, we examined preoperative serum samples from patients with TMG to identify key prognostic proteins that could serve as a foundation for clinically predicting postoperative efficacy and guiding treatment selection.\nMETHOD: According to the Clinical Research Guidelines of the Myasthenia Gravis Foundation of America (MGFA) for Post-Intervention Status (PIS), 20 patients with TMG were divided into an effective group (T1) [the PIS was minimal manifestation status (MMS) and above] and an ineffective group (T2) (the PIS did not reach MMS and above), with 10 cases each, and a healthy control group (C) with nine cases. Blood samples from the three groups were collected through data-independent acquisition (DIA) proteomic analysis performed by mass spectrometry to identify differentially expressed proteins and search for key proteins associated with myasthenia prognosis. Finally, the target proteins were validated through the utilization of enzyme-linked immunosorbent assay (ELISA).\nRESULTS: A total of 514 proteins were identified in this research. Between the T1 and T2 groups, there were 20 proteins that exhibited differential expression, with 10 showing upregulation and 10 displaying downregulation. The Kyoto Encyclopedia of Genes and Genomes (KEGG) functional annotation indicated that these proteins were mainly involved in signaling pathways such as complement and coagulation cascade, prion disease, systemic lupus erythematosus, neutrophil extracellular trap formation, and transcription dysregulation in cancer. Three proteins were discovered to have a significant correlation with the prognosis of TMG: L-selectin (SELL) was downregulated, and human leukocyte antigen (HLA) class I histocompatibility antigen (HLA-A) and complement 5 (C5) were upregulated. ELISA results confirmed the proteomic results.\nCONCLUSION: HLA-A, C5, and SELL may be potential prognostic biomarkers of TMG. This study may provide a more accurate prognostic risk assessment of TMG patients to help clinicians better individualize the initial treatment regimen for patients with different risk stratification, plan a more reasonable frequency of follow-up visits, and make more precise maintenance treatment decisions, thereby improving the overall prognosis of TMG patients.", "authors": ["Lin Xiaoting", "Liu Peng", "Qi Guoyan"], "journal": "Frontiers in immunology", "entry_date": "2025/07/02 05:25", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40599774/", "pub_types": ["Journal Article"], "affiliations": ["Department of Oncology, Hebei Medical University, Shijiazhuang, Hebei, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40598873", "title": "Ocular Myasthenia Gravis following strabismus surgery and presenting as refractory strabismus.", "abstract": "INTRODUCTION: Ocular myasthenia gravis is a protean disorder and can present with myriad disorders of ocular motility. The diagnosis may not be obvious at presentation and strabismus surgery has occasionally been performed with unexpected outcomes. Strabismus surgery can be performed on patients with ocular myasthenia gravis who have stable ocular deviations, although outcomes may vary.\nCASE REPORT: We report two patients who were operated for strabismus and were diagnosed as ocular myasthenia gravis later, when classic signs appeared. The first patient underwent right medial rectus recession and left lateral rectus plication for a left sixth nerve palsy surgery. He developed recurrent strabismus and ptosis 3 months after surgery and was diagnosed as ocular myasthenia gravis on the basis of positive ice test, fatigue test and repetitive nerve stimulation test. He was started on a tapering regime of oral steroids and pyridostigmine. This reduced the deviations to a level correctable by prisms eventually becoming orthophoric in primary position. The second patient had a severe undercorrection of strabismus after large recess resect procedure on the right eye for large angle exotropia. Five months after surgery, he presented with right eye ptosis and a recurrence of strabismus. He tested positive for anti-acetylcholine receptor antibodies. The ptosis improved with oral steroids and pyridostigmine and he eventually went into a natural remission. The ocular deviation, however, remained unchanged.\nDISCUSSION: The emergence of ocular myasthenia in patients undergoing strabismus surgery is a rare occurrence but should be suspected in patients with unexpected outcomes after strabismus surgery.", "authors": ["Nagasubramanian Vidhya", "Rajamani Muralidhar", "Ghaisas Shamika Pravin", "Dandapani Ramamurthy"], "journal": "Strabismus", "entry_date": "2025/07/02 04:59", "pub_date": "2026-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40598873/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Pediatric Ophthalmology and Strabismus, The Eye Foundation, Coimbatore, India."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.8, "journal_quartile": "4区"}, {"pmid": "40597804", "title": "Circulating inflammatory cytokines and the risk of myasthenia gravis: a bidirectional Mendelian randomization study.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is an autoimmune disorder of the neuromuscular junction. Increasing evidence has suggested inflammation is involved in the pathogenesis of MG, but whether it is the cause or a downstream effect remains unclear. In this study, a two-sample Mendelian randomization (TSMR) analysis was performed to explore the causal relationship between 91 circulating inflammatory cytokines and MG.\nMETHOD: In this study, the data of 91 circulating inflammatory cytokines from 4824 Europeans and the largest GWAS database of MG (1873 patients and 36370 controls) were used to screen instrumental variables (IVs). Inverse variance weighting (IVW), Bayesian weighted MR (BWMR), MR-Egger regression, weighted median (WM), simple mode and weighted mode were used to evaluate the association between MG and inflammatory cytokines. The MR-Egger intercept test and Cochran's Q test were used to test the pleiotropy and heterogeneity of IVs.\nRESULT: Our results showed that adenosine deaminase (ADA) and CD40 Ligand‌ (CD40L) are positively associated with the risk of MG (OR = 1.16, 95%CI: 1.00-1.33, P = 0.041; OR = 1.20, 95%CI: 1.02-1.40, P = 0.025), while interleukin-1-alpha (IL-1α), glial-cell-line-derived neurotrophic factor (GDNF), Osteoprotegerin (OPG) and tumor necrosis factor-beta (TNF-β) are negatively associated with the risk of MG (OR = 0.80, 95% CI: 0.64 ~ 0.99, P = 0.042; OR = 0.74, 95%CI:0.58 ~ 0.0.96, P = 0.022; OR = 0.76, 95% CI: 0.61 ~ 0.94, P = 0.013; OR = 0.76, 95% CI: 0.61 ~ 0.94, P = 0.012; OR = 0.80, 95% CI: 0.68 ~ 0.93, P = 0.006). In addition, genetically predicted MG affected the expression of seven cytokines. Sensitivity analysis showed no horizontal pleiotropy and significant heterogeneity of all results.\nCONCLUSIONS: Our results provided promising clues for the treatment of MG. We evaluated the association between inflammatory cytokines and the disease by genetic informatics approach, which may help to better understand the underlying mechanisms of MG.", "authors": ["Su Boyang", "He Zhengqing", "Shi Luyao", "Li Mao", "Huang Xusheng"], "journal": "BMC neurology", "entry_date": "2025/07/02 04:17", "pub_date": "2025-07-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40597804/", "pub_types": ["Journal Article"], "affiliations": ["Medical School of Chinese PLA, Beijing, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "40590525", "title": "Correction to \"Efgartigimod for Generalized Myasthenia Gravis: A Multicenter Real-World Cohort Study in China\".", "abstract": "", "authors": [], "journal": "Annals of clinical and translational neurology", "entry_date": "2025/07/01 08:52", "pub_date": "2025-09", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40590525/", "pub_types": ["Published Erratum"], "affiliations": [], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40589698", "title": "Efficacy and Immune-Related Adverse Events of Immune Checkpoint Inhibitors in Patients With Non-small Cell Lung Cancer and Autoimmune Diseases.", "abstract": "BACKGROUND: Autoimmune diseases (AIDs) are often associated with lung cancer, but their clinical characteristics remain unclear.\nPURPOSE: The study aimed to elucidate the clinical features of non-small cell lung cancer (NSCLC) in patients with AIDs.\nMETHODS: This single-center, retrospective observational study was conducted between June 2016 and October 2024. It included patients diagnosed with primary NSCLC and comorbid AIDs who received lung cancer treatment.\nRESULTS: A total of 32 patients (median age: 68 years; male/female: 14/18) were enrolled. Rheumatoid arthritis was the most common AID (10 cases, 31.3%), followed by Graves' disease, Hashimoto's thyroiditis, and ulcerative colitis (four cases each, 12.5%). Other AIDs included systemic lupus erythematosus (two cases, 6.3%) and one case (3.1%) each of Behçet's disease, dermatomyositis, myasthenia gravis, scleroderma, Schmidt's syndrome, psoriasis, and sarcoidosis. Immune checkpoint inhibitors (ICIs) were administered to 11 patients (34.3%), with a response rate and disease control rate of 63.6%. Immune-related adverse events (irAEs) occurred in 72.7% (8/11) of patients, including one grade 3 event. Of which, AID exacerbation related to ICI occurred in 45.5% (5/11) of patients. The median progression-free survival was 126 days, and the median overall survival (OS) was 1,594 days. Among patients without driver mutations who received ICI therapy, the median OS was significantly longer compared to those with driver mutations (2,274 vs. 654 days; P < 0.001). Multivariate analysis revealed that good performance status, adenocarcinoma history, and ICI administration were associated with better OS.\nCONCLUSIONS: ICIs may be effective in selected NSCLC patients with AIDs; however, careful monitoring is essential due to the risk of irAE and AID exacerbation.", "authors": ["Takashima Kenta", "Isobe Kazutoshi", "Wakabayashi Hiroki", "Kaneko Kaichi", "Saiki Atsuhito", "Matuzawa Yasuo"], "journal": "Cureus", "entry_date": "2025/07/01 04:18", "pub_date": "2025-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40589698/", "pub_types": ["Journal Article"], "affiliations": ["Department of Internal Medicine, Toho University Graduate School of Medicine, Tokyo, JPN."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40588742", "title": "Delving into immune modulation: thymectomy in myasthenia gravis.", "abstract": "OBJECTIVE: The study aims to investigate the impact of thymectomy (TX) on immune function and cytokines levels in patients with myasthenia gravis (MG).\nMETHODS: A total of 44 patients with MG were enrolled in the study, divided into two groups based on the treatment they received: the MG-TX group (14 MG patients who underwent thymectomy) and the control group (30 MG patients who received drug treatment alone). Patients were assessed at baseline (0 months), 1 month, 3 months, 6 months, and 12 months post-treatment. The levels of T lymphocytes subtypes (CD3+, CD4+, CD8 + T cells, and the CD4+/CD8 + ratio), immunoglobulins and complements levels (IgG, IgM, IgA, C3 and C4), and cytokines (IL-2, IL-4, IL-6, INF-γ, and TNF-α) were measured and compared between the two groups.\nRESULTS: At baseline, both the MG-TX and control groups exhibited similar levels of immune markers. Following thymectomy, there was a significant decrease in CD3+, CD4+, and CD8 + T cell levels at 1 month, which remained stable throughout the study period. At 12 months, the CD4 + levels in the MG-TX group were significantly lower than in the control group (P < 0.001). Additionally, the CD4/CD8 ratio was significantly lower in the MG-TX group at both 6 months and 12 months (P < 0.01 and P < 0.001, respectively). No significant changes in immunoglobulin and complement levels were observed in either group throughout the study. For cytokines, IL-2, IL-6, INF-γ, and TNF-α levels decreased significantly at 1-month post-treatment (P < 0.001). At 3 months, INF-γ levels in the MG-TX group remained higher than in the control group (P < 0.001), but stabilized by 6 months and 12 months. IL-4 levels significantly increased at 1 month post-treatment (P < 0.001), but at 12 months, the control group had higher IL-4 levels than the MG-TX group (P < 0.05).\nCONCLUSION: Thymectomy in MG patients results in a long-term decrease in T lymphocyte levels and a shift in the CD4/CD8 ratio. The procedure also induces transient changes in cytokine levels, which stabilize after 3 months. These findings suggest that thymectomy has a lasting impact on cellular immunity and cytokine secretion, with potential implications for immune system function and the risk of infections in MG patients.", "authors": ["Lin Nanlong", "Yang Zhongshan", "Yi Weiqiang", "Chen Yanxun", "Lai Fancai"], "journal": "Journal of cardiothoracic surgery", "entry_date": "2025/06/30 23:33", "pub_date": "2025-06-30", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40588742/", "pub_types": ["Journal Article"], "affiliations": ["Department of Thoracic Surgery, First Affiliated Hospital of Fujian Medical University, Fuzhou, 350005, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.1, "journal_quartile": "2区"}, {"pmid": "40585131", "title": "Bridging the Heterogeneity of Myasthenia Gravis Severity Scores for Digital Twin Development.", "abstract": "Myasthenia gravis (MG) is a rare autoimmune neuromuscular disease. Clinical trials with rigorously collected data, especially for rare diseases, provide opportunities for mathematical modeling of patient outcomes over time; however, building a larger data set from multiple trials faces the challenge of harmonization of outcome measures. To accurately model MG and predict individual patient trajectories, one requires integrating three primary data types: (i) Laboratory and medication data, (ii) Electronic Health Record (EHR) data (e.g., age, sex, years since diagnosis, BMI), (iii) Disease severity scores. Among these, MG severity scores are crucial for measuring disease progression from the patient's and clinical evaluator's perspectives. However, clinical studies often employ various scoring systems (e.g., ADL, QMG, MG-CE, MGQOL-15), making it challenging to determine the most reliable measure. In this study, we investigate the relationships among clinical outcome measures across multiple clinical studies. Our objective is to develop a robust \"Myasthenia Gravis Portrait\" that can be applied across diverse clinical studies. This standardized portrait will facilitate the creation of a virtual population of digital twins, enabling the application of machine learning techniques to a larger patient population.", "authors": ["Garbey Marc", "Lesport Quentin", "Kaminski Henry J"], "journal": "medRxiv : the preprint server for health sciences", "entry_date": "2025/06/30 06:20", "pub_date": "2025-06-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40585131/", "pub_types": ["Journal Article", "Preprint"], "affiliations": ["Care Constitution Corp - Houston, TX, USA."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null}, {"pmid": "40584640", "title": "Understanding Racial and Ethnic Disparities in Myasthenia Gravis Outcomes: EXPLORE-MG Registry Experience.", "abstract": "BACKGROUND AND OBJECTIVES: Past studies have reported racial and ethnic differences in patients with myasthenia gravis (MG) but either are over a decade old or only examine small samples. To better understand these differences, using the EXPLORE-MG registry, we conducted a retrospective cohort study of racial and ethnic differences in the characteristics and long-term outcomes of patients with MG.\nMETHODS: Patients with a diagnosis of MG confirmed by one or more of the assessments such as antibody seropositivity, positive single-fiber electromyography, or decremental repetitive nerve stimulation between January 2001 and October 2023 were included in the analysis. For logistic regression models, we performed a complete case analysis, therefore excluding patients with unknown age at onset or history of thymoma. Only patients with 2 years of follow-up data were included in the long-term outcome analysis.\nRESULTS: Of 594 study participants, the clinical features of 473 White, 48 African American (AA), 42 Hispanic, and 523 non-Hispanic patients were compared. Hispanic patients (mean age 41.5 ± 20.3 years vs 58.9 ± 19.9 years; p < 0.001) were significantly younger at onset compared with non-Hispanic patients, and AA patients were significantly younger at onset compared with White patients (mean age 38.6 ± 17.1 years vs 60.7 ± 19.4 years; p < 0.001). AA patients underwent thymectomy more frequently (63.6% vs 29.5%; p < 0.001) compared with White patients. After adjusting for covariates, AA patients were approximately 3 times more likely to experience hospitalization for MG crisis or exacerbation compared with White patients (odds ratio 2.77; 95% CI 1.19-6.50; p = 0.018).\nDISCUSSION: Despite variations in disease severity and clinical profiles, long-term outcomes of patients did not differ. Our findings identify the areas of MG care that vary across racial and ethnic groups, which should be further addressed by clinicians.", "authors": ["McLaren Nilay P", "Roy Bhaskar", "Nowak Richard J"], "journal": "Neurology. Clinical practice", "entry_date": "2025/06/30 06:14", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40584640/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Yale School of Medicine, New Haven, CT."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 3.2, "journal_quartile": "3区"}, {"pmid": "40584517", "title": "Consensus guidelines on the diagnosis and management of myasthenia gravis by the Saudi Arabia Neuromuscular and Electrodiagnostic Medicine and neuromuscular specialists from the Gulf Cooperation Council region.", "abstract": "The introduction of numerous therapeutic advancements in the management of myasthenia gravis (MG) may add difficulties in clinical decision-making, especially when no recommendations tailored to the local context are available. For this reason, the Saudi Arabia Neuromuscular and Electrodiagnostic Medicine (SANEM) chapter of the Saudi Neurology Society launched an initiative to discuss and agree on issues related to the management of MG in the Gulf Cooperation Council (GCC) region. An expert panel from all GCC countries (Saudi Arabia, United Arab Emirates, Bahrain, Kuwait, Qatar, and Oman) was formed to develop practical recommendations using the Delphi method to facilitate the management approach of MG and enhance patient outcomes.\nThe diagnosis and treatment of myasthenia gravis by experts in Saudi Arabia and the gulf region Myasthenia Gravis (MG) is a condition that affects how muscles work. With so many new treatments arising, the condition is becoming more complex to manage. This makes it challenging for doctors to choose the best care. To address this, the Saudi Neurology Society’s SANEM (Saudi Arabia Neuromuscular and Electrodiagnostic Medicine) chapter gathered experts from all GCC countries to create practical recommendations for MG using a structured method called the Delphi method. These recommendations make it easier for doctors to choose the best treatment for patients with MG.", "authors": ["Alshehri Ali Mohammed", "Alanazy Mohammed H", "Alabdali Majed", "Abuzinadah Ahmad R", "Alshareef Aysha", "Abulaban Ahmad", "AlRoughani Raed A", "Abdulla Fatema Mohamed", "Hassan Ali M A", "Alhatou Mohammed Ibrahim", "Almadani Abubaker", "Alrukn Suhail Abdulla", "Alsaadi Taoufik", "Al Salti Abdullah Mohammed", "Shatila Ahmed", "Thakre Mona Chetan", "Alyahya Mossaed", "Alzahmi Fatmah", "AlHajjar Lynn", "Alsolaihim Alanood A", "Alamro Mazen", "Alotaibi Muteb Khidhran", "Bushnag Areej Abdulrahman", "Bamaga Ahmed K", "Jumah Mohammed Al"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/06/30 06:12", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40584517/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuroscience Center, King Faisal Specialist Hospital and Research Center, P.O. Box 3354, Riyadh 11211, Saudi Arabia."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "40583272", "title": "CD19xCD3 T cell engager blinatumomab effective in refractory generalized myasthenic syndromes.", "abstract": "In this case series, we report the first off-label use of the CD19xCD3 T cell engager blinatumomab in two patients with generalized myasthenia gravis (MG). Refractory MG remains a major therapeutic challenge, with patients experiencing severe disability and potentially life-threatening crises despite intensive immunotherapy. This study evaluates the clinical efficacy and safety of short-term blinatumomab treatment in two patients with severe, refractory generalized MG. Both individuals had been experiencing persistent disease burden with myasthenic crises leading to severe disability, despite multimodal immunotherapy. Following treatment with blinatumomab, both patients showed rapid and sustained clinical improvements, reflected in significant reductions in MG-specific scores (MG Activities of Daily Living scale, Quantitative MG score, and revised MG Quality of Life-15), further patient-reported outcomes, digital activity markers, and gait analyses. Laboratory findings revealed persistent B cell depletion in patient 1, whereas patient 2 demonstrated clinical improvement and autoantibody reduction despite B cell repopulation by day 106. Both patients experienced grade 1 cytokine release syndrome during initial treatment phases, but no neurotoxicity or severe adverse events were observed. This report underscores the potential of CD19xCD3 T cell engagers as a promising therapeutic approach in severe autoimmune neuroimmunological disorders, warranting further investigation in clinical trials and mechanistic studies.", "authors": ["Ruck Tobias", "Huntemann Niklas", "Öztürk Menekse", "Schreiber Stefanie", "Lichtenberg Stefanie", "Masanneck Lars", "Nelke Christopher", "Ben Moussa Hend", "Ulrych Thomas", "Seifert Marc", "Mougiakakos Dimitrios", "Dietrich Sascha", "Meuth Sven G"], "journal": "Molecular therapy : the journal of the American Society of Gene Therapy", "entry_date": "2025/06/30 01:36", "pub_date": "2025-09-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40583272/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Ruhr University Bochum, BG University Hospital Bergmannsheil, Department of Neurology, 44789 Bochum, Germany; BG University Hospital Bergmannsheil, Heimer Institute for Muscle Research, 44789 Bochum, Germany; Department of Neurology, University Hospital and Medical Faculty Düsseldorf, Heinrich Heine University Düsseldorf, 40225 Düsseldorf, Germany. Electronic address: tobias.ruck@med.uni-duesseldorf.de."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40580880", "title": "Presentation, management and outcomes of patients with diplopia in the emergency department.", "abstract": "BACKGROUND: Diplopia is a reason for emergency department (ED) visits with both ophthalmological and neurological causes, some of which may require urgent therapeutic intervention. Epidemiological data on this symptom, particularly in the context of general EDs, remain scarce. This study aims to investigate the epidemiology, clinical characteristics, management strategies, and etiologies of diplopia in general EDs.\nMETHODS: We conducted a bicentric retrospective study of patients admitted for diplopia between January 2022 and December 2023 in the general EDs of two French university hospitals.\nRESULTS: We included 788 patients admitted for diplopia, representing 0.2 % of all ED admissions. Binocular diplopia was predominant, accounting for 751 cases (95 %), with the most common etiologies being microangiopathies (250 cases, 33 %), strokes (140 cases, 19 %), and myasthenia gravis (36 cases, 5 %). Cardiovascular risk factor prevalence did not differ between monocular and binocular diplopia. Imaging was performed in 712 cases (90 %), including 694 cases (92 %) of binocular diplopia and 18 cases (48 %) of monocular diplopia. The imaging primarily consisted of magnetic resonance imaging in 550 cases (70 %), computed tomography in 283 cases (36 %), and both modalities in 121 cases (15 %). Urgent etiological treatment was needed in 332 (42 %) cases, and 248 (31 %) patients required hospitalization.\nCONCLUSION: Diplopia accounted for 0.2 % of all ED admissions. Binocular diplopia predominated, with microangiopathies and strokes as leading causes. The use of imaging was high, even for monocular diplopia. The high rate of urgent treatments highlights the need for clearer imaging guidelines in emergency settings.", "authors": ["Occelli Céline", "Coffin Valentine", "Raynaud Oliver", "Vigneau Jean-François", "Coisy Fabien", "Marchetto Pauline", "Bobbia Xavier"], "journal": "The American journal of emergency medicine", "entry_date": "2025/06/28 18:10", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40580880/", "pub_types": ["Journal Article", "Multicenter Study"], "affiliations": ["Montpellier University, Emergency Medicine Department, Montpellier University Hospital, Montpellier, France; Côte d'Azur University, Medical school, Emergency Medicine Department, Nice University Hospital, Nice, France. Electronic address: celine.occelli@chu-montpellier.fr."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.2, "journal_quartile": "3区"}, {"pmid": "40580181", "title": "Endogenous Endophthalmitis and Subretinal Abscess Following Rituximab Therapy in Myasthenia Gravis: A Report of Two Cases.", "abstract": "PURPOSE: Endogenous endophthalmitis is a serious vision-threatening condition commonly associated with immunosuppression and is invariably linked to a systemic focus. Rituximab infusion is one of the treatment options for refractory Myasthenia Gravis but can become a double-edged sword, increasing susceptibility to serious infections. This study reports the occurrence and management of Endogenous endophthalmitis in two patients after rituximab infusion given for refractory Myasthenia Gravis. Endogenous endophthalmitis post Rituximab has not been reported.\nMETHOD: A retrospective review of patients' records was done.\nRESULTS: Case 1 is a 55-year-old male, on treatment with Rituximab for refractory Myasthenia Gravis, presented with painful loss of vision in left eye for 5 days. The patient had right upper limb cellulitis, cavitary bronchopneumonia with septicaemia, 10 days prior. Left eye showed 4+ cells in the anterior chamber with fibrinous exudates and dense vitritis, confirmed on B-scan ultrasonography. Blood culture isolated Escherichia coli and methicillin-resistant Staphylococcus aureus (MRSA) sensitive to meropenem and vancomycin. The patient was administered systemic and intravitreal antibiotics along with vitrectomy. Case 2 is a 45-year-old male with a similar history and presentation to case 1, involving the right eye. Blood culture isolated Nocardia farcinia with sensitivity to amikacin and meropenem. This patient also received systemic and intravitreal antibiotics with vitrectomy. Complete resolution of the infection was noted with improvement in vision in both patients.\nCONCLUSION: With the increasing use of Rituximab, EE incidence is likely to increase. Hence, an awareness of this uncommon complication will help in early recognition and treatment, leading to good outcomes.", "authors": ["Thomas Sherina", "Rao Vaishnavi Prasad", "Nithyanandanam Suneetha", "Rao Vybhavi", "Shaji Dimple", "Nagaraj Savitha", "Raju Merin Ann"], "journal": "Ocular immunology and inflammation", "entry_date": "2025/06/28 10:33", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40580181/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Ophthalmology, St. John's Medical College Hospital, Bangalore, India."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.0, "journal_quartile": "4区"}, {"pmid": "40579340", "title": "Myasthenia gravis: Mechanisms, clinical syndromes, and diagnosis.", "abstract": "Myasthenia gravis (MG) is an autoimmune neuromuscular disorder characterized by muscle weakness and fatiguability. The pathogenesis of MG is mediated in most cases by autoantibodies directed against the nicotinic acetylcholine receptor at the neuromuscular junction, although less commonly autoantibodies may target muscle-specific kinase (MuSK) or low-density lipoprotein receptor-related protein 4 (LRP4). These autoantibodies disrupt cholinergic transmission at the neuromuscular junction through several mechanisms, including direct functional blocking, downregulation, destruction, or disruption of receptor clustering in the postsynaptic membrane. MG is characterized by fatigable muscle weakness in the ocular, bulbar, respiratory or limb muscles. Clinical manifestations can vary significantly among individuals depending on the type of autoantibody or presence of thymoma. Due to the variable presentation of symptoms, diagnosing MG can be challenging. A comprehensive approach that combines clinical assessment, serological testing, electrophysiological studies, and imaging is essential for accurate diagnosis.", "authors": ["Fecto Faisal"], "journal": "Disease-a-month : DM", "entry_date": "2025/06/27 21:54", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40579340/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuromuscular Neurology, Advocate Lutheran General Hospital, 1875 Dempster St, 60068, United States. Electronic address: Faisal.Fecto@aah.org."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "40579339", "title": "Patient perspectives on myasthenia gravis.", "abstract": "To better understand what it's like to live with myasthenia gravis (MG), we spoke to two individuals who have been living with the disease for years. They graciously shared stories that shed light on the day to day impact of this rare condition extending from muscle strength and daily functioning to personal identity and relationships. In sharing their experiences, they also offered insights and advice for others newly diagnosed with MG and for physicians managing the patients and their challenges.", "authors": ["Randall Matthew C"], "journal": "Disease-a-month : DM", "entry_date": "2025/06/27 21:54", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40579339/", "pub_types": ["Journal Article", "Personal Narrative"], "affiliations": [], "china_related": false, "study_types": ["Personal Narrative"], "evidence_level": null, "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "40578418", "title": "Association of blocking acetylcholine receptor antibodies with clinical subtypes and disease severity in myasthenia gravis.", "abstract": "BACKGROUND AND AIM: The identification of serum antibodies, particularly acetylcholine receptor antibodies (AChR-ab), is essential for diagnosing myasthenia gravis (MG). However, the clinical significance of blocking AChR-abs (bAChR-ab) and their correlation with disease severity remain underexplored. This study aims to evaluate the distribution of bAChR-ab across MG subtypes and their correlation with clinical severity.\nMETHODS: 148 MG patients were recruited from Huashan Hospital, Fudan University. The positive ratio of nAChR-ab and bAChR-ab was evaluated, and the correlations of bAChR-ab inhibition rate were analyzed in relation to clinical severity.\nRESULTS: Of total148 patients diagnosed with MG, 76 (51.35%) classified as ocular myasthenia gravis (OMG) and 72 (48.65%) as generalized myasthenia gravis (GMG). Thymic abnormalities were more common in GMG, with 19.44% of GMG patients having thymoma compared to 9.21% of OMG patients, though the difference was not statistically significant. 43.24% of patients tested positive for bAChR-ab, with a significantly higher positivity rate observed in GMG (58.33%) compared to patients with OMG. Elevated bAChR-ab inhibition rate significantly correlated with disease severity, while nAChR-ab did not demonstrate any correlation with either the MGC score or the ADL score in either groups.\nCONCLUSION: bAChR-ab was exclusively detected and showed a strong association with severe clinical manifestations, including myasthenic crises. These findings highlight bAChR-ab as a potential biomarker for monitoring MG severity. The role of bAchR-ab in seronegative MG will be further verified. Larger, multi-center studies warrant to validate these results and refine diagnostic and therapeutic strategies for MG management.", "authors": ["Liu Kuan", "Yang Wenbo", "Liu Xiaoni", "Yu Hai", "Zhu Dongqin", "Li Yarong", "Chen Xiangjun", "Zhang Xiang"], "journal": "Clinica chimica acta; international journal of clinical chemistry", "entry_date": "2025/06/27 19:11", "pub_date": "2025-09-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40578418/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Huashan Hospital, Fudan University and Institute of Neurology, Fudan University, National Center for Neurological Disorders, Shanghai, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "40574941", "title": "A Rare Case of Lambert-Eaton Myasthenia Syndrome With Dysphasia and Dysarthria.", "abstract": "Lambert-Eaton Myasthenic Syndrome (LEMS) is a rare autoimmune disorder resulting in muscle weakness. LEMS typically presents with progressive proximal muscle weakness, especially in the lower extremities, areflexia, and autonomic dysfunction. Bulbar involvement and respiratory compromise tend to occur later in the disease course and usually in severe, advanced cases. We report a unique case of a 50-year-old male with a known history of LEMS, autoimmune retinopathy, erectile dysfunction, and prediabetes who presented with progressive bulbar symptoms - slurred speech and difficulty swallowing - without accompanying weakness in the upper or lower extremities. Despite receiving four doses of intravenous immunoglobulin (IVIG) prior to admission with no improvement, he showed a significant clinical response to six sessions of plasmapheresis. Notably, the absence of limb weakness and preserved motor strength throughout his hospital stay raised diagnostic uncertainty, prompting evaluation for myasthenia gravis, which was ruled out through negative acetylcholine receptor antibody testing and reaffirmed voltage-gated calcium channel (VGCC) antibody positivity. Chest imaging showed no underlying malignancy. This case illustrates an atypical LEMS presentation dominated by severe bulbar dysfunction in the absence of limb involvement or respiratory failure, which is uncommon and may mimic other neuromuscular junction disorders such as myasthenia gravis. The favorable response to plasmapheresis emphasizes the importance of early recognition and aggressive immunomodulatory treatment in preventing clinical deterioration. Clinicians should maintain a high index of suspicion for LEMS even in unusual presentations to ensure timely and appropriate management.", "authors": ["Harimohan Hridya", "Yasonova Mia", "Sukkar Marah", "Sabetian Katayoun"], "journal": "Cureus", "entry_date": "2025/06/27 04:46", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40574941/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Internal Medicine, Kern Medical, Bakersfield, USA."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 1.3, "journal_quartile": null}, {"pmid": "40572755", "title": "Dyslipidemia in Myasthenia Gravis: A Systematic Review and Meta-Analysis.", "abstract": "Background and Objectives: Myasthenia Gravis (MG) comprises an autoimmune disorder marked by muscle weakness and fatigue. MG has been associated with comorbid conditions, including dyslipidemia (DL), which may exacerbate the clinical burden of MG and impact the overall quality of life. Materials and Methods: This systematic review and meta-analysis aimed to assess the prevalence of DL in patients with MG. Following PRISMA guidelines, a comprehensive search was conducted in the MEDLINE, Scopus, and Google Scholar databases. Primary outcomes included the pooled prevalence of DL in MG patients, and the relative risk of DL compared to healthy controls. Results: Nineteen studies involving 98,947 MG patients were analyzed. The pooled prevalence of DL was 23.64% (95% CI: 17.01-30.98). The relative risk of DL in MG patients versus controls was 1.13 (95% CI: 0.53-2.41), indicating no significant increase. Meta-regression revealed a positive correlation between DL prevalence and MG onset age (β = 0.02, p < 0.001), with a 2% rise in DL prevalence per 1-year increase in onset age. Regional subgroup analysis showed a statistical trend of higher DL prevalence in the USA (33.02%) compared to Asia (19.89%) and Europe (17.5%). Conclusions: This study found that approximately one in four MG patients has comorbid DL, with MG onset age significantly influencing DL prevalence. These findings highlight the need for personalized management strategies and evaluations (e.g., statins, LP(a) levels). Further research is warranted to elucidate the pathophysiological links between MG and DL.", "authors": ["Giannopapas Vasileios", "Smyrni Vassiliki", "Papagiannopoulou Georgia", "Salakou Stavroula", "Kitsos Dimitrios K", "Bethani Ilianna", "Zompola Christina", "Tzartos John S", "Tsivgoulis Georgios", "Giannopoulos Sotirios", "Kosmidou Maria"], "journal": "Medicina (Kaunas, Lithuania)", "entry_date": "2025/06/27 01:04", "pub_date": "2025-06-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40572755/", "pub_types": ["Journal Article", "Meta-Analysis", "Systematic Review"], "affiliations": ["Second Department of Neurology, Attikon University Hospital, School of Medicine, National and Kapodistrian University of Athens, 12462 Athens, Greece."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I"}, {"pmid": "40571422", "title": "Pembrolizumab-induced Triple M Overlap Syndrome, example of indiscriminate immune activation.", "abstract": "Triple M Overlap Syndrome is an ultra-rare and seldom-described immune-related adverse event (irAE) secondary to pembrolizumab therapy. This entity and its namesake are due to auto-immune phenomena involving myocardium, striated muscle and neuromuscular junction, yielding a syndrome of myocarditis, myositis and myasthenia gravis. Since it was first identified in 1975, only 100 cases of this syndrome are found in the literature. With the increasing use of immune checkpoint inhibitors (ICIs) for the treatment of various malignancies, however, more cases are likely to be diagnosed in the future. We present a patient who received her first cycle of pembrolizumab therapy 3 weeks prior to presentation with complaints of intense myalgias, diffuse muscle weakness and ptosis. Investigative workup revealed myocarditis, myositis and myasthenia gravis. Treatment with high-dose steroids plus plasma exchange drastically improved her symptoms. This case demonstrates the presenting symptoms, diagnostic findings, critical complications and management strategies of Triple M Overlap Syndrome.", "authors": ["Schroeder Ben", "Bosak Emily", "Nandu Nitish", "Mikhael Mary"], "journal": "BMJ case reports", "entry_date": "2025/06/26 21:33", "pub_date": "2025-06-26", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40571422/", "pub_types": ["Journal Article", "Case Reports"], "affiliations": ["Department of Medicine, University of Missouri System, Columbia, Missouri, USA btschroeder4@gmail.com."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.5, "journal_quartile": "4区"}, {"pmid": "40569533", "title": "Circulating inflammatory proteins as pathogenic mediators and potential therapeutic targets in myasthenia gravis.", "abstract": "BACKGROUND: Myasthenia gravis (MG) is a neurological immune-mediated disorder affecting approximately three million people worldwide. While specific circulating inflammatory proteins (CIPs), including cytokines and chemokines, have been strongly implicated in the pathogenesis of MG, their causal roles remain poorly understood.\nMETHODS: A cis-Mendelian randomization (MR) framework was utilized to assess the genetically inferred causal associations between 91 CIPs, as proxied by protein quantitative trait loci, and the risk of MG. The inverse-variance weighted method served as the primary analytical approach, supplemented by sensitivity analyses to ensure the robustness of our findings and compliance with key MR assumptions. Furthermore, enrichment and protein-protein interaction (PPI) analyses were conducted to determine the functional associations among the significant CIPs.\nRESULTS: Positive associations were observed between plasma TNFSF12 levels and both MG and late-onset MG. Additionally, elevated plasma levels of CD244 and CXCL6 were associated with an increased risk of late-onset MG. In contrast, early-onset MG exhibited significant negative associations with plasma levels of GDNF, IL12B, and IL18R1, but a positive association with CX3CL1 levels. These key findings were further validated through sensitivity analyses. Gene Ontology enrichment analysis indicated that the identified CIPs are primarily involved in biological processes related to natural killer and T cell immune responses, whereas PPI analysis revealed their interactions with other mainstay drug targets for MG.\nCONCLUSIONS: Our study genetically established several CIPs as culprits contributing to disease causation and potential therapeutic druggable targets for MG. Further research is warranted to decipher the underlying molecular mechanisms in greater depth.", "authors": ["Chen Kangzhi", "Zeng Chudai", "Ren Yijun", "He Ting", "Ouyang Yuzhen", "Shi Guanzhong", "Yang Huan"], "journal": "Neurological sciences : official journal of the Italian Neurological Society and of the Italian Society of Clinical Neurophysiology", "entry_date": "2025/06/26 11:21", "pub_date": "2025-10", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40569533/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Xiangya Hospital, Central South University, Changsha, 410008, Hunan, China."], "china_related": true, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40566997", "title": "The Impact of Splicing Dysregulation on Neuromuscular Disorders and Current Neuromuscular Genetic Therapies.", "abstract": "Eukaryotic genes contain non-coding segments known as introns, which interrupt coding sequences. Consequently, eukaryotic transcription produces precursor messenger RNA (pre-mRNA) that relies on precise splicing to remove highly diverse introns from the genome and to generate the mature mRNA essential for maintaining normal cellular activities. The extensive heterogeneity of neurons necessitates complex splicing regulation, particularly alternative splicing, to ensure the accuracy of gene expression in neurogenesis, signal transduction, and synaptic function and to maintain stability and adaptability in the nervous system. With the improvement of genetic testing technology, aberrant splicing has been identified as a contributing factor to the pathogenesis of neuromuscular disorders (NMDs) such as spinal muscular atrophy (SMA), amyotrophic lateral sclerosis (ALS), Duchenne muscular dystrophy (DMD), myotonic dystrophy (DM), Charcot-Marie-Tooth disease (CMT), myasthenia gravis (MG), and multiple sclerosis (MS). Studying the correlation between splicing defects and neuromuscular disorders is crucial for gaining a more comprehensive understanding of the pathogenesis of these diseases and for developing effective therapies. In this review, we introduce the intricate process and key factors of pre-mRNA splicing, with a focus on aberrant splicing and pathogenesis in several major neuromuscular disorders, providing an overview of the latest therapeutic strategies.", "authors": ["Wu Jing", "Yan Shuxuan", "Bian Yuqin", "Liu Rui", "Lyu Xinxing", "Zhang Zhaoxiang", "Huang Shuhong", "Chen Tao", "Cheng Lin"], "journal": "Journal of neurochemistry", "entry_date": "2025/06/26 03:33", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40566997/", "pub_types": ["Journal Article", "Review"], "affiliations": ["School of Clinical and Basic Medicine, Shandong First Medical University and Shandong Academy of Medical Sciences, Jinan, Shandong, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.0, "journal_quartile": "3区"}, {"pmid": "40565966", "title": "Risk of Diabetes Mellitus in the Myasthenia Gravis: A Systematic Review and Meta-Analysis.", "abstract": "Background/Objectives: Myasthenia gravis (MG) comprises an autoimmune disorder marked by muscle weakness and fatigue. MG frequently coexists with other autoimmune conditions, such as diabetes mellitus, which may exacerbate the clinical burden of MG and adversely impact overall quality of life. Methods: This systematic review and meta-analysis aimed to assess the prevalence of diabetes in patients with MG. Following PRISMA guidelines, a comprehensive search was conducted in the MEDLINE PubMed, Scopus, and Google Scholar databases. Results: A total of 11 studies comprising 16,825 patients were included. The pooled prevalence of diabetes among MG patients was 15.6% (95% CI [8.4%, 24.7%]; I2 = 99%, p < 0.001). Compared to healthy controls, MG patients had a 1.24-fold increased risk of developing diabetes (95% CI [1.01-1.54], p < 0.001). Meta-regression showed no association between age and diabetes prevalence, although potential publication bias was noted (Egger's test, p = 0.72). Conclusions: This meta-analysis reveals a higher prevalence of diabetes among MG patients, with an elevated risk compared to healthy individuals. These findings suggest that the association between MG and diabetes may be mediated by corticosteroid use, genetic factors, and reduced physical activity. The main limitations of this study are the lack of reported data regarding the type of diabetes and patients' demographic and disease characteristics (MG classification severity and duration and type of treatment). Further studies are needed to investigate the underlying causal mechanisms and to elucidate the relationship between MG and diabetes subtypes.", "authors": ["Giannopapas Vasileios", "Stefanou Maria-Ioanna", "Zouvelou Vasiliki", "Papagiannopoulou Georgia", "Smyrni Vassiliki", "Kosmidou Maria", "Kitsos Dimitrios K", "Keramida Anna", "Salakou Stavroula", "Tsivgoulis Georgios", "Tzartos John S", "Giannopoulos Sotirios"], "journal": "Journal of clinical medicine", "entry_date": "2025/06/26 01:17", "pub_date": "2025-06-13", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40565966/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Second Department of Neurology, Attikon University Hospital, National and Kapodistrian University of Athens, 10679 Athens, Greece."], "china_related": false, "study_types": ["ITC"], "evidence_level": "I", "journal_if": 2.9, "journal_quartile": "3区"}, {"pmid": "40563042", "title": "Machine Learning-Based Risk Assessment of Myasthenia Gravis Onset in Thymoma Patients and Analysis of Their Correlations and Causal Relationships.", "abstract": "The study aims to utilize interpretable machine learning models to predict the risk of myasthenia gravis onset in thymoma patients and investigate the intrinsic correlations and causal relationships between them. A comprehensive retrospective analysis was conducted on 172 thymoma patients diagnosed at two medical centers between 2018 and 2024. The cohort was bifurcated into a training set (n = 134) and test set (n = 38) to develop and validate risk predictive models. Radiomic and deep features were extracted from tumor regions across three CT phases: non-enhanced, arterial, and venous. Through rigorous feature selection employing Spearman's rank correlation coefficient and LASSO (Least Absolute Shrinkage and Selection Operator) regularization, 12 optimal imaging features were identified. These were integrated with 11 clinical parameters and one pathological subtype variable to form a multi-dimensional feature matrix. Six machine learning algorithms were subsequently implemented for model construction and comparative analysis. We utilized SHAP (SHapley Additive exPlanation) to interpret the model and employed doubly robust learner to perform a potential causal analysis between thymoma and myasthenia gravis (MG). All six models demonstrated satisfactory predictive capabilities, with the support vector machine (SVM) model exhibiting superior performance on the test cohort. It achieved an area under the curve (AUC) of 0.904 (95% confidence interval [CI] 0.798-1.000), outperforming other models such as logistic regression, multilayer perceptron (MLP), and others. The model's predictive result substantiates the strong correlation between thymoma and MG. Additionally, our analysis revealed the existence of a significant causal relationship between them, and high-risk tumors significantly elevated the risk of MG by an average treatment effect (ATE) of 9.2%. This implies that thymoma patients with types B2 and B3 face a considerably high risk of developing MG compared to those with types A, AB, and B1. The model provides a novel and effective tool for evaluating the risk of MG development in patients with thymoma. Furthermore, correlation and causal analysis have unveiled pathways that connect tumor to the risk of MG, with a notably higher incidence of MG observed in high risk pathological subtypes. These insights contribute to a deeper understanding of MG and drive a paradigm shift in medical practice from passive treatment to proactive intervention.", "authors": ["Liu Wei", "Wang Wei", "Zhang Hanyi", "Guo Miaoran"], "journal": "Journal of imaging informatics in medicine", "entry_date": "2025/06/25 23:22", "pub_date": "2026-04", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40563042/", "pub_types": ["Journal Article"], "affiliations": ["School of Health Management, China Medical University, Shenyang, China. wliu@cmu.edu.cn."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 3.1}, {"pmid": "40562618", "title": "IMAAVY (nipocalimab-aahu).", "abstract": "", "authors": ["Beninger Paul"], "journal": "Clinical therapeutics", "entry_date": "2025/06/25 21:53", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40562618/", "pub_types": ["Editorial"], "affiliations": ["Department of Public Health and Community Medicine, Tufts University School of Medicine, Boston, Massachusetts. Electronic address: paul.beninger@tufts.edu."], "china_related": false, "study_types": ["Editorial"], "evidence_level": null, "journal_if": 3.6, "journal_quartile": "3区"}, {"pmid": "40561659", "title": "Chimeric antigen receptor T cell therapy for autoimmune diseases.", "abstract": "Autoimmune diseases represent a significant global health burden, characterized by aberrant immune responses leading to tissue damage and functional impairment. Despite advancements in immunosuppressive therapies, achieving sustained remission remains challenging, necessitating innovative therapeutic approaches. Chimeric antigen receptor (CAR) T cell therapy, a groundbreaking immunotherapy originally developed for oncology, has emerged as a promising strategy in the treatment of autoimmune diseases. By engineering autologous or allogeneic T cells to target specific immune components, CAR-T cell therapy has demonstrated profound efficacy in preclinical and clinical studies across diverse autoimmune disorders. Early clinical applications in refractory systemic lupus erythematosus highlight its potential to induce durable immune reprogramming, achieving drug-free remission and resolving multiorgan involvement. Moreover, its success extends to other autoimmune disorders, including systemic sclerosis, myasthenia gravis, and rheumatoid arthritis. However, challenges such as immune-related toxicity, persistence of therapeutic cells, and antigen escape remain key barriers. This review synthesizes recent advancements in CAR-T technology, clinical outcomes in autoimmune disease trials, and emerging strategies to optimize safety and efficacy, underscoring the transformative potential of CAR-T cell therapy in revolutionizing autoimmune disease management and highlighting the need for further large-scale clinical trials to realize its full clinical applicability.", "authors": ["Nie Wen", "Yang Xinyu", "Ma Mingrui", "Xu Xiaogang", "Hou Jin"], "journal": "Current opinion in immunology", "entry_date": "2025/06/25 18:04", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40561659/", "pub_types": ["Journal Article", "Review"], "affiliations": ["National Key Laboratory of Immunity and Inflammation, Naval Medical University, Shanghai 200433, China."], "china_related": true, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 5.8, "journal_quartile": "2区"}, {"pmid": "40560146", "title": "On the road to blood biomarkers in myasthenia gravis (MG): Beyond clinical scales.", "abstract": "Myasthenia Gravis (MG) is a heterogeneous neuromuscular autoimmune disorder characterized by fluctuating skeletal muscle weakness and a highly variable disease course. MG subgroups are defined by antibody type, age at onset, clinical phenotype, and thymus pathology. Given the unpredictable disease course, disease-specific objective biomarkers are needed to enable personalized treatment strategies and improve clinical trial outcomes beyond conventional clinical scales. Biomarkers are measurable indicators of physiological processes, disease states, and therapy responses. Despite significant advances in MG diagnostics and therapeutics, predictive biomarkers for personalized treatment remain underdeveloped. This review explores the progress and challenges in identifying blood-based biomarkers for MG, highlighting their potential applications in diagnosis and disease monitoring. Established diagnostic blood biomarkers include autoantibodies against acetylcholine receptors (AChR) and muscle-specific tyrosine kinase (MuSK), which confirm MG diagnosis and guide initial treatment decisions. Prognostic biomarkers, such as microRNAs (miR-150-5p and miR-30e-5p), show promise in predicting disease progression. Pharmacodynamic biomarkers, including CD20+ B cell counts, may enhance treatment precision for therapies like Rituximab. Furthermore, emerging research on metabolites, T and B-cell markers, complement factors, and proteomics offer new avenues to refine MG subtyping and identify molecular signatures predictive of treatment response to novel immunosuppressants. While the journey toward clinically useful blood biomarkers in MG remains complex, ongoing collaborative efforts within the MG research community hold the potential to revolutionize disease management. Future studies integrating multi-omics approaches, large-scale longitudinal cohorts, and disease controls will be critical to translating these biomarkers from research into routine clinical practice.", "authors": ["Bhandage Amol K", "Huang Yu-Fang", "Punga Tanel", "Punga Anna Rostedt"], "journal": "Journal of neuromuscular diseases", "entry_date": "2025/06/25 10:43", "pub_date": "2026-05", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40560146/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Medical Sciences, Clinical Neurophysiology, Uppsala University, Uppsala, Sweden."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "40560121", "title": "Telemedicine and remote monitoring in neuromuscular diseases: Challenges and opportunities.", "abstract": "BACKGROUND: Telemedicine, the application of those information technologies to remotely provide health services either for synchronously catching or asynchronous monitoring patient medical data, has shown a growing and widespread application in several chronic diseases, and, especially during and after COVID-19 pandemics, also in neuromuscular diseases.\nOBJECTIVE: this review aims at providing an updated overview on the application of telemedicine and telemonitoring tools in neuromuscular diseases, in clinical practice, research and trials.\nMETHODS: a literature search was conducted on PubMed using keywords regarding telemedicine applications and several neuromuscular diseases, including papers up to May 2024.\nCONCLUSIONS: several tools have been developed and tested in myopathies, motoneuron diseases, myasthenia gravis and peripheral neuropathies, providing monitoring, assistance, and rehabilitation protocols for such frail population, for which obtaining real life data remotely can represent a concrete advantage in clinical trials and clinical practice. Although several barriers in the implementation of telemedicine in NMD still need to be overcome, there is evidence for both clinicians and patients showing positive acceptance and satisfaction on the use of remote supports, regarding them as confident outcome measures of quality of life in view of a more general concept of e-health solutions in routine medical care.", "authors": ["Torri Francesca", "Schirinzi Erika", "Fontanelli Lorenzo", "Ricci Giulia", "Mancuso Michelangelo", "Bochicchio Mario", "Siciliano Gabriele"], "journal": "Journal of neuromuscular diseases", "entry_date": "2025/06/25 10:33", "pub_date": "2026-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40560121/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Translational Research and New Technologies in Medicine and Surgery, University of Pisa, Pisa, Italy."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.4, "journal_quartile": "2区"}, {"pmid": "40557170", "title": "HLA DRB1* Allele Lupus Erythematosus, Rheumatoid Arthritis, and other Autoimmune Disorders with Skin Involvement.", "abstract": "OBJECTIVE: A narrative short review has been made aiming to identify the most important immune disorders associated with the HLA DRB1*allele.\nMATERIAL AND METHODS: Data have been taken from PubMed, and 36 articles have been retrieved.\nRESULTS: It has been found that DRB1*16:02 is associated with autoimmune diseases with production of autoantibodies, mainly systemic lupus erythematosus and myasthenia gravis. DRB1*04 is associated with lupus erythematosus, bullous pemphigoid, and pemphigus vulgaris. DRB1*is also associated with dermatitis herpetiformis, alopecia areata, acute generalised exanthematous pustulosis, and systemic sclerosis. No association of DRB1 has been found either with psoriasis or with psoriatic arthritis, while the association of Cw6 and DRB1*07 confers less severe joint damage in patients with psoriatic arthritis.\nCONCLUSION: DRB1* is associated with lupus erythematosus rheumatoid arthritis and with most immune disorders with skin involvement.", "authors": ["Klimi Eleni"], "journal": "Mediterranean journal of rheumatology", "entry_date": "2025/06/25 04:31", "pub_date": "2025-03", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40557170/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Department of Dermatology, Thriassio General Hospital, Elefsina, Greece."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.4, "journal_quartile": "4区"}, {"pmid": "40557161", "title": "Case Report: Therapeutic effect of efgartigimod in refractory anti-GQ1b antibody syndrome coexisting with myasthenia gravis.", "abstract": "Anti-GQ1b antibody syndrome is a spectrum of autoimmune neurological disorders that includes Miller Fisher syndrome, Guillain-Barré syndrome (GBS) with ophthalmoplegia, Bickerstaff brainstem encephalitis, and acute ophthalmoplegia without ataxia. These conditions are characterized by the presence of immunoglobulin G (IgG) antibodies targeting GQ1b gangliosides. The coexistence of anti-GQ1b antibody syndrome and myasthenia gravis (MG) is rare and presents diagnostic and therapeutic challenges. We report the case of an 84-year-old Japanese man with overlapping features of both disorders, describing his clinical course and response to add-on treatment with the neonatal Fc receptor antagonist efgartigimod. He presented with fever and diarrhea, followed by acute limb weakness. He was initially suspected of having had a stroke but was later diagnosed with GBS based on areflexia, anti-ganglioside antibody positivity, and nerve conduction abnormalities. Intravenous immunoglobulin therapy was initiated but his condition worsened, leading to respiratory failure and mechanical ventilation. Subsequently, bilateral ptosis and eye movement dysfunction emerged, prompting the consideration of MG. Anti-acetylcholine receptor antibodies and tensilon test results were positive and high-dose methylprednisolone was administered, resulting in partial improvement. Plasmapheresis was performed, but profound limb weakness and respiratory failure persisted; intravenous efgartigimod was thus introduced. Remarkably, the patient's respiratory function improved within 7 days, leading to ventilator weaning, and his limb weakness showed notable recovery. After a second cycle of efgartigimod, the patient regained speech and independent mobility, allowing transfer to a rehabilitation facility. His case underscores the diagnostic complexity of overlapping anti-GQ1b antibody syndrome and MG, and it highlights the therapeutic potential of efgartigimod in treating refractory cases of overlapping autoimmune neuromuscular syndromes. Given the rapid efficacy of efgartigimod for improving both respiratory and motor functions in this case, it is apparent that efgartigimod can be a valuable therapeutic option in complex neuromuscular autoimmune conditions.", "authors": ["Watanabe Keiko", "Takahashi Seiya", "Kanda Akane", "Watanabe Takuya", "Kakinuma Yuki", "Yano Satoshi", "Kinno Ryuta"], "journal": "Frontiers in immunology", "entry_date": "2025/06/25 04:31", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40557161/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Internal Medicine, Showa Medical University Northern Yokohama Hospital, Yokohama, Japan."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40556853", "title": "Cerebral venous sinus thrombosis as a complication of heparin-induced thrombocytopenia in myasthenia gravis: A rare and complex case.", "abstract": "BACKGROUND: Cerebral venous sinus thrombosis (CVST) is an uncommon yet critical complication, especially when arising from heparin-induced thrombocytopenia (HIT). In patients with preexisting conditions such as myasthenia gravis (MG), this correlation adds further complexity to clinical management and outcomes.\nCASE PRESENTATION: We report a unique case of CVST induced by HIT in a patient with an established diagnosis of MG. Following plasma exchange therapy, which included heparin administration, the patient developed symptoms indicative of CVST. Diagnostic imaging confirmed thrombosis in the cerebral venous sinuses. Management involved the immediate discontinuation of heparin and the initiation of fondaparinux, leading to effective anticoagulation and clinical improvement.\nDISCUSSION: This case illustrates the rare intersection of CVST and HIT within the context of MG, underscoring the potential risks associated with heparin therapy in vulnerable patient populations. Early recognition of the signs is essential, as these conditions, in combination, demand prompt and specialized interventions to prevent serious complications.\nCONCLUSION: The successful management of this complex case demonstrates the importance of heightened awareness and proactive strategies in patients with MG undergoing heparin therapy. This report advocates for careful monitoring and tailored treatment to mitigate risks in similarly complex clinical scenarios.", "authors": ["AbuAlrob Majd A", "Gumander Abdullah Mantawil", "Zammar Khaled", "Qazakzeh Abdullah I Al", "Alnakhala Sadi Y", "Khalil Osama M", "Hussain Suhail"], "journal": "Qatar medical journal", "entry_date": "2025/06/25 04:27", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40556853/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Neuroscience Institute, Hamad Medical Corporation, Doha, Qatar."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V"}, {"pmid": "40556711", "title": "Epidemiology and patient characteristics of the US myasthenia gravis population: real-world evidence from a large insurance claims database.", "abstract": "BACKGROUND: The epidemiology of myasthenia gravis (MG), a rare autoimmune disease, is not completely understood. This retrospective claims analysis assessed the epidemiologic rates of MG in the USA and the characteristics of the incident and prevalent MG populations.\nMETHODS: Patients with MG were identified using Inovalon closed claims data; those with ≥2 International Classification of Diseases, 10th Revision (ICD-10) codes for MG from 2016 to 2019, separated by ≥30 days, were eligible. Patients in the prevalent cohort had continuous insurance coverage from January to December 2019. Patients in the incident cohort had continuous insurance coverage from January 2018 to December 2019 and no MG claims before 2019. Incidence and prevalence rates were adjusted using US census data. Treatment utilisation was assessed in both cohorts and grouped by provider type. Exacerbations were identified using ICD-10 code G70.01; codes occurring ≤30 days following a previous exacerbation code were considered as part of a single event.\nRESULTS: The incident cohort included 1442 patients (adjusted incidence: 4.3 per 100000); the prevalent cohort included 14 373 patients (adjusted prevalence: 35.7 per 100 000). In 2019, approximately two-thirds of patients in both cohorts (incident, 67.7%; prevalent, 61.6%) received MG treatments, most commonly acetylcholinesterase inhibitors, followed by oral steroids. Among incident patients with ≥1 year of continuous follow-up (n=1204), 32.1% (n=387) experienced ≥1 exacerbation, with 50% (n=194) having ≥2 exacerbations and 41% (n=159) having an exacerbation as the index MG event.\nCONCLUSIONS: Estimates of MG incidence and prevalence were comparable to findings from two recent US studies. Acetylcholinesterase inhibitors and corticosteroids remain widely used. Exacerbations occurred in >30% of incident patients with ≥1 year of continuous follow-up, including 13% who had a relapse as their index event. These results highlight the need for earlier detection and use of more effective therapies in the treatment paradigm to achieve sustained disease control.", "authors": ["Miller-Wilson Lesley-Ann", "Arackal Joel", "Edwards Yuriy", "Schwinn Jennifer", "Rockstein Kristen Elizabeth", "Venker Brett", "Nowak Richard J"], "journal": "BMJ neurology open", "entry_date": "2025/06/25 04:25", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40556711/", "pub_types": ["Journal Article"], "affiliations": ["Immunovant Inc, New York, New York, USA."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.4, "journal_quartile": "3区"}, {"pmid": "40556475", "title": "Validation of the \"Patient-Acceptable Symptom State\" Question as Outcome Measure in AChR Myasthenia Gravis: A Multicentre, Prospective Study.", "abstract": "INTRODUCTION: Patient Acceptable Symptom State (PASS) is emerging as a valuable subjective measure of the overall myasthenia gravis (MG)-related burden. This study aimed at identifying PASS-positive thresholds for the most used clinical scales, investigating whether PASS and MGFA post-intervention status capture different aspects of the disease outcome, and identifying clinical variables associated with PASS=YES response.\nMETHODS: Adult AChR-MG patients were prospectively enrolled at two Italian Centres (Rome: index cohort; Florence: validation cohort). PASS thresholds for MG-ADL, QMG, and MG-QOL15r were defined in the index cohort by ROC analysis and validated in the validation cohort; predictors of favorable PASS were identified by multivariable analysis.\nRESULTS: This study included 173 patients (44% females, median age at onset: 53 years). PASS=YES patients had significantly lower median MG-ADL, QMG, and MG-QOL15r scores, with the following thresholds for PASS=YES: MG ADL ≤ 2, QMG ≤ 8 and MG-QOL15r ≤ 6. The MG-ADL (OR = 0.46, 95% CI = 0.36-0.60, p < 0.001), QMG (OR = 0.72, 95% CI = 0.64-0.81, p < 0.001) and MG-QOL15r (OR = 0.76, 95% CI = 0.70-0.84, p < 0.001), were independently associated with a favorable PASS. The degree of ocular involvement in each scale was the strongest negative determinant of PASS=YES.\nCONCLUSIONS: This study validates the PASS question and highlights the relevance of ocular complaints in patients' perception of MG burden.", "authors": ["Spagni Gregorio", "Verza Massimiliano Ugo", "Cornacchini Sara", "Beretta Francesca", "Sun Bo", "Lotti Antonio", "Falso Silvia", "Barilaro Alessandro", "Massacesi Luca", "Evoli Amelia", "Damato Valentina"], "journal": "European journal of neurology", "entry_date": "2025/06/25 03:23", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40556475/", "pub_types": ["Journal Article", "Multicenter Study", "Validation Study"], "affiliations": ["Department of Neurosciences, Psychology, Drug Research and Child Health (NEUROFARBA), University of Florence, Florence, Italy."], "china_related": false, "study_types": ["Unclassified"], "evidence_level": null, "journal_if": 3.9, "journal_quartile": "2区"}, {"pmid": "40554803", "title": "Transient worsening of thyrotoxic myopathy following methimazole and metoprolol initiation in a 12-year-old girl: a case report and literature review.", "abstract": "OBJECTIVES: Thyrotoxic myopathy (TM) is a muscle disorder associated with hyperthyroidism. Although TM is common in adults, its incidence in children is unknown due to the limited number of reports. TM usually improves with the treatment of hyperthyroidism. This is the first report of a patient with TM who experienced transient worsening of muscle weakness shortly after administration of methimazole (MMI) and metoprolol tartrate.\nCASE PRESENTATION: A 12-year-old Japanese girl with Graves' disease was administered MMI and metoprolol tartrate. Within 12 h of treatment initiation, the patient experienced difficulty in standing from a chair. Examination revealed proximal lower-limb weakness and reduced grip strength. Based on the patient's clinical course and blood test results, thyrotoxic periodic paralysis, myasthenia gravis, or polymyositis were considered unlikely. While the side effects of MMI and metoprolol tartrate were also considered as differential diagnoses, her history revealed mild pre-existing lower limb muscle weakness for 2 months before treatment, suggesting that the side effects of the medication were unlikely. Given the clinical course, the worsening of TM was the most probable cause, and treatment was continued cautiously. Muscle weakness gradually improved over 3 months as her thyroid hormone levels normalized. Magnetic resonance imaging taken 1 month later revealed gluteus muscle atrophy, which resolved within 10 months.\nCONCLUSIONS: TM may show transient worsening after MMI and metoprolol tartrate administration, requiring the evaluation of TM, drug side effects, and other possible causes before continuing treatment. This case highlights the importance of recognizing TM in pediatric patients.", "authors": ["Onishi Yuto", "Higuchi Shinji", "Iwata Kohei", "Watanabe Yoh", "Yamada Yuki", "Mori Jun"], "journal": "Journal of pediatric endocrinology & metabolism : JPEM", "entry_date": "2025/06/24 17:33", "pub_date": "2025-12-17", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40554803/", "pub_types": ["Journal Article", "Case Reports", "Review"], "affiliations": ["Division of Pediatric Endocrinology, Metabolism and Nephrology, 13877 Children's Medical Center, Osaka City General Hospital , Osaka, Japan."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 1.2, "journal_quartile": "4区"}, {"pmid": "40554686", "title": "Deletion of thymic myoid cells regulates the thymic microenvironment involved in the progression of tumor-associated myasthenia gravis.", "abstract": "Myasthenia gravis (MG) is an autoimmune disease commonly associated with immune disorders in thymoma. The role of thymus myoid cells (TMCs) in the pathogenesis of autoimmune diseases has attracted much attention. Therefore, the present study was designed to reveal the impact of TMCs on the pathophysiology of tumor-associated MG (TAMG). This study included clinical patients and healthy volunteers and validated the potential role of TMCs in TAMG progression using a TMCs-deficient mouse model. Correlative findings showed that TMCs deletion affected thymic architecture in MG patients, as evidenced by the expression of key myogenic factors as well as AChR and RyRs receptors in the thymus. Further experimental validation showed that TMCs deletion increased the levels of Th1 and Th17 cells, decreased the levels of Th2 and Treg cells, and altered the secretion of corresponding cytokines, including IL-2, IL-4, IL-17, IL-22, and TGF-β concentrations. Co-culture of CD4+ T cells with Thy0517 cells or CD4+ T cells with a myoblastoid cell line using the Transwell system demonstrated that deletion of TMC inhibited the differentiation of CD4+ T cells to Treg cells. In this study, we hypothesized that TMCs are involved in TAMG progression by regulating CD4+ T cell differentiation.", "authors": ["Hu Bo", "Luo Yang", "Ding Xiangyu", "Sun Min", "Niu Li"], "journal": "Clinical and experimental immunology", "entry_date": "2025/06/24 14:43", "pub_date": "2025-01-21", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40554686/", "pub_types": ["Journal Article"], "affiliations": ["Department of Orthopedics, The First Affiliated Hospital of Anhui Medical University, Hefei, Anhui, China."], "china_related": true, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 3.8, "journal_quartile": "3区"}, {"pmid": "40551857", "title": "Juvenile Ocular Myasthenia Gravis in a 3-Year-Old African Girl: A Case Report.", "abstract": "INTRODUCTION: Myasthenia gravis (MG) is an autoimmune disorder causing muscle weakness. When diagnosed before 18, it is termed juvenile MG. Ocular symptoms are more common in children than adults. Diagnosis of ocular MG involves tests like the ice pack test, while treatment includes cholinesterase inhibitors and corticosteroids.\nCASE PRESENTATION: We present a case of a 3-year-old girl who had a 2-month history of progressive weakness of both eyelids, but no other body weakness reported. She was diagnosed with ocular MG after a positive ice pack test and detection of autoantibodies against acetylcholine receptors. She was started on pyridostigmine and later added cyclosporine, and her symptoms improved greatly afterward.\nCONCLUSION: Ocular MG is rare. This case report highlights the challenges of diagnosing and managing ocular MG in low-resource settings, stressing the need for early recognition and treatment.", "authors": ["Ngowi Elisamia", "Lusheke Humrath", "Mbuma Rashid", "Juneja Zeenat", "Mbuki Mayila", "Thaver Sheliza Parvez", "Magodi Tatenda", "Osman Rukhsar", "Salum Hajaj"], "journal": "Case reports in ophthalmology", "entry_date": "2025/06/24 04:15", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40551857/", "pub_types": ["Case Reports", "Journal Article"], "affiliations": ["Department of Paediatrics and Child Health, Aga Khan Hospital Tanzania, Dar es Salaam, Tanzania."], "china_related": false, "study_types": ["Case Report"], "evidence_level": "V", "journal_if": 0.6, "journal_quartile": "4区"}, {"pmid": "40549349", "title": "Factors that increase utilization management risk: a proof of concept.", "abstract": "OBJECTIVES: To (1) develop a metric that quantitatively measures the risk that utilization management (UM) policies pose to patients and (2) measure the relationship between this metric and payers' real-world UM use.\nSTUDY DESIGN: We conducted a targeted literature review and an expert elicitation exercise to create the Data-Based Utilization Management Risk Designation (BURDEN) score. Real-world data analysis measured the relationship between BURDEN and actual payer policies.\nMETHODS: The BURDEN score was based on 9 UM factors impacting patient outcomes. Factors were weighted based on an expert elicitation procedure with 6 stakeholders. UM policy restrictions were drawn from Tufts Medical Center's Specialty Drug Evidence and Coverage database, and net price data came from SSR Health. Ordinary least square regressions were performed to examine the relationship between the BURDEN score and coverage policies.\nRESULTS: Among 98 treatments identified across 30 unique diseases, UM policies on treatments for myasthenia gravis, multiple myeloma, and lupus nephritis posed the highest risk to patients, according to the BURDEN score. When treatments had a high BURDEN score, payers were 22.0% less likely to impose any UM restriction (P = .041) and 36.2% less likely to impose step edits (P = .039).\nCONCLUSIONS: This study developed a quantitative measure (BURDEN) to estimate the relative risk to patients of payer UM policies. Payers appeared modestly sensitive to treatments that posed a high risk to patients should UM be implemented. However, coverage decisions did not appear to be fully patient-centered, as some higher BURDEN products experienced increased UM usage.", "authors": ["Shafrin Jason", "Fajnor Jacob", "Zhang Shurui", "Nichols Donald E"], "journal": "The American journal of managed care", "entry_date": "2025/06/23 11:23", "pub_date": "2025-06", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40549349/", "pub_types": ["Journal Article"], "affiliations": ["Center for Healthcare Economics and Policy, FTI Consulting, 350 S Grand Ave, Ste 3000, Los Angeles, CA 90071. Email: jason.shafrin@fticonsulting.com."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.1, "journal_quartile": "4区"}, {"pmid": "40547861", "title": "Comparison of outcomes and postoperative immunotherapy between patients with non-thymomatous and thymomatous myasthenia gravis following thymectomy.", "abstract": "BACKGROUND: Outcomes after thymectomy differ greatly between non-thymomatous and thymomatous myasthenia gravis (MG), meriting an in-depth exploration.\nOBJECTIVE: To examine the treatment and prognosis of non-thymomatous and thymomatous MG patients after thymectomy.\nDESIGN: A multicenter, retrospective, case-control study focused on MG patients following thymectomy from November 2010 to January 2024. After propensity score matching, 284 patients (142 with non-thymomatous MG and 142 with thymomatous MG) were included, with a median follow-up of 2.94 years.\nMETHODS: Four outcomes were examined: minimal manifestations status (MMS) or better at the final visit, sustained clinical response, postoperative myasthenic crisis, and long-term mortality. Kaplan-Meier, logistic regression, cox regression, nomogram, receiver operating characteristic curve, decision curve, and calibration curve analyses were used for assessment.\nRESULTS: Non-thymoma patients had a lower proportion of postoperative myasthenic crisis (5.6% vs 13.4%, p = 0.026) and long-term mortality (1.4% vs 9.9%, p = 0.002) but a higher proportion of sustained clinical response (66.2% vs 52.1%, p = 0.016) than thymoma patients. For both non-thymomatous and thymomatous MG, anti-acetylcholine receptor antibody (AChR-Ab) positivity was the independent predictor for MMS or better at the final visit (p = 0.048; p = 0.016) and sustained clinical response (p = 0.035; p = 0.037). Most severe Myasthenia Gravis Foundation of America (MGFA) classification and high-grade Masaoka histopathology were independent predictors for postoperative myasthenic crisis (p < 0.001; p = 0.010) and long-term mortality (p = 0.006; p = 0.014) for thymomatous MG. Postoperative prednisone combined with tacrolimus (Pred + TAC) was associated with achieving sustained clinical response (p = 0.026; p = 0.030) and prednisone tapering for both groups.\nCONCLUSION: Non-thymomatous MG exhibited a more benign course with better outcomes. AChR-Ab positivity indicated a better prognosis for both groups, while thymomatous MG with severe MGFA classification and high-grade histopathology requires close monitoring and follow-up. Postoperative Pred + TAC could be an effective immunotherapy option for beneficial outcomes.\nComparing outcomes and postoperative treatment after thymectomy for two types of myasthenia gravis Why was the study done? Myasthenia gravis (MG) is an immune-mediated disorder characterized by muscle fatigue and fluctuating weakness. MG can be classified into two types: non-thymomatous MG (without thymus tumors) and thymomatous MG (with thymus tumors). This study aimed to examine the treatment and prognosis of these two types of MG and see if certain interventions after thymectomy can help improve recovery. What did the researchers do? The researchers conducted a study that included 284 patients (142 with non-thymomatous MG and 142 with thymomatous MG) who underwent thymectomy between November 2010 and January 2024. The study compared the postoperative prognoses between the two groups of patients following thymectomy, with a particular focus on evaluating the role of postoperative immunosuppressive therapy. What did the researchers find? The study found that non-thymomatous MG had better outcomes after thymectomy, as evidenced by fewer severe episodes (called myasthenic crisis), lower long-term mortality, and a higher rate of sustained improvement than thymomatous MG. Both non-thymomatous and thymomatous MG patients who tested positive for a specific antibody (AChR-Ab) had better recovery. However, thymoma patients with more severe MG before surgery and high-grade histopathology were at higher risk of problems after surgery. The combination of prednisone and tacrolimus after surgery was associated with better long-term outcomes for both groups of patients. What do the findings mean? The findings suggested that non-thymomatous MG exhibited a more benign course with better outcomes. AChR-Ab positivity indicated a more favorable prognosis for both groups. Thymomatous MG patients with severe conditions and high-grade histopathology require enhanced management and follow-up. Additionally, using prednisone and tacrolimus could be a good treatment option for MG after thymectomy.", "authors": ["Zhang Qing", "Pan XuanXuan", "Bi Zhuajin", "Zhan Jiayang", "Yang Mengge", "Lin Jing", "Gui Mengcui", "Li Zhijun", "Zhang Min", "Ma Xue", "Bu Bitao"], "journal": "Therapeutic advances in neurological disorders", "entry_date": "2025/06/23 06:16", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40547861/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Tongji Hospital, Tongji Medical College, Huazhong University of Science and Technology, Wuhan, China."], "china_related": true, "study_types": ["Adjusted Retrospective Cohort"], "evidence_level": "III", "journal_if": 4.1, "journal_quartile": "2区"}, {"pmid": "40547042", "title": "Povetacicept (ALPN-303; TACI vTD-Fc), an enhanced, potent dual inhibitor of BAFF and APRIL, ameliorates experimental autoimmune myasthenia gravis in C57BL/6N mice.", "abstract": "BACKGROUND AND OBJECTIVES: Myasthenia gravis (MG) is a T cell-dependent, B cell-mediated autoimmune disease targeting the acetylcholine receptor (AChR) and other proteins of the neuromuscular junction postsynaptic membrane. Production of pathogenic autoantibodies results from B cell activation and expansion of antibody-secreting cells, including plasma cells, whose differentiation and survival are reliant on the TNF family cytokines APRIL and BAFF. Povetacicept (ALPN-303; TACI vTD-Fc) is an Fc fusion protein of an engineered TACI domain with significantly more potent dual inhibition of APRIL and BAFF than wild-type (WT) TACI-Fc (e.g., telitacicept).\nMETHODS: In this study, the activity of povetacicept was evaluated in the mouse experimental autoimmune MG (EAMG) model, compared to (i) telitacicept, (ii) a depleting anti-CD20 antibody, (iii) neonatal Fc receptor blocker efgartigimod, (iv) a matched Fc control protein, and (v) PBS as vehicle.\nRESULTS: Therapeutic administration of povetacicept ameliorated clinical manifestations in EAMG mice and was associated with significantly lower levels of immunoglobulin subclasses and anti-AChR antibody titers in serum, along with increased muscle AChR content - superior to the evaluated comparators. Povetacicept treatment also reduced the number of total B220+ and Ki67+ proliferating cells in draining lymph node follicles and resulted in modifications of splenic T and B cell subset frequencies, compared to controls.\nDISCUSSION: The potent, dual BAFF/APRIL inhibitor povetacicept significantly improves clinical disease activity in EAMG, associated with reductions in pathogenic anti-AChR autoantibodies and superior to comparator therapeutic interventions based on WT TACI-Fc, CD20 depletion, or FcRn inhibition. Povetacicept may therefore confer beneficial clinical outcomes in the treatment of MG and other autoantibody-related neurological diseases.", "authors": ["Rinaldi Elena", "Puleo Elisa", "Consonni Alessandra", "Miglietti Martina", "Mantegazza Renato", "Wang NingXin", "Peng Stanford L", "Lewis Katherine E", "Dillon Stacey R", "Baggi Fulvio"], "journal": "Frontiers in immunology", "entry_date": "2025/06/23 06:05", "pub_date": "2025", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40547042/", "pub_types": ["Journal Article"], "affiliations": ["Department of Clinical Neurosciences, Fondazione Istituto di Ricovero e Cura a Carattere Scientifico (IRCCS) Istituto Neurologico Carlo Besta, Milan, Italy."], "china_related": false, "study_types": ["Animal Study"], "evidence_level": null, "journal_if": 5.9, "journal_quartile": "2区"}, {"pmid": "40545307", "title": "Impact of 2014 Japanese practice guidelines on treatment patterns in patients with myasthenia gravis: an insurance claims database study.", "abstract": "OBJECTIVES: To evaluate changes in oral corticosteroid (OCS) use after the publication of the 2014 Japanese clinical practice guidelines for myasthenia gravis (MG).\nDESIGN: Retrospective cohort study performed in three Japanese health insurance databases: the JMDC database between 2005 and 2021; the DeSC database covering the National Health Insurance (NHI) and the DeSC database covering the Late-Stage Elderly Healthcare Service (LSEHS) between 2014 and 2021. Achievement of OCS ≤5 mg/day was defined as ≥90 days of consecutive OCS ≤5 mg/day during follow-up, without any gap longer than 60 days between two consecutive claims. The time to achieve OCS ≤5 mg/day was estimated using Kaplan-Meier survival analysis.\nSETTING: Real-world treatment setting in Japan.\nPARTICIPANTS: Patients aged ≥16 years with a record of MG (International Classification of Diseases 10th edition code: G70.0) with a serological test, who had baseline period ≥180 days before inclusion with no MG claim and who started immunotherapy (including OCS) within 90 days of MG diagnosis.\nOUTCOME MEASURES: Prescription of OCS and other therapies for MG.\nRESULTS: Overall, 811 patients were included. The mean age was 49 years in the JMDC, 61 years in the NHI and 80 years in the LSEHS. In the JMDC, the median time to achieve OCS ≤5 mg/day was significantly shorter (p=0.042; log-rank test) in patients included in 2015 or later (11.0 months) than in patients included before 2015 (17.9 months). The median time to achieve OCS ≤5 mg/day was shorter in the LSEHS (6.5 months) than in the JMDC (11.0 months) and the NHI (11.7 months).\nCONCLUSIONS: Faster tapering of the OCS dose was observed in patients starting treatment after the publication of the 2014 guidelines, although use of higher-dose OCS remained widespread after this date. This highlights the need to improve awareness of guidelines by healthcare providers in order to decrease the burden of higher-dose OCS.\nTRIAL REGISTRATION NUMBER: Clinical Trials Registry (UMIN-CTR): UMIN000051155; Post-results.", "authors": ["Konno Shingo", "Uzawa Akiyuki", "Samukawa Makoto", "Todaka Hiroshi", "Mishiro Izumi", "Taki Kentaro", "Quelen Céline", "Czubin Adrianna", "Majewska Renata", "Shiraiwa Kunihiko", "Ohashi Yohei"], "journal": "BMJ open", "entry_date": "2025/06/22 20:53", "pub_date": "2025-06-22", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40545307/", "pub_types": ["Journal Article"], "affiliations": ["Department of Neurology, Toho University Ohashi Medical Center, Tokyo, Japan."], "china_related": false, "study_types": ["Single Arm"], "evidence_level": "IV", "journal_if": 2.3, "journal_quartile": "3区"}, {"pmid": "40544482", "title": "Autoimmune Diseases and Pregnancy - Is There a Greater Risk of Giving Birth to a Sick Child?", "abstract": "This study aims to describe the impact of some of the most common autoimmune diseases, such as multiple sclerosis (MS) and neuromyelitis optica spectrum disorders (NMOSD), myasthenia gravis (MG), chronic inflammatory bowel disease (IBD), type 1 diabetes (T1D), autoimmune thyroid disease, rheumatoid arthritis (RA), systemic lupus erythematosus (SLE), psoriasis, vasculitis, and antiphospholipid syndrome (APS), on pregnancy in women. This review investigates the risk to the offspring of the women; that is, whether the mother's disease may affect fertility or disturb fetal development.", "authors": ["Pszczołowska Magdalena", "Walczak Kamil", "Kołodziejczyk Weronika", "Mroziak Magdalena", "Kozłowski Gracjan", "Leszek Jerzy"], "journal": "Archivum immunologiae et therapiae experimentalis", "entry_date": "2025/06/22 14:22", "pub_date": "2025-01-01", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40544482/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Clinic of Psychiatry, Department of Psychiatry, Medical Department, Wrocław Medical University, Wrocław, Poland."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 3.9, "journal_quartile": "3区"}, {"pmid": "40544117", "title": "A comprehensive review of the treatment options in myasthenia gravis.", "abstract": "The challenge of treating of Myasthenia Gravis (MG) stems from the multiple underlying mechanisms, the varied presentations, the need for chronic immunotherapy, and the long-term consequences of treatment. The disease itself is varied with clinical presentations ranging from droopy eyes to respiratory failure. The underlying etiology may be paraneoplastic or one of several identified antibodies that affect the post-synaptic neuromuscular junction. Treatment strategies vary depending on all of these factors. There are limited medications available for symptomatic treatment of the neuromuscular junction while most treatment focuses on immunotherapy to limit the immune response. Thymectomy is beneficial for most patients with thymoma and many with antibody positive disease. Choosing the right treatments to maximize benefits and limit adverse effects of the medicines is crucial in this chronic disease.", "authors": ["Randall Alexander J", "Post David J"], "journal": "Disease-a-month : DM", "entry_date": "2025/06/21 21:54", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40544117/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuromuscular Neurology, Advocate Lutheran General Hospital, 1875 Dempster St, 60068, United States."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.3, "journal_quartile": "2区"}, {"pmid": "40544116", "title": "The recognition, physiology, and treatment of Lambert-Eaton myasthenic syndrome.", "abstract": "Lambert-Eaton myasthenic syndrome (LEMS) is a rare disease affecting the neuromuscular junction. It causes weakness due to the failure of acetylcholine transmission at the neuromuscular junction. It is also responsible for autonomic symptoms due to the loss of acetylcholine release at autonomic nerves resulting in most often dry mouth, but also impotence, sweating disturbance and orthostatic hypotension. The underlying pathology is split nearly evenly as either paraneoplastic or autoimmune. The challenges in making a diagnosis result in a delay which may correlate with a later initiation of cancer therapy in those with cancers, predominantly small cell lung cancer. There are effective treatments for symptoms of LEMS that work directly at the neuromuscular junction, as well as treatments for the cancer if present. Various types of immunosuppression can be beneficial for both paraneoplastic (T LEMS) and non-tumor LEMS (NT LEMS).", "authors": ["Randall David P"], "journal": "Disease-a-month : DM", "entry_date": "2025/06/21 21:54", "pub_date": "2025-08", "doi": "", "url": "https://pubmed.ncbi.nlm.nih.gov/40544116/", "pub_types": ["Journal Article", "Review"], "affiliations": ["Neuromuscular Neurology, Advocate Lutheran General Hospital, Park Ridge, IL, 1875 Dempster St, 60068, United States. Electronic address: David.randall2@aah.org."], "china_related": false, "study_types": ["Review"], "evidence_level": "VI", "journal_if": 4.3, "journal_quartile": "2区"}];
